window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[0]=[{"i":0,"n":"אאוריי, אברהם ממרוקו","b":"מחכמי מרוקו, עמד לדין בפני רבני טיטואן-תסא."},{"i":1,"n":"אאיליון, יעקב מירושלים","b":"חכם הכולל,מגדולי ירושלים-ת\"ק"},{"i":2,"n":"אאיליון, משה חיים משלוניקי","b":"מחכמי שלוניקי-תרם."},{"i":3,"n":"אאיליון, משה מאמשטרדם","b":"מגדולי חכמי הספרדים,רב באמסטרדם-תק\"צ"},{"i":4,"n":"אאיליון, משה משלוניקי","dt":"תמח - ו תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":5,"n":"אאיליון, שלמה מאמשטרדם","f":"יעקב","k":"בעל פרי עץ חיים","bt":"תכד","bp":"צפת","dt":"תפח - א אייר","dp":"אמשטרדם","b":"מקובל מחכמי צפת, בשליחות באיטליה. רב בלונדון, רב הספרדים באמשטרדם-תס וראש ישיבת \"עץ חיים\" שם. תשובותיו ב\"דבר שמואל\", \"חכם צבי\" - בענין כשרות בשר לספרדים בקהילות אשכנזיות. חיבר גם ספר בקבלה בכת\"י. הואשם בשבתאות ע\"י ר משה חאגיז. תמך בנחמיה חיון כנגד ה\"חכם צבי\" שנידהו. מצאצאיו - ר נחמיה-תלמיד הגר\"א, ור יעקב מקרוז(=יענקעלע קראזער)-תלמיד ר חיים מוולוזין."},{"i":6,"n":"אב יהודה הכהן מאלגיר","bt":"ר","dt":"רע - בערך","b":"רב בהוניין, דיין בתלמסאן. היה בקשרי מכתבים עם הריב\"ש ובאמצעותו העביר הריב\"ש תשובות ליהודי מחוז תוואת שבמדבר הסהרה."},{"i":7,"n":"אבא - ראבה גאון","f":"רבא גאון - הלכות פסו","b":"תלמיד רב יהודאי גאון."},{"i":8,"n":"אבא איסר מזבורוב","b":"אב\"ד זבורוב. נזכר ב\"שואל ומשיב\"."},{"i":9,"n":"אבא אסכנדרי ממצרים","f":"סכנדרי, אלעזר אב\"א","dt":"שפ","dp":"מצרים","b":"ג'יליבי במצרים-שעז על מקום ר שמואל הכהן, ור יעקב טבולי על מקומו אחריו. נהרג עק\"ה."},{"i":10,"n":"אבא ברוך מניו יורק","f":"יהודה אפרים","k":"בעל ברכת אב","bp":"קובנא","b":"רב ודרשן ומשכיל בניו יורק. היה מחלוקת כנגדו וכנגד ספרו. נפטר צעיר."},{"i":11,"n":"אבא גאון","b":"מחכמי בבל-ד'תק - אביהם של ר יוסף גאון פומפדיתא, ורב ביבי (מרדכי) גאון אביו של ר יוסף גאון וזקנו של רב שרירא גאון."},{"i":12,"n":"אבא גאון פומפדיתא","f":"אמי גאון","b":"נכד ר שמואל גאון, מצאצאי האמורא אמימר מסורא. גאון פומפדיתא-ד'תרכט על מקום ר מתתיהו בן רב גאון, ור צמח בן פלטוי גאון על מקומו אחריו. גאון סורא בימיו היה ר עמרם בן ששנא בעל סידור רב עמרם."},{"i":13,"n":"אבא גאון פומפודיתא","f":"רב גאון","b":"גאון פומפודיתא על מקום ר פלטוי גאון-ד'תריז, ור מנחם בר יוסף על מקומו אחריו. בימיו היה גאון סורא - רב נטרונאי בר הלויא גאון. בנו - רב קיומי גאון."},{"i":14,"n":"אבא הכהן מאוסטרהא","f":"פסח מזסלב","k":"אבאלי דער גרויסער","dt":"תקעב - א אדר","dp":"אוסטרהא","b":"חתן ר ר יקותיאל זוסמן מאוסטרהא. פרנס ותלמיד חכם באוסטרהא. מחותן עם ר דב בר ממזבוז-אביו של ר חיים רפפורט בעל מים חיים מאוסטרהא. למרות שהיה מתנגד היה מקורב לר ייב\"י. מבניו: ר שלמה זלמן הכהן זוסמן, ר משה הכהן. חתניו: ר אריה ליב אשכנזי בן ר משלם זלמן מאוסטרהא, ר אברהם מייזלש, ר חיים הכהן רפפורט, ר יצחק צבי הלברשטם."},{"i":15,"n":"אבא ליב מדוינסק","b":"מגדולי תלמידי ה\"צמח צדק\" בנו ר יהודה ליב ונכדו ר שלמה זלמן מקפוסט"},{"i":16,"n":"אבא מבומסלא","f":"שלמה","k":"בעל אור הנשמה","b":"רב בביהם. חיבר בלשון אשכנז \"אור הנשמה\" - בזל שמט. הו\"ל \"נפש החכמה\" - שסח, עם הקדמה ושירים ממנו."},{"i":17,"n":"אבא מהורדנא וירושלים","f":"מ' חיים מהורדנא וירו","bt":"תקסב","bp":"הורדנא","dt":"תרמח - א ניסן","dp":"ירושלים","b":"תלמיד חבר של ר נחום שמש מהורדנא (ר נחומק'ה). עלה לירושלים-תריד. מקובל בישיבת \"קהל חסידים\" של הספרדים. כתב הגהות על עץ חיים לר חיים ויטאל בשם הגהות אב\"ח נדפסו בתוך עץ חיים ירושלים תרכו חתם על האיסור על בתי ספר חילוניים - בספר דרכה של תורה. (אצל גליס תאריך פטירתו - תרלד - כג טבת - וזהו תאריך פטירת אביו)."},{"i":18,"n":"אבא מטשכנוב","b":"חסיד ר מנחם מנדל מקוצק, ר אברהם מסוכטשוב, בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר, והשפת אמת."},{"i":19,"n":"אבא מלוד שמא","b":"מרבני ספרד-ק' רב בלודשמא (נזכר בפירוש תהלים לר אברהם סבע - שמביא ממנו)."},{"i":20,"n":"אבא מקליקול","f":"יצחק ראובן מקליקול","b":"רב בקליקול על מקום אביו."},{"i":21,"n":"אבא מרי","f":"קלונימוס","b":"נזכר בספר דקדוק בכת\"י בשם \"לקח טוב\"."},{"i":22,"n":"אבא מרי הירחי מלוניל מונטפלייר","f":"משה בן יוסף","k":"בעל מנחת קנאות","bp":"לוניל","b":"נינו של ר משלם בן יעקב מלוניל. מחכמי לוניל ומונטפלייר-סו בדורם של הרשב\"א והרא\"ש. תלמיד הרא\"ש. ממתנגדי לימוד הפילוסופיה, אליו (ואל חברו ר טודרוס די בלקיירי) הופנה מכתבו של הרשב\"א האוסר ללמוד פילוסופיה עד גיל 30, והיה מחלוקת על כך ובראש החולקים ר יעקב בן מכיר ן תיבון ור יהודה בן משה ן תיבון - מחכמי מונטפלייר. גלה מארצו-סו בגירוש צרפת ופרובנס ורצה לעבור אל בנו בפירפיניאן (שהיתה בשליטת מלך מיורקה) אך בגלל המחלוקת מנעו מתנגדיו את בואו (ועל כך הוכיחם הרשב\"א). חיבר \"מנחת קנאות\" פרשבורג תקצח ובו אסף את המכתבים בענין החרם, \"ספר הירח\" ובו מגן על הרמב\"ם מהמשיגים עליו. בנו - ר משלם מפירפיניאן."},{"i":23,"n":"אבא מרי הכהן מברצלונה","f":"חנוך","b":"מחכמי ברצלונה. נזכר בשו\"ת הרשב\"א."},{"i":24,"n":"אבא מרי מברצלונה","f":"יצחק","b":"מחכמי ברצלונה. נזכר בשו\"ת הרשב\"א."},{"i":25,"n":"אבא מרי מברצלונה","f":"מכיר","b":"מחכמי ברצלונה. נזכר בשו\"ת הרשב\"א."},{"i":26,"n":"אבא מרי מניגש-צרפת","f":"יצחק","k":"אבי בעל העיטור","b":"נשיא ופקיד השלטון בניגש-צרפת ונקרא ס\"ט גולש בזמן המלך רימנוד החמישי מטולוז, ונזכר במסעות רבי בנימין. נזכר בספר בנו - העיטור - כמה פעמים."},{"i":27,"n":"אבא מרי מספרד - א","f":"יוסף","k":"בעל פירוש על הריף","b":"מחכמי ספרד - פרובנס, ומגדולי הראשונים-שנת מ'. חיבר פירוש על הריף"},{"i":28,"n":"אבא מרי מספרד - ב","f":"נחמן הכספי","b":"מחכמי ספרד, תלמיד הריב\"ש"},{"i":29,"n":"אבא מרי מפרובנס","f":"שלמה","b":"מחכמי פרובנס-ד'תתקן. נזכר בספר התמיד לר ראובן בן חיים - שהיה אחיינו-בן אחותו."},{"i":30,"n":"אבא מרי משלון אשטריק די נובל","f":"אליגדור","k":"בעל פירוש לתורה","b":"מכונה שין אשטריק די נובל - או נגרו. מגדולי חכמי דורו. רב בשלון-נ'. חיבר פירוש לתורה ומסכתות. מתלמידיו ר קלונימוס בעל \"אבן בוחן\", ר שמואל בן יהודה ממרסליא שמזכירו בספרו העתקת אוקלידס. פירושו לאיוב בכת\"י - באוקספורד."},{"i":31,"n":"אבא ן, יוסף מאלגיר ותנס","bt":"קס - בערך","dt":"רל - בערך","b":"רב בווהראן, תונס. היה בקשרי מכתבים עם הרשב\"ץ."},{"i":32,"n":"אבא שאול, בן ציון","f":"אליהו","k":"בעל אור לציון","bt":"תרפד","bp":"ירושלים","dt":"תשנח - יט תמוז","dp":"ירושלים","b":"מגדולי הפוסקים בדורנו, , חיבר \"אור לציון\"","bk":[["אור לציון","שו\"ת - אחרונים"],["אור לציון – שו\"ת וחי'",""]]},{"i":33,"n":"אבא שו\"ב מטשעהרין","b":"חתן ר אליהו מטשעהרין. תלמיד ר נחמן מברסלב."},{"i":34,"n":"אבא שמעון מפוסוואל","f":"חיים יצחק","k":"בעל דורות ראשונים","b":"שו\"ב בפוסבול. חיבר \"דורות ראשונים\" - קידאן תרצה."},{"i":35,"n":"אבאד, חיים יצחק מפטרץ","b":"דיין בפטרץ החדשה(=פטראג'יק)-תק."},{"i":36,"n":"אבאיו, יצחק משלוניקי","dt":"רפז - ד תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":37,"n":"אבאיו, סלימאן ממרוקו.","dp":"תאחנאות-מרוקו","b":"צדיק במרוקו, ורבים באים לפקוד את קברו."},{"i":38,"n":"אבגרדן די לאכריס","b":"שתדלן ופרנס באנגליה-ן', נזכר בספרי הגויים שם שהיה ראש הרבנים בזמן המלך אדוארד ה-I, והיה שתדלן שניסה לעזור לעמו בזמן גזירות המלך, היה מקורב למלך צרפת לודוייג התשיעי והצליח לעזור ליהודים שם. לא נודע שמו העברי."},{"i":39,"n":"אבו איוב מספרד","f":"סהל","b":"פייטן מספרד-ד'תתק. חיבר שיר \"נאום אשר בן יהודה\". מכתב ממנו אל ר יעקב בן חלפון בן נתנאל."},{"i":40,"n":"אבו אל רביע, שמואל הכהן גאון","f":"דניאל בן שמואל","b":"חתן ראש הישיבה יצחק הלוי בן עלי. גאון בבגדד-ה'יח (1258). נחשב לגאון האחרון בבגדד. סייע לר שמואל הנגיד נכד הרמבם בזמן המחלוקת על הרמבם. החרים את ר שמואל פטיט מצרפת שהתישב בעכו. בניו ר חנניה ור אהרן תלמידי הישיבה וחתמו עמו על מכתב לר דוד בן אברהם בן הרמבם בעכו. בזמן המחלוקת על ספרי הרמבם, הציע הרופא ר הלל בן שמואל מפורלי-איטליה, שהדבר יובא להכרעת גאוני בבל, שכל ישראל כפופים להם."},{"i":41,"n":"אבו אלמנא ממצרים","f":"אבו נצר בן חפץ הכהן","k":"בעל מנהאג אד כאן","b":"רב במצרים-ה'כ. חיבר ספר רפואה בערבית."},{"i":42,"n":"אבו אלפרג' יעקב מרמלה","b":"מחכמי רמלה בשנת ד\"א תתמד ברשימה על פירוש רות ושיר השירים ליפת בן עלי נכתב: נעתק עבור ספריית אבו אלפרג' יעקב"},{"i":43,"n":"אבו אמיר, יוסף ממגנישיה","b":"רב במגנישיה-שפד."},{"i":44,"n":"אבו חסדאי, אברהם","k":"בעל בן המלך והנזיר","b":"חכם,משורר ומתרגם-שנת ל'"},{"i":45,"n":"אבו יוסף","f":"יוסף","b":"מחכמי צפון אפריקה בזמן הרמב\"ם"},{"i":46,"n":"אבו כתיר יחיה בן זכריה","b":"ראה יוחנן בן זכריה"},{"i":47,"n":"אבו סולימאן, דוד","f":"ראשלה","b":"פייטן, חכם קדמון בספרד-ד'תש\"נ"},{"i":48,"n":"אבו סעד","k":"אבו סעיד הרופא","b":"כתב ספר רפואה בפרסית"},{"i":49,"n":"אבו עמרן מוסא ממרוקו","b":"מתלמידיו - ר ששת הנשיא מפאס-מרוקו."},{"i":50,"n":"אבו רבי, אהרן מסיציליה","f":"גרשון","k":"בעל ספר המיישר","b":"מחכמי סיציליה, חיבר \"ספר המיישר\""},{"i":51,"n":"אבוביץ, מאיר מדליאטיץ ונוברדוק","f":"ישעיהו","k":"בעל פני מאיר","bt":"תרלו","dt":"תשא","b":"רב בדליאטיץ(=דעלייטיץ)-פלך מינסק-תרסה, ליובצי, נוברדוק, ממיסדי ישיבת \"אהל תורה\" בנוברדוק יחד עם ר שמואל פרידלנדר מבולטימור. מחותן עם ר אלחנן וסרמן - חתנו - ר אליעזר שמחה וסרמן. חיבר גם \"כוכבי אור\", \"זכרון ישעיה\". פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח, \"קובץ דרושים\" - פיעטרקוב תרפג, \"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":52,"n":"אבוביץ, משה מנווהרדוק","k":"בעל פני מאיר","dt":"תשא - ז טבת","b":"רב בנווהרדוק(=נוברדוק)."},{"i":53,"n":"אבוג'מיל, משה מברושא","b":"רב בברושא(=ברוסא) - בדור שלאחר הגירוש."},{"i":54,"n":"אבודיינטי, משה מפורטוגל","k":"בעל דקדוק לשון הקדש","b":"חיבר דקדוק לשון הקדש ושירים בספרדית, וחיבור להוכיח אמיתות הגאולה."},{"i":55,"n":"אבודני","k":"אביו של דונש?","bp":"פאס","b":"היה בדורו של רב סעדיה גאון ביקר בארץ ישראל, יש סברה שזהו אביו של דונש לברט הלוי"},{"i":56,"n":"אבודראץ, יהושע מצפת","dp":"חברון","b":"מחכמי צפת, לאחר המגיפה בשנת שמה עבר לחברון."},{"i":57,"n":"אבודרהם, אברהם מטיטואן-מרוקו","b":"רב בטיטואן-תעב, חתם על פסקי דינים וחלקם בשו\"ת \"משפט וצבי\"."},{"i":58,"n":"אבודרהם, אברהם מספרד","b":"מחכמי אגרמונטי-ספרד-קמד. העתיק ספר המדות לאריסטו."},{"i":59,"n":"אבודרהם, אברהם מתלמסאן","b":"רב בתלמסאן-שי, ונזכר אז בשטר."},{"i":60,"n":"אבודרהם, אליהו מטיטואן","b":"מחכמי טיטואן-מרוקו, חתם על פס\"ד-תקצב עם ר יהודה אנאהורי."},{"i":61,"n":"אבודרהם, דוד","b":"מחכמי מראקש"},{"i":62,"n":"אבודרהם, דוד מאישביליה","f":"יוסף","k":"בעל אבודרהם","b":"תלמיד הטור. מגדולי הפוסקים הראשונים, מרביץ תורה באישביליה (סביליה)-ק. חיבר \"פירוש הברכות והתפילות-שנת ק', נודע בשם ספר אבודרהם."},{"i":63,"n":"אבודרהם, יהודה מטיטואן","f":"יוסף","dt":"תקמח - אחרי","b":"רב בטיטואן, עם ר יעקב מלכא, ר אפרים מונסונייגו, ר יהודה קוריאט, ר שלמה אבודרהם. בניו: ר יוסף, ר מנחם - מתו בחייו."},{"i":64,"n":"אבודרהם, יהודה מטיטואן - ב","f":"מנחם","b":"רב בטיטואן, חתם על פס\"ד-תרטז עם ר יצחק ן ואליד, ר יעקב טאוריל, ר ראובן אלמליח, ר יוסף חג'ואל, ועוד."},{"i":65,"n":"אבודרהם, יוסף מטיטואן","b":"מו\"ץ בטיטואן-שנות ה-תק'. נזכר ב\"תקפו של יוסף\"."},{"i":66,"n":"אבודרהם, יעקב מסאלי","k":"בעל קהלות יעקב","b":"מחכמי סאלי. חיבר דרושים לתורה, והיו אצל אחיו - ר מרדכי שהוסיף גם משלו וקרא לספר \"קהלות יעקב\"."},{"i":67,"n":"אבודרהם, יצחק מטיטואן","b":"רב בטיטואן, חתם-תח עם ר יעקב הלוי, ור חנניה ארובאש."},{"i":68,"n":"אבודרהם, מנחם מטיטואן","b":"מחכמי טיטואן-תקמח חתם על פסק עם ר מנחם נהון-תקמח. מתורתו ב\"תקפו של יוסף\"."},{"i":69,"n":"אבודרהם, משה מאדרינופול","b":"רב באדרינופול-שנות ה-ש'."},{"i":70,"n":"אבודרהם, משה ממצרים - א","b":"רב ברשיד(=רוזיתא)-מצרים - שנות ה-ר'-ש'. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":71,"n":"אבודרהם, משה ממצרים - ב","b":"מגדולי רבני מצרים-ת\"נ"},{"i":72,"n":"אבודרהם, שבתי מקושטא","b":"דיין איסור והיתר בקושטא-תרנג."},{"i":73,"n":"אבודרהם, שלמה מטיטואן ואיטליה","bp":"טיטואן","b":"מצאצאי ר דוד אבודרהם. רב במגרב, עבר לאיטליה."},{"i":74,"n":"אבודרהם, שלמה מטיטואן-מרוקו","b":"חתן ר אברהם ן זמרא. רב בטיטואן עם ר יהודה אבודרהם ור יהודה קוריאט, וחתם עמם-תקח, חתם-תקט עם ר מימון אדהאן. נזכר ב\"מעשה רקם\" - תקסו. בנו ר יצחק נזכר ב\"זכות אבות\" - תקנא."},{"i":75,"n":"אבודרהם, שלמה מטיטואן-מרוקו-ב","dt":"תקעב - לפני","b":"מו\"ץ בטיטואן, עבר לגיברלטר-תקסב. חתם על פס\"ד עם ר מנחם עטייה ונזכר בשו\"ת מוהר\"ך אד\"א."},{"i":76,"n":"אבודרהם, שלמה מספרד","f":"משה","b":"רב בטולידו-ספרד. חתם על החרם נגד הפילוסופיה."},{"i":77,"n":"אבודרן, יהושע מצפת וחברון","bp":"צפת","dp":"חברון","b":"מחכמי צפת-שנות ה-ת', עבר לחברון."},{"i":78,"n":"אבוהב, אברהם מהמבורג ואיטליה","dt":"תב","b":"ממשפחה ממגורשי ספרד שהתישבה בהמבורג, ויסד ביכ\"נ \"כתר תורה\"-שץ, עבר לוירונה-איטליה אל בנו ר שמואל בעל \"דבר שמואל\". נספד ב\"בינה לעתים\"."},{"i":79,"n":"אבוהב, אברהם ממרוקו","b":"דיין מחכמי טיטואן-תעו, חתם עם ר אברהם אלמושנינו-תפו."},{"i":80,"n":"אבוהב, אברהם מספרד","b":"מחכמי ארגון-ספרד-קן וישב בעיר פיליפ. מקורב למלכות. שמועה ממנו בתשובות ר יהודה בן הרא\"ש."},{"i":81,"n":"אבוהב, אברהם משלוניקי","f":"יעקב","b":"תלמיד בעל \"באר לחי\" שהספידו."},{"i":82,"n":"אבוהב, יהודה ממרוקו","b":"דיין במרוקו, חתם על פס\"ד-תיד, ונזכר ב\"משפט וצבי\"."},{"i":83,"n":"אבוהב, יוסף מונציה","f":"שמואל-דבר שמואל","k":"בעל חדושי סופרים","bt":"ת","bp":"ונציה","dp":"חברון","b":"מחכמי ונציה, עמד בראש הישיבה של אביו בזמן נדודי אביו, עלה לחברון בערך שנת תס. חיבר \"חידושי סופרים\" שנכללו בספר \"חיים שאל\" של החידא. והחידא שהכירו הרבה לספר בשבחו."},{"i":84,"n":"אבוהב, יוסף מחברון","f":"חזקיהו","b":"מחכמי חברון, עמד עם ר אליעזר בן ארחא בראש רבני חברון, ושניהם חתומים על קבלת כספים מהעיר רג'יו אמילא בשנת תג."},{"i":85,"n":"אבוהב, יעקב הרופא מירושלים","b":"מחכמי ירושלים, מוזכר ב\"חרבות ירושלים\" כרופא הנבון, בין הנפגעים בפרעות אבן פארוך בשנת שפה, אחיו היה ר יצחק גם הוא בירושלים."},{"i":86,"n":"אבוהב, יעקב מונציה","f":"שמואל - דבר שמואל","k":"בעל סממני הקטורת","dt":"תפז","b":"רב בונציה על מקום אביו. חיבר הקדמה לספר אביו - \"דברי שמואל\". תשובותיו בספרי חכמי דורו ובהם\"שמש צדקה\" ו\"פחד יצחק\" - שם הסכמה ממנו בשם רבני ונציה. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה. חיבר מפתח ל\"ילקוט שמעוני\", \"סממני הקטורת\". כתב הקדמה ל\"אמונת חכמים\" לר אביעד שר שלום באסילה."},{"i":87,"n":"אבוהב, יעקב מחלב","b":"מראשי קהלת הספרדים בחלב-שנות ה-ש'."},{"i":88,"n":"אבוהב, יעקב מטיטואן","b":"מו\"ץ בטיטואן ור ששון קרסיינטי על מקומו אחריו, חתם על פס\"ד-תלט עם ר סעדיה ן דנאן, ר עמנואל סירירו."},{"i":89,"n":"אבוהב, יעקב משלוניקי","dt":"תעב","dp":"שלוניקי","b":"גביר בשלוניקי, פרנס הת\"ת, ותרם לצדקה והחזקת ישיבות, בשליחות הקהלה בקושטא יחד עם ר יצחק מסראן - בענין המס."},{"i":90,"n":"אבוהב, יעקב משלוניקי","dt":"שפב - יג תמוז","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":91,"n":"אבוהב, יצחק די פונסיקה מאמשטרד","f":"דוד","k":"בעל נשמת חיים","bt":"שסה-ט","bp":"קשטרו - פורטוגל","dt":"תנג - כז אדר","dp":"אמשטרדם","b":"בן למשפחת אנוסים מפורטגל שברחו לאמשטרדם - בהיותו בן שבע, נקרא בשם די פונסיקו. תלמיד ר יצחק עוזיאל. רב באמשטרדם בזמן ר מנשה בן ישראל, וראש ישיבת \"עץ חיים\". עבר עם חבורת יהודים לברזיל-תב, התישבו בעיר פרנמבוקו-ברזיל ויסדו בה קהלה יהודית, אך נאלצו לברוח בגלל המלחמה עם הפורטוגזים. חזר לכהן כרב באמשטרדם-תט, וחתם על החרם נגד שפינוזה-תטז, חיבר \"שער השמים\", שירים ופיוטים, ממיסדי ביהכ\"נ הגדול של הספרדים. מקורב לשבתאות. תשובה ממנו ב\"המאור\" - תל אביב תרצה.","bk":[["כתבי רבי יצחק אבוהב די פונקיסה",""],["מחברת נשמת חיים - קבלה, אם לנשמת אדם לא מאמין יש תיקון",""],["מלאכת הדקדוק",""]]},{"i":92,"n":"אבוהב, יצחק מאמשטרדם","f":"מתתיה","bp":"אמשטרדם","dt":"תקמד - ג סיון","dp":"אמשטרדם","b":"מחכמי קהלת הפורטוגזים באמשטרדם. חיבר ספר מוסר בפורטוגזית לבנו - אמשטרדם תם, ועוד ספרים בכת\"י."},{"i":93,"n":"אבוהב, יצחק מטולדו","k":"בעל נהר פישון","bt":"קצג","dt":"רנג","dp":"פורטו-פורטוגל","b":"תלמיד ר יצחק קנפנטון. מגדולי חכמי טולדו בקשטיליה, מרביץ תורה, עבר לפורטו-פורטוגל בזמן הגירוש. מתלמידיו: ר משה דנון, מהר\"י בירב, דון יצחק אברבנאל, ר אברהם זכות בעל ספר יוחסין. חיבר גם פירוש לביאור הרמב\"ן, שיטה לתלמוד, ועוד."},{"i":94,"n":"אבוהב, יצחק מספרד","f":"אברהם","k":"בעל מנורת המאור","b":"מחכמי ספרד, נשוא פנים אצל מלך פורטוגל. חיבר גם \"ארון העדות\", \"שלחן הפנים\". על שמו ביהכ\"נ אבוהב בצפת."},{"i":95,"n":"אבוהב, עמנואל מפורטוגל","f":"יצחק","k":"בעל נומולוגיה","bt":"שטו","bp":"פורטו (פורטוגל)","dt":"שפח","dp":"ירושלים או ונציה","b":"בן למשפחת אנוסים בפורטוגל, את חנוכו היהודי קבל מסבו האנוס אברהם בן יצחק אבוהב השני מטולידו. נמלט מפורטוגל לאיטליה-שכ ושב ליהדות בגלוי, התיישב אצל קרוביו ונכדו ר יצחק אבוהב בונציה, והיה בקשרים עם ראשי העיר, ונשא נאום לפני הדוכס והמועצה בונציה אודות נאמנות היהודים למדינה. פעל לקירוב האנוסים ליהדות. חיבר גם \"יסוד האמת\", \"נומולוגיה\" לאנוסים. עלה לירושלים-שעה בראש חבורה עם בתו גראסיה (ויש אומרים שנפטר בטרם הספיק לעלות)."},{"i":96,"n":"אבוהב, שלמה מספרד ומרוקו","f":"יצחק?","dt":"שה- לפני","dp":"פאס?","b":"תלמיד ר משה חלאווה. מחכמי ספרד, אחרי הגירוש התישב בפאס. היה מעורב במחלוקת הריאה עם ר חיים גאגין, וחתם על תקנה-שה."},{"i":97,"n":"אבוהב, שלמה משלוניקי","dt":"תטו - א ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":98,"n":"אבוהב, שמואל - ב","k":"בעל תקון סופרים","b":"נזכר ב\"דבר שמואל\". חיבר \"תקון סופרים\"."},{"i":99,"n":"אבוהב, שמואל מאיטליה","f":"אברהם","k":"בעל דבר שמואל","r":"יש אומרים ב' אלול שנשמע ונתבשר גליון 178","bt":"שע","bp":"המבורג","dt":"תנד - א אלול","dp":"ונציה","b":"תלמיד וחתן ר דוד פרנקו מונציה. רב בוירונה, ונציה-תי. גדול המשיבים בדורו באיטליה. בניו - ר יעקב על מקומו אחריו בונציה, ר אברהם ור דוד. חיבר גם \"הזכרונות\", אגרות שנדפסו ב\"דור אחד בארץ\" ירושלים תשמח. מראשוני המתנגדים לשבתי צבי.","bk":[["דבר שמואל","שו\"ת - אחרונים"],["ספר הזכרונות","הלכה ומנהג - אחרונים"],["דבר שמואל – שו\"ת",""]]},{"i":100,"n":"אבוהב, שמואל מחברון","b":"מחכמי חברון, בשנת תכא חתם על כתב שליחות עם חכמי חברון, היה רבו של ר אברהם ישראל זאבי בעל \"אורים גדולים\"."},{"i":101,"n":"אבוזמיל, שמואל מתלמסאן","bt":"[ש]","dt":"שס - בערך","b":"רב בתלמסאן וראש הקהלה. רבו של ר אברהם בן יעקב גבישון השני (שכתב שיר לכבוד רבו). התכתב עם הרשב\"ץ."},{"i":102,"n":"אבוחצירא - משפחה","b":"משפחת רבנים ממרוקו. ראש המשפחה ר שמואל אלבז תלמידו של ר חיים ויטאל, בנו ר יוסף, בנו ר מכלוף מדרעא-מרוקו, בנו ר יחיא, בנו ר עיוש, בנו ר יחיא, בנו ר מסעוד, בנו ר יעקב בעל \"אביר יעקב\"."},{"i":103,"n":"אבוחצירא, אבא","f":"יצחק","dt":"תרצז - כו חשון","dp":"בודניב(מרוקו)","b":"מרבני מרוקו, נכד ר' יעקב אביחצירא"},{"i":104,"n":"אבוחצירא, אברהם מדאר-אלבידה","bp":"מכנאס","dt":"תשח - ח אדר","dp":"דאר אלבידה","b":"דיין בדאר אלבידה(כאשר היה בדרכו לא\"י)"},{"i":105,"n":"אבוחצירא, אברהם מיבנה","f":"יצחק (בבא חאקי)","bt":"תרעה","bp":"תאפיללת","dt":"תשלד - כא כסלו","dp":"רמלה","b":"עלה לא\"י-תשט, רב ביבנה-תשי, מילא מקום אביו רב ברמלה-תשל."},{"i":106,"n":"אבוחצירא, אברהם ממרוקו וטבריה","f":"יעקב - אביר יעקב","k":"הו\"ל גנזי המלך","bt":"תרא","bp":"תפיללאת (מרוקו)","dt":"תרעג - יא אד\"א","dp":"טבריה","b":"רב בתאפיללת-תקלג, עלה לארץ, רב בטבריה. חתום בהסכמה על ספר \"מלחמת המגן\"; הוציא לאור את ספרו של אביו \"גנזי המלך\""},{"i":107,"n":"אבוחצירא, אברהם מתאפילאלת","f":"יחיא","b":"מקובל, מחמי תאפילאלת-מרוקו. זקנו של ר יעקב בעל \"אביר יעקב\". מסופר עליו שהיה לו גילוי אליהו, ושנעשה לו נס בזמן עצירת גשמים."},{"i":108,"n":"אבוחצירא, אהרן מתאפילאלת-מרוקו","f":"יעקב - אביר יעקב","bp":"תפיללאלת","dt":"תרסא - כא אלול","dp":"תלוואת-מרוקו","b":"רב ודיין בתאפילאלת-מרוקו. הו\"ל את כתבי אביו. בניו - ר ישראל - בבא סאלי לקביר, ר שלום, ר יוסף-'בבא סו'."},{"i":109,"n":"אבוחצירא, אליהו מתאפילאלת","f":"אהרן","dt":"תרפה","b":"רב בתאפילאלת"},{"i":110,"n":"אבוחצירא, אלעזר מבאר שבע","f":"מאיר מאשדוד","bt":"תשח","bp":"ריסאני-מרוקו","b":"עלה לארץ-תשכו. נכד הבבא סאלי. אדמור בבאר שבע."},{"i":111,"n":"אבוחצירא, ברוך מנתיבות","f":"ישראל - הבבא סאלי","b":"ממשיך דרכו של אביו בנתיבות."},{"i":112,"n":"אבוחצירא, דוד ממרוקו","f":"מסעוד","k":"בעל פתח האהל","bt":"תרכו-נו","bp":"תפילאלת","dt":"תרף-פד -יד כסלו","b":"נכד בעל \"אביר יעקב\". גדול בתורה, מתמיד. נהרג עק\"ה. חיבר גם \"רישא וסיפא\", ועוד. מתולדותיו ב\"אני לדודי\"."},{"i":113,"n":"אבוחצירא, דוד מנהריה","f":"מאיר מאשדוד","bt":"תשיב","b":"נכד הבבא סאלי. אדמו\"ר בנהריה."},{"i":114,"n":"אבוחצירא, יוסף מקולומב-בשאר","f":"אהרן בן יעקב-אביר יע","k":"בבא סו","dt":"תשלד","b":"מקובל ורב בקולומב-בשאר(=בצ'אר)-אלגיר (ליד העיר תאפיללת-מרוקו), עבר לצרפת בשנותיו האחרונות."},{"i":115,"n":"אבוחצירא, יחיא השני","f":"עיוש","b":"זקנו של ר יעקב בעל \"אביר יעקב\"."},{"i":116,"n":"אבוחצירא, יחיא מתאפילאלת","b":"מחכמי תאפילאלת. (כנראה טעות והכוונה ל-ילוז ולא אבוחצירא)."},{"i":117,"n":"אבוחצירא, יעקב","f":"עיוש","b":"אחיו של ר יחיא השני-זקנו של ר יעקב בעל \"אביר יעקב\"."},{"i":118,"n":"אבוחצירא, יעקב מתפילאלת","k":"בעל אביר יעקב","r":"שערי בינה תולדו' המח' ע' ח'","bt":"תקנ","dt":"תרמ - כ טבת","dp":"דמנהור-מצרים","b":"איש מופת,רב בתאפילאלת-מרוקו, ניסה לעלות לארץ כמה פעמים אך נמנע ממנו הן בגלל השלטונות והן בגלל הפצרת היהודים, נפטר בדרכו לארץ בדמנהור-מצרים. מגדולי חכמי מרוקו. בקהלות הדרום והמזרח במרוקו נהגו ע\"פ שיטתו בהלכה, והשפעתו היתה על כל יהודי מרוקו. חיבר גם\"דורש טוב\", \"מעגלי צדק\", ועוד. בניו: ר יצחק, ר מסעוד, ר אהרן, ר אברהם.","bk":[["אביר יעקב",""],["אלף בינה – מוסר",""],["בגדי השרד – הגדה של פסח",""],["גנזי המלך – תיקונים",""],["דורש טוב – דרוש",""],["יגל יעקב",""],["יורו משפטיך ליעקב – שו\"ת",""],["לבונה זכה – ש\"ס בסדר התורה",""],["מחשף הלבן – עה\"ת",""],["מעגלי צדק – תנ\"ך",""],["פתוחי חותם – עה\"ת",""],["שערי ארוכה – דרוש על כב אותי'",""],["שערי תשובה – כח פנים בתשוב'",""]]},{"i":119,"n":"אבוחצירא, יצחק מתאפיללת","f":"יעקב - אביר יעקב","k":"בעל אלף המגן","bt":"תרכה \\ תרכ","dt":"תרעב - יד שבט","dp":"תולאל","b":"רב ומקובל מחכמי ישיבת אביר יעקב בתאפיללת-מרוקו, דודו של ראש הישיבה ר ישראל הבבא סאלי שקרא לו מורי ורבי, היה נוסע בשליחות הישיבה ונהרג עק\"ה ע\"י שודדים בזמן שליחותו. חיבר \"לב טהור\", \"השבת הגדול\" ועוד.","bk":[["אלף המגן – תנ\"ך",""],["זבחי צדק – שחיטה כת\"י",""],["כתר תורה – דרשות כת\"י",""],["לב טהור – דרשות",""],["שבת הגדול – כת\"ר המצוות",""],["שערי בינה – שיר השירים",""],["שרביט הזהב – ש\"ס כת\"י",""]]},{"i":120,"n":"אבוחצירא, יצחק מתפילאלת","f":"מסעוד","k":"בבא חאקי","bt":"תרנז","dt":"תשל - כה אד\"ב","b":"רב פעלים,מרביץ תורה,רב בתפילאת-מרוקו, עלה לארץ-תשט וכיהן כרב ברמלה-תשט."},{"i":121,"n":"אבוחצירא, ישראל - א","f":"אהרן","k":"בבא סאלי לקביר","bp":"תאפילאלת","dt":"בשאר-אלגיר","dp":"תשד","b":"רב בבשאר(=קולומב בשאר)-אלגיר - אשר רוב תושביה יוצאי תאפילאלת-מרוקו."},{"i":122,"n":"אבוחצירא, ישראל - ב","f":"מסעוד","k":"בבא סאלי","bt":"תרן","dt":"תשמב - ד שבט","dp":"נתיבות","b":"רב וראש הישיבה בתאפילאלת על מקום אביו. עלה לארץ-תרפא, אולם חזר לאחר שאחיו ר דוד בעל \"שכל טוב\" שמילא את מקומו, נרצח בידי ערבי. נהג באדמורות ונחשב לאחד מגדולי הצדיקים במרוקו. עלה לארץ-תשכד והתישב ביבנה, ליד חתנו ר אברהם אבוחצירא - בנו של אחיו ר מאיר, עבר לאשקלון, נתיבות. בנו הו\"ל את ספרו \"אהבת ישראל\" - תשמח. מתולדותיו ב\"מאור ישראל\"."},{"i":123,"n":"אבוחצירא, מאיר שלום","f":"ישראל-בבא סאלי","k":"בבא מאיר","bt":"תרעז","bp":"תפיללאת-מרוקו","dt":"תשלג - יז ניסן","dp":"ירושלים","b":"מחכמי מרוקו. רב במדלת-מרוקו (בהוראת אביו), ארפוד-תשיא על מקום אביו שעלה לארץ. דחה הצעות רבנות ממקומות שונים. עלה לארץ והתישב באשדוד. בניו - ר אליעזר, ר דוד, ר רפאל, ר יקותיאל ור ישועה רחמים. נפטר בחיי אביו. חיבוריו בכת\"י - אבדו (רובם שרף בעצמו). מבניו: ר אלעזר, ר דוד."},{"i":124,"n":"אבוחצירא, מימון ממרוקו","b":"רב במרוקו, חתם-תרעב עם ר שלמה שטרית."},{"i":125,"n":"אבוחצירא, מכלוף - א","f":"יוסף","k":"באיו (=אבא)","dp":"תרגליל-דרעא-מרוקו","b":"מצאצאי ר שמואל אביחצירא, מאבות המשפחה. מחכמי מחוז דרעא-מרוקו."},{"i":126,"n":"אבוחצירא, מכלוף - ב","f":"אליהו","k":"בעל יפה שעה","bt":"תרנח","bp":"תפילאלת-מרוקו","b":"תלמיד ר מסעוד אמסלם, ודודו ר ישראל אביחצירא, ור יחיא אדהן, ובישיבת ר משה אתורז'מאן. רב בתפילאלת על מקום אביו-תרפז. רב ודיין בבני מלאלא תדלא ובוז'עד (ליד קזבלנקה)-תשב, רב בקזבלנקה-תשז, מראקש-תשח, והיה ממקורבי המלך והציל כמה נפשות משמד. עלה לארץ-תשכח. חיבר גם \"קהלות יעקב\", ו\"מכלל יופי\"."},{"i":127,"n":"אבוחצירא, מסעוד","f":"אברהם","b":"אביו של ר יעקב בעל \"אביר יעקב\"."},{"i":128,"n":"אבוחצירא, מסעוד מתאפיללת","f":"יעקב-אביר יעקב","dt":"תרסח - יב אייר","dp":"תאפיללת","b":"מגדולי רבני מרוקו-תרמ. אביו של הבבא סאלי. רב בתאפיללת על מקום אביו וראש הישיבה. בתקופתו ובתקופת אביו השתלטה צרפת על אלגיר, והרבנים דאגו על יהודי מרוקו שהלכו למסחר באלגיר שלא \"יתקלקלו\" ולכן הנהיגו להשביעם בנקיטת חפץ - בצאת לאלגיר - שישמרו על עצמם ממקומות הטומאה שם, ומי שהסכים קיבל מהם את ברכת הדרך."},{"i":129,"n":"אבוחצירא, משה ממרוקו - ב","f":"יחיא","b":"רב במרוקו, ר יעקב אביחצירא הזכירו בספרו."},{"i":130,"n":"אבוחצירא, משה מתאפיללת","b":"רב בתאפיללת."},{"i":131,"n":"אבוחצירא, עיוש מתאפילאלת-מרוקו","f":"יחיא","b":"מגדולי המקובלים במרוקו, מאבות משפחת הרבנים, מצאצאיו ר יעקב בעל \"אביר יעקב\"."},{"i":132,"n":"אבוחצירא, עמרם ממרוקו","b":"בנו של הרב של מחוז תלוואת. הגיע למרוקו בשליחות מארץ ישראל, ונפטר בשליחותו, בנו ר יוסף."},{"i":133,"n":"אבוחצירא, שלום ממרוקו","f":"אהרן בן יעקב-אביר יע","k":"בעל כלי כסף","dt":"תשלה","b":"רב בבשאר-אלג'יר-תשה עד תשכב, על מקום אחיו-ר ישראל. חיבר גם \"זהב שבא\", \"כלי כסף\", ועוד. בספרו \"כלי כסף\" מתאר את יציאתם הכפויה של היהודים מאלג'יר-תשכב."},{"i":134,"n":"אבוחצירא, שלמה ממרוקו","b":"מחכמי מרוקו-תקכד."},{"i":135,"n":"אבוחצירא, שמואל אלבז","k":"אביחצירא-בעל המחצלת","b":"נחשב לראש משפחת הרבנים - קיבל את שמו אביחצירא(=מחצלת) ע\"ש נס שנעשה לו כשחצה את הים על גבי מחצלת. נזכר ב\"שם הגדולים\" לחיד\"א."},{"i":136,"n":"אבוחצירא, שמואל מחלב וגובר","b":"מקובל מחכמי חלב בזמן האר\"י, והתגורר גם בגובר-ליד דמשק. השתמש בקבלה מעשית לפי הצורך. נקרא בשם אבו חצירא משום שבמקום הכובע היה עוטה מחצלת קלועה מעלים. ישב בבית כנסת שבנה אותו הנביא אלישע בן שפט."},{"i":137,"n":"אבוחצירא, שמואל מרוקו","f":"אהרן","dt":"תשטו - יט אייר","dp":"ארפוד-מרוקו","b":"נכד ה\"אביר יעקב\"."},{"i":138,"n":"אבוחצירא, שמעון מארפוד וירושלי","b":"למד שנים רבות בחברותא עם קרובו האדמור ר מאיר ה\"בבא מאיר\". דיין בארפוד-מרוקו, עלה לירושלים וכיהן כרב שכונה."},{"i":139,"n":"אבוחצירא, שמעיה ממרוקו","b":"רב במרוקו, חתם עם ר אהרן אבוחצירא-תרלט בערך."},{"i":140,"n":"אבוכזיר, אברהם מאלכסנדירה","bt":"תרכא","dt":"תשה - כח תשרי","b":"רב באלכסנדריה-תרס\"ח,חכם באשי,ראב\"ד בירושלים-תרפ\"ט"},{"i":141,"n":"אבולכיר - משפחה","b":"משפחה קדומה באלגיר - ראש המשפחה ר אבו אלכיר תאהרתי מתאהרת(=תייארת) בסוף תקופת הגאונים."},{"i":142,"n":"אבולכיר, אהרן מאלגיר","dt":"תקם - כט אב","dp":"ירושלים","b":"מרבני אלג'יר, עלה לירושלים. בניו: ר יוסף, ר שמואל, ר יצחק הי\"ד - רבנים באלגיר."},{"i":143,"n":"אבולכיר, בנימין מאלגיר","f":"חיים","k":"בעל משאת בנימין","bt":"תרך","dt":"תרץ","b":"רב בבג'איה(בוג'י), חיבר \"משאת בנימין\""},{"i":144,"n":"אבולכיר, דוד מווהראן","f":"יעקב","bt":"[של]","dt":"[ת]","b":"תלמיד רשב\"ץ באלגיר ונשלח על ידי רבו לווהראן. רב ופייטן בווהראן. פיוטים ממנו במחזור ווהראן, אגרת ממנו לחכמי ירושלים."},{"i":145,"n":"אבולכיר, חיים מאלגיר","bt":"תקץ - בערך","dt":"[תרס]","b":"רבה של בג'איה באלג'יר-תק\"ץ-תר\"ס. אחיו של ר שמואל מאלגיר. חיבר בכת\"י - תולדות הריב\"ש והרשב\"ץ (והיה אצל ר אנשל אשר פרל וכנראה אבד). בנו - ר בנימין."},{"i":146,"n":"אבולכיר, יוסף מאלגיר","f":"אהרן","b":"רב ומקובל באלגיר. מתורתו ב\"קרבן אהרן\" לר אהרן מועטי. חתום על שאלת רבני אלגיר מר יוסף זרקא מתונס, ומר מסעוד אלפסי מתונס. נמנה על חבורת המקובלים שבקשו להנהיג מנהגי קבלה כנגד המסורת שם."},{"i":147,"n":"אבולכיר, יצחק מאלגיר","f":"יוסף","dt":"תקעה","dp":"אלגיר","b":"רב באלגיר-תקסה. נהרג עק\"ה לאחר הלשנה (בשנים תקסה-תקעה נהרגו עק\"ה כמה מראשי הקהל באלגיר)."},{"i":148,"n":"אבולכיר, שמואל מאלגיר","f":"יוסף בן שמואל","k":"בעל סדר הגט והחליצה","dt":"תרן","dp":"ירושלים","b":"דיין ומלמד לתלמידים באלג'יר, מתלמידיו ר יהודה לופראני, ור שמואל צרור. עלה לירושלים-תרן בערך. מתורתו בספרי חכמי דורו. תשובה ממנו ב\"כרם חמר\"-תרכט. הסכים על \"פתשגן הכתב\" - אלגיר תרמה."},{"i":149,"n":"אבולעפיה חיים בן דוד","bt":"1700","dt":"ה'תקלה 1775","bk":[["נשמת חיים",""]]},{"i":150,"n":"אבולעפיה טודרוס בן יהודה","bt":"1247","dt":"ה'ס 1300","bk":[["גן המשלים והחידות",""]]},{"i":151,"n":"אבולעפיה, אברהם יחזק'","f":"חיים שלמה","bp":"טבריא"},{"i":152,"n":"אבולעפיה, אברהם מאזמיר","b":"מחכמי אזמיר-שנות ה-ת'."},{"i":153,"n":"אבולעפיה, אברהם מטולדו","f":"שמואל","k":"בעל אמרי שפר","bt":"ה'א בערך","bp":"טולדו או סרגוסה","b":"תלמיד המקובל ר ברוך תוגרמי, נדד בארצות יון, חיפש את עשרת השבטים, תלמיד ר הלל מוירונה, חזר לספרד. מקובל, רב בטולידו, מסינה. בשנת מ' הגיע לאיטליה ופגש את האפיפיור ניקולס ורצה לגיירו ונידון לשריפה והצליח לברוח, הכריז על עצמו כנביא וחשב על עצמו כמשיח והיה מחלוקת כנגדו, והרשב\"א יצא כנגדו, וכאשר היה בפלרמו-איטליה בירר ר אחיטוב רב העיר על אודותיו בספרד והשיבו לו משם בשם הרשב\"א דברים חריפים כנגדו, וכן יצאו נגדו ר יהודה חייט, ויש\"ר מקנדיא. לעומת זאת רמ\"ק מביא ממנו בספר הפרדס ועוד מקובלים הביאו מתורתו, וגם החיד\"א מזכירו כחכם ומקובל. חיבר גם \"אור השכל\", \"אוצר עדן גנוז\", ועוד. מתלמידיו: ר יהודה סלמון שלמה מברצלונה, ר שלמה בן יצחק, ר\"י גיקטליא, ר אברהם המשכיל ממסיני-סיציליה, ור נתן ממסיני."},{"i":154,"n":"אבולעפיה, אליהו דוד מאזמיר","b":"רב באזמיר"},{"i":155,"n":"אבולעפיה, אליהו חיים מטבריה","f":"מאיר ישכר","bt":"תרו-י - ו אב","dt":"תרפז -כב-ד אלול","b":"מגדולי מחכמי טבריה, הספידו ר יוסף ילוז בספר \"תולדות אליהו\""},{"i":156,"n":"אבולעפיה, אליהו יעקב מאזמיר","f":"יעקב","bt":"תריב","bp":"אזמיר","dt":"תרעה - יט חשון","dp":"אזמיר","b":"חתן ר שלמה פלאג'י. דין אצל ר אברהם פלאג'י. רב באזמיר-תרנה, הוזמן לכהן כרב בירושלים-תרסח בזמן המחלוקת על הרבנות - וסירב. תשובות ממנו ב\"כבוד יעקב\", חתם על פסקים עם ר משה ברקי."},{"i":157,"n":"אבולעפיה, אליהו מאזמיר","b":"דיין, מרבני איזמיר"},{"i":158,"n":"אבולעפיה, אלעזר","f":"יוסף דוד","dp":"טבריה"},{"i":159,"n":"אבולעפיה, דוד מטבריה","b":"מחכמי טבריה, בשנת תקמה חתם על אגרת שליחות ר אברהם אריה, ובשנת תקס על אגרת שליחות של ר רחמים יעקב בן ראובן ור חיים ברוך מאיסטרו."},{"i":160,"n":"אבולעפיה, דוד מירושלים","b":"דרשן, שד\"ר מירושלים, ישב כמה שנים במקנאס, דיין-תר\"כ"},{"i":161,"n":"אבולעפיה, דוד מירושלים","f":"אליהו","bt":"תרנג","bp":"גליפולי","b":"עלה לירושלים-תרפא, מראשי העדה הספרדית בירושלים, ממיסדי שכונת \"רמת דוד\"."},{"i":162,"n":"אבולעפיה, זרחיה הלוי","f":"מאיר","k":"ר' זרחיה הקדוש","dt":"ד'תתקעה","b":"מחכמי ספרד, נהרג על קידוש השם"},{"i":163,"n":"אבולעפיה, חזקיהו דוד מירושלים","k":"בעל בן זקונים?","dt":"תקלג - ז חשון","dp":"ירושלים","b":"מחכמי טריאסט, טבריה וירושלים, אולי הוא מחבר הספר \"בן זקונים\" ליוורנו תקנד, \"וידבר דוד\", \"מזמור לדוד\" ליוורנו תקע."},{"i":164,"n":"אבולעפיה, חיים","b":"בשליחות בליוורנו, והספיד שם את החיד\"א-תקסז."},{"i":165,"n":"אבולעפיה, חיים (השני) מטבריה","f":"יעקב","k":"בעל עץ חיים","bt":"תכ","bp":"חברון או טבריה","dt":"תקד - ו ניסן","dp":"חברון או טבריה","b":"נכד ר חיים אבולעפיה הזקן ונכד(-אבי אמו) ר יצחק בן ג'מיל. עבר לירושלים ולמד בישיבת \"בית יעקב\" לר יעקב חגיז, שבראשה עמד אז ר משה גלנטי, ובין חבריו לישיבה ר חזקיהו די סילוא בעל \"פרי חדש\". בשנת תנט בשליחות בתורכיה. בשנת תפ כיהן כרבה של אזמיר (התמנה גם לרב באמשטרדם על מקום ר יצחק בן דנא די בריטו אולם נשאר באזמיר), ועזר רבות לקהלה גם במצבם החומרי. זכה שם לכבוד רב גם מהגויים. מושל טבריה דאהר בן עומר הזמינו לטבריה לחדש את הישוב ור חיים עלה עם משפחתו והביא יהודים רבים עמו, לאחר שנחלש מסר את ההנהגה לבנו יצחק, ספור המאורעות בטבריה בספר \"זמרת הארץ\" לחתנו ר יעקב בירב. חיבר \"עץ חיים\" אזמיר תפט, \"מקראי קדש\" אזמיר תפט, ועוד. חתן נוסף היה ר חיים וינטורה. אולי בן נוסף הוא ר יחזקאל מטבריה. נספד בספר \"שארית יעקב\" לר יעקב אלגזי. הסכים על \"כנסת הגדולה\"-תצד, \"עבודת ישראל\"-תצז, \"מר דרור\"-תץ, \"חמדת ימים\" ועוד. (לפי רוזניס היה נכד ר יעקב ולא בנו ונולד בצפת תלו, והיה אחיו מאמו של ר שלמה אלגזי מירושלים ומצרים."},{"i":166,"n":"אבולעפיה, חיים הזקן - המוסמך","f":"יעקב מדמשק","k":"המוסמך","bt":"שמ בערך","bp":"צפת כנראה","dt":"תכז-ח - תמה","dp":"ירושלים","b":"מצאצאי ר יעקב בירב (אביו ר יעקב אל מצרי-נכדו של ר יעקב בירב). דיין מחכמי צפת, תלמיד מהרימ\"ט יחד עם חבריו: ר חיים בנבנשתי בעל \"כנסת הגדולה\", ר יהושע בנבנשתי בעל \"שדה יהושע\" בבית מדרשו של ר יוסף מיטרני, מצאצאי ר מאיר הלוי אבולעפיה חברו של הרמבן. בשנת שנט בשליחות לקושטא, בלגרד, אזמיר, בשנת שסג השתקע בקושטא בשנת תה היה בירושלים, עבר לחברון והחזיק בה ישיבה. חזר לירושלים ובה נפטר. בשנת תכב עמד בראש המשלחת שיצאה לעזה לבדוק על נתן העזתי-תכב, ולדברי אחד השבתאים היה הוא הגורם לגירושו של שבתי צבי מירושלים. לפי רוזנס נפטר בשנת תמה (נמצאה חתימה ממנו על כתב שליחות ר חייא מחברון משנת - תלב). בניו - ר יעקב, ר שלמה מחברון."},{"i":167,"n":"אבולעפיה, חיים יעקב מאזמיר","f":"אליהו בן יעקב","bt":"תרמג","bp":"אזמיר","b":"מחכמי אזמיר, עלה לירושלים-תרצד. תמך בנסיון חדוש הסמיכה של ר אהרן מנדל בהר\"ן מטבריה בעל \"סמיכת חכמים\"."},{"i":168,"n":"אבולעפיה, חיים יצחק מירושלים","f":"רפאל ידידיה","dt":"תרסד - כו אדר","dp":"ירושלים","b":"מחכמי ירושלים. חתן של ר דוד בן שמעון(=דב\"ש). חתם על ההסכם עם משפחת הנדיב ר חיים גדליה, בשנת תרכה הוצא קונטרס \"ארשות החיים\" ירושלים תרכה."},{"i":169,"n":"אבולעפיה, חיים ישכר מטבריה","f":"יוסף דוד","b":"חתנו של ר אברהם עזריאל ממשפחת בעל \"כפי אהרן\", בין השנים תרעא- תרעט היה ממלא מקום הרב הראשי בטבריה, וחברי בית דינו - ר יעקב הכהן סקאלי, ר יעקב חי זריהאן, ר שמואל קיקי."},{"i":170,"n":"אבולעפיה, חיים מדמשק","b":"חתן ר יעקב בירב המוסמך. בנו - ר יעקב מגליפולי."},{"i":171,"n":"אבולעפיה, חיים מצפת ואזמיר","f":"דוד","k":"בעל נשמת חיים","bt":"לאחר תן (תס?)","bp":"ירושלים או טבריה","dt":"תקלה -ה-כה אד\"ב","b":"פוסק, דיין בצפת, בן אחיו של ר חיים אבולעפיה בעל \"עץ החיים\" ולמד אצלו, ואצל ר יצחק הכהן רפפורט בעל \"בתי כהונה\", סמוך לשנת תק רב בלאריסה ובין תלמידיו שם ר יוסף נחמולי שהיה גם סופרו והיה רב שם על מקומו אחריו. בשנת תקטו גלה עם רבים מהקהלה לשלוניקי בגלל גזרות. בשנת תקכא נתמנה לרב הקהלה הספרדית באמשטרדם אולם בינתיים נתפנתה משרת הרב הראשי באזמיר ור חיים נתמנה לחכם באשי ור חיים מודעי על מקומו אחריו באזמיר. ר אליקים גאטיניו שהיה דיין בבית דינו מעיד כי בימיו של ר חיים היו נוהגים על פיו בלבד. רבים מפסקיו בספרי חכמי דורו. חבורו הגדול על הסמ\"ג אבד בשרפה באזמיר בשנת תקלב יחד עם שאר חבוריו, חיבר \"נשמת חיים\" שלוניקי תקס. תלמידו ר יוסף נחמולי הדפיס בספרו \"אשדות הפסגה\" את פירושו של ר חיים להגדה, כמה מספריו בכתב יד היו בידי החידא אך אבדו. (אצל גאון במילואים תאריך פטירתו - יד חשון תקלה)."},{"i":172,"n":"אבולעפיה, חיים נסים מטבריה","f":"יצחק","k":"חנ\"א","bt":"תקלה (באו תקנה)","bp":"סופיה","dt":"תרכא - כח שבט","dp":"ירושלים","b":"עלה עם אביו (שהוזמן ע\"י ר חיים פרחי לכהן בה כרב) לטבריה, רבה של טבריא, רגלו נשברה ברעש-תקצד. בשנת תקסה חתום עם רבני טבריה, בשנת תקע חתום עם רבני צפת על בקשת עזרה, בשנת תקפה נתמנה כרב ומנהיג הקהלות צפת וטבריה במקום אביו. בשנת תקצד נפצע ברעש בצפת, בעקבות המאורעות הקשים, עבר לארם צובה ואח\"כ לדמשק. היה חותנו של ר שלום משה חי גגין-תרה בנו של הראשון לציון, מאז נשאר בירושלים בהוראת הרב אברהם חיים גאגין. בשנת תר חתם על כתב שליחות ר חיים שמואל הכהן. בשנת תרטו נתמנה \"ראשון לציון\" לאחר פטירת ר יצחק קובו. השאיר כמה חבורים בכתב יד, וביניהם \"קרא חנא\", \"ארש צבי\" . כמה מפסקיו בספר \"בני בנימין\" לר בנימין מרדכי נבון."},{"i":173,"n":"אבולעפיה, חיים שלמה","f":"יחזקאל בן חיים","k":"בעל הניסים","bt":"תקעו","bp":"טבריה","b":"מחכמי טבריה, נכדו של ר חיים אבולעפיה בעל \"עץ חיים\", בשנת תקעו בשליחות קהילת טבריה ואז הדפיס בליוורנו \"זמרת הארץ\" לר יעקב בירב. את כתב שליחותו הדפיס הרב טולדנו בספרו \"שריד ופליט\". בשנת תקפט בשליחות באיטליה ובתונס ושם כונה בשם \"בעל הנסים\""},{"i":174,"n":"אבולעפיה, טודרוס הלוי - ג","f":"יהודה","k":"בעל גן משלים והחידות","bt":"ז","bp":"ספרד","dt":"סז","b":"מקורב למלכות, פייטן, משורר, דיין בטוליטולא(=טולידו)."},{"i":175,"n":"אבולעפיה, טודרוס הלוי - הזקן","f":"יהודה הלוי","dt":"ד'תתקפה","b":"מגדולי יהדות ספרד, נגיד ונדיב בבורגוס(ספרד), ראש קהילות היהודים בקשטיליה, ביער את הקראים מקשטיליה. לכבודו חיבר ר יהודה הלוי את \"מלחמת החכמה והעושר\". בנו - ר מאיר הלוי."},{"i":176,"n":"אבולעפיה, טודרוס הלוי - הנכד","f":"יוסף","k":"בעל אוצר הכבוד","bt":"ד'תתפ? או תתקצד","bp":"בורגוס(ספרד)","dt":"ד'תתקצד או ה'נח","dp":"טולידו","b":"נכד ר טודרוס הזקן. מקובל, פייטן, עשיר, שר בקסטיליה. בנו - ר לוי. הרמ\"ק מביא ממנו ב\"פרדס רימונים\" ומספר שחיבר \"מערכת האלקות\". חיבר \"אוצר הכבוד\" - בכת\"י, אולי חיבר גם \"עליות יבמות\"."},{"i":177,"n":"אבולעפיה, י'","dt":"תקמא - ט אייר?","b":"בשליחות-תקכד עם החיד\"א ועם הרב ן' אשר. אולי הוא שנספד ב\"קול שמואל\", וב\"בן פדהצור\"."},{"i":178,"n":"אבולעפיה, ידידיה","f":"יעקב אלמצרי","b":"רב-שנת ת\"ס"},{"i":179,"n":"אבולעפיה, ידידיה מאזמיר","dt":"תמד - כט אלול","dp":"אזמיר","b":"רב באזמיר בזמן ר חנן אלדיס. כנראה תלמידו של מהר\"ח אלפנדרי באזמיר. מוזכר ב\"שארית יעקב\"."},{"i":180,"n":"אבולעפיה, ידידיה מאזמיר","dt":"תקמג - כג אד\"א","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":181,"n":"אבולעפיה, ידידיה רפאל חי","k":"היר\"א-בעל צדק ושלום","bt":"תקסז","bp":"ירושלים","dt":"תרכט - טו סיון","dp":"ירושלים","b":"מגדולי המקובלים בדורו, ראש ישיבת \"בית אל\" על מקום ר אברהם גאגין, תלמידו וסופרו של ר אברהם שלום שרעבי נכד הרשש. מתלמידיו ר מאיר אוירבוך ור יעקב ליב לעווי, חתום על מכתבים והסכמות, וביניהם כתב שליחות ר מיכאל בדהב בשנת תרה. הסכים על ספר \"עץ חיים\" לר חיים רפאל ויטאל, ועל ספר \"חמדה גנוזה\". חיבר \"צדק ושלום\" נדפס בסוף \"שער הכוונות\" לר חיים ויטאל ירושלים תרכג, כתב הקדמה ופירוש לספרי ר חיים ויטאל ירושלים תרכג-תרלא. נפצע ברגלו מרסיסי כדור, לאחר שהתפללו על יושבי ירושלים שלא יפגעו, בסופו של דבר נפטר מכך. חתם שמו גם - הצעיר\"א.","bk":[["דרך ושלום",""]]},{"i":182,"n":"אבולעפיה, יהודה הלוי מספרד","f":"מאיר","b":"מחכמי ספרד בדורו של הרמב\"ם"},{"i":183,"n":"אבולעפיה, יהודה מטבריה","f":"יוסף דוד אבולעפיה","b":"רב בטבריה,דמשק,צידון-תר\"ע"},{"i":184,"n":"אבולעפיה, יוסף דוד (הזקן)","f":"ישכר","dt":"תקצז","dp":"טבריה","b":"מחכמי דמשק שעלה לטבריה, בשנת תקעז בשליחות בארם צובא, בשנת תקפח כיהן כאחד הרבנים בטבריה. הסכים על \"פאת השלחן\" בשנת תקצו, חתם על \"קול מדבר\" גילוי דעת על חלוקת כספים. בנו - ר יהודה מטבריה ודמשק וצידון. אחיו - ר חיים דוד מאזמיר (ואם כך - שם אביו דוד)."},{"i":185,"n":"אבולעפיה, יוסף דוד (הנכד)","f":"ישכר","bp":"סופיה","dt":"תרנו-ח - טו שבט","dp":"טבריה","b":"מחכמי דמשק בשנת תריז, עלה לטבריה ושימש כרב בשנת תרמג, צפת. הסכים על ספר \"אריה שאג\" לר יהודה ליב צייטלין בשנת תרנז. חתם על כתב שליחות ר בן ציון אלקלעי בשנת תרמח, על כתב שליחות ר דוד יבגי. בניו: ר חיים ישכר, ר יהודה. חתנו - ר שמואל בן קיקי."},{"i":186,"n":"אבולעפיה, יוסף הלוי מטולדו","f":"טודרוס","b":"מגדולי מקובלי ספרד בטולידו-ס וחברו של ר משה די ליאון שהקדיש לו את ספרו \"הרמון\", והעיד לפני ר יצחק דמן עכו על אמיתות ספר הזהר."},{"i":187,"n":"אבולעפיה, יוסף הלוי מטולידו","f":"שלמה","dt":"קב-קכ","dp":"אשביליה","b":"מחכמי ספרד, יועץ למלך, נהרג."},{"i":188,"n":"אבולעפיה, יוסף שמואל מטבריה","f":"מאיר ישכר","k":"בעל ישא ברכה","bt":"תרה","bp":"טבריה","dt":"תרנד - כא תשרי","dp":"מוגאדיר-מרוקו","b":"מחכמי טבריה, תלמיד ר שמואל קונוורתי. חיבר שות \"ישא ברכה\" בכתב יד. חיבר פיוט לכבוד ר מאיר בעל הנס. בשליחות במרוקו בשנת תרלב, ושם נפטר."},{"i":189,"n":"אבולעפיה, יחזקאל אליעזר","f":"חיים בן יעקב-עץ חיים","dt":"תקם-ד","dp":"טבריה","b":"מחכמי טבריה, בשנת תקד רבה של טבריה אחר פטירת אביו, בשנת תקכו בשליחות בתורכיה, בשנת תקלח חתם על כתב שליחות ר חיים שלום עמאר. מבניו: ר מיכאל רפאל שבתי, ר חיים שלמה."},{"i":190,"n":"אבולעפיה, יחזקאל אליעזר","f":"חיים שלמה בן יחזקאל","dt":"תריט","dp":"טבריה","b":"מחכמי טבריה, חתנו של ר חיים שבתי לאגו בעל \"שמחת עולם\", חי בליוורנו ועלה לטבריה. בשנת תקפז בשליחות באיטליה, בשנת תקצט הדפיס בליוורנו \"בן המלך והנזיר\". בפדובה הסכים על ספריו של ר מרדכי גירונדי."},{"i":191,"n":"אבולעפיה, יחזקאל אליעזר מטבריה","f":"רפאל שבתי","b":"מחכמי טבריה. בשליחות-תקפז עד תקצה."},{"i":192,"n":"אבולעפיה, יעקב","f":"ידידיה אבולעפיה"},{"i":193,"n":"אבולעפיה, יעקב מגליפולי וצפת","f":"חיים מדמשק","bp":"צפת","dt":"שס","dp":"צפת","b":"נכד(-בן בתו) של ר יעקב בירב המוסמך, למד אצל סבו ונסמך על ידו, למד גם אצל ר שלמה אבסאבן. רב בגליפולי ואחר כך בדמשק-שג ומתלמידיו שם ר יאשיהו פינטו, חזר לצפת. חברי בית דינו בדמשק - ר משה אלשיך ור שמואל כליף. בהיותו בצפת היה ממתנגדי האר\"י. מתשובותיו בספרי חכמי דורו. בניו: ר משה, ר חיים הזקן מירושלים. לדעת ניפי-גירונדי היה חתן ר חיים ויטאל בעל \"עץ חיים\", והוא שחיבר \"זמרת הארץ\" - זקנו - ר יעקב בירב היה נקרא יעקב אל מצרי."},{"i":194,"n":"אבולעפיה, יעקב מטבריה","f":"יוסף דוד","bt":"תקעב","bp":"טבריה","dt":"תרלט","dp":"טבריה","b":"מחכמי טבריה, ניצל מהרעש בתקצז, בשנת תר חתם על כתב שליחות ר חיים קונוורתי, וחתימות שונות על מסמכים בטבריה."},{"i":195,"n":"אבולעפיה, יעקב מטבריה - הנכד","f":"חיים המוסמך","b":"ראב\"ד בטבריה-תמ על מקום ר ברוך מאיסטרו. בנו ר חיים אבולעפיה השני."},{"i":196,"n":"אבולעפיה, יעקב מקושטא וטבריה","f":"ישכר","dt":"תקנב - ט תשרי","dp":"טבריה","b":"מחכמי קושטא, עלה לטבריה בשנת תקמט, וכיהן שם כרב. בשנת תקן חתם על כתב שליחות ר יהודה סג'רי."},{"i":197,"n":"אבולעפיה, יעקב מקושטא וטבריה","f":"ישכר","bp":"קושטא","b":"מחכמי קושטא, עלה לטבריה. חתם על כתב שליחות ר נחום הכהן מזרחי בשנת תרכח, ועל כתבים שונים. לדעת גאון הוא תרגם את ספר \"מנורת המאור\" ללדינו."},{"i":198,"n":"אבולעפיה, יצחק מאמאסיה","b":"מחכמי אמאסיה(=מסיא)-תורכיה-רסה."},{"i":199,"n":"אבולעפיה, יצחק מטבריה","f":"ישכר","dt":"תקפה - כז אייר","dp":"ירושלים","b":"מחכמי טבריה, נכדו של ר חיים אבולעפיה ואביו של ר חיים נסים אבולעפיה. בשנת תקסח קנה שטח גדול וצרפו לשכונה היהודית, בשנת תקעו חתם על כתב שליחות ר חיים רפאל סגרי. היה רבם של טבריה ושל צפת 31 שנה, בשנת תקפא ברח מהשר הממונה לירושלים. נהרג כתוצאה מהעינויים שעבר, וגם בהלויתו בירושלים, התפרעו ערביי סילואן ותקפו את המלווים בדרישתם לבקשיש."},{"i":200,"n":"אבולעפיה, יצחק מטבריה","f":"חיים - עץ חיים","k":"בעל פחד יצחק","dt":"תקמה - ט אייר","dp":"קוסקונג'וק-קושטא או סופיה","b":"רב בטבריה-תקד על מקום אביו (שהיה מחדש הישוב בטבריה), חתם על אגרות שונות עם חכמי צפת. בשליחות בחו\"ל - השד\"ר הראשון של קופת ר מאיר בעל הנס, רב בבלגרד, סופיה, ישב בדמשק-תרי? (התאריך לא מסתדר), בדרכו נפטר. הסכים על \"יד מלאכי\"-תקכז. חיבר \"פחד יצחק\" בכת\"י. כתב הקדמה לספרו של גיסו - ר יעקב בירב \"זמרת הארץ\". לפי רוזניס נפטר בסופיה תקע בערך."},{"i":201,"n":"אבולעפיה, יצחק מטבריה ודמשק","f":"משה או חנ\"א","k":"בעל פני יצחק","bt":"תקפד","bp":"ירושלים","dt":"תרע","dp":"ירושלים","b":"נכד ר חיים נסים (ויש אומרים - בנו). מחכמי טבריה, בשנת תרל רב בדמשק, אזמיר. חיבר \"פני יצחק\" ארם צובא תרלא, \"לב נשבר\". חזר לירושלים, היה מחכמי ישיבת המקובלים \"בית גדליה\", חתום על הסכמות פסקים ואגרות. חתנו - ר משה לניאדו. (כנראה זהה לר יצחק בן חיים נסים (חנ\"א)."},{"i":202,"n":"אבולעפיה, יצחק מסופיה וטבריה","f":"ישכר","dt":"תקעט - טו אלול","dp":"ירושלים","b":"רב בסופיה, עלה לטבריה וכיהן שם כרב, ברח לירושלים מאימת הפחה."},{"i":203,"n":"אבולעפיה, יצחק מרדכי","f":"חנ\"א מירושלים","k":"בעל פני יצחק","b":"מצאצאי בעל עץ חיים. רב בטבריה-תרל, והסכים אז על ספר אחיינו ר יצחק בן משה. בשליחות הקהלה בירושלים וכיהן כרב בדמשק, צפת, טבריה. (כנראה הוא זהה לר יצחק בן משה מטבריה)."},{"i":204,"n":"אבולעפיה, ישכר מטבריה","f":"יוסף דוד","bp":";","dt":"תרל","dp":"צידון","b":"מחכמי טבריה, בשנת תריז חתם עם חכמי טבריה."},{"i":205,"n":"אבולעפיה, ישכר מטבריה","f":"חיים - עץ חיים","bt":"תפו","bp":"אזמיר","dt":"תקמא - ט אייר","dp":"סופיה (טבריה?)","b":"עלה עם אביו מאזמיר לטבריה. בשליחות קהלת טבריה בארצות הבלקן, ונתמנה לרב בבלגרד-תקכו על מקום ר שלמה שלם ור עזריאל יחיאל מאגריסו על מקומו אחריו, היה בליוורנו-תקכז והסכים שם על \"יד מלאכי\", דיין בשלוניקי-נאלץ לעזוב אחרי תקלב ועבר ללארסו, ואח\"כ בראש ישיבה בסופיה-תקלג (בזמן ר ראובן בן יעקב), נתמנה לעמוד בראש הישוב בטבריה לאחר פטירת אחיו (ולפי זכרון שלוניקי - נפטר בסופיה). העתיק כת\"י ר יצחק הכהן מירושלים בשם \"ספר הזכרון\". הסכים על \"יד מלאכי\"-תקכד."},{"i":206,"n":"אבולעפיה, לוי הלוי מספרד","f":"טודרוס-אוצר הכבוד","b":"מקובל מחכמי ספרד"},{"i":207,"n":"אבולעפיה, מאיר ישכר מטבריה","f":"יחזקאל אליעזר","k":"רב משרשיא","bt":"תקסט","bp":"[טבריה]","dt":"תרמו - כא חשון","dp":"טבריה","b":"מחכמי טבריה, בשליחות במצרים-תריד, במרוקו-תריז. בנו - ר חיים ישכר מטבריה."},{"i":208,"n":"אבולעפיה, מאיר מטולידו","f":"יוסף הלוי","dt":"קט - סיון","dp":"טולידו","b":"גביר מחכמי טולידו."},{"i":209,"n":"אבולעפיה, מאיר מספרד","f":"טודרוס הלוי מטולדו","k":"הרמ\"ה - בעל יד רמ\"ה","bt":"ד'תתקל (1170)","bp":"בורגוש-ספרד","b":"גדל בטולדו שם כיהן אביו כרב. חתן ר יוסף ן שושן והיה גיסו של ר אברהם אלפאכר-שר ומקורב למלך בטולדו. דיין אצל אביו יחד עם חברו ר אברהם הירחי בעל המנהיג. רב בטולידו על מקום אביו וראש ישיבה, וכונה בתואר \"נשיא\". מגדולי הרבנים בדורו וחיבר פירושים בתלמוד בשם \"פריטי פריטין\". חיבר גם פיוטים. התנגד לפילוסופיה וניסה להגביל בגיל את לימוד הרמבם והיה במחלוקת עם ר אהרן מלוניל על כך."},{"i":210,"n":"אבולעפיה, משה","b":"רב בדמשק,נתפס ועונה בעלילת דמשק-ת\"ר"},{"i":211,"n":"אבולעפיה, משה מגליפולי וצפת","f":"יעקב בן חיים","dp":"צפת","b":"רב בגליפולי בשנת שפ, עלה לצפת יחד עם אביו. רוזנס אומר כי נפטר בצפת ליד ר יוסף קארו."},{"i":212,"n":"אבולעפיה, משה מדמשק","f":"חיים נסים","b":"רב בדמשק. נאסר ועונה בעלילת הדם בדמשק-תר. בנו - ר יצחק בעל \"פני יצחק\" חתם גם בשם אביו - \"יצחק משה\"."},{"i":213,"n":"אבולעפיה, מתתיה ג'יליבי מטבריה","dt":"תקצא - לפני","b":"מחכמי טבריה, בשליחות בתורכיה, ותשובה ממנו בהיותו בקושטא בענין האתרוגים, והסכים עליו השליח באיטליה (לאחר פטירתו) ר מרדכי אשיאו-תקצא."},{"i":214,"n":"אבולעפיה, מתתיהו","b":"מחכמי טבריה, בשנת תקצט בשליחות בתורכיה."},{"i":215,"n":"אבולעפיה, רפאל ידידיה","f":"חיים יצחק","bt":"תרנד","bp":"ירושלים","b":"מחכמי ירושלים, מורה בטנטה-מצרים-תרסט בהשתדלות אלברט ענתבי, עבר לארגנטינה וכיהן כנשיא הקהלה הספרדית בבואנוס איירס, חזר לירושלים-תרצח."},{"i":216,"n":"אבולעפיה, רפאל מיכאל שבתי","f":"יחזקאל","dt":"תקסז","dp":"קושטא","b":"מחכמי טבריה, נכדו של ר חיים אבולעפיה, בשנת תקמז בשליחות ובשנת תקנד בשליחות בתורכיה. בשנת תקסא בשליחות חברון בשלוניקי והדפיס את ספרו של ר חיים שבתי ולאגו \"שמחת עולם\". בנו - ר יחזקאל עזרא מטבריה - בשליחות כמה פעמים."},{"i":217,"n":"אבולעפיה, רפאל מקושטא","k":"בעל תורת המנהגות","b":"ממונה איסור והיתר בקושטא-תרמז. פסק ממנו בענין טריפות, וחלק על פסק של ר שלמה עוזיאל בעל \"ענף עץ\". חיבר ספר על מנהגי קושטא \"תורת המנהגות\" בכת\"י."},{"i":218,"n":"אבולעפיה, שלמה מחברון","f":"חיים הזקן המוסמך","b":"מחכמי חברון, בשנת תמג בשליחות בתורכיה, בהיותו בבלגדרד כתב תשובות לר משה אלמושנינו."},{"i":219,"n":"אבולעפיה, שלמה רחמים מטבריה","f":"חיים נסים-חנ\"א","dt":"תרסז - כא סיון","dp":"טבריה","b":"מגדולי חכמי טבריה, התעוור בנערותו. בשליחות-תרלא בתורכיה ומרוקו. חכם באשי בטבריה-תרנט. בשנת תרסג חתם עם חכמי טבריה, הסתלק מרבנותו בגלל מחלוקת עם ר אהרן אלחדיף."},{"i":220,"n":"אבולעפיה, שמואל מטולידו","bt":"ס","bp":"טולידו","dt":"קכא - חשון","dp":"טולידו","b":"שר האוצר של דון פדרו בקשטיליה. נהרג עק\"ה."},{"i":221,"n":"אבולעפיה, שמואל מספרד","b":"מחכמי ספרד, אביו של ר אברהם אבולעפיה."},{"i":222,"n":"אבומאי הכהן גאון פומפדיתא","f":"אברהם","b":"גאון פומפודיתא-ד'תקעא על מקום קרובו-בן דודו רב כהנא בן רב חנינא בן רב אברהם גאון, ולפי רב שרירא גאון נבחר ע\"י חלום. ר יוסף בן רבא גאון על מקומו אחריו. גאון סורא בזמנו היו רב יעקב הכהן בן רב מרדכי, ורב אבומאי גאון (בעל אותו השם)."},{"i":223,"n":"אבומאי הכהן מסורא","b":"אחיו של ר מרדכי כהנא-אביו של ר יעקב. גאון בסורא ורב צדוק (יצחק) על מקומו אחריו. בזמנו היהו בפומפדיתא רב יוסף בן רב גאון, רב באומאי, ורב אברהם."},{"i":224,"n":"אבון","f":"אברהם","b":"מחכמי ספרד, דיין בבי\"ד של הרשב\"א"},{"i":225,"n":"אבון","b":"אביו של רבנא משה-זקנו של ר משה הדרשן."},{"i":226,"n":"אבון ממגנצא","f":"יצחק בר אבון?","k":"רבינו אבון הגדול","b":"מצאצאי ר יוסף הזקן בן ר שמעון ממנש-צרפת, רב במגנצא-ד'תש, בזמן רב שרירא גאון בבבל, בניו ר יהושע הגדול, ר יצחק החסיד, ואולי נכדו הוא ר שמעון הגדול בן ר יעקב בן משה בן אבון."},{"i":227,"n":"אבון מספרד","f":"שאול ?","b":"פייטן בספרד-ד-תת. חיבר סליחה ופיוטים במחזור אביגניין והראן. נספד מאת ר משה ן עזרא. כנראה אינו המשורר שנזכר אצל אלחריזי שהיה לפני ר שמואל הנגיד. לדעת צונץ הוא ר אבן בן שאול שנזכר אצל הראב\"ד בעל האשכול כר אבון ממיורקא."},{"i":228,"n":"אבון-אבין ממיורקה","b":"תלמיד הרי\"ף. מחכמי ספרד-ד'תתן-תתק - ויתכן והוא ר אבין בן שמואל הנזכר במחזורים."},{"i":229,"n":"אבועזיז, ישכר מירושלים","b":"תלמיד ישיבת שער אורה בירושלים מיסודו של ר חזקיה שבתי יהושע, ותלמיד חבר של ר סלמן אליהו. רב בירושלים וש\"ץ ביה\"כ המכוונים של ישיבת פורת יוסף."},{"i":230,"n":"אבועזיז, מסעוד ממוסתגאנם-מרוקו","b":"מחכמי מוסתגאנם. נזכר ב\"אוצר המכתבים\" לר יוסף משאש."},{"i":231,"n":"אבוקארא, אברהם מתונס","f":"משה","k":"בעל בן אברהם","dt":"תרם","b":"פוסק ומקובל, אב\"ד קהלת פורטוגזים בתונס."},{"i":232,"n":"אבוקארא, שמשון מתונס","k":"בעל עת לדבר","dt":"תרמב","dp":"תונס","b":"מחכמי תונס-תרך, סופר סת\"ם."},{"i":233,"n":"אבוקיה, יעקב מאלגיר - הנכד","f":"משה","bt":"תקי - בערך","dt":"תקץ - בערך","b":"רב באלגיר (עזב לאחר פרעות תקסה-תקעה), ליוורנו, ארץ ישראל, בשליחות בשנת תקפא בצפון אפריקה. היה בליוורנו-תקפא והגיה את \"קרבן אשה\" לר אליהו שמעא הלוי. הסכים על ספר \"ברית אברהם\" לר אברהם בושערה. בספריה הלאומית ספר בחתימתו משנת תקנה. כנראה נכד ר יעקב השליח מירושלים שהשתקע באלגיר."},{"i":234,"n":"אבוקיה, יעקב מירושלים - הזקן","b":"מחכמי ירושלים, רב במצרים, בשליחות בצפון אפריקה-תנא. בשנת תס חתם בירושלים על תעודה בדבר חלוקת תרומות. יתכן והשתקע באלגיר והוא הנזכר ב\"בית יהודה\" לר יהודה עיאש - ונכדו ר יעקב בן משה מאלגיר."},{"i":235,"n":"אבוראבי, יצחק ממגנישיאה","f":"חיים","b":"רב במגנישיאה-שנות ה-ש'."},{"i":236,"n":"אבורביע, אברהם מטריפולי","bt":"תקי","dt":"תקף - בערך","dp":"טריפולי","b":"רב בטריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":237,"n":"אבורביע, יוסף ממרוקו וירושלים","bt":"תקצח","bp":"טיטואן","dt":"תרעח","dp":"ירושלים","b":"מחכמי מרוקו, עלה לירושלים בשנת תרסו."},{"i":238,"n":"אבורביע, משה מאלקלעא","b":"מחכמי אלקלעא. נזכר ב\"עץ חיים\" לר חיים גאגין."},{"i":239,"n":"אבורביע, עמרם ממרוקו","f":"שלמה","k":"בעל נתיבי עם","bt":"תרנב-ד","bp":"טיטואן","dt":"תשכז - ז טבת","dp":"פתח תקוה","b":"עלה ממרוקו לירושלים עם סבו, ולמד בישיבת \"טובי ישבעו\" לעדת המערבים. תלמיד וחתן ר יוסף חיים הכהן בעל \"מנחת כהן\". ר\"מ בישיבת \"פורת יוסף\" בירושלים, ובישיבת \"שערי ציון\" אצל ר בן ציון מאיר חי עוזיאל הרשל\"צ. דיין בבית הדין לעדת המערבים בירושלים. רב בפתח תקוה-תשיא ומדייניו שם היה ר עובדיה יוסף שנהג לשלוח את ילדיו לנשק את ידי ר עמרם.","bk":[["נתיבי עם - מנהגי ירושלם ובית אל, בירורי הלכות על שו\"ע, ודרשות",""],["נתיבי עם",""]]},{"i":240,"n":"אבורביע, פיג'ו מאריף-מרוקו","b":"מחכמי אריף-מרוקו, מכתב אליו מהיעב\"ץ, ר יהודה ן עטר ור אברהם ן דנאן-תעח."},{"i":241,"n":"אבורביע, שלמה ממרוקו","f":"יוסף","bt":"תרנג","bp":"מרוקו","dt":"תרעו - יז תמוז","dp":"ירושלים","b":"רב בטיטואן, עלה לירושלים והחזיק ישיבה בשם \"אור זרוע\". חיבר חדושים בכת\"י והחזיקם בנו ר עמרם אבורביע מירושלים."},{"i":242,"n":"אבורדיאל, אברהם ממצרים","b":"רב במצרים בדור שלאחר הרדב\"ז."},{"i":243,"n":"אבושדיד, אברהם מירושלים - הזקן","b":"מחכמי מרוקו, עלה לירושלים והיה מראשי העדה המערבית. בנו - ר רחמים שלמה מירושלים."},{"i":244,"n":"אבושדיד, אברהם מירושלים - הנכד","bp":"ירושלים","dt":"תרץ - ט אדר","dp":"תל אביב-ירושלים","b":"נכד ר אברהם ממרוקו וירושלים. ד\"ר לרפואה, רופא ב\"משגב לדך\" בירושלים."},{"i":245,"n":"אבושדיד, חיים מירושלים","dt":"תרמב - יד טבת","b":"דיין, מעסקני כולל המערבים בירושלים, חתם על שטר-תרכג. בשליחות בתונס-תרלז."},{"i":246,"n":"אבושדיד, משה מפאס","bp":"ראבאט","dp":"ירושלים","b":"מחכמי פאס-שנות ה-ת', ומלמד תורה, עלה לירושלים."},{"i":247,"n":"אבושדיד, רחמים שלמה מירושלים","f":"אברהם","k":"רח\"ש","b":"מחכמי העדה המערבית בירושלים-תרמא, חתם על תעודה עם ר דוד ן שמעון, ור משה מלכא."},{"i":248,"n":"אבושערה, יעקב ממצרים","b":"רב במצרים-שנות ה-ת'."},{"i":249,"n":"אבותבוט, שלום מירושלים","b":"מחכמי ירושלים, חתם-תיז על אגרת ר ברוך גד בענין עשרת השבטים."},{"i":250,"n":"אבזי, דוד","k":"בעל צורת הארץ","b":"חי בשנות ה-ש'."},{"i":251,"n":"אבזמיל, יצחק","b":"מגדולי חכמי מצרים"},{"i":252,"n":"אבזרדאל, אברהם מירושלים","k":"ן אבוזארדאל; ן בזכנד","bt":"רכג","bp":"ספרד","dt":"רפג","dp":"ירושלים","b":"עלה מטולדו לירושלים, נזכר בשו\"ת הרדב\"ז ובמחזיק ברכה ובחדושי דינים לרבני ירושלים הקדמונים, פסקי דינים ממנו ב\"שיורי ברכה\"."},{"i":253,"n":"אבזרדאל, בנימין משלוניקי","dt":"תא - ה אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":254,"n":"אבזרדאל, יצחק משלוניקי","dt":"שפא - ב תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":255,"n":"אבזרדאל, יצחק משלוניקי","dt":"תיא - יד אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":256,"n":"אבזרדאל, מוסא ממרוקו וירושלים","b":"עלה לירושלים-שא עם ר יצחק בר מוסא."},{"i":257,"n":"אבזרדאל, עיוש מפאס"},{"i":258,"n":"אבזריאל, אברהם מירושלים","bp":"ספרד","b":"תלמיד ר יצחק די ליאון בספרד, לאחר הגירוש עלה לירושלים. מקובל מחכמי ירושלים, בקי במנהגי ירושלים."},{"i":259,"n":"אבטאן, יצחק מדרעא-מרוקו","dp":"דרעא-מרוקו","b":"צדיק מחכמי דרעא-מרוקו, באים להשתטח על קברו."},{"i":260,"n":"אבטאן, יצחק ממוגאדור וטבריה","dp":"טבריה","b":"רב במוגאדור-מרוקו, עלה לארץ והתישב בטבריה."},{"i":261,"n":"אבטאן, שלמה ממרוקו","dt":"תרצו - אייר","dp":"מראקש","b":"מחכמי מראקש. נכד ר יעקב אבטאן."},{"i":262,"n":"אבטליון מאיטליה","f":"מרדכי ממודנא","bt":"רצט","dt":"שעא","dp":"פיררה","b":"רופא, תלמיד מהר\"ם פאדובה. מגדולי חכמי איטליה. זקנו של ר יהודה אריה ממודנא. רב במודנא, בולוניה, פיררה. מוזכר בספר \"מאור עינים\" לתלמידו ואולי גם אחיינו - ר עזריה מן האדומים. נשלח מטעם הקהלות בשנת שמא (או שעא) אל האפיפיור גרגוריו ה-13, על גזרת שריפת התלמוד ודבר עמו בלטינית והצליח בשליחותו. חתנו - ר יהודה סאלטרו מפאנו בעל \"מקוה ישראל\". אחיינו גם ר יהודה אריה ממודנא בעל פירוש \"הבונה\" ל\"עין יעקב\" והזכיר את דודו בספרו שהיה לו גילוי אליהו. הניח חיבורים ופזמונים בכת\"י, פסק ממנו ב\"מקוה ישראל\" אודות המקוה ברוויגו."},{"i":263,"n":"אבטליון מקונסילייו ורוויגו","f":"שלמה","k":"בעל פלגי מים","dt":"שעו - יד תשרי","b":"תלמיד ר שמואל יהודה קצנלנבוגן(=קצב, מהר\"ם שי\"ק), והחזיק בציור תמונת רבו כנגד עיניו -כדי לקיים והיו עיניך רואות את מוריך. רב ברוויגו. חיבר \"פלגי מים\" (ויש חולקים על כך) - כנגד \"משבית מלחמות\" - בנוגע למחלוקת אודות המקוה ברוויגו - המקוה היה בבית אחיו ר יקותיאל והיו בו צנורות ואחיו חיבר את \"משבית מלחמות\" - להתיר את המקוה. היה מחלוקת כנגדו בענין שתיית סתם יינם - שנטה להתיר, ולבסוף חזר בו - ונזכר ב\"קלט הקמח\"."},{"i":264,"n":"אבטליון מקושטא","b":"רב בקושטא-ד'תתקלו, נזכר אצל ר בנימין מטודילא."},{"i":265,"n":"אבטליון, יעקב זאב מיפו","bt":"תרנז","dt":"תשטו - יז חשון","b":"רב בטהורן,עלה ליפו תרצ\"ח"},{"i":266,"n":"אבטליון, משה משלוניקי","b":"מחכמי שלוניקי-שע - בערך."},{"i":267,"n":"אבי אסף מאלכסנדריה","f":"יצחק","b":"מחכמי אלכסנדריה-ד'תתק. חיבר ספרים בתכונה ונעתקו ע\"י הסופר פנחס בן שלמה - בספרית הותיקן."},{"i":268,"n":"אבי דרע, יאיר","k":"אבי דרעי","dt":"שפו","b":"מרבני אלכסנדריה,דיין"},{"i":269,"n":"אבי יהודה לייב אריה מחב\"ד","dt":"ג חשון"},{"i":270,"n":"אבי נדב עבאסי","b":"חיבר פיוט ונמצא במחזורים ישנים - כת\"י \"אנא ברוב חסדיך\". עבאסי(=אריה בערבית)."},{"i":271,"n":"אבי שמואל חי בלעיש, בן הרה\"ר לתוניסיה","dt":"יא תשרי תשכ\"ז"},{"i":272,"n":"אביאוב, שמעון מחברון","f":"דוד","k":"בעל בת מלך","b":"מחכמי חברון. חיבר \"בת מלך\" ונציה תעב."},{"i":273,"n":"אביגד, זכריה","k":"בעל משפטי אמת","bt":"תרסא","bp":"צירא(תימן)","dt":"תשס - כז ניסן","dp":"ירושלים","b":"מלמד תינוקות, עלה לא\"י-תרפ\"ה, חתן ר' חייא, גר בתל אביב, בקי בנגלה ובנסתר, התפרנס כפקיד, אך כשפוטר ראה בכך אות וקיבל רבנות על ישובי המרכז, בקי בהלכות עירובין, חיבר \"משפטי אמת\" על \"חושן משפט\" בנגלה ובנסתר"},{"i":274,"n":"אביגדור","f":"דוד מללוב"},{"i":275,"n":"אביגדור אשכנזי מירושלים","f":"דוד","k":"התנא מצפת","bp":"פולין","b":"עלה לארץ אחרי שנת של היה מתלמידי הארי"},{"i":276,"n":"אביגדור בן עזריאל מירושלים","f":"ראה: עזריאל, אביגדור"},{"i":277,"n":"אביגדור הכהן מוינה","f":"אליהו","b":"תלמיד ר אלעזר בן שמואל מוירונה(-תלמיד הר\"י-בעל התוספות) והיה גם קרובו (מחותנו או גיסו), ותלמיד ר שמחה בן שמואל משפירא (ולא ר שמחה תלמיד רש\"י כמובא בחיד\"א בטעות) . חתן ר חיים בן משה מניישטט(ליד וינה). מבעלי התוספות, רב בוינה אחרי פטירת ר יצחק בעל \"אור זרוע\". תשובה אליו בשו\"ת \"אור זרוע\" (ולא כפי שסברו אחרים), ומר אהרן מוירשבורג, תשובות ממנו ב\"מרדכי\", הגהות מיימונית, \"שבולי הלקט\". אחיהם של ר אלעזר ור שניאור. חיבר פיוטים ובהם \"אל מי נקרא\". התכתב עם מהר\"ם מרוטנבורג, מתלמידיו: ר עובדיה מניישטט(-ליד וינה), ר חיים אור זרוע, ר הלל בן שמואל, ר משה בן יהושע, ויתכן שגם ר אלעזר מטוך. השיב לחכמי איטליה ובהם: ר צדקיה בעל \"שבולי לקט\", ר צדקיה השני, ר בנימין בן אברהם, ר יהודה בן אברהם, ר יחיאל בן בנימין - ונזכרו ב\"שבולי לקט\" ו\"התניא\" (וכנראה הכירוהו מימים שלמד בוירונה ואולי היה מוצאו מאיטליה)."},{"i":278,"n":"אביגדור הלוי מגלוגא - אל\"ם","f":"שמחה","k":"בעל דבר טוב","b":"מחכמי גלוגא-תקן. מחותן עם ר צבי הירש מברלין. חברו של משה מנדלסון, והדפיס מאגרותיו את \"אגרות הרמ\"ד\". חיבר גם \"דבר טוב\", ועוד. מתלמידיו - ר זמן בן שמואל בומסלא שהגיה את הספר \"מרפא לשון\" לר משה ן חביב שאותו הדפיס-פרג תקמג. מחותן עם ר צבי הירש ברלין מלונדון."},{"i":279,"n":"אביגדור הצרפתי","f":"יצחק","k":"בעל פירוש לתורה","b":"תלמיד ר יהודה ממיץ. מחכמי צרפת שנת ה'א. נזכר בספר המקנא יחד עם ר יחיאל מפאריס. חיבר פירושים לתורה בכת\"י, ומובא ממנו בעניני קבלה בספר קדמוניות ועוד. תלמידו - ר מתתיה בעל \"ספר מתת\"."},{"i":280,"n":"אביגדור חריף מפורז'אן","f":"שמואל","dt":"תקלא - טו אדר","dp":"וילנא","b":"אב\"ד בפרוז'אן-תעט, רוזנוי, וולקוביסק, פודזאלווה, עבר לוילנא-תקי אל בנו ר שמואל-האב\"ד האחרון של וילנא. נזכר ב\"מקום שמואל\" לר שמואל בן אלקנה, וב\"גבעת שאול\" לר שאול בן משה. בניו - ר שמואל-אב\"ד וילנא-חתן היסו\"ד, ר יצחק איזיק (קמינקר)."},{"i":281,"n":"אביגדור יהודה מלובלין","dt":"תרכד","b":"דיין בלובלין."},{"i":282,"n":"אביגדור מאופוטשנא","b":"מחשובי תלמידי החוזה מלובלין, ר שמחה בונם מפשיסחא ור יצחק מווארקי."},{"i":283,"n":"אביגדור מאשכנז","f":"מנחם","b":"מחכמי אשכנז-ן'. תשובות ממנו בשו\"ת מהר\"ם מרוטנבורג, ועוד, וחתם אבגדור בר מנחם זקן שמי(-והוא ר\"ת זכר קדושים נצח שלום משכבו ינוח)."},{"i":284,"n":"אביגדור מבייסיגולה","b":"אב\"ד בייסיגולה(=ביסגאלה)-פלך קובנא. אחיו - ר יחזקאל מגרינקישוק."},{"i":285,"n":"אביגדור מדובנא","f":"דוד","bp":"דובנא?","b":"חתם על מכתב ראשי קהילת ירושלים לקהילת מיץ באייר תקכח"},{"i":286,"n":"אביגדור מהמבורג","f":"משה מפרשעדבורש","b":"דיין באה\"ו-תקל אצל ר דוד ברלין, חתם עמו ועם ר משה בן הקדוש יום טוב ליפמן."},{"i":287,"n":"אביגדור מהרובישוב","f":"פנחס","b":"רב בהרובישוב"},{"i":288,"n":"אביגדור מזלחוב","b":"רב בזעלחוב"},{"i":289,"n":"אביגדור מירושלים","f":"מנחם","dt":"תקעט","dp":"ירושלים","b":"מחכמי ירושלים. ראה גם: אביגדור טוריאל מירושלים."},{"i":290,"n":"אביגדור מלבוב","f":"יעקב","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה."},{"i":291,"n":"אביגדור מלובלין","f":"מרדכי","dt":"תקסז - כב תשרי","dp":"לובלין","b":"מחכמי לובלין."},{"i":292,"n":"אביגדור מפולין וצפת","f":"יוסף","b":"עלה לארץ-ש עם אביו ר יוסף אשכנזי. תלמיד האר\"י ונזכר ב\"דברי יוסף\" לר יוסף סמברי."},{"i":293,"n":"אביגדור מפוניבז","dt":"תרכו - ט כסלו","b":"אב\"ד בעיר חדש-פלך פוניבז, מו\"ץ בפוניבז."},{"i":294,"n":"אביגדור מפעסט","b":"רב בסט' מיקלוש-תרי\"ג,פעסט-תר\"כ"},{"i":295,"n":"אביגדור מפרובנס","f":"נתן מאביניון","b":"מחכמי פרובנס-ד'תתקן. נזכר בספר המנהיג כר אביגדור בן רבנו נתן מאביניון."},{"i":296,"n":"אביגדור מקוריץ","f":"פנחס","b":"הו\"ל \"רבנו בחיי על התורה\" קורץ תקנט."},{"i":297,"n":"אביגדור מקידאן","b":"מצאצאי ר אורי שרגא פיבוש אשכנזי מוילנא וירושלים. מחכמי קידאן. בנו - ר יצחק מפומפיאן (כך לדעת מרקוביץ), ונכדו ר יוסף זונדל בעל \"זיר יצחק\"."},{"i":298,"n":"אביגדור מקרויצבורג-קורלנד","b":"אב\"ד קרויצבורג-קורלנד. נזכר ב\"מצב הישר\". בניו: ר יעקב אליהו ריבלין מריגא, ר ישראל ריבלין מדאנקוריא."},{"i":299,"n":"אביגדור משה יצחק בן שמואל","bt":"1801","dt":"ה'תרכה 1865","bk":[["גליוני קדש",""],["פרדס רמונים",""]]},{"i":300,"n":"אביגדור משווערוויגן","b":"רב בשווערוויגען-ת\"ע"},{"i":301,"n":"אביגדור משוורזינץ","dt":"תקכא","b":"אב\"ד שוורזינץ. הסכים על \"זבח שמואל\" פפד\"א תקיג."},{"i":302,"n":"אביגדור נחום ן, קנה","k":"בעל קנה בינה","b":"מגדולי המקובלים הקדמונים-ד'תש\"מ"},{"i":303,"n":"אביגדור סופר מאיזנשטט","f":"משה","k":"איצמונש","b":"מחכמי הדור-ש'. תרגם פיוטים ותפילות ללשון אשכנז - קרימונה שנד, חיבר ספר על גירוש יהודי אוסטריה-שסט."},{"i":304,"n":"אביגדור עזריאל מירושלים","dt":"תקח - ג טבת","dp":"ירושלים","b":"מחכמי ירושלים. חתם עם רבני ירושלים על \"בית הבחירה\" למאירי, ועל \"דרך ישרה\"-תקמח (התאריך לא מסתדר)."},{"i":305,"n":"אביגדור, אברהם ישכר בער מטרווה","f":"יעקב מפודקמין","bt":"תקצב (ולא תרי)","dt":"תרפא - יב אלול","dp":"טרווה","b":"חסיד בלז - בנו של המשב\"ק, תלמיד ר יעקב הורביץ מדלטין, רבה של טרווה-וולסקה-תרכא למעלה מששים שנה. חיבר כתבים רבים שנשרפו במלחמת העולם הראשונה, כמה מחדושיו בספר \"אביר יעקב\". חתנו של ר מנחם מנדל הורביץ מלינסק ואחר כך חתנן ר דוד גלר, מבניו ר חיים נפתלי שפירא האדמור מקאלושין(=קלושין). (בקול קורא לטובת כולל גליציה נדפס בטעות שמו כבערינברוד והוא שיבוש של בר\"י אבד בראד)."},{"i":306,"n":"אביגדור, דוד מאנדריכוב","f":"אברהם ישכר בר","k":"רודגיבא","bt":"תרנח","dt":"תשג - א תשרי","dp":"טרנוב","b":"רבה של אנדריכוב-תרפב, נסמך על ידי ר אליהו קלצקין מלובלין ור אריה ליב ברודא, נשיא \"תורה ועבודה\" בגליציה וממיסדי השומר הדתי, התקבל כרב במושב שדה יעקב אך לא הספיק לעלות ונספה בשואה. תשובות אליו מאחיו ב\"אביר יעקב\". עליו ביומנה של רוחקה ליבליך - בתוך \"קובץ האשה בשואה\"."},{"i":307,"n":"אביגדור, יעקב מדרוהוביטש","f":"אברהם ישכר בר","k":"בעל חלק יעקב","bt":"תרנו","bp":"טיראווא-ואלאסקא-מחוז סאני","dt":"תשכז - יח אדר","dp":"מכסיקו","b":"תלמיד ר נטע דים מסאניק, ר משה מייזלש מפשמישל, נסמך מאת ר מאיר אריק, ר א\"מ שטינברג מברודי ור דוד הורביץ מסטניסלב. רבה של דרוהוביטש-תרף, בוריסלב-תרפח, ניצל מהשואה ואחריה רב בברוקלין ולבסוף במכסיקו-תשי. מקורב לאדמורי גליציה, חתן ר נפתלי צבי הורביץ מצאנז, דרשן וסופר, בקי במדעים ובשפות. איבד חלק ממשפחתו בשואה, ולאחריו חתן ר מרדכי שפירא מברטש. חיבר \"חלק יעקב\" פיעטרקוב תרפט, \"אביר יעקב\" פיעטרקוב תרצד, \"איה סופר\" הספד על \"אח\"ד סופר מדרוהוביטש, \"השיב יעקב\", ועוד. פרסם מאמרים ב\"רשפי אש\" - לודז תרפז."},{"i":308,"n":"אביגדור, יעקב מפודקמין","f":"אברהם ישכר דב בר","k":"בעל חלק יעקב","bt":"תקס","dt":"תרמה","b":"רבה של פודקמין-תקץ וברודי-תרכט, חתן אחותו חיינה אוסטרוצר מאודסה. למד עם ר שלמה קלוגר, והוציא לאור את ספריו הראשונים עם הגהות ומפתחות. בניו ר אברהם ישכר בער מטרווה, ר שלום בעל \"ציון לנפש חיה\". חתניו ר משה באב\"ד מיקולניץ, ר דוד יהודה לוין. חיבר \"חלק יעקב\" בכתב יד. תשובות אליו מחכמי גליציה. רב בפודקמין, ברודי. חסיד בלז ורשם את תורות השר שלום ונסע לאדמור למורת רוחו של המהרש\"ק - שהיה ידידו."},{"i":309,"n":"אביגדור, יצחק חיים מבוריסלוב","f":"יעקב","k":"בעל טרערן נישט פארטר","bt":"תרף","bp":"דרוהוביטש?","b":"רבה של בוריסלב-תרצט (כעוזרו של אביו), הרטפורד-קונטיקט-תשטו. עבר את השואה, ניצל ועבר לאמריקה, ממנהיגי \"המזרחי\" . חיבר \"טרערן נישט פארטריקנטע\" אנטוורפן, \"מן המצר למרחב\" ניו יורק תשלו - הכולל את קורותיו בשואה, ועוד. תלמיד ר אברהם יעקב הורביץ מפרוביזנא. וחיבר \"בלעטלעך פון א טאגבוך\" - תשז, על קורותיו בשואה."},{"i":310,"n":"אביגדור-אבן גדור","f":"נחום","b":"אביו של ר אלקנה בעל ספר הקנה."},{"i":311,"n":"אביגיל, דובער","dt":"תשג","b":"רב בדוקשטי"},{"i":312,"n":"אבידור שמואל הכהן","bt":"1926","dt":"ה'תשסה 2005","bk":[["שלשה כתרים",""]]},{"i":313,"n":"אבידני, עלואן מכורדיסטן","f":"שלמה או שמעון","k":"בעל מעשה גדולים","bt":"תרנב","bp":"עמאדיה-כורדיסטן","dt":"תשכח - ט חשון","dp":"ירושלים","b":"רב בעמאדיה-כורדיסטן על מקום אביו. ממשפחה שמוצאה מפרס. גויס לצבא התורכי והיה אחראי שם על הכשרות, ברח למוסול ונדד כמה שנים. עלה לירושלים-תרצא, וכיהן כרב שכונת נחלאות, ורבה של הקהלה הכורדית בארץ."},{"i":314,"n":"אבידע-זלוטניק, י' ליב","k":"בעל מדרש המליצה","dt":"תשכה","b":"חכם וסופר,רב בפולין,בדרום אפריקה,עלה לירושלים"},{"i":315,"n":"אבידרבי, יאיר ממצרים","b":"רב באלכסנדריה-שנות ה-ר'."},{"i":316,"n":"אביה","f":"יקטן","b":"פרנס קדום, וחיבר פיוטים ובהם סליחה על הרוגי מלכות המתחילה: \"חטאנו\"."},{"i":317,"n":"אביוב, אהרן מקושטא ואישקופיה","k":"בעל שמן המור","dt":"שמב - אחרי","b":"תלמיד מהרח\"ש, מהרשד\"ם. רב בקושטא, רב בשלוניקי, דיין-שנד, רב באישקופיה(=אסקופיה)-שלא יחד עם ר אליהו ארבארו, אב\"ד באדריאנופולי-שסא, בנו - ר שלמה. חיבר \"שמן המור\" - שלוניקי שנו. מתורתו בשו\"ת מהרשד\"ם."},{"i":318,"n":"אביוב, יוסף מברושה","b":"רב בברוסה-רץ על מקום ר אברהם ן יעיש. נבחר לדיין בענין ירושת בתו של ר משה ן חביב ויורשי בעלה - אברהם די גאון הלוי. בנו - ר יעקב הרופא שנהרג עק\"ה."},{"i":319,"n":"אביוב, יעקב מאמאציא הקדוש","f":"יוסף","b":"רופא מחכמי אמאציא. נהרג עק\"ה בעלילת דם-ש'."},{"i":320,"n":"אביוב, שלמה מאסקופיה","f":"אהרן משלוניקי","dp":"אישקופיה","b":"תלמיד ר חיים שבתי בשלוניקי. מרביץ תורה באסקופיה(=אישקופיה)-שצ."},{"i":321,"n":"אביוב, שמעון","f":"דוד","b":"מחכמי ארץ ישראל, בשנת תעב היה באיטליה והדפיס \"זרע קודש מצבתה\" לר משה מפרג ביחד עם \"בת מלך\"."},{"i":322,"n":"אביזרדיל, יצחק מפאס","b":"רב בפאס-שלה, חתם על פס\"ד-שנא. היה לו ביכ\"נ בפאס ונהרס-תז."},{"i":323,"n":"אביחצירא יעקב בן מסעוד","bt":"1805","dt":"ה'תרמ 1880","bk":[["בגדי השרד",""],["גנזי המלך",""],["דורש טוב",""],["יורו משפטיך ליעקב",""],["לבונה זכה",""],["מחשף הלבן",""],["פתוחי חותם",""],["שערי תשובה",""]]},{"i":324,"n":"אביטאס, משה מפאס","b":"מקורב למלכות במכנאס, היה מעורב במחלוקת בקהלה."},{"i":325,"n":"אביטבול, אברהם מטאגרה-מרוקו","b":"מחכמי מטאגרה-מרוקו-שלט, תשובה ממנו אצל ר שמואל ן דנאן."},{"i":326,"n":"אביטבול, אברהם ממראקש","dt":"תשא - י אדר","b":"מחכמי מראקש, דיין"},{"i":327,"n":"אביטבול, אברהם מצפרו-מרוקו","f":"שאול ישועה מצאפרו","b":"מחכמי צאפרו-מרוקו."},{"i":328,"n":"אביטבול, אברהם מראבאט-מרוקו","b":"מו\"ץ בראבאט-מרוקו-תקצו עם ר אהרן אלמליח."},{"i":329,"n":"אביטבול, אברהם משה","b":"חתם שמו על שער הספר ראשית חכמה."},{"i":330,"n":"אביטבול, אברהם משה","f":"משה?","b":"חתם שמו בספר ראשית חכמה - אמשטרדם תסח."},{"i":331,"n":"אביטבול, אהרן מפאס","bt":"תרכז-כב אד\"ב","bp":"פאס","b":"רב ראשי ואב\"ד בפאס"},{"i":332,"n":"אביטבול, אליהו מאלגיר","f":"משה","b":"רב בתלמסאן-רפו. נזכר ב\"אוצר המכתבים\"."},{"i":333,"n":"אביטבול, חיים","dt":"תקצז - כא טבת","dp":"טבריא","b":"נספה במפולת ברעש"},{"i":334,"n":"אביטבול, חיים אליהו מצפרו-מרוק","f":"עמור","dt":"תרלח - סיון","b":"מו\"ץ בצפרו ואחיו ר רפאל על מקומו אחריו."},{"i":335,"n":"אביטבול, חיים מאלגיר","dt":"תרפה","b":"נכד ר חיים קצבי. רב בווהראן. הו\"ל פיוט \"מי כמוך\" מאת ר מסעוד דרמון לזכר הצלת יהודי ווהראן מידי הערבים בזמן הכיבוש הצרפתי-תקץ. נזכר ב\"קול תחנה\", \"בנפש דוד\", ועוד."},{"i":336,"n":"אביטבול, יהושע מצפרו","b":"מחכמי צפרו. בנו - ר מוסא."},{"i":337,"n":"אביטבול, יוסף ממראקש","b":"מו\"ץ במראקש-שנות ה-תק'. חתם על פס\"ד עם ר מסעוד ן מוחא, ר רפאל יוסף חרוש."},{"i":338,"n":"אביטבול, יוסף מצפרו-מרוקו","f":"שיש\"א","b":"רב בצפרו-מרוקו-שנות ה-תק'. התכתב עם ר שמואל אלבאז."},{"i":339,"n":"אביטבול, יחיא מדאדיש-מרוקו","k":"בעל יקובל האמת","bp":"מרוקו","b":"רבה האחרון של דאדיש (במדבר סהרה), בשנת תקנב עלה לצפת. חיבר \"יקובל האמת\" ליוורנו תרלט."},{"i":340,"n":"אביטבול, יחיאל מצפת","b":"מחכמי צפת, בשנת תרלו בשליחות בצפון אפריקה. כתב משם תשובות בענין שטר מתנה."},{"i":341,"n":"אביטבול, יעקב מצפרו-מרוקו","b":"רב בצפרו-מרוקו שנות ה-תר', שיר לכבודו מאת ר שמואל אלבאז ליום חתונתו בתוך \"נועם שיח\"."},{"i":342,"n":"אביטבול, יעקב מצפת","b":"רב בצפת, חתם-תקץ על שטר הרשאה עם חבריו - ר אברהם שושנה, ר יו\"ט אליקים."},{"i":343,"n":"אביטבול, יצחק מצפרו","b":"מחכמי צפרו-מרוקו, אביו של ר שאול ישועה-שיש\"א."},{"i":344,"n":"אביטבול, ישועה - הזקן","b":"צדיק מחכמי מרוקו, וזכה לגילוי אליהו. זקנו של ר שאול ישועה בעל \"אבני שיש\"."},{"i":345,"n":"אביטבול, ישראל ממרוקו","f":"יהודה","b":"מו\"ץ במרוקו. אולי הוא שחתום על שאלה מחכמי תאזא לחכמי פאס-תקלב יחד עם ר נפתלי ן גיגי."},{"i":346,"n":"אביטבול, לוי מדמנאת-מרוקו","bp":"מרוקו","b":"מחכמי מרוקו מהעיר דמנאת (ליד מארקש), עלה לירושלים, בשליחות חברון בפאס-תסו, ר יעקב אבן צור נתן לו אגרת המלצה. כתב לגיסו ר סעיד ברדע בקהיר-תסח איגרת ובה פרטים רבים אודות שליחותו."},{"i":347,"n":"אביטבול, מוסא מצפרו","f":"יהושע","b":"מחכמי צפרו."},{"i":348,"n":"אביטבול, מסעוד ממרוקו וטבריה","b":"עלה עם אחיו ר אברהם ור משה לטבריה. גיסו - ר אליהו אדהאן. בניו - ר יחיא חתן ר רפאל אוחנא, ור יעקב חתן דודו ר אליהו אדהאן."},{"i":349,"n":"אביטבול, מרדכי ממרוקו","b":"רב בפאס-תרם."},{"i":350,"n":"אביטבול, משה מאלגיר","bt":"תקך","dt":"תקץ","b":"רב בווהראן-אלגיר - תקן-תקף. נזכר באוצר המכתבים."},{"i":351,"n":"אביטבול, משה מצפת","b":"מחכמי צפת, בשליחות בשנת תקסד בצפון אפריקה. על אגרת שליחותו חתמו - ר ראובן בן יעקב מסופיה וצפת, ר חיים דוד אבולעפיה, ר אברהם סורג'ון."},{"i":352,"n":"אביטבול, עמור יוסף ממרוקו","f":"שלמה","k":"בעל שבלי העמר","bt":"תקף","bp":"צפרו","dt":"תריד - א שבט","b":"מחכמי צפרו-מרוקו, והיה עשיר ובביתו התארחו גדולי ישראל בהיותם שם. נאלץ לברוח מעירו יחד עם חברו ר יהודה אלבאז, בגלל השר המקומי, והגיע מפאס. בניו ר חיים אליהו ור רפאל, חתנו ר משה אזולאי ונכדו ר שלום אזולאי, עוד מנכדיו ר אהרן אפרייאט ור מתתיה בן זכרי. מתורתו נדפס \"מנחת העמר\", וחיבר גם \"עומר התנופה\" ועוד."},{"i":353,"n":"אביטבול, רפאל מצפרו-מרוקו","f":"עמור","bp":"צפרו","dt":"תרסט - ז אדר","dp":"[צפרו]","b":"רב בצפרו על מקום אחיו ר חיים. חתום על פסקי דין עם חכמי דורו."},{"i":354,"n":"אביטבול, רפאל מצפרו-מרוקו","f":"שאול - אבני שיש","bt":"תקל","bp":"צפרו","dt":"תקסג - א","dp":"פאס","b":"רב בצפרו-מרוקו, דרשן ומקובל. נפטר בגיל צעיר בחיי אביו. קינה לזכרו מהמשורר ר יעקב בירדוגו ממכנאס, ומר יהודה אלבאז."},{"i":355,"n":"אביטבול, שאול ישועה מצפרו","f":"יצחק","k":"בעל אבני שיש","r":"רב דצפארו במרוקו","bt":"תצט","bp":"מרוקו","dt":"תקסט - כה אלול","b":"נכד ר ישועה. תלמיד ר אליהו הצרפתי. רב בצפרו-תקך, כמעט 50 שנה. חיבר גם \"אבני קדש\", ועוד. מכתב תמיכה ממנו-תקסא לשליח טבריה ר יהודה נחמד.","bk":[["אבני שיש","שו\"ת - אחרונים"],["אבני שי\"ש - שו\"ת",""],["רבני קודש - הלכות טריפות וחידושים על התנ\"ך והש\"ס",""],["רבני קודש - הלכות טריפות וחידושים על התנ\"ך והש\"ס, אבני שי\"ש - שו\"ת",""]]},{"i":356,"n":"אביטבול, שלמה ממראקש","f":"דוד","b":"מו\"ץ במראקש, חתם-תרלב על פס\"ד."},{"i":357,"n":"אביטבול, שלמה ממראקש","b":"מראשי השבתאים במרוקו, יחד עם ר יעקב ן סעדון והנגיד מימון מימרן."},{"i":358,"n":"אביטבול, שלמה מצפרו-מרוקו","f":"מימון","dt":"תקעח","dp":"צפרו-מרוקו","b":"תלמיד ר אליהו צרפתי מפאס ונסמך ממנו. רב בצפרו-מרוקו, תחת ר שאול ישועה אביטבול בעל אבני שיש. היה בעל ספריה גדולה, ובעל צדקה גדול."},{"i":359,"n":"אביטבול, שמואל מפאס-מרוקו","f":"מרדכי","b":"מחכמי דרעא, פאס, חברם של ר אהרן מלכא, ור אהרן ן שמחון, שיצאו ביחד לעלות לארץ עם האחים ר יוסף ור חלפתא ן אליד, והגיעו עד תלמסן (ורק האחים ן אליד המשיכו בדרכם)."},{"i":360,"n":"אביטבול, שמעון מאלג'יר","bt":"תרם - בערך","dt":"תשי - בערך","b":"רב בתייארת-אלג'יר-תרף. נזכר ב\"שיח יצחק\" לר יצחק אלמליח."},{"i":361,"n":"אביטן, יהודה","b":"מחכמי ורבני מרוקו,דרשן"},{"i":362,"n":"אביטן, ישעיה ממרוקו","dt":"תרכז - כח תמוז","b":"רב בדרעא-מרוקו. חיבר ספר בהלכות שו\"ב כמנהג דרעא. בנו ר יצחק בעל \"לרץ ארח\"."},{"i":363,"n":"אביי מקושטא","b":"מחכמי קושטא-רן. בנו ר אהרן בן אביי. קינה לזכרם מאת ר מיכאל הכהן בלכו מקנדיא ששלח לבנו ר ישועה (בכתה\"ע ציון)."},{"i":364,"n":"אביי מקושטא","b":"מחכמי קושטא-שן. נזכר בשו\"ת מהרשד\"ם. הקדמה ממנו ל\"לקח טוב\" לר משה נגארה."},{"i":365,"n":"אביי, אליהו מקושטא - הזקן","dt":"שמט - אחרי","b":"רב בקושטא, חתם עם ר מהרשד\"ם, ועם ר יחיאל באסאן."},{"i":366,"n":"אביי, אליהו מקושטא - הנכד","dt":"תכו","b":"פוסק, מרביץ תורה בקושטא-ת', רב בפאלטיין-תט. תשובות ממנו ב\"פני משה\"."},{"i":367,"n":"אביכזיר, אברהם מאלגיר וירושלים","f":"שלמה או משה","bt":"תרכו או תרכא","bp":"אוראן או תאפילאלת","dt":"תשה - כח תשרי","dp":"תשה","b":"נולד באוראן להורים שמוצאם מתאפילאלת-מרוקו. עלה עם אימו לירושלים, תלמיד \"דורש ציון\" בראשות ר יצחק פרג, ר אלעזר בן טובו בעל \"פקודת אלעזר\". בשליחות באלכסנדריה-תרנב והתישב בה לבקשת ר משה פארדו-הרב הכולל - ולימד תורה, אב\"ד באלכסנדריה-תרסח, חזר לירושלים-תרפח וכיהן כנשיא עדת המערבים בירושלים, וראב\"ד עדת הספרדים."},{"i":368,"n":"אביכזיר, יעקב חי מצפת","bt":"תרמו","bp":"צפת","b":"סופר ומזכיר ביה\"ד. בשליחות צפת במצרים-תרפח, בתונס-תרצא, ובמרוקו-תרצה."},{"i":369,"n":"אביכזיר, משה ממרוקו","b":"רב בכפר בגריס(=בנריס) מנוף תאפיללת-מרוקו-תקן ודיין אצל ר יעקב אביחצירא. מתורתו ב\"שופריה דיעקב\" לר יעקב בירדוגו, שכינהו - ידיד נפשי. אסף וקיבץ ספרים רבים."},{"i":370,"n":"אביכזיר, סמחון","dt":"תרם","b":"חכם וחסיד."},{"i":371,"n":"אבילה די - משפחה","b":"משפחת רבנים שמוצאה בעיר אבילה בקסטיליה, ולאחר הגירוש הגיעו למרוקו."},{"i":372,"n":"אבילה די, אברהם","b":"שנת תק\"ל"},{"i":373,"n":"אבילה די, אליעזר - רב אד\"א","f":"שמואל משה","k":"בעל מגן גבורים","bt":"תעד","bp":"סאלי","dt":"תקכא - ג אד\"א","dp":"רבאט","b":"מחכמי סאלי, רבאט. נכד ר חיים ן עטר (או בן אחותו). רבאט, חתן ר' אליהו הלוי בן שושן, חיבר \"מגן גיבורים\" חתנו - ר שלמה די אבילה - הו\"ל את ספריו."},{"i":374,"n":"אבילה די, דוד משלוניקי","dt":"שפב - ד תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":375,"n":"אבילה די, דניאל גלייגו משלוניק","k":"בעל דיאלוגו דיל קולו","b":"רופא בשלוניקי-שס. חיבר בלדינו \"דיאלוגו דיל קולוראדו\" שלוניקי שסא."},{"i":376,"n":"אבילה די, דניאל מיאנינה","b":"רב ביאנינה-סוף שנות ה-ת'."},{"i":377,"n":"אבילה די, יהודה","b":"מצאצאי ר\"א די אבילה. נזכר ב\"קדשי דוד\" לרב חסאן שהביא מחדושיו בספרו."},{"i":378,"n":"אבילה די, יהודה ממרוקו","f":"משה","b":"מחכמי מרוקו. אחיו של ר שמואל בעל \"עוז והדר\"."},{"i":379,"n":"אבילה די, יהודה מסאלי-מרוקו","f":"יצחק בן משה","b":"מחכמי סאלי-מרוקו-שנות ה-ת'. גיסו-חתן אחות ר רפאל ן צור. אולי הוא שעלה לירושלים ולמד בישיבת כנסת ישראל של ר חיים ן עטר בעל אור החיים."},{"i":380,"n":"אבילה די, יוסף מסאלי-מרוקו","f":"יצחק בן משה","b":"מחכמי סאלי-מרוקו. חיבר פירוש בכת\"י-תעז. בנו - ר מאיר מצפרו שהיה תלמיד ר חיים ן עטר."},{"i":381,"n":"אבילה די, יעקב מאלגיר","f":"משה","b":"רב בתלמסאן. נזכר בשטר-תקץ."},{"i":382,"n":"אבילה די, יעקב ממרוקו","f":"משה","dt":"תפה - ט אב","dp":"מרוקו","b":"מחכמי מרוקו ודרשן על מקום אביו. נפטר צעיר"},{"i":383,"n":"אבילה די, יצחק מסאלי - הזקן","b":"מחכמי ארבאט, סאלי-תעז - חתם אז על פסק עם ר חנניה בן זכרי. אביו של ר משה."},{"i":384,"n":"אבילה די, יצחק מסאלי - הנכד","f":"משה","b":"מחכמי סאלי. נכד ר יצחק די אבילה הראשון. בניו - ר יהודה, ר יוסף, ור משה."},{"i":385,"n":"אבילה די, ישועה מצפרו-מרוקו","f":"מאיר","k":"בעל קיבוץ גלויות","b":"תלמיד ר משה בן חמו."},{"i":386,"n":"אבילה די, מאיר מצפרו-מרוקו","f":"יוסף מסאלי","k":"בעל קבוץ גלויות","dt":"תצג - לפני","b":"תלמיד ר משה ן חמו, ור יהודה ן עטאר. רב בצפרו-תסט, עם חבריו ר שמואל ן חותא ור ישועה בן חמו."},{"i":387,"n":"אבילה די, מסעוד ממכנאס","b":"מחכמי מכנאס וסופר שטרות-תקע."},{"i":388,"n":"אבילה די, משה ממכנאס","f":"יצחק","dt":"תפד - לפני","b":"תלמיד ר חיים ן עטר ואירחו בביתו בדרכו לעלות לארץ. מחכמי מכנאס, מלמד תורה ודרשן ולא שימש ברבנות, דיין בראבאט. חתם עם ר חיים דוד סירירו, ור שמואל ן זמרא. בניו ר יעקב, ר יצחק, ור שמואל בעל \"אוזן שמואל\" - שהיה חתן ר משה ן עטר מסאלי."},{"i":389,"n":"אבילה די, משה ממרוקו - ב","b":"דיין בסאלי-תקס. חתם עם ר שמואל די אבילא ור יוסף אלמליח."},{"i":390,"n":"אבילה די, משה מסאלי וראבאט","f":"שלמה","dt":"תפה - ט אב","b":"מחכמי סאלי וראבאט. נכד(-אבי אמו) ר אליעזר די אבילה, ואחיו של ר שמואל בעל \"עוז והדר\"."},{"i":391,"n":"אבילה די, משה משלוניקי","b":"מחכמי שלוניקי-שץ, תלמיד ר שלמה ן מאיור."},{"i":392,"n":"אבילה די, שלמה ממרוקו","f":"משה","b":"מחכמי רבאט. חתן ר אליעזר די אבילא בעל \"מגן גיבורים\", ועסק בהדפסת חיבורי חותנו. המלך אליאזיד מארבאט שלל את רכושו יחד עם יהודים אחרים."},{"i":393,"n":"אבילה די, שמואל ממרוקו - א","f":"משה","k":"בעל כתר תורה","bt":"תמז","bp":"מכנאס","dp":"מרוקו","b":"רב דרשן לא רשמי על מקום אביו-תע. חתן ר משה ן עטר מסאלי (וגיסו של בעל \"אור החיים\"), ולמד אצל אבי חותנו ר חיים ן עטר ממכנאס, ותלמיד ר יוסף בן בהתית. היה במחלוקת עם קהילת מכנאס שדרשו ממנו מס גבוה, ועבר לסאלי ולרבאט, וכשהמחלוקת המשיכה הגיעו לדין בפני רבני פאס, וחיבר \"כתר תורה\" להוכיח שתלמידי חכמים פטורים ממסים גם עם הם עשירים. חיבר גם \"אזן שמואל\", \"מעיל שמואל\", ועוד. בנו ר אליעזר."},{"i":394,"n":"אבילה די, שמואל ממרוקו - ב","f":"שלמה","k":"בעל עוז והדר","b":"נכד(-אבי אמו) ר אליעזר די אבילה. ונינו של ר שמואל די אבילא הראשון. רב בסאלי - בשנות התקמ. חתם עם ר יוסף אלמליח, ור משה דאבילא."},{"i":395,"n":"אבין מברצלונה","f":"אברהם","b":"דיין אצל הרשב\"א בברצלונה וחתם על תקנות ותשובות."},{"i":396,"n":"אבין מספרד","f":"שררה","b":"פייטן ומשורר במיורקה-ספרד, בימי ר שמואל הנגיד. נזכר אצל ר סעדיה ן דנאן ב\"חמדה גנוזה\" - בכת\"י. נזכר אצל ר משה ן עזרא שמספידו בדיואן."},{"i":397,"n":"אבין, אהרן מחברון","b":"מחכמי חברון, אירח את ש\"ץ בביתו."},{"i":398,"n":"אבין, בנדיקט הרופא מארלס","b":"רופא מחכמי פרובנס, בקי במדעים, מקורב למלכות."},{"i":399,"n":"אבין, נחמן צבי מארה\"ב","bt":"תרמד","dt":"תשג - כב אייר","b":"רב פעלים,רב בפנסילבניה-תרס\"ט,ברוקלין-תר\"פ"},{"i":400,"n":"אבינון, אברהם מסרייבו","dt":"תרסג - כו שבט","dp":"סרייבו","b":"תלמיד מהר\"ם פיררה מטראבניק וגדל בביתו. רב בטראבניק על מקום רבו, שאראי בושנא(=סרייבו). ביקר בירושלים וחזר לסרייבו."},{"i":401,"n":"אבינרי יצחק","bt":"1900","dt":"ה'תשלז 1977","bk":[["היכל רש\"י",""]]},{"i":402,"n":"אביסדיד, סלימן מתוגורט-אלגיר","k":"סלימן אלחאמי","bt":"שי","bp":"אלחאמא-תונס","dt":"שפ - בערך","b":"רב בתוגורט(=תוקורט)-סהרה של אלגיר. שאלה ממנו לרשב\"ץ ונזכר ב\"חוט המשולש\" ולעתים מכונה ר סלימן אלחאמי (ע\"ש מוצאו)."},{"i":403,"n":"אביסרור, שלום ממרוקו","k":"בעל נתיבות שלום","b":"רב במרוקו. חיבר \"נתיבות שלום\" קזבלנקה תשו."},{"i":404,"n":"אביעזר יהודה מטיקטין וירושלים","f":"יצחק אייזיק","k":"בעל משמרת הברית","bp":"טיקטין","dp":"ירושלים","b":"הדפיס בעלום שם ספר שערי צדק לזרע יצחק; עלה לירושלים תר; ספרים נוספים: משמרת הברית, ברכה משולשת, תוספת ברכה, בירור הברכות, ועוד"},{"i":405,"n":"אביעזרי זליג מקורב","b":"אב\"ד קורב-ליד לובלין-שסא. חיבר מעשיות ומוסר מהזהר בלשון אשכנז, הכתבים אבדו בגזרות תח ותט, ונכדו ר צבי הירש חאטש הו\"ל בשם \"נחלת צבי\" פפד\"מ תעא. בנו - ר יוסי מוינה."},{"i":406,"n":"אביצרור, יעקב ממרוקו","b":"מחכמי מרוקו-שנות ה-תק'. אחיו של ר יצחק."},{"i":407,"n":"אביצרור, יצחק ממרוקו","b":"מחכמי מרוקו-שנות ה-תק'."},{"i":408,"n":"אביקציץ, אברהם ממראקש","f":"מסעוד","b":"מחכמי מראקש-שנות ה-תק'."},{"i":409,"n":"אביקציץ, דוד","dt":"תרכו","dp":"מראקש","b":"חכם שלם במראקש"},{"i":410,"n":"אביקציץ, יהודה ממוגאדור וטבריה","bt":"תקעג","bp":"מוגאדור","dt":"תרל - יב חשון","dp":"מכנאס","b":"מו\"ץ במוגאדור, חתם על פס\"ד-תרט עם ר אברהם ן עטר, עלה לטבריה-תרכז, בשליחות במרוקו-תרכח ונפטר בעת שליחותו."},{"i":411,"n":"אביקציץ, יוסף מראבאט-מרוקו","b":"מחכמי ראבאט, חתם על פס\"ד-תץ."},{"i":412,"n":"אביקציץ, יחיא מסאלי וראבאט","b":"מו\"ץ בסאלי-מרוקו, ראבאט, יחד עם ר מרדכי הכהן ור יעקב ביבאס. חתם על פס\"ד-תעא ונזכר ב\"משפט וצבי\"."},{"i":413,"n":"אביקציץ, מימון מרבאט-מרוקו","b":"מחכמי רבאט, חתם על פס\"ד-תץ."},{"i":414,"n":"אביקציץ, מכלוף ממרוקו","f":"מסעוד","b":"מחכמי מרוקו-שנות ה-ת'."},{"i":415,"n":"אביקציץ, מסעוד מאזאוויא-מרוקו","f":"מכלוף","b":"רב באזאוואיה-מרוקו, שאלה ממנו-תקכז למהרי\"ט וחתם על השאלה עם חבריו - ר מימון בוסידאן, ור יהודה אדהאן. בנו - ר אברהם."},{"i":416,"n":"אביקציץ, מסעוד ממרוקו","b":"מחכמי מרוקו-שנות ה-ת'. נזכר אצל היעב\"ץ. אביו של ר מכלוף."},{"i":417,"n":"אביקציץ, שמעון ממוגאדור-מרוקו","k":"בעל שש אנוכי","bp":"מוגדור-מרוקו","b":"ראש ישיבת \"כתר תורה\" בקזבלנקה, דיין במוגדור. חיבר גם \"אך טוב לישראל\" לונדון תרסו, \"פלגי מים\" לונדון תרסו."},{"i":418,"n":"אביר, אברהם הכהן","b":"בשנת תקץ חתום אל אגרת שליחות בצפת של השדר ר ראובן, מראשי העדה החסידית שם"},{"i":419,"n":"אבירג'יל, אליהו","b":"מחכמי מכנאס-תקל\"ט"},{"i":420,"n":"אבירג'יל, סמחון ממכנאס","b":"מחכמי מכנאס-שנות ה-תק', בזמן ר שמעיה בטאג'."},{"i":421,"n":"אבירג'יל, ראובן מפאס ן קיקי","b":"מחכמי פאס-שנות ה-ש'."},{"i":422,"n":"אבירג'יל, רפאל ממרוקו","dt":"תשמח - יז כסלו","dp":"נתיבות","b":"מחכמי מרוקו, עלה לארץ והתישב בנתיבות."},{"i":423,"n":"אבירו, חיים","b":"סופר באיזמיר"},{"i":424,"n":"אבירלין, יהודה משלוניקי","b":"ראש קהלת האשכנזים בשלוניקי-שך בערך, עלה לצפת ור דוד הלוי אשכנזי על מקומו אחריו."},{"i":425,"n":"אבירמאט, משה ממרוקו","k":"בעל ויאמר משה","bt":"תרלח","bp":"מרוקו","dt":"תשטו","b":"רב במרוקו."},{"i":426,"n":"אבישי","b":"פייטן וכמה מפיוטיו במחזורים - כת\"י."},{"i":427,"n":"אבישי","b":"חכם משנת ד'תתק-תתקן. מראשוני מפרשי ר אברהם ן עזרא (כ-3 שנים אחר פטירתו) - כנזכר בהקדמת ר יהודה משקוני לספרו."},{"i":428,"n":"אבישר, דוד מחברון","f":"מאיר מחברון","bt":"תרמח","bp":"חברון","b":"פעיל ציבור, פרסם מאמרים בעתוני התקופה, בשליחות ביון ומצרים,"},{"i":429,"n":"אביתור ן, יוסף שטנאס מקורדובה","f":"יצחק","bt":"ד'תש","dt":"ד'תשפ","b":"תלמיד ר משה השבוי, פירש את הש\"ס בערבית למלך אלחכים. ראשון פייטני ספרד, מחכמי קורדובה, היה במחלוקת עם ר חנוך בן משה השבוי שהחרימו עד שנאלץ לצאת לגלות, עבר לבבל ורצה להגיע אל ר שמואל הכהן בן יאשיה אך ר שמואל חשש לחרם וסירב לפגשו, מצרים, א\"י, סוריה. חיבר מעמד והוא סדר העבודה ליום הכפורים."},{"i":430,"n":"אביתר הכהן","f":"אליהו גאון ירושלים","k":"גאון ארץ ישראל","dt":"תתסט [1071]","dp":"סוריה","b":"נכד ר שלמה, ומצאצאי רב יוסף הכהן גאון. היה אחרון גאוני ארץ ישראל וראש ישיבת \"גאון יעקב\" על מקום אביו, ואחיו ר שלמה היה אב\"ד אצלו. חתום עם אביו בתשובה לר משולם בן משה ממגנצא את אריות הקודש בירושלים-ד'תתלא. נזכר בנוסח הקדיש (שנמצא בגניזה) שאמרו \"בחיי רבינו אביתר הכהן וכו'\". נאלץ לברוח בזמן הכיבוש הצלבני ועבר עם הישיבה לצור, נאלץ לברוח מצור-ד'תתנו ואז ברח לטריפולי ויסד ישיבה, אחיו ר שלמה יסד ישיבה בחדרך-ליד דמשק ונקראה \"ישיבת א\"י\" או \"ישיבת ארץ צבי\". חיבר פיוט שנכנס למחזור \"שרפי צבא שחק אשר במעונים\", חיבר \"מגילת אביתר\" ובו מספר על המחלוקת עם רב דוד בן דניאל ממצרים שרצה לנשלו מכסאו - בתמיכת הנגיד רב מבורך. בניו: ר אליהו ממצרים ור צדוק. חתנו רב עמרם הכהן מירושלים. נזכר באגרת ר מנחם בן אליהו מטריפולי שנשלחה לקושטא כנגד מחשבי הקץ לשנת ד'תתנו. בספר חסידים נזכר כי פגש את רב האי בירושלים ודנו ביחד (והדבר לא מסתדר עם חשבון השנים - ואולי הכונה לזקנו של ר אביתר - ר שלמה גאון ירושלים שהיה בזמן רב האי)."},{"i":431,"n":"אביתר הכהן","f":"שמואל","b":"מחכמי בבל-ן', חתם על חרם ר דוד בן דניאל ראש הגולה כנגד ר שלמה הקטן."},{"i":432,"n":"אביתר הכהן מבבל","f":"יפת","b":"מחכמי בבל-ן', חתם על חרם ר דוד בן דניאל ראש הגולה כנגד ר שלמה הקטן."},{"i":433,"n":"אביתר ישעיה מדגסטן וירושלים","bt":"תקצט","bp":"דאגסטאן","dt":"תרפז - יח אד\"ב","dp":"ירושלים","b":"מחכמי ירושלים מעולי דאגסטן ורב העדה בירושלים."},{"i":434,"n":"אביתר מעכו","f":"יוסף","b":"מרבני עכו, חתום בשאלת ר יוסף בן גרשום מר אברהם בן הרמבם-ד'תתקצח."},{"i":435,"n":"אביתר ן, דוד","b":"דיין באמשטרדם"},{"i":436,"n":"אבל, אפרים מקלויזנבורג","b":"רב בקלויזנבורג-תקעב."},{"i":437,"n":"אבל, יהושע השל","b":"רב בדוביסר-תר\"ע"},{"i":438,"n":"אבל, שלמה זלמן מניישטט-טאווריג","k":"בעל בית שלמה","bt":"תריז","bp":"ניישטט-טאווריג","dt":"תרמו - ג ניסן","dp":"טלז","b":"נינו של ר אברהם אחי הגר\"א. בגיל 12 חיבר פירוש לספר איוב, ובגיל 14 חיבר \"חזיון חיי דוד\". ביוזמתו הוזמן ר אליעזר גורדון לטלז וייסד בה את ישיבת טלז, ור שלמה כיהן בה כראש ישיבה. תולדותיו נכתבו ע\"י אביו בהקדמה לספרו \"בית שלמה\"."},{"i":439,"n":"אבלי","b":"רב בברטשהן(בסרביה)"},{"i":440,"n":"אבלמן, דובער","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":441,"n":"אבלמן, יהונתן מווילון","f":"אברהם אבא יצחק","k":"בעל זכרון יהונתן","bt":"תריד","bp":"[ווילון-ליטא]","dt":"תרסג-ז - טז אדר","dp":"ביאליסטוק","b":"תלמיד ישיבות איישישוק, ווילנא. חתן ר ישראל סלנטר (ובאמת נשא קרובת משפחתו). רב בחורושץ(=חורנץ)-ליד ביאליסטוק-תרלה, אב\"ד ביאליסטוק-תרמד. חיבר גם \"תורת יהונתן\", והערות וחדושים על הנודע ביהודה - יחד עם הרב רבינזון מרדושקביץ. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":442,"n":"אבלס, אביגדור מסט מיקלוש","dp":"בודפשט","b":"חתן ר אברהם שיק. רב בסט. מיקלוש-תריג עד תריט, ועבר לבודפשט."},{"i":443,"n":"אבלס, אברהם יעקב מבעצקא","f":"יוסף משאלא","b":"רב בבעצקא. גיסו של ר חנניה יו\"ט ליפא דייטש מקיראל - ניו יורק בעל \"טהרת יו\"ט\"."},{"i":444,"n":"אבלס, אברהם מטשקובה","f":"מאיר","b":"מחכמי טשקובה. ממשתתפי \"קהילת אשר\"."},{"i":445,"n":"אבלס, אברהם צבי משאר-בוגארד","f":"מרדכי","bt":"תקעט","bp":"גירבא-פינצעהעל","dt":"תרלא - כד אדר","b":"תלמיד החת\"ס. חתן ר יצחק משה פרלס מבאניהאד ועבר לשם-תרג, רב בשרבוגרד-תרט. תשובות ממנו ב\"נחלת בנימין\". מתורתו בספר בנו - \"לב יהודה\". חתנו ר נתן נטע הלוי קעלל - על מקומו אחריו."},{"i":446,"n":"אבלס, בנימין זאב וולף","b":"רב בסעטשין,טאפאנא,טאב"},{"i":447,"n":"אבלס, יונה מבודפשט","dt":"תרסב - כט אלול","dp":"בודפשט","b":"תלמיד הכת\"ס. רב בבודפשט - ממיסדי הקהלה החרדית שם."},{"i":448,"n":"אבלס, יוסף מאטש","b":"רב באטש"},{"i":449,"n":"אבלס, יוסף משאלא","f":"משה יהודה מוויצען","bt":"תרלו","bp":"וויצען","dt":"תשד - יז תמוז","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר בנימין בונם אבלס מוויצען. רב בשאלא(=נאדי-שאלוי)-תרסה. נספה בשואה. חתנו - ר חנניה יו\"ט ליפא דייטש בעל \"טהרת יו\"ט\"."},{"i":450,"n":"אבלס, ישראל מבודפשט","f":"מאיר מקיצע","b":"חתנו - ר עזריאל מייזנר מבודפשט."},{"i":451,"n":"אבלס, מאיר מקיצע","bt":"תקסו או תקנז","bp":"ניקלשבורג","dt":"תרמז - ג אלול","dp":"קיצע","b":"תלמיד החת\"ס. חתן ר מנדל כץ מקיצע ועבר לשם. רב בקיצע-תקצז. תשובה אליו ב\"חתם סופר\". (החת\"ס סיפר לו כי כשנבחר לרב במטרסדורף וגם בעיר חדש - שאל את רבו ר נתן אדלר במי לבחור - וכשאמר לו מטרסדורף - מיד קיבל דעתו - וכך צריך לציית לרב)."},{"i":452,"n":"אבלס, משה מאויבן","k":"בעל יד משה","bp":"רכניץ","dt":"תקצא - כה-ח אב","dp":"בודפשט","b":"דיין באויבן-תקעד, וראב\"ד ומגיד שם. חיבר \"יד משה\" על הש\"ס ושו\"ע - בכת\"י (אולי כתב בעצמו ואולי בידי סופר). חתם-תקפא עם ר משה מינץ ור יהודה מאיר אסטריך."},{"i":453,"n":"אבלס, צבי הירש מאטש(=אץ')","b":"רב באטש-תקעב כ-20 שנה. נזכר בשו\"ת החת\"ס."},{"i":454,"n":"אבלס, שלמה","bt":"תקצא","dt":"תרפו","b":"רב בקרלסבד"},{"i":455,"n":"אבלסון, אברהם אבא משאוולי","b":"רב \"מטעם\" בשאוולי."},{"i":456,"n":"אבלסון, אברהם יואל מאודסה","k":"בעל תקנת עגונות","bt":"תרא","bp":"מאריאמפול","dt":"תרסג","dp":"אודיסה","b":"תלמיד ישיבת רוזנטל במאריאמפול, רב בסוקולוב(=סאקאלקא)-פלך שדליץ, סטוויסק, טורוב-פלך פינסק, אודסה-תרמג-נג. עסקן ציוני. הו\"ל ירחון \"כנסת חכמי ישראל\" (והוא על מקומו של \"יגדיל תורה\") - אודסה-פיעטרקוב-ברדיטשוב תרנג. חיבר \"תקנת עגונות - בענין חליצת מומר\". פרסם מאמרים ב\"מכילתא דרבנן\" - אודסה תרמו, \"הצפירה\", \"המליץ\", ועוד."},{"i":457,"n":"אבלסון, דב בער","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":458,"n":"אבלסון, יהודה","k":"בעל זכרון יהודה","b":"חוקר הלכה מניישטאט-שאקי שבליטא-תר. חיבר מבוא למשנה בשם \"זכרון יהודה\"."},{"i":459,"n":"אבלסון, יהודה שרגא","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":460,"n":"אבלסון, יהושע מאנגליה","f":"אברהם","bt":"תרלג","bp":"מארטיר מיידויל-ווילס","b":"תלמיד ביהמ\"ד לרבנים בלונדון. רב בקרדיף, בריסטול, מורה בבימ\"ד לרבנים \"אריא קאלירזש\" (נוסד ע\"י הגביר ה' לואיס אריא)."},{"i":461,"n":"אבלסון, יהושע מויסצק","dt":"תשג","b":"רב בוויסצק"},{"i":462,"n":"אבלסון, יעקב מוייצען","b":"תלמיד ר מיכאל הופמן מסערדאוהל-תרלה ורשם בכתב ידו מחדושי רבו. (אולי הוא שהיה רב בלצקובה עד השואה)."},{"i":463,"n":"אבלסון, יעקב מלצקובה","dt":"תש..","b":"רבה האחרון של לצקובה. נספה בשואה."},{"i":464,"n":"אבלסון, יצחק מאודסה","f":"אברהם יואל","bt":"תרלג","bp":"סוקולוב","b":"רב באודסה-תרסג."},{"i":465,"n":"אבן אבו אלרביע, אברהם","k":"ר' אברהם החסיד","b":"מחכמי מצרים, רופא"},{"i":466,"n":"אבן אריה מקורדובה","b":"חסיד מחכמי ספרד-ד'תתן. נזכר באגרת תימן לרמב\"ם - שהיה מנבא עתידות והיה שחשבוהו למשיח עד שנענש ונודה ע\"י חכמי קורדובה ובהם זקנו של הרמב\"ם על כך שהניח לאנשים להאמין שהוא המשיח."},{"i":467,"n":"אבן ג’נאח יונה","bt":"995","dt":"ד'תתי 1050","bk":[["הרקמה",""],["ספר השרשים",""],["פירוש לכתבי הקדש",""]]},{"i":468,"n":"אבן חלווה","bt":"טו","bk":[["שלחן של ארבע",""]]},{"i":469,"n":"אבן עזרא משה בן יעקב","bt":"1055","dt":"ד'תתק 1140","bk":[["הענק הוא התרשיש",""],["שירי החל",""],["שירת ישראל",""]]},{"i":470,"n":"אבן עקנין יוסף בן יהודה","bt":"1150","dt":"ד'תתקפ 1220","bk":[["מבוא התלמוד",""],["ספר מוסר",""]]},{"i":471,"n":"אבן צדיק יוסף בן יעקב","bt":"1075","dt":"ד'תתקט 1149","bk":[["העולם הקטן",""],["עולם הקטן",""]]},{"i":472,"n":"אבן שמואל (קויפמן), יהודה","b":"סופר וחוקר חכמת ישראל. הו\"ל הכוזרי בתרגום חדש, ועוד. חיבר ספר על ר יו\"ט ליפמן מילהויזן בעל ספר הנצחון."},{"i":473,"n":"אבן שפרוט שם טוב","bt":"1375","dt":"ה'קמ 1380","bk":[["פרדס רמונים",""]]},{"i":474,"n":"אבן, יצחק מבוריסלב","b":"עבר לבוריסלב ויסד את ביה\"ס העברי הראשון בגליציה. פרסם בכתבי עת שונים, עבר ללמברג ועסק בחינוך. עבר לארה\"ב-תרסט ועבד ב\"אוצר ישראל\" וכן פרסם ספורים ומאמרים באידיש. תורגם לעברית \"הנער בנימין מטריעסט - סיפור הסטורי\" למברג תרנו, ועוד."},{"i":475,"n":"אבן, צבי מפידבוש","b":"רב בפידבוש-תרנב"},{"i":476,"n":"אבן-עזרא אברהם בן חיים ידידיה","bt":"1690","dt":"ה'תקכ 1760","bk":[["בית האסופים",""],["בתי כנסיות",""]]},{"i":477,"n":"אבנד, מנחם מנדל שלמה מנמירוב","f":"צבי","k":"בעל עבודת משא","bt":"תרח","bp":"נמירוב","dt":"תרסא","b":"רבה של נמירוב-תרלא, חתנו היה ר משה טויב, נכדו האדמור מקאליב ר מנחם שלמה טויב. חיבר \"עבודת משא\" ברוקלין תשל. נשיא מחז\"ה בקהילתו. תלמידו - ר משה הרציג מטשיטש. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח."},{"i":478,"n":"אבנד, נפתלי אריה ליבוש מנמירוב","bt":"תקס","dt":"תרל","b":"רבה של נמירוב-תרכב, מתורתו בספר נכדו \"עבודת משא\"."},{"i":479,"n":"אבנדנה, יעקב מאמשטרדם","f":"יוסף","k":"בעל לקט שכחה","dt":"תנו","dp":"לונדון","b":"רב באמשטרדם, לונדון-תם. תרגם ספר הכוזרי לספרדית - אמשטרדם תכג. הו\"ל \"מכלול יופי\" לר\"ש בן מלך עם הוספות בשם \"לקט שכחה\" - תך, חיבר ויכוח מחקרי על בית שני - בכת\"י (די רוסי בספרו). אחיו של ר יצחק - מתרגם המשנה ללטינית. תרגם ספר הכוזרי לספרדית."},{"i":480,"n":"אבנהולץ, אליהו ממעליץ","b":"בע ממעליץ לכהן כחזן ומגיד ברדומישל. חתן ר שלום ברנד. מלחין וכן בניו ר נפתלי ואחיו השו\"ב וחזן ברדומישל."},{"i":481,"n":"אבנער, שרגא פיביש מלמברג","bp":"צ'רנוביץ","b":"חסיד בלז ומו\"ל קמחז\"ה. במחלוקת עם אדמורי קומרנא. בניו ר יוסף מרדכי חתן הגביר ר אברהם קנעכט מפשמישל, ור משה חתן ר ברל לעוו מטרנוב - שני הבנים המשיכו להדפיס בלמברג-תרפו."},{"i":482,"n":"אבנר המומר מבורגס","bt":"ה'ל","b":"המיר דתו בגיל 60 וחיבר ספרים ובהם \"מורה צדק\", \"מנחת קנאות\" כנגד דת ישראל - וחכמי ישראל השיבו לו בספרים כנגדו. וטען כי אין בחירה בעולם והכל בגזירה, (ב\"סדר הדורות\", ושה\"ק מובא שהיה תלמיד הרמב\"ן - וזה לא יתכן כי הרמב\"ן נפטר לפני שנולד)."},{"i":483,"n":"אבנר מואסלביץ","b":"חסיד החוזה מלובלין. עמד בקשרי שו\"ת עם ר עקיבא איגר, ועם ר יצחק אברהם מפינטשוב, ונזכר בספריהם."},{"i":484,"n":"אבנר מסטאשוב","b":"רב בסטאשוב. נזכר בשו\"ת ר עקיבא איגר."},{"i":485,"n":"אבנר מספרד","b":"מקובל מחכמי ספרד-קן ונזכר ב\"מאירת עינים\" לר יצחק מעכו שהביא דברים בשם ר שם טוב בעל \"מגדל עוז\"."},{"i":486,"n":"אבנר, פיביש מלמברג","k":"הו\"ל קול מחזיקי הדת","bt":"לבוב","bp":"תרטז","dt":"תרסא","b":"מחכמי לבוב. חיבר \"דברי ימי ישראל\" לבוב תרנט. הוציא לאור את \"קול מחזיקי הדת\". חתנו ר יהושע צבי וילף."},{"i":487,"n":"אבנרי (מוסטוביץ), ירחמיאל מירו","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו, \"תל תלפיות\" - ירושלים תשא."},{"i":488,"n":"אבסבאן, שלמה מארם צובא","b":"רב בארם צובא בזמן ר שמואל לניאדו. נספד ב\"מגן אברהם\". (יתכן והוא מוחלף עם ר שלמה מצפת)."},{"i":489,"n":"אבסבאן, שלמה מצפת","bt":"רפ - בערך","dt":"שנז או שנב","dp":"צפת או דמשק","b":"מגורי האר\"י בצפת, ותלמיד ר יוסף קארו ואולי גם נסמך על ידו (וי\"א שהיה אחד הרבנים שסמכו בשנת רצח את ר יעקב בירב וחדשו את הסמיכה). רב בצפת-שכ וחתם עם ר יוסף קארו ור משה מטרני. נמנה על החכמים שדנו בתביעת בנו של ר יעקב בירב אודות צוואת אביו, חתם על תשובה נגד ר יצחק די מולינא, וחתם על החרם נגד יריבו של דון יוסף נשיא. חברו של ר אלעזר אזכרי. מתלמידיו ר יעקב אבולעפיא המוסמך. יתכן והוא ר משה אבסבאן הנזכר אצל ר משה אלשיך ושיצא עמו לשליחות בקושטא ונפטר שם ומזכירו ב\"חזות קשה\". תשובות ממנו בספרי חכמי דורו. נספד על ידי ר אברהם אבולעפיה ור אברהם לניאדו בספרו \"מגן אברהם\". חתם-שלא על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":490,"n":"אבעלוב, יעקב משה מזאראן","dt":"תש","b":"רב בזאראן"},{"i":491,"n":"אבעסט, אליהו ממוסקבה","b":"בנו חורגו וחתנו של ר יצחק בלזר. שו\"ב במוסקבה. חיבר בכת\"י את תולדות חותנו (היה אמור להיות בהקדמה ל\"פרי יצחק\" אך לא נדפס)."},{"i":492,"n":"אבראהאם, יהודה ליב מאדלני","k":"בעל מדרש ריב\"ש טוב","b":"רב באדאלני-מחוז בורשוד. חיבר \"מדרש ריב\"ש\" - ליקוטים מתורת הבעש\"ט."},{"i":493,"n":"אבראהאם, צבי יעקב מטורדא ונ\"י","f":"אברהם טירע","k":"בעל בית אולפנא","bt":"תרנז","dt":"תשלד - כג אלול","dp":"ירושלים","b":"חתן ר בן ציון ווזל מטורדא, כיהן במשרד הרבנות שם תחת חותנו. ניצל מהשואה ועסק בהצלה. עורך הירחון \"האמת\" בהונגרית, עבר לניו יורק, עלה לארץ והתגורר בבני ברק."},{"i":494,"n":"אברבאליה, משה מגירונדי-ספרד","b":"רב בגירונדי-קלג. ממשתתפי ועדת הרבנים בברצלונה שזימן המלך פדרו הרביעי."},{"i":495,"n":"אברבוים, אפרים יעקב מוילון","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":496,"n":"אברבוך, משלם זושא יצחק מטלומש","f":"יחיאל מיכל מקורימא","bt":"תקעט","dt":"תרמב - ב סיון","b":"מצאצאי ר זושא מאניפולי. חתן ר יעקב ישראל מטשרקאס (טשרנוביל), ובזיוו\"ש חתן ר חיים מקוסוב. רב בטלומאטש. הו\"ל \"לקוטי תורה\" לר מרדכי מטשרנוביל."},{"i":497,"n":"אברבוך, שמואל יחזקאל מפודגורזע","b":"מחכמי פודגורזע - תשובה אליו ב\"מנחת יחיאל\"."},{"i":498,"n":"אברביה, יהושע מתורכיה וארץ ישר","bt":"תרלח","bp":"דרדנל-תורכיה","dt":"תרצד - כח סיון","dp":"תל אביב","b":"מנהל ביה\"ס בגליפולי, עלה לארץ-תרסד, עסקן ציבור."},{"i":499,"n":"אברבנל, אברהם משלוניקי","f":"שמעון","b":"גביר בשלוניקי. סייע בהדפסת \"מטה שמעון\" ח\"ג לר מרדכי שמעון-תקעט."},{"i":500,"n":"אברבנל, אשר משלוניקי - א","dt":"תנח","dp":"שלוניקי","b":"מחכמי שלוניקי, תלמיד בישיבת נתן העזתי בשלוניקי-תלז - אחרי המרתו של ש\"ץ."},{"i":501,"n":"אברבנל, אשר משלוניקי - ב","f":"משה","dt":"תקכה","dp":"שלוניקי","b":"גביר ומורשה קהלת שלוניקי-תקד, יחד עם חבריו: ר משה יצחק קואינקה, ר בנימין משה עשאל, ר יצחק קאזיש, וא' טאזארטי."},{"i":502,"n":"אברבנל, דוד משלוניקי","dt":"תקטז - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"אדמת קדש\"-תקטז."},{"i":503,"n":"אברבנל, חייא משלוניקי","f":"יצחק","b":"מחכמי שלוניקי-שנות ה-ש', מצאצאי דון יצחק אברבנאל."},{"i":504,"n":"אברבנל, חיים אשר משלוניקי","b":"מראשי קהלת שלוניקי-תקד, וחתם אז מטעם הקהלה על הסכם בין יהודי איטליה היושבים בשלוניקי לבין בני קהלת שלוניקי בענין הסדרת המס."},{"i":505,"n":"אברבנל, יהודה ממראקש","f":"לוי בן מאיר","dt":"תקצט","dp":"מראקש","b":"מו\"ץ במראקש בדורות הקדמונים, נהרג עק\"ה, עם בתו וחתנו. נזכר ב\"מבשר טוב\"."},{"i":506,"n":"אברבנל, יהודה מספרד","f":"שמואל מסביליה","dt":"רל","b":"עשיר, נדיב, מנהיג בישראל, סוכן בית האוצר, גזבר של מלך קשטיליה."},{"i":507,"n":"אברבנל, יהודה מספרד ואיטליה","f":"יצחק","k":"בעל דייאלוגי די אמור","bt":"רך","bp":"ליסבון","dt":"רצה","b":"מכונה - ליאון דילמדיגו. לאחר גירוש ספרד עבר עם אביו לאיטליה והתישב בגנואה, נפולי. חיבר \"דייאלוגי די אמורי\" באיטלקית. שירים ממנו בספרי אביו. אביו כתב כי הוא מבחירי הפילוסופים בדור הזה."},{"i":508,"n":"אברבנל, יהודה משלוניקי","b":"מחכמי שלוניקי-שנות ה-ש'."},{"i":509,"n":"אברבנל, יונה מאמשטרדם","f":"יוסף הרופא","dt":"תכז - כא אב","dp":"אמשטרדם?","b":"אחיינו של ר מנשה בן ישראל מאמשטרדם. משורר ומתרגם באמשטרדם, תרגם את ספר תהלים לספרדית יחד עם ר אפרים בואינו - אמשטרדם תי, הו\"ל תפלות וקינות לזכרו של ר אברהם נוניס שנהרג עק\"ה."},{"i":510,"n":"אברבנל, יוסף מספרד","k":"דון יוסף אברבנאל","b":"חכם,רופא,נשוא פנים,בגירוש ספרד עבר לאיטליה-רנ\"ב"},{"i":511,"n":"אברבנל, יוסף משלוניקי","dt":"תקך","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":512,"n":"אברבנל, יוסף משלוניקי - א","b":"דיין בשלוניקי-שעה, ועסק גם במסחר."},{"i":513,"n":"אברבנל, יוסף משלוניקי - ב","dt":"תמה","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":514,"n":"אברבנל, יעקב משלוניקי","b":"חתן ר אברהם די בוטון ממונשטיר. גביר מחכמי שלוניקי-שץ, ואשתו שרה - גם היא נדיבה בשלוניקי."},{"i":515,"n":"אברבנל, יצחק מספרד","f":"יהודה","k":"דון יצחק אברבנאל","bt":"קצז","bp":"ליסבון","dt":"רסט - אב","dp":"ונציה","b":"שר וגדול ליהודים, למד תורה אצל ר' יוסף חיון, ובישיבה של ר' יצחק אבוהב, היה שר האוצר של מלך פורטוגל, כשמת המלך בנו הרג את כל האצילים, ורבינו הצליח לברוח לספרד, שם היה שר אוצר שמונה שנים עד לגירוש אותו ניסה למנוע, ברח לנפולי, כאשר נכבשה ע\"י צרפת לקח אותו מלך איטליה לסיציליה, עבר לקורפו-רנ\"ה, ופישר בין ראשי ונציה למלך פורטוגל, נקבר בפאדובה, חיבר פירוש אברבנאל על התנ\"ך, ובו \"מרכבת המשנה\" על ספר דברים ויסודות האמונה והיראה"},{"i":516,"n":"אברבנל, יצחק משלוניקי","dt":"שג","b":"רופא בשלוניקי"},{"i":517,"n":"אברבנל, יצחק מתורכיה","f":"שמואל","b":"מצאצאי דון יצחק אברבנל. מחכמי תורכיה בזמן מהרם פאודבה. מובא בשות הרשד\"ם."},{"i":518,"n":"אברבנל, לוי ממראקש","f":"מאיר","dt":"תקף - בערך","b":"מחכמי מראקש. נהרג עק\"ה. בנו - ר יהודה נהרג גם הוא עק\"ה."},{"i":519,"n":"אברבנל, משה הרופא המומר","f":"רפאל","k":"האיאט זאדי","dt":"תנא - אחרי","dp":"קושטא","b":"מומר, רופא בחצר השולטן ובעל השפעה רבה, שיכנע את ש\"ץ להתאסלם. נאסר ע\"י השולטן סולימן השני-תנא ומת בכלא."},{"i":520,"n":"אברבנל, משה משלוניקי - הזקן","dt":"תיז - כג שבט","dp":"שלוניקי","b":"מחכמי שלוניקי. זקנו של דון משה - נשיא העדה בשלוניקי."},{"i":521,"n":"אברבנל, משה משלוניקי - הנכד","dt":"תפו","dp":"שלוניקי","b":"מראשי קהלת שלוניקי-תעה, וראש מורשי הקהלה (שאחראי על גביית המסים מהקהלה עבור השלטונות)."},{"i":522,"n":"אברבנל, שיניאור משלוניקי","dt":"תקיא","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":523,"n":"אברבנל, שלמה משלוניקי","dt":"תצח","dp":"שלוניקי","b":"חתן ר יעקב די בוטון. גביר מחכמי שלוניקי. תמך בהדפסת כמה ספרים. נזכר ב'עדות ביעקב'-שלוניקי תף."},{"i":524,"n":"אברבנל, שמואל מספרד ואיטליה","f":"יצחק","k":"דון שמואל אברבנאל","dt":"שיא","b":"מגדולי חכמי ספרד,בגירוש עבר לאיטליה-רנב, שר גדול וחכם. אשתו - בונאוידה(=בנוינידה)-מזל טוב - מקורבת למלכות גם בספרד וגם בנפולי."},{"i":525,"n":"אברבנל, שמואל משלוניקי","b":"נכדו של דון יצחק אברבנל, מחכמי שלוניקי בזמן הרדב\"ז, ונזכר בספרי חכמי דורו."},{"i":526,"n":"אברבנל, שניאור משלוניקי","dt":"שצ","b":"מגדולי שלוניקי, דרשן, מעיין בישיבת ר' אשר כהן ן' ארדוט."},{"i":527,"n":"אברבנל, שניאור משלוניקי","dp":"שלוניקי","b":"תלמיד ישיבת ר אשר הכהן ן ארדיט. מחכמי שלוניקי-ת'. נפטר צעיר. חבריו: ר יהודה בנבנשתי, ר יעקב די בוטון, ר ברוך אנגל, ר שמואל דניאל, ר מרדכי פינצי, ועוד."},{"i":528,"n":"אברדם, אפרים פישל","f":"חיים הלוי מפשמישל","bt":"תקפא","dt":"תרנה","b":"גביר מחכמי סמבור. חתן ר יצחק תאומים מקריסנפולי, גיסיו ר מיכל לאם ור יונה אשכנזי."},{"i":529,"n":"אברדם, זכריה מנדל הלוי מטרנוב","bt":"תר","dt":"תרס","b":"נכד הבאר היטב והויכר ר ליב. חתן ר וולף לייזר מטורנא ועבר לשם. גביר מראשי הקהל בטרנוב."},{"i":530,"n":"אברדם, חיים מסמבור","b":"מחכמי עיר ישן (סמבור) תשובה אליו ב\"כוכב מיעקב\"."},{"i":531,"n":"אברדם, יוסף","b":"תשובה אליו \"נחלת יהושע\"-תרמו."},{"i":532,"n":"אברדם, צבי מבוצאץ","b":"מחכמי בוצאץ, ממשתתפי \"ועד חכמים\"."},{"i":533,"n":"אברדם, שמעון מטורנא","b":"מחכמי טורנא, ממשתתפי \"ועד חכמים\"."},{"i":534,"n":"אברהם","f":"שמואל","b":"אחיהם של ר יוסף טוב עלם, ור בנימין. הושלך לכבשן האש וניצל."},{"i":535,"n":"אברהם","f":"משה","b":"חתן ר שמואל יהודה וייל."},{"i":536,"n":"אברהם","f":"ליפמן"},{"i":537,"n":"אברהם","b":"מגדולי הראשונים-ד' תתק\"מ. רבו של הרוקח"},{"i":538,"n":"אברהם","f":"יהושע","b":"רב גדול בתורה-ת\"ז"},{"i":539,"n":"אברהם","f":"אברהם","b":"אביו של ר מרדכי-רבה של מדינת רוסיה."},{"i":540,"n":"אברהם","f":"יוסף","bp":"פרווינצא","b":"מתלמידי הראבד בעל ההשגות, ומוזכר בספרו \"ספרן של ראשונים\" על כך שעלה לארץ ישראל."},{"i":541,"n":"אברהם","f":"חיתית","k":"בעל פירוש לתהלים","b":"חיבר פירוש על תהלים - כת\"י."},{"i":542,"n":"אברהם","f":"שלמה בן עובדיה","b":"מצאצאי הרמב\"ם. דיין על מקום זקנו ר יעקב בן גו. סדר יחוסו לרמב\"ם לא ברור. נזכר בספר אילימה."},{"i":543,"n":"אברהם","f":"אליעזר","k":"בעל פירוש לפירש\"י","b":"חיבר פירוש לפירוש רש\"י לתורה ונדפס בספרו של ר אהרן אלדבי."},{"i":544,"n":"אברהם","f":"שמריה","b":"מחכמי דורו - רן-ש. חיבר הגהות ומראה מקומות לטור - קושטא ש'. נזכר ב\"בית יוסף\"."},{"i":545,"n":"אברהם","f":"שבתי","b":"רב במנית זפתא-ד'תתק, ובנו ר שבתי על מקומו אחריו."},{"i":546,"n":"אברהם","f":"חלפון","b":"פייטן ומשורר-רן, פיוטים ממנו במחזורי תימנים."},{"i":547,"n":"אברהם","f":"דוד","b":"חתם על חרם ראש הגולה מדמשק-ן'."},{"i":548,"n":"אברהם","f":"משה בן דוד הי\"ד","b":"חיבר הגהות על התשב\"ץ - בכת\"י-קן."},{"i":549,"n":"אברהם","f":"ישעיה","b":"נזכר ב\"מדרש תלפיות\" שמועה ממנו-רן."},{"i":550,"n":"אברהם","f":"דוד","b":"בעל השגות על רש\"י, אולי הוא מחברו של פירוש לספר יצירה."},{"i":551,"n":"אברהם (גיסו)","b":"מתורתו בספר \"אביר יעקב\". האם גיסו שם משפחה או גיסו של ר אברהם לניאדו)."},{"i":552,"n":"אברהם (דב) מחרסון וירושלים","dt":"תרכה - ב שבט","dp":"ירושלים","b":"רב בחרסון, עלה לירושלים."},{"i":553,"n":"אברהם אבא","f":"חיים מזאלווע"},{"i":554,"n":"אברהם אבא אבלי ממאקוב","k":"בעל ברכת אברהם","dt":"תקלא","b":"מקובל. אב\"ד מאקוב, נתמנה לרב בפפד\"מ ולא הגיע לשם."},{"i":555,"n":"אברהם אבא חסיד מקרוז'","k":"אבא אריכא","bp":"קרוז'-פלך קובנה","dt":"תקלא","dp":"[קרוז']","b":"מחכמי קרוז'(=קראז)-תר בערך. הצניע עצמו עד שהגיע אליו שליח מהגר\"א למסור לו מכתב, ואז נתפרסם. צדיק מפורסם ואגדות רבות מהלכות עליו, התרועע עם ר עקיבא איגר. מתלמידיו ר רפאל הכהן מאלטונה. חתנו - ר אלחנן הכהן מוארנא-פלך קובנא, בנו ר צבי הירש, ונכדו ר אברהם אבלי רוזניש. נמסר על נסים שאירעו לאנשים שבאו להתפלל על קברו. גיסו - ר אריה ליב חסיד מטלז. נזכר ב\"זכרון אברהם\" לר אברהם אבלי רוזניש."},{"i":556,"n":"אברהם אבא מארי מנוברדוק","f":"יצחק מקרקא או יעקב מ","b":"תלמיד ר אברהם יהושע השל(=ר העשיל) מלובלין וקראקא. רב בנוברדוק-שנות ה-ת' ועוד קהלות בליטא ור ראובן בן משה על מקומו אחריו בנוברדוק. בניו - ר ישראל איסרל מבריסק ופינסק, ר אליהו מצורטקוב. חתנו - ר זאב וולף הכהן מלומזה ובריסק."},{"i":557,"n":"אברהם אבא מדוביסאר","b":"תלמיד הבעשט ושימש כש\"ץ בבית מדרשו."},{"i":558,"n":"אברהם אבא מוילנא","f":"בנימין בן יעקב","dt":"תרטו - טו אלול","b":"קרובו של ר אבלי מוילנא, ושל ר אהרן צמח'ס מוילנא, נכד-אבי אמו ר קויפמן מוילקומיר. דיין בוילנא, וחתנו ר יעקב בער בן זאב וולף פלאהם על מקומו אחריו."},{"i":559,"n":"אברהם אבא מורז'אן-ליטא","b":"רב בורז'אן, ור אברהם שניצר על מקומו אחריו."},{"i":560,"n":"אברהם אבא מחרסון וקיוב","f":"נפתלי מטולטשין","k":"בעל בית אברהם","b":"תלמיד ר אברהם יהושע השל מאפטא. חתן ר מרדכי הכהן מחרסון. אב\"ד בשקלוב, קיוב, חרסון-תקע על מקום חותנו."},{"i":561,"n":"אברהם אבא מטשנגר","b":"דומ\"צ בטשנגר-תק\"צ"},{"i":562,"n":"אברהם אבא מניישטאט","dt":"תקעז - ב חשון","b":"תלמיד ר מרדכי מנסכיז, והחוזה מלובלין. נחשב לרבו של היהודי הקדוש מפשיסחא, ולאחר מכן היה לחסידו. אדמור בניישטאט, ולאחר חצי שנה פרש מאדמורות ועבר אל ר שמחה בונם מפשיסחא. בנו ר קלמן. מתלמידיו ר חנוך הניך מאלכסנדר."},{"i":563,"n":"אברהם אבא מפוטיק","b":"רב בפוטיק, טלומטש. תשובה אליו ב\"בית שלמה\"-תרכה."},{"i":564,"n":"אברהם אבא מפולנאה","b":"ראב\"ד בפולנאה. בנו ר יעקב היה פרנס באוסטרהא. עבר לאוסטרהא אל בנו (נרשם בפנקס ח\"ק אוסטרהא ששלחו לו דבש - סמל לחשיבות)."},{"i":565,"n":"אברהם אבא מקריבטש-תלמיד הבעשט","b":"תלמיד הבעשט שאף התאכסן בביתו. רב בקריבוש=קריבטש-שדה לבן-תקי, פודולסק על מקום ר אברהם מפודולסק-תלמיד הבעשט."},{"i":566,"n":"אברהם אבא מרי מנוברדוק","f":"יעקב מוינה","b":"מצאצאי בעל \"תרומת הדשן\", ומהר\"ם פדובה ומהר\"י מינץ. תלמיד ר יהושע השל מלובלין וקראקא. חתן ר שלמה מזאמושט, ובזיוו\"ש חתן ר ישראל איסר מלובלין-נכד המהרש\"א. רב בכמה קהלות בליטא, נוברדוק(=נאווהרדוק)-תמ. בניו: ר ישראל איסר מבריסק ופינסק, ר אליהו מצורטיקוב, ר שמשון מזולקווא, ר שלמה מקוברין..חתנו - ר זאב וולף הכהן מלומזה ובריסק."},{"i":567,"n":"אברהם אבוצחאק משלוניקי","dt":"רפד - תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":568,"n":"אברהם אבוש ליברמן מחעלם","dt":"תרמח","b":"אב\"ד חעלם."},{"i":569,"n":"אברהם אבוש מבוצאץ","b":"מחכמי בוצאץ בזמן הדע\"ק. תשובה אליו ב\"בית אפרים\"-תקסב."},{"i":570,"n":"אברהם אבוש מסיקסא","b":"אב\"ד סיסקא. נזכר בשו\"ת החת\"ס."},{"i":571,"n":"אברהם אבוש מקריסנפולי","b":"מחכמי קריסנפולי. תשובה אליו ב\"ארץ צבי\"-תרנד."},{"i":572,"n":"אברהם אבוש מרדכי הלוי","f":"צבי הירש","k":"אמ\"ן הלוי","bt":"תקסט","bp":"צישינוב","dt":"תר","b":"מחכמי גליציה, היה מקורב ל אפרים זלמן מרגליות. חיבר \"עלה לדוגמא\" זאלקווא תרצה, \"שיר מחקרי חלד\" זולקווא תרצה (בעילום שם המחבר)."},{"i":573,"n":"אברהם אבוש מרדכי מבלז","b":"נכד ר ברוך הלוי מבלז. רבו של ר חיים אהרן הופנר בעל \"העבריה\"."},{"i":574,"n":"אברהם אביגדור בונט ממונטפלייר","f":"משלם","k":"בעל סגולת מלכים","b":"חיבר \"סגולת מלכים\" - ובו חרז ספר ההיגיון לאריסטו בדרך שיר בעברית. חיבר גם דקדוק בלשון עברית - בכת\"י. למד רפואה במונפילייר. רופא מחכמי ספרד-קל, העתיק ספרי חכמה עם בנו ר שלמה. חיבר ספר על מלאת חכמת הגיון, ו\"מבוא הנערים\" - ברפואה."},{"i":575,"n":"אברהם אביגדור מקושטא","b":"חתן ר יצחק בן דוד מקושטא בעל \"דברי אמת\", וחיבר הקדמה לספר חותנו-תקך. (ראה גם: ר אברהם בן אביגדור בעל \"זכור לאברהם\")."},{"i":576,"n":"אברהם אבינון מסרייבו","dt":"תרסג","b":"גלל בבית רבי משה פיררא מטראבניק, היה רב בסארייבו, בשנת תרנט עלה לארץ ואחר כך חזר לסרייבו. נספד בספר אברהם שנית לר אברהם מירקדו."},{"i":577,"n":"אברהם אביש (אבא) מקראקא","b":"מחכמי קראקא-שן. חתם על התקנה ביריד קרמניץ שלא לקנות רבנות בכסף."},{"i":578,"n":"אברהם אביש אבלי מקונסקוולא","dt":"תקצב - יד ניסן","b":"תלמיד ר אלימלך מליזנסק, החוזה מלובלין, והמגיד מקוזניץ - שנהג להעביר אליו אל כל השאלות בהלכה. רב בקונסקוולא(=קנסקוואלי), מו\"צ בוארשא. הסכים על \"תורת משה\" תקמו. הגיה את ספר העיטור - וארשא תקסא. בנו ר פישל על מקומו אחריו. ובנו ר שמחה רב במעכיאוו."},{"i":579,"n":"אברהם אביש מליסא ופפד\"מ","f":"צבי הירש ממזריטש","k":"בעל מחזה אברהם","r":"אב\"ד פפד\"מ","bt":"תן-ס","dt":"תקכט - יא תשרי","dp":"פפד\"מ","b":"תלמיד בעל \"בית שמואל\", ר צבי הירש מהלברשטט, ר נפתלי בעל \"סמיכת חכמים\". חתן ר נחום מסלוצק (לפי עיר לאסק היה מהעיר לאסק). ונכדת ר שמואל מוודילסב-רבה של פיורדא. רב בקוריב, ריטשוואל, יאנוב, ליקוב, מזריטש, ליסא-תקיג, פפד\"מ-תקכא. היה אחד משלושת הבוררים שנקראו לישב את מחלוקת ר יונתן איבשיץ. היה בראש ביה\"ד בפפד\"מ שפסל את הגט מקליווא - דבר שגרר מחלוקת בין גדולי הרבנים בדור. חיבר גם \"ברכת אברהם\" - ורשא תרמא. מצאצאיו - ר אברהם ח' ש\"ב מיכלסון שחיבר \"אהל אברהם\" - לתולדות חייו של זקנו ר אברהם אביש ומתורתו, נכדו גם - ר יוסף לוינשטין מסערוצק. מתורתו ב\"קול תורה\" - וארשא תרסח.","bk":[["ברכת אברהם – ש\"ס",""],["הגהות עמק המלך – רמב\"ם",""],["מחזה אברהם – הגדה של פסח",""],["קנה אברהם – עה\"ת",""],["ברכת אברהם",""]]},{"i":580,"n":"אברהם אביש מקאריב","f":"אריה ליבש מקאריב","b":"רב בקאריב"},{"i":581,"n":"אברהם אביש מקרסטור","b":"אב\"ד קרסטור. גדל אצל ר ירמיה-אב\"ד סטנוב. נזכר בשו\"ת החת\"ס."},{"i":582,"n":"אברהם אביש מראב ושטמפן","b":"חזן בראב, שטמפן-תקעח."},{"i":583,"n":"אברהם אבלי","f":"שלמה מזלקווא","b":"בנו - ר שלמה."},{"i":584,"n":"אברהם אבלי הכהן חריף מקליש","f":"יחיאל מיכל","bt":"תצח","dt":"תקסט","b":"נכד ר אלכסנדר סנדר מלסלא, ומצד אמו נכד ר שמואל כץ מלוסק. רב בקאליש-תקכז. מתורתו ב\"שמן רוקח\". הסכים על \"בחינות עולם\" תקנב, \"ברכת אברהם תקעה, ועוד. אחיו - ר אריה יהודה מפוזנא."},{"i":585,"n":"אברהם אבלי הכהן כ\"ץ מראדזין","k":"בעל זכרון אברהם","dt":"תרה","b":"אב\"ד ראדזין. חיבר גם \"פני אברהם\"."},{"i":586,"n":"אברהם אבלי מביאלא","dt":"תקצג","b":"אב\"ד ביאלא-ליטא. נספד מאת ר אברהם דב פלאהם ב\"אבל יחיד\". מתורתו ב\"חמדת שלמה\"."},{"i":587,"n":"אברהם אבלי מבלז","f":"אלחנן מבוצ'אץ","dt":"תסז - כג תמוז","b":"רב בבעלז. (ב\"שם הגדולים השלישי\" מופיע נכד אחיו - ר אברהם אבלי מבריסק בן ר שלמה חריף מסלוצק והוא שנפטר ב-תסז)."},{"i":588,"n":"אברהם אבלי מבריסק","f":"שלמה חריף מסלוצק","dt":"תסז","b":"נכד ר אברהם אבלי מבלז. רב בבריסק. אחיו של ר אריה ליב מסלוצק. (באוצר הרבנים מופיע אחי זקנו - ר אברהם אבלי מבלז - והוא שנפטר ב-תסז)."},{"i":589,"n":"אברהם אבלי מדרוהוביטש","k":"בעל באר אברהם","bt":"תקכ","bp":"דרוהוביטש","dt":"תקצה או תרנב?","b":"תלמיד החוזה מלובלין. התפרנס כמלמד ונחשב לצדיק נסתר, רבו החוזה שלח אליו לקבל ברכות. בנו ר ישעיה מוסקוביטש, חתנו ר יוסף יעקב בן אליעזר ליפא מאלסק בעל \"אהל יעקב\". חיבר \"באר אברהם\" למברג תרכט."},{"i":590,"n":"אברהם אבלי מדרישקפאלי","b":"אב\"ד דרישקאפאלי. מתורתו ב\"תורת משה\"-נאוידוואהר תקנו."},{"i":591,"n":"אברהם אבלי מהורוחוב","b":"רב בהורוחוב"},{"i":592,"n":"אברהם אבלי מהרובשוב","f":"ישראל","b":"רב בהרובשוב"},{"i":593,"n":"אברהם אבלי מוארז'אן","f":"בן ציון מזעזמיר","k":"בעל אהבת איתן","dt":"תרמט - כא כסלו","b":"נינו של ר אברהם אבלי ממינסק בעל \"זכרון אברהם\"-נכדו של ר אבא אריכא חסיד מקרוז'. אב\"ד טירקשלה, וארז'אן-תקץ, לידוביאן, ירזניק-פלך סובאלק. בניו: ר ישראל מלודוינובה, ר בן ציון משוואקשנה, ר משה אהרן מריטובה. חתניו: ר יהודה ליב גרוסברד מגאוורי, ר ישראל יצחק פינברג מלייפון."},{"i":594,"n":"אברהם אבלי מוילנא","f":"אליעזר מקרוז ווילנא","b":"רב בוילנא. אחיו של ר משה מצייקישוק."},{"i":595,"n":"אברהם אבלי מוילנא","f":"מנשה","b":"שליח קהלת וילנא יחד עם ר יחזקאל בן ליב בזמן המחלוקת בקהלה עם רוזני וילנא."},{"i":596,"n":"אברהם אבלי מוילקומיר","f":"צמח מוילנא","b":"מצאצאי ר מרדכי יפה בעל ה\"לבושים\". רב בוילקומיר. בנו - ר בנימין הצדיק מוילקומיר."},{"i":597,"n":"אברהם אבלי מטשעריץ","b":"אב\"ד טשעריץ. גיסו של ר יחזקאל שרגא פיבל פרנקל-תאומים מקלאסני."},{"i":598,"n":"אברהם אבלי מניקלשבורג","f":"מרדכי בעל הלבוש","dt":"תיז","b":"רב בניקלשבורג. (לפי אוצר הרבנים - נכד בעל הלבוש)."},{"i":599,"n":"אברהם אבלי מסובאלק","f":"ברוך מאפטא","dt":"תרי - בערך","b":"תלמיד דודו ר יהודה ליב מרגליות בעל \"פרי תבואה\". מצאצאי בעל \"זרע ברך\". בניו - ר עזריאל אריה ליב ממאריאמפול, ר דב בר מולקוביסק."},{"i":600,"n":"אברהם אבלי מעיר חדש (מע\"ח)","b":"רב בעיר חדש-תק\"ע"},{"i":601,"n":"אברהם אבלי מפארצאווי","b":"אב\"ד פארצאווי-ליד מזריטש-מחוז וארשא."},{"i":602,"n":"אברהם אבלי מפוסוואל ווילנא","f":"אברהם שלמה מפוסבול","k":"בעל באר אברהם - בכתי","r":"רב במקום אביו בפאסוול, ומגיל שלושים ושמונה ראב\"ד וילנא","bt":"תקכד","bp":"פוסוואל","dt":"תקצו - יג אב","dp":"וילנא","b":"תלמיד ר שלמה לנדא מוילקומיר-תלמיד הגר\"א. חתן ר אליקים גצל מפוסוואל, ובזיוו\"ש חתן אב\"ד לנדצוט, ובזיוו\"ש חתן ר יצחק ז\"ק אב\"ד פוסבול ובירז'. אב\"ד פוסבול-תקסב על מקום אביו וחותנו, וילנא-תקצב, על מקום ר דב בר טרוויש. מתשובותיו ב\"מנחה בלולה\" לר שמעון בן דב מסלונים, וב\"בגדי ישע\" לר שמואל הלוי בן יוסף מביאליסטוק. דן במחלוקת בין המדפיסים ראם בוילנא ובין מדפיסי סלאויטה, שהחלו להדפיס את הש\"ס באותו הזמן - ופסק לטובת המדפיסים ראם. נספד ע\"י ר יצחק מוולוזין. לאחר פטירתו פנו פרנסי וילנא לר עקיבא איגר שסירב ואז נתמנה גיסו של ר אבלי - ר יחזקאל הלוי לנדא על מקומו אחריו. (הסכים על \"תעודה בישראל\" למשכיל ריב\"ל - ועל כך היו דעות שונות האם הסכים בעל כרחו). אחיו - ר חיים מפוסוואל.","bk":[["באר אברהם - חידושים ושו\"ת",""]]},{"i":603,"n":"אברהם אבלי מקאלוואריה","f":"ירמיהו מסימנא","k":"בעל מדבר סין","bp":"קאלוואריה","b":"מ\"מ בסימנא-פלך הורדנא-בשנות התק'. חיבר גם \"סדר אברהם\"."},{"i":604,"n":"אברהם אבלי מקטינברג","f":"יוסף יאסקי","dt":"תקסא - יז תשרי","b":"רב בקטרינברג"},{"i":605,"n":"אברהם אבלי מרוהטין","f":"זלמן ליברס מלמברג","b":"רב ברוהטין-תקע. נינו של בעל \"לקט יוסף\"."},{"i":606,"n":"אברהם אבלי משטעריץ","b":"רב בשטעריץ"},{"i":607,"n":"אברהם אבלי משנארווי","b":"אב\"ד שנארווי-תקסג."},{"i":608,"n":"אברהם אבלי פרנס מלובלין","f":"ישראל איסר בן משה","k":"אברהם הקטן ר איסרלש","dt":"תקז - כא ניסן","dp":"לובלין","b":"מצאצאי המהרש\"א. פרנס בלובלין, זולקווא?. חתם-תנט עם ראשי ועד ארבע ארצות בענין דפוס זולקווא. הסכים על \"דמשק אליעזר\" על התורה, לפני עמד הבעש\"ט בענין יעלה ויבא (כנזכר בשבחי הבעש\"ט ללא אזכור שמו), אחיו - ר מרדכי הפרנס מזולקוא. בנו - ר ישראל איסר מלובלין - הנכד."},{"i":609,"n":"אברהם אהרן הלוי מירושלים","bt":"תרל","bp":"ירושלים","dt":"תרפא - כד טבת","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":610,"n":"אברהם אהרן מהאלעש","b":"רב בהאלעש."},{"i":611,"n":"אברהם אונווייליס מספרד ומרוקו","b":"מחכמי ספרד, לאחר הגירוש הגיע לפאס-מרוקו. נזכר ב\"נר המערב\"."},{"i":612,"n":"אברהם אורי משלוניקי","b":"רב באמשטרדם-שמו, עבר לשלוניקי וכיהן כרב הקהלה האשכנזית. מתורתו ב\"בני שמואל\" לר שמואל חיון. אחיו - ר משה אורי - רב הקהלה האשכנזית באמשטרדם."},{"i":613,"n":"אברהם אורי פיבש מקראקא","f":"שמואל"},{"i":614,"n":"אברהם אזרח מרומי","f":"מתתיהו","b":"מחכמי רומא-ד'תתן. חתם בתשובת חכמי רומי לחכמי פאריס בענין חזקת ישוב. חיבר פיוטים ונכנסו למחזור רומי."},{"i":615,"n":"אברהם אחי המהר\"ם מרוטנבורג","f":"ברוך","k":"בעל סיני","dt":"נח","dp":"רונדפלייש - רוטנבורג","b":"תלמיד ר משה מחקו, ר שמואל בן ברוך מבונבורג. פוסק, פייטן - חיבר קינה על הנהרגים בעיר פורצהיים-ה'לא (ונהרגו שם ר יקר הלוי ואביו ר שמואל - בשם \"כי אזעק במר לב\". אחי המהר\"מ מרוטנבורג, נהרג עק\"ה בגזירות רונדפלייש ברוטנבורג. גיסו של ר סעדיה בן שניאור חתן הר\"מ."},{"i":616,"n":"אברהם אייזיק מארה\"ב","dt":"תקסג","b":"יהודי היחיד? בפורטסמוט-ארה\"ב, שומר תורה ושבת."},{"i":617,"n":"אברהם אלברשווילר","b":"מחכמי אלברשוויל(-עיירה ליד מנהיים). אין פרטים."},{"i":618,"n":"אברהם אלחנן מפלאנטש","f":"יהודה","k":"בעל ברכת אברהם","r":"תלמיד הקדושת לוי","dt":"תקצה - ה טבת","b":"תלמיד ר לוי יצחק מברדיטשוב. רב בפלאנטש, ובנו ר דב צבי על מקומו אחריו.","bk":[["ברכת אברהם – עה\"ת וש\"ס",""]]},{"i":619,"n":"אברהם אליהו הכהן","b":"העתיק פירוש יג מדות של ר ישמעאל, ונמצא בותיקן."},{"i":620,"n":"אברהם אליהו מטלז וקרויצבורג","dt":"תרכו","b":"אב\"ד טלז, קרויצבורג. בנו - ר פנחס משה גורדון מביאליסטוק בעל \"תפארת אברהם\"."},{"i":621,"n":"אברהם אליהו מפטשינוב","b":"רב בפאטשינוב"},{"i":622,"n":"אברהם אליעזר הכהן משלוניקי","dt":"תקיז","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":623,"n":"אברהם אליעזר הלוי מירושלים וטב","f":"צבי","bp":"ירושלים או איטליה","dt":"תקפו - יא כסלו","dp":"טריאסט","b":"פוסק, עלה בצעירותו לירושלים (לפי גליס - נולד בירושלים), תלמיד החיד\"א, הספד של על החיד\"א נדפס בספר \"שבולים בודדות\" לדיינרד. יצא בשליחות לאיטליה והיה רב בטריאסט-תקסא. בכתב ידו ספר מנהגי תפלה וקריאה של קהילת טריאסט (בספריה הלאומית)."},{"i":624,"n":"אברהם אליעזר לייזר מקראקוב","f":"ראה: דמשק, אברהם אלי"},{"i":625,"n":"אברהם אליעזר מרדומישל","dt":"תקע","b":"רב ברדומישל. זקנו של ר אשר זליג לנדא מאושפיצין."},{"i":626,"n":"אברהם אליעזר משלוניקי","b":"מורשה קהלת שלוניקי לשליחת המס לקושטא עם עוזרו ר יהודה הכהן, נאלץ לברוח מהשלטונות."},{"i":627,"n":"אברהם אלכסנדר מאמריקה","dt":"תקמד","b":"רב בצ'רלסטון-דרום קרולינה-תקכד על מקום ר יצחק די קוסטה, ועל מקומו אחריו ר אברהם אזובי."},{"i":628,"n":"אברהם אלעזר מספרד","f":"כלפון","k":"בעל פירוש לספר הענק","b":"בלשן ומדקדק מחכמי ספרד. חיבר פירוש לספר הענק לר משה ן עזרא."},{"i":629,"n":"אברהם אלתר יוסף הלוי מטבריה","f":"פייבוש סגל","dt":"תרמד","dp":"טבריה","b":"מחכמי טבריה, נכדם של ר אריה ליב מוולטשיסק ור יעקב שמשון משפטיבקה, היה ממונה על החלוקה. בשנת תרכה בשליחות."},{"i":630,"n":"אברהם אנשיל מסעקולי","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":631,"n":"אברהם ארדנטל מספרד","f":"שלמה","k":"בעל ספר זכרון בקבלה","b":"מקובל מחכמי ספרד. חיבר ספר זכרון בקבלה - בכת\"י. מכונה בשם - ארדנטאל טורטיאל."},{"i":632,"n":"אברהם אריה ליב הלוי מסטריזוב","f":"יהודה","k":"בעל דרישת ארי","bt":"תצה","bp":"טסריזוב","dt":"תקסג","b":"תלמיד המגיד מקוזניץ. רב סטריזוב-תקל ובעוד קהלות. נחשב לאחד מגדולי הדור בנגלה ובנסתר ובין תלמידיו בן דודו ר משה טייטלבוים מאויהל. חיבר \"דרישת ארי\" למברג תקסד ועוד."},{"i":633,"n":"אברהם אריה ליב מעתיק מוילנא","f":"יצחק מעתיק בית הלל","dt":"תרמח - ז חשון","b":"חתן ר מרדכי-דיין בוילנא, מעתיק הקהלה על מקום אביו. בנו ר דוד - למד משפטים בפטרבורג ונשאר יהודי נאמן."},{"i":634,"n":"אברהם אריה מאמשטרדם","b":"חתם-תרד בשם פקידים ואמרכלים מאמשטרדם, עם ר יעקב מאיר להרן ור זלמן רובענס."},{"i":635,"n":"אברהם אשכנזי אפטייקה מלודמיר","k":"בעל סם חיים","b":"מחכמי לודמיר-שן. חיבר ספר מוסר עם לשון אשכנז - פרג שן."},{"i":636,"n":"אברהם אשכנזי מצפת","f":"שמעון","b":"שליח צפת בשנת תקעח (1815) בתוניס, הסכים שם על ספר \"נר דוד\" לר דוד גיג ליוורנו תרכח."},{"i":637,"n":"אברהם אשכנזי מצפת","f":"יצחק","b":"מחכמי צפת-שן. הקים דפוס בצפת יחד עם ר אליעזר בן יצחק אשכנזי, בשליחות בתימן-שמ, והמשורר ר זכריה יחיא אל צאהרי מפליג בשבחו בספר המוסר שלו."},{"i":638,"n":"אברהם אשר הלוי מירושלים","f":"יעקב מרדכי","bt":"תקצה","bp":"ירושלים","dt":"תרמה","dp":"ירושלים","b":"ראש ישיבת גדולת מרדכי, דיין בירושלים-תרל אצל ר יוסף רפאל עוזיאל, יצא לשליחות לטורקיה להודו, שם פעל למען היהודים השחורים שהיו עבדים או צאצאיהם, ועקב כך החלה מלחמה נגדו על ידי יהודי קוצ'ין, נספד באזמיר בספר \"אברהם את ידו\""},{"i":639,"n":"אברהם אשר מאמשטרדם","bt":"תרמד","dt":"תרפו - כו אייר","b":"דיין באמסטרדם-תרע\"ח,רב ראשי בגליל גרוניגן(הולנד)"},{"i":640,"n":"אברהם באע\"ז משעפסק","b":"רב בשעפסק-פולין. הסכים על \"קול יהודה\" - יוזפוב תקפו."},{"i":641,"n":"אברהם בכור הלוי משלוניקי","dt":"תקב","b":"מחכמי שלוניקי"},{"i":642,"n":"אברהם בכר שבתי משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"ראש משביר\"-תר, \"בית מנוחה\"-תריא - עם כמה מחבריו."},{"i":643,"n":"אברהם בן אליהו מוילנה","bt":"1750","dt":"ה'תקסח 1808","bk":[["תרגם אברהם",""]]},{"i":644,"n":"אברהם בן אשר אנשל ממינסק","bt":"1760","dt":"ה'תקצג 1833","bk":[["עמוד הימיני",""]]},{"i":645,"n":"אברהם בן דוד מפוסקיר ראב\"ד ה","bt":"1120","dt":"ד'תתקנח 1198","bk":[["איסור משהו להראב\"ד",""],["בעלי הנפש",""],["דרשה לראש השנה",""],["חידושי הראב\"ד",""],["חידושי הראשונים עמ''ס סוכה פרק לולב הגזול",""],["פירוש הראב\"ד",""],["שער הזקנים",""],["תורת כהנים – ווין – תרכ”ב",""],["תמים דעים",""]]},{"i":646,"n":"אברהם בן הרמב\"ם","f":"משה-רמב\"ם","k":"רבנו אברהם החסיד","bt":"ד'תתקמו-סיון","dt":"ד'תתקצח-יח כסלו","b":"רופא המלך וראש רבני מצרים, כתב תשובות למשיגים על אביו הרמב\"ם, וספר \"המספיק לעובדי ה'\"","bk":[["רבי אברהם בן הרמב\"ם","מפרשי תורה"],["המספיק לעובדי השם","הלכה ומנהג - ראשונים"],["המספיק לעובדי השם","מחשבה ומוסר - ראשונים"],["רבי אברהם בן הרמב\"ם","שו\"ת - ראשונים"],["ברכת אברהם","שו\"ת - ראשונים"],["מעשה נסים","שו\"ת - ראשונים"],["ברכת אברהם","מפרשי רמב\"ם"],["שו\"ת ר' אברהם בן הרמב\"ם","מפרשי רמב\"ם"],["המספיק לעובדי השם \\ כפאיה אלעאבדין",""],["מלחמות השם והמאמר על דרשות חז\"ל",""],["מעשה נסים - שאלות ר' דניאל הבבלי ותשובות ר' אברהם בן הרמב\"ם",""],["פירוש רבינו אברהם בן הרמב\"ם על - בראשית ושמות",""],["ברכת אברהם – שו\"ת \\ תשובות רבינו אברהם בן הרמב\"ם",""],["המספיק לעובדי ה', ד' תתקצ\"ז",""]]},{"i":647,"n":"אברהם בן יעקב יוסף מאוסטרהא","f":"ראה: ספרד, אברהם מקי","k":"בעל מראה עינים","dt":"תקפו","dp":"אזמיר","b":"חיבר גם \"מראה הנוגה\", \"מראה הגדול\" ועוד."},{"i":648,"n":"אברהם בן יעקב מנשה משלוניקי","f":"ראה: מנשה, אברהם"},{"i":649,"n":"אברהם בן יצחק מנרבונה","bt":"1085","dt":"ד'תתקיח 1158","bk":[["האשכול",""],["ספר האשכול",""],["רבנו אברהם אב\"ד",""]]},{"i":650,"n":"אברהם בן צור מצפת - א","b":"מראשי חכמי צפת בשנת תמח"},{"i":651,"n":"אברהם בן צורי מצפת - ב","dt":"תקצז","dp":"צפת","b":"נמנה על ההרוגים ברעש"},{"i":652,"n":"אברהם בן ציון ממינסק","f":"מיכאל אליהו","dt":"תרמב - ח חשון","dp":"מינסק","b":"מחכמי מינסק."},{"i":653,"n":"אברהם בנימין וולף מגריידיץ","f":"יוסף יוסקא","k":"בעל אם לבינה?","b":"רב בגריידיץ. הסכים על \"בית אהרן\" - פפד\"א תן."},{"i":654,"n":"אברהם בנימין זאב הלוי (שפירא)","f":"שמואל ל\"ש מפרג","dt":"תקנב","dp":"פפערשא","b":"מצאצאי ר אהרן שמעון שפירא מפרג. חתן ר צבי הירש שפיץ מוינה. אב\"ד מדינת איטינגן-תקיג, פפערשא-תקכג ומדינת שוועבין על מקום ר יצחק זקיל עטהויזן בעל \"אור נעלם\". הסכים על \"אניה בלב ים\" - פיורדא תקכו, ו\"זבד בנימין\" תקמג. נזכר אצל ה\"נודע ביהודה\". גיסו(-בעל אחותו) ר ר בצלאל בן משה ברנדס בעל 'צדה ברוך'."},{"i":655,"n":"אברהם בנימין מבלגרד","b":"רב בבלגרד-שנות ה-ש'."},{"i":656,"n":"אברהם בנימין משירון","b":"מראשי קהלת שירון-שנות ה-ת'."},{"i":657,"n":"אברהם בנימין נתן העזתי","f":"אלישע אשכנזי","k":"בעל חמדת ימים?","bt":"תד","bp":"ירושלים","dt":"תמ - יא שבט","dp":"איסקופיה(=איסקוב)","b":"תלמיד ר יעקב חגיז בירושלים. חתן הגביר שלמה ליסבונה מעזה ועבר לשם. נביא השקר שהכתיר את ש\"ץ למשיח. גם לאחר התאסלמות ש\"ץ, המשיך לתמוך בו, הקים ישיבה בשלוניקי, ומתלמידיו: ר שלמה פלורנטין, ר יוסף פילוסוף (חותנו של ש\"ץ), ר יצחק חנן, ר אברהם פרץ, ר ירמיהו, ר יוסף רוסו, ר חיים גאגין, ר יוסף קובו, ר יהודה ברוך, ר רפאל ברוך-חתן ר פלורנטין, ר שבתי עמנואל, ר מרדכי הכהן, ר דוד קרימישין, ר אליעזר הכהן, דון אשר אברבנאל."},{"i":658,"n":"אברהם בנימין רפאל הכהן מחברון","f":"אברהם חיים","bp":"פולין","dp":"טבריה","b":"בשנת תקי עלה לחברון, הדפיס בפיורדא תקטז קונטרס \"מים חיים\" מאת אביו. היה בטבריה ויצא בשליחות טבריה לצפון אפריקה שם הסכים על ספר \"מאמר מרדכי\" לר מרדכי צרמון ליוורנו תקמז."},{"i":659,"n":"אברהם בעל שם מדילאציץ","f":"אליהו מדילאציץ","b":"רב בדילאציץ."},{"i":660,"n":"אברהם בער מאיהומען","b":"רב באיהומען-תר\"ל"},{"i":661,"n":"אברהם בער מדלטין","b":"מו\"צ בדאליטין"},{"i":662,"n":"אברהם בער מנדבורנא","b":"תלמיד ר מנחם מנדל מקוסוב. מו\"צ בנדבורנא"},{"i":663,"n":"אברהם בר","f":"יוסף-חתן ר נחמן מברס","b":"נכד-(בן בתו אדל) ר נחמן מברסלב. חתן ר משה חינקעס. השתדך עם חסיד טולנה בזמן המחלוקת בין טולנה לברסלב."},{"i":664,"n":"אברהם בר חייא מקטלוניא הנשיא","k":"ראב\"ח - הגיון הנפש","b":"רב בקטלוניא-ד'תת\"ע"},{"i":665,"n":"אברהם בר צדקה מאשקלון","b":"בשנת ד תתקד (1144) כתב באשקלון מכתב כידיד הישיבה לר נתנאל התלמיד בן צדקה."},{"i":666,"n":"אברהם ברא\"ק מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":667,"n":"אברהם ברוך הרופא מאזמיר","f":"ברוך?","k":"בעל אשמורת הבקר","b":"רופא באזמיר-שנות ה-ת'."},{"i":668,"n":"אברהם ברוך הרופא מאזמיר","b":"רופא מחכמי אזמיר-שנות ה-ת'."},{"i":669,"n":"אברהם ברוך מגאנייה","bt":"שטו","dt":"תו","b":"רב בגאנייה"},{"i":670,"n":"אברהם ברוך מטריקלה","b":"דיין בטריקלה-תכז אצל ר דניאל הכהן \"איש חמודות\"."},{"i":671,"n":"אברהם ברוך ממאצוב","b":"דיין במאצוב"},{"i":672,"n":"אברהם ברוך מצפת","f":"מרדכי","b":"נמנה בין העולים לצפת עם ר מנחם מנדל משקלוב, וחתם-תקעג בענין ר יוסף יעקבקא פרנקל מברסלוי."},{"i":673,"n":"אברהם ברוך מקושטא","b":"רב בקושטא-שנו."},{"i":674,"n":"אברהם ברוך מקנדיא","f":"ברוך","bp":"שלוניקי","dt":"תל - בערך","dp":"קנדיא?","b":"תלמיד ישיבת ר מרדכי קלעי בשלוניקי. עסק במסחר בלאריסה עם אחיו - שבתי ברוך, רב בקנדיא(=כרתים) ור משה אלקוסטנטין על מקומו אחריו-תל. עמד לדין מול סוחרים בלאריסה בפני ביה\"ד בשלוניקי והפסיד בדין."},{"i":675,"n":"אברהם ברוך מריגא","k":"אדמור מריגא","b":"תלמיד החוזה מלובלין. וכיהן כאדמור."},{"i":676,"n":"אברהם ברוך משלוניקי","b":"מחכמי שלוניקי בשנות הש', בקי בלשון, נספד ע\"י ר סעדיה לונגו."},{"i":677,"n":"אברהם ברוך משלוניקי","dt":"ת - כב אלול","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":678,"n":"אברהם גאון","f":"מזהיר","b":"הוא או אביו חתן למשפחת גאוני ארץ ישראל הכהנים יוסף, שלמה, אליהו, אביתר. ראש ישיבת \"גאון יעקב\" בחדרך ודמשק על מקום ר מצליח בן שלמה הכהן (ישיבת ארץ ישראל גלתה לאחר כיבוש הארץ בידי הנוצרים). מכתב אליו מר נתן בן שמואל החבר, אולי הוא שפגש בו ר יצחק בן הראב\"ע בבבל. בניו: רב עזרא על מקום אביו בדמשק, רב שר שלום אב\"ד דמשק."},{"i":679,"n":"אברהם גאון","f":"יאשיהו","b":"ראש ישיבת גאון יעקב בירושלים. בנו ר אהרן ונכדו ר יאשיהו גאון ישיבת רמלה."},{"i":680,"n":"אברהם גאון מרומא","f":"יואב","b":"מחכמי רומא בזמן הגאונים-ד'תשן. פייטן, כונה במחזורים בשם ר אברהם הזקן, סליחה ממנו בשם \"אבוא היום בתפילה\". (יש אומרים שהוא אביו של ר יחיאל, וזקנם של ר נתן בעל הערוך, ר אברהם ור דניאל)."},{"i":681,"n":"אברהם גאון פומפדיתא","f":"שרירא","dt":"ד'תקפט","b":"גאון פומפדיתא-ד'תקעז על מקום רב יוסף בן יהודה גאון. היה מחלוקת על ראשות הגולה ודניאל ראש גלותא מינה במקומו את רב יוסף בן חייא ולאחר שנתפייס עם ראש הגולה חזר רב יוסף לכהן כאב\"ד, ועל מקומו אחריו."},{"i":682,"n":"אברהם גבריאל מפינטשוב","b":"רב בפינטשוב-תקמ\"ג"},{"i":683,"n":"אברהם גבריאל מצפת","dt":"שעב - אחרי","b":"מתלמידי הארי, ומוסמך ע\"י ר יעקב בירב. עבר מטבריה לצפת בשנת שע והיה רב קהילת איטליה בצפת. חתום על אגרת שליחות מטעם עדת האיטליאנים לר חיים יוסף שנת שמא חתום על תקנה משנת שנז, מכתב גדולי צפת לר אהרן ברכיה ממודנא בשנת שע. הסכים על ספר \"באר שבע\" שעב, מוזכר בשות \"לחם רב\" צב, שות שם טוב צהלון, כנסת הגדולה ריש ח\"ג יו\"ד. המביט מזכירו בתשובותיו, מופיע בתשובות כתי לר אברהם ארחא."},{"i":684,"n":"אברהם גבריאל משלוניקי","b":"רב בשלוניקי-ש\"פ"},{"i":685,"n":"אברהם גץ (כץ) מג'רבה","b":"רב בגרייבא (ג'רבה). מחדושיו בספר \"קרני ראם קטן\" על רש\"י והרא\"ם."},{"i":686,"n":"אברהם גר צדק מירושלים","dt":"תרטו - ח חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":687,"n":"אברהם גר צדק מקורדובה","b":"חיבר בספרדית \"אמיתות יסודי האמונה\" ותורגם מר מרדכי לוצטו ל\"צריח בית אל\"."},{"i":688,"n":"אברהם גרשון אשכנזי מירושלים","f":"יקר","dt":"תקע - יב אד\"ב","dp":"ירושלים","b":"נכדו של ר אברהם גרשון מקיטוב, ונכד של ר משה אוסטרר בעל \"ערוגת הבשם\" זאלקוא תקה. מראשי ישיבת \"בית אל\""},{"i":689,"n":"אברהם גרשון הלוי מניקופול וצפת","b":"גביר וראש קהלת ניקופול-שנות ה-תק', עלה לצפת וקיבל מהקהלה את ספר התורה של ר יוסף קארו והשיבו לניקופול."},{"i":690,"n":"אברהם גרשון מירושלים","dt":"תרלז","dp":"ירושלים","b":"היה דיין, נספד בישיבת אח\"ד, ונדפס ההספד בספר \"קול שחל\" דרוש א."},{"i":691,"n":"אברהם גרשון קיטובר מברוד","f":"אפרים מקיטוב","k":"גיס הבעש\"ט","bt":"תנו","bp":"ברודי","dt":"תקכא - כה אד\"א","dp":"ירושלים","b":"גיסו של הבעש\"ט, מחכמי קיטוב, מחכמי ה\"קלויז\" בברודי, שאל את הנודע ביהודה ונזכר בספרו, וכן אצל ר יונתן איבשיץ, ור יוסף תאומים בעל פרי מגדים. עלה לחברון-תקז, ואחר כך בירושלים, מחברי ישיבת המקובלים בית אל. בניו ר יקיר, ור חיים אהרן - שעלו עמו לארץ, ושאר בניו ר משה-תלמיד הבעשט, ר יצחק, ר אפרים פישל, ור יהודה ליב המגיד מלאדיזין שנשארו בחו\"ל - לתולדותם ב\"אור כי טוב\". חתנו - ר אברהם רוביו מחברון."},{"i":692,"n":"אברהם דב בער הלוי מרדושקביץ","f":"יחזקאל בן שמואל מאמד","dt":"תרכה","b":"נכד ר שמואל הכהן מאמדור (האם היה כהן או לוי?), ואחיינו של ר הלל מהורדנא בעל \"חוט המשולש\" ונזכר בספרו. אב\"ד רדושקביץ, קמניץ ובנו ר משה על מקומו אחריו. נספד ב\"בכי ומספד\" לר ישראל וישניק. (ראה גם: ר אברהם דב מרגליות מרדושקביץ)."},{"i":693,"n":"אברהם דב בר הכהן מוארשא","b":"תלמיד ר צבי יחזקאל מיכלסון מוארשא. מעורכי \"שערי תורה\" - וארשא תרסג. (אולי הוא בעל \"ברכת אברהם\")."},{"i":694,"n":"אברהם דב בר הלוי מקמניץ","f":"יחזקאל הלוי","k":"בעל זכר אברהם","dt":"תרכט - טו תשרי","b":"מצאצאי ר אלכסנדר זיסקניד בעל \"יסוד ושורש העבודה\". רב בקמניץ. נזכר ב\"חוט המשולש\" לר אליעזר יצחק מוולוזין, \"עמודי אש\" לר אברהם שמואל מאישושוק. בנו - ר משה מקמניץ."},{"i":695,"n":"אברהם דב בר מארשא","f":"שלמה","k":"בעל באר אברהם","b":"מצאצאי ר אברהם ברוידא ממיץ בעל \"אשל אברהם\", ונכד-מצד אמו ר שמואל הלוי מפוחוביץ. רב בארשא-תקמג."},{"i":696,"n":"אברהם דב בר מבוברויסק","b":"חסיד חב\"ד בבוברויסק. לתולדותיו \"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":697,"n":"אברהם דב הלוי מאוסטרהא","f":"שמואל שמלקי","dt":"תקיא - א חשון","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אחיו של ר נתן נטע הדיין מאוסטרהא."},{"i":698,"n":"אברהם דב מדלטין","b":"רב בדלטין. חתן ר שמואל שמחה זימל מקוסוב (גיסו של ר יעקב קופל מקולומיאה). נכדו - ר יוסף חיים מטריבושאן בעל \"פרח הגפן\"."},{"i":699,"n":"אברהם דב מחמלניק","b":"רב בחמלניק"},{"i":700,"n":"אברהם דב מניקולייב","b":"רב בניקולייב-תרל\"ה"},{"i":701,"n":"אברהם דב סענער מחברון","b":"מחסידי חב\"ד בחברון. חתם על כתב שליחות-תקצה."},{"i":702,"n":"אברהם דוד בן אשר מבוצ’ץ’","bt":"1771","dt":"ה'תר 1840","bk":[["אמרות טהורות",""],["אשל אברהם",""],["ברכת אברהם",""],["דברי אבות",""],["דעת קדושים",""],["מחזה אברהם",""],["מילי דחסידותא",""],["עזר מקודש",""],["קונטרס תרל (תר\"ל)",""],["תפלה לדוד",""]]},{"i":703,"n":"אברהם דוד הכהן מליטומירסק","k":"בעל ראש יוסף","b":"רב בלוטומירסק(=ליטומירסק)-תרל. תלמיד ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר. היה מהמכתירים את ר אברהם מסוכטשוב."},{"i":704,"n":"אברהם דוד מאזמיר","dt":"תקך - כג תמוז","dp":"אזמיר","b":"רב באזמיר."},{"i":705,"n":"אברהם דוד מטושוויץ וסטנוב","f":"משה","b":"רב בטושוויץ-תקו, סטאנוב-תקל. הסכים על \"אהל יוסף\" - אלקסניץ תקכז, \"אגרת בית תפלה\" - ברלין תקלג."},{"i":706,"n":"אברהם דוד ממירופול","f":"משה בן שמואל","k":"אדמור ממירופול","dt":"תרעא - כט חשון","b":"נכד ר שמואל מקמינקא. חתן ר צבי הירש מקמינקא. תלמיד דודו ר אהרן מטשרנוביל."},{"i":707,"n":"אברהם דוד משירון","k":"בעל תפארת אדם","b":"רב בשירון - בשנות התק-תר. תשובה אליו-תקף מר יעקב רפאל מנשה משלוניקי, ר חיים שמואל גטניו ור דוד הלוי קרסו. (ראה גם: חיים אברהם בן דוד אישטרושא)"},{"i":708,"n":"אברהם דוד משלוניקי","b":"דיין בשלוניקי, חתם-תקעב עם ר אברהם פרחיה הכהן, ר מנחם הכהן ן ארדיט ור אברהם גטניו."},{"i":709,"n":"אברהם דוד משקלוב","b":"דיין בשקלוב-תר\"מ"},{"i":710,"n":"אברהם דוד נחמן מקושטא","b":"מדפיס בקושטא אצל השותפים יוסף אלקלעי, רפאל טרוויש ויהושע מזרחי, הדפיסו \"חדושי גטין\"-תעא."},{"i":711,"n":"אברהם דון דין מספרד ואיטליה","b":"מחכמי ספרד והתישב באיטליה, רב בפיסא-ש'. חתם ב\"פחד יצחק\" בענין חליצה."},{"i":712,"n":"אברהם דעס רב'ס","f":"יצחק בן שמואל זנויל","b":"חתן ר יעקב שור מלוצק ובריסק. בנו של ר יצחק מזולקוא."},{"i":713,"n":"אברהם הבבלי מספרד","b":"מחכמי בבל והגיע לספרד-ד'תת בערך. נזכר בספרי הראב\"ע, אצל רבנו תם, ועוד. קונטרס ממנו באוכספורד."},{"i":714,"n":"אברהם הגדול מרגנשבורג","f":"משה בן יואל","b":"אביו היה מתלמידי ריב\"א-תלמיד רש\"י. מחכמי אשכנז-ד'תתקן. חתן בנו של ר מרדכי-אחי הריב\"ם. מתלמידיו ר יצחק בעל \"אור זרוע\"."},{"i":715,"n":"אברהם הגר","b":"מאמר ממנו בביאור קשים גרים כספחת מובא בתוספות."},{"i":716,"n":"אברהם הגר מאויגסבורג","b":"גר צדק מאישפורג(=אויגסבורג)-כ\"ה ששבר צלמים נוצריים נתפס ונהרג עק\"ה, ואח\"כ היה שם פרעות ביהודים ונהרגו כל יהודי זקהיים דנציג, וכמה רבנים חברו סליחות על כך ובהם ר מרדכי בן הלל, ור משה בן יעקב."},{"i":717,"n":"אברהם הגר מוילנא","f":"אברהם","dt":"תקט - ז סיון","dp":"וילנא","b":"ממשפחת פוטוצקי. נהרג עק\"ה אחר שסירב לחזור בו מיהדותו. מקורב לגר\"א."},{"i":718,"n":"אברהם הגר מצפת","f":"אברהם","dt":"תרג","dp":"ירושלים","b":"שליח צפת, הדפיס המלצה לשליחותו בליוורנו; כנראה עבר לירושלים אחר רעידת האדמה בצפת"},{"i":719,"n":"אברהם הגר משלוניקי","dt":"תרל","dp":"שלוניקי","b":"גר יווני, מחכמי שלוניקי, דרשן ומוכיח. חיבר כת\"י ונזכר אצל אלקן נתן אדלר בביקורו בשלוניקי."},{"i":720,"n":"אברהם הזרקל אלברטוני","b":"מחכמי התכונה הקדומים, ונזכר ב\"ראשית חכמה\" לאבן עזרא - המספר שחי כ-70 שנה לפניו ושיחבר לוחות כוכבים שנקראו לוחות טוליטולא. כונה בשם - \"אלברטוני\", \"אבן יצחק אברהם בן יחיא\"."},{"i":721,"n":"אברהם החבר ממצרים","b":"מחכמי מצרים-ד'תתקן בזמן הרמב\"ם ונזכר בתשובותיו, ויתכן והיה דיין אצלו. חתם על תקנת הרמב\"ם-ד'תתקמז בענין טבילת נשים, וכן חתם בתשובות הרמב\"ם על כמה תשובות. נזכר בספרי ר אברהם בן הרמב\"ם שכיבדו וקרא לו החסיד. רשימת עזבונו נמצאה בגניזה (ובה פירוט של ספרי קדש וספרי רפואה). (יש אומרים שהוא ר אברהם בן הלל)."},{"i":722,"n":"אברהם החבר מרמלה","f":"שמאל השלישי","b":"מחכמי רמלה בשנת ' תשפו (1026), בנו של ר שמואל בריבי הושענא, חתום כראש בית דין בתעודה שפרסם מ אסף בידיעות ח עמ' 64"},{"i":723,"n":"אברהם החוזה מטבריה","b":"מראשי הקהלה בטבריה בשנת תתקכה 1165, מוזכר במסעות ר בנימין מטודלה. מיוחסת לו הקינה \"ציון קחי כל צרי גלעד\", יש אומרים שהוא ר אברהם ן עזרא"},{"i":724,"n":"אברהם החזן","b":"פייטן מזמן הגאונים. כמה מפיוטיו נכנסו למחזור. קטעי פיוטים ממנו נמצאו בגניזה."},{"i":725,"n":"אברהם החסיד","k":"בעל שבולת הלקט","b":"נזכר ב\"קב וישר\"."},{"i":726,"n":"אברהם הטרוקי הקראי","f":"יאשיהו","k":"בעל בית האוצר","dt":"תמח - ז כסלו","dp":"חצר סודרן","b":"מחכמי הקראים, ורופא המלך יאן סוביסקי. חיבר גם \"משא העם\", ועוד. בנו - יהודה."},{"i":727,"n":"אברהם הירושלמי","f":"יום טוב","b":"חתום על הסכמה ל\"ברכת אברהם\" לר אברהם צרפתי, ובספר \"נחלה ליהושע\" לר יהושע שונצין סימן יז. מופיע באגרות ובספרים שונים וביניהם ר יוסף קארו. הדפיס בצמוד למחזור רומניא המנהגים לעדת הרומניטים (בומברג של). בשנת שו חתום על הסכמה בירושלים. בשנת רמז חתום ב\"כתר תורה\" עם רבני שלוניקי. רבלין בתח\"י סבור שיש כאן ערבוב בין 2 או 3 רבנים שונים באותו השם."},{"i":728,"n":"אברהם הכהן","f":"אליעזר","k":"בעל אורי וישעי","b":"נכד בעל \"מתנות כהונה\". חיבר \"אורי וישעי\" ברלין תעד, \"עיני הכהן\", הו\"ל \"מראה כהן\" לזקנו."},{"i":729,"n":"אברהם הכהן איזידור מירושלים","b":"מחכמי ישיבת \"בית אל\" בירושלים-תקיח."},{"i":730,"n":"אברהם הכהן הפייטן מאשכנז","f":"יצחק","b":"פייטן בשנת ד'תת בערך. כמה מפיוטיו נמצאים במחזור אשכנז, חיבר גם פיוט לברכת חתנים, נוסח הרחמן הוא יברך אבי הילד - לברית מילה, ויוצר ושו\"ת לברית מילה במחזור נפולי."},{"i":731,"n":"אברהם הכהן הרופא מפאס וירושלים","f":"יצחק?","bt":"שג","bp":"פאס","dt":"תיג","dp":"ירושלים","b":"תלמיד ר יוסף אלמושנינו? מחכמי פאס בזמן ר סעדיה ן רבוח, חתם בשנים-שמד-שנא. עלה לירושלים-תיג בשנת פטירתו בגיל 110 שנים, היה חברו של ר אברהם בן חיים בעל \"קרבן אהרן\" על הספרא. אולי בניו - ר יוסף ור יהודה (שנפטרו בחייו). לפי נר המערב יתכן והיו 2 חכמים באותו השם."},{"i":732,"n":"אברהם הכהן כ\"ץ מאויבן","b":"רב באויבן-ק\"צ"},{"i":733,"n":"אברהם הכהן כ\"ץ מבטושאן","f":"ברוך מקאסוב","dt":"תקעב - ג תשרי","b":"מגיד בבטושאן"},{"i":734,"n":"אברהם הכהן כ\"ץ מטורלא","f":"יעקב קופל מלבוב","b":"חתן ר נחמיה הכהן מחנטשין. רב בטורלא(=טארלי)-שנת ת'. גיסו - ר זאב וולף כץ מלבוב."},{"i":735,"n":"אברהם הכהן מאוסטרהא","f":"משה הקדוש","dt":"תקד - כו סיון","dp":"אוסטרהא","b":"מגדולי אוסטרהא. (אולי הוא אביה של מרת שרה נכדת המהרש\"א). אחיו - ר משה."},{"i":736,"n":"אברהם הכהן מאזמיר - ב","dt":"תקמז - ו טבת","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":737,"n":"אברהם הכהן מאזמיר ואמאציה","bp":"אזמיר?","b":"מחכמי אמאציאה-תורכיה-תכג, אזמיר-תכה, מגנישיאה-תכז. אולי אחיו של ר שלמה הכהן מאזמיר."},{"i":738,"n":"אברהם הכהן מאזמיר וכיאו","f":"יצחק","b":"רב באזמיר-שנות ה-ש', כיאו."},{"i":739,"n":"אברהם הכהן מאישקופיה","b":"גביר מראשי קהלת אישקופיה-תן, ברח לקושטא בזמן הכיבוש האוסטרי."},{"i":740,"n":"אברהם הכהן מאלגיר","bp":"מעסכר-אורן","dt":"תקפז","dp":"צפת","b":"רב בלמעסכר(=מסכארא)-אלגיר, עלה לארץ והתישב בצפת. תשובה ממנו ב\"הון יוסף\" לר יוסף זמירו, ואולי הוא הרב א' הכהן שנזכר ב\"גושפנקא דמלכא\" לר פארוז קרסיינטי מווהראן."},{"i":741,"n":"אברהם הכהן מאלגיר","bt":"ק","dt":"קע","b":"רב במסתגאנם-אלגיר. נזכר בשו\"ת הרשב\"ש."},{"i":742,"n":"אברהם הכהן מאלגיר","dt":"תרץ - בערך","dp":"ירושלים","b":"מחכמי ארץ ישראל, בשליחות בצפון אפריקה והתישב באלגיר. רב ברוליזאן-אלגיר, ג'יריויל(=אל באייאד)-אלגיר, חזר לארץ. בקי בדקדוק. בקשרי מכתבים עם ר דוד הכהן סקלי מווהראן. נזכר ברשימת המסייעים ל\"ארץ חיים\" לר חיים סתהון - ירושלים תרסח. פיוט ממנו ב\"שבחי צדיקים\" גרבה תשח."},{"i":743,"n":"אברהם הכהן מאנקונא","dt":"שיו - יב תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":744,"n":"אברהם הכהן מארונו וקנדיא","b":"מחכמי יון-ק' וכנראה מקנדיא. חיבר פיוט ונמצא במחזור קורפו - \"כל עצמותי תאמרנה\". שירים ממנו בקובץ שירים מאוצה\"ס רומא."},{"i":745,"n":"אברהם הכהן מארץ ישראל","f":"יוסף","b":"ראש ישיבת ארץ ישראל, מכתב אליו משנת ד'תשפט ( 1029), כתב מכתב לקהלות חמת וטבריה בשנת ד'תשפז. י מאן \"הצופה לחכמת ישראל\" תרפב, מספר שגלה למצרים ונאסר על ידי בן ריבו כנראה קראי בשנת תשפד ובבית הסהר חיבר פיוט לאמרו בתוך שמונה עשרה. אחיהם של ר שמואל, ור אהרן - גאוני ארץ ישראל."},{"i":746,"n":"אברהם הכהן מארץ ישראל","f":"חגי","b":"מחכמי ארץ ישראל-ד'תשן. מכתבים ממנו בגניזה - בספר מאן."},{"i":747,"n":"אברהם הכהן מארץ ישראל","f":"עמרם","b":"חכם בזמן הגאונים-ד'תשן. הובא באוצה\"ס למס' ראש השנה."},{"i":748,"n":"אברהם הכהן מארץ ישראל","b":"פייטן מחכמי ארץ ישראל וחיבר פיוט לאמרו בתוך תפילת שמונה עשרה את הפיוט חיבר בזמן שישב בבית הסוהר בגלל מלשינות של קראי-ד'תתכב."},{"i":749,"n":"אברהם הכהן מאשכנז","f":"מאיר בן אברהם","b":"נינו של ר יהודה ליאונטין. מחכמי לותיר-ד'תת-תתן בזמן רש\"י, ותשובה מרש\"י אליו בספר הפרדס. תשובה ממנו עם חברו ר קלונימוס הזקן בן יצחק. שאלה ממנו לר יעבץ הלוי ונזכר ב\"תולדות אדם\" לרשב\"א. קינה ממנו במחזורים \"אשאג מנהמת לבי\". בנו ר אלעזר הכהן. נכדו-בן בתו ר שמריה בן מרדכי משפירא."},{"i":750,"n":"אברהם הכהן מבולוניא","f":"משה","b":"רב בבולוניא-רן בזמן ר יחיאל טרבוט ופציגטון ור בנידיט. תשובה ממנו בקובץ פסקי גאוני איטליה משנת רע\"ח. ותשובה ממנו אל ר אברהם מינץ - ומזהירו להזהר בכבוד חבריו (היה מחלוקת כנגד ר אברהם מינץ על שפגע בכבוד ר משה נויירא ור\"י מרגליות). חיבר ביאור על פירש\"י לתורה. מופיע ב\"אוצרות הספרים\" לר חיים מיכל. הו\"ל ספר חסידים - בולוניא רצח."},{"i":751,"n":"אברהם הכהן מברסלוי","k":"בעל כללות או\"ה","b":"רב בהאלי,ברסלוי-רצ\"ה"},{"i":752,"n":"אברהם הכהן מג'רבה","k":"בעל וישב אברהם","dt":"תרלד - כט אייר","dp":"ג'רבא","b":"מקובל, מרביץ תורה, רב בג'רבא, ובנו ר דוד על מקומו אחריו. חיבר גם \"שיר חדש\", \"קן צפור\".","bk":[["וישב אברהם",""]]},{"i":753,"n":"אברהם הכהן מהאלי","f":"אליהו","b":"תלמיד המהרי\"ל. רב בערפורט, האלי. נזכר ב\"דרכי משה\" - בשם מהר\"א כץ מארפורט. ונזכר בתה\"ד שהיה ביום הנועד בארפורט יחד עם ר ליפמן מילהויזן, ר נתן איגרא, ר חזקיה וישליניז ועוד. נזכר בשו\"ת מהר\"י וייל. תשובה ממנו לקהל הלברשטט בדין ניקור."},{"i":754,"n":"אברהם הכהן מוידין","b":"דיין בוידין-תקפג עם ר שם טוב בן ציון ור יוסף בן אברהם."},{"i":755,"n":"אברהם הכהן מוישניזי","f":"מאיר","dt":"סד - ז ניסן","b":"חתן ר אליקים בן שמעון. מחכמי אשכנז בעיר וישניזי(=וייס עבענדע). נהרג עק\"ה עם חותנו. קינה לזכרו מאת ר שלמה בן יוסף - במחזור - כת\"י."},{"i":756,"n":"אברהם הכהן מזולקוא או לבוב","b":"חתם-שפד בפנקס על תקנות קהלת זולקווא שנתקיימה על ידי מנהיגי לבוב."},{"i":757,"n":"אברהם הכהן מזנטי ופדובה","f":"שבתי","k":"בעל כהונת אברהם","b":"הגיע מקנדיא ללמוד רפואה בפדובה. רב ומשורר בפדובה. חיבר \"כהונת אברהם\" עם הסכמות גדולי איטליה וביניהם ר יצחק חיים כהן צדק מהחזנים."},{"i":758,"n":"אברהם הכהן מחיפה","dt":"תרסג - ד תשרי","dp":"חיפה","b":"אב\"ד ור\"מ בחיפה"},{"i":759,"n":"אברהם הכהן מטורלא וזאמושט","f":"יצחק מזאמושט","k":"בעל בית אברהם","b":"חתן ר העשיל מקראקא. רב בטרלי(=טורלא), זאמושץ-תק, לובלין (כמה חודשים), ונאמן דד\"א-תקח. תמך בר יעקב עמדן במחלוקתו עם ר יונתן איבשיץ. לחם בשבתאים. נזכר ב\"עטרת צבי\" לר הירש הלברשטט, ובשו\"ת ר חיים הכהן מלבוב. חיבר גם \"משפט שלום\". בנו ר יהושע השל מלודמיר קיבל הצעה לרבנות לובלין על מקומו אך לא הסתייע. גיסו של ר שלמה מלבוב והסכים על ספרו - \"מרכבת המשנה\" פפד\"א תקיא, הסכים גם על שו\"ת רבנו חיים הכהן רפפורט מלבוב, ועוד. בנו גם - בנו - ר צבי הירש מלבוב וטורלא."},{"i":760,"n":"אברהם הכהן מטריפולי","b":"מחכמי טריפולי, הגהות ממנו על ספר הזכרון שנדפס בליוורנו תרה."},{"i":761,"n":"אברהם הכהן מירושלים","b":"גביר מחכמי ירושלים-שנז. נזכר ב\"כתר תורה\" בענין פטור ממס."},{"i":762,"n":"אברהם הכהן מירושלים","dt":"תרטו - ט-יז שבט","dp":"ירושלים","b":"מרבני ירושלים"},{"i":763,"n":"אברהם הכהן מירושלים","dt":"תשכג - אדר","dp":"תל אביב","b":"מקובל בירושלים"},{"i":764,"n":"אברהם הכהן מירושלים","f":"דוד","b":"דיין בביה\"ד חסידים בירושלים-תרעב."},{"i":765,"n":"אברהם הכהן מירושלים","b":"מחכמי ירושלים-שנות ה-תק'. דודו של בעל \"שמן רוקח\" בירושלים, אולי אחיו של זקנו(-אבי אמו) ר שמואל כץ מירושלים. נזכר ב\"סמא דחיי\" וארשא תקנז."},{"i":766,"n":"אברהם הכהן מירושלים","b":"נזכר בשטר חוב לכולל עדת המערבים-תרכג."},{"i":767,"n":"אברהם הכהן מלבוב","dt":"תרח","b":"דרשן ואב\"ד בלבוב. לתולדותיו ב\"תולדות ר אברהם הכהן\" לר אברהם צבי צופניצק מדרוהוביטש - תרכט."},{"i":768,"n":"אברהם הכהן מלמברג","f":"יוסף (או שלמה)","k":"ר' אברהם הקדוש","dt":"תכד - ח אייר","dp":"לבוב","b":"דיין ור\"מ בלבוב(=למברג). נהרג עק\"ה, יחד עם אביו ר שלמה בן שמואל."},{"i":769,"n":"אברהם הכהן ממכנאס - א","f":"חיים","b":"מחכמי מכנאס-שנות ה-ש' בערך."},{"i":770,"n":"אברהם הכהן ממכנאס - ב","f":"חיים","b":"מחכמי מכנאס-ת' בערך."},{"i":771,"n":"אברהם הכהן ממצרים","b":"ראש קהילת פוסטט-מצרים-ד'תת. מכתב מר שלמה בן יהודה אליו נמצא בגניזה."},{"i":772,"n":"אברהם הכהן ממצרים","b":"מחכמי מצרים, רב באלכסנדריה, תלמיד הרמב\"ם ונזכר באגרת ר שמואל ן תבון לרמב\"ם. היה מחלוקת בינו לר פנחס בן משלם הדיין מאלכסנדריה שהתלונן עליו בפני הרמב\"ם ונזכר בתשובות הרמב\"ם."},{"i":773,"n":"אברהם הכהן ממרוקו","f":"יהודה","k":"מארי מתניתין","b":"מחכמי מרוקו."},{"i":774,"n":"אברהם הכהן מסופיה","f":"עקיבא","b":"מראשי קהלת האשכנזים בסופיה - בדור שלאחר הגירוש."},{"i":775,"n":"אברהם הכהן מסטנוב","b":"רב בסטאנוב-תק\"ע"},{"i":776,"n":"אברהם הכהן מסמאקוף","b":"מו\"ץ בסמאקוף, סייע לרחל יהודה אריה-בתו של ר משה יצחק הלוי מסופיה להדפיס את ספר אביה \"מעשה נסים\" - פרשבורג תרלד."},{"i":777,"n":"אברהם הכהן מספרד ואיטליה","f":"משה","b":"פוסק, רב בקואינקה(ספרד), בגירוש הגיע לאיטליה-רנ\"ב, רב בבולניה-רס\"ד"},{"i":778,"n":"אברהם הכהן מפאס","f":"אברהם הכהן הרופא מפא","b":"תלמיד ר יוסף אלמושנינו? מחכמי פאס בזמן ר סעדיה ן רבוח, חתם בשנים-שמד-שנא."},{"i":779,"n":"אברהם הכהן מפאס","dt":"תרנו","dp":"פאס","b":"מחכמי פאס"},{"i":780,"n":"אברהם הכהן מפאס","b":"רב בפאס-ש\"ד"},{"i":781,"n":"אברהם הכהן מפטרץ","b":"סופר הקהל בפטרץ-תק."},{"i":782,"n":"אברהם הכהן מצאנטי","f":"שבתי","k":"בעל כבוד חכמים","bt":"תל","dt":"תפט","b":"הגיע מהאי צאנטי-איטליה, מחכמי פדובה, חזר לצאנטי. משורר, רופא, חיבר \"כבוד חכמים\", \"כהונת אברהם\", \"בני קטורה\", ועוד."},{"i":783,"n":"אברהם הכהן מצפת","b":"בשנת תעג חתום על מכתב קהילת צפת לר יצחק למפרונטי אודות השליח ר שמואל בן עובדיה הלוי, ובשנת תצו על מכתב בקשת עזרה"},{"i":784,"n":"אברהם הכהן מצרפת","f":"יהודה ליאונטין בן מא","b":"מחכמי צרפת-ד'תש. חיבר פיוטים ונכנסו למחזור אשכנז, ובהם \"אלקים ביתה תושיב יחידים\". בנו - ר מאיר הכהן ונכדו ר אברהם הכהן."},{"i":785,"n":"אברהם הכהן מצרפת","f":"חיים","b":"חותנו של ר שמואל מפלישא בעל פירושי \"א' אלקים ברוחות\" שנזכר באור זרוע - והביא מחותנו בספרו."},{"i":786,"n":"אברהם הכהן מצרפת - ב","f":"יהודה","k":"בעל ספר דינים","b":"פייטן. קרובו של ר אברהם הכהן בן יהודה הראשון (שחיבר פיוטים גם כן)."},{"i":787,"n":"אברהם הכהן מקאליסק","f":"אלכסנדר הכהן","k":"בעל חסד לאברהם","bt":"תקא","bp":"קליסק","dt":"תקע - ד שבט","dp":"טבריה","b":"תלמיד המגיד ממזריטש. בזיוו\"ש חתן ר משה סגל מהורוקי (אלמנת החסיד ר זלמן מוילנא). עלה תקלז היה מראשי חבורת העולים החסידים, עם ר מנחם מנדל מויטבסק, ועמד בראש העדה בטבריה אחריו-תקמח. היה מתלמידי הגרא שהתקרב לחסידות, והפך לתלמיד המגיד ממזריטש, והנהיג עדה בחייו המגיד. בשנת תקלח חתם על מכתב עם ר מנחם מנדל מויטבסק בדבר הרגעת הרוחות במחלוקת החסידות. דברי תורתו הובאו בספר \"חסד לאברהם\" צרנוביץ תריא. מכתבים ממנו בסוף ספר \"פרי הארץ\" לר מנחם מנדל מויטבסק. בנו ר אלכסנדר נזכר בתקמו. ונזכרו גם נכדו ישאל אלעזר ונכדה מבנו - ולא ידוע עליהם דבר. נכדו - ר דב זוסמן אלתר לוין."},{"i":788,"n":"אברהם הכהן מקאשטוריאה","b":"דיין בקאשטוריאה-שנות ה-תק' אצל ר אברהם גראסיאני."},{"i":789,"n":"אברהם הכהן מקושטא ומצרים","bp":"שלוניקי","b":"רב בקושטא-שנח (או שלוניקי), אלכסנדריה, קהיר-שסה."},{"i":790,"n":"אברהם הכהן מקרוצא","b":"רב בקרוצא"},{"i":791,"n":"אברהם הכהן מרמלה","f":"יצחק","b":"ממנהיגי קהילת רמלה ובעל תואר שיך. מכתב אליו מר אברהם בן שמואל בן הושענא אודות איש אחד שהחריב ביכ\"נ ברמלה ומבקש מר אברהם שיקרא אותו ויוכיחו."},{"i":792,"n":"אברהם הכהן מרשיד-מצרים","f":"יוסף ממצרים","b":"גביר ברשיד-שנות ה-ת', חוכר המכס אצל יצחק נבארו שר האוצר על מקום אביו."},{"i":793,"n":"אברהם הכהן משאד וירושלים","f":"יעקב","dt":"תרכג-ו -יח אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":794,"n":"אברהם הכהן משלוניקי","dt":"שנג - ג חשון","dp":"שלוניקי","b":"מחכמי טורקיה. רב בשורין-מקדוניה-שן, שלוניקי."},{"i":795,"n":"אברהם הכהן משלוניקי","f":"נחמן","k":"בעל טהרת המים","bt":"תקמ","dt":"תרמו - ב כסלו","dp":"שלוניקי","b":"רב בשלוניקי, יסד ישיבת \"בית אברהם לחיים\", חיבר גם \"בית אברהם לחיים\", ועוד."},{"i":796,"n":"אברהם הכהן משלוניקי","f":"שלמה - מהרש\"ך","dt":"ת - ז ניסן","dp":"שלוניקי","b":"תלמיד ר דניאל אישטרושא. מחכמי שלוניקי, רב בטיריא יחד עם אחיו."},{"i":797,"n":"אברהם הכהן משלוניקי","dt":"תקצז","dp":"שלוניקי","b":"רב בשלוניקי. נפטר במגיפה."},{"i":798,"n":"אברהם הכהן משלוניקי","dt":"תכג - ח אדר","dp":"שלוניקי","b":"גביר מחכמי שלוניקי"},{"i":799,"n":"אברהם הכהן מתונס","f":"דוד","k":"בעל אברהם יגל","dt":"תר","dp":"צפת","b":"היה אב\"ד תונס-תקמו, חיבר \"אברהם יגל\" ליוורנו תרג, עם הסכמה מר שלמה סוזין מצפת תקצו."},{"i":800,"n":"אברהם הכהן מתונס - א","dt":"תעה","b":"מגדולי דייני תונס"},{"i":801,"n":"אברהם הכהן מתונס - ב","b":"רב בתונס-תרמ\"א"},{"i":802,"n":"אברהם הכהן מתימן","f":"יוסף","b":"מחכמי שבאם-תימן, סופר, העתיק בכת\"י פירוש רש\"י וליקוטים נוספים לתורה-תקד. מביא מפירושי זקנו - ר אברהם בן עודד."},{"i":803,"n":"אברהם הלוי אלפצינא מגיברלטר","b":"מחכמי גיברלטר."},{"i":804,"n":"אברהם הלוי אלצדיק מגרנדה","f":"דוד","k":"בעל קיצור ספר יוחסין","b":"מחכמי גרנדה. חיבר קיצור ספר יוחסין ונזכר בפירוש ר\"י משקוני על האבן עזרא. נזכר ברד\"ק."},{"i":805,"n":"אברהם הלוי בברדזיב וירושלים","b":"רב בברדזיב,עלה לירושלים"},{"i":806,"n":"אברהם הלוי מאליק","f":"יהושע הלוי","b":"רב באליק-ת\"ו"},{"i":807,"n":"אברהם הלוי מאלכסנדרי-ווהלין","b":"רב באלכסנדרי-וואהלין"},{"i":808,"n":"אברהם הלוי מאמלוק ולודז","b":"ר\"מ בישיבת \"בית אברהם\" בלודז. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":809,"n":"אברהם הלוי מאפיון וטוקאט","b":"רב באפיון(=קארה-היסאר) וטוקאט-שנות ה-ש'."},{"i":810,"n":"אברהם הלוי מאשכנז","f":"אליעזר","b":"תלמיד מהר\"ם מרוטנבורג ונזכר בתשובותיו. מחכמי אשכנז-ן'. שאלה ממנו בתשובות הרא\"ש."},{"i":811,"n":"אברהם הלוי מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":812,"n":"אברהם הלוי מגירונא","f":"יצחק","dt":"קנד - חשון","b":"משורר ופילוסוף מחכמי גרונה-ספרד, ברח מהפרעות בספרד-קנא, עבר לפרובנס, מצרים וא\"י, אך חזר לספרד. חיבר פירוש לשיר השירים. אחיו של דון אשטרוק יצחק הלוי. קינה לזכרו מבעל האפודי."},{"i":813,"n":"אברהם הלוי מוידין","f":"אלצפן מוידין","b":"מחברי החברא קדישא בוידין-תקלג, עם הרופא חיים דוד בן גבריאל."},{"i":814,"n":"אברהם הלוי מוינה","f":"מרדכי מאדל הלוי","b":"מגדולי וינה"},{"i":815,"n":"אברהם הלוי מוינה","dt":"שלב","b":"רב בוינה. ממנו משפחות מיוחסות באשכנז ובהם: מירלה, הלר, ולרשטין."},{"i":816,"n":"אברהם הלוי מחעלם ועמדין","f":"משה","k":"ר' אברהם מחעלם","b":"אב\"ד הילדסהיים-תקמ, עמדין על מקום ר שאול הלוי מהאג ור אריה ליב ברסלא בעל \"פני אריה\" על מקומו אחריו. חיבר הגהות ל\"גנת אגוז\" לר יוסף גיקטיליא. הסכים על שו\"ת הרדב\"ז, \"פרדס דוד\" - זולצבך תקמז. נזכר ב\"נודע ביהודה\"."},{"i":817,"n":"אברהם הלוי מירושלים","dt":"תקסא","b":"מחכמי ירושלים, בשליחות הקהלה. נספד ב\"בן אברהם\"."},{"i":818,"n":"אברהם הלוי מירושלים","f":"חייא","b":"בשנים שפג - שפה, חתם על תקנה נגד הפירוד ועל תקנה לשחרור תלמידי חכמים."},{"i":819,"n":"אברהם הלוי מירושלים","f":"אליעזר","b":"בשנת רטז יצא בשליחות ירושלים"},{"i":820,"n":"אברהם הלוי מירושלים","dt":"תקף - ה אייר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":821,"n":"אברהם הלוי מלובלין","b":"מחכמי לובלין. גבאי בח\"ק-תנו וחתם בפנקס הח\"ק."},{"i":822,"n":"אברהם הלוי מלוקטש","f":"יצחק הלוי","k":"בעל ספר החכמה","b":"תלמיד ר יונתן איבשיץ. רב בלאקטש-תקל. חיבר \"חוסן ישועה\", ועוד."},{"i":823,"n":"אברהם הלוי מלנצהוט","b":"רב בלאנצוט"},{"i":824,"n":"אברהם הלוי ממצרים","f":"מרדכי - דרכי נועם","k":"בעל גינת ורדים","bt":"ת-תטו","bp":"מצרים","dt":"תע-ב","b":"עשיר, פוסק, דיין במצרים אצל ר דוד גרשון, אב\"ד על מקום אביו בעל דרכי נועם. השיב לרבנים ממקומות שונים ובהם שלוניקי, ירושלים, ועוד. חתנו - הרופא ר חיים בן משה טאויל שירש את רכושו ואת כתביו."},{"i":825,"n":"אברהם הלוי ממצרים","f":"מרדכי","bt":"תי","bp":"מצרים","dt":"תסד","dp":"מצרים","b":"רב במצרים"},{"i":826,"n":"אברהם הלוי ממראקש","b":"מחכמי מראקש-מרוקו-תצב, וחתם ב\"תקפו של יוסף\"."},{"i":827,"n":"אברהם הלוי ממרוקו","b":"מחכמי מרוקו-ת'. (אינו החכם המוזכר ב\"תקפו של יוסף\")."},{"i":828,"n":"אברהם הלוי מסופיה","f":"משה יצחק מסופיה","b":"רב בסופיה-תקץ, אחיו - ר יצחק - רבה של סופיה."},{"i":829,"n":"אברהם הלוי מסינאווא","b":"תלמיד ר אברהם יהושע השל מאפטא. אב\"ד סינאווא-ליד מזבוז."},{"i":830,"n":"אברהם הלוי מספרד","k":"בעל מסורת החכמה","b":"מקובל בספרד בתקופת הגירוש-ר\"נ."},{"i":831,"n":"אברהם הלוי מספרד","f":"דוד הלוי","k":"הראב\"ד בעל הקבלה","bt":"ד'תתע","bp":"קורדובה","dt":"תתקמ-ס","dp":"טולדו","b":"נכד-בן בתו ר יצחק בן ברוך ן אלביליה. תלמיד דודו ר ברוך ן אלביליה. מגדולי חכמי ספרד, בקי במדעים, רופא, היסטוריון, פילוסוף, חיבר \"ספר סדר הקבלה\", \"אלעקידה אלרפיעה\"(=אמונה נשאה או אמונה רמה), נהרג עק\"ה ע\"י מלך ספרד כשלא הסכים להמיר דתו. כונה בשם ר אברהם די אודי."},{"i":832,"n":"אברהם הלוי מספרד וצפת","f":"אליעזר","k":"בעל משרא קטרין","bt":"רכ","bp":"ספרד","dt":"רפח-רץ","dp":"ירושלים","b":"אחיו של ר שלמה הלוי. תלמיד ר יצחק גאקון בקבלה. מקובל ומחשב קיצין, מחכמי ספרד, גיסו של ר אברהם זכות בעל ספר יוחסין. אחר גירוש ספרד נדד באירופה טורקיה, מצרים והיה מקורב לנגיד ר יצחק שולאל שתמך בו, וקושטא, עלה לצפת, עבר לירושלים-רעה. תלמיד הרמ\"ק. חיבר \"משרי קטרין\" על דניאל - קושטא, ועוד. מתורתו בספר \"תקוני שבת\" למהר\"י פוייטו. חיבר פירוש על \"נבואת הילד\" בשם \"משרא קטרין\" קושטא תפו ובו יצא כנגד אחד החכמים שחישב את זמן הגאולה-רעב, וחישב בעצמו את זמן הגאולה-רץ וכשעבר הזמן נגרמה אכזבה גדולה - וכנגדו יצא ר נחום בן זכריה אלקושי מרומיני. \"מסורת החכמה\" (שמקצתו נדפס בחוברת של ג שלום - ירושלים תרפה). ועוד. לדעת אור החיים ותג\"י זהה רבי אברהם עם ר אברהם ברוכים."},{"i":833,"n":"אברהם הלוי מסרייבו","f":"משה","dt":"תרלא - ח אלול","dp":"ירושלים","b":"רב בסרייבו, עלה לירושלים וחתם בשנת תרל על מעשה בית דין."},{"i":834,"n":"אברהם הלוי מעמדין (שור)-ראבי\"ה","f":"יעקב בן מאיר שור","k":"בעל מרכבת המשנה","dt":"תקיח - ו כסלו","dp":"עמדין","b":"חתן ר מאיר גינצבורג. רב בעמדן. בניו - ר יצחק איזיק מוילנא, ר יעקב מאניקשט. (האם התערבבו כאן שני רבנים? - מופיע גם כבנו של ר יעקב בן אליהו)"},{"i":835,"n":"אברהם הלוי מקושטא","b":"רב בקושטא-ש\"פ"},{"i":836,"n":"אברהם הלוי מקושטא","dt":"תקצז (ולא תקעז?","b":"אב\"ד בקושטא-תקעו-פ, בלאט, חכם באשי ראשון בקושטא-תקצה-תקצז (ולפי רוזניס - בשנת תקעו? - ולא תקפו כמופיע ב\"משנת ר אליעזר\"). בנו - ר חזקיה אברהם הלוי."},{"i":837,"n":"אברהם הלוי מקושטא","k":"בעל נבואת הילד","b":"מחכמי קושטא, חיבר(?) \"נבואת הילד\" - קושטא תצח."},{"i":838,"n":"אברהם הלוי מקרוז","dt":"תקצט","b":"רב בקרוז'. חברו של ר עקיבא איגר מפוזנא. בנו - ר חיים מקובנא."},{"i":839,"n":"אברהם הלוי מרודוס","b":"רב ברודוס-תקמג בערך על מקום ר משה ישראל בעל \"משה ידבר\"."},{"i":840,"n":"אברהם הלוי מרוזניאטוב","f":"[פנחס]","b":"אב\"ד רוזניאטוב-תרנב."},{"i":841,"n":"אברהם הלוי מרישא","b":"פרנס דד\"א,רב רישא-ת\"כ"},{"i":842,"n":"אברהם הלוי משלוניקי","f":"חסדאי","b":"מחכמי שלוניקי-שמב. תרגם מערבית \"בן המלך והנזיר\" - מנטובה."},{"i":843,"n":"אברהם הלוי משלוניקי","dt":"תג - כח תמוז","dp":"שלוניקי","b":"מרבני שלוניקי. אולי נכדו ר אברהם בעל \"עין משפט\"."},{"i":844,"n":"אברהם הלוי משלוניקי","f":"יצחק - באר מים חיים","dt":"תקמב","dp":"שלוניקי","b":"דיין בשלוניקי. בנו - ר מיכאל משלוניקי."},{"i":845,"n":"אברהם הלוי משלוניקי","f":"יוסף","k":"בעל עין משפט","dt":"שעח-ט","b":"תלמיד ר דוד נחמיאש, ר שבתי יונה. מחכמי שלוניקי. נפטר צעיר. חיבר שו\"ת \"עין משפט\" ונדפס ע\"י ר דוד פיפאנו - שלוניקי תרנז - עם הקדמה ותולדות המחבר, חיבר גם הלכות מתנה ומחילה - בכת\"י."},{"i":846,"n":"אברהם הלוי משלוניקי","dt":"תקל","b":"מחכמי שלוניקי."},{"i":847,"n":"אברהם הלוי משלוניקי","dt":"תקע","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":848,"n":"אברהם הלוי מתימן","f":"זכריה","b":"רב בג'יבלה-תימן-ש'. חיבר שו\"ת בכת\"י."},{"i":849,"n":"אברהם המגיד מפשיסחא","bt":"תקסו","b":"מראשוני החסידים בפולין. מגיד בפשיחסא-תקכא. קירב את המגיד מקוזניץ לחסידות."},{"i":850,"n":"אברהם המלאך מפסטוב וחווסטוב","f":"דב בער-המגיד ממזריטש","k":"בעל חסד לאברהם","bt":"תקא","dt":"תקלח - יב תשרי","dp":"חווסטוב (=פאסטוב)","b":"חתן ר פיבוש מקרמניץ בעל \"משנת חכמים\". התבודד בפסטוב ליד קיוב. נקרא ר אברהם המלאך. מבניו ר שלום שכנא-אביו של ר ישראל מרוזין, ור ישראל חיים מלודמיר."},{"i":851,"n":"אברהם ה\"ן דוד ויוסף ידיע דויכו","b":"סופר שטרות מחכמי פאס-תקנג, חתם-תרא. חיבר ספר רפואות בכת\"י. חיבר שיר לכבוד ר שלמה ן צור."},{"i":852,"n":"אברהם הנגיד - נין הרמב\"ם","f":"דוד הנגיד","k":"אברהם הנגיד","bt":"ו-ח","dt":"עג-פ","b":"נינו של הרמב\"ם. רב ונגיד במצרים על מקום אביו יחד עם אחיו ר שלמה. נזכר ב\"מעשה נסים\" על מכתב ניחומים שקבלו על פטירת אביהם, ואצל ר יוסף כספי בפירושו למורה נבוכים, ואצל ר יוסף יעבץ שמביא את ר אברהם שגייר קראים וחושב זאת על ר אברהם בן הרמב\"ם ובאמת הוא ר אברהם נינו של הרמב\"ם. בניו: ר יהושע נגיד על מקומו אחריו, ר עובדיה, ר משה. נכדו - ר דוד הנגיד בדמשק שבניו נשבו ואבדו במלחמת הטטרים. ייהד קראים רבים במצרים."},{"i":853,"n":"אברהם הנזיר מפרובנס","b":"מחכמי פרובנס בזמן הרמב\"ן. נתפרסמה אגרת מתלמידו בשמו ב\"מאסף סופרי א\"י\" - תש."},{"i":854,"n":"אברהם הנשיא מספרד","f":"חייא","k":"בעל צורת הארץ","bt":"ד'תתל","b":"מכונה \"חבא אל שירטה\". תלמיד ר משה הדרשן מנרבונא, ר אברהם בן שלמה. מגדולי חכמי ספרד-ד'תתץ, רב בשוריא, ברצלונה, פרובנס. מרבותיו של ר אברהם אבן עזרא. חיבר גם ספר העיבור, ועוד."},{"i":855,"n":"אברהם הסופר מירושלים","f":"אורי שבתי","k":"אברהם רבי שבתי'לס","b":"נכד(-אבי אמו) ר יוסף זונדל סלנט. מחכמי ירושלים-תרמב."},{"i":856,"n":"אברהם הספרדי","b":"מכתב אליו מר דוד בן משה בונפונטו שהיה כנראה תלמידו."},{"i":857,"n":"אברהם הספרדי מאלגיר","f":"נתן","b":"מחכמי ספרד, בגזירות-קנא עבר לאלגיר והתישב במיסתגנים, דיין במסתגאנם, והורה גם ליושבי מטמאטה-אלגיר הסמוכה (ישוב באותו השם קיים גם בתונס), והיה בקשר עם הריב\"ש, ונזכר אצל הרשב\"ש. מתלמידיו ר שמואל חכים - שלמד אצלו את קדוש החדש, ר שמואל בן דוד חלאיו - שלמד ממנו דקדוק. החליף מכתבים עם הרשב\"ץ."},{"i":858,"n":"אברהם הספרדי מונציה","b":"רב בונציה בזמן הרמ\"ף ור יחיאל טרבוט. הסכמה ממנו ב\"פחד יצחק\" אודות חליצה."},{"i":859,"n":"אברהם העזרוני","b":"מחכמי טבריה, חתום בשנת תר על כתב שליחות ר חיים שמואל הכהן."},{"i":860,"n":"אברהם הפייטן","f":"מנחם","b":"פייטן-ד'תתק. חיבר פיוט לעשרה בטבת \"אבן הראשה\"."},{"i":861,"n":"אברהם הפייטן","f":"לוי","b":"פייטן-שנות ה-ק'. חיבר פיוט לר\"ה על מלכויות זכרונות ושופרות."},{"i":862,"n":"אברהם הפייטן","f":"שמואל","b":"פייטן קדום, חיבר פיוט \"אל מי מגואלי\" הנמצא במחזור ספרד, וכמה פיוטים במחזור אויניון."},{"i":863,"n":"אברהם הפייטן","f":"נתן נשיא","b":"חיבר תחינה \"ה' ארכו שני בגלות\"."},{"i":864,"n":"אברהם הפייטן","f":"סיסא","b":"פייטן-שנות ה-ק'. חיבר פיוט לשבת תשובה."},{"i":865,"n":"אברהם הפרוש החסיד אל קונסטנטינ","b":"עלה מקושטא והיה מאבלי ציון, מוזכר בספרו של בנימין מטודלה משנת ד'תתקכה (1165), ר פתחיה מרגנשבורג מספר בשנת תתמ על ר אברהם הצבע בירושלים שנותן מס למלך שמינהו שם ואולי הוא ר אברהם הנל"},{"i":866,"n":"אברהם הצרפתי","k":"בעל תמיד השחר","b":"מחכמי צרפת-פא. חיבר \"תמיד השחר\" שהועתק ע\"י ר אברהם מקינון-מבעלי התוספות."},{"i":867,"n":"אברהם הקונטי מאיטליה","f":"יצחק","b":"מחכמי צרפת ואיטליה-שן, היה מעורב במחלוקת חכמי איטליה עם ר יהודה די ליאון וחתם עם ר\"י דלטאש ועוד מחכמי איטליה."},{"i":868,"n":"אברהם הקראי","f":"יהודה","k":"בעל יסוד מקרא","b":"מחכמי הקראים-רפו, נזכר אצל ה\"ר ישר. חיבר תפילות ופיוטים וחלקם בסידור הקראים."},{"i":869,"n":"אברהם הרופא","b":"לאחר שנגזר על היהודים בבדרש שלא יעסקו ברפואה-ה'א, וכשחלה הנסיך אלפונסו אחיו של המלך לודויג התשיעי מצרפת פנו לרופא היהודי אברהם שיטפל בו וסירב כי היא אסור לו בגלל החוק ואז השתדלו האדונים מלוניל לבטל הגזירה."},{"i":870,"n":"אברהם הרופא","f":"יהודה","b":"חיבר ספר רפואה על מחלות השתן."},{"i":871,"n":"אברהם הרופא","f":"שלמה כונת","b":"רב וסוחר ומדפיס. הדפיס טור או\"ח-רלו בעזרת אשתו אישטילונה. הדפיס גם \"בחינת עולם\" בעזרת ר יעקב הלוי מטרשקן, \"נופת צופים\", ועוד."},{"i":872,"n":"אברהם הרופא מרמלה","f":"משה","b":"ראש בית הדין ברמלה בשנת ד תתכה (1065), תעודה חתומה מבית דינו פורסמה ע\"י מ אסף."},{"i":873,"n":"אברהם זאב הלוי ממריאמפול","k":"בעל שיחות של סבא","bt":"תרמו","dt":"תשא","b":"רב במריאמפול,זידיק"},{"i":874,"n":"אברהם זבאריזר מזולזקווא","f":"דוד","b":"מגיד מישרים בזאמושט."},{"i":875,"n":"אברהם זוטרא ממונסטיר","k":"בעל מלחמות ה'","bt":"תקמד","bp":"ברוק-בואריה","dt":"תרל - ח חשון","b":"תלמיד ישיבות פיורדא ופרג. רב בדורטמונד וגליל מינסטר, לימבורג ורהעדלר, גליל פאדעבארן(=פדברן) תביץ(=תוויץ). חיבר פירוש לתורת כהנים ונזכר אצל הרא\"ם. פרסם מאמרים ב\"אוצר חכמה\" - לבוב תרך, \"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":876,"n":"אברהם זכ\"ש מאיטליה קאסטלץ","b":"ממשפחת קסטלאץ באיטליה. נשא ונתן עם המהרי\"ק ונזכר בשו\"ת המהרי\"ק. חתנו - ר יעקב לנדא בעל ה\"אגור\", ובנו הצייר ר משה מקטלאצו, ובנו ר יחיאל ונכדו ר שמעון קסטלאץ רב במצרים."},{"i":877,"n":"אברהם חיים בן גדליה מזלוצ’וב","bt":"1750","dt":"ה'תקעו 1816","bk":[["אורח לחיים",""],["פרי חיים",""]]},{"i":878,"n":"אברהם חיים הכהן מירושלים וחברו","f":"שמואל פיבוש כץ","k":"בעל ארץ החיים","dp":"חברון","b":"נכד בעל הסמ\"ע, עמד לעלות בשיירת ר יהודה החסיד אך התעכב בונציה, בשנת תקח יצא שנית לדרכו ועלה לירושלים עם בנו ר אברהם בנימין. חיבר ספר \"ארץ החיים\" קושטא תקי. בשנת תקיח חתום בחברון על ספרו של ר אברהם זאבי \"אורים גדולים\", בשנת תקכד ראש רבני חברון."},{"i":879,"n":"אברהם חיים מאזמיר","f":"דוד","b":"מחכמי איזמיר"},{"i":880,"n":"אברהם חיים מבגדד","f":"רחמים","bt":"תרמד","bp":"בגדאד","dt":"תשיד-ב תמוז","b":"מקובל, הרביץ תורה בבגדאד, עלה לירושלים"},{"i":881,"n":"אברהם חיים מהאלמין","dt":"תרנב - יז ניסן","b":"דומ\"צ בהאלמין"},{"i":882,"n":"אברהם חיים מזלוטשוב","f":"גדליה מזולקוא","k":"אדמור מזלוטשוב-אורח","r":"אב\"ד זלאטשוב","bt":"תפה (ולא תקי)","bp":"זולקווא","dt":"תקעו - כו טבת","b":"תלמיד המגיד ממזריטש, ר שמואל שמלקא מניקלשבורג, דודו ר יוסף חאווקיס מאליק - תלמיד הבעשט, ור יחיאל מיכל מזלוטשוב, חתן ר פנחס הורביץ בעל ההפלאה, ובזיוו\"ש חתן ר ישכר בער מזלוטושוב. גיסו של רז\"ו הורביץ. רב בזבורוב, זלוטשוב-תקנג על מקום חותנו שעלה לארץ. נפטר ללא ילדים. בנו חורגו - ר יוסף עזריאל ביליג מגוליגור הו\"ל את ספרו \"אורח לחיים\" ברדיטשוב תקסו. (באוצר הרבנים תאריך פטירתו - תרח - כז טבת).","bk":[["אורח לחיים – עה\"ת",""],["פרי חיים – אבות, הגדה של פסח",""]]},{"i":883,"n":"אברהם חיים מירושלים","b":"מחכמי ישיבת \"גדולת מרדכי\" בירושלים-תקיח."},{"i":884,"n":"אברהם חיים ממיקולייב","dt":"תרלא - יח ניסן","b":"ר' אברהם חיים ממיקולייב"},{"i":885,"n":"אברהם חיים מפאס","f":"שמואל אבן חיים","b":"רב בפאס ש\"ז"},{"i":886,"n":"אברהם חנניה מבלגרד","bp":"קושטא","dt":"תכח - לפני","b":"רב בבלגרד."},{"i":887,"n":"אברהם חסאן (חסון) הסופר מספרד","b":"מחכמי ספרד לפני הגירוש. חיבר ספר בעניני סת\"ם, ונזכר בבית יוסף."},{"i":888,"n":"אברהם חריף מלונטשיץ","f":"יהודה ליב חריף","dp":"לונטשיץ","b":"חתן ר משה הכהן מבריסק ולויצק. רב בלונטשיץ-תמ. בנו - ר אלישע מהורדנא, חתנו - ר יוסף מפרמישלא. נפטר קרוב לגיל 100."},{"i":889,"n":"אברהם חריף מפיקלין","f":"צבי מגאוורע","dt":"תרלו","b":"מצאצאי ר אברהם בן שלמה מכפר סיאון-ליד ראסיין. רב בפיקאלן(=פיקעלין)-ליטא-תרך. מתלמידיו - ר אריה ליב פרומקין."},{"i":890,"n":"אברהם טאויל (הארוך)","f":"יצחק","b":"פייטן - בשנת ן' ומחכמי דורו, רבים מפיוטיו נכנסו למחזורים שונים ובעיקר במחזור טריפולי, וי\"א שהוא המחבר של \"אחות קטנה\"."},{"i":891,"n":"אברהם יאריטשינער מירושלים","dt":"תעז - לפני","b":"מחכמי ירושלים, בשליחות-תעב לפולין יחד עם ר זליג. נזכר במכתב לר דוד אופנהיים."},{"i":892,"n":"אברהם יהודה אליהו ממינסק","f":"אליעזר","k":"בעל עיר חומה","b":"ר\"מ במינסק. חיבר \"עיר חומה\" על המשניות עם פירוש \"בית מושב\"."},{"i":893,"n":"אברהם יהודה ליב מאויבן","b":"ראב\"ד באויבן-שצ\"ח"},{"i":894,"n":"אברהם יהודה ליב מברוק","k":"בעל מלאת אבן","r":"אב\"ד בראק","bt":"תקעד","dt":"תרנה-ך -יח אלול","b":"תלמיד ר משה אהרן מקוטנא, ר מנחם מנדל מקוצק - שמינהו לאב\"ד ברוק, בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר, ור יהודה אריה ליב מגור. חיבר גם \"איל מלואים\" על התורה. בנו ר ישראל יצחק על מקומו אחריו, חתנו ר חיים שלמה אב\"ד קרסנושליץ ואסטרדין. בשם הגדולים השלישי - תאריך פטירתו - תרך - בערך.","bk":[["איל מילואים – אה\"ע",""],["יד יוסף",""],["מלאת אבן - אבן העזר",""],["תלמוד למשנה - משניות",""]]},{"i":895,"n":"אברהם יהודה ליב מקושטא ואזמיר","b":"מדפיס בקושטא, אזמיר אצל ר יונה אשכנזי ור דוד חזן."},{"i":896,"n":"אברהם יהודה מאמשטרדם","dt":"תד","b":"רב לאשכנזים באמסטרדם"},{"i":897,"n":"אברהם יהודה מבאניהאד","b":"רב בבוניהאד(=באניהאד)-תק\"מ"},{"i":898,"n":"אברהם יהודה ממאזיר","b":"מו\"צ במאזיר,רב בנאראווליע"},{"i":899,"n":"אברהם יהודה משלוניקי","dt":"תעג","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":900,"n":"אברהם יהודה משלוניקי","b":"מחכמי שלוניקי. הגיה את \"לב שלמה\" לר שלמה בנימין הלוי-תקסח."},{"i":901,"n":"אברהם יהודה שלום מקושטא","b":"דיין בקושטא-תקף עם ר יעקב גוזז, ור נסים חיים ביסודו."},{"i":902,"n":"אברהם יהודיל'ס","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":903,"n":"אברהם יהושע השל מארזוה","k":"אדמור מארזוה","b":"הסכים בשם האדמור ר משה ליב מפקשן על \"בית ועד לחכמים\" - יאסי תרסט."},{"i":904,"n":"אברהם יהושע השל מברדיטשוב","f":"מרדכי","k":"אדמור מברדיטשוב","dt":"תרסט - כח שבט","b":"נכד ר שמואל מקמינקא. חתן ר אליעזר מפולנאה בן ר יעקב שמעון מזסלב (קוריץ). אדמור בברדיטשוב."},{"i":905,"n":"אברהם יהושע השל מבריסק ולובלין","f":"יעקב מלובלין בן אפרי","k":"הרבי ר השל","r":"רב ור\"מ בלובלין וקראקא","bt":"שנה","dt":"תכד - כ תשרי","dp":"קראקא","b":"נכד ר אפרים נפתלי הירש. ראש חכמי דורו, חתן הגביר ר משה ר ליזרש מבריסק. ניצל בגזרות תח. ר\"מ בלובלין-תי על מקום אביו - ופגש שם את ר שבתי בעל הש\"ך ואת בעל הט\"ז, בריסק על מקום ר שלמה זלמן בן ירמיה יעקב, ניקלשבורג-תטז ופגש שם את ר מנדל קרוכמל והיה מחלוקת ביניהם בענין עגונה מלובלין, רב בקראקא-תטו על מקום בעל \"תוספת יו\"ט\", נסע לוינה (בגזרת השמד) לבקש בעד היהודים, חזר לקראקא. (היה מיועד להיות חתן השר ר שאול וייל - שלבסוף חזר בו ובחר בר אפרים זלמן שור כחתנו - ור השל הקפיד על כך). מתלמידיו: ר אהרן שמואל קיידנובר-מהרש\"ק, ר דוד הלוי בעל הט\"ז, בעל הש\"ך, ועוד. בניו - ר שאול מבריסק על מקומו אחריו בקראקא-תנח (כיון שהיה צעיר כיהן בינתים ר יהודה אריה ליב בן זכריה כאב\"ד שם), ר ישכר דב, ר מרדכי, ר אליעזר מדובנא. בתו שנולדה אחר פטירתו נקראה על שמו - העסל וחתנו ר מאיר הלפרין, חתניו גם - ר בנימין וולף. ר נפתלי הירש, ר אברהם מגזע צבי, ר נתן נטע הילדסום, ר יהושע השל מקראסני-ברוד, ולודמיר. גיסו - ר בנימין זאב ז\"ק-זקנו של החכם צבי. (לפי","bk":[["חנוכת התורה – עה\"ת",""]]},{"i":906,"n":"אברהם יהושע השל מליועב","f":"מרדכי מליועב","b":"אדמו\"ר מליועב-תר\"ס"},{"i":907,"n":"אברהם יהושע השל מליטשיניץ","f":"ישראל מליטשיניץ","k":"אדמור מליטשיניץ","dt":"ח סיון","b":"חתן ר לוי מראדויל (זלוטשוב)."},{"i":908,"n":"אברהם יהושע השל משענא","b":"רב בשענא-תר\"מ"},{"i":909,"n":"אברהם יהושע מפודהייץ","b":"רב בפודהייץ-תריג."},{"i":910,"n":"אברהם יהושע מפוקרוי","f":"צבי הירש חריף מנישוו","dt":"תרסו","b":"נכד ר שלמה מקאמין קשורסק. רב בפיקעלן, פאקריי(=פוקרוי)-תרמ. הניח חבורים - בכת\"י."},{"i":911,"n":"אברהם יהושע מפיקאלן-ליטא","b":"רב בפיקאלן-ליטא-אחרי תרלו."},{"i":912,"n":"אברהם יואל מקושטא","b":"גביר בקושטא-שנות ה-ת', סייע ללומדי תורה."},{"i":913,"n":"אברהם יונה מאישפלטרו","k":"אביו\"ן (כך חתם)","bp":"אישפלטרו","dt":"תקעה","dp":"תקעה","b":"מחכמי ליפאנטו(=אישפלטרו), רב בונציה. תלמיד בעל \"שושנים לדוד\" ובעל \"נהר שלום\". מתורתו ב\"חיים וחסד\", \"פרי צדיק\" ועוד. הניח חבורים על דרך הפרד\"ס."},{"i":914,"n":"אברהם יוסף אבא מלובאשוב","f":"שמריהו מלובאשוב","b":"תלמיד המגיד ממזריטש. רב בסורוקה, דינאווא (ולפי ברוורמן יאנוב), לובעשאוו(=לובאשוב)-תקפ על מקום אביו, ובנו ר יצחק על מקומו אחריו. מחותן עם - ר דוד הלוי המגיד מסטעפין."},{"i":915,"n":"אברהם יוסף מאוסויעט","dt":"תרי","b":"אב\"ד אוסויעט-פלך ויטבסק. נכדיו - ר אברהם יוסף לוריא מקריסלאוויא, ר נחום גרינהויז מטרוקי(=טראק)."},{"i":916,"n":"אברהם יוסף מבלאשקי","dt":"תרלג - ג תשרי","b":"חסיד קוצק וגור. רב בבלאשקי. בנו - ר מנחם מנדל, ונכדו - ר אברהם יוסף פסח מבלגיה וארה\"ב."},{"i":917,"n":"אברהם יוסף מוויניטש","b":"רב בוויניטש (ליד בריגל)-תרפז."},{"i":918,"n":"אברהם יוסף מירושלים","f":"שלמה","b":"בתר\"ל שליח ירושלים לאפריקה ואירופה מטעם \"בית אל\", חותנו ר יהודה בן שלמה הכהן מגדולי ירושלים"},{"i":919,"n":"אברהם יוסף משה מהרמילוב","f":"יעקב","k":"בעל אמרי משה","dt":"תקצו - י תשרי","b":"תלמיד ר משה יהודה ליב מסאסוב. רב בהורמילוב, פרש מהרבנות ועבר לטרנופול. חיבר \"אמרי משה\"."},{"i":920,"n":"אברהם יחזקאל אבולעפיה","f":"שלמה","k":"הרב המלומד בנסים","dp":"טבריה","b":"הספיד בליוורנו את החיד\"א בשנת תקסו"},{"i":921,"n":"אברהם יחזקאל מבצרה","bp":"בגדד","b":"גביר בבצרה-תק בערך. (אולי בן למשפחת יהודה)."},{"i":922,"n":"אברהם יחיאל פישל מטרבובלה","f":"זאב וולף","k":"בעל אמרי צרופה","b":"רב בסלפקוביץ-שנות ה-תק', שאריגרד, טרבובלה-פלך לבוב."},{"i":923,"n":"אברהם יעקב הכהן מוילנא","f":"שלמה הכהן","b":"מו\"צ בווילנה"},{"i":924,"n":"אברהם יעקב מלובלין","f":"משה בעל גבעת שאול","dp":"לובלין","b":"מחכמי לובלין. הוא או אביו חברו \"גבעת שאול\"."},{"i":925,"n":"אברהם יצחק בן צבי הירש פרוש","b":"ראה פרוש, אברהם יצחק"},{"i":926,"n":"אברהם יצחק הכהן מקרליץ","k":"העילוי מפשצניץ","bt":"תריב","bp":"פלשצניץ-פלך בוריסוב","dt":"תרפג","b":"תלמיד ישיבת וולוזין, מקורב לר ירוחם \"הגדול ממינסק\" שהביא בשמו דברי תורה בשם \"חכם אחד\". רב בפיסאצענא-פלך מינסק-תרמו, קרליץ-תרן."},{"i":927,"n":"אברהם יצחק הלוי מזאגראוי","f":"שלמה פוזנר פלסנר","b":"רב בזאגראווי(=זגראווי)-פולין-תרס."},{"i":928,"n":"אברהם יצחק מאוסטרהא","f":"אריה ליב","b":"מגדולי אוסטרהא, והיה מהמול\"ים של שו\"ע \"אשלי רברבי\" - אוסטרהא תקנה, יחד עם ר שמואל בן ישכר בר בעל הדפוס הראשון באוסטרהא, ור אברהם משה בן ישראל יהודה. בנו ר שמחה ביבר מאוסטרהא. ונכדו ר אברהם יצחק ביבער (זקנו של ר מנחם מנדל ביבער בעל \"מזכרת לגדולי אוסטרהא\")."},{"i":929,"n":"אברהם יצחק מבלוזוב","b":"רב בבלוזוב (והיה מחלוקת על כך עם ר יעקב נח)."},{"i":930,"n":"אברהם יצחק מבריסק","f":"יוסף יוסל- פורת יוסף","k":"בעל ארבע כוסות","b":"רב בבריסק. חיבר הספד לפטירת ר נח חיים צבי מאה\"ו בשם \"ארבע כוסות\", \"פשר דבר\"."},{"i":931,"n":"אברהם יצחק מדוברוביץ","b":"תלמיד ר שלמה מקרלין, ר צבי אריה מאליק, ר אשר מסטולין, ובנו ר אהרן מקרלין."},{"i":932,"n":"אברהם יצחק מוישנובה - הזקן","f":"מנחם מנדל מאלשאן","dt":"תרו - בערך","b":"אב\"ד וישנובה. אחיו: ר משה מאלשאן, ר יוסף מואלקוניק. בנו - ר יעקב יוסף מוישנובה ונכדו ר אברהם יצחק רבינוביץ מראסיין."},{"i":933,"n":"אברהם יצחק מליסא","f":"יעקב","k":"בעל מנחת עני","b":"רב בליסא-תקפ."},{"i":934,"n":"אברהם יצחק מקרלין","f":"אליעזר הלוי","b":"ר\"מ בקלויז בקרלין-תקס. חתנו - ר משה אהרן מואשלישוק. מחותן עם ר אשר משרשוב בעל ברכת ראש."},{"i":935,"n":"אברהם יצחק משלוניקי - ב","k":"בעל משמרות כהונה","b":"רב בשלוניקי-ת\"ר (האם הוא ר אברהם יצחקי מתונס?)"},{"i":936,"n":"אברהם יצחק משלוניקי - הזקן","dt":"תיט - יב אב","dp":"שלוניקי","b":"מחכמי שלוניקי. בנו - ר יצחק אברהם."},{"i":937,"n":"אברהם ירוחם פישל מקוליקוב","f":"יהודה","k":"פישל קוליקובר","bp":"קוליקוב","b":"גר בפודקמין. עלה לארץ-תקם והתישב בצפת, חזר לגליציה. חיבר \"פרי הארץ\" למברג תקמה."},{"i":938,"n":"אברהם ישמעאל מירושלים","b":"חתם-תקיב על שטר התקשרות של 12 מחכמי ירושלים."},{"i":939,"n":"אברהם ישראל הכהן מהמבורג","f":"דוד יעקב","k":"בעל זרע אברהם","dt":"תקנח - ט אב","dp":"אה\"ו","b":"חתן הפרנס ר שלמה זלמן מאלזס והמבורג. מחכמי המבורג, מיסד ביהמ\"ד של ר פיבש בן ברוך מהמבורג. גיסו של ר מתתיה אלזס."},{"i":940,"n":"אברהם ישראל חי הכהן מפדובה","f":"שמואל","dt":"תקכב - כד חשון","dp":"פדובה","b":"גביר מחכמי פדובה. זקנו של ר מרדכי גירונדי בעל \"תולדות גדולי ישראל\"."},{"i":941,"n":"אברהם ישראל מירושלים","dt":"תצט","dp":"ירושלים","b":"בשנת תסב שליח ירושלים לברסלוי, נספד בשלוניקי על ידי ר חיים משה אמריליו (בספרו :יד משה)."},{"i":942,"n":"אברהם ישראל מקהיר","b":"רב בקהיר-רפ\"ז"},{"i":943,"n":"אברהם ישראל משלוניקי","dt":"תמה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":944,"n":"אברהם ישראל פרצע'ס","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":945,"n":"אברהם כהנא גאון פומפדיתא","b":"גאון פומפדיתא-ד'תקיט על מקום רב נטורנאי כהנא בן רב אמונה, ור דוראי בן רב נחמן על מקומו אחריו. גאון סורא בזמנו - רב יהודאי גאון בעל הלכות - אחיו של רב דוראי מפומפדיתא. בניו: ר חנינא כהנא גאון, רב אבומאי גאון."},{"i":946,"n":"אברהם כץ הכהן מלאסק","f":"יחיאל מיכל מלוסק","k":"בעל בית יעקב","bp":"לוסק","dt":"תקנח","dp":"ירושלים","b":"רב בלוסק(=לאסק), עבר לפירט(=פיורדא), הגיע לאיטליה ועלה לירושלים-תקל, בשליחות באשכנז-תקמא, היה בפרנקפורט-תקמג ובעל פרי מגדים הסכים על ספרו \"וחשב לו הכהן\". בשנת תקמה העיד בפני ר שאול רבה של אמשטרדם לטובת השד\"ר הספרדי רפאל יוסף בן רבי שגם האשכנזים זוכים לחלקם מכספי התרומות בירושלים. בשליחות בליוורנו ותונס-תקנב. חיבר ספר \"ושב הכהן\" ליוורנו תקמז, \"עין פנים בתורה\", ועוד. נהרג עק\"ה בידי התורכים בגלל מס שלא שולם מצד הקהלה. הסכים על \"ברכת אברהם לאחיינו-בן אחותו - ר אברהם קצנלנבוגן מלוסק. אחיו - ר שמואל כץ לסקר מלוסק."},{"i":947,"n":"אברהם ליב","f":"חיים גבריאל בלוך"},{"i":948,"n":"אברהם ליב מבוצאץ","b":"שו\"ב בבוצאץ."},{"i":949,"n":"אברהם ליב מניקלשבורג ובוניהאד","dt":"תקסה - כט שבט","dp":"בוניהאד","b":"רב בבוניהאד, ור בנימין וולף בוסקוביץ על מקומו אחריו."},{"i":950,"n":"אברהם ליפא מפרוזין","b":"מחכמי פרוזין ומלמד תורה - בזמן רבנות ר ירחם יהודה פרלמן \"הגדול ממינסק\"."},{"i":951,"n":"אברהם מאבדזידה","f":"ראובן בן אליהו","k":"בעל בית אברהם","b":"מחכמי קושטא, ש\"ץ באבדזידה. חיבר \"בית אברהם\" על המסורה - קושטא תצב. אחיו - ר יהושע בעל \"קול יהושע\""},{"i":952,"n":"אברהם מאדרינופול","f":"מאיר","b":"גביר מחכמי אדרינופול-שנות ה-ש'."},{"i":953,"n":"אברהם מאדרינופול","f":"שמואל","dp":"אדרינופול","b":"גביר מחכמי אדרינופול, עסק במסחר עם ונציה ופאריס. מתורתו ב\"מורה צדק\"."},{"i":954,"n":"אברהם מאדרינופול וקושטא","f":"שמואל אביגדור","k":"בעל זכור לאברהם","bt":"תעה","dt":"תקמו-נז","b":"תלמיד ר אליעזר בן יעקב נחום מאדרינופול בעל \"חזון נחום\". רב ור\"מ באדרינופול, עבר לקושטא-תקיא, רב הכולל בקושטא-תקע. בנו - ר יוסף שחיבר הגהות והוספות לספר אביו \"זכור לאברהם\", ונדפס בידי נכדו - ר אביגדור בן יוסף - תרסה."},{"i":955,"n":"אברהם מאויבן","b":"מו\"צ באויבן-ש\"ס"},{"i":956,"n":"אברהם מאונסדורף","b":"דיין באונסדורף אצל ר יואב בעל \"שערי בינה\". נפטר בן למעלה מ-100, היה סגי נהור כ-40 שנה ונתפקח. נזכר ב\"המבשר\"-תרכב."},{"i":957,"n":"אברהם מאוסטרהא","f":"מאיר","dt":"תעט - כז ניסן","dp":"אוסטרהא","b":"מנהיג מדינה באוסטרהא. לדעת מנחם מנדל ביבער (מזכרת אוסטרהא) יתכן שאביו היה ר מאיר ז\"ק שהיה פרנס באוסטרהא, או שהיה חתנו של ר יעקב מפוזנא."},{"i":958,"n":"אברהם מאוסטרהא","b":"רב באוסטרהא. בנו - ר יצחק"},{"i":959,"n":"אברהם מאוסטרהא","f":"דוד","k":"בעל כור לזהב","b":"רב באוסטרהא. חיבר \"כור לזהב\" - פפד\"מ. אולי אביו של ר דוד בן אברהם מאוסטרהא."},{"i":960,"n":"אברהם מאוסטרהא","f":"שמואל","dt":"תק..","dp":"אוסטרהא","b":"פרנס באוסטרהא."},{"i":961,"n":"אברהם מאוסטרהא","f":"ברוך","dt":"תקמו - ו אד\"א","dp":"אוסטרהא","b":"פרנס באוסטרהא-תקכה. חתם על כתב רבנות ר מאיר חריף."},{"i":962,"n":"אברהם מאוסטרהא","f":"צבי הירש הקדוש","bp":"פבלוביטש","dt":"תקעב - כ חשון","dp":"אוסטרהא","b":"אולי אביו מתשעת קדושי פאוולוביטש שנהרגו עק\"ה (ור יונתן איבשיץ חיבר קינה עליהם - קשת יהונתן). חתן ר ייב\"י. מחכמי אוסטרהא, וחתם בפנקס הח\"ק. מבניו: ר נתן נטע מאוסטרהא, ר יעקב יוסף מאוסטרהא, ר יונה מאוסטרהא."},{"i":963,"n":"אברהם מאוסטרהא","f":"יצחק","k":"ר אברהם מעזירטשער","dt":"תקף - ג סיון","dp":"אוסטרהא","b":"דיין באוסטרהא. הסכים על ,שבחי הבעשט\" ברדיטשוב תקעה, ועוד."},{"i":964,"n":"אברהם מאוסטריה","f":"שמחה","b":"רב באוסטריה-קן. נזכר ב\"אור זרוע\"."},{"i":965,"n":"אברהם מאורליאנש","f":"יוסף","b":"תלמיד רבינו תם. מגדולי בעלי התוספות באורליינש-ד'תתק. חתנו - ר יהודה בן יצחק מפאריס. נזכר במרדכי ובאור זרוע שנהגו בנותיו לזמן."},{"i":966,"n":"אברהם מאזמיר","f":"יקר","bp":"אזמיר?","dt":"תריג","b":"מעולי אזמיר, הספידו באזמיר חתנו ר יוסף בן חיים פאלאגי בספרו \"ארצות החיים\": דרוש ז."},{"i":967,"n":"אברהם מאזמיר","f":"יוסף מנשה","b":"מדפיס באזמיר אצל ר דוד חזן-תצג."},{"i":968,"n":"אברהם מאזמיר","f":"יעקב","b":"מדפיס באזמיר-תק אצל המדפיס הארמני אוסטה מארגוס."},{"i":969,"n":"אברהם מאיטליה","f":"יוסף בן שיכון","b":"רב באיטליה-ן'. תשובותיו בספרי חכמי איטליה ובהם \"שיבולי לקט\"."},{"i":970,"n":"אברהם מאיטליה","f":"דניאל","bt":"רעא","bp":"מודנא-איטליה","b":"מחכמי מודנא-קן, מנטובה, ועבר בין ערים שונות באיטליה. משורר ופייטן ורבים מפיוטיו במחזורי איטליה."},{"i":971,"n":"אברהם מאיטליה","f":"יצחק בן יחיאל","dt":"שיד","b":"מחכמי פיסא-איטליה-ש', בולוניה. תשובותיו בספרי חכמי דורו ובהם רמ\"ע מפאנו (י\"א שהוא אביו של ר שמעון גינצבורג מפוזנא)."},{"i":972,"n":"אברהם מאיטליה","f":"שלמה","b":"מחכמי איטליה-ה'א. נזכר ב\"שבולי לקט\" ואולי הוא רבו של ר אברהם הנשיא."},{"i":973,"n":"אברהם מאיר הכהן מהמבורג","dt":"תקיח - כב סיון","b":"דיין בהמבורג,רב בהנובר"},{"i":974,"n":"אברהם מאיר כץ מירושלים","f":"ירמיה בן מאיר","bp":"ישראל","b":"אביו עלה עם עולי הגר\"א תקסח, חתום על תקנות ישיבת \"עץ חיים\", מוזכר בשטר שליחות משנת תקצז, שליח הקהילה באירופה, בשנת תרז נמנה על מיסדי חברת משמורים"},{"i":975,"n":"אברהם מאיר מיאלאבזיק","f":"ישעיה מפרגא","b":"רב ביאלאבזיק-תר\"ז"},{"i":976,"n":"אברהם מאיר ממנדוק","dt":"תשד","b":"רב במנדוק"},{"i":977,"n":"אברהם מאמשטרדם","f":"יהושע","b":"רב לאשכנזים באמשטרדם-שצו. הסכים על \"אור חדש\" - אמשטרדם תלא."},{"i":978,"n":"אברהם מארץ ישראל","f":"משה איש חי","b":"שליח קהילת אשכנזים באיטליה סביב השנה תיט 1659, אישר בקאסלי תשובה מאת ר יהושע אהרן בן שלמה הכהן"},{"i":979,"n":"אברהם מארץ ישראל","f":"שלה","b":"בשנת ד תת (1050) - תתב (1042) מוזכר במכתב ר נתן בן אברהם שהיה גאון ארץ ישראל שכתב \"גדולנו מרנא ורבנא אברהם החבר וכו'\""},{"i":980,"n":"אברהם מארץ ישראל","f":"שלמה בן יהודה גאון","b":"בנו של גאון ארץ ישראל-ד'תת."},{"i":981,"n":"אברהם מאשכנז","f":"משה","b":"מגדולי חכמי אשכנז-שנת ל'"},{"i":982,"n":"אברהם מאשכנז","f":"יוסף","dt":"נג","dp":"אשכנז","b":"מחכמי אשכנז. חיבר קינה \"הלא תשאלי לשלום אמונים\" ונכנס למחזור. נהרג עק\"ה."},{"i":983,"n":"אברהם מאשכנז","f":"מרדכי","b":"מחכמי אשכנז בזמן בעל הלבוש-שמח. תשובה ממנו ב\"נתיבות עולם\" למהר\"ל."},{"i":984,"n":"אברהם מאשכנז","f":"אפרים","k":"בעל קיצור סמ\"ג-סימני","b":"תלמיד ר טוביה בן אליהו. מחכמי אשכנז-ל'. חיבר קיצור סמ\"ג בשם ספר ה\"סמנין\", ונזכר בספר הריקנטי, נזכר גם ב\"שלטי הגבורים\" בשם המרדכי. חיבר פזמון \"אבותי כי בטחו\"."},{"i":985,"n":"אברהם מאשכנז","b":"חותנו של המהרי\"ל בזיוו\"ש."},{"i":986,"n":"אברהם מאשכנז","f":"מרדכי","b":"נזכר בתוס' קושיא ממנו."},{"i":987,"n":"אברהם מאשפנבורג","b":"מחכמי אשכנז-ן'. נזכר בספר האסופות."},{"i":988,"n":"אברהם מבאר","f":"ברוך מזאמושטש","k":"בעל בדרך אלשיך","b":"רב בבאר, ובכמה קהלות בפודוליה ליד לבוב. חיבר פירוש על דרך האלשיך בשם \"בדרך אלשיך\", \"חדודי דאבא\", \"מרכבת המשנה\" על המשנה."},{"i":989,"n":"אברהם מבוואריה וסופיה","b":"מחכמי ביירען(=ביירן)-בוואריה, לאחר גירוש היהודים-רל עבר לסופיה וכיהן כרב. ושנים אח\"כ עשו לו אזכרה ביוה\"כ."},{"i":990,"n":"אברהם מבוזנוב","b":"רב בבודזנוב-תקם, טרנופול. תשובות אליו בחת\"ס-תקץ, ועוד."},{"i":991,"n":"אברהם מבולוניא","b":"רב בבולוניא-ר\"כ"},{"i":992,"n":"אברהם מבולוניה","k":"ר' אברהם הספרדי","b":"מגדולי חכמי איטליה,רב בבולוניא-רע\"ח-ש\"ט"},{"i":993,"n":"אברהם מבורגיל","f":"יהודה","b":"מחכמי צרפת-ד'תתק. הובא בתוס' וברשב\"א, ובמרדכי מביא בשם - ר אברהם מאורליאנס (ואולי זה הוא - לפי החיד\"א זה חכם אחר)."},{"i":994,"n":"אברהם מביזנאוו","b":"רב בביזנאוו-תק\"מ"},{"i":995,"n":"אברהם מבילקמין","f":"שמריהו","dt":"תנז - ח כסלו","dp":"לבוב","b":"רב בבילקומין"},{"i":996,"n":"אברהם מבירז","f":"שלמה זלמן","b":"מו\"ץ ומ\"מ בבירז. הסכים על \"נאדר בקדש\" על חובות הלבבות - הורדנא תקן. (לדעת ליפמן-קובנא - יש המחליפים אותו עם ר אברהם אחי הגר\"א)"},{"i":997,"n":"אברהם מבלגרד ושלוניקי","f":"אברהם","k":"בעל אורים ותומים","b":"השתמד בוידין, עבר לסופיה, ושב ליהדות באדרינופול (ושם התגייר והסתיר את יהדותו, וכשנתן גט לאשתו-תץ התברר הדבר). חיבר \"אורים ותומים\"-נדפס בדירנפורט."},{"i":998,"n":"אברהם מברוד","f":"יצחק מזלקווא","b":"פרנס ומנהיג דד\"א"},{"i":999,"n":"אברהם מברוסא","f":"יעיש","b":"רב בברושא(=ברוסא) - בדור שלאחר הגירוש. שאלות ממנו לר יוסף קארו בניקופול."},{"i":1000,"n":"אברהם מברזניץ","f":"בירך","b":"רב בברזניץ-שנות ה-ת', פעל כמתווך בקהלת באיא בענין מסי הקהל."},{"i":1001,"n":"אברהם מבריסק","f":"מרדכי אהרן","b":"שמש קהלת בריסק, חתם-תטו על קיום פסקי דין."},{"i":1002,"n":"אברהם מברצלונה","f":"יהודה","k":"בעל ארבע טורים","b":"מקובל. חיבר \"ארבע טורים\" בקבלה בכת\"י-קלה - נמצא בותיקן (רשימת הכומר די רוסי) - נכתב בבית ר חסדאי קרשקש, ע\"י הסופר אברהם בן ליאון מקנדיא (ואולי הוא המחבר עצמו)."},{"i":1003,"n":"אברהם מברצלונה","f":"ראובן","b":"מחכמי ברצלונה בזמן הרשב\"א וחתם בתשובת הרשב\"א."},{"i":1004,"n":"אברהם מגוטשריש","b":"מחכמי פרובנס. חיבר חיבורים בתלמוד ונזכר ב\"שערי ציון\" לר\"י דלאטש."},{"i":1005,"n":"אברהם מגירונדי","k":"הזקן, אברהם מגירונ","b":"חכם בגירונה, אביו של רבינו יונה"},{"i":1006,"n":"אברהם מגריידיץ","f":"יהודה","k":"בעל אמרי נועם","b":"מ\"מ בגריידיץ-פלך פוזנא. חיבר \"אמרי נועם\" ובתוכו \"אורים גדולים\", לוחות המועדות, ועוד - המבורג תרד."},{"i":1007,"n":"אברהם מדוברומיל","b":"רב בדוברומיל, חתנו - ר צבי הירש בן יהודה על מקומו אחריו."},{"i":1008,"n":"אברהם מדמורה","b":"משורר מחכמי יון, והזכירו אלחריזי בספרו \"תחכמוני\" שפגש בו בארץ יון-ד'תתקע."},{"i":1009,"n":"אברהם מדרוהוביטש","f":"שלמה","dt":"תקצג - ז אדר","b":"רב בדראהביטש"},{"i":1010,"n":"אברהם מדרוהוביטש ולבוב","f":"אהרן","b":"מראשי קהלת לבוב, חתם-תקד על תקנה עם הקדוש ר חיים בן יחיאל מיכל, ור אברהם בן יואל ועוד."},{"i":1011,"n":"אברהם מדרש","f":"שלמה","b":"חיבר ספר ויכוח נגד הנוצרים-ה'לג (1273) - בכת\"י (בספריה בפאריס)."},{"i":1012,"n":"אברהם מהורדנא","f":"בנימין","dt":"תר-ט חשון","dp":"הורדנא","b":"ר\"מ בהורדנא"},{"i":1013,"n":"אברהם מהורדנא ווילנא","f":"מהורי\"ל","dt":"תרג - יט אד\"ב","b":"ר\"מ בוילנא. אחיו - ר יעקב מהורדדנא ווילנא."},{"i":1014,"n":"אברהם מהלברשטט","f":"מנחם מנקי מהלברשטט","k":"הו\"ל בעל הנפש","dt":"תקמב - ד אדר","dp":"ברלין","b":"חתן ר שמואל כץ מהלברשטט. תלמיד ר יונתן איבשיץ. רב בהלברשטט. הו\"ל \"בעל הנפש\" לראב\"ד עם הגהות ממנו ונציה תקא. מחכמי ברלין. החליף אגרות עם חברו ר ירמיה בן אפרים מברלין בענין התפשטות ההשכלה, ונדפסו ב\"געשיכטא דער יודען אין הלברשטט\" לר אוירבך מהלברשטט. אחיהם של ר זליג הלברשטט מגלוגא וברלין, ור משה בורג מברלין."},{"i":1015,"n":"אברהם מוארשא","f":"אלעזר הכהן מפולטוסק","b":"נכד ר יעקב מליסא בעל \"חוות דעת\". מו\"צ וממלא מקום הרב בוארשא. בנו ר פנחס שמואל זנויל. אחיו - ר צבי הירש מזגירז, ר יהושע. גיסו - ר דוד מייזלש מלוסק."},{"i":1016,"n":"אברהם מוהראן-אלגיר","f":"יוסף","b":"פייטן, חיבר רשות לקדיש."},{"i":1017,"n":"אברהם מוולוזין","b":"מחכמי וולוזין. חתניו - ר רפאל שלמה היימן מקרמנצוג, ר שמחה זיסל, ר נחמיה מוצלאוו, ר אליעזר יצחק ברמן מקרמנצוג."},{"i":1018,"n":"אברהם מויטבסק","b":"מו\"צ בויטבסק. חתנו - ר הלל מויטבסק."},{"i":1019,"n":"אברהם מוילנא","f":"הגר\"א","k":"בעל רב פעלים","bp":"וילנא","dt":"תקסט - כה כסלו","b":"חתן ר נח מינדע'ס בעל \"נפלאות חדשות\" (נכדת ר אליהו פעסעלס). מגדולי חכמי וילנא. הו\"ל כמה מספרי אביו. הניח חבורים בכת\"י ובהם \"דרוש הספד\" על אביו הגר\"א. מבניו: ר יעקב משה מסלונים. חתנו - ר רפאל מחיטוביץ, ונכדתו שרה זלאטא (שארלאטא דיא חיטאוויצערין) אשת הגביר ר שמריהו צוקרמן ממוהליב שהחזיקה כמה מכתבי הגר\"א. מכתב ממנו ב\"תורה מציון\" - ירושלים תרנה-תרסה. בנו - ר יעקב משה מסלונים. נקבר לצדו של ר מרדכי בן יהודה ליב אפשטין."},{"i":1020,"n":"אברהם מוילנא","f":"משה","b":"אב\"ד וילנא-תקכו עד תקמב."},{"i":1021,"n":"אברהם מוילנא","f":"יעקב","b":"רב בוילנא, חתם-תסא עם ר הלל בן נפתלי הרץ מוילנא וקידאן."},{"i":1022,"n":"אברהם מוילנא","f":"יחיאל","b":"גביר מראשי קהלת וילנא, חתם-תע בפנקס הקהלה. נזכר-תקא אצל ר אריה ליב שפירא בפנקס הקהלה."},{"i":1023,"n":"אברהם מוילנא","f":"אורי","b":"דיין בוילנא, חתם-תפח עם ר יהודה מטיקטין."},{"i":1024,"n":"אברהם מוילנא","f":"יעקב צבי","b":"דיין בוילנא, חתם-תקד עם ר יהשע השל. חתם-תקי על כתב הרבנות של ר שמואל-אב\"ד וילנא."},{"i":1025,"n":"אברהם מוילנא","f":"אליעזר","b":"דיין בוילנא, חתם-תקי עם היסו\"ד."},{"i":1026,"n":"אברהם מוילנא","f":"אליעזר","dt":"תקנח - ד סיון","dp":"וילנא","b":"מלמד תורה בוילנא."},{"i":1027,"n":"אברהם מונש מלבוב","b":"מצאצאי ר קופל קלמנקיש מלבוב. חתן מהר\"ם מלבוב. מחכמי לבוב, מצאצאיו - ר אליעזר ליפשיץ בעל \"השיב רבי אליעזר\". אחיו - הגביר ר נתן צוזמיר."},{"i":1028,"n":"אברהם מזוויהל ואוסטרהא","f":"אהרן מאוסטרהא","dt":"תקכב - ח אייר","dp":"אוסטרהא","b":"מגדולי חכמי דורו. לאחר שנתייתם גדל אצל זקנו ר יוסף יוזפא מאוסטרהא פרנס מדינת ואהלין. חתן ר יוסף גינצבורג בעל \"לקט יוסף\". מחכמי אוסטרהא, רב בזוויהל ובנו ר יוסף על מקומו אחריו, מתורתו ב\"גורל יהושע\". בנו ר ישראל פרנס באוסטרהא. נפטר בחיי זקנו ר יוסף יוזפא. גיסו - ר אברהם משלם זלמן אשכנזי בעל \"דרכי רב משלם\"."},{"i":1029,"n":"אברהם מזולקווא","f":"מרדכי ליבשס","dt":"תפא - כ חשון","b":"חתן הגביר ר יצחק מזולקוא. רב בזולקווא"},{"i":1030,"n":"אברהם מזולקווא","f":"משה מדומברובה","dt":"תצד - כ ניסן","dp":"זולקווא","b":"מחכמי זולקווא. (הוא או אביו היה מגיד בדאמבראווי(=דומברובה)."},{"i":1031,"n":"אברהם מזולקווא ובלז","f":"שלום","b":"חתם-שפו על תקנת קהלת זולקווא. ואולי הוא הנזכר בשו\"ת מהר\"ם מלובלין (סי' קכז) ובשו\"ת הבח\"ח החדשות (סי' מב)."},{"i":1032,"n":"אברהם מזורוונא","f":"משה שאול","b":"רב בזורוונא"},{"i":1033,"n":"אברהם מזיטומיר","f":"צבי הירש","k":"בעל משנת אברהם","dt":"תרך","b":"סופר סת\"ם ומגיה מחכמי זיטומיר. התכתב עם רבנים שונים ובהם ר גרשון קיטובר, ר שבתי ראשקיווער, ר אריה יעקב מסמילא, ר שמואל מקמינקא, ועוד. בניו: ר מרדכי צבי מזיטומיר, ר יהושע זלמן - הו\"ל את ספרו \"משנת אברהם\" - זיטומיר תרכט - עם הקדמה, והגהות מאת ר משה-שו\"ב בזיטומיר."},{"i":1034,"n":"אברהם מזמיגראד","b":"רב בזמיגראד-ת\"מ"},{"i":1035,"n":"אברהם מזשונהים","f":"משה","k":"בעל תיקון תפילין ומז","b":"כונה גם אברהם חזן מאורפורט. סופר ונקדן באשכנז-ן'. תלמיד מהר\"ם מרוטנברג, רבנו פרץ מצרפת, ר מנחם בן נטרונאי מוירצבורג הנקרא ר קיבלין ורבנו מלכיאל. חיבר תיקון תפילין ומזוזות ור שמשון חיבר הגהות בשם ברוך שאמר על הספר ונדפס בשם \"ברוך שאמר\", ור ברוך מעיד כי היה ראש לכל כותבי התפילין ולא קם כמוהו."},{"i":1036,"n":"אברהם מחברון","f":"ישעיה","k":"החבר החברוני","b":"דיין בחברון, חתום על מכתב אודות הריסת בית הכנסת ובניית חדש במקומו."},{"i":1037,"n":"אברהם מחברון","f":"סעדיה","b":"עמד בראש קהילת חברון בראשית המאה ה-יא, מ. אסף מצטט מכתב ששלח לר משה הכהן הזקן ב\"ר גוליב, י מאן פרסם מכתב ששלח לר שלה בעיר אבולביס."},{"i":1038,"n":"אברהם מחדליק","b":"מחכמי אשכנז בזמן בעל \"אור זרוע\"-ה'א. חיבר דינים ומנהגים - בכת\"י, חיבר גם סליחות ופיוטים שנרשם עליהם \"מר\"א חדליק\". מתלמידיו - ר חזקיה ממידבורג(=מהרי\"ח). אולי הוא ר אברהם בן עזריאל."},{"i":1039,"n":"אברהם מחווסטוב","f":"צבי הירש","b":"חתן ר מנחם נחום מטשרנוביל. מג\"מ בחווסטוב-תקף. בניו: ר ישראל המגיד מבפאלי, ר אריה ליב מסדילקוב. חתנו ר שלום שכנא."},{"i":1040,"n":"אברהם מחווסטוב","dt":"תרנח - כז אב","b":"רב בחווסטוב"},{"i":1041,"n":"אברהם מחסלביץ","b":"חתום על פשר החלוקה בין פרושים וחסידים בשנת תקפט, חתם-תקצו על רכישת חצר לכולל הפרושים עם ר אברהם ברי\"צ ור משה יצחק בן בצלאל הכהן."},{"i":1042,"n":"אברהם מחרסון","dt":"תרכח-ב שבט","b":"רב בחרסון,עלה לירושלים"},{"i":1043,"n":"אברהם מטאמשפיל","f":"יחיאל","k":"בעל חסד לאברהם","dt":"תרי - בערך","b":"רב בטאמאשפיל-פודוליה (מרכז אוקראינה). חתנו - ר יעקב שפירא מויניציא - חיבר הקדמה לספרו \"חסד לאברהם\"."},{"i":1044,"n":"אברהם מטוטשין","f":"שלמה אריה ליב מטוטשי","b":"רב בטוטשין"},{"i":1045,"n":"אברהם מטולידו","f":"יום טוב","b":"מחכמי ספרד-ק', מתלמידי הרא\"ש ונזכר בתוס' הרא\"ש. (ואולי הוא אברהם בן קרשף)"},{"i":1046,"n":"אברהם מטולידו","f":"יצחק","bt":"ש","dt":"שס","b":"מחכמי פורטוגל"},{"i":1047,"n":"אברהם מטולידו","f":"מזאח","b":"תלמיד הרא\"ש. מחכמי טולידו-קן. נזכר ב\"זכרון יהודה\" לר יהודה בן הרא\"ש."},{"i":1048,"n":"אברהם מטולידו - א","f":"שמואל","b":"מחכמי הדור בטוליטולא(=טולידו)-תתן-תתק. חתם על מכתב שאלת חברו ר יוסף בן חיים מהר\"י מיגש ונזכר בתשובות הרמב\"ם."},{"i":1049,"n":"אברהם מטורטולה-ספרד","f":"יעקב","b":"מחכמי ספרד-ד'תש. חיבר ספרי מסעות ופגש את הקיסר אוטו."},{"i":1050,"n":"אברהם מטריויש","f":"מתתיה","b":"רב בצרפת-קן. נזכר בהגהות לספר הנייר."},{"i":1051,"n":"אברהם מטרני","f":"מארינוס","b":"מחכמי איטליה-ק', חיבר פיוטים ובהם \"מי כמוך אדיר\"."},{"i":1052,"n":"אברהם מטשרנוב","b":"תלמיד ר אפרים פישל מסטריקוב."},{"i":1053,"n":"אברהם מיאנוב","f":"גד","dp":"פרנקפורט","b":"בשנת תסא בשליחות מירושלים לפרג ופרנקפורט, בשנת תסז חתום על כתב רבנות מירושלים, בשנת תעא בשליחות באשכז בענין בעלי החובות הערבים בירושלים."},{"i":1054,"n":"אברהם מיאנוב","dt":"תקסז - יג אייר","b":"חתן ר עוזר ממזריטש. אב\"ד יאנוב."},{"i":1055,"n":"אברהם מיאסווין-ליטא","k":"בעל בית אברהם","b":"רב ביאסווין על מקום ר נפתלי אמשטרדם."},{"i":1056,"n":"אברהם מירושלים","f":"אברהם","dt":"תרטו - כד אדר","b":"מחכמי ירושלים ומראשי הקהלה, היה מעורב במחלוקת בין ר רפאל נבון ור חיים אברהם גאגין. פעל לבנית ארבעת בתי הכנסת בירושלים, ושכנע את מונטיפיורי לבנות את הבית שעל קבר רחל. בנו - ר משה-חתן ר יעקב שאול אלישר."},{"i":1057,"n":"אברהם מירושלים","f":"אליעזר","dt":"תקנג - כה תשרי","dp":"ירושלים","b":"דיין בירושלים. שליח ירושלים בערי טורקיה, הסכים על ספר \"קול שמואל\" לר' שמואל קרנפורט."},{"i":1058,"n":"אברהם מירושלים","f":"דאנה","b":"פרנס ירושלים בזמן אבן פארוך תכב. מוזכר בפנקס ספרדים בהמבורג שבא מירושלים לבקש על יהודי חברון."},{"i":1059,"n":"אברהם מירושלים","f":"ישועה","b":"בשנת רע נזכר במכתב בני הישיבה בירושלים."},{"i":1060,"n":"אברהם מירושלים","f":"נתן","b":"דיין בירושלים, מוזכר במסע ר משולם מוולטרה משנת רמב"},{"i":1061,"n":"אברהם מירושלים","f":"שלמה בן יהודה","b":"בשנת ד תשפז (1027) שליח במצרים מטעם ישיבת גאון יעקב בירושלים."},{"i":1062,"n":"אברהם מירושלים","f":"הזייר","b":"מחכמי ירושלים-תטז, חתם על כתב שליחות ר ברוך גד."},{"i":1063,"n":"אברהם מירושלים","f":"דוד מפינסק","dt":"תרכז - א אד\"ב","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":1064,"n":"אברהם מכפר סיאון-ליד ראסיין","b":"מחכמי כפר סיאון-ליד ראסיין. חברו של ר שמואל חסיד מראסיין. מצאצאיו - ר אברהם חריף מפיקלין. חתנו - ר יחיאל מיכל מוידוקלא-מחוז ראסיין פלך קובנא."},{"i":1065,"n":"אברהם מלאריסה","f":"אליה יונה","b":"רב בלאריסה-שנות ה-ש'."},{"i":1066,"n":"אברהם מלבוב","f":"דוד","k":"בעל פירוש על הריף","dt":"שפב - ד אב","dp":"לבוב","b":"ר\"מ וראב\"ד בלבוב. חיבר פירוש על הרי\"ף."},{"i":1067,"n":"אברהם מלבוב","f":"משה","b":"דיין בלבוב, חתם-תקלג עם ר דב בר בהגאון מזמושט, ר נחמן רפפורט, ועוד."},{"i":1068,"n":"אברהם מלבוב","f":"מרדכי אריה מפרמישלן","k":"אדמור מפרמישלן בלבוב","b":"אדמור מפרמישלן בלמברג."},{"i":1069,"n":"אברהם מלבוב","f":"מרדכי","dt":"תט - ח טבת","dp":"לבוב","b":"פרנס, מראשי הקהלה בלמברג."},{"i":1070,"n":"אברהם מלבוב","f":"עזריאל","dt":"תה-ח - יג אלול","dp":"לבוב","b":"מראשי קהלת לבוב."},{"i":1071,"n":"אברהם מלבוב","f":"שלמה (או יוסף)","dt":"תכד - יא אייר","dp":"לבוב","b":"דיין ור\"מ בלבוב, נהרג עק\"ה."},{"i":1072,"n":"אברהם מלבוב","f":"יהודה ליב","b":"מחכמי לבוב, חתם-תצו על פסק דין."},{"i":1073,"n":"אברהם מלבוב","f":"יואל","b":"מראשי קהלת לבוב, חתם-תקד על תקנה עם הקדוש ר חיים בן יחיאל מיכל. (אולי הוא שנזכר בהקמת תולדות יצחק - או מולדות יצחק)."},{"i":1074,"n":"אברהם מלבוב","f":"שלמה","b":"מראשי קהלת לבוב, חתם-תקי על שטר מתנה של הקהלה."},{"i":1075,"n":"אברהם מלובלין","k":"בעל מחזה אברהם","dt":"תקסט - כב תשרי","b":"רב בלובלין"},{"i":1076,"n":"אברהם מלובלין","k":"ר' אברהם מוכר ירקות","b":"רב בלובלין-ש\"מ"},{"i":1077,"n":"אברהם מלובלין","f":"בער מוכר בשמים","dt":"תח - ז אלול","dp":"לובלין","b":"מחכמי לובלין. נפטר צעיר."},{"i":1078,"n":"אברהם מלובלין","f":"יעקב קופל","dt":"תקפח -ט-יט אלול","b":"רב בלובלין. ראה גם: ר אליעזר משה מלובלין."},{"i":1079,"n":"אברהם מלטה","f":"יצחק","b":"פייטן מגדולי החכמים בזמן רב האי גאון-ד'תשן ופיוטיו נכנסו למחזורים שונים - ישנם פיוטים שיוחסו אליו והם מרב האי גאון."},{"i":1080,"n":"אברהם מליסא","f":"יוסף יאסקה","b":"נגיד ומצוה, פרנס ועד ארבע ארצות בזמן מחלוקת ר יעקב איבשיץ."},{"i":1081,"n":"אברהם מליפנא","b":"מחסידי קוצק. כונה בשם \"רבי אברהם הגדול\". מלמד בני האדמור ר מנחם מנדל מקוצק."},{"i":1082,"n":"אברהם מליקיווא","b":"אחיו של ר משה אהרן מקוטנא. חסיד החוזה מלובלין, ואחריו חסיד ר משה מאויהל."},{"i":1083,"n":"אברהם מלמד הפייטן","b":"פייטן, חיבר פיוט \"אגיל בשמחה ורון\"."},{"i":1084,"n":"אברהם מלמונטי","b":"חיבר קונטרס בפתרון חלומות."},{"i":1085,"n":"אברהם מלענטשנא","f":"שלמה יהודה ליב מלינט","k":"אדמור מלענטשנא","b":"רב בלענטשנא. חתנו - ר שמואל מסלונים."},{"i":1086,"n":"אברהם ממגנצא","f":"גמליאל בן פדהצור","b":"מחכמי מגנצא-קן, בזמן ר משה מולין-אבי המהרי\"ל, וחתמו יחד על תשובה. חתם בתקנות שו\"ם. (השם פדהצור הוא לזכר נס שנעשה לו)."},{"i":1087,"n":"אברהם ממודנא","f":"משלם","b":"חתן ר יצחק די לטאש מאיטליה. מחכמי איטליה-שיח. אחד המגיהים של ספר הזהר - מנטובה שיח."},{"i":1088,"n":"אברהם ממונקטש - א","b":"אב\"ד מונקטש-שנות ה-תק'. נזכר ב\"נודע ביהודה\"."},{"i":1089,"n":"אברהם ממונקטש - ב","f":"דוד","k":"בעל ברכת אברהם","b":"דומ\"צ במונקאטש-תרכ\"ו"},{"i":1090,"n":"אברהם ממוסט","b":"רב במוסט, נכד הרב יאקיל. תשובה אליו בשו\"מ."},{"i":1091,"n":"אברהם ממיטאוי","f":"יואל","b":"מראשי קהלת מיטאוי-תץ, וגבאי ראשון."},{"i":1092,"n":"אברהם ממינדען וברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":1093,"n":"אברהם ממינסק","f":"אריה ליב","k":"בעל משנה ברורה","b":"נכד ר שמואל מאמדור בעל \"תשובת שמואל\". מחכמי מינסק. חיבר פירוש למסכת ברכות בשם \"משנה ברורה והלכה ברורה\" - בכת\"י."},{"i":1094,"n":"אברהם ממינסק","f":"ישעיה","dt":"תרטו - טו חשון","dp":"מינסק","b":"מחכמי מינסק. בנו - ר מאיר צוקרמן."},{"i":1095,"n":"אברהם ממסינה-סיציליה","b":"מחכמי סיציליה-ן'. נזכר בספרי ר אברהם אבולעפיה."},{"i":1096,"n":"אברהם ממצרים","f":"נתן-אב\"ד ירושלים ורמ","b":"דיין ראשון בפוסטאט, חתם ברמלה בשנת ד'תתנו (1056) יחד עם יהושע החבר בן עלי. בשנת ד'תתסב חתם בפוסטאט על תעודה יחד עם ר יהושע החבר בן ר עלי החבר, ועם ר אברהם בן ר שמעיה החבר, נחשב כשני אחר הנגיד."},{"i":1097,"n":"אברהם ממצרים - א","f":"הלל בן צדוק","b":"סופר ופייטן מחכמי מצרים-ד'תתק. מבניו ר שלמה. (יתכן והוא המחבר של מגילת זוטא)."},{"i":1098,"n":"אברהם ממצרים - ב","f":"הלל בן נסים","k":"בעל מגילת זוטא","dt":"ד'תתצקה - אדר","dp":"קהיר","b":"פייטן ומשורר מחכמי קהיר-ד'תתקן. חתם על תקנות הרמב\"ם בשם - אברהם החבר. חיבר מגילת זוטא (נמצאה בגניזה) - ובה מתאר את קורות הנגידות בזמן שלפני הרמב\"ם. כונה בשם שייך אבו אסחאק וכנראה הוא ר אברהם שנזכר בספרו של ר אברהם בן הרמב\"ם (ונמצא בגניזה שחתם עמו על שטר מכירת קרקע)."},{"i":1099,"n":"אברהם ממרוקו","f":"יוסף","b":"מחכמי מרוקו. חתם עם ר שלמה הלוי מצפת-תקמח."},{"i":1100,"n":"אברהם ממרקישוב","f":"יעקב","dt":"תקצו - כ אב","b":"רב במרקישוב,דיין בוורשה"},{"i":1101,"n":"אברהם מנדל מאורזיסטשוב","f":"יעקב יוסף מאורזיסטשו","k":"אדמור מאורזיסטשוב","dt":"תרע - ט שבט","b":"חתן דודו ר מאיר ברונפמן מלובער, ובזיוו\"ש חתן ר יעקב ישראל מזוויהל (זלוטשוב). אדמור באורזיסטשוב על מקום אביו. ביקר בארץ."},{"i":1102,"n":"אברהם מנדל מפוזנא","b":"מחכמי פוזנא. תלמיד בעל \"תרומת הדשן\". כשהתמנה ר משה מהאלא לרב בפוזנא רצה לדחות את ר אברהם וחבריו שנהגו עד אז כרבנים בפוזנא - ופנו לרבם \"תרומת הדשן\" והצדיקם."},{"i":1103,"n":"אברהם מנוברדוק","dt":"תרם","b":"רב בנוברדוק בזמן ר ברוך מרדכי מנוברדוק, נספד ב\"זרע אברהם\" וילנא תרמח."},{"i":1104,"n":"אברהם מנחם הלוי מטריספולי","b":"אב\"ד טריספולי, מ\"מ בקורבא. הסכים על \"תורת משה\" - נאוידואהר תקמו."},{"i":1105,"n":"אברהם מנחם מאניש מסיגט","b":"סופר בסיגט. סופרו של האדמור ר ישראל מויזניץ."},{"i":1106,"n":"אברהם מנחם משלוניקי","dt":"שכז","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":1107,"n":"אברהם מניישטט וירושלים","f":"יקותיאל","dt":"תרכג - יג אד\"ב","dp":"ירושלים","b":"היה דיין בקהילת ניישטאט-שירוינדט ועלה לירושלים."},{"i":1108,"n":"אברהם מנצור מצפת","b":"מחכמי צפת, חתם-תפא על כתב שליחות ר משה ישראל מרודוס."},{"i":1109,"n":"אברהם מנרבונא","f":"יצחק","k":"הראב\"ד השני - האשכול","dt":"ד'תתקיט-כ חשון","b":"תלמיד ר יצחק בן מרן לוי-תלמיד ר יהודה בן משה מנרבונא-תלמיד רבנו גרשום מאור הגולה, תלמיד חבר לר משה בן יוסף, ר יהודה ברזילי ברצלוני. מכונה בפוסקים בשם - ר\"א אב\"ד. ראש ישיבה ואב\"ד בנרבונא-פרובנס (ליד לוניל) בזמן הרבנים: ר משה בן יוסף, ר משה בן טודרוס, ר טודרוס בן משה, גיסו - ר שלמה בנבנשת, ועוד. חותנו של הראב\"ד בעל ההשגות. חיבר ספר האשכול. מתלמידיו: חתנו הראב\"ד בעל ההשגות, ר שמואל בן דוד, ר משה בן יהודה, ר זרחיה הלוי בעל המאור, ר יונתן הכהן, ר שלמיה. חיבר פירוש לש\"ס. (באוצר הגדולים - יש בלבול בשמו - חתנו קרא לו חמי ומכאן נוצרה טעות שחשבו שיש רב בשם רב חמאי גאון שחיבר ספר היחוד וספר העיון - ובאמת הכוונה לראב\"ד בעל האשכול. גם בענין ספר האשכול חל בלבול בגלל גרסאות שונות של הספר ובגלל ספר ממחבר אחר שנקרא באותו השם וראה גם אצל ר צבי בנימין בעל נחל אשכול)."},{"i":1110,"n":"אברהם מנרול","f":"יעקב","dt":"תרב-יא -כג חשון","b":"מגדולי תלמידי ר צבי הירש מזידיטשוב. רב בנארול(=נאהרל). הסכים על ספר רבו \"פרי קודש הללוים\"."},{"i":1111,"n":"אברהם מסטאויסק","k":"בעל אבני זכרון","b":"רב בסטאויסק. חיבר גם \"רשפי קשת\" ובו הספד על ר עקיבא איגר מפוזנא, ר אליהו מקאליש ור שלמה זלמן מיטקטין. (אולי הוא ר אברהם בק מהאליטש)."},{"i":1112,"n":"אברהם מסטניסלב","b":"רב בסטאניסלוב-ת\"צ"},{"i":1113,"n":"אברהם מסטניסלבציק","b":"שו\"ב. תשובה אליו ב\"תפארת צבי\", ו\"האלף לך שלמה\"."},{"i":1114,"n":"אברהם מסלונים","k":"אדמור מסלונים","b":"ראש ישיבה ואדמו\"ר בסלונים-עד ת\"ר"},{"i":1115,"n":"אברהם מסמורה","f":"שלמה","b":"חיבר מאמר על שכר ועונש - בכת\"י."},{"i":1116,"n":"אברהם מסמילוביץ","f":"אשר","b":"רב בסמילוביץ"},{"i":1117,"n":"אברהם מסעזשורץ","b":"דומ\"צ בסעזשורץ-תק\"צ"},{"i":1118,"n":"אברהם מסענזשארץ","b":"רב בסענדזשארץ. נזכר ב\"מראה יחזקאל\", ואולי הוא ר אברהם שטיין שהיה אח\"כ רב בערדא-סענזשארץ."},{"i":1119,"n":"אברהם מסערהיי","f":"יחזקאל","dt":"תקנח - א אייר","b":"חתן ר חנוך זונדל יפה. רב בסערהיי-תקע, לאזדייא. מחותן עם הגר\"א - חתנו - ר יהודה ליב בן הגר\"א."},{"i":1120,"n":"אברהם מספאניא","dt":"שיו - יג אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":1121,"n":"אברהם מספרד","f":"משה","b":"תלמיד הרא\"ש. מחכמי ספרד. נזכר בתשובות הרא\"ש."},{"i":1122,"n":"אברהם מספרד","f":"שלמה","b":"מחכמי ספרד-ד'תתן. תלמידו ר אברהם בן חייא בעל \"צורת הארץ\" מספר שרבו שכנעו לחבר את ספרו על חכמת הכוכבים."},{"i":1123,"n":"אברהם מספרד","f":"נחמיה","b":"רב בפולקירא-ק'. נזכר בשו\"ת הר\"ן."},{"i":1124,"n":"אברהם מספרד","f":"שמחה","b":"פגש את נשיא הכוזרים - דוד, ששלחו לפרס להביא ספרים עבור הכוזרים. בשנת ד'תשמו הגיעו שליח קיוב לפגוש את מלך הכוזרים, ואז נשלח בשליחותו לפרס. לדעת פירקוביץ אולי הוא הפייטן מספרד שכמה מפיוטיו נכנסו למחזור הקראי."},{"i":1125,"n":"אברהם מספרד ואיטליה","f":"יהודה אלימלך","k":"בעל לקוטי שכחה","b":"התישב באיטליה עוד לפני רנב, מחכמי אנקונה-רע בזמן הגירוש והצליח לברוח (נהרגו שם 12 יהודים). חיבר \"לקוטי שכחה\" - פיררה שטז והוא פירוש מאמרים בתלמוד על דרך הקבלה."},{"i":1126,"n":"אברהם מספרד ופולין","f":"יחיאל","dt":"רפב - טו תשרי","dp":"לבוב","b":"ממגורשי ספרד,מחסידי פרובינצא, לאחר גירוש ספרד ופורטוגל הגיע לפולין והיה רב ומרביץ תורה בלבוב-רנח."},{"i":1127,"n":"אברהם מסקווירא","f":"אהרן מטיטיוב","b":"נינו של הבעשט. לאחר שנתייתם גדל אצל גיסו ר ברוך ממז'בוז'-נכד הבעשט. חתן גיסו (בעל אחותו שנפטר) ר צבי מקוריסטשוב. חתנו - ר שלמה מסאווראן על מקומו אחריו (חסידיו של ר אברהם עברו אליו). בניו ר אהרן ור ברוך."},{"i":1128,"n":"אברהם מסראטיני (סרקטיני)","b":"מחכמי איטליה-ר'. חיבר קונטרס בענין שנאת נשים ושיר בשם \"שונא הנשים\" כנגד ר אברהם מפאנו שחיבר קונטרס בענין אהבת נשים, ור אליהו חיים בעל \"אגרת חמודות\" קונטרס אגרת מליצה לפשר ביניהם - הכל בכת\"י, ור אביגדור מפאנו השיב לו גם הוא."},{"i":1129,"n":"אברהם מסרדיניה","b":"נזכר בדברי הימים לרומים שבשנת ד'תר מצא עם חברו חקיקות עמוקות באבנים בסרדיניה שהן ראשית דברי הימים ליושבי הארץ ההיא."},{"i":1130,"n":"אברהם מסרייבו וירושלים","dt":"תרלא - ח אלול","b":"ר\"מ וראב\"ד בשאריי-בושנה,עלה לירושלים"},{"i":1131,"n":"אברהם מעיר חדש","f":"שלמה זלמן","b":"רב בחדש,שילעל(=שילאל)-תר, שיקאגו."},{"i":1132,"n":"אברהם מעכו","f":"יחיאל","b":"מחכמי עכו, חתם עם חכמי עכו על הסכמה לר אברהם בן הרמבם בשנת ד'תתקצד (1234). יתכן שאביו הוא ר יחיאל בן יצחק הצרפתי שמיוחס לו \"עלה רענן\" ברפואה."},{"i":1133,"n":"אברהם מפאנו","b":"רב באיטליה-רן - ש'. חיבר קונטרס בענין אהבת נשים, וכנגדו חיבר ר אברהם מסרקעטני (סראטיני) קונטרס בענין שנאת נשים, ור אליהו חיים בעל \"אגרת חמודות\" קונטרס אגרת מליצה לפשר ביניהם - הכל בכת\"י."},{"i":1134,"n":"אברהם מפאס","b":"דיין בפאס-ש\"כ"},{"i":1135,"n":"אברהם מפאס","f":"יעקב","b":"מחכמי אפריקה-ד'תשן."},{"i":1136,"n":"אברהם מפודולסק","k":"בעל חסד לאברהם","b":"תלמיד הבעשט ונפטר בחיי הבעשט - שטיפל בו בזמן מחלתו. רב בפודולסק, ובשדה לבן."},{"i":1137,"n":"אברהם מפוזנא - א","f":"שלמה","b":"רב בפוזנא-שן. חתם עם 30 רבנים על איסור לקנות רבנות בכסף."},{"i":1138,"n":"אברהם מפוזנא - ב","b":"דיין בפוזנא-ת\"ח. בנו ר חנוך הניך מאיטינגא ופוזנא בעל \"ויכוח יוסף והשבטים\"."},{"i":1139,"n":"אברהם מפולין","b":"מחכמי פולין-רן. בתה\"ד יש תשובה ממנו באמצעות בנו ר פתחיה."},{"i":1140,"n":"אברהם מפולין","f":"ברוך מארץ יוון","b":"חתן היעב\"ץ."},{"i":1141,"n":"אברהם מפומורן","f":"משה אהרן","dt":"תקכג - כד חשון","b":"רב בפומורן"},{"i":1142,"n":"אברהם מפונטישא","b":"מתורתו ב\"אורחות חיים\", ו\"כלבו\"."},{"i":1143,"n":"אברהם מפושקיירא ונרבונא","f":"דוד","k":"הראב\"ד בעל ההשגות","bt":"ד'תתפ","dt":"ד'תתקנט-כו כסלו","b":"תלמיד ר משלם הזקן, ר משה בן יוסף מנרבונא, ר משלם בן יעקב, ר יוסף בן פלט. חתן ר אברהם מנרבונא בעל האשכול. מגדולי הראשונים, פוסק דורו, רב וראש ישיבה בנרבונא, נמשי(=ניעמש), פושקיירא (המכונה קרית יערים), מונטפלייר, היה עשיר והחזיק את הישיבה בכספו. חיבר גם \"בעלי הנפש\", ועוד. בניו ר יצחק סגי נהור, ר דוד. ומצאצאיו הרב המאירי. מתלמידיו: ר יצחק הכהן-רבו של ר ראובן בעל התמיד, ר אשר בן שאול בעל המנהגות, ועוד, ר יהודה בן אברהם, ראב\"ן הירחי, ר מאיר בן יצחק מטרנקטילה, ר יונתן הכהן מלוניל, ועוד."},{"i":1144,"n":"אברהם מפטרבורג","b":"תלמיד ר נחמן מברסלב, וכותב תורתו לפני בואו של ר נתן מנמירוב."},{"i":1145,"n":"אברהם מפיזרו","b":"מגדולי הראשונים-ה'ל'"},{"i":1146,"n":"אברהם מפליסקוב","dt":"תרלא - כו כסלו","dp":"טבריה","b":"תלמידו של ר דוד שלמה אייבשיץ מסורוקא בעל \"לבושי שרד\""},{"i":1147,"n":"אברהם מפפד\"מ","f":"אליקים","b":"מחכמי פפד\"מ. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":1148,"n":"אברהם מפרג","f":"שלמה יעקב","dt":"שע - י ניסן","b":"רב בפרג"},{"i":1149,"n":"אברהם מפרג","b":"רב בפרג-ק\"ס. חיבר הגהות לטור"},{"i":1150,"n":"אברהם מפרג","f":"שמעון מיכל מפרשבורג","b":"בנו של ראש היהודים מפרשבורג. מראשי קהלת פרג."},{"i":1151,"n":"אברהם מפרהובישט","f":"שלום שכנא מפרהובישט","bt":"תקמז","dt":"תקעג - יז אדר","b":"נינו של המגיד ממזריטש, אחיו של האדמור ר ישראל מרוז'ין וגדלו אחר פטירת אביהם. חתן ר יוסף משה מקרוסנא, ובזיוו\"ש חתן הרב קבלינסקי. אדמור בפרהובישט על מקום אביו, נפטר צעיר ללא ילדים. מתורתו ב\"עירין קדישין\"."},{"i":1152,"n":"אברהם מפרובנס","f":"יהודה","b":"רב באלרדי-פרובנס. חתם על פסק-סה עם חבריו, והובא בשו\"ת ר\"י דלטאש. וחתם - אברהם בן יהודה בן יהודה ישי - והשם יהודה ישי הוא שם משפחה וישי הוא ר\"ת יבוא שלום ינוח על משכבו בשלום."},{"i":1153,"n":"אברהם מפרובנס","f":"ראובן מנרבונא","b":"מחכמי נרבונא-ה'א. בנו - ר לוי בעל \"לוית חן\"."},{"i":1154,"n":"אברהם מפרובנס","f":"חיים","b":"מחכמי פרובנס - תחילת האלף ה-שישי. חיבר פיוט לפרשת פרה - במחזור אויניון וקרפנטרץ. אולי בנו - ר לוי בעל \"לוית חן\", ואולי הוא הנזכר במאירי לאבות."},{"i":1155,"n":"אברהם מפרובנס","b":"מחכמי פרובנס, פיוט ממנו במחזור \"אספרה אל חוק\". אביו של ר גרשון וזקנו של הרלב\"ג."},{"i":1156,"n":"אברהם מפרובנס","f":"יוסף","b":"תלמיד הראב\"ד בעל ההשגות, מחכמי פרובנס-ד'תתקן, עלה לארץ. הראב\"ד כתב כי חיבר את ספר המצוות לר אברהם ולר אשר בן שאול."},{"i":1157,"n":"אברהם מפרובנס","f":"חיים","b":"מחכמי בדרש-פרובנס-ד'תתקטו, ראב\"ע חיבר לכבודו ולכבוד חברו ר יצחק בן יהודה את ספרו \"ספר השם\", נזכר אצל המאירי וב\"שערי ציון\", מתורתו ב\"ספר השלמה\" לנזיקין\". (לא נזכר במסעות ר בנימין מטודלה שביקר בבדרש-ד'תתקל)."},{"i":1158,"n":"אברהם מפריס","b":"תלמיד ר\"ת ונזכר בספר הישר יחד עם חבריו ר יחיאל ור אליעזר בן יהודה בן יו\"ט, ותלמיד הרשב\"ם ונזכר ב\"שבולי לקט\"."},{"i":1159,"n":"אברהם מפרירה","b":"מחכמי מעהרן-שן, נזכר בשו\"ת הרמ\"א."},{"i":1160,"n":"אברהם מפרמישלא","f":"מרדכי מרישא","k":"בעל פתח האהל","b":"רב בפרעמיסלא-ת\"מ"},{"i":1161,"n":"אברהם מפרנקפורט","k":"ר' אברהם מהנובר","b":"רב בפרנקפורט-שנת ק'"},{"i":1162,"n":"אברהם מפרס","f":"בצלאל","dt":"תפח - א סיון","dp":"אזמיר","b":"הגיע מפרס, ונפטר באזמיר."},{"i":1163,"n":"אברהם מפרצובה","b":"רב בפרצובה"},{"i":1164,"n":"אברהם מפרשבורג","f":"אהרן יונה","b":"דיין בפרשבורג-רמח - במינוי זמני של ר אליקים בן קלונימוס, ודן בענין כתובת אלמנה."},{"i":1165,"n":"אברהם מפשטניזין","f":"מנחם","dt":"תקעה","b":"רב בפטשניזין."},{"i":1166,"n":"אברהם מצור","f":"שבתי","b":"מחכמי צור בשנת ד תתנא (1091), מצור הגיע למצרים והיה דיין בקהילת מיניה-זיפתה"},{"i":1167,"n":"אברהם מצפת","k":"בעל גלי רזיא","b":"מקובל בצפת, תלמיד האר\"י-שס."},{"i":1168,"n":"אברהם מצפת","f":"אברהם","k":"בעל נאדר בקודש","b":"שליח לעצמו מצפת, הדפיס באמשטרדם בשנת תפג את הספר \"נאדר בקודש\""},{"i":1169,"n":"אברהם מצפת","f":"חנניה","k":"בעל בית אברהם","bt":"שמה-סה","bp":"שלוניקי","dt":"תל","dp":"עזה - חברון או ירושלים","b":"תלמיד מהרימ\"ט בקושטא, (ולדעת בניהו היה סופרו), חברו של ר יהודה שאראף. מקובל בשלוניקי, קושטא, רב בבלגרד בזמן ר שמחה הכהן. בשליחות קהלת צפת-תי בטורקיה, בשנת תיד התישב בצפת ואחר כך עבר לירושלים-תיז, רב ברמלה-תכג, עזה (ברח מחברון בגלל המגפה ונפטר שם). לדברי רוזניס בהיותו בעזה גנב ממנו נתן העזתי ספר כת\"י בקבלה. חתום על אגרת ר ברוך גד מעשרת השבטים. חתום על תשובות ואגרות שונות, בשנת תכג ברח לרמלה, על כך בספר \"גט פשוט\" לר משה בן חביב, וכן בספר \"משפטי צדק\" לר שמואל גרמיזן. חיבר ספרים בכתב יד (רובם אבדו) וביניהם \"בית אברהם\" הנמצא בספריה הלאומית. חתנו - ר משה הלוי הנזיר מחברון. (אצל רוזניס מופיעים תאריכים שונים ותאריך פטירתו - תפד? כנראה טעות)"},{"i":1170,"n":"אברהם מצפת","f":"רחמים","dt":"תקצז","dp":"צפת","b":"מחכמי צפת, חתם על אגרת שליחות לאיטליה, נהרג ברעש בצפת"},{"i":1171,"n":"אברהם מצפת","f":"אשר","dt":"תקלג - כסלו","b":"רב הכולל בצפת. נפסד מאת ר רפאל אליעזר נחמיאש בשלוניקי."},{"i":1172,"n":"אברהם מצרפת","b":"תלמיד הרשב\"ם ומובא במרדכי וב\"שבולי לקט\"."},{"i":1173,"n":"אברהם מצרפת","f":"יהודה","b":"מובא בתוספות - כנראה דודו של הר\"י בעל התוספות."},{"i":1174,"n":"אברהם מצרפת ומצרים","b":"נזכר אצל ר אברהם בן הרמב\"ם - שהגיע מצרפת והוא אביהם של רבנו גרשום, ר יוסף, ור דוד."},{"i":1175,"n":"אברהם מקאבלין","f":"ישראל ורעשנא מקאבלין","b":"רב בקאבלין, וועלין(=וילען)-ליד פוזנא-תקף על מקום אביו. אחיהם של ר משה מלובלינץ וליסא, ור שאול מטומשוב."},{"i":1176,"n":"אברהם מקאליש","f":"יהודה","b":"רב בקאליש-תנ\"ח"},{"i":1177,"n":"אברהם מקאמאהרין","b":"אב\"ד קאמאהרין. נזכר בשו\"ת החת\"ס."},{"i":1178,"n":"אברהם מקולבסוב","b":"רב בקולבסוב - תשובה אליו ב\"משיב שלום\"-תרפה."},{"i":1179,"n":"אברהם מקולומיא","f":"יוסף","dt":"תכד - ח אייר","dp":"לבוב","b":"ר\"מ בקולומיא. נהרג עק\"ה בלבוב."},{"i":1180,"n":"אברהם מקופנהגן","f":"צבי הירש","b":"רב בקופנהגן-תקם. הסכים על \"משנת דרבי אליעזר\" - אלטונא תקעה, \"קול יעקב\" - המבורג תקסה."},{"i":1181,"n":"אברהם מקוריסטשוב","f":"צבי הירש מקוריסטשוב","b":"חתן ר מנחם נחום מטשרנוביל. רב בקרטשוב(=קורסיטשוב)-תקפ. בנו - ר אריה ליב מסדילקוב. חתנו - ר שלום שכנא."},{"i":1182,"n":"אברהם מקושטא","f":"יצחק אסא","b":"רב בקושטא-תצ\"ג. חיבר ותרגם ספרים בלדינו."},{"i":1183,"n":"אברהם מקושטא","k":"ר' אברהם הירושלמי","bt":"רל","dt":"של","b":"רב בקושטא"},{"i":1184,"n":"אברהם מקושטא","f":"ידידיה","b":"מדפיס אצל אברהם פרנקו תח."},{"i":1185,"n":"אברהם מקושטא","f":"יצחק - דברי אמת","b":"רב בקושטא-שנות ה-תק."},{"i":1186,"n":"אברהם מקושטא","f":"שמואל יהודה","b":"דיין בקושטא-תקיא אצל ר מאיר יצחקי עם ר אליעזר משה הכהן, עלה לירושלים. חתם על מינוי ר אליקים גירון לרב באדרינופול."},{"i":1187,"n":"אברהם מקושטא","f":"דוד","b":"דיין בקושטא-תקסו עם ר שמואל חיים ור יוסף בן שאלתיאל."},{"i":1188,"n":"אברהם מקושטא ואזמיר","f":"יהודה ליב","b":"מדפיס אצל ר יונה בן יעקב אשכנזי בקושטא-תע, ועבר עם הדפוס לאזמיר-תצג."},{"i":1189,"n":"אברהם מקיורו","f":"משה","dt":"תחדהו","b":"מחכמי איטליה"},{"i":1190,"n":"אברהם מקיטוב","f":"יוסף","dt":"תקע - כט שבט","b":"רב בקיטוב"},{"i":1191,"n":"אברהם מקירואן","f":"נתן עטא","b":"פייטן, משורר, רב בקירואן-ד'תשן-ד'תת, בזמן ר יהודה בן יוסף, ור יעקב בן עמרם על מקומו אחריו. יתכן והוא אביו של ר נתן בן אברהם שעלה מקירואן לירושלים והיה בר פלוגתיה של רב שלמה בן יהודה גאון ארץ ישראל."},{"i":1192,"n":"אברהם מקסטריא","f":"יעקב","b":"פייטן, פיוטים של במחזור בני רומניא. חיבר קינות ובהם \"ציון אשר אמרו\"."},{"i":1193,"n":"אברהם מקפואה","b":"רב בקוש-עדאסי-תכא."},{"i":1194,"n":"אברהם מקראקא","f":"שמואל אנשילס","dt":"תקעח-ג בכסלו","b":"דיין בקרקא"},{"i":1195,"n":"אברהם מקראקא","f":"ישעיה מנדל ר אביגדור","dt":"תח","dp":"קראקא"},{"i":1196,"n":"אברהם מקרים","f":"אפרים - דת יהודית","dt":"תרפד - טז שבט","dp":"ירושלים","b":"רב בקרים, חזר לירושלים."},{"i":1197,"n":"אברהם מקריפטש","b":"רב בקריפטש-ת\"ר"},{"i":1198,"n":"אברהם מקרלין","b":"נסע לא\"י ונפטר שם"},{"i":1199,"n":"אברהם מקרפנטרץ","f":"יצחק","b":"מחכמי פרובנס-קן בזמן הרשב\"א פייטן ומשורר. נזכר בתשובת ר\"י דלטאש - שבאה להצדיק את ר יצחק הכהן ממנשקואה שהיה במחלוקת עם רבנו ברוך - שנת סה. נזכר בשירו של ר אברהם בדרשי \"חרב המתהפכת\"."},{"i":1200,"n":"אברהם מראגולה-אחי הגר\"א","f":"שלמה זלמן מוילנא","k":"בעל מעלות התורה","dt":"תקסז - ז ניסן","dp":"עיר חדש","b":"אחיו של הגר\"א. רב בקרוז', מגיד מישרים בשקלוב-תקן, בגלל מחלוקת עם החסידים עבר לראגולה. ומתלמידיו שם ר אליהו מראגולה (ר אלינקע ראגולער). עבר אל בנו ר אליהו בניישטאט-טאווריג. חיבר גם פירוש למסכת מגילה על דרך הקבלה, ועוד. (מסופר כי עזב את קרוז' לאחר שר אליהו בן מאיר-גיסו של הגר\"א קיבל את הכיבוד הראשון בשמחת תורה במקומו). בניו: ר גרשון משאדובה בעל עבודת הגרשוני, ר אליהו אב\"ד ניישטוט-טאווריג, ר משה החסיד מקיידאן, ר שמואל אב\"ד שאט."},{"i":1201,"n":"אברהם מראטין","b":"אב\"ד ראטין. הסכים על \"יסוד יצחק\" - זולקווא תקע."},{"i":1202,"n":"אברהם מראסיין","f":"שלמה","dt":"תקע","dp":"ראסיין","b":"מחכמי כפר סיאין-ליד ראסיין. חברו של ר שמואל חסיד מראסיין. חתנו - ר יחיאל מיכל מוידוקלא. נכדו - ר אברהם חריף מפיקעלין."},{"i":1203,"n":"אברהם מראקיץ","b":"תלמיד ר יעקב פופרש מפרג ופפד\"מ. גיסו של ר ישעיהו בסאן-רבו של הרמח\"ל."},{"i":1204,"n":"אברהם מרגנשבורג","f":"עזריאל","k":"בעל ערוגת הבושם","b":"תלמיד ר יהודה החסיד, ר ברוך בן שמואל ממגנצא, ר אלעזר בעל הרוקח. רב מזקני ביהם-ד'תתק\"צ, מבעלי התוספות, מגדולי חכמי רגנשבורג. חיבר פירוש לפיוטים \"ערוגת הבושם\". חישב את זמן הגאולה - קיב."},{"i":1205,"n":"אברהם מרגנשבורג","b":"מגדולי בעלי התוספות בחכמי אשכנז-שנת ה'כ'"},{"i":1206,"n":"אברהם מרדכי מארה\"ב","b":"גביר נדבן במונטגומרי-אלבמה, הגיע מפנסילבניה והיה מיסד הקהלה היהודית במונטגומרי."},{"i":1207,"n":"אברהם מרדכי מוילנא","f":"שבתי","b":"גבאי ישיבת מייליס בוילנא. חתם על כתב התמנות ר ישראל סלנטר לראש הישיבה, על מקום ר מרדכי מלצר."},{"i":1208,"n":"אברהם מרדכי מטריקאלה","b":"רב בטריקאלה-שצג."},{"i":1209,"n":"אברהם מרדכי מלויצק","k":"בעל תורת חסד","b":"תלמיד ר אברהם יהושע השל מאפטא."},{"i":1210,"n":"אברהם מרוהטין","f":"יקותיאל זלמן","dt":"תרו - כז טבת","b":"רב ברוהוטין"},{"i":1211,"n":"אברהם מרוטנברג","b":"מהראשונים-שנת ה'מ'"},{"i":1212,"n":"אברהם מרוטרדם","b":"רב ברוטרדם. בנו ר יעקב רוטרדם."},{"i":1213,"n":"אברהם מריוויץ","b":"הניח כת\"י ובהם מביא הרבה מתורת החוזה מלובלין."},{"i":1214,"n":"אברהם מרמון-גרנדה","f":"יצחק","k":"בעל ספר הברית","b":"רב ומקובל ברמון היא גרנדה-ספרד, חברו של הרמב\"ן, תלמיד ר יצחק בן הראב\"ד. חזן מפורסם והרמב\"ן התיחס לתפילתו, נזכר גם אצל ר משלם מקאפירה. חיבר חיבר ספר \"הברית\", \"ברית מנוחה\" (והוא שונה מהספר שנדפס אח\"כ ואולי הוא ספר אחר) ובו מביא קטעי זהר שאינו בזהר שבידינו. (י\"א שהספר חובר בידי ר הראב\"ד בעל האשכול\" וי\"א שהוא מידי רב חמאי גאון)."},{"i":1215,"n":"אברהם מרמלה","f":"יצחק","k":"יסוד הישיבה (ברמלה)","b":"בשנת ד'תתיז 1057 עמד בראש הישיבה ברמלה"},{"i":1216,"n":"אברהם מרמלה","f":"שמואל בן הושענא","b":"דיין ברמלה-ד'תשן. מכתב ממנו אל ר אברהם הכהן בן יצחק שיק, ונוסח גט שסידר-ד'תרצה והיה גם עד וגם סופר - כמנהג בבל."},{"i":1217,"n":"אברהם משה","f":"יצחק לזדונר","b":"רב בראקוב"},{"i":1218,"n":"אברהם משה אלימלך מלובלין","f":"יצחק","dt":"תקמח - טז תמוז","dp":"לובלין","b":"מחכמי לובלין ומלמד תורה. חתם על אישור צוואה של ר יעקב אברהם קצנלנבוגן לטובת ביהכ\"נ ר צבי הירש בן משה דאקטאר."},{"i":1219,"n":"אברהם משה הגדול מפשוורסק","f":"צבי הירש","k":"משה פשוורסקר הראשון","dt":"תקנד - ט חשון","b":"רב בפשוורסק. ידידו של משה פשוורסקר השני. תלמיד המגיד ממזריטש ורבו של החוזה מלובלין, ורבו של ר צבי הירש מרימנוב בנערותו. מחותן עם הנועם אלימלך. הסכים על ספרים רבים. יש הרושמים פטירתו - יב טבת."},{"i":1220,"n":"אברהם משה מאוסטרהא","b":"רב באוסטרהא"},{"i":1221,"n":"אברהם משה מאזמיר","b":"מדפיס באזמיר-תק אצל המדפיס הארמני אוסטה מארגוס."},{"i":1222,"n":"אברהם משה מבראהילוב","f":"אשר סגל","k":"בעל מים קדושים","b":"רב בפיקוב, פרקולי, בראהילוב. ביקר אצל ר ברוך ממזבוז. בספרו מביא מתורת המגיד ממזריטש."},{"i":1223,"n":"אברהם משה מלאזדיי-ליטא","dt":"תקפה","b":"רב בלאזדיי, על מקום ר אברהם צבי בעל \"דברי הברית\"."},{"i":1224,"n":"אברהם משה ממרקישוב","b":"אדמו\"ר בלובלין"},{"i":1225,"n":"אברהם משה מפטשניזין","f":"שואל","dt":"תקצז","b":"רב בפטשניזין"},{"i":1226,"n":"אברהם משה מפשיסחא","f":"שמחה בונם מפשיסחא","k":"אדמור מפשיסחא","r":"בן רבי שמחה בונים","bt":"תקס","dt":"תקפט-ב טבת","b":"חתן ר שמואל רפאל'ס-חתן היהודי הקדוש מפשיסחא. אדמור בפשיסחא (לחלק מחסידי אביו)-תקפז - נפטר אחרי שנתיים."},{"i":1227,"n":"אברהם משה עובדיה מירושלים","b":"מחכמי קיוסטנדיל, עלה לירושלים, וחזר לקיוסטנדיל. חתם-תקסב על תקנת בתי הכנסת."},{"i":1228,"n":"אברהם משוטלסדורף","b":"אב\"ד שוטלסדורף. נזכר בשו\"ת החת\"ס."},{"i":1229,"n":"אברהם משטיפי","f":"יצחק","b":"מראשי קהלת שטיפי-שנות ה-ר'-ש'."},{"i":1230,"n":"אברהם משטיפי","f":"שמואל","b":"מראשי קהלת שטיפי שנות ה-ר'-ש'."},{"i":1231,"n":"אברהם משימאנרע","b":"אב\"ד שימאנרע. נזכר בשו\"ת החת\"ס."},{"i":1232,"n":"אברהם משיראד","f":"משה","b":"אב\"ד שיראד? הסכים על \"ערוגות הבשם\" - קניגסברג תרך."},{"i":1233,"n":"אברהם משירדז","b":"רב בשירדז-תר\"י"},{"i":1234,"n":"אברהם משלוניקי","f":"אליעזר שלום","b":"מחכמי שלוניקי, ומחותמי ה\"הסכמות\"-שנות הר'-ש'."},{"i":1235,"n":"אברהם משלוניקי","f":"דוד נחמן","b":"מחכמי שלוניקי, קושטא. מדפיס-תעג ומגיה, הגיה גם את \"דבר משה\"-תקג. אולי אביו של המדפיס ר מרדכי נחמן."},{"i":1236,"n":"אברהם משלוניקי","f":"נתן","dt":"תפה","b":"גביר בשלוניקי ויסד ישיבה בק\"ק \"סיציליה\", עבר לרישיד."},{"i":1237,"n":"אברהם משלוניקי","f":"שמואל הרופא בן פרחיה","dt":"רעה - ח אייר","dp":"שלוניקי","b":"נכד ר פרחיה הכהן, ואחיינו של הרופא פרחיה הכהן."},{"i":1238,"n":"אברהם משלוניקי","f":"יצחק שלום","b":"מדפיס בשלוניקי אצל אברהם בן דוד נחמן ויום טוב קאנפיליאש-תע."},{"i":1239,"n":"אברהם משלוניקי - הנכד","f":"יצחק","dt":"תפט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":1240,"n":"אברהם משלם מפדובה","f":"משלם הלוי","b":"מחכמי פדובה. הניח כל נכסיו לעניי ירושלים ופדובה ולבית הכנסת בפדובה !(מופיע בספר זכרון פדובה)."},{"i":1241,"n":"אברהם משעביז","b":"רב בשעביז,פרייל"},{"i":1242,"n":"אברהם משפטיבקה","b":"רב בשפטיבקה-תר\"מ"},{"i":1243,"n":"אברהם משפיירא","f":"שמואל החסיד בן קלוני","b":"אחיו של ר יהודה החסיד בעל ספר חסידים. תלמיד הריב\"א בשפיירא. מגדולי הראשונים פייטן וחיבר קינות, רב בשפירא-ד'תתקל. שאלה ממנו בראב\"ן. תלמידיו: ריב\"ק ממגנצא, ריב\"ק משפיירא, בעל הרוקח, ר שמחה משפיירא. קינה שחיבר \"אמרות ה' נחמות\"."},{"i":1244,"n":"אברהם משקלוב","f":"שאול משקלוב","k":"בעל גאון אברהם","b":"רב בשקלוב-תקס. חיבר חדושים על הש\"ס בשם \"שני המאורות\" ומהם נדפס חלק אחד בשם \"גאון אברהם\" - אודסה תרכד."},{"i":1245,"n":"אברהם מתורכיה","f":"יום טוב","b":"מחכמי טורקיה"},{"i":1246,"n":"אברהם מתורכיה","f":"שמחה","b":"מחכמי טורקיה, חיבר הגהות לטור(הובאו בספר \"בית יוסף\""},{"i":1247,"n":"אברהם מתורכיה","f":"דוד","b":"מחכמי האשכנזים בתורכיה, חיבר פירוש על \"מערכת אלוקות\" לרבינו פרץ-רכב עבור תלמידו ר יצחק בן שבתי."},{"i":1248,"n":"אברהם מתימן","f":"שלמה","k":"בעל פירוש לתנך","b":"מגדולי חכמי תימן-ר'. חיבר פירוש לתנך. פגש את ר שמריה בן אליהו אקרוטאי מיון (יתכן שביקר ביון)."},{"i":1249,"n":"אברהם מתימן","f":"שלמה","k":"בעל מדרש אלצאני","b":"מחכמי תימן-ן'. חיבר מדרש אלצאני."},{"i":1250,"n":"אברהם מתתיהו מאוסטרהא","f":"משה","bp":"פינסק","dt":"תקיט - טו כסלו","dp":"אוסטרהא","b":"הגיע מפינסק לכהן כרב ודיין באוסטרהא. פרנס וגביר. חתם על תקנה-תקה בהסכמת הרב ר אברהם משולם זלמן. בנו ר יהודה ליב דיין באוסטרהא."},{"i":1251,"n":"אברהם מתתיהו מיליסוטגרד","f":"ר\"י","b":"פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז."},{"i":1252,"n":"אברהם ן פראת מטבריה","b":"מחכמי טבריה בשנים ד תקלה-תקפה (775-825), כלול ברשימת חכמי המסורה שפרסם מאן בספרו ח\"ב 44."},{"i":1253,"n":"אברהם ן ריקאת מטבריה","b":"מחכמי טבריה ומבעלי המסורה בשנים ד תקלה (775) - תקפה (825)"},{"i":1254,"n":"אברהם נחמיה מביירות","b":"דיין בביירות-תלד עם ר יוסף הכהן אשכנזי ור מרדכי נחמיאש."},{"i":1255,"n":"אברהם נחמן משלוניקי","b":"מגיה בדפוס בצלאל הלוי אשכנזי בשלוניקי-תקב."},{"i":1256,"n":"אברהם נפתלי הרץ הלוי מפפד\"מ","k":"בעל הגהות למהריל","dt":"שנט - כב תמוז","b":"רב בפפד\"מ על מקום ר אליעזר טריווש, ומחותנו ר שמואל מפרידברג על מקומו אחריו. חיבר הגהות למהרי\"ל. חידש את התקנה יחד עם ר אשר אנשל בן שמעון הכהן - וקבעו שאין אפשרות לחכמים מחוץ לפפד\"מ להטיל תקנות או חרמות על יהודי פפד\"מ - אלא יש לפנות אל ביה\"ד המקומי. מחותן עם ר שמואל בן אליעזר מפרידברג, וחתניו האחרים ר זליגמן מפפד\"מ, ור אהרן דודלסהים."},{"i":1257,"n":"אברהם נתן מרשיד-מצרים","f":"נתן","bp":"קושטא","b":"גביר ברשיד-מצרים. הקדיש מכספו להקמת ישיבת \"חסד לאברהם\" בירושלים-תקז בראשות ר דוד פארדו. סייע בהדפסת הספרים - \"גט פשוט\", \"שיורי כנסת הגדולה\", ועוד."},{"i":1258,"n":"אברהם נתן משלוניקי","dt":"תקיז","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":1259,"n":"אברהם סגי נהור מריזאן","b":"רב בריזאן-תר\"כ"},{"i":1260,"n":"אברהם סגל מה\"פ","b":"אב\"ד ה\"פ?. נזכר בשו\"ת החת\"ס."},{"i":1261,"n":"אברהם סגל מוילנא","b":"רבה הראשון של וילנא ואגפיה - לפני שעז ור מנחם מאנוש חיות על מקומו אחריו. תלמיד גיסו (אחי אשתו) - של ר יצחק קצנלנבוגן בעל \"תולדות יצחק\" - המזכירו בספרו (ר יצחק היה חתן ר יחיאל לוריא - בנו של ר יחיאל לוריא?)."},{"i":1262,"n":"אברהם סגל מטיסמניץ - א","f":"יוסף","k":"אברהם ר יוספש","b":"ראש מדינה בטיסמניץ, חתם-תן על תקנות קהלת זולקווא שנתקנו בקוליקוב - יחד עם רבני לבוב. בנו - ר יוסף - חתן ר מנחם מנדל מרגליות, ר שמואל?, ונכדו ר מרדכי-ראש מדינה בטיסמניץ. חתנו - ר ישראל בן מנחם מנדל שטנגן-מרגליות (לפי אוצר הרבנים ר ישראל היה חתנו של ר אברהם). מצאצאיו - ר אברהם מטיסמניץ."},{"i":1263,"n":"אברהם סגל מסטנוב ולבוב","b":"מראשי קהלת לבוב, חתם-תקלז על תקנה."},{"i":1264,"n":"אברהם סגל מקראקא","f":"יוסף","k":"בעל חדושי מהר\"א","b":"מחכמי קראקא. חיבר פירוש למגילת תענית בשם - \"פירוש מהרא\"ה, חדושי מהרא\"ה. רב בפולין בשנים תח-תטז - בזמן הפרעות שם - וניצל. חיבר גם פירוש לתורה ולמסכת תענית - בכת\"י."},{"i":1265,"n":"אברהם סופר מפרג","k":"בעל ברית אברהם","b":"חיבר ספר על חכמת החשבון בשם \"ברית אברהם\" נדפס בפרג."},{"i":1266,"n":"אברהם סנגיל מירושלים","f":"יהודה","k":"בעל מאירת עינים","b":"חיבר בירושלים-קמג \"מאירת עינים\"."},{"i":1267,"n":"אברהם עבריל מלבוב","f":"שמעיה","b":"חתם-תטו עם ר אברהם בן גרשון מייזלש."},{"i":1268,"n":"אברהם עובדיה הספרדי משלוניקי","dt":"רפט","b":"ממשפחה שגלתה מספרד-קנא, התישב בארטא-יוון. היה מקורב לר בנימין שמריה שהתיעץ עמו בהלכה. נזכר בשו\"ת בנימין זאב, ובשו\"ת מהרשד\"מ כר אברהם ספרדי מארטא. נפטר ללא ילדים."},{"i":1269,"n":"אברהם עלי הכהן","b":"אין פרטים."},{"i":1270,"n":"אברהם עקיבא מטריאנוב","f":"מנחם מנדל","b":"אב\"ד טריאנוב. הסכים על \"משנה תורה\" לרמב\"ם - ברדיטשוב תקעח."},{"i":1271,"n":"אברהם עקרין מלבוב","f":"שמריה עבריל","dt":"תכא-מא - יג טבת","dp":"לבוב","b":"דיין בלבוב. חתם-שצד על העתקה מפנקס ועד ארבע ארצות עם ר ראובן בן זליג ור יעקב יעקל במהר\"ם מלבוב, חתם-תיג עם חבריו על פס\"ד, חתם-תטו על שטר עם ר מרדכי מודל בן מנחם ור אברהם בן גרשון מייזלש. הסכים על תנ\"ך - אמשטרדם תמז. (לפי בובר נפטר תמא ובטעות נרשם במצבה תכא)."},{"i":1272,"n":"אברהם פישל בן צבי מלבוב","f":"אפרים פישל בן צבי","dt":"תיג","b":"אצל בובר נכתב בטעות אברהם פישל אבל צריך להיות אפרים פישל"},{"i":1273,"n":"אברהם פישל מצפת","b":"בשליחות קהלת צפת-תקל-תקם בערך בהולנד."},{"i":1274,"n":"אברהם פנחס מצפת","f":"שלמה זלמן הכהן מוילנ","dt":"תקצז","dp":"צפת","b":"נכד ר משה סגל מהארקי-מצד אמו. נתייתם בגיל 3, נספה ברעש בצפת-תקצז, אשתו נצלה ונפטרה אחרי תרכו. בנו ר אלעזר הכהן חי בשנים תקפט-תרנד."},{"i":1275,"n":"אברהם פרנס מוילנא","f":"חיים נחמן פרנס מוילנ","bt":"תקעה - א אד\"א","dt":"תרמג - א אד\"א","dp":"וילנא","b":"חתן הגביר ר יצחק איזיק עליאשברג מאיוועניץ, ובזיוו\"ש חתן הגביר ר חיים רוטנר. גביר מחכמי וילנא ופרנס כאביו לפניו. נשיא צדקת ארץ ישראל יחד עם ר מתתיהו שטרשון. נפטר ביום הולדתו. בניו: ר יצחק איזיק - חתן ר שלום יחזקאל לוריא-בן ר דוד ביחווער - נפטר בטו אב תרלב בדובנא, ר ליבעלע - חתן הגביר ר מרדכי צבי מרשלקוביץ מדובנא - נפטר ב א כסלו תרלו במינסק, ר יעקיל פרנס בוילנא."},{"i":1276,"n":"אברהם פרנס מלובלין - א","dt":"תקך - יז טבת","dp":"לובלין","b":"מחכמי לובלין. פרנס בועד ארבע ארצות."},{"i":1277,"n":"אברהם פרנס מלובלין - ב","f":"חיים מלובלין","k":"ר אברהם ר חיימש","dt":"תקכג - טו חשון","dp":"לובלין","b":"נכד(-אבי אמו) ר בנימין וולף הלפרין-נכדו המהר\"ם מלובלין. חתן ר יוסף אב\"ד אפאטשנע. מחכמי לובלין ופרנס ועד ארבע ארצות. יסד בית מדרש שנקרא \"פרנס ביהמ\"ד\". בניו: ר יעקב חיים מלובלין, ר צבי הירש מלוקאבי, ר מאיר, ר משה פנחס מסווירז."},{"i":1278,"n":"אברהם פרץ מקושטא","b":"דיין בקושטא-תקץ אצל ר אליעזר די טולידו, חתם-תקצה עם רבו ועם ר חזקיה אברהם הלוי."},{"i":1279,"n":"אברהם פרץ משלוניקי","k":"בעל אגרת מגן אברהם","dt":"תפו","dp":"שלוניקי","b":"מחכמי שלוניקי, תלמיד בישיבת נתן העזתי בשלוניקי-תלז - אחרי המרתו של ש\"ץ. חתם על הסכמת ר יוסף קובו-תפה בענין פטור תלמידי חכמים ממס. חיבר קונטרסים בקבלה לפי שיטת רבו - נתן העזתי - \"אגרת מגן אברהם\", \"סוד היחוד\"."},{"i":1280,"n":"אברהם צבי הירש מנובידבור","f":"מאיר","k":"בעל דברי הברית","b":"חתן רבה של אמדור. רב בנווידואהר, לזדיי-ליטא. גיסו של ר גד משה בן שלמה זלמן מקריניק והורדנא."},{"i":1281,"n":"אברהם צבי הכהן מדאוג","f":"שמואל איסר הכהן","bt":"תקצז","bp":"וילנא","dt":"תרפא","b":"אביו כיהן כראש ישיבת מייליס בוילנא. אב\"ד בדאוג-תרנ כ-40 שנה. הניח חבורים בכת\"י."},{"i":1282,"n":"אברהם צבי הכהן מסנט-פעטר","b":"רב בסנט-פעטר-תקפב בזמן כהונת ר זאב וולף פאפא. היה בקשר שו\"ת עם החת\"ס."},{"i":1283,"n":"אברהם צבי הלוי מצפת וטבריה","f":"מנחם מנדל","dt":"תרנא-ו - כסלו","dp":"טבריה","b":"רב הקהלה האשכנזית בצפת לאחר הרעש בשנת תקצז, עבר לטבריה, בשנים תרלג-תרמד הוא חותם על מכתבים כראב\"ד טבריה, הקים את הישיבה בעיר."},{"i":1284,"n":"אברהם צבי יהודה הירש מדרגיצין","b":"רב בדרגיצין-תרצה."},{"i":1285,"n":"אברהם צבי מגריידנג","dt":"תקצא - יז אדר","b":"רב בגריידינג"},{"i":1286,"n":"אברהם צבי מחרסון","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":1287,"n":"אברהם צבי מירושלים","dt":"תרכט - כג חשון","dp":"ירושלים","b":"מצאצאי הגר\"א, מחכמי ירושלים."},{"i":1288,"n":"אברהם צבי מליסא","dt":"תק","b":"דיין בליסא"},{"i":1289,"n":"אברהם צבי מסקאלא","b":"רב בסקאלא."},{"i":1290,"n":"אברהם צבי מצ'עצ'ע","b":"רב בצ'עצ'ע-תר\"מ"},{"i":1291,"n":"אברהם צבי מצפת","b":"מחכמי צפת, חתם על מכתב לקהילת מנטובה"},{"i":1292,"n":"אברהם צרלל מספרד","f":"פרץ בן אברהם","dt":"קכט","b":"רופא מחכמי ספרד וכן אביו. בקי בתכונה ואסטרולוגיה והיה רופא המלך פדרו-ק' ומקורב אליו גם בזכות האסטרולוגיה."},{"i":1293,"n":"אברהם קאשי מלובלין","f":"אושעיה","k":"אברהם מוכר ירקות","dt":"שג - כד סיון","dp":"לובלין","b":"מחכמי לובלין. נזכר בשה\"ג שהיה בזמן מהרש\"ל ועל מקומו אחיו - וזה אינו כי נפטר שנים רבות לפני מהרש\"ל."},{"i":1294,"n":"אברהם קבסי","f":"משה בן שמואל","b":"מקובל וראש מתיבתא בקאבס-מרוקו-ד'תשן, נזכר ברי\"ף תשובה ששלח רב האי אל ר אברהם, ובריטב\"א מביא מרב האי שכתב עליו שהיה \"מכיר עתידות בנענוע ראשי אילנות\" והוא חכמת שיחת דקלים,"},{"i":1295,"n":"אברהם קופל מקרסטיר","b":"אב\"ד קרסטיר. הסכים על \"עקידת יצחק\" - פרשבורג תרח."},{"i":1296,"n":"אברהם קלמן יואלש","b":"דיין בלבוב, חתם-תפח עם ר יהודה ליב איטינגא, ועוד."},{"i":1297,"n":"אברהם ר וואלפש מקאלימיי","b":"מחכמי זולקווא. חתם-תכד על תקנות הקהלה שנתקיימו בועד זווירז - חתומים עמו: ר שמעון גינצבורג מפרמישלא, ר יוסף איזיק מיאברוב, ר שמואל זנויל מלבוב, ר דוד ברעגר מבוטשטש, ובעל הט\"ז."},{"i":1298,"n":"אברהם ראובן מאישטיפי וירושלי","f":"ראובן או אברהם","k":"בעל דרך ישרה","bp":"אישטיפי(=אסטיפי)","dp":"ירושלים","b":"רב באישטיפי-יוון-תקכה, עלה לירושלים - אחרי תקלה, וישב בישיבת \"חסד לאברהם\" בראשות ר דוד פארדו. בשליחות-תקמה. חתן ר אברהם בעלול מירושלים. בשליחות לצורך הדפסת ספרו והיה בשלוניקי ובולגריה וכן באיטליה - שנים רבות. חיבר \"תקוני הנפש\" בספרדית, ותרגמו לעברית בשם \"דרך ישרה\" שלוניקי תקמה, - פרק מספרו בשם \"שער הסגולות\" נדפס כמה פעמים בנפרד."},{"i":1299,"n":"אברהם ראובן משלוניקי","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי."},{"i":1300,"n":"אברהם ראכעלציק","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":1301,"n":"אברהם רביצנקער-תלמיד הבעשט","b":"תלמיד הבעשט, ועליו ב\"דרכי החיים\", ומסופר שיצר \"גולם\" והשתמש בו להצלת ישראל."},{"i":1302,"n":"אברהם ריזלס מברוד וירושלים","f":"ישראל","k":"בעל לקוטי אמרים?","dt":"תקו - ז אלול","dp":"ירושלים","b":"עלה לצפת עם ר אלעזר רוקח בעל מעשה רוקח, ואח\"כ לירושלים. לדעת ריבלין מזוהה עם ר אברהם ריזילס או ר אברהם שווערדעלשעק המוזכרים במכתבו של ר אברהם גרשון מקיטוב."},{"i":1303,"n":"אברהם שאול מירושלים","dt":"תריא - יח תמוז","b":"מחכמי ירושלים, שד\"ר לקושטא-תר\"ג"},{"i":1304,"n":"אברהם שאול משלוניקי","dt":"תקמב - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":1305,"n":"אברהם שוועקשנער","b":"מחכמי טלוסט - תשובה אליו ב\"שערי דעה\"-תרלח."},{"i":1306,"n":"אברהם שלום מאיפסולה","b":"מחכמי איפסולה-תכז, חתום על ההסכם עם נתן העזתי."},{"i":1307,"n":"אברהם שלום מדרעא","dt":"שלז - לפני","b":"מחכמי צפון אפריקה. נזכר בספר \"חזיונות\" לר חיים ויטאל. נספד מאת ר מסעוד הכהן מדרעא וצפת-לפני שלז."},{"i":1308,"n":"אברהם שלום מצפת - הנכד","f":"אליעזר שלום","bp":"שלוניקי","dt":"שי - אחרי","b":"נכדו של ר אברהם שלום הזקן, תלמיד ר שלמה סאגיס, ר יוסף טאיטצק, ר יעקב בירב. חתן ר חייא רופא בעל \"מעשה חייא\" - שהיה ראב\"ד צפת, דיין בצפת עם ר זכריה ורנק ור שלמה חסון, עמד בראש ישיבה בצפת, היה שליח צפת עם ר יוסף מטירני בקושטא בשנת שנט, בשנת שצח חתם על אגרת מונציה בענין הקדש ר יצחק פרינסיפל לישיבת טבריה (מטה יוסף לר יוסף נזיר). בנו ר חייא שלום. נזכר ב\"גינת ורדים\" שכיהן על מקום זקנו לאחר שאביו נפטר צעיר במגפה-שכב והיה אז לפני בר מצוה ורצו הקהל למנות את ר משה אלשיך, אולם ר שלמה אלקבץ אמר שהמקום שמור לר אברהם."},{"i":1309,"n":"אברהם שלום משלוניקי","b":"גביר בשלוניקי. חתנו - ר שאול מולכו, ואירחו בביתם את הדרשן ר אהרן בן משה יהודה צבי אשכנזי-תקף - ור אהרן כתב לכבודם שני שירים."},{"i":1310,"n":"אברהם שלום משלוניקי","dt":"תקט","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":1311,"n":"אברהם שלום משלוניקי - הזקן","f":"[אליעזר הזקן]","dt":"שמ","dp":"צפת","b":"ממשפחת רבנים שהגיעו מספרד, מחכמי שלוניקי, רב בצפת-רץ (בקהילות אישר, מגנסיא), חברם של המבי\"ט ואברהם בירב, מתלמידי ר יעקב בירב ואחד מארבעה שנסמכו על ידו, יצא להגנת רבו בענין גט בצפת והרלב\"ח השיב לו (שו\"ת הרלבח). היה דור 23 של רבנים. בנו ר אליעזר נפטר בחייו-שכב ונכדו ר אברהם כיהן על מקומו אחריו - בהוראת ר שלמה אלקבץ - למרות שהיה אז פחות מבר מצוה."},{"i":1312,"n":"אברהם שלום מתורכיה","f":"דוד","b":"מחכמי תורכיה-שן. נזכר בשו\"ת מהרשד\"ם."},{"i":1313,"n":"אברהם שלמה הירש מברגסאס","dt":"תשד","b":"דומ\"צ ורב בברגסאס"},{"i":1314,"n":"אברהם שלמה הכהן מאזמיר","b":"רב באיזמיר-תמ. בנו - ר יצחק מירושלים."},{"i":1315,"n":"אברהם שלמה הלוי מירושלים","dt":"תקפז - כז תמוז","dp":"ירושלים","b":"מחכמי ירושלים"},{"i":1316,"n":"אברהם שלמה מבקשביץ","b":"רב בבקשביץ, רוהטין."},{"i":1317,"n":"אברהם שלמה מפוסוואל","f":"גרשון מלובלין אניקשט","dt":"תקסו","b":"חתן ר יצחק ז\"ק מבירז. רב בפוסוואל(=פוסבול) על מקום ר ישראל ז\"ק, ובנו ר אבלי על מקומו אחריו, פומפיאן, בירז על מקום ר ישראל ז\"ק-אחי חותנו (ולפי ליפמן-קובנא על מקום חותנו, ור ישראל אחי חותנו על מקומו אחריו), ור נפתלי הרץ על מקומו אחריו. הסכים על \"שירה לדוד\" הורדנא תקנז. בניו ר אבלי מפוסוואל, ור חיים מפוסוואל(=פאסוואל,פסוול). אחיו - ר משה."},{"i":1318,"n":"אברהם שמואל מאישטיפי","bp":"שלוניקי","b":"תלמיד ר אברהם מוטאל. ר\"מ באישטיפי-שנות ה-ת'. משורר ופייטן וחיבר ספר פזמונים ושירים."},{"i":1319,"n":"אברהם שמואל מדרוזגניק","f":"יצחק אביגדור מקובנא","b":"רב בדרוזגניק."},{"i":1320,"n":"אברהם שמואל מטשאווס","f":"ישראל איסרל מבריסק","dt":"תקמג","b":"רב במוהילוב, טשאווס, צורטקוב. הסכים על \"באר אברהם - שקלוב תקמג, \"חן טוב\" קוריץ תקם, ועוד. אחיו - ר אשר מאליק ונארול."},{"i":1321,"n":"אברהם שמואל מסופיה","b":"רב בסופיה-שנות ה-ת'."},{"i":1322,"n":"אברהם שמואל שאלתיאל בכור","k":"אש\"ן","b":"מחכמי שלוניקי-תרם. הו\"ל את ספרי ר אברהם הכהן \"טהרת המים\", \"יוקח נא\", עם הגהות ממנו שעליהם חתם שמו - אג\"ן."},{"i":1323,"n":"אברהם שמחה מאמציסלב","f":"נחמן מפאהאסט","k":"בעל בנין של שמחה","dt":"תרכה - ו תשרי","b":"אחיינו ותלמידו של ר חיים מוולוזין. רב באמטשיסלב(=אמציסלב)-תקצט. מתורתו ב\"תבונה\" - ירושלים תשא. הסכים על ספר דודו \"נפש החיים\", ש\"ס וילנא, בנו - ר חיים יוסף מאמציסלב - הו\"ל את ספר אביו."},{"i":1324,"n":"אברהם שמחה מוולוזין","f":"יצחק מוולוזין","b":"רב בנישוויז-תקס. חתנו - ר ראובן יהושע זליג אשכנזי מפילטען בן ר ליב מיורבורג."},{"i":1325,"n":"אברהם שמיעדל מגעוויטש","b":"אב\"ד געוויטש. הסכים על \"עקידת יצחק\" פרשבורג תרח."},{"i":1326,"n":"אברהם שמשון כץ מראשקוב וטבריה","f":"יעקב יוסף-תולדות יעק","dt":"תקנט - ח אלול","dp":"צפת","b":"תלמיד הבעשט. רב בראשקוב על מקום אביו. עלה לארץ לפני תקב, וחזר לחו\"ל, עלה שנית-תקם והתישב בטבריה, עבר לצפת. נפטר ללא ילדים. הניח סדור בכת\"י ובו עניני קבלה."},{"i":1327,"n":"אברהם שמשון מזוואלין","dt":"תקז-ג אלול","b":"גדול בנגלה ונסתר,רב בזוואלין"},{"i":1328,"n":"אברהם שמשון מחוליוב","f":"נתן נטע","b":"מגיה בדפוס פוריצק-תקמו אצל ה\"דברת שלמה\"."},{"i":1329,"n":"אברהם תלמיד הספרדי מתורכיה","b":"תלמיד ר משה פישו. היה באיטליה וסייע בהדפסת הש\"ס הראשון - שונצינו רנב. היה לו דין ודברים עם יתומי הנגיד ר יצחק שולאל-רעג."},{"i":1330,"n":"אברהם, בן ציון","b":"מרבני ירושלים-תקס\"ו"},{"i":1331,"n":"אברהם, דוד","k":"בעל יד דוד","bt":"תקסו","dt":"תרלו","b":"רב ביבאנטי, תלמיד ר' יעקב שמשון שבתי סיניגאליא, חיבר \"יד דוד\""},{"i":1332,"n":"אברהם, חיים יהודה מאזמיר","f":"יהושע אברהם יהודה","k":"בעל אחי וראש","dt":"תרט - יח כסלו","b":"מרבני איזמיר,חיבר שו\"ת \"אחי וראש\",דיין"},{"i":1333,"n":"אברהמוף - משפחה בירושלים","b":"משפחה בוכרית בירושלים, מבני המשפחה - יצחק ובניו - הגבירים יונה, פנחס, מאיר חזקיה ושמעון שיסדו את ישיבת 'מגן אברהם' בירושלים-תרעג."},{"i":1334,"n":"אברהמי, אליהו מתונס","k":"בעל נדר אליהו - כת\"י","b":"תלמיד ר אברהם הכהן בעל \"משמרות כהונה\". מחכמי תונס, סופר בתונס, מרביץ תורה בנאבל. חיבר \"נדר אליהו\" - בכת\"י ובו מתורת רבו, תרגם הגדה לערבית - ליוורנו תרכט."},{"i":1335,"n":"אברהמי, מרדכי מאלגיר","bt":"של","dt":"ת","b":"תלמיד הרשב\"ץ. רב באל קלעא-אלגיר."},{"i":1336,"n":"אברהמס, אברהם דב ברנדרד מדר\"א","f":"יוסף","k":"בעל מיינע זיבעציק יא","bt":"תרמ","bp":"קרוז'","dt":"תריז","b":"תלמיד ישיבות ליטא, היגר ללונדון ומשם לדרום אפריקה והתעשר. בעל ספריה גדולה ששימשה את בני התורה שם. גביר תלמיד חכם שתרגם למוסדות חסד בקרוז'-ליטא ובדרום אפריקה, ציוני וביקר בארץ כמה פעמים ותרם גם לישיבות ומוסדות בארץ. חיבר אוטוביוגרפיה \"מיינע דיבעציק יאר\" - יוהנסבורג תשיד."},{"i":1337,"n":"אברהמס, אברהם זוסמן מלונדון","f":"יוסף אברהמס","k":"בעל בית אברהם","bt":"תקס-סב","bp":"שדליץ","dt":"תרמ - י שבט","b":"בילדותו הכיר את החוזה מלובלין ואת המגיד מקוזניץ וכתב זכרונות מהם. תלמיד ר שמעון דייטש מזליחוב. היגר ללונדון והיה שו\"ב בלונדון-תר, עלה לירושלים-תרלט. חיבר גם \"ויגש אברהם\", \"ברוך מבנים\", \"ויעש אברהם\", ועוד"},{"i":1338,"n":"אברהמס, אברהם מארה\"ב","b":"עסקן בניו יורק, נאמן הברון הירש פונד."},{"i":1339,"n":"אברהמס, ברוך ברנט מלונדון","f":"אברהם-בית אברהם","b":"דיין בקהלת הספרדים בלונדון-תרל, וראש המורים בביהמ\"ד לרבנים בלונדון."},{"i":1340,"n":"אברהמס, דניאל מאמשטרדם","b":"מראשי פקידים ואמרכלים באמשטרדם-תרנג."},{"i":1341,"n":"אברהמס, יוסף מאוסטרליה","f":"ברוך ברנט","bt":"תרטז","bp":"לונדון","dt":"תרצח - כט אב","b":"נכד ר אברהם אברהמס מלונדון בעל \"זכור לאברהם\". תלמיד ביהמ\"ד לרבנים בלונדון, ברלין, בעל תואר ד\"ר. חתן ר אלכסנדר ברוך דיוויס מסידני. רב הכולל במלבורן-אוסטרליה-תרנד ופרש מרבנות-תרעט."},{"i":1342,"n":"אברהמס, ישראל מאנגליה","f":"ברוך ברנט","b":"פרופסור לספרות רבנית בקיימבריג-אנגליה. אחיהם של ר יוסף ממלבורן ור משה מלידס."},{"i":1343,"n":"אברהמס, משה מאנגליה","f":"ברוך ברנט","bt":"תרכ","bp":"לונדון","b":"תלמיד ביהמ\"ד לרבנים בלונדון ובעל תואר ד\"ר. רב בלידז-אנגליה. אחיו - ר יוסף מאוסטרליה."},{"i":1344,"n":"אברוצקי, ברוך מרדכי מטריינוב","f":"אברהם דב","bt":"תרא","b":"רב בטרייאנוב-תרכז."},{"i":1345,"n":"אבריל מניקלשבורג ובודה","dt":"תקו - לפני","dp":"בודפשט","b":"רב באפען(=בודה,בודפשט)."},{"i":1346,"n":"אברך, זאב וולף משאט","f":"יצחק אייזיק","k":"בעל רביד הזהב","bt":"תרה","bp":"ריטובה","dt":"תרפב - יג חשון","b":"נסמך מאת: ר יצחק אלחנן מקובנא, ר אברהם מפיקעלן, ר דוד רגנשבורג משאד. מו\"ץ בפיקאלן-(=פיקעלן)-תרלב אצל ר אברהם חריף וראש הישיבה, ר\"מ בשאט(=שאד)-תרלה, רבה הראשון של מאזייק(=מוראוויאווא)-פלך קובנא-תרמה עד תרפב. חיבר גם שו\"ת-וארשא תרנח. פרסם מאמרים ב\"יגדיל תורה\" - אודסה תרלט, \"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":1347,"n":"אברך, יצחק איזיק","f":"אליעזר","b":"נכד ר טודרוס מריטעווע. רב-שנת תר\"י. בנו - ר זאב בעל \"רביד הזהב\". מתלמידיו - ר ברוך נתנאל נייווידל מטאווריג. הניח חדושים על הש\"ס - בכת\"י."},{"i":1348,"n":"אברל, שלמה מזיכלין","f":"אברהם","k":"בעל בנין שלמה","b":"רב בזיכלין-תק\"ך"},{"i":1349,"n":"אברמוביץ, אברהם דב מסט לואיס","k":"בעל כתב הדת","b":"רב בסט לואיס-תרס."},{"i":1350,"n":"אברמוביץ, אברהם י' מארה\"ב","b":"רב בפורט וורט-ארה\"ב."},{"i":1351,"n":"אברמוביץ, אברהם מסאהל","f":"יהושע אברמוביץ","bt":"תריא","dt":"תרצא - כח כסלו","b":"רב בסאהל"},{"i":1352,"n":"אברמוביץ, אברהם קלמן","f":"גרשון","bt":"תרכו","b":"תלמיד ישיבת וולוזין. רב באלעשסק-פלך טבריא-תרע."},{"i":1353,"n":"אברמוביץ, אהרן מסאל","b":"רב בסאל"},{"i":1354,"n":"אברמוביץ, אהרן מסדיגורא","b":"נאמן ביתו של האדמור ר אברהם יעקב מסדיגורא בעל \"אביר יעקב\"."},{"i":1355,"n":"אברמוביץ, בר משאוולי","dt":"תש..","dp":"מחנה שטוטהוף","b":"יו\"ר התאחדות בעלי מלאכה בשאוולי, ציר בסיים הליטאי סגן יו\"ר הקהלה בשאוולי. עסקן ציבור וצלם במקצועו. נספה בשואה."},{"i":1356,"n":"אברמוביץ, דב בר מירושלים וארהב","f":"אברהם מנחם","k":"בעל כתב הדת","bt":"תרכד-ה","bp":"ליטא","dt":"תרפו","dp":"ירושלים","b":"מחכמי ירושלים עלה בילדותו עם הוריו ולמד אצל ר שמואל סלנט, בישיבת עץ חיים אצל ר משה נחמיה כהנא. מו\"צ בירושלים. היגר לארה\"ב וכיהן כרב בפילדלפיה-תרנב, ניו יורק-תרנד, סנט לואיס-תרסב, ניו יורק. בשנת תרפב חזר לירושלים-תרפב, חיבר \"כתב הדת\" ניו יורק תרס, \"דת ישראל\", ועוד. עורך \"בית ועד לחכמים\" - נ\"י תרסג. ו\"הישראלי\" נ\"י תרסג. ממיסדי \"אגודת הרבנים דארה\"ב\".","bk":[["דת ישראל",""],["כתב הדת",""]]},{"i":1357,"n":"אברמוביץ, דב מנשה משאוולי","f":"דוד מטלז","bt":"תרל","bp":"ראסיין או טלז","dt":"תשב","dp":"שאוולי","b":"תלמיד ישיבות ליטא, חתן ר אליהו יאנובר מקעלם. פנה להשכלה וכיהן כרב \"מטעם\" בראסיין-תרסד על מקום ר אברהם אבלי יפה. עורך דין בשאוולי ונחשב לאחד מהטובים בליטא בזמנו. עסקן ציבור, ציר בקונגרס הציוני, יו\"ר המזרחי. ראש המדברים במשלחות לממשלה ואחד האישים המשפיעים בין יהודי ליטא לפני השואה. נספה בשואה."},{"i":1358,"n":"אברמוביץ, דוד יהושע מארה\"ב","b":"פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":1359,"n":"אברמוביץ, דוד מטלז","dt":"תרסט","b":"מחכמי טלז. בנו - ר דב מנשה משאוולי וראסיין."},{"i":1360,"n":"אברמוביץ, הירש","k":"בעל פארשוונדענע געשט","bt":"תרם","bp":"טרוקי-ליטא","dt":"תשך","b":"תלמיד הסמינר למורים בוילנא, פעיל בבונד, עתונאי וסופר. פרסם מאמרים בקבצים שונים בעניני השעה ספרות וחינוך. ערך את האטלס הראשון באידיש. מנהל \"הילף דורך ארבעט\" בוילנא. חיבר \"פארשוונדענע געשטאלטן זכרונות און סילועטן\" בואנוס איירס תריח."},{"i":1361,"n":"אברמוביץ, חיים זנוויל מריבניצא","f":"משה","k":"אדמור מריבניצא","bt":"תרנח","bp":"באטושאן","dt":"תשנו - כה תשרי","b":"לאחר שנתייתם בילדותו, גדל אצל האדמור אברהם מתתיהו פרידמן משטפנאשט, והיה תלמיד ר יודא ליב צירלסון מקישינוב בעל \"מערכי לב\", ר שמעון שלמה מטשיטשליניק. חתן ר שלמה מרזינא, וכיהן כרב ברזינא על מקומו אחריו, רב ביאסי, חברו של האדמור יעקב יוסף טברסקי מקאלארש-סקווירא, ניצל מהשואה וישב בריבניצא-רוסיה, מסר נפשו על קיום הדת, ועודד את היהודים ומקרבם לתורה. בזיוו\"ש חתן ר חיים אלכסנדר ניימן מארה\"ב. עלה לארץ-תשלג, ניו יורק-תשלה, מונסי. (ישנה עדות כי נועד ע\"י האדמור משטפנשט לכהן כיורשו אחריו - לאדמור משטפנשט לא היו ילדים)."},{"i":1362,"n":"אברמוביץ, יהושע","f":"אהרן אברמוביץ","dt":"תרל","b":"רב בסאהל"},{"i":1363,"n":"אברמוביץ, יוסף טוביה","k":"בעל יד יוסף","bp":"קעלם","dt":"תשי","b":"שו\"ב במנצסטר, עלה לירושלים. חיבר \"יד יוסף\" על הלכות שחיטה פולטובה תרעג (המהדורה אבדה בזמן מלחה\"ע ה-I."},{"i":1364,"n":"אברמוביץ, יעקב מארץ ישראל","b":"עסקן צבור, פעל להקמת ישיבת \"היכל התלמוד\" בתל אביב-תרצד."},{"i":1365,"n":"אברמוביץ, יעקב מוורנה","b":"רב בוורנה על מקום ר יהושע השל מלמד."},{"i":1366,"n":"אברמוביץ, ישעיה מירושלים","b":"מחכמי ירושלים, בשנת תרט בשליחות בגליציה."},{"i":1367,"n":"אברמוביץ, משה","b":"רב במלדצנא-תרצ\"א"},{"i":1368,"n":"אברמוביץ, שלום יעקב","f":"חיים משה","k":"מנדלי מוכר ספרים","bt":"תקצו","bp":"קאפיל-פלך מינסק","b":"תלמיד ישיבות סלוצק, וילנא בישיבת רמיילא וביהמ\"ד הגר\"א. סופר. פרסם מאמרים בעתוני התקופה."},{"i":1369,"n":"אברמוביץ, שמואל","dt":"תשך","b":"רב ברמת יצחק"},{"i":1370,"n":"אברמוביץ, שמואל מתל אביב","b":"משמשו של האדמור ר מרדכי יוסף שלום מסדיגורא בעל \"כנסת מרדכי\"."},{"i":1371,"n":"אברמן, ישראל ישעיה מגרודזיסק","f":"ב\"צ","b":"הסכים בשם אביו על תהלות חיים לר חיים פלטרוביץ."},{"i":1372,"n":"אברמסון, אבא ראובן מדיסנא","bt":"תרכז","dt":"תרפו","b":"תלמיד ישיבות ליטא. בעל בית מסחר לספרים. עבר בעיירות ליטא והטיף לציונית. עבר ליקטרינסלב, לאחר פרעות 1905 עבר לטרנופול. פרסם מאמרים בעתונים הציוניים, חזר לרוסיה והיה מורה בלוזובאיא-אוקראינה. יצא בשליחות ארגונים ציוניים לכל רחבי אירופה. עסק במסחר ספרים. נפטר בדרכו לקרים."},{"i":1373,"n":"אברמסון, אברהם מפוטסדאם","f":"יעקב","k":"בעל פערזוך איבער דען","bt":"1854","bp":"פוטסדאם-גרמניה","dt":"1811","b":"אמן בחריטה במדינת פרוסיה, הכין מטבע עם דיוקנו של פרידריך מלך פרוסיה. חיבר ספר על מקצועו - ברלין 1801."},{"i":1374,"n":"אברמסון, אפרים אברהם","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי, \"הנשר\" - טירנוי תרצג-תשד."},{"i":1375,"n":"אברמסון, אשר מלונדון","b":"פרסם מאמרים ב\"המסילה\" - לונדון תשז."},{"i":1376,"n":"אברמסון, דוד הרופא","bt":"תק","bp":"דנציג","dp":"דנציג","b":"למד רפואה בקניגסברג, רופא בהאזנפוט. חיבר ספר רפואה בגרמנית."},{"i":1377,"n":"אברמסון, צבי הירש משארבוגרד","b":"רב בשארבוגרד-תרע\"ד,בודאפשט"},{"i":1378,"n":"אברמסון, שמואל מארה\"ב","k":"בעל תורי זהב","b":"רב בדובעלין-קורלנד, ניו יורק-תרס."},{"i":1379,"n":"אברמסון, שרגא מירושלים","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":1380,"n":"אברמסקי, אליהו מארה\"ב","k":"בעל זכרון אליהו","b":"רב בארה\"ב-תרפב."},{"i":1381,"n":"אברמסקי, יחזקאל חיים מלונדון","f":"מרדכי זלמן","k":"בעל חזון יחזקאל","b":"תלמיד ר חיים סולוביציק מבריסק. חתן ר ישראל יהונתן ירושלמסקי. רב בסמולעויטש-ליטא, לונדון, ירושלים. ראש ישיבת סלובודקה בבני ברק. פרסם מאמרים ב\"דברי תבונה\" - קובנה תרף, \"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז, \"כנסת ישראל\" - ירושלים תשג, \"תבונה\" - קובנא תרפא, \"שערי ציון\" - ירושלים תרפא. עורך \"יגדיל תורה\" - בוברויסק תרפח - ביחד עם ר שלמה זוין - על מקום ר משה בנימין טומשוב שעבר לניו יורק."},{"i":1382,"n":"אברמציק, מרדכי מסונסוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":1383,"n":"אברשטרק, חיים צבי ממריאמפול","f":"משה","bt":"תרמד","bp":"גליציה","dt":"תשג","b":"חתן ר אברהם מרדכי ספרין מבוריסלב, רב מריאמפול-תרעג, דיין בבוריסלב, נספה בשואה עם בניו."},{"i":1384,"n":"אברשטרק, יצחק יהודה ממוסט","f":"משה","k":"העילוי מבילקמין","bt":"תרם","bp":"גליציה","dt":"תשג","b":"חתן ר יחיאל מונד אבד מוסט. רב במוסט-תרסו על מקום חותנו, נספה בשואה. חתנו היה ר אהרן הורביץ שנספה בשואה."},{"i":1385,"n":"אברשטרק, משה מבילקמין","f":"יוסף מנדל","bt":"תריח","bp":"טרנוב","dt":"תרעה","b":"תלמיד ר נפתלי גולדברג בעל \"בית לוי\" , היה מלמדם של בני האדמור מרדמוסק. חתן ר אפריל מלנצהוט. אב\"ד בבילקמין."},{"i":1386,"n":"אברשטרק, שמעון יחיאל מטרנוב","dt":"תשמא","dp":"ירושלים","b":"דיין בירושלים-תרצז"},{"i":1387,"n":"אברשטרק, שמעון ממנהיים","f":"אהרן","bt":"תרנה","bp":"טרנוב","dp":"ירושלים","b":"תלמיד דודו ר משה עבערשטארק מבילקמין ותלמיד בעל חדושי אבר\"ח. רב בלודבינגסהפן ובמנהיים בגרמניה. עלה לירושלים-תרצה, ר\"מ בישיבת \"תורת חיים\" ורב חסידי סדיגורא בירושלים. חתנו ר רפאל בלזם."},{"i":1388,"n":"אבשלום הכהן מקאשטוריא","b":"רב בקאשטוריא, היה מחלוקת כנגדו והודח מכהונתו-תף, חזר לכהונתו והודח שנית."},{"i":1389,"n":"אבשלום, אברהם","b":"רב בדרעא"},{"i":1390,"n":"אבשרגא, שם טוב משלוניקי","b":"רופא בשלוניקי. סייע בהדפסת \"ילקוט שמעוני\" רפג."},{"i":1391,"n":"אבשרנא, שלמה מקומורג'ינה","b":"רב בקומורג'ינה-שנות ה-ש'."},{"i":1392,"n":"אגבבא, מאיר מעירק","f":"בבא שלום","bp":"בבל","dt":"תרעב - ד חשון","dp":"[חברון]","b":"עלה מבבל לחברון-תרך. תלמיד ר אליהו מני. מלמד בחברון. חיבר ספר דרושים וכן פיוטים."},{"i":1393,"n":"אגודיש, יוסף ממונסטיר","f":"שלמה","b":"רב במונסטיר-שנות ה-ש'."},{"i":1394,"n":"אגוזי, דוד מקושטא","dt":"תו","b":"מרבני קושטא, תלמיד מהראנ\"ח. אחיו של ר חיים מקושטא."},{"i":1395,"n":"אגוזי, חיים מקושטא","b":"דיין ורב בקושטא-שנג. אחיו של ר דוד."},{"i":1396,"n":"אגוזי, מנחם מקושטא (קארידי)","f":"משה","k":"בעל גל של אגוזים","b":"רב ומשורר בקושטא. דיין אצל ר אליהו בן חיים - המהראנ\"ח. רב קהילת רומאניה בקושטא-שנג. חיבר עוד \"עטרה לבית אבות\" ועוד."},{"i":1397,"n":"אגוזי, נסים מירושלים","dt":"תצח - לפני","dp":"מוסול-עירק","b":"מחכמי ירושלים, בשנת תצז בשליחות בעירק, נפטר בשליחותו."},{"i":1398,"n":"אגוזי, נסים מקושטא - א","b":"רב בקושטא-תי, חתם עם ר ברוך ן חיים, ר אליהו אביי, ור משה בנבנישתי."},{"i":1399,"n":"אגוזי, פרץ מקושטא","b":"מחכמי קושטא-שנות ה-ת'. נזכר ב\"פני משה\"."},{"i":1400,"n":"אגוזי-קארידי, נסים מקושטא","f":"חיים","b":"רב בקושטא, נוטה לשבתאות."},{"i":1401,"n":"אגולניק, אהרן מנוברדוק","k":"אהרן קמאעייר","bp":"קאמאי","b":"אחיו של ר יצחק מבפוסובל. תלמיד בישיבת קאמאי (יחד עם שלושת אחיו ובהם ר יצחק). משגיח בישיבת נוברדוק באוסטרוב-מזובייזק."},{"i":1402,"n":"אגולניק, יצחק מפוסוואל","f":"משה","bt":"תרנה-ז","bp":"קאמאי","dt":"תשא - ג אב","b":"מגדולי הרבנים בליטא בדורו. תלמיד ישיבות קאמאי (יחד עם אחיו אהרן מנוברדוק ושני אחיהם), ראדין וסלובודקה, תלמידו המובהק של הסבא מסלובודקה-ר נטע צבי פינקל. רבה האחרון של פוסבול-תרצא. נספה בשואה עם קהילתו. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":1403,"n":"אגוסטרי-ציון, נסים ממצרים","b":"מחכמי אלכסנדריה וסופר בית הדין, חתום על קבלת עדות-שסד. נזכר בשו\"ת מהר\"ם גאויזון."},{"i":1404,"n":"אגז, יוסף מתונס","b":"רב ראשי בתונס. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":1405,"n":"אג'ייני, אלישע ממרוקו וירושלים","f":"שמואל ממרוקו","b":"עלה ממרוקו לירושלים, מחכמי ירושלים-תרפז. תשובה ממנו אצל ר שלמה דנאן בהלכות טריפות. הו\"ל ספר אביו \"רמת שמואל\" ירושלים תרפז."},{"i":1406,"n":"אג'ייני, רחמים יוסף ממרוקו","f":"משה","k":"בעל ויגד לאברהם","dt":"תרנא - אדר","dp":"צפרו-מרוקו","b":"רב בצפרו, תונס, תורכיה, קצמטינא(=קסונטינא)-אלגיר, ושב לצפרו-מרוקו וכיהן כדיין עם ר רפאל משה אלבז, ר חיים אליהו אביטבול, ור רפאל אביטבול. חיבר \"ויגד לאברהם\" - פירוש להגדה של פסח יחד עם חברו ר אברהם חלימי. בניו: ר שלמה מפאס ור אבנר מצפרו. אחיו - ר שמואל."},{"i":1407,"n":"אג'ייני, שמואל מצפרו-מרוקו","k":"בעל רמת שמואל","b":"רב בצפרו-מרוקו, אחיו של ר רחמים יוסף, חתם עם חכמי דורו. בשליחות הישיבה ע\"י ר אליהו הרוש. בנו ר אלישע שעלה לירושלים הו\"ל את ספרו \"רמת שמואל\" תרפז. ?? לא באוצר ??"},{"i":1408,"n":"אגילאר, גראס חנה","f":"עמנואל","k":"בעל פעולות החנוך בבי","bt":"1816","dt":"1847","dp":"פפד\"מ","b":"חיברה ספרים בתולדות אנשי שם בישראל, ותרגמה ספרים. חיברה גם \"נשי ישראל\" - לונדון 1845, \"רוח היהדות\" פילדלפיה 1843, קורות היהודים באנגליה, ועוד."},{"i":1409,"n":"אגילאר, משה רפאל מאמשטרדם","f":"יצחק ישראל","dt":"תרלט","b":"בן למשפחת אנוסים באמשטרדם. יצא לברזיל-תא עם קבוצת יהודים בראשות ר יצחק אבוהב ושימש כחזן בריסיפי-ברזיל, כשהעיר נפלה בידי הפורטוגזים שב לאמשטרדם, ר\"מ בישיבת \"כתר תורה\" על מקום ר מנשה בן ישראל. דיין באמשטרדם אצל ר יצחק אבוהב, ורב על מקומו אחריו. חיבר ספרים רבים בעברית וספרדית בנושאים שונים. ובהם דקדוק עברי \"ליידן תרכ, דיני שחיטה ובדיקה בספרדית. השיב לשאלות אנוסים וסייע להם לשוב ליהדות."},{"i":1410,"n":"אג'ימאן - משפחה","b":"משפחה עשירה בקושטא, נדבנים. (מקור המשפחה ביער ג'ימאן-ספרד)."},{"i":1411,"n":"אג'ימאן, אליהו מקושטא","b":"גביר מראשי הקהלה בקושטא, סייע בהדפסת \"גט מקושר\" לר רפאל משה בולה. בניו - ברוך, אברהם, דוד."},{"i":1412,"n":"אג'ימאן, ברוך מקושטא","f":"ישעיה מקושטא","dp":"קושטא","b":"גביר בקושטא לצד אחיו יעקב, נהרג במרידה בקושטא."},{"i":1413,"n":"אג'ימאן, יעקב מקושטא","f":"ישעיה מקושטא","dt":"תקסז","dp":"קושטא","b":"גביר בקושטא ופעל למען היהודים יחד עם אחיו ברוך. ממונה על בית המטבעות של השולטן על מקום דודו שנהרג - מאיר אג'ימאן. נהרג במרד היניצ'רים ובנו ישעיה (השני) על מקומו אחריו."},{"i":1414,"n":"אג'ימאן, ישעיה מקושטא - הנכד","f":"יעקב","b":"גביר מראשי הקהלה בקושטא, הוגלה לקפריסין, עלה לירושלים-תקף. הקדיש בית להכנסת אורחים ביפו. (כנראה נכדו של ר ישעיה הראשון שנהרג בקושטא - ויש בלבול ביניהם)"},{"i":1415,"n":"אג'ימאן, ישעיה מקושטא- א","dt":"תקפו - ט כסלו","b":"מראשי קהלת קושטא בזמן החיד\"א ושר האוצר. סייע בהדפסת ספרים ובהם \"שמן למאור\" לר עזרא מלכי, \"דברי חפץ\"-תקנה, ועוד. נהרג ע\"י השלטון. בניו - הגבירים ברוך ויעקב-שניהם נהרגו במרידות בקושטא, אחיו - הגביר מאיר, אליהו."},{"i":1416,"n":"אג'ימאן, מאיר מקושטא","b":"ממונה על בית המטבעות של השולטן ונהרג. אחיו - הגביר ישעיה, ובן אחיו - יעקב אג'ימאן על מקומו אחריו עד שנהרג במרד היניצ'רים."},{"i":1417,"n":"אגמאתי, זכריה","f":"יהודה הלוי","k":"בעל ספר הנר","b":"רב באגמאת(מרוקו) בתקופת הרמב\"ם, חיבר \"ספר הנר\" על הרי\"ף, בתוספת חיבורי הגדולים בדורות שלפניו"},{"i":1418,"n":"אג'מי, שלום ממכנאס","b":"רב במכנאס-תקט."},{"i":1419,"n":"אגנץ, משה ליב מקוואטקי","f":"זוסמן","bt":"תרכו","b":"רב בקוואטקי-פלך קובנא-תרנח."},{"i":1420,"n":"אגסי, אליהו מבגדד","b":"מחכמי בגדאד, נסע להודו"},{"i":1421,"n":"אגסי, יצחק מירושלים","b":"מחבורת המקובלים בירושלים-תשיב, מתלמידי ר יהודה אשלג בעל הסולם."},{"i":1422,"n":"אגסי, יצחק שמעון","dt":"תרעז - שבט","b":"רב בבומבי, עלה לירושלים"},{"i":1423,"n":"אגסי, שמעון מבגדד","f":"אהרן בן אבא","k":"בעל זכרון אהרן","bt":"תריא-ד","bp":"בגדד","dt":"תרעד - אב","dp":"בגדד","b":"מקובל, רב בבגדד-תרע. מתלמידיו - ר יהודה משה פתיה."},{"i":1424,"n":"אג'רבי - משפחה -","k":"ראה: ג'רבי","b":"משפחה בטריפולי. משפחת סמייא היא ענף למשפחה."},{"i":1425,"n":"אג'רבי, כמוס (אזאוי) מטריפולי","bt":"תר","bp":"טריפולי","dt":"תרעג - כט טבת","dp":"טריפולי","b":"תלמיד ר משה אסרוסי מטריפולי. מחכמי טריפולי ולבסוף אב\"ד-תרס עם ר אברהם חביב ור שלום תשובה. ר שמואל סלנט בהיותו בשליחות בטריפולי פגשו והתפעל מחריפותו ולמדנותו. תלמידו ר\"ח גביזון. תמך בפתיחת בי\"ס באיטלקית ובו שילוב לימודים כלליים."},{"i":1426,"n":"אג'רבי, מבורך מטריפולי","dt":"תרמח","dp":"טריפולי","b":"רב, מקובל, ודיין בטריפולי - במאה ה-יט. חיבוריו אבדו."},{"i":1427,"n":"אדא אלוף מנהר פקוד","b":"מחכמי הגאונים, ומובא ממנו ב\"הלכות גדולות\", ובתשובות הגאונים."},{"i":1428,"n":"אדא גאון","b":"בעל חשבון התקופות שעל פיו מעברין את השנים - ויש אומרים שהוא מחכמי הגמרא, וי\"א שהוא מזמן הגאונים."},{"i":1429,"n":"אדא, נימן מנאגי-קאניזא","k":"עורך \"מאדיאר איזראל","b":"רב הקהילה הניאולוגית בנאג'י-קאניז'א-מחוז זאלא על מקום הירש פאסל וד\"ר יעקב וינקלר על מקומו אחריו. עורך ירחון אגודת הרבנים הניאולוגים \"מאדיאר איזראל\"-1908."},{"i":1430,"n":"אדאדי, אברהם חיים מטריפולי","f":"מסעוד חי","k":"אחא\"י -בעל השומר אמת","bt":"תקסא","bp":"טריפולי","dt":"תרלד","dp":"צפת","b":"נין לר מסעוד חי רוקח בעל \"מעשה רקח\", ונכד ותלמיד לר נתן אדאדי. עלה לארץ עם זקנו-תקעח דרך איטליה, והתישבו בצפת, הגיע לטריפולי-תקץ, חזר לצפת-תקצב, בשליחות באיטליה, פרס עירק ועוד מטעם קהלת צפת, הגיע לליוורנו-תקצג ומשם לטריפולי, כיהן כדיין בטריפולי-תקצח, וחזר לצפת-תרלב. חיבר \"השומר אמת\", \"ויקרא אברהם\". בנו - ר שאול עובדיה.","bk":[["ויקרא אברהם [שו\"ת]",""],["השומר אמת",""],["ויקרא אברהם",""]]},{"i":1431,"n":"אדאדי, מסעוד חי מטריפולי","f":"נתן","bt":"תקם - בערך","dt":"תקע - בערך","dp":"טריפולי","b":"רב בטריפולי. נפטר צעיר, בנו - ר אברהם חיים."},{"i":1432,"n":"אדאדי, נתן מירושלים וטריפולי","k":"בעל מאורי נתן","bt":"תק","bp":"ירושלים","dt":"תקעח","dp":"צפת","b":"עבר מצפת לליוורנו, רב ודיין בטריפולי. חתן ותלמיד ר מסעוד חי רוקח. בשליחות בליוורנו-תק, דיין בטריפולי-תקנב, עלה לצפת-תקעח עם נכדו ר אברהם אדאדי. נזכר ע\"י יהודי לוב יחד עם שאר רבנים אחרי \"כל נדרי\". בנו - ר אברהם, ר מסעוד חי. חיבר גם \"חק נתן\" - וספריו אבדו. (כמה מחבוריו נמסרו ע\"י נכדו ר אברהם לר יצחק גואטה בליוורנו כדי להדפיסם - אך לא נדפסו). מתלמידיו: נכדו ר אברהם חיים, ר יהודה לביא, ר דוד דבש."},{"i":1433,"n":"אדאדי, רחמים מטריפולי","dt":"תרנט","dp":"טריפולי","b":"רב בטריפולי. נזכר אצל גבריאל רוקח בלוח שנה שפרסם בליוורנו."},{"i":1434,"n":"אדאדי, שאול עובדיה מטריפולי","f":"אברהם חי-ויקרא אברהם","bt":"תרי או תקצא","bp":"טריפולי-לוב","dt":"תרעט - יג תשרי","dp":"[טריפולי]","b":"רב ודיין בטריפולי על מקום אביו שעלה לצפת, יחד עם ר אברהם חביב ור רפאל דאבוש. יסד ישיבת \"יגדיל תורה\" עם חבריו: ר נ' נחום, ר ציון צרור ור מ' ג'אנח. חיבר הקדמה לספר אביו \"ויקרא אברהם\", הגהות ל\"משפט כתוב\" לר אברהם פינסו - בכת\"י. פעל להדפסת סידור \"שאו מנחה\" ג'רבה תרעה, נזכר ממנו בפנקס בי\"ד טריפולי \"זכרון עדות\", חיבר גם פיוטים - בכת\"י."},{"i":1435,"n":"אדאטו, ישראל מאדריאנופול","b":"רב באדריאנופול-ת. חתם עם ר פנחס הכהן, ר אברהם אלביאג, ר אברהם מאגריסו ור שמעון פנחס - בשנת ת. בנו - ר מנחם."},{"i":1436,"n":"אדהאן, אברהם (ברהום) ממרוקו","b":"מחכמי מרוקו-שנות ה-תק'."},{"i":1437,"n":"אדהאן, אהרן ממרוקו","k":"בעל מנחת עני","b":"מחכמי דמנאת(מרוקו), חיבר \"מנחת עני\""},{"i":1438,"n":"אדהאן, דוד","bp":"תאפילאלאת","dt":"תרנב","b":"מרביץ תורה"},{"i":1439,"n":"אדהאן, דוד מדאר אלבידא-מרוקו","dt":"תשו - אייר","b":"דיין בדאר אלבידא(מרוקו)-תרץ. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":1440,"n":"אדהאן, דוד מטבריה","b":"חתם על קבלה-תרפג מישיבת חכמי הספרדים בטבריה."},{"i":1441,"n":"אדהאן, דוד ממרוקו","b":"מחכמי מרוקו-שנות ה-ש'. בנו - ר יצחק."},{"i":1442,"n":"אדהאן, חיים ממצרים","b":"חכם קדמון,מרבני קהיר"},{"i":1443,"n":"אדהאן, חיים מפאס","b":"מחכמי פאס-שנות ה-תק'."},{"i":1444,"n":"אדהאן, ידידיה","f":"אברהם","k":"בן ברהום","b":"מגדולי חכמי מראקש,ראש ישיבה"},{"i":1445,"n":"אדהאן, יהודה ממרוקו","b":"מחכמי כפר אזאוייא-מרוקו-תקכז, עם ר מימון בוסידאן, ור מסעוד אביקציץ."},{"i":1446,"n":"אדהאן, יוסף חיים מירושלים-הנכד","f":"אברהם","k":"בעל אבנים שלמות","b":"נכד ר יוסף בעל \"שופריה דיוסף\". מחכמי שבתא-מרוקו, עלה לירושלים. הו\"ל את ספרי זקנו."},{"i":1447,"n":"אדהאן, יוסף מדמנאת","f":"אברהם","b":"מחכמי דמנאת-מרוקו-תרסב, העתיק בכת\"י מגלת אסתר עם שרח ערבי עבור ר מרדכי אדהאן."},{"i":1448,"n":"אדהאן, יוסף מטיטואן-מרוקו-הזקן","k":"בעל יוסף חן","dp":"ארץ ישראל","b":"רב בטיטואן-מרוקו-שנות ה-תק', עלה לארץ. נזכר ב\"ליצחק ריח\" לר יצחק ן דנאן. חיבר גם \"אוצרות יוסף\", \"שופריה דיוסף\". נכדו ר יוסף נסים בעל \"דברי יוסף\"."},{"i":1449,"n":"אדהאן, יוסף ממרוקו","b":"מחכמי מרוקו-שנות ה-ת'-תק'."},{"i":1450,"n":"אדהאן, יחיא מסאלי-מרוקו","f":"שלמה","b":"מחכמי סאלי, חתם על פס\"ד-תפט."},{"i":1451,"n":"אדהאן, יעיש מפאס","b":"מחכמי פאס-שנות ה-ש'."},{"i":1452,"n":"אדהאן, יעקב מטיטואן","b":"מו\"ץ בטיטואן, חתם על פס\"ד-תקיח, נזכר ב\"עדות ביהוסף\"."},{"i":1453,"n":"אדהאן, יעקב ממכנאס","f":"מימון","b":"מחכמי מכנאס, חתם בצפרו על אגרת-תקלא על פטירת מהרי\"ט, אגרת ניחומים אליו על פטירת אביו-תקטו. נזכר ב\"תהלה לדוד\". חיבר פיוטים."},{"i":1454,"n":"אדהאן, יעקב ממכנאס","f":"משה","b":"מו\"ץ במכנאס, חיבר שירים ומהם: \"אלי וגואלי הקשב ושמע קולי\" שנדפס ב\"ארבעה גביעים\", ואולי הוא שחיבר גם שיר \"עורי אצולה מכסא\". בנו - ר משה."},{"i":1455,"n":"אדהאן, יעקב ממרוקו","b":"מחכמי מרוקו, חתם-תרטז עם ר\"י ן ואליד, ור אליהו ביבאס, ור שמואל ברגילון."},{"i":1456,"n":"אדהאן, מאיר מתילית-מרוקו","b":"מחכמי תילית-מרוקו, חתם-תרס בערך על תקנה של השד\"ר ר מסעוד אדהאן."},{"i":1457,"n":"אדהאן, מימון","f":"משה אידהן"},{"i":1458,"n":"אדהאן, מימון מטיטואן - א","dt":"תקטז - חשון","b":"מו\"ץ בטיטואן, תשובה אליו מהיעב\"ץ-תקט, חבריו הדיינים ר שלמה אבודרהם, ר יעקב ן מלכא."},{"i":1459,"n":"אדהאן, מימון מטיטואן - ב","b":"מחכמי טיטואן, חתם על פס\"ד-תקכו עם ר אברהם גבישון."},{"i":1460,"n":"אדהאן, מימון ממכנאס","dt":"תקטו - טבת","b":"רב במכנאס, חתם על פסקי דין עם ר יהודה בירדוגו, ור יעקב טולידנו. אחיו של ר משה."},{"i":1461,"n":"אדהאן, מימון ממרוקו","dt":"תצד - לפני","b":"נזכר במורה צדק ביעקב."},{"i":1462,"n":"אדהאן, מישאל מכלוף מבאר שבע","f":"שאול","k":"בעל מעדני מלך","bt":"תרף","bp":"זגורא-מרוקו","dt":"תשנז - כה אלול","dp":"באר שבע","b":"לאחר שנתייתם מאביו, גדל אצל ר רפאל ברוך טולידנו ממכנאס, ולמד בישיבת \"כתר תורה\" במכנאס. דיין בעיר אפלו-אלגיר, עלה לארץ-תשט, כיהן כרב בבאר שבע-תשיא. חתן ר יצחק אלון מגרסיף. חיבר גם \"מוסר מלכים\" ועוד."},{"i":1463,"n":"אדהאן, מכלוף מאלגיר","f":"שלמה","b":"רב ומשורר באלגיר. חיבר \"מוסר לבני אדם\" - אלגיר תרנח - על הפגיעות ביהודי אלגיר."},{"i":1464,"n":"אדהאן, מכלוף מצפרו-מרוקו","b":"רב בצפרו, וחתם עם ר רפאל משה אלבז על כתובות ושטרות. בנו ר שלמה - פייטן."},{"i":1465,"n":"אדהאן, מסעוד מאלגיר","f":"יצחק","k":"בעל יאתיו חשמנים","bt":"תר","dt":"תרף","b":"רב באלגיר. חיבר ספרים בערבית יהודית ובהם: \"יאתיו חשמנים\", \"יחיה האדם\" - בקבלה, \"מבקש אמונה\", \"לבב חכמה\" (חלקם אבדו)."},{"i":1466,"n":"אדהאן, מסעוד מטבריה","f":"יחיא מתפלילאת-מרוקו","dt":"תשא - כב חשון","b":"מחכמי תפלילאת-מרוקו, עלה לטבריה-תרלה והיה מרבני טבריה. בשליחות במרוקו ובאלגיר."},{"i":1467,"n":"אדהאן, מסעוד ממגאדור","b":"מחכמי מוגאדור-שנות ה-תק'. נזכר ב\"תקפו של יוסף\"."},{"i":1468,"n":"אדהאן, מסעוד מתאפילאלת","b":"מחכמי גריס מנוף תאפילאלת. בנו - ר שלמה בעל \"בנאות דשא\" המזכירו בספרו."},{"i":1469,"n":"אדהאן, מרדכי ממכנאס","b":"מחכמי מכנאס, חתם-תקס עם רבני מכנאס ובהם ר מימון בירדוגו. הזמין אצל ר יוסף אדהאן מדמנאת מגילת אסתר עם שרח ערבי.."},{"i":1470,"n":"אדהאן, משה מירושלים","f":"מכלוף","bt":"תרנא","bp":"ירושלים","b":"תלמיד \"דורש ציון\", ביהמ\"ד לרבנים של חברת \"העזרה\". מורה בטאטאר פאזארדז'יק-בולגריה-תרעג, חזר לארץ והקים שכונה \"נחלת משה\" בירושלים."},{"i":1471,"n":"אדהאן, משה ממכנאס","f":"יעקב","dt":"תצז - ט חשון","b":"אב\"ד במכנאס על מקום ר משה בירדוגו-המשבי\"ר. חיבר קינה הנאמרת בט באב, ופיוט לשבת. הגביר אהרן ן הרוש יסד עבורו ביכ\"נ בנו - ר יעקב. אחיו - ר מימון שחתם עמו ועם ר יהודה בירדוגו ואחרים."},{"i":1472,"n":"אדהאן, משה ממראקש","f":"אליהו","dt":"תשלו - כד סיון","b":"מחכמי מראקש."},{"i":1473,"n":"אדהאן, משה ממרוקו","b":"רב גדול במערב הפנימי"},{"i":1474,"n":"אדהאן, משה ממרוקו","f":"יעקב בן משה","dp":"פאס","b":"מחכמי מרוקו - שנות ה-תק'. ב\"קונטרס הקינות\" לר חיים דוד סירירו - קינה ממנו."},{"i":1475,"n":"אדהאן, סעדיה ממרוקו","b":"מקובל מחכמי בגריס מנוף תאפילאלת-שס. בנו - ר שלמה."},{"i":1476,"n":"אדהאן, סעדיה מפאס","b":"שו\"ב מחכמי פאס, חתם על פס\"ד בעניני טריפות עם ר יוסף אלחדד, ור אברהם אדארוקי."},{"i":1477,"n":"אדהאן, שלום ממרוקו","dp":"איית יעיש","b":"מצדיקי מרוקו. בנו ר אליהו."},{"i":1478,"n":"אדהאן, שלמה מבגריס-מרוקו","b":"מחכמי בגריס-נוף תאפילאלת. בנו - ר מסעוד, נכדו - ר שלמה בעל \"בנאות דשא\"."},{"i":1479,"n":"אדהאן, שלמה מפאס-מרוקו","f":"חיים","dt":"תצג - אחרי","b":"מחכמי פאס-תנא, והספיד אז את ר שלמה עמאר. חתם עם חכמי פאס-תצז."},{"i":1480,"n":"אדהאן, שלמה מפאס-מרוקו - ב","b":"מחכמי פאס-תקמח, וכתב אז אגרת לר יוסף אירגאס ב\"מנחת יוסף\"."},{"i":1481,"n":"אדהאן, שלמה מתאפילאלת - א","f":"מסעוד","k":"בעל בנאות דשא","b":"מחכמי בגריס-נוף תפילאלת-מרוקו, הגיע לאמשטרדם והדפיס את ספרו \"נאות דשא\"-תצה. הדפיס \"זהר הרקיע\" ופירוש האזהרות לרשב\"ץ."},{"i":1482,"n":"אדהאן, שמעון ממראקש-מרוקו","b":"רב במראקש-מרוקו-תרמא, וחתם אז עם חכמי דורו."},{"i":1483,"n":"אדהאן, שמעון ממרוקו","b":"רב בקורנדו-מרוקו."},{"i":1484,"n":"אדוט סווינא, יהודה מקושטא","b":"גביר בקושטא-תקצו, עבר לוינה, תמך בהדפסת \"באר המים\" לר יעקב רפאל מנשה, ובהדפסת \"נר מצוה\" לר יהודה ן סיד."},{"i":1485,"n":"אדולף, אברהם יעקב מפשוורסק","f":"זכריה","bt":"תרנה","dt":"תשנו","dp":"שיקגו","b":"חסיד בלז. ניצל מהשואה."},{"i":1486,"n":"אדולף, מרדכי מרישא","dt":"תשג","b":"רב ברישא-תרס. נספה בשואה."},{"i":1487,"n":"אדון ן, חיים יוסף משלוניקי","dt":"תקפה","b":"דיין בשלוניקי, הממונה על החזקות-תקסה. תשובותיו בספרי חכמי דורו. חתם-תקפב עם הדיינים ר מרדכי מטאלון ור שאול בן יצחק מולכו. וכן עם ר חיים יוסף ן ארדוט. נספד מאת ר יעקב רפאל מנשה."},{"i":1488,"n":"אדון ן, יוסף משלוניקי","b":"רב הכולל בשלוניקי-תמז עד תנא. מתורתו ב\"חסד לאברהם\"."},{"i":1489,"n":"אדון, יצחק דון מחלב","b":"רב בקהלת הספרדים בחלב-שנות ה-ש'."},{"i":1490,"n":"אדוני, יצחק מירושלים","f":"יוסף","bt":"תרסג","bp":"ירושלים","b":"עסקן בקהלה הספרדית בירושלים."},{"i":1491,"n":"אדוני, שמואל מכורדיסטן ברזני","k":"בעל אבני זכרון","b":"מגדולי דורו, רב וראש ישיבה באשור-כורדיסטן-שס, עמאדיה, הקים ישיבות במקומות שונים בכורדיסטן והפך את האזור למקום תורה. חיבר גם \"דברי שמואל\", ועוד."},{"i":1492,"n":"אדוניהו הכהן","dt":"תרסג","dp":"ירושלים","b":"רב ראשי של אנוסי משהד בירושלים"},{"i":1493,"n":"אדוניהו ן, יעקב חיים מתונס","f":"יצחק","b":"מחכמי תונס-רפ, מגיה בדפוס בומבירגי בונציה. ופעל להו\"ל חומש עם פירושים ומסורה, וכן תלמוד, רמב\"ם ועוד. מסופר עליו ב\"אמונת חכמים\" לר אביעד שר שלום, ולדעת שד\"ל המיר את דתו לפני שנת רצח."},{"i":1494,"n":"אדונים הלוי מפאס","f":"נסים","b":"רב ופייטן בפאס. פיוטים ממנו במחזור כת\"י שנמצא בגניזה."},{"i":1495,"n":"אדונים, דונש","f":"תמים","b":"מחכמי קירואן-ד'תשפ, פילוסוף, מדקדק, אסטרונום, רופא בבית הכליף, מעט אחרי ר' סעדיה גאון, פיוטים ממנו במחזור כת\"י שנמצא בגניזה."},{"i":1496,"n":"אדיג'יש, אברהם","b":"חכם-תט\"ו"},{"i":1497,"n":"אדיג'יש, יוסף מבריקוביצה","b":"מחכמי בירקוביצה, הקדיש ספר תורה."},{"i":1498,"n":"אדיין, סלימן ממרוקו וארץ ישראל","dp":"תאחנאות-מרוקו","b":"מחכמי ארץ ישראל והגיע למרוקו ונפטר שם, ורבים עולים אל קברו."},{"i":1499,"n":"אדכייר, ישראל מטריפולי","f":"יצחק","bt":"תן","dt":"תקך - בערך","dp":"טריפולי","b":"רב וסופר דווקני בטריפולי. חתימתו בפנקס בי\"ד טריפולי."},{"i":1500,"n":"אדל, אברהם הלוי","f":"יהודה ליב מסלונים","b":"אחיהם של ר יוסף אליעזר ליבר מסלונים, ור שלמה."},{"i":1501,"n":"אדל, יהודה ליב מסלונים","k":"בעל אפיקי יהודה","bt":"תקיז או תקך","bp":"זאמושט","dt":"תקפח (או תקסז)","dp":"סלונים","b":"דרשן ומדקדק, מ\"מ בסלונים-תקנז, בנו ר יוסף אליעזר ליבר על מקומו אחריו. בקי בספרות האגדה והמדרשים, היה מקובל על חכמי דורו ובראשם הגר\"א והיה ממקורביו. בנו ר שלמה רב בשרשוב. חיבר \"אפיקי יהודה\" (ובו הספד על הגר\"א), \"מים טהורים\", \"איי הים\", \"מי נפתוח\", ועוד, חיבוריו משמשים כחומר לדרשנים. עוד מבניו: ר אברהם, ר שלמה."},{"i":1502,"n":"אדל, יוסף אליעזר ליבר מסלונים","f":"יהודה ליב מסלונים","k":"בעל דרכי יוסף","b":"מגיד מישרים בסלונים על מקום אביו-תקסז. מגדולי הדרשנים כאביו לפניו."},{"i":1503,"n":"אדל, מרדכי","f":"יהודה ליב","b":"משפחת אדל מצאצאי בעל המאור (ומכאן שמם עד\"ל - עד למאור). אביו של ר צבי הירש מיברוב, נכדו של בעל \"אפיקי יהודה\"."},{"i":1504,"n":"אדל, צבי הירש מיברוב","f":"מרדכי או יהודה","k":"הו\"ל עץ שתול ופרי הע","bt":"תקף","bp":"ראווא","dt":"תרל","b":"רב ביברוב, נכדו של בעל \"אפיקי יהודה\" והדפיס את הספר עם תוספות שלו בשם \"עץ שתול ופרי העץ\" למברג תרכד. חתנו - ר צבי הירש גרטנהויז."},{"i":1505,"n":"אדלהויך, שפטל","dt":"תשג","b":"דומ\"צ באיסקא"},{"i":1506,"n":"אדלמן צבי הירש","bt":"1805","dt":"ה'תריח 1858","bk":[["גדולת שאול",""],["גנזי אקספרד",""],["דברי חפץ",""],["דרך טובים",""],["מגילת ספר",""],["סדר ההגדה לליל שמורים",""],["סדר ההגדה לליל שמורים עם תרגום גרמני",""],["עלים למבחן",""]]},{"i":1507,"n":"אדלמן, אברהם וולף מורשא וארה\"ב","dt":"תרנג","dp":"לוס אנג'לס","b":"מחכמי וארשא, הגיע לאמריקה, וכיהן כרב בלוס אנג'לס-תרכב (הרב הראשון שם)."},{"i":1508,"n":"אדלמן, אברהם יצחק מארה\"ב","b":"רב קהלת \"מחזיקי הרב\" בניו יורק."},{"i":1509,"n":"אדלמן, אליעזר מרוביזביץ","f":"שמריהו","bt":"תרכח","b":"רב ברוביזאוויטש-פלך מינסק-תרסד. הניח כתבים בדרוש והלכה."},{"i":1510,"n":"אדלמן, ברוך נחמן","f":"חיים דוב מפטריקוב","k":"בעל בן הימין","bt":"תריז","b":"רב בפטריקוב-פלך מינסק-תרנז על מקום אביו. חיבר שו\"ת ודרשות בשם \"בן הימין\", \"בת דינא\"."},{"i":1511,"n":"אדלמן, חיים דוב","f":"יצחק גולדברג מקלעצק","dt":"תרסט","b":"חתן ר משה שלמה האכגילרנטר. רב בפיטרקוב-פלך מינסק ובנו ר ברוך נחמן על מקומו אחריו, עלה לארץ-תרמז."},{"i":1512,"n":"אדלמן, יהושע","b":"פרסם מאמרים ב\"הלפיד\" - וארשא תרצז."},{"i":1513,"n":"אדלמן, מנשה","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":1514,"n":"אדלמן, מרדכי שרגא","b":"פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":1515,"n":"אדלמן, צבי הירש מארה\"ב","f":"ראה: אדלשטין-חן טוב"},{"i":1516,"n":"אדלמן, שמריהו","b":"רב-שנת תר\"מ"},{"i":1517,"n":"אדלס, ישראל אברהם מהאלאס","b":"רב בהאלאס-תר\"ס"},{"i":1518,"n":"אדלס, נתן פייטיל מקאשוי","f":"שלמה זלמן מטשטשוביץ","b":"מו\"צ בקאשוי."},{"i":1519,"n":"אדלס, שלמה זלמן מטשטשוביץ","b":"נכד(-אבי אמו) ר יהושע ברוך רייניץ מטשעטשוביץ. דיין בטשעטשוביץ."},{"i":1520,"n":"אדלסברג, שאול הכהן מברודשין","f":"גרשון מנדל","bt":"תקן","dt":"תריא","dp":"ברודשין","b":"רב בברודשין, חסיד ר מאיר מפרמישלן, נפגש עם ר ישראל מרוזין. נזכר בשו\"ת \"ישועות יעקב\". בנו ר אלכסנדדר יואל בעל \"מגן אבות\". מצאצאי ר משה היילפרין שהיה דור יג לר אלחנן בעל התוספות ורבה של ברדיטשוב."},{"i":1521,"n":"אדלר - משפחה","b":"משפחת כהנים עתיקה בפפד\"מ. מקור השם - אחר חזרת היהודים לפפד\"מ לאחר דיכוי מרד פטמילך-שעו נשא ראש המשפחה את נשר הרייך בראש התהלוכה."},{"i":1522,"n":"אדלר הורביץ, אריה ליב","f":"ישראל סלנטר","k":"בעל חיי אריה","b":"חתן ר יו\"ט ליפמן הלפרין בעל \"עונג יום טוב\". רב בחורושץ(=רואשיץ), יאנובה, ברזנא(=ברעזין)-פלך מינסק-תרמ. אשתו הו\"ל אחר פטירתו את ספרו \"חיי אריה\" וילנא תרסז."},{"i":1523,"n":"אדלר, אביגדור","f":"אברהם הכהן","bp":"פרימישלן","dt":"תשב","b":"מצאצאי ר נתן אדלר מפפדמ. עבר לארה\"ב-תרסו, חזר ונעשה חסיד בלז. התישב בביליץ. חתן ר שמואל טרויריג מוישניצה. בנו ר מאיר אלדר בעל \"גחלים באש ובמים\" על תולדות משפחתו."},{"i":1524,"n":"אדלר, אברהם יהודה מפשוורסק","b":"חתן ר שמואל אדולף. רב בפשוורסק. תלמידו - ר משה הרציג מטשיטש. נשיא מחז\"ה בקהילתו. חדושים ממנו ב\"הבאר\" תרפד, ובאהל מועד תרפח, \"אהל תורה\" - ירושלים תרפו, \"אחיאסף\"."},{"i":1525,"n":"אדלר, אברהם יונה מאופשא","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":1526,"n":"אדלר, אברהם מאשפנבורג","bt":"תקסח","dt":"תרמ","b":"תלמיד ר אברהם בינג בוירצבורג, ר וולף המבורג בפיורדא. רב בבורגפרך, אשפנבורג-בווריה ור שמחה במברגר (אחיו של חתנו) על מקומו אחריו. חתנו - ר שלמה במברגר (בן הגרי\"ד)."},{"i":1527,"n":"אדלר, אברהם מנייטרא","f":"יצחק","b":"נכד ר יעקב מאיר פרידנלנד משוראן."},{"i":1528,"n":"אדלר, אברהם שלמה מירושלים","f":"יהושע מנחם אהרן מי-ם","bt":"תרל","dt":"תרעח - כא שבט","dp":"ירושלים","b":"נכד ר אלעזר מנחם מנדל בידרמן האדמור מללוב בירושלים. חתן דודו ר דוד צבי שלמה בידרמן - האדמור מללוב בירושלים. נפטר צעיר."},{"i":1529,"n":"אדלר, אליעזר מגייטסהד","f":"יהודה יונה מסוסניצה","bp":"סוסניצה","dt":"תשח","b":"שם המשפחה המקורי היה \"האס\" ונאלצו לשנותו. עבר לאנגליה התישב בניו קסל ועבר לגייטסהד (היה היהודי השני שם) והקים שם מקום תורה והיה רב הקהלה."},{"i":1530,"n":"אדלר, אלכסנדר","b":"רב בינקובץ,פאקש-תרל\"ה"},{"i":1531,"n":"אדלר, אלכסנדר הכהן מליבק","bt":"תקעו","dt":"תרכט","b":"תלמיד ר יצחק דב במברגר מוירצבורג. רב במויסלינג-תרטו, הרב הראשון בליבק-תריט."},{"i":1532,"n":"אדלר, אלעזר מזוויהל","f":"יוסף יהושע אהרן","bt":"תרפא","b":"מצאצאי ר דוד מללוב. נכד ר שלמה גולדמן מזוויהל. חתן ר משה מבלנדוב (קוזניץ). אדמור חסידי זוויהל בארה\"ב-תרצז בהוראת זקנו האדמור ר שלמה מזוויהל, בשיקגו, לוס אנגלס ובנה בימ\"ד בשם \"בית דוד\" ע\"ש זקנו האדמור מללוב."},{"i":1533,"n":"אדלר, אריה ליב מוילנא","f":"ירמיה רוטנר או ישראל","b":"אצל אווצינסקי-קורלנד נרשם כבנו של ר ישראל סלנטר חתן ר יום טוב ליפמן הלפרין מביאליסטוק בעל \"עונג יו\"ט\". נכד הרש\"ש בוילנא. מחכמי חאראשיץ, אב\"ד ברעזענא-פלך מינסק. מתורתו בספר חותנו, וב\"פרי יצחק\" לר יצחק בלזר."},{"i":1534,"n":"אדלר, אשר אנשיל","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":1535,"n":"אדלר, אשר אנשיל מדונא-פאלדואר","f":"משה מגוטא","k":"בעל מאשר שמינה לחמו","bt":"תריז","dt":"תרצא - ג חשון","dp":"פאקש","b":"גדל אצל דודו ר יצחק זעקל הלוי פולק מסערדאוהל ובאניהאד. תלמיד השב\"ס, ור מיכאל הופמן מסערדאוהל. חתן ר יהודה הרצל מדונא-פאלדוואר ועבר לשם-תרמב. שו\"ב בפאד-תרסב, רב בדונא-פאלדוואר. ?? לא באוצר ??"},{"i":1536,"n":"אדלר, גבריאל הכהן מהנובר","f":"מרדכי מהנובר","k":"בעל כנפי נשרים","b":"רב באברנדורף, מירינגן-שוורצלנד-תקפ. הו\"ל את ספרו דודו זקנו - ר דוד טבלי שיף מלונדון - \"לשון זהב\" עם הוספות ממנו ומאחיו ר בער. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. ?? לא באוצר - מופיע תחת שם אביו - מרדכי ??"},{"i":1537,"n":"אדלר, גרשון מפילזנא","f":"ישראל מפילזנא","b":"רב בפילזנא-תרנט, אחיו ר יהושע על מקומו אחריו וגם חתנו ר דוד זינגר. (אולי בתו היה שנכנס בה דיבוק ונסעה לאדמור אברהם חיים מפלנטש - כמתואר בספר רדומישל). חתם על \"כוס הישועות\"-תרסד"},{"i":1538,"n":"אדלר, דב בר הכהן מפפד\"מ","f":"מרדכי מהנובר","k":"בעל רבינישע גוטאכטן","b":"דיין בפפד\"מ-תר. מתורתו ב\"לשון זהב\" - לדודו זקנו ר דוד שיף מלונדון, שהו\"ל אחיו - ר גבריאל. אחיו של ר נתן בעל \"נתינה לגר\". ערך מאמרים של ידידו ר שלמה טריר - כנגד הריפורמה. ידידו של ר אהרן פולד ויחד עמו שלח איגרת הסכמה לר זכריה פרנקל - שעזב את ועידת הרבנים-תרה מתוך מחאה על הריפורמה. חיבר פירוש לבראשית רבה, וספר בגרמנית עם רבו ר זלמן טריר - ובו אספת מכתבים כנגד הריפורמים וכוונתם לבטל את ברית המילה."},{"i":1539,"n":"אדלר, חיים מרדכי מפארוי","bt":"תרטו","dt":"תרעח - כה סיון","b":"חתן ר עמרם ישי סגל ביליצר מסערענטץ (באוצר הרבנים - מופיע כאביו). דומ\"צ במעדיאסא-תרן, רב בפארוי. גיסו של ר פנחס ביליצר מסערענטץ. מתורתו ב\"בית נפתלי\". בנו - ר יצחק איזיק."},{"i":1540,"n":"אדלר, חיים נחום","dt":"תשד","b":"רב בסערעדנא-תש\"ד"},{"i":1541,"n":"אדלר, יהושע מנחם אהרן מירושלים","f":"נתן יהודה מטיסא-עסלר","dt":"תרלו - כב אלול","dp":"ירושלים","b":"אביו היה אחיינו של ר נתן אדלר. שמו המקורי מנחם אהרן ושינה שמו בהוראת רבו ה\"דברי חיים\" מצאנז - ליהושע אהרן. תלמיד הכת\"ס. חתן ר חיים אברהם ארנשטין מבארדיוב בעל \"דברי אברהם\". עלה לצפת, בזיוו\"ש חתן ר אלעזר מנחם מנדל בידרמן - האדמור מללוב בירושלים. נפטר צעיר. בנו ר אברהם שלמה."},{"i":1542,"n":"אדלר, יהושע מפילזנא","f":"ישראל מפילזנא","b":"רב בפילזנא לפני השואה על מקום אביו. חתן ר אברהם קורן."},{"i":1543,"n":"אדלר, יואב מהאנשוביץ","f":"שלום מסערעדנא","bt":"תרלז-מ","bp":"סערעדנא","dt":"תשג-ד - יב חשון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור יהודה גרינולד מסטמר. חתן ר דוד יהודה ליב זלצר מהומנא. רב בדאברא-תרסז, רבה האחרון של האנשוביץ-תרפב. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":1544,"n":"אדלר, יואל","f":"אברהם צבי הירש","b":"חתן ר אלתר עזרא זיידמן מסטריזוב. נספה בשואה."},{"i":1545,"n":"אדלר, יום טוב ליפמן מבייאה.","dt":"תרעג","b":"תלמיד הכת\"ס, ור עזריאל הילדסהימר, ובעל תואר ד\"ר. חתן ר יואל אונגר מפאקש ועבר לשם. רב בפאקש-תרלא, בייאה-תרלט על מקום ר משה נאשאר."},{"i":1546,"n":"אדלר, יונה מפעזינג","f":"משה אהרן מפעזינג","b":"מחכמי פעזינג. זקנו של ר יצחק טוביה וייס אב\"ד העדה החרדית בירושלים."},{"i":1547,"n":"אדלר, יוסף גבריאל מעטינגן","f":"אברהם אדלר","bt":"תקסב","dt":"תרלג","b":"רב בעטינגן,בורגפרפך"},{"i":1548,"n":"אדלר, יוסף יהושע אהרן - א","b":"חתן האדמור מללוב - ר אלעזר מנחם מנדל."},{"i":1549,"n":"אדלר, יוסף יהושע אהרן - ב","f":"אברהם שלמה","bt":"תרמג","dt":"תשט - יא כסלו","b":"מצאצאי אדמורי ללוב. חתן ר אלימלך מירוסלב. יד ימינו של זקנו ר דוד צבי שלמה בידרמן האדמור מללוב, ואדמור אחריו בירושלים - בזמן שדודו ר שמעון נתן נטע היה בקראקא. מבניו - ר אלעזר מזוויהל - לוס אנג'לס."},{"i":1550,"n":"אדלר, יוסף מטארדא(=טורדא)","f":"אברהם מנייטרא","bt":"תרמד","bp":"נייטרא","dt":"תשלז - יב אדר","dp":"ירושלים","b":"נכד ר יעקב מאיר צבי פרידלנדר משוראן. תלמיד הכת\"ס, ור דוד פרידמן מצעהלים ור משה כץ מנייטרא, ור שלמה זלמן ברוידא מפפד\"מ. חתן ר בנציון ועזעל מטארדא. דיין בטארדא לצד חותנו. רב בשעסבורג-תרף, רב בטארדא-תרצח על מקום חותנו ונשיא הלשכה האורטודוקסית בטרנסילבניה. ניצל מהשואה ואחריה כיהן שוב כנשיא הלשכה - נבחר באסיפה בקלויזנבורג-תשה. עלה לירושלים-תשי. חתנו ר דוד ברקוביץ משעסבורג - לונדון - ירושלים. פרסם מאמרים ב\"עמק הלכה\" - באטארקס תרפא."},{"i":1551,"n":"אדלר, יוסף מליטא וניו יורק","f":"שלמה","bt":"תרלז","bp":"קלצק-ליטא","dt":"תרצח - טז תמוז","dp":"ניו יורק","b":"תלמיד ישיבות איישישוק, קובנא, וולוזין. חתן ר משה חיים רזניק. היגר לארה\"ב-תרע, רב בביכנ\"ס \"אהבת ציון\" בניו יורק-תרעא, ביכנ\"ס \"של העם\"-תרעח, \"עדת וולקוביסק\"-תרפד, ר\"מ בישיבת \"תורה ודעת\"-תרפו, ישיבת \"תפארת ירושלים\"=תרצא, \"ביכנ\"ס \"אנשי סלונים\"-תרצב. חיבר חדושים בכת\"י. מיסד ומראשי מפלגת ה\"מזרחי\" באמריקה. בניו - ר משה חיים, בנימין."},{"i":1552,"n":"אדלר, יוסף שמואל מפאפראד","f":"יואב מהאנשוביץ","dt":"תשד","b":"תלמיד הדעת סופר. חתן ר צבי הרש הלוי פרגר מפאפראד. רב בפאפראד על מקום חותנו. נספה בשואה."},{"i":1553,"n":"אדלר, יעקב מיונק","b":"רב ביונק"},{"i":1554,"n":"אדלר, יצחק איזיק מסערעדנא","f":"מנחם יהודה מסערעדנא","dt":"תרצה - יב תמוז","b":"חתן ר נחמן כהנא מספינקא. רב בסערעדנא על מקום אביו וחתנו - ר נפתלי מנחם אדלר על מקומו אחריו. פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה."},{"i":1555,"n":"אדלר, יצחק איזיק מפארוי","f":"חיים מרדכי","b":"רב בפארוי-תרע\"ח"},{"i":1556,"n":"אדלר, יצחק ממילכדורף","f":"משה יהודה ליב","dt":"תרמא - טז אד\"ב","dp":"ירושלים","b":"תלמיד הכת\"ס. רב במילכדורף, סעמערין-תרכד, עלה לירושלים."},{"i":1557,"n":"אדלר, יש\"י","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":1558,"n":"אדלר, ליב מהמבורג","f":"שמעון משה מברודי","bt":"תקעא","bp":"המבורג","dt":"תרסה - ט ניסן","dp":"המבורג","b":"תלמיד ר יחזקאל יואלזון מאלטונא, ר יעקב עטלינגר. חתן ר משה מנדלסון. מלמד בת\"ת בהמבורג. חיבר פירוש למסכת פסחים"},{"i":1559,"n":"אדלר, מאיר שלמה יהודה","dt":"תרפב - ג חשון","b":"חתן האדמור מללוב - ר אלעזר מנחם מנדל."},{"i":1560,"n":"אדלר, מנחם","f":"יוסף גבריאל אדלר","bt":"תרא","dt":"תרעא - יט אדר","b":"רב בשרמבק-תר\"ד,מילנבורג-תר\"ח,מינברכהים-תרכ\"ח,,קיצינגן-תרל\"ה"},{"i":1561,"n":"אדלר, מנחם יהודה מסערדנא","f":"שלום - רב שלום","k":"בעל פני חסד","dt":"תרעח - כג שבט","b":"חתן ר אהרן וייס מבנעדעקוביץ. רב ברדוונקה(=ראדוואנקע)-תרנז, סערעד(=סערעדניע), ובנו ר יצחק איזיק על מקומו אחריו. חיבר \"פני חסד\". ?? לא באוצר ??"},{"i":1562,"n":"אדלר, מנחם יהושע אהרן מירושלים","b":"חתן ר חיים אברהם אורנשטין מברדיוב."},{"i":1563,"n":"אדלר, מרדכי דוד מיאסלו","b":"פרסם מאמרים ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":1564,"n":"אדלר, מרדכי הכהן מפפד\"מ","f":"אלכסנדר אדלר","dt":"תקצא","b":"חתן ר דוד פרנקל מהנאו. מחכמי פפד\"מ. רב ראשי בהנובר-תקמא. בניו: ר בער מפפד\"מ, ר גבריאל ממירינגן, ר נתן בעל \"נתינה לגר\" על מקומו אחריו ואח\"כ בלונדון."},{"i":1565,"n":"אדלר, מרדכי צבי סגל מאיגלא","k":"בעל עיר מבצר","b":"דומ\"צ באיגלא-תרעד. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":1566,"n":"אדלר, משה אהרן מפעזינג","f":"אליעזר מפעזינג","dt":"תרנה - יח אדר","dp":"פעזינג","b":"תלמיד החת\"ס. ראש הקהלה בפעזניג."},{"i":1567,"n":"אדלר, משה מירושלים","f":"יוסף יהושע אהרן מללו","bt":"תרסט","dt":"תשנב - ח שבט","b":"מצאצאי אדמורי ללוב בירושלים. חתן ר ירוחם פישל יהושע ברנשטיין. רב \"שיכון הרבנים\" בירושלים."},{"i":1568,"n":"אדלר, משה מישל הלוי מרעננה","f":"יקותיאל יהודה מאיגלא","k":"בעל אורייתא דמשה","b":"תלמיד הדעת סופר, ור שאול בראך מקאשוי. חתן ר אלעזר איזמן מגליציה. מחכמי איגלא, בזמן השואה היה בבודפשט, עלה לארץ וכיהן כרב ברעננה. חיבר משנת המדות על פרקי אבות ועוד."},{"i":1569,"n":"אדלר, משה נחום מפעזינג","f":"יונה מפעזינג","dt":"תשג - כ תמוז","dp":"נייטרא","b":"תלמיד השב\"ס, ור משה צבי פוקס מגרוסורדין. מחכמי פעזינג וראש הח\"ק. נספה בשואה."},{"i":1570,"n":"אדלר, נפתלי חיים מדזיקוב-נתניה","f":"מרדכי יהודה","k":"אדמור מדזיקוב בנתניה","bt":"תרעד","bp":"ירושלים","dt":"תשנה - אדר","dp":"רחובות","b":"נכד האדמור ר אליעזר ניסן הורביץ מדזיקוב-צפת ונכד האדמור ר דוד צבי בידרמן מללוב. גדל אצל אביו חורגו ר ברוך מסערט ויזניץ ועזר לו בהקמת הקריה החסידית רמת ויזניץ בחיפה וראש ישיבה שם. חתן ר חיים מאיר הגר האדמור מויזניץ. מראשי הישיבה בסערט. עבר לנתניה וכיהן כאדמור מדזיקוב בנתניה. חתנו - האדמור מסלונים."},{"i":1571,"n":"אדלר, נפתלי מנחם מסערדענא","f":"יואב מהאנשוביץ","dt":"תשד","b":"תלמיד הדעת סופר. חתן ר יצחק איזיק אדלר מסערעדנא. רב בסערעדנא-תרצו על מקום חותנו. נספה בשואה. פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":1572,"n":"אדלר, נפתלי צבי הירש הרמן מלונ","f":"נתן הכהן - נתינה לגר","k":"בעל נפתלי אלקים","bt":"תקצט","bp":"הנובר","dt":"תרעא - כב תמוז","b":"הגיע כילד עם אביו ללונדון שם נתמנה אביו לרב. תלמיד ר מרדכי קאליש, ש\"י רפפורט בפרג. למד שפות ומדעים, ד\"ר מאוני' לייפציג. חתן סלומון יוזעפס. ראש ביהמ\"ד החכמה בלונדון על מקום ר ברוך איברמס. רב בלונדון-תרלט לצד אביו, רב הכולל לבריטניה-תרנא על מקום אביו. ביקר בארץ וחיבר \"המסע לארץ הקדש\", \"היהודים באנגליה\", ועוד - באנגלית. בעל ספריה גדולה ואחיו - ר נפתלי סייע בעדו לאסוף כתבי יד חשובים מארצות המזרח. ?? לא באוצר ??"},{"i":1573,"n":"אדלר, נתן הכהן מלונדון","f":"מרדכי","k":"בעל נתינה לגר","bt":"תקסד","dt":"תרנ - ח שבט","b":"נכד ר דוד פרנקל מהנאו, ומצאצאי ר שאול וייל. גדול בחכמה ומדע, רב ראשי באלדנבורג, הנובר על מקום אביו, רב הכולל בלונדון ובריטניה."},{"i":1574,"n":"אדלר, נתן הכהן מפפד\"מ","f":"שמעון או יעקב שמשון","bt":"תקב","dt":"תקס - כו אלול","dp":"פפד\"מ","b":"תלמיד ר יעקב יהושע פאלק בעל \"פני יהושע\", ר משה ראפ, ר דוד טבלי שיף, ועוד. מרביץ תורה בפפד\"מ, רב ברכניץ, בסקוביץ-מורביה-תקמב, פפד\"מ תקמו. היה מחלוקת כנגדו בפפד\"מ בגלל ששינה ממנהגי המקום ובגלל קרבתו לקבלה ונאסר עליו-תקלז לקיים מנין בביתו, ובהמשך חתם גם ר פנחס בעל ההפלאה על האיסור (הענין הגיע לשלטונות), בשנת-תקמט הוכרז כנגדו חרם בפפד\"מ, וספר שיצא בעילום שם \"מעשה תעתועים\" יצא כנגדו וכנגד תלמידיו (מאת ליב ועצלר), החרם בוטל-תקס, ור נתן נספד בידי ר פנחס הורביץ. חיבר הגהות ופירוש למשנה ונדפס בשם \"משנת ר נתן\". מתלמידיו - החת\"ס שהלך אחריו לבוסקוביץ. מאמר ממנו ב\"הנשר\" - טירנוי תרצג-תשד. בנו - ר מרדכי."},{"i":1575,"n":"אדלר, נתן הכהן מפפד\"מ","dt":"תנט","b":"דיין בפפד\"מ"},{"i":1576,"n":"אדלר, נתן יהודה","dt":"תרח","b":"תלמיד החת\"ס. בן אחות ר נתן אדלר מבסקביץ ופרנקפורט. נהרג עק\"ה-תרח. בנו יהושע אהרן מנחם מירושלים."},{"i":1577,"n":"אדלר, נתן מפפד\"מ","f":"מרדכי","dt":"תקמד - כב אייר","b":"מחכמי פפד\"מ. חתן ר דוד שטרויס מפיורדא."},{"i":1578,"n":"אדלר, פנחס יעקב","f":"יואל","b":"חתן ר חיים יצחק לויליכט. נספה בשואה."},{"i":1579,"n":"אדלר, פנחס יצחק איזיק מהאנשובי","dt":"תשד","b":"רב בהאנשוביץ"},{"i":1580,"n":"אדלר, פנחס מראוונקא","f":"שלום מסערעדנא","k":"בעל פני חסד","bt":"תרמד","b":"נכד-אבי אמו ר יצחק ביליצר. רב ברדוונקה-תרס\"ב. חתן ר יוסף שמואל מושקוביץ מאונגוואר. חיבר גם \"אלף המגן\" נדפס בספר זקנו \"באר יצחק\". ?? לא באוצר ??"},{"i":1581,"n":"אדלר, פרידריך מפרשבורג","b":"מראשי הקהלה החרדית בפרשבורג-תרצא."},{"i":1582,"n":"אדלר, צבי הירש","b":"רב בהאנשוביץ-תק\"פ"},{"i":1583,"n":"אדלר, צבי הירש מהעוואש","b":"תלמיד מהר\"ם א\"ש מאונגואר. רשם מחידושי רבו ביארמוט-תקצג. (אולי הוא שהיה רב בהאנשוביץ)."},{"i":1584,"n":"אדלר, צבי הירש מפוהורינסק","b":"רב בפוהורינסק, בשנת תרנב חתם על ספר התמונה."},{"i":1585,"n":"אדלר, צבי הרש מאויהל","f":"פנחס מאבאני","b":"תלמיד החת\"ס. מחכמי אויהל-תקפג."},{"i":1586,"n":"אדלר, שלום מסערעדנא","k":"רב שלום","r":"אב\"ד סערעדנע","bt":"תרז","bp":"בודנר-מחוז מרגרטן","dt":"תרס - יד-ה כסלו","b":"רב בסערעדנא(=נאדיאידא?)-תרל כ-30 שנה, חתן ר יצחק איזיק הלוי ביליצר מנאדי-אידא בעל \"באר יצחק\". בנו - ר יואב מהאנשוביץ.","bk":[["רב שלום – עה\"ת",""]]},{"i":1587,"n":"אדלר, שלום צבי מדיאסעג","f":"יואב מהאנשאויץ","k":"בעל קב שלם","dt":"תשד","b":"תלמיד ר יוסף צבי דושינסקי מגאלאנטא וחוסט. חתן ר משה קליין-תרפה מגרוסורדין ורבה של רעטע ועבר אל רבו. רב בדיוסג(=דיאסעג,יאסעג) ליד גרוסורדין. נספה בשואה. הו\"ל \"ערכי הכנויים\" עם הוספות ממנו בשם \"קב שלם\" סטמר תרצט. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד. ?? לא באוצר ??"},{"i":1588,"n":"אדלר, שלמה אהרן מסאלקוס","f":"שמואל זנויל","b":"תלמיד הכת\"ס. חתן ר ירחמיאל דב בר בנט מליפטא סנט מיקלוש. מחכמי סאלקוס."},{"i":1589,"n":"אדלר, שלמה זאב מבודפשט","f":"משה אלעזר","dt":"תש - כה אד\"א","b":"תלמיד השב\"ס. מחכמי בודפשט-תרנו."},{"i":1590,"n":"אדלר, שמואל","f":"נתן","b":"אולי הוא בנו של ר נתן אדלר מפפד\"מ-רבו של החת\"ס."},{"i":1591,"n":"אדלר, שמואל זנויל","b":"בנו - ר שלמה אהרן מסאלקוס, וחתנו ר משה רייך מבנביץ."},{"i":1592,"n":"אדלר, שמואל מוינה","dt":"תרפו","dp":"וינה","b":"תלמיד הכת\"ס. מחכמי וינה."},{"i":1593,"n":"אדלר, שמואל עוזר הכהן מרעטשק","f":"יהושע הכהן רפפורט","dt":"תרטו - כג תשרי","dp":"ערלוי","b":"רב ברעטשק, פעטרוואשאר."},{"i":1594,"n":"אדלר, שמעון מפרשבורג","b":"חבר בועד הלא רשמי של יהודי פרשבורג ועסק בהצלת יהודים בזמן השואה - כל זמן שניתן היה."},{"i":1595,"n":"אדלר-נשר, אברהם","k":"בעל כנפי ישרים","dt":"תשלג","b":"רב בירושלים"},{"i":1596,"n":"אדלר-קיטובר, ישראל מפילזנא","f":"גרשון","dt":"תרנח","b":"נכד ר גרשון מקיטוב גיסו של הבעשט. רב בפילזנא. בניו ר גרשון ור יהושע על מקומו אחריו."},{"i":1597,"n":"אדלשטין (חן טוב), צבי הירש","f":"מרדכי","k":"בעל גנזי אוכספורד","bt":"תקסג","bp":"סיסלביץ-גליל הורדנא","dt":"תריט - חשון","dp":"ברלין","b":"עבר לברלין, הו\"ל ספרי קדמונים. חיבר עם י\"ל דוקס \"גנזי אוכספורד\", חיבר \"גדולת שאול\" על השר ר שאול וייל ומשפחתו. פרסם מאמרים ב\"היכל התורה\" - מיר-נוברדוק תרצה, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":1598,"n":"אדלשטין, אברהם עביר מפיסטין","b":"מחכמי פיסטין - תשובה אליו ב\"אבני צדק\"."},{"i":1599,"n":"אדלשטין, אברהם צבי","bt":"תרסג","dt":"תשיא","b":"רב ברמת השרון"},{"i":1600,"n":"אדלשטין, בנימין חיים","b":"רב בשאמוב,עלה לא\"י-תרצ\"ד"},{"i":1601,"n":"אדלשטין, גרשון","b":"רב בראזדיל-תק\"מ"},{"i":1602,"n":"אדלשטין, דוד שלמה הכהן","k":"בעל סדר הלכה","b":"מגדולי חכמי וור"},{"i":1603,"n":"אדלשטין, זכריה","f":"גרשון אדלשטין","dt":"תקעה - כ תשרי","b":"רב בזדיטשוב"},{"i":1604,"n":"אדלשטין, זכריה מטשרנוליצה","f":"נתן נטע יעקב","dt":"תשב","dp":"תל אביב","b":"מצאצאי ר אברהם גרשון קיטובר. אב\"ד טשרנוליצה (ליד קולומיאה)-תרמז על מקום אביו, עלה לארץ-תשא. בנו ר חיים צבי טויבש - רב בציריך."},{"i":1605,"n":"אדלשטין, ירחמיאל גרשון מבני בר","f":"צבי יהודה","b":"נכד ר ירחמיאל גרשון משומיאץ. ראש ישיבת פוניבז בבני ברק."},{"i":1606,"n":"אדלשטין, ירחמיאל גרשון משומיאץ","k":"בעל בן אריה","b":"תלמיד ר חיים סולוביציק. אב\"ד שומיאץ ובנו ר צבי יהודה על מקומו אחריו. נכדו - ר גרשון ירחמיאל - ראש ישיבת פוניבז בבני ברק."},{"i":1607,"n":"אדלשטין, משה מפרוביזנא","f":"צבי"},{"i":1608,"n":"אדלשטין, נתן נטע יעקב","k":"נתן נטע יעקב אשכנזי","b":"חסיד בויאן. רבה של טשרנוליצה, בנו ר זכריה על מקומו אחריו, נכדו של ר אברהם גרשון מקיטוב. תשובה אליו בשות מהרשם. חתנו ר פנחס דיסטנפלד."},{"i":1609,"n":"אדלשטין, צבי יהודה משומיאץ","f":"ירחמיאל גרשון משומיא","k":"בעל הוד צבי","dt":"תשיא - כ שבט","b":"נסמך מאת ר פסח פרוסקין מקוברין. אב\"ד שומיאץ על מקום אביו, עלה לארץ וכיהן כרב ברמת השרון-תרצה. בנו - ר גרשון ירחמיאל (ראש ישיבת פוניבז)."},{"i":1610,"n":"אדלשטין, שאול מטשרנוביץ","f":"יהושע","bt":"תרסג","bp":"בויאן","dt":"תשנא","b":"חסיד בויאן. חתן ר חיים דב הלפרין מווסלוי, וגיסו של ר יצחק יעקב ויס. ממיסדי בית יעקב ומראשי אגו\"י בטשרנוביץ. ניצל מהשואה, עלה לארץ-תשי והתישב בתל אביב."},{"i":1611,"n":"אדם בעל שם","k":"אדם בעל שם","b":"מקובל,השאיר כתביו לבעל שם טוב. מכתבים ממנו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":1612,"n":"אדם ן, עזרא","bt":"תרו","dt":"תרפה - ד אלול","b":"רב בבגדד"},{"i":1613,"n":"אדמור\"י בית איז'ביצא זצ\"ל ושליט\"א","bk":[["מעייני השילוח - חנוכה",""]]},{"i":1614,"n":"אדר א' רבי דב (בערל) אייזנשטיין זצ\"ל ראש ישיבות \"חכמת שלמה\" ו\"קרית מלך\" אדר ה'תשס\"ג (הר הזיתים) אדר","dt":"י אדר"},{"i":1615,"n":"אדר, נפתלי מדזיקוב","b":"עבר מסוקולוב לדזיקוב והיה שם מלמד. עבר מדזיקוב להולנד וללונדון."},{"i":1616,"n":"אדר, שמואל","f":"שמחה טוביה","dt":"תרצג","dp":"קראקא","b":"גדל בביתו של ר\"א מדזיקוב."},{"i":1617,"n":"אדרבי, אברהם מטירייא","dt":"תי","dp":"טירייא","b":"גביר בטירייא(=תירייא). נדב להקמת ישיבה בצפת שנקראה על שמו."},{"i":1618,"n":"אדרבי, אליהו מסקופיא","b":"רב בסקופיא-בולגריה-שן. נזכר במהרשד\"מ, ועוד מחכמי דורו."},{"i":1619,"n":"אדרבי, אליהו מצפת","b":"מחכמי ארץ ישראל, מקובל בצפת, תלמיד האר\"י"},{"i":1620,"n":"אדרבי, יוסף משלוניקי","dt":"שן","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":1621,"n":"אדרבי, יצחק משלוניקי","f":"שמואל","k":"בעל דברי ריבות","bt":"רף - בערך","dt":"שלז - ז אייר","b":"תלמיד ר יוסף טאיטצק. רב בשלוניקי בזמן מהרשד\"ם ומהרמ\"א-ר משה אלמושנינו, היה במחלוקת עם ר מרדכי מטאלון וטען כנגדו שהוא מיקל במסורת, והמהרשד\"ם יצא כנגדו והגן על ר מרדכי מטאלון. ר דוד ן שושן רב ק\"ק שלום בשלוניקי על מקומו אחריו. (יש רושמים תאריך פטירתו - שמד)."},{"i":1622,"n":"אדרבי, שלמה משלוניקי","dt":"שן - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":1623,"n":"אדרבי, שלמה משלוניקי","dt":"שץ - יג תשרי","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":1624,"n":"אדרבי, שם טוב משלוניקי","dt":"שפט","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":1625,"n":"אדרבי, שמואל מקושטא","dp":"קושטא","b":"נכד ר יצחק אדרבי משלוניקי. תלמיד ר אברהם מוטאל. מחכמי קושטא-שנות ה-ת'."},{"i":1626,"n":"אדרבי, שמואל משלוניקי","f":"יצחק - כנראה","dt":"שמד - ט תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר צעיר. נזכר בשו\"ת רשד\"ם כערב על חוב אישה לדון חייא יהודה אברבנאל."},{"i":1627,"n":"אדרבי, שמואל משלוניקי - הזקן","dt":"שטו - יד תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי. אביו של ר יצחק משלוניקי."},{"i":1628,"n":"אדרוט ן, אליעזר ממיורקא","k":"ר' אליעזר הרופא","b":"מחכמי מיורקה-ספרד-נ'. נזכר אצל ר יוסף כספי."},{"i":1629,"n":"אדרוטיל, אברהם מפאס - א","f":"שלמה","k":"בעל תשלום ספר הקבלה","bt":"רמב","bp":"ספרד","dt":"שה - לפני","b":"תלמיד ר משה חלאווה, ר יעקב לואלי בפאס-ממגורשי פורטוגל. רב בפאס, חיבר \"תשלום ספר הקבלה\", אבני זכרון\"."},{"i":1630,"n":"אדרוטיל, אברהם מפאס - ב","b":"מחכמי פאס-מרוקו - שנות ה-ק', היה מעורב במחלוקת אודות נפיחת הריאה."},{"i":1631,"n":"אדרוטיל, שלמה מספרד","bt":"[קפב]","bp":"ספרד","dt":"רנב-ג - טו ניסן","dp":"פאס","b":"מחכמי ספרד, תלמיד ר יצחק קנפנטון, אחר הגירוש הגיע לפאס - בגיל 70. נפטר במגפה שפגעה ברבים מפליטי ספרד במרוקו- רנב-ג. בנו - ר אברהם."},{"i":1632,"n":"אדרוקי, אברהם מפאס","b":"שו\"ב בפאס. חתם עם ר סעדיה ן דנאן, ר יוסף אלחדד אודות עניני טריפות, נזכר ב\"מראה עינים\" לר אליעזר בהלול."},{"i":1633,"n":"אדרוקי, חסאן ממכנאס","b":"מחכמי מקנאס-תכט, בזמנם של ר דניאל טולדנו ור חיים טולדנו."},{"i":1634,"n":"אדרוקי, שלמה מסופיה","b":"דיין בסופיה-שנו. נזכר בשו\"ת מהרש\"ך."},{"i":1635,"n":"אדרי, אברהם","f":"נתן אדרי","k":"בעל וירא אברהם","bt":"תקס","dt":"תרלד - כח סיון","b":"רב בטריפולי,עלה לצפת"},{"i":1636,"n":"אדרי, שאול","f":"אברהם אדרי","bt":"תרי","dt":"תרעט - יג תשרי","b":"מחכמי טריפולי"},{"i":1637,"n":"אדרמן, אלתר בן ציון מלויצק","b":"פרסם מאמרים ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":1638,"n":"אדרעי, אברהם ממרוקו","f":"מסעוד","b":"מחכמי כפר ליד מארקש, חתם על פס\"ד עם רבני מארקש-תקיא."},{"i":1639,"n":"אדרעי, אהרן מאלגיר","bt":"תקף","dt":"תרס","b":"סופר הקהל בתלמסאן-תרי."},{"i":1640,"n":"אדרעי, דוד חי מצפת","k":"בעל בד דוד","bt":"תרמח","bp":"צפת","dt":"תרצב - כ אייר","dp":"ציפרו (מרוקו)","b":"דיין בצפת, מירון, בשנת תרע בשליחות בבוכרה, כיהן שם כרב - בכותאייס-בוכרה, בשנת תרעב בשליחות בגורג'יה בשנת תרעג עבר בטשקנט ונתמנה לרב, בשנת תרף חזר לצפת. חיבר \"בד דוד\" צפת תרפב, ועוד בכתב יד. נפטר בשליחות במרוקו","bk":[["בד דוד – שו\"ת",""]]},{"i":1641,"n":"אדרעי, חיים מצפת","bt":"תריג","dt":"תרץ - כא תמוז","dp":"צפת - מירון","b":"מחכמי צפת תרע, קפריסין-תרעד, דיין שני לראב\"ד ר חיים סתהון בצפת, אחרי מלחמת העולם הראשונה רב ראשי בצפת תרפ. בשליחות צפת בשנת תרנט, חתם על תעודה בקוצין (הודו)"},{"i":1642,"n":"אדרעי, יהודה מפאס","b":"מחכמי פאס-מרוקו, אחיו של ר שלם."},{"i":1643,"n":"אדרעי, יחיא מאלגיר","b":"מצאצאי ר משה אדרעי-תלמיד הרמב\"ם. רב בתלמסאן-אלגיר."},{"i":1644,"n":"אדרעי, מכלוף","dt":"תריח","b":"מחכמי טבריה, בשנת תרט בשליחות במרוקו."},{"i":1645,"n":"אדרעי, מסעוד יונה ממרוקו","k":"בעל שפת אמת","bt":"תרעד","bp":"דגאנה","dt":"תשכח - ט אלול","dp":"ירושלים","b":"למד בישיבה במכנאס. עלה לארץ והתישב בראש פינה ושם נחשב לאיש קדוש ונערץ.","bk":[["שפת אמת",""]]},{"i":1646,"n":"אדרעי, משה ממוגאדור","f":"יצחק","k":"בעל תורת חיים","bt":"תקלה","bp":"מוגדיר (אגאדיר)","dt":"תקפט - אחרי","b":"תלמיד ר יהודה אנהורי ברבאט. מחכמי מרוקו,עבר ממוגאדור לאצווירא, היה בלונדון-תקנב ובאמשטרדם-תקסב והיה מחכמי בית המדרש עץ חיים ומגיה בדפוס פרופס, עלה לארץ ישראל בשנת תרב. חיבר \"תורת חיים\" לונדון תקנב (בהקדמה לספר מספר על קורותיו), חיבר גם \"מעשה נשים\", \"יד משה\", ועוד. לדעת טולדנו-נר המערב היה באדינבורו-תקפט ונפטר אז אחרי זמן קצר."},{"i":1647,"n":"אדרעי, משה ממרוקו","bp":"צפון אפריקה","dp":"ארץ ישראל","b":"מחכמי המערב ד'תתק, תלמיד ר יוסף הלוי מיגאש. הרמבם מזכירו בשם דרעי, וכן באגרת תימן."},{"i":1648,"n":"אדרעי, ראובן מטיטואן"},{"i":1649,"n":"אדרעי, רפאל ממרוקו","k":"בעל היטיבו נגן","bt":"תרמא","bp":"מכנאס","dt":"תשך - ה סיון","dp":"מכנאס","b":"מחכמי מכנאס, תלמיד ר יוסף אלקובי בקבלה. פייטן."},{"i":1650,"n":"אדרעי, שלום מפאס-מרוקו","b":"דיין מחכמי פאס עם ר יהודה ן עטר, ור יעקב ן צור. סופר השטרות של בית הדין. חתם על תקנות בשנים תפט-תקא. חיבר חדושים לש\"ס בכת\"י."},{"i":1651,"n":"אדרעי, שלמה ממראקש","b":"מו\"ץ במראקש, חתם-תרמא על פס\"ד."},{"i":1652,"n":"אדרת ן, יהודה מברצלונה","f":"הרשב\"א","b":"רב בברצלונה-שנת ס'. חתם במכתבי אביו, נזכר בספר הפרדס."},{"i":1653,"n":"אדרת ן, יצחק מספרד","f":"שלמה - הרשבא","b":"מחכמי ברצלונה, אחיו של ר יהודה. חתם עם נכבדי ברצלונה בתשובות הרשבא."},{"i":1654,"n":"אדרת ן, מצליח מאזמיר","f":"משה - ברך משה","dt":"תקיח - ה ניסן","dp":"אזמיר","b":"מחכמי אזמיר, נפטר בחיי אביו יחד עם אחיו - ר שלמה."},{"i":1655,"n":"אדרת ן, משה מאזמיר","dt":"שלח","b":"בקי,מלומד בנסים,רב באזמיר"},{"i":1656,"n":"אדרת ן, משה מאזמיר","k":"בעל ברך משה","dt":"תקב-יח - יא אב","dp":"אזמיר","b":"רב באזמיר, רודוס, שלוניקי. חיבר ספרים על הש\"ס, הרמב\"ם ושו\"ת ועוד. נזכר ע\"י החידא ור חיים פלאג'י. בנו - ר מצליח מאזמיר - נפטר בחיי אביו."},{"i":1657,"n":"אדרת ן, משה מצפת","b":"מחכמי צפת, חתם-תפא על כתב שליחות ר משה ישראל מרודוס. (ואולי הוא שהיה באזמיר ושלוניקי?)."},{"i":1658,"n":"אדרת ן, קרישקאש","b":"תשובה אליו ב\"כללי התלמוד\" שבסוף \"שיורי כנסת הגדולה\"."},{"i":1659,"n":"אדרת ן, שלמה - הרשב\"א","f":"אברהם מברצלונה","k":"בעל תורת הבית","bt":"ד'תתקצה (1235)","bp":"ברצלונה","dt":"ע (1310)","b":"תלמיד רבינו יונה והרמב\"ן. גדול חכמי דורו, ומגדולי המשיבים בכל הדורות, וראש ישיבה בברצלונה. מתלמידיו הריטב\"א, ר שם טוב גאון בעל \"מגדל עוז\", רבינו בחיי בעל פירוש לתורה, ר יצחק דמן עכו, ר משה חלאווה, ועוד."},{"i":1660,"n":"אדרת ן, שלמה מאזמיר","f":"משה - ברך משה","dt":"תקיח - ה ניסן","dp":"אזמיר","b":"מחכמי אזמיר, נפטר בחיי אביו יחד עם אחיו - ר מצליח."},{"i":1661,"n":"אדרת, שלמה מיוזיל-היסאר","b":"מראשי קהלת יוזיל-היסאר-ליד אזמיר-שנות ה-ת'."},{"i":1662,"n":"אהאני, משה ממנטובה","b":"אב\"ד מנטובה-שנות ה-תק'. חתם על הפסק של ר ברוך עוזר מהמבורג כנגד הריפורמים."},{"i":1663,"n":"אהובי, ישראל מפיליפופולי","dt":"תק - אדר","dp":"פיליבי(=פיליפופלי)","b":"מצאצאי ר ישאל בן שמואל אהובי. רב בפיליפופולי."},{"i":1664,"n":"אהובי, ישראל מקושטא וסופיה","f":"שמואל","b":"רב בקושטא, חברו של ר משה שלטון, רב בסופיה לצד ר שלמה ן ג'מיל."},{"i":1665,"n":"אהונאי גאון","k":"ראה: אחונאי גאו","b":"תלמיד רב יהודאי גאון. חיבר פירוש שקטעים ממנו פורסמו ב\"רבנן סבוראי\" - ע\"י לוין. ואולי שמו הוא אחונאי גאון שכיהן אחרי רב פפא."},{"i":1666,"n":"אהילייון, יצחק מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק', שם אשתו - אגולה."},{"i":1667,"n":"אהרון הכהן, ב' אלפים תפ\"ז קבור בהר ההר בירדן","dt":"א אב"},{"i":1668,"n":"אהרונוביץ, בנימין מוארז'אן וני","bt":"תרכה","bp":"וארז'אן","b":"נסמך לרבנות ע\"י הנצי\"ב ור ירוחם ליב ממינסק. ראש המכינה שע\"י הישיבה בטלז. היגר לארה\"ב-תרסז וכיהן כרב בלאול-מסצוסטס, עבר לניו יורק וכיהן כר\"מ בישיבת ר יצחק אלחנן. פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":1669,"n":"אהרונוביץ, יצחק זאב מהאזנפוט","f":"יהושע","dt":"תרלו","dp":"האזנפוט","b":"רב בליקובא, האזנפוט-תריב. חתנו - ר משה אליהו בן נתן דאמיע מליבאוי."},{"i":1670,"n":"אהרונוביץ, שלמה מגריווא","b":"יסד מנין חדש בגריווא בשם \"מנין של ר יחזקאל\", עם ר ליב פדרמן."},{"i":1671,"n":"אהרונוף עולמא, אברהם","b":"ראב\"ד בוכארה"},{"i":1672,"n":"אהרוני, ישראל","f":"אברהם","bt":"תרמב","bp":"ווידז-ליטא","dt":"תשו","dp":"ירושלים","b":"תלמיד ישיבת טלז. פנה להשכלה ולמד זואולוגיה ושפות בפרג, והצטרף לציונות. עלה לארץ-תרסא והיה מנהל בי\"ס ברחובות, חוקר החי בארץ ישראל וסביבותיה, פרופ' באוניברסיטה העברית בירושלים. חיבר תורת החי\", ועוד."},{"i":1673,"n":"אהרן","b":"חתן הש\"ך-ת\"מ"},{"i":1674,"n":"אהרן","f":"מיכל מפינטשוב"},{"i":1675,"n":"אהרן","f":"נחום"},{"i":1676,"n":"אהרן","f":"גרשום","b":"נזכר בשו\"ת הרמ\"א שביקש לאסור שמן זית מחשש לשומן חזיר והרמ\"א לא הסכים עמו."},{"i":1677,"n":"אהרן","f":"יצחק","b":"נזכר בשה\"ק שהיה במעמד חכמים וכו'."},{"i":1678,"n":"אהרן","f":"ברוך שקלאבער","b":"אביהם של ר יעקב ברוכין מקרלין בעל \"משכנות יעקב\", ור יצחק מקרלין בעל \"קרן אורה\""},{"i":1679,"n":"אהרן","f":"זכריה","k":"בעל נתיבות השלום","b":"מדקדק, סייע למנדלסון בביאור לתורה \"נתיבות השלום\" - חיבר את הביאור ל-במדבר. הו\"ל מלות ההגיון עם פירוש מנדלסון."},{"i":1680,"n":"אהרן אבא הלוי מלבוב","f":"יוחנן","dt":"תג - ל סיון","dp":"לבוב","b":"ראב\"ד בלבוב-שעב. כנראה מחותן עם מהר\"ם מלובלין המזכירו בתשובותיו. ואולי הוא ר אביש מקראקא שנזכר ב\"חוקת עולם\" שהוא בין החותמים על החרם שלא לקנות רבנות בכסף-שנא. (במצבות קדש תאריך פטירתו - כח תמוז)."},{"i":1681,"n":"אהרן אב\"ד פומפדיתא","b":"אב\"ד פומפדיתא-ד'תקעג בזמן ר אבומאי גאון פומפדיתא, ונזכר באגרת רב שרירא גאון שנבחר ר אבומאי לגאון במקומו בגלל חלום. ישנה דעה בין חכמי אשכנז שר אהרן בגלל הבושה עבר לאיטליה."},{"i":1682,"n":"אהרן אברהם הלוי מאשכנז","f":"ברוך שמעון","k":"בעל אגרת הטעמים","b":"מחכמי אשכנז בארץ ישראל-שן, חיבר ספר \"אגרת הטעמים\" קושטא שמ, ועם פירוש ר שבתי הורביץ בשם \"שפע טל\", ספר \"קרניים\" שנתפרש על ידי ר שמעון מאוסטרופולי בשם \"דן ידין\" זולקווא תסט."},{"i":1683,"n":"אהרן אלימלך (אלמלח) מקושטא","b":"רב בקושטא-שנות ה-ת', בשנת תכה ישב כדיין עם ר משה שלטון ור שמואל רוזניס."},{"i":1684,"n":"אהרן אריה ליב הנה'לס מדרוידוקר","f":"משה חריף","dt":"תקמו - אחרי","b":"תלמיד המגיד ממזריטש, ר מנחם מנדל מויטבסק. עלה לארץ. מכתביו נדפסו בין אגרות החסידים הראשונים בארץ ישראל ומהם ב\"יסוד המעלה\" לאהרן סורסקי. בנו ר שמואל."},{"i":1685,"n":"אהרן אריה ליב מפרמישלן","f":"מאיר מפרמישלן","k":"אדמור מפרמישלן","dt":"תקעג - ב אד\"א","b":"תלמיד ר יחיאל מיכל המגיד מזלוטשוב, ור אלימלך מליזנסק. היה מקורב לר לוי יצחק מברדיטשוב. בנו ר ישכר דב בער מבערזן."},{"i":1686,"n":"אהרן אריה ליב מרוזניאטוב","f":"ישראל מקאלוש","k":"אדמור מרוזניאטוב","dt":"תרמג - ו סיון","b":"ממשפחת אדמורי פרמישלן. חתן ר אהרן שמואל מאוריניאן. רב ברוזניאטוב, ואדמור בחיי אביו."},{"i":1687,"n":"אהרן אריה מלשקוביץ","f":"יוסף יוסקה מלשקוביץ","b":"רב בנדבורנה"},{"i":1688,"n":"אהרן אריה מנדבורנה","b":"חתם עם בנו ר משה על \"דרש משה\"."},{"i":1689,"n":"אהרן אריה מראזלא","b":"מגדולי תלמידי ר יצחק איזיק מזידיטשוב. על קברו נבנה \"אוהל\"."},{"i":1690,"n":"אהרן אשר מגרויניגן","bt":"תרלז","dt":"תרפו","b":"רב בגרויננגן"},{"i":1691,"n":"אהרן בן אשר מקרלין","bt":"1802","dt":"ה'תרלב 1872","bk":[["בית אהרן",""]]},{"i":1692,"n":"אהרן בן שמואל","k":"בעל בית אהרן","bt":"1620","dt":"ה'תנ 1690","b":"חיבר \"בית אהרן\" מראה מקום הבאורים והמדרשים בתנ\"ך - פפד\"א תן, חיבר גם \"סיסרא תורה\", \"שלוח מנות\".","bk":[["בית אהרן",""]]},{"i":1693,"n":"אהרן בנציון מלאכסנדריה","f":"ישועה","b":"רב ודיין באלכסנדריה"},{"i":1694,"n":"אהרן בער ש\"ץ מטרעביטש","f":"צבי","dt":"תרכד - יא אב","dp":"ירושלים","b":"עלה לירושלים מטרעביטש-מעהרן. מחכמי ירושלים. חתנו - ר ישכר בער צוובנר."},{"i":1695,"n":"אהרן ברכיה ממודנא","f":"משה ממודנא","k":"בעל מעבר יבק","bt":"שכ","dt":"שצט - כה תמוז","b":"מקובל, נסמך ע\"י גדולי צפת-ש\"ע. תלמיד ר הלל ממודנא ור מנחם עזריה מפאנו, גיסו של ר יוסף קרמי בעל \"כנף רננים\", חיבר \"מעירי שחר\" מנטובה שפד, \"מעיל צדקה\" מנטובה תקט, \"מעבר יבוק\" ועוד."},{"i":1696,"n":"אהרן גאון","f":"יאשיהו","b":"אב\"ד בתקופת הגאונים בשנים ד'תשן (990) - תת (1040). בניו: ר יאשיהו (שקנה פירוש ישעיהו לרס\"ג-ד'תשצא), ר צדוק, ר אליהו מעכו (שהעתיק פירוש למקרא-ד'תתא)."},{"i":1697,"n":"אהרן גארדייא הרופא מאוסטרהא","f":"שמשון","k":"אהרן דוקטור גארדיא","bt":"תעח","dt":"תקע - כו אד\"ב","dp":"אוסטרהא","b":"היה רופא מלך פרוסיה, התקרב למגיד ממזריטש והיה רופאו (מסופר כי אמר למגיד \"רפא אותי מחולי הנפש וארפא אותך מחולי הגוף\"), אחר פטירת המגיד עבר לאוסטרהא והיה שם רופא (בזמן ההוא נכבשה פולין בידי הרוסים ועמד לבחינה מיוחדת ואז אושר מינויו כרופא המחוז באוסטרהא). גם בתו היחידה היתה רופאה ונקראה \"חנה'לי דיא דאקטרין - חנה'לה הרופאה\"."},{"i":1698,"n":"אהרן דוד מברלין","f":"נפתלי","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":1699,"n":"אהרן דוד מחאטין וצפת","b":"מחכמי צפת, חתם על שטר-תרלב."},{"i":1700,"n":"אהרן הגאון מרמלה","f":"אברהם","b":"בשנת ד תשן (990) היה ראש ישיבת גאון יעקב, בנו ר יאשיהו היה ראש ישיבת גאון יעקב ברמלה, בנו השני ר יצחק בישיבת ר יוסף הכהן גאון ארץ ישראל, ור מאיר \"ראש הסדר\" במצרים"},{"i":1701,"n":"אהרן הגדול מטבריה","f":"יצחק איזיק","dt":"תקנג - אחרי","b":"חתן ר עזריאל. תלמיד ר אברהם מקאליסק-שהיה אז מתנגד לחסידות ושלחו לבחון את המגיד ממזריטש, ואח\"כ השפיע על רבו לפגוש את המגיד ממזריטש. עלה עם רבו לארץ-תקלז. בשליחות בחו\"ל."},{"i":1702,"n":"אהרן הגדול מקרלין","f":"יעקב הנתסר מיאנובה","k":"אדמור מקרלין","bt":"תצו","dt":"תקלב - יט כסלו","b":"מייסד שושלת קרלין סטולין. תלמיד המגיד ממזריטש, ומפיץ החסידות בליטא, אדמור בקרלין-תקכה, והשפעתו בליטא גרמה למחלוקת כנגד החסידות בליטא. מתורתו בספר נכדו \"בית אהרן\". מתולדותיו ב\"ילקוט דברי אהרן\", \"ברכת אהרן\" ובקובצי \"בית אהרן וישראל\"."},{"i":1703,"n":"אהרן החדרי ממארסיליה","f":"אברהם","b":"רב במארשלייא-ן' ונזכר בשו\"ת הרשב\"א."},{"i":1704,"n":"אהרן הכהן","f":"יוסף בן אהרן הכהן","k":"בעל ספר הגן","b":"נכד ר אהרן הכהן מצרפת שנזכר בפירוש התוס'. תלמיד ר אליקים בן מנחם מקלין, ר שלמה הקדוש בן אברהם מדרויש, ר\"ש בן שניאור מאיברא, ר משה בן שניאור מאיברא, ר יעקב מקינון. נזכר בפירוש התוס' לתורה, וגם לש\"ס (ואולי שם הכוונה לזקנו). כנראה היה גם תלמיד רבני אנגליה בעל התוספות שמביא מהם בספרו."},{"i":1705,"n":"אהרן הכהן","f":"חיים הקדוש","b":"חיבר פירוש למנהגי התפילה. אחיינם של ר יעקב ור יהודה מקורביל, ר שמשון מקוצי, ר אפרים בן מנחם ור שמריה בן יצחק. אולי הוא ר אהרן הכהן מצרפת - זקנו של בעל \"ספר הגן\"."},{"i":1706,"n":"אהרן הכהן גאון פומפדיתא","f":"יוסף","k":"כלף בן שארוגארו","b":"תלמיד רב מבשר גאון. ראש ישיבת פומפדיתא-ד'תשד על מקום רב חנינאי בן יהודה גאון - אביו של רב שרירא - שהיא אב\"ד בימיו, והיה מחלוקת כנגדו מצד רב שרירא גאון שטען כלפיו שלא היה ראוי לגאונות. היה מעורב במחלוקת רב סעדיה גאון עם ראש הגולה והיה מהחולקים על רב סעדיה."},{"i":1707,"n":"אהרן הכהן מאוניפולי","f":"ליב הכהן מאוניפאלי","b":"רב באוניפאלי"},{"i":1708,"n":"אהרן הכהן מאפטא","f":"צבי","k":"בעל עונג שבת","bt":"תקסג","b":"רב באפטא, זליחוב, בילגוריא. חיבר גם \"אור הגנוז לצדיקים\", פירוש לסידור \"כתר נהורא\", ו\"כתר שם טוב\" - ובו ליקוטים מדברי הבעשט."},{"i":1709,"n":"אהרן הכהן מארץ ישראל","f":"יוסף","b":"מחכמי ארץ ישראל-ד'תש בערך. אחיו ר אברהם - כך נמצא בגניזה."},{"i":1710,"n":"אהרן הכהן מביאליסטוק","k":"בעל עבודת הקרבנות","bt":"תרכד","dt":"תרצו - כה שבט","b":"רבה של ביאליסטוק, מיכלישוק-תרע, חתנו של החפץ חיים, חיבר \"עבודת הקרבנות\". עלה ליפו בשנת תרפא וכיהן כרב העיר."},{"i":1711,"n":"אהרן הכהן מברצלונה","b":"נזכר אצל ר יצחק בן טודרוס שהביא בשמו - ואולי יש ט\"ס ושמו אינו מדויק."},{"i":1712,"n":"אהרן הכהן מדבדו-מרוקו","b":"מחכמי דבדו(=דיבדו), שאלה ממנו לחכמי פאס-תכו."},{"i":1713,"n":"אהרן הכהן מזלחוב","k":"בעל אור הגנוז","b":"רב בזעלחאוו-תק\"ל"},{"i":1714,"n":"אהרן הכהן מיוזיל-היסאר","b":"דיין ביוזיל-היסאר-שנות ה-ת', אצל ר אברהם רולו."},{"i":1715,"n":"אהרן הכהן מימפלא","b":"רב מיאמפלא"},{"i":1716,"n":"אהרן הכהן מירושלים","f":"יוסף - דברי יוסף","b":"רב בירושלים. בשליחות באמריקה, ונזכר בחיד\"א."},{"i":1717,"n":"אהרן הכהן מלבוב (רפפורט)","f":"נתן הכהן מלבוב","dt":"ראזינוי","b":"חתן ר יהודה יודל בעל קול יהודה. רב בלבוב, ראזנוי-תמה-תסט, ויתר על רבנותו לר' שלמה מזלקווא. בניו - ר יצחק רפפורט-חתן ר יחיאל הלפרין בעל סדר הדורות. בנו - ר נתן מראזנוי, ר זאב וולף, ר יצחק."},{"i":1718,"n":"אהרן הכהן מלוניל ונרבונא","f":"יעקב בן דוד","k":"בעל ארחות חיים","b":"מגדולי הראשונים, פוסק דורו, רב בלוניל, פרובנס, אחרי גירוש צרפת-ה'סו התיישב במיורקא והיה רב אצל ר שם טוב פלכו. הבית יוסף מביא מספרו. קיצור מספרו נדפס בשם \"כלבו\". יש שסברו שהיה תלמיד הרא\"ש וכנראה זו טעות."},{"i":1719,"n":"אהרן הכהן ממצרים","k":"אבו נצר ן אפחט אלכהן","b":"רופא מחכמי מצרים. חיבר ספר רפואות ומעשה מרקחת(=רוקחות)-ה'כ בשם \"מנהאג אלדכאן וקסתור אלעאן\"."},{"i":1720,"n":"אהרן הכהן מסטרליסק","b":"רב בסטרליסק-תרט."},{"i":1721,"n":"אהרן הכהן מעכו","f":"מריון","b":"פייטן מבני עכו, בן המאה ה-יא, פיוטים שלו פורסמו ב\"ידיעות המכון לחקר השירה העברית\" למ. זולאי עמ' קעט. יתכן והוא שכתב שירים לחברו עלי הרופא - ונמצא בגניזה."},{"i":1722,"n":"אהרן הכהן מפאס","dt":"תרלב","b":"סופר בפאס"},{"i":1723,"n":"אהרן הכהן מפאס-מרוקו","f":"נחמיה","b":"מחכמי פאס, חתם על הסכמה-רפז ונזכר ב\"עץ חיים\" לר חיים גאגין."},{"i":1724,"n":"אהרן הכהן מצרפת","b":"מחכמי צרפת-ד'תתקן. חיבר פירוש לתורה ונזכר בפירוש התוס'. בנו ר יוסף ונכדו ר אהרן בעל \"ספר הגן\". מתורתו ב\"פענח רזא\"."},{"i":1725,"n":"אהרן הכהן מראגוזה","f":"דוד","k":"בעל זקן אהרן","b":"רב בראגוזה(=דוברובניק)-תי. פסק ממנו בענין איסור לימוד תורה לגוי - בשנת תיג. חיבר קונטרס בענין כתיבת ספר תורה. חיבר \"זקן אהרן\" פירוש ל\"שמן הטוב\" לזקנו ר שלמה אוהב, ובסופו \"מעשה ישורון\". נזכר בשו\"ת ר שמואל אבוהב."},{"i":1726,"n":"אהרן הכהן מרובנא","f":"שמואל","dt":"תקמט","b":"תלמיד הבעשט, ומסופר שהוא שהביא את המגיד ממזריטש על הבעשט לראשונה. הקים בית מדרש חסידי ברובנא, עבר לטורטשין."},{"i":1727,"n":"אהרן הכהן מתימן","f":"דוד","dt":"תלט","dp":"צנעא","b":"אב\"ד ורב בצנעא"},{"i":1728,"n":"אהרן הלוי","dt":"תקעד","dp":"ירושלים","b":"חיבר ספר \"מטה אהרן\" שלוניקי תקעט"},{"i":1729,"n":"אהרן הלוי","f":"שמואל","b":"מגדולי דורו-ה'ס. חתם על חרם הנשיא מדמשק-מו על מתנגדי הרמב\"ם. יתכן והוא מחבר הפיוט \"אמרי קח נא\"."},{"i":1730,"n":"אהרן הלוי הרופא","f":"יהודה","k":"גומפרכט קאססל","b":"חיבר פיוטים על צרות ישראל במלכות ביהם(=בוהמיה) במלחמות הוסיאטען-קפא."},{"i":1731,"n":"אהרן הלוי מאלגיר","f":"שמואל","bt":"קף - בערך","dt":"רן - בערך","b":"תלמיד הרשב\"ץ, ובנו הרשב\"ש. וב\"אוהב משפט\" לרשב\"ץ יש שיר ממנו. רב באלגיר."},{"i":1732,"n":"אהרן הלוי מאלקסניץ","f":"יהודה","k":"בעל חסדי אבות","bt":"תץ","bp":"ברזן","dt":"תקם (באו' תקכח","b":"רב באלקסניץ (אלכסנדרוב), ואחר כך מחכמי ברודי. חיבר \"חסדי אבות\" זולקווא תקלא ועוד."},{"i":1733,"n":"אהרן הלוי מברוד","b":"רב בברודי"},{"i":1734,"n":"אהרן הלוי מברצלונה מיחס לו; שעוועל חיים דב","bt":"1906","dt":"ה'תשמב 1982","bk":[["ספר החינוך",""]]},{"i":1735,"n":"אהרן הלוי מהורודוק","b":"אחיינו של ר יעקב יוסף מאוסטרהא. פגש בילדותו את הבעשט. תלמיד ר שניאור זלמן מליאדי, ר שלמה מקרלין. חי כ-100 שנה."},{"i":1736,"n":"אהרן הלוי מוילנא","f":"אברהם הער","b":"רב בוילנא, חתם-תמד על פסק דין עם ר שמואל בן מאיר, ר יוסף בן יעקב, ר אריה לבי בן שמחה לבית אהרן."},{"i":1737,"n":"אהרן הלוי מטיבסק","b":"תלמיד ר מנחם מנדל מויטבסק. בנו - ר לייב אביו של שלר מנדל (מענזיק) חתן ר מאיר הנגיד ממיר."},{"i":1738,"n":"אהרן הלוי מטיווה","b":"רב בטיווה(=תבץ)-שנות ה-ש'."},{"i":1739,"n":"אהרן הלוי מטרנשטין","b":"רב בטרנשטין-תקפ\"ו"},{"i":1740,"n":"אהרן הלוי מירושלים","f":"אליהו","k":"הו\"ל כנסת הגדולה","dt":"תקכז - ג אלול","dp":"אזמיר","b":"מחכמי ישיבת \"בית אל\", חתם על כתבי התקשרויות בשנים תקד(תקיד) ותקיח, בנו היה \"הראשון לציון\" ר מרדכי הלוי הנקרא הרב המליץ, הוציא לאור את הספרים \"כנסת הגדולה\" ו\"בתי כהונה\", היה שליח באזמיר ושם נפטר."},{"i":1741,"n":"אהרן הלוי מלובלין","f":"הלל","dt":"תקעג-ו - יז אדר","dp":"לובלין","b":"דיין בלובלין"},{"i":1742,"n":"אהרן הלוי מסאלי","b":"מחכמי סאלי, חתם-תקיג עם ר חיים טולדנו, ר יעקב ביבאס על אגרת נחומים לר רפאל עובד ן צור על פטירת אביו היעב\"ץ."},{"i":1743,"n":"אהרן הלוי מסטראבין","b":"רב בסטראבין. בנו - ר אליהו פיינשטין מחסלביץ, פרוזין. חתנו ר יקתיאל זוסמן קפלן."},{"i":1744,"n":"אהרן הלוי מספרד","f":"פנחס","b":"אחיינו-בן אחיו של הרא\"ה, מחכמי ספרד. חיבר פסקים על כמה פסקים."},{"i":1745,"n":"אהרן הלוי מספרד-הרא\"ה","f":"יוסף","k":"הרא\"ה - ספר החינוך","bp":"ברצלונה","dt":"נג","b":"מצאצאי ר משלם בן יעקב מלוניל, נכד ר בנבשתי בן ר יוסף בן ר זרחיה בעל המאור. נקרא גם ר אהרן די נה קלארא (על שם אמו). תלמיד הרמב\"ן, ואחיו ר פנחס הלוימגדולי חכמי ישראל בספרד, רב בטוליטולה(=טולידו)-מו, מרביץ תורה במונטפלייר, רב ודיין בברצלונה בזמן הרשב\"א, והיה מחלוקות הלכתיות ביניהם ואף חיברו ספרים בהשגות זה על זה. חיבר \"בדק הבית\"-השגות על \"תורת הבית\" לרשב\"א. מתלמידיו: הריטב\"א, ר קרשקש וידאל, ר יהודה בן זבארי, ר דון אשטרוק, י\"א שגם בעל \"מגיד משנה\". יש אומרים שהוא מחבר \"ספר החינוך\" (במחלוקת בינו לבין הרשב\"א בענין ירושה - הובאה להכרעת רבני צרפת שפסקו כרשב\"א - ובספר החינוך מביא רק את דעת הרשב\"א - ומכאן נראה שלא הרא\"ה הוא המחבר)."},{"i":1746,"n":"אהרן הלוי מקושטא","b":"נכד ר דוד סיר ליאון משלוניקי, הו\"ל ספר זקנו - \"תהלה לדוד\" - קושטא שלז."},{"i":1747,"n":"אהרן הקטן מסמאליין","f":"מאיר","b":"תלמידו ומשמשו של ר מנחם מנדל מויטבסק, ועלה עמו לארץ."},{"i":1748,"n":"אהרן הרופא הקראי","f":"יוסף","k":"בעל ספר המבחר","bt":"ק'","bp":"קרים","b":"מחכמי הקראים, רופא בקושטא. חיבר פירוש למקרא."},{"i":1749,"n":"אהרן זאב וולף מקיטב","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":1750,"n":"אהרן זליג","f":"יהודה ליוואי","k":"בעל בית אהרן","b":"נכד ר שמואל ועליש מירושלים. חיבר \"בית אהרן\"-תקכח, ו\"בית יהודה\"-תרטו."},{"i":1751,"n":"אהרן זליג כץ מאוסטרהא","f":"יהודה ליב","dt":"תנו - כא אדר","dp":"אוסטרהא","b":"פרנס ושתדלן באוסטרהא. בשלח לאספה בפשוורסק כשתלדן ממדינת וואהלין לטובת בתי כנסיות אשר במדינה. מיוצאי חלציו היו מנהיגים ופרנסים באוסטרהא."},{"i":1752,"n":"אהרן זליג מאוסטרהא","f":"יואל פיבש מאוסטרהא","k":"בעל עולת אהרן","dt":"תקטו - יז טבת","b":"תלמיד חכם ופרנס באוסטרהא בזמן הרבנים ר דוד הלפרין. מחותן עם ר דוד גינצבורג מאליק. חיבר \"עולת אהרן\" אמשטרדם תצג, \"משחת אהרן\", \"אהל אהרן\".","bk":[["עולת אהרן - אגדות עין יעקב, אהל אהרן - משניות (כת\"י), משחת אהרן - ש\"ס",""]]},{"i":1753,"n":"אהרן זליג מאשווא","f":"יעקב הומינר (חומינר?","b":"ספרא ודיינא אצל קרובו ר רפאל בהמבורג, רב באשווא. פגש את הגר\"א בהיותו בגלות - אצל ר רפאל. בנו ר ישראל זליגמן מדריסא."},{"i":1754,"n":"אהרן זליג מזולקווא","f":"משה ר הללס מבריסק","k":"בעל עמודי שש-שבע","dt":"תג - יא אלול","dp":"זולקווא","b":"מקובל, רב בזולקווא. חיבר עמודי שבעה עם הקדמה מאת ר ישראל שפירא מקליב בעל \"זרע ישראל\". אחיו - ר שמואל - פרנס בבריסק."},{"i":1755,"n":"אהרן זליג מזולקווא","f":"הלל - בית הלל","dt":"תצד - טו-כ שבט","dp":"זולקווא","b":"ראש ומנהיג בזולקווא. חתם על תקנת הקהלה-תנד וכן בשנים תסד-ה, תעד, תפד."},{"i":1756,"n":"אהרן זליג מירושלים","f":"ישכר בער","b":"בשנת תסא היה בברסלוי בשליחות ירושלים, בשנת תסז חתם בירושלים על כתב הרבנות לר דוד אופנהיים"},{"i":1757,"n":"אהרן זליג מסטניסלב","b":"רב בסטאניסלוב"},{"i":1758,"n":"אהרן זליג מסקאהל","b":"רב בסקול. תשובה אליו ב\"אמרי דוד\"-תרצג."},{"i":1759,"n":"אהרן חיים מרעצפט","b":"רב בראצפערט-תרי\"ב"},{"i":1760,"n":"אהרן טוביה מוארשא","dt":"תריב - א אלול","b":"דיין בוורשה"},{"i":1761,"n":"אהרן יהודה ליב מאוסטרהא","f":"משה","dt":"תקנז - ה חשון","dp":"אוסטרהא","b":"מחכמי אוסטרהא. חתם על מגילת תמוז-תקנב - מגילה זו היתה אודות המאורעות שעברו על הקהלה בזמן נפוליאון והנסים וההצלה שהיו אז."},{"i":1762,"n":"אהרן יהושע מפרשבורג","f":"יוסף","b":"מחכמי פרשבורג, חתם-תקכח על תקנות החברא קדישא."},{"i":1763,"n":"אהרן יואל מקניגסברג","b":"רב בלומבלא-תק\"נ"},{"i":1764,"n":"אהרן יונה מאשכנז","b":"מחכמי ביהם-רן, תלמיד ר נתן איגרא. רב באיגרא. נזכר בתשובות מהר\"י קולין."},{"i":1765,"n":"אהרן יוסף מבוליחוב","b":"רב בבוליחוב."},{"i":1766,"n":"אהרן יוסף מוורמייזא","f":"משה","b":"מחכמי פפד\"מ. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":1767,"n":"אהרן יוסף מחארזיל","f":"דוד","dt":"תרנג","dp":"ירושלים","b":"היה אבד קהילת חארזיל ועלה לירושלים"},{"i":1768,"n":"אהרן יוסף שמואל סגל מטרנטשין","f":"יחזקאל מטרנטשין","bt":"תקסו","bp":"טרנטטשין","dt":"תרמב - י אב","b":"תלמיד החת\"ס, תלמיד ר אליעזר לעוו מסנטוב. חתן בן רבו - ר בנימין זאב וולף לעוו מוערבא. רב בטרנטשין-תקצ לצד אביו, ועל מקומו אחריו-תקצט (בהמלצת החת\"ס). מתורתו בספר אביו \"תורת יחזקאל\"."},{"i":1769,"n":"אהרן יחיאל מאיזביץ","b":"רב באיזביץ"},{"i":1770,"n":"אהרן יחיאל מלבוב","f":"יוסף","dt":"תכד - ח אייר","dp":"לבוב","b":"ר\"מ ודיין בלבוב. נהרג עק\"ה."},{"i":1771,"n":"אהרן יחיאל מלמברג","f":"לפידות","k":"אהרן הקדוש","dt":"תכד - יג אייר","b":"דיין ור\"מ בלבוב. נהרג עק\"ה עם אשתו רייזל בת ר יעקב."},{"i":1772,"n":"אהרן יצחק מסיציליה וקושטא","b":"נשבה בסיציליה, נפדה בקושטא, נתמנה למתורגמן בחצר המלך בקושטא - אחרי ד'תתקלו."},{"i":1773,"n":"אהרן ישכר בער מיאנוב","b":"רב ביאנובה-תקם. ראה גם אהרן ישכר בער סגל מלבוב."},{"i":1774,"n":"אהרן ישכר בער סגל מלבוב","f":"יוסף","b":"דיין בלבוב אצל ר שלמה בעל מרכבת המשנה, הסכים-תקלו על \"זכרון כהונה\". חתם-תקכב עם ר ישכר בער איגרא, ר יחיאל מיכל בריסקר, ר מנחם מנדל רפפורט, ועוד. חתם-תקכו עם ר ישעיה קיקניש, ר אשר אנשל בן משה מטיסמניץ, ועוד חתם פעמים נוספות. חתם שמו לפעמים אהרן ישכר ולפעים רק ישכר."},{"i":1775,"n":"אהרן ליב מלובלין","dt":"תרמו - יח תשרי","b":"מו\"צ בלובלין"},{"i":1776,"n":"אהרן ליב מקראקא","dt":"תלא","b":"מגדולי חכמי קרקא"},{"i":1777,"n":"אהרן מאדא","b":"רב באדא-תר\"כ"},{"i":1778,"n":"אהרן מאונגריש ברוד ורייניץ","dt":"תקיט - ד שבט","b":"דיין באונגריש-ברוד-תקס\"ט"},{"i":1779,"n":"אהרן מאוסטרהא","f":"יוסף יוזפא מאוסטרהא","dt":"תפח - ה סיון","dp":"אוסטרהא","b":"נפטר צעיר. הניח יתומים שגדלו על ברכי יוסף אבי זקינם. בנו: ר אברהם מזוויהל, חתנו - ר אברהם משלם זלמן מאוסטרהא בנו של החכם צבי."},{"i":1780,"n":"אהרן מאוסטרהא","f":"ירחמיאל","dt":"תקעו - כ סיון","dp":"אוסטרהא","b":"ספרא ודיינא באוסטרהא. הסכים על \"עין יעקב\" - תקעא, \"שבחי הבעש\"ט\", ועוד."},{"i":1781,"n":"אהרן מאוסטריה הקדוש","f":"יונה","b":"רב בקרומזא-אוסטריה. נהרג עק\"ה בגזירות קח."},{"i":1782,"n":"אהרן מאיוויא","f":"אורי שרגא בן יקותיאל","b":"אב\"ד איוויא. (אולי הוא אחיו של ר נח בלוך - פעטליצער)."},{"i":1783,"n":"אהרן מאיזנשטט","b":"מו\"צ באייזנשטט-שנת ת'"},{"i":1784,"n":"אהרן מארץ ישראל","f":"יצחק","b":"אב\"ד בישיבת ארץ ישראל על מקום אביו-ד'תשכ - בזמן הגאון ר אהרן בן מאיר."},{"i":1785,"n":"אהרן מארץ ישראל","f":"שמחה","b":"ממונה \"כולל רייסין\" בטבריה-תרטו. חתם על כתב הסמכה לר אברהם מסלונים להיות הממונה על איסוף הכספים לכולל."},{"i":1786,"n":"אהרן מאשכנז","b":"מגדולי חכמי אשכנז"},{"i":1787,"n":"אהרן מאשכנז","f":"אליעזר","b":"מחכמי אשכנז-רן. נזכר בהקדמה לפסיקתא, ונזכר בהגמי\"י על שאלה ששאל מר אביגדור הכהן מוינה, ובתשובות מהר\"ם מרוטנבורג."},{"i":1788,"n":"אהרן מאשכנז","f":"יונתן בן יעקב","b":"מחכמי אשכנז-ה'ק. נזכר בשו\"ת ר חיים אור זרוע."},{"i":1789,"n":"אהרן מאשכנז ושלוניקי","b":"מחכמי אשכנז, עבר לשלוניקי. הסכים בע\"פ על \"תקון ישכר\"-שיד."},{"i":1790,"n":"אהרן מבבל","k":"בעל ספר הנקוד","b":"מקובל וראש ישיבה בבבל-ד'תשצה. נזכר בפירוש ר משה בוטרל לספר יצירה, חיבר ספר הנקוד וספר הפרדס. אולי הוא אבו אהרן מבבל וארץ ישראל."},{"i":1791,"n":"אהרן מבבל וארץ ישראל","f":"שמואל","k":"אבו אהרן,אהרן מבגדד","b":"מחכמי בבל, עבר לעיר לוקא-איטליה דרך א\"י-ד'תר, לימד בישיבה ופגש שם את ר משה הזקן בן קלונימוס בעל הפיוט \"אימת נוראותך (שעבר אח\"כ למגנצא), היה בעיר אורי ופגש שם את החכמים בני הפייטן ר אמיתי - ר שפטיה ור חננאל והנהיג שם בי\"ד שדן בדיני נפשות, עבר בעיר בארי-ד'תר - שנכבשה אז ע\"י הערבים וביקר אצל המלך שודאן שניסה לשכנעו להישאר אצלו. חזר לא\"י."},{"i":1792,"n":"אהרן מבודה","f":"ישראל","b":"גביר מראשי קהלת בודה-שנות ה-ש'."},{"i":1793,"n":"אהרן מבוטושאן","b":"חתן ר חיים טירר מטשרנוביץ, רב בבוטושאן על מקום חותנו."},{"i":1794,"n":"אהרן מבורגנא","f":"יוסף","b":"תלמיד רבינו תם, ובספר הישר תשובה אליו. כנראה הוא ר יוסף מבורגנא."},{"i":1795,"n":"אהרן מבישנקוביץ","b":"מגדולי תלמידי ר דב בר מליובאויטש, ור אהרן מסטראשלא. רב בסעננא, בישנקוביץ."},{"i":1796,"n":"אהרן מברודא","f":"יצחק","b":"דיין בברודא, חתם-תקיח עם ר מנחם מנדל דייטש מנייטרא, ור חיים אילאווי מברודא."},{"i":1797,"n":"אהרן מברלין","f":"יצחק בנימין וולף-נחל","dt":"תפא - א אב","dp":"פפד\"א","b":"חתן דודו הגביר ר יודא ברלין. רב במחוז ניימרק ופומורן-תנז תחת ר שמעיה רב ברלין והמדינה, רב וראש ישיבה בברלין-תסט על מקום ר שמעיה בן אברהם ישכר בר בעזרת חותנו וחותנתו והיה מחלוקת כנגדו מצד מתנגדי משפחת חותנו ועבר לכהן כרב בפפד\"מ וגיסו ר מיכל חסיד על מקומו אחריו-תעד. הסכים על כמה ספרים ובהם \"עוז לאלהים\" לנחמיה חייא חיון מצפת ועל כך היה מחלוקת כנגדו משנתבררה נטייתו השבתאית של נחמיה חיון. חתניו: ר הירש אספורט, ר יהודה ליב בן שאול מפפד\"א."},{"i":1798,"n":"אהרן מברלין","f":"יצחק איזיק","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":1799,"n":"אהרן מברסלב","f":"משה מקארסאן","bt":"תקלה","dt":"תרה - א אב","b":"הוא ואביו מתלמידי ר אהרן מטיטיוב, תלמיד ר נחמן מברסלב. רב בקארסאן בחיי אביו, אב\"ד ברסלב-תקסג. בניו: ר צבי אריה, ור נחמן."},{"i":1800,"n":"אהרן מגולדינגן","f":"אלחנן","k":"בעל מנחת אהרן","dt":"תריא","dp":"ריגא","b":"תלמיד ר חיים מוולוזין. רב בגולדינגן-תקפו, בויסק על מקום ר מרדכי רבינר, ריגא-תקצב."},{"i":1801,"n":"אהרן מגרודנא","f":"חיים בן שמואל קמינקר","k":"בעל מורה דרך","b":"נכד ר שמואל מרבינו (קמינקר). חיבר ספר על נדודי בני ישראל במדבר וחלוקת הארץ לשבטים בשם \"מורה דרך\" - גרודנא תקצו."},{"i":1802,"n":"אהרן מדוברובנא ולאזני","b":"מגדולי תלמידי ר מנחם מנדל מליובאויטש, ובנו ר יהודה ליב ונכדו ר שלמה זלמן מקפוסט. ר\"מ בדוברוונא, ויטבסק, רב בליאזני(=לאזני)-תרם."},{"i":1803,"n":"אהרן מדוידהורדוק","b":"רב בדוידהורדוק"},{"i":1804,"n":"אהרן מדמשק","f":"חיפא","b":"מחכמי דמשק-שן. נזכר בספר חזיונות לר חיים ויטאל."},{"i":1805,"n":"אהרן מהאראדאק","bp":"אוסטרהא","b":"ממשפחת הרב ייב\"י. פגש את הבעשט באוסטרהא בהיותו בן 7. עבר להאראדאק, תלמיד ר שניאור זלמן מליאדי."},{"i":1806,"n":"אהרן מהורדנא"},{"i":1807,"n":"אהרן מהיבנוב","b":"רב בהובאנוב"},{"i":1808,"n":"אהרן מהשטיפט פדרבורן","b":"מחכמי אשכנז. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":1809,"n":"אהרן מואלינוב","f":"סיני","b":"רב בואלינוב(=וולאנוב)-תר\"כ"},{"i":1810,"n":"אהרן מוארשא","f":"ישראל מסטולין","bt":"תרמז","b":"חתן ר נתן דוד מפרצוב (פשיסחא). עבר לוארשא וכיהן כמנהיג חסידי קרלין בפולין אולם סירב לאדמורות. נהרג עק\"ה - כשניסה להציל אישה מתוקף נאצי."},{"i":1811,"n":"אהרן מוואשאן","b":"רב בוואשאן-תקע\"א"},{"i":1812,"n":"אהרן מוושוואר","b":"מו\"צ בוואשוואר"},{"i":1813,"n":"אהרן מוילנא","f":"שלמה זלמןןןןןןןןןןןן","dt":"תקעג - כא תשרי","dp":"וילנא","b":"דיין בוילנא. הסכים על \"תולדות אדם\"-תקנח, \"שבט ביהודה\"."},{"i":1814,"n":"אהרן מוילנא","f":"אברהם","b":"רב בוילנא, חתם-תסה עם ר מרדכי בן ישראל, ר יהודה ליב בן ישראל חריף, ר שמואל זנויל מייזלש."},{"i":1815,"n":"אהרן מוילנא","f":"שלמה זלמן בערקש","b":"גביר מראשי קהלת וילנא, חתם-תע בפנקס הקהלה."},{"i":1816,"n":"אהרן מוילקומיר","bp":"וילנא","dt":"תרט","b":"רב בראגולה, אב\"ד וילקומיר כ-60 שנה על מקום ר יהודה ליב זלקינד. מתנגד לחסידות - ואחר פטירתו פרצה מחלוקת עם החסידים שמינו רב משלהם ולאחר שנתיים ויתרו ונבחר ר בנימין רבינוביץ מראגולה על מקומו אחריו."},{"i":1817,"n":"אהרן מוירצבורג","f":"אהרן מבורגנא","b":"נזכר בתוס' שאנצי ישנים, והוא ט\"ס וצ\"ל ר אהרן מבורגנא."},{"i":1818,"n":"אהרן מזולקווא","f":"יוסף","b":"מחכמי זולקווא, חתם-תקנא על החרם הגדול הנדפס ב\"לוחות העדות\" עם עוד 12 חותמים."},{"i":1819,"n":"אהרן מזולקווא","f":"יצחק","b":"מחכמי זולקווא, חתם-שפא עם ר אברהם בן שמואל מרגליות."},{"i":1820,"n":"אהרן מזולקווא - א","f":"משה הקדוש","dt":"שפה - ז כסלו","dp":"זולקווא","b":"גביר מחכמי זולקווא, נזכר-שעה בפנקס הקהלה, נתן ספר תורה לביהכ\"נ."},{"i":1821,"n":"אהרן מזולקווא - ב","f":"משה","b":"מחכמי זולקווא, חתם-שפ על תקנת הקהלה."},{"i":1822,"n":"אהרן מזיטומיר ואשוואר","f":"מרדכי","k":"בעל תולדות אהרן","dt":"תקעז-פב-כו תשרי","b":"תלמיד ר לוי יצחק מברדיטשוב. רב בזיטומיר-תקנח, עבר להונגריה והיה בקראלי, אשוואר, וארגן בהם קהלות חסידים, וקהילת אשוואר הפכה לחסידית בהשפעתו. חתנו ר מרדכי בן ר אריה ליב."},{"i":1823,"n":"אהרן מזלוזיץ","b":"מג\"מ בוולדטשיק,זאלוזיץ"},{"i":1824,"n":"אהרן מזלוטשוב","dt":"תיט - ה אב","b":"רב בזלאטשוב"},{"i":1825,"n":"אהרן מזקראטשין","f":"יהודה ליב","dt":"תקפו - כד חשון","b":"רב בזקראטשין. בנו - ר ישכר מימון מפראגא."},{"i":1826,"n":"אהרן מחודרוב","b":"תלמיד ר אלימלך מליזנסק. מחותנו של ר משה מאיהל."},{"i":1827,"n":"אהרן מטבריה","f":"יצחק","k":"אהרן הגדול","b":"מראשי עדת החסידים בטבריה, בשנת תקמו שליח בפולין ורוסיה, על מכתב ההמלצה חתמו ר מנחם מנדל מויטבסק ור אברהם מקליסק. נקרא \"אהרן הגדול\" להבדילו מר אהרן מסאמליין משמשו של ר מנחם מנדל מויטבסק שהיה נרא \"אהרן הקטן\""},{"i":1828,"n":"אהרן מטבריה","f":"יעקב משקלוב","k":"בעל שבחי ירושלים"},{"i":1829,"n":"אהרן מטבריז ראש גלות","f":"יוסף בן דניאל","b":"ראש גלות-ד'ן. נזכר אצל חכם ערבי שכתב שראה אצלו שלשלת יחוס מדוד המלך. ונרשם בחבריז-בארץ המונגולים."},{"i":1830,"n":"אהרן מטולטשין","f":"מאיר - מהר\"ם מלובלין","b":"אב\"ד טולטשין. נפל בשבי-תח יחד עם עשרה רבנים - על מנת שאביו יפדהו."},{"i":1831,"n":"אהרן מטיטיוב","f":"צבי בן הבעשט","k":"ארלי מטיטיוב","dp":"פאוויליטש","b":"נכד הבעש\"ט ותלמידו. ישב בקונסטנטין ישן, עבר לטיטיוב ופאוויליטש."},{"i":1832,"n":"אהרן מטרבוולא","b":"רב בטרבוולא-ת\"פ"},{"i":1833,"n":"אהרן מטרבוולי","f":"יצחק","dt":"תרא - כד אב","b":"רב בטרבוולי"},{"i":1834,"n":"אהרן מטשקטורנא","b":"רב בטשאקטורנא-תקפ\"ח"},{"i":1835,"n":"אהרן מיורק-אנגליה","f":"יוסי","dt":"טו","b":"רב באנגליה-ד'תתקצז, ואחראי על המסים של היהודים יחד עם הדיין ר אליהו דיסוגאנוס. לאחר פטירתו החרים המלך את כל רכושו. בנו - קוק, ובתו ויניצירה."},{"i":1836,"n":"אהרן מירושלים","f":"עזוז","b":"סופר הקהלה בירושלים, נזכר בשטרות וחתימה ממנו משנת רפז, מופיע בשות ר יעקב בירב סימן ד ובשות ההרלבח ס\"א"},{"i":1837,"n":"אהרן מירושלים","f":"מאיר","b":"עלה לארץ מליטא, חתם-תקמט על מכתב (קרית ספר שנה ד)."},{"i":1838,"n":"אהרן מלאסק","f":"אברהם","k":"ארון נאמן","dt":"תרד - כ סיון","dp":"לאסק","b":"דיין בלאסק."},{"i":1839,"n":"אהרן מלבוב","f":"ישכר בר","dt":"תסב - ו ניסן","dp":"לבוב","b":"ר\"מ בלבוב."},{"i":1840,"n":"אהרן מלבוב","f":"פנחס","dt":"תיא - א תמוז","dp":"לבוב","b":"דיין ור\"מ בלבוב, חתם-תח עם ר יהודה ליווא אפשטין ונזכר ב\"איתן האזרחי\"."},{"i":1841,"n":"אהרן מלובלין","f":"יוזפא","dt":"שעט - כ חשון","dp":"לובלין","b":"מחכמי לובלין."},{"i":1842,"n":"אהרן מלובלין","f":"יהודה ליב","dp":"לובלין","b":"דיין בלובלין."},{"i":1843,"n":"אהרן מלונטשיץ","b":"מחכמי פולין-שן בזמנו של ר שכנא. רב וראש ישיבה בפרג, רב בפוזנא. היה נגד לימוד הפילוסופיה ואף נגד לימוד ספרי הרמב\"ם והיה מחלוקת נגדו ואף יצא קונטרס כנגדו (יש אומרים שמחבר הקונטרס היה ר אברהם הלוי אביו של בעל השל\"ה). בניו: ר אפרים בעל \"עוללות אפרים\", ר משה מהורדנא. חתנו - ר יוסף אשכנזי שעלה לצפת בזמן האר\"י."},{"i":1844,"n":"אהרן מלוניל","f":"משלם מלוניל","dt":"ד'תתקע-תתקסה","b":"מגדולי הראשונים, רב בלוניל. השיב לרמ\"ה(=ר מאיר הלוי מטולידו) בשם חכמי לוניל על השגותיו של הרמ\"ה על ספרי הרמב\"ם - ונדפס ב\"אגרות הרמ\"ה\". נזכר שמו בטעות במק\"א כר אהרן מפולג. אחיינו-בן אחותו ר משלם מביא מתורתו. מתלמידיו ר שמואל ן תיבון. (הרמ\"ה נפטר בשנת ה'-ד - כלומר 34 שנים אחריו ואולי יש חכם אחר בשם זה שחלק על הרמ\"ה)."},{"i":1845,"n":"אהרן מלוניל","f":"משלם","dt":"ד'תתקסה","b":"נזכר שמו בטעות במק\"א כר אהרן מפולג."},{"i":1846,"n":"אהרן מלונינץ","f":"זאב וולף מדויד הורוד","k":"אדמור מלונינץ","b":"בן האדמור מדויד הורודוק. חתן ר שמאי דרוהוביטשער ממזבוז. רב ואדמור בלונינץ. כונה ע\"י הגויים \"הרב היפה\". נספה בשואה."},{"i":1847,"n":"אהרן מלכוויץ","f":"מרדכי מלעכוויץ","b":"חתן ר אשר מקרלין. רב בלעכוויץ-ת\"ר"},{"i":1848,"n":"אהרן מלעווא","b":"רב בלעווא-תר\"י"},{"i":1849,"n":"אהרן ממאלטש","dp":"פרוזין","b":"מו\"ץ ומ\"מ במאלטש."},{"i":1850,"n":"אהרן ממאליאט","f":"יחזקאל","b":"רב במאליאט-ליטא-תקצג."},{"i":1851,"n":"אהרן ממאראנאויי","f":"ישעיה","k":"בעל לחם תרומה","b":"מחכמי איטליה. חיבר \"לחם תרומה\" - \"מדות חכמים\" - \"לחם מן השמים\"."},{"i":1852,"n":"אהרן ממזבוז","b":"תלמיד הבעשט. ואולי הוא המכונה ר \"אהרן משרת\"."},{"i":1853,"n":"אהרן ממזריטש","b":"רב במזריטש-תק\"נ"},{"i":1854,"n":"אהרן ממיטאוי","f":"צבי הירש חריף ממיטאו","dt":"תקסג - טו כסלו","dp":"מיטאוי","b":"מחכמי מיטאוי."},{"i":1855,"n":"אהרן ממיכאילשוק","f":"יחיאל מיכל ממיכאילשו","k":"בעל קרבן אהרן","dt":"תקפה","b":"חיבר סידור \"נהורא\" (והוא היפוך אותיות \"אהרן\") - אוסטרהא תקע, ופירושים למחזור בשם \"מטה לוי\", \"בית לוי\" \"קרבן אהרן\", ועוד. בניו: ר יוסף זאב וולף לוינזון-הו\"ל ספרי אביו, ר פנחס מוילנא, ר רפאל אליהו ממיכאילשוק(=מיכאילישוק), ר אברהם מיכל מווולוזין, ר יצחק מרדכי מקלצקי."},{"i":1856,"n":"אהרן ממצרים","f":"ישועה","k":"אלעומאני","b":"חכם בארץ ישראל ואחר כך במצרים, ר יהודה הלוי התאכסן בביתו בדרכו לארץ,"},{"i":1857,"n":"אהרן מנעמפילבורג","f":"אליעזר","k":"בעל קרבן אהרן","b":"רב בנעמפילבורג בזמן ר שעפטל סגל מפוזנא ור אברהם פונסיקא מאמשטרדם. חיבר \"קרבן אהרן\" - אמשטרדם תז."},{"i":1858,"n":"אהרן מסאהל","b":"מו\"צ בסאהל"},{"i":1859,"n":"אהרן מסאלא","k":"אהרן הסבעוני","b":"מקובל,רב בסלא-שנת ת'"},{"i":1860,"n":"אהרן מסטולין","b":"נכד ר שמשון מאוסטרופולי. רב בפאהאסט,סטולין"},{"i":1861,"n":"אהרן מסטניסלב","f":"אביגדור","b":"רב בסטניסלב."},{"i":1862,"n":"אהרן מסיציליה","f":"גרשון","k":"בעל נזר הקדש","b":"חתן ר משה ן גבאי. רב בקטיניאה-סיציליה-קן. היה בויכוח ברומא אצל האפיפיור, היה בויכוח עם הקראים, היה במחלוקת עם הנגיד ר משה חפץ. חיבר גם \"מטה אהרן\", ועוד. נזכר בשו\"ת הרדב\"ז שהשיג עליו. כנראה שנדד בארצות שונות, האמין באסטרולוגיה ואין דעת חכמים נוחה ממנו בגלל שהשיג על הקדמונים בלשון קשה."},{"i":1863,"n":"אהרן מסלונים","dt":"תקפט - כג אלול","b":"מו\"צ בסלונים-תקל\"ט"},{"i":1864,"n":"אהרן מסלחוב","f":"צבי הירש מטשדונוב","b":"מצאצי הבעשט. חתן ר דב בערצי מטלוסט האדמור מקוריץ."},{"i":1865,"n":"אהרן מסלפקוביץ","b":"מג\"מ סלאפקוביץ-תק\"כ"},{"i":1866,"n":"אהרן מספרד","f":"אביי","b":"מחכמי ספרד"},{"i":1867,"n":"אהרן מעכו","f":"יצחק","b":"עלה לארץ והתישב בעכו-ה'מו. חתם עם חבריו על חרם ראש הגולה מדמשק על החולקים על הרמב\"ם."},{"i":1868,"n":"אהרן מפטר","b":"מתורתו ב\"מנחת יהודה\" לר יהודה בן אליעזר יחד עם אביו. אולי הוא מאבותיו של ר אהרן בעל ספר הגן."},{"i":1869,"n":"אהרן מפילוישוק","f":"צבי הירש","b":"רב בפילוישוק."},{"i":1870,"n":"אהרן מפינסק וקרטינגה","k":"בעל תוספות אהרן","dt":"תרא-ה","dp":"פינסק","b":"רב בשילאל, קרטינגה, פינסק ור מרדכי זקהיים על מקומו אחריו."},{"i":1871,"n":"אהרן מפיסרו","k":"בעל תולדות אהרן","b":"מגדולי חכמי איטליה, רב בניקולאורה, פיסארו-שיא. חיבר \"תולדות אהרן\" - והוא מראה מקומות לדרשות הגמרא על פסוקי התורה - נדפס עם \"תולדות יעקב\" לר יעקב ששפורטש. סייע בהדפסת פירוש אברבנל על התורה. בנו - ר מיכה, ונכדו ר יהודה."},{"i":1872,"n":"אהרן מפפד\"מ","b":"מגדולי חכמי פפד\"מ-תק\"י"},{"i":1873,"n":"אהרן מפפד\"מ","f":"נתן","b":"מחכמי פפד\"מ. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":1874,"n":"אהרן מפפנהיים","b":"מחכמי רגנשבורג ופפנהיים-רן. אחיו של ר יצחק שטיין. תלמיד ר יונה בעל או\"ה, ור טבלי מנירנברג. נזכר בספרי חכמי דורו."},{"i":1875,"n":"אהרן מפראפאיסק","f":"יעקב משקלוב בן יהודה","b":"רב בפראפאיסק, קראסנא-פאלע, שקלוב. הו\"ל ספר אביו בשם \"מורה צדק\". (בתולדות אנשי השם - בנו של ר ברוך משקלוב ונכדו של ר יעקב)"},{"i":1876,"n":"אהרן מפרובנס","f":"פרץ","b":"רב באביניון-פרובנס-ה'קן. נזכר ב\"מנחת קנאות\"."},{"i":1877,"n":"אהרן מפשדבורז","b":"רב בפשדבורז-ת\"מ"},{"i":1878,"n":"אהרן מצילץ","b":"רב בצילץ-תק\"מ"},{"i":1879,"n":"אהרן מצפת","f":"גבריאל","b":"מחכמי צפת, בשנת שפא חתם על ההזמנה לר ישכר בר איילינבורג."},{"i":1880,"n":"אהרן מקאטה","b":"רב בקאטה"},{"i":1881,"n":"אהרן מקולין(=לינקולן)-אנגליה","f":"יוסי","b":"רב בניקולה(=קולין=לינקולן)-אנגליה, נזכר בספר הגן. בניו: אברהם, ברוך, דוד אליהו, חיים."},{"i":1882,"n":"אהרן מקונטברי","f":"דוד","b":"סופר ב\"ד בקונטברי-אנגליה-ה'מ בערך."},{"i":1883,"n":"אהרן מקונטברי-אנגליה","f":"שמשון","b":"מחכמי אנגליה-ה'ן, ונקרא ר אהרן מקונטבריאה(=מקונטרבורי). אביו שהיה עשיר גדול וכשנפטר הוכרחו בניו לשלם מס גדול על ירושתם למלכות."},{"i":1884,"n":"אהרן מקושטא","f":"אביי","b":"מחכמי קושטא-רן. היה במחלוקת עם ר משה קפסלי."},{"i":1885,"n":"אהרן מקיטוב-תלמיד הבעש\"ט","f":"אפרים מקיטוב","dt":"תקכ - לפני","b":"גיסו של הבעשט - אחי אשתו. נפטר בחיי הבעשט."},{"i":1886,"n":"אהרן מקיפין","b":"תלמיד ר פנחס מקוריץ. חתנו - ר ישראל בן יוסף מטשאהן."},{"i":1887,"n":"אהרן מקליוואן-ספלקוביץ","b":"תלמיד הבעשט. רב בקליוואן."},{"i":1888,"n":"אהרן מקרדינא","k":"בעל קרניים","b":"מקובל מחכמי ספרד או פרובנס. חיבר גם \"כתרו ישועה\", \"פרח ציץ\", \"קרניים\" ור שמשון מאוסטרופול חיבר לו פירוש בשם \"דן ידין\". מזכיר בספרו את ר אברהם די אודי - והוא כנראה הראב\"ד"},{"i":1889,"n":"אהרן מקרלין הנכד","f":"אשר מסטולין","k":"אדמור מקרלין סטולין","bt":"תקסב","dt":"תרלב - יז סיון","dp":"מלינוב","b":"חתן ר מרדכי מקרמניץ (זלוטשוב). אדמור בקרלין, עבר לסטולין. חיבר \"בית אהרן\", היה מלחין וסופר סת\"ם מומחה. בנו - ר אשר על מקומו אחריו בסטולין.","bk":[["בית אהרן - על התורה ועל העבודה",""]]},{"i":1890,"n":"אהרן מקרמנצוג","f":"אליהו מקרמנצוג","b":"רב בקרמנצוג. נכדו או נינו של בעל התניא."},{"i":1891,"n":"אהרן מקשביץ","f":"אשר למיל","b":"רב בקשביץ, תלמיד הרב הקודם ר צבי."},{"i":1892,"n":"אהרן מקשטיליה","k":"אהרן מטרני,בעל התוס'","b":"מחכמי קאשטיליה,באלטראני שבנאפולי-רס\"ב,בא לאדרינופולי"},{"i":1893,"n":"אהרן מראסיין","f":"צדוק","dt":"תרך - בערך","dp":"ראסיין","b":"מו\"ץ ור\"מ בראסיין."},{"i":1894,"n":"אהרן מראסיין וקובנא","f":"משלם זלמן מראסיין","dt":"תרלד-ו - ד סיון","dp":"קובנא","b":"דיין בראסיין, קובנא."},{"i":1895,"n":"אהרן מרגנשבורג","b":"מבעלי התוספות באשכנז. תלמיד ריצב\"א מדנפיר. חברו של ר יהודה הכהן מפרידבורג. תלמידו - ר אליעזר בעל תוספות טוק. נזכר ב\"אור זרוע\" כ\"לבדו נשאר בדור.. כי יש בו תורה וזקנה..\". נזכר בשטר נכסים בכתבי ערכאות מרגנשבורג-ד'תתקפה."},{"i":1896,"n":"אהרן מרדכי הלוי מראווא","b":"אב\"ד ראווא. מחותנו של ר\"ש מנ\"ש."},{"i":1897,"n":"אהרן מרוטנבורג","f":"אליעזר","k":"מגדולי הראשונים","b":"פוסק דורו ברוטנבורג-שנת כ'"},{"i":1898,"n":"אהרן מרוסיה-ליטא","f":"מנחם","k":"בעל סייג לתורה","b":"רב-תקע, חיבר \"סייג לתורה\" ובו ציונים ומראה מקום על הש\"ס."},{"i":1899,"n":"אהרן מרכניץ","b":"ראש קהלת רכניץ. השתתף באספת נציגי יהדות הונגריה-תקנא ברכניץ בענין הגיוס לצבא - ותמך בדעת ר קופל טעבן מפרשבורג - להתנגד - והצליחו."},{"i":1900,"n":"אהרן משה הכהן מקראקא","f":"יוסף - שארית יוסף","dt":"שעו - ט אדר","dp":"קראקא","b":"מגדולי חכמי קרקא-שן. אחיינו של הרמ\"א."},{"i":1901,"n":"אהרן משה יצחק גר צדק משבדיה","dt":"תקסג - ל אדר","b":"מאצילי שבדיה שהתגייר-תק\"ט,מקובל,מו\"צ באמסטרדם"},{"i":1902,"n":"אהרן משה מלבוב וגריידונג","f":"צבי הירש","k":"בעל הלכה למשה","b":"נכד ר שלמה סגל חריף מלבוב. דיין בלבוב-תקל. חיבר \"הלכה למשה\", אהל מועד\" זולצבך. אחיו - ר מנחם מנדל משינאווי בעל \"שיחת חולין\"."},{"i":1903,"n":"אהרן משה מקראטי","b":"תלמיד ר פנחס מקוריץ. רב בקראטי (פודוליה)."},{"i":1904,"n":"אהרן משוורניק","b":"רב בשווערניק-תק\"פ"},{"i":1905,"n":"אהרן משטפינשט","b":"תלמיד ר משולם זוסיא מאניפולי, ובנו ר צבי מנחם מנדל. רב בשטפינשט בזמן ר חיים מטשרנוביץ."},{"i":1906,"n":"אהרן משיניבה","b":"רב בשינאווי"},{"i":1907,"n":"אהרן משלם זלמן (תאומים)","b":"חתן ר מנחם מנדל מפרג. אבי משפחת תאומים (את השם תאומים קיבל נכדו)."},{"i":1908,"n":"אהרן משלם מלויצק","b":"רב בלויצק(=לוצק)."},{"i":1909,"n":"אהרן משפנהויזן","dt":"קח-ט","b":"מחכמי אשכנז. נהרג עק\"ה-בגזירות קח-קט ונזכר בפנקס מגנצא."},{"i":1910,"n":"אהרן משקלוב","f":"ישראל","k":"בעל אבן תקומה","b":"מחכמי ליטא-תקם. חיבר גם \"מנחת אהרן\", \"מדות אהרן\", ועוד. בנו - ר מרדכי (שהסכים על \"חדושי מהר\"י (ר יעקב בן לוי מבריסק)."},{"i":1911,"n":"אהרן ן, דוד מטריפולי","b":"רב ומשורר בטריפולי. חיבר קובץ פיוטים - נזכר אצל חיים כחלון (\"ההעפלה מלוב\")."},{"i":1912,"n":"אהרן ניסן מוינה","b":"גביר מראשי ומיסדי עדת יהודי תוגרמה בוינה-תעח (על פי הסכם השלום בין האוסטרים לתורכים)."},{"i":1913,"n":"אהרן סגי נהור מירושלים","f":"אליעזר בן דוד","k":"בעל ספר המצנפת","b":"נכד ר משה ארוך. מלמד בירושלים, עבר למצרים, חזר והתישב בצפת-שה, חיבר \"ספר המצנפת\" מנטובה שכא, במכתב ר ישראל מפירושא (המעמר כרך ג) כתוב על חכם ר אהרן סגי נהור שהלך למצרים לזמן ארעי, ריבלין משער שהוא ר אהרן הנ\"ל"},{"i":1914,"n":"אהרן סגל מברודשין","b":"רב בברודשין-תרלז."},{"i":1915,"n":"אהרן סגל מואנילוב","f":"צבי הירש","b":"דיין בואנילוב(=וואנילוב), חתם-תלג עם ר שניאור פיבש בן דוד ור מנחם בן צבי כץ."},{"i":1916,"n":"אהרן סגל מלבוב","f":"בנימין","dt":"תג - ה אלול","dp":"לבוב","b":"חתן ר יצחק בן יהודה ליב מירושלים. ר\"מ בלבוב לצד חותנו. נפטר צעיר."},{"i":1917,"n":"אהרן סטן הרופא ריפאח","b":"חיבר ספר ברפואה והובא בשו\"ת ר יוסף קארו. בניו: ר מאיר, ר יוסף, ונכדו ר טוביה."},{"i":1918,"n":"אהרן עובדיה מחברון","bt":"תקמט","bp":"חברון","dt":"תרכו - לפני","b":"מחכמי חברון, חתום על אגרת חכמי חברון בשנת תקץ, חתימות שונות מהשנים תקץ-תרכב"},{"i":1919,"n":"אהרן עזריאל מירושלים - קונורטי","f":"עזריאל קונורטי","k":"בעל כפי אהרן","bt":"תקעט","bp":"ירושלים","dt":"תרלט - ט סיון","dp":"יפו","b":"נכדו של ר אביגדור עזריאל בעל \"זמרת הארץ\", למד אצל ר נסים שמואל ארואץ המכונה \"הרב הנשי\"א\", ור רפאל ידידיה אבולעפיה המכונה \"הרב היר\"א\". כיהן כראש ישיבת \"בית אל\" בירושלים. חיבר \"כפי אהרן\" ירושלים תרלד, \"אזן אהרן\" ירושלים תרמו, ועוד. פיוטים ממנו מפוזרים בספריו וגם בספר \"יגל יעקב לר יעקב בורלא, ו\"יצחק ירנן\" לר רפאל יצחק אלטארס. היה שליח חברון וירושלים, בקורפו-תרך, מכתב ששלח לבנו מיוון נדפס בשם \"מוסר אב\" בסוף ספרו \"אזן אהרן\", חתם בשנת תרלב על כתב שליחות ר אברהם בן שלמה. עליו ועל משפחתו בספר \"תשע דורות למשפחת עזריאל בירושלים\"."},{"i":1920,"n":"אהרן עזריה הלוי מאיטליה","f":"מרדכי","b":"מראשי קהלת דוכסות פארמה-תקיח עם ר אברהם מיכאל פונטאנילה."},{"i":1921,"n":"אהרן פוטמאכר מבענטשען","b":"אב\"ד בענטשען-תרה. מכתב ממנו לראשי קהלת המבורג - בקשת עזרה לאחר השריפה."},{"i":1922,"n":"אהרן פלומלין הקדוש מאוסטריה","dt":"קפא - ט ניסן","dp":"וינה","b":"תלמיד קרובו ר שלום בן יצחק מוינה (=מהר\"ש), חברו של המהרי\"ל. גיסו של ר אברהם קלויזנר (=מהרא\"ק). רב בקרימזא-אוסטריה-קן, וינה על מקום ר יעקל. נהרג עק\"ה יחד עם אחותו-אמו של ר ישראל איסרלן בעל תרומת הדשן. נכדו - ר יודא בר מורקל. מתלמידיו: אחיינו-בן אחותו - ר' ישראל איסרלן בעל \"תרומת הדשן\", מוהר\"ר מיישטרלן מניישטט, ר טבלי, ר איזיק טירנא. נזכר בספרי חכמי דורו ובהם המהרי\"ל, \"תרומת הדשן\", ועוד."},{"i":1923,"n":"אהרן פרץ","b":"מתורתו בספר \"קרני ראם קטן\"."},{"i":1924,"n":"אהרן פרץ מחברון","b":"מחכמי חברון, בשנת תקלב חתום בין גדולי חברון, בשנת תקלה חתם על אגרת בקשה לעזרה, בשנת תקסג חתם על אגרת שליחות ר רחמים בגאיו ור יצחק זאבי, בשנת תקמב על אגרת שליחות ר שמואל הכהן"},{"i":1925,"n":"אהרן פרץ מחברון","b":"מחכמי חברון, חתום בשנת שעו על מכתב בקשה של רבני חברון"},{"i":1926,"n":"אהרן פרץ משלוניקי","dt":"שסא","dp":"שלוניקי","b":"מחכמי שלוניקי-שן."},{"i":1927,"n":"אהרן צבי מביאלא","f":"דוב בעריש מביאלא","dt":"תרע - ז סיון","b":"רב בביאלא"},{"i":1928,"n":"אהרן קוטי מיוון","b":"רב בטיבש(=טעוון)-יון. נזכר במסעות ר בנימין מטודלה שפגש בו-ד'תתקל, ואת אחיו ר משה, והעיד עליו שהוא מגדולי הדור."},{"i":1929,"n":"אהרן שו\"ב מהורודוק","f":"יעקב קאסעס","b":"נכד ר ברוך תלמיד הבעשט. תלמיד ר אשר מסטולין שהזכירו לשבח במכתב. מתורתו ב\"בית אהרן\"."},{"i":1930,"n":"אהרן שותק מזליחוב","dt":"תקלח","b":"תלמיד מובהק לר עוזיאל מייזליש מריטשוואהל. רב בזליחוב-תקלד. נקרא ה\"שותק\" או ה\"אילם\" על שיותר מעשרים שנה ישב על התורה והעבודה ולא דיבר עם שום אדם מאומה. בנו ר משה דב מטבריה.."},{"i":1931,"n":"אהרן שטאציק מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":1932,"n":"אהרן שלום הלוי"},{"i":1933,"n":"אהרן שמואל מצפת","f":"משה מגיד מוילייקה","dt":"תרסד - כד חשון","b":"עלה לארץ-תקצו עם אביו ואחיו ר מרדכי."},{"i":1934,"n":"אהרן שמואל מקרמניץ","f":"משה שלום","k":"בעל נשמת האדם","b":"רב בפיורדא (או פולדא)-שעח. חיבר \"נשמת האדם\" וילהמשדורף."},{"i":1935,"n":"אהרן שמעון (שמשון) מקולוניא","f":"יעקב אברהם מקופנהגן","k":"בעל אור הישר","b":"סופר ונאמן דקהילת קולוניא. רב בבונא-תקכ. חתן ר יודא מילד. היה סופר הגט מקליווא-תקכו - שעורר מחלוקת גדולה בין הרבנים. חיבר \"אור הישר\" אמשטרדם."},{"i":1936,"n":"אהרן שמעון מימפולא","b":"רב ביאמפלא"},{"i":1937,"n":"אהרן, אריה ליב מוילנא","f":"שמחה","b":"רב בוילנא, חתם-תמד על פסק דין עם ר שמואל בן מאיר, ר יוסף בן יעקב, ר אהרן בן אברהם הלוי הער."},{"i":1938,"n":"אהרן, יוסף מארה\"ב","k":"בעל מפתח אל לשון העב","b":"רב בארה\"ב. חיבר \"מפתח אל לשון העברי\" נ\"י תרצד."},{"i":1939,"n":"אהרנובסקי, מנחם מנדל","f":"אהרן","k":"בעל מנחם בכורים","bt":"תרל","b":"מצאצאי ר יצחק אבן טוב מוועטקא, נכד ר ישראל אהרנובסקי מסטראדוב. חתן הגביר ר עקיבא הכהן מאסטער-פלך צרניגוב. תלמיד כולל קובנא. רב בסמנובקה(=סעמיאנאווקא)-פלך צרניגוב-תרסו. נסמך מאת: ר יצחק אלחנן מקובנא, ר משה דנישבסקי, ר שלמה הכהן מוילנא, ר חיים יהודה סוסניצער מסמרגון, ר רפאל שפירא מוולוזין, האדמור מהורנסטיפל. חיבר שו\"ת וחדושים בשם \"מנחת בכורים\" - בכת\"י."},{"i":1940,"n":"אהרנסון יהושע משה","bt":"1910","dt":"ה'תשנג 1993","bk":[["ישועת משה",""]]},{"i":1941,"n":"אהרנסון, אברהם מארץ ישראל","b":"עסקן צבור, פעל להקמת ישיבת \"היכל התלמוד\" בתל אביב-תרצד."},{"i":1942,"n":"אהרנסון, יהושע משה מפתח תקוה","k":"בעל ישועות משה","b":"דיין בפתח תקוה. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד. חיבר \"ישועות משה\"."},{"i":1943,"n":"אהרנסון, יוסף צבי מארה\"ב","k":"בעל שקל יוסף","b":"רב בארה\"ב. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":1944,"n":"אהרנסון, יעקב הכהן","b":"רב בקרוצ'-תרכ\"ה"},{"i":1945,"n":"אהרנסון, מיכאל אליהו","b":"פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":1946,"n":"אהרנסון, מנחם מנדל מליטא","bp":"ראסיין-ליטא","b":"רב בליטא, היגר לדרום אפריקה והיה ממנהיגי ה\"מזרחי\"."},{"i":1947,"n":"אהרנסון, משה זלמן","f":"שמואל הלל","k":"בעל מורה נבוכי הדור","b":"מורה עברי והוגה דעות. תרגם את \"אגרות צפון\" ו\"חורב\" לרש\"ר הירש. הו\"ל \"תורה אור\" עם תרגום ופירוש \"עטרת צבי\" לרש\"ר הירש עם תרגום עברי."},{"i":1948,"n":"אהרנסון, משה מסלנט","k":"בעל פרדס הבינה","bt":"תקסה","bp":"סלאנט","dt":"תרלה - כה אלול","dp":"שיקגו","b":"רב בכמה קהלות ברוסיה, רב בראצקי, עבר לארה\"ב-תרכב (הרב הראשון מרוסיה שעבר לאמריקה) וכיהן כרב בניו יורק. היה במחלוקת עם רבני ניו יורק בענין הכשר יין קליפורניה, ובענין שליחי ישיבת \"עץ חיים\" מירושלים, ונאלץ לעזוב את ניו יורק, והגיע לשיקגו-תרלג. חיבר גם \"מטעי משה\" הכולל שו\"ת שהשיב באמריקה."},{"i":1949,"n":"אהרנסון, משה מראצקי ונ\"י","k":"בעל מטעי משה","b":"רב ברוצקי, ניו יורק-תרלח."},{"i":1950,"n":"אהרנסון, ניסן מדובנא","k":"בעל עצי לבונה","b":"דומ\"צ בדובנא-תקס. חיבר גם \"מעין גנים\". מתלמידיו - ר חיים יעקב אשכנזי מדובנא."},{"i":1951,"n":"אהרנסון, שלמה הכהן מקיוב","f":"יעקב","bt":"תרכג","bp":"קריצי (מוהילב)","dt":"תרצה - כ אד\"ב","dp":"תל אביב","b":"למד אצל אביו ואצל אחיו ר אברהם בלאדי. רב בגלוחוב, נייזין, קייב(=קיוב). עלה לכהן כרבה הראשי של תל אביב בשנת תרפד."},{"i":1952,"n":"אובן מצרפת","b":"נוסע צרפתי שחיבר ספר על אודות מרוקו והיהודים שם, ותורגמו ב\"היהודי\" - לונדון תרסו."},{"i":1953,"n":"אובצינסקי, לוי ליב מאלט אויטץ","f":"דב יונה","k":"בעל נחלת אבות","bp":"דויגלישקי-פלך וילנא","dt":"תשג","b":"תלמיד ישיבת שוינציאן, לידא, ר נחמן אידל מיקובשטט. נסמך מאת ר נחמן אידל מרגליות מיאקובשטט, ר שלמה הכהן מוילנא. רב \"מטעם\" באלט-אויטץ-קורלנד, מיטאוי. חיבר \"נחלת אבות\" - לתולדות גדולי ישראל שלא נזכרו ב\"שם הגדולים\", \"תולדות ישיבת היהודים בקורלנד\". נספה בשואה. נסמך מאת: ר שלמה הכהן מוילנא, ר יצחק יעקב ריינס."},{"i":1954,"n":"אוברברייט, עזריאל עוזיאל מפרשב","dt":"תרנב - כא אלול","dp":"פרשבורג","b":"תלמיד החת\"ס, ור מרדכי בנט מניקלשבורג. חתן ר ברוך בייא-רוט מפרשבורג. מו\"ץ בפרשבורג - אצל השב\"ס."},{"i":1955,"n":"אוברניק, יהודה מאיטליה","dt":"רל","b":"מגדולי חכמי אשכנז,רב במיישטרי באיטליה"},{"i":1956,"n":"אוגווילוס, אברהם מפאס","dt":"שכג-ה - לפני","dp":"פאס?","b":"רב בפאס-שה."},{"i":1957,"n":"אוגווילוס, יעקב מפאס","f":"שמואל","b":"מחכמי פאס-שנות ה-ת'."},{"i":1958,"n":"אוגלו בוגוז, עראפ מקושטא","b":"מדפיס ארמני בקושטא-תקסג."},{"i":1959,"n":"אודאי, יחיא ממרוקו","dt":"תקיג - לפני","b":"מחכמי מרוקו, נזכר אצל ר רפאל עובד ן צור."},{"i":1960,"n":"אודסר, ישראל דב מטבריה","k":"הסבא - בעל הפתקא","bt":"תרמו","bp":"צפת או טבריה","dt":"תשנו","dp":"טבריה","b":"תלמיד ר ישראל הלפרין מקרדון (ר ישראל קרדונר). מחשובי חסידי ברסלב בטבריה. מכתביו נדפס \"אבי הנחל\"."},{"i":1961,"n":"אודרברג, שמעון","b":"תלמיד החוזה מלובלין ומפורסם ברוח הקודש שלו. רב-שנת תקצ. חתם על שטר התנאים של ר יצחק איזיק מקומרנא עם ר אברהם מרדכי מפינטשוב."},{"i":1962,"n":"אוהב","f":"אברהם","b":"פייטן-קן."},{"i":1963,"n":"אוהב הנשיא מספרד","f":"מאיר בן שמירטקס","b":"חכם ופייטן בספרד-ד'תתן. נזכר בספר הקבלה לראב\"ד. חיבר פיוטים ונכנסו למחזור קדום."},{"i":1964,"n":"אוהב, שלמה מראגוזה","k":"בעל שמן הטוב","b":"מקובל,רב בראגוזה-ש\"מ. נכדו - ר אהרן הכהן. חיבר \"שמן הטוב\" ו\"שמן ששון\" ונציה."},{"i":1965,"n":"אוהבי","f":"אברהם","b":"פייטן בספרד-ק'"},{"i":1966,"n":"אוהבי, אברהם מברושא","bp":"קושטא","b":"אב\"ד ברושא-תכז, פעל נגד נתן העזתי שהגיע לעיר. בן משפחתו של ר ישראל אהובי מסופיה."},{"i":1967,"n":"אוהעל, יוסף משאראש-פאטאק","b":"תלמיד החת\"ס. במקורו מאויהל. מחכמי שאראש-פאטאק-תקצא. תשובה אליו ב\"חתם סופר\"-תקצא."},{"i":1968,"n":"אווין, שלום מריגה","b":"חתן ר משה שפירא מריגה (בנו של ר איזל חריף). רב בריגה על מקום חותנו, בזמן מלחה\"ע ה-I היה אחד מ-10 בני ערובה בידי הרוסים כדי לערוב לנאמנות היהודים."},{"i":1969,"n":"אווינון, אברהם מטרבניק","dt":"תרסד - אדר","b":"רב בטרבניק, רב הכולל לקהילה הספרדית בבוסניה, היה תקיף והיה מכה בלחי את העובר על דבריו."},{"i":1970,"n":"אוושאוויץ, אברהם יצחק מארה\"ב","b":"חתן רשא\"ה יפה. רב בפילדלפיה. נפטר צעיר בגיל 35."},{"i":1971,"n":"אוז'אלבו, משה מאדרינופול","b":"גביר באדרינופול, סייע בהדפסת \"דברי חפץ\"-תקנה לר אהרן טולידו."},{"i":1972,"n":"אוזידה, שמואל מצפת","f":"יצחק","k":"בעל מדרש שמואל","bt":"ש-שטו","bp":"צפת","dt":"שסד - בערך","b":"מחכמי צפת, מתלמידי הארי - בשנת שלה חתום בשטר התקשרות תלמידי הארי. תלמיד ר חיים ויטאל אחר פטירת הארי. ראש ישיבה בצפת-שמ. בשנת שנז בשליחות בקושטא. חיבר גם \"אגרת שמואל\" קורוגישמי שנז, ועוד. בשנת שפה היה בירושלים וסבל מפרעות אבן פארוך. מתלמידיו ר יוסף בנבנשת די שיגוביא."},{"i":1973,"n":"אוזליאנער, יהודה ליב ממינסק","f":"צבי","dt":"תרלג - ח טבת","dp":"מינסק","b":"מחכמי מינסק."},{"i":1974,"n":"אוחיון, יהודה ממראקש","b":"מחכמי מראקש-שנות ה-תק', בזמן מהר\"א פינטו, נזכר ב\"קופת הרוכלים\" לר\"י מונסונייגו."},{"i":1975,"n":"אוחיון, יעקב ה\"ן דוד מפאס","f":"דוד","b":"מחכמי פאס, חתם בשטר עדות-תקל, ו-תקנז."},{"i":1976,"n":"אוחיון, יעקב ממראקש","dt":"תקעח - א ניסן","b":"מחכמי מראקש."},{"i":1977,"n":"אוחיון, מוסא ממראקש","f":"דוד","dt":"תקעז - אלול","b":"רב וראש ישיבה במרוקו. תלמידו ר משה רוזיליו בעל קול מבשר מזכירו בספרו. בנו - ר משה."},{"i":1978,"n":"אוחיון, מימון ממרוקו","b":"רב ראשי במרוקו על מקום ר שאול ן דנאן."},{"i":1979,"n":"אוחיון, מכלוף מאספי-מרוקו","b":"סופר באספי-מרוקו, חתם-תקמח ונזכר ב\"תקפו של יוסף\"."},{"i":1980,"n":"אוחיון, מסעוד ממרוקו","dp":"ישראל","b":"שו\"ב מחכמי מרוקו, עלה לארץ."},{"i":1981,"n":"אוחיון, שלם מאופראן-מרוקו","dp":"אופראן-מרוקו","b":"מחכמי מרוקו, נקבר במערת אופראן עם בנו - ר מכלוף."},{"i":1982,"n":"אוחיון, שמואל ה\"ן דוד ממרוקו-א","f":"יוסף","b":"מחכמי תאזא-מרוקו-שנות ה-ת'."},{"i":1983,"n":"אוחיון, שמואל ה\"ן דוד ממרוקו-ב","f":"אברהם","b":"מחכמי תאזא-מרוקו-שנות ה-תק'."},{"i":1984,"n":"אוחיון, שמעון ברוך ממרוקו","f":"אברהם","k":"בעל הליכות שבא","r":"האדמו\"ר מזוועהיל בירושלם","bt":"תרסו","bp":"מוגדור","dt":"תשנא - ניסן","b":"תלמיד ישיבת מראקש, וישיבת \"עץ חיים\" במוגדור. ר\"מ בישיבת \"עץ חיים\" באספי-מרוקו. רב ודיין. עלה לארץ-תשטו וכיהן כרב בכמה מקומות ולאחרונה ביפו."},{"i":1985,"n":"אוחנא, אברהם","b":"דיין במרוקו"},{"i":1986,"n":"אוחנא, אברהם","b":"דיין במרוקו"},{"i":1987,"n":"אוחנא, אברהם","b":"דיין במרוקו"},{"i":1988,"n":"אוחנא, אהליאב","f":"שלמה","bt":"תרנב","bp":"דנמאת(מרוקו)","dt":"תרפב - יח שבט","dp":"טבריה"},{"i":1989,"n":"אוחנא, גד","f":"אברהם אוחנה","b":"רב בעיר מדינה(אלג'יר)"},{"i":1990,"n":"אוחנא, דוד מאלגיר","bt":"תרל","dt":"תש","b":"רב בתייארת, מסתגאנם-תרף. התכתב עם ר יוסף משאש מתלמסאן."},{"i":1991,"n":"אוחנא, יהודה ממכנאס וטבריה","bt":"תקנו","bp":"מכנאס","dt":"תרלג - כג כסליו","dp":"טבריה?","b":"מחכמי מאכנס, בשנת תרכה עלה לטבריה עם נכדו ר רפאל אוחנא בעל \"טובת מראה\" והביא תולדות זקנו בספרו."},{"i":1992,"n":"אוחנא, יהודה ממראקש","f":"אליעזר","k":"בעל פרי מגדים","b":"רב במראקש, תונס-תקסה. חיבר \"פרי מגדים\" דרשות על התנ\"ך."},{"i":1993,"n":"אוחנא, מסעוד מאלגיר","f":"אברהם","b":"רב במדיא-אלגיר-תרל. בנו - ר נסים בנימין."},{"i":1994,"n":"אוחנא, נסים בנימין","f":"מסעוד או סלימן","k":"בעל תורת אמת","bt":"תרמב","bp":"למדייא(=מידיאה)","dt":"תשכב - כז אד\"ב","b":"מחכמי מרוקו, עלה בילדותו לירושלים וכיהן כרב בעזה-תרסד, קהילת יוצאי סוריה בניו יורק-תרעג, מלטה-תרעה, פורט סעיד-מצרים-תרף, קהיר-תרצה, רב ראשי בחיפה-תשז. חתן ר נחמן בטיטו, ובזיוו\"ש חתן ר יצחק משה פיררה. חיבר גם תרגום ש\"ס לעברית, \"נאה משיב\", ועוד. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו.","bk":[["נא\"ה משיב","שו\"ת"]]},{"i":1995,"n":"אוחנא, סולימן ממרוקו וצפת","bp":"פאס","dt":"שצח - אחרי","dp":"צפת","b":"מחכמי פאס, עלה לטבריה בשנת שסג, עבר לצפת ובשנת שסה נמנה על חכמיה, היה קשור עם תלמידי הארי ונחשב לגדול בקבלה. הגיה ספרים חשובים ובהם מדרשים משניות ופירושי הראשונים, חדושיו מובאים בספרי חכמי דורו והדורות הבאים, כגון \"ספרי דבי רב\" לר דוד פרדו. כמו כן היה סופר סתם מפורסם."},{"i":1996,"n":"אוחנא, ציון מצפת","f":"שמעון מצפת","b":"מתלמידי ישיבת הרדב\"ז בצפת, בשליחות במרוקו-תרף."},{"i":1997,"n":"אוחנא, ראובן ממכנאס","b":"חתם-תקכו עם ר חסין ן לחסין, על פסק דין של ר יקותיאל ור רפאל בירדוגו."},{"i":1998,"n":"אוחנא, רפאל ממרוקו וטבריה","f":"חיים","k":"בעל פרשת ראה","bt":"תרי","bp":"מכנאס","dt":"תרסב - כז אב","dp":"צפת","b":"לאחר שנתייתם גדל אצל זקנו ר יהודה אוחנא, עלה לארץ-תרכה או תרטו עם זקנו והתישבו בטבריה. חתן ר דוד נתנאל רופא, ובזיוו\"ש חתן ר מרדכי אוחנא. בשנת תרם בשליחות בבוכרה, היה חותנו של ר משה מאיר חי אליקים. בדרכו עבר בבגדד ונשא ונתן עם ר יוסף חיים, בשנת תרנד בשליחות בהודו ובורמה, בשליחות טבריה-תרם בערב, פרס ובוכרה - בבוכרה כינוהו היהודים \"המלאך רפאל\" וקראו לילדים על שמו. בשליחות-תרנד בהודו ובורמה, ובשליחות במרוקו-תרנז. חיבר גם \"יסוד מערבי\", \"מראה הילדים\", ועוד."},{"i":1999,"n":"אוחנא, שלמה אברהם מצפת","bp":"צפת","b":"מחכמי צפת. בשליחות ישיבת רשב\"י בהודו-תרפה, אלגיר-תרפז, הודו-תרפח וגייס לעזרתו את הגביר אברהם חי יחיא מנשה מהודו, מרוקו-תרצב בשליחות ירושלים."},{"i":2000,"n":"אוחנה רפאל בן חיים","bt":"1850","dt":"ה'תרסב 1902","bk":[["טובת מראה",""],["יסוד מערבי",""],["מראה הילדים",""],["פרשת ראה (רא\"ה)",""],["ראה מעשה",""]]},{"i":2001,"n":"אוחנונה, דוד מאלגיר","bt":"תרי - בערך","dt":"תרץ - בערך","b":"רב בגרדאייא-אלגיר-תרן. נזכר ברשימת התורמים להדפסת \"ארץ חיים\"-ירושלים תרסח."},{"i":2002,"n":"אוטולינגי, אליעזר מאיטליה","f":"יהושע ישראל","k":"בעל סדר עבודה","bt":"תקף","bp":"אקווי-איטליה","dt":"תרן","dp":"רומא","b":"רב באקווי-איטליה. חיבר סדר עבודה לחנוכת ביה\"כ באקווי - טורינו תרכב."},{"i":2003,"n":"אוטולינגי, דאריו משלוניקי","b":"רופא בשלוניקי-תרס - בבית החולים האיטלקי (שהיה בו מחלקה כשרה)."},{"i":2004,"n":"אוטולינגי, יוסף מקרימונה","k":"בעל לוח מכל הדינים","dt":"של","b":"ראש ישיבה ומדפיס בקרימונה. חיבר \"לוח מכל הדינים בר\"ן\", ועוד."},{"i":2005,"n":"אוטולינגי, משה יעקב מאיטליה","dt":"תרסא","dp":"שלוניקי","b":"מנהל הת\"ת בליוורנו, נקרא לשלוניקי-תרם לנהל את בית הספר ת\"ת ברוח המשכילים החרדים באיטליה."},{"i":2006,"n":"אוטולינגי, נתן מקוניאן","b":"רב בקוניאן - איטליה. תשובה ממנו ב\"מקוה ישראל\" בענין המקווה ברוויגו, ותשובה ממנו ב\"פלגי מים\"-שסא."},{"i":2007,"n":"אוטולינגי, שמואל דוד מפדובה","f":"יחיאל","k":"בעל מעיל שמואל","bp":"קזאלה מונפירטו","dt":"תעח - כה אב","dp":"ונציה","b":"תלמיד הרמ\"ז ומהרב\"ך-ר בנימין הכהן. רב ומקובל, ומדקדק, מחכמי רג'יו-איטליה. רב במקסאלי, בפדובה-תסו, ונציה. חיבר שירים וקינות בכת\"י. תשובה ממנו ב\"פחד יצחק\", ועוד. חיבר תקון מנחת שובבים, וכן תיקן חברת מלביש ערומים וחברת שובבים. חיבר גם \"קריה נאמנה\". הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":2008,"n":"אוטיאן, יוסף יהושע מטארגין","f":"בר","dt":"תרלד","b":"רב בטרגין-ליטא.א"},{"i":2009,"n":"אוטיץ, נתן","b":"רב בבמברג-תצ\"ד"},{"i":2010,"n":"אויב, נפתלי הירש ממינכן","b":"רב במינכן-תרז, חתנו - אברהם בן יצחק הלוי וולפסהיימר."},{"i":2011,"n":"אויג, מנחם מנדל מדלטין","f":"אורי ישראל","k":"בעל לקוטי רמ\"א","bt":"תרלב","dt":"תרץ - בערך","b":"מצאצאי ר אלעזר הרוקח ור השל. תלמיד ר שלמה הלברשטם מבובוב. רבה של דלטין-תרסד. חיבר \"ליקוטי רמ\"א\" בכתב יד. נסמך מאת: ר פיבל מברודשין, ר ליב הורביץ מסטניסלב, ר אברהם שטינברג מברודי."},{"i":2012,"n":"אויגאדור, שאלאמיאש משלוניקי","dt":"שצה - כז תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":2013,"n":"אויווארי, פטר מפרשבורג","b":"עורך העתון היהודי בהונגרית \"יודעא\" - פרשבורג תרפה."},{"i":2014,"n":"אויזרמן, יהודה אשר מקרילוב","f":"אליהו","k":"בעל בית יהודה","bt":"תקצב או תרה","b":"תלמיד ר מרדכי מלצר. רב בפושאלט, קרולוב(=קרילוב, קרילאוו)-פלך חרסון-תרל, נובוגיאורגיאבסק-פלך חרסון. חיבר גם \"בית לחם יהודה\", \"מטה יהודה\"."},{"i":2015,"n":"אויסטרליץ, צבי הרש מוינה","f":"קופל","b":"תלמיד הכת\"ס. מחכמי וינה-תרלב. העתיק הרבה מתורת רבו."},{"i":2016,"n":"אויסלנדר, יעקב שמואל","k":"בעל בכורי ראשית","dt":"תש..","b":"תלמיד ר שלמה זלמן ארנרייך משאמלוי. חתן ר נתן יחזקאל וייסבלום מלודמיר, ועבר לשם. עבר לשאמלוי, ר\"מ בישיבה בגרוסורדין. נספה בשואה."},{"i":2017,"n":"אויסשפיץ, אברהם יצחק מדעש","f":"אשר אנשיל מדעש","k":"בעל אשל אברהם","dt":"תרצב - טו אב","b":"תלמיד ר מנחם מנדל פאנט מדעש. פרנס ובעל בנק בדעש (שכל עובדיו חסידים)."},{"i":2018,"n":"אוירבך אשכנזי, שמ' זנ'","b":"דיין בלבוב-ת\"ח"},{"i":2019,"n":"אוירבך מנחם נתן בן שלמה","bt":"1858","dt":"ה'תרצ 1930","bk":[["אורח נאמן",""],["זכות אבות וענף אבות",""]]},{"i":2020,"n":"אוירבך שלמה זלמן בן חיים יהודה ליב","bt":"1910","dt":"ה'תשנה 1995","bk":[["מאורי אש",""],["מנחת שלמה",""],["מנחת שלמה קמא",""],["מנחת שלמה תנינא",""],["מעדני ארץ",""]]},{"i":2021,"n":"אוירבך, אביעזרי זליגמן","f":"צבי הירש מורמייזא","bt":"תפד-ו","dt":"תקכז-ח","b":"תלמיד ר יונתן איבשיץ. רב בבוכסוילר. בנו - ר אברהם מבון."},{"i":2022,"n":"אוירבך, אביעזרי זליגמן מהלברשט","f":"צבי בנימין-נחל אשכול","dt":"תרם","b":"רב בהלברשטט תרכז על מקום אביו."},{"i":2023,"n":"אוירבך, אברהם בנימין ביניש מיר","b":"מחכמי ירושלים. נכד בעל \"אמרי בינה\" מקאליש. חתן ר אברהם יוסף יוסקא גוסטמן האדמור מיאס-בוקרשט."},{"i":2024,"n":"אוירבך, אברהם בנימין מארה\"ב","b":"נכד ר מנחם נתן נטע מירושלים בעל \"אורח נאמן\"."},{"i":2025,"n":"אוירבך, אברהם דב בר מחמלניק","dt":"תקעז - ב אייר","b":"חתן ר צבי מברודי בן ר חיים צאנזר חתנו של ר יעקב יוסף בעל \"תולדות יעקב יוסף\". תלמיד הבעשט, ואחריו של חותנו זקנו ר יעקב יוסף מפולנאה. רב בחמלניק, פולנאה-תקנד. בניו ר משה זאב, ר יעקב פנחס ממזבוז, ר יוסף יוסקא, ר דוד."},{"i":2026,"n":"אוירבך, אברהם דב מאבריטש","f":"דוד","k":"בעל בת עין","bt":"תקכה","bp":"חמעלניק","dt":"תרא - יב כסלו","dp":"צפת","b":"חתן ר נתן נטע מאווריטש-תלמיד הבעש\"ט. תלמיד ר מנחם נחום (מרדכי) מטשרנוביל ור יהודה ליב הכהן מאניפולי. רב בחמלניק-תקמה, אב\"ד אבריטש על מקום חותנו, זיטומיר-תקפו, אברוטיש, עלה לצפת-תקץ, וברעש-תקצז ניצל וכן ניצל כל מי שהיה לצדו בביהכ\"נ. בספר \"יהודית\" של מונטיפיורי מתואר כרב ק\"ק פולין בצפת. נפטר ללא ילדים. אחיו ר יוסף צבי מגיד מישרים בחמלניק, ר ישראל ליב מוארחיבקא.","bk":[["בת עין","חסידות"],["בת עין – עה\"ת",""]]},{"i":2027,"n":"אוירבך, אברהם דב מירושלים טשרנ","f":"יהודה דוד מצפת","k":"אדמור מירושלים בטשרנ","b":"מצאצאי ר יעקב יוסף בעל \"תולדות יעקב יוסף\". אדמור מירושלים בטשרנוביץ."},{"i":2028,"n":"אוירבך, אברהם דוב מחמלניק","b":"רב בחמלניק"},{"i":2029,"n":"אוירבך, אברהם דוב מטשרנוביץ","dt":"תרפב","b":"רב ואדמו\"ר בטשרנוביץ,עלה לירושלים"},{"i":2030,"n":"אוירבך, אברהם ליב","f":"צבי הירש מורמיזא","b":"אביו היה רבה של וורמייזא עד תקלח."},{"i":2031,"n":"אוירבך, אברהם מבונא","f":"אביעזרי מבוכסוילר","bt":"תקכג","dt":"תרו - ג חשון","dp":"בונא","b":"גדל אצל זקנו ר צבי הירש מוורמייזא. תלמיד ר נתן אדלר מפפד\"מ. חתן דודו ר יוסף דוד זינצהיים בעל \"יד יוסף\". רב בפורבך, קובלנץ, קולוניה, נויביד, בונא(=בון) - בזמן שלטון נפוליאון. בנו - ר צבי הירש בנימין מהלברשטט בעל \"נחל אשכול\"."},{"i":2032,"n":"אוירבך, אברהם מלונטשיץ","f":"יצחק","bt":"תקסב","b":"לאחר שנתייתם גדל אצל זקנו ר זאב וולף אוירבך מלונטשיץ, ואחר אצל קרובו ר חיים אוירבך - שנתמנה לרבה של לונטשיץ אחר ר זאב וולף. תלמיד ישיבת פרשבורג."},{"i":2033,"n":"אוירבך, אברהם מלמברג","b":"מחכמי לבוב. תלמיד רד\"ב ויידנפד, בשנת תשא השיב לו רבו ללבוב ב\"דובב מישרים\"."},{"i":2034,"n":"אוירבך, אהרן מבון","f":"אברהם אוירבך","b":"אחיו של ר צבי בנימין בעל \"נחל אשכול\". תלמיד אביו ר אברהם וחברו של אביו ר יהודה ליב קרלבורג-אב\"ד קרעפערד (שניהם מתלמידי ר נתן אדלר). רב בנויביד-תקצז,בונא-תרה."},{"i":2035,"n":"אוירבך, אהרן מלובלין וירושלים","b":"מגדולי חכמי לובלין-ת\"ז,עלה לירושלים"},{"i":2036,"n":"אוירבך, אליעזר מטולטשין ודובנא","f":"ניסן","k":"בעל טורי אבן","dt":"תקפו-ט","dp":"דובנא","b":"אב\"ד קולטשין(=טולטשין), ראב\"ד בדובנא בזמן כהונת ר חיים יעקב אשכנזי. מתלמידיו בעל \"לבושי שרד\". אחיינו - ר יוסף ליב אוירבך-פעסיס, מצאצאיו ר אלתר ור יאקיל צוקרמן."},{"i":2037,"n":"אוירבך, אליעזר מלונטשיץ","f":"שלמה","bt":"תרכו","dt":"תשג","b":"נכד ר מאיר אוירבך מקאליש בעל \"אמרי בינה\". רב בלונטשיץ-פלך קאליש-תרסח."},{"i":2038,"n":"אוירבך, אליעזר מקאליש","f":"חיים מלונטשיץ","k":"בעל מגדנות אליעזר","bt":"תקפד","dt":"תרטז - ד תשרי","b":"חתן נכדת זקנו ר שמואל לסקר מלוסק. רב בקאליש. חיבר גם \"חדושי מהר\"א\"."},{"i":2039,"n":"אוירבך, אליקים געץ מאוסטרהא","f":"יחיאל מיכל","dt":"תפח - ה אדר","dp":"אוסטרהא","b":"ראש ומנהיג ופרנס באוסטרהא, היה מלוה מכספו להח\"ק, ונזכר רבות בפנקס הקהלה. בניו: ר אביגדור - נפטר צעיר בחיי אביו, ר יחיאל מיכל מאוסטרהא."},{"i":2040,"n":"אוירבך, אפרים ממזריטש והארחוב","f":"יצחק יהודה מראזישט","k":"בעל שו\"ת - בכת\"י","bt":"תריז","b":"רב במזריטש-פלך ראוונא-ווהלין-תרלח, חרחוב(=הארחוב)-ווהלין-תרנא. מתורתו בשו\"ת מהרש\"ם מברעזן, וב\"דברי מלכיאל\" לר מלכיאל טננבוים מלומזה. חיבר שו\"ת - בכת\"י. נסמך מאת: ר ליביש מזסלב בעל \"שם אריה\", ור שמואל מראוונא."},{"i":2041,"n":"אוירבך, אריה ליב מסטניסלב","f":"מרדכי מרדוש","k":"בעל נחלת אריה","dt":"תקי","b":"אחיינו של בעל הט\"ז. מגדולי חכמי דורו, רב בסטניסלב-תק. אבי משפחת אוירבך ואביו של ר דוד צבי משאריגראד וקרמניץ. חיבר \"נחלת אריה\". חתנו ר משלם זלמן מפואמרין, ובזיוו\"ש (לאחר שנפטר ר משלם זלמן) - חתנו - אחיינו ר מאיר מרגליות בעל \"מאיר נתיבים\"."},{"i":2042,"n":"אוירבך, בנימין זאב מאוזיראן","f":"יצחק צבי מנחם מלשנוב","k":"אדמור מאוזיראן","bt":"תקפה","dt":"תרנט - טז תשרי","b":"נינו של המגיד מזלוטשוב. ומצאצאיר משולם פייביש מזבאריז. חתן ר נחמן מסקאליט. סירב לקבל פדיונות והתפרנס כסופר סת\"ם. חסיד האדמור דוד משה מצורטקוב, אף שהיו לו חסידים משלו."},{"i":2043,"n":"אוירבך, ברוך מאיווניצא","f":"ישראל ממזיבוז","b":"רב באיווניצא-תרך על מקום אביו, ובנו ר מרדכי על מקומו אחריו."},{"i":2044,"n":"אוירבך, ברוך מברלין","bt":"תקנג","bp":"אינוורצלב","dt":"תרכד","b":"מנהל הת\"ת בברלין, ובית היתומים."},{"i":2045,"n":"אוירבך, ברוך מנחם מקליש","bt":"תר - בערך","b":"התייתם בילדותו וגדל אצל הנגיד משה וסרצוג בפולוצק. חתן ר אליהו כהן שפירא. רב בוארנקא-ליד פוזנא, גולאנץ. הו\"ל עם חותנו חדושי הריטב\"א לפסחים וארשא תרכו. חתנו - ר אליקים בן יהודה למשפחת אריה הו\"ל מעזבונו את יומן זכרונות משה וסרצוג."},{"i":2046,"n":"אוירבך, ברטהולד (משה ברוך)","k":"בעל דאס יודענטהום או","bt":"1812","bp":"גרדשטטין-גליל וירטמברג","dt":"1882","b":"תלמיד ישיבות העכניגען וקרלסרוהא, למד פילוסופיה. סופר. חיבר ספרים בגרמנית."},{"i":2047,"n":"אוירבך, דוד","b":"רב-שנת-ת\"צ"},{"i":2048,"n":"אוירבך, דוד מארץ ישראל","f":"אברהם דב בער מחמלניק","dt":"תקץ - כח כסלו","dp":"ארץ ישראל","b":"נינו כל ר חיים צאנזר, ור יעקב יוסף בעל \"תולדות יעקב יוסף\". עלה לארץ-תקלז בערך."},{"i":2049,"n":"אוירבך, דוד משפס","dt":"ל ניסן","b":"רב בשפס"},{"i":2050,"n":"אוירבך, דוד צבי מדובנא","k":"בעל מלבושי טהרה","b":"חתן ר חיים יעקב אשכנזי מדובנא, רב בדובנא-תרי על מקום חותנו (אולי היה ביניהם ר חיים מרדכי מרגליות). בניו - ר מנחם מנדל מדובנא, ר זאב וולף מדובנא."},{"i":2051,"n":"אוירבך, דוד צבי מדינוביץ","f":"נחמן זאב אורבך","b":"רב בדינאוויץ"},{"i":2052,"n":"אוירבך, דוד צבי ממנוסטרישץ","f":"אריה ליב","bt":"תקג","bp":"סטניסלב","dt":"תקסה - יט אייר","b":"סנדקו בברית היה הבעש\"ט והוא שנתן לו את שמו. חתן ר אהרן כץ נכד ה\"סמיכת חכמים\". תלמיד המגיד מזלוטשוב. בזיווג שני חתן ר ליבוש אוירבך מוישניוביץ. רב בפומורן, מנוסטרישץ-תקנא, קמניץ, קמרניץ(=קרמניץ)-תקסב, סורוקה ועוד. חיבר חבורים שלא נדפסו, מדברי תורתו בספרי נכדו ר ישראל מתתיהו. בניו: ר מנחם מנדלי מקרמניץ, ר נחמן זאב על מקומו במנוסטרישץ, ור ליבוש, חתניו ר אריה ליבוש מיזלש מפרמישלא, ר נתן שטרנהרץ מברסלב, ר אהרן שמעון מימפולי, ר חיים צבי מקרמניץ. נכדו ר אברהם אלעזר חיים מצפת חיבר \"גדולת דוד\" - מגלת היחוסין של המשפחה - קשאנוב תרסה."},{"i":2053,"n":"אוירבך, דוד צבי מסוקולוב","f":"ישראל מתתיהו-אלפי יש","k":"בעל לקוטי מהרצ\"א","bt":"תרל","bp":"צשינוב","dt":"תרצח - ג טבת","dp":"סוקולוב?","b":"חסיד האדמור ר דוד משה מצ'ורטקוב. חתן ר מרדכי גרוס מאברטין. רב באברטין-תרנה, סוקולוב-תרסו. חיבר \"לקוטי מהרצ\"א\" נדפס בספרי אביו \"נזר ישראל ומקרא קדש\". הספיד את רבו והדפיסו בשם \"אבל משה\" - קאלאמע תרסד. נסמך מאת: ר יצחק שמלקס, מהרש\"ם מברעזן, ר בנימין וייס מטשרנוביץ, קרובו- ר משה מייזלס מפרמישלא. בנו ר נחמן זאב עבר לברלין והיה רב בצלב האדום הגרמני - עלה לארץ-תרצג."},{"i":2054,"n":"אוירבך, הלל מחומסק","b":"מצאצאי ר הלל בעל \"בית הלל\". רב בחומסק. בנו - ר יוסף מברעזי."},{"i":2055,"n":"אוירבך, זאב וולף מדובנא","f":"דוד צבי אורבך","b":"מו\"צ בדובנא-תר\"ס"},{"i":2056,"n":"אוירבך, זאב וולף מלונטשיץ","f":"מנחם מנדל אורבך","b":"רב בלונטשיץ-ת\"ק"},{"i":2057,"n":"אוירבך, חיים זאב מיגולניצה","b":"רב ביגולניצה, זבלטוב."},{"i":2058,"n":"אוירבך, חיים זאב מסיגט","b":"רב בסיגט, נזכר ב\"מאמר מרדכי\"."},{"i":2059,"n":"אוירבך, חיים יהודה ליב מירושל'","f":"אברהם דב מירושלים","k":"בעל חכם לב","r":"ראב\"ד סערעד","bt":"תרמו-ז","bp":"יפו","dt":"תשיד - כח אלול","dp":"ירושלים","b":"מצאצאי ר יעקב יוסף בעל \"תולדות יעקב יוסף\". מיסד וראש ישיבת המקובלים \"שער השמים\". חתן ר שלמה זלמן פרוש גלקימן, תלמיד ר שמעון צבי הורביץ מלידא. סגן קונסול פרס ובמלחמת העולם ה-I הציל יהודים רבים, לאחר הלשנה נאלץ להסתתר, וחיבר במסתור \"חכם לב\".יסד ת\"ת \"שער השמים\" לילדי עדות המזרח. בשליחות באמריקה-תרצא למשך שנתיים, ושוב ב-תשיב. פרסם מאמרים ב\"סיני\" - ירושלים תרצז.","bk":[["חכם לב - קידושין",""]]},{"i":2060,"n":"אוירבך, חיים מלונטשיץ","f":"יצחק איצק אורבך","k":"בעל דברי משפט","r":"רב בלונטשיץ","bt":"בשנת תקל כבר היה דיין ראשון בליסא","bp":"ליסא","dt":"תקצט - יב אלול","b":"בזיוו\"ש חתן ר יהודה ליב ליפשיץ-חתנו של ר שמואל לסקר מלוסק. רב בלונטשיץ. בנו - ר מנחם מאוסטרווא הו\"ל את ספרו \"דברי משפט\" עם הוספות ממנו - קרוטושין תקצה. בניו גם - ר אליעזר בעל \"מגדנות אליעזר\", ר יצחק. חתנו - המלבי\"ם.","bk":[["דברי משפט - חושן משפט",""]]},{"i":2061,"n":"אוירבך, חיים מקראקא","f":"משלם זלמן פישהוף","b":"מגדולי חכמי קרקא-ת\"ל"},{"i":2062,"n":"אוירבך, יהודה דוד מצפת","f":"יואל פייבל שטיין","b":"נכד ר אברהם דב מחמלניק. מצאצאי ר יעקב יוסף בעל \"תולדות יעקב יוסף\". עבר מצפת לירושלים. בנו ר אברהם דב ונכדו ר חיים ליב-ראש ישיבת \"שער השמים\"."},{"i":2063,"n":"אוירבך, יהודה ליב מפראשקה","f":"מרדכי אוירבך","bt":"תקפה","dt":"תריח - כה כסלו","b":"רב בפראשקה,קוואל,רב בקוטנא"},{"i":2064,"n":"אוירבך, יהודה ליב מקוסוב","f":"ישראל מקוסוב","k":"בעל מחוקק יהודה","bt":"תקי","dt":"תקע","b":"רב בהורודנקא-תקל, קוסוב וטורטשין-תקסא ווישניוביץ-תקסז, חתן ר שאול מהורודנקה, ואחר כך חתן ר שמואל שינדלינגר. חיבר \"מחוקק יהודה\" למברג תקנב, ועוד."},{"i":2065,"n":"אוירבך, יהושע מרדכי מטבריה","f":"יואל פייבל שטיין","b":"מצאצאי ר יעקב יוסף בעל \"תולדות יעקב יוסף\". ממונה על כולל קוסוב בטבריה ומראשי חסידי קרלין בטבריה. בנו ר אליעזר שלמה."},{"i":2066,"n":"אוירבך, יהושע פאלק מבריסק","f":"צבי הירש אוירבך","b":"רב בבריסק,פלאצק-תר\"נ,עבר לברלין"},{"i":2067,"n":"אוירבך, יהושע פאלק מקלטשוב","f":"יצחק איצק-דברי חיים","dt":"תרלח","b":"רב בקלעטשוב(=קלעטשאווי)-תרכ. אחיו - ר מאיר מקאליש בעל \"אמרי בינה\"."},{"i":2068,"n":"אוירבך, יואל זאב מגאלוב","f":"צבי הירש אוירבך","b":"רב בגאלוב-תר\"נ"},{"i":2069,"n":"אוירבך, יוסף יוסקא","f":"אברהם דב בער מחמלניק","b":"נינו של ר חיים צאנזר, ור יעקב יוסף בעל \"תולדות יעקב יוסף\". חתן ר נ חמן מברסלב."},{"i":2070,"n":"אוירבך, יוסף ליב מדובנא","b":"דומ\"צ בדובנה-תק\"פ"},{"i":2071,"n":"אוירבך, יוסף מברעזי","f":"הלל מחומסק בן נחמיה","b":"רב בברעזי."},{"i":2072,"n":"אוירבך, יוסף מטרניגרד","f":"אביגדור אוירבך-מרגלי","k":"בעל אות יוסף","b":"רב באסטרווצי,טרניגרד-ת\"ק"},{"i":2073,"n":"אוירבך, יוסף מפרוזין","b":"עסקן מחכמי פרוזין-תרם בזמן הגדול ממינסק."},{"i":2074,"n":"אוירבך, יחיאל מיכל מדוניביץ","f":"צבי מנדל","k":"אדמור מדוניביץ","b":"גורש לסיביר לאחר שנחשב במעורבות בהריגת \"מוסר\", ובדרך שוחרר ע\"י חסידיו. הוברח לבובוב ואחר לקורימא. (ראה עוד אצל ר אליהו רובין \"ממונקטש עד אושוויץ)."},{"i":2075,"n":"אוירבך, יעקב יוקב מיארטשין","f":"מנחם אורבך","b":"רב ביאראטשין-פרייסן-תר\"כ"},{"i":2076,"n":"אוירבך, יעקב יצחק מליסקא","b":"רב בליסקא-תק\"נ"},{"i":2077,"n":"אוירבך, יעקב מלמברג","b":"מומעד לרב בלמברג-תקעד לבקשת נכבדי הקהלה מה\"ישועות יעקב\"."},{"i":2078,"n":"אוירבך, יעקב פנחס ממזבוז","f":"אברהם דב בער מחמלניק","b":"נינו של ר חיים צאנזר, ור יעקב יוסף בעל \"תולדות יעקב יוסף\". חתן ר ברוך ממזבוז. רב בדלעטיטשוב."},{"i":2079,"n":"אוירבך, יצחק איזיק","f":"ראה רייס אורבך, איזק"},{"i":2080,"n":"אוירבך, יצחק איצק מלונטשיץ","f":"חיים מלונטשיץ","k":"בעל דברי חיים","r":"אב\"ד פלאצק דאברי ולונטשיץ","bt":"בנו בעל האמרי בינה תקעה","dt":"תרו - ו אדר","b":"חתן ר יצחק אילנברג מטרעקי ולודז. רב בדוברי, פלצק, לינטשיץ על מקום אביו. בנו - ר מאיר בעל \"אמרי בינה\", ר אברהם משה.","bk":[["דברי חיים – שו\"ע",""]]},{"i":2081,"n":"אוירבך, יצחק איצק מליסא","f":"מנחם אורבך","b":"רב בליסא-תק\"מ"},{"i":2082,"n":"אוירבך, יצחק איצק מפפד\"א וברלי","f":"צבי הירש אורבך","b":"ר\"מ בפפד\"מ,ברלין"},{"i":2083,"n":"אוירבך, יצחק אליעזר מאוסטרובצא","b":"אין פרטים (חתם על ספר)"},{"i":2084,"n":"אוירבך, יצחק יהודה מראזישט","b":"מצאצאי ר השל, והב\"ח, ובעל \"מגלה עמוקות\". נכד ר יהודה ליבוש אוירבך מוישנוביץ. רב בראזישט-ווהלין-תרל."},{"i":2085,"n":"אוירבך, יצחק מבריסק","b":"שמש קהלת בריסק, חתם-שצט על תקנות הקהלה."},{"i":2086,"n":"אוירבך, יצחק מהלברשטט","f":"אביעזרי זליגמן","bt":"תרכח","dt":"תרצב","b":"נכד ר בנימין צבי בעל \"נחל אשכול\". אב\"ד ראגאזען, לייפציג, הלברשטם-תרסד כ-30 שנה., נשיא הקהילות החרדיות בגרמניה, וחבר באגו\"י."},{"i":2087,"n":"אוירבך, יצחק מטלוסט","b":"רב בטלוסט-תר\"ז"},{"i":2088,"n":"אוירבך, יצחק מירושלים","f":"מנחם נתן אורבך","bt":"תרלח","dt":"תשיג","b":"מו\"צ ברוחמה-ירושלים. פרסם מאמרים ב\"ועד חכמים\" - ירושלים תרפג, \"המגיד\" - סטמר תרפח-תרצט."},{"i":2089,"n":"אוירבך, ירוחם פישל מאומן","f":"יהודה ליב מקריוואזר","bt":"תקנט","dt":"תרכז - כז שבט","b":"חתן הגביר ר בנימין מאומאן. תלמיד ר לוי יצחק מברדיטשוב, ור משה צבי מסאווראן. עלה לצפת-תקצג - בהוראת האדמור מסאווראן, והיה ליד ימינו של ר אברהם דב בער מאווריטש. בנו ר בנימין יהודה ליב ברנשטין."},{"i":2090,"n":"אוירבך, ישראל ממזיבוז","f":"יעקב פנחס מדלטיטשוב","dt":"תרך - בערך","b":"נכד-אבי אמו ר ברוך ממזיבוז-נכד הבעש\"ט. רב באיווניצא, ובנו ר ברוך אוורבוך על מקומו אחריו-תרך."},{"i":2091,"n":"אוירבך, ישראל מתתיהו מאוסציא","f":"נחמן זאב","k":"בעל אלפי ישראל","bt":"תקצט","bp":"מנוסטרישץ","dt":"תרסא - טו תשרי","dp":"גוואזדיץ","b":"חתן ר משה צבי הירש הורביץ מציעשינוב. רב באוסציא, בציעשינוב, בוסק וגוואזדיץ. חסיד האדמור דוד צבי משה מצורטקוב. חיבר \"אלפי ישראל\" למברג תרל, ועוד."},{"i":2092,"n":"אוירבך, מאיר חיים ממנוסטרישץ","f":"נחמן זאב אורבך","dt":"תרסב - ט כסלו","b":"רב במאניסטריץ"},{"i":2093,"n":"אוירבך, מאיר יהודה","b":"תשובה אליו רח\"כ-תקך."},{"i":2094,"n":"אוירבך, מאיר מקליש וירושלים","f":"יצחק איצק-דברי חיים","k":"בעל אמרי בינה","r":"רב דברעסלוי","bt":"תקעה","bp":"דוברה-ליד קאליש","dt":"תרלח - ה אייר","dp":"ירושלים","b":"היה רב בקאליש, קוילי ועוד, עלה לירושלים בשנת תריט, והתמנה לעמוד בראש הישוב יחד עם ר שמואל סלנט. חיבר \"אמרי בינה\" ירושלים תרכט. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"כבוד הלבנון\" - ירושלים תרכג, \"תבונה\" - ממל-קניגסברג תרכא.","bk":[["אמרי בינה -",""]]},{"i":2095,"n":"אוירבך, מנחם מאוסטרובצא","f":"חיים אורבך","b":"רב באסוטרווצע(=אוסטראווא)-תר. מתלמידיו - ר אברהם מפיסקרעטשאס בעל \"מקורי הדינים\"."},{"i":2096,"n":"אוירבך, מנחם מדובנא","f":"דוד צבי אורבך","b":"רב בדובנא-תר\"נ"},{"i":2097,"n":"אוירבך, מנחם מנדל מוינה","f":"משלם זלמן פישהוף","k":"בעל עטרת זקנים","r":"ראש ישיבה בקראקא ובווינה, ואח\"כ רב בקראטשין, תלמיד הב\"ח","bt":"שפ","dt":"תמט - כ תמוז","b":"נכד(-אבי אמו) ר יהודה ליב רופא מוינה. למד עם שני חבריו - ר גרשון בעל \"עבודת הגרשוני\", ר צבי הירש קלויזנר מלובלין - בישיבת הב\"ח בקראקא, אצל ר יהושע בעל ה\"מגיני שלמה\", ואצל ר מנחם מנדל קרוכמל בעל \"צמח צדק\" (והזכירם בספרו) - והתישבו בקראקא. מקובל, פוסק, עשיר, מרביץ תורה בוינה, דיין בקראקא, רב ברויזניץ-תכה, קורוטשין-תלא.","bk":[["עטרת זקנים","מפרשי שו\"ע"],["עטרת זקנים - אורח חיים (שאר החלקים נשאר בכת\"י)",""],["עקרת הבית - ש\"ס ופוסקים (כת\"י)",""]]},{"i":2098,"n":"אוירבך, מנחם מנדל מקרוטושין","f":"משה מטרניגרד","k":"בעל עטרת זקנים","dt":"תפט - יד אד\"א","b":"רב בקורוטשין. בנו - ר אביגדור אוירבך-מרגליות מחנטשין."},{"i":2099,"n":"אוירבך, מנחם מנדל מקרמניץ","f":"דוד צבי אורבך","b":"רב בקרמניץ-תקס\"ח"},{"i":2100,"n":"אוירבך, מנחם מפוזנא","f":"שלמה זלמן אורבך","b":"ר\"מ בפוזנא-תק\"י"},{"i":2101,"n":"אוירבך, מנחם מקרוטושין","f":"צבי אורבך","b":"רב בקארטשין,ראוויטש-תר\"נ"},{"i":2102,"n":"אוירבך, מנחם מרוזניץ","b":"רב ברויזניץ-ת\"מ"},{"i":2103,"n":"אוירבך, מנחם נתן מירושלים","f":"שלמה","k":"בעל זכות אבות","bt":"תרא - תריח","bp":"יאנווא או לונטשיץ","dt":"תרץ - ה אלול","dp":"ירושלים","b":"מחכמי פולין, עלה עם אביו בשנת תרלא לירושלים והתחנך בבית סבו ר מאיר אוירבוך. חיבר \"זכות אבות וענף אבות\" ירושלים תרנג, ועוד. פרסם מאמרים ב\"הדביר\" - ירושלים תרעט, \"שערי ציון\" - ירושלים תרפא, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":2104,"n":"אוירבך, מנשה מנדבורנה","b":"דיין בנדבורנה-תרנט, תשובה אליו ב\"אוריין תליתאי\"."},{"i":2105,"n":"אוירבך, מרדכי מדוברינין","f":"דוד אורבך","dt":"תרכט - ל ניסן","b":"רב בדוברינין,סימפולא"},{"i":2106,"n":"אוירבך, מרדכי מקאטלנא","f":"ברוך מאיווניצא","bt":"תריט","b":"נכד-אבי אמו ר משה טברסקי מקריסטשוב. רב באיווניצא-תרלט על מקום אביו, קאטעלנה-ווהלין-תרנה. נסמך מאת: ר יוסף יוזפא אפרתי מברדיטשוב."},{"i":2107,"n":"אוירבך, מרדכי מרדוש","f":"דוד אוירבך","b":"רב בלמברג והמדינה-ת\"ס"},{"i":2108,"n":"אוירבך, משה אברהם מויזשאלי","f":"אלימלך מאויהל","bt":"תקעב או תקפב","bp":"וויזשאלי","dt":"תרן - טו אלול","dp":"ויזשאלי","b":"מחכמי ויזשאלי."},{"i":2109,"n":"אוירבך, משה זאב מחמלניק וצפת","f":"אברהם דב מחמלניק","dt":"תקצז","dp":"צפת","b":"נינו כל ר חיים צאנזר. חתן ר צבי בן הבעשט. עלה לארץ בשיירת תקלז או סמוך לכך והתישב בצפת. נהרג ברעידת האדמה בצפת. חתנו ר דב בר בן ר ישראל חיים מלודמיר האדמור מריזין. בנו ר ישראל לאדזינר - נקרא ע\"ש זקנו הבעשט ובנו היה ר משה מחמלניק."},{"i":2110,"n":"אוירבך, משה מברנשיב","b":"רב בברנשיב - תשובה אליו בשו\"מ."},{"i":2111,"n":"אוירבך, משה מקרטשין","f":"מנחם מנדל מרגליות","b":"נכד ר מרדכי מרגליות מקראקא. חתן ר שאול בן ר השל מאמשטרדם. עשיר,נגיד,פרנס ועד דד\"א וראש בקרשטין-ת\"ס. בניו: ר מנחם מנדל מקורוטשין בעל \"עטרת זקנים\", ר יוסף מזולקווא ויזליוויץ. חתנו - ר יוסף בן משה אוירבך מקראקא."},{"i":2112,"n":"אוירבך, משלם זוסיא יצחק","f":"המגיד מזלוטשוב","bt":"תקעט","dt":"תרמב - ב סיון","b":"מצאצאי ר זושא מאניפולי. רבה של טלומטש (סטלומץ)-תרכב. חתן האדמור מטשרקס, (ואולי האדמור רד\"ב שניאורסון מלאדי), ואחר כך חתן ר חיים מקוסוב. אביו נאסר עם ר ישראל מרוז'ין וברח להונגריה וכיהן כרב בקורימא. בנו ר מרדכי דב טברסקי (כשם סבו האדמור) היה רב בהורנוסטייפול וחתנו של ר חיים מצאנז."},{"i":2113,"n":"אוירבך, נחמן זאב מגוואזדיץ","f":"ישראל מתתיהו","bt":"תרכה","bp":"צישינוב","dt":"תרצג","b":"רב בגוואזדיץ-תרסא על מקום אביו."},{"i":2114,"n":"אוירבך, נחמן זאב ממנוסטרישץ","f":"דוד צבי","bt":"תקן","dt":"תרטו - כח אדר","b":"מחכמי מנוסטרישץ, בנו ר מאיר חיים אדמור ממנונסטרישץ. שבעת בניו היה רבנים וביניהם ר שלמה אהרן בירנבוים מבויאן בעל \"תפארת שלמה\"."},{"i":2115,"n":"אוירבך, נפתלי הרץ מפרונקירכן","f":"מנחם אורבך","dt":"תצג - יז תמוז","b":"רב בפרונקירכן"},{"i":2116,"n":"אוירבך, נפתלי מנארול","f":"אהרן אורבך","dt":"תסג - ה תשרי","b":"רב בנארול"},{"i":2117,"n":"אוירבך, פיבל","b":"עלה לא\"י בעליית החסידים-תק\"נ"},{"i":2118,"n":"אוירבך, פנחס זליג מקראקא ווינה","f":"שמעון וולף","k":"בעל הלכה ברורה","b":"בקי,דיין בקרקא-תנ\"ו,ר\"מ בווינה"},{"i":2119,"n":"אוירבך, צבי בנימין מהלברשטט","f":"אברהם אורבך","k":"בעל נחל אשכול","bt":"תקסד","dt":"תרלב - טו תשרי","b":"בעל תואר ד\"ר. רב בדרמשטט-תקצה, עזב לפפד\"מ מפני הריפורמים, רב בהלברשטט-תרכג. חיבר גם \"ברית אברהם\". חיבר גם ספר בגרמנית."},{"i":2120,"n":"אוירבך, צבי הירש מוורמייזא","f":"זליג מברוד","k":"הירש מבראנדיש","bt":"תנה","dt":"תקלח - ו אייר","b":"רב בוורמייזא 45 שנה. הסכים על \"כרם שלמה\" לר שלמה גייגר, על \"עמודי בית יהודה\"-תקכה. בניו - ר אביעזרי, ר אברהם ליב."},{"i":2121,"n":"אוירבך, צבי הירש מליסא וקונין","f":"מנחם אוירבך","k":"בעל דברי תורה","dt":"תרמג","b":"דיין בליסא,רב בקאנין"},{"i":2122,"n":"אוירבך, ראובן מסטרליסק","b":"אב\"ד סטרליסק, דיין בלבוב-תקמח אצל רצ\"ה רוזניש, הסכים על קצות החושן-תקמח, נפש דוד-תקס, שפת אמת-תקמח, ועוד."},{"i":2123,"n":"אוירבך, שאול מלבוב","f":"יעקב","b":"דרשן ודיין בלבוב, נזכר בשו\"ת \"מאמר מרדכי החדש\"."},{"i":2124,"n":"אוירבך, שאול מלמברג","f":"ראובן","bt":"תקמו","bp":"סטרליסק","dt":"תרכו","b":"רב בלבוב על מקום אביו."},{"i":2125,"n":"אוירבך, שבתי שעפטל מפרג","f":"זלמן מוינה","b":"מלמד תורה בפרג. ממגורשי וינה."},{"i":2126,"n":"אוירבך, שלום מקישינוב","f":"נחמן זאב אורבך","dt":"תרעג - ב אלול","b":"רב בקישינוב"},{"i":2127,"n":"אוירבך, שלמה אברהם מקאזמין","f":"ישראל","bt":"תרל","b":"תלמיד ר משה מסילאפקביץ, ר שמחה מפרנפיל, ונסמך מאת: רבותיו, ר אלתר שמואל אברהם מקונסטנטין. רב בקאזמין-פודוליה-תרס על מקום זקנו-אבי אמו."},{"i":2128,"n":"אוירבך, שלמה אהרן מבאיאן","f":"נחמן אורבך","k":"בעל תפארת שלמה","bt":"תקפה","dt":"תרנג - יט תמוז","b":"מקובל בבאיאן"},{"i":2129,"n":"אוירבך, שלמה זלמן מירושלים","f":"חיים יהודה מירושלים","k":"בעל מאורי האש","dt":"תשנה - כא אדר","b":"מגדולי הפוסקים. ראש ישיבת \"קול תורה\" בירושלים. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"כרם ציון\" - ירושלים תרצה-תשיג, \"תורת ירושלים\"-\"תפארת ירושלים\" - ירושלים תרצו."},{"i":2130,"n":"אוירבך, שלמה זלמן מפוזנא","b":"מקובל,רב בפוזנא-ת\"פ"},{"i":2131,"n":"אוירבך, שלמה משלטיץ","f":"מאיר - אמרי בינה","k":"בעל דברי שלמה","bt":"תקצח","dt":"תרסה - ה שבט","b":"רב בשלאטיץ, אוניבה, לונטשיץ-תרלג, נתבקש לכהן כרב בירושלים-תרלח על מקום אביו.","bk":[["אמרי שלמה",""],["דברי שלמה",""],["דברי שלמה , אמרי שלמה",""]]},{"i":2132,"n":"אוירבך, שמואל זנויל מלבוב","f":"יהודה","dt":"שצא - ה אדר","dp":"לבוב","b":"מרביץ תורה, ר\"מ בלבוב. חתם-שסו עם ר משה כ\"ץ אשכנזי מלבוב. חתם-תי עם ר אהרן קלונימוס גראפין, ועוד. (בובר מציין כי תאריך פטירתו אולי שגוי כי נמצאה חתימתו גם אחרי כן)."},{"i":2133,"n":"אוירבך, שמואל ישכר בער","f":"מארים","bt":"תרנד","dt":"תרצה - כח כסלו","b":"רב במאריביינקה(=מאראוויאנקע)-פלך סובאלק-תרסג, עלה לארץ וכיהן כרב ברמת השרון."},{"i":2134,"n":"אוירבך, שמואל מלובלין","f":"דוד הקדוש","k":"בעל חסד שמואל","b":"מחכמי לובלין. ניצל בנס מהפרעות-תיז בעיר רייזין ליד ליסא (וחברו שהיה לצדו ר יחזקאל כץ מפינצק - נהרג). וחיבר ספר בלשון אשכנז בשם \"זכרונות הנפטרים\" ובו שמות הנהרגים בשנת תנא, ובהם: שלמה בן זינוויל מקרעשיוו, יהודה בן אהרן, אברהם בן יהודה מלובלין, וולף בן נפתלי, זליג בן יעקב, פנחס בן משה מטאמשאוו."},{"i":2135,"n":"אוירבך, שמואל צבי מסלובודקה","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":2136,"n":"אוירבך, שמחה בונם מטבעון","k":"בעל עמודי המחשבה","dt":"תשלא","b":"רב בשדה יעקב,טבעון"},{"i":2137,"n":"אוירבך, שמעון וולף מטורבין","f":"דוד טעביל","dt":"שצב - יז חשון","dp":"פרג","b":"חתן המהרש\"ל. מגדולי חכמי דורו, רב בטורבין, לובמלא, לובלין-שלט, פרמישלא-שנו, פוזנא-שפז, וינה, פרג. חתנו - ר אליעזר ליפמן הלפרין. היה במחלוקת בלובלין עם מהר\"ם מלובלין, ובפרג עם ר יו\"ט הלר בעל תוי\"ט - ונזכר אצל נכדו ר זאב וולף הלפרין מאליק. נזכר ב\"אור צדיקים\" לר מאיר פאפאס, ועוד. הסכים על \"שיח יצחק\" - שעז."},{"i":2138,"n":"אוירבך, שמעון יוסף","b":"נכד ר דוד צבי משא\"ג ומוהליב. רב-שנת תר\"ל. חתנו - ר אפרים סטניסלבסקי בעל \"סמא דחיי\"."},{"i":2139,"n":"אוירבך, שמעון מרודניק","f":"מנדל","bt":"תרסז","bp":"רודניק","dt":"תש..","b":"תלמיד ר מאיר ארק בטרנוב. חתן ר מוטל ניימן ר\"מ בבובוב, ועבר אל חותנו. נספה בשואה."},{"i":2140,"n":"אויש יפה, יצחק ממאקא ופאקש","f":"שלמה צבי יפה","k":"בעל שמועות דוד","dt":"תרנה - יג אב","dp":"קלויזנבורג","b":"תלמיד הכת\"ס. חתן ר יעקב הלמן מקלויזנבורג. צדיק מחכמי מאקא. חתנו ר יהודה בעל \"מניחות יהודה\". אחיו - ר יצחק מבאניהאד."},{"i":2141,"n":"אויש, אהרן מלופן-הונגריה","f":"דוד מפאקש או יחיאל מ","dt":"תשך - ג סיון","dp":"ירושלים","b":"תלמיד דודו בעל \"ערוגת הבשם\" בחוסט. חתן ר חיים פרידלנדר האדמור מליסקא. רב בלופן(=לופעני)-תרסז, ניצל מהשואה ואחריה רב בגרוסורדין. עלה לירושלים. מתורתו ב\"פרי אהרן\". תשובות אליו ב\"יד יצחק\", \"פרי השדה\"."},{"i":2142,"n":"אויש, יהודה מפרג","dt":"תקסו","b":"דיין אצל בעל \"נודע ביהודה\" בפרג."},{"i":2143,"n":"אויש, יחיאל מיכל מפאקש","f":"יצחק מיינק","dt":"תרסג - כו אלול","dp":"ירושלים","b":"תלמיד הכת\"ס. חתן ר יוסף אליהו פישל מפאקש. מחכמי יינק, פאקש, באניהאד(=בניהאד). עלה לירושלים-תרס."},{"i":2144,"n":"אויש, יצחק מבאניהאד","f":"יחיאל מיכל מפאקש","k":"בעל תורת יצחק","bt":"תרך","bp":"פאקש","dt":"תשד - יח תמוז","dp":"אושוויץ","b":"תלמיד השב\"ס, ור אליעזר זוסמן סופר מפאקש. בזיוו\"ש חתן ר יואל ובר מוואדקערט. מראשי הקהלה בבאניהאד. נספה בשואה. חיבר \"באר יצחק\", \"לבוש יצחק\"."},{"i":2145,"n":"אויש, יצחק מיינק","f":"שלמה צבי ממיהלפאלווא","bp":"יינק","b":"מצאצאי בעל ה\"לבוש\". תלמיד החת\"ס. רב ביינק. אחיו של ר משה אהרן."},{"i":2146,"n":"אויש, משה אהרן","f":"שלמה צבי ממיהלפאלווא","b":"תלמיד הכת\"ס, ור ישראל דוד יפה מרגליות שלזינגר מפעזינג, ור יואל אונגר מפאקש. אחיו של ר יצחק ממאקא."},{"i":2147,"n":"אויש, משה וולף מפרג","f":"יהודה פרג","b":"רב בפרג בזמן כהונת קרוב משפחתו ר שמואל לנדא בנו של ה\"נודע ביהודה\". מחותן עם בעל \"תשובה מאהבה\" - המזכירו בספרו. בנו ר שמעון מחכמי פרג."},{"i":2148,"n":"אויש, שמעון מפרג","f":"משה וולף מפרג","b":"מחכמי פרג בזמן כהונת קרוב משפחות ר שמואל לנדא בנו של \"הנודע ביהודה\". וניהל עמו קשרי שו\"ת."},{"i":2149,"n":"אוליבירו, דוד מקיוסטנדיל","b":"דיין בקיוסטנדיל-תקסז אצל ר יצחק שמואל חרבון, יחד עם ר יעקב בן יהודה אלעזר."},{"i":2150,"n":"אוליווירה, דוד ישראל מאמשטרדם","dt":"תיט - יג תשרי","b":"רב ומשורר באמשטרדם. חיבר שירים בלשונות שונות. בנו - ר שלמה מאמשטרדם."},{"i":2151,"n":"אוליווירה, דוד מצפת","k":"מסטרו פדרו","dp":"טבריה","b":"מאנוסי פורטוגל, רופא מחכמי צפת-שנות ה-ש', טבריה. אחיו - ר יוסף גדליה מצפת."},{"i":2152,"n":"אוליווירה, יוסף גדליה מצפת","k":"דון מנואל","b":"מאנוסי פורטוגל, חזר ליהדות והתישב בצפת-שנות ה-ש' עם אחיו - ר דוד."},{"i":2153,"n":"אוליווירה, שלמה מאמשטרדם","f":"דוד ישראל","k":"בעל אילת אהבים","bp":"ליסבון","dt":"תסח - ד סיון","b":"רב ראשי, מדקדק משורר ומתרגם באמשטדם-תנח. בן למשפחת אנוסים שחזר ליהדות ועבר לאמשטרדם. תלמיד ר מנשה בן ישראל, ור שאול מורטירה. רב עדת הספרדים באמשטרדם על מקום ר יעקב ששפורטש-תנח וראש ישיבת \"עץ חיים\". חיבר ספרים רבים בשפות שונות ובהם גם \"שרשות גבלות\", \"אילת אהבים\", \"דרכי נועם\" ועוד."},{"i":2154,"n":"אולימן אשכנזי, שלמה","dt":"תץ בערך","dp":"חברון","b":"מחכמי צפת, עבר לחברון. בשליחות באיטליה-תיא ונשבה במסינה, ר שמואל אבוהב טיפל בפדיונו, לאחר חרבן צפת עבר לירושלים, בשליחות קהילת ירושלים באיטליה עם ר נתן שפירא בשנת תכ. היה אחד מארבעת הרבנים שליחי רבני קושטא-שץ - לעמוד על טיבו של נתן העזתי בעזה, יחד עם ר אברהם אמיגו, ר גבריאל איפירנסה ור חיים אבולעפיה."},{"i":2155,"n":"אולמא, אליהו","f":"יהודה הלוי מהאנוי","b":"הגיה תנך עם פירושים - בזל שעט ושיר ממנו."},{"i":2156,"n":"אולמא, זליגמן","f":"משה שמעון","b":"הגיה \"שפע טל\", ונדפס עם שיר ממנו, וטורים בלי ב\"י-הנאו שע. ואולי הוא שספרו נמצא בסוף \"נשמת אדם\" לר אהרן שמואל - האנאו שעז."},{"i":2157,"n":"אולמא, חיים","f":"שמואל","bt":"שלג","b":"תלמיד המהר\"ל, יחד עם חברו ר שמואל בכרך מורמייזא. רב בפרג, ירוסלב.(וניצל שם מהשריפה-שפה) החזיק בספריה חשובה, ושו\"ת מהר\"ם מרוטנבורג שנדפס בפרג שסח היה על פי כתב יד שהיה ברשותו."},{"i":2158,"n":"אולמא, שלמה","b":"מצאצאיו ר אריה ליב גינצבורג-חותנו של ר חיים מוולוזין."},{"i":2159,"n":"אולמו, יעקב דניאל מאיטליה","f":"אברהם","k":"בעל עדן ערוך","bt":"תן","dt":"תקיז - ז סיון","b":"תלמיד ר יצחק למפרונטי. רב בפיררה, ותיקן שם תקנות. חיבר \"עדן ערוך\", פיוט \"מלכא רמא\" ועוד. מתורתו גם בספרי חכמי דורו. פרסם מאמר ב\"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":2160,"n":"אולמן, אברהם יצחק מגרוסורדין","f":"משה מגרוסורדין","dt":"תשד - ט סיון","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר גרשון הלוי ליטש רוזנבוים מטאליא. מזכיר הקהלה בגרוסורדין ונשיא חברת ש\"ס שם. נספה בשואה. מנכדיו - ר אברהם יצחק בן יעקב דב אולמן רב בעדה החרדית בירושלים, ור שלמה זלמן בן גרשון אולמן רב בבני ברק."},{"i":2161,"n":"אולמן, אברהם מאנטורפן","f":"אהרן זאב","bt":"תרמג","bp":"ריגליץ","dt":"תשכח","b":"למד בישיבת בובוב והיה מחסידי האדמור. רב באנטוורפן-תרע, דורטמונד-תרעח, ליברטי -ניו יורק - תרצג, פרסם מאמרים בכתבי עת תורניים, ובשות המאור."},{"i":2162,"n":"אולמן, אברהם מלקנבך וטופולצאן","f":"שלום חריף מלקנבך","k":"בעל בית אברהם","r":"אב\"ד בכמה קהילות קדושות ובסוף ימיו בלאקענבאך","bt":"תקנא","dt":"תרט - כד אב","dp":"לקנבך?","b":"ר\"מ בטפלשטיין(=טופולצאן)-תקע וראש ישיבה שם, ור בנימין וולף לעוו על מקומו אחריו, רב בסבדקה-תקפ, לקנבך-תקפד על מקום אביו ובנו ר דוד על מקומו אחריו. ממקורבי החת\"ס ובנו הכת\"ס. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. הסכים על \"ארץ צבי\" פרשבורג תרו. נזכר בשו\"ת החת\"ס, \"אמרי אש\", \"יד אליעזר\", ועוד. חיבר \"בית אברהם\"-תרסט - שסדר והו\"ל ר משה אהרן קרויס מטשטשנוביץ. אחיו - ר שלמה זלמן בעל \"יריעות שלמה\".","bk":[["בית אברהם – שו\"ת",""]]},{"i":2163,"n":"אולמן, אברהם מפרשבורג","f":"ישראל איסר מפיורדא","dt":"תקמה","dp":"פיורדא","b":"מחכמי פרשבורג. אחיו - ר שלום משטמפן ור משה מליפטא-מיקלוש."},{"i":2164,"n":"אולמן, בנימין מוואלקא","f":"שלמה זלמן ממאקווא","bt":"תרז","bp":"מאקווא","dt":"תרצב - כב אלול","b":"תלמיד הכת\"ס. חתן ר שלמה רוטשילד מוואלקא ועבר לשם. הו\"ל ספר אביו \"יריעות שלמה\" עם הערות ממנו."},{"i":2165,"n":"אולמן, בערמן","dt":"תר","b":"רב בזשאמבוקרט"},{"i":2166,"n":"אולמן, דוד מלקנבך","f":"אברהם מלקנבך","k":"בעל בית דוד","bt":"תקפו","dt":"תרסא-ז - כב טבת","dp":"לקנבך","b":"תלמיד הכת\"ס. חתן ר שמעון וינר. רב בלקנבך-תרט על מקום אביו. חיבר \"בית דוד\" ונדפס בסוף ספר אביו \"בית אברהם\". נזכר בשו\"ת מהר\"י אסאד, \"שבט סופר\", \"בן יהודה\", ועוד."},{"i":2167,"n":"אולמן, יוסף מקהיר","f":"נח צבי אולמן","b":"רב פעלים,רב ומו\"צ לאשכנזים בקאהיר"},{"i":2168,"n":"אולמן, יעקב אשר אנשיל מגרוסורד","f":"ישראל מגרוסורדין","k":"בעל בני ישראל","dt":"תרסח - כט סיון","b":"נכד בעל \"יריעות שלמה\". מחכמי גרוסורדין, וישב ולמד עם אחיו ר שלמה זלמן. חיברו הערות וביאורים לספר זקנם. נפטר צעיר."},{"i":2169,"n":"אולמן, ישכר מגרוסורדין","f":"שלמה זלמן-יריעות שלמ","b":"גביר ופרנס מחכמי גרוסורדין, יחד עם אחיו - ר משה, ר שלום, ר ישראל."},{"i":2170,"n":"אולמן, ישראל","f":"שלמה זלמן-יריעות שלמ","b":"גביר. בניו - ר שלמה זלמן ור יעקב אשר הוציאו לאור ספר זקנים \"יריעות שלמה\"."},{"i":2171,"n":"אולמן, ישראל איסר","f":"אברהם מלקנבך","b":"תלמיד הכת\"ס. אחיו של ר דוד אב\"ד לאקנבך. חתנו - ר יו\"ט יהודה ליב אבלס מוינה בעל \"לב יהודה\"."},{"i":2172,"n":"אולמן, ישראל איסר מזנטא","bt":"תקע","b":"עק\"ה,רב בזענטא"},{"i":2173,"n":"אולמן, ישראל איסר מפיורדא","dp":"פיורדא","b":"מנהיג ופרנס בפיורדא. מחותן עם ר יוסף שטינהרט בעל \"זכרון יוסף\". בניו - ר שלום מאנשבך ושטמפן, ר אברהם, ר משה מליפטא-מיקלוש."},{"i":2174,"n":"אולמן, ישראל מגרוסורדין - הנכד","f":"שלמה זלמן מגרוסורדין","b":"ראש הקהל בגרוסורדין על מקום אביו. בנו ר שלמה זלמן רב בבני ברק."},{"i":2175,"n":"אולמן, ישראל מגרוסורדין הסבא","f":"שלמה זלמן ממאקובה","b":"בנו - ר שלמה זלמן מגרוסורדין, וחתנו - ר יוסף שמואל בנימין גינז-שלזינגר."},{"i":2176,"n":"אולמן, ליב מלקנבך","f":"דוד מלקנבך","b":"חתנו - ר משה אהרן קרויס מנאדי-באניא."},{"i":2177,"n":"אולמן, מרדכי שלמה מבריסל","f":"נח צבי מאנטורפן","bt":"תרמג","bp":"בודפשט","dt":"תשכה - כג אייר","dp":"פיטע (הולנד)","b":"תלמיד השב\"ס. חתן ר אלעזר חיות (ריינס) - מצאצאי מהריץ חיות.רב קהילת האשכנזים בקהיר (מצרים)-תרסט, הולנד-תרעד, אנטורפן-תרעח, בריסל-תרצט. ניצל מהשואה."},{"i":2178,"n":"אולמן, משה מגרוסורדין","f":"שלמה זלמן-יריעות שלמ","bt":"תקפד","bp":"לקנבך","dt":"תרנט - כה ניסן","dp":"גרוסורדין","b":"נכד ר בונם איגר ממטרסדורף. חתן ר יעקב בער פלדמן מכפר פעטרא-ליד מארגרטן, ועבר לשם. רב בפעטרא, מארגרטען, גרוסורדין-תרמט. מחדושיו בספר אביו \"יריעות שלמה\" ובספר בנו \"נחלת צבי\". אחיו ר ישראל ראש קהילת גרוסורדין."},{"i":2179,"n":"אולמן, משה מליפטא מיקלוש","f":"ישראל איסר מפיורדא","b":"חתן ר נפתלי מליפטא-מיקלוש ועבר לשם. אחיו - ר שלום משטמפן ור אברהם מפרשבורג."},{"i":2180,"n":"אולמן, משה נפתלי מני יורק","f":"נח צבי מאנטורפן","k":"בעל הלכה למשה מסיני","b":"נכד בעל \"מחנה חיים\" מפסט. ונכד בעל \"יריעות שלמה\" ממאקעווע. רב בניו יורק-תשיט. חיבר גם צל העדה."},{"i":2181,"n":"אולמן, נח צבי מאנטורפן","f":"משה מפעטרא","k":"בעל נחלת צבי","bt":"תרטז או תרכ","bp":"פעטרא","dt":"תרעז - כג חשון","dp":"שוענינגן - פיטע (הולנד)","b":"נכד ר בונם איגר-אחיו של ר עקיבא. תלמיד זקנו ר שלמה זלמן בעל \"יריעות שלמה\", הכת\"ס, ודודו ר יהושע אהרן צבי וינברגר ממארגרטן. חתן ר חיים סופר מבודפשט ועבר לשם. רבה הראשון של קהילת החרדים באנטורפן-תרמג."},{"i":2182,"n":"אולמן, נפתלי הרץ ממיינץ והולנד","k":"בעל חכמת השרשים","b":"עבר להאג-הולנד-לפני תקל. פילוסוף, מחבר ספרים."},{"i":2183,"n":"אולמן, רפאל מזשאמבקרט","f":"אברהם מלקנבך","bt":"תקצו","bp":"לקנבך","dt":"תרעו - אדר","dp":"זשמבקרעט","b":"תלמיד הכת\"ס. מחכמי זשאמבאקרט במשך כששים שנה. ציר בקונגרס היהודי-תרכט."},{"i":2184,"n":"אולמן, שלום חריף מאנשבך","f":"ישראל איסר מפיורדא","k":"בעל דברי ר\"ש","bt":"תקטו - טז אדר","dt":"תקפה - טז אדר","b":"תלמיד קרובו ר יוסף שטינהרט בעל זכרון יוסף, ר פנחס הורביץ בעל ההפלאה, ר נתן אדלר מפפד\"מ ולמד אצלו קבלה. חתן ר רפאל ריסס מענדינגן-שוייץ ועבר לשם ובזיוו\"ש חתן ר דוד שטופא מפרוסטיץ (אלמנת ר מיכאל ורדניק). רב באנשבך-תקמד על מקום ר שמואל צורנדורפר, שטמפן-תקנג על מקום ר נתן מן אורהולץ, נאדי-אטאד-תקנט, פרונקירכן על מקום ר דוד דייטש, לקנבך-תקסט ובנו ר אברהם על מקומו אחריו, בנו גם - ר שלמה זלמן בעל \"יריעות שלמה\", אליקים (כנראה נפטר בילדותו).","bk":[["דברי ר\"ש - סוגיות",""]]},{"i":2185,"n":"אולמן, שלום מוייצען","f":"ישכר בערמן מזשאמבאק","b":"רב בווייצען-תר\"ס"},{"i":2186,"n":"אולמן, שלום מנאג'-אטאד","b":"רב ניאולוגי בנאג'י-אטאד-1799. רב ראשי של הקהילות הניאולוגיות במחוז שומוג'י. נזכר בשו\"ת החת\"ס."},{"i":2187,"n":"אולמן, שלמה ברוך מטורונטו","f":"אברהם","k":"בעל חנוך ומדע באור","bt":"תרעב","bp":"גורליץ","dt":"תשלב","dp":"טורונטו","b":"גדל אצל משפחה חשוכת ילדים בכפר הוס בהולנד, למד אצל ר יעקב גולדשמיד, עלה לירושלים, וניסה לפתח תרופה לסרטן מתאנים ע\"פ התנ\"ך. עבר לטורנטו ועסק בחינוך. חיבר \"חנוך ומדע לאור היהדות\" ובה רשימה ביבליוגרפית של כתביו."},{"i":2188,"n":"אולמן, שלמה זלמן מביסטריץ","f":"משה מגרוסורדין","bt":"תרכא-ד או תריט","dt":"תרצא - ו אלול","dp":"ביסטריץ","b":"תלמיד השב\"ס, ור משה הרש פוקס מגרוסורדין. חתן ר שלמה רוטשילד מואלקא. רב בויזניץ, גרוסורדין-תרן, ביטריץ(=ביסטריץ)-תרנה וחתנו ר מאיר שפיץ על מקומו אחריו, נשיא הלשכה האורטודוכסית בטרנסילבניה לאחר מלחמת העולם ה-I. קיבל אות הצטיינות ממלכות רומניה עבור שירותיו למען קהילות ישראל. מתורתו בספר אחיו ר נח צבי אולמן מאנטורפן - \"נחלת צבי\"."},{"i":2189,"n":"אולמן, שלמה זלמן מבני ברק-הנכד","f":"ישראל מגרוסורדין","b":"רב שכונת משכנות יעקב בבני ברק."},{"i":2190,"n":"אולמן, שלמה זלמן מגרוסורדין","f":"ישראל מגרוסורדין","k":"בעל בני ישראל","dt":"תרעה - כד ניסן","dp":"גרוסורדין","b":"נכד בעל \"יריעות שלמה\". תלמיד השב\"ס. חתן ר יצחק יהודה ליב סופר מדראהביטש בן הכת\"ס. מחכמי גרוסורדין, וישב ולמד עם אחיו התאום ר יעקב אשר אנשיל. חיברו הערות וביאורים לספר זקנם בשם \"בני ישראל\" וילנא תרסה. ראש הקהלה בגרוסורדין עם אביו ועל מקומו אחריו, ובנו ר ישראל על מקומו אחריו."},{"i":2191,"n":"אולמן, שלמה זלמן מפרוינקירכן","b":"רב בפרוינקירכן."},{"i":2192,"n":"אולמן, שלמה זלמן מרנדיק","f":"שלום מלקנבך","k":"בעל יריעות שלמה","r":"רב במאקווא","bt":"תקנב","bp":"לקנבאך","dt":"תרכג - יא טבת","dp":"מאקובה","b":"מגדולי חכמי דורו, חתן ר שמחה בונם איגר-גינז ממטרסדורף - אחיו של רע\"א, ובזיוו\"ש חתן הגביר ר יצחק קניגסברג מצהלם. רב ברענדעק-תקעח, מאקעווע(=מאקוב)-תקף על מקום חותנו כ-33 שנה, בקהילה פעל בית כלא בחצר בית הכנסת והיה סמכות להעניש את עבריני הדת. היה מחלוקת כנגדו בגלל התנגדותו לחדושים ותיקונים בדת והוסר מכהונתו וחזר אחר כמה חדשים. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד. \"שומר ציון הנאמן\" - אלטונא תרו-תרטז. נכדו - ר שלמה זלמן קליין מגאווא הו\"ל את ספרו עם הקדמה ותולדות המחבר. בניו - ר משה, ר ישכר, ר שלום, ר ישראל. ונכדיו - ר שלמה זלמן ור אשר - הו\"ל את ספרו - וילנא תרסה.","bk":[["יריעות שלמה – יו\"ד וש\"ס",""]]},{"i":2193,"n":"אולמן-ברמן, ישכר מזשאמבאק","f":"משה","bp":"ליפטא","dt":"תר - תשרי","b":"תלמיד החת\"ס. מחכמי אילאווא-תקפד, רב בזשאמבאק-תקצב."},{"i":2194,"n":"אולסקר, זאב וולף הלוי אשכנזי","f":"שמואל הלוי","k":"בעל חדושי הרז\"ה","bt":"תס","bp":"אלסק","dt":"תקלח","dp":"ירושלים","b":"לדעת ריבלין הוא החכם ר זאב הלוי בן שמואל מגדולי חכמי ברוד-תקל, ומגיד בטרנופול-תקיד, זולקווא-תקלא, והוא אחיו של ר חיים הלוי רבה של רובנא. עלה לירושלים-תקלו. חיבר ספר \"חדושי רבי זאב הלוי\", \"חדושי וכללות הרז\"ה\" - ירושלים תרמה. וכן \"דרישות הזאב\" דרשות על התורה שהחלו בטרנופול וגמרו בירושלים בשנת תקלו. בעל \"קרבן אליצור\" מספידו בספר \"פדהצור\"."},{"i":2195,"n":"אולף, דוד יוסף מפפד\"מ ומנהיים","dt":"תעט","b":"חתן ר אברהם דרוך, ובזיוו\"ש חתן ר אהרן דרשן תאומים שנאפר מקראקא (ונישאה לאחר פטירתו לר וולף צונץ מפפד\"מ). מחכמי פפד\"מ-תע. רב במנהיים. מבניו: ר יעקב."},{"i":2196,"n":"אולף, דוד מפפד\"מ","f":"יעקב","dt":"תקיד - ח סיון","dp":"פפד\"מ","b":"מחכמי פפד\"מ. נפטר צעיר."},{"i":2197,"n":"אולף, זליגמן יעקב מפפד\"מ","b":"מחכמי פפד\"מ-תקל בערך."},{"i":2198,"n":"אולף, יעקב מפפד\"מ","f":"דוד","dt":"תקכט - ה אייר","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":2199,"n":"אולשוונג, דב אריה מגרייבה","bp":"לוקניק","dt":"תשב","dp":"סמרקנד","b":"רב בגריווע(=גרייבה), קרסווע(=קראסלובקה), בזמן השואה ברח לסמרקנד ונפטר שם. פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":2200,"n":"אולשוונג, משה מטלז","bt":"תרסב","dt":"תשא - כ תמוז","b":"משגיח בישיבת טלז"},{"i":2201,"n":"אולשוונג, נחום","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":2202,"n":"אולשוונג, צבי יהודה מארה\"ב","f":"נחום","bt":"תרלג","b":"תלמיד ישיבות טלז, וולוזין, קעלם. נסמך מאת: ר אליעזר גורדון, הרוגצ'ובר. חתן ר משה מרדכי יודלביץ. גיסו של ר שמעון שקופ המזכירו בספרו. רב בדריירייסן, ביהכ\"נ \"משנה וגמרא\" בשיקגו, ר\"מ בישיבת טלז בקליבלנד, עלה לארץ והיה ר\"מ בישיבת סלובודקה בבני ברק-תשט."},{"i":2203,"n":"אולשוונגר, יצחק זאב מטאווריג","f":"שמואל","bt":"תקפה","bp":"פלונגיאן","dt":"תרנו - כח אב","dp":"פטרסבורג","b":"תלמיד ר ישראל סלנטר. רב בטוירגן(=טאווריג)-תרי, בפטרסבורג-תרלח. עסק בעניני ציבור ופעיל באגודת \"חו\"צ\". התנגד לאתרוגי קורפו."},{"i":2204,"n":"אומנסקי, יוסף","f":"חיים ישראל","k":"בעל לוי בן סיסי","bt":"תרל","bp":"סטאוויטשטש (קיוב)","dt":"תשכה","b":"מורה בחדר עברי בדובובה. מנהל בית הספר העברי בויזניץ, בתרסח בטרנוב. עבר לוינה ועלה לארץ-תרצד לקיבוץ גניגר. חיבר \"לוי בן סיסי\" טרנוב תרפט, \"תולדות רב\" טרנוב-פיעטרקוב תרצא, חכמי התלמוד ועוד.","bk":[["חכמי התלמוד",""]]},{"i":2205,"n":"אומרו (לקצנסקי), דוד","f":"דב יונה","k":"בעל נחלת אבות","bp":"אליטא-ליטא","dt":"תשא","b":"סופר אידי. פרסם ב\"דאס ווארט\" וב\"פאלקס בלאט\", עבר מהציונות למחנה הקומוניסטי. ערך את העתון הקומוניסטי \"וילנער עמעס\". פתח את כינוס הסופרים האידיים בליטא בנאום על תפקיד הסופר היהודי במהפכה. נספה בשואה."},{"i":2206,"n":"אונא, יוסף","b":"פרסם מאמרים ב\"ישורון\" - ברלין תרף."},{"i":2207,"n":"אונא, יצחק ממנהיים","f":"משה","k":"בעל שואלין ודורשין","bt":"תרלב","dt":"תשח - י אייר","b":"רב בקלויז במנהיים-תרנח, רב במנהיים-תרפ, עלה לארץ תרצה."},{"i":2208,"n":"אונא, משה","bt":"תרלג","b":"גדול בתורה ומדע,רב במנהיים-תרנ\"ט"},{"i":2209,"n":"אונגר, אביעזרי זליג אלעזר מקלו","f":"אברהם אלחנן מקאלושין","k":"אדמור מקאלושין","dt":"תרסא - ל תשרי","b":"חתן ר משה מקארוב (שושלת בעלז). אדמו\"ר בקאלושין(=קאלשין) על מקום אביו. בנו ר שלום שפירא מראוא רוסקא."},{"i":2210,"n":"אונגר, אברהם","dt":"תרז - א ניסן","b":"ראב\"ד בפאסטו"},{"i":2211,"n":"אונגר, אברהם אלחנן מקאלושין","f":"מרדכי דוד מדומברובא","dt":"תרמג - ד טבת","b":"חתן ר קלונימוס קלמן מפאריצק (שושלת לובלין), ובזיוו\"ש חתן ר חיים מאיר יחיאל ממוגלניצא (שושלת קוזניץ). רב בקוויף, אופוטשנא, אדמור בקאלושין. הו\"ל ספר המגיד מקוזניץ \"עבודת ישראל\". מבניו: ר יהושע יחיאל מגרודזיסק."},{"i":2212,"n":"אונגר, אברהם יהודה ליב מפרשבור","f":"יצחק מפרשבורג","k":"בעל קריה נאמנה","bt":"תרלה","bp":"קורטאקסי","dt":"תשה - כה תשרי","dp":"אושוויץ","b":"תלמיד השב\"ס, ור דוד יהודה ליב זלצר מהומנא. חתן ר דוד יוסף שטינר מפרשבורג. מחכמי פרשבורג וכיהן כסגן נשיא הקהלה. נספה בשואה. בניו - ר עקיבא שמחה מפרשבורג, ר דוד יוסף מירושלים בעל קרית דוד."},{"i":2213,"n":"אונגר, אברהם צבי מקאפוואר","k":"בעל מחנה אברהם","dt":"תשד","b":"רב בקאפוואר. נספה בשואה. בניו - ר יצחק שלמה מירושלים ור שמואל אפרים זלמן - הו\"ל את ספריו."},{"i":2214,"n":"אונגר, אלחנן יוחנן מאוסטרובא","f":"נפתלי אריה מאוסטרובא","k":"אדמור מאוסטרובא בנ\"י","b":"תלמיד האדמור מרדזימין."},{"i":2215,"n":"אונגר, אליעזר מדמביץ","f":"ישראל יוסף","bt":"תרע","bp":"דמביץ","dt":"תשנז","dp":"קנדה","b":"ממיסידי השומר הדתי בקראקא-תרפח, מנהל ביה\"ס בקליש. ניצל מהשואה, עלה לארץ-תשד. בשליחות בעניני עליה וחנוך בדרום אמריקה. חיבר ספר \"זכור\" על השואה."},{"i":2216,"n":"אונגר, אלעזר מז'אבנא","dt":"תשד","b":"רב בז'אבנה"},{"i":2217,"n":"אונגר, אלעזר מטרנוב","f":"שלום דוד","k":"אדמור מזבנא בטרנוב","bt":"תרן","bp":"רוזבדוב","dt":"תשג - ב אלול","b":"רב בזבנא-תרעט, אדמור מטרנוב-תרפג על מקום אביו. חתן ר נפתלי רוקח מנבריה, ואחר כך חתן ר אהרן אלימלך טברסקי האדמור מקראסנא. נספה בשואה עם רוב משפחתו. (באוצר הרבנים תאריך פטירתו י כסלו)"},{"i":2218,"n":"אונגר, בן ציון מצאנז","f":"מרדכי דוד מצאנז","dt":"תשא","b":"רב בסאנדז(=צאנז). חתן ר שלום ריינמן מנאראל. נספה בשואה."},{"i":2219,"n":"אונגר, בנימין מיאסלו","bt":"תרסח","bp":"יאסלו","b":"חזן בוינה. עלה לארץ-תרצה, וכיהן כחזן בתל אביב."},{"i":2220,"n":"אונגר, בנציון יוסף מפישטיאן","f":"שמואל דוד מטירנוי","bt":"תרעב","bp":"קראמפך","dt":"תשה - ז תשרי","dp":"סערעד","b":"תלמיד הדעת סופר. חתן ר קלונימוס קלמן ובר מ פישטיאן, רב בפישטיאן על מקום חותנו-תרצה. נספה בשואה. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא, \"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":2221,"n":"אונגר, גרשון מברלין","f":"אליהו","dt":"תקכח - כד ניסן","b":"מו\"צ בברלין, ומלמד תורה. הסכים על 'באר יעקב'-פיודא תקכז עם ר אהרן מגזע צבי ור יואל בן יקותיאל זקש."},{"i":2222,"n":"אונגר, דב בר מסטרטין למברג","f":"אברהם אלחנן מקאלושין","b":"חתן ר יהודה צבי מסטרטין. אדמור בלמברג. בנו ר יעקב יצחק שפירא - אב\"ד בירטש."},{"i":2223,"n":"אונגר, דוב מאונגואר","dt":"תשג","b":"רב באונגוואר"},{"i":2224,"n":"אונגר, דוד מסידרהרסט","f":"פנחס אליהו מאוסטרובא","b":"חתן ר אברהם אבא מפיטסבורג."},{"i":2225,"n":"אונגר, זלמן מביילסקי וגומבין","f":"יעקב אונגר","bt":"תרנז","dt":"תשג","b":"רב בביילסקו,גומבין"},{"i":2226,"n":"אונגר, חיים אליעזר מרדלוב","f":"יעקב יצחק מזבנא","bt":"תרכה","dt":"תרף","dp":"טרנוב","b":"חתן ר מאיר נתן הלברשטם-בן ה\"דברי חיים\" מצאנז, ובזיוו\"ש חתן ר נפתלי הורביץ ממעליץ. רב ואדמור ברדלוב-תרן."},{"i":2227,"n":"אונגר, חיים ידידיה הלוי","f":"שמואל דוד מטירנוי","b":"פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":2228,"n":"אונגר, חיים מאיר יחיאל מרדיחוב","f":"אבי עזרי זליג אלעזר","k":"אדמור מרדיחוב","dt":"תרסה","b":"חתן ר יצחק בצלאל מברוד (שושלת רופשיץ). בנו ר בעריש ריינמן מנארול."},{"i":2229,"n":"אונגר, ידידיה מטירטש","dt":"תשד","b":"רב בטירטש"},{"i":2230,"n":"אונגר, יהודה מסוקולוב","f":"יעקב יצחק מזבנא","k":"אדמור מסוקולוב ברישא","bt":"תרכב","dt":"תרצט - יז סיון","dp":"ניימרקט","b":"חתן ר יהושע חריף. רב בזבנא, סוקולוב-תרם, אדמור ברישא-תרסה, עבר לניימרקט. בנו היה ר נפתלי שמילא מקומו ונספה בשואה."},{"i":2231,"n":"אונגר, יהושע יחיאל מגרודזיסק","f":"אברהם אלחנן מקאלושין","dt":"תרנב","b":"חתן ר צבי פרנקל (שושלת פרמישלן)."},{"i":2232,"n":"אונגר, יואל מפאקש","f":"אליעזר","k":"בעל שו\"ת ריבא","bt":"תקס","bp":"רעכניץ","dt":"תרמו - יא טבת","dp":"פאקש","b":"תלמיד החת\"ס, ור אלכסנדר מייזלש מרעכניץ. חתן ר יוסף יוסט משאכטיץ ועבר לשם. רב בשאכטיץ-תקצז (נאלץ לקבל על עצמו רבנות בגלל התרוששות חותנו ובגלל בקשת החת\"ס שיעזוב את המסחר ויעבור לרבנות), רב בפאקש-תרג וראש ישיבה, חתנו ר אליעזר זוסמן סופר על מקומו אחריו. בזיוו\"ש חתן ר יעקב ברודא מקיצע.","bk":[["תשובת ריב\"א",""]]},{"i":2233,"n":"אונגר, יוסף","f":"מרדכי דוב אונגר","dt":"ב חשון","b":"רב בקושניץ,דומברובה"},{"i":2234,"n":"אונגר, יוסף יהודה מרדלוב","f":"חיים אליעזר מרדלוב","dt":"תש..","b":"נספה בשואה."},{"i":2235,"n":"אונגר, יוסף מדומברובה","f":"מרדכי דוד מדומברובה","bt":"תקס","dt":"תרכז - ב חשון","b":"תלמיד ר חיים מאיר יחיאל ממוגלניצא, ור ישכר בער מרדושיץ. חתן ר משה אליקים בריעה מקוזניץ, רב בקוזניץ על מקום חותנו זקנו-המגיד מקוזניץ. ובזיוו\"ש חתן ר אלעזר בן ה\"נועם אלימלך\". רב ואדמור בדומברובה-תרו על מקום אביו. בנו ר ישראל אלימלך רב אחריו. חתנו ר מאיר רובין מגלוגוב, ובזיוו\"ש חתן ר אלעזר מליזנסק. מתורתו במאסף \"כרם החסידות\"."},{"i":2236,"n":"אונגר, יוסף מפטשינוב","b":"רב בפטשינוב-תרצח."},{"i":2237,"n":"אונגר, יוסף משה מפישטיאן","f":"שמואל הלוי מבסקביץ","r":"רב בפישטיאן","bt":"תרטו-ז","dt":"תרנח - יז תשרי","b":"נכד ר יוסף דוקס מפרשבורג. תלמיד הכת\"ס, ור אליעזר זוסמן סופר מפאקש. חתן ר דוד משה פישר מפישטיאן, רב בפישטיאן-תרמג על מקום חותנו. מחדושיו בסוף \"נאות דשא\" לבנו - ר שמואל דוד מנייטרא, ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי. (באוצר הרבנים תאריך פטירתו - יז ניסן תרנז).","bk":[["שפתי יוסף - משניות",""]]},{"i":2238,"n":"אונגר, יחיאל מיכל מצעהלים","bt":"תקץ","dt":"תרעא - ח אדר","dp":"צהעלים","b":"תלמיד הכת\"ס, והמכתב סופר. חתן ר שלמה גשטטנר מטשארנא. מחכמי צעהלים-תרך."},{"i":2239,"n":"אונגר, יחיאל צבי הירש מטרנוב","f":"מרדכי דוד","k":"אדמור מטורנא","bt":"תקס-ע","dt":"תרם - כא תשרי","dp":"טרנוב (ולא ירושלים)","b":"חתן ר שמשון מזוולין-תלמיד היהודי הקדוש מפשיסחא. חותנו של ר חיים מצאנז-בזיוו\"ש. ראש קלויז צאנז בטורנא. בנו ר מרדכי דוד אב\"ד זמיגרוד."},{"i":2240,"n":"אונגר, יעקב","dt":"תשג","b":"רב בוולצלובק"},{"i":2241,"n":"אונגר, יעקב יצחק מדומברובא","f":"בן ציון מצאנז","k":"אדמור מדומברובה בנ\"י","dt":"תשסג","b":"אדמור מדומברובה בברוקלין-תשיא, מחותן עם האדמור מבובוב."},{"i":2242,"n":"אונגר, יעקב יצחק מזבנא","f":"ישראל אלימלך מזבנא","k":"אדמור מזבנא","bt":"תקצה-ח","dt":"תרנב - יד כסלו","dp":"זבנא","b":"אדמור בז'אבנה-תרכ. חתן ר מאיר מדזיקוב, בניו: ר שלום דוד, ר יהודה, ר חיים אליעזר, ר ישראל יוסף."},{"i":2243,"n":"אונגר, יעקב יצחק מניו יורק","f":"פנחס אליהו מאוסטרובא","bt":"תרצב","b":"חתן ר משה ביק. התגורר בניו יורק."},{"i":2244,"n":"אונגר, יעקב מרדיחוב","f":"שמואל מרדכי","bp":"רדיחוב","dt":"תש..","b":"נכד בעל \"דעת קדושים\", וגיסו של ר אליעזר מישל. חתן ר יצחק תאומים מקריסנפולי. רב ברדיחוב. נספה בשואה."},{"i":2245,"n":"אונגר, יעקב קופל מפרוינקירכן","b":"בנו - ר מאיר אליהו מפרוינקירכן, חתנו - ר נתן יהודה סופר ממיאווע - וינה."},{"i":2246,"n":"אונגר, יצחק אלעזר מדומברובה","f":"משה אליקים בריעה","b":"רב בלאמרוונע. חתן גיסו ר אברהם הורביץ מפקשיבניצה."},{"i":2247,"n":"אונגר, יצחק שלמה מבני ברק","b":"רב קהלת חתם סופר בבני ברק-תשלח."},{"i":2248,"n":"אונגר, ירחמיאל מברוקלין","f":"מרדכי דוד","dt":"תשנט","dp":"ניו יורק","b":"חתן ר חיים יעקב ספרין האדמור מקומרנא. ר\"מ בישיבת חתן סופר בניו יורק."},{"i":2249,"n":"אונגר, ישראל אהרן מקאשוי","f":"נפתלי צבי מברדיוב","k":"אדמור מקאשוי בקנדה","b":"חתן ר חיים מטעטש, ובזיוו\"ש חתן ר מרדכי זיגל מויליפולי. סייע לאביו בניהול הישיבה בברדיוב. אדמור במונטריאול."},{"i":2250,"n":"אונגר, ישראל אלימלך מזבנא","f":"יוסף מדומברובא","k":"אדמור מזבנא","bt":"תקעט","dt":"תרכז - ז אלול","b":"חתן ר יחיאל קוריצר נכד ה\"חוזה מלובלין\", היה רב בזבנא-תר והתחיל שושלת אדמורים שם."},{"i":2251,"n":"אונגר, ישראל יוסף מטרנוב","f":"יעקב יצחק מזבנא","k":"אדמור מזבנא בטרנוב","bt":"תרכח","bp":"זבנא","dt":"תשב - ל סיון","b":"חתן ר ראובן מדמביץ (שושלת רופשיץ). תלמיד דודו ר יהושע מדזיקוב, ואחר פטירתו בתרעג נהיה לאדמור בטרנוב. היה מלחין של תפלות. נספה בשואה עם רוב משפחתו, בן אחד ששרד והוא ר אליעזר חיבר \"זכור\" תל אביב תשה."},{"i":2252,"n":"אונגר, ישראל מזבנא","f":"שלום דוד מזבנא","k":"אדמור מזבנא","bt":"תרם","dt":"תרצז - א כסלו","dp":"ניו יורק","b":"חתן ר אריה ליב מצאנז. רב ואדמור בזבנא על מקום אביו. אשתו וילדיו נספו בשואה."},{"i":2253,"n":"אונגר, מאיר אליהו מטרנוב","f":"ישראל יוסף","dt":"תשג","b":"רב בטרנוב"},{"i":2254,"n":"אונגר, מאיר אליהו מפרוינקירכן","f":"יעקב קופל מפרוינקירכ","dt":"תרצט - כד כסלו","dp":"בודפשט","b":"תלמיד השב\"ס. מחכמי פרוינקירכן."},{"i":2255,"n":"אונגר, מאיר חיים מלקנבך","k":"בעל מאור החיים","bt":"תרסה","bp":"צעהלם","dt":"תשיח - י טבת","dp":"ירושלים","b":"רב בלקנבך-תרצה, עלה לירושלים-תרצט. חתנו - ר נתן גשטטנר."},{"i":2256,"n":"אונגר, מאיר חיים מצהלם","b":"פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":2257,"n":"אונגר, מאיר יהושע מסטבניץ","f":"מנחם מנדל מסטבניץ","k":"אדמור מסטבניץ","dt":"תרמא - יג אדר","dp":"ארץ ישראל","b":"חתן ר יהודה זונדל מאוחאן (שושלת בלז), ובזיוו\"ש חתן ר דוד ברדק-קלגסברון מוישניצא. מגדולי תלמידי ה\"דברי חיים\" מצאנז. עלה לארץ."},{"i":2258,"n":"אונגר, מאיר מקראקא","f":"משה אליקים בריעה","k":"אדמור מדומברובא קרקא","b":"בן האדמור מדומברובא. אדמור בקראקא."},{"i":2259,"n":"אונגר, מאיר מרדלוב","f":"חיים אליעזר מרדלוב","dt":"תשב - ל סיון","dp":"טורנא"},{"i":2260,"n":"אונגר, מנחם מנדל מסטבניץ","f":"מרדכי דוד מדומברובא","k":"אדמור מסטבניץ","dt":"תרמב","b":"חתן ר ישראל רוטנברג מסטאשוב (שושלת אפטא). תלמיד ר חיים מאיר ממגלוניצא. אדמור על מקום חותנו בסטאבניץ."},{"i":2261,"n":"אונגר, מרדכי דוד מדומברובה","f":"צבי הירש","k":"אדמור מדומברובה","bt":"תקל","dt":"תרג-ו - ז שבט","b":"עסק ביבוא יין מהונגריה ומכאן מקור שמו - אונגרען. תלמיד המגיד מקוזניץ, ר אלימלך מליזנסק ושל החוזה מלובלין, היה אדמור בדומברובה-בהוראת החוזה מלובלין, והתחיל שושלת אדמורים. נסעו אליו גדולי החסידות ובהם ה\"דברי חיים\" מצאנז, ר שלום מקמינקא ועוד. בניו ר מנחם מנדל מבלוזוב, ר אברהם אלחנן, ר נפתלי מזבנא."},{"i":2262,"n":"אונגר, מרדכי דוד מזמיגרוד","f":"יחיאל צבי הירש מטורנ","bt":"תרי","dt":"תרסו","b":"חתן ר בנימין זאב אבד זמיגרוד, אב\"ד זמיגרוד-תרלג על מקום חותנו. מחסידי צאנז ושיניבה, חתנו ר אשר ישעיה בן יצחק טוביה רובין מצאנז."},{"i":2263,"n":"אונגר, מרדכי דוד מצאנז","f":"ישראל אלימלך מזבנא","bt":"תריח","dt":"תרעו","b":"חתן דודו זקנו ר משה אונגר, ובראש בימ\"ד בצאנז אחר פטירת חותנו זקנו. רב בצאנז. נספה עם רוב משפחתו בזמן הטבח בצאנז. בנו היחיד ששרד ר יעקב יצחק שהיה לימים האדמור מדומברובה בניו יורק."},{"i":2264,"n":"אונגר, משה","b":"רב בסט-מיקלוש-תק\"פ"},{"i":2265,"n":"אונגר, משה","f":"מרדכי דוד","bt":"תקף","dt":"תרנה - יח תשרי","dp":"צפת","b":"חתן ר חיים מצאנז, עלה לצפת. בנו ר יעקב יצחק בצפת. חתנו היה רנ\"ח הורביץ - הצדיק הפלאי."},{"i":2266,"n":"אונגר, משה אליקים","f":"ישראל אלימלך אונגר","dt":"תקיח","b":"אדמו\"ר בדומברווה-תר\"ס"},{"i":2267,"n":"אונגר, משה אליקים בריעה","f":"ישראל אלימלך מזבנא","k":"אדמור מדומברובה","bt":"תריג","bp":"זבנא","dt":"תרעז - כא טבת","dp":"קשוי - דומברובא","b":"חסיד צאנז ואחר כך שינאווא, חתן ר אברהם הורביץ משנדישוב (אשתו נספתה בשואה בגיל 100). אדמור בדומברובה, בזמן מלחה\"ע ה-I ברח לקאשוי."},{"i":2268,"n":"אונגר, משה מלונג-ביץ","f":"פנחס אליהו מאוסטרובא"},{"i":2269,"n":"אונגר, משה מנחם מאוסטרובא נ\"י","f":"נפתלי אריה מאוסטרובא","k":"אדמור מאוסטרובא בנ\"י","dt":"תשמב - יח טבת","b":"אדמור מאוסטרובא בנ\"י. בנו ר יעקב יצחק בעל בימ\"ד בניו יורק."},{"i":2270,"n":"אונגר, נפתלי מזבנא","f":"מרדכי דוד מדומברובא","b":"חתן ר יעקב ממעליץ (שושלת רופשיץ)."},{"i":2271,"n":"אונגר, נפתלי מניימרקט","f":"יהודה מרישא","bt":"תרמב","dt":"תשב - כג סיון","b":"חתן ר יהושע חריף, וחתן ר אלתר זאב הורביץ מסטריזוב. היה אב\"ד בניימרקט-תרצט. נספה בשואה. חתנו ר לוי יצחק הורביץ האדמור מבוסטון."},{"i":2272,"n":"אונגר, נפתלי צבי מברדיוב","f":"משה אליקים בריעה","bt":"תרם","bp":"דומברובה","dt":"תשב - טז אב","b":"חתן ר משה הלברשטם אב\"ד ברדיוב. ויתר על אדמורות דומברובה לאחיו הצעיר. עמד בראש ישיבה בברדיוב. נספה בשואה."},{"i":2273,"n":"אונגר, עקיבא מסודיטץ","f":"יונתן","k":"בעל מאמר רבי עקיבא","bt":"תקעג","bp":"יארמוט","dt":"תרמא - כא אד\"א","b":"תלמיד מהר\"ם א\"ש, ר יחזקאל בנט מנייטרא ונסמך ממנו. רב ביארמוט, אב\"ד סודיטץ(=סודיוטץ)-תריא, היה גם מוהל. חתן ר עזריאל אקשטין מאנטורפן. מתורתו ב\"קרית ארבע\"-ירושלים תשכה."},{"i":2274,"n":"אונגר, עקיבא שמחה מפרשבורג","f":"אברהם יהודה ליב","k":"בעל קרית משוש","bt":"תרע","bp":"פרשבורג","dt":"תשב - ו אדר","dp":"בוכנולד","b":"רב בפרשבורג. נספה בשואה."},{"i":2275,"n":"אונגר, פנחס אליהו מאוסטרובא","f":"נפתלי אריה מאוסטרובא","dt":"תשמד - כט טבת","b":"חתן ר ברוך מרדכי בורשטין."},{"i":2276,"n":"אונגר, ראובן","b":"רב בנאדי-טעטעני-תרמ\"ה"},{"i":2277,"n":"אונגר, ראובן מקוזמיר","f":"ישראל יוסף מטורנא","k":"אדמור מקוזמיר","dt":"תשג - חשון","b":"תלמיד ר מאיר אריק מטורנא. רב בראזמיריז,וילקי, רב ואדמור בקוזמיר."},{"i":2278,"n":"אונגר, שלום דב (דוד) מזובנא","f":"יעקב יצחק מזבנא","k":"אדמור מזבנא-יד שלום","bt":"תרך","bp":"זבנא","dt":"תרפג - א אלול","dp":"וינה","b":"חתן ר מנחם מנדל שפירא אב\"ד לנצהוט, ובזיוו\"ש חתן ר משה מרוזוודוב (וב\"אהלי שם\" חתן - ר צבי הירש הורביץ מרוזוודוב). ההדיר את ספר סבו \"אמרי נועם\". רב בראקוב, רב ואדמור בזבנא-תרנב על מקום אביו, ברח לוינה-תרעד ואחר כך טרנוב. חיבר \"יד שלום\" טאלטשווא תרעא (בעילום שמו כמחבר) בהשתדלות תלמידו ר ישכר שלמה טייכטל. תשובה ממנו ב\"קהלת אשר\" - אושפיצין תרפג (ונדפסה גם ב\"יד שלום\" - נ\"י תשכז)."},{"i":2279,"n":"אונגר, שלום משה הלוי מנייטרא","b":"חתן ר שמחה נתן גרינבורג מקעזמרק. רב בנייטרא-ניו יורק."},{"i":2280,"n":"אונגר, שלמה זלמן מגלינא","dt":"תרצח","b":"היגר לארה\"ב. פרסם בעתונים."},{"i":2281,"n":"אונגר, שמואל","b":"חתן ר יוסף דוקס מפרשבורג. אביו של ר יוסף מפישטיאן."},{"i":2282,"n":"אונגר, שמואל דוד מטירנוי","f":"יוסף משה מפישטיאן","k":"בעל נאות דשא-תשכג","r":"רב בקורמפך שבסלובקיה, ואח\"כ בטירנוי, ובסוף ימיו בנייטרא","bt":"תרמו","dt":"תשה - ט אדר","b":"חתן ר נח ברוך פישר מפרשוב. דיין בקרומניץ-תרעד, רב וראש ישיבה בטירנוי-תרעח, נייטרא-תרצא על מקום ר אברהם אהרן כץ וראש ישיבה - הישיבה האחרונה ששרדה בסלובקיה בזמן השואה (נקראה בשם \"הותיקן של היהודים\"). נשיא הקהילות החרדיות בצ'כוסלובקיה, ומראשי אגו\"י. ביקר בארץ-תרצה. בעל ספריה עשירה. נספה בשואה. תלמידיו הוציאו לאור קובץ \"הלכות החדש\" - טירנוי תרצא. פרסם מאמרים ב\"משא ומתן\" - טירנוי תרצא, \"שערי אורה\" - מיהאלביץ תרץ-תרצד.","bk":[["נאות דשא - הגדה של פסח ועוד",""]]},{"i":2283,"n":"אונטברג, ישראל מליטא וארה\"ב","bt":"תרכג","dt":"תרלד","b":"היגר לניו יורק. גביר ונדבן ומחשובי עסקני היהדות החרדית בניו יורק, ממיסדי \"החברה לחנוך יהודי\", ותרם רבות לעניני חנוך יהודי. פעיל בארגון העזרה לפליטים אחרי מלחה\"ע ה-I."},{"i":2284,"n":"אונטרמן, איסר יהודה מירושלים","b":"רב ראשי בארץ ישראל על מקום הרב יצחק הרצוג. פרסם מאמרים ב\"כרם ציון\" - ירושלים תשכג - קובץ \"מדרש בני ציון\", \"המסלה\" - נ\"י תרצו, \"סיני\" - ירושלים תרצז, פרסם מאמרים ב\"קול תורה\" - ירושלים תשז, \"תבונה\" - ירושלים תשא-תשח, \"תלפיות\" - נ\"י תשד."},{"i":2285,"n":"אוני, שמואל משלוניקי","dt":"שפב - ג תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":2286,"n":"אונסדורפר, הלל מלאשאנץ","f":"מרדכי אריה מגוטא","bt":"תרנב","dt":"תשה - ז טבת","b":"חתן ר צבי הרש הלוי רוזנברג מפרשבורג. ר\"מ בביהמ\"ד של רבי משולם איגרא בפרשבורג, רב בלושאנץ-תרפא. נספה בשואה."},{"i":2287,"n":"אונסדורפר, זלמן מפרשבורג","b":"מחכמי פרשבורג ומלמד תורה, ספרן של החברא קדישא על מקום ר שמואל דונט. ר\"מ בחברה \"מבקשי תורה\"-תרעו."},{"i":2288,"n":"אונסדורפר, מרדכי אריה מגוטא","b":"שו\"ב ורב בגוטא. חתן ר צבי הרש הלוי רוזנברג מנהל בית היתומים בפרשבורג."},{"i":2289,"n":"אונסדורפר, צבי מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":2290,"n":"אונסדורפר, שלמה זלמן מפרשבורג","f":"מרדכי אריה מגוטא","k":"בעל שפתי שלמה","bt":"תרן","bp":"בערעשק-קעטי","dt":"תשה - א חשון","b":"תלמיד הדעת סופר, ור יוסף צבי דושינסקי. חתן ר יחזקאל שטרן מפרשבורג. רב ומלמד בפרשבורג. נספה בשואה."},{"i":2291,"n":"אונסדורפר, שמואל אלכסנדר","f":"שלמה זלמן מפרשבורג","bp":"פרשבורג","dt":"תשסב - יט ניסן","dp":"נתניה","b":"תלמיד הדעת סופר, ור שמואל דוד אונגר מנייטרא, ור פסח סגל ממנצסטר. חתן ר יוסף דב בלייך. רב במונטריאול. עלה לארץ-תשמו וכיהן כרב חסידי צאנז בפתח תקוה."},{"i":2292,"n":"אוסובסקי, יהודה","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":2293,"n":"אוסובסקי, שלמה זלמן מסלובודקה","f":"יוסף ברוך","k":"בעל כרם שלמה","bt":"תרמג","bp":"קרלין","dt":"תשא","dp":"סלובודקה","b":"תלמיד ישיבת מיר, גלה לרוסיה בזמן מלחה\"ע ה-I, ואחריה רב בסלובודקה. נספה בשואה - בפוגרום שערכו הליטאים. חיבר חדושים על הש\"ס, פרסום בחוברת שע\"י ישיבת \"בית ישראל\". נרצח בטרם הספיק לסיים את הדפסת ספרו \"כרם שלמה\". פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב."},{"i":2294,"n":"אוסטה מרגוס מאזמיר","b":"מדפיס ארמני באזמיר-תק בערך."},{"i":2295,"n":"אוסטר, זאב וולף מלנצהוט","bt":"תקף","dt":"תרם","b":"נכד ה\"נועם אלימלך\", חסיד צאנז, חתן ר נפתלי מליזנסק. דיין בלנצהוט, מחותן של הרבי מויליפולי. חתנו ר שמואל צבי ויס בעל \"פרי לבנון\"."},{"i":2296,"n":"אוסטר, יצחק מקראקא","f":"זאב","bt":"תרעג","dt":"תשנד","b":"עבר לאנטורפן, ניצל מהשואה, עבר לארה\"ב. עלה לארץ-תשיט, והתישב בבני ברק."},{"i":2297,"n":"אוסטרובסקי, משה","f":"מאיר נחמן","k":"בעל מבוא לתלמוד","bt":"תרמה","bp":"קרלין-פינסק","b":"עלה לארץ-תרנד, תלמיד ישיבת \"תורת חיים\" בירושלים אצל ר זרח אפשטין. רב במזכרת בתיה. פרסם מאמרים ב\"הדביר\" - ירושלים תרעט. חיבר גם \"כנסת ישראל\", \"שבת הארץ\", ועוד. מיסד ביהמ\"ד למורים \"מזרחי\" בירושלים, ממיסדי שכונת \"קרית משה\" בירושלים."},{"i":2298,"n":"אוסטרובסקי-המאירי, מ'","k":"בעל מבוא התלמוד","bt":"תרמו","dt":"תשז - כה סיון","b":"רב פעלים ליישוב א\"י,רב בעקרון-תרע\"ב,קרית משה בירושלים"},{"i":2299,"n":"אוסטרויל, יעקב","b":"תלמיד ר ישראל רפפורט מטורנא שהזכירו בספרו \"מהר\"י הכהן\"."},{"i":2300,"n":"אוסטרזצר, ישראל מקולומיאה","bt":"תרסד","b":"סגן מנהל המכון למדעי היהדות בוארשא-תרפט, מרצה בסמינר הממלכתי למורי דת משה-תרצג. חיבר מאמרים תלמודיים שהופיעו בוארשא ובבודפשט בשנים תרצא-תרצה."},{"i":2301,"n":"אוסטרזצר, מאיר","f":"שלמה","dt":"תרפד","dp":"אלטונה","b":"נכד ר משולם ישכר הורביץ מסטניסלב. חתן ר יעקב קלוגהופט מברודי."},{"i":2302,"n":"אוסטרזצר, שמואל דב מאנטורפן","f":"מאיר","k":"בעל עלי דשא","bt":"תרסב","bp":"ברודי","dt":"תשמה","dp":"הרצליה","b":"תלמיד רש\"י רבינוב. מחנך בדיסלדורף, ומזכיר \"מחז\"ה\" באנטורפן. חתן ר שלמה דרפלר. ניצל מהשואה. עסק בחינוך באנטורפן. חיבר \"עלי דשא\" בני ברק תשלז."},{"i":2303,"n":"אוסטרינסקי, יהודה ליב משטוצין","f":"מנחם מנדל איזנשטט","bt":"תרלד","b":"רב בשטוצין-פלך וילנא-תרסא, רב בלידוונקה(=לידווענאווע)-פלך סובאלק."},{"i":2304,"n":"אוסטרינסקי, מנחם מנדל","f":"איזנשטט, מנחם מנדל","k":"בעל צמח מנחם","b":"רב בסטוטשין(=שטוצין)-תר\"נ"},{"i":2305,"n":"אוסטרליץ, בנימין זאב וולף מאיז","dt":"תרכט - כסלו","b":"ראב\"ד באייזנשטט. חתם-תריד עם ר עזריאל הילדסהיימר. חתנו - ר אהרן פישר, ונכדו ר שלמה פישר מקרלסבורג."},{"i":2306,"n":"אוסטרליץ, זאב וולף מפרג","b":"תלמיד ר יונתן איבשיץ. דיין ור\"מ בפרג-תקל."},{"i":2307,"n":"אוסטרליץ, ליב הרש מפרשבורג","b":"חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":2308,"n":"אוסטרליץ, שמואל הלוי ממישקולץ","f":"שמעון מוינה","bt":"תרכב","bp":"וינה","dt":"תרצט - יז אלול","dp":"מישקולץ","b":"תלמיד השב\"ס, ור אליעזר זוסמן סופר מפאקש. חתן ר משה אריה רוט מפאפא ועבר לשם. רב בסעמרין(=שומוריה)-תרסג, מישקולץ-תרעד וראש ישיבה. פעיל בתנועה הציונית וביקר בארץ-1939."},{"i":2309,"n":"אוסטרר, אורי פיבל מקריסנפולי","f":"אהרן","k":"בעל אור החכמה","bt":"תץ-תק","bp":"לשצוב","dt":"תקסו","b":"תלמיד ר קהת מווערש,ר לייב שרה'ס, ור יעקב יצחק החוזה מלובלין. התגורר בקריסנפולי, רב בטולטשין ובדובנקא-תקן (ליד לובלין). רוב כתביו נשרפו. חיבר \"אור החכמה\" לשצוב תקעה. מחותן עם ר מרדכי מנשכיז. בניו ר מנחם מנדל, ר פנחס, ר משה מזענטא-מראשוני החסידים בהונגריה - חותנו של ר חיים פולק מבריגל.,"},{"i":2310,"n":"אוסטרר, אורי שרגא פיבל מבלשביץ","f":"שלמה כץ","b":"מחכמי בלשביץ, תלמיד רמ\"ל מססוב ונודע בשם ר פייביש. שמו המלא מופיע בפנקס \"הלואת חן\"."},{"i":2311,"n":"אוסטרר, משה מאוסטרהא וברוד","f":"הלל מזאמושט","k":"בעל ערוגת הבושם","bt":"תסה","dt":"תקמה - יא טבת","b":"מקובל מחכמי אוסטרהא, עבר לברוד וכיהן כמגיד מישרים שם. חתם על החרם נגד הקמיעות - ברודי תקיב. תלמידו בנסתר היה ר מרדכי מרגליות מברוד. חיבר \"ערוגת הבושם\", תהלים עם פירוש \"דרש משה\" (שהיה אצל האדמור מבלז נגנב ממנו ונמצא ונמסר לנכד ר אהרן אוסטרר מברודי שהוציאו לאור). נזכר ב\"מקדש מלך\" לר שלום בוזגלו. הסכים על כמה ספרים ובהם \"תולדות יוסף\".","bk":[["ערוגת הבושם – שיר השירים וקבלת שבת",""]]},{"i":2312,"n":"אוסטרר, שמואל מברוד","f":"שלום","k":"בעל תורת האדם","bt":"תקכ","bp":"ברודי","dt":"תקפט - כז טבת","b":"חתן ר משה אוסטרר. גיסו של ר אברהם גרשון מקיטוב שעלה לירושלים. תלמיד ר אברהם נח הלר מדולינא. מקובל, איש מופת. עבר מאוסטרהא (שעל שמה נקרא) לברודי ונחשב לצדיק. חיבר \"תורת האדם\" למברג תקפה, ועוד. בנו ר דוד שלמה מטולטשין תלמיד ר ברוך ממזבוז. נכדו - ר שמואל אוסטרובסקי מחכמי ברודי."},{"i":2313,"n":"אוסיליו, יהודה חיים ממודנא","b":"מחכמי מודנא, למד רפואה ופילוסופיה בפדובה, שיר לכבודו-תכ מאת ר שלמה קוניאן."},{"i":2314,"n":"אוסימה, דוד אשכנזי ממנטובה","f":"מלכיאל","b":"דיין במנטובה-תנה. חתם על פס\"ד ותעודות עם הרמ\"ז ועם ר יהודה בריאל, חתם על שטר שידוכין אלמנת הרמ\"ז עם ר אביעד שר שלום (וחתם דוד בן מלכיאל אשכנזי)."},{"i":2315,"n":"אוסלנדר, אליעזר מאויהל","dt":"תשד","b":"ר\"מ באויהל"},{"i":2316,"n":"אוסנברג, יצחק מטשבין","f":"אברהם דוד הלוי","bt":"תרסז","bp":"טשבין","dt":"תשנג","b":"חסיד בלז. חתן ר שלמה זלמן דבי מקראקא. לימד בשטיבל בלז בעיר. ניצל מהשואה, עבר לאנגליה ושימש כרב בישיבת בלז בלונדון. בזיוו\"ש חתן ר שמעון נוסבוים-טיפנברון מדובצק. עלה לירושלים-תשמג. נפטר ללא ילדים."},{"i":2317,"n":"אופיבך, יהודה אשר מברוכסאל","b":"אב\"ד ברוכסאל-תקן בערך. בנו - ר מאיר אופנהיים."},{"i":2318,"n":"אופיבך, יעקב משה קאשמן מפרשבור","dt":"תקעג - כ תמוז","dp":"פרשבורג","b":"מחכמי פרשבורג ומראשי הח\"ק."},{"i":2319,"n":"אופלטקה רחמים יוסף חיים","bt":"1847","dt":"ה'תרסז 1907","bk":[["מסעי היר\"ח",""]]},{"i":2320,"n":"אופן, אהרן מרישא","f":"מאיר","bt":"תרפג","bp":"רישא","dt":"תשנב","b":"תלמיד רד\"ב ויידנפלד בטשבין. ניצל מהשואה וגלה לסמרקנד - שם התקרב לחב\"ד. עלה לארץ ושימש רב בביכ\"נ חב\"ד ברמת גן."},{"i":2321,"n":"אופן, יצחק מסטוטשין","b":"רב בסטוטשין-תקף, בנו ר חיים על מקומו אחריו-תקצח (והיה מחלוקת על הבן - תמך בו ר אברהם מרדכי רימלט והתנגד ר שבתי רפפורט מדומברובה."},{"i":2322,"n":"אופנבך, קשמן מפרשבורג","b":"מחכמי פרשבורג-תקסז, והחת\"ס התגורר בחדרו בזמן מלחמת נפוליאון."},{"i":2323,"n":"אופנבך, שלמה מפרשבורג","b":"מנהל ביה\"ס הלאומי בפרשבורג-1790."},{"i":2324,"n":"אופנהיים, אברהם","b":"ת\"ז"},{"i":2325,"n":"אופנהיים, אברהם חיים מפעציל","f":"שמעון - הר הכרמל","k":"בעל אלון בכות","bt":"תקנו","dt":"תקעח-ף-פד","b":"רב בפעצעל(=פעציל)-הונגריה. נפטר צעיר בחיי אביו - שהדפיס לזכרו \"הר אבל\" לבוב תקפה."},{"i":2326,"n":"אופנהיים, אברהם ממנהיים","f":"ליב ממנהיים","k":"בעל אשל אברהם","dt":"תקמז - יא חשון","dp":"הנובר","b":"רב במנהיים, אמשטרדם, ר\"מ בהנובר."},{"i":2327,"n":"אופנהיים, אהרן מפפד\"מ","b":"שתדלן יהודי נסיכות ביירויט-תם. מראשי קהילת פפד\"מ. היה במשלחת יהודי פפד\"מ אל הקיסר יוזף-תסב - והיה דובר המשלחת. יהודי ביירוט כיבדו אותו ב\"מי שבירך\" מיוחד מדי שבת."},{"i":2328,"n":"אופנהיים, אליהו מהמבורג","f":"משה מנחם מנדל","dt":"תקמג - ב טבת","dp":"אלטונא","b":"תלמיד ר יחזקאל קצנלנבוגן. חתן ר ישכר בער הכהן מהמבורג. גביר ופרנס בהמבורג, ממיסדי הקלויז הישן בהמבורג-תקיד. עמד לצדו של ר יונתן איבשיץ בזמן המחלוקת."},{"i":2329,"n":"אופנהיים, אנשיל מפפד\"מ","b":"דיין אצל ר נתן אפשטין-רמ. נזכר ב\"יוסף אומץ\" לר יוזפא האן, חיבר הגהות לספר עברונות."},{"i":2330,"n":"אופנהיים, אריה יהודה ליב מנישט","f":"אברהם","k":"בעל דרך עולם הנצחי","dt":"תקסד - ג חשון","b":"נכד ר יהודה ליב מבוסקוביץ. רב בניישטטל(=פריישטאט)-תקלד. חתנו - ר שמעון קרומנוי מפעסט, בנו - ר שמואל אופנהיים מפאפא - הו\"ל תרי\"ג מצוות לר יונתן איבשיץ לבוב תקעד."},{"i":2331,"n":"אופנהיים, אשר אנשיל","f":"שמעון וואלף אופנהים"},{"i":2332,"n":"אופנהיים, אשר אנשיל מדעסוי","f":"נפתלי הרץ","k":"בעל דברי אשר","b":"חיבר ספר בענין המילה בשם \"דברי אשר\" - \"חרבות צורים\"."},{"i":2333,"n":"אופנהיים, געץ מוינה","b":"ממונה על הקדש ר שמשון ורטהיימר בוינה לטובת ארץ ישראל, ופגש את ר ישראל משקלוב בהיותו בוינה-תקעג."},{"i":2334,"n":"אופנהיים, דב בר - הזקן","dt":"תקפד - י כסלו","dp":"פרשבורג","b":"חתן ר ברוך רפפורט מפיורדא. אב\"ד פרשבורג. זקנו של בעל \"מי באר\"."},{"i":2335,"n":"אופנהיים, דב בר מאיבשיץ","f":"חיים","bp":"פרשבורג","dt":"תרכ - ל כסלו","b":"רב באיבשיץ(=איבנשיץ), דרזניץ. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. לפי רש\"י פין - הוא המחבר \"מי באר\" - ראה: ר דב בר בן יצחק מפרשבורג."},{"i":2336,"n":"אופנהיים, דב בר מפרידבורג","f":"יחיאל מיכל אופנהיים","b":"רב בפרידבורג והמדינה-תק\"נ"},{"i":2337,"n":"אופנהיים, דב בר מפרשבורג-הנכד","f":"יצחק אופנהיים","k":"בעל מי באר","dt":"תרי - יג תשרי","dp":"פרשבורג","b":"נכד ר דב בר מפרשבורג(-חתנו של ר ברוך רפפורט מפיורדא). חתן ר שלמה טלטש ממורביה. תלמיד חכם משכיל ונוטה לריפורמה בפרשבורג, ממיסדי ביה\"ס בפרשבורג-תקף - בניגוד לדעת החרדים, הצטרף לחוגי ה\"מתקדמים\" - החת\"ס והכת\"ס וכן ר אריה ליב צינץ בעל \"משיבת נפש\" הזכירוהו בספריהם, אולם לבסוף כשפנה לריפורמה קרא עליו החת\"ס \"מי באר לא נשתה\". חיבר שירים ובהם ב\"בכורי העתים\"-תקפב, וכן שיר לכבוד המלכה קרולינה והודפס ע\"י הקהלה. (אצל הרצוג - קהלת שטמפי - תאריך פטירתו טז תשרי תריא)."},{"i":2338,"n":"אופנהיים, דוד מיאמניץ","f":"דוב בער אופנהיים","dt":"תרכז - ג חשון","b":"רב ביאמניץ,בטשקרק"},{"i":2339,"n":"אופנהיים, דוד מניקלשבורג","f":"אברהם","k":"בעל תהלה לדוד","bt":"תכד","bp":"ורמייזא","dt":"תצג-ז - ז תשרי","b":"תלמיד ר גרשון אוליף בעל \"עבודת הגרשוני\" (וחיבר הקדמה לספר רבו). מגדולי דורו, עשיר, מרביץ תורה בעל ספריה גדולה, רב בניקלשבורג-תנ, פרג והמדינה-תסב, נתקבל לאב\"ד בבריסק-תנח אך לא הגיע לשם. חיבר \"נשאל דוד\". מאמר ממנו ב\"פליטת סופרים\" - וילנא תרכג."},{"i":2340,"n":"אופנהיים, דוד מקרימנויא וטימיש","f":"צבי או ליב","k":"בעל נחלת דוד","bt":"תקי","dt":"תקפא - כג אדר","b":"נינו של ר דוד אופנהיים מפרג. תלמיד ר מאיר ברבי מפרשבורג, ור ירמיה ממטרסדורף. רב בטימישואר על מקום ר אליעזר ליפמן, ובנו ר יהושע צבי בעל \"עיני הדעת\" על מקומו אחריו (נטה להשכלה). בנו גם - ר שמעון בעל \"הר הכרמל\"."},{"i":2341,"n":"אופנהיים, זוסמן מפרשבורג","b":"נכד ר שמואל אופנהיימר מוינה. ראש קהלת פרשבורג-תצו."},{"i":2342,"n":"אופנהיים, זיסקינד","dt":"1737","dp":"אשפערג","b":"גביר ובנקאי אצל הקרדינל אלכסנדר מוירטנברג, לאחר מות פטרונו נאסר ונהרג עק\"ה לאחר שסירב להתנצר כדי להציל את עצמו."},{"i":2343,"n":"אופנהיים, חיים מדרזדן","f":"יצחק אופנהיים","bt":"תקכד","dt":"תקפב - יא תשרי","b":"רב בדרזדן"},{"i":2344,"n":"אופנהיים, חיים מטאהרן","f":"דוב בער אופנהיים","bt":"תקצג","dt":"תרנא","b":"חתן ר שמעון פרידמן מלובליניץ. רב בטוהרן."},{"i":2345,"n":"אופנהיים, יהודה ליב מבסקוביץ","k":"בעל מנחת יהודה","b":"רב בבסקוביץ-תסח, פערשא ומדינת שוובן. דודו-אחי אמו ר דוד אופנהיים. בנו ר ישכר בר אופנהיים."},{"i":2346,"n":"אופנהיים, יהודה ליב מנירטיגולה","dt":"תרלח","dp":"ראסיין","b":"חתן ר שלמה לוינסון מיאסווען ליד קידאן בעל \"זכרון שמואל\". רב בגירטיגולה(=נירטעגלי)-פלך ראסיין, ור שמואל אפשטין בעל \"אמרי שפר\" על מקומו אחריו, דיין ומו\"ץ בראסיין.."},{"i":2347,"n":"אופנהיים, יהודה ליב מפרשבורג","f":"דניאל משה","dt":"תצב - ז אדר","dp":"פרשבורג","b":"מחכמי פרשבורג"},{"i":2348,"n":"אופנהיים, יהושע צבי הירש מטימי","f":"דוד - נחלת דוד","k":"בעל עיני הדעת","bt":"תקנג-ו","bp":"כפר אלמאש-ליד הוניאד","dt":"תריט - יח סיון","b":"תלמיד ר מרדכי בנעט, ר משה מינץ מאופן והחת\"ס. רב באלמאש, טימישואר(=טעמעשוואר) לצד אביו, ועל מקומו אחריו-תקפא. סירב לרבנות קרלסבורג על מקום ר יחזקאל בנט. חיבר \"עיני הדעת\" חלקו בגרמנית - כנגד אהרן חורין בעל \"אלאסף\" שיצא כנגד מאמרי חז\"ל."},{"i":2349,"n":"אופנהיים, יואל","b":"מגדולי חכמי אשכנז-שנת ק'"},{"i":2350,"n":"אופנהיים, יוסף","f":"דוד אופנהים","dt":"תצט - טז תמוז","b":"מרביץ תורה,רב בהעלישוי,עבר להנובר"},{"i":2351,"n":"אופנהיים, יחיאל מיכל מפרידבורג","f":"דוד אופנהיים","b":"רב בפרידבורג-תק\"כ"},{"i":2352,"n":"אופנהיים, יעקב משאמשון","f":"דוד אופנהיים","b":"רב בשאמשון-תר ור יצחק יעקב בלום על מקומו אחריו."},{"i":2353,"n":"אופנהיים, יצחק","b":"מגדולי חכמי אשכנז,רב באופנהיים-ר\"כ"},{"i":2354,"n":"אופנהיים, יצחק מפיורדא","f":"דוב בער אופנהיים","b":"רב בפיורדא-תק\"ל"},{"i":2355,"n":"אופנהיים, ישכר דוב מבודפשט","f":"יהודה ליב","dt":"תקה - ה אייר","dp":"בודפשט","b":"רב באויבן ישן(=בודפשט) ור נתן בן מתתיה על מקומו אחריו. נכדו - ר שמעון אופנהיים קרומונוי מפעסט."},{"i":2356,"n":"אופנהיים, לאזל מפרשבורג","f":"קופל מפרשבורג","b":"מחכמי פרשבורג, חתם-תקס על תקנות הח\"ק."},{"i":2357,"n":"אופנהיים, ליב","f":"אשר אנשל","b":"מרבני אשכנז"},{"i":2358,"n":"אופנהיים, ליב הזקן","f":"אברהם","b":"רב-שנת תק\"כ. בו ר אברהם ונכדו ר ליב"},{"i":2359,"n":"אופנהיים, ליב מגלוגא","f":"שמואל","k":"בעל מטה יהודה","b":"רב בגלוגלא. חיבר \"מטה יהודה\" אופיבך תפא."},{"i":2360,"n":"אופנהיים, ליב מפריישטט הנכד","b":"רב בפריישטט-תק\"ע. חתנו - ר שמעון אופנהיים"},{"i":2361,"n":"אופנהיים, ליזר מפפד\"מ","dt":"תצט - כו אייר","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ-תפא."},{"i":2362,"n":"אופנהיים, מאיר מפיורדא","f":"יהודה אשר אופיבך","b":"נאמן קהלת פיורדא-תקסה. נזכר בשו\"ת ר ידידיה טיאה-וייל."},{"i":2363,"n":"אופנהיים, מיכאל מפרשבורג","b":"מחכמי פרשבורג-תקנב, נשא את אמו של ר יוסף דוקס וגידלו וחינכו."},{"i":2364,"n":"אופנהיים, מיכל מפפד\"מ","dt":"תקיב - א אב","dp":"פפד\"מ","b":"ר\"מ בפפד\"מ."},{"i":2365,"n":"אופנהיים, משה הלוי מלנדא","b":"מחכמי פפד\"מ, לנדא. חתם על תקנה בפפד\"מ-שג בענין המחלוקת עם קהל שוואבן."},{"i":2366,"n":"אופנהיים, משה מטימישואר","f":"דוד מטימישואר","dt":"תרא - ב טבת","b":"רב בטימישואר-תקפב אצל אביו. נפטר צעיר."},{"i":2367,"n":"אופנהיים, משה מלנדא","b":"רב בלנדא. השתתף באסיפת הרבנים בוורמייזא-שב כנציג מדינת אלזס."},{"i":2368,"n":"אופנהיים, משה מפפד\"מ","f":"יו\"ט","b":"חתן ר יעקב שמש מפפד\"מ. מחכמי פפד\"מ."},{"i":2369,"n":"אופנהיים, משה מפרשבורג","f":"וולף","k":"פרשבורג","dp":"תקכח - כה סיון","b":"מחכמי פרשבורג."},{"i":2370,"n":"אופנהיים, צבי הירש","b":"רב בהילדסהיים-ת\"ק"},{"i":2371,"n":"אופנהיים, צבי הירש מלאפוש","b":"רבה של הקהילה הניאולוגית בלאפוש, ורב ראשי של חבל בנאנאט - וגם אחריו נשאו רבני לאגוש תואר רב ראשי."},{"i":2372,"n":"אופנהיים, צבי יעקב מקלם","k":"בעל צבי גאון יעקב","bt":"תריד-טו","bp":"יאקובובה","dt":"תרפו - כו שבט","b":"רב בציטוביאן-תרמא, ר\"מ אצל ר שמחה זיסל זיו בישיבת המוסר בקלם, רב בקלם-תרמד מעל 40 שנה על מקום ר אליעזר גורדון שעבר לטלז וחתנו ר קלמן מביינושביץ הי\"ד על מקומו אחריו. וחתנו השני ר משה בנימין טומשוב בעל \"אבני שהם\". פרסם מאמרים ב\"יגדיל תורה\" - סלוצק-בוברויסק תרסט."},{"i":2373,"n":"אופנהיים, קופל מפרשבורג","b":"מחכמי פרשבורג, חתם-תקכח על תקנות החברא קדישא."},{"i":2374,"n":"אופנהיים, קלמן מפפד\"מ","f":"מרדכי","dt":"תקנה - טז אדר","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":2375,"n":"אופנהיים, שלמה מפפד\"מ","b":"מחכמי פפד\"מ, היה חבר בועדה בראשות ר מיכאל שפייאר שניסחה את תקנות הקהילה-תקמד."},{"i":2376,"n":"אופנהיים, שמואל מוינה","b":"ספק החצר בוינה. בנו ר דניאל משה מוינה ופרשבורג. סייע לשיירת ר יהודה החסיד בדרכם לארץ."},{"i":2377,"n":"אופנהיים, שמואל מפאפא","f":"אריה ליב-דרך עולם הנ","b":"מחכמי פאפא. הו\"ל תרי\"ג מצוות בדרך שיר לר יונתן איבשיץ - לבוב תקעד."},{"i":2378,"n":"אופנהיים, שמעון וולף מורמייזא","b":"מגדולי חכמי אשכנז,רב בוורמס-שפ\"ו"},{"i":2379,"n":"אופנהיים, שמעון מפעסט","f":"דוד - נחלת דוד","k":"בעל הר הכרמל","bt":"תקיג","dt":"תריא - כב שבט","b":"תלמיד ר בנימין וולף בוסקוביץ, הנודע ביהודה (והיה מלמד לנכדו - ר יוסף בן שמואל לנדא). דומ\"צ בקיצע, ראב\"ד בפעסט-תקפ כ-50 שנה. חיבר גם \"נזר הקדש\" - אובן תקצא, \"עמוד השחר\". אחיו - ר צבי הירש מטימישואר בעל \"עיני הדעת\"."},{"i":2380,"n":"אופנהיים, שמעון מפרשבורג","f":"לאזיל מפרשבורג","k":"בעל שם משמעון","bt":"תקנא","bp":"פרשבורג","dt":"תריב - ד כסלו","dp":"פרשבורג","b":"תלמיד החת\"ס. חתן הגביר ר שמואל הרצפלד מבאניהאד, וכיהן כדיין בקיצע הסמוכה ובפרשבורג על מקום ר מרדכי טאסק-תקצז - אצל החת\"ס ואצל בנו הכת\"ס."},{"i":2381,"n":"אופנהיים, תיאודור מפפד\"מ","b":"פרנס ומראשי קהילת פפד\"מ-תך."},{"i":2382,"n":"אופנהיים-קרומוניא, שמעון","b":"נכד ר ישכר דב מבודפשט. תלמיד בעל נודע ביהודה. דיין וראב\"ד בבודפשט כ-50 שנה, חתם-תקפה עם ר ישראל והרמן ור עזריאל בריל."},{"i":2383,"n":"אוקונובסקי, משה","dt":"תשג","b":"ר\"מ בישיבת חכמי לובלין"},{"i":2384,"n":"אוקס, דוד בונם מבוזנוב","f":"אברהם משה","b":"נכד התבואות שור. חסיד צורטקוב בבוזנוב. בניו - חסידי צורטקוב: ר ליב ממיקוליניץ, ר קלונימוס קלמן, ר שלמה מטרנופול, ר מנדל מלמברג חתנו של ר נחום פרייס - נספו בשואה."},{"i":2385,"n":"אוקס, דוד בונם מטורונטו","f":"קלונימוס קלמן","bt":"תרסה","bp":"הרבוזוב-פלך זבורוב","dt":"תשמה","b":"מצאצאי בעל \"תבואות שור\". חתן ר שמואל יצחק רייך. למד בוינה אצל ה\"מחזה אברהם\". תלמיד ר אברהם מנחם שטינברג מברודי, ר בן ציון כץ מטשרנוביץ, נסמך מרבותיו ומאת: ר אהרן בקשט משאוועל. ד\"ר לפילוסופיה ודיין אצל ר יוסף באבד בוינה. רב קהל הרב הורביץ שעבר לסטניסלב-תרצה, עבר למנצסטר-תרצט וכיהן כרב קהלת בית ישראל, ומנהל בית המדרש למורים של קרן התורה. רב בטורונטו-תשה על מקום ר יעקב קמנצקי (או על מקום ר יהודה ליב גרויברט) וראש ישיבה. בנו ר מרדכי רב על מקומו. חיבר חדושים בתורה, ספר לתולדות הריפורמים בגרמניה."},{"i":2386,"n":"אוקס, קלונימוס קלמן מזבורוב","f":"דוד בונם","dt":"תשב","b":"בעל בנק בזבורוב. חתן ר אפרים צבי פרייס. עבר לאנטורפן, נספה בשואה."},{"i":2387,"n":"אור בונה, יהודה","b":"מחכמי ספרד בדורם של הר\"ן והריטב\"א,חיבר חידושים לש\"ס"},{"i":2388,"n":"אור זרוע, חיים מוינה","f":"יצחק - אור זרוע","k":"בעל אור זרוע הקצר","b":"רב בניישטט-וינה, קולוניא-שנת ה'ס'. חיבר קיצור לספר אביו - אור זרוע, תשובותיו נדפסו בלייפציג תרך."},{"i":2389,"n":"אור שרגא, אור מפרס","f":"משה","b":"רב ביזד-פרס, חתם-תרצד על רבני הקהלה."},{"i":2390,"n":"אור שרגא, יוסף חיים מירושלים","dt":"תשי","b":"רב בטהרן-פרס, עלה לירושלים-תרפח. בנו - ר יעקב."},{"i":2391,"n":"אור שרגא, יעקב","k":"בעל רשפי אש","b":"רב בזלאטאווי-ת\"ק"},{"i":2392,"n":"אור שרגא, יצחק מיזד-פרס","f":"משה","b":"נכד ר מולא אור שרגא. רב ביזד, חתם על כתובות בתקצט-תרכה. בנו - ר משה מיזד."},{"i":2393,"n":"אור שרגא, מולא מיזד-פרס","f":"שמואל","dt":"תקנד - כח חשון","dp":"יזד","b":"רב באיספהן אחד משלשה רבנים שניצלו שם ממות (לאחר ששבעה רבנים נהרגו עק\"ה), הגיע ליזד (חברו מולא דרויש הגיע לשיראז, ומולא משה לכשאן). רב ומנהיג הקהילה-תקמב וצאצאיו אחיו במשך כ-200 שנה. היה קשור גם עם קהילת משהד, ומינה את חכם סימן טוב מלמד לרב במשהד. הפך את יזד לעיר תורה עד שנקראה \"ירושלים הקטנה\" ופרסית \"דאר אל עיבאראת\" (=עיר האמונה). בניו - ר משה ור שמואל, ונכדו ר יצחק - רב ביזד."},{"i":2394,"n":"אור שרגא, משה מיזד-פרס","f":"יצחק מיזד","b":"רב ביזד-פרס-תרן."},{"i":2395,"n":"אור שרגא, משה מפרס","f":"מולא אור שרגא","b":"רב ביזד-פרס?, בנו - ר יצחק."},{"i":2396,"n":"אור שרגא, נחום מניישטט","f":"יעקב אור שרגא","k":"בעל זכרון מנחם","dt":"תקלג - כג סיון","b":"רב בניישטט"},{"i":2397,"n":"אור שרגא, פיבש מירושלים","dt":"תל - אחרי","b":"תלמיד ר מאיר מלובלין-המהר\"ם מלובלין. מחכמי האשכנזים בירושלים-תטו. בזמן שעבר בבודון-תטו תיקן להם תקנות. נזכר ב\"קורא הדורות\". בשליחות במצרים-תכח וחתם אז על כת\"י מר יהודה עבאס. ראה גם: ר אורי שרגא פיבש מקראקא וירושלים."},{"i":2398,"n":"אוראי, אברהם מאלגיר","f":"יצחק","bt":"ד'תרץ","dt":"ד'תשס","b":"רב בתאהרת(=תייארת)-אלגיר. היה בקשרי מכתבים עם גאוני בבל."},{"i":2399,"n":"אורבינו, יוסף ברוך ממנטובה","k":"בעל מזמור שיר","b":"רב במנטובה. חתן ר נתנאל טרבוט, וקרובו של בעל \"באר עשק\" שהביא ממנו בספרו. חיבר \"שיר ידידות, מזמור שיר ו\"בנות השיר\" - מנטובה. תרגם חבור על התכונה לעברית - בכת\"י."},{"i":2400,"n":"אורבינו, יצחק שבתי חיים","bt":"תלה","dt":"תקכד","b":"תלמיד הרב\"ך. חברו של ר ישעיה בסאן. רב בפיזארו."},{"i":2401,"n":"אורבינו, שלמה מאיטליה","f":"אברהם בן שמואל","k":"בעל אהל מועד","b":"רב באורבינו-איטליה. חיבר \"יפה נוף\", \"אהל מועד\" על המילים הנרדפות, הרי\"ב קאנטון חיבר עליו קונטרס \"יתד האהל\"."},{"i":2402,"n":"אורבך מרגליות, אביגדור מחנטשין","f":"מנחם אורבך","b":"חתן ר משה צבי הירש מייזלש מזולקווא. רב בחנטשין-תק. בניו: ר יחזקאל מאוסטרובצא, ר יוסף אוירבך מטרניגרד וחנטשין בעל \"תבנית אות יוסף\", ר צבי הירש מהילדסהיים, ר משה נפתלי הירץ לנדא מוישניצא."},{"i":2403,"n":"אורגלר שמואל בן יוסף","bt":"1645","dt":"ה'תס 1700","bk":[["עולת תמיד",""]]},{"i":2404,"n":"אורגלר, חיים מקראקא","dt":"תמט - טו חשון","b":"מו\"צ בקראקא. נכדו-בן בתו - ר שמואל מאלטונא."},{"i":2405,"n":"אורגלר, שמואל מאלטונא","f":"יוסף","k":"בעל עולת תמיד","dt":"תס - א-ג אדר","dp":"אלטונא","b":"נכד-אבי אמו ר חיים אורגלר מקראקא. מגדולי חכמי דורו, דיין בקראקא, אלטונא-תלד. נזכר ב\"זכרונות גליקל\". חיבר \"עולת תמיד\" ונזכר ב\"מגן אברהם\" שהחשיבו.","bk":[["עולת שבת – או\"ח חלק ב'",""],["עולת תמיד – או\"ח ח\"א",""]]},{"i":2406,"n":"אורדמן, ישראל","b":"פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":2407,"n":"אורדנטליך, חיים גרשון","b":"רב בטלקי-תר\"מ"},{"i":2408,"n":"אורדנטליך, חיים גרשון מטלגד","bt":"[תרי]","bp":"כפר איקלוד-ליד סאמוש","dt":"תרצ.. - בערך","dp":"ירושלים","b":"תלמיד ר שמואל ארנפלד בעל \"חתן סופר\". רב בטלגד-ליד גרוסורדין. עלה לירושלים."},{"i":2409,"n":"אורה בואינה, יונה מספרד ושלוני","b":"חזן בספרד, לאחר הגירוש חזן בשלוניקי."},{"i":2410,"n":"אורה בואינה, יוסף מספרד","b":"מגדולי חכמי דורו,רב הכולל בנבארה-ק\"נ"},{"i":2411,"n":"אורוביו, יצחק די קשטרו מספרד","b":"מאנוסי פורטוגל ונקרא שמו בלטזר, עבר לספרד ולמד רפואה, ולימד פילוסופיה בסביליה וסלמנקה, עבר לצרפת והיה רופא. התגייר ועבר לאמשטרדם. הדפיס חבורים שונים להוכיח אמיתות התורה (די רוסי)."},{"i":2412,"n":"אורזל, נתן מפפד\"מ","b":"מראשי קהילת פפד\"מ, ומבין 12 מחברי תקנות הקהילה-תקיג."},{"i":2413,"n":"אורטאש, אברהם מקושטא","b":"שוחט בקושטא-תקס בערך. נפטר ללא ילדים, ונזכר אצל ר אליעזר די טולידו בענין חזקת השחיטה."},{"i":2414,"n":"אורטינברג, דוד מברדיטשוב","k":"בעל תהלה לדוד","bt":"1840","dt":"תרע - כד אדר","b":"תלמיד ר ישראל מרוזין ובנו ר אברהם יעקב מסדיגורא ונכדו ר יצחק מבויאן. מגדולי ההלכה בדורו, ראב\"ד בברדיטשוב.","bk":[["תהילה לדוד [תוכן העניינים]","מפרשי שו\"ע"],["תהילה לדוד [הקדמות]","מפרשי שו\"ע"],["תהילה לדוד","מפרשי שו\"ע"],["תהילה לדוד [חלק ג]","מפרשי שו\"ע"],["שהם וישפה","מפרשי רמב\"ם"],["שהם וישפה – רמב\"ם",""],["תהלה לדוד – שו\"ע",""],["שהם וישפה – רמב\"ם , תהלה לדוד - שו\"ע",""]]},{"i":2415,"n":"אורטינברג, ישראל מברדיטשוב","f":"דוד מברדיטשוב","dt":"תרצב - ב אייר","b":"רב בברדיטשוב, חתם- על כתב סמיכה למנקר (ר דב בעריש קמינסקי) יחד עם ר יחיאל מיכל רושזהאן."},{"i":2416,"n":"אורטנר, אלתר משה שמואל מהינביב","f":"דב בריש מהיבניב","bt":"תרסו","bp":"היבניב","b":"חסיד בלז. חתן ר מרדכי הכהן מנדל. עלה לארץ-תשא והקים בית דפוס בתל אביב."},{"i":2417,"n":"אורטנר, דב בריש מהיבניב","f":"מאיר ישראל איסר","bt":"תרמג","bp":"היבניב","b":"חסיד בלז. חתן ר יוסף הלוי רבהון מנמירוב. עבר לברלין והקים בית דפוס-תרף. עלה לארץ-תרצג והעלה אתו את בית הדפוס. נכדו ר נתן אורטנר הדפיס לזכרו \"דבר חן\" תל אביב תשכג."},{"i":2418,"n":"אורטנר, ישראל מהיבניב","b":"מחשובי חסידי בלז. בדחן בחתונות. נקרא היבניבר (על שם מקומו)."},{"i":2419,"n":"אורטנר, נתן","f":"אלתר משה שמואל","k":"בעל דבר חן","b":"רבה של לוד. חיבר \"דבר חן\" תל אביב תשכג, ועוד."},{"i":2420,"n":"אורי","f":"אליקים בן יהודה","b":"מחכמי אשכנז-ה'א. בניו: ר יחיאל אבי הרא\"ש, ר אליעזר - שנזכר בספר הראבי\"ה."},{"i":2421,"n":"אורי בן פינחס מסטרליסק","bt":"1740","dt":"ה'תקפו 1826","bk":[["אמרי קדוש השלם",""]]},{"i":2422,"n":"אורי הלוי","f":"יואל בן יצחק","dt":"ד'תתקעז","dp":"קולוניא(=קלן)","b":"אחיו של ר יואל - ראבי\"ה. נהרג עק\"ה. חיבר פיוטים ובהם: \"באתי לפניך מלכי וצורי\". לפיוטיו היה נגון קבוע לפנים - ונשכח במהלך הדורות."},{"i":2423,"n":"אורי הלוי ממרוקו","f":"דוד","b":"מחכמי מרוקו. הניח חבור בענין כתיבת סת\"ם, והביא מתורת ר שלמה אבוהב."},{"i":2424,"n":"אורי יצחק איזיק מירושלים","f":"אבא קדיש","dt":"תרכז","dp":"ירושלים","b":"חתן ר שמואל פוזיץ. חיבר ספר \"מאורות בית יצחק\" וארשא תרטו וירושלים תרכו, היה בן בנו של ר אהרן אבד נוברדוק, נצר לבעל סדר הדורות. היה מתומכי ר\"מ יאניווער בזמן המחלוקת בירושלים - נזכר ב\"אמת ומשפט\"."},{"i":2425,"n":"אורי ליפמן הכהן מאוסטרהא","f":"יעקב דוד","dt":"תקמ - כב אד\"א","dp":"אוסטרהא","b":"מחכמי אוסטרהא. נזכר בצוואת ר דוד הלפרין מאוסטרהא שציוה לתת לקרובי ר אורי 30 זהובים."},{"i":2426,"n":"אורי מאשכנז","b":"מחכמי אשכנז-ד'תתק. תלמיד וחתן הראב\"ן ונזכר בשו\"ת ראב\"ן."},{"i":2427,"n":"אורי מאשכנז","b":"מחכמי אשכנז. חיבר פירוש למחזור בכת\"י. אחיינו של ר מאיר ש\"ץ בן יצחק מוורמייזא."},{"i":2428,"n":"אורי מבונא","k":"חתן הראב\"ן","dt":"ד'תתקעו","b":"מגולי הראשונים רב בבונא"},{"i":2429,"n":"אורי מביאלה(=ביעל) וצפת","f":"שמעון","k":"הו\"ל יחוס האבות","bp":"פולין","b":"מחכמי אשכנז, עלה לצפת בזמן ר יוסף קארו. העתיק בצפת-שכד אגרת על מקום קברות הקדמונים בארץ, (האגרת נכתבה ב-רצז), נדפסה בשם \"יחוס האבות\" הידלברג 1659, ונדפסה בקיצור אצל כרמולי ב\"אלה המסעות\". חיבר גם לוח לארבעים שנה - ונציה שלה."},{"i":2430,"n":"אורי מדרויא-ליטא","f":"יהודה ליב","b":"מחכמי ליטא. חיבר \"בן אורי\" זולקווא-תפה."},{"i":2431,"n":"אורי מויזניץ","b":"רב בווישניץ-תר\"מ"},{"i":2432,"n":"אורי מוילנא","f":"יעקב גבריאל","b":"מחכמי וילנא-תקמט. מחותן עם הגביר ר אשר גינצבורג."},{"i":2433,"n":"אורי מוילנא וארץ ישראל","b":"עלה לארץ מליטא-תקל בערך, עליו ב\"אור נערב\"."},{"i":2434,"n":"אורי מזולקוא","b":"רב בזלקווא"},{"i":2435,"n":"אורי מסאהל","b":"רב בסאהל-תרלו."},{"i":2436,"n":"אורי מסטרטין","f":"אברהם ברנדוויין","k":"אדמור מסטרטין","b":"אדמו\"ר בסטרטין"},{"i":2437,"n":"אורי מענגבורגו","f":"רפאל","b":"חיבר סליחה על גזרות קהלות ישראל \"אורי וישעי אליך אזעק\" - מזכיר את ר יום טוב ליפמן הלר בברכת נר\"ו - כנראה חי בזמנו - שנות ה-ש'-ת'."},{"i":2438,"n":"אורי מפודולי ואיוד","b":"חתן ר יחיאל מיכל הגר מסטרוזניץ. רב בנאג'-אניד(=איוד)."},{"i":2439,"n":"אורי מפרובנס","f":"משלם","b":"מחכמי פרובנס."},{"i":2440,"n":"אורי מקאמאי","f":"אריה ליב - דברי אריה","b":"נכד-אבי אמו ר שמחה רפפורט מדובנא ולובלין. בניו: ר יצחק רבינוביץ, ר אריה ליב מחויאדאן (אצל מרקוביץ-קידאן ר צבי הירש מקאמאי), ר משה בעל \"אמרי משה\". (ב\"דעת קדושים\" בתולדות משפחת רפפורט נכתב בטעות שהיה לו בן אחד - ובאמת היו לו חמשה בנים)."},{"i":2441,"n":"אורי מקרוז'","b":"רב בקרוז-תקן בערך. מחותנו של ר אליהו בן מאיר מקרוז' - שהיה גיסו של הגר\"א."},{"i":2442,"n":"אורי פיבוש בר\"ה מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":2443,"n":"אורי פיבוש כץ ממיץ","f":"אלעזר ליברמן הכהן","k":"בעל הלכה ברורה","b":"אב\"ד מיץ. חיבר \"הלכה ברורה\" - מיץ תקנג."},{"i":2444,"n":"אורי פיבש (פיבל) מירושלים","b":"דרשן ירושלמי,מחכמי ירושלים-שנ. בשליחות בקראקא וישב שם כ-40 שנה. נזכר ב\"איתן האזרחי\"."},{"i":2445,"n":"אורי פיבש מברסלוי","f":"אריה ליב","k":"בעל וארטערבוך","b":"חיבר \"מדרש מלים\", \"קרואי מועד\", \"לקוטי אורות\" ובתוכו - \"פתגם המלך\"."},{"i":2446,"n":"אורי שבתי דיין מירושלים","f":"חיים","dp":"ירושלים?","b":"דיין בירושלים-תקצח, חתן ר יוסף זונדל סלנט, חתם על כתב שליחות ר אברהם מאיר בן ירמיהו בשנת תקצז, ועל תקנת התכשיטים בשנת תריב. נמנה על מייסדי הת\"ת בחורבת ר יהודה החסיד. בנו - ר אברהם הסופר המכונה \"רבי אברהם ר שבתי'לס\"."},{"i":2447,"n":"אורי שרגא כץ מצפת","f":"מנחם","b":"מחכמי צפת, חתם בשנת שפא על ההזמנה לר ישכר בר איילינבורג"},{"i":2448,"n":"אורי שרגא מקראקא","dt":"תרז - יז אב","b":"דיין בקראקא"},{"i":2449,"n":"אורי שרגא פיבוש מקראקא","dt":"תנז-תפ (תכנהה)","dp":"קראקא","b":"תלמידו של ר מאיר מלובלין, בשנת תט יצא בדרכו לארץ, בשנת תטו עבר בעיר בודון, ושם הפצירו בו להישאר כרב ולתקן להם תקנות, הוא נעתר לבקשתם ותיקן להם תקנות שעליהם הסכימו חכמי בילוגרד וסופיה, ואחת התקנות שלא לקבל רב שיש לו קרובים שם, על תקנה זו התעוררה מחלוקת, ויש חליפת מכתבים בינו לר אפרים מוילנא, בשנת תיז חתם בוינה על תעודה ממנה משמע שהיה רב גם שם, בשנת תכח היה בירושלים ונתמנה לראש העדה, היה בשליחות במצרים וחתם על פסקים של ר יהודה עבאס. בספר \"איתן האזרחי\" מובא דרשה שאמר ר אורי בשם הר\"מ אלשאקר. לדברי יערי היה שליח ארץ ישראל בשם זה בשנת שע בקראקא וכנראה שהיו שניים בשם זה. ראה גם: אור שרגא, פיבש."},{"i":2450,"n":"אורי שרגא פיבל מבלשביץ","f":"שלמה","k":"אשפ\"ה","b":"תלמיד המגיד מזלוטשוב. מצאצאיו ר שמעון הורודנר מגליגור."},{"i":2451,"n":"אורי שרגא פיבל מלובלין","f":"לאזר יודליש מקראקא","dt":"תג - כא אדר","dp":"לובלין","b":"ממנהיגי קהילת לובלין."},{"i":2452,"n":"אורי שרגא פיבל מליסא ושטמפן","b":"דומ\"צ בליסא, רב בשטאמפן-ליד פרשבורג-תקל? (בקורות בתינו תאריך פטירתו לפני תצב). בנו - ר ישכר דב מפרשבורג בעל \"באר טוב\"."},{"i":2453,"n":"אורי, חיים אברהם משלוניקי","dt":"תש..","b":"חזן להלויות מתים בשלוניקי. נספה בשואה."},{"i":2454,"n":"אורי, שמעון מצפת","k":"בעל ספר הכוונות","b":"מתלמידי הארי בצפת, אחיו של ר ישראל - תלמיד הארי. ממקובלי צפת, חיבר ספרי קבלה ובהם ספר כוונות, ספר ליקוטים, וספר דרושים."},{"i":2455,"n":"אוריאטו, אברהם מצפת","b":"מחכמי צפת-שן, חתם עם ר יוסף קארו והמבי\"ט-שך על תשובה ונזכר בשו\"ת ר\"י דלטאש, וחתם באגרת אל רבני צפת-שלא ונזכר ב\"נשמת חיים\"."},{"i":2456,"n":"אוריאל אליה משלוניקי","dt":"תיט - כא כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":2457,"n":"אוריאל מאיטליה","b":"נהרג עק\"ה בעיר אוריס-איטליה-ד'תרפה - אחד מעשרה צדיקים שנהרגו שם כמובא ב\"תחכמוני\" לר שבתי דנולי."},{"i":2458,"n":"אוריגה, אברהם ממצרים","b":"רב במצרים-שנות ה-ת'."},{"i":2459,"n":"אוריול, אברהם","dp":"דאד(מרוקו)","b":"שד\"ר מא\"י, הגיע לסאלי (אוריור)"},{"i":2460,"n":"אוריזה, אברהם","b":"מגדולי רבני מצרים-ת\"כ"},{"i":2461,"n":"אורינסון, יוסף חיים מז'יים","f":"יעקב הלוי","bt":"תרמ-א","dt":"תרצה - כג חשון","b":"רב ביעלנא, זיים-פלך קובנא-תרסג, שוואדאסץ(=שוויאדסאסץ)-פלך קובנא."},{"i":2462,"n":"אוריסה, שמואל משלוניקי","b":"דיין בשלוניקי-שנה."},{"i":2463,"n":"אורלוביץ, זליג מראקישוק","bt":"תרנח","dt":"תשא - אב","b":"רבה האחרון של ראקישוק. נספה בשואה."},{"i":2464,"n":"אורליאון, יהודה ליב מוארשא","dp":"תשד","b":"בן למשפחת חסידי גור. תלמיד ר נתן בירנבוים, נשיאה הראשון של \"פועלי אגודת ישראל\", ממיסדי הוצאת \"ישורון\". מנהל \"בית יעקב\" בוארשא, מנהל הסמינר בקראקא, בזמן השואה ניהל בתי ספר בגיטו. נספה בשואה."},{"i":2465,"n":"אורלינסקי צבי הירש בן יצחק","bt":"1864","dt":"ה'תש 1940","bk":[["דרשות מהרצה\"א",""]]},{"i":2466,"n":"אורלנדר, עוזר מסמבור","f":"שלמה","bt":"תרע","bp":"סמבור","dt":"תשנג","b":"חסיד בלז. תלמיד ר דוד הורביץ מסטניסלב, ורנ\"ה בומבך מסמבור. ניצל מהשואה, פעל במחנה פירט לשיקום העקורים. עבר לארה\"ב-תשי וכיהן כשו\"ב בפיטסבורג."},{"i":2467,"n":"אורלנסקי אהרן","bt":"1854","dt":"ה'תרע 1910","bk":[["תקות אהרן",""]]},{"i":2468,"n":"אורלנסקי, אברהם יעקב הכהן","f":"אהרן","bt":"תרלט","bp":"ביאליסטוק","dt":"תרפט","dp":"חברון","b":"עלה בגיל 4, למד בישיבת תורת חיים, היה רב בפתח תקוה, בזכרון יעקב - תרעט ובחברון. כתב ספרים שנשארו בכתי, הוציא קונטרס תקוות אהרן. עסק בפיענוח תשובת הגאונים מערבית. פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ, \"שערי ציון\" - ירושלים תרפא."},{"i":2469,"n":"אורלנסקי, אהרן הכהן","f":"שבתי","bt":"תריד","bp":"ביאליסטוק","dt":"תרעא","dp":"פתח תקוה","b":"רב בביאליסטוק, עלה לארץ בשנת תרמד והתמנה לרב בפתח תקוה בהמלצת ר מאיר שמחה מדוינסק, ספרו \"תקות אהרן\" נדפס על ידי בנו (ירושלים תרעג)"},{"i":2470,"n":"אורלנסקי, צבי הירש מקרינאק","k":"בעל דרשות מהרצ\"א","b":"רב בקרינאק, שטוצין, ניו יורק-תרפא."},{"i":2471,"n":"אורלנסקי, שמואל אליהו מקמניץ","b":"מתורתו ב\"תורה אור\" - שנחאי תשו."},{"i":2472,"n":"אורנגיל, אליהו","f":"גרשון מפוזנא","b":"רב בלבוב"},{"i":2473,"n":"אורנר, זאב יהודה מלודז","b":"תלמיד ר מנחם מנדל מקוצק."},{"i":2474,"n":"אורנר, חנוך הניך מלסקרוב","f":"זאב יהודה","bt":"תרלב","dt":"תשג","b":"תלמיד האדמור ר אברהם מסוכטשוב, ר יהושע מזשארץ בעל \"חומת יהושע\". רב בלאסקראב(=לסקרוב)-פלך שדליץ-תרס."},{"i":2475,"n":"אורנר, יעקב מנאשלסק","f":"זאב יהודה","k":"בעל טהרת אזוב","bt":"תרכז","b":"מצאצאי ר יחיאל מנמרוב הי\"ד (נהרג בפרעות תח). תלמיד חותנו זקנו - ר זאב נחום מביאלא בעל \"אגודת אזוב\", ר אברהם מסוכטשוב בעל \"אגלי טל\", ר אברהם ליב מברוק בעל \"מלאת אבן\", רב במאדזיץ(=איוואנגרד)-פלך לובלין-תרנא, נאשלסק(=נאשעלסק)-פלך וארשא-תרנו. פרסם מאמרים ב\"שערי תורה\" - וארשא תרסג. הו\"ל \"נפש יהונתן\" לר יונתן איבשיץ עם ביאור ממנו בשם \"ציון לנפש\", \"אגודת אזוב\" לחותנו זקנו עם הוספות ממנו בשם \"טהרת אזוב\" ובו גם לתולדות משפחתו. חיבר \"אמרי היהודי\" לתורתו של היהודי מפרשיסחא עם הוספות וביאורים - בכת\"י, ועוד. אחיו של ר חנוך הניך מלאסקרוב."},{"i":2476,"n":"אורנשטין, אברהם","k":"בעל הנשיאות בישראל","dt":"תשל","b":"רב בתל-אביב"},{"i":2477,"n":"אורנשטין, אהרן יצחק מוינה","f":"נתן","dt":"תקד - ז אלול","b":"גביר מראשי קהלת וינה. מבניו: ר נתן אדם בעל תואר בארון."},{"i":2478,"n":"אורנשטין, אורי מצפת","f":"משה בן מרדכי","bt":"תקסו","dt":"תרלט - יז אדר","dp":"ירושלים","b":"חתן ר יצחק ברוכין אב\"ד קרלין בעל \"קרן אורה\", הפך לחסיד חבד, עלה לצפת-תקצב והיה תלמיד חבר של ר אברהם אוירבוך מאבריטש. לאחר שאיבד רבים מבי משפחתו במחלות ובפרעות, עבר לירושלים-תרא ועמד בראש כולל חבד שם, נסע בשליחות וחזר לירושלים. בנו - ר ישעיה, ונכדו ר יעקב."},{"i":2479,"n":"אורנשטין, ברוך משה מגלוגוב","b":"רב בגלוגוב-תרמא."},{"i":2480,"n":"אורנשטין, דוד אלעזר סופר","f":"אברהם יהושע שפירא","k":"בעל יסוד הדעת","b":"מצאצאי המגיד מקוזניץ, ור אברהם יהושע השל מאפטא, ובנו של האדמור ממוגלונציה. חיבר גם \"מפענח נעלמים\", \"אור חדש\"."},{"i":2481,"n":"אורנשטין, זלמן","b":"גביר מפורסם. חתן ר דב בר מלחוביץ, ואשתו היתה הנגידה הצדקנית מרת אסתר - נכד ר יעקב יוסף מפולנאה-נכד רב ייב\"י."},{"i":2482,"n":"אורנשטין, חיים אברהם (בבלוי)","f":"מרדכי בבלוי","k":"בעל דברי אברהם","bt":"תקעב-ד","bp":"פרשבורג","dt":"תרלא - יד תמוז","dp":"ברדיוב","b":"תלמיד החת\"ס, ור צבי הרש הלר חריף מאויבן. חסיד הדברי חיים מצאנז. חתן ר נתן אליהו עהרמן מאירשא ועבר לשם. רב בטיסא-בעא-תר, ברדיוב(=ברטפלד)-תריח ור משה הלברשטט על מקומו אחריו. מבניו: ר ישראל מרדכי מקרסטור(=קרסטיר), הגביר ר משה נתן מזמיגרוד, ר מנחם מסטרופקוב. חתנו ר מנחם אהרן אדלר מירושלים.","bk":[["ויקרא אברהם","שו\"ת - אחרונים"]]},{"i":2483,"n":"אורנשטין, חיים אברהם מברדיוב","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח."},{"i":2484,"n":"אורנשטין, יהודה ליביש מבלשביץ","f":"נפתלי הרץ","k":"בעל שות מהריל","r":"אב\"ד פלאטיטשאן","bt":"תקעד","dt":"תרמט - כא אדר","b":"ממשפחתו של השר שלום מבלז, ונכדו של ה\"תבואות שור\". רב בבלשביץ, פודהייץ, חורוסטקוב, פולטושאן-תרכה. תלמיד ר מאיר מפרימישלן, רוזין-סדיגורא. עלה לירושלים-תרלד וכיהן כראב\"ד בבית הדין החסידי הראשון, עמד לצדו של ר עקיבא יוסף שלזינגר בזמן המחלוקת כנגדו. חיבר שו\"ת \"מהרי\"ל לא אבוש\" (נקרא גם \"טל ירושלם\") ירושלים תרלג. חתנו ר חנניה יוסף הלפרין בן יחיאל מיכל מהאליטש - עלה עמו לארץ.","bk":[["טל ירושלים",""],["שו\"ת מהרי\"ל",""]]},{"i":2485,"n":"אורנשטין, יעקב מירושלים","f":"ישעיה","k":"בעל עמק המלך","bt":"תריט","bp":"ירושלים","dt":"תרסח","dp":"ירושלים","b":"תלמיד המהרי\"ל דיסקין בירושלים, מחכמי ירושלים, ראש ישיבת \"אהל משה\", ודרשן גדול, היה מלומד במתמטיקה ומדעים והשתמש בידע לבירור שאלות הלכתיות. חיבר \"עמק המלך\" ירושלים תרן, \"כל המצוה\" ירושלים תרסב, ועוד. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז. עורך: \"תורה מציון\" - ירושלים תרנה-תרסה - וגם הספיד שם את רבו המהרי\"ל."},{"i":2486,"n":"אורנשטין, יעקב משלם מירוסלב","f":"מרדכי זאב מלבוב","k":"בעל ישועות יעקב","bt":"תקלה","bp":"סטנוב","dt":"תקצט - כה אב","dp":"לבוב","b":"חתן ר צבי הירש ואהל המכונה ר הירש מייטשיס. רב בירוסלב-תקס, זולקווא, לבוב-תקסה. הסכים על \"שבט יהודה\" זולקוא תקסב, \"דרך חיים\" זולקוא תקסב, \"תקון השלחן\" זולקוא תקסד, \"טהרות הקדש\" זולקוא תקסד, ועוד. חיבר \"ישועות יעקב\" זולקווא תקסט. מתורתו ב\"הפלס\" - ברלין תרסא-תרסה. נספד ב\"אבל משה\" לר שלמה קלוגר - וארשא תרג. (אצל ריבלין-תוח\"י מופיע חכם בשם ר יעקב משלם מלבוב שנפטר בירושלים בערך בשנים אלו?)"},{"i":2487,"n":"אורנשטין, יצחק אביגדור מירושלי","bt":"תרנד","b":"עק\"ה,רב הכותל בירושלים העתיקה"},{"i":2488,"n":"אורנשטין, יצחק ראובן הכהן","k":"בעל חרוזי פנינים","dp":"לונדון","b":"נכדו של ר אורי ברי הימלשטין, תלמידו של ר שמעון סופר. רב בקראקא, ודיין בלונדון-תרל. חיבר \"חרוזי פנינים\" קראקא תרנז."},{"i":2489,"n":"אורנשטין, ישעיה מירושלים","f":"אורי","bt":"תקצו","bp":"צפת","dt":"תרסט","dp":"ירושלים","b":"חתן בעל \"קרן אורה\". מחכמי ירושלים, תלמיד ר משה יהודה ליב מקוטנא, עמד בראש כולל חב\"ד ועסק רבות בצרכי צבור. בשנת תרנד יסד את ישיבת \"אהל משה\" יחד עם בנו ר יעקב, והמהרי\"ל דיסקין היה מלמד שם."},{"i":2490,"n":"אורנשטין, ישראל אברהם אבא","f":"אפרים","bt":"תרל","dt":"תרצ - טו שבט","b":"רב במיכל-פוליא-תרנד, טשארנא-אוסטרוב-פודוליה."},{"i":2491,"n":"אורנשטין, ישראל מרדכי מקרסטיר","f":"חיים אברהם מברדיוב","dt":"תרמה - כא ניסן","b":"רב בקערעסטור(=קרעסטיר)."},{"i":2492,"n":"אורנשטין, ליבוש מפודהייץ","b":"מחכמי פודהייץ, תשובות אליו ב\"טוב טעם ודעת\"."},{"i":2493,"n":"אורנשטין, מאיר אורי מירושלים","b":"חתם עם ראיש מוסדות וממוני הכולל בירושלים-תרע-ף בערך."},{"i":2494,"n":"אורנשטין, מנחם מסטרופקוב","f":"חיים אברהם מברדיוב","dt":"תרץ - ח אדר","b":"רב בסטרופקוב."},{"i":2495,"n":"אורנשטין, מרדכי","b":"חתן ר אברהם יהושע השל מאפטא. בנו ר יעקב יואל חתן ר משה אליקים בריעה מקוזניץ. חתנו ר פנחס זאב בן ר אריה יהודה ליב מוואלטשיסק."},{"i":2496,"n":"אורנשטין, מרדכי זאב הסבא-הגדול","f":"משה יוסק'ס מזולקוא","bt":"תצה","bp":"זולקווא","dt":"תקמז - ב חשון","dp":"למברג","b":"שינה שמו לאורנשטין כדי לקבל רשות לגור בלבוב. חתן ר שאול חריף, ובזיוו\"ש חתן ר אליקים גצל. אב\"ד קמינקא-תקיד, רב בימפולי והתקרב לחסידות בהשפעת בעל ההפלאה שגר בעירו. רב בסטנוב-תקלב, רב בלבוב-תקלח, סטנוב, רב המדינה בגליציה. הסכים על \"הר הכרמל\"-תקמב, \"קרבן ראשית\"-תקלח, ועוד. אחד מבניו היה ר אליקום אריה ליב הידוע מפרשת הגט מברודי, בן נוסף ר יעקב משולם בעל \"ישועות יעקב\". (לפי \"גדולי אוסטרהא\" היה אחיו של ר משלם זלמן אשכנזי מפמורין). חתניו: ר אריה ליב קצנלנבוגן, ר יהודה ברוידא, ר יצחק אהרן? איטינגא מלבוב, ר דוד הלפרין. יש רושמים תאריך פטירתו - תקנא."},{"i":2497,"n":"אורנשטין, מרדכי זאב מפשמישל","f":"יעקב משלם-ישועות יעק","bt":"תקן","bp":"ירוסלב","dt":"תקצז - יז חשון","dp":"לבוב","b":"נכד(-אבי אמו)-החכם צבי, אחיו של ר משלם זלמן אשכנזי בעל בית משלם. לאחר שנתייתמו גדלו אצל אביהם החורג ר צבי הירש מרגליות אב\"ד לובלין (אך לפי בובר נפטר בחיי אביו). רב בלבוב, אב\"ד פשמישל(=פרמישלא) ולפי בובר לא הלך לשם, מחידושיו בספר אביו \"ישועות יעקב\". בניו: ר צבי הירש לימים אב\"ד לבוב, ר ירחמיאל."},{"i":2498,"n":"אורנשטין, משה יהושע השל","f":"מרדכי זאב מלבוב","k":"בעל הים התלמוד","bt":"תקלד","bp":"סטנוב","dt":"תקפד","b":"תלמיד ר צבי הירש בעל \"תפארת צבי\", חברו של ר אפרים זלמן מרגליות. רב ברדיויל(=ראדוויל)-תקנד, טרניגרד שם הקים ישיבה ובין תלמידיו ר חיים מצאנז, עבר לרוהטין-תקעה (בגלל התגברות החסידות - היה מתנגד לחסידות), חיבר \"הים התלמוד\" למברג תקפח (הי\"ם ראשי תיבות שמו), ובהמשך עם תוספות בשם \"מפרשי הים\", כתבים נוספים נדפסו על ידי אחרים בהעלמת שמו ובלי רשות. הסכים על \"תפארת צבי\". אחיו - ר יעקב משלם בעל \"ישועות יעקב\"."},{"i":2499,"n":"אורנשטין, משה ליב מירושלים","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":2500,"n":"אורנשטין, משה נתן מזמיגראד","f":"חיים אברהם מברדיוב","b":"גביר בזמיגראד."},{"i":2501,"n":"אורנשטין, נתן מוינה","f":"אהרן יצחק","b":"חתן הגביר איטציג פייט מברלין. גביר וברון בוינה-1814, סייע בהקמת בית כנסת , ומוסדות רבים בוינה."},{"i":2502,"n":"אורנשטין, פנחס מסטעפין","f":"יעקב","bt":"תרכה","b":"רב בסטעפין-ווהלין-תרס."},{"i":2503,"n":"אורנשטין, צבי הירש מבריסק","f":"מרדכי זאב","k":"בעל ברכת רצ\"ה","bt":"תקעו","bp":"לבוב","dt":"תרמח - ט ניסן","b":"רב בבריסק-תרכה ור יהושע ליב דיסקין על מקומו אחריו (לאחר שגורש בידי הרוסים), רישא-תרלג, לבוב-תרלה והיתה שם מחלוקת גדולה בענין זה עם החסידים שהתנגדו לו. חתן הגביר ר יונה מסלוצק. חיבר \"ברכת רצ\"ה\" למברג תרמט. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג, \"תורה מציון\" - ירושלים תרנה-תרסה. מתשובותיו ב\"ספר זקנו \"ישועות יעקב\". חתנו - ר אריה ליב ברודא בעל \"מלחמות אריה\" הביא מתורתו בספרו. הסכים על \"ברכת יעקב\", \"הלכה למשה\", \"מנחת יוסף\", ועוד.","bk":[["ברכת רצ\"ה [שו\"ת]",""]]},{"i":2504,"n":"אורנשטין, שמואל מברזן","b":"מחכמי ברזן. רב ברימלייא (רוסיה)-תריח."},{"i":2505,"n":"אורנשטין, שמשון (שמעון) מקאליש","f":"משה","k":"בעל תפארת שמשון","bt":"תקפד","dt":"תרסד - כג כסלו","b":"רב באוזרקוב, קאליש. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":2506,"n":"אורצקי, אליעזר","dt":"תשג","b":"רב בפוטייב"},{"i":2507,"n":"אורשיצר, אברהם יהודה מטרנוב","bt":"תקצה","dt":"תרעה","b":"דיין בטרנוב-תרנו."},{"i":2508,"n":"אושנבורג, שמעון הלוי","f":"יצחק","dt":"שס","dp":"ירושלים","b":"בשנת שמח היה בונציה והדפיס את ספרו \"דבק טוב\". עלה לירושלים בשנת שמט,"},{"i":2509,"n":"אושעיא הלוי","b":"מגדולי הראשונים בטרוייאש-ד'תתק\"נ"},{"i":2510,"n":"אושעיה טרייטל הכהן מוילנא","f":"משה","dt":"תקעג - כ טבת","dp":"וילנא","b":"מחכמי וילנא, ומרואי פני הגר\"א."},{"i":2511,"n":"אושפיץ, אברהם ישעיה","b":"רב המדינה בניקלשבורג-תקל\"ב"},{"i":2512,"n":"אושפל, יצחק דב מנ\"י","b":"פרסם מאמרים ב\"קובץ חדושי תורה\" - נ\"י תשד - קובץ תלמידי ישיבות \"תומכי תמימים ליובאויטש\"."},{"i":2513,"n":"אושפל, שלמה אליהו מקרניץ","b":"רב בקרניץ לפני השואה."},{"i":2514,"n":"אושקי, אברהם מספרד ואיטליה","f":"שלמה","b":"ממשפחת אנוסים בפורטוגל, ברח מליסבון לפיררה-איטליה, והקים בית דפוס והדפיס תרגום המקרא לספרדית בעזרת ר יו\"ט לוי עטיאס ודונה גרציה מנדס."},{"i":2515,"n":"אושקי, שלמה מספרד","k":"דוארטי גומיץ","b":"מחכמי ספרד, מהאנוסים, ברח לאיטליה וחזר ליהדות. מדפיס בקושטא. חיבר שירים ופיוטים, ור יהודה אריה ממודנא העתיק משיריו לאיטלקית. שליחו של דון יוסף נשיא לצרפת."},{"i":2516,"n":"אושקי, שמואל מפורטוגל ואיטליה","k":"בעל ספר תנחומות","b":"מאנוסי פורטוגל, התישב בפיררה. חיבר בפורטוגזית \"תנחומות גליות ישראל\" - אמשטרדם."},{"i":2517,"n":"אזאגורי, משה ממרוקו","k":"בעל ירים משה","bt":"האביר יעקב (אבוחצירא) בירך אותו כשהיה נער יתום בן יב נמצא שלא אחרי תרכח שכן האביר יעקב נפטר בשנת תרם","bp":"יונילאן-מרוקו","dt":"תשא - כב סיון","dp":"מרוקו","b":"גדל בכפר יונילאן במחוז תלוואת בהרי האטלס. רב ביונילאן והאזור (עד למראקש) וראש ישיבה. מגדולי פוסקי ההלכה בדורו. מתלמידיו ר דוד פרץ בעל \"מגן דוד\", ר שמעון הכהן, ר יוסף פרץ, ר שמעון דרעי ועוד. בניו ר רפאל, ר מאיר ור נסים.","bk":[["ירים משה - על התורה",""]]},{"i":2518,"n":"אזאגורי, נסים ממרוקו","b":"גביר ושר בדבדו-מרוקו."},{"i":2519,"n":"אזאווי, כמוס","bt":"תר","dt":"תרעג - כט טבת","b":"בקי,רב בטריפולי"},{"i":2520,"n":"אזאווי, משה ממרוקו","b":"רב בפאס-תרם."},{"i":2521,"n":"אזאווי, שלום ממרוקו","b":"רב במרוקו (רבאט?). שיר תפלה לכבודו מאת זאכוב אבטאן - רבאט."},{"i":2522,"n":"אזאווי, שמואל מסאלי-מרוקו","f":"משה","dt":"תקט - לפני","b":"מחכמי סאלי-מרוקו, סופר בי\"ד, שו\"ב דיין, והיה במחלוקת עם הדיינים חבריו, ר\"י צרפתי, ר\"ש כהן, ור\"ש קארו, והמחלוקת הגיע לרבני פאס ומכנאס, בראש המתנגדים אליו היה היעב\"ץ שכתב אליו אגרת בחרוזים ובהם רמוז ענין המחלוקת, אך כנראה נשאר דיין וחתם ב\"משפט וצדקה ביעקב\"."},{"i":2523,"n":"אזאמיל, שלמה משלוניקי","f":"יונה","dt":"רפז - טו אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":2524,"n":"אזגגורי, מאיר ממרוקו","f":"משה-ירים משה","bt":"תרס","bp":"יונילאן-מרוקו","dt":"תשמו","b":"רב ביונילאן שבמחוז תלוואת בהרי האטלס במרוקו על מקום אביו. עלה לארץ והתישב בנתיבות."},{"i":2525,"n":"אזהארה ן, אליעזר","f":"מנחם","b":"מחכמי ספרד, תלמיד הרי\"ף. רב בפעווילא אשונילא. נזכר אצל ר יהודה הלוי, ואצל ר משה ן עזרא."},{"i":2526,"n":"אזו ן, אהרן משלוניקי","f":"אברהם","b":"מחכמי שלוניקי-שפ, חברו של ר שלמה הלוי הבחור."},{"i":2527,"n":"אזובי, משה מצידון","b":"רב בצידון-תקך בערך על מקום ר משה חגיז."},{"i":2528,"n":"אזוביב, אהרן ממצרים וחברון","b":"מגדולי רבני מצרים-ת\"מ. חתנו - ר יוסף הלוי הנזיר בעל \"מטה יוסף\". חברו של ר אליעזר ן ארחא. נזכר ב\"פרי חדש\". אלמנתו סייעה לר ישועה שבאבאו (שהיה נשוי לנכדתה) להדפיס את ספר השו\"ת של חותנו (וחתנה) ר יוסף הלוי נזיר."},{"i":2529,"n":"אזוביב, דוד משלוניקי","b":"מדפיס בשלוניקי-של."},{"i":2530,"n":"אזוביב, יוסף מאלגיר","f":"דוד","bt":"תי - בערך","dt":"תף - בערך","dp":"ירושלים","b":"רב באלגיר, עלה לירושלים-תסו. נזכר ב\"פרי צדיק\" לר רפאל צרור. מתלמידיו ר מכלוף עמאר המביא מתורתו (בקונטרס דרושים - ליוורנו תקיט). אחיו של ר סעדיה"},{"i":2531,"n":"אזוביב, יוסף מאלגיר - הזקן","f":"נהוראי","k":"בעל ימים אחדים","dt":"תקנד","b":"נכד ר סעדיה אזוביב. חתן ר דוד חיים שמואל חסאן והסכים על ספרו \"מכתם לדוד\". רב באלגיר, מקובל ונמנה בחברות המקובלים של ר אברהם טוביאנה. חיבר הקדמה ל\"מטה יהודה\" לר יהודה עייאש. מתלמידיו - ר עמרם עמאר. מבניו - ר מרדכי."},{"i":2532,"n":"אזוביב, יוסף מאלגיר - הנכד","f":"מרדכי בן יוסף","dt":"תרן","b":"רב באלגיר. הו\"ל ספר זקן זקנו - ר סעדיה - \"תוכחות מוסר\" - ליוורנו תרלא עם הקדמה ממנו, חיבר חדושים לתנ\"ך ולמאמרי חז\"ל ונדפסו בסוף ספר זקנו."},{"i":2533,"n":"אזוביב, משה משלוניקי","dt":"שו - תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":2534,"n":"אזוביב, נהוראי מאלגיר","f":"סעדיה","dt":"תקמה","b":"רב ודרשן באלגיר על מקום ר יעקב ן נאיים, בזמן ר יהודה עייאש - וחיבר הקדמה לספריו \"לחם ומטר\" ו\"קול יהודה\". פייטן ומפיוטיו בקרובץ מנהג אלגיר. חיבר שירים בעברית וערבית יהודית. חיבר פירוש לקרוב\"ץ. הו\"ל \"חכמת המסכן\" - סדר תפילות ופיוטים."},{"i":2535,"n":"אזוביב, נהוראי מאלגיר - הראשון","bt":"שע","dt":"תן","b":"חתן ר סעדיה זוראפא. ראש משפחת אזוביב באלגיר."},{"i":2536,"n":"אזוביב, סעדיה מאלגיר - א","f":"דוד","dp":"ירושלים","b":"רב ומשורר באלגיר. עלה לירושלים-תסו. מתורתו ב\"ברית אברהם\" לר אברהם בושערה."},{"i":2537,"n":"אזוביב, סעדיה מאלגיר- ב -לסדר","f":"נהוראי","k":"בעל תוכחות מוסר","bp":"אלגיר","dt":"תפה - בערך","dp":"ארץ ישראל","b":"דיין באלגיר אצל ר ידידיה שלמה צרור. ממתנגדי השבתאות וחתם עם רבני אלגיר ב\"מלחמה לה'\" ו\"חרב לה'\". פעל לטובת היהודים בזמן הגזירות שהיו בימיו באלגיר. חיבר \"תוכחות מוסר\" ליוורנו תרלו, ועוד. תשובה ממנו ב\"מלחמה להשם\" כנגד נחמיה חיא חיון - יחד עם רבני אלגיר ר שלמה קרשקש ור שלמה אבן כספי, ר צמח דוראן, ועוד. (אצל גליס מופיע - עלה לארץ בשנת תסו יחד עם אחיו ר יוסף - והוא טעות - הכוונה לרב אחר באותו השם)."},{"i":2538,"n":"אזוילוס, חביב","dt":"תרפג","b":"מחכמי מראקש"},{"i":2539,"n":"אזולאי - משפחה","b":"משפחת רבנים במרוקו."},{"i":2540,"n":"אזולאי, אברהם ממראקש","f":"משה","b":"מחכמי מראקש-מרוקו, הסכים על \"תהלה לדוד\" לר דוד חסין-תקמג."},{"i":2541,"n":"אזולאי, אברהם ממרוקו","k":"בעל הגהות על אוצרות","bt":"תכ","dt":"תצו-תקא","b":"תלמיד ר יצחק דלויה. מקובל מחכמי פאס, רב בטיטואן, מכנאס, מראקש. כתב הגהות על ספרי האר\"י ועל השו\"ע. מתלמידיו בקבלה - ר יעקב פינטו ממראקש, ר ישעיה הכהן ממראקש."},{"i":2542,"n":"אזולאי, אברהם מספרד ומרוקו","b":"מגולי ספרד, רב בפאס בזמן ר שמעון לביא. נכדו - ר אברהם בעל \"חסד לאברהם\"."},{"i":2543,"n":"אזולאי, אברהם מפאס וחברון","f":"מרדכי","k":"בעל חסד לאברהם","bt":"של","bp":"פאס","dt":"תה - כא חשון","dp":"חברון","b":"עלה לארץ-שסו, רב בחברון, ירושלים-שעט, עזה, חזר לחברון, חיבר גם \"בעלי ברית אברהם\", ועוד. זקנו של החיד\"א. בנו - ר יצחק, חתניו: ר בנימין זאבי, ר אברהם יצחקי."},{"i":2544,"n":"אזולאי, אברהם מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו-תרו."},{"i":2545,"n":"אזולאי, אברהם מצפת","f":"החיד\"א","bt":"תקיג","bp":"ירושלים","dt":"תקנט","dp":"ירושלים","b":"רב בצפת-תקנט, בשליחות במקומות שונים ובהם אלגיר-תקמ, אנקונה וליוורנו-תקמה. חתם על אגרות ותעודות, כמה ממכתביו נדפסו על ידי בניהו בסוף ספר החידא. נפטר בחיי אביו החיד\"א בגיל 50."},{"i":2546,"n":"אזולאי, אברהם מתל אביב","b":"אשכנזי ממשפחת החיד\"א, עלה לארץ והתישב בתל אביב."},{"i":2547,"n":"אזולאי, אליהו מאלגיר","f":"יצחק","bt":"תקף","dt":"תרן","b":"רב באלגיר. נזכר בשו\"ת \"שמו משה\" לר משה פארדו."},{"i":2548,"n":"אזולאי, אליעזר מאלגיר","f":"אברהם","bt":"תקי","dt":"תקף","b":"סופר שטרות וסת\"ם בתלמסאן-אלגיר."},{"i":2549,"n":"אזולאי, חיים יוסף דוד","f":"יצחק זרחיה","k":"החיד\"א","r":"החיד\"א","bt":"תפד או תפז","bp":"ירושלים","dt":"תקסו - יא אדר","dp":"ליוורנו","b":"תלמיד ר יונה חנון בעל \"נחפה בכסף\", ר חיים ן עטר ור יצחק הכהן רפפורט בעל \"בתי כהונה\". חתן ר' נסים ברכה (בגיל 14). חתם על שטר ההתקשרות עם ר שלום שרעבי. בשליחות חברון פעמים רבות במקומות שונים ובהם מצרים, איטליה, גרמניה, הולנד, אנגליה וצרפת-תקיג-תקיח, דיין ומרביץ תורה בירושלים, רב בקהיר-תקכד, מרביץ תורה בחברון-תקכט, בשליחות באירופה-תקלג, רב בליוורנו-תקלח (סירב להיות רב ראשי), אפריקה ואירופה. פגש רבים מגדולי דורו במזרח ובמערב, חיבר כמאה ספרים, ספרו הראשון \"שער יוסף\" ליוורנו תקיז, אסף ספרים וכתבי יד והיה מגדולי החוקרים. על מסכתות קטנות. ר' חיים יוסף דוד אזולאי (חיד\"א). מחכמי ורבני ירושלים. נפטר בליוורנו תקס\"ו. מחיבוריו: ברכי יוסף, חיים שאל, יוסף אומץ. על שו\"ע או\"ח. ר' חיים יוסף דוד אזולאי (חיד\"א), מחכמי ורבני ירושלים. נפטר בליוורנו תקס\"ו. מחיבוריו: חיים שאל, יוסף אומץ, טוב עין.","bk":[["חומת אנך","מפרשי תנ\"ך"],["יוסף תהילות [תהילים]","מפרשי תנ\"ך"],["נחל אשכול [מגילות]","מפרשי נ\"ך"],["נחל קדומים","מפרשי תורה"],["נחל שורק [הפטרות]","מפרשי תנ\"ך"],["פני דוד","מפרשי תורה"],["צוארי שלל [הפטרות]","מפרשי תנ\"ך"],["מראית העין [הקדמה]","מפרשי ש\"ס - אחרונים"],["מראית העין [על הגמרא]","מפרשי ש\"ס - אחרונים"],["מראית העין [על המשנה]","מפרשי ש\"ס - אחרונים"],["מראית העין [נספחים]","מפרשי ש\"ס - אחרונים"],["פתח עינים [הקדמה]","מפרשי ש\"ס - אחרונים"],["פתח עינים [על הגמרא]","מפרשי ש\"ס - אחרונים"],["פתח עינים [על המשנה]","מפרשי ש\"ס - אחרונים"],["שער יוסף","מפרשי ש\"ס - אחרונים"],["ברכי יוסף [תוכן העניינים]","מפרשי שו\"ע"],["ברכי יוסף","מפרשי שו\"ע"],["שיורי ברכה","מפרשי שו\"ע"],["מחזיק ברכה","מפרשי שו\"ע"],["יוסף בסדר","הלכה ומנהג - אחרונים"],["כף אחת","הלכה ומנהג - אחרונים"],["לדוד אמת","הלכה ומנהג - אחרונים"],["מורה באצבע","הלכה ומנהג - אחרונים"],["סנסן ליאיר","הלכה ומנהג - אחרונים"],["צפורן שמיר","הלכה ומנהג - אחרונים"],["קשר גודל","הלכה ומנהג - אחרונים"],["שומר ישראל","הלכה ומנהג - אחרונים"],["דבש לפי","כללים"],["מדבר קדמות","כללים"],["עין זוכר","כללים"],["שם הגדולים מערכת גדולים","כללים"],["שם הגדולים מערכת ספרים","כללים"],["חיים שאל","שו\"ת - אחרונים"],["טוב עין","שו\"ת - אחרונים"],["יוסף אומץ","שו\"ת - אחרונים"],["שער יוסף","שו\"ת - אחרונים"],["חיד\"א","שו\"ת - אחרונים"],["לב דוד","מחשבה ומוסר - אחרונים"],["אהבת דוד","דרשות"],["דברים אחדים","דרשות"],["חדרי בטן","דרשות"],["כסא דוד","דרשות"],["עט רצון","דרשות"],["ראש דוד","דרשות"],["רוח חיים","דרשות"],["דברים אחדים – דרוש",""],["זרוע ימין – אבות",""],["חדרי בטן – דרוש",""],["חסדי אבות וראשי אבות – אבות",""],["יוסף אומץ – שו\"ת וענינים",""],["יוסף תהילות – תהלים",""],["כסא דוד – דרוש",""],["כסא רחמים – מסכתות קטנות",""],["מחזיק ברכה – שו\"ע",""],["מעגל טוב",""],["מעשה דוד (כת\"י)",""],["מראית העין – עין יעקב",""],["נחל קדומים – עה\"ת",""],["עבודת הקודש",""],["עט רצון - על התורה",""],["פני דוד – עה\"ת",""],["פתח עינים – עין יעקב",""],["צווארי שלל – הפטרות",""],["רוח חיים – דרוש",""],["שו\"ת החיד\"א",""],["שם הגדולים",""],["שמחת הרגל – פסח",""],["שער יוסף – הוריות",""],["ברכי יוסף – שו\"ע",""],["אהבת דוד – דרוש",""],["חומת אנ\"ך – תנ\"ך",""],["חיים שאל – שו\"ת",""],["יעיר אוזן – עין זוכר",""],["ככר לאדן – מסכתות קטנות",""],["לב דוד - מוסר",""],["שיורי ברכה – שו\"ע",""],["חיד\"א [חיבר כ- ספרים]",""],["אגרות הרב חיד\"א",""],["אור תורה",""],["בית אבות",""],["דבש מלוקט",""],["ועד לחכמים",""],["זרוע ימין",""],["זרע אנשים",""],["חומת אנך חלק",""],["חסדי אבות",""],["יוסף תהלות",""],["יעיר אוזן",""],["ככר לאדן",""],["כסא רחמים",""],["לחם מן השמים",""],["מראית העין",""],["סדר תפלות החדש",""],["פירוש חומ\"ת אנ\"ך",""],["פתח עינים",""],["צוארי שלל",""],["שאלות ותשובות מרבנא חיים יוסף דוד אזולאי",""],["שמחת הרגל",""],["שמחת הרגל חלק ב",""],["תהילים",""],["ועד לחכמים – שיורי שם הגדולים",""],["שם הגדולים-כתב יד","כתב יד החיד\"א מספרו שם הגדולים"],["ברכי יוסף-דפוס שאלוניקי","שו\"ע"]]},{"i":2550,"n":"אזולאי, חנניה חביב מירושלים","k":"בעל מגן הדת","b":"מחכמי ירושלים. בשליחות מהרי\"ל דיסקין, מורה בביהמ\"ד לרבנים בפאריס אצל ר צדוק הכהן, לונדון, התישב בקזבלנקא. הו\"ל כתב עת \"אור המערב\", ובלונדון הו\"ל \"הציון\". היה במחלוקת עם ר משה מאיר אליקים מטבריה וחיבר כנגדו \"מגן הדת\" ור משה מאיר חיבר כנגדו \"מלחמת המגן\"."},{"i":2551,"n":"אזולאי, יהודה זרחיה מטבריה","b":"מרבני טבריה"},{"i":2552,"n":"אזולאי, יהודה זרחיה ממרוקו וי","f":"משה בן דוד","bp":"מראקש-מרוקו","dt":"תרלא","dp":"ארץ ישראל","b":"מחכמי פאס, עלה ממארקש-מרוקו לירושלים-תקעב, משפחה שמוצאה מחכמי קאשטיליה. אשתו הראשונה ממשפחה מחסידי חב\"ד - בתו של של ר אהרן יפה מבריסק - שנקרא חיים יוסף דוד על שם זקנו החיד\"א. בשנת תקעד בשליחות בתורכיה ואיטליה, בתקץ בשליחות במרוקו ובמקומות שונים לתקופה ארוכה. בשנת תרכח חזר לארץ. הו\"ל בליוורנו - שו\"ת הרדב\"ז ח\"ה עם \"שאלות מן השמים\" לר יעקב ממרויש. מכתבים שלו פרסם י.מ. טולידנו ב\"ירושלים\" שנה ג."},{"i":2553,"n":"אזולאי, יהודה מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו-שנות ה-ת'-תק'. בנו - ר ישועה."},{"i":2554,"n":"אזולאי, יעקב מצפת","f":"יצחק","bt":"תרנט","bp":"צפת","b":"מצאצאי החיד\"א. שופט בתל אביב."},{"i":2555,"n":"אזולאי, יצחק זרחיה מחברון","f":"אברהם השני","k":"בעל זרע יצחק","bt":"שעט","bp":"חברון","dp":"קושטא","b":"מחכמי חברון, ירושלים, מאבות אבותיו של החיד\"א, רבו של ר ישראל זאבי שהיה גם בן אחותו. חתם על מכתבים והסכמות. בשליחות בקושטא ושם נפטר. לדעת רוזניס חתניו היו - ר בנימין זאבי מחברון, ר דוד יצחקי מחברון."},{"i":2556,"n":"אזולאי, יצחק זרחיה רפאל","f":"ישעיה","k":"בעל בית יעקב","bt":"תסב","bp":"ירושלים","dt":"תקכה - כג טבת","dp":"ירושלים","b":"מחכמי ירושלים בישיבת בית יעקב פיררה-תקו, אביו של החיד\"א, אביו ר ישעיה היה מקורב לחבורת ר יהודה החסיד ואשתו היתה שרה בתו של ר יוסף בייאלר מבני החבורה. חבר \"בית יעקב\", בשנת תקא בשליחות באירופה עם ר אברהם בן אשר, חתום על פסקים והסכמות."},{"i":2557,"n":"אזולאי, יצחק מירושלים","f":"החיד\"א","b":"מגדולי חכמי ירושלים-תק\"ע,שד\"ר לערי פרנקיא ואשכנז. ב'אבני בית היוצר' מביא הקדשה ממנו לר מאיר ברבי מפרשבורג ושם חותם יצחק בן רפאל בן החיד\"א."},{"i":2558,"n":"אזולאי, ישעיה הזקן מירושלים","f":"יצחק","dt":"תצב - ו אדר","dp":"ירושלים","b":"זקנו של החיד\"א. תלמיד ר חזקיה די סילוא בעל \"פרי חדש\". רב וראש ישיבה בירושלים. בנו - ר יצחק זרחיה, מתורתו בספר נכדו - החיד\"א."},{"i":2559,"n":"אזולאי, ישעיה מצפרו-מרוקו","f":"יהודה","b":"מחכמי צפרו-מרוקו הקדומים."},{"i":2560,"n":"אזולאי, ישראל ממראקש","b":"רב במראקש, חתם על פס\"ד-תקמח."},{"i":2561,"n":"אזולאי, מימון מירושלים","b":"מחכמי ירושלים, בשנת תנא בשליחות במרוקו."},{"i":2562,"n":"אזולאי, מימון מפאס","b":"מחכמי פאס - שנות ה-ת."},{"i":2563,"n":"אזולאי, מסעוד (סגי נהור) מצפת","dt":"שמא","b":"מחכמי פאס, עלה לצפת בשנת שלד והיה מגורי האר\"י. בשנת שפא חתם על כתב הזמנה לרב לר ישכר בר. היה רבו של ר שלמה שלומיל מיינשטרל. מדברי תורתו בספרי חכמי דורו."},{"i":2564,"n":"אזולאי, מרדכי מפאס","b":"אביו של המקובל ר אברהם בעל \"חסד לאברהם\"."},{"i":2565,"n":"אזולאי, משה","f":"רפאל ישעיה אזולאי","k":"בעל זכרון משה","bt":"תקמז","bp":"אמשטרדם","dt":"תריג - לפני","b":"נכד החיד\"א (שבחר את שמו), ונכד ר שלמה שלם מאמשטרדם. חיבר קיצור ומפתחות לספרי זקנו החיד\"א בשם \"זכרון משה\"."},{"i":2566,"n":"אזולאי, נחמיה מירושלים","b":"מחכמי ישיבת \"גדולת מרדכי\" בירושלים-תקיח."},{"i":2567,"n":"אזולאי, נסים זרחיה מירושלים וצ","f":"אברהם הרביעי","k":"בעל שלחן הטהור","bt":"תקם - לפני","bp":"ירושלים","dt":"תקצז","dp":"צפת","b":"נכדו של החיד\"א, ובשנת תקסג היה אצלו בליוורנו וקיבל את ספרו \"מורה חדש\". מחכמי ירושלים-תקסד, רב במגנציא-ליד אזמיר. רב בצפת-תקצא. הסכים שם עם ר אהרן משקלוב ור אברהם אנהורי על \"עפר יעקב\" לר יעקב אינהורן. חתם על כתב שליחות ר משה ן סמחון-תקצה. נספה ברעש בצפת."},{"i":2568,"n":"אזולאי, סעדיה מאלגיר","dt":"תרס - לפני","b":"רב החברא קדישא באלגיר. מתורתו ב\"חסד ואמת\" - אלגיר תרמח."},{"i":2569,"n":"אזולאי, עמרם ציון חי מפאס","bt":"תרעט","bp":"פאס","dt":"תשנט - כו אייר","dp":"ירושלים","b":"מחכמי פאס, עלה לירושלים, למד עם ר שלום כהן, ואחיו ר יעקב מפורת יוסף, ועם ר בן ציון אטון, תקופה מסויימת התגורר ליד הצדיק ר אריה לוין ולמד עמו בחברותא, עבר לבני ברק. מחותנו של הרב עובדיה יוסף."},{"i":2570,"n":"אזולאי, רפאל ישעיה","f":"החיד\"א","k":"ברי\"א - בעל אמרי נעם","bt":"תק-ג","dt":"תקפו - ט שבט","b":"בנו הבכור של החיד\"א, בשנת תקמ בשליחות טבריה, בשנת תקמז היה באמשטרדם, חתן ר שלמה שלם מאמשטרדם, נתמנה לרב באנקונה-תקמח. עשרות מכתבים ממנו לאביו וחזרה (חלקם באגרות החידא), ספרו \"אמרי נעם\" נדפס בשם \"תפארת משה\" בתוך ספר בנו \"זכרון משה\", וכן חיבר ספר דרושים בכת\"י. פסקים ממנו בספרי אביו ובנו ר משה אזולאי."},{"i":2571,"n":"אזולאי, שלום מצפרו-מרוקו","k":"בעל בצלצלי שמע","bt":"תרח","bp":"צפרו-מרוקו","dt":"תרפב - טו שבט","b":"משורר, דיין בצפרו-מרוקו אצל ר רפאל משה אלבאז, וראב\"ד מטעם הממשלה-בסוף ימיו. החזיק בספריה גדולה, והעתיק ספרים. חיבר שירים \"צלצלי שמע\" ונדפסו בסוף \"עת לכל חפץ\". ערך מפתחות ל\"משפט וצדקה ביעקב\" ח\"ב."},{"i":2572,"n":"אזולאי, שלום מרדכי מצפרו-מרוקו","dt":"תשכא - כז שבט","dp":"ירושלים","b":"רב בצפרו-מרוקו, פאס. עלה לארץ-תרפא, והיה מחבורת לומדי הקבלה אצל ר אליהו אלעג'מי. דיין לעדת המערבים, ור\"מ בישיבת \"פורת יוסף\", לימד קבלה יחד עם חברו ר אפריםהכהן. דרש לתלמידי חכמים וגם להמון העם. נספד ע\"י חברו ר עובדיה הדאיה ב\"ויקח עובדיהו\"."},{"i":2573,"n":"אזולאי, שמואל מסאלי-מרוקו","b":"רב בסאלי-מרוקו-תפו. חתם עם ר שמואל אזולאי, ר אהרן הצרפתי ור יהודה הלוי."},{"i":2574,"n":"אזולאי, שמעון ממראקש","f":"ישועה","b":"מחכמי צפרו-מרוקו-שנות ה-תק'. בנו - ר אליהו."},{"i":2575,"n":"אזיוידו די, דוד הכהן","dt":"תקנב","b":"רב קהל ספרדים באמשטרדם על מקום ר שלמה שלם-תקמא. מצאצאי מגורשי ספרד. הסכים על \"פני אריה\", \"דרך חכמה\", \"גבעת שאול\", עיני אברהם\", ועוד."},{"i":2576,"n":"אזינסקי, בנימין","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":2577,"n":"אזכרי, אלעזר מצפת - הזקן","b":"מחכמי צפת-ר'. בנו ר משה ונכדו ר אלעזר בעל \"ספר חרדים\"."},{"i":2578,"n":"אזכרי, אלעזר מצפת - הנכד","f":"משה","k":"בעל ספר חרדים","bt":"רצג","bp":"קושטא","dt":"שס-א","dp":"צפת","b":"מחכמי שלוניקי, עלה לצפת, תלמיד ר יוסף סאגיס, המבי\"ט, לדברי החיד\"א היה מן הסמוכים בידי ר יעקב בירב ויש אומרים שנסמך ע\"י רבו המבי\"ט. חיבר \"ספר חרדים\", פירוש לירושלמי, ועוד. הספידו ר נפתלי אשכנזי בספרו \"אמרי שפר\". אחיו של ר מלכי."},{"i":2579,"n":"אזכרי, יוסף יעקב משלוניקי","b":"מחכמי שלוניקי שעלה לארץ. בשנת תקעו הדפיס על חשבונו את ספר \"מראה עינים\" לר רפאל אשכנזי."},{"i":2580,"n":"אזנאתי, אברהם מסאלי","b":"סופר בי\"ד בסאלי-מרוקו-תקכד."},{"i":2581,"n":"אזנאתי, יוסף ממרוקו","f":"שלמה","k":"בעל כלי השרת","b":"מחכמי מרוקו-תק. חיבר \"כלי השרת\" על דיני קריאת התורה."},{"i":2582,"n":"אזנאתי, רפאל מאלג'יר","bt":"תקם - בערך","dt":"תרי - בערך","b":"מחכמי אלג'יר, עלה לארץ-תקפט עם חבורת עולים (לאחר הכיבוש הצרפתי), והתישב בצפת."},{"i":2583,"n":"אזנאתי, שלמה מאלג'יר","dt":"תקמג - לפני","b":"רב ומקובל בדזאייר(=אלגיר). נזכר בהקדמת \"חסד לאברהם\" - אזמיר תקכד."},{"i":2584,"n":"אזנקוט, יהודה מטנג'יר","b":"רב בטנג'יר-תרפב."},{"i":2585,"n":"אזנקוט, סעדיה ממראקש","k":"בעל אגרת הפורים","b":"מחכמי מראקש בשנות ה-ת'."},{"i":2586,"n":"אזנקוט, שלמה ממראקש","b":"רב במראקש. נזכר אצל ר ידידיה מונסונייגו ב\"קופת הרוכלים\"."},{"i":2587,"n":"אזעף, חנוך מאוטואצק","b":"פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":2588,"n":"אזראד, יוסף ממכנאס","b":"מחכמי מכנאס. חתם-תקנד עם ר מימון בירדוגו. העתיק בכתב ידו את אגרת התשובה לרבנו יונה."},{"i":2589,"n":"אזראד, ישעיה ממכנאס","dt":"שנח","b":"חתן ר יוסף בהתית. מחכמי מכנאס."},{"i":2590,"n":"אזראד, שלמה מאלג'יר","f":"אברהם","k":"בעל מאורי אור","bt":"תקפד","bp":"בלידא-תונס","dt":"תרסה","b":"רב וסופר באלגיר, ובקי במנהגי אלגיר ובהלכות עיבור ומולד. חיבר גם \"רעשים ורעמים\", ו\"אור המנורה\"."},{"i":2591,"n":"אזרדכ, חנניה מפאס","f":"סלימן","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":2592,"n":"אזרחוביץ, דוד בן ציון","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":2593,"n":"אחא גאון סורא","b":"גאון סורא-ד'תקיט על מקום רב מרי הכהן מנהר פקוד, ורב יהודאי גאון על מקומו אחריו. היה בזמנו של רב אחאי גאון בעל השאילתות."},{"i":2594,"n":"אחא הכהן גאון פומפדיתא","f":"רבא גאון","b":"גאון פומפדיתא על מקום רב פלטוי בן אביי-ד'תריז, ורב מנחם בר יוסף על מקומו אחריו. בנו רב קומי גאון. בזמנו היה גאון סורא - רב נטרונאי בן רב נהילאי גאון."},{"i":2595,"n":"אחאי גאון משבחא","dt":"תקיב (752)?","b":"מגדולי חכמי בבל בשנים ד תמ (680) - תקיב (752), מחכמי ישיבת פומפודיתא, לאחר שלא קיבל את משרת הגאון מידי ראש הגולה, עלה לארץ ישראל, כנראה ד'תקח (748), ואולי נתמנה שם כראש פירקא, לאחר רב פנחס שהיה האחרון בשושלת ראשי פרקא צאצאי מר זוטרא ראש הגולה שעלה לארץ ישראל כ-230 שנה קודם לכן. חיבר ספר \"שאילתות\" שנחשב לספר הראשון בהלכה."},{"i":2596,"n":"אחד הגאונים","b":"חיבור \"שימושא רבא\" הועתק על ידי הרא\"ש בפסקיו על הלכות תפילין [\"הלכות קטנות\", הובא בדפוסי הש\"ס בסוף מס' מנחות], הרא\"ש מקדים לחיבור: \"ועתה אכתוב הלכות תפילין הנמצאים על שם גאון ז\"ל ונקרא שימושא רבא\". החיבור מופיע בשינויים גם אצל קדמונים אחרים שהזכירוהו בשמות שונים, מהם: שימושא רבא דגאונים; תיקון תפילין של גאונים; הלכות שימושי תפילין. מחברו לא ידוע לנו, אם כי יש אומרים שמחברו הוא רב שר שלום גאון (שו\"ת כנסת יחזקאל סי' כב, בשם המגלה עמוקות; כתב יושר ([אורח מישור] עמ' 27; דעת קדושים [בוטשאטש] או\"ח סי' כז ס\"ד; רגל ישרה [דינוב] מערכת ת אות לו; נחל אשכול ח\"ב עמ' 84 [אות ב]. ואמנם ספרים אלו - מלבד הנחל אשכול - לא הזכירו אלא ששם המחבר הוא רב שר שלום, אך המביאים את הייחוס בשמם נקטו לרב שר שלום גאון).","bk":[["שימושא רבא [הל' תפילין]",""]]},{"i":2597,"n":"אחד הגאונים (שם הגדולים מערכת ספרים ע' סדר)","bk":[["סדר תנאים ואמוראים (סדר תו\"א)",""]]},{"i":2598,"n":"אחד הגאונים. כנראה אחרי רב יהודאי","bk":[["הלכות קצובות",""]]},{"i":2599,"n":"אחד מגדולי הדור (לשון השער במהדורת קניגסברג תריח)","dt":"ד' אלפים רס בערך","bk":[["ארחות צדיקים \\ אורחות צדיקים - והוא ספר המידות",""]]},{"i":2600,"n":"אחד מגודלי חכמי ירושלם","bk":[["תרומה גדולה - ספר התרומות וגדולי תרומה",""]]},{"i":2601,"n":"אחד מתלמידי הרשב\"א","bk":[["אור הגנוז [על ס' הבהיר - המיוחס לר\"נ בן הקנה]",""]]},{"i":2602,"n":"אחונאי הכהן גאון סורא","f":"פפא","b":"גאון סורא-ד'תקכג על מקום רב יהודאי גאון בעל הלכות גדולות, רב חנינאי הכהן גאון על מקומו אחריו. בזמנו היה גאון פומפדיתא - רב דוראי ורב חנינא בן רב משרשיא."},{"i":2603,"n":"אחיה הפייטן","b":"פייטן, ומפיוטיו במחזורים קדומים. חיבר פיוט להבדלה \"השב על כנם בנים גורשים מקנם\"."},{"i":2604,"n":"אחיהו הכהן מטבריה","b":"מחכמי המסורה בטבריה-ד'ת."},{"i":2605,"n":"אחיטוב הרופא מאיטליה","f":"יצחק","b":"מחכמי פלורמא(=פלרמו?)-איטליה, ומעתיק. חיבר \"מחברת הטנא\" בסוף ספר התדיר לר משה בן יקותיאל מרומא. תרגם מאמר הגיון לרמב\"ם מערבית לעברית. מכתב אליו מהרשב\"א אודות המקובל ר אברהם אבולעפיה."},{"i":2606,"n":"אחייהו הכהן","k":"החבר ממדינת מעזיה","bt":"ד'תקלה (775)","dt":"ד'תקפה (825)","dp":"טבריה?","b":"מחכמי טבריה בעלי המסורה, בשנים ד תקלה (775) - תקפה (825)."},{"i":2607,"n":"אחימעץ","f":"פלטיאל בן שמואל","k":"בעל מגילת אחימעץ","bt":"ד'תשעז","b":"סופר ופייטן בקפואה-איטליה-ד'תתיד, איזורי-איטליה. בניו: ר פלטיאל, ר שמואל בעל \"מגילת אחימעץ\" - ובו תולדות משפחתו. חיבר פיוטים ובהם \"איש ימיני\", ועוד."},{"i":2608,"n":"אחימעץ מאיטליה","b":"מחכמי איטליה-ד'תרן, עלה בכל שנה לירושלים ללמוד מראשי הישיבות. נזכר במגילת אחימעץ."},{"i":2609,"n":"אחימעץ מפרובנס","f":"אליעזר בן אחימעץ","b":"מחכמי פרובנס-ה'א."},{"i":2610,"n":"אחרפי, יעקב ן שעיא","b":"דיין במרוקו-תעג, נזכר אצל היעב\"ץ."},{"i":2611,"n":"אטאס, אברהם משלוניקי","f":"יעקב משלוניקי","dt":"תש..","b":"מנהל ביה\"ס ת\"ת בשלוניקי-אחרי ברוך בן יעקב, וחבר באגודת הפייטנים בשלוניקי. נספה בשואה."},{"i":2612,"n":"אטאס, דוד מאזמיר","b":"רב באזמיר-תקף בערך. תשובה אליו מר שמואל חיים ב\"שמן המשחה\"."},{"i":2613,"n":"אטאס, יעקב משלוניקי","b":"מורה בביה\"ס ת\"ת בשלוניקי-לפני השואה. בנו אברהם."},{"i":2614,"n":"אטאס, מנחם משלוניקי","b":"חזן להלויות מתים בשלוניקי. נספה בשואה."},{"i":2615,"n":"אטארט, פנחס מצרפת","b":"חבר באסיפה היהודית צרפתית-תקף, יחד עם אברהם פיקארט, פנחס אטראט."},{"i":2616,"n":"אטובי, אלישע מפאס","b":"מחכמי פאס-תרא."},{"i":2617,"n":"אטובי, מכלוף ממרוקו","b":"מחכמי מרוקו-שנות ה-ש', נזכר במכתב חכמי סאלי - ר אהרן הצרפתי, ר שלמה הכהן ור שמואל קארו."},{"i":2618,"n":"אטוויל, משה מפאס","b":"מחכמי פאס-שי. מתורתו ב\"מראה עינים\" לר אלעזר בהלול."},{"i":2619,"n":"אטון, אברהם מאלגיר","f":"יוסף","bt":"תך","dt":"תץ - בערך","b":"רב באלגיר, ספרא רבא והעתיק סידור ופירוש על פי הקבלה לבקשת ר בנימין דוראן."},{"i":2620,"n":"אטון, אברהם מארטא","b":"רב בארטא על מקום ר רפאל הכהן-שנות ה-ת'. (אולי הוא שהיה רב בשלוניקי?)."},{"i":2621,"n":"אטון, אברהם משלוניקי","b":"מרבני שאלוניקי"},{"i":2622,"n":"אטון, בן ציון מירושלים","f":"מאיר","bt":"תרנה","bp":"ירושלים","dt":"תשלה - כט אייר","b":"מחכמי ירושלים, מראשוני ישיבת \"פורת יוסף\". אביו של ר שבתי."},{"i":2623,"n":"אטון, כדיר","k":"בעל בנימין צעיר","b":"תלמיד ר מקיקץ שלי."},{"i":2624,"n":"אטון, מאיר מירושלים","b":"רב בירושלים, אביו של ר בן ציון אטון."},{"i":2625,"n":"אטון, שבתי מירושלים","f":"בן ציון","bt":"תרפו","bp":"ירושלים","dt":"תשסו - יב שבט","dp":"ירושלים","b":"מחכמי ירושלים בן למשפחה מרודוס, וזקנו ר מאיר עלה משם לירושלים. חתן ר יוסף שהרבני, גיסו של ר בן ציון אבא שאול. ראש ישיבת \"ראשית חכמה\" בירושלים, ורב שכונות דרום ירושלים, ר\"מ בישיבת \"פורת יוסף\". הו\"ל קובץ \"משואות\" ובו חדושים מחכמי ישיבת \"פורת יוסף\""},{"i":2626,"n":"אטורטרוס, שלמה מחלב","b":"רב בחלב-שכ."},{"i":2627,"n":"אטילזון, ברוך מליטא ושיקגו","f":"יונה","k":"בעל תקות ישראל","bt":"תקסו","bp":"שאקי-ליטא","b":"חיבר גם \"כנפי יונה\" על מדרש הזית. היגר לארה\"ב-תרם והתישב בשיקגו. הו\"ל \"תאומי צביה\" - שיקגו תרנא, ועוד."},{"i":2628,"n":"אטינגן, אנשיל","b":"מרביץ תורה בחאלטש"},{"i":2629,"n":"אטינגר, אברהם סגל מדוקלא","b":"פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט."},{"i":2630,"n":"אטינגר, אפרים פישל מקולומיאה","b":"מחכמי קולומיאה. תשובה אליו ב\"שושנים לדוד\"."},{"i":2631,"n":"אטינגר, הלל ממינסק","b":"גביר מחכמי מינסק-תרן."},{"i":2632,"n":"אטינגר, יואל מטורנא","b":"רב בטורנא-תרנט."},{"i":2633,"n":"אטינגר, יחיאל מיכל מליבאוי","bp":"פינסק","b":"גביר מחכמי ליבאוי, פעיל בעניני צבור וחסד."},{"i":2634,"n":"אטינגר, יחיאל מיכל מראווא וארש","k":"מיכל ראווער","dt":"תקצו - טז שבט","b":"גביר מראשי קהלת וארשא. לזכרו הדפיס קרובו - ר יוסף שמואל לנדא מקעפנא \"גורן אטד\" - וארשא תקצז. בנו - ר יעקב הלל ממינסק."},{"i":2635,"n":"אטינגר, יעקב הלל ממינסק","f":"יחיאל מיכל ראווער","dt":"תריח - ח תמוז","dp":"מינסק","b":"חתן ר צבי הירש שמחוביץ מרגליות ממינסק. גביר מחכמי מינסק-תר בערך."},{"i":2636,"n":"אטינגר, יעקב יוסף מברלין","bp":"גלוגא","dt":"תרכא - כב חשון","dp":"ברלין","b":"תלמיד ר צבי הירש מזאמושט בעל \"תפארת צבי\", רב בברלין. הסכים-תרג על אבן בחן לר נתן מפרען."},{"i":2637,"n":"אטינגר, יעקב מהומין","b":"גביר מפורסם. חתנו - הגביר ר מאיר זוסמן בן ר אבא צבי מאוסטרהא."},{"i":2638,"n":"אטינגר, מיכל מליבאוי","b":"מחכמי ליבאוי, ועמד בראש הת\"ת-תרס."},{"i":2639,"n":"אטינגר, מרדכי","b":"גביר. חתן ר חיים מרדכי זוסמן מאוסטרהא."},{"i":2640,"n":"אטינגר, משה מקישקערעש","b":"רב בקישקערעש-תר\"ב"},{"i":2641,"n":"אטינגר, שאול זאב מהליטש","k":"בעל אמרי שאול","dt":"תש..","b":"רב בהליטש, ופודגורזע-תרע. תלמיד ר יהושע פנחס בומבך. נספה בשואה. חיבר \"אמרי שאול\" לא נדפס?."},{"i":2642,"n":"אטינגר, שמחה ממינסק","f":"יעקב","dt":"תרמח - י תמוז","dp":"מינסק","b":"גביר מחכמי מינסק-תר בערך. בניו - הגביר ר הלל ממינסק, ר איזיק שמואל מוארשא. חתניו - ר דובער פינס, ר ברוך זלדוביץ, ר עקיבא רפפורט."},{"i":2643,"n":"אטלס, אברהם ליב מקאמאי"},{"i":2644,"n":"אטלס, אליהו מפשמישל","b":"מחכמי פשמישל-תרלב."},{"i":2645,"n":"אטלס, אליעזר מליטא","bt":"תריא","bp":"בייסיגולה","dt":"תרסד","dp":"ביאליסטוק","b":"פרסם מאמרים בכתב עת שונים, עורך \"הכרם\", מעורכי הלכסיקון \"אשכול\". פרסם מחקר על הריב\"ש. מסות על א\"ה וייס, גרץ ועוד. חיבר פירוש לתהלים. חיבר מחקר על \"ועד ארבע ארצות\" - וכתה\"י אבד. תמך בחובבי ציון, אך התאכזב ועבר למתנגדים. הצטרף ל\"לשכה השחורה\" ופרסם מאמרים נגד הציונות ב\"הפלס\"."},{"i":2646,"n":"אטלס, בנימין בינוש מגלאסגוי","f":"מאיר מטלז","b":"רב בגלסגוי-תרפה. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא. הסכים על \"זוודין לאורחא\" גרוסוארדין תרצו."},{"i":2647,"n":"אטלס, בצלאל מסאקלי וויזנא","f":"ישראל","bt":"תריח","b":"רב בוויזנא-פלך לומזה-תרן וראש ישיבה (המשגיח - ר יצחק נטע פרלוביץ). פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז."},{"i":2648,"n":"אטלס, יצחק מוילקוטש","b":"רב בוילקוטש. תשובה אליו ב\"קנאת סופרים\"."},{"i":2649,"n":"אטלס, מאיר מסלנט","f":"דוד","bt":"תרח","bp":"בייסיגולה","dt":"תרפו - יב שבט","b":"מגדולי חכמי דורו, ר\"מ בישיבת טלז-תרמא, רב בליבאוי-תרמה, סלנט-תרנח, קוברין-תרנט, שאבעל(=שאוולי)-תרסו על מקום ר יוסף זכריה שטרן. פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו. חתנו - ר אלחנן וסרמן הי\"ד."},{"i":2650,"n":"אטלס, ר.מ. מירושלים","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט."},{"i":2651,"n":"אטלס, שלום אברהם מראצע","f":"יוסף צבי","bt":"תריח","dt":"תרצה - טו אב","b":"דומ\"צ ביאלשווא-תרס, רב ברעצע(=ראצע). נסמך מאת: ר פסח זינגר מקירכדורף, ר משה מארגירטן מלופיאן, ר יעקב טננבוים מפוטנאק, ר משה סופר מטיסאפירד, ר אליעזר דייטש מבאניהאד. בנו - ר משה שמואל. חתנו - בן הגביר ר ישראל אברהם קאהן מקערעסט."},{"i":2652,"n":"אטלס, שמואל מליטא ארה\"ב","k":"בעל לחקר התלמוד","bt":"תרנח","bp":"קאמאי-ליטא","b":"תלמיד ישיבות סלובודקה, פוניבז. דוקטור לפילוספיה. מרצה לתלמיד בקיימבריג-1934, אוכספורד-1936, היברו יוניון קולג' בסינסינטי-1942, ומכון של סטיפן וייז בניו יורק-1950. חיבר גם מאמרים בספרי יובל ובהם \"לתולדות הסוגיא\" , \"הערמה משפטית בתלמוד\", ועוד."},{"i":2653,"n":"אטנגי, מרדכי","b":"רב באלג'יר-תרמ\"ז"},{"i":2654,"n":"אטנזאסער, דוד מפיורדא","f":"הירש","k":"בעל קריה נאמנה","b":"מחכמי פיורדא-שנות ה-תק'. תרגם וביאר את התנ\"ך עם פירושים בשם \"קריה נאמנה\", סדר הקינות, חיבר פירוש על בחינת עולם, ועוד."},{"i":2655,"n":"אטנר, חיים מליזנסק","f":"שלום","bt":"תרסו","dt":"תשמב","dp":"ירושלים","b":"חסיד בלז. עבר לטורנא. רב בלונדון-תרצח, לוס אנגלס-תשח. עלה לארץ."},{"i":2656,"n":"אטצנר, יוסף הכהן מפודגורזע","b":"פרסם מאמרים ב\"המפלפל\" - קראקא תרעג."},{"i":2657,"n":"אטקס, יואל מטרנוב","dp":"ירושלים","b":"דיין בטרנוב, חסיד שינאווא, עלה לירושלים בשנת תרס."},{"i":2658,"n":"אטראני, יצחק מאלגיר","bt":"קפ - בערך","dt":"רן - בערך","b":"רב בקצמטינא-אלגיר. שאלה ממנו לרשב\"ש ונזכר בשו\"ת הרשב\"ש."},{"i":2659,"n":"אטראני, שמואל מאלגיר","f":"משה","bt":"[ר]","dt":"רס - בערך","b":"רב בקצמטינא(=קסנטינא)-אלגיר, התכתב עם ר צמח בן הרשב\"ש."},{"i":2660,"n":"אטרמן, חיים משלם קויפמן מגוסטי","f":"שימאן הכהן","k":"בעל פתח האהל","bt":"תרכא","bp":"וארשא","dt":"תרפד - יד סיון","b":"תלמיד ר יחאיל מיכל הכהן מזאקאראטש בעל \"חשרת מים\", ר מאיר יחיאל מאוסטרובצה, ר חיים אליעזר וקס מפיעטרקוב בעל \"נפש חיה\". רב בראטשינז-תרמג, גאסטיין(=גוסטינין)-תרנח, פולטוסק-פלך וארשא-תרסז ויסד ישיבה ועמד בראשה. פרסם מאמרים ב\"שערי תורה\" - וארשא תרסג. חיבר גם \"אלה המצות\", \"נס לשושנים\"."},{"i":2661,"n":"איבגי, שמעון ממרוקו","dt":"תרצד - כה אלול","dp":"מראקש","b":"רב ומקובל במראקש."},{"i":2662,"n":"איבלאגון, אברהם","k":"בעל נכנס יין","b":"כתב ספר \"נכנס יין\" בקושטא"},{"i":2663,"n":"איבנשיץ, דובער","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":2664,"n":"איבנשיץ, ישראל","k":"בעל תפארת ישראל","b":"נכד ר יונתן איבשיץ, חתם בפנקס קהלת אלטונא-תקיט."},{"i":2665,"n":"איבריין, נפתלי הרץ הלוי מקולונ","f":"יצחק","dt":"תכו - כו חשון","dp":"דייץ","b":"גביר בדייץ. פרנס ומנהיג במדינת קולוניא, שתדלן - הצליח להציל את קהלת דייץ-תכה מפוגרום."},{"i":2666,"n":"איבשיץ, אהרן מפיורדא","f":"נתן נטע מאיבשיץ","b":"אחיו של ר יונתן איבשיץ. רב בפיורדא. בנו - ר נתן נטע מפשדבורז. מצאצאיו - בעל חדושי הרי\"מ (מצד אמו)."},{"i":2667,"n":"איבשיץ, אהרן מפיורדא","f":"יונתן - כרתי ופלתי","dt":"תקכט"},{"i":2668,"n":"איבשיץ, אלימלך מקלימנטוב","dt":"תשג","b":"רב בלאפשנא, קלימנטוב. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":2669,"n":"איבשיץ, אלעזר הלוי מסטרדין","b":"מחסידי אלכסנדר, רב בסטרדין. פרסם מאמרים ב\"בית ישראל\" - לודז תרץ, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":2670,"n":"איבשיץ, אריה ליב","f":"נתן נטע אייבשיץ"},{"i":2671,"n":"איבשיץ, דוד צבי שלמה מנדבורנה","f":"ירחמיאל או אביגדור","k":"בעל לבושי שרד","r":"אב\"ד סאראקא -","bt":"תקטו","bp":"אוזיראן או לשקוביץ","dt":"תקעד-ו -כב חשון","dp":"צפת","b":"תלמיד ר משה צבי הלר בעל \"גאון צבי\", ר מיכל המגיד מזלוטשוב, ר משולם פיבש מזבאריז, ועוד. חתנו של ר יחיאל מיכל מלשקוביץ. רב בנדבורנה-תקם, חורוסטקוב, רב ביאסי, ביזינוף, בודזנוב-תקן, סורוקה-בסרביה-תקסג, קופיטשיניץ, ברזן. בשנת תקסז דרש בקראקא בדבר תקון בית הכנסת. עלה לצפת-תקסח-ט. מחותן עם ר לוי יצחק מברדיטשוב. חיבר גם \"אשד הנחלים\", \"נאות דשא\" ליוורנו תקפא, \"ערבי נחל\" סדילקוב תקצה, ועוד בדפוס ובכתב יד. מוזכר במכתבו של ר חיים הלוי (בספרו של הרב טולדנו \"שריד ופליט\").","bk":[["לבושי שרד","מפרשי שו\"ע"],["ערבי נחל","חסידות"],["מגילת סתרים","חסידות"],["לבושי שרד [על שו\"ע]",""],["ערבי נחל [עה\"ת]",""],["אשד הנחלים",""],["בגדי שרד – טריפות",""],["כד הקמח – שו\"ת (חידושים על ק'מא מ'ציעא וח'ולין - כת\"י)",""],["לבושי שרד – שו\"ע",""],["מגילת סתרים - מוסר על פרק ראשון של תהילים",""],["משוש כל המתאבלים – איכה",""],["נאות דשא – שו\"ת",""]]},{"i":2672,"n":"איבשיץ, וולף","f":"יונתן - כרתי ופלתי","b":"מקורב למלכות בוינה, עשה תשובה, בנה מחדש את ביהכ\"נ שבנה אחיו ר נתן בדרזדן."},{"i":2673,"n":"איבשיץ, זעקל מבאייה","dt":"תקעו - כט חשון","b":"התגורר בזאמבאר וכיהן כרב מדינת באטשקא-תקל."},{"i":2674,"n":"איבשיץ, יהודה ליב","f":"יונתן - כרתי ופלתי","dt":"תקלב","b":"מתמיד בתורה - נפטר צעיר."},{"i":2675,"n":"איבשיץ, יהודה מבאלשא-סעלי","bt":"תרלה","bp":"ניאראשד","b":"תלמיד השב\"ס, ור שמואל בורגר מגאלאנטא. גר בפרשבורג-תרסא ולמד מלאכת השו\"ב. שו\"ב באלשא-סעלי-תרסב."},{"i":2676,"n":"איבשיץ, יונתן","f":"נתן נטע","k":"בעל כרתי ופלתי","bt":"תנ","dt":"תקכד - כא אלול","b":"לאחר שנתייתם גדל אצל הגביר ר שמעון בוויען, תלמיד ר מאיר א\"ש בעל פנים מאירות בפרוסניץ, גדל בביתו של ר יצחק שפירא-אב\"ד פרג, והיה לחתנו. גדול במדע בנגלה ונסתר, פוסק, דרשן, איש מופת, מנהיג דגול,מרביץ תורה. קיבל תואר אציל. רב ביונגבונצלוי-תסח-בגיל 18, דרשן וראש ישיבה בפרג-תע, רב במיץ-תק, אה\"ו-תקט."},{"i":2677,"n":"איבשיץ, יונתן הלוי מוארשא","k":"בעל שער יהונתן","dt":"תשג","b":"מו\"צ בואלמין, וארשא. פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח, \"הבאר\" - זאמושץ-וארשא תרפד, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"עמק הלכה\" - וארשא תרפו, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":2678,"n":"איבשיץ, יונתן מלושיץ","bp":"קוצק","dt":"תרסז - ב חשון","b":"חסיד גור. רב בלושיץ(=לאשיץ). מתלמידיו - ר יצחק איזיק מורגנשטרן מקאלושין והביא מתורת רבו בספרו \"תולדות יצחק אהרן\"."},{"i":2679,"n":"איבשיץ, יחיאל מיכאל","f":"יונתן מפרג","bt":"תפה","bp":"פרג","b":"חתן אחות ר גרשון פוליץ מניקלשבורג. מחכמי גרוסורדין - אך לא שימש ברבנות."},{"i":2680,"n":"איבשיץ, יעקב דוד הלוי מוארשא","b":"פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז."},{"i":2681,"n":"איבשיץ, יצחק","f":"יונתן - כרתי ופלתי","dp":"פרג"},{"i":2682,"n":"איבשיץ, ישראל מליכטנשטין","f":"נתן נטע אייבשיץ","dt":"תקעא - ד תמוז","b":"רב בליכטנשטין"},{"i":2683,"n":"איבשיץ, מרדכי מפרשבורג","f":"יונתן - כרתי ופלתי","dt":"תקנט","b":"חתן ר אברהם טעבן-ראש קהלת פרשבורג. מחכמי שטמפן-תקיב, פרשבורג-תקכט (חזר לשטמפן-תקלז - חתם שם בפנקס הקהל). נחשד בשבתאות בפרשבורג וגורש מהעיר בזמן המחלוקת בין חותנו לבין ר מנדל לייטסדורף ועבר לשטמפן. בנו - יונתן."},{"i":2684,"n":"איבשיץ, נתן נטע","dt":"תסח - יב חשון","b":"נכד המגלה עמוקות. חתן ר ליב צונץ. מקובל,גדול בנגלה ונסתר,ראב\"ד באייבשיץ. בנו ר יונתן מאייבשיץ"},{"i":2685,"n":"איבשיץ, נתן נטע מפרג","f":"יונתן - כרתי ופלתי","dt":"תקמט - כד אב","b":"מחכמי פרג, רב בדרזדן, יסד ביכ\"נ הנקרא \"אייבשיטצער\"."},{"i":2686,"n":"איבשיץ, נתן נטע מפשדבורז","f":"אהרן אייבשיץ","b":"רב בפשדבורז-תקמ\"ג"},{"i":2687,"n":"איבשיץ, נתן נטע מרופשיץ","b":"רב בראפשיץ-תק\"נ"},{"i":2688,"n":"איבשיץ, שלמה מיוזפוף","b":"תלמיד ר ישכר דב מרדושיץ. רב ביוזעפוף-תרל."},{"i":2689,"n":"איבשיץ-פירד, אליעזר","f":"נתן נטע","b":"רב באייבשיץ"},{"i":2690,"n":"איגל, אליהו אליעזר אברהם","f":"שמואל","k":"בעל יובל שי","bp":"למברג","b":"למד בביהמ\"ד בפדובה והיה רב ליד האב\"ד ר מרדכי שמואל גירונדי. רב בטשרנוביץ לצד ר בנימין אריה וייס. חיבר \"יובל שי\" למברג תרט."},{"i":2691,"n":"איגל, נפתלי חיים","f":"דוד","bp":"ירוסלב","dt":"תשנח","dp":"ירושלים","b":"חסיד בלז. ניצל מהשואה. עלה לארץ וכיהן כשו\"ב ברמת גן."},{"i":2692,"n":"איגלר, צבי הירש הלוי מסמבור","b":"רב בסמבור-תקפו."},{"i":2693,"n":"איגר, אברהם מלובלין","f":"יהודה ליב מלובלין","k":"אדמור מלובלין","r":"אדמו\"ר מלובלין","bt":"תרו","dt":"תרעד - כב טבת","b":"אדמור בלובלין. חיבר \"שבט מיהודה\", הגהות על ספר אביו.","bk":[["שבט מיהודה",""]]},{"i":2694,"n":"איגר, אברהם מלובלין בני ברק","f":"שלמה מלובלין","k":"אדמור מלובלין בני בר","bt":"תרעו","b":"אדמור מלובלין בבני ברק-תשה על מקום אביו."},{"i":2695,"n":"איגר, אברהם ממזריטש","f":"יהודה ליב","b":"רב במעזריטש-תק\"פ"},{"i":2696,"n":"איגר, אברהם מראויטש","f":"עקיבא מפוזנא","bt":"תקלט","dt":"תריד","b":"רב בראוויטש-תר, חתניו: ר יעקב ליויער מואנגרוויטץ, ר איזיק קארא מברלין שקיבל מחותנו את הגהות רע\"ק על שו\"ע והו\"ל תשובת ר עקיבא איגר מהדורה תנינא, ר נפתלי הירש בליכרוירט מקרניק."},{"i":2697,"n":"איגר, אלתר עזריאל מאיר מלובלין","f":"אברהם מלובלין","k":"אדמור מלובלין בפילוב","bt":"תרלג","dt":"תשא - ה תמוז","b":"חתן ר חיים רוקח נכד בעל \"מעשה רוקח\". אדמור מלובלין בפילוב, וארשא-תרעז. חיבר \"הצעת תקנה נחוצה\", \"תקנת רבים\", ועוד. מבניו: ר יהודה ליב, ר משה מירוסלב, ר עקיבא מלודז, ר צדוק, ר שלום. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":2698,"n":"איגר, בנימין וולף מצילץ וליפני","f":"עקיבא איגר","k":"בעל שער הלבנון","bt":"תקטז","dt":"תקנו - ו תשרי","b":"רב בצילץ, לייפניק-תקמג. אביו של ר עקיבא מהלברשטט. מתלמידיו - אחיינו ר עקיבא איגר מפוזנא."},{"i":2699,"n":"איגר, יהודה ליב","f":"אלתר עזריאל מאיר מלו","r":"האדמו\"ר מלובלין","bt":"ה'תקעו","dt":"ה'תרמח","b":"חתן ר יצחק זליג מסוקולוב (שושלת קוצק).","bk":[["תורת אמת [עה\"ת]",""],["תורת אמת – עה\"ת ומועדים",""]]},{"i":2700,"n":"איגר, יהודה ליב מלובלין","f":"שלמה בן עקיבא מפוזנא","k":"אדמור מלובלין","bt":"תקעה","dt":"תרמח - כב שבט","b":"חתן ר עזריאל מאיר גרדשטין, התקרב לחסידות ולמד אצל ר מנחם מנדל מקוצק, ר מרדכי יוסף מאיזביצא. אדמור בלובלין-תריד אחר פטירת רבו. חיבר \"תורת אמת\", \"אמרי אמת\". נספד מאת ר ישראל טונגלאג מוארשא ב\"אבל כבד\" - וארשא תרמט. בנו - ר אברהם מלובלין.","bk":[["תורת אמת","על התורה"]]},{"i":2701,"n":"איגר, יהודה ליב מרוטרדם","f":"עקיבא מפרשבורג","dt":"תקסט - ו אייר","b":"רב ברוטרדם, הלברשטט-תקלה. הו\"ל עם אחיו ר וולף את חדושי אביהם 'משנת דרבי עקיבא'. בניו - ר פרץ זאבל בעל \"עטרת פז\", ר אברהם ממזריטש."},{"i":2702,"n":"איגר, יוסף מהלברשטט","f":"עקיבא מהלברשטט","dt":"תריד","b":"רב בהלברשטט על מקום אביו. חיבר קונטרס \"ראשית דעת\" - ובו מתורת אביו, וכן דרושים שאמר בחבורת \"כנסת ישורון\" - בכת\"י."},{"i":2703,"n":"איגר, יעקב מאיגרא וינה קרימזא","b":"מגדולי חכמי אשכנז,מרביץ תורה,רב באיגרא,ווינה,קרימזא-ר\"י"},{"i":2704,"n":"איגר, יצחק ליב מיוהנסבורג","f":"עקיבא מפוזנא","b":"גביר מחכמי יוהנסבורג-פרוסיה."},{"i":2705,"n":"איגר, ישראל","f":"שלמה בן עקיבא מפוזנא","b":"אחיו - ר יהודה ליב מלובלין. בנו - ר שלמה."},{"i":2706,"n":"איגר, ליב מהלברשטט","f":"אליהו","dt":"תקי","b":"פרנס ומראשי קהלת הלבששטט. בנו ר שמחה ונכדו ר עקיבא איגר מפרשבורג."},{"i":2707,"n":"איגר, מאיר מברלין","f":"בונם","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":2708,"n":"איגר, משה מסובודקא","b":"פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה."},{"i":2709,"n":"איגר, נתן","b":"תשובה אליו ממהר\"ם פדובה."},{"i":2710,"n":"איגר, עקיבא","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":2711,"n":"איגר, עקיבא מהלברשטט","f":"בנימין וולף","bt":"תקכט","dt":"תקפד - כט תשרי","b":"נכד ר עקיבא בעל \"משנת רבי עקיבא\". רב בהלברשטט. בנו ר יוסף על מקומו אחריו."},{"i":2712,"n":"איגר, עקיבא מלודז","f":"אלתר עזריאל מאיר מלו","dt":"תשג","b":"חתן ר שמואל צבי מאלכסנדר. רב בועד הרבנים בלודז."},{"i":2713,"n":"איגר, עקיבא מפוזנא","f":"משה גינז","k":"רעק\"א,בעל גליון הש\"ס","r":"אב\"ד פוזנא","bt":"תקכב","bp":"פרשבורג","dt":"תקצז - יג תשרי","b":"נכד-מצד אמו של ר עקיבא בעל \"משנת רבי עקיבא\". פוסק הדור, מרביץ תורה בליסא, רב בפרידלנד-תקנא, פוזנא-תקע\"ה. חותנו של החת\"ס. נספד ב\"אבל יחיד\" לתלמידו ר רפאל פירשטנטל מברסלוי - ברסלוי תקצח. בניו: ר שלמה, ר אברהם, חתנו - ר אברהם משה קלישר ובזיוו\"ש החת\"ס, ר פישל, ר שמואל בירנבוים.","bk":[["ר' עקיבא איגר",""]]},{"i":2714,"n":"איגר, עקיבא מפרשבורג - הזקן","f":"שמחה בונם מהלברשטט","k":"בעל משנת רבי עקיבא","bt":"תפב","bp":"הלברשטט","dt":"תקיח - טו אלול","dp":"פרשבורג","b":"תלמיד ר הירש חריף ביאלער, ר יעקב הכהן מפפד\"מ בעל \"שב יעקב\", ר צבי הירש הלברשטט. ראש ישיבה בהלברשטט בהסכמת רבו. חתן ר זנויל (זאביל) לייטרסדורף מוינה (וגיסו של ר מנדל לייטסדורף מראשי קהלת פרשבורג). רב בצילץ-תקט, רב ור\"מ בפרשבורג-תקטז אצל ר משה לבוב חריף ועל מקומו אחריו-תקיח - במשך 11 יום בלבד ואז נפטר - היתה מחלוקת בקהלה בענין מינויו בין גיסו לבין מתנגדיו ובראשם ר אברהם טעבן. חיבר \"משנת רבי עקיבא\" פרשבורג תקמא. בניו: ר אריה ליב אב\"ד רוטרדם והלברשטט, ר בנימין וולף אב\"ד ליפניק. חתנו ר משה גינז אביו של ר עקיבא איגר. נכד נוסף ר עקיבא מהלברשטט."},{"i":2715,"n":"איגר, פרץ זאב (זאבל)","f":"יהודה ליב איגר","k":"בעל עטרת פז","b":"רב בברונשווייג(=ברוינשוייג)-תקע. חיבר גם \"רמון פרץ\"."},{"i":2716,"n":"איגר, שלמה אלעזר מפילוב","f":"אלתר עזריאל מאיר מלו","k":"אדמור מלובלין פילוב","b":"חתן ר דוד וידנפלד מוארשא. אדמור בפילוב על מקום אביו. נספה בשואה."},{"i":2717,"n":"איגר, שלמה מלובלין","f":"אברהם מלובלין","k":"אדמור מלובלין","bt":"תרל","dt":"תש - ג תמוז","b":"חתן ר אלתר וולשטין. אדמור בלובלין-תרעח על מקום אביו, מראשי ישיבת חכמי לובלין-תרצה. מבניו: ר אריה ליב, ר שמחה, ר עקיבא, ר ישראל מאיר, ר שלום."},{"i":2718,"n":"איגר, שלמה מפוזנא ווארשא","f":"עקיבא בעל הגליון","k":"בעל גליון מהרש\"א","r":"רב בקאליש ואח\"כ בפוזנא","bt":"תקמה","dt":"תריב - יא טבת","b":"חתן ר ישראל הירשזון-פרנס קהלת וארשא. גביר מחכמי וארשא, התרושש בזמן המרד הפולני (שתמך בו יחד עם ר חיים דוידזון ור בעריש מייזלש), ואח\"כ רב בקאליש-תקצה, פוזנא-תר על מקום אביו. הספד עליו ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. חיבר גם שו\"ת ר שלמה איגר, ספר ה\"עיקרים\", ועוד.","bk":[["גליון מהרש\"א",""],["ספר העיקרים - ביאורים בעיקרי הלכות",""],["ספר העיקרים - ביאורים בעיקרי הלכות, גליון מהרש\"א",""]]},{"i":2719,"n":"איגר, שמואל ממינסק","f":"עקיבא מפוזנא","dt":"תרז - יב תשרי","dp":"מינסק","b":"מחכמי מינסק, חברו של ר ישעיה זכריה יולס ממינסק. בנו - שלום אלעזר ממינסק."},{"i":2720,"n":"איגר, שמחה","f":"שלמה מלובלין","b":"בן האדמור מלובלין. חתן ר שמואל שמריהו היינה השני."},{"i":2721,"n":"איגר, שמחה בונם מברזאן","f":"עקיבא (בעל הגליון)","bt":"תקפא","dt":"תרכח","b":"רב בברזאן-תרח, סייע לאחיו ר איצק ליב להדפיס את ספר שו\"ע עם הגהות רע\"א."},{"i":2722,"n":"איגר, שמחה בונם מהלברשטט","f":"ליב מהלברשטט","dt":"תקכד","b":"חתן ר אברהם עקיבא הלוי מהלברשטט. גביר מחכמי הלברשטט. אביו של ר עקיבא איגר מפרשבורג."},{"i":2723,"n":"איגר, שמחה בונם ממטרסדורף","f":"משה גינז","bt":"תקל","bp":"איזנשטט","dt":"תקפט - ד סיון","b":"אחיו של ר עקיבא איגר מפוזנא. רב ברוגוזין(=ראגאזן)-פוזנא, רב וראש ישיבה במטרסדורף-תקע. פגש שם את החת\"ס ואף שידך לו את בת אחיו-ר עקיבא איגר מפוזנא. מתורתו בספרי חכמי דורו ובספרי אחיו - ר עקיבא. חתנו - ר שלמה זלמן אולמן ממאקווא בעל \"יריעות שלמה\". לתולדותיו ב\"עלי עש\"ר\", חדושי ר בונם איגר-מכון ירושלים תשנ'. בניו - ר משה גינז-שלזינגר, ר יוסף גינז-שלזינגר."},{"i":2724,"n":"איגר, שמעון צבי מקריפטש","b":"פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד, \"ועד חכמים\"."},{"i":2725,"n":"איגרא משלם בן שמשון","bt":"1752","dt":"ה'תקסב 1802","bk":[["איגרא רמה",""],["חידושי רבי משולם איגרא",""]]},{"i":2726,"n":"איגרא, אברהם יוסף מזילין","f":"אריה יהודה ליבוש","k":"אדמור מזילין","bt":"תרא","dt":"תרעה-ח -כד אלול","dp":"קראקא","b":"נכדו של ר משולם איגרא. תלמיד האדמור מקוזניץ ור חיים מצאנז. חתן ר ברוך פיירשטין, ובזיוו\"ש חתם ר מרדכי מנדבורנה. ר דוד משה מצורטקוב הסמיכו לאדמור. היה רב בבוטושן, רב ואדמור בזילין(=זעלין)-תרם על מקום חותנו, טרנוב(=טורנא)-תרנח, קשאנוב-תרנט. נפטר ללא ילדים. חיבר סידור \"אורה ושמחה\" קשאנוב תרעד, \"ליקוטי יוסף\" פאדגורזע תרעד, \"תולדות אברהם יוסף\"."},{"i":2727,"n":"איגרא, אריה יהודה ליבוש מגריצא","bt":"תקס","dt":"תרל","b":"תלמיד ר חיים מצאנז, אב\"ד גריצא, טורבין וזלישטשיק. חתן ר צבי הירש מנדלסבורג. בנו ר פסח דוד על מקומו כאדמור."},{"i":2728,"n":"איגרא, יעקב","dt":"קט","b":"עק\"ה, מגדולי חכמי אשכנז הקדמונים באיגרא"},{"i":2729,"n":"איגרא, יצחק אליהו","f":"משלם","bt":"תקמד","dt":"תקסד","b":"בנו היחיד של של ר משולם. חתן דודו ר ישכר בעריש אב\"ד הנובר. נפטר בצעירותו ללא בנים."},{"i":2730,"n":"איגרא, ישכר בער מלבוב","f":"משה","b":"רב בלבוב-תצ, חתם-תקכב עם ר יחיאל מיכל בריסקר, ור אהרן ישכר בער בן יוסף, חתם-תקכב, תקכח, ועוד. הסכים על \"קהלת יעקב\"-תקיט."},{"i":2731,"n":"איגרא, ישעיה יעקב מסטרי","f":"ישראל","bp":"סטרי","b":"דיין בסטרי-תרלו, מצאצאי ר משולם, חתן ר חיים יעקב דומיניץ מניישטט."},{"i":2732,"n":"איגרא, משה משלם מטיסמניץ","f":"שמשון מבוצאץ","k":"בעל איגרא רמא","bt":"תקי-יב","bp":"בוצאץ","dt":"תקסב","dp":"פרשבורג","b":"חתן הגביר ר שמואל ביק מברוד, ובזיוו\"ש חתן ר יצחק הורביץ-אב\"ד ברוד. אב\"ד מחוז סטניסלב בעיר טיסמניץ בגיל 17. מתלמידיו החוות דעת, בעל קצות החושן, ועוד. עזב לאחר עשרים שנה בגלל מחלוקת עם החסידים ועבר לפרשבורג-תקנד על מקום ר מאיר ברבי (לפי מורשת הונגריה על מקום אביו ר מאיר ברבי - וכנראה טעות). (זקני בוצאץ דורות אחריו היו עומדים מלא קומתם כשהיו מזכירים דבר תורה משמו). ספר תולדותיו \"גרם המעלות\". חיבר \"איגרא רמה\" (ראשי תיבות רמ\"ה הרב רבי משולם) למברג תרלג, ועוד. הניח אלפי גליונות של חידושי תורה שחלקם נלקחו והודפסו על ידי זרים שלא ברשות. מתלמידיו: ר נפתלי צבי מרופשיץ, ר יעקב ליסא בעל \"חוות דעת\", ר משה מינץ מאופן, ר ברוך פרנקל בעל \"ברוך טעם\", ר יצחק משה פרסל, ועוד."},{"i":2733,"n":"איגרא, נתן","b":"מגדולי הפוסקים בחכמי אשכנז,מרביץ תורה בנירנברג,רב באיגרא,עלה לירושלים-ר\"כ"},{"i":2734,"n":"איגרא, צבי הירש מיברוב","b":"רב ביברוב-תרכב."},{"i":2735,"n":"איגש, חיים יהודה ליב מקובנה","bt":"תקנט","dt":"תרלז","dp":"ירושלים","b":"רב בקובנה, עלה לירושלים. בנו ר שמחה ראובן בעל \"דורשי רשומות\"."},{"i":2736,"n":"איגש-אדלמן, חנוך הניך מוילנא","f":"שמחה ראובן איגש-אדלמ","k":"בעל מרחשת","bt":"תרכד","bp":"ראסיין","dt":"תשא - טו אלול","dp":"וילנא","b":"מו\"צ בוילנא-תרנח, ולאחר פטירת ר חיים עוזר גרודזנסקי היה זקן רבני וילנא. עמד בראש מוסדות תורניים וחינוכיים, חבר המזרחי-עד תרפו. חיבר גם \"מנחת חנוך\", ועוד. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ. חיבר \"מנחת חנוך\" ונדפס בסוף \"עולת שמואל\" לר שמואל ליובצער מוילנא-אבי חותנו. פרסם מחאה עם גדולי הרבנים ב\"המסלה\" - נ\"י תרצו - כנגד תקנת הקונסרבטיבים בענין גט על תנאי שימסר לאישה מיד אחר הקידושין.","bk":[["מרחשת","מערכות"]]},{"i":2737,"n":"איגש-אדלמן, מרדכי יצחק","f":"שמחה ראובן","k":"בעל חכם ושר","bp":"ראסיין","dt":"תרס. - בערך","b":"מחכמי ביאליסטוק. אחיו של ר חנוך הניך איגש. חיבר ספרים רבים ובהם: \"חכם ושר\" לתולדות אביו, \"ידות המדות\", ועוד."},{"i":2738,"n":"איגש-אדלמן, שמחה ראובן","f":"חיים יהודה ליב מקובנ","k":"ש\"ר העדולמי-התירוש","r":"אביו של המרחשת מכונה השר העדולמי","bt":"תקפא","bp":"ראסיין או וילנא","dt":"תרנג - כב טבת","dp":"וארשא","b":"בן למשפחת סולוביציק. בקי בספרות ופילוסופיה, לוחם נגד פורקי האמונה. רב-שנת תרל. חיבר \"שושנים\", \"המסילות\", \"התירוש\", ועוד. פרסם מאמרי ביקורת כנגד מהר\"א צוויפל מביהמ\"ד בזיטומיר, כנגד \"משפחת סופרים\" (בתוך \"הכרם\" לאליעזר אטלס), כנגד \"דור דור ודורשיו\" לוייס - בשם \"דורש רשומות\", ועוד. בניו ר חנוך הניך מוילנא, ר מרדכי יצחק אדלמן בעל \"מערת עדולם\".","bk":[["דרושי רשומות",""],["המסילות",""],["השושנים",""],["התירוש",""]]},{"i":2739,"n":"איגשטטר, שמואל הלוי מהמבורג","f":"שלמה","bt":"תקסג","dt":"תרכג","dp":"אלטונא","b":"מחכמי הקלויז של ר ליב בר שאול בהמבורג על מקום ר משה שלזינגר, יחד עם ר אברהם בן יחזקאל זיטנפלד, ר חיים נתנזון. הערות ממנו בסידור \"עבודת ישראל\"-רדלהיים."},{"i":2740,"n":"אידלביץ, לוי יצחק","b":"גבאי האדמור מוהר\"ש - לובאביטש."},{"i":2741,"n":"אידלביץ, משה מרדכי מסמרגון","b":"גביר בסמרגון. גיסו - ר אליעזר גורדון מטלז. חתנו - ר שמעון שקופ."},{"i":2742,"n":"אידלברג, דוד","dt":"תשג","b":"רב בפלאצק"},{"i":2743,"n":"אידלברג, מרדכי דוב מקאנטיקוזיו","f":"יצחק","k":"בעל חזון למועד","bt":"תרמא","bp":"ביאליסטוק","dt":"תשב - ה חשון","b":"רב בליסקובה(=ליסקאווא)-פלך סובאלק-תרסז, קנטיקוזיב(=קאנטיקוזיווא)-פלך חרסון-תרע, ניקולייב, מאקוב, פלאצק-תרפה. על הספר בתוך \"תבונה\" - לודז תרפב."},{"i":2744,"n":"אידלזק, שמואל מיאנישוק ות\"א","f":"אברהם אבא","k":"בעל דברי שמואל-תשא","bt":"תרכב","bp":"יאנישוק","dt":"תשז","dp":"תל אביב","b":"תלמיד ישיבות טלז, סלובודקה, איישישוק. ר\"מ בישיבת דובנא-תרנד, איישישוק-תרנט, עלה לארץ-תרפה והיה ממייסדי ישיבת \"בית יוסף\" ו\"עטרת יוסף\" בתל אביב. עסקן ציבור. פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":2745,"n":"אידליס, נתן פייטל מקאשוי","dt":"תשד","b":"רב בקאשוי"},{"i":2746,"n":"אידליץ, זרח ניישטטל מפרג","f":"מאיר","k":"בעל אור לישרים","dt":"תקמו - יב אייר","dp":"פרג","b":"תלמיד ר יונתן איבשיץ. רב בפרג, בקי בחכמות ומדעים. חיבר גם \"מלאכת מחשבת\" על הלוח העברי, ונדפס חלק ראשון בשם \"מלאכת החשבון\" פרג תקלה. נספד מאת ר אליעזר פלעקלס."},{"i":2747,"n":"אידלסון, א.צ.","b":"פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה."},{"i":2748,"n":"אידלסון, אברהם","f":"דוד","bt":"1865","bp":"ואקשנה","dt":"1921","dp":"ברלין","b":"עתונאי ומנהיג ציוני. עורך \"יעוורייסקאיה זיזן\", ועוד. חבר בארגונים ציוניים. עורך \"העולם\" בלונדון-1920. קובץ מאמריו נדפסו ב-1919. לזכרו \"ספר אידלסון\" - ת\"א 1946."},{"i":2749,"n":"אידלסון, אברהם מארה\"ב","b":"רב בסאוואנה-ג'ורג'יה. פרסם מאמרים ב\"יגדיל תורה\"-תרעו."},{"i":2750,"n":"אידלסון, וולף","k":"דיאוגן","bp":"ליטא","dt":"1866","dp":"אודסה","b":"מחלוצי ההשכלה. תלמיד ר מנשה מאילייה. מורה בבריסק, עבר לדובנא - נרדף ע\"י החסידים ועבר לאודסה. רוב כתביו נשרפו. מתלמידיו המדקדק חיים צבי לרנר, והצנזור הרוסי ולדימיר פיודרוב (ביהדותו - גרינברג). חיבר מסת בקורת על \"מגלת אסתר\"."},{"i":2751,"n":"אידלסון, יהודה אידל זלאצאווסקי","f":"חיים","bt":"תרלד","bp":"נווהארדוק","b":"מצאצאי ר חיים סנדר מנישוועז, ונכד ר דוד זאווילס מסלונים. חתן ר שבתי יעקב בן אברהם יצחק מסלצניק-ליד וילנא. תלמיד ישיבת מיר, קבוץ איישישוק, ר אליהו משה מזאלודאק-ליד לידא, כולל קובנא. רב בדנוור-ארה\"ב-תרסא. נסמך מאת: ר שלמה הכהן מוילנא, ר צבי הירש רבינוביץ מקובנא, ר משה מסלובודקא, ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\". הניח דרשות - בכת\"י."},{"i":2752,"n":"אידלציק, אברהם חיים מקכנוב","f":"יהודה אידל צדוק","bt":"תרכג","b":"תלמיד ישיבת וולוזין. מו\"צ בסלאוויאני-תרן, רב בקכנוב(=קאחאנאוו)-פלך מוהילוב-תרנד. נסמך מאת: הרידב\"ז, ר צבי הירש ליפמן מאיהומען. מחותן עם ר אברהם רבינסקי מדובראוונא."},{"i":2753,"n":"אידלש, אברהם צבי הירש מקרומונו","k":"בעל נוית ברמה","b":"רב בקרומונו-תק\"ס"},{"i":2754,"n":"אידלש, ישראל מלבוב","f":"יוסף","k":"חותן הסמ\"ע","b":"גביר, ראש ומנהיג בלבוב, החזיק ישיבה, בנה בתי כנסת, השיא בנות ישראל, נדב לעניי א\"י. חתנו - בעל הסמ\"ע הזכירו בספרו וקרא לו \"בית ישראל\" לכבודו."},{"i":2755,"n":"אידלש, מרדכי מפלאצק","dt":"תשג","b":"רב בפלאצק"},{"i":2756,"n":"אידלש, שלמה זלמן מטשעטשביץ","dt":"תשד","b":"דומ\"צ בטשעטשעוויץ-תרע\"ד"},{"i":2757,"n":"אידלש, שמואל - מהרש\"א","f":"יהודה הלוי","k":"מהרש\"א","bt":"שטו","bp":"קראקא","dt":"שצב - ה כסלו","b":"גדול חכמי דורו. מצאצאי ר עקיבא הכהן מאויבן. חתן ר משה ליפשיץ מבריסק-גיסו של ר משה אשכנזי בעל \"זכרון משה\", וחותנתו אידל החזיקה את ישיבתו בפוזנן כ-20 שנה בשנים שמה-שסה - ומכאן שמו \"אידלש\". מפרש התלמוד, רב בטיקטין, פוזנא, חעלמא, לובלין, אוסטרהא-שעו, מחבר חדושי הלכות ואגדות על הש\"ס. (בן דודו של בעל הט\"ז - ב\"אוצרות חיים\" מביא שאביו יהודה היה אחיו של ר שמואל אביו של בעל הט\"ז). חתניו: ר יצחק בן שלמה סגל מלבוב נכד בעל \"שארית יוסף\". ר יצחק רבי בונמש מלובמלא ולובלין בעל \"מהדורא בתרא\"."},{"i":2758,"n":"אידנשטין, מאיר ישראל מקישינוב","b":"פרסם מאמר תמיכה בר יהודה ליב צירלזון מקישינוב ב\"שערי תורה\" - וארשא תרסג-תרצט - בענין חזרתו מהסכמה לרבנות בראדום."},{"i":2759,"n":"איוב ן, שלמה מספרד ופרובנס","f":"יוסף","k":"בעל שר המשקים","bp":"גרנדה-ספרד","dt":"כד - אחרי","b":"חכם, מדען, פילוסוף, רופא בספרד, עבר לבדרש-פרובאנס-שנת י', ותרגם שם את \"ספר המצות\" לרמב\"ם, ועוד. חיבר גם \"ספר הטחורים\"."},{"i":2760,"n":"איזגור, אהרן הלוי מקיוב","k":"בעל שלוש תקופות","bt":"תרלד","bp":"ברזינא-פלך מינסק","b":"תלמיד ישיבות ובקי בשפות. מורה בקיוב-תרנג וחברם של שאצקעס, ויסברג. פרסם ב\"הצפירה\", \"המליץ\", ועוד. חיבר \"שלש תקופות בדברי הימים לב\"י."},{"i":2761,"n":"איזיוידו, דוד","b":"רב הספרדים באמסטרדם-תק\"מ"},{"i":2762,"n":"איזלנד, יעקב (ינקל) מפשצלוב","b":"רב בפשצלוב, תשובה אליו בשות מהרשם."},{"i":2763,"n":"איזלנד, ראובן","b":"מופיע בספר רדומישל 830."},{"i":2764,"n":"איזלר, מתתיהו מקלויזנבורג","bt":"1865","dt":"1930","b":"תלמיד ביהמ\"ד לרבנים בבודפשט, ד\"ר לפילוסופיה. רב הקהילה הניאולוגית (קונגרסאית) בקלויזנבורג-1891. היסטוריון וחוקר תולדות היהודים בטרנסילבניה. בלשן ובקי בלשנות שמיים."},{"i":2765,"n":"איזן, אביגדור מווריש","f":"פנחס (כנראה)","bt":"תקף","dt":"תרם","b":"רב בוואריש, חתן ר יצחק לנגנר אב\"ד טרטקוב. בנו ר חיים אב\"ד סוירז."},{"i":2766,"n":"איזן, אברהם אביש מרדכי","f":"פנחס","bt":"תקפב","dt":"תרם","b":"רב בווברניפקה וברוזדוביץ, בנו ר יהושע השל היה רב בווברניפקה ועלה לצפת."},{"i":2767,"n":"איזן, אברהם אביש מרדכי מצפת","f":"יהושע השל","bt":"תרמא","bp":"גליציה","dt":"תרצה","b":"עלה לצפת עם הוריו בילדותו, בגיל שש עשרה נסע לגליציה וקיבל סמיכה מהמהרש\"ם. חתן ר שלמה זלמן פרידמן, עבר לירושלים. היה עוזרו של הרידבז וסייע לו להכין לדפוס את \"פאת השלחן\" עם \"בית רידבז, והיה מעורב בפולמוס השמיטה-תרע. מתורתו בכתב עת ובספרי חכמי ירושלים. בנו ר פנחס - תלמיד ישיבת \"תורת חיים\"."},{"i":2768,"n":"איזן, אברהם מפודהייץ","f":"חיים","bt":"תרם","dt":"תשג","b":"ראב\"ד פודהייץ-תרסז, נספה בשואה."},{"i":2769,"n":"איזן, אורי מסטרטין בוברקא","f":"חיים מסווירז","k":"אדמור מסטרטין בבוברק","r":"אדמו\"ר משאץ - לונדון","bt":"תרלו","dt":"תרצו - כב טבת","b":"חתן דודו ר יחיאל מיכל הורודנר. רב בסוירז, בסטרטין, ברזן, אדמור מסטרטין בבוברקא-תרף. חיבר \"יאיר חיים\" בכתב יד.","bk":[["יאיר חיים",""]]},{"i":2770,"n":"איזן, אליעזר מאיסטריק","f":"נחמיה","k":"בעל ארבעה טורים אבן","bt":"תקץ","dt":"תרנה","b":"רב באיסטריק. חיבר \"ארבעה טורים אבן\" פשמישל תרמו. בנו ר אלתר שלום יוסף - שו\"ב באיסטריק."},{"i":2771,"n":"איזן, גבריאל מקראקא","b":"מחכמי קראקא."},{"i":2772,"n":"איזן, חיים הלוי מסווירז","f":"אביגדור מואריש","k":"בעל שמות אנשים","bt":"תריב","dt":"תרסח","b":"שו\"ב בנריוב, רב בווריש, סווירז, חתן דודו ר יהודה צבי השני מסטרטין. חיבר \"שמות אנשים\" בכתב יד."},{"i":2773,"n":"איזן, יהושע השל מוברניפקה","f":"אברהם אביש מרדכי","bt":"תרה","dt":"תרעה","b":"רבה של ווברניפקה, בשנת תרמא עלה לצפת, ואחר כך לירושלים, היה מחסידי קרלין סטולין. בנו ר חיים יצחק אייזיק שנולד בצפת היה לימים מזכירו של השדי חמד בחברון."},{"i":2774,"n":"איזן, יחזקאל משנדישב","b":"דומ\"ץ בשנדישב וירוסלב. בנו ר יעקב כיהן אחריו בירוסלב."},{"i":2775,"n":"איזן, משה הכהן מטרנופול","k":"בעל שלומה של מלכות","bt":"תקע","dt":"תרך","b":"רב בטרנופול. חיבר \"שלומה של מלכות\" למברג תריא."},{"i":2776,"n":"איזן, משה מרדכי מרימנוב","b":"רב ברימנוב. תשובות אליו בספרים \"אמרי יושר\", שות מהרשם, ועוד."},{"i":2777,"n":"איזן, משה פנחס מברוד","f":"חיים מסווירז","k":"אדמור מסטרטין בברוד","bt":"תרמג","dt":"תשג","b":"בנו של אב\"ד סוירז, חתן דודו ר ישראל לנגנר מברודי וכיהן אחריו כאדמור מסטרטין בברודי. נספה בשואה."},{"i":2778,"n":"איזן, פנחס מווריש","b":"רבה של וואריש, בניו ר אביגדור שכיהן כרב אחריו, ור אברהם אביש מרדכי."},{"i":2779,"n":"איזן, פנחס מווריש (הנכד)","f":"אביגדור","bt":"תרה","dt":"תרעה","b":"רב בוואריש על כסא אביו-תרמו."},{"i":2780,"n":"איזן, שלום מירושלים","f":"אברהם אבוש מרדכי","bt":"תרעו","dt":"תשמח","dp":"ירושלים","b":"תלמיד \"עץ חיים\". רב בירושלים. פרסם מאמרים ב\"תורת בית הוראה\" - ירושלים תשג - קובץ ישיבת רבנו חיים יוסף."},{"i":2781,"n":"איזן, שלמה מויליפולי","f":"אברהם","dt":"תש..","b":"דומ\"ץ ויליפולי עד השואה נספה בשואה. חתן רצ\"ה שלזינגר הי\"ד. אחיו ר מנחם איזן היה חמיו של ר שלמה דימנט מסטריזוב."},{"i":2782,"n":"איזנבוד, אליהו מהורודשיץ","f":"אליעזר","bt":"תרלז","dt":"תשג","b":"נכד ר בן ציון איזנבוד מנעשויז, ונכד-אבי אמו ר אלימלך מלידא. תלמיד ישיבת וולוזין. חתן ר יוסף דוד רובינשטין מואשלישוק. רב בסטולביץ-תרסד, הורדשיץ(=האראדישטץ)-פלך מינסק (יש עוד ערים באותו השם - בפלך פולטובה ובפלך קיוב)-תרסז, ואשילישוק על מקום חותנו."},{"i":2783,"n":"איזנבוד, נח מפינסק","f":"אליהו איזנבוך","dt":"תשב","b":"ר\"מ בישיבת פינסק. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":2784,"n":"איזנבוים, זלמן צבי מאלכסנדר","b":"פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":2785,"n":"איזנבט, משה מאלגיר","f":"זאב","dt":"תשיח","b":"רב קהילות אלגיר-תרפח-תרצב מטעם הקונסיסטואר בצרפת. חתם על תשובה בשו\"ת ר א' הלוי פינגהרוט. פרסם מחקרים לתולדות יהודי אלגיר וצפון אפריקה, פעל מול הרשויות בזמן מלחמת העולם השניה."},{"i":2786,"n":"איזנבך, זאב וולף מצאנז","b":"מחכמי צאנז. חתן הגביר ר יצחק וילדשטין מקרניץ. רב בשיניבה."},{"i":2787,"n":"איזנבך, יהושע מפריסטיק","f":"יצחק אייזיק","k":"בעל אותות ומועדים","bt":"תקף","dt":"תרך","b":"דומ\"ץ בפריסטיק, חסיד ר צבי אלימלך מדינוב, ובנו ר אלעזר מלנצהוט. חיבר \"אותות ומועדים\" ברטפלד תרסד."},{"i":2788,"n":"איזנבך, יחיאל מיכל","f":"זאב וולף","bt":"תרפה","dt":"תשנג","b":"ניצל מהשואה - היה בסיביר. עלה לארץ-תשי. חסיד בלז. חתן ר מרדכי יהודה אינפלד."},{"i":2789,"n":"איזנבך, שלום ליב מירושלים","f":"אברהם","k":"בעל ביאר יצחק","bt":"תרכה","bp":"פעסט","dt":"תרעח","dp":"ירושלים","b":"מחכמי ירושלים עלה מהונגריה עם אביו בשנת תרלח. חיבר \"באר יצחק\" ו\"תכלת מרדכי\" ירושלים תרעא. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד, \"אור תורה\", ו\"תל תלפיות\", \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":2790,"n":"איזנברג, אברהם חריף מאולינוב","f":"יצחק חריף-האלף לך של","k":"בעל תולדות אברהם","bt":"תקמב","dt":"תקפד - ב תשרי","dp":"אולינוב","b":"רב בגלינא(=גלוגא), אולינוב-תקעג על מקום אחיו ואביו, חסיד ר נפתלי צבי מרופשיץ שהעריכו מאוד ואמר עליו \"הלואי והייתי מיחד יחודים.. מה שמייחד ר אברהם בשעתיים\". חיבר \"תולדות אברהם\" פרזמישל תרמב, \"זרע יצחק\". בנו - ר משה יוסף מפרוכניק."},{"i":2791,"n":"איזנברג, אברהם שלמה מקראקא","b":"רב בביהמ\"ד \"בקור חולים\" בקראקא-תרצד."},{"i":2792,"n":"איזנברג, אליעזר מנמעסטא","f":"אברהם מאונגוואר","dt":"תרנט - בערך","b":"תלמיד השב\"ס. עבר לאונגוואר לאחר נישואיו. רב באודווארד-תרמא, וואג-שעליע-תרמו, שו\"ב בוועטש-תרמז, נאמעסטא-תרמט."},{"i":2793,"n":"איזנברג, דוד מלאסק","f":"יהודה ליב מלאסק","b":"נכד(-אבי אמו) ר צבי אריה יעקב מלאסק. (אביו נספה בשואה - לא ידוע אם גם הוא נספה)."},{"i":2794,"n":"איזנברג, יהודה ליב מלאסק","f":"יוסף","bt":"תרן","bp":"פיעטרקוב","dt":"תשג","b":"חתן ר צא\"י יעקב מייזלש בעל \"חדות יעקב\" מלאסק, רב בלאסק-תרעג לצד חותנו ועל מקומו אחריו-תרצג. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג. בזמן השואה הבין כי זו מלחמת שמד והורה ליהודים למרוד בנאצים, סירב להוראה לשרוף את ביה\"כ בלאסק והספיקו להחביא את ספרי התורה. נרצח במחנה חלמנו. כתביו אבדו בשואה. בנו - ר דוד."},{"i":2795,"n":"איזנברג, יונה מבוצאץ","b":"מחכמי בוצאץ-תריד."},{"i":2796,"n":"איזנברג, יוסף משה מפינסק וצפת","f":"יקותיאל זלמן חריף","k":"בעל חלוקא דרבנן","bt":"תסה","dt":"תקמא (ולא תקי)","dp":"צפת","b":"סבו מצד אמו ר משה אלימלך פילוט אב\"ד סטרי שהיה דור י\"ג ברבנות. חתן ר יהודה בן יצחק מפינסק. רב בדרוגאטשין(=דרגיטשין) (ליד פינסק), פינסק-תקה, סמבור-תקכז ובנו ר יצחק חריף על מקומו אחריו, עלה לצפת-תקלה ונפטר שם. חיבר גם \"מגיד משנה\" והוא פירוש ל\"משנת חסידים\", \"קרית ארבע\" בקבלה זולקווא תקכה, ועוד."},{"i":2797,"n":"איזנברג, יעקב נפתלי מסמבור","f":"יצחק חריף מסמבור","k":"יעקב הייזלבך - ה\"ב","bt":"תקם","dt":"תקפה","dp":"אולינוב","b":"כינה עצמו גם ה\"ב (ראשי תיבות של הר ברזל), רב בטורקא, אולינוב-תקעב על מקום אביו, סמבור-תקעג על כסא אביו. חיבר \"אמרי מהרין\" יאראסלויא תרסח."},{"i":2798,"n":"איזנברג, יצחק חריף מסמבור","f":"יוסף משה חריף","k":"בעל פני יצחק","bt":"תק","dt":"תקעג","b":"תלמיד ר יונתן איבשיץ, חתן ר שמואל מסמבור. רב באולינוב ובנו ר אברהם על מקומו אחריו, סמבור על מקום אביו ובנו ר יעקב נפתלי על מקומו אחריו. הוצעה לו רבנות פרשבורג-תקנב אולם ראש הקהל העלים ממנו את המכתב ואת הרבנות קיבל ר משלם איגרא (וקיבל את הסכמתו של ר יצחק - לאחר שנודע לו על הענין). חיבר \"האלף לך שלמה\", \"פני יצחק\" ביאראסלויא תרסה, ועוד."},{"i":2799,"n":"איזנברג, ירוחם ישכר בריש מקראק","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":2800,"n":"איזנברג, ישעיה מקלוואריה","f":"יחיאל מיכל","bt":"תרסב","bp":"קלווריע","dt":"תש..","b":"תלמיד ישיבת בובוב בקראקא. נספה בשואה."},{"i":2801,"n":"איזנברג, ישראל איסר יונה","f":"צבי","bt":"תקצה","dt":"תרנט","b":"תלמיד ר יוסף חריף מזבורוב. אחיו של ר עוזר מידלובה ור יושע מזמיגרוד. מצאצאי ר יונתן איבשיץ, דיין בזמיגרוד-תרכט, ראב\"ד בוקובסק, רב בדינוב. חסיד ר אליעזר מדזיקוב. בניו ר יעקב מצאנז ור ראובן. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד."},{"i":2802,"n":"איזנברג, מנחם מנדל מקראקא","f":"שמואל","b":"מחכמי קראקא. תשובה אליו ב\"שנות חיים\"."},{"i":2803,"n":"איזנברג, משה יוסף מפרוכניק","f":"אברהם","bt":"תקפג","dt":"תרלג","b":"אב\"ד פרוכניק, חתנו היה ר פסח שפירא בן מאיר בנו של הבני\"ש."},{"i":2804,"n":"איזנברג, עוזר מידלובה","bt":"תקע","dt":"תרל","b":"רב בידלובה, ברזסטוק, דמביץ. היה תלמיד ר צבי הירש מרימנוב, ואחר כך של ר חיים מצאנז. אחיו היו ר ישראל איסר יונה, ור יהושע."},{"i":2805,"n":"איזנברג, פייביש מאוזיראן","b":"מחכמי אוזריאן, חתנו של הבמ\"ח. תשובה אליו בספר \"שירי טהרה\"."},{"i":2806,"n":"איזנברג, צבי הירש מקשנוב","f":"חיים","b":"מחכמי סוסנוביץ. אביו היה בנו של ר חיים הדיין מקשאנוב. למד אצל רד\"ב וידנפלד מטשעבין. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":2807,"n":"איזנברג, ראובן מזמיגרוד","f":"ישראל איסר","bt":"תרל","dt":"תש","b":"דיין בזמיגרוד על כסא אביו, חתן ר יחיאל אנגלהרדט-אנגל. בניו ר ישראל יונה ויוחנן היו תלמידי ישיבת עץ חיים בבובוב. פרסם מאמרים ב\"אסיפת חכמים\" - אושפצין תרצד."},{"i":2808,"n":"איזנברג, שלום מקשאנוב","b":"אביו היה מחכמי קראקא ונפטר בן 104. חתן ר אבא מקשאנוב. דומ\"ץ בקשאנוב(=קרשנוב)-תרסה. חסיד רדומסק. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":2809,"n":"איזנברגר, גאזא מגודולו","dp":"אושוויץ","b":"רב (ניאולוגי?) בגודולו-1926. חיבר תחינה בימי הצער (בזמן השואה). חיבר \"תפלות לפני ארון הקודש\" - בהונגרית. נספה בשואה."},{"i":2810,"n":"איזנברגר, משה אברהם מניר","f":"דב בריש מפפדמ","bt":"תקפד","bp":"נאמסטא (אראווא)","dt":"תרן - י שבט","dp":"ניר-קאראס","b":"תלמיד החת\"ס. חתן ר אליעזר צבי אלפנט. חתנו ר אלחנן דב כץ על מקומו אחריו."},{"i":2811,"n":"איזנטל, אלימלך","f":"פנחס מגניווישוב","dt":"תרכא - ל תשרי","b":"היה חסיד חשוב בעיני ה\"דברי חיים\" מצאנז ור שלמה מראדמוסק."},{"i":2812,"n":"איזנטל, פנחס מגניווישוב","dt":"תקעד","b":"תלמיד ר אלימלך מליזנסק, ואדמור בגניווישוב אחר פטירת רבו. היה נוסע אל החוזה מלובלין. בנו ר אליעזר."},{"i":2813,"n":"איזנמן, ברוך ממינסק וארה\"ב","bt":"תרא","dt":"תרצב - יג כסלו","b":"דרשן במינסק,רב בברוקלין"},{"i":2814,"n":"איזנמן, יוסף הלוי","f":"אברהם שמחה","bt":"תרלו","bp":"טישוביא-פלך לובלין","b":"תלמיד ישיבות בריסק, סלובודקה, קובנה. נסמך מאת: ר משה דנישבסקי, ר צבי הירש רבינוביץ מקובנה, הגדול ממינסק, ר יהודה ליב צירלסון מפרילוק-קשינוב. רב ברוסטוב-תרס, היגר לארה\"ב-תרע, רב בביהכ\"נ \"עמנואל\" ו\"בני יעקב\" בדטרויט-מישיגן, חבר אגודת הרבנים, ועוסק בפעילות ציבורית."},{"i":2815,"n":"איזנמן, משה מדומברובא","b":"פרסם מאמרים ב\"התפוח\" - בנדין תרפח."},{"i":2816,"n":"איזנצויג, יעקב אריה מוארשא","dt":"תשג","b":"רב בנובומינסק, מו\"צ בוארשא. פרסם מאמרים ב\"עמק הלכה\" - וארשא תרפו."},{"i":2817,"n":"איזנר, אברהם אבא מטשבין","f":"דב בריש","k":"בעל תולדות הגאון דוד","bt":"תרלב","bp":"טשבין - טרשעבין","dt":"תש","dp":"טשבין","b":"חתן ר יעקב וינר מקשאנוב. עבר לברסלוי. מצאצאי ר דוד לידא וחיבר 'תולדות הגאון ר דוד לידא'."},{"i":2818,"n":"איזנר, אברהם אבוש מקרליפקה","k":"בעל אוהב שלום","bt":"תרו","bp":"קורולובקה","dt":"תרצד","b":"רב בהוש (רומניה), בגרידונג, קרליפקה (גליציה). התפטר מרבנותו והתפרנס מחנות ספרים. ייסד עתון הצופה לחדשות ודברי עיון (יצאו 2 חוברות בלבוב תרלח)."},{"i":2819,"n":"איזנר, יוסף יהושע מפיטשניזין","f":"משה","bt":"תרכה","dt":"תרץ - בערך","b":"מו\"ץ בפיטשניזין. תשובות אליו ב\"אמרי יושר\"."},{"i":2820,"n":"איזנר, נתן נטע שמואל מטלומטש","f":"משה","bt":"תרי","bp":"טלומטש","dt":"תרצד","b":"ראבד בטלומטש, בשנת תרעד עם הכיבוש הרוסי הוגלה לזלוצוב ואחר כך להונגריה עד חזרתו בשנת תרעז"},{"i":2821,"n":"איזנרוד, נח","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":2822,"n":"איזנשטאדטער, אהרן משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":2823,"n":"איזנשטאדטער, אנשל משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":2824,"n":"איזנשטאדטער, גבריאל משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":2825,"n":"איזנשטאדטער, שלמה משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":2826,"n":"איזנשטט מנחם בן מאיר","bt":"1808","dt":"ה'תרכט 1869","bk":[["זכרון יהודה",""],["חומת אש",""]]},{"i":2827,"n":"איזנשטט, אברהם מארה\"ב","dt":"תרמז","b":"רב בארה\"ב"},{"i":2828,"n":"איזנשטט, אברהם מליובטש","f":"צבי הירש א\"ש","b":"רב בליובטש"},{"i":2829,"n":"איזנשטט, אברהם צבי הירש","f":"יעקב מביאליסטוק","k":"בעל פתחי תשובה","bt":"תקעג","bp":"ביאליסטוק","dt":"תרכה-ח - ב אלול","dp":"קניגסברג","b":"נכד(-אבי אמו) - ר נפתלי הורביץ מזולקוא. רב בברסטוביץ-תקצו, אוטיאן-תרטז. חיבר גם \"נחלת צבי\", ועוד. בניו - ר נפתלי מוילנא, ר בנימין מאומיאן ונכדו הסופר ליאון רבינוביץ עורך \"המליץ\".","bk":[["פתחי תשובה","מפרשי שו\"ע"],["נחלת צבי [אייזנשטט]","מפרשי שו\"ע"]]},{"i":2830,"n":"איזנשטט, אברהם צבי מאוטיאן","f":"בנימין מאוטיאן","bt":"תרלא","bp":"אוטיאן-ליטא","dt":"תרצט - ל תשרי","dp":"אוטיאן-ליטא","b":"רב באוטיאן על מקום אביו כ-20 שנה, גלה לפרייל-בלמחה\"ע ה-I. פעל להפצת הרעיון הציוני."},{"i":2831,"n":"איזנשטט, אהרן מליפקוב","f":"צבי הירש א\"ש","b":"רב בליפקוב"},{"i":2832,"n":"איזנשטט, אליהו עקיבא","f":"אלימלך א\"ש","b":"ראב\"ד בלידא"},{"i":2833,"n":"איזנשטט, אלימלך מלידא","f":"צבי הירש א\"ש","b":"רב בלידא-תק\"ע-ת\"ר"},{"i":2834,"n":"איזנשטט, אליעזר משידלובצא","f":"מאיר - פנים מאירות","b":"רב בשידלובצה"},{"i":2835,"n":"איזנשטט, אלתר מנ\"י","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":2836,"n":"איזנשטט, בן ציון מניו יורק","f":"משה","k":"בעל דורות האחרונים","bt":"תרלג","bp":"קלעצק-פלך מינסק","b":"תלמיד ר יוסף בישיבת נעשויז, ר יהושע רבינוביץ בנעשויז, ר נתן נטע מקלעצק בעל \"נתיבות אור\". דרשן, רב ברוסיה, ניו יורק-תרסז, חיבר גם \"דור רבניו וסופריו\", ועוד. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד, \"בית ועד לחכמים\" - נ\"י תרסג, \"כנסת הגדולה\" - וארשא תרן, \"המגיד\" - סטמר תרפח-תרצט."},{"i":2837,"n":"איזנשטט, בנימין מאוטיאן","f":"אברהם צבי מאוטיאן","k":"בעל משאת בנימין","bt":"תקצח-תרו","bp":"ברסטוביץ-פלך גרודנא","dt":"תרפ - יב שבט","b":"חתן ר אהרן זליג ציוני. רב באוטיאן-תרכח על מקום אביו-בגיל 22, והשופט בעיר היפנה אליו מתדיינים בענינים אזרחיים, גלה ללטביה-במלחה\"ע ה-I, וחזר לאוטיאן-ישב ברבנות שם מעל 50 שנה. מחדושיו בספר חותנו \"שות ציוני\"."},{"i":2838,"n":"איזנשטט, בנימין מאונגריש ברוד","f":"מאיר - פנים מאירות","dt":"תקל - טז ניסן","b":"רב באונגאריש ברוד,זאגור,לקנבך"},{"i":2839,"n":"איזנשטט, בנימין מרוזינאי","f":"אייזיק","dt":"תרז - א תמוז","b":"דיין ברוזינאי-תק\"ס"},{"i":2840,"n":"איזנשטט, ברוך בן ציון מאמדור","k":"בעל אמרי ברוך","b":"אב\"ד אמדור. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. גיסו של ר אביגדור מרדכי כץ מגראיעווע בעל \"ענבי הגפן\"."},{"i":2841,"n":"איזנשטט, דב בר מלכוביץ","b":"אב\"ד לכוביץ. נכדו ר מנחם צבי רב בקראקא - ניו יורק."},{"i":2842,"n":"איזנשטט, דוד מסוברנץ ואונגוואר","f":"מנחם מאונגואר","bt":"תקצא","dt":"תרכד - בערך","dp":"[אונגואר]","b":"חתן הגביר ר יוסף יוחנן כהנא מסיגט, ועבר לשם, רב בסוברנץ, רב באונגואר על מקום אביו-תרכד אך נפטר סמוך לכך."},{"i":2843,"n":"איזנשטט, דוד צבי מסערדהאלי","b":"רב בסערדאהעלי,רב בטעטינג-ת\"ר"},{"i":2844,"n":"איזנשטט, יהודה ליב מסוברנץ","f":"מאיר מיארמוט","dt":"תרכב-ז - א שבט","b":"רב בסובראנץ. אחיו - ר מנחם בעל \"זכרון יהודה\"."},{"i":2845,"n":"איזנשטט, יהודה מביאלא","f":"מאיר - פנים מאירות","b":"רב בביאלא-תקכ,"},{"i":2846,"n":"איזנשטט, יוסף דוד ממיר","f":"צבי הירש מזיטל","bt":"תקכו-ז","bp":"וילנא או זאטל","dt":"תרו - כח טבת","b":"חתן ר משה איזנשטט מקלצק. רב בזיטל, אב\"ד ומנהל הישיבה במיר, ובנו ר משה אברהם על מקומו אחריו-תרו. הסכים על ש\"ס וילנא-תקצה, ועוד. לזכרו \"ניר דוד\" לר מרדכי קעלמער רבינוביץ מוילנא בתוך \"גן פרחים\". בניו גם - ר ישראל, ר שלמה נתן - חתן הגביר ר יצחק מבוטען."},{"i":2847,"n":"איזנשטט, יחיאל יצחק","bt":"תרכא","dt":"תרפט","b":"רב בלעכוויץ"},{"i":2848,"n":"איזנשטט, יעקב מאיזנשטט","f":"מאיר - פנים מאירות","b":"רב באייזנשטט-תצ-תקמד."},{"i":2849,"n":"איזנשטט, יעקב מביאליסטוק","f":"משה בן מיכאל","b":"רב בביאליסטוק-תקפ. בנו - ר אברהם צבי הירש בעל \"פתחי תשובה\"."},{"i":2850,"n":"איזנשטט, יעקב מלבוב","f":"יוסף ישראל שלי\"ט","dt":"תיב - יב אב","dp":"לבוב","b":"ראב\"ד בלבוב, דיין בועד ארבע ארצות. חתם-תו עם ר מתתיה בן סיני, חתם גם עם ר אליעזר שליט שנבורג. חתם-תח עם ר יעקב בן אברהם קצנלנבוגן, ר אברהם זלצבורג."},{"i":2851,"n":"איזנשטט, יעקב מלונדון","f":"אליעזר א\"ש","k":"בעל תולדות יעקב","b":"רב בלונדון-תק\"כ"},{"i":2852,"n":"איזנשטט, יעקב פיבוש מזלוטוב","k":"בעל תהלות יעקב","b":"גדול בנגלה ונסתר,דרשן,רב בזלאטאווי-תק\"כ"},{"i":2853,"n":"איזנשטט, יעקב קופל מהנובר","dt":"תריג - ג אד\"ב","b":"מו\"צ בהנובר תקפ\"ג"},{"i":2854,"n":"איזנשטט, יצחק","b":"חתן ר מאיר כץ מאסטיבאווי, ומוהילוב. מגדולי נכבדי דורו-ת\"מ. בנו - ר מאיר בעל \"פנים מאירות\"."},{"i":2855,"n":"איזנשטט, יצחק יחיאל מוארשא","f":"דב בר מלכוביץ","b":"בנו - ר מנחם צבי מקראקא - ניו יורק."},{"i":2856,"n":"איזנשטט, יצחק מנעשוויז","f":"מאיר - פנים מאירות","k":"חתן החכם צבי","b":"חתן החכם צבי. רב בנעשוויז, סלאוויטא, ביאלא-תקי."},{"i":2857,"n":"איזנשטט, ירמיה","b":"רב-שנת ת\"ק"},{"i":2858,"n":"איזנשטט, ישראל","f":"יוסף דוד ממיר","b":"גביר תלמיד חכם. בנו - ר דוד משה שרשבסקי. אחיו - ר משה אברהם ממיר."},{"i":2859,"n":"איזנשטט, ישראל טוביה מרוזינאי","f":"יהודה צבי","k":"בעל דעת קדושים","bt":"1893","bp":"רוז'נוי-פלך גרודנא","dt":"תרנג - כה טבת","dp":"פטרבורג","b":"מצאצאי הקדוש טוביה בכרך - קרבן עלילת הדם-תיט. מחכמי רוזינאי(=רוז'נוי). חיבר \"דעת קדושים\" לתולדות משפחות ידועות בישראל - נדפס לאחר פטירתו במימון הגביר רא\"ל פרידלנד מפטרבורג ועם הערות ש' וינר."},{"i":2860,"n":"איזנשטט, מאיר","b":"מקובל-שנת ת\"כ. חיבר הערות לספר הגלגולים של ר חיים ויטאל, ור דוד גרינהוט רצה להוציאו לאור-תמב ואף הספיק להדפיסו - אך חכמי פפד\"מ לא הרשו לו להפיצו."},{"i":2861,"n":"איזנשטט, מאיר - מהר\"ם א\"ש - א","f":"יצחק א\"ש","k":"מהרם א\"ש-פנים מאירות","bt":"תל","bp":"ליטא","dt":"תקד - כז סיון","b":"נכד אחותו של בעל הש\"ך. תלמיד בעל \"מגן אברהם\" בקליש, למד בוורמס(=וורמייזא) ונתמך בידי ר שמשון ורטהיימר. פוסק, מגדולי חכמי דורו, רב בסוכטשוב, פרוסטיץ ור\"מ בישיבה שם, שידלובצה, איזנשטט-תעה (שהיתה הקהילה הראשית של \"שבע הקהילות\") ורב ראשי של בורגנלנד (\"שבע הקהילות\") וראש ישיבה. מתלמידיו ר יהונתן אייבשיץ. חיבר \"פנים מאירות\", \"מאורי אור\", ועוד. בניו: ר יהודה-חתן ר נפתלי מזולקווא, ר יצחק אב\"ד נשוויז-חתנו של החכם צבי, ר בנימין אב\"ד לקנבך, ר מיכאל אב\"ד קלוצק, ר אלעזר אב\"ד שידלובצה, ר שבתי אב\"ד שרשוב, ר יעקב, ר צבי הירש."},{"i":2862,"n":"איזנשטט, מאיר - מהר\"ם א\"ש - ב","f":"יהודה ליב","k":"בעל אמרי אש","bt":"תקמ","bp":"שוסבורג","dt":"תריב - כד טבת","dp":"אונגוואר","b":"נכד ר מאיר מפינטשוב ויאקא, ומצאצאי(-מצד אמו) ר שמשון וינר. תלמיד החת\"ס, ור רפאל העלין מאיזנשטט. חתן ר דוד דייטש מסערדאוהל ועבר לשם, בזיוו\"ש חתן אלמנת ר יצחק פרנקל מקראלי. רב בבייאה-תקסז על מקום ר ישעיה בן ישראל הכהן, באלאש-יארמוט(=באלשא-גיורמט)-תקעה, אונגוואר-תקצה ור אליקים גץ משוערין על מקומו אחריו, ושם התקרב לחסידות. בנו ר מנחם על מקומו אחריו באונגוואר. החת\"ס החשיבו לאחד מגדולי תלמידיו - ואף היו חולקים בעניני הלכה. (היה מתפלל בכל יום תפלה מיוחדת לאריכות ימיו של החת\"ס). חיבר גם \"אמרי בינה\", ועוד. עמד בראש ישיבה בקהילות בהם כיהן. פרסם מאמרים ב\"הלכה למעשה\" - דעש תרצג. בנו גם - ר יהודה."},{"i":2863,"n":"איזנשטט, מאיר מוולאווע","f":"מנחם א\"ש","dt":"תרנ - ה אייר","b":"רב בוולאווע"},{"i":2864,"n":"איזנשטט, מאיר מיאקע","b":"ברח מפינטשוב-פולין, רב ביאקע-תקכ. נכדו ר מאיר-מהר\"ם א\"ש."},{"i":2865,"n":"איזנשטט, מאיר מנעשוויז","f":"אהרן א\"ש","bt":"תקי","dt":"תרח","b":"רב בנעשוויז"},{"i":2866,"n":"איזנשטט, מיכאל ירמיהו מוילנא","f":"אברהם בצלאל מוילנא","k":"רמ\"י - בעל יד מלאכי","bt":"תרג","bp":"קלוואריה","dt":"תרן - ב תשרי","b":"נכד ר שאול הגדול ממיר. תלמיד ישיבת מיר, וולוזין. חתן הגביר ר ראובן הרץ גיגוזין מוילנא. קרובו הנצי\"ב מוולוזין נתן לו לעבור על ספרו \"העמק שאלה\" ולהגיהו ולתקנו וכמה מחדושיו נדפסו בספר בשם \"משארי הרב רמ\"י א\"ש\". פרסם מאמרים בכתבי עת ובהם \"המגיד\", \"הצופה\", ועוד. אחיו של ר דב בער רוטנר מוילנא."},{"i":2867,"n":"איזנשטט, מיכאל מירער","f":"אברהם מירער","k":"שיר תהלה","b":"חתן ר אליהו הלוי סלוצקי ממיר בן ר בצלאל מסלוצק. חיבר \"שיר תהלה\" על הצלחת הצאר אלכסנדר במלחמת נפוליאון - שקלוב תקעד. בשליחות פלך מאוהילוב לפטרבורג בפני השלטון להשיב על שאלות ולבקש על היהודים. נינו - הנצי\"ב מוולוזין."},{"i":2868,"n":"איזנשטט, מיכאל מקלצק","f":"מאיר - פנים מאירות","b":"חתן ר ליב מירקש. רב באיזנשטט, קלצק, מיר-תקכ. בניו: ר אברהם ממיר, ר משה אב\"ד קלצק על מקום אביו - חתן בעל אור חדש, ר איסר משקלוב, ר שלמה טריספולר, ר מאיר בריסווער, ר הירש ליובטשער, ר גרשון מסלונים. תשובה ממנו בספר אביו \"פנים מאירות\"."},{"i":2869,"n":"איזנשטט, מיכאל מקלצק","f":"משה א\"ש","b":"רב בקלצק-תק\"נ"},{"i":2870,"n":"איזנשטט, מנחם מחוסט","f":"מהר\"ם א\"ש","k":"בעל חומת אש","bt":"תקסח","dt":"תרל - ו כסלו","dp":"אונגוואר","b":"חתן הגביר ר אלחנן דב מליסקא, ובזיוו\"ש חתן הגביר ר שמואל הורביץ (חתנו של הגביר ר אלחנן דב) ועבר לשם (ליסקא). רב בסערדנא, חוסט, אונגוואר על מקום אביו. חיבר גם \"זכרון יהודה\" - על אביו."},{"i":2871,"n":"איזנשטט, מנחם מנדל משטוצין","f":"נח חיים איזנשטיין","k":"בעל צמח מנחם","bt":"תר","bp":"שטוצין-פלך וילנא","dt":"תרס","b":"רב בקמייקא-תריח, ליסקובה, זיכלין, שטוצין(=סטוטשין)-תרלה."},{"i":2872,"n":"איזנשטט, מנחם צבי מקראקא","f":"יצחק יחיאל מוארשא","k":"בעל זכרון יצחק","bt":"תרסא","bp":"קראקא","dt":"תשכו - ד אב","dp":"ירושלים","b":"תלמיד הדעת סופר, ישיבות מיר וסלובודקה. נסמך על ידי ר עקיבא סופר ור חיים עוזר גרודונסקי. חתן ר יוסף נחמיה קורניצר אב\"ד קראקא, ועבר לשם-תרפח, היה מראשי הקהלה והקים ישיבה בקראקא ותמך בה. עלה לארץ-תש ויסד בימ\"ד בתל אביב. עבר לניו יורק בשנת תשח שם חידש את ישיבת הרמה מקראקא בניו יורק. הוציא לאור פירוש הרמבן ניו יורק תשיט. הדפיס ספר סבו \"כנפי שחר\" פיעטרקוב תרצה.","bk":[["מנחת צבי",""]]},{"i":2873,"n":"איזנשטט, מרדכי","k":"בעל חזיונות שבתי צבי"},{"i":2874,"n":"איזנשטט, משה אברהם ממיר","f":"יוסף דוד ממיר","b":"חתן ר שמעון בן דב בר מסלונים בעל \"מנחה בלולה\". רב בזעטל, אב\"ד ור\"מ במיר-תרכה על מקום אביו. בנו ר צבי הירש דב בר מוילנא."},{"i":2875,"n":"איזנשטט, משה אליעזר - הזקן","b":"מחכמי ביאליסטוק-תר. נכדו - הרב ד\"ר משה אליעזר מפטרבורג ופאריס."},{"i":2876,"n":"איזנשטט, משה יעקב מקלצק - ב","f":"מיכאל א\"ש","b":"רב בקלצק-תק\"פ"},{"i":2877,"n":"איזנשטט, משה מלייפניק","f":"ירמיה א\"ש","dt":"תקעב - כו אדר","b":"רב בלייפניק,בוניהאד(=בניהאד)-תקמ\"ב"},{"i":2878,"n":"איזנשטט, משה ממיר","f":"מאיר - פנים מאירות","b":"רב במיר-ת\"ק"},{"i":2879,"n":"איזנשטט, משה מקלצק - א","f":"מיכאל א\"ש","dt":"תקנב - יב חשון","b":"רב בקלצק-תכ\"ב"},{"i":2880,"n":"איזנשטט, משה מרוסיה","k":"בעל מנסיעתי במזרח הק","b":"ביקר בארצות המזרח וחיבר על כך \"מנסיעתי במזרח הקרוב\" וילנא תרע."},{"i":2881,"n":"איזנשטט, משלם פיבוש","dt":"תרב-כ - כ סיון","b":"תלמיד בעל \"נודע ביהודה\". רב בוישגראד-פלך וארשא."},{"i":2882,"n":"איזנשטט, צבי הירש","f":"מאיר - פנים מאירות","b":"רב-שנת תק\"י"},{"i":2883,"n":"איזנשטט, צבי הירש","f":"אלימלך א\"ש","b":"רב בטריספאלי-ת\"ר"},{"i":2884,"n":"איזנשטט, צבי הירש דב בר","f":"משה אברהם מזעטל","k":"ר הירש'ל אליהו זלמנס","bt":"תקעד","dt":"תרם - כו ניסן","dp":"וילנא","b":"חתן הגביר ר אליהו הלפרין הנקרא ר אליהו זלמנ'ס. גביר ופרנס מחכמי וילנא. מתורתו ב\"מקורי הרמב\"ם מעין חיים\", פרסם ב\"כרמל\", ועוד. בקי בחשבון. נזכר ב\"ראשית בכורים\", ועוד. החזיק לומדים בביהמ\"ד, גבאי בת\"ת, ובח\"ק. בנו ר שלמה זלמן גלאבוש. חתניו: ר ליב איסר גרודזנסקי מוילנא בן ר שמואל אהרן מקאלואריא,"},{"i":2885,"n":"איזנשטט, צבי הירש ממיר","f":"מיכאל א\"ש","b":"חתן ר מנחם נחום כהנא מצערקוב. חריף, דרשן, רב בליובטש, מיר-תקס"},{"i":2886,"n":"איזנשטט, צבי הירש ממיר","f":"משה א\"ש","b":"רב במיר-תק\"ל"},{"i":2887,"n":"איזנשטט, שלמה","b":"חתן ר מרדכי מוכיח מפרשבורג. בניו - ר צבי הירש, ר מנחם יצחק. (אולי הוא ר שלמה מלקנבך - נכד פנים מאירות)."},{"i":2888,"n":"איזנשטט, שלמה זלמן","f":"בנימין א\"ש","b":"רב בלקנבך-תק\"ל"},{"i":2889,"n":"איזנשטט, שלמה זלמן","f":"צבי הירש דב בר מוילנ","dt":"תרמג - יא תמוז","dp":"סובאלק","b":"נקרא ע\"ש ר שלמה זלמן גלאבוש. חתן הגביר ר משה ענדלמן מוארשא בן ר חנוך זונדל חלפן (אשר שימש את הגר\"א בהיותו עצור בסערהייא). גביר מחכמי וילנא."},{"i":2890,"n":"איזנשטט, שלמה מביטון","f":"יוסף דוד א\"ש","dt":"יח אדר","b":"רב בביטון-תר\"מ"},{"i":2891,"n":"איזנשטט, שלמה מבריסק","f":"מיכאל מקלעצק","b":"רב בבריסק-תקס. בנו - הגביר ר מיכאל מבריסק."},{"i":2892,"n":"איזנשטט-קצנלנבוגן, מאיר משטמפן","f":"חיים","k":"בעל נר למאור","bp":"איזנשטט","dp":"שטמפן","b":"ממגורשי איזנשטט-תל, הגיע לפרג, רב בשטאמפן-תמ. הו\"ל ספר הגלגולים עם הוספות ממנו. חיבר גם \"משתה יין\". אחיו - ר משה. בנו - ר צבי הירש הו\"ל את ספרו עם הוספות - פיורדא תצז."},{"i":2893,"n":"איזנשטטר((א\"ש), אליהו מדרטשקע","bp":"וילנא","dt":"תרלו - ו שבט","b":"תלמיד הכת\"ס. חתן לבית הלר בשוראן ועבר לשם-תריב, רב בדרעטשקע(=דרצ'קא)-מחוז ביהור-תרטז כ-30 שנה וראש ישיבה שם, ר צבי ברמן על מקומו אחריו."},{"i":2894,"n":"איזנשטין, אברהם מירושלים","f":"צבי הירש","k":"ר' אריה\"ס","bt":"תקס","bp":"הורדנא או דרוהטשין","dt":"תרמו - ו אלול","dp":"ירושלים","b":"חתן ר חיים הכהן מפינסק, (אצל פרומקין-ריבלין - חתן ר אריה ליב בן ירחמיאל מרקוס). דיין בדרהיטשין(=דרוהיטשין). עלה עם תלמידי הגר\"א, בשליחות הקהלה בהונגריה, דיין אצל ר ישראל משקלוב בצפת, וראש הועד הכללי, דיין בירושלים אצל רמ\"א אוירבך. העתיק את כתב היד שיטה מקובצת. הגיה את הריטב\"א על ראש השנה ועוד. בני משפחתו נהרגו ברעש בצפת-תקצז. בנו - ר אליהו מרדכי."},{"i":2895,"n":"איזנשטין, אליהו מרדכי מירושלים","f":"אברהם מירושלים","b":"נאמנו של ר שמואל סלנט בירושלים, גזבר ונאמן ה\"ועד הכללי\", ישיבת עץ חיים, ובקור חולים בירושלים."},{"i":2896,"n":"איזנשטין, אשר","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":2897,"n":"איזנשטין, דב מאיר","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\"."},{"i":2898,"n":"איזנשטין, יהודה דוד","k":"בעל אוצר ישראל","bt":"תריד","dt":"תשטז","b":"גדול בתורה וחכמה,מטובי הסופרים המאספים בדור האחרון, ארה\"ב-תרלב. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג."},{"i":2899,"n":"איזנשטין, יעקב מסלנט","b":"רב בסלנט. חותנו של ר ישראל ליפקין סלנטר."},{"i":2900,"n":"איזנשטין, ישראל","k":"בעל עמודי אש","b":"בקי,רב בבאהאפאל-תר\"ל"},{"i":2901,"n":"איזנשטין, נח חיים משטוצין","dt":"תרלד - כח אב","b":"חתן ר דב בערמסלאנימא. רב בשטוצין-תרא. בניו: ר שלום דב, ר מנחם מנדל בעל \"צמח מנחם\", ר ברוך בן ציון."},{"i":2902,"n":"איזנשטין, שלום דוב","f":"נח חיים איזנשטין","k":"בעל כנפי שחר","dt":"ב כסלו","b":"רב בלעזכוויץ-תר\"ס"},{"i":2903,"n":"איזנשטש, שבתי מביאלא ושערשוב","f":"מאיר - פנים מאירות","dt":"תקנ - ב תמוז","b":"רב בביאלא, שרשוב. חתם על תקנה בבריסק-תקמה עם ר יצחק בן ברוך מוואלפא."},{"i":2904,"n":"איזקסון, אברהם ישכר בער","f":"שלמה מרומאן","bt":"תרנד","dt":"תשד","b":"חתן ר ישראל חיים פרידמן מראחוב בעל \"ליקוטי מהרי\"ח\". רב בפאליען-ריסקווה(=פוליען-ריסקובה) - מארמרוש. פעל לסייע ליהודי מארמרוש לעלות לארץ, וביזמתו עלו-תרצה כ-200 איכרים והתישבו ברחובות ובראשון לציון. נספה בשואה."},{"i":2905,"n":"איזקסון, דוד מראמאן","f":"יצחק מקאלוש","k":"אדמור מראמאן","dt":"תרסח - א חשון","b":"נינו של ר מאיר מפרמישלן. חתן ר אפרים יוסף גלנטי."},{"i":2906,"n":"איזקסון, יוסף מרוטרדם","bt":"תקעו","bp":"פיהלענע","dt":"תרנח - טז טבת","dp":"פיהלענע","b":"חתן רבקה קלישר-נכדת החת\"ס ובזיוו\"ש חתן ר יעקב עטלינגר. רב בפפד\"א, עמדין, רוטרדם, ואחר שהתעשר התיישב בהמבורג לעסוק בתורה, דרשן. היה מחלוקת בינו לר אשר שטרן. נספד ע\"י גיסו - ר שלמה הכהן משווערין. תשובות ממנו ב\"בנין ציון\". (יש רושמים תאריך פטירתו - תרמה)."},{"i":2907,"n":"איזקסון, יחיאל יהודה מסיגט","f":"אברהם ישכר בר מפליען","dt":"תשם","b":"חתן ר חיים צבי טיטלבוים מסיגט. ניצל מהשואה, ואחריה רב בסיגט ודיין בבית הדין להתרת עגונות ברומניה. עלה לארץ וכיהן כרב בחיפה, רב בלוס אנג'לס וראש ישיבת \"תורת אמת\"."},{"i":2908,"n":"איזקסון, ישראל מווליקי ונ\"י","f":"יצחק איזיק","bt":"תריא","bp":"זיקיבראק-ליד מיר","dt":"תרפג","b":"נכד ר מרדכי טראינאווער מירושלים (המכונה ר מרדכי מתמיד), ונכד-אבי אמו הגביר ר ישעיה אברהם ברגר. תלמיד ישיבת מיר, וולוזין רב בווילקי-ליד קובנא-תרסא, קאידינוב-פלך מינסק-תרסב, היגר לאמריקה וכיהן כרב קהילת סובאלק בניו יורק-תרסז (\"כל ישראל אנשי פולין\"), ור\"מ בישיבת ר יצחק אלחנן בניו יורק."},{"i":2909,"n":"איזקסון, ישראל מקידנוב ונ\"י","k":"בעל הרבני","b":"רב בקידנוב, ניו יורק-תרעב. הו\"ל ירחון \"הרבני\" נ\"י תרעב."},{"i":2910,"n":"איזקסון, מאיר מפאקשן","k":"בעל מבשר טוב","b":"מצאצאי אדמורי פרמישלן ונדבורנה. רב בארה\"ב-תשלו."},{"i":2911,"n":"איזקסון, שלמה מרומאן","f":"יצחק מנדבורנא","k":"תשיא","bt":"תרלו","bp":"קאלוש","b":"נכד האדמור ר אהרן אריה מנדבורנא.. חתן דודו ר מאיר מקרטשנוף. רב ואדמור ברומאן-רומניה-תרס כ-50 שנה."},{"i":2912,"n":"איזראלזון, אברהם יעקב מגולדינג","f":"יהודה ישראל מגולדינג","dt":"תרה - י אייר","b":"מחכמי גולדינגן-תקפד. בניו - ר יחיאל מיכל, ר ישראל. נכדיו (בני בתו) - ר חיים ישראל בלומנטל, ר יהודה בלומנטל, ר אהרן בלומנטל."},{"i":2913,"n":"איזראלזון, ברוך יעקב מטלז","f":"אברהם יעקב מגולדינגן","dt":"תרנח","dp":"פרידריכשטט","b":"שם אביו נרשם גם - ר יחיאל מיכל. נכד ר ישראל איזראלזון. רב בקאנדאוי(=קאנדוי)-תרנג, פרידריכשטט-תרנז. פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"תורה מציון\" - ירושלים תרנה-תרסה. חיבר פירוש למסכת ברכות - בכת\"י."},{"i":2914,"n":"איזראלזון, יהודה ישראל מגולדינ","dt":"תקכה - בערך","dp":"גולדינגן","b":"מו\"ץ הראשון בגולדינגן. בנו - ר אברהם יעקב מגולדינגן."},{"i":2915,"n":"איזראלזון, מנחם מנדל ממיטאוי","f":"ישראל","dt":"תרך - יט אב","b":"רב בשאבילן(=שאוויל), גולדינגן, ליבאוי, פילטען-תרטז, מיטאוי-תריט. מבקר (צנזור) מטעם השלטון."},{"i":2916,"n":"איזראלזון, שלום מליטא וארה\"ב","f":"אשר","k":"בעל דברי שלום","bt":"תרכא","bp":"יאנישוק","dt":"תרצא - יב שבט","b":"הוסמך לרבנות בקובנא ע\"י ר יצחק אלחנן, עבר לפוניבז והכין לדפוס את חיבוריו, רב ביאנישוק-ליטא, היגר לארה\"ב-תרנז וכיהן כרב במילווקי, טורונטו-תרס, שיקגו-תרס. חיבר גם \"עצת שלום\", \"נוה שלום\", \"דרך שלום\" סט לואיס תרפו. פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו, \"המצפה\" - נ\"י תרע."},{"i":2917,"n":"איזראליט, יהודה יהושע פאלק","dt":"תרצח - כד אייר","b":"רב בצ'לסי-מסצ'וסס-ארה\"ב. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד, \"בית ועד לחכמים\" - נ\"י תרסג, \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":2918,"n":"איזראליט, ישראל מגרודנא","bt":"תקע","bp":"ליטא","dt":"תרנה","b":"מגיד מישרים בבריסק, גרודנא(=הורדנא), מינסק ומקורב לגדול ממינסק. דרשן מפורסם בליטא, התעוור לעת זקנתו אך המשיך בדרשנותו. חתנו - ר אהרן זלצר מונדזיגולה. הספדו האחרון היה של הגדול ממינסק. חברו של ר נחום מהורדנא - ומתורתו ב\"תולדות מנחם\"-ספר תולדותיו של ר נחום. נזכר גם ב\"הדרשה בישראל\" לר שמעון גלקיסברג - תש, וב\"עלי חלדי\" לר יצחק ניסנבוים."},{"i":2919,"n":"איזראליט, שמחה ליב מקלצק","b":"חתן ר יעקב וישנבסקי ממינסק. גביר מחכמי קלצק-תרן בערך."},{"i":2920,"n":"איזראעל, אברהם מאיר מהוניאד","f":"יהודה ליב","k":"בעל אוצר הפסח","bt":"תרעח","bp":"הידאלמאש","b":"תלמיד ישיבת ר שאול בראך בקרולה. ראש ישיבה בהוניאד-תשא, רב בהוניאד-תשב. ניצל מהשואה ואחריה רב בהוניאד וגליל הידאלמאש, ודיין בבית הדין להתרת עגונות ברומניה. רב קהילת \"שארית הפליטה\" בוינה, עבר לארה\"ב-תשי וכיהן כרב בניו יורק. ממיסדי שכונת קרית מטרסדורף בירושלים. חיבר גם \"תולדות איש חי\" נ\"י תשכב, \"אמרי אברהם\" ניו יורק תשך, \"הוי דניאל\"."},{"i":2921,"n":"איזראעל, הינריך מפרשבורג","b":"עורך העתון היהודי בהונגרית \"מאדיאר זשידו\" - פרשבורג תרנב."},{"i":2922,"n":"איזראעל, יעקב קופל מקלויזנבורג","f":"מאיר מבילקא","bt":"תרך","dt":"תשד - ט סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור משה פולק מבאניהאד. חתן ר מנחם מנדל שינדלר מלאנע (ליד קוליזנבורג). מחכמי בילקא, לאנע, מלמד בקלויזנבורג. נספה בשואה."},{"i":2923,"n":"איזראעל, מאיר מבילקא וירושלים","b":"תלמיד ר אשר אנשל יונגרייז בעל מנחת אשר. רב בבילקא-תרמ, עלה לירושלים. נזכר בשו\"ת מהר\"ם שיק, \"יד יצחק\". חתנו - ר ישעיה יונגריז מזערענד."},{"i":2924,"n":"איטינגא, אברהם מדוקלא","f":"יונה","k":"בעל שיחת חולין של תח","bt":"תרלה","bp":"דוקלא","dt":"תרפד","b":"רב בדוקלא, חוקר תולדות הרבנות. חיבר \"שיחת חולין של ת\"ח החדש\" מונקטש תרסט, \"דעת זקנים\" סאניק תרעא, ועוד."},{"i":2925,"n":"איטינגא, אברהם מקראקא","f":"אליהו מוענגרוב","b":"נכד ר אברהם יועץ הקיסר בוינה. מצאצאי ר שמעון גינצבורג מפוזנא. ראש מדינה בגליל קראקא מוישנצא. בנו ר השל."},{"i":2926,"n":"איטינגא, אהרן הלוי מיברוב","f":"חיים יהודה מלבוב","bt":"תפ","dt":"תקכט - יט סיון","dp":"לבוב","b":"חתן ר חיים הכהן רפפורט מלבוב. ראב\"ד ביברוב-תקי, רב ברישא-תקכד, היה מהמתנגדים לחסידות בזמן ה\"נועם אלימלך\". נפטר צעיר ונספד מאת חותנו. אחיו ר יוסף אב\"ד רוהטין. (במאורי גליציה תאריך פטירתו - תקמא)"},{"i":2927,"n":"איטינגא, אליעזר ממזריטש","dt":"תקעב - ב אלול","b":"רב במזריטש"},{"i":2928,"n":"איטינגא, אליעזר סגל מפרג","f":"אברהם ליכטנשטיין","dt":"תע - כט תשרי","b":"פרנס בפרג, מגדולי חכמי דורו, רב בהעלישוי, נתקבל לרב של קראקא-אך נפטר לפני שהגיע. בניו - ר חיים יהודה ליב, ר יוסף בעל \"עדות ביהוסף\"."},{"i":2929,"n":"איטינגא, אריה יהודה ליב מליטבי","f":"[יעקב משה מאומן]","b":"רב בליטעוויץ."},{"i":2930,"n":"איטינגא, ברוך מרדכי מבוברויסק","f":"אליעזר מלמברג","k":"העילוי משוינציאן","bt":"תקכז","bp":"ליטא","dt":"תריב-ז -יד אלול","dp":"ירושלים","b":"פגש את הגר\"א בוילנא, ממשפחת ר מרדכי זאב בעל \"מפרשי הים\", חתן אביו חורגו ר שמואל-רבה האחרון של וילנא. ראש ישיבה בוילנא, דיין-תקנא. התקרב לחסידות חבד-תקנג והיה קרוב לאדמור הזקן, ובנו ר דב בער מליובאויטש, וחתנו ר מנחם מנדל. היה מחלוקת כנגדו בגלל חסידותו ואף נאסר בגלל הלשנה ושוחרר. רב הקהלה החסידית בבוברויסק-תקסב כ-40 שנה. עלה לירושלים-תריא או תרטז - בברכת ה\"צמח צדק\". נכדו - ר ברל מרקס אטינגר."},{"i":2931,"n":"איטינגא, דב בער סגל מטימניץ","b":"מחכמי טיסמניץ-תריא."},{"i":2932,"n":"איטינגא, הרץ מפרמישלא","f":"אברהם מווין","b":"רופא בפרעמיסלא"},{"i":2933,"n":"איטינגא, חיים יהודה ליב מלבוב","f":"אליעזר מהלישוי","k":"בעל דברי אריה יהודה","dt":"תקל - ג שבט","dp":"ירטשוב","b":"חתן ר שמחה הכהן רפפורט מדובנא. רב בקידאן, קראקא? (ולדעת צונץ צ\"ל קראק=קרוק-ליד קידאן), לבוב-תעח, ואב\"ד על מקום ה\"פני יהושע\"-תצא, היה במחלוקת עם ר חיים רייצס ולכן עזב את לבוב לירטשוב ושם נפטר. הסכים על \"מאמר מרדכי\", \"טעמי המסורה\", \"עדות ביהוסף\" שחיבר אחיו, ועוד. בניו: ר יחיאל מיכל, ר מנחם מנדל ממזריטש, ר יוסף מרוהטין, ר אהרן מיברוב ורישא-חתן ר חיים רפפורט. חתניו: ר יצחק איזיק מאוסטרהא, ר שמואל-רבה האחרון של וילנא. מחותן עם גיסו - ר חיים רפפורט. (יש בלבול בינו לבין גיסו ר אריה ליב מויטבסק בעל \"דברי אריה\" - מי מהם היה חותנו של ר שמואל מוילנא). (לדעת בובר הוא זהה עם ר יהודה ליב סגל מלבוב שהיה תלמיד ר נפתלי מגלוגא."},{"i":2934,"n":"איטינגא, יהודה ליב סגל מטשיביץ","f":"אברהם מטיסמניץ","dt":"תקנג - יב כסלו","b":"רב בטישוויץ(=טישביץ). בניו - ר מרדכי, ר נפתלי הרץ."},{"i":2935,"n":"איטינגא, יונה הלוי מברוד","f":"יעקב שמחה","bt":"תרי","dt":"תרנב","b":"מחכמי ברודי, חתן ר חיים יהודה קלוגר בנו של המהרשק. בנו ר אברהם סגל מדוקלא."},{"i":2936,"n":"איטינגא, יוסף הלוי מזולצבך וגל","f":"אליעזר הלוי מזולצבך","k":"בעל עדות ביהוסף","b":"דרשן ומו\"ץ בזולצבך, גלוגא-תק. חיבר גם \"יפה מראה\" על התלמוד - בכת\"י. גיסו של ר יחיאל מיכל מגלוגא בעל \"נזר הקדש\"."},{"i":2937,"n":"איטינגא, יוסף מרוהטין","f":"חיים יהודה מלבוב","b":"חתן ר יצחק סגל לנדא מלבוב וקראקא. רב באיטינגא, חמלניק, רוהטין-תקטו. נזכר ב\"לוחות העדות\" תשובות ממנו לר יונתן איבשיץ."},{"i":2938,"n":"איטינגא, יחיאל מיכל מטישביץ","f":"חיים יהודה מלבוב","b":"רב בטישוויץ-תקל."},{"i":2939,"n":"איטינגא, יעקב משה מאומן","f":"מרדכי זאב","bt":"תקץ","bp":"למברג","dt":"תרם","b":"רב באומן, תשובות אליו בספרי שו\"ת שונים."},{"i":2940,"n":"איטינגא, יעקב שמחה מברדיטשוב","f":"יוסף איטינגא","b":"רב בברדיטשוב-תר\"כ"},{"i":2941,"n":"איטינגא, יצחק אהרן מלבוב","f":"מרדכי זאב-מאמר מרדכי","k":"בעל שו\"ת מהרי\"א הלוי","bt":"תקפז או תקף","bp":"למברג","dt":"תרנא - ז שבט","dp":"למברג","b":"תלמיד קרובו ר מרדכי זאב מדרוהוביטש, מקורב לאדמור ר יצחק איזיק מזידיטשוב ולדברי חיים מצאנז. אב\"ד פשמישל-תרכו, רב לבוב-תרמח. היה נשיא ארץ ישראל בגליציה יחד עם ר חיים מצאנז והתפטר בשנת תרלז בגלל מחלוקת, (אודות המחלוקת נדפסו חוברות \"אגרת פתוחה\" ו\"אגרת בקורת\"). חיבר \"שות מהריא הלוי\" למברג תרנג. בניו: ר נפתלי הירץ, ר יעקב מבוליחוב, ר שלמה (מחותן עם הגביר ר יצחק תאומים מפרמישלא). חתנו - ר יהושע בן חיים מרדכי זוסמן מאוסטרהא. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא.","bk":[["מהרי\"א הלוי","שו\"ת - אחרונים"],["שו\"ת מהרי\"א הלוי",""]]},{"i":2942,"n":"איטינגא, יצחק אהרן מלבוב","f":"נפתלי הירץ","bt":"תקכ","bp":"למברג","dt":"תקפה","b":"חתן ר מרדכי זאב אורנשטין מלבוב, גיסו ומחותנו של ר יעקב אורנשטין \"הישועות יעקב\"."},{"i":2943,"n":"איטינגא, ליבוש","b":"תשובות אליו בספר \"ישועות יעקב\"."},{"i":2944,"n":"איטינגא, מאדל מוינה ואלטונא","f":"נפתלי הרץ סגל","dt":"תפז - יד כסלו","dp":"אלטונא","b":"סגי נהור ממגורשי וינה-תל, התישב באלטונא."},{"i":2945,"n":"איטינגא, מנחם מנדל סגל","f":"חיים יהודה מלבוב","b":"חתן ר יעקב מוענגרוב. רב במזריטש גדול-תקי. נזכר ב\"זכרון למשה\", \"עיר דוד\"."},{"i":2946,"n":"איטינגא, מרדכי זאב מלבוב","f":"יצחק אהרן מלמברג","k":"בעל מאמר מרדכי","r":"גיסו של השואל ומשיב, אב\"ד לבוב","bt":"תקסד","dt":"תרכג - ב תמוז","dp":"סדיגורא","b":"נכד ר מרדכי זאב אורנשטין מלבוב (ונקרא על שמו). תלמיד דודו ר יעקב מליסא בעל \"ישועות יעקב\", ר נפתלי הירץ סטנוב מלבוב (אביו של ר גבריאל בעל מצבות קדש). חתן ר יעקב קלמן קלונימוס ליפיס. למד עם גיסו ר יוסף שאול נתנזון ושניהם נודעו כ\"מפרשי הים\". יסד עם ר חיים מקוסוב את כולל עסטרייך והיה נשיאו. מלבד הספרים שחיבר עם גיסו \"מפרשי הים\" \"מגן גבורים\" ועוד, חיבר \"מאמר מרדכי\" למברג תריב, ועוד. נתבקש במכתב בצפת על ידי רבני צפת להכריע בערעור יורשי הגביר ר יעקב נסים מבגדד.","bk":[["מגן גיבורים [הקדמה]","מפרשי שו\"ע"],["מגן גיבורים [אלף המגן]","מפרשי שו\"ע"],["מגן גיבורים [שלטי גיבורים]","מפרשי שו\"ע"],["מגן גיבורים [תיקון סופרים]","מפרשי שו\"ע"],["מאמר מרדכי - שו\"ת",""]]},{"i":2947,"n":"איטינגא, נפתלי הרץ","f":"[אברהם מטיסמניץ]","dt":"תקכה","b":"חתן ר שמחה הכהן רפפורט מלובלין."},{"i":2948,"n":"איטינגא, נפתלי הרץ סגל","f":"יחיאל מיכל מטשיביץ?","b":"חתן ר יעקב שמחה לנדא. נכד ר חיים יהודה ליב מלבוב בעל \"דברי אריה יהודה\". גביר ופרנס מחכמי לבוב-תקפ. בניו: ר יצחק אהרן, ר יוסף."},{"i":2949,"n":"איטינגא, נפתלי הרץ סגל מוינה","f":"אברהם איטינגא","b":"מגדולי חכמי ונכבדי ווינה-ת\"י"},{"i":2950,"n":"איטינגא, עזריאל יהודה הלוי","f":"מהר\"א מגומבין","b":"אולי בנו של ר אליעזר מגובין (שהסכים על \"נקודות הכסף\" נובידוואר תקן). כנראה כיהן כרב."},{"i":2951,"n":"איטינגא, שלמה","f":"יצחק אהרן-שו\"ת מהרי\"","b":"חתן ר אפרים זלמן זוסמן מאוסטרהא."},{"i":2952,"n":"איטינגא, שמואל שמלקא מוורנה","b":"נינו של ר משה מטלז. רב בוורנה."},{"i":2953,"n":"איטינגן, אברהם הלוי","f":"מרדכי מאדל גינצבורג","dt":"שצז - ב סיון","b":"נכד ר שמעון גינצבורג מפוזנא, יועץ הקיסר בוינה. בניו ר אליהו מוענגרוב, ר הירץ רופא מפרמישלא, ר ליב חתן ר מאיר מבריסק. (יש בלבול באוצר הרבנים)"},{"i":2954,"n":"איטינגן, אברהם מבומסלא"},{"i":2955,"n":"איטינגן, אליהו הלוי - ב","f":"אברהם מוינה","k":"בעל ברית הלוי","b":"רב בוונגרוב(=וענגרוב)-שן, חתן ר שמעון גינצבורג מפוזנא?, בנו ר מרדכי מאדל איטינגן, ונכדו ר אברהם מוינה - יועץ הקיסר."},{"i":2956,"n":"איטינגן, אליהו מוענגרוב - א","f":"אברהם מוינה","b":"רב בונעגרוב. חתן ר יעקב שמילש מפרג, ובזיוו\"ש חתן ר משה ליזרש מוילנא, בנו ר אברהם ראש מדינה בגליל קראקא, חתניו ר שאול וואלש מבריסק, הראש ר שמואל ר איסרלש מלובלין, ר הירש ר יאקוב לעמליש מוילנא."},{"i":2957,"n":"איטינגן, אשר אנשיל","dt":"תשג","b":"רב בחאמסק"},{"i":2958,"n":"איטינגן, משה מהאזנפוט","b":"גביר מחכמי האזנפוט-תקס בערך."},{"i":2959,"n":"איטליאנו, שלמה הכהן משלוניקי","dt":"רצב - תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":2960,"n":"איטלסון, אברהם יוסף","f":"חנוך הניך מויליאמפול","b":"חתנו - ר נפלתי אמשטרדם מנובוגרוד. בנו - ר שמעיה מוידז."},{"i":2961,"n":"איטלסון, אליהו צבי","f":"חנוך הניך מויליאמפול","b":"חתנו - ר יהושע השל סירקין מוילנא."},{"i":2962,"n":"איטלסון, חנוך הניך מויליאמפול","f":"אליעזר פרוזינר","b":"רב בויליאמפול-סלובודקה-תקפח. נקרא ע\"ש אמו - איטא - שהיתה מפורסמת בחכמתה. מחותן עם ר חיים יעקב סלוצקי מוילנא בעל \"נטעי נעמנים\". חתם עם הדיינים ר אליעזר בן יהושע, ור שמעון בן גבריאל הלוי, וחתם-תקפח עם הדיינים ר נחום בן חיים, ור ישעיה בן יצחק. בניו - ר אברהם יוסף, ר אליעזר מאיר, ר צבי."},{"i":2963,"n":"איטקין, חיים יונה משיוינשוק","f":"דובער נחום","bt":"תרמב","b":"תלמיד ישיבת סלובודקא. חתן ר אברהם ברוך קלמפמן משיבאט-קורלנד. רב בשביניקשי(=שיווינישאק)-קורלנד-תרסח. נסמך מאת: ר יוסף רוזין-הרוגצובר ונתחנך בביתו להוראה למעשה."},{"i":2964,"n":"איטקין, חיים ליב מאלכסנדרי","f":"יואל","bt":"תריז","b":"נכד ר שלמה מסטרידוב. רב באשאקוב(=אטשאקוב)-פלך חרסון-תרמה, אלכסנדרי-חרסון-תרסט על מקום אביו, חבר ועדת הרבנים בפטרסבורג-תרע."},{"i":2965,"n":"איטקין, חיים משיקגו","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":2966,"n":"איטקין, יואל - הזקן","b":"רב באלכסנדרי-חרסון. בניו: ר שלמה מסטרידוב, ר פסח מאלסטויקער, ר פיבל מאסטער."},{"i":2967,"n":"איטקין, יואל - הנכד","f":"שלמה מסטרידוב","b":"רב באלכסנדרי-חרסון-תרם ובנו ר חיים ליב על מקומו אחריו."},{"i":2968,"n":"איטקין, ישראל ליב מרומנקובה","f":"שיימן בן יואל","bt":"תרמו","b":"תלמיד ישיבת לובאביץ. חתן ר פיבש יעקב חפץ מפאצאפ-פלך צרניגוב. רב ברומנובקה(=ראמאנאווקא)-פלך חרסון-תרסו. נסמך מאת: ר דוד מלובאביץ, ר משה מבריסלוב, ר יהושע נתן מפאצאפ."},{"i":2969,"n":"איטקין, פיבל מאסטער","f":"יואל מאלכסנדרי","b":"רב באסטער-תר\"ס"},{"i":2970,"n":"איטקין, שיימא מברמנובקא","b":"רב בברמנובקה-תר\"ס"},{"i":2971,"n":"איטקין, שלמה מסטרידוב","f":"יואל","b":"נכד ר ליב חריף בעל \"קול אריה\". רב בסטרידוב-תר."},{"i":2972,"n":"אייבנשיץ, משה משוראן","b":"שו\"ב בשוראן. חתניו - ר שמעיה דייטש משוראן ור אברהם מנדל מוועטש."},{"i":2973,"n":"אייבראמס, ויליאם","bt":"1894","bp":"שאוולי","b":"עתונאי ועסקן בבונד. היגר לארה\"ב-1913. פעיל סוציאליסטי בניו יורק. מעורכי \"סיגנאל\", מעורכי \"פאר ווערטס\"-1924, חיבר \"צו דער געשיכטא פון דער אידשער ארבייטער..\", \"איך ניי און ניי\"."},{"i":2974,"n":"אייברמס, אברהם מארה\"ב","f":"יהודה","dt":"תרעא - א תמוז","dp":"ניו יורק","b":"גביר נדבן בניו יורק, מקורב לנשיא תיאודור רוזבלט."},{"i":2975,"n":"אייברמס, אברהם מארה\"ב - ב","b":"מנהל ישיבת רבי יצחק אלחנן בניו יורק. הו\"ל-תשה ספר גיסו ר יצחק אלחנן מיטלמן."},{"i":2976,"n":"אייז, חיים ישראל","b":"השתתף בועידת אגודת ישראל בפרשבורג-תרף."},{"i":2977,"n":"אייזא מסטריא","b":"רב בסטריא"},{"i":2978,"n":"אייזיקוב, שמואל מוילנא","f":"זליג","bt":"1872","bp":"אולקניק-פלך וילנא","dt":"1939","dp":"וילנא","b":"מחנך בוילנא ומנהל \"תורת אמת\". חיבר עם ב. פרדקין - מלון כיס רוסי עברי - וילנא תרעד."},{"i":2979,"n":"אייזיקוביץ, דוד אריה מחוסט","f":"שמאל מסעליש","k":"בעל מגדל דוד","b":"תלמיד הדעת סופר, ור משה גרינולד מחוסט. חתן ר שמעון משה הטרשטין מחוסט. מחכמי חוסט וראש הח\"ק."},{"i":2980,"n":"אייזיקס, אברהם מארה\"ב","f":"שמואל מאיר","bp":"ניו יורק","b":"תלמיד ביהמ\"ד לרבנים בברסלוי, ראש המורים לספרות גרמנית בניו יורק. סופר באנגלית, ומטיף בקהלת \"בני ישורון\" בפטרסון-ניו ג'רסי."},{"i":2981,"n":"אייזיקס, מאיר שמואל מניוארק","f":"שמואל","bt":"תרא","bp":"ניו יורק","dt":"תרסד","dp":"ניו יורק","b":"אביו היה רב \"בני ישורון\" בנ\"י. תלמיד אוני' נ\"י ועורך דין ופרופסור למשפטים, שופט. פעיל בעניני היהודים, ובעיקר בעניני מוסדות צדקה. נשיא מפעל הצדקה של הברון הירש. פעיל בעתון היהודי של אביו."},{"i":2982,"n":"אייזיקס, צבי מדרום אפריקה","bp":"סובאלק","b":"הגיע בילדותו לאנגליה. רב בלונדון, יוהניסבורג-דרום אפריקה-תרנד, רב בקימברלי-דרום אפריקה-תרס. קיבל אות כבוד על פעילותו למען הבריטים בזמן מלחמת הבורים והמצור בקימברלי, ונזכר בספרו של לורד רוברטס על המלחמה. חיבר מאמרים באנגלית."},{"i":2983,"n":"אייזיקס, שלמה משאוועל","b":"רב בשאוועל-תר\"מ"},{"i":2984,"n":"אייזיקס, שמואל הלל מניו יורק","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":2985,"n":"אייזיקס, שמואל מאיר מלונדון","bt":"תקסד","bp":"לעווארדן-הולנד","dt":"תרלח","b":"עבר בילדותו עם הוריו ללונדון. הגיע לארה\"ב-תקצח, וכיהן כרב החרדים יוצאי אשכנז. לחם בריפורמים, וכתב הרבה מאמרים ב\"אקסידענט\". גזבר קופת ארץ ישראל באמריקה. הסכים על \"עמק רפאים\" ניו יורק תרכה - כנגד הריפורמים."},{"i":2986,"n":"אייזנמנגר","b":"גרמני שלמד עברית ותלמוד. חיבר ספר בגרמנית \"היהדות החשופה\" כנגד היהודים. בעזרת ר שמשון ורטהיים מוינה נעצרה הפצת הספר בפפד\"מ-תס, ועל כך תבע אייזנמנגר את קהילת פפד\"מ לדין, המשפט נמשך ע\"י יורשיו שנים רבות ומלכי גרמניה תמכו בהם, והיהודים זכו בדין-תקלג בוינה."},{"i":2987,"n":"אייזנשיץ, אברהם מטרישט ופרשבור","k":"בעל יפה נוף-כת\"י"},{"i":2988,"n":"אייכל, יצחק אהרן מהאזנפוט","f":"משה אברהם","bt":"תקטז","dt":"תקסד","b":"תלמיד בן מנחם בעל \"העתקת תפלת ישראל\" ו\"דברי קהלת\". מיושבי האזנפוט-תקס אצל אחיו - ר פנחס. נזכר בתולדות היהודים לגרץ."},{"i":2989,"n":"אייכל, פנחס מהאזנפוט","f":"משה אברהם","b":"חתן הגביר ר חיים מהאזנפוט. אחיו של הסופר - ר יצחק אהרן. מחכמי האזנפוט-תקס והיה יועץ שופטי העיר."},{"i":2990,"n":"איילבירט, אברהם משה מארה\"ב","k":"בעל זכר אברהם","b":"שו\"ב בסט. לואיס-ארה\"ב-תרפה. חיבר גם \"חקר הלכה\" בהלכות שחיטה."},{"i":2991,"n":"איינבינדר, משה מפאדולאטשוסקא","b":"גביר בפאדואלאטשוסקא, מכתב הוקרה אליו מאת ר יהושע קראהן מבראשטשוב-תרסג."},{"i":2992,"n":"איישטיין, שמואל חיים","b":"קנה את כתב היד של \"שאגת אריה החדשות\" ואת הוספות בן המחבר ר אשר גינצבורג, מאת ר גרשון אמשטרדם שרכשם מר אשר בן המחבר. הו\"ל בוילנא תרלד."},{"i":2993,"n":"איכהורן, יעקב מקראקא","f":"יוסף","k":"יעקב חיד\"א","bt":"תקכ","dt":"תרה - כח חשון","dp":"קראקא","b":"מחכמי קראקא, חתן ר שלמה זלמן רוזס שהיה בעל תוקע אצל הבעש\"ט. עלה לצפת-תקץ, חזר לקראקא ושימש שם כרב. חיבר \"עפר יעקב\" ברסלוי תקצט עם הסכמות חכמי צפת, ועוד, על ספריו הסכימו ר ישראל משקלוב ועוד."},{"i":2994,"n":"איכלר, דוד מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":2995,"n":"איכנבוים, יעקב","f":"משה","k":"בעל קול זמרה","bt":"תקנז","bp":"קריסנפולי","b":"משורר מחכמי זאמושט, נדד במקומות רבים, ובהם אומאן, מוהילוב, אודסה וישב אצל הגביר אפרתי, משגיח בביה\"ס של המדינה בקישינוב. חיבר ספרים בלשון אשכנז. חיבר גם \"הקרב\", \"הקוסם\", ועוד. פרסם שירים בכתבי את ובהם \"ציון\", \"פרחי צפון\", \"המליץ\", ועוד."},{"i":2996,"n":"איכנטשין, יצחק מזידיטשוב","f":"אברהם חיים מזידיטשוב","k":"אדמור מזידיטשוב","dt":"תרף - ד אייר","b":"אדמור בזידיטשוב על מקום אביו."},{"i":2997,"n":"איכנשטין (גוטליב), שלמה","f":"ישכר דב בריש","bt":"תרן","bp":"חודרוב","dt":"תשג","b":"חתן ר שמואל הורביץ אב\"ד דמביץ. רב בלודמיר, חודרוב (עזב בגלל מחלוקת עם ראשי הקהל יחד עם הדיין ר משה ראובן גינצבורג), סכודניצה-תרפח, שדלץ-תרצו. נספה בשואה."},{"i":2998,"n":"איכנשטין, א' ליפא","f":"יצחק אייזיק איכנשטין"},{"i":2999,"n":"איכנשטין, א' ליפא","dt":"תשד","b":"רב בסטריסוב"},{"i":3000,"n":"איכנשטין, אברהם","dt":"תשא","b":"רב בבאראנוב,לובלסק"},{"i":3001,"n":"איכנשטין, אברהם חיים מזידיטשוב","f":"מנחם מנדל","bt":"תרך","dt":"תרסט-פד-כו ניסן","dp":"זידיטשוב","b":"חתן ר יחזקאל גולדשלג מרוהטין. אב\"ד זידיטשוב-תרסח. בנו ר יצחק האדמור מזידיטשוב. חתנו - ר הנך בן מנחם מנדל מאלסק."},{"i":3002,"n":"איכנשטין, אברהם מזידיטשוב שיקג","f":"יהושע השל מחודרוב","k":"אדמור מזידטשוב","dt":"תשכז - כב תמוז","b":"חתן רפנחס שלום רוטנברג. אדמור מזידיטשוב בשיקגו, ובנו ר יהושע השל על מקומו אחריו. עוד מבניו: ר מנחם צבי אב\"ד סט לואיס, ור משה משיקגו. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":3003,"n":"איכנשטין, אהרן מאיר מקאשוי","dt":"תשד","b":"חתן ר מנחם מנדל מזידיטשוב. רב בקאשוי. בנו - ר יצחק."},{"i":3004,"n":"איכנשטין, אהרן מנחם מנדל מאלס","f":"אלכסנדר סנדר יו\"ט","k":"אדמור מאלסק","bt":"תרך","dt":"תרפג - יט אב","dp":"למברג","b":"חתן ר יצחק מאלסק, ובזיוו\"ש חתן ר חיים יחיאל מגלוגוב (רופשיץ). רב ואדמור באלסק-תרסד על מקום חותנו, למברג-בזמן מלחה\"ע ה-I."},{"i":3005,"n":"איכנשטין, אהרן מראזלא","f":"אברהם חיים מזידיטשוב","dt":"תשג - ה אד\"א","dp":"ציצלוביץ-ליד סטרי","b":"ממשפחת אדמורי זידיטשוב. נספה בשואה."},{"i":3006,"n":"איכנשטין, איזיק","dt":"תשג","b":"רב בפדהייץ"},{"i":3007,"n":"איכנשטין, אליהו מזידיטשוב","f":"יצחק איזיק מזידיטשוב","bt":"תקצו","dt":"תרלה-ח - ה סיון","b":"חתן ר יהודה ליביש ארליך מרוזדול-חתן ר בי הירש מזידיטשוב. רב בחסידות זידיטשוב, אדמור בזידיטשוב על מקום אביו, ובצוואתו הוריש את האדמורות לאחיו ר ישכר דב בעריש שהיה אדמור מזידיטשוב בדולינא. מקצת מתורתו בספר \"זכרון אליהו\" המבוסס על דברי אביו."},{"i":3008,"n":"איכנשטין, אליהו מזידיטשוב","f":"משה מזידיטשוב","bt":"תרמד","dt":"תשג - א סיון","b":"רב בזידיטשוב על מקום אביו. חתן ר מנחם מנדל קנר מסאנוק. נספה בשואה."},{"i":3009,"n":"איכנשטין, אליהו מזקופנה","f":"שלמה יעקב מסטרי","bt":"תרמג","dt":"תרצח","b":"חתן ר חיים דוד שטורך מזקופנא וניו יורק. רב בזקופנה-תרסה על מקום חותנו, ובנו ר יצחק איזיק על מקומו אחריו."},{"i":3010,"n":"איכנשטין, אלימלך מוולדיזש","f":"פנחס מסטרי","b":"רבה של וולדיזש בין שתי המלחמות."},{"i":3011,"n":"איכנשטין, אלכסנדר משה מרידיק","f":"[יעקב קופל]","dt":"תרעד","b":"אב\"ד רידיק-תרעב, בנו ר יצחק על מקומו אחריו, ובנו ר שמריה רב בקולומיאה."},{"i":3012,"n":"איכנשטין, אלכסנדר סנדר יום טוב","f":"יצחק איזיק","k":"אדמור מזידיטשוב","bt":"תקפד","dt":"תרמד - יא תשרי","b":"תלמיד ר יהודה מרוזלא, חתן ר אלעזר וייזר, ובזיוו\"ש חתן ר יהודה ליביש מסטרי-בן בעל \"מלוא הרועים\". אב\"ד זידיטשוב בחיי אביו, ואדמור אחרי פטירת אביו."},{"i":3013,"n":"איכנשטין, אלכסנדר סנדר ליפא","f":"יוסף","bt":"תרם","dt":"תש","dp":"תש","b":"אביו היה האדמור מטרנופול. רבה של סטריסוב."},{"i":3014,"n":"איכנשטין, אלכסנדר סנדר מקומרנא","f":"יצחק איזיק מספרין","k":"אדמור מקומרנא","bt":"תקל","bp":"ספרין","dt":"תקעח - כא אב","dp":"אויהעל","b":"חתן ר יעקב קופל מליקובא. מתלמידי החוזה מלובלין. אב\"ד זידיטשוב, זורובנא, קומרנא-תקעב. חיבר \"זכרון דברים\" למברג תרלא."},{"i":3015,"n":"איכנשטין, אלתר יצחק שלום מבוס","f":"חנוך הניך מאלסק","k":"אדמור מזידיטשוב-בוסק","dt":"תשג - יג אייר","b":"חתן ר אלתר ישכר מאלטשטאט (שושלת קומרנא). רב ואדמור בבוסק."},{"i":3016,"n":"איכנשטין, אלתר משה מיריטשוב","f":"שלמה יעקב מסטרי","k":"אדמור מיריטשוב","bt":"תריג","dt":"תרף","dp":"זידיטשוב","b":"חתן ר יהושע רוזנפלד מקמינקא,"},{"i":3017,"n":"איכנשטין, אשר","b":"רב בפרוכניק-תר\"ס"},{"i":3018,"n":"איכנשטין, אשר ישעיה מניו יורק","f":"שלום מזידיטשוב צפת","b":"מצאצאי אדמורי זידיטשוב, וחוקר חסידות זידיטשוב."},{"i":3019,"n":"איכנשטין, אשר ישעיה מפרוכניק","f":"ישכר בריש מזידיטשוב","bt":"תרכד","dt":"תרפז","b":"חתן ר יחיאל השל האדמור מקריליביץ. אב\"ד פרוכניק-תרנד בוברקא-תרע. חותנו זקנו היה המהר\"י מבלז ואצלו ישב כעשר שנים."},{"i":3020,"n":"איכנשטין, בן ציון מצאנז","f":"יהודה","b":"אב\"ד צאנז-תרצב. בנו ר משה גם הוא אב\"ד צאנז - נספה בשואה."},{"i":3021,"n":"איכנשטין, זאב וולף מישיניצה","f":"שלמה יעקב מישיניצה","bt":"תרל","dt":"תש","b":"רבה של ישיניצה-תרפב על כסא אביו."},{"i":3022,"n":"איכנשטין, חיים יוסף מאוקליבה","f":"מנשה מוורצקי","k":"אדמור מאוקליבא","dt":"תשג","b":"רב ואדמור באוקליבא (הוקשיווא), ואלוויץ, מונקטש על מקום אביו. נספה בשואה."},{"i":3023,"n":"איכנשטין, חיים משה מאלטשטט","f":"אלכסנדר סנדר","k":"אדמור מאלטשטט","b":"רב ואדמור באלטשטט."},{"i":3024,"n":"איכנשטין, חנוך הניך מבוסק","f":"אהרן מנחם מנדל מאלסק","k":"אדמור מבוסק","dt":"תרפט","b":"רב ואדמור בבוסק, בנו ר אלתר יצחק שלום על מקומו אחריו. חתן ר אברהם חיים איכנשטין מזידיטשוב."},{"i":3025,"n":"איכנשטין, י' ליבוש","dt":"תשד","b":"רב בלאדמיר"},{"i":3026,"n":"איכנשטין, יהודה מסנוק","f":"אלכסנדר סנדר","k":"אדמור מסנוק","b":"אדמור בסנוק-תרסג. בניו - ר בן ציון מצאנז, ר משה יואל מלונדון."},{"i":3027,"n":"איכנשטין, יהודה צבי","f":"ישראל צבי רוטנברג","dt":"תשא - אלול","b":"רב בדובראני","bk":[["דעת קדושים","מאמרים לשבתות ועניינים שונים"]]},{"i":3028,"n":"איכנשטין, יהודה צבי הירש מדולי","f":"ישכר דב בריש מדולינא","k":"אדמור מדולינא","bt":"תריח","dt":"תרסט - יב אייר","b":"חתן ר משה אונגר (דומברובא)-חתנו של ר חיים מצאנז, וישב אצלו 3 שנים. אדמור בדולינא(=דאלין), חתנו ר יהושע הלברשטם מילא את מקומו כאדמור אחר פטירתו. כתב נגד הציונות ב\"דובב שפתי ישנים\". גנז את כתביו. חיבר הקדמות לספרי אביו ודודו. חיבר \"צמח צבי לצדיק\"."},{"i":3029,"n":"איכנשטין, יהודה צבי הירש מרוזד","f":"משה מסמבור","k":"אדמור מזידיטשוב","r":"אבדק\"ק ראדאזל","bt":"תקנא","dt":"תרח - ז חשון","b":"תלמיד וחתן דודו ר צבי הירש האדמור מזידיטשוב, רב בגלינא, בורדשין, רוזדול, אדמור מזידיטשוב ברוזדול על מקום דודיו. חיבר \"דעת קדושים\" למברג תרט, ועוד.","bk":[["דעת קדושים",""],["תעלומות חכמה (רוזדול/ראזלא)",""],["דעת קדושים - קבלה",""],["עמוד התורה - קבלה",""],["תעלומות חכמה - על התורה",""]]},{"i":3030,"n":"איכנשטין, יהושע השל","f":"משה בן אברהם משיקגו","b":"נכד ר אברהם איכנשטין האדמור מזידיטשוב בשיקגו. לא נוהג אדמורות. ראש בימ\"ד בשיקגו."},{"i":3031,"n":"איכנשטין, יהושע השל מחודרוב","f":"אלכסנדר סנדר יו\"ט ל'","bt":"תרב","dt":"תרמה","b":"חתן ר אליעזר מאוזפולי (סטרטין). אב\"ד חודרוב, בנו ר ישכר דב בריש על מקומו אחריו."},{"i":3032,"n":"איכנשטין, יהושע השל מחודרוב","f":"ישכר דב בריש","k":"אדמור מחודרוב בשיקגו","bt":"תרמב","dt":"תש - יא אד\"ב","b":"חתן ר אלתר זאב מסטריזוב (שושלת רופשיץ). אב\"ד חודרוב על מקום אביו, היגר לארה\"ב-תרפב-ד והיה רב וראשון האדמורים בשיקגו."},{"i":3033,"n":"איכנשטין, יהושע השל מירושלים","f":"מנחם צבי מסט לואיס","b":"עלה לירושלים. ראש ישיבת יד אהרן."},{"i":3034,"n":"איכנשטין, יהושע השל משיקגו","f":"אברהם מזידיטשוב שיקג","b":"חתן ר אברהם דוד הורביץ משטרסבורג. אדמור מזידיטשוב בשיקגו על מקום אביו."},{"i":3035,"n":"איכנשטין, יהושע מגרוסורדין","f":"אשר ישעיה מפרובניק","k":"אדמור מזידיטשוב גרוס","bt":"תרנה-ו","bp":"פרוכניק","dt":"תשה - טז סיון","dp":"הולצהוזן (ליד מינכן) -צפת","b":"תלמיד מהרש\"ם מברעזאן, ובעל \"ערוגת הבושם\". חסיד בלז. תלמיד וחתן ר חיים ירוחם מאלטשטט (=סאמבור) רב בפרוכניק-תרעד על מקום אביו, רב ואדמור חסידי זידיטשוב בגרוסורדין-תרפב. ניצל מהשואה - אך נפטר מיד בסופה במחנה הולצהוזן-גרמניה."},{"i":3036,"n":"איכנשטין, יהושע מזידיטשוב פ\"ת","f":"ישכר בעריש מזידיטשוב","k":"אדמור מזידיטשוב בפ\"ת","bt":"תרפח","b":"אדמור מזידיטשוב בפ\"ת על מקום אביו בעל \"ישועת ישכר\"."},{"i":3037,"n":"איכנשטין, יואל משה מטרנוב","dt":"תש..","b":"רב בטרנוב. נספה בשואה."},{"i":3038,"n":"איכנשטין, יוסף מטרנופול","f":"אלכסנדר סנדר יו\"ט","k":"אדמור מטרנופול","dt":"תשג","b":"חתן ר נחום מבורשטין (סטרטין). אדמור בטרנופול-תרפז. בנו ר אלכסנדר ליפא מסטריסוב."},{"i":3039,"n":"איכנשטין, יחזקאל מנמירוב","k":"אדמור מנמירוב","dt":"תשג","b":"אדמור בנמירוב. נספה בשואה."},{"i":3040,"n":"איכנשטין, יחיאל מיכל מזידיטשוב","f":"משה","k":"אדמור מזידיטשוב בסמב","bt":"תקנה","dt":"תרה","dp":"זידיטשוב","b":"אדמור מזידיטשוב בסמבור. חיבר \"עטרת זקנים\" למברג תרסח."},{"i":3041,"n":"איכנשטין, יעקב מלימנוב","f":"אלתר שמואל מלימנוב","bt":"תרעח","dt":"תשג","b":"תלמיד ישיבות טשבין ובובוב. נספה בשואה."},{"i":3042,"n":"איכנשטין, יצחק איזיק","f":"צבי","dt":"תקב - ב אדר","b":"רב בספרין. אחד מהאחים במסל\"ה."},{"i":3043,"n":"איכנשטין, יצחק איזיק","dt":"תשג","b":"רב בזאקופאנע"},{"i":3044,"n":"איכנשטין, יצחק איזיק מזידיטשוב","f":"ישכר בריש","k":"אדמור מזידיטשוב","r":"רב בזידיטשוב","bt":"תקסה","dt":"תרלג - ט סיון","b":"תלמיד דודיו ר צבי הירש מזידיטשוב ור משה מסמבור. אדמור בזידיטשוב, מחשובי האדמורים בדורו. חיבר \"לקוטי תורה והש\"ס\" למברג תרלז, \"פירושי מהרי\"א\", \"לקוטי מהרי\"א\" למברג תרן, ועוד. מתולדותיו ב\"פאר יצחק\".","bk":[["ילקוט מהרי\"א - תורה מדרש רבה וילקוט שמעוני",""],["ליקוטי מהרי\"א – ילקוט שמעוני",""],["ליקוטי תורה והש\"ס",""],["פירוש מהרי\"א – מדרש רבה",""],["פירוש מהרי\"א – מדרש רבה, ליקוטי מהרי\"א – ילקוט שמעוני , ליקוטי תורה והש\"ס",""]]},{"i":3045,"n":"איכנשטין, יצחק איזיק מזקופנה","f":"אליהו","k":"בעל חגים וזמנים","dt":"תש..","b":"ר\"מ בישיבת רסיגיווא. רב על מקום חו\"ז ר אהרן וייס. רב בזקופנה על מקום אביו. נספה בשואה. חיבר \"חגים וזמנים\" מונקטש תרצח."},{"i":3046,"n":"איכנשטין, יצחק איזיק מנחם","f":"שלמה יעקב מסטרי","k":"אדמור מפודהייץ","bt":"תרלט","bp":"זידיטשוב","dt":"תשג - יג אדר","dp":"פודהייץ","b":"תלמיד וחתן ר נחום בנרדוין מבורשטין. אדמור בפודהייץ-תרסט. נספה בשואה."},{"i":3047,"n":"איכנשטין, יצחק איזיק מספרין","f":"צבי בן אלכסנדר מסטבנ","bt":"תק","bp":"ספרין","dt":"תקס - א אדר","b":"מצאצאי התוספות יום טוב, היה מקורב לבעל \"קצות החושן\" והיה שואל אותו בתורה. נודע כצדיק נסתר והתפרנס ממסחר בחנותו. מראשוני חסידיו של החוזה מלובלין. חמשת בניו מכונים בראשי תיבות \"במסל\"ה\" (ר\"ת בעריש, משה, סנדר, ליפא, הירש)."},{"i":3048,"n":"איכנשטין, יצחק איזיק מקאשוי","f":"אהרן מאיר מקאשוי","bt":"תרעג","bp":"קאשוי","b":"חתן האדמור ר אלעיזר שפירא מקיבישוב. ניצל מהשואה, ואחריה רב בקאשוי וארגן את שרידי הקהלה עם חברו ר רפאל בלום, היגר לניו יורק-תשח וחבר לאדמור ר יואל מסטמר."},{"i":3049,"n":"איכנשטין, יצחק מרידיק","f":"אלכסנדר משה מרידיק","bt":"תרנב","dt":"תשא","b":"רב ברידיק על מקום אביו-תרעד. (היה במחלוקת עם האדמור המקומי ר פנחס נתן ספרין). נספה בשואה."},{"i":3050,"n":"איכנשטין, ישכר בריש","f":"יהושע מגרוסורדין","k":"אדמור מזידיטשוב בפ\"ת","r":"אדמו\"ר מזידיטשויב פתח תקוה","bt":"תרפח","dt":"תשמט - יב אב","b":"ניצל מהשואה. עלה לארץ-תשה. דיין ואדמור מזידיטשוב בפתח תקוה-תשלא על מקום דודו ר מנשה יצחק מאיר. בנו ר יהושע על מקומו אחריו. חיבר \"ישועת ישכר\" פתח תקוה תשן.","bk":[["ישועת ישכר - עה\"ת",""],["שמחת ישכר",""],["שמחת ישכר, ישועת ישכר - עה\"ת",""]]},{"i":3051,"n":"איכנשטין, ישכר בריש מזידיטשוב","f":"אלכסנדר סנדר יו\"ט","k":"אדמור מוורצקי-זידיטש","bt":"תרח (י\"א תרד)","bp":"זידיטשוב","dt":"תרפד - כא ניסן","b":"תלמיד זקנו המהרי\"א. חתן ר מנשה מרופשיץ, חמיו של ה\"חקל יצחק\", רב ואדמור בוורצקי-ליד מונקטש-תרלג, זידיטשוב-תרע או תרעג, גרוסורדין-בזמן מלחה\"ע ה-I, מונקטש-תרפב. חיבר \"מלבוש לשבת ויום טוב\" מונקטש תרפז."},{"i":3052,"n":"איכנשטין, ישכר בריש מזידיטשוב","f":"יצחק איזיק מספרין","k":"אדמור מזידיטשוב","bt":"תקכה","dt":"תקצב - ז סיון","b":"תלמיד אחיו ר צבי הירש, ר משה יהודה ליב מסאסוב, והחוזה מלובלין. חתן הגביר ר אליהו לנגנויער מרידניק. היה רב ואדמור בזידיטשוב על מקום אחיו ר צבי הירש."},{"i":3053,"n":"איכנשטין, ישכר בריש מניו יורק","f":"שלום מזידיטשוב צפת"},{"i":3054,"n":"איכנשטין, ישכר דב בר מזידיטשוב","f":"יצחק איזיק מזידיטשוב","k":"אדמור מדולינא זידיטש","bt":"תקצה","dt":"תרמו - כט שבט","b":"חתן ר אברהם מסטרטין. דיין בזידיטשוב-תרטז, אדמור בדולינא על מקום אביו, ואחר פטירת אחיו ר אליהו מזידיטשוב עברו אליו חסידיו על פי צוואתו. השתתף באספת היסוד של \"מחזיקי הדת\". תלמידו הדפיס תורה שאמר בשם \"לקוטי תורה מהר\"י\" למברג תרמו."},{"i":3055,"n":"איכנשטין, ישכר דב בריש מחודרוב","f":"יהושע השל מחודרוב","bt":"תרך","dt":"תרעח - ח אלול","b":"נכדו של המהרי\"א, חתן ר נחום גוטליב מלודמיר (משושלת קרלין). אב\"ד חודרוב על מקום אביו, בנו ר יהושע השל ישב אחריו על כסאו."},{"i":3056,"n":"איכנשטין, ישכר דב מניו יורק","f":"מנחם צבי מסט לואיס","b":"רב בניו יורק."},{"i":3057,"n":"איכנשטין, ישכר דוב מגרוסורדין","b":"רב לחסידי זידטשוב בגרוסוורדיין-תר\"פ"},{"i":3058,"n":"איכנשטין, ישראל יוסף","f":"צבי הירש","bt":"תרג","b":"חתן ר אהרן מאיר פרידלנדר מבוליחוב."},{"i":3059,"n":"איכנשטין, ליפא מסמבור","f":"יצחק איזיק","bt":"תקם","dt":"תקפא - ד אייר","b":"אחד מהאחים \"במסל\"ה\". נפטר בצעירותו - מסר נפשו למען אחיו ר צבי הירש, ואחיו רצ\"ה גידל את בנו ר טוביה ובנותיו."},{"i":3060,"n":"איכנשטין, מאיר מקאשוי","f":"חיים פרידלנדר","k":"אדמור מזידיטשוב בקאש","dt":"תשד","b":"רב ואדמור מזידיטשוב בקאשוי. חתן ר מנחם מנדל איכנשטין מזידיטשוב - ומכאן שמו. נספה בשואה."},{"i":3061,"n":"איכנשטין, מנחם מנדל","f":"אהרן מאיר","dt":"תשה","b":"רב בזידיטשוב, נספה בשואה."},{"i":3062,"n":"איכנשטין, מנחם מנדל מזידיטשוב","f":"יצחק איזיק","k":"בעל אדם וחוה ותולדות","r":"אחיו של בעל הישועות יעקב","bt":"תר","dt":"תרסא - יא אדר","b":"נקרא על שם ר מנחם מנדל מרימנוב, תלמיד וחתן ר חיים אברהם רדליק ממיקוליב, אב\"ד במיקוליב על מקום חותנו, זידיטשוב-תרמד. חיבר גם\"מנחם צדק צדקה\", ועוד.","bk":[["אדם וחוה ותולדותיהם",""],["ליקוטי מהרמ\"ם",""],["מנחם משיב נפשי ציון ובונה ירושלים צדק צדקה צדיק",""],["מנחם צדק",""],["ספר הכל",""],["ספר הליקוטים",""],["ספר יעקב ישראל וישורון",""],["פרד\"ס מנחם צדק צדקה צדיק",""]]},{"i":3063,"n":"איכנשטין, מנחם מנדל מזידיטשוב","f":"אברהם חיים מזידיטשוב","k":"אדמור מזידיטשוב","bt":"תרע","dt":"תשג - כט אייר","b":"חתן ר אפרים מרוזוודוב (שושלת רופשיץ). אדמור בזידיטשוב-תרפד על מקום אביו. נסע לאדמורי קומרנא. נספה בשואה."},{"i":3064,"n":"איכנשטין, מנחם צבי מסט לואיס","f":"יהושע השל מחודרוב","b":"חתן ר משה מרדכי טברסקי האדמור מטריסק לובלין. אב\"ד סט לואיס-ארה\"ב. לכבודו יצא \"היובל\" סט לואיס תשטו."},{"i":3065,"n":"איכנשטין, מנחם צבי מסט לואיס","f":"אברהם מזידיטשוב שיקג","b":"בן האדמור מזידיטשוב בשיקגו. רב בסט לואיס."},{"i":3066,"n":"איכנשטין, מנחם צבי מסטריזוב","f":"יהושע השל מחודרוב","k":"בעל פרי יהושע","bt":"תרע","bp":"סטריזוב","dt":"תשמא","b":"נשלח מארה\"ב על ידי הוריו ללמוד בישיבת דושינסקי בחוסט, בפרשבורג אצל הדעת סופר ובישיבת חכמי לובלין. חתן ר משה מרדכי טברסקי האדמור מטריסק לובלין. חזר לארה\"ב והיה רב בשיקגו, סנט לואיס - למעלה מארבעים שנה. חיבר \"פרי יהושע\" סנט לואיס תשט."},{"i":3067,"n":"איכנשטין, מנשה יצחק מאיר","f":"אשר ישעיה מפרוכניק","k":"אדמור מזידיטשוב בפ\"ת","bt":"תרנד","dt":"תשלא - כז טבת","b":"חתן ר שמעון שיף האדמור מליזנסק בקלויזנבורג ועבר לשם. אדמור מזידיטשוב בפטרזיין(=פטרוז'ן)-רומניה-תרף, ניצל מהשואה ואחריה התישב בקלויזנבורג. עלה לפתח תקוה. נפטר חשוך ילדים."},{"i":3068,"n":"איכנשטין, מנשה מרישא","f":"ישכר בריש מוורצקי","k":"אדמור מזידיטשוב","bt":"תרכה","dt":"תרצה - טז תמוז","b":"חתן ר יהושע הורביץ מדזיקוב. נבחר לרב בבוברקא אך לא כיהן (בגלל שנדרש לשם סכום גבוה), רב ואדמור מווורצקי ברישא והיה שם מראשי חסידי צאנז. אדמור מזידיטשוב במונקטש. חיבר \"אלפי מנשה\" פרמישלא תרנה, ועוד."},{"i":3069,"n":"איכנשטין, משה מדרוהוביטש","f":"ישראל יוסף מזידיטשוב","k":"אדמור מזידיטשוב בדרו","bt":"תריז","dt":"תרצט - יז ניסן","b":"אדמור מזידיטשוב בדרוהוביטש. חתן ר יחיאל מקולבסוב (אויהל), וחתן למשפחת ר מרדכי מנדבורנה. בנו ר יהודה צבי - חתן האדמור יולס מסמבור."},{"i":3070,"n":"איכנשטין, משה מזידיטשוב","f":"ישכר בריש מוורצקי","k":"בעל זכרון משה","bt":"תרלד","dt":"תשד - ג סיון","b":"חתן ר צבי הירש ערליך-נכד ר צבי הירש מזידיטשוב, ובזיוו\"ש חתן דודו ר אליהו מזידיטשוב - וממנה ילדיו. אב\"ד זידיטשוב-תרנב, רב ואדמור בוורצקי על מקום אביו, מונקטש, נספה בשואה. המשכילים הדפיסו כנגדו ספר \"עמק יהושפט\". חיבר \"זכרון משה\" ניו יורק תשמה. בנו ר סנדר ליפא-נספה בשואה ג סיון תשד."},{"i":3071,"n":"איכנשטין, משה מסכודניצה","f":"יהושע השל","bt":"תרלב","dt":"תשב","b":"אב\"ד סכודניצה, נספה בשואה עם משפחתו."},{"i":3072,"n":"איכנשטין, משה מסמבור","f":"יצחק איזיק מספרין","k":"אדמור מסמבור-תפלה למ","bt":"תקכה-לב","bp":"ספרין","dt":"תר - ו אייר","b":"בנו של ר יצחק מספרין (אחד מ\"במסל\"ה\" ראשי תיבות 5 הבנים). חתן ר יודל בן ר משה יוסף מדרוניטשין. התגורר בסמבור. היה תלמיד של אחיו ר צבי הירש. נפגש עם גדולי האדמורים שכבדוהו מאוד ובהם החוזה מלובלין. בשנת תקצב נעשה אדמור בסמבור. חיבר \"תפלה למשה\" למברג תרטז. בנו ר יעקב קופל - רב ברידיק-תקס.","bk":[["תפלה למשה - על התורה מלא מוסר ויראת השם",""]]},{"i":3073,"n":"איכנשטין, משה מצאנז","f":"בן ציון","b":"רב בצאנז, על כסא אביו. נספה בשואה."},{"i":3074,"n":"איכנשטין, משה מרדכי מטריסק","f":"דב בער","k":"אדמור מטריסק בי-ם","b":"אדמור מטריסק בירושלים."},{"i":3075,"n":"איכנשטין, משה מרידיק","f":"יהודה","dt":"תשיז","dp":"לונדון","b":"אב\"ד רידיק, חתן הרב מונד ממוסט גדול. כנראה היה בנו של ר יהודה מסאנוק. עבר ללונדון לפני השואה וכיהן כאדמור."},{"i":3076,"n":"איכנשטין, משה מרישא","b":"חתן ר אליעזר הורביץ. רב ברישא-תרן. חתנו - ר ישעיה אשר יולס. (כנראה טעות והכוונה לר מנשה)"},{"i":3077,"n":"איכנשטין, מתתיהו אהרן מרוזדול","dt":"תשג","b":"רב ברוזדול. נספה בשואה."},{"i":3078,"n":"איכנשטין, מתתיהו מהולשיץ","f":"מנשה מוורצקי-אלפי מנ","k":"אדמור מדזיקוב בארה\"ב","bt":"תרמו","bp":"דזיקוב","dt":"תשל - ה אלול","b":"חתן ר אברהם יעקב זילברשטין אב\"ד הולשיץ, היגר לארה\"ב-תרפד, וכיהן כאדמור מדזיקוב."},{"i":3079,"n":"איכנשטין, נתן מזידיטשוב ת\"א","f":"יהושע מגרוסורדין","k":"אדמור מזידיטשוב בת\"א","dt":"תשלו - א אד\"ב","b":"נכד ר אשר ישעיה מפרוכניק. חתן ר שמריהו גור אריה-נכד ר משה צבי מסאווראן. רב בטטרוש, גרוסורדין, ניצל מהשואה ואחריה עלה לארץ, אדמור מזידיטשוב בתל אביב."},{"i":3080,"n":"איכנשטין, סנדר ליפא מסטרי","f":"פנחס","b":"חתן ר שלום מלוביטשוב (משושלת בלז)."},{"i":3081,"n":"איכנשטין, פנחס מסטרי","f":"אלכסנדר סנדר יו\"ט","k":"אדמור מסטרי זידיטשוב","b":"בנו של האדמור מזידיטשוב. חתן ר אלימלך מיריטשוב. בנו - ר סנדר ליפא - חתנו של ר שלום רוקח מליביטשוב."},{"i":3082,"n":"איכנשטין, צבי הירש מזידיטשוב","f":"יצחק איזיק מספרין","k":"אדמור מזידיטשוב","r":"אב\"ד יאס והמדינה","bt":"תקכג","dt":"תקצא - יא תמוז","dp":"זידיטשוב","b":"בכור האחים \"במסל\"ה\" - ראשי תיבות בניו של ר יצחק איזיק. היה תלמיד ר יצחק חריף מסמבור, נעשה תלמידו של החוזה מלובלין בהשפעת אחיו ר משה מסמבור, והיה מקורב לגדולי האדמורים. היה לאדמור בחיי רבו החוזה-תקעא, ולאחר פטירת ר נפתלי מרופשיץ היה למנהיג חסידי גליציה ולנשיא ארץ ישראל. תלמידיו היו ארבעת אחיו, ארבעת חתניו ועוד רבים. כונה בשם \"שר בית הזוהר\" ורבים עלו אל קברו. חיבר \"סור מרע ועשה טוב\" למברג תקצב (בשער תקסד - בגלל הצנזורה), \"פרי קדש הלולים\" למברג תקצג (בשער תקסב), \"עטרת צבי\" למברג תקצד, ועוד.","bk":[["צבי לצדיק",""],["בית ישראל – עה\"ת",""],["הקדמה ודרך לעץ החיים",""],["יפרח בימיו צדיק – עה\"ת",""],["עטרת צבי – זוהר",""],["פרי קודש הילולים – הקדמה לפרי עץ חיים",""],["קונטרס השמות – זוהר ויקרא",""]]},{"i":3083,"n":"איכנשטין, שלום מפרוכניק צפת","f":"אשר ישעיה מפרוכניק","k":"אדמור ממונקטש","bt":"תרסב","dt":"תשמח - ג אלול","dp":"ארה\"ב","b":"חתן ר חיים סופר סת\"ם ממונקטש. כיהן כאדמור במונקטש, סעבען, צפת, ניו יורק. ניצל מהשואה. מתורתו ב\"רב שלום\" שנדפס בתוך \"מלבוש לשבת ויו\"ט\" - נ\"י תשמח."},{"i":3084,"n":"איכנשטין, שלמה יהודה מקולומיאה","f":"צבי הירש","k":"אדמור מקולומיאה","bt":"תרל","dt":"תש..","b":"נכד האדמור מהרי\"א מזידיטשוב. אדמור בקולומיאה. חתן ר שמה ולדמן מוארשא, ובזיוו\"ש חתן דודו ר חיים פרידלנדר. נספה בשואה."},{"i":3085,"n":"איכנשטין, שלמה יעקב מסטרי","f":"יצחק איזיק מזידיטשוב","k":"אדמור מזידיטשוב סטרי","bt":"תקץ","dt":"תרמו - כו כסלו","b":"מחכמי סטרי, חתן ר יוסף רוטנברג מקוזובה (קוסון), ובזיוו\"ש חתן ר אברהם הורביץ משנדישוב (רופשיץ). אדמור בזידיטשוב, סטרי."},{"i":3086,"n":"איכנשטין, שמשון מאלסק","f":"אהרן מנחם מנדל מאלסק","k":"אדמור מאלסק","dt":"תש..","b":"חתן ר יוסף דוד מייער מססוב. רב ואדמור באלסק. נספה בשואה."},{"i":3087,"n":"אילאווי, חיים מברודא","f":"פנחס","b":"דיין בברודא, חתם-תקיח עם ר מנחם מנדל דייטש מנייטרא, ור אהרן בן יצחק מברודא."},{"i":3088,"n":"אילאווי, יעקב - א","k":"ר' יעקב אילוואי מברו","b":"רב בקעלין והמדינה-ת\"צ"},{"i":3089,"n":"אילאווי, יעקב יהודה ליב - ב","f":"ישכר דב - א","b":"מחכמי קאלין-ביהם - תקעד, בנו ר ישכר דב - באמריקה."},{"i":3090,"n":"אילאווי, ישכר דב - א","f":"יעקב מקונין","b":"זקנו של ר ישכר דב שהיה רב באמריקה-תקעד."},{"i":3091,"n":"אילאווי, ישכר דב בר מסינסינטי","f":"יעקב יהודה ליב מקלין","k":"בעל מלחמות אלקים","bt":"תקעד","bp":"קאלין","dt":"תרלא - ג תמוז","dp":"סינסינטי","b":"תלמיד החת\"ס, ור חיים דייטשמן מקאלין. חתן ר וולף שיף מרודניץ. מלמד בצנאיים (בוהמיה), עזב בגלל מלחמה והגיע לאשכנז-תרט, רב הגלליל בהעסען-קאסעל - תרי, המבורג, עבר לאמריקה וכיהן כרב ק\"ק \"שערי צדק\" בניו יורק-תריב, פילדלפיה-תריג, סניט לואיס-תרטו, סירקוז-תריז, בולטימור-תריט, ניו אורליאנס-תרכא, סינסינטי-תרכו. מהלוחמים נגד הרפורמים. תשובות ממנו בכת\"י, ונזכר בשו\"ת ר עזריאל. תשובה ממנו בענין פסול אתרוגי אמריקה והתיר בזמן מלחמת האזרחים - כהוראת שעה. העביר מוהל מתפקידו בניו אורליאנס בגלל שמל ילד שאמו נכרית - בלא טבילת גירות."},{"i":3092,"n":"אילאווי, פנחס מברוד","b":"רב בברודי. נזכר ב\"פנים מאירות\". בנו ר ישכר דב."},{"i":3093,"n":"אילאווי, צבי מאמריקה","f":"שכר דב בר מסינסינטי","k":"בעל פשט במקרא","b":"חיבר \"פשט במקרא\" - ניו יורק תרעט."},{"i":3094,"n":"אילבורג, יצחק","b":"מגדולי חכמי אשכנז,רב באשרסלבן-ר\"כ"},{"i":3095,"n":"אילגובסקי, דוד","f":"ראובן זליג","bt":"1885","bp":"דאוג","dt":"1950","dp":"תל אביב","b":"תלמיד ישיבות איישישוק, וילנא. גביר בקובנא, קבלן ממשלתי ועשיר. חבר המרכז הציוני בליטא וממיסדי העתון \"אידישע שטימע\". תמך לעניני תרבות וחנוך עבריים. עלה לארץ-1933 ובנה שכונה בתל אביב. עבר לתנועה הרביזיוניסטית, ויצא בשליחות זבוטינסקי לליטא לנצל את ידידותו עם הנשיא סמאטונה לטובת היהודים, וניהל עמו מו\"מ בדבר יציאת היהודים עם רכושים לא\"י."},{"i":3096,"n":"איליאן, גבריאל מרוען-ליפלנד","b":"חתן ר משה לרנבלט מראסיין וסאסמקין. רב ברוען-ליפלנד."},{"i":3097,"n":"איליאן, יצחק ראובן מקליקול","f":"יקותיאל זיסל (משה?)","k":"בעל שדה יצחק","dt":"תרעה","b":"חתן ר משה לרנבלאט מסאסמקין. רב בריגא, קליקול על מקום אביו?, ובנו ר אבא על מקומו אחריו."},{"i":3098,"n":"איליבצקי, אליעזר ישעיה מטעלחן","bt":"תרכב","b":"רב בטעלחאן-פלך מינסק-תרלו. נסמך מאת: ר מרדכי מלצר, ר אליהו שיק מזאגער, ר אליעזר משה הורביץ מפינסק, ר דוד פרידמן מקרלין. חתנו - ר יצחק מרדכי סנדברג."},{"i":3099,"n":"איליוביץ, גבריאל יהודה משאמשון","f":"אליהו יואל מנייפעסט","bt":"תרסז","bp":"נייפעסט","dt":"תשלט - ל סיון","dp":"ניו ג'רסי","b":"תלמיד הדעת סופר. חתן ר יוסף צבי סופר משאמשון. רבה האחרון של שאמשון על מקום חותנו-תרצא. ניצל מהשואה ואחריה רב בבודפשט, האהענענמס (אוסטריה)-תשט, ניו יורק."},{"i":3100,"n":"איליוביץ, יוסף צבי משאמשאן","f":"גבריאל יהודה משאמשן","b":"רב בשאמשון-ברוקלין."},{"i":3101,"n":"איליוביץ, יצחק יעקב מקאשוי","f":"גבריאל יהודה משאמשן","b":"רב בקאשוי-ברוקלין."},{"i":3102,"n":"איליוביץ, מאיר אברהם מסן פאולו","f":"גבריאל יהודה משאמשן","b":"רב בסן פאולו."},{"i":3103,"n":"אילן, מרדכי","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":3104,"n":"אילנבורג יששכר בר בן ישראל","bt":"1550","dt":"ה'שפג 1623","bk":[["באר שבע",""]]},{"i":3105,"n":"אילנברג, אברהם מטויסט","f":"חיים יוסף מלמברג","k":"בעל עט אברהם","bt":"תרכח","dt":"תרנד - יג אלול","b":"נכדו של ר שמחה נתן, אב\"ד טויסט. חיבר \"עט אברהם\" בכתב יד."},{"i":3106,"n":"אילנברג, בנימין מבקשביץ","f":"שמחה נתן","bt":"תקסו","dt":"תרטז - כט אלול","dp":"לבוב","b":"חתן ר חיים יוסף תאומים. אב\"ד בקשביץ(=באקטשעויץ), ראב\"ד בלבוב-תרי על מקום אביו ובחיי אביו - נפטר צעיר. בנו ר חיים יוסף על מקומו אחריו."},{"i":3107,"n":"אילנברג, חיים יוסף מלבוב","f":"בנימין","bt":"תקצד","bp":"בקשביץ","dt":"תרלח - טז אב","b":"דיין בלמברג אצל ר יוסף שאול נתנזון בעל השו\"מ, סידר לדפוס את ספריו ונזכר בהם פעמים רבות. נפטר צעיר ביום חתונת בתו."},{"i":3108,"n":"אילנברג, חיים יוסף מקוסוב","f":"אברהם מטויסט","dt":"תש..","b":"נכדו של ר חיים יוסף מלבוב. רב בקוסוב-תרץ, זלוטשוב. נספה בשואה."},{"i":3109,"n":"אילנברג, יהודה ליב מבריסק","f":"עובדיה","k":"בעל מנחת יהודה","dt":"שעא - י טבת","b":"רב בבריסק. חתם על תקנה ביריד גרמניץ בלובלין שלא לקנות רבנות בכסף. הסכים על \"תקוני זבח\"."},{"i":3110,"n":"אילנברג, יוסף","dt":"תשא","b":"מו\"צ בזלאטשוב"},{"i":3111,"n":"אילנברג, יעקב מקראקא","f":"חיים","k":"בעל תולדות יעקב","b":"רב בקראקא-תס. הו\"ל \"שחיטות ובדיקות\" עם ביאור - אמשטרדם תפח."},{"i":3112,"n":"אילנברג, יצחק מטרעק ולודז","f":"אלעזר ספיר","k":"איצק טורקער","dt":"תריח","dp":"לודז","b":"נכד ר איצק גאלדעס מלאסק. מחכמי טורעק, לודז. אחיו של ר סיני ספיר בעל \"מנחת עני\" וחיבר הקדמה לספר אחיו. בניו - ר צבי הירש מאיר מפטשנוב, ר אברהם טורקער, ר ליבוש טורקער, ר ישעיה טורקער, ר שמעון טורקער. חתניו: ר יודל פרנקל מלודז, ר אפרים דמבינסקי מלודז, ר צבי הירש גולומב, ר אברהם משה אוירבך בן יצחק מלונטשיץ בעל \"דברי חיים\"."},{"i":3113,"n":"אילנברג, יצחק מקראקא וליסא","f":"אברהם משה ישראל","b":"דיין ודרשן בקראקא-שצ, רב בליסא, ניישטט-תל. חתם-שצח עם ר אליהו בן שמואל יוסף משה ליפשיץ מקראקא."},{"i":3114,"n":"אילנברג, ישכר בער מגוריציאה","f":"ישראל ליזר","k":"בעל באר שבע","b":"תלמיד הסמ\"ע, ר מרדכי יפה בעל הלבוש. רב בגוריציאה-שצ, התקבל לרב בצפת ונפטר בדרכו לארץ. חיבר גם \"צידה לדרך\"."},{"i":3115,"n":"אילנברג, צבי הירש מאיר מפטשנוב","f":"יצחק מטרעק ולודז","b":"רב בפטשנוב. נכד ר אלעזר ספיר מלאסק בעל \"אבן ספיר\" (אביו שינה שמו לאילנברג - שהיה מצאצאי הקדוש ר יוסף אילנברג)."},{"i":3116,"n":"אילנברג, שמחה נתן ממושציסק","f":"אריה ליב","k":"בעל דרוש לכבוד המלכו","bt":"תקמז","bp":"לוקטש","dt":"תריט - כב תשרי","dp":"לבוב","b":"תלמיד בעל הקצות, ר נפתלי הירץ מלבוב (אבי בעל \"מצבות קדש\"). אב\"ד מושציסק-תקפו ובנו ר צבי הירש על מקומו אחריו, לבוב-תרו, בנו ר בנימין על מקומו אחריו בלמברג. חיבר \"דרוש לכבוד המלכות\" - \"כבוד חופה\". תשובה אליו מבעל \"קהילות יעקב\" ב\"הפלס\" - ברלין תרסא-תרסה."},{"i":3117,"n":"אילרנץ, נפתלי הירש מהורודנקה","b":"מחכמי הורודנקה - תשובה אליו בטוט\"ד."},{"i":3118,"n":"אימיאנסון, נחום מרעזיצא","f":"הלל","b":"גביר תלמיד חכם ברעזיצא, בעל משרה בכירה בעסקי הגביר ר יוזיל גינצבורג, בקי בדתי המדינה ורבים השכימו לפתחו לדרוש בעצתו. חתנו - ר אברהם דב גבאי מוארקלאן."},{"i":3119,"n":"אינגבר, אברהם אבלי מזוויחווסט","f":"אביגדור","bp":"זוויחווסט","b":"חתן הגביר ר מיכל הירשפלד מניסקא. חתם על \"תוצאות חיים\" - תרנט. חתנו ר דוד הלברשם מסוקולוב."},{"i":3120,"n":"אינגבר, יצחק מאיר מרישא","k":"בעל הוספות למגלת יוח","bp":"רישא","b":"חתן ר יהושע השל ולרשטין מרישא. חיבר הוספות ל\"מגלת יוחסין\" שבראש \"כרם יהושע\". תשובה אליו ב\"שדה יהושע\"-תרנב."},{"i":3121,"n":"אינגברמן, פנחס","bt":"תרפ","dt":"תשטו","b":"רב בברוקלין-תשי\"א. פרסם מאמר ב\"אוהל יוסף\" נ\"י תשו."},{"i":3122,"n":"אינגלגיר, צבי הירש מסמבור","b":"דיין בסמבור בזמן השו\"מ עם ר יעקב מנחם מנדל ור אברהם משה שטרן."},{"i":3123,"n":"אינגלצין-רפפורט, זאב וולף","f":"חיים יצחק אהרן רפפור","bt":"תקצח","dt":"תרסג - יב כסלו","dp":"וילקומיר","b":"רב בוילקומיר. הניח חדושים בכת\"י. כמה מחדושיו בספר אביו - \"כתר תורה\"."},{"i":3124,"n":"אינגרליב, אליעזר מראדויל-אוסטי","f":"יוסף מראדויל","k":"אדמור מראדויל אוסטיל","dt":"תרנח - כה אב","b":"חתן ר חיים מרדכי מרגליות מדוביסאר-חתן ר מנחם נחום ממקרוב. רב בראדויל, אוסטילא-תרלט. בניו ר יוסף מויניצא, ר משה מגאייסין, ר שלמה מאקרמן-בוקרשט-תל אביב."},{"i":3125,"n":"אינגרליב, דן מקונסטנטין","f":"לוי מראדויל","k":"אדמור מקונסטנטין","b":"חתן ר ברוך מקונסטנטין."},{"i":3126,"n":"אינגרליב, דן מראדויל","f":"יצחק מראדויל","k":"אדמור מראדויל","dt":"תקצח - כה ניסן","b":"נגד המגיד מזלוטשוב. חתן ר אברהם יהושע השל מאפטא. אדמור מראדויל ובנו ר לוי על מקומו אחריו."},{"i":3127,"n":"אינגרליב, יוסף מראדויל","f":"אליעזר מטשען","k":"אדמור מראדויל","bt":"תקף","dt":"תרלה - יג אייר","dp":"גלינא","b":"גדל אצל זקנו ר ישראל מטשען. חתן ר פנחס מאוסטילה (נסכיז). אדמור בלנוביץ-תקצז (בגיל 17), ראדויל-תרז, וינוביץ-תרכח, נאסר ע\"י השלטון הרוסי בקרמניץ, עבר לגלינא. מתולדותיו בספרי חתנו ר יצחק מבנדר - \"כסא דוד\" ו\"עץ אפרים\"."},{"i":3128,"n":"אינגרליב, יצחק מהארחוב","f":"סנדר שמואל מוישנוביץ","k":"אדמור מהארחוב","b":"חתן ר מאיר מרובנא (סטעפין)."},{"i":3129,"n":"אינגרליב, מאיר נחום מוישנוביץ","f":"סנדר שמואל מוישנוביץ","dt":"תש..","b":"רב בוישנויביץ-תרמח על מקום אביו. נספה בשואה."},{"i":3130,"n":"אינגרליב, מרדכי מראדויל-ברוד","f":"לוי מראדויל","k":"אדמור מברוד","dt":"תרסה - ג טבת"},{"i":3131,"n":"אינגרליב, משה מקרמניץ","f":"סנדר שמואל מוישנוביץ","k":"אדמור מקרמניץ-ארה\"ב","b":"חתן דודו ר מרדכי משומסק. אדמור בקרמניץ, היגר לארה\"ב."},{"i":3132,"n":"אינגרליב, סנדר שמואל מוישנוביץ","f":"יוסף מראדויל","dt":"תרמח","b":"רב בוישנוביץ(=וישנובה?), בנו ר מאיר נחום על מקומו אחריו."},{"i":3133,"n":"אינדיך, ישראל איסר מסינסינטי","b":"חתן ר אברהם דוד שיוביץ מנאפראד-ברוקלין. רב בסינסינטי-אוהיו."},{"i":3134,"n":"אינדיקיס, אברהם מאזמיר","b":"גביר באזמיר, נספד מאת - ר נסים חיים שלום מרגונטו."},{"i":3135,"n":"אינדיקיס, שלמה מאזמיר","b":"גביר מחכמי איזמיר-שנות ה-ת'."},{"i":3136,"n":"אינדרויזר, אברהם הכהן","bt":"תרח","dt":"תרצה - יא כסלו","b":"רב ראשי באמשטרדם"},{"i":3137,"n":"אינהורן, אברהם חיים מצפת","f":"יחיאל צבי","k":"בעל ברכת הבית","bt":"תרה","bp":"טרניווה-מאמארוש","dt":"תרסח - ב סיון","dp":"צפת","b":"תלמיד מהרם א\"ש, ובנו - ר מנחם א\"ש, ר יקותיאל יהודה טיטלבוים בסיגט. חתן הגביר ר מרדכי צבי אינדיג ממאסיף, ועבר לשם-תרן, עבר לאויברווישווה. עלה לצפת. חיבר שערי טוהר, ברכת הבית, מקור הברכה, עצי העולה, מנוחה ושמחה. מוזכר בשות אבני נזר, השאיר הרבה כתבי יד. (אצל גליס תאריך הפטירה - תרצג).","bk":[["ברכת הבית","הלכה ומנהג - אחרונים"],["עצי העולה",""],["שערי טוהר",""]]},{"i":3138,"n":"אינהורן, אברהם מסוכובוליה וירו","f":"ישראל איסר הגדול","dt":"תרעב","dp":"ירושלים","b":"היה רב בסוחיואלע=סוכובוליה, עלה לירושלים."},{"i":3139,"n":"אינהורן, אברהם משטינמנגר","bt":"תרמב","dt":"תרצג - ב כסלו","b":"דיין בשוראני,שטיינמנגר(=סומבוט האלי)."},{"i":3140,"n":"אינהורן, אברהם צבי מטשען","f":"ישעיה מטשען","dt":"תרץ","dp":"קראקא","b":"חסיד בובוב. עבר לקראקא."},{"i":3141,"n":"אינהורן, אהרן מארה\"ב","b":"מלמד יהדות בשנחאי-תרף - בבתי הכנסת אהל משה ואהל שרה, כנראה לפני כן התגורר בחרבין-סין, היגר לארה\"ב-תרפח וכיהן כרב בקהלת תלמוד תורה בית אהרן בניו יורק."},{"i":3142,"n":"אינהורן, איסר יוסף","k":"בעל האדם","bt":"1866","bp":"קידאן","dt":"1925","b":"תלמיד ישיבת מייליס בוילנא. למד חקלאות בצרפת. עלה לארץ ולימד ב\"מקוה ישראל\". התישב בוארשא-1912. חיבר גם \"תורת עבודת האדמה\" לונדון תרע. תרגם ספרים לעברית."},{"i":3143,"n":"אינהורן, אפרים צבי מאמסטוב","f":"זאב וולף","k":"בעל שארית אפרים","bt":"תרטו","bp":"בריגל","dt":"תרס","dp":"קראקא","b":"חתן ר זליג ריטרמן מקראקא. תלמיד ר יהושע מקוטנא וה\"אבני נזר\", מקורב לר אברהם בעל \"חסד לאברהם\" ובהשתדלותו נתמנה לרב באמסטוב על מקום ר שלום וינגרטן, והקים שם ישיבה, בנו ר דב בר על מקומו אחריו. חיבר \"שארית אפרים\" בני ברק תשן."},{"i":3144,"n":"אינהורן, דב בריש מאמסטוב","f":"אפרים צבי","bt":"תרלז","b":"חתן בעל \"שפתי צדיק\" מפילץ. רב באמסטוב על מקום אביו."},{"i":3145,"n":"אינהורן, דוד גדליה","b":"פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!) - בהיותו בחור."},{"i":3146,"n":"אינהורן, זאב וולף מהורדנא","f":"ישראל איסר","k":"בעל ביאור מהרז\"ו","bt":"סוף המאה ה-18","bp":"גרודנה","dt":"תרכג - יג אד\"ב","dp":"וילנא","b":"מחכמי הורדנא, רב בוילנא-תקץ. חיבר גם \"נתיב חדש\".","bk":[["מהרז\"ו [על: מדרש רבה",""],["פרקי דר\"א]",""]]},{"i":3147,"n":"אינהורן, יהודה יוסף מפרשבורג","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":3148,"n":"אינהורן, יצחק מעיר חדש","bp":"עיר חדש","dt":"תרלה","b":"רב ריפורמי בבודפשט-תרח, השתתף במרד ההונגרי נגד השלטון האוסטרי. מזכיר הממשלה-תרכז."},{"i":3149,"n":"אינהורן, ישראל מפרשבורג","b":"מלמד בביה\"ס של הקהלה החרדית בפרשבורג - לפני השואה."},{"i":3150,"n":"אינהורן, צבי משטינמנגר","b":"ראש הישיבה בשטינמנגר(=סומבוט האלי)."},{"i":3151,"n":"אינהורן, ראובן מקראקא","f":"יעקב מקראקא","bt":"תרעו","bp":"קראקא","dt":"תש..","b":"תלמיד ישיבת בובוב בקראקא. ידיד נפש לר משה אהרן בן האדמור מבובוב. סופר ורושם תורות האדמור ר בן ציון מבובוב. חתן דודו ר שאול אינהורן. כתביו מתורת האדמור אבדו בשואה. נספה בשואה."},{"i":3152,"n":"אינזלבך, אליהו הלוי מארה\"ב","bt":"תרכו או תרל","bp":"נעשויז","dt":"תרצו - טו תמוז","b":"תלמיד ישיבת מיר, איישישוק, בריסק, וולוזין. ר\"מ באשמינא, היגר לארה\"ב וכיהן כרב בסקענעקטעדי, ניו יורק-תרסו, רב בשכונת אחוזה בחיפה-תרצא."},{"i":3153,"n":"אינילוב, היימן מארה\"ב","bt":"1847","bp":"קובנא","dt":"1934","b":"היגר לארה\"ב ולמד בהיברו יוניון קולג. רב ריפורמי בקהילות שונות-1898, ביהכ\"נ עמנואל בניו יורק-1912. סגן נשיא ועידת רבני אמריקה. ניהל את פעולות העזרה בצרפת בזמן מלחה\"ע ה-I. הו\"ל \"מנורת המאור\" לר ישראל בן יוסף אלמקאווה - נ\"י 1929."},{"i":3154,"n":"אינלגיר, מרדכי מקוזלוב","b":"נכדו של הרב מבלשביץ, כיהן כרב בקוזלוב. אולי הוא תלמיד ה\"כוכב מיעקב\" - הגביר מטרנופול."},{"i":3155,"n":"אינסברוק, אליעזר מנויביד","b":"מחכמי נויביד, מכתב ממנו-תקל אל ר נתן מאז בפפד\"מ."},{"i":3156,"n":"אינספרוק, יהודה מהמבורג","b":"רב בהמבורג. היה מהמערערים על הגט מקליווא-תקכו."},{"i":3157,"n":"אינריקס, יצחק","b":"רב בליוורנו-ת\"ק"},{"i":3158,"n":"אינריקס, יצחק מסאלי","b":"מחכמי סאלי, נזכר אצל היעב\"ץ."},{"i":3159,"n":"אינשטט, דוד","b":"מגדולי חכמי אשכנז באיינשטט-ר\"י"},{"i":3160,"n":"אינשטין, דניאל מגלוואן","dt":"תשג","b":"רבה האחרון של געלוואני(=גלוואן)."},{"i":3161,"n":"אינשטין, ישראל","b":"רב בניקולייב-תר\"ע"},{"i":3162,"n":"איסטאמאטי, אברהם מקוש-אדאסי","b":"דיין בקוש-אדאסי-תקנט, ישב בדין פטירת יצחק אלמדיאל עם ר חיים שמעון גדיליא ור אברהם חיים דוד סארדי."},{"i":3163,"n":"איסטרומשה, דניאל","b":"מגדולי חכמי ירושלים-תק\"כ"},{"i":3164,"n":"איסלימיא=סלימנא,סליבנה-קהלה","b":"קהלה בבולגריה."},{"i":3165,"n":"איספאניה, אברהם משלוניקי","dt":"שצה","b":"מחכמי שלוניקי, רב בטיריא-שעג, חזר לשלוניקי."},{"i":3166,"n":"איספאניה, יצחק מירושלים","bp":"שלוניקי","b":"רופא ומלמד תורה בקושטא, עלה לירושלים בשנת שפ יחד עם ר צמח הנרבוני. ולפי האוצר - עלה בשנת - תח. אחיו - ר אברהם."},{"i":3167,"n":"איספאניה, שם טוב משלוניקי","dt":"שצב - טו כסלו","dp":"שלוניקי","b":"מחכמי שלוניקי. (ב\"קורא הדורות\" נרשם בטעות - אברהם)."},{"i":3168,"n":"איספאניה, שמואל משלוניקי","dt":"שצב - לפני","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":3169,"n":"איספירנסה, גבריאל משלוניקי וצפ","bt":"שפ","bp":"שלוניקי","dt":"תלח-תמה","dp":"צפת","b":"תלמיד ר דניאל איסטרושה, עלה לצפת-תי והיה רב שם בזמן ר יונתן גלנטי ור בנימין הלוי הזקן, חתם-תכד על כתב שליחות, במכתב רבני קושטא-תכו נתבקש ר אברהם אמיגו לצאת לעזה עם ר גבריאל הנ\"ל לחקור אודות נתן העזתי, בשנת תכח חבר בית דינו של ר שמואל עדילה ואחריו ראש חכמי צפת, והאחים ר חייא ור יצחק שלום על מקומו אחריו (בזה אחר זה). השיב תשובות רבות, מקצת מהן בספר \"לב שלמה\" לר שלמה בן בנימין הלוי. מבין פירושיו נדפסו חלק על ידי ר חיים אבולעפיה בספרו \"עץ החיים\", חדושים ממנו ב\"חוט המשולש\" לר יהודה דיואן, ועוד. בשנת תלז פרץ ויכוח בינו לר מרדכי הלוי בעל \"דרכי נועם\" ור משה גלנטי השכין שלום ביניהם. החיד\"א כותב שנקרא כך על שם איספירנסה האשה שגידלה אותו לאחר שהתייתם משני הוריו."},{"i":3170,"n":"איסקוי (יצחק) ריש גלותא"},{"i":3171,"n":"איסקלסקי, יעקב מקאזאן ונ\"י","f":"דובער","k":"בעל תריג מצות","bt":"תרלו","bp":"מיר","dt":"תרצב - א אדר","b":"מצאצאי ר ליב מירעליש ממיר. תלמיד ר יוסף שליפר מסלונים, כולל קובנא. רב בלובליה(=ריבליא)-פלך מינסק-תרסג, קאזשאן-הורדוק - פלך מינסק, היגר לארה\"ב וכיהן כרב בסקרנטון-פנסילבניה-תרסז, קהלת \"אנשי סלוצק\" בניו יורק-תרעב. עורך \"המצפה\" - נ\"י תרע, יחד עם ר אברהם אהרן יודלביץ. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":3172,"n":"איסר יהודה מבריסק","f":"נחמיה","k":"בעל נחמת יהודה","dt":"תרלו","dp":"ירושלים","b":"היה רב ודיין בבריסק, עלה לירושלים בתרלב. חיבר \"נחמת יהודה\" וארשא תרכו. \"עזרת יהודה\" וארשא תרכב. חתנו - ר ישראל ברלין."},{"i":3173,"n":"איסר מוילנא","b":"מראשי הקהלה בוילנא שהתקרב לחסידות, והיה במחלוקת על כך. עלה לארץ בסוף ימיו."},{"i":3174,"n":"איסר מרוזוודוב","b":"תלמיד החוזה מלובלין."},{"i":3175,"n":"איסרוביץ, משה","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":3176,"n":"איסרל מוינה","f":"מרדכי","dt":"תפה - כז אב","b":"מחכמי וינה, פייטן."},{"i":3177,"n":"איסרלן, יונה מסלוצק","b":"חתן ר מנחם מניש ליפשיץ. בניו - ר שכנא איסרלן-חותנו של ר שמואל שימחוביץ. אחיו וחתנו - ר איסר איסרלין."},{"i":3178,"n":"איסרלן, ישראל - תרומת הדשן","f":"פתחיה","k":"מהרי\"א - תרומת הדשן","bt":"קנ","dt":"רכ","b":"נכד ר ישראל מקרימז בעל \"הגהות אשר\"י\". תלמיד ר עוזר משלזיה (מתלמידי המהר\"ם מרוטנבורג), ותלמידי דודו ר אהרן הקדוש. מגדולי הפוסקים ביהדות אשכנז, מרביץ תורה, מקובל, רב במרבורג(שטיירמרק)-קפו, וינער ניישטאט על מקום ר שלום."},{"i":3179,"n":"איסרלן, ישראל איסר מוילנא","f":"מרדכי מסלוצק","k":"בעל פתחי תשובה","r":"מסלוצק","bt":"תקפז","dt":"תרמט - טו תמוז","dp":"וילנא","b":"מצאצאי הרמ\"א. נכד-אבי אביו ר הרש אחיו של ר יונה סלוצקר, נכד-אבי אמו ר חיים ברודא מהורדנא. פוסק, רב בוילנא-תרכד בבימ\"ד בחצר הגביר ר כתריאל משה שיינוק. חיבר גם \"תוספות ירושלים\", \"שם ישראל\", ועוד.","bk":[["אשי ישראל",""],["הוראת איסור",""],["מור ואהלות – שו\"ת",""],["פתחי תשובה",""],["שם ישראל - על המשניות",""],["תוספות \\ תוספת ירושלים",""]]},{"i":3180,"n":"איסרלש, אברהם אבא מציעשינוב","bt":"תקסא","dt":"תרמא","b":"רב בציעשינוב, זבורוב-תריב."},{"i":3181,"n":"איסרלש, אברהם יעקב מטורקא","f":"רמ\"א מסקלי","bt":"תר","dt":"תרסו","b":"אב\"ד טורקא-תרסד. חתנו יהודה רוזנהק המשיך אחריו כרב. באוצר הרבנים רשום אביו - זכריה מנדל מגוליגור."},{"i":3182,"n":"איסרלש, אהרן מקראקא","f":"ישראל בן יוסף איסרלן","k":"אחי הרמ\"א","b":"מגדולי חכמי קראקא-ש\"ל"},{"i":3183,"n":"איסרלש, אליעזר","f":"ישראל איסרלן","dt":"שפג - א-יא אב","dp":"וינה","b":"אחיו של הרמ\"א. חתן המהרש\"ל. מבניו: ר משה מבריסק(=ר משה ר ליזרש)-חותנו של ר השל מלובלין וקראקא. מחתניו: ר יעקב בן אשר אהרן מפרידבורג גינצבורג"},{"i":3184,"n":"איסרלש, זכריה מנדל","b":"בשנת תר תשובה אליו בספר \"בחסד לאברהם\"."},{"i":3185,"n":"איסרלש, יוסף מבריסק","f":"ישראל בן יוסף איסרלן","k":"אחי הרמ\"א","b":"נזכר בשו\"ת אחיו - הרמ\"א, וב\"דרישה\"."},{"i":3186,"n":"איסרלש, יחזקאל ממוהילוב","b":"רב במוהילוב-תר. חיבר שו\"ת וחדושים על הש\"ס - בכת\"י - והיה אצל נינו ר חיים וילדה מזלאבין."},{"i":3187,"n":"איסרלש, יצחק מקראקא","f":"ישראל איסרלס","dt":"שמא - א תשרי","dp":"קראקא","b":"מחכמי קראקא, אחי הרמ\"א."},{"i":3188,"n":"איסרלש, ישראל איסר מזבורוב","f":"אברהם אבא מזבורוב","b":"ראש חסידי סטרטין בזבורוב-תרסג, תשובה אליו ב\"לבושי מכלול\"."},{"i":3189,"n":"איסרלש, ישראל איסרל מקראקא","f":"יוסף","k":"איסרל לאזרש מקראקא","dt":"שיד - יג-ט אד\"א","dp":"קראקא","b":"גביר, פרנס בקראקא. בניו - הרמ\"א, ר אליעזר-חתן המהרש\"ל. ר יצחק, בתו - מרים בילה."},{"i":3190,"n":"איסרלש, משה - הרמ\"א","f":"ישראל בן יוסף איסרלן","k":"בעל דרכי משה","bt":"רפ","dt":"שלב - יח אייר","b":"גדול הפוסקים בדורות האחרונים, תורה וגדולה במקום אחד הוראתו נתפשטה ונתקבלה בכל ישראל. חתניו - ר וולף-חותנו של בעל הש\"ך, ר בונם ר אברהם רייזלש, ר אליעזר גינצבורג. בנו - ר יהודה. גיסיו - ר משלם, ר פנחס, ר ליב, ר אליהו. מחותן עם ר שמעון גינצבורג. אחיו - ר יוסף מבריסק, ר יצחק, ר אליעזר-חתן המהרש\"ל."},{"i":3191,"n":"איסרלש, שמעון (שמשון)","dt":"תקעא - ה אב","b":"רב בסלוצק"},{"i":3192,"n":"איסרס, דוד מוילנא","f":"משה","dt":"תרח - כז חשון","b":"דיין בוילנא. מצאצאי הרמ\"א ומכאן השם איסר'ס."},{"i":3193,"n":"איסרס, הרץ","dt":"תקמז - ט טבת","b":"רב בראווא"},{"i":3194,"n":"איסרסון, אהרן שישקעס מוילנא","f":"ישראל איסר מסלוצק","k":"ר ארעלע שישקעס","dt":"תרכו - כו כסלו","dp":"וילנא","b":"מצאצאי הרמ\"א. חתן ר מאיר שישקעס אשכנזי לובלינר. גביר מחכמי וילנא. בנו ר אברהם אסירסון. חתניו: ר בצלאל איסר רבינוביץ, ר יצחק גינצבורג-אחיו של ר מאיר."},{"i":3195,"n":"איעיש, יצחק מפאס","b":"רב בפאס, מתורתו ב\"מראה עינים\" לר אלעזר בהלול."},{"i":3196,"n":"איעסטי, אשר אנשיל","b":"רב-שנת תק\"ל"},{"i":3197,"n":"איפרגאן, מרדכי ממרוקו","dp":"תיזנית-מרוקו","b":"מחכמי תיזנית - חבל סוס במרוקו."},{"i":3198,"n":"איפרגאן, שלום ממרוקו","bt":"תרע","bp":"מרוקו","dt":"תשנד - ח תמוז","dp":"נתיבות","b":"מצדיקי תיזנית-מרוקו, התבודד במשך כשבע שנים ובהם עסק בתורה ובקבלה. עלה לארץ והתישב בנתיבות."},{"i":3199,"n":"איפרגן, אברהם","f":"דוד","b":"מחכמי אסאקה(מרוקו)"},{"i":3200,"n":"איצחקוביץ, יעקב","b":"רב בדרבנד-קווקז-תר\"נ"},{"i":3201,"n":"איצינגר, חיים שמואל מבייטש","bt":"תריג","bp":"דמביץ","dt":"תשב","b":"מחכמי בייטש וממלא מקום הרב. נספה בשואה."},{"i":3202,"n":"איצינגר, מנחם מנדל מפריסטיק","b":"אב\"ד פריסטיק-תרסב, תשובה אליו בשות מהר\"ש להר\"ש ענגיל."},{"i":3203,"n":"איצל, שלמה","b":"מרבני פלונגיאן"},{"i":3204,"n":"איצמונש, אביגדור סופר","b":"סופר הקהילה באייזנשטט-ש\"ל"},{"i":3205,"n":"איצק","f":"אברהם אייכל","k":"בעל תולדות הרמבמ\"ן","bt":"תקטז","dt":"תרסד","b":"מתלמידי מנדלסון. תרגם את ספר משלי ללשון אשכנז, ואת סדר התפילות. הו\"ל פרקי ר אליהו בחור, יסד חברה \"געזעלשאפט דער פרייגדע\"."},{"i":3206,"n":"איצק מרנדסבורג","f":"ליב","b":"ש\"ץ ברנזיבורג(=רנדסבורג)-ליד אלטונא על מקום ר זאב פאהן ור מאיר בן אורי פיבש על מקומו אחריו."},{"i":3207,"n":"איצקוביץ, אברהם יעקב הלוי מב\"ב","b":"חתן ר שמואל הלוי וזנר מבני ברק. רב שכונת רמת דוד בבני ברק."},{"i":3208,"n":"איצקוביץ, יהודה בנימין","f":"יצחק","bt":"תקפב","dt":"תרמא","dp":"ירושלים","b":"היה ראש ישיבה בסלונים, חיבר ספר \"פני יהודה\" וילנא תרל, \"לקט יהודה\" וילנא תרלב ועוד. עלה בזקנותו הגיע לטבריה ואחר כך לירושלים."},{"i":3209,"n":"איצקוביץ, יוסף","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":3210,"n":"איראי, אברהם מאלגיר","f":"יצחק","bt":"ד'תשן","dt":"ד'תת","b":"מחכמי תהרס-אלגיר-ד'תשן-תת. שאלה ממנו לרב האי גאון בתשובות הגאונים."},{"i":3211,"n":"אירגנג, דב בר הלוי מפשמישל","bt":"תרלח","b":"מחכמי פרמישלא, וינה. תרגם את ספר \"השר מקוצי\" לליהמן - פשמישל תרס. פרסם מאמרים ב\"הבונה\" - לבוב תרסד."},{"i":3212,"n":"אירגס, אברהם","f":"יוסף","b":"ליוורנו-תק\"ב"},{"i":3213,"n":"אירגס, אליה","b":"מחכמי קושטא-תקע\"א"},{"i":3214,"n":"אירגס, יהושע","b":"מחכמי צפת וראשון השליחים בקושטא בשנת שץ."},{"i":3215,"n":"אירגס, יוסף מאיטליה","f":"עמנואל אירגס","k":"בעל דברי יוסף","bt":"תמה","dt":"תץ - כ סיון","b":"מקובל, רב בפיסה, ליוורנו. חיבר גם \"שומר אמונים\", ועוד. גיסו - משה פיגיירו השבתאי.","bk":[["שומר אמונים",""]]},{"i":3216,"n":"אירגס, יוסף מטבריה","dp":"טבריה","b":"מחכמי טבריה, בשנת תקלט בשליחות הקהלה."},{"i":3217,"n":"אירגס, יצחק מטבריה","f":"רפאל משה","k":"בעל ויעתר יצחק","dt":"תקצה - אחרי","dp":"טבריה","b":"מחכמי טבריה, בשליחות בצפון אפריקה-תקפב, בטיטואן כתב תשובה בהלכה שנדפסה ב\"משפטים צדיקים\". הגיע לליוורנו והדפיס את ספר זקנו ר עמנואל אירגס - \"מנחת יוסף\" ובתוכו את ספרו \"ויעתר יצחק\" - תקפז."},{"i":3218,"n":"אירגס, עמנואל","b":"רב בליוורנו-תנ. חתן ר משה פניירו. מוזכר בהקדמה לספר בנו - \"דברי יוסף\". תשובה אליו ב\"דבר שמואל\"."},{"i":3219,"n":"אירגס, רפאל מלייורנו","f":"אהרן","k":"בעל ספר הזכרונות","b":"רב בליוורנו. מצאצאי ר יוסף אירגאס בעל \"דברי יוסף\". חיבר ספר הזכרונות - ניו יורק תשמה."},{"i":3220,"n":"אירואינו אברהם","b":"ישב בבית דינו של ר יוסף קארו בשנים שיח שכג שלא. מופיע בשו\"ת המבי\"ט ח\"א סימן רפז"},{"i":3221,"n":"אירום, ישראל מטרנוב","f":"מאיר","bt":"תר","dt":"תרפה","b":"רב בטרנוב, דיין בקלוריה-תרכט."},{"i":3222,"n":"איריסה, אברהם מרודוס","b":"גביר ברודוס-תקן בערך, תמך ברבני ובהדפסת ספריהם."},{"i":3223,"n":"איריסה, דוד מקנדיא","b":"דיין בקנדיא-תל בזמן ר משה אלקונסטנטיני."},{"i":3224,"n":"איריסה, יצחק מרודוס","b":"רב ברודוס לצד ר משה הכהן, היה מחלוקת ביניהם ור משה עבר לאי כיאו-בשנת שעה."},{"i":3225,"n":"איריסה, נסים יחזקאל","b":"מגיה הספר קורות היהודים בתורכיה לרוזניס."},{"i":3226,"n":"איריץ, אהרן דוד מפרשבורג","f":"שמואל","bt":"תקלז","dt":"תרד - ד תשרי","dp":"פרשבורג","b":"מראשי קהלת פרשבורג. חתם על כתב מנוי רבנות לחת\"ס-תקסז. חתם על תקנות ביה\"ס למלאכה שע\"י הקהלה-תקפא."},{"i":3227,"n":"אירלנדר, מרדכי","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":3228,"n":"אירס, אברהם שמחה מארה\"ב","f":"ישראל דוד","bt":"תרסד","bp":"רישא","b":"היגר לארה\"ב, תלמיד ישיבת רבי חיים ברלין בברונזויל, ישיבת רבי יצחק אלחנן ונסמך מאת ר שלמה פוליטשוק. רב בניו יורק."},{"i":3229,"n":"איררה, משה משלוניקי","b":"מחכמי שלוניקי, עלה לארץ. חיבר חדושים ותשובות בהלכה בכת\"י."},{"i":3230,"n":"איש אמת יוסף","f":"משה מזעווירש","b":"איש אמת,רב-שנת ת\"ס"},{"i":3231,"n":"איש ירושלים, יוסף","b":"מגדולי בעלי התוספות,עלה לא\"י-ד'תתקע\"א,מרביץ תורה בירושלים"},{"i":3232,"n":"איש מבית לוי, יצחק","b":"דיין בלבוב-תנ\"ד"},{"i":3233,"n":"איש שלום מיכאל בן יהודה","dt":"ה'תרסה 1905","bk":[["מקומות קדושים",""]]},{"i":3234,"n":"אישטרושה - משפחה","b":"משפחה מיוחסת משלוניקי. בני המשפחה החזיקו בחזקת השחיטה, במשך מאות שנים היו השוחטים בשלוניקי מבני 3 משפחות: ברכה - החל משנות ה-ש', מולכו, אישטרושה(=איסטרומסה) ורק להם היתה הזכות לכך."},{"i":3235,"n":"אישטרושה, אברהם יצחק משלוניקי","dt":"תקכז","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"מגן גבורים\"-תקיד."},{"i":3236,"n":"אישטרושה, גבריאל מצפת","b":"מחכמי צפת בזמן ר יונתן גלנטי-שנות ה-ש'."},{"i":3237,"n":"אישטרושה, דוד משלוניקי","f":"דניאל","dt":"תכב - ד אב","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":3238,"n":"אישטרושה, דוד משלוניקי","f":"אברהם","b":"מחכמי שלוניקי-שנות ה-תק'. חיבר שו\"ת ודרשות ונדפסו בספרי בנו ר אברהם - \"בן אברהם\", \"ירך אברהם\". (אצל גאון - ביהודי המזרח שמו - דניאל)."},{"i":3239,"n":"אישטרושה, דניאל מסופיה","f":"דוד","b":"רב בסופיה-שנות ה-ת'."},{"i":3240,"n":"אישטרושה, דניאל משלוניקי","f":"יצחק בן דוד","dt":"תקך","dp":"שלוניקי","b":"מחכמי שלוניקי. הגיה \"מגן גבורים\" לזקנו."},{"i":3241,"n":"אישטרושה, דניאל משלוניקי - א","k":"בעל מגן גבורים","bt":"שמב","bp":"שלוניקי","dt":"תיד - כה תשרי","dp":"שלוניקי","b":"תלמיד ר מרדכי קלעי, פוסק, מקובל, רב בשלוניקי וראש ישיבת קהילת הפורטוגאלים בשלוניקי, ורב הכולל על מקום רבו ר מרדכי קלעי. נספה במגיפה. מתלמידיו: ר דוד קונפורטי בעל \"קורא הדורות\", ר גרשון מוטאל מאזמיר, ר גבריאל איספיראנסה מצפת, ר יעקב דניאל ועוד. בניו - ר דוד, ר יוסף, ר יצחק. מתורתו גם ב\"ירך אברהם\" לר אברהם אישטרושה. בזמן גזירות תח-תט בפולין התארגנה גם קהלת שלוניקי בראשותו לפדות את השבויים הרבים שהגיעו לשם."},{"i":3242,"n":"אישטרושה, דניאל משלוניקי - ב","f":"משה","dt":"תקה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3243,"n":"אישטרושה, ויטאליס משלוניקי","bt":"1865","bp":"שלוניקי","b":"מזכיר הועדה המקדונית אצל חלמי פאשה, שר היערות והמכרות בתורכיה בממשלה החדשה (התורכים הצעירים)."},{"i":3244,"n":"אישטרושה, חיים אברהם משלוניקי","f":"דוד או דניאל","k":"בעל ירך אברהם","bt":"תקך - בערך","bp":"שלוניקי","dt":"תקפט","b":"נכד ר דניאל אישטרושה ונכד(-אבי אמו) הגביר ר אברהם אישטרושה. תלמיד ר משה הירירה, ור מיכאל הלוי בשלוניקי. חתן ר משה אלשיך משלוניקי. מחכמי שלוניקי, פוסק, רב בקומורג'ינה(=קומירג'ינה)-תקנג על מקום ר יעקב אלבוחר (שהיה גיסו - נשואים לשתי אחיות), מטיף בקהלת קאשטיליא ישן בשלוניקי, שירון-תקסד, לאריסה, קאשטוריאה, שלוניקי (בשנית), ירושלים?. חיבר גם \"בן אברהם\". (באוצר הרבנים מופיע - רב בירושלים-תקסו). גיסו - ר יוסף מירקאדו אלשיך."},{"i":3245,"n":"אישטרושה, יוסף משלוניקי","dt":"תנג","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3246,"n":"אישטרושה, יעקב מירושלים","b":"מחכמי ירושלים, הסכים-תרג על \"דברי שלום\"."},{"i":3247,"n":"אישטרושה, יצחק משלוניקי","b":"מחכמי שלוניקי. חתם על הסכמת ר יוסף קובו-תפה - בענין פטור תלמידי חכמים ממס."},{"i":3248,"n":"אישטרושה, יצחק משלוניקי","dt":"תצה","dp":"שלוניקי","b":"נכד ר דניאל אישטרושה. מחכמי שלוניקי, חתם על ההסכמה-תפה."},{"i":3249,"n":"אישטרושה, משה משלוניקי","dt":"שט - יד אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3250,"n":"אישישקי, צבי אידל","f":"שבתי איישישקי","bt":"תרכא","b":"רב ביאשון,מו\"צ בפאריס"},{"i":3251,"n":"אישישקי, שבתי","b":"רב בווראנוב(=וארנוב)-תר\"ל"},{"i":3252,"n":"אישישקין, יחזקאל מיאשון וארה\"ב","k":"בעל דברי יחזקאל","bt":"תרכג-ד","bp":"אישישוק","dt":"תרצה - ה אלול","b":"תלמיד ישיבות וולוזין, קובנה. רב ביאשון-פלך וילנא, היגר לארה\"ב וכיהן כרב בביהמ\"ד \"נחל יצחק\" בניו יורק, דטרויט-תרסה. מחידושיו ב\"המאסף\" בירושלים. פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו."},{"i":3253,"n":"אישפיאירה, נחמיה משלוניקי","dt":"תפז - ו חשון","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":3254,"n":"אישפינוזה, בנימין מתונס","f":"יעקב","k":"בעל בית העזר","dt":"תקלו","dp":"ליוורנו","b":"מרבני תונס, חכם בתורה, דקדוק ושירה, דיין בליוורנו, תשובה ממנו בענין \"וי\"ו קטיעא דלשום\" - שהיה מחלוקת בין רבני ונציה ורוויגו. חיבר \"בית העזר\" ושו\"ת, ב\"יוסף אומץ\" מזכיר את ספרו \"יסוד הקיים\" שחולק על ספר \"ישרש יעקב\"."},{"i":3255,"n":"אישפריאל, אברהם מירושלים","b":"מחכמי ירושלים, מהסובלים בפרעות אבן פארוך-שפה. אחיו של ר יהודה."},{"i":3256,"n":"אישפריאל, חנניה מצפת","b":"מחכמי צפת-בזמן ר חיים אבולעפיה המוסמך, בשנת תכא בחברון וחתם שם על כתב שליחות ר חייא דיין לצפון אפריקה. הניח חבורים על הש\"ס בכת\"י (חלקם בספריה הלאומית). אחיו - ר רפאל."},{"i":3257,"n":"אישפריאל, יהודה מקושטא וירוש","bp":"קושטא","b":"מגדולי חכמי קושטא,עלה לירושלים-שפ. נאסר עם השל\"ה ע\"י אבן פארוך-שפה, דיין-שצה. אחיו של ר אברהם."},{"i":3258,"n":"אישפריאל, מתתיהו מירושלים","f":"רפאל","b":"רב בירושלים, דיין אצל ר רפאל שלמה הבדלה."},{"i":3259,"n":"אישפריאל, נחמיה הרופא משלוניקי","b":"רופא בשלוניקי-שנות ה-ת'-תק'."},{"i":3260,"n":"אישפריאל, רפאל מקושטא","b":"תלמיד מהרימ\"ט. מחכמי קושטא, עלה לירושלים-תי. מתשובותיו בספר אחיו ר חנניה מחברון, ותשובה ממנו גם ב\"פני משה\" (לר משה בנבנשתי)."},{"i":3261,"n":"אישקאלוני, אהרן משלוניקי","dt":"תקמז","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":3262,"n":"אישקאלוני, יצחק משלוניקי","dt":"תצו","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3263,"n":"אישקאפה, דניאל משלוניקי","b":"דיין בשלוניקי-שמח."},{"i":3264,"n":"אישקאפה, יוסף","k":"בעל עבודת משא","dt":"תרט - ד טבת","b":"מחכמי תורכיה, חיבר \"עבודת משא\" - שלוניקי תרו. נספד מאת ר חיים פלאגי."},{"i":3265,"n":"אישקאפה, יוסף מאזמיר","f":"שאול","k":"בעל ראש יוסף","bt":"שכט-של","bp":"שלוניקי","dt":"תכב - כו טבת","b":"תלמיד ר אהרן ששון משלוניקי. ר\"מ בשלוניקי, רב הכולל באזמיר-שפ - שרוב בני הקהלה הגיעו אז משלוניקי. בסוף ימיו סגי נהור. ממתנגדי שבתי צבי וגרם לגירושו מאזמיר. תיקן תקנות רבות באזמיר ובהם - מינוי 12 ממונים ומפקחים בכל עניני העיר. חלק מההסכמות בוטלו בידי ר יצחק הכהן-תקט"},{"i":3266,"n":"אישקיר, אברהם הכהן מירושלים","bt":"תפ","dt":"תקמב","b":"מחכמי ירושלים בימי ר שלום שרעבי"},{"i":3267,"n":"אישקלוני, יצחק משלוניקי","b":"דיין בשלוניקי אצל ר יצחק ן שאנגי שהביא מתורתו בספרו \"באר לחי רואי\"."},{"i":3268,"n":"איתאח, יצחק ממרוקו","b":"רב בצפרו-מרוקו, חתם-תר בערך עם ר עמור אביטבול."},{"i":3269,"n":"איתיאל","b":"ממשפחת ר משה הזקן, ונסע לשמש את גאוני קירואן או בבל - הביא עמו ספר ובו תשובה מרב שרירא לחכמי קירואן. חיבר פיוטים."},{"i":3270,"n":"איתיאל ממגנצא","b":"מצאצאי ר משלם בן קלונימוס מלוקא. בנו - ר משה ונכדו ר משלם הגדול, ואחר פטירתו רצה נכדו לנהוג אבלות על זקנו - אולם ר אליעזר הגדול הראשון לא הניח לו, ונזכר ב\"אור זרוע\", ומרדכי. אחיהם של ר קלונימוס, ור יקותיאל משפירא."},{"i":3271,"n":"איתמר","k":"איתמר הכהן הגדול","b":"פועל ישועות-תק\"ס"},{"i":3272,"n":"איתמר הכהן","dt":"כו אדר","b":"רב בצ'יזקוב"},{"i":3273,"n":"איתמר הכהן הנסתר מטשזיקוב","b":"תלמיד ר לוי יצחק מברדיטשוב, וידידו של ר ליב שרה'ס. ר אורי השרף מסטרליסק אמר שאם יבנה ביהמ\"ק בימיו הוא יהיה כהן גדול."},{"i":3274,"n":"אכטל, צבי מסמבור","b":"סופר בסמבור. תשובה אליו ב\"שושנים לדוד\"."},{"i":3275,"n":"אכסול, אברהם","dt":"תרו","b":"מקובל, מראקש"},{"i":3276,"n":"אכסילר, בינידינו אשכנזי מבולו'","b":"רב בבולוניה - לפני הגירוש. תשובות ממנו נדפסו בונציה-רעח. בזמן ר חייא בר דוד והיה במחלוקת עם ר דוד פיציגוטון."},{"i":3277,"n":"אל אג'מי, שלום","b":"מקובל,מרבני מכנאס-תק\"ט"},{"i":3278,"n":"אל בחרי, עמנואל","b":"מחכמי ירושלים בשנת שפה בזמן פרעות אבן פארוך"},{"i":3279,"n":"אל הבריזי","b":"מחכמי ספרד, פילוסוף"},{"i":3280,"n":"אל נבוב, שמואל מקושטא","b":"רב בקושטא בזמן הרא\"ם."},{"i":3281,"n":"אל קארה, סלימן מתימן","b":"רב ראשי בתימן בזמן השתלטות התורכים על הארץ, ושלחו היהודים שליח לקושטא שישלח להם חכם באשי לייצגם בפני השלטון והגיע אליהם ר יצחק שאול שמילא את שליחותו בהצלחה, וראה עצמו כפוף לרב סלימן."},{"i":3282,"n":"אל רייס, מנצור ממצרים","b":"מחכמי מצרים-רפ בזמן הרדב\"ז."},{"i":3283,"n":"אלאג'ים, אוריאל","k":"עאג'ים","b":"מחכמי צפת-תמ\"א"},{"i":3284,"n":"אלאדאד, קומלוש מבודפשט","k":"בעל היהודים על פרשת","b":"מלמד בביהמ\"ד לרבנים בבודפשט. משורר, סופר ומבקר. חיבר \"היהודים על פרשת דרכים\" - על בעית ההתבוללות והתחיה הלאומית בהונגריה."},{"i":3285,"n":"אלאזרקי","k":"בעל שלום ירושלים ראה: אלזרקי","b":"מחכמי קושטא,עלה לירושלים-ת\"ר"},{"i":3286,"n":"אלאטיני, אוגו משלוניקי","b":"גביר מראשי קהלת שלוניקי-תרלח."},{"i":3287,"n":"אלאטיני, אליעזר משלוניקי","f":"משה","bt":"תקלו","bp":"איטליה","dt":"תקצד - כא אב","dp":"שלוניקי","b":"למד רפואה באיטליה, עבר לשלוניקי והיה רופא מפורסם. חתן ר דוד מורפורגו. אבי משפחת אלאטיני בשלוניקי. תרם הרבה לפדיון שבויים. בניו: משה, מנחם, דוד (דאריו), שלמה."},{"i":3288,"n":"אלאטיני, וידאל יחיאל רחביה","b":"רופא מחכמי איטליה - שנות ה-ר', היה גם רופא האפיפיור יוליוס השלישי. חיבר ספרים ברפואה. אחיו של ר משה, ודודו של ר דוד די פאמיס."},{"i":3289,"n":"אלאטיני, חיים מספוליטו","b":"רב ורופא בספוליטו(=ספאלטא). נכדו ר דוד פומיס בעל \"צמח דוד\" סיפר על זקנו שהיה גדול שמו בין הרופאים ושחיבר ספרים ברפואה."},{"i":3290,"n":"אלאטיני, יצחק משלוניקי","b":"ראש קהלת ליסבון בשלוניקי-רע."},{"i":3291,"n":"אלאטיני, משה משלוניקי - הנכד","f":"אליעזר משלוניקי","k":"רוטשילד של תורכיה","bt":"תקסט","bp":"שלוניקי","dt":"תרמג - ז תשרי","dp":"שלוניקי","b":"למד רפואה בליוורנו, והיה רופא בטוסקנה, חזר לשלוניקי והשתתף עם אחיו בעסקים-שירשו מאביהם, וגם היה רופא שטיפל בעניים. כונה בשם \"רוטשילד של תורכיה\" - והיה פעיל צבור וניצל את קשריו עם השלטון לטובת היהודים, ותרם רבות לצדקה. כמו כן פעל להקמת בתי ספר מודרנים בשלוניקי. בניו: לאזארו, קרלו, ראובן, הוגו, אידוארדו, רוברטו, ודאריו."},{"i":3292,"n":"אלאטיני, משה משלוניקי ואיטליה","b":"ראשון למשפחה ידועה בשלוניקי. רופא ורב בשלוניקי, לאריסה?, מונסטיר בשנות ה-תק', עבר לאיטליה והיה רב ורופא בספליטו. ובנו הרופא אליעזר בכר משה לאטין. נזכר בהקדמת \"צמח דוד\" ע\"י ר עמנואל אבואב ור דוד פומיס, ואצל ר חיים חנוך פיפאנו."},{"i":3293,"n":"אלאטיני, עזריאל פתחיה מפיררה","k":"בעל תורת המוקצה","b":"רב בפיררה, ונבחר-שמא, בין השנים עשר שנשלחו להשתדל אצל החשמן שלא לכלוא את היהודים בגיטו. ממשפחת הרופא ר יחיאל רחביה אלאטינו, ואחיו - ר משה אלאטינו - ונזכרו ב\"צמח דוד\". חיבר \"תורת המוקצה\" בכת\"י. תשובה ממנו שחלק עם ר נתנאל טרבוט בענין החזרת נדוניה."},{"i":3294,"n":"אלאטיני, שלמה מקאבאלה","b":"רב הקהלה הספרדית בקאבאלה-שנות ה-ש'."},{"i":3295,"n":"אלאטיני, שמואל משלוניקי","dt":"רצא - כא אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3296,"n":"אלאטיף, ישראל מקושטא","b":"רב בקושטא - ממונה על איסור והיתר-תקמו. מתשובותיו בספרי חכמי דורו."},{"i":3297,"n":"אלאטרינו, אליהו מאיטליה","f":"יוסף בן יחיאל","b":"מחכמי מצרתא-איטליה-קן. חיבר ספר החינוך-קלב בכת\"י. ואולי הוא המובא ב\"שפתי ישנים\" שחיבר \"קול תרועה\"."},{"i":3298,"n":"אלאטרינו, יצחק","f":"אברהם","k":"בעל כנף רננים","b":"חיבר \"כנף רננים\" עם הסכמת הרמ\"ז (אצל ר חיים מיכל - אוצרות חיים)."},{"i":3299,"n":"אלאלוף, בכור משלוניקי","dt":"תצד","dp":"שלוניקי","b":"נהרג עק\"ה בשלוניקי-תצד."},{"i":3300,"n":"אלאלוף, ברוך משלוניקי","b":"מורה בביה\"ס ת\"ת בשלוניקי-לפני השואה."},{"i":3301,"n":"אלאלוף, יעקב משלוניקי","dt":"תקל - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי-תקל. חתנו - יעקב בכר צמח אלאלוף (והתחייב לתת לו לנדוניה ש\"ס בבלי)."},{"i":3302,"n":"אלאמאן, מנחם מצפת","b":"רב בצפת-סוף שנות ה-ש'. אחיו - ר שלמה."},{"i":3303,"n":"אלאמאן, שלמה מצפת","dp":"חברון","b":"רב בצפת-סוף שנות ה-ש'. אחיו - ר מנחם."},{"i":3304,"n":"אלאמאני, יוסף אשכנזי מבודה","f":"שלמה","k":"בעל שער הפנים","b":"ראש הקהלה בבודה-רפ בזמן הכיבוש התורכי, עמד בראש משפחה שקבלה כתב שחרור ממסים על שסייע לשולטן בכיבוש בודה. בניו - שלתי, ישראל."},{"i":3305,"n":"אלאניש, אליהו מאיטליה","b":"רב בסאלובנו-איטליה-רן. נזכר בשה\"ק, וסה\"ד."},{"i":3306,"n":"אלאשוילי, מיכאל מסוגונא-גרוזיה","f":"מנוח מסוג'ונה","k":"בעל זבח ומנחה","bt":"תריז-כא","b":"תלמיד ר משה גאנאשוילי בקילאש-פלך כותאוס. מחכמי סוג'ונה-גרוזיה-תרמ, יחד עם ר אברהם מיכלאשוילי ור רפאל אפרמאשוילי. רב בסוג'ונה על מקום ר רפאל אפרמאשוילי - שעלה לירושלים, הקים ת\"ת לנערים בעירו, רב בפותי-תרץ. היה במחלוקת עם הרב חנקין בעיניני גיטין. בשנת תרצח נעצר ע\"י הרוסים, והשמידו את רוב כתביו. חיבר גם \"בן מנוח\", \"שדי מגרש\", \"אלון בכות\" - בכת\"י."},{"i":3307,"n":"אלאשוילי, מנוח מסוגונא","b":"משנה רב בסובונה(=סוג'ונא)-גרוזיה - תר-תרם ובנו ר מיכאל מסוג'ונא."},{"i":3308,"n":"אלאשוילי, רפאל","bt":"תרצד","bp":"קולאשי-גרוזיה","dt":"תשסה - כג סיון","b":"גדל אצל זקנו ר אהרן בותרשוילי בקולאשי, חזן בבית הכנסת הגדול שם. עלה לארץ-תשלב והתישב בלוד, רב ראשי ליהודי גרוזיה בארץ-תשמח."},{"i":3309,"n":"אלבא די, דוד משלוניקי","dt":"תסב - כב סיון","dp":"שלוניקי","b":"רופא מחכמי שלוניקי."},{"i":3310,"n":"אלבא די, יעקב מפירנצי","k":"בעל תולדות יעקב","b":"רב בפירנצי. חיבר \"תולדות יעקב\" ונציה שסט."},{"i":3311,"n":"אלבא די, יצחק מאזמיר","bt":"שס","bp":"שלוניקי","dt":"תמא - י אדר","dp":"אזמיר","b":"תלמיד ישיבת ר דניאל אשטרושה, מחכמי שלוניקי, עבר לאזמיר וכיהן כדיין זמני-תכד בעניני ממונות עד למינויו הקבוע של ר אהרן לפפא כדיין קבוע-תכה, ולאחר שעזב-תכח נתמנה שנית על מקומו אחריו. תשובה ממנו לונציה בענין האיסור להשתמש בעורך דין בבית הדין. מתלמידיו - שבתי צבי. מתומכי שבתי צבי באזמיר. (יש רושמים תאריך פטירתו - תלה-ו)."},{"i":3312,"n":"אלבא די, יצחק מאזמיר","dt":"תעד - ד תמוז","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3313,"n":"אלבא די, ישראל יעקב מירושלים","dt":"תקנט - ד חשון","dp":"ירושלים","b":"מחכמי ירושלים. נפטר צעיר."},{"i":3314,"n":"אלבא די, רפאל משה מירושלים","dt":"תקע - א חשון","dp":"ירושלים","b":"מחכמי ירושלים. בנו - ר חיים יעקב."},{"i":3315,"n":"אלבאז, אבא מצפרו","f":"עמרם","k":"בעל זובחי הזבח","r":"ראב\"ד ור\"מ בעיר צפרו שבמרוקו","bt":"תריא-יד תשרי","bp":"צפרו (מרוקו)","dt":"תרצח - כו אלול","b":"דיין בצפרו, בעל ספריה חשובה, נזכר ב\"מלכי רבנן\". הניח כתבים בכת\"י ובהם \"זובחי הזבח\"-ירושלים תשם, \"דין אבא\", ועוד. בנו - ר יקותיאל מיכאל שהו\"ל \"אבני שיש\" ירושלים תרצד.","bk":[["מילי דאבא - ליקוטי הערות תנ\"ך גמרא ושלחן ערוך (נדפס יחד עם ספרי שבות יהודה ובנין נערים לזקניו)",""]]},{"i":3316,"n":"אלבאז, אברהם ממקנאס","b":"מו\"ץ במקנאס בזמן ר\"י בהתית."},{"i":3317,"n":"אלבאז, אברהם מפאס","b":"מחכמי פאס, חתם-תקסא עם ר שאול סירירו."},{"i":3318,"n":"אלבאז, איזו","dp":"בוזעד(מרוקו)","b":"מחכמי מרוקו"},{"i":3319,"n":"אלבאז, אפרים ממכנאס","dt":"תעא - אייר","b":"מו\"ץ במכנאס, יחד עם ר משה טולדנו, ר יוסף בהתית. נספד ב\"אוזן שמואל\" לר שמואל דאבילא."},{"i":3320,"n":"אלבאז, בנימין","b":"מחכמי מרוקו"},{"i":3321,"n":"אלבאז, דוד ממכנאס","b":"מרבני מכנאס, חתם על הסכמה-תקסד."},{"i":3322,"n":"אלבאז, יהודה ממרוקו","k":"בעל שבות יהודה","bt":"תקל","dt":"תרז - טו שבט","dp":"צפרו","b":"רב בצפרו-מרוקו. חיבר דרשות בשם \"שבות יהודה\". בניו: ר שמואל, ר אליעזר, ר עמרם, ר שאול.","bk":[["שבות יהודה",""]]},{"i":3323,"n":"אלבאז, יוסף מאלגיר","k":"הו\"ל סדר פסח ומילה","bp":"דמנאת-מרוקו","dt":"תרץ - בערך","dp":"ירושלים","b":"הגיע ממרוקו וכיהן כרב בגרדאייא-אלגיר, עלה לירושלים. הו\"ל \"סדר פסח ומילה\" - ליוורנו תרסב."},{"i":3324,"n":"אלבאז, יעקב מפאס","b":"מקובל מחכמי פאס. מצאצאי ר שמואל אלבאז."},{"i":3325,"n":"אלבאז, יעקב מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו. בנו - ר שמואל."},{"i":3326,"n":"אלבאז, יצחק ממרוקו","dt":"תסב-ג - כז תמוז","b":"מחכמי מרוקו. בנו ר שמואל אלבאז."},{"i":3327,"n":"אלבאז, יקותיאל מצפרו","f":"עמרם","b":"מו\"ץ בצפרו-מרוקו - שנות ה-תק'. הניח כתבים ופס\"ד."},{"i":3328,"n":"אלבאז, מ' ממכנאס","b":"מחכמי מכנאס, נזכר ב\"משפטים ישרים\"."},{"i":3329,"n":"אלבאז, מרדכי מארבאט","b":"מחכמי ארבאט וסופר בי\"ד-תקיא, אולי היה גם שו\"ב, ויש דיני בדיקה משמו, ונזכר ב\"קופת הרוכלים\" לר ידידיה מונסונייגו. אולי הוא שחתם-תקכא עם חכמי מכנאס."},{"i":3330,"n":"אלבאז, משה ממכנאס","b":"מחכמי מכנאס, חתם על הסכמה-תקסד."},{"i":3331,"n":"אלבאז, משה ממרוקו","f":"מימון","k":"בעל היכל הקדש","b":"מקובל בתרודאנת-מרוקו-שלה, בתקופת האר\"י בצפת. מתלמידיו ר יצחק הכהן בעל \"גינת ביתן\", ר יעקב איפרגן - \"היוצר\" בעל \"פרח שושון\", ור יעבק חנין - דודו של ר יעקב איפרגן. חיבורו בקבלה מבוסס על מסורת קדומה ממרוקו שקדמה לתורת הארי בצפת. ר אהרן הסבעוני מסאלי הגיה והוסיף הערות לספר גם מדברי האר\"י. (באוצר: מגדולי המקובלים בדורו-שנת ת' ! )"},{"i":3332,"n":"אלבאז, משה מפאס","dt":"תרלב","b":"רב בפאס בזמן ר יהודה ן עטר."},{"i":3333,"n":"אלבאז, משה מפאס","f":"שמואל","b":"רב בפאס, חתם-תקלט עם ר יהודה ה\"ן דוד ויוסף, וחתם-תקל עם ר יהודה בן שלמה הכהן, חתם תקמד עם ר יהודה הכהן."},{"i":3334,"n":"אלבאז, נחמיה מפאס","dt":"תרכח","b":"דיין בפאס בזמן ר ידידה מונסונייגו."},{"i":3335,"n":"אלבאז, עמרם מצפרו-מרוקו","f":"יהודה","k":"בעל חיי עמרם","bt":"תקנט","bp":"צפרו-מרוקו","dt":"תריז - א טבת","dp":"צפרו-מרוקו","b":"רב ופייטן בצפרו, חברם של ר וידאל הצרפתי, ר יהודה בירדוגו, ר ידידיה מונסוניינו ועוד. חיבר גם \"בנין נערים\" - נדפס ב\"שבות יהודה\" ירושלי םתשם, \"קול זמרה\". בניו ר יקותיאל, ר יוסף מרדכי, ר אהרן. בתו היתה עגונה וכשקבלה גט היתה עליו שאלה שדנו בה חכמי מכנאס.","bk":[["חיי דעמרם",""]]},{"i":3336,"n":"אלבאז, רפאל משה מפאס - א","b":"סופר בי\"ד בפאס-תקמח וחתם אז על פסק עם ר יהודה הכהן."},{"i":3337,"n":"אלבאז, רפאל משה מצפרו - ב","f":"שמואל","k":"בעל הלכה למשה","bt":"תקפג-ד","bp":"צפרו-מרוקו","dt":"תרנו - כב תמוז","b":"תלמיד דודו ר עמרם אלבאז, ור עמור אביטבול. מקובל, משורר ודיין בצפרו-מרוקו. נפטר ללא ילדים. חיבר גם \"עדן מקדם\", \"מיני מתיקה\", ועוד. מתלמידיו - ר שלום אזולאי, ר אברהם ן שטרית, בן דודו ר אבא אלבאז, ועוד."},{"i":3338,"n":"אלבאז, שאול ממרוקו","f":"יהודה","dt":"תרנה","b":"מחכמי צפרו-מרוקו, דרשן ומוהל."},{"i":3339,"n":"אלבאז, שלום ממראקש","k":"בעל שלום רב","dt":"תשסא","b":"רב במראקש, עלה לארץ וכיהן כרב בחדרה."},{"i":3340,"n":"אלבאז, שלמה ממכנאס","b":"מחכמי מכנאס-תקץ, וחתם אז עם חכמי העיר."},{"i":3341,"n":"אלבאז, שמואל מפאס-מרוקו","f":"יצחק","k":"בעל עוז והדר","bt":"תנח","bp":"מרוקו","dt":"תקט","b":"מחכמי פאס-תצה, תלמיד ר יהודה ן עטר. חתן נכדת ר נחמיה הכהן וירש ממנו את חזקת ביהכ\"נ בפאס, ראש ישיבה ומתלמידיו ר יוסף בן סאמון, ר שם טוב ן אמוזג, ור אברהם מאנסאנו. רב בפאס עם ר יהודה ן עטר, ר יעקב ן צור, ועוד. תשובותיו בספרי חכמים דורו ובהם \"משפט וצדקה ביעקב\". חתם על תקנות שונות. בזמן שהיה ר חיים ן עטר בפאס מסר לו את הנהגת הישיבה. חיבר גם \"הנער שמואל\", \"ויאמר שמואל\" ועוד. בניו ר משה, ר יהודה ור יעקב."},{"i":3342,"n":"אלבאז, שמואל מצפרו-מרוקו","f":"יהודה","k":"בעל נועם שיח","bt":"[תקמט]","bp":"מרוקו","dt":"תרד - יב תמוז","dp":"פאס - צפרו","b":"רב בצפרו, ומשורר. בניו ר רפאל משה, אליהו, בצלאל. חיבר גם \"ע\"ט דודים\", דרשות, קינות, ושיטה בכת\"י. חברו של ר שאול ישועה אביטבול."},{"i":3343,"n":"אלבאז, שמואל מצפרו-מרוקו","f":"יעקב","b":"מחכמי צפרו."},{"i":3344,"n":"אלבאלאג'י, אהרן מאזמיר","dt":"תקכז - ג אלול","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3345,"n":"אלבאליה, ברוך מספרד","f":"יצחק","bt":"ד'תתלז-אדר","bp":"קורדובה","dt":"ד'תתפו","b":"הרביץ תורה בקורדובה, דיין, בקי ביוונית, תלמיד הרי\"ף(לאחר שאביו ציוה עליו לפני מותו לפייס את הרי\"ף על הפולמוס ביניהם)"},{"i":3346,"n":"אלבאליה, יצחק מספרד","f":"ברוך","k":"בעל קופת הרוכלין","bt":"ד'תתצה","bp":"קורדובה","dt":"ד'תתנד -יט ניסן","dp":"ספרד","b":"מחכמי ספרד בדור השני (במאה ה-11) ומקורב למלכות, אחד מחמש החכמים בשם יצחק שהפיצו תורה בדור זה. זקנו של ר אברהם בן דוד בעל ספר הקבלה. למד אצל ר פריגורס - שהגיע מצרפת, ואצל ר שמואל הנגיד שתמך בלימודיו, בזמן שנרצח ר יוסף בן שמואל הנגיד בגרנדה - היה בביתו, וניצל בנס. יועץ המלך-ד'תתכט, ונשיא הקהלה, והחזיק ישיבה בשביליה-גרנדה. היה במחלוקת עם הרי\"ף, אך ציוה את בנו ר ברוך שילך אצל הרי\"ף ויפייסו וילמד אצלו. חיבר \"סוד העיבור\" ושירים ופיוטים. נכדו - הראב\"ד בעל הקבלה."},{"i":3347,"n":"אלבאצי","b":"נזכר ב\"וזאת ליהודה\"."},{"i":3348,"n":"אלבגג, אפרים אבו אל גרדן","b":"נזכר בחידושי ר יהודה אל מדארי לסנהדרין, יש אומרים שהוא ר אפרים תלמיד הרי\"ף."},{"i":3349,"n":"אלבו, אברהם מירושלים","b":"מחכמי ירושלים-שפ, חתום על אגרת שליחות לעיר פאס בשנת שץ"},{"i":3350,"n":"אלבו, חיים מסעוד מאלגיר","b":"רב ומרביץ תורה באלג'יר-תקך-תקץ. מתלמידיו: ר שלמה זוראפה מאלגיר."},{"i":3351,"n":"אלבו, יוסף מסופיה","b":"רב עדת הרומנים בסופיה-שנב, עבר לשלוניקי לאחר שהיה מחלוקת כנגדו ומתנגדיו מינו את ר אהרן מלטי."},{"i":3352,"n":"אלבו, יוסף מספרד","k":"בעל ספר \"עקרים\"","bp":"ק\"פ","dt":"ר","dp":"ספרד","b":"תלמיד ר חסדאי קרשקש. מגדולי המחשבה בחכמי ספרד, רופא מהנדס, רב בדרוקה-קסג שיריאה. השתתף בויכוח בטורטושא וסאן מטיאו-1414, ובויכוח עם המומר די סנטה(=יהושע הלורקי)."},{"i":3353,"n":"אלבו, יצחק מירושלים","b":"מחכמי ירושלים ורב עדת המסתערבים בשנים רס - רצ בערך. במכתב הנוסע משנת רפא מספר עליו שהיה רב קבוע לעדה. מוזכר בספרי חכמי דורו, חתם עם בית דינו של ר יצחק שולל הנגיד, בספר \"חיים וחסד\" מובא על ויכוח שהיה לו עם ר עובדיה מברטנורה."},{"i":3354,"n":"אלבו, ישמעאל מאלגיר","f":"אליהו","k":"הו\"ל רוממות אל","bt":"תר - בערך","dt":"תרע - בערך","b":"פייטן וש\"ץ בביהכ\"נ בשכונת לחארא-אלגיר (ר יצחק מרעלי מספר על מסורת ולפיה בביהכ\"נ הזה נפגשו הרשב\"ץ והריב\"ש בפעם הראשונה - בתשעה באב). עורך \"רוממות אל\"-אלגיר תרנג - ושם גם פיוט ממנו."},{"i":3355,"n":"אלבו, משה משלוניקי","b":"מחכמי שלוניקי, רב בסופיה - עדת הרומניוטים."},{"i":3356,"n":"אלבו, שמואל דון משלוניקי","b":"מראשי קהלת גרוש ספרד בשלוניקי-רן-ש'."},{"i":3357,"n":"אלבוחר, אהרן משלוניקי","f":"יצחק","dt":"תקיד","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3358,"n":"אלבוחר, דוד מקושטא","k":"בעל נחמתי בעניי","b":"רב בקושטא-תקצט. חיבר פירוש לתורה בשם \"נחמתי בעניי\"."},{"i":3359,"n":"אלבוחר, יעקב מקומירג'ינה","dt":"תקנב - חשון","b":"רב הכולל בקומירג'ינה ור אברהם אישטרושא על מקומו אחריו."},{"i":3360,"n":"אלבוחר, יצחק מקאשטוריאה","b":"דיין בקאשטוריאה-תע עם ר מנחם בן חיים הכהן ור יצחק בן חיים בנבנישתי."},{"i":3361,"n":"אלבוחר, שמואל משלוניקי","dt":"רפט","b":"מחכמי שלוניקי. מחותמי ההסכמות. חברו של ר חיים די בושאל בעל \"באר מים חיים\"."},{"i":3362,"n":"אלבוטיני, אליעזר מירושלים","f":"משה","b":"מחכמי ירושלים-רן-רפד ונזכר ב\"כתר תורה\". אחיו של ר יהודה מירושלים בעל פירוש על הרמב\"ם."},{"i":3363,"n":"אלבוטיני, יהודה מירושלים","f":"משה","k":"בעל יסוד משנה תורה","dt":"רפ (באוצר רפג)","dp":"ירושלים?","b":"מקובל מחכמי ירושלים, אביו היה מחכמי ליסבון (פורטוגל), נכדו של ר יוסף אבן חיון, עלה לירושלים וחתם בה בשנת רסט, הוראותיו מפוזרות בספר \"חדושי דינים לרבני ירושלים הקדמונים\". היה ראש הרבנים וראש הישיבה בירושלים לאחר ר יעקב מטרייל. מופיע במכתב ר ישראל מפירושא. חיבר מספר ספרים בכתב יד. קטע מספרו \"סולם העליה\" נדפס על ידי ג. שלום ב\"קרית ספר\" שנה כב חו\"ב. מתלמידיו: ר ישראל אשכנזי, ר יוסף קולון, ר יוסף מדרש."},{"i":3364,"n":"אלבוים, אברהם","f":"אלימלך בן ישראל","b":"נינו של ה\"נועם אלימלך\", ושל ר קופיל מליקווא."},{"i":3365,"n":"אלבוים, אהרן","f":"יצחק","b":"תשובה אליו ב\"השיב משה\"."},{"i":3366,"n":"אלבוים, אלימלך","f":"ישראל בן שלמה","b":"נכד ר אלימלך מליזנסק בעל \"נועם אלימלך\" מצד אמו, ונכד ר שלמה בן ר קופל מליקווא. חתן דודו ר אלעזר מליזנסק. עלה לארץ."},{"i":3367,"n":"אלבוים, יצחק מטעשין","k":"בעל שאילת יצחק","b":"חתן ר יצחק איזיק פרידריך מהומנא. רב בטעשין, טורונטו-קנדה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":3368,"n":"אלבוים, ישראל ליב","b":"בניו - ר שמעון מירוסלב, ר יעקב קופל מאולינוב, ר משה מליזנסק, ר שמעון מקולבסוב."},{"i":3369,"n":"אלבוים, מנחם מנדל מליזנסק","k":"בעל אגרת פתוחה","bt":"תקצו","dp":"תרם","b":"עלה לירושלים עם הוריו. סופר כולל אוסטריה. בשליחות-תרכט בוינה. (נפטר בגולה - בקפידת הרבי משיניבה). חיבר \"אגרת פתוחה\" וינה תרם."},{"i":3370,"n":"אלבוים, צבי שמעון מארה\"ב","f":"נפתלי הרץ","k":"בעל מחאה גלויה","bt":"תרט","bp":"טאוריג-ליטא","dt":"תרפא - ו סיון","b":"רב בשיקאגו-תרנ\"א. חיבר \"מחאה גלויה\" שיקגו תרסט."},{"i":3371,"n":"אלבוים, שמואל מלודז","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":3372,"n":"אלבחר, אברהם מקושטא","b":"גביר בקושטא-שנות ה-תק'."},{"i":3373,"n":"אלבחר, יוסף מאלגיר","b":"מחכמי תלמסאן. נזכר בפנקס הקהלה. אחיו של ר עיוש."},{"i":3374,"n":"אלבחר, יעקב מקושטא","b":"גביר בקושטא-שנות ה-ש'. מכתב אליו מר שלמה ן מאיור משלוניקי."},{"i":3375,"n":"אלבחר, עיוש מאלגיר","bt":"תקי - בערך","dt":"תקץ - בערך","b":"רב בתלמסאן - בשנות ה-תק, וחתם על מעשה ב\"ד. מקור השם אלבחאר (=ים בערבית) הוא כנראה נס שנעשה לאבי המשפחה בים או שמקצועו היה קשור בים. אחיו ר יוסף חתום גם הוא בפנקס הקהלה."},{"i":3376,"n":"אלביב, מכלוף","b":"מחכמי צפת, בשנת תקנה חתם על מכתב בקשת עזרה."},{"i":3377,"n":"אלבילדה, אברהם מארטא","b":"רב קהלת סיציליא בארטא, היה במחלוקת עם ר מנחם דילמידיגו."},{"i":3378,"n":"אלבילדה, יעקב משלוניקי","b":"מגדולי חכמי ספרד בזמן הגירוש-רנב, ר\"מ בשלוניקי. בנו - ר משה."},{"i":3379,"n":"אלבילדה, משה מיאנינה - הנכד","b":"נכד ר משה מספרד ושלוניקי. רב ביאנינה-שנות ה-ש' לצד ר יהושע ן עזרא."},{"i":3380,"n":"אלבילדה, משה מספרד ושלוניקי","f":"יעקב","k":"בעל עולת תמיד","bt":"רלח","bp":"אלבילדה-ספרד","dp":"אוילונה או שלוניקי","b":"רב ופילוסוף בספרד, למד בקלהורא-ספרד, וגלה לשלוניקי עם אביו, רב בארטא-רצד וחתם על תקנה לאסור ריקודים מעורבים ולאחר שלא קוימה התקנה פרש ממשרתו ועבר לאבלונה(=אוילונה) וכיהן כרב, עזב בגלל מחלוקת ועבר לשלוניקי - ולפי זכרון שלוניקי נפטר שם. התכתב עם ר לוי ן חביב. חיבר פירוש על רש\"י - ונדפס עם פירושי ר יעקב קניזל, ר שמואל אלמושנינו ור אהרן אלדבי - קושטא שד. בניו ר אברהם ור יהודה הדפיסו חלק מספריו. חיבר גם \"דרש משה\", \"ראשית דעת\" ועוד."},{"i":3381,"n":"אלבינגר, חנוך הניך","b":"פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":3382,"n":"אלבינגר, יוסף","b":"פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":3383,"n":"אלבינגר, ליבל מוארשא","b":"עורך כתב העת \"בית אברהם\" - וארשא תרצד כנראה ביחד עם ר זליג שניצר. כתב העת נוסד ע\"י תלמידי ר אברהם מסוכטשוב בעל \"אבני נזר\"."},{"i":3384,"n":"אלבינגר, שמעון מוארדיש","b":"רב בווראדיש-תר\"י"},{"i":3385,"n":"אלבכאש, יצחק מאקאי-מרוקו ופאס","b":"מחכמי אקאי-מרוקו, פאס-תקיז."},{"i":3386,"n":"אלבלג, אברהם מבלגרד","f":"יצחק מבלגרד","b":"גביר בבלגרד וקשטוריאה, חתן הגביר יעקב בנבנישתי מקשטוריאה. אחיו - שמואל."},{"i":3387,"n":"אלבלג, חיים מאדרינופול","k":"חותן ר' יוסף קארו","dt":"רפב - לפני","b":"מחכמי אדרינופול-רסח. חתנו - ר יוסף קארו - ה\"בית יוסף\" המזכירו בספרו."},{"i":3388,"n":"אלבלג, יצחק","k":"בעל תקון הדעות","b":"פילוסוף-שנות ה-ק'. חיבר \"תקון הדעות\" בפילוסופיה, והיה מחלוקת כנגדו מצד ר יצחק אברבנל ואחרים, ולעומתם זכה להוקרה מצד ר יצחק בן פלקרי."},{"i":3389,"n":"אלבלג, יצחק מבלגרד","b":"מראשי קהלת בלגרד-תן. בניו - אברהם, שמואל."},{"i":3390,"n":"אלבלג, שמואל מבלגרד","f":"יצחק מבלגרד","b":"גביר בבלגרד וקשטוריאה, חתן הגביר יעקב בנבנישתי מקשטוריאה. אחיו - אברהם."},{"i":3391,"n":"אלבלג, שמואל מקשטוריאה","b":"דיין בקשטוריאה-תצד."},{"i":3392,"n":"אלבלידה, משה בירב מתימן","k":"בעל מדרש אשת חיל","b":"רב בכפר ליד צנעא-רע\"ב"},{"i":3393,"n":"אלבעלי, אברהם מאזמיר","b":"מחכמי איזמיר"},{"i":3394,"n":"אלבעלי, חיים אברהם מאזמיר","dt":"תקמד - טו תמוז","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3395,"n":"אלבעלי, חיים יוסף מאזמיר","dt":"תקם - ה אלול","dp":"אזמיר","b":"מלמד תורה מחכמי אזמיר."},{"i":3396,"n":"אלבעלי, יהודה מאזמיר","b":"דיין באיזמיר"},{"i":3397,"n":"אלבעלי, יעקב מאזמיר","f":"יצחק","k":"בעל קהלת יעקב","dt":"תקלד - ז-ט אדר","dp":"אזמיר","b":"דיין רב ומו\"צ באזמיר-תקכא. חיבר גם \"חלק יעקב\", ועוד. נספד בידי ר יוסף נחמולי ב\"אשד הנחלים\". (תאריך פטירתו נרשם גם - תקלה)."},{"i":3398,"n":"אלבעלי, משה מאזמיר","k":"בעל תורת משה","dt":"תקך - י תמוז","dp":"אזמיר","b":"רב באזמיר."},{"i":3399,"n":"אלבצק ן, מצליח","b":"מגדולי חכמי איטליה הראשונים,ראש ישיבה בסיציליאה-ד'תת\"מ"},{"i":3400,"n":"אלבצראוי, אברהם מצפת","f":"משה חיים","bt":"תקן","bp":"בצרה","dt":"תרל - טו חשון","b":"עלה לצפת-תקץ, ועסק במסחר אבני חן. מקורב לגביר דוד ששון מבומבי, לאחר הרעש-תקצז עבר לירושלים, בזיוו\"ש חתן ר יעקב ספיר בעל \"אבן ספיר\". סייע בבניית הבית בקבר רחל-תרכה."},{"i":3401,"n":"אלבצראוי, בצלאל מירושלים","f":"נסים","bt":"תרנו","bp":"ירושלים","b":"תלמיד \"דורש ציון\", \"תפארת ירושלים\", ביהמ\"ד למורים של חברת העזרה. מורה ופעיל ציוני בדמשק-תרף, מורה בזכרון יעקב, ירושלים. פרסם מאמרים רבים ומהם נדפסו בספר."},{"i":3402,"n":"אלבצראוי, נסים אברהם מירושלים","bt":"תרכט","bp":"ירושלים","dt":"תרעז - כב כסלו","dp":"ירושלים","b":"מחכמי ירושלים ומנהל ת\"ת. בשליחות \"בית אל\"-תרסא בבוכרה, ופעם שניה-תרסג נשאר שם וכיהן כרב בבוכרה, וסיפר כי השליחות השניה לא עלתה יפה כמו הראשונה בגלל שמכמה ערים בבוכרה גורשו היהודים, והתחרות מצד הקופות של מולא יוסף כוג'הין שאסף חלק מכספי הצדקה. חזר לירושלים והתפרנס ממסחר באבני חן."},{"i":3403,"n":"אלבצראוי, שלמה מבבל","k":"בעל דבר שלמה","dt":"תרץ - יג אדר","dp":"תל אביב","b":"מחכמי בבל, ופייטן. חתן ר שלום משה חי גאגין. עלה לארץ והתישב בתל אביב. הניח כתבים בכת\"י. אחיו של ר נסים אברהם."},{"i":3404,"n":"אלבק שלום בן יחזקאל","bt":"1858","dt":"ה'תרפ 1920","bk":[["כופר האשכול",""],["מחוקקי יהודה",""]]},{"i":3405,"n":"אלבק, חנוך","b":"פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"סיני\" - ירושלים תרצז."},{"i":3406,"n":"אלברג שמחה","r":"הרב מלובלין","bt":"1910","dt":"ה'תשנה 1995","bk":[["מנחת ביכורים",""],["ספר היובל",""],["שלמי שמחה",""]]},{"i":3407,"n":"אלברג, אברהם נתן מזגירז","f":"יחיאל איכל מזגיערז","k":"בעל בית נאמן","bt":"תרכח","dt":"תש-א","b":"רב בלאשקיץ. סניקי (פולין)-תרסג, ראב\"ד זגירז'-תרסג, רב בסאנוק-תרפה. נספה בשואה. חיבר \"בית נאמן\" בילגוריא תרפד, \"בית אברהם\" ועוד. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"הבאר\" - זאמושץ-וארשא - תרפד, \"המגיד\" - סטמר תרפח-תרצט, \"קובץ מפרשי התורה\" - מארגרטן תרצג, \"תפארת ישראל\" - וארשא-נ\"י-תל אביב תרצו, \"אפריון\" - בודפשט תרפד."},{"i":3408,"n":"אלברג, אהרן שלמה מקוטנא","k":"בעל אשא עיני","bt":"תרמב","b":"פרנס קהלת קוטנא, עלה לארץ-תרצג והיה ממיסדי העיר בני ברק. חיבר גם ספרים על בני ברק ועל העיר קוטנא."},{"i":3409,"n":"אלברג, יחיאל מיכל מזגיערז","f":"יצחק יודל בן יחיאל","b":"נכד ר יחיאל איכל מקוטנא. רב בזגיערז. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב. (שמו אולי יהודה יחיאל מיכל). לתולדותיו בספר בנו \"בית נאמן\", וב\"צבי לצדיק\". תשובה ממנו ב\"אבן שהם\"."},{"i":3410,"n":"אלברג, שמחה מניו יורק","k":"בעל שלמי שמחה","b":"תלמיד ר נתן שפיגל-גלס בישיבת \"עמק הלכה\" בוארשא, ור מנחם זמבא מפראגא. רב בוארשא, ניצל מהשואה והגיע דרך שנחאי-סין לניו יורק וכיהן כרב ומראשי אגודת הרבנים באמריקה. חיבר גם \"עקדת טרבלינקה\". עורך \"עמק הלכה\" - וארשא תרפו, הירחון \"הפרדס\" בניו יורק על מקום ר שמואל אהרן פרדס. פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז. חיבר גם \"וארשא של מעלה\"."},{"i":3411,"n":"אלברגה, אשר מפרובנס","f":"משה","b":"רב בקרפנטרץ-פרובנס-רן."},{"i":3412,"n":"אלברהניץ, משה מספרד ופאס","b":"רב בספרד, הגיע לפאס-לאחר הגירוש, אחד מ-4 חותמי התקנה הראשונה למגורשים בפאס-רנד."},{"i":3413,"n":"אלברטס, משה ז' מארה\"ב","k":"בעל מעם לועז","b":"רב בניו יורק-תרעז."},{"i":3414,"n":"אלבריס, יעקב מתונס","b":"מחדושיו ב\"אורח לצדיק\" לר אברהם רודריגס."},{"i":3415,"n":"אלברצלוני, יהודה","f":"ברזילי","k":"בעל ספר העתים","bt":"ד'תתנ","bp":"ברצלונה","b":"תלמיד ר יצחק בן ראובן אלברצלוני. מגדולי הראשונים מעצבי ההלכה, רב בברצלונה. מצאצאיו - משפחת שאלתיאל מקטלוניה. חיבר \"ספר העיתים\" בדיני מועדות","bk":[["העיתים","הלכה ומנהג - ראשונים"],["הלכות ספר תורה [גנזי מצרים]","הלכה ומנהג - ראשונים"],["שערי שבועות (הלכה ומנהג - ראשונים) (1080?)",""],["ספר העתים",""],["פירוש לספר יצירה",""],["תיקון שטרות",""]]},{"i":3416,"n":"אלברצלוני, יצחק מדניה-ולנסיה","f":"ראובן","k":"בעל אזהרות","bt":"ד'תתג","bp":"ברצלונה","b":"נכד הרי\"ף? מחכמי ספרד בדור הרביעי ופייטן, כנראה עבר למרוקו וישב בפאס. תלמיד ר חנוך בן משה - (אחד מארבעת השבויים). רב בדניה-ולנסיה. חיבר פיוטים סליחות ואזהרות שנכללו במחזורי צפון אפריקה, תרגם מערבית את ספר המקח לר האי גאון, ואולי הוא המחבר של \"שערי שבועות\". תלמידו - ר יהודה בר ברזילי מברצלונה. זקנו של הרמבן?"},{"i":3417,"n":"אלברשטין, שלמה יהודה ליב","f":"דוד","bt":"תריב","b":"תלמיד ר זאב נחום מביאלא-פלך שדליץ. מצאצאי ר דוד בעל \"חומת ירושלים\". רב בסטאק-פלך שדליץ-תרמא. נסמך מאת: ר ישראל איסר שפירא ממזריטש, ר דב בר מבנדין. חתנו - ר שמואל אריה בן ר בנימין בעל \"מזבח אבנים\"."},{"i":3418,"n":"אלגאבה די, יעקב מקושטא","f":"משה","b":"מחכמי קושטא. תרגם מספרדית \"אמאדיש דגאולה\" - קושטא רצד-שו."},{"i":3419,"n":"אלגאבה, אליהו מטבריה","dt":"תקע - כט שבט","b":"מחכמי טבריה"},{"i":3420,"n":"אלגאבה, משה מקושטא ולאריסה","bp":"קושטא","b":"מחכמי קושטא, נדד במקומות שונים בתורכיה, היה בשיהיר-קיואי(=פירוט)-תקנט, אזמיר-תקס, רב בלאריסה-תקסא על מקום ר משה אשכנזי. התכתב עם חכמי קושטא - ר שמואל חיים, ר יעקב רוסו, ר אברהם הכהן (לא ברור מי הם)."},{"i":3421,"n":"אלגאבה, משה משלוניקי - א","f":"אהרן","k":"בעל יסוד עולם","b":"מחכמי קושטא, מגיה בשלוניקי, הגיה את \"טל אורות\" לר יוסף ן ג'ויה-תקנה הדפיסו עם קונטרס ממנו בשם \"קנין אין כאן\". חיבר \"יסוד עולם\" שלוניקי תקטז, ובסופו חדושים לר יעקב בירב (שהיו אצלו בכת\"י)."},{"i":3422,"n":"אלגאסיס, הלל","b":"מחכמי צפון אפריקה, מתלמידי רב נסים גאון, הרמב\"ם כותב שחיבור בעניני תפילה"},{"i":3423,"n":"אלגדיש, מאיר מספרד","dt":"רטו","b":"תלמיד ר' יהודה בן הרא\"ש. רופא למלך קשטיליה, ונשיא קהלות ישראל בספרד. נזכר בחבורי הרמב\"ן. תרגם לעברית את ספר המדות לאריסטו. נהרג."},{"i":3424,"n":"אלגוואדיש, מאיר מקסטיליה","dt":"קע","dp":"ספרד","b":"רב ורופא בקסטיליה. רופאו של המלך, וגדול בתורה ובחכמה. חברו של ר חסדאי קרשקש. נהרג עק\"ה לאחר שהעלילו עליו כי ניסה להרעיל את המלך אנריקה ה-3."},{"i":3425,"n":"אלגוואדיש, שלמה מאנקונא","dt":"שיו - ה אייר","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":3426,"n":"אלגז, אליהו מתונס","f":"יעקב","b":"רב בגבל, מזכיר הרבנות הראשית בתונס. נפטר בצרפת בדרך לא\"י. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":3427,"n":"אלגזי ישראל יעקב בן יום טוב","bt":"1680","dt":"ה'תקטז 1756","bk":[["ארעא דרבנן",""],["אמת ליעקב",""],["הגדה של פסח",""],["נאות יעקב",""],["קהלת יעקב",""],["שארית יעקב",""],["שלמי צבור",""],["שמע יעקב",""]]},{"i":3428,"n":"אלגזי, אברהם מאזמיר וירושלים","f":"נסים שלמה","b":"מחכמי אזמיר, עלה עם אביו לירושלים בשנים תנ-תק, העתיק את ספר תעלומות חכמה לרבי משה מגלייגו. גיסו - ר חיים חזן בעל \"שנות חיים\"."},{"i":3429,"n":"אלגזי, אברהם מברושה","bt":"של","bp":"קושטא","dt":"שצ","dp":"כיאו-יון","b":"רב בברושה(=ברוסה) על מקום ר אברהם ן יעיש שעבר לקושטא ור יהודה אלגזי על מקומו אחריו, כיאו-יון. נזכר ב\"אגרת שמואל\" לר שמואל אוזידה. בניו: ר משה מאזמיר, ר שלמה מאזמיר, ר מנחם מאזמיר, ר יצחק מאזמיר, ר חיים מאזמיר."},{"i":3430,"n":"אלגזי, אברהם מקושטא","f":"שלמה אלגאזי הזקן","dt":"תס - כג טבת","dp":"אזמיר"},{"i":3431,"n":"אלגזי, אליעזר יצחק מבלבירישוק","b":"רב בבלבירישוק-ליטא על מקום ר חיים ירמיהו פלנסברג, ור ברוך גרוסברד על מקומו אחריו."},{"i":3432,"n":"אלגזי, דוד מברושא","b":"מחכמי ברוסא-ת'"},{"i":3433,"n":"אלגזי, חיים יהודה מאזמיר","dt":"תעג - כב אדר","dp":"אזמיר","b":"רב באזמיר, מתלמידיו - ר משה בן מאיר דנון."},{"i":3434,"n":"אלגזי, חיים מאזמיר","dt":"תלא - יט אלול","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3435,"n":"אלגזי, חיים מקושטא","f":"אברהם","k":"בעל נתיבות המשפט","bt":"שעה","bp":"קושטא","dt":"שפט-ת - כד אדר","b":"תלמיד מהרימ\"ט. עשיר. רב ומפרש בקושטא, וראש ישיבה. חיבר \"נתיבות משפט\" על \"תולדות אדם וחוה\"."},{"i":3436,"n":"אלגזי, חיים מקושטא","b":"מחכמי קושטא-שנות ה-ת'."},{"i":3437,"n":"אלגזי, חיים מקושטא וירושלים","f":"יצחק","k":"בעל עין ימין","dt":"תקפא - כ אלול","dp":"ירושלים","b":"רב באזמיר לאחר ר יוסף חזן, עלה לירושלים-תקעג. הסכים על הספר \"לב מבין\" אזמיר תקץ וחתם בראש. חיבר \"עין ימין\" שלוניקי תקעז, \"דרך עץ החיים\" על הטור. נספד בספר \"מראה הגדול\" ועוד. (יש רושמים תאריך פטירתו תקעט)."},{"i":3438,"n":"אלגזי, חיים מרודוס ואזמיר","f":"מנחם","k":"בעל בני חיי","bp":"אזמיר","dt":"תע - בערך","dp":"אזמיר","b":"תלמיד ר חיים בנבנישתי בעל \"כנסת הגדולה\", ר שלמה אלגזי הזקן, וחתנו ר אהרן לפפא. רב ברודוס, חזר לאזמיר-תמ. חיבר \"בני חיי\" ונדפס ע\"י תלמידיו ר מאיר דאנון ור חיים בן יצחק רפאל אלפנדרי, \"קונטרס הגטין\" בתוך \"יד אהרן\" לר\"א אלפנדרי. בספרו מביא גם מתורת דודו (אחי אמו) - ר יעקב אלפנדרי."},{"i":3439,"n":"אלגזי, יהודה מירושלים","b":"מרבני ירושלים-תמ."},{"i":3440,"n":"אלגזי, יהודה מירושלים וקושטא","f":"אברהם","k":"בעל שער יהודה","bt":"תפ","dt":"תקנ","dp":"צפת","b":"דיין בירושלים, רב בקושטא, אזמיר, חיבר \"שער יהודה\". נזכר ב\"גופי הלכות\" לר שלמה אלגזי - ושם מזכיר שהיה בר פלוגתא של ר משה בנבנישתי די שיגוביא."},{"i":3441,"n":"אלגזי, יהודה מקושטא וברושה","b":"רב בקושטא-שעו, ברושה על מקום ר אברהם אלגזי. נזכר בתשובות ר יהושע בנבנישתי."},{"i":3442,"n":"אלגזי, יהודה מקושטא וירושלים","f":"אברהם","k":"בעל שער יהודה","dt":"שכ","dp":"צפת","b":"רב בקושטא-רפ, ירושלים, שלוניקי ואזמיר. סבו של ר שלמה אלגזי, נשא ונתן עם ר משה בנבנשתי די סיגוביא שמביא דברים בשמו בספרו \"דובב שפתי ישנים\", וכן עם ר יהושע צונצין בשנת שטז. מוזכר בספרי חכמי הדור. מוזכר אצל מהר\"ם ן חביב בספרו. חיבר \"שער יהודה\" שלוניקי תקסה"},{"i":3443,"n":"אלגזי, יום טוב מאזמיר","f":"שלמה אלגאזי","dt":"תפז","dp":"אזמיר","b":"רב באזמיר. אביו של ר ישראל יעקב."},{"i":3444,"n":"אלגזי, יום טוב מירושלים","f":"ישראל יעקב","k":"בעל הלכות יום טוב","bt":"תפז","bp":"אזמיר","dt":"תקסב - ב אד\"א","dp":"ירושלים","b":"מכונה מהריט\"א. עלה לירושלים עם אביו שהיה רבה של ירושלים, ולמד אצלו. למד בישיבת פירירה אצל ר יונה נבון. מחכמי ישיבת \"נוה שלום\"-תקיח, מחכמי \"אהבת שלום\" ביחד עם החיד\"א, שבראשה עמדו אביו ור שלום שרעבי, בשנת תקכט בשליחות באירופה יחד עם ר יעקב חזן, פגש את ה\"חתם סופר\" בפרנקפורט הכותב עליו גדולות. עמד בראש ישיבת \"בית אל\", בשנת תקנה בשליחות נוספת. בנו ר יעקב היה פקיד חברון ונרצח על ידי הערבים. בשנת תקמב \"ראשון לציון\" במקום ר רפאל משה בולה (ולפי רוזניס על מקום ר אברהם בן שמואל מיוחס). חיבר \"הלכות יום טוב\" ליוורנו תקנד, \"גט מקושר\" ועוד.","bk":[["שמחת יום טוב",""]]},{"i":3445,"n":"אלגזי, יום טוב מירושלים","dt":"תקעו - ח סיון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":3446,"n":"אלגזי, יוסף","b":"זקנם של ר שמואל אלגזי מקנדיא, ור משה צרפתי בעל \"תולדות אדם קטן\"."},{"i":3447,"n":"אלגזי, יוסף מאזמיר","f":"שלמה אלגאזי","b":"מגדולי חכמי אזמיר-ת\"נ"},{"i":3448,"n":"אלגזי, יוסף משה ממצרים","b":"מחכמי חברון בשנת תקנג וצפת, וחתם אז על הספר \"שמן המור\". חתן ר חיים מודעי מצפת. רב במצרים-תקף על מקום ר שלמה סכנדרי, וכיהן שם עד תרו. מכתב ממנו לר חיים עמרם מצפת אחרי תקס."},{"i":3449,"n":"אלגזי, יעקב מאזמיר","dt":"תקמח -כה אייר","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3450,"n":"אלגזי, יעקב מחברון","f":"יום טוב","dt":"תקנו - ג אד\"א","dp":"חברון או ירושלים","b":"מחכמי אזמיר, עלה לירושלים, פקיד הכולל בחברון. נהרג עק\"ה בידי הערבים. אולי הוא שחתם-תקיו על שטר התקשרות עם חכמי ירושלים."},{"i":3451,"n":"אלגזי, יעקב מקושטא","b":"רב בקושטא-תקס. סייע לר יצחק ארגואיטי בהוצאת ספרו \"מעם לועז\" ונזכר בהקדמה."},{"i":3452,"n":"אלגזי, יצחק","dt":"תקיב","b":"מגדולי חכמי דורו"},{"i":3453,"n":"אלגזי, יצחק מאזמיר","f":"שלמה","bt":"תרמב","bp":"אזמיר","b":"חזן ומשורר ומלחין, עבר לקושטא-תרפט והו\"ל עתון \"לה בוז די אוריינטי\" (קול המזרח), עבר לפאריס-תרצג."},{"i":3454,"n":"אלגזי, יצחק מאזמיר","f":"אברהם מכיאו","bt":"תיד","dt":"תץ","dp":"בונגאר-באשי ליד אזמיר","b":"תלמיד ר חיים בנבנישתי. ממונה על ממונות באזמיר-תלא, דיין ומו\"צ (אחר פטירת רבו). אחיו - ר משה ור נסים שלמה. נספד בידי ר ברזילי יעבץ."},{"i":3455,"n":"אלגזי, יצחק מירושלים","dt":"תקן - טו חשון","dp":"ירושלים","b":"מחכמי ארץ ישראל, בשנת תקלד הדפיס את הספר \"אמת ליעקב\" לר ישראל יעקב אלגזי ואף הוסיף לו הקדמה."},{"i":3456,"n":"אלגזי, יצחק מכיאו-יון","f":"אברהם","k":"בעל דורש טוב","bt":"שפח","bp":"קושטא","dp":"אזמיר","b":"תלמיד ר חיים בנבנשתי בעל כנסת הגדולה שהביא ממנו בספרו \"בעי חיי\", ור אהרן בן חיים. ממונה על השחיטה בקושטא. רב באי כיאו-יוון (בגיל 17), פרש מהרבנות ורבו אהרן בן חיים התיר לו את שבועתו וחזר לכהונתו. חיבר שו\"ת ר יצחק אלגזי."},{"i":3457,"n":"אלגזי, ישראל יעקב מאזמיר וי-ם","f":"יום טוב","k":"בעל אמת ליעקב","bt":"תמ בערך","bp":"אזמיר","dt":"תקטז - ו-י תמוז","dp":"ירושלים","b":"נכד ר שלמה אלגזי הראשון. תלמיד ר חיים אבולעפיה בעל עץ החיים, ור יצחק רפפורט בעל בתי כהונה. מחכמי אזמיר. עלה לצפת-תצה, רב בירושלים-תקט על מקום ר נסים חיים משה מזרחי ור יצחק רפפורט על מקומו אחריו (ולפי רוזניס על מקום ר יצחק רפפורט ור רפאל מיוחס על מקומו אחריו), חתם-תקיד על שטר התקשרות חכמי \"בית אל\". חיבר \"אמת ליעקב\" קושטא תקכד, ועוד בדפוס ובכתב יד. הגיה את \"חמדת ימים\" באזמיר. בשליחות בקושטא ושלוניקי. הסכים על \"אדמת קדש\", \"חוט המשולש\"-תצט, \"נחפה בכסף\"-תקו, \"פרי האדמה\"-תקז, ועוד. גיסו - הגביר ר יהושע אשכנזי מקושטא.","bk":[["ארעא דרבנן",""]]},{"i":3458,"n":"אלגזי, מנחם מאזמיר - א","f":"אברהם אלגזי","b":"מגדולי חכמי אזמיר-ת\"כ"},{"i":3459,"n":"אלגזי, מנחם מאזמיר - ב","f":"אברהם","b":"רב באזמיר-תר."},{"i":3460,"n":"אלגזי, מרדכי מאדרינופול","b":"דיין באדרינופול-תקנט אצל ר יקיר אסטרוק גירון, יחד עם ר דוד ן ארולייא."},{"i":3461,"n":"אלגזי, משה החסיד","f":"אברהם","b":"מחכמי אזמיר-ת'. אחיו של ר שלמה (נסים) מאזמיר וירושלים. נטה לשבתאות וחזר בו לאחר המרת ש\"ץ. חיבר חדושים על הש\"ס ונדפסו בתוך \"דובב שפתי ישנים\" לר משה בנבנשתי."},{"i":3462,"n":"אלגזי, משה מברושא","b":"רב בברושא-תכח על מקום ר אברהם אוהבי, פעל נגד נתן העזתי שהגיע לעיר. שאל את בן אחיו - ר שלמה אלגזי מאזמיר."},{"i":3463,"n":"אלגזי, משה מקהיר-מצרים","f":"יוסף","b":"רב בקהיר-תר. בזמן עלילת הדם בדמשק ארגן את פגישת מונטיפיורי, אדולף כרמייה ושלמה מונק עם המושל מוחמד עלי, כדי להציל את יהודי דמשק מהעלילה."},{"i":3464,"n":"אלגזי, נסים יעקב מצפת","b":"מחכמי צפת, בשליחות בתורכיה-תצא, ורבני שלוניקי - ר חיים משה אמריליו, ר יצחק פרנסיס, ור אשר שלם - מביאים חדושים משמו. חתם על כתב שליחות ר חיים בן יעקב דוד ור מאיר די שיגורא-תצו."},{"i":3465,"n":"אלגזי, נסים שלמה - ג","dt":"תקמד - כג טבת","dp":"ירושלים","b":"נכדו של ר נסים שלמה - הנכד? נפטר צעיר."},{"i":3466,"n":"אלגזי, נסים שלמה מאזמיר -הזקן","f":"אברהם","k":"בעל שמע שלמה","bt":"שע","bp":"ברוסה","dt":"תמג","dp":"ירושלים","b":"נכד ר יוסף די שיגוביה בנבנשתי בעל \"דובב שפתי ישנים\". מחכמי ברוסה, עלה לירושלים ובשנת תו חזר לתורכיה, עמד בראש ישיבה באזמיר, היה מראשוני הלוחמים בשבתאות, ואף נאלץ לברוח מהם עם חתנו ר אהרן לפפא. בשנת תל חזר לירושלים ונמנה על בית המדרש \"בית יעקב\" שיסד ר יעקב חגיז, ובשנת תלג היה אב\"ד ירושלים. חיבר \"שמע שלמה\" אזמיר תיט, ועוד. חתנו - ר אהרן לפפא בעל \"בני אהרן\". נכד(-אבי אמו) ר יוסף בנבנישתי די שיגוביא. תלמיד ישיבת ר יוסף גאנסו, ר יוסף ששון ור מאיר די בוטון בגליפולי. מחכמי אזמיר, עלה לירושלים, חזר לאזמיר-תב וכיהן כדיין וראש ישיבה. ממתנגדי ש\"ץ, נאלץ לברוח-תכה וחזר-תל אחר המרתו של ש\"ץ. תשובה ממנו לר יעקב ששפורטש מאמשטרדם בענין ש\"ץ. מתלמידיו באזמיר - חתנו-ר אהרן לפפא, קרובו-ר חיים ן מנחם אלגזי בעל \"בני חייא\". בניו - ר יוסף, ר אברהם , ר יום טוב. אחיו - ר משה. תלמיד ישיבת ר יוסף גאנסו, ר יוסף ששון ור מאיר די בוטון בגליפולי. מחכמי אזמיר, עלה לירושלים, חזר לאזמיר-תב וכיהן כדיין וראש ישיבה. ממתנגדי ש\"ץ, נאלץ לברוח-תכה וחזר-תל אחר המרתו של ש\"ץ. תשובה ממנו לר יעקב ששפורטש מאמשטרדם בענין ש\"ץ. מתלמידיו באזמיר - חתנו-ר אהרן לפפא, קרובו-ר חיים ן מנחם אלגזי בעל \"בני חייא\". חיבר גם \"הליכות אלי\"."},{"i":3467,"n":"אלגזי, נסים שלמה מירושלים","dt":"תקסב - יט טבת","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":3468,"n":"אלגזי, נסים שלמה מירושלים הנכד","f":"אברהם","bt":"תע-תל","bp":"ירושלים","dt":"תקכא (בא' תקכו)","dp":"קהיר","b":"נכד ר נסים שלמה הזקן וגדל אצלו לאחר שנתייתם, תלמיד ר חזקיה די סילוה, רב בירושלים בזמן ר אברהם יצחקי. התמנה לרב במצרים רב במצרים יחד עם ר אברהם מעלי ור יהודע זיין ושהה שם מעל ארבעים שנה, אחי אמו של ר חיים אבולעפיה הזקן מחדש הישוב היהודי בטבריה. סייע לחדש את הישוב היהודי בכפר יאסיף. הסכים על \"חק לישראל\"-תק, \"שער יוסף\"-תקיד. (לפי רוזניס היה אחיו מאמו של ר חיים בנבנישתי - ולא דודו)."},{"i":3469,"n":"אלגזי, סולימן (שלמה) מתונס","bp":"תונס","b":"מחכמי תונס-שנות ה-ת' הגיע למרוקו-תנט, וקיבל תעודה מר יעקב מלכא."},{"i":3470,"n":"אלגזי, עלי ממרוקו","dp":"תאגית-מרוקו","b":"מצדיקי מרוקו, כנראה מגולי ספרד."},{"i":3471,"n":"אלגזי, רפאל אברהם מאזמיר","dt":"תקסג - ב אלול","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3472,"n":"אלגזי, רפאל מאזמיר","dt":"תקלא - ד סיון","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3473,"n":"אלגזי, שלום שלמה מאזמיר","dt":"תעז - יז שבט","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3474,"n":"אלגזי, שמואל מקנדיא","f":"יצחק","k":"בעל קבוצת כסף","b":"רב בקנדיא(=כרתים). נזכר אצל ר יצחק שמואל ריגיו - יש\"ר מקנדיא. חיבר קונקורדנציה לספרות התלמוד בשם \"קבוצת כסף\", \"תנחומות אל\", ועוד."},{"i":3475,"n":"אלגיז, יעקב מצפת","b":"מחכמי צפת, חתם-תפא על כתב שליחות ר משה ישראל מרודוס."},{"i":3476,"n":"אלג'ים, אוריאל מצפת","b":"מחכמי צפת בשנת תמה, חתם על כתב שליחות ר יוסף עאטוד בשנת תמו, של ר שלמה אאיליון בשנת תמח, ושל ר יוסף שאלתיאל בשנת תנז"},{"i":3477,"n":"אלגמוט, יהודה אריה","k":"בעל יסוד חינוך הדת","b":"חיבר ספר למורים \"יסוד חנוך הדת\" ריגא תרצז."},{"i":3478,"n":"אלגראנטי, אברהם מאזמיר","b":"גביר מחכמי ורבני איזמיר, תלמיד ר' חיים פלאג'י?."},{"i":3479,"n":"אלגראנטי, יוסף מאזמיר","b":"אין פרטים"},{"i":3480,"n":"אלגראנטי, יצחק מאזמיר","dt":"תקכח - כג חשון","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3481,"n":"אלגראנטי, כלב מאזמיר","b":"רב באזמיר-ת. נזכר ב\"בעי חיי\" לר חיים בנבנשתי."},{"i":3482,"n":"אלגראנטי, משה מאזמיר - א","f":"אברהם","b":"רב באזמיר. תשובה אליו מר חיים בנבנשתי-תד, תכח. (לדעת \"ארזי הלבנון\" מדובר בשתי תשובות לשני חכמים בעלי אותו השם)."},{"i":3483,"n":"אלגראנטי, משה מאזמיר - ב","dt":"תקכט - ט חשון","dp":"אזמיר","b":"רב באזמיר."},{"i":3484,"n":"אלגראנטי, שמואל מאזמיר","b":"מחכמי אזמיר, חברו של ר חיים בנבנישתי בעל כנסת הגדולה - וארחו בביתו כשהגיע לאזמיר."},{"i":3485,"n":"אלגרבלי, מימון ממרוקו","dp":"סטאט-מרוקו","b":"מצדיקי מרוקו."},{"i":3486,"n":"אלגרנאטי, משה מטיריא","b":"רב בטיריא-שעג."},{"i":3487,"n":"אלגרנאטי, נסים חיים מאזמיר","b":"תלמיד ר חיים פלאג'י המזכירו ב\"נפש חיים\". אולי שמו גם יצחק."},{"i":3488,"n":"אלדאודי, חייא מספרד","bt":"ד'תתקיד","dt":"ד'תתקיד","dp":"ספרד","b":"פייטן בקסטיליה ומפיוטיו במחזורים ישנים, מצאצאי ראש הגולה ר' חזקיה. אולי הוא שאסף את שירי ר יהודה הלוי יחד עם ר יהודה בן אליהו (ויש אומרים שהוא ר חייא המערבי)."},{"i":3489,"n":"אלדאודי, מכלוף מצפת","dt":"תרע - ד כסלו","dp":"צפת","b":"רבה של עכו - חכם באשי-תרנו, חיפה, מתורתו ב\"ישא איש\" לר יעקב שאול אלישר. בנו - שלום - תרגם את \"אהבת ציון\" למאפו לערבית."},{"i":3490,"n":"אלדבי (אבן דבי), משה מאלגיר","f":"זכריה","b":"תלמיד דודו ר שלמה בן צמח דוראן וכתב שיר לכבוד רבו. רב באלגיר בזמן האר\"י, אחיו ר יוסף מחכמי אלגיר. ושניהם נזכרים ב\"יכין ובועז\"."},{"i":3491,"n":"אלדבי, מאיר מספרד - אבן אל דבי","f":"יצחק","k":"בעל שבילי אמונה","bt":"ע","bp":"טולידו","dt":"קב","dp":"ירושלים","b":"מקובל מחכמי ספרד, נכדו של הרא\"ש, עלה לירושלים-קח. חיבר \"שבילי אמונה\" ריווא די טרינטו שיט."},{"i":3492,"n":"אלדד הדני","b":"נזכר בשאלת חכמי קירואן-ד'תרם מרב צמח גאון מסורא אודות אלדד הדני שביקר אצלם וסיפר שהוא משבט דן וסיפר להם על מנהגי היהודים במקומו."},{"i":3493,"n":"אלדד ישראל","bt":"1910","dt":"ה'תשנו 1996","bk":[["הגיונות מקרא",""]]},{"i":3494,"n":"אלהבוז, יעקב מאלגיר","bt":"שפ - בערך","dt":"תם - בערך","b":"רב בתלמסאן, וסופר סת\"ם. אחיו ר יהודה סופר סת\"ם גם הוא."},{"i":3495,"n":"אלהבוז, סעדיה מאלגיר","bt":"תק - בערך","dt":"תקף - בערך","b":"רב באלגיר-תקם ונזכר אז בשטר, ישב גם בתאזא-מרוקו עם ר מנחם ן גיגי ושאלו-תקעו שאלה מחכמי פאס. חיבר חיבור על טעמי הלכות המועדים - בכת\"י. נזכר ב\"שופריה דיעקב\"."},{"i":3496,"n":"אלואל","f":"נדרנל","b":"מחכמי תימן-שס\"א"},{"i":3497,"n":"אלואריש קוריאה, עמנואל מליוורנ","bt":"תי","bp":"ליוורנו","dt":"תעז - ה שבט","dp":"קורסאו","b":"תלמיד ישיבת \"עץ חיים\" באמשטרדם, רב בקורסאו."},{"i":3498,"n":"אלואריש, משה מאמשטרדם","b":"רב באמשטרדם. תשובות ממנו ב\"פרי עץ חיים\" - אמשטרדם."},{"i":3499,"n":"אלואשאוולי, ראובן","b":"רב בקוטאיס."},{"i":3500,"n":"אלובאד, עבד הרופא ממצרים","b":"רופא מחכמי מצרים בזמן הרדב\"ז."},{"i":3501,"n":"אלוביץ, יהושע מפרוכניק","f":"אלעזר אליעזר ליפא","bt":"תקצט","dt":"תרנג","b":"היה נינו של הבעש\"ט, חתנו של ר שמחה וובר אב\"ד פרוכניק, ומילא שם מקומו כאב\"ד פרוכניק. גיסו של ר נפתלי בער מליטוביסק."},{"i":3502,"n":"אלוביץ, שלום מטוכוב","k":"ניאמץ","b":"רב בטוכוב בין שתי מלחמות העולם. תשובה אליו ב\"אמרי יושר\"."},{"i":3503,"n":"אלוי-הלוי, סעיד מטריפולי","bt":"תל","dt":"תק - בערך","dp":"טריפולי","b":"רב וספרא דדיינא בטריפולי, וחתם בפנקס בי\"ד טריפולי בשם \"אלוי\" (במקום \"הלוי\")."},{"i":3504,"n":"אלוני נחמיה","bt":"1906","dt":"ה'תשמג 1983","bk":[["מספרות ימי הבינים",""]]},{"i":3505,"n":"אלוני-דובוב, זלמן יוסף מדבלין","f":"יצחק","b":"מחסידי חב\"ד. רב בדבלין-אירלנד. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח. גיסו - ר אהרן פישל הרלינג."},{"i":3506,"n":"אלועס ריבילה, דוד מאנגליה","dt":"תקנו","dp":"האקנייא-אנגליה","b":"גביר מלומד באנגליה."},{"i":3507,"n":"אלוף, שמעון מקושטא","b":"גביר מחכמי קושטא, סייע-תקב לר נסים חיים משה מזרחי בהדפסת ספרו \"אדמת קדש\"."},{"i":3508,"n":"אלופלא, יוסף מספרד","f":"יצחק","b":"מחכמי וושקה-אראגון-שנות ה-ק', בזמן הרשב\"א. העתיק פירוש הרמב\"ם למשנה."},{"i":3509,"n":"אלוש, אברהם מקושטא","b":"מחכמי קושטא-שנות ה-ת'. אחיו - ר חיים אליעזר מקושטא."},{"i":3510,"n":"אלוש, אליעזר מקושטא","b":"רב בקושטא-שנות ה-ת'."},{"i":3511,"n":"אלוש, חיים אליעזר מקושטא","b":"מחכמי קושטא-שנות ה-ת'. אחיו - ר אברהם מקושטא."},{"i":3512,"n":"אלזו, יצחק משלוניקי","dt":"שג","b":"רופא בשלוניקי."},{"i":3513,"n":"אלזוק, אהרן מאלגיר","f":"משה","b":"רב במסתגנאם-אלגיר-רן. נזכר בשו\"ת \"יכין ובועז\"."},{"i":3514,"n":"אלזוק, אהרן מאלגיר","f":"חגי","bt":"שי - בערך","dt":"שפ - בערך","b":"נינו של ר חגי שהיה רבה של מסתגאנם. רב במסתגאנם, על מקום זקנו. התכתב עם ר שלמה דוראן."},{"i":3515,"n":"אלזוק, חגי מאלגיר","f":"שלמה","bt":"קע - בערך","dt":"רן - בערך","b":"תלמיד הרשב\"ש בישיבת אלג'יר. מקובל, רב ודיין במוסתגאנם. התכתב עם הרשב\"ש ששלח אליו את התנגדותו ללימודי הקבלה של תלמידו, והוכיח אותו על שאינו עולה לארץ. מקורב גם לר יוסף ששפורטש מהוניין ונזכר בספרו."},{"i":3516,"n":"אלזם, לוי ממראקש","f":"שלמה","b":"דיין במראקש, חתם על פס\"ד-תצב."},{"i":3517,"n":"אלזרע, אברהם ממרוקו","f":"יוסף","b":"גביר מחכמי ארטיב-מרוקו-תקלה, מכתב בקשה אליו מקהלת חברון. אחיו - ר משה, ר אהרן."},{"i":3518,"n":"אלזרע, אברהם מתאפילאלת-מרוקו","k":"אבא\"ל","b":"מו\"ץ בתאפלאלת-תקס. הניח כתבים בכת\"י וחתם \"אבא\"ל\" = אברהם אלזרע, יחד עמו חתום מסב\"ר(=מסעוד בן רוואח)."},{"i":3519,"n":"אלזרע, אהרן ממרוקו","f":"יוסף","b":"גביר מחכמי ארטיב-מרוקו-תקלה, מכתב בקשה אליו מקהלת חברון. אחיו - ר משה, ר אברהם."},{"i":3520,"n":"אלזרע, חיים מאלגיר","bt":"תרן - בערך","dt":"תש - בערך","b":"רב בסעידא-אלגיר, אינקרמן(=ואד רחיו)-אלגיר. שאלה ממנו ב\"פרחי כהונה\" מר מסעוד הכהן. בעיר גרבה היתה משפחת כהנים - אלזרע, ואולי גם באלגיר המדובר בכהנים."},{"i":3521,"n":"אלזרע, ישראל ממרוקו","b":"תלמיד ר ישראל אבוחצירא בישיבה בבודניב-מרוקו. רב במרוקו, עלה לארץ וכיהן כרב באשדוד."},{"i":3522,"n":"אלזרע, מכלוף מארפוד-מרוקו","b":"דיין בבית דינו של הבבא סאלי בארפוד-מרוקו, יחד עם ר שמעון אבוחצירא."},{"i":3523,"n":"אלזרע, משה ממרוקו","f":"יוסף","b":"גביר מחכמי ארטיב-מרוקו-תקלה, מכתב בקשה אליו מקהלת חברון. אחיו - ר אהרן, ר אברהם."},{"i":3524,"n":"אלזרקי, אברהם מקושטא","b":"מו\"ץ באורטא-קיואי-קושטא-תקף בערך."},{"i":3525,"n":"אלזרקי, אברהם משלוניקי וירושלי","f":"שלמה","k":"בעל ירושלים דדהבא","dt":"ד טבת","dp":"ירושלים","b":"רב בשלוניקי, עלה לירושלים-תקץ ושם נפטר, היה בן בתו של ר שלמה אמריליו, מבני ישיבתו של ר רפאל ניסים פואה, נזכר בספר מקרא קודש לר אפרים חיוג. חיבר גם חיבור בהלכות ארץ ישראל שחלקו נדפס בשם ירושלים דדהבא, וכן ספר שלום ירושלים, תוספת שביעית, וספר הפרדס, וכן בכתב יד שו\"ת מבשרת ירושלים, מבשרת ציון, מוסר השכל ודרושים משנת תקעח. , נזכר ב\"מקרא קדש\" לר אפרים חיוג."},{"i":3526,"n":"אלזרקי, חיים אברהם מאזמיר וירו","dt":"תקנד - יב תשרי","dp":"ירושלים","b":"מחכמי איזמיר,עלה לירושלים בסוף ימיו."},{"i":3527,"n":"אלזרקי, יעקב מאזמיר","dt":"תקכט - י כסלו","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3528,"n":"אלזרקי, שלמה מאזמיר","b":"גביר מחכמי אזמיר-שנות ה-ת', תמך בהדפסת לשון ערומים לר ברזילי יעבץ."},{"i":3529,"n":"אלזרקי, שם טוב מאזמיר","b":"מחכמי אזמיר. דרשה ממנו ב\"צדקה לחיים\" לר חיים פלאג'י."},{"i":3530,"n":"אלחאייך, מרדכי חיים מטריפולי","bt":"תקם","dt":"תרי - בערך","dp":"טריפולי","b":"רב וסופר בטריפולי. חתימתו בפנקס בי\"ד טריפולי. בנו - עוזיאל (יתכן והוא ממשפחת ר עוזיאל אלחייאך מתונס)."},{"i":3531,"n":"אלחאייך, מרדכי מצפת","dt":"תקלז","dp":"צפת","b":"מחכמי צפת. נספד בספר \"חיים וחסד\" לבנו."},{"i":3532,"n":"אלחאייך, עוזיאל מתונס","f":"מרדכי","k":"בעל משכנות הרועים","b":"רב בתונס - תקכז-תקע, דיין עם ר שמואל הכהן יצחקי. תלמיד ר נתן בורגל ור דוד נג'אר, ור שמואל צוייד. התכתב עם ידידו ר יצחק טייב בעל \"ערך השלחן\". חיבר גם \"מערתא דדייני\" ועוד."},{"i":3533,"n":"אלחאייך-סידון, עלאל מאלגיר","f":"אלחאייך","bt":"רך - בערך","dp":"ש - בערך","b":"תלמיד ר יהודה כלץ, ור אברהם סבע בעל \"צרור המור\". רב ומשורר בתלמסאן. לבקשתו חיבר רבו - ר אברהם חיבור בענין עשר הספירות - המופנה אליו, וכן פירוש לתפלה בדרך הסוד. ומפיוטיו בספרי חכמי אלגיר ובהם \"שבחי אלקים\" - ווהראן תרם. נזכר אצל ר יוסף משאש שהיה צדיק קדמון במרוקו והציל את היהודים כמה פעמים מעלילות. יש אומרים כי הוא ר עלאל בן יוסף בן סידון שביקש מר יהודה כלץ להתישב בתלמסאן."},{"i":3534,"n":"אלחאייק, עזריאל מתונס","k":"בעל חיים וחסד","b":"רב בטוניס-תק\"ע"},{"i":3535,"n":"אלחאליל, חיים משלוניקי","b":"סוחר משלוניקי-תק, היה גם ברוסג'וק, מכתב ממנו לר חיים מבורך מניקופול."},{"i":3536,"n":"אלחאליל, יצחק משלוניקי","dt":"שפח - א טבת","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3537,"n":"אלחאמי, (הלחמי), אברהם","f":"דוד","b":"מחכמי תורכיה, עלה לצפת. רב בצפת, בשנת שכג חתום על תשובה, היה מגיה בעיקר על מדרשי הלכה - חתם-שה \"למטעב מט ספח קצח\" ופירושו באלפא אלב\"ם (א=ל ב=מ וכו') - אברהם בן דוד חזק. חתם על אגרת ר שלמה אלקבץ עם רבני צפת."},{"i":3538,"n":"אלחאמי, יעקב מצפת וירושלים","b":"מחכמי צפת וירושלים, חתם על תקנה לשחרור תלמידי חכמים ממס בשנת שמז ושנז. לדעת ריבלין זהה עם ר יעקב שחתם בפסק בדבר עגונה בצפת במחלקות ר יוסף קארו והמביט. בנו ר משה אלחמי שגידל את ר שלמה עדני בעל \"מלאכת שלמה\". יתכן שהוא ר יעקב חמי שחתם בשנת שן בדבר שטר צוואה ומובא בשות ר בצלאל אשכנזי."},{"i":3539,"n":"אלחאמי, משה ממצרים וירושלים","f":"יעקב מצפת וירושלים","b":"גביר בעל חסד במצרים, עלה לירושלים-לפני שמו. נזכר בהקדמת ר שלמה עדני ל\"מלאכת שלמה\"."},{"i":3540,"n":"אלחאנטי, דוד משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":3541,"n":"אלחאנטי, חיים אהרן משירון","b":"מראשי קהלת שירון-שנות ה-ת'."},{"i":3542,"n":"אלחאנטי, יצחק (יצחקוג'ו) משלונ","b":"נבחר לפרלמנט היוני-1923 מטעם שלוניקי."},{"i":3543,"n":"אלחאנטי, שם טוב משלוניקי","dt":"שב - י תשרי","dp":"שלוניקי","b":"מחכמי ספרד, הגיע אחרי הגירוש לשלוניקי וכיהן רופא ור\"מ בק\"ק קשטיליה בשלוניקי, חתם על הסכמות-רצג. בספרד היה סופרו ומגיהו של ר יצחק עראמה. נספד ע\"י ר סעדיה לונגו."},{"i":3544,"n":"אלחג'רא מטריפולי","k":"חכם אלחג'רא","b":"רב בז'ריאן-לוב, לדברי גבריאל רוקח - מוצאו כנראה מארץ ישראל (עליו ב\"מחניים\" תשכד)."},{"i":3545,"n":"אלחדד, אהרן הכהן ממראקש-מרוקו","b":"מחכמי מרוקו באזור מראקש."},{"i":3546,"n":"אלחדד, אלעזר הכהן ממראקש","dp":"כפר תאגמות-ליד מארקש","b":"מקובל, מחכמי מראקש"},{"i":3547,"n":"אלחדד, דב הכהן"},{"i":3548,"n":"אלחדד, דוד ממרוקו","f":"יחיא","k":"בעל מעגלי צדק","b":"רב במרוקו בזמן היעב\"ץ. חיבר \"מעגלי צדק\"-תקיג בכת\"י."},{"i":3549,"n":"אלחדד, יהודה הכהן ממרוקו","dp":"אלנזאל-נוף מראקש","b":"מחכמי מרוקו."},{"i":3550,"n":"אלחדד, יוסף הכהן ממראקש","b":"מחכמי מראקש-שנות ה-תק'."},{"i":3551,"n":"אלחדד, יוסף הכהן ממרוקו","f":"יעקב מתאזנאנאת","dp":"כפר וארזאזאת-מרוקו","b":"צדיק ומלוב\"ן במרוקו."},{"i":3552,"n":"אלחדד, יוסף הכהן מפאס","f":"זבולון","b":"שו\"ב מחכמי פאס יחד עם ר אברהם אדארוקי, לבקשת ר יצחק הצרפתי - חתמו על פס\"ד עם ר עזוז למדאדסי, ר משה מאמאן."},{"i":3553,"n":"אלחדד, יעקב הכהן","b":"מחכמי מרוקו. בנו - ר ישראל."},{"i":3554,"n":"אלחדד, ישראל הכהן ממרוקו","b":"מחכמי מרוקו, מצאצאיו חיים בקזבלנקה."},{"i":3555,"n":"אלחדד, מסעוד הכהן מירושלים","f":"דוד","k":"בעל כח מעשיו הגיד","r":"אב\"ד ראחוב","bt":"תקף בערך","bp":"מרוקו","dt":"תרפז - כד סיון","dp":"ירושלים","b":"עלה עם הוריו לירושלים. ראש ישיבת המקובלים \"בית אל\"-תרסג. בשליחות בצפון אפריקה ובאירופה-תרסב. למד קבלה עם ר וידאל אנג'ל ור שלום הדאיה בעל \"דעה והשכל\" שכיהן על מקומו אחריו. נפטר בגיל 107. בנו - ר יוסף נפטר צעיר בחיי אביו והניח יתומים קטנים.","bk":[["בן מכבד אב - עה\"ת",""],["כח מעשיו הגיד לעמו - דרושים",""],["שמחת כהן – שו\"ת",""],["שמחת כהן",""]]},{"i":3556,"n":"אלחדד, סעיד הכהן ממראקש","f":"יוסף","b":"מחכמי מראקש-שנות ה-תק'."},{"i":3557,"n":"אלחדד, שלם הכהן ממראקש","b":"מחכמי מראקש-תקמח וחתם בעניני טריפות."},{"i":3558,"n":"אלחדד, שלמה מסאלי","f":"אברהם","b":"מחכמי סאלי-תפח וחתם עם ר שלמה הכהן בן מרדכי אלכלאץ ור אלעזר בן דוד הלוי."},{"i":3559,"n":"אלחדד, שמעון הכהן","b":"מחכמי צפת, בשנת תקנה חתם על מכתב עם חכמי צפת."},{"i":3560,"n":"אלחדיב - משפחה","b":"משפחה ממוריאה-יוון ונקראו גם אלחדף. מבני המשפחה גם ברודוס בפטרץ(=פאטרץ), בליפאנטו, חלקם עבר לונציה."},{"i":3561,"n":"אלחדיב, אברהם מירושלים","b":"רב ברודוס, עלה לירושלים, הסכים על \"ברית אברהם\"-תקנא."},{"i":3562,"n":"אלחדיב, חביב","dt":"שפד - יד אב","b":"מחכמי ורבני יוון"},{"i":3563,"n":"אלחדיב, יצחק","f":"שלמה בן צדיק","k":"בעל פסח דורות","bt":"ק-קי","dt":"קץ - בערך","b":"מצאצאי הרא\"ש. נכד ר יהודה קרישף - חתנו של הרא\"ש. תלמיד ר יהודה בן הרא\"ש השני מבורגוש. מחכמי בורגוש, טולידו. עזב את ספרד ועבר למגרב מאימת הפרעות-קנא, סירקוז-סיצילה, פלרמו-תקפח. תלמידו - ר פרגי נסים בן שבתי אל פרגי. חיבר שירי ר יצחק אלחדד - לוד תשמח, ועוד חלקם בכת\"י. המציא מכשיר אסטרונומי."},{"i":3564,"n":"אלחדיב, יצחק הספרדי","f":"שלמה בן יצחק","k":"בעל לשון הזהב","b":"פייטן מחכמי ולנסיה-ק, חכם בחכמת התכונה בספרד (לפי ארזי הלבנון - איטליה בזמן מהר\"ם פאדובה). חיבר \"לשון הזהב\" - ונציה, \"אורח סלולה\" על סוד העיבור ועוד."},{"i":3565,"n":"אלחדיב, יצחק ממצרים","b":"מגדולי רבני מצרים-ת\"ל"},{"i":3566,"n":"אלחדיב, יצחק ממצרים","b":"מרבני מצרים-שס\"ד"},{"i":3567,"n":"אלחדיב, מנחם מפאטראץ","b":"רב בפאטראץ-יון."},{"i":3568,"n":"אלחדיב, עזרא מונציה","f":"שלמה","b":"תלמיד ר אברהם ן חיים מפאס בעל \"קרבן אהרן\" בהיותו בונציה, ור יהודה אריה ממודנא. רב בונציה-שץ יחד עם ר עזריה פיגו. כנראה (לדעת בעל ארזי הלבנון) חיבר ספר דרושים בכת\"י (ונאמר עליו כי לא נודע למי). מוזכר ב\"דבר שמואל\". חתום על תשובה עם ר שמחה לוצטו - בכת\"י."},{"i":3569,"n":"אלחדיף, אברהם מטבריה","bt":"תקסא","bp":"טבריה","dt":"תרל-ו - ח אד\"ב","dp":"טבריה","b":"מחכמי טבריה. חתם על מסמכים רבים יחד עם חכמי טבריה."},{"i":3570,"n":"אלחדיף, אברהם מקורפו","f":"שלמה","b":"דיין בקורפו-רצ וחתם אז עם חבריו ר שבתי בכר יצחק הכהן ור שבתי בכר שלמה. נזכר ב\"בנימין זאב\"."},{"i":3571,"n":"אלחדיף, אברהם מרודוס וירושלים","bp":"רודוס","dt":"תקנט","dp":"חלב","b":"דיין ברודוס - תפב, חברו של ר' חיים אבולעפיה עלה מאזמיר עם חברו ר חיים לטבריה-תצח עם חידוש הישוב שם, בשליחות-תקא - השליח הראשון מטבריה, עבר לירושלים, היה חבר בבית דינו של ר' נסים חיים משה מזרחי-תקח, וכן בבית דינו של ר יצחק רפפורט בעל בתי כהונה, בשליחות בטריפולי-תקמז ונפטר בדרכו חזרה. מופיע בספרו של ר' אברהם כלפון \"ספר הדורות\", חיבר שו\"ת בכת\"י. (התאריכים לא מסתדרים?)"},{"i":3572,"n":"אלחדיף, אהרן בכור מטבריה -אב\"א","f":"חיים","k":"בעל מפי אהרן","bt":"תקצה","bp":"טבריה","dt":"תרסט - טז אב","dp":"טבריה","b":"מחכמי טבריה, חתום על תעודות שונות, חתנו של ר יעקב שאלתיאל ניניו, בשנת תרלו חתם על כתב שליחות ר יהודה בירדוגו, והיה בעצמו שדר. בשנת תרנח נבחר כחכם באשי בטבריה, חיבר \"מפי אהרן\" ירושלים תרסז, שות \"כפי אהרן ירושלי תרסז, \"זכות יוסף\" ליוורנו תרלג ועוד . תשובה ממנו בספר \"גדולי ארץ ישראל\" ירושלים תשל, בענין נשואי קראית. חתם בשם - \"אב\"א ס\"ט\"."},{"i":3573,"n":"אלחדיף, אהרן מטבריה","dt":"תרה - אחרי","dp":"טבריה","b":"מחכמי טבריה-תקנח, בשנת תקנח חתם על אגרת שליחות של ר משה יעקב מאגאר, בשנת תקעו על השליח ר חיים שלמה אבולעפיה, ועוד"},{"i":3574,"n":"אלחדיף, אהרן ממצרים","b":"גביר מחכמי מצרים-שנות ה-תק'."},{"i":3575,"n":"אלחדיף, דוד מטבריה","f":"אברהם","bt":"תקצד","bp":"טבריה","dt":"תרצא","dp":"טבריה","b":"מפרנסי טבריה"},{"i":3576,"n":"אלחדיף, זכאי מטבריה","f":"חיים","bt":"תרן","bp":"טבריה","b":"מראשי הקהלה בטבריה, וראש העיר-תרפג."},{"i":3577,"n":"אלחדיף, חיים מטבריה - א","k":"בעל מקור חיים","bt":"תקנו?","bp":"טוסקנה","b":"בשנת תקפו עלה לצפת וחתם שם בשנת תרו, רב בטבריה-תרך. חיבר \"מקור חיים\", ואת החוברת \"יצב גבולות\" חמד תרסד. חתם על כתב שליחות ר בן ציון אלקלעי-תרמח. בניו: ר חנן, ר בכור אהרן."},{"i":3578,"n":"אלחדיף, חיים מטבריה - ב","f":"בכור אהרן אלחדף","k":"בעל יצב גבולות","bt":"תרכ","bp":"טבריה","dt":"תרפז - כא אד\"ב","b":"מרבני טבריה-תרן. בשליחות טבריה לתורכיה-תרסג, ראש ישיבת \"מאיר בת עין\", חיבר \"יצב גבולות\""},{"i":3579,"n":"אלחדיף, חנן מטבריה","f":"חיים מטבריה","b":"מחמכי טבריה, מכר את זכות השליחות למרוקו-תרן."},{"i":3580,"n":"אלחדיף, יצחק ממצרים","b":"רב במצרים-שנות ה-ת'."},{"i":3581,"n":"אלחדיף, יצחק מספרד","f":"שלמה","k":"בעל ארח סלולה","b":"מחכמי ולנסיה-ק' בזמן ר שמואל צרצה-אבן סנה. בקי בחכמה ופילוסופיה."},{"i":3582,"n":"אלחדיף, שמואל מירושלים","f":"אברהם","dt":"תקלד - לפני","b":"מחכמי ירושלים, בשנת תקיב חתם על שטר התקשרות עם ר שלום שרעבי. בשנת תקיח היה מחכמי \"בית אל\" וישיבת \"חסד לאברהם\". בשנת תקכד בשליחות עם שבעה חכמים בקושטא ומצרים. בשנת תקכד חתם עם חכמי טבריה על כתב שליחות ר חיים שלום עמאר. התגורר תקופה במצרים וחזר לטבריה. נזכר ב\"מעגל טוב\" לחיד\"א."},{"i":3583,"n":"אלחכים, יצחק מפיררה","b":"רב בפיררה, מדפיס בקושטא. הדפיס והגיה חבורי ר יוסף יעבץ - \"מאמר האחדות\" ו\"יסוד האמונה\". והוסיף מאמר משלו. ועוד."},{"i":3584,"n":"אלחכים, שלמה מתימן","b":"מחכמי חבאן - במאה ה-16. למרות שהיה סגינהור ידע לסייע למושל העיר בזמן מצור עליו, וכשרצה לגמול לו, העניק לו רובע עבור היהודים שנקרא במקורו \"חאפית בא בעאר\" - ושונה שמו ל\"חאפית אל יהוד\"."},{"i":3585,"n":"אלחליח, אליהו מירושלים","f":"יעקב","bp":"תונס","dt":"תרסח","dp":"ירושלים","b":"עלה לירושלים, חיבר ספר \"בקע לגולגולת\" ירושלים תרעא."},{"i":3586,"n":"אלחנן","f":"צבי","b":"מקובל. בנו ר לייב דיין בניקלשבורג."},{"i":3587,"n":"אלחנן","f":"מרדכי דוד מדומברווה"},{"i":3588,"n":"אלחנן בעל התוספות","f":"יצחק - ר\"י הזקן","k":"מגדולי הראשונים","dt":"ד'תתקמד","b":"מחבר תוספות על התלמוד, רב בדינפייר, נהרג בחיי אביו עק\"ה? (ידוע שנהרג בחיי אביו - לא ידוע אם ע\"י שונאים). חיבר פיוטים ונכנסו למחזור, חיבר ספר בדיני תפילה וברכות בשם \"סדר תקון תפלה\", ועוד."},{"i":3589,"n":"אלחנן בעל שם טוב","b":"מקובל,רב בוינה"},{"i":3590,"n":"אלחנן גאון - הזקן","b":"אביו של רב שמריה גאון ממצרים-ד'תש. כנראה מוצאו מאיטליה והתישב בקירואן."},{"i":3591,"n":"אלחנן גאון מצרים - הנכד","f":"שמריה גאון","b":"תלמיד ישיבות רב שרירא ורב האי בבבל. גאון במצרים על מקום אביו-ד'תשסב. כנראה נאלץ לברוח בגלל ויכוח עם מומר - והתישב במוסול ולשם כתב לו ר צמח בן פלטוי."},{"i":3592,"n":"אלחנן דוד מירושלים","dt":"תריב - כב שבט","dp":"ירושלים","b":"חתן ר אלעזר משה. מחכמי ירושלים."},{"i":3593,"n":"אלחנן הלוי סגי נהור","b":"חכם ומקובל-ש'. חיבר קונטרס המשיג על ר שמואל בן חיים הספרדי בעניני קבלה."},{"i":3594,"n":"אלחנן מאויבן","dt":"תקכט - כ טבת","b":"ראב\"ד באויבן"},{"i":3595,"n":"אלחנן מאויבן","dt":"תיא","b":"מקובל,רב באויבן"},{"i":3596,"n":"אלחנן מאיטליה","f":"יהודה","b":"מחכמי איטליה-ד'תתק."},{"i":3597,"n":"אלחנן מאיטליה","f":"שלמה","b":"מחכמי איטליה-ק'."},{"i":3598,"n":"אלחנן מאשכנז וירושלים","b":"עלה לירושלים-רפג, ונזכר במכתב ר ישראל מפירושה שאחיו העשירים שולחים לו כסף כל שנה."},{"i":3599,"n":"אלחנן מבוצאץ וסטרי","f":"זאב וולף מאליק","dt":"תמו - יד אלול","b":"נכד ר יצחק בן שמואל זנויל מזולקוא. נכד המהרש\"ל. רב בבוטשאטש(=בוצאץ), סטריא. מתורתו ב\"הפלס\" - ברלין תרסא-תרסה."},{"i":3600,"n":"אלחנן מבוריסוב","f":"יחזקאל פייבל-תולדות","dt":"תרי-יג - כב אב","dp":"מינסק","b":"נכד ר יחזקאל פיבל בעל \"תולדות אדם\". חתן הגביר ר הרש האראדאקער מאסקעס. רב בבוריסוב-תקן. נזכר בשו\"ת ר יקב מאיר פאדובה מבריסק - \"תשובות מהרי\"ם\". נספד ב\"בית דוד\" לר דוד טעביל. (באוצר הרבנים - נפטר בחשון). בניו ר אפרים זלמן מראזינאי, ור זאב וולף רידקין מבוטען, חתנו ר נתנאל שפירא - שהחזיק בכת\"י ממנו. אחיו של ר וועלוועלע מגיד מוילנא."},{"i":3601,"n":"אלחנן מביירות-לבנון","b":"רב בביירות-לבנון-שנות ה-ש'."},{"i":3602,"n":"אלחנן מגריצה","b":"רב בגריצה"},{"i":3603,"n":"אלחנן מדנציג וקלן","b":"רב בדנציג, קלן ארנסבורג ומינסטר - ובתחום רבנותו גם בון - והיה היחיד שביה\"ד בפפד\"מ הסכים למסור בפניו את זכרון הדברים בפרשת הגט מקליווא-תקכו."},{"i":3604,"n":"אלחנן מוילנא","f":"יצחק זעלקא","dt":"תקמה - כח אב","dp":"וילנא","b":"חתן ר אריה ליב בלוך מוילנא (ובאמת גיסו). דיין בוילנא. חתנו - ר יחזקאל פיבש מוילנא בעל \"תולדות אדם\"."},{"i":3605,"n":"אלחנן מוילקוביסק","k":"אלחנן הפרוש","b":"רב בוילקובישק"},{"i":3606,"n":"אלחנן מוינה","k":"בעל ארבע חרשים","dt":"תיא - יד טבת","b":"מחכמי וינה. בניו - ר יוסף ישכר בער געץ מקרזמיר, ר יהודה ליב מהאציפלאץ וניקלשבורג."},{"i":3607,"n":"אלחנן מזולקוא","dt":"תסו - כה תמוז","b":"רב בסלוצק"},{"i":3608,"n":"אלחנן מטיבינגן","f":"מאיר","b":"פרנס וראש הקהלה בטיבינגן-תקך, היה במחלוקת עם האב\"ד ר אברהם בנימין שפירא, נזכר בפנקסו של הרב, נזכר גם ב'יש מנחילין' לר פנחס קצנלנבוגן שבנו ר יעקב החליף את ר אברהם בנימין. גיסו - ר ליב וסרמן."},{"i":3609,"n":"אלחנן מירושלים","b":"מחכמי ירושלים בשנת רפג, נזכר במכתב ר ישראל מפירושא כרב מן האשכנזים."},{"i":3610,"n":"אלחנן מכמפונטי","b":"מחכמי יון-ד'תתק."},{"i":3611,"n":"אלחנן מלונדון","f":"יקר","k":"בעל יסוד היסודות","b":"מחכמי אנגליה-ה'א. חיבר ספר \"יסוד היסודות\" ונזכר בעבודת הקדש לר\"מ גבאי."},{"i":3612,"n":"אלחנן מפאלאטא","b":"רב בפאלאטא(=פאלטא)"},{"i":3613,"n":"אלחנן מפאנו","f":"יצחק","b":"מחכמי איטליה-ש', גביר עשיר מיושבי בולוניה ופיררה. חתם על תקנות חכמי הדור-שיד בראשות מהר\"ם פאדובה."},{"i":3614,"n":"אלחנן מפיורדא","b":"רב בפיורדא"},{"i":3615,"n":"אלחנן מפרשבורג הקדוש","f":"מאיר רופא","dt":"תקמה - יב שבט","dp":"פרשבורג","b":"מחכמי פרשבורג וחברי הח\"ק-תקם. נהרג עק\"ה."},{"i":3616,"n":"אלחנן מצור","f":"משה","b":"מחבר בית הדין בצור בשנת ד תשעו (1014), חתום על תעודה שפרסם מ. אסף בתרביץ ט, ומאן בספרו ח\"ב."},{"i":3617,"n":"אלחנן מצפת","f":"שמעון","b":"מחכמי צפת, חתום על אגרת חכמי צפת בתקמג"},{"i":3618,"n":"אלחנן מקהיר","k":"מגדולי הראשונים","b":"רב בפוסטט-קהיר-ד'ת\"ת"},{"i":3619,"n":"אלחנן מקורביל","b":"נזכר ב\"שער הרזים\" לר טודרוס הלוי שהביא שמועוה ממנו. נזכר בקונטרס כת\"י מר משה בן שמעון מבורגוס שמביא דבר קבלה בשם הרמב\"ן שהביא בשם ר אלחנן."},{"i":3620,"n":"אלחנן מרקנדורף","b":"שו\"ב ברקנדורף-ליד פרשבורג. נסמך-תקסג מאת ר אלעזר לעוו בעל \"שמן רוקח\"."},{"i":3621,"n":"אלחנן משוטלנד","f":"שמואל זנוויל אשכנזי","k":"בעל סדרי טהרה","b":"רב בפרדאן(בגיל 18), שוטלנד, בונא-תקכז, חזר לשוטלנד(נפטר בגיל 66). חיבר \"סדרי טהרה\" ובתוכו \"חדוד הלכות\", ו\"שיורי טהרה\" - יצא לאור ע\"י בנו - ברלין תקמג."},{"i":3622,"n":"אלחנן סופר מברלין","f":"יוסף","b":"מראשי הקהילה בברלין-תע, והיה מתומכי ר יהודה ברלין ואשתו אסתר בזמן המחלוקת אודות ביהכ\"נ בברלין."},{"i":3623,"n":"אלחריזי, אברהם מספרד","k":"אסחאק אלחריזי","b":"פייטן ומשורר בספרד-ד'תתק בערך. נזכר אצל ר משה ן עזרא ב\"שירת ישראל\", וב\"תחכמוני\"."},{"i":3624,"n":"אלחריזי, יהודה מספרד","f":"שלמה","k":"בעל תחכמוני","bt":"ד'תתקכה","bp":"ברצלונה","dt":"ד'תתקצ-ד","dp":"ברצלונה","b":"משורר,מתרגם,חוקר,למדן,עבר בנדודיו בצרפת-מרשיליה, איטליה, יון, פרס, ארץ ישראל, סוריה, מצרים, חיבר \"תחכמוני\", \"מחברות אתיאל\" בכת\"י, \"ספר הגורלות\"."},{"i":3625,"n":"אלט, אברהם אליעזר זאב","f":"משה דוד אלט","dt":"תרנח - טו ניסן","b":"דיין באדנבורג, רב בקויבסדורף. דודו - ר צבי הירש קוניץ מבעלעד."},{"i":3626,"n":"אלט, יעקב ישראל","dt":"תרלז - אדר","b":"רב בפבערבעטע-תקצ\"ז,"},{"i":3627,"n":"אלט, משה דוד","b":"רב בקויבסדורף-תר\"כ"},{"i":3628,"n":"אלט-אייבניץ, דוד מקברסדורף","f":"גדליה","bt":"תקלז","dt":"תרי - כג ניסן","dp":"קברסדורף","b":"תלמיד החת\"ס. חתן ר משה קוניץ מלקנבאך. רב בקברסדורף, בנו ר אברהם אליעזר זאב על מקומו אחריו. מוזכר ב\"חתם סופר\"."},{"i":3629,"n":"אלטאנסי, אברהם משלוניקי","b":"מחכמי שלוניקי-רץ."},{"i":3630,"n":"אלטביב, אברהם","b":"חתם שמו על ספר עין ימין-שלוניקי תקעז."},{"i":3631,"n":"אלטביב, אברהם - א","b":"מתורתו ב\"מקור חיים\" לר שמואל צרצה. חיבר השגות על פירוש התורה לר שלמה פרנקו ועל פירוש ראב\"ע - בכת\"י."},{"i":3632,"n":"אלטביב, אברהם מיוון","f":"שלמה","b":"מחכמי יון-ש', נזכר בשו\"ת בנימין זאב, וכנראה שהיה רב בקורפו."},{"i":3633,"n":"אלטביב, דוד מקומורג'ינה","b":"רב בקומורג'ינה-שנות ה-ש'."},{"i":3634,"n":"אלטביב, דוד משלוניקי","b":"גביר מחכמי שלוניקי-בתחילת שנות ה-ש'."},{"i":3635,"n":"אלטביב, משה מפטרץ","b":"רב בפטרץ-שנות ה-ש'."},{"i":3636,"n":"אלטביב, משה משלוניקי","b":"דיין בשלוניקי-שיב."},{"i":3637,"n":"אלטביב, שלמה מקושטא","dt":"רפ - אחרי","b":"מחכמי קושטא-רן, נזכר אצל הרא\"ם."},{"i":3638,"n":"אלטביב, שמואל"},{"i":3639,"n":"אלטביב, שמואל משלוניקי","dt":"ש - ח טבת","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3640,"n":"אלטברג, יצחק מאלטשטט","b":"רב באלטשטט-תרמה, תשובה אליו ב\"מצפה אריה\". תלמיד ה\"שערי דעה\"."},{"i":3641,"n":"אלטון, יצחק משלוניקי","dt":"שט - כה טבת","dp":"שלוניקי","b":"מיוצאי ספרד, מחכמי שלוניקי וחתם עם רבני שלוניקי על החרם בענין הצמר. בנו - ר נסים."},{"i":3642,"n":"אלטון, משה משלוניקי","dt":"רצג - פסח","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":3643,"n":"אלטון, נסים משלוניקי","f":"יצחק מספרד ושלוניקי","dt":"שם-ס - כט טבת","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3644,"n":"אלטוניס, משה מאיטליה","b":"מחכמי איטליה, העתיק ארבעה מספרי אריסטו-רנב."},{"i":3645,"n":"אלטוסקי, יהודה מארה\"ב","k":"בעל הגיוני יהודה","b":"חיבר \"הגיוני יהודה\" נ\"י תרצה."},{"i":3646,"n":"אלטורטושי, יוסף משלוניקי","dt":"רצו - יד אד\"א","dp":"שלוניקי","b":"מוצאו בטורטושה-קטלוניה. מחכמי שלוניקי."},{"i":3647,"n":"אלטין, אברהם מסוקולוב","b":"רב בסוקולובקה-תרפה, תשובה אליו ב\"מחזה אברהם\" ו\"חזון נחום\"-תרצד."},{"i":3648,"n":"אלטמוגר, שמואל חנוך מקריניק","b":"ר\"מ בראסיין, דיין בקריניק. הניח חדושי תורה בכת\"י."},{"i":3649,"n":"אלטמן, אברהם אליהו","f":"שלמה זלמן משובאץ","bt":"תרלח","dt":"תשח","b":"רב בעקרון."},{"i":3650,"n":"אלטמן, אלימלך מפשצלוב","b":"רב בפשצלוב וגבאי א\"י-תרפה, השיב לו ב\"משיב שלום\"."},{"i":3651,"n":"אלטמן, אליעזר זוסמן מבעקש-טשבא","f":"שמשון מפאקש","k":"בעל נבכי נהרות","bt":"תרעה","dt":"תשד - יז תמוז","dp":"אושוויץ","b":"תלמיד הדעת סופר, וזקנו ר שמעון סופר מפאקש. חתן ר יצחק טיגרמן מבעקש-טשאבא, וכיהן כרב לצד חותנו. נספה בשואה."},{"i":3652,"n":"אלטמן, חיים מראווה","f":"דוד הלוי","bt":"תרנו","bp":"ראווה","dt":"תשמו","b":"חסיד בלז. עבר לארגנטינה. עלה לארץ-תשלה."},{"i":3653,"n":"אלטמן, חיים שלמה מטשבין","dt":"תש..","b":"מחכמי שטשאקאווע, ר\"מ בטשבין. נספה בשואה. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":3654,"n":"אלטמן, יהודה (יוסף) ממעזא-טשאט","f":"יצחק מבאלקאן","k":"בעל מי יהודה","bt":"תריט או תרכד","bp":"ניר-באלקאני","dt":"תרפג - ג אדר","b":"תלמיד ר יהושע ברוך רייניץ, חתן ר שרגא צבי טננבוים ממעזא-טשאטה בעל \"נטע שורק\". רב במעזא-טשטא-תרנד על מקום חותנו, ובנו ר שרגא צבי על מקומו אחריו. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":3655,"n":"אלטמן, יהודה ליב מקמינקא","f":"יצחק שמחה","b":"רב בקמינקא-תקן."},{"i":3656,"n":"אלטמן, יוסף מקרלסרוהא","b":"רב בקרלסרוהא-תר."},{"i":3657,"n":"אלטמן, יעקב צבי מווריש","b":"רב בווריש-תרל."},{"i":3658,"n":"אלטמן, יצחק מבאלקאן","bp":"קאלוש","b":"תלמיד הכת\"ס, ור שמואל קליין מסעליש. חתן ר שמשון לוסטיג מבאלקאן ועבר לשם-תריט וכיהן כראש הקהלה. בנו ר יהודה אב\"ד מעזא טשאטה."},{"i":3659,"n":"אלטמן, משה","b":"תלמיד ישיבת פאקש. פרסם מאמרים ב\"הפלפול\" - שאפראן תרצח."},{"i":3660,"n":"אלטמן, משה מסובאלק","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":3661,"n":"אלטמן, שבתי","f":"יהודה אלטמן","b":"מו\"צ בבודפסט-תר\"צ"},{"i":3662,"n":"אלטמן, שבתי מבודפשט","f":"יהודה ממעזא-טשאטה","bt":"תרנו","dt":"תרצו - כז אייר","dp":"בודפשט","b":"תלמיד הדעת סופר. חתן ר חיים טיטלבוים מהעדילא-מאדע. רב בבודפשט-תרץ."},{"i":3663,"n":"אלטמן, שלמה מקיקל","b":"אב\"ד קיקל. בזמן שהיה בוארשא-תרפא היה מעורכי \"שערי תורה\" - וארשא תרסג-תרצט ועורך הירחון המצורף לו \"בית מדרש\"."},{"i":3664,"n":"אלטמן, שמואל זנויל מפשמישל","bt":"תרכה","bp":"פשמישל","dt":"תרצט","b":"רב בהוסיאטין לצד חותנו, בזיוו\"ש חתן הגביר ר אלימלך וולף מסטרי-סאל. גבאי של האדמור מהוסיאטין=תרע."},{"i":3665,"n":"אלטמן, שמעון מסענדרא","b":"פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":3666,"n":"אלטמן, שמשון מפאקש","f":"יהודה מטשעט-מי יהודה","k":"בעל שבולת הנהר","bt":"תרנד","bp":"מעזא-טשאטה","dt":"תשד - יז תמוז","dp":"אושוויץ","b":"תלמיד הדעת סופר. חתן ר שמעון סופר מסענדרא, ועבר לשם. רב על מקום חותנו-תרעח - כשחותנו עבר לפאקש, רב בפאקש-תרצב על מקום חותנו. נספה בשואה. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד.","bk":[["שבולת הנהר",""]]},{"i":3667,"n":"אלטמן, שרגא צבי ממעזא-טשאטה","f":"יהודה ממעזא-טשאטה","k":"בעל עטרת צבי","bt":"תרנח","bp":"מעזא-טשאטה","dt":"תשד - כד סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר. חתן ר אשר אנשיל יונגרייז ממאזא-קיוועשד. רב במעזא-טשאטה-תרפג על מקום אביו. נספה בשואה."},{"i":3668,"n":"אלטער, אריה ליבש-דער","f":"ישעיה מקרקא","b":"רב בנסכיז-תקל\"ב"},{"i":3669,"n":"אלטפסט, אלעזר מזולקוא","b":"חתן ר אהרן לורברבוים מזולקוא. רב בזולקוא-תרצב. תשובה אליו ב\"צור יעקב\"."},{"i":3670,"n":"אלטקורן, אריש מסקול","b":"פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח."},{"i":3671,"n":"אלטקרן, אהרן (אריש) מסקאלא","b":"מחכמי סקאלא-תרצא, ממשתתפי \"הפרדס\"."},{"i":3672,"n":"אלטר יהודה אריה ליב בן אברהם מרדכי","bt":"1847","dt":"ה'תרסה 1905","bk":[["גערער מעשיות",""],["דברי שלום ואמת",""],["שפת אמת",""]]},{"i":3673,"n":"אלטרס, אהרן מדמשק","b":"גביר עשיר מחכמי דמשק בזמן ר משה מרדכי גלנטי ונזכר ב\"ברך משה\" שסייע להדפיסו-תקסט."},{"i":3674,"n":"אלטרס, דוד מונציה - דב\"ש","f":"שלמה","k":"בעל צוף דבש קטן","dt":"תעד - יג ניסן","b":"רב בונציה בזמן ר שלמה ניצה ור רפאל די סילוה - וחתם עמם בתשובת רבני ונציה בשו\"ת ארח לצדיק-תע, ועוד. חיבר \"צוף דבש קטן\", \"כללי הדקדוק\"."},{"i":3675,"n":"אלטרס, דוד מחלב וירושלים","b":"רב בארם צובא, עלה לירושלים-תקל. נזכר ב\"המעלות לשלמה\" לר רפאל שלמה לניאדו."},{"i":3676,"n":"אלטרס, יוסף מדמשק","b":"פייטן מגדולי חכמי דמשק-שס, רב בחלב. נזכר אצל ר ישראל נג'ארה. בנו - ר נסים."},{"i":3677,"n":"אלטרס, יעקב יצחק מחלב וצרפת","bt":"תקמו","bp":"חלב","dp":"אוקס-צרפת","b":"עלה בילדותו עם אביו לירושלים, התישב במרסיל-צרפת-תקסו והיה מראשי הקהלה. ניסה לעזור ליהודי רוסיה ע\"י הגירה לאלגיר (שהיתה בשליטת צרפת)."},{"i":3678,"n":"אלטרס, יעקב משה חי","k":"בעל זכרון ירושלים","bt":"תרכג","bp":"סרייבו","dt":"תרעט - ט אד\"ב","dp":"בלגרד","b":"תלמיד ר יהודה פינצ'י מסרייבו, עלה לירושלים עם הרופא שמואל סומבול, חזר לסרייבו-תרמד. שו\"ב בביחאג', דרשן, רב בבלגרד."},{"i":3679,"n":"אלטרס, משה","b":"נזכר בספר \"יצחק ירנן\" לקרובו ר רפאל יצחק אלטראס שהביא שיר ממנו בספרו ומכנהו \"הגביר המרומם\"."},{"i":3680,"n":"אלטרס, משה מונציה","k":"בעל ליברו די מאנטיני","b":"רב בונציה-של בזמן ר שמחה לוצטו. תרגם ללאדינו (באותיות לטיניות) את השלחן ערוך בשם \"ליברו די מאנטינימיינטו דיל אלמה\" שלוניקי שכח (מיועד לאנוסים). חתם עם רבני עירו בענין חלוקת אחים."},{"i":3681,"n":"אלטרס, נסים מדמשק","f":"יוסף מדמשק","b":"פייטן מחכמי דמשק-שנת ת'."},{"i":3682,"n":"אלטרס, סידי ן מספרד","dt":"ד'תרצב","dp":"ספרד","b":"רב בקשטיליה, עלה לארץ והתקרב לקראים ולמד אצל אבו אלפראג', חזר לספרד כרב קראי. אבי משפחת אלטראס."},{"i":3683,"n":"אלטרס, רפאל יצחק מחלב","k":"בעל יצחק ירנן","bp":"ארם צובא","b":"משורר מחכמי חלב, עלה לירושלים-תרה. היה חסוך בנים. חיבר \"יצחק ירנן\" ירושלים תרטו. בבית הכנסת איסטנבוליס היתה מצבה חקוקה לזכרו משנת תריא. יסד חברה \"ויעתר יצחק\" לתינוקות של בית רבן לאמירת תהלים ושירות באשמורת הבוקר."},{"i":3684,"n":"אלטרס, שבתי מחלב","b":"מחכמי חלב. נזכר ב\"המעלות לשלמה\" לר\"ש לניאדו."},{"i":3685,"n":"אלטרס, שלמה מונציה וירושלים","k":"בעל לקט האומר","dt":"תקנה","dp":"ירושלים","b":"רב בונציה בשנת תעא, עלה לירושלים. חיבר \"לקט האומר\". חתם על החרם נגד רמח\"ל. הסכים על \"רזא דיהודה\" לנחמיה חיון-מקורבו של ש\"ץ."},{"i":3686,"n":"אלטרץ, אברהם מסרייבו ווינה","b":"גביר מראשי קהלת סרייבו, עבר לוינה עם רבים מבני הקהלה-תקס בערך בזמן מרד הסרבים."},{"i":3687,"n":"אלטרץ, דוד מרודוסטו","b":"סוחר ברודוסטו-תקן בערך."},{"i":3688,"n":"אלטרץ, שלמה חיים מירקאדו","b":"בן אחותו של ר אלישע חביליו שהקדיש לו שיר בספרו \"שבעת בנינים\" - ליוורנו תקנג."},{"i":3689,"n":"אלטשודאיווער, אריה ליב","b":"תלמיד ר ברוך ממזבוז, ורושם תורתו."},{"i":3690,"n":"אלטשול, יהושע - הזקן","f":"משה אלטשול","b":"ממשפחה מגולי פרובנס. מחכמי דורו-תקם. בנו - ר עקיבא מסלוצק, ונכדו ר יהושע מטשאווס."},{"i":3691,"n":"אלטשול, יהושע מטשאווס - הנכד","f":"עקיבא מסלוצק","dt":"תרמד","b":"חתן ר מרדכי פינס מסלוצק. רב בטשאווס"},{"i":3692,"n":"אלטשול, יהושע מפרג","b":"מגדולי חכמי פרג-ש\"ב"},{"i":3693,"n":"אלטשול, משה","f":"יהושע אלטשול","b":"מגדולי חסידי פרובינצא,מגדולי חכמי פרג-ש\"נ"},{"i":3694,"n":"אלטשול, משה צבי מבאקו","f":"שלמה זלמן מטשאווס","b":"חתן ר שלמה מאנעוויץ מקסטיקאויטש. גביר תלמיד חכם בבאקו ומראשי הקהלה."},{"i":3695,"n":"אלטשול, עקיבא","f":"שלמה זלמן מטשאווס","b":"חתן ר שלום בר חשין מפעטרוביץ. גביר תלמיד חכם."},{"i":3696,"n":"אלטשול, עקיבא מסלוצק","f":"יהושע אלטשול","dt":"תרה - טז אייר","b":"נכד-אבי אמו ר שלמה בן עקיבא מבוריסוב. חתן נכדת בעל \"סדר הדורות\". ראש ישיבה בסלוצק."},{"i":3697,"n":"אלטשול, שלמה זלמן מטשאווס","f":"יהושע מטשאוס","bt":"תר","b":"חתן נכדתו ותלמידו של ר דוד טבלי ממינסק בעל \"בית דוד\" (שהיה גם גיסו - אשתו בזיוו\"ש של ר דוד היתה אחות ר שלמה זלמן). נכד ר עקיבא מסלוצק, ונכד-אבי אמו ר\"י מקאפוליא. ר\"מ בישיבת זקנו ר עקיבא בסלוצק-תרכב, לאחר שריפת הישיבה רב בטשאווס-פלך מוהילוב-תרכח לצד אביו ועל מקומו אחריו-תרמד. החזיק במגלת יוחסין - בכת\"י לתולדות משפחתו. נסמך מאת: ר יוסף דב סולוביציק, ר אליהו גולדברג מבוברויסק. בניו: ר משה צבי מבאקו, ר עקיבא, חתנו - ר משה טשארני מבאקו."},{"i":3698,"n":"אלטשול, שמואל שמלקא מירוסלב","b":"רב בירוסלב-תקנה."},{"i":3699,"n":"אלטשולר, אליעזר מרדכי","f":"צבי","k":"בעל פרשת מרדכי","bt":"1844","bp":"מאריאמפול","dt":"1921","dp":"סובאלק","b":"מחובבי ציון וממיסדי חברת \"יסוד המעלה\". עלה לארץ וניסה לארגן ישוב ליד טבריה אך נתקל בקשיים וחזר לעירו. הניח ספר זכרונות."},{"i":3700,"n":"אלטשולר, אריה ליב","b":"בנו - ר דוד."},{"i":3701,"n":"אלטשולר, דוד","f":"אריה ליב אלטשולר","k":"בעל המצודות","b":"ממגורשי פורטוגל שבאו לפרג והביאו אתם אבני בית הכנסת שבנאום שם, לכן קראום אלטשולר, נכד ר מנחם מאניש חיות מוילנא. מגדולי פרשני המקרא-תפו, ובנו - ר יחיאל מיכל השלים את פירושו."},{"i":3702,"n":"אלטשולר, דוד יצחק מירושלים","f":"משה יוסף","bt":"תרמה","bp":"באבר-רוסיה","b":"נכד ר דוד טביל ממינסק. תלמיד ישיבת מינסק, ועוד. עלה לארץ-תרנח ולמד בישיבת \"מאה שערים\" בירושלים אצל מהר\"ג הורביץ, ותלמיד דודו רש\"ח הורביץ מדוברובנה. מיסד ומנהל \"בית חינוך ילדים\" בירושלים, מנהל \"בתי פליטי רוסיה\", ועסקן צבור חרדי."},{"i":3703,"n":"אלטשולר, זאב וולף מלוצין","f":"דובער בן יוסף","k":"בעל שפת הים","dt":"תקסו","b":"רב בלוצין-תקמו. חיבר גם \"זבד טוב\". בנו - ר אליקים גצל מפנצעל הו\"ל את ספרו \"שפת הים\" תקעד. חתנו - ר אברהם מרגליות מטלז (ולפי אווצינסקי-קורלנד - המדובר בבנו - ר יהודה ליב בן אברהם מטלז)."},{"i":3704,"n":"אלטשולר, יהודה אהרן משה","f":"אברהם חנוך","k":"בעל ויחל משה","b":"מקובל, רב בקרונוי(=קרימנויא)-שעג. חיבר גם \"בחורי חמד\" והוא ביאור על ספר המכלול (לדעת שפתי ישנים המחבר הוא ר שבתי סופר)."},{"i":3705,"n":"אלטשולר, יהושע מארץ ישראל","f":"נח","b":"מחכמי ארץ ישראל-תקמט, אחיו ר שלום שכנא-חתנו של ר שניאור זלמן מלאדי ואביו של ה\"צמח צדק\". יתכן והוא שהו\"ל \"דרכי צדק\" - לבוב תקנו."},{"i":3706,"n":"אלטשולר, יחיאל הלל מיברוב","f":"דוד","k":"בעל המצודות","b":"רב ביאברוב-תקכ, הגיע לאיטליה. מפרש המקרא, השלים את פירוש אביו לתנ\"ך - \"מצודת דוד\" ו\"מצודת ציון\"."},{"i":3707,"n":"אלטשולר, יצחק הכהן מסימיאטיץ","b":"רב בסימיאטיץ"},{"i":3708,"n":"אלטשולר, מאיר יהושע מהאלוסק","b":"שו\"ב בהאלוסק, חתם-תרעד על אישור נישואין."},{"i":3709,"n":"אלטשולר, מרדכי","f":"יחיאל הלל אלטשולר","b":"רב בחאדרוב-תק\"פ"},{"i":3710,"n":"אלטשולר, עזרא מואינוטה","f":"יהודה ליב","k":"בעל תיקון האדם","r":"אב\"ד ואיינוטא שבליטא וקודם לכן בקאלטינאן","bt":"תריט","bp":"מיר","dt":"תרצח - ח אייר","dp":"כפר סבא","b":"תלמיד ישיבות מיר, וולוזין, ואיישישוק, ותלמיד ר יוסף מזאבלודוב. רב בקולטיניאן--פלך קובנא-תרמד, ואינוטה(=ויינוטה)-פלך קובנא-תרסא. עלה לארץ-תרצא והתיישב בכפר סבא. חיבר גם \"תקנות עזרא\", ועוד. חיבר מאמרים ב\"הבאר\" - זאמושץ-וארשא תרפד, \"דברי תבונה\" - קובנה תרף, \"חכמי ליטא\" - קאלואריא תרמה, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"עמק הלכה\" - באטארקס תרפא, \"שערי ציון\" - ירושלים תרפא, \"תבונה\" - קובנא תרפא.","bk":[["תקון דרך החיים - הוספות לספר דרך החיים",""],["תקון האדם - מוסר",""],["תקון הצבא - ספר הצבא לרבינו זרחיה הלוי",""],["תקנת ארצות - תוספתא ה' חילוקי דינים בין בני בבל לבני ארץ ישראל",""],["תקנת השבים (כת\"י)",""],["תקנת עזרא - מעילה ש\"ס ורמב\"ם",""]]},{"i":3711,"n":"אלטשולר, שלמה זלמן","f":"שמאי הלל","k":"בעל סוכת שלמה","bt":"תרז","b":"נכד-אבי אביו ר בנימין מדובראיינא, ונכד-אבי אמו ר נחמן מדפאהאסט-אחיו של ר חיים מוולוזין. רב בקניזין-ליד מאהילוי-תר\"מ, באבר-פלך מוהילוב-תרמט. חיבר \"סוכת שלמה\" - בכת\"י."},{"i":3712,"n":"אלטשטט, אליהו מבורשטין","f":"שלמה","bt":"תק","dt":"תקעה","b":"מחכמי בורשטין, יסד חברות גמ\"ח במקומות שונים. פנקס תקנות של החברה נכתב בשנת תקעג עם הסכמות גדולי הדור."},{"i":3713,"n":"אלטשטט, אלימלך מפרמישלא","f":"זאב","k":"בעל פרפראות לחכמה","bt":"תקע","dt":"תרן","b":"מחכמי פרמישלא, תלמיד ר צבי אלימלך מדינוב. חיבר \"פרפראות לחכמה\" פרזעמישל תרמח."},{"i":3714,"n":"אלטשטט, אליעזר ליפמן מברוד","f":"יהודה ליב סגל","k":"בעל טל אורות","bt":"תפ","dt":"תקמא","b":"מחכמי ברודי, דרשן בבית המדרש של בן דודו ר יהושע יעציס. חיבר \"טל אורות\" וינה תקעב, \"בית שלמה\" זולקווא תקס, ועוד."},{"i":3715,"n":"אלטשטט, אליעזר מדולינה","f":"שלמה","bt":"תקן","dt":"תרכב","dp":"קולומיאה","b":"מחכמי דולינה, מתלמידי החוזה מלובלין."},{"i":3716,"n":"אלטשטט, אליעזר פישל מציעשינוב","f":"יצחק","k":"בעל מדרש לפירושים","bt":"תק","bp":"סטריזוב","dt":"תקעב","dp":"ברודי","b":"רב בציעשינוב, מתנגד לחסידות, רב בברודי. בנו ר יחיאל מיכל היה אב\"ד ביאלא בליטא. חיבר \"עולם הגדול בשם \"מדרש לפירושים\" זולקווא תקס, \"עולם אחד\" זולקווא תקסה, ועוד."},{"i":3717,"n":"אלטשטט, חיים אריה מקרופיטש","bt":"תרנג או תרמה","dt":"תשג","b":"מצאצאי ר לוי יצחק מברדיטשוב. חסיד צ'ורטקוב, אב\"ד קרופיטש(=קראפיץ)-תרפח על מקום חותנו - ר חיים ברוך הוכברג - שעבר לניזנוב, סטניסלב. נספה בשואה."},{"i":3718,"n":"אליא","f":"אליעזר","b":"מחכמי קושטא, דיין פוסק"},{"i":3719,"n":"אליאב הכהן","k":"מגדולי בעלי התוספות","b":"רב במיידויינה-שנת נ\"ז"},{"i":3720,"n":"אליאב הכהן ממודנא","b":"מחכמי איטליה-ה'א. נזכר בתוספות טוך, ובשיטה מקובצת, ועוד."},{"i":3721,"n":"אליאב מתורכיה","f":"מתתיה","b":"מדקדק מחכמי תורכיה. נזכר בספרי הדקדוק הקדמונים. חיבר פיוטים."},{"i":3722,"n":"אליאך, אברהם אשר מטבריה וסטולי","f":"שלמה יוסף מסטולין","b":"יצא מטבריה לסטולין ללמוד עם ר ישראל \"הינוקא\" מסטולין - וישב שם 13 שנה."},{"i":3723,"n":"אליאך, שלמה יוסף מירושלים","f":"אברהם אשר","bt":"תריב","bp":"טבריה","b":"סופר בית התבשיל בירושלים."},{"i":3724,"n":"אליאך, שלמה יוסף מסטולין","f":"יצחק","dt":"תרך - יא אייר","b":"בנן אחיו של ר אהרן הגדול מקרלין. תלמיד ר אשר מסטולין. עלה לארץ והשתקע בטבריה. בנו ר אברהם אשר."},{"i":3725,"n":"אליאל הלוי מתימן","f":"נדרגל","b":"מחכמי תימן. חיבר פירוש בערבית על פירוש הרמב\"ם לר יחיא בן סולימן אל סדאלי."},{"i":3726,"n":"אליאס כהן, חיימאקי משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":3727,"n":"אליאש, אברהם שלמה","f":"אליהו מטאלדאש","bt":"תרלד-ה","dt":"תרצ - כז טבת","b":"תלמיד בעל \"ערוגת הבשם\" בחוסט שהזכירו בספרו. חתן ר יצחק יוסף הכהן מסאמוש-אויוואר. דיין בסאמוש-אויוואד-תרנה, רב על מקום חותנו-תרפא. היה בביה\"ד שדן במחלוקת בענין רבנות סטמר. רוב כתביו אבדו בשואה."},{"i":3728,"n":"אליאש, אליהו","f":"יעקב מפיאטרא","bt":"תקצה","bp":"פיאטרא","dt":"תרסו - כט ניסן","dp":"ירושלים","b":"מצאצאי ר אברהם אחי הגר\"א. שו\"ב ומורה בטאלדאש-תרל, עלה לירושלים-תרסה. חיבר \"אהל יעקב\" - חדושים והגהות לש\"ס בכת\"י. בניו ר חיים שמואל חתן ר משה מערדיסנזשארץ, ר אברהם שלמה חתן ר יצחק יוסף מסאמוש אויוואר ורב שם, ר יוסף אשר."},{"i":3729,"n":"אליאש, בנימין משלוניקי","b":"ראש הישיבה \"תלמוד תורה\" בשלוניקי-שנות ה-ש'. גיסו של הגביר ר משה עטייה."},{"i":3730,"n":"אליאש, חיים שמואל","f":"אליהו מטאלדאש","bt":"תרלב","bp":"טאלדאש","dt":"תרסא - בערך","b":"חתן ר משה שטיין מערדא-סענזשארץ בעל \"באר משה\". רב בגימש-בוק-מחוז צ'יק. נזכר ב\"דור רביעי\"."},{"i":3731,"n":"אליאש, יעקב שמואל מסאמוש","f":"אברהם שלמה מסאמוש","bt":"תרס","dt":"תשה - ה ניסן","b":"תלמיד ר אליעזר דוד גרינוולד מסטמר, ור שאול בראך מקרולה. חתן ר חיים יעקב הכהן בינדר מזענטא. רב בכפר סיק ליד סאמוש-אויוואר, רב בסאמוש-אויוואר על מקום אביו-תרץ. נספה בשואה - בצעדת המות מאושוויץ."},{"i":3732,"n":"אליאש, יצחק משלוניקי","f":"משה","dt":"שפא - ה אב","dp":"שלוניקי","b":"מחכמי שלוניקי, נזכר אצל ר שלמה הלוי הבחור."},{"i":3733,"n":"אליאש, יקותיאל זלמן מולנא","f":"צבי הירש מוילנא","dt":"תר - ג כסלו","dp":"וילנא","b":"נכד ר אליהו פעסעלעס. חתן הגביר ר איסר לוריא ממוהליב. נכד ר אברהם יקותיאל זלמן פרלעס מברוד, ונינו של ר חיים רפפורט מטרנופול. גביר בוילנא. נקבר לצד ר יהושע בן שלום מוילנא."},{"i":3734,"n":"אליאש, מאיר משלוניקי","b":"תלמיד ר שמואל גאון משלוניקי."},{"i":3735,"n":"אליאש, מרדכי צבי הירש מוילנא","f":"יעקב אליאש","b":"בן אחות וחתן ר יצחק אליהו לנדא מוילנא."},{"i":3736,"n":"אליאש, משה מטרנסילבניה","f":"אברהם שלמה מסאמוש","bt":"תרעא","dt":"תש..","b":"תלמיד ר שמואל דוד אונגר מטירנוי, ור יהודה רוזנר מסעקעיהיד. חתן ר בנימין זאב שוורץ ממאנשטור. רב בכפר סיק (על מקום אחיו - ר יעקב שמואל - שעבר לסאמוש). סירב לרבנות מאנאשטור. נספה בשואה."},{"i":3737,"n":"אליאש, משה משלוניקי","b":"סופר חברת \"תלמוד תורה\" בשלוניקי-שנות ה-ש'."},{"i":3738,"n":"אליאש, משה משלוניקי - א","b":"דיין בשלוניקי-שיט."},{"i":3739,"n":"אליאש, משה משלוניקי - ב","f":"יצחק - אולי","dt":"שצב - ה תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3740,"n":"אליאשברג, אברהם צבי פנחס מטיקט","f":"יצחק איזיק","bt":"תרכג-ד","bp":"נובידבור פלך גרודנא","dt":"תשד","dp":"ירושלים","b":"מצאצאי ר איזיק אליאשברג מאיוויניץ, נכד ר אברהם מבאקשט. תלמיד ישיבות גרודנא, איישישוק, וולוזין. חתן נכדת ר פיבל קרעשעס מביאליסטוק. תלמיד ר נחום מגרודנא, ר יצחק מדוברוונא, ר משה מגרודנא, ישיבת וולוזין. רב בקאפיצוב(=קאפציאויע, קופצאווה)-תרמח, סערהיי(=סארהיי)-פלך סובאלק-תרסא, טיקטין-פלך לומזה-תרסט, עלה לארץ-תרפט. נסמך מאת: הנצי\"ב, ר שמואל מוהליבר מביאליסטוק. בנו: ר יצחק אריה בעל \"רגשי יצחק\". חתנו - ר יוסף פינס בן ר מרדכי מטיקטין."},{"i":3741,"n":"אליאשברג, אליהו מפינסק וליבאוי","f":"שמואל","b":"מצאצאי ר שמואל-אב\"ד אחרון בוילנא. גביר מחכמי פינסק, עבר לליבאוי, פעיל בעניני צבור, ופעל אצל השלטונות לטובת יהודי ליבאוי, ולטובת הגולים שגורשו משם ויצאו לאמריקה, וגייס לעזרתם את הברון הירש."},{"i":3742,"n":"אליאשברג, אליעזר ליפא מאיוועני","b":"חתן ר שמואל-אב\"ד אחרון בוילנא. גביר מחכמי איוועניץ, ומגדולי התומכים בישיבת וולוזין הסמוכה. (ר יצחק מוולוזין נפטר כששהה בבית המשפחה בביקורו שם ונקבר שם). בנו - ר שמואל מאיוועניץ."},{"i":3743,"n":"אליאשברג, השל מסמילוביץ","b":"רב בסמילוביטש. בנו - ר פנחס, חתנו - ר שלמה גרודזנסקי."},{"i":3744,"n":"אליאשברג, ידידיה ליפמן","b":"חתן ר שאול קצנלנבוגן מוילנא. בנו - ר שאול. (ובמקום אחר - חתן ר שמואל אב\"ד וילנא)."},{"i":3745,"n":"אליאשברג, יהודה בצלאל","f":"זאב וולף","k":"בעל מרפא לעם","bt":"תקס","dt":"תרח - כג תשרי","dp":"מינסק","b":"אחיו של ר יוסף אליהו מוילנא. מחכמי איבנוביץ ונאמן משפחת אליאשברג בעסקיהם, התגורר גם במינסק. תרגם ספר רפואה בשם \"מרפא לעם\", חיבר גם \"תמים דעים\" וילנא תרב. לדעת איזנשטט-מינסק הוא הסופר המפורסם - לבנדה (אבל שם אביו של לבנדה היה יוסף ולא זאב). בנו - ר משה אליהו ונכדו ר בצלאל ממינסק."},{"i":3746,"n":"אליאשברג, יונתן מוילקוביסק","f":"מרדכי מבויסק-תרומת י","k":"בעל דרכי הוראה","bt":"תריא","bp":"קובנה","dt":"תרנט - ח כסלו","b":"תלמיד ישיבת סלובודקא. רב בפומפיאן-תרלה, מאריאמפול-תרלז, וולקוביסק(=וילקוביסק)-תרמח. פרסם מאמרים בעתוני התקופה על חיבת ציון. חיבר גם \"שביל הזהב\". הו\"ל ספר אביו \"תרומת יד\" עם \"קסת יהונתן\" ממנו. חתנו - ר אלחנן הכהן מפאשואמין-פלך קובנא."},{"i":3747,"n":"אליאשברג, יוסף אליהו מוילנא","f":"זאב וולף מקומען","k":"ר יוסף אליהו לאפפ","bt":"תקנח","bp":"איוונויץ","dt":"תרמא - כז אב","dp":"וילנא","b":"אחיו של ר יהודה בצלאל בעל \"מרפא לעם\". נכד ר יוסף אליהו בן ר אברהם חסיד בן ר חיים זאלודקער. חתן הגביר ר יצחק בר הכהן לאפ מוילנא (ועל שם חותנו כינוייו). גבאי צ\"ג ופרנס, הקדיש בימ\"ד. גבאי ישיבת מייליס בוילנא. חתם על כתב התמנות ר ישראל סלנטר לראש הישיבה, על מקום ר מרדכי מלצר. סייע למדפיסי ש\"ס וילנא - אחרי השריפה תרב. מחתניו: ר מאיר גינצבורג, ר מתתיהו שטרשון."},{"i":3748,"n":"אליאשברג, יוסף מצייקישוק","dp":"ירושלים","b":"רב בצייקישוק, רומשישוק - לפני תרכו. בנו ר מרדכי מבויסק."},{"i":3749,"n":"אליאשברג, יצחק איזיק מאיוועניץ","dt":"תקפא - י שבט","b":"חתן ר אהרן ישעיהו בקשטר. נספד עם ר חיים מוולוזין ב\"שמע יעקב\". חתנו - ר אברהם פרנס בן ר חיים נחמן פרנס מוילנא."},{"i":3750,"n":"אליאשברג, ליפמן ממינסק","b":"גביר מחכמי מינסק-תרן."},{"i":3751,"n":"אליאשברג, מרדכי מז'אזמיר ובויס","f":"יוסף מצייקישוק","k":"בעל תרומת יד","bt":"תקעז","bp":"צייקישוק-ליטא","dt":"תרן - יח כסלו","dp":"בויסק","b":"תלמיד ישיבת וולוזין ולמד בחברותא עם הנצי\"ב (בגיל 14). מחכמי קובנא ומיודד עם ר ליב מקובנא. בזיוו\"ש חתן ר יהודה ליב קרליץ ממיכאלשוק(=מיכאילשוק). רב בז'אזמיר-תריא, בויסק-תרכא. התקרב לתנועת חיבת ציון בהשפעת ר צבי קלישר, התיר לעבוד בשנת השמיטה והיה מחלוקת על כך. חיבר גם \"שביל הזהב\", פרסם מאמרים ב\"כבוד הלבנון\". בנו ר יונתן מוילקוביסק בעל \"דרכי הוראה\", חתנו - ר אלחנן הכהן סלנטר מפאשואמין-פלך קובנא. (באוצר הרבנים תאריך פטירתו - תרנה - ח כסלו)"},{"i":3752,"n":"אליאשברג, פנחס מריגה","f":"השל מסמילוביץ","k":"בעל די סדרה","dt":"תש..","b":"רב בכמה קהלות ברוסיה ובהם סאמסשיסלוב, עבר לריגה.הו\"ל ספרים שונים, ועלונים לפרשת שבוע בשם \"די סדרה\". נספה בשואה."},{"i":3753,"n":"אליאשברג, שמואל יונה ממינסק","b":"גביר מחכמי מינסק-תרן."},{"i":3754,"n":"אליאשברג, שמואל מאיוועניץ","f":"אליעזר (ידידיה) ליפא","b":"נכד(-אבי אמו) ר שמואל-אב\"ד אחרון בוילנא. חתן ר שמואל חיים שבתיל'ס לנדא מוילנא. גביר מחכמי איוועניץ, ומגדולי התומכים (כאביו לפניו) בישיבת וולוזין הסמוכה. בנו - הגביר ר אליהו מפינסק וליבאוי."},{"i":3755,"n":"אליאשויץ, חיים שלמה זלמן","f":"בצלאל מוילנא","k":"חזא\"ל","dt":"תרלז - יא אייר","dp":"לונדון","b":"מחכמי וילנא. חיבר עם חברו איזיק מאיר דיק ספר \"האורח\" על בקורו של מונטיפיורי בוילנא. פרסם מאמרים ב\"המגיד\" בשם \"חזאל\". עבר לאנגליה וסייע לר נתן אדלר בהגהת ספרו \"נתינה לגר\". הו\"ל \"תלמוד לשון עברי\" עם הערות ממנו. עסק גם בהפצת ספרים. חתנו - הפרופ' הרמן שפירא."},{"i":3756,"n":"אליאשזון, יהושע השל מווילקי","f":"בנדיט מקרוז'","bt":"תקנט","dt":"תרלד - כח אדר","b":"אחיו של ר יצחק איצה'לה קראזר. רב בשאקי, זעזמיר(=ז'אזמיר) על מקום ר ידידיה גינצבורג, יאנובה, וילקי, שווינציאן, סייני. כונה \"ראש הברזל\". בתחילה היה ממתנגדי \"בית המוסר\" של ר ישראל סלנטר מחשש ייסוד כת חדשה בישראל."},{"i":3757,"n":"אליגרי, אברהם מקושטא","f":"שלמה","k":"בעל לב שמח","bt":"של","bp":"קושטא","dt":"תיב","b":"פוסק, מרבני קושטא, חיבר \"לב שמח\" על הרמב\"ם, ושו\"ת באותו שם. היה במחלוקת עם ר\"ח אלפנדרי ותשובותיהם נדפסו ב\"מגיד מראשית\"."},{"i":3758,"n":"אליד ן, חלפתא ממרוקו ואלגיר","f":"לוי","bt":"קצ - בערך","dt":"רס - בערך","b":"חתן ר אהרן ן שמחון מדרעא ותלמסאן. רב בדרע-מרוקו, ויצא עם אחיו ר יוסף לעלות לארץ, ובהיותם בווהראן בקשו בר צמח דוראן שיתיר את נדרם, ושאר בני חבורתם ובהם - ר אהרן בן מלכה, ר שמואל בן אבו אלטבול - פנו באותו הענין לר אפרים שוראקי מתלמסאן."},{"i":3759,"n":"אליד ן, יוסף ממרוקו ואלגיר","f":"לוי","b":"מחכמי פאס-שנות ה-ר'-ש'. יצא עם אחיו ר חלפתא מדרעא-מרוקו לעלות לארץ, ובהיותם בווהראן בקשו בר צמח דוראן שיתיר את נדרם, ושאר בני חבורתם פנו באותו הענין לר אפרים שוראקי מתלמסאן. (לפי מלכי רבנן הגיע לארץ)."},{"i":3760,"n":"אליד ן, לוי מדרעא-מרוקו","b":"רב בדרעא-מרוקו בשנות ה-ר. חיבר ספר על עיבור שנים, וקונטרס בדיני טרפות. בניו ר חלפתי ור יוסף שניסו לעלות לארץ."},{"i":3761,"n":"אלידו, מרדכי מירושלים","dt":"תקעו - כא אדר","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":3762,"n":"אליה ן, גבריאל","b":"מחכמי שלוניקי הקדומים. בנו - ר שבתי - רב בקושטא-שכט."},{"i":3763,"n":"אליה ן, שבתי מקושטא","f":"גבריאל משלוניקי","b":"רב בקושטא. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":3764,"n":"אליה, פנחס מאיטליה","f":"צמח","b":"רב במנטובה בזמן מהרשד\"ם. נזכר ב\"פחד יצחק\"."},{"i":3765,"n":"אליהו","b":"מבעלי התוספות-ד'תתק\"ס"},{"i":3766,"n":"אליהו","k":"בעל טוב טעם","b":"מגדולי חכמי הדקדוק-ר\"צ"},{"i":3767,"n":"אליהו"},{"i":3768,"n":"אליהו","b":"הביא לדפוס ספר המקנה לר יוסף אופניאל וחיבר לו הקדמה - נדפס בתוך \"מזרח ומערב\". תלמיד ר יום טוב מיוני."},{"i":3769,"n":"אליהו","f":"אליעזר","b":"חיבר פירוש לתורה-ה'א - בכת\"י"},{"i":3770,"n":"אליהו","f":"משלם הקדוש","b":"כנראה אחיו של ר נתן מנרבונא. מתורתו ב\"יוסף המקנא\"."},{"i":3771,"n":"אליהו","f":"צדוק","b":"פייטן. חיבר פיוט לסוכות \"אתן רוממות\" ונמצא במחזור ישן."},{"i":3772,"n":"אליהו","f":"יצחק","b":"פייטן. חיבר מערבית לסוכות \"איומתך אדרת\" - וחתם שמו, ועוד."},{"i":3773,"n":"אליהו","f":"אליהו","b":"תשובה אליו מרגמ\"ה-ד'תת."},{"i":3774,"n":"אליהו","f":"יקר","b":"פייטן, חיבר סליחה לי\"ז בתמוז \"אפפו עלינו רעות ותקפו\"."},{"i":3775,"n":"אליהו (אשכנזי) מלובלין וחברון","f":"שמואל מלובלין","k":"בעל יד אליהו","dt":"תפ","dp":"חברון","b":"אב\"ד בביאלי, בריסק, איבשיץ, עלה לחברון-תס, החיד\"א מספר ששמע עליו שהיה מופלג בבקיאותו ובעל הנהגות. חיבר \"יד אליהו\" קושטא תצט - ובספרו מביא מחדושי חכמי לובלין. בנו ר משה חיבר \"פרחי שושנים\" ויש מיחסים הספר לאביו."},{"i":3776,"n":"אליהו אריה מטלוסט","b":"רב בטלוסט-תק\"ס"},{"i":3777,"n":"אליהו אריה מירושלים","b":"שליח ירושלים במוסול לפני שנת תקכח, בשנת תקמא היה בשליחות בבגדד."},{"i":3778,"n":"אליהו בן טיפא מירושלים","b":"מחכמי ירושלים, מוזכר בחרבות ירושלים כאחד האסורים בזמן אבן פארוך בשנת שפה, יחד עמו נאסרו 15 מראשי העדה ובראשם השלה"},{"i":3779,"n":"אליהו בן יהודה אהרן מחלם","bt":"1520","dt":"ה'שנ 1590","bk":[["תולדות אדם",""]]},{"i":3780,"n":"אליהו בן שלמה זלמן (הגר\"א)","bt":"1720","dt":"ה'תקנז 1797","bk":[["אגרת הגר\"א",""],["אדרת אליהו",""],["איל משולש",""],["אלי' רבא",""],["אליהו רבא",""],["אמרי נועם",""],["אשי ישראל",""],["באור אגדות בבא קמא",""],["באורי אגדות",""],["באורי הגר\"א",""],["ביאור",""],["ביאור הגר\"א",""],["ביאור וגם הגהות",""],["ביאור מהגר\"א",""],["דברי אליהו",""],["דקדוק אליהו",""],["חידושי הלכות",""],["חידושי וביאורי הגר\"א",""],["יד אליהו",""],["יהל אור",""],["ילקוט אבנים",""],["ילקוט שערים",""],["מאורות הגר\"א",""],["מגילת אסתר עם פירוש הגר\"א",""],["מגלת אסתר עם פירוש הגר\"א",""],["מגלת רות",""],["מכתב אלי'",""],["מנחת אליהו",""],["מסעות ישראל",""],["מעיל צדקה",""],["מרכבת אליהו",""],["סדר אלי'",""],["סדר עולם רבה וזוטא",""],["סידור הגר\"א",""],["ספר יונה עם פירוש הגר'א",""],["ספר יצירה",""],["ספרא דצניעותא",""],["ספרי",""],["פירוש",""],["פסקי הגר\"א",""],["פסקי הגר\"א חלק א",""],["פסקי הגרא (הגר\"א)",""],["צורת הארץ לגבולותיה",""],["קול אליהו",""],["שדה אליהו",""],["שנות אליהו",""],["תבנית הבית השלישי",""]]},{"i":3781,"n":"אליהו בנימין מאזמיר","dt":"תקלא - א תמוז","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":3782,"n":"אליהו בנימין מירושלים","b":"מו\"צ במינסק-תר\"י"},{"i":3783,"n":"אליהו בעל שם מאיטליה","b":"מחכמי איטליה. בשליחות במצרים-קעט יחד עם ר בנימין בן אלחנן - כדי לברר אצל הנגיד במצרים האם אמת בשמועות שמלכי עשרת השבטים כבר יצאו להילחם במלכי האומות וקרובה הגאולה וכו'."},{"i":3784,"n":"אליהו בעל שם מדילאציץ","b":"חיבר ביאור למסכת אבות. בנו - ר אברהם בעל שם מדילאציץ."},{"i":3785,"n":"אליהו בעל שם מחעלם","f":"אהרן","r":"רב בחעלם","dt":"שנ","b":"תלמיד המהרש\"ל. מלומד בניסים, רב בחעלמא-שכ. נזכר בתשובות מהרש\"ל. נכדו ר יואל בעל \"תולדות אדם\", ונכדו ר אליהו-זקנו של ה\"חכם צבי\" ונזכר בספרו ובספר בנו היעב\"ץ - על כך שברא גולם וכו'. היה מחלוקת בינו לבין קרובו בעל \"שארית יוסף\" בענין כתובת אלמנת אחיו של ר אליהו. (יש שטעו ובלבלו בינו לבין ר אליהו לואנץ בעל שם).","bk":[["תולדות אדם - תפילות קמיעות וסגולות",""]]},{"i":3786,"n":"אליהו בער מירושלים","f":"יצחק איזיק","b":"נזכר במכתב מאת ר יוסף זונדל סלנט-תרכד."},{"i":3787,"n":"אליהו גאון","k":"בעל אזהרות","b":"גיסו של רב האי גאון,מגדולי הראשונים,מרביץ תורה במדינת מאנש-ד'תת\"כ"},{"i":3788,"n":"אליהו דב משוואבאך","b":"גביר בשוואבאך. נכד(בן בתו) ר אברהם ברוידא בעל \"אשל אברהם\". חתן ר יוסף האמיל-בנה של גליקל מהאמיל. חתנו - ר נח חיים צבי ברלין מאה\"ו."},{"i":3789,"n":"אליהו דיינא מאיטליה","b":"דיין באיטליה-רן. תשובות ממנו בספרי חכמי איטליה, היה בין החולקים על ר\"א מינצי ונזכר ב\"דעת קדושים\"."},{"i":3790,"n":"אליהו הבבלי","b":"נזכר ב\"מאירת עינים\" לר יצחק בן שמואל מעכו - שרב פלטוי כתב לו עליו."},{"i":3791,"n":"אליהו הזקן מפריס","f":"מנחם","b":"אחיו של ר יצחק, ור יקותיאל. תלמיד רגמ\"ה ובעל אחותו של רב האי גאון (כך בתשובות המהרש\"ל). מבעלי התוספות, חברו של ר שמעון הגדול, חיבר אזהרות ופיוטים ובהם \"אמת יהגה חכי\" - בתוס' נאמר \"כי היה המנהג בכל צרפת לומר אזהרותיו\", חיבר גם \"סדר המערכה\", ו\"סדר המעמדות\" שנמצא בסידורים - ושכנגדו יצא יעב\"ץ (שלא ידע מי המחבר והשיג עליו). ב\"אור זרוע\" מביא שהתיר להתפלל \"קרובות\" בג' ברכות ראשונות."},{"i":3792,"n":"אליהו הכהן גאון ירושלים","f":"שלמה בן יוסף גאון","dt":"ד'תתמד - כסלו","dp":"צור","b":"גאון ארץ ישראל. דיין אצל רב שלמה בן יהודה ריגי מירושלים, גאון עם אחיו רב יוסף גאון, וגאון ישיבת ירושלים אחר פטירת אחיו-ד'תתכב ראש ישיבת רמלה, עבר עם הישיבה לצור-ד'תתמג. היה מחלוקת כנגדו מצד דניאל בן עזריה מבבל. עבר לחיפה ורצה לחדש את הסמיכה ואת קידוש החודש ע\"פ הראיה (יש שאינם סוברים שרצה לחדש את הסמיכה). שאלה ממנו מאת חכמי מגנצא ובהם ר משלם בן משה בן איתיאל - האם לומר השיאנו בתפילת ראש השנה. בניו: ר אביתר בעל \"מגילת אביתר\", רב שלמה גאון ישיבת צור ודמשק."},{"i":3793,"n":"אליהו הכהן גאון ירושלים","b":"ראש ישיבת ירושלים-ד'תשע. ויתכן שהוא ר אליהו הכהן מסרמיד שעבר לירושלים."},{"i":3794,"n":"אליהו הכהן גאון מסרמיד","f":"אברהם","b":"אב\"ד בסרמיד-ד'תשפ - בסוף תקופת רב האי גאון, ורב שלמה על מקומו אחריו. קיבל רשות גאוני בבל ללמד חכמים מארץ אדום(=אשכנז ואיטליה) את תורת בבל. היה עם בנו ר עמרם במצרים ונתאכסן אצל ר יעקב בן רב יוסף."},{"i":3795,"n":"אליהו הכהן גאון מרמלה","f":"שלמה","b":"אב\"ד ברמלה-ד'תתי\"ג, ראש ישיבת ארץ ישראל-ד'תתכ\"ב, גלה לצור-ד'תתל\"א, ראש הישיבה שם עד ד'תתמ\"ג"},{"i":3796,"n":"אליהו הכהן מאזמיר ס\"ט","k":"בעל מנחת אליהו","bp":"אזמיר","dt":"תפט - ה אד\"ב","dp":"אזמיר","b":"מחכמי איזמיר-תקע."},{"i":3797,"n":"אליהו הכהן מאלטונא","f":"דוד מאלטונא","dt":"תיג","dp":"אלטונא","b":"מחכמי אלטונא, נפטר בחיי אביו-הראב\"ד."},{"i":3798,"n":"אליהו הכהן מאשכנז","b":"מחכמי אשכנז והובא ממנו בתוס' על התורה. אחיינו של ר משה הכהן ממגנצא. נזכר בהגהה לספר יראים לר בנימין בן אברהם - שהיה כנראה תלמידו של ר אליהו."},{"i":3799,"n":"אליהו הכהן מלונדון","b":"ראש הרבנים באנגליה מטעם המלכות-ה'ג על מקום ר אהרן בן יוסף מיורק, ר חיים בן משה על מקומו אחריו. נזכר בתעודות מערכאות ישנים."},{"i":3800,"n":"אליהו הכהן מליוורנו","f":"משה","b":"מחכמי ליוורנו, דיין"},{"i":3801,"n":"אליהו הכהן ממצרים","f":"אביתר","b":"התישב במצרים-ד'תתעא, העתיק חלק מפירוש ר חננאל על הש\"ס. מכתב אליו מעבדיו באשקלון."},{"i":3802,"n":"אליהו הכהן ממרוקו","dt":"תרעד - ו אלול","dp":"קולמב-מרוקו","b":"מחכמי תאפילאלת, בדרכו לארץ נפטר בקולומב-מרוקו. בנו - ר מסעוד."},{"i":3803,"n":"אליהו הכהן ממרוקו","b":"רב בפאס-תרם."},{"i":3804,"n":"אליהו הכהן מספרד","f":"משה בן נסים","b":"מחכמי ספרד-ה'ן, מעתיק ומתרגם. תרגם מערבית \"מגילת העופר\""},{"i":3805,"n":"אליהו הכהן משוואקשנא","f":"אליקים גצל","dt":"תרלט","dp":"ירושלים","b":"עלה לירושלים"},{"i":3806,"n":"אליהו הכהן משלוניקי","f":"שלמה","b":"דיין בשלוניקי-תנח, סופר ביה\"ד של ר שלמה אמריליו."},{"i":3807,"n":"אליהו הכהן משלוניקי ולאריסה","f":"יהושע","k":"ג'יליבי אליהו","dt":"תרד","dp":"שלוניקי","b":"גביר מחכמי לאריסה, התישב בשלוניקי. הקים ישיבה בשם \"לה בוייאנה\" - ישיבת ג'יליבי אליהו כהן. סייע בהדפסת כמה מספרי ר חיים פלאג'י ועוד - אחיו ר משה השתתף עמו בכמה מפעולותיו."},{"i":3808,"n":"אליהו הכהן צלבי מאנאטולי","k":"בעל אזהרות","b":"פייטן מחכמי יון. פיוט ממנו \"אזהרות לחג שבועות\" ונזכר אצל ר מנחם בן תמר, ועוד."},{"i":3809,"n":"אליהו הלוי","f":"אליקים גץ מקרזמיר","b":"חתן ר מרדכי הכהן מאה\"ו."},{"i":3810,"n":"אליהו הלוי מאזמיר","dt":"תקי","dp":"ירושלים","b":"גבאי ח\"ק באזמיר. עלה לירושלים. סייע בהדפסת \"בתי כהונה\" ו\"כנסת הגדולה\". נספד ב\"קול יעקב\". בניו: ר רפאל בעל \"קול בן לוי\", ואחר פטירת בנו נולד לו בן ונקרא גם הוא רפאל."},{"i":3811,"n":"אליהו הלוי מאזמיר וירושלים","f":"חיים ג'יליבי בכור","bt":"תרכב","bp":"אזמיר","b":"מחכמי אזמיר ובקי בתכונה, עלה לירושלים-תרצד."},{"i":3812,"n":"אליהו הלוי מאלגיר","bt":"תקסד","dt":"תרם - בערך","b":"רב באלגיר, עלה לצפת-אחרי תקץ והיה מחשובי הרבנים שם."},{"i":3813,"n":"אליהו הלוי מהמבורג","dt":"תקעה - כא טבת","dp":"אלטונא","b":"מו\"צ בהמבורג-תקנד ומחכמי הקלויז החדש, ברח לאלטונא בזמן מלחמת נפוליאון."},{"i":3814,"n":"אליהו הלוי מוילקומיר","f":"מאיר","b":"רב בוילקומיר"},{"i":3815,"n":"אליהו הלוי מירושלים","f":"ברוך","dt":"תרסב","dp":"ירושלים","b":"אב\"ד פושעלאט, עלה לירושלים,"},{"i":3816,"n":"אליהו הלוי מקושטא","k":"אליהו הזקן","b":"רב בקושטא-רן, הוא או אביו היה רבו של הרא\"ם שמביא ממנו בספריו. התיר ללמד תורה לקראים בניגוד לר משה קפסלי שאסר. מתלמידיו גם: ר חנוך סאפורטא, ר אליעזר קפסלי, ועוד. הגיה את האלפס-רסט בקושטא. ראה גם: אליהו פרנס בן שמואל מאישטיפי."},{"i":3817,"n":"אליהו הלוי משלוניקי וקושטא","f":"בנימין","k":"בעל תנא דבי אליהו","dt":"ש - אחרי","b":"תלמיד ר משה קפסאלי - והגן עליו כנגד ר יוסף קארו (צ\"ל קולון) שיצא כנגדו. רב בשלוניקי ומגיה בדפוס נחמיאש-רנד (הגיה את ספר הטורים לר יעקב בן אשר), קושטא בק\"ק רומניטים בזמן הרא\"ם, פייטן, רב ראשי-רפו על מקום ר תם ן יחיא שהיה רב אחרי הרא\"ם (יחד עם ר יהושע קנדיוטי), ור מנחם בכור שמואל על מקומו אחריו. חיבר מחזור לבני רומניאה בתוגרמה עם פיוטים ממנו. חיבר גם \"לוית חן\" - קושטא תם."},{"i":3818,"n":"אליהו הלוי מתבריז","f":"חננאל","b":"רב בתבריז-פד."},{"i":3819,"n":"אליהו הלל ג'יליבי הקראי מקושטא","b":"מראשי עדת הקראים בקושטא-ת'."},{"i":3820,"n":"אליהו הפייטן","f":"מרדכי","b":"פייטן באיטליה?-ד'תש, חתום על יוצר למנחה ליוה\"כ מהמחזור, מפיוטיו: \"אראלים בשם תם ממליכים\". הראב\"ן פירש כמה מפיוטיו."},{"i":3821,"n":"אליהו הפרנס מכרתים","b":"רב בכרתים-שנת כ'"},{"i":3822,"n":"אליהו הצדיק ממרוקו","dp":"פצ'אר לביצ'א-מרוקו","b":"צדיק ממרוקו, קברו נחשב למקום מקודש וביכ\"נ נמצא על קברו."},{"i":3823,"n":"אליהו הקדוש מאיטליה ואשכנז","f":"שמואל","dt":"נז","dp":"וירצבורג","b":"פייטן מחכמי איטליה. נהרג עק\"ה בזמן מלחמת האפיפיור נגד בני קולנה עם חבריו ר אפרים בן אברהם ור יצחק בן נתן."},{"i":3824,"n":"אליהו השטיפאני","b":"חכם ופייטן בסטיפאנוב על נהר פרוט-רכ\"ט"},{"i":3825,"n":"אליהו זאב מוילנא","b":"רב בווילנה"},{"i":3826,"n":"אליהו זלמנ'ס מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":3827,"n":"אליהו חיים מברוקא","dt":"תרד - ז תשרי","b":"רב בברוקא"},{"i":3828,"n":"אליהו חסיד מוילנא","f":"משה קרמר מוילנא","dt":"תע - כא אלול","dp":"וילנא","b":"חתן ר פתחיה בן משה ריבקש בעל באר הגולה. דיין בוילנא ומראשי הקהילה. בניו: ר ישכר בער-זקנו של הגר\"א, ר משה מקובנא, ר צבי הירש."},{"i":3829,"n":"אליהו חריף משאט","f":"רגולר, אליהו מקאליש","b":"נכד(-אבי אמו) ר אליהו מראסיין. רב בשאט, ראגלי, סלובודקה, קאליש. בנו - ר יעקב מניישטאט."},{"i":3830,"n":"אליהו טוביה"},{"i":3831,"n":"אליהו יהודה ליב מרישא","b":"תלמיד ה\"ישמח משה\". מחכמי רישא. חתן ר וולף דמשק."},{"i":3832,"n":"אליהו יוסף מטראספול","b":"אחיו - ר מנחם נחום טראספולר מבריסק."},{"i":3833,"n":"אליהו ישראל מירושלים","b":"מוזכר ב\"חרבות ירושלים\" כאחד מ15 האסורים יחד עם השל\"ה בפורענות אבן פארוך-שפה."},{"i":3834,"n":"אליהו מאדרינופול ויאמבול","f":"יעקב","b":"דיין באדרינופול-תקעה בזמן ר יעקב גירון."},{"i":3835,"n":"אליהו מאויניון","b":"רב באויניון-תקלז בזמן שעבר שם החיד\"א."},{"i":3836,"n":"אליהו מאוסטרהא","f":"יצחק","dt":"תקנז - ד אייר","dp":"אוסטרהא","b":"פרנס באוסטרהא."},{"i":3837,"n":"אליהו מאוסטרהא","f":"חיים חייקא מאוסטרהא","dt":"תקסו - טו אדר","b":"מחכמי אוסטרהא."},{"i":3838,"n":"אליהו מאיטליה","f":"יהודה","k":"בעל תולדות","b":"מחכמי איטליה, רב ורופא במריני. חיבר ספר ברפואה - בכת\"י."},{"i":3839,"n":"אליהו מאיטליה","f":"שמעיה","b":"רב בבארי-איטליה (עליה אמר רבינו תם \"כי דבר ה מאוטרנטו ומציון תצא תורה בעיר בארי). חתם עם חבריו בתשובה - הובא בראב\"ן. חיבר פיוטים - נכנסו במחזור."},{"i":3840,"n":"אליהו מאיר מסינגפור","b":"גביר נדיב בסינגפור, סייע לבן איש חי בהדפסת ספריו."},{"i":3841,"n":"אליהו מאיר מראסיין","f":"ברוך מסוגינדט","dt":"תרח","dp":"זאגער","b":"תלמיד ר אליהו רגולר מקאליש. מחכמי ראסיין. אחיו - ר שלום טוביה משונציאן."},{"i":3842,"n":"אליהו מאלגיר","bt":"של - בערך","dt":"תי - בערך","b":"רב בתלמסאן יחד עם ר משה שוראקי. תשובה אליו מר שלמה צרור ב\"חוט המשולש\"."},{"i":3843,"n":"אליהו מאניקשט","b":"רב באניקשט-תק\"ס"},{"i":3844,"n":"אליהו מארץ ישראל","b":"נזכר באגרת ר משלם מואלטורה שסיפר בשם הנגיד ר עמרם ממצרים \"שבשנת קפ עלה (לארץ) דרך מצרים רב גדול שמו ר אליהו עם תלמידו ר בנימין בן אלחנן ובקשו סיוע מהנגיד."},{"i":3845,"n":"אליהו מביאליסטוק","k":"אליהו ביאלישטאקער","b":"בשליחות קהלת וילנא להביא את כספי התרומות לצפת וירושלים-תקעח עם ר זלמן הכהן."},{"i":3846,"n":"אליהו מבלגרד","f":"אהרן","b":"מחכמי בלגרד-שנות ה-ת'. תשובה אליו ב\"דבר שמואל\"."},{"i":3847,"n":"אליהו מבלחוב","f":"משלם הכהן","b":"רב בבולחוב"},{"i":3848,"n":"אליהו מבעליצא","b":"אב\"ד בעליצא."},{"i":3849,"n":"אליהו מדינבורג","b":"ספרא ודיינא בדינבורג"},{"i":3850,"n":"אליהו מדליאטיץ","f":"אברהם","k":"בעל בן אברהם","b":"חיבר גם \"שני אליהו\" עם הגהות הגר\"א ו\"מעשנה אליהו\" על עוקצין."},{"i":3851,"n":"אליהו מדמשק","f":"עמיאל","b":"מחכמי דמשק-שן, ונזכר בספר החזיונות למהרח\"ו."},{"i":3852,"n":"אליהו מהנאו וירושלים","b":"מחכמי הנאו, עלה לארץ - ר-רל בערך. אחיינו ר יוסף השתדלן מרוסהיים בעל ספר המקנה מספר כי בהיותו בן שש היה אצל דודו ר אליהו שהלך לירושלים וביקש לקחתו עמו, ועל שמו נקרא נכד ר יוסלמן - ר אליהו בעל שם. (נזכר בספר משפחת לוריא)."},{"i":3853,"n":"אליהו מהעכים-בואריה","f":"חיים","k":"בעל שבילי דרקיע","b":"תלמיד ר יחזקאל לנדא בעל \"נודע ביהודה\". רב בהעכים-בוהמיה. חיבר גם \"ילדי הזמן\" על ספר \"בחינות עולם\", ועוד."},{"i":3854,"n":"אליהו מוולוזין","dt":"תקס - א טבת","b":"רב בסמרגון, זסקוביץ(=זסקביץ). דוד ורבו של ר מנשה מאיליא. חתנו - ר יוסף זסקביצר ונכדו ר שמואל שטרשון מוילנא."},{"i":3855,"n":"אליהו מוילנא","f":"יצחק","dt":"תקפב - ז אב","dp":"וילנא","b":"נכד-אבי אביו בעל \"חיי אדם\". מחכמי וילנא. נפטר צעיר."},{"i":3856,"n":"אליהו מוילנא","f":"יעקב יעקל מוילנא","k":"ר אלינקע יעקילס","b":"(כינויו של אביו - ר יעקעלע ר ליבעלעס). חתן ר אריה ליב ברוידא מקאלווריה. אחיו - ר דובער אלי'ס מדובנא, ר מרדכי צבי, ר חיים. גיסו ר יעקב בן ר זיסל רפפורט ממינסק."},{"i":3857,"n":"אליהו מוילנא","f":"אליעזר","dt":"תקסו - יח אייר","dp":"וילנא","b":"מחכמי וילנא."},{"i":3858,"n":"אליהו מוילנא (הינדיש)","f":"מרדכי בן יעקב ישראל","k":"אליהו הינדעס","dt":"תקפט - כד תמוז","dp":"וילנא","b":"אחיינו-בן אחותו של ר שמעון פרגר (המכונה הגדול) מוילנא. סו\"ד בוילנא, מסדר הגיטין. כתובת מצבתו נכתב בידי אד\"ם הכהן. אחיהם של ר ישראל, ר שאול מאסטרין, ר ירחמיאל."},{"i":3859,"n":"אליהו מוילנא - הגר\"א","f":"שלמה זלמן מוילנא","k":"הגר\"א-הגאון מווילנה","r":"הגאון","bt":"תפ","bp":"סעלץ","dt":"תקנח - יח תשרי","dp":"וילנא","b":"חתן ר יהודה מקידאן, ובזיוו\"ש חתן ר יחזקאל לונץ מקידאן ושעוויל. ראש גאוני ישראל מרביץ תורה הנגלה ובנסתר בוילנא, מחבר הגהות וביאורים בכל מקצועות התורה. מאמר בשמו ב\"העץ\" - לובלין תרצג. חתניו - ר צבי הירש מדיסנא, ר שרגא פיבוש מדוברווא.","bk":[["אדרת אליהו","מפרשי תורה"],["הגר\"א יונה","מפרשי תנ\"ך"],["הגר\"א אסתר על דרך הפשט","מפרשי תנ\"ך"],["הגר\"א אסתר על דרך הרמז","מפרשי תנ\"ך"],["דבר אליהו","מפרשי נ\"ך"],["דברי אליהו","מפרשי תנ\"ך"],["קול אליהו","מפרשי תנ\"ך"],["אליהו רבא","מפרשי משנה"],["שנות אליהו [הקדמה]","מפרשי משנה"],["שנות אליהו הקצר","מפרשי משנה"],["שנות אליהו הארוך","מפרשי משנה"],["באור הגר\"א","מפרשי תוספתא"],["הגהות הגר\"א","מפרשי תוספתא"],["הגהות הגר\"א","מפרשי ש\"ס - אחרונים"],["משנת אליהו","מפרשי ירושלמי"],["באור הגר\"א","מפרשי שו\"ע"],["מעשה רב","הלכה ומנהג - אחרונים"],["אגרת הגר\"א","מחשבה ומוסר - אחרונים"],["הגר\"א",""],["הגר\"א (הגאון מווילנא)",""],["ביאור הגר\"א – הגהות שו\"ע,",""]]},{"i":3860,"n":"אליהו מוילנא פרג ואמשטרדם","f":"עזריאל מוילנא","k":"בעל מענה אליהו","bt":"תס","bp":"וילנא","dt":"תקח","b":"יצא עם אביו מוילנה לאשכנז-תס. תלמיד ר אברהם ברודי ור יונה לנדסופר בפרג. חיבר \"מעיל צדקה\" בהשגחת ר יונה לאנדסופר. חיבר תקון סופרים-כללים לסופרי סת\"ם בתמיכת ר יעקב כץ מפרנקפורט ור דוד אופנהים מפרג - אך לא הסתייע, ועבר לאמשטרדם, הרבנים אסרו לפרסם השגות על ספרו בלי הסכמת שלשה רבנים. הו\"ל עם אביו סדור \"מענה אליהו\" והיה מחלוקת כנגדו מהמדקדק ר זלמן הענא. לדעת רוזניס הוא אחיו של המדפיס נפתלי בן עזריאל אשכנזי מקושטא."},{"i":3861,"n":"אליהו מזולקווא","f":"העזל","b":"מראשי קהלת זולקווא, חתם-תפד עם ראשי הקהלה."},{"i":3862,"n":"אליהו מחעלם - הנכד","b":"נכד ר אליהו בעל שם מחלם. רב בחעלמא(=חלם). זקנו של ה\"חכם צבי\"."},{"i":3863,"n":"אליהו מיוראוויטש","f":"זאב וולף כץ","b":"תלמיד ר מנחם נחום מטשרנוביל, שהזכירו בהקמת ספרו \"מאור עינים\"."},{"i":3864,"n":"אליהו מיורק","f":"יוסף","dt":"ד'תתקנ","dp":"יורק","b":"מבעלי התוספות, רב ביורק(=אוברקא)-אנגליה. נהרג עק\"ה."},{"i":3865,"n":"אליהו מירושלים","dt":"תיו - א כסלו","dp":"ירושלים","b":"מחכמי ירושלים"},{"i":3866,"n":"אליהו מירושלים","f":"ישראל","b":"מחכמי ישיבת \"חסד לאברהם\" בירושלים-תקז בערך."},{"i":3867,"n":"אליהו מכורדיסטן וארץ ישראל","f":"זכריה","dt":"תשלד - כד שבט","b":"מחכמי כורדיסטאן, עלה לא\"י-תשי\"א, רב מושב מיטב"},{"i":3868,"n":"אליהו מלאסק","dt":"תקצב","b":"תלמיד היהודי הקדוש מפשיסחא, ר שמחה בונם מפשיסחא, ור מנחם מנדל מקוצק. חברו של ר חנוך הניך מאלכסנדר."},{"i":3869,"n":"אליהו מלבוב","f":"צבי הירש","b":"דיין בלבוב, חתם-תסד עם ר ישעיה קצנלנבוגן, ר יחיאל מיכל מסקול, ועוד."},{"i":3870,"n":"אליהו מלבוב","f":"נתן יחיאל","dt":"שצב - כג תשרי","dp":"לבוב","b":"ר\"מ ודיין בלבוב."},{"i":3871,"n":"אליהו מלובלין","f":"קלונימוס","k":"בעל אדרת אליהו","b":"מחכמי לובלין. חיבר \"אדרת אליהו\" - פפד\"א תנד."},{"i":3872,"n":"אליהו מלובלין","f":"מנחם מנדל","dt":"תקעב - כז חשון","dp":"לובלין","b":"מחכמי לובלין ומלמד תורה."},{"i":3873,"n":"אליהו מלובלין ואולינוב","f":"יעקב","k":"בעל ברכת אליהו","b":"מצאצאי ר שכנא מלובלין. רב באולינוב, קאלטשין, נאלץ לברוח ועבר בתורכיה, איטליה והתישב באמשטרדם אצל האב\"ד ר אריה ליב. חיבר \"ברכת אליהו\" על מנהגי אשכנז ובסופו תוספות דינים לר משה חגיז."},{"i":3874,"n":"אליהו מלומזה וירושלים","f":"ליפמן (ליטמן?)","dt":"תרכט - יב אב","dp":"ירושלים","b":"היה דיין בלומז'ה ועלה לירושלים"},{"i":3875,"n":"אליהו מליוביץ","b":"דיין בליוביץ-תר\"מ"},{"i":3876,"n":"אליהו מליוורנו","k":"בעל אדרת אליהו","b":"רב בליוורנו. חיבר \"אדרת אליהו\" על התורה ומעט קבלה."},{"i":3877,"n":"אליהו ממונפלייר (מן ההר)","b":"תשובה ממנו בענין קידושי קטן - בכת\"י (הובא ב\"סיני\" שנה יא)."},{"i":3878,"n":"אליהו ממזריטש","f":"שמואל הכהן","dt":"תעה - כה ניסן","b":"רב במזריטש"},{"i":3879,"n":"אליהו ממזריטש וירושלים","f":"דוד","dt":"תרכו - כו חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":3880,"n":"אליהו ממיטאוי","f":"דוד יחזקאל","b":"רב במיטאוי, וינדאווי"},{"i":3881,"n":"אליהו ממילנו","f":"שמואל בן אליעזר","b":"חיבר פירוש לספר איוב - בכת\"י."},{"i":3882,"n":"אליהו ממנטובה","k":"בעל אור עינים","b":"מגדולי חכמי איטליה, רב במנטובה-שי. (אולי הוא ר פנחס אליהו ממנטובה)"},{"i":3883,"n":"אליהו ממרוקו","f":"חיים","b":"מחכמי מרוקו, רוב חבוריו אבדו, הניח חיבור דרשות על התורה-בכת\"י. נזכר אצל החיד\"א."},{"i":3884,"n":"אליהו ממריאמפול","b":"רב במריאמפול-תר\"נ"},{"i":3885,"n":"אליהו מנחם מאנגליה","f":"משה בר יום טוב","k":"מגדולי בעלי התוספות","dt":"מד","b":"תלמיד ר\"ש בן אברהם משאנצי, ר בנימין מקונטבריא-תלמידו של רבינו תם. מבעלי התוספות, רב בלונדון-ה'א, ומקובל. עשיר ומקורב למלכות ורופא. רבה האחרון של אנגליה לפני הגירוש. אחיו: ר ברכיה מניקולא, רב האי גאון. חיבר פירוש למשנה. תלמידו: ר יצחק בן שלמה מרקוש. לדעת מרדכי ליב זקס - פירוש התוס' ל\"ראש השנה\" הידוע כתוס' ר\"ש משאנץ - הינם למעשה עריכה וקיצור שעשה ר אליהו מנחם על תוס' ר\"ש. הוזמן ע\"י מלך פלנדריה לבוא לרפאו. ששת בניו יצאו לגלות בזמן הגירוש-ן'."},{"i":3886,"n":"אליהו מסטאויצק וירושלים","f":"יוסף","dt":"תרכח - ד כסלו","dp":"ירושלים","b":"עלה לירושלים וכיהן כדיין."},{"i":3887,"n":"אליהו מסיאמטיץ","dt":"תרכו - כ חשון","b":"רב בסמיאטיץ,עלה לירושלים"},{"i":3888,"n":"אליהו מסלרנו","b":"מחכמי סלרנו-ד'תתקל. נזכר ע\"י ר בנימין מטודלה יחד עם ר יהודה בן יצחק, ר מלכי צדק (=ר\"י סמפונטי), ר שלמה הכהן, ור אברהם הנרבוני."},{"i":3889,"n":"אליהו מסמרגן","dt":"תרס - ו כסלו","b":"רב בסמרגן"},{"i":3890,"n":"אליהו מעכו","f":"אהרן בן רבנא יאשיהו","b":"מחכמי עכו-ד'תתא (941), מראשי ישיבת \"גאון יעקב\". חיבר פירוש לתנ\"ך בדרך דקדוק - ואבד - שרד קטע ממנו. אחיו של ר יאשיהו אב\"ד-אביו של ר צדוק."},{"i":3891,"n":"אליהו מעכו","dt":"פד (1324)","dp":"עכו?","b":"מחכמי עכו-ן' (1290), נשא ונתן עם הרשבא ומוזכר בתשובותיו, ישנם שו\"ת ממנו (לונדון גסטר)"},{"i":3892,"n":"אליהו מפורלי","f":"יצחק","k":"בעל אגרת התכונה","b":"מחכמי איטליה, בקי בתכונה. חיבר \"אגרת התכונה\"."},{"i":3893,"n":"אליהו מפיזרו ונציה ירושלים","b":"רב בונציה, פיזרו-איטליה. חיבר מכתב על מסעו לארץ - חזר מהאי ציפרוס(=קפריסין) כי שמע שפרצה מגפה בארץ, ומספר על פגישתו עם ר\"א אשכנזי בעל \"מעשי ה\". חיבר פירוש על איוב ושיה\"ש - בכת\"י, מאמר על התשובה, ועוד."},{"i":3894,"n":"אליהו מפילטען","f":"יוסף","b":"מו\"ץ בפילטען-תקעה ור דובער מזידוק על מקומו אחריו. בנו - ר יוסף הרצברג."},{"i":3895,"n":"אליהו מפינטשוב","f":"משה גרשון","k":"בעל מענה אליהו","b":"רופא מחכמי פינטשוב-תקל. חיבר גם \"מלאכת מחשבת\", \"הדרת אליהו\", ועוד."},{"i":3896,"n":"אליהו מפינסק (פוחוביצר)","f":"יהודה ליב - קנה חכמה","b":"רב בפינסק-תנ על מקום אביו - ר יהודה ליב פוחוביצר. בנו ר משה רב באוסטרהא והגליל. חיבר ספר דרושים - בכת\"י. נכדו ר אליהו זוטא פינס מסלוצק"},{"i":3897,"n":"אליהו מפיררה וירושלים","bp":"איטליה","dp":"[ירושלים]","b":"רופא מגדולי חכמי איטליה, עלה לירושלים-קצד(=1434) יחד עם בנו יעקב ונכדו מנחם שטבעו בדרכם, היה רב הקהלה לאחר המגפה שפגעה קשות בתושבי ירושלים. כתב כמה אגרות שאחת מהם פורסמה בספר \"דברי חכמים (מיץ תרט), באגרותיו מתאר את מצב העדה בירושלים."},{"i":3898,"n":"אליהו מפלאצק","f":"חיים נחמן פרנס מוילנ","dt":"תרל - א ניסן","b":"אחיו - ר אברהם פרנס מוילנא."},{"i":3899,"n":"אליהו מפרג","b":"תלמיד בעל \"תרומת הדשן\" שהזכירו בתשובותיו. רב בפרג-רטז בזמן מהרי\"ק. היה במחלוקת עם כמה רבנים בגלל התערבותו בנעשה מחוץ לתחום רבנותו והתלוננו עליו אצל רבו שהוכיחו על כך. התערב במחלוקת בין רבו לבין ר\"ר מיישטרליין לטובת הר\"ר מיישטרליין ועל זה כתב לו רבו תוכחה ואף מזכיר לו שמהר\"א לוריא קובל עליך, ומהר\"י ברונא, ועוד. בסוף ימיו הגיע לפראג ר אליעזר פולק מפיסרו-תלמיד מהר\"י וייל ו\"תרומת הדשן\" והיה מחלוקת ביניהם עד שהיו שרצו לפגוע בר אליהו ואז התערבו רבים מגדולי הדור לטובתו (מהרא\"י בעל תרומת הדשן אמנם תמך בו אך גם בר אליעזר יריבו - וזאת לפי שיטתו שאין השגת גבול ברבנות). מתורתו ב\"לקט יושר\" לר יוסף מינסטר, ובהגהות ומנהגים לר איזיק טורנא. חיבר הגהות על הטור."},{"i":3900,"n":"אליהו מפרובנס","f":"יצחק","k":"בעל ספר האסופות","b":"מחכמי קרקושנא-פרובנס. יש אומרים שחיבר ספר האסופות. בניו: ר יצחק (ממגורשי צרפת), ר יעקב-אביו של ר יהודה שחיבר גם הוא ספר אסופות - ואולי ישנו ספר אחד והוא מהנכד. (יש אומרים שהיה תלמיד בעל הרוקח - ויש אומרים שחכם אחר הוא שהיה תלמיד הרוקח וחיבר ספר אסופות). אחיו של ר\"ש מקרקשונא."},{"i":3901,"n":"אליהו מפריס","f":"יהודה בן יו\"ט","b":"מגדולי בעלי התוספות בזמן ר\"ת שהיה מקרובי משפחתו (ר\"ת כינה את ר יו\"ט \"זקני\"), כנראה מתלמידי רש\"י (הוא או אבותיו). פוסק, מקובל, רב בפאריס-ד'תתקל. תשובה ממנו לראב\"ן - יחד עם ר\"ת ור משלם. היה מחלוקת בינו לר\"ת בגלל שביטל כמה ממנהגי רש\"י ויצא ר\"ת כנגדו ובעיקר כנגד ר משלם בן נתן חברו על כך. אחיו כנראה ר מתתיה. מבניו: ר מאיר בן אליהו. מתלמידיו: ר משה מפנטשא, ריצב\"א מדנפיר. פיוט ממנו לשבועות \"אומץ יום בכורים\" - במחזור."},{"i":3902,"n":"אליהו מציטוביאן ואקמיאן","f":"זרחי","b":"תלמיד ר אליהו רגולר. רב בציטוביאן, אקמיאן. נחשב לבעל מופת."},{"i":3903,"n":"אליהו מצפת","f":"משה","b":"מחכמי קהלת הפרושים בצפת. חתם-תקעה על מינוי הגבאים ר ישראל משקלוב, ר צבי הירש כץ, ר משה בן יוסף."},{"i":3904,"n":"אליהו מצרפת","f":"כלב בן ליאון","b":"מחכמי צרפת-ד'תתק, עלה לארץ. מכתב ממנו לנגיד ר שמואל בן חנניה מאלכסנדריה - בגניזה."},{"i":3905,"n":"אליהו מצרפת","b":"מחכמי צרפת-ה'א. בניו: ר פרץ מקורבייל, ור יוסף מטריוויש. חתנו - ר אלעזר מקונין בן יוסף."},{"i":3906,"n":"אליהו מקאשטוריה","f":"אברהם","b":"פייטן-ק' ומפיוטיו במחזורי הספרדים הישנים."},{"i":3907,"n":"אליהו מקוברין","k":"בעל מכתב אליהו","b":"רב בשנת ת\"ס"},{"i":3908,"n":"אליהו מקוסוליבקא","b":"תלמיד הבעשט"},{"i":3909,"n":"אליהו מקושטא","f":"מנחם","b":"מגדולי חכמי קושטא-שפ\"ה"},{"i":3910,"n":"אליהו מקושטא","f":"יעקב","b":"דיין בקושטא עם ר משה מרגונטו ור חיים עובדיה נתן."},{"i":3911,"n":"אליהו מקושטא","f":"אליעזר","b":"רב בקושטא-תר בערך."},{"i":3912,"n":"אליהו מקושטא","f":"יעקב דוד","b":"דיין בקושטא-תקץ בערך אצל ר אליהו ענבי."},{"i":3913,"n":"אליהו מקושידאר ופילטן וקליקול","b":"רב בזמן הגר\"א בקליקול, קושידאר-ליטא, פילטן. הגר\"א חיבבו והוקירו."},{"i":3914,"n":"אליהו מקנדיא","b":"מגדולי חכמי דורו-שנת ל', רב בקנדיא(=כרתים). נזכר בשו\"ת הרשב\"א שהשיב לו."},{"i":3915,"n":"אליהו מקנדיא","f":"ראובן","b":"פרנס מחכמי קנדיא. חתם בתקנות קנדיא-קסח. ונזכר ב-\"אהל דוד ששון\"."},{"i":3916,"n":"אליהו מקראקא","dt":"שצז","b":"עק\"ה,מחכמי קרקא"},{"i":3917,"n":"אליהו מקראקא","b":"רב בקרקא"},{"i":3918,"n":"אליהו מקראקא","f":"יהודה","dt":"שצז - ה סיון","dp":"קראקא","b":"מחכמי קראקא. נהרג עק\"ה."},{"i":3919,"n":"אליהו מקרוז' - גיס הגר\"א","f":"מאיר","b":"גביר מחכמי קרוז'-תקע בערך בזמן כהונת ר אברהם אחי הגר\"א. גיסו של הגר\"א - אחותו היתה אשתו השניה של הגר\"א - והגר\"א כיבד את ר אליהו בסידור הקידושין. מבניו: ר יחזקאל משאוולי, ר ישעיה מקרוז (נולד לו בגיל 90). חתניו: ר יעקב ור בנדט - רבני קרוז'. מסופר כי ר אברהם-אחי הגר\"א עזב את קרוז' לאחר שר אליהו קיבל את הכיבוד הראשון בשמחת תורה במקומו."},{"i":3920,"n":"אליהו מקרזמיר","b":"רב בקרזמיר-תק\"י"},{"i":3921,"n":"אליהו מקרסטיר","b":"רב בקרסטור(=קרסטיר)"},{"i":3922,"n":"אליהו מקרעמזיר","b":"רב בקרעמזיר-תק בערך, הסכים על באר טוב לר ישכר דב מפרשבורג."},{"i":3923,"n":"אליהו מריטובה","dt":"תקע","b":"חתן ר זאב וולף מראסיין בן ר שמואל מפלונגיאן. אב\"ד ריטובה. גיסיו - ר שמואל חסיד מראסיין, ר מנחם מנדל מוילנא בעל \"יעיר קינו\", ר דוד בן אליהו מראסיין."},{"i":3924,"n":"אליהו מרייטץ","b":"רב ברייטץ-תקפא על מקום ר יצחק איזיק ליב, ור אליעזר וינטר על מקומו אחריו. נזכר בשו\"ת החת\"ס (ושם דן איך כותבים שם העיר רייץ או רייטץ), ונזכר גם ב\"צמח השדה\" לר נתן פרידר מטשארנא."},{"i":3925,"n":"אליהו משדה-לבן","f":"יעקב מלאנצהוט"},{"i":3926,"n":"אליהו משימבורג ומיטאוי","f":"צבי","dp":"בויסק","b":"מחכמי זופראן, רב בשימבורג, מיטאוי. נפטר צעיר."},{"i":3927,"n":"אליהו משלוניקי","f":"יעקב נסים","dt":"תרכט","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים, בשנת תרטז תריט שליח במרוקו, וכן בשנת תרכג"},{"i":3928,"n":"אליהו משלוניקי","f":"יוסף","k":"בעל קול תרועה","b":"מחכמי שלוניקי-ש', אחיו של ר יונה בעל \"קול יונים\". חיבר \"קול תרועה\" - שכב."},{"i":3929,"n":"אליהו משלוניקי","f":"דוד","dt":"תצג","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":3930,"n":"אליהו משלוניקי","f":"יהודה עוזיאל","dt":"שלג - אחרי","b":"מחכמי שלוניקי. חתם על הסכמות הקהל בשלוניקי."},{"i":3931,"n":"אליהו משערשוב","f":"יוסף בן חיים מוולוזי","b":"נכד ר חיים מוולוזין, ערך את ההקדמה לספר זקנו \"נפש החיים\". בגיל 40 התקרב לחסידי לכוביץ בשרשוב והצטרף לקהילתם."},{"i":3932,"n":"אליהו נתן מקושטא","b":"גביר בקושטא-שנות ה-תק'."},{"i":3933,"n":"אליהו סגל הלוי מפינאלי","f":"רפאל שלמה","k":"בעל כורסיא דאליהו","bt":"תעג - ז שבט","bp":"פינאלי(איטליה)","dt":"תקנב - ז תמוז","dp":"אליסאנדריא דילה פאלייה","b":"תלמיד חבר לר\"י למפרונטי, ושניהם תלמידי מהר\"י בריאל ממנטובה. רב באליסנדריאה דילה פאלייה-איטליה-תצח, פיימונטי-תקיט, וכן צאצאיו אחריו. מתשובותיו ב\"שמש צדקה\" ו\"פחד יצחק\" ו\"גבעת פנחס\". היה מעורב במחלקות בין רבני ונציה ורבני רוויגו - בשאלה האם לחייב ספרים בהגהה - הוא סבר שאין צורך בהגהה. חיבר סדר דאליהו\" מנטובה תקמו, \"בן בגימטריא אליהו\", טייעא דאליהו\", \"כורסיה דאליהו\" - בכת\"י."},{"i":3934,"n":"אליהו סטאמלער מנובוגרד","dt":"תרעב - אייר","b":"נכד ר מאיר מראסיין-תלמיד הגר\"א. רב בנובוגרד-ליד וילנא."},{"i":3935,"n":"אליהו סטרעלצר מירושלים","f":"משה מאישישוק וירושלי","dt":"תרנט","dp":"ירושלים","b":"חתן ר אליהו דייכס מירושלים. מחכמי ירושלים."},{"i":3936,"n":"אליהו עובדיה מאדרינופול וירושל","f":"עובדיה","b":"מחכמי אדרינופול-סוף שנות ה-ש', עלה לירושלים, יצא בשליחות למצרים ותשובה ממנו שם בספר \"גינת ורדים\", וכן תשובה ממנו בספר \"זרע אברהם\". שליח בטורקיה בשנת תנח. (בשכנה\"ג אות ג בשם ר אליהו בענין וידוי השץ). אחיו - ר סימן טוב עובדיה."},{"i":3937,"n":"אליהו עובדיה מבגדד","f":"יהושע","k":"בעל שיחת דקלים","bt":"תקמח","dt":"תרנה","b":"מחכמי בגדאד, אב\"ד, חיבר \"שיחת דקלים\""},{"i":3938,"n":"אליהו עובדיה משלוניקי - א","f":"עובדיה או חיים","dt":"שלג","b":"ר\"מ בק\"ק קאטאלן בשלוניקי-שנות ה-ש', ובנו ר משה על מקומו אחריו. משורר מחברי ר גדליה ן יחיא. (באוצר - ממשפחת די בושאל)."},{"i":3939,"n":"אליהו עובדיה משלוניקי - ב","b":"רב בשלוניקי-תן. תשובה ממנו ב\"גנת ורדים, וב\"זרע אברהם\"."},{"i":3940,"n":"אליהו פרנס מיון","f":"יקטן","b":"פייטן מחכמי יון, מפיוטיו במחזורים קדומים."},{"i":3941,"n":"אליהו פרנס מקושטא-ניגרופונטי","b":"ראש קהלת ניגרופונטי-בקושטא-רן-ש'."},{"i":3942,"n":"אליהו פרץ מוילנא","f":"ישכר בר - מעשה רב","bt":"תקסו","dt":"תרכז - ט תשרי","b":"נכד ר תנחום מארלע והורדנא. בזיוו\"ש חתן ר ישראל חפץ וגיסו של ר נפתלי צבי הירש חפץ בעל \"גן צבי\". רב בוילנא על מקום אביו. החזיק בכתביו של ר אברהם יהושע השל מקראקא. פרסם מאמרים ובהם ב\"הכרמל\"."},{"i":3943,"n":"אליהו צבי מבוריסוב","b":"נכד הגר\"א. התצטרף לחסידות והיה מתלמידי ר מנחם מנדל מליובאויטש."},{"i":3944,"n":"אליהו צבי מדרהטשין","b":"רב בדרהיטשין(=דרהטשין), ובנו ר מנחם על מקומו אחריו."},{"i":3945,"n":"אליהו צבי מירושלים - א","b":"מחכמי ישיבת \"יפאר ענוים\" בירושלים-תקיח, מבית דינו של ר יום טוב אלגזי, בשנת תקל חתם על מכתב חכמי ירושלים לאיטליה, בשליחות באירופה-תקלד - יחד עם חבריו ר יעקב בורלא ור יקר בן אברהם גרשון מקיטוב - בשליחות משותפת לספרדים והאשכנזים (יתכן שבסופו של דבר לא יצא לשליחות), בשנת תקלו ותקמא חתם על תקנת העזבונות והחזקות. הסכים על הספר \"|וחשב לו הכהן\", ועל ספר \"בית יעקב\" לר אברהם הכהן מלאסק. ועל מכתב רבני ירושלים לר רפאל יוסף בן רובי שיצא לגיוס כספים להצלת הר הזיתים שלא יהרס במצוות התורכים. ועוד"},{"i":3946,"n":"אליהו צבי מירושלים - ב","b":"מחכמי ירושלים, חתום על תקנות הקהלה משנת תקעא"},{"i":3947,"n":"אליהו צבי מפרידברג, גאלין ופסט","k":"בעל בית האוצר","b":"רב בפרידברג, גאלין, בילזן, הסתלק מרבנות והתיישב בפעסט. חיבר גם \"מנחה חדשה\", \"הביצוע\", \"מנחת עומר\"."},{"i":3948,"n":"אליהו צבי מקושטא","b":"דיין בקושטא-תקפז, חתם עם ר אברהם גבאי, ר משה פריסקו ור שמואל חיים."},{"i":3949,"n":"אליהו צבי מרובזאל","b":"רב ברובזאל-מדינת באדן."},{"i":3950,"n":"אליהו קליקאלער מפילטען וקאליקו","f":"יוסף או מאיר","dt":"תקעה - א חשון","dp":"פילטען","b":"תלמיד דודו ר ליב אפשטין מקניגסברג בעל \"הפרדס\", והגר\"א (דוד אשתו), חתן ר ראובן רובינזון. סירב לרבנות קידאן, רב בפילטן(=פילטען), קאליקול. בנו - ר אברהם בויער מליבאוי. מתלמידיו - אחייניו - ר משה מיכל מקרקינווא, ר יעקב מבויסק בעל \"זכרון יעקב\". בניו - ר שמעון מניישטט-סוגיגד, ר אברהם בויער מליבאוי, ר ברוך בנדט. גיסו - ר יונתן מפינסק."},{"i":3951,"n":"אליהו רבנא","b":"מחכמי צפת בשנת שצו. חתם על הסכמה בספר \"חוט המשולש\", מובא בשות \"פני משה\" ח\"ב ובשות \"באר מים חיים\" לר שמואל ויטאל. בשנת תכב חתם שני לר שמואל עדילה."},{"i":3952,"n":"אליהו ריטווער","b":"רב בריטעווע(=ריטובה), ובנו ר טודרוס על מקומו אחריו. אחיו של ר שלמה מהאזענפיט."},{"i":3953,"n":"אליהו שאול הקדוש מאויגשבורג","bt":"כד","dt":"קח","dp":"אויגסבורג","b":"מחכמי אשכנז. חיבר ביאור לסמ\"ג. נזכר ב\"שפתי ישנים\" בשם ר אליהו שאול."},{"i":3954,"n":"אליהו שלמה זלמן מוולוזין","f":"יצחק מוולוזין","b":"נכד ר חיים מוולוזין. חתנו - ר יהושע השל לוין מוילנא."},{"i":3955,"n":"אליהו ששון מירושלים - ב","b":"מחכמי ירושלים, חתום על קבלת עדות פרוזבול בשנת תקעט עם ר יהודה עזריאל. בקונטרס \"תוספת שביעית\" נמצא ספר \"מכתב מאליהו\" כנראה מר אליהו הנ\"ל, ליוורנו תרכג בתוך הספר \"קנין הגוף\" לר נתן עמרם."},{"i":3956,"n":"אליהו ששון מפטרץ","b":"דיין בפטרץ החדשה(=פטראג'יק)-תק."},{"i":3957,"n":"אליהו ששון מצפת - א","b":"מחכמי צפת-ש', בעל ספר \"חרדים\" מביאו בספרו, וכן המביט בתשובותיו סימן תר."},{"i":3958,"n":"אליהו, אבא דוד","dt":"תרלו - כג אייר","b":"מחכמי בגדאד"},{"i":3959,"n":"אליהו, יהושע אברהם מבומביי","dt":"תרעח","b":"רב בבומבאי"},{"i":3960,"n":"אליהו, יצחק משה מקאשטוריאה","b":"גביר בקאשטוריאה-תקן בערך, ברח עם אחיו - מרדכי לוינה."},{"i":3961,"n":"אליהו, מנחם מוינה","b":"מצאצאי האחים מרדכי ויצחק משה שברחו מקאשטוריאה לוינה-תקן, גביר בוינה עם בניו ישבו גם בבוקרשט, והקימו בנק \"האחים אליהו\"."},{"i":3962,"n":"אליהו, מרדכי מירושלים","f":"סלימן","b":"רב בירושלים. ראשון לציון."},{"i":3963,"n":"אליהו, מרדכי מקאשטוריאה","b":"גביר בקאשטוריאה-תקן בערך, ברח עם אחיו - יצחק משה לוינה."},{"i":3964,"n":"אליהו, סלימן מבגדד","f":"יוסף","k":"בעל כרם שלמה","bt":"תרלב","bp":"בגדד","b":"אביו של ר מרדכי אליהו הראשל\"צ. מחכמי ומקובלי בגדד, תלמיד ישיבת \"בית זלכה\". תלמיד ר אפרים זלכה ור ציון חזן ור יהושע שרבאני, שבהמשך הפכו לחבריו ואף לתלמידיו (כדברי ר אפרים זלכה). נסע ללונדון, עלה לירושלים ולמד קבלה אצל ר שאול דוויק הכהן. מגדולי המקובלים בירושלים."},{"i":3965,"n":"אליוביץ, מרדכי","dt":"תשג","b":"רב בסלונים"},{"i":3966,"n":"אלים ן, יום טוב מברושא","b":"רב בברושא(=ברוסא) - בדור שלאחר הגירוש."},{"i":3967,"n":"אלימאן - משפחה","b":"משפחה בארצות המזרח שמקורה באשכנז."},{"i":3968,"n":"אלימלך","k":"בעל טעם אלימלך","b":"תלמיד בעל שם אשכנזי."},{"i":3969,"n":"אלימלך","f":"הרבי ממגלניצא","dt":"תרמב - א ניסן","b":"רב בראדומסק"},{"i":3970,"n":"אלימלך דב מקרלין וירושלים","f":"אריה ליב","dt":"תרכב - ח אלול","dp":"ירושלים","b":"מחכמי ירושלים נפטר בגיל 35. חתם-תריט עם ר ליב בר\"מ מסטנוב על צוואה. בנו - ר אריה ליב הרשלר מירושלים."},{"i":3971,"n":"אלימלך הלוי מבילקמין","f":"אליעזר ליברמן","dt":"תד - ט אדר","dp":"לבוב","b":"אב\"ד בבילקאמין(=בילקמין)"},{"i":3972,"n":"אלימלך הלוי מקויל","b":"אב\"ד קויל. חתנו - ר יוסף זיידל מבלאשקי."},{"i":3973,"n":"אלימלך הלוי קו\"פ מחירוב","b":"רב בחירוב-תרסה."},{"i":3974,"n":"אלימלך ואנש מאילקוסט","f":"אריה","bp":"אילקוסט","dt":"תרמו?","b":"שו\"ב ומו\"ץ באילוקסט-תר על מקום ר חיים רפאל, ובנו ר צבי אריה על מקומו אחריו. יסד חברת \"בקור חולים\" עם ר יעקב אקרמן."},{"i":3975,"n":"אלימלך לוי","f":"משלם פייש לוי","b":"רב בטאש-תרס\"ח"},{"i":3976,"n":"אלימלך מליזנסק","k":"אדמור מליזנסק","r":"וויסבלום","bt":"תעז","dt":"תקמו - כא אדר","b":"רב בליזנסק, מפיץ תורת החסידות, בעל \"נעם אלימלך\".","bk":[["נועם אלימלך – עה\"ת",""]]},{"i":3977,"n":"אלימלך משאמשאן","dt":"תקצג - א טבת","b":"מרביץ תורה,דומ\"צ בה' מאד, רבה הראשון של האידו שאמשון(=שאמאשן)."},{"i":3978,"n":"אלימלך סגל מלבוב","b":"דיין בלבוב (תוך העיר)-תפה."},{"i":3979,"n":"אלימלך, א' שניאור זלמן","dt":"תרעד - יט חשון","b":"מגיד בקראס"},{"i":3980,"n":"אלימן, יוחנן מקושטא וספרד","k":"בעל חשק שלמה","b":"מחכמי קושטא, עבר לספרד ולימד שם את החכם הנוצרי דון פיקי דיל מיראנדולא. בקי בחכמה ומדעים."},{"i":3981,"n":"אלימן, שלמה מירושלים וצפת","b":"היה במשלחת הרבנים שנשלחו מירושלים בשליחות רבני קושטא לבדוק אחר נתן העזתי - יחד עם ר גבריאל איספיראנסה. עבר לצפת וכיהן כדיין אצל ר גבריאל."},{"i":3982,"n":"אלימני, אברהם","f":"שלמה","bp":"תימן","b":"עלה לירושלים תקמז, ויסד בית כנסת שנקרא על שמו כנסת בן אלימני, בגניזה נמצאו 2 מכתבים ממנו, וכן מכתב תלונה כנגדו על שחלק על ר' אברהם בן הרמבם."},{"i":3983,"n":"אלינא, דוד מאלטשטט","f":"שמעיה מטוטשאפ","b":"תלמיד החת\"ס, ותלמיד דודו-אחי אמו - ר שמואל יהודה. רב באלטשטט (סטארא-מעסטא)-תרי."},{"i":3984,"n":"אלינג, אליעזר מדמביץ","b":"מחכמי דמביץ - ממשתתפי \"אהל מועד\"-תרנח."},{"i":3985,"n":"אלינג, צבי מקרוסנו","b":"תלמיד ישיבת רדמוסק בסוסנוביץ. מתורתו ב\"תורת העולות\". פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":3986,"n":"אלינגר, מאיר הלוי מאיכנהאוזן","bt":"תצו","dt":"תקפו","b":"תלמיד ר נתן אדלר מפפד\"מ. ראב\"ד באיכנהאוזן. תשובה אליו בשו\"ת \"בגדי כהונה\"."},{"i":3987,"n":"אלינוביץ, אהרן מליטא","dt":"תשא","b":"רבה האחרון של ויסאקי-דוואר(=ויסוקידבור) על מקום ר מרדכי רבינוביץ. נספה בשואה."},{"i":3988,"n":"אלינוביץ, י.","b":"פרסם מאמרים ב\"בית המדרש החדש\" - גריבה תרפח."},{"i":3989,"n":"אליניק, אליהו מראסיין","b":"רב בראסיין, עמד בראש חברת \"תפארת בחורים\"."},{"i":3990,"n":"אליניק, חיים טוביה מואלטשין","f":"אלכסנדר סנדר","k":"בעל באר חיים","bt":"תריג","bp":"ואקשנא-ליטא","b":"רב בוולטשין(=וואלטשטין)-פלך גרודנא-תרמז. נסמך מאת: גראי\"ס מקובנא, ר אלכסנדר משה לפידות מראסיין. חיבר גם \"דברי חיים\", \"לב חיים\" - תרנב."},{"i":3991,"n":"אליס, אברהם מארה\"ב","f":"דוד אליהו","b":"עסקן צבור בפילדלפיה, נשיא הת\"ת וממיסדי ביהכ\"נ \"ישורון\"."},{"i":3992,"n":"אליס, יצחק","f":"מרדכי משה עליס","k":"בעל יסוד התשובה","b":"רב-שנת ש\"כ"},{"i":3993,"n":"אליס, משה","k":"בעל יסוד תשובה","b":"חיבר \"יסוד תשובה\"."},{"i":3994,"n":"אליסברג, יוסף","b":"גדול בתורה-תק\"פ"},{"i":3995,"n":"אליסברג, יוסף משלוניקי","bp":"רוסיה","b":"רופא בשלוניקי-תרס."},{"i":3996,"n":"אליסיד ן, עובדה מחברון","b":"רב בחברון-שן."},{"i":3997,"n":"אליעזר","k":"חתן ר' שמשון משאנץ","b":"מגדולי בעלי התוספות"},{"i":3998,"n":"אליעזר"},{"i":3999,"n":"אליעזר"},{"i":4000,"n":"אליעזר","f":"ישראל מטשעהאן"},{"i":4001,"n":"אליעזר","f":"בן יעקב יסו\"ד","k":"בעל משנת דראב\"י","bt":"תקד","dt":"תקצא","dp":"סלונים","b":"חתן ר יצחק איזיק בן ישראל מפינסק ובריסק."},{"i":4002,"n":"אליעזר","f":"פנחס","k":"אבי הבעל שם טוב","b":"איש החסד-ת\"נ"},{"i":4003,"n":"אליעזר","b":"מגדולי הראשונים-שנת ד'תת\"ל"},{"i":4004,"n":"אליעזר","f":"שמעון","b":"מגדולי תלמידי הישיבה של ר יצחק הלוי אסיר התקוה בשנת קד"},{"i":4005,"n":"אליעזר","f":"מנחם"},{"i":4006,"n":"אליעזר","f":"אוריה או עיירי","b":"חיבר ספר משלים. נזכר אצל רב סעדיה גאון."},{"i":4007,"n":"אליעזר","f":"זאב וולף","k":"בעל דמשק אליעזר","b":"רב ברוסיה. חיבר \"דמשק אליעזר\" - פאריצק תקן."},{"i":4008,"n":"אליעזר - אחי הרא\"ש","f":"יחיאל","b":"אחיהם של הרא\"ש, ושל ר חיים. נפטר צעיר בן 27. ר יהודה בן הרא\"ש העיד שהיה גדול בתורה כאחיו הרבנים."},{"i":4009,"n":"אליעזר או עזריאל","f":"יחיאל","b":"מחכמי אשכנז-ן'. נזכר בפסק רבני שפירא שיעמוד לדין על סכסוך שהיה לו. ובין החותמים ר יצחק בן מאיר מדורא."},{"i":4010,"n":"אליעזר אלנטסי מספרד וקושטא","b":"ממגורשי ספרד, עבר לקושטא. נזכר בספרי חכמי דורו."},{"i":4011,"n":"אליעזר בר מגרבוביץ","dt":"תקפג","b":"תלמיד ר שמחה בונם מפשיסחא, והיה ה\"נואם\" במשלחת הידועה של פשיסחא ל\"חתונת אוסטילא\". גיסו של ר מרדכי יוסף מאיזביצא. עבר מגרבוביץ לטומשוב-לובלסק."},{"i":4012,"n":"אליעזר גאגוס מספרד","f":"משה","b":"מחכמי ספרד-רמד. חיבר סדר מנהגים לכבוד ר יצחק בן ישעיה הכהן."},{"i":4013,"n":"אליעזר גר צדק מאשכנז וספרד","b":"הכומר המוודה של הקיסר לודוויג בן קרל הגדול ששמו היה בודא, התגייר-ד'תקעה וניתן לו השם אליעזר, והקיסר הגן עליו והצליח לברוח לספרד והיה מחכמי ישראל בסרגוסה-ספרד."},{"i":4014,"n":"אליעזר גרשון מקושטא","b":"רב בקושטא-שנות ה-ת'."},{"i":4015,"n":"אליעזר דן מלוצון","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":4016,"n":"אליעזר הגדול","b":"השם \"הגדול\" ניתן לחכמי אשכנז שלא רצו להיקרא \"גאון\" מתוך כבוד לחכמי בבל. היו כמה חכמים שנקראו בשם זה - בארצות יוון ובאשכנז."},{"i":4017,"n":"אליעזר הגדול","f":"משלם","b":"אביו ר משלם כנראה בן ר משה בן ר איתיאל. רב בשפירא בזמן ר קלונימוס הזקן. מתלמידיו: ר שמואל החסיד, ר שמריה בן מרדכי משפירא. אחיו של ר דוד השתדלן (בזמן גזירות תתנו). בנו - ר טוביה בעל \"לקח טוב\"."},{"i":4018,"n":"אליעזר הגדול מאשכנז או יוון","f":"יצחק","b":"מחכמי אשכנז או יון-ד'תתמח. חיבר פירוש לש\"ס. בניו: ר טוביה-מחבר הפסיקתא, ר יהודה אבי ר אליעזר."},{"i":4019,"n":"אליעזר הגדול ממגנצא","f":"יצחק הגדול","k":"בעל ספר הצוואות","b":"נכד ר יהושע החסיד בן ר אבין הגדול. אחר שנתייתם גדל אצל קרובו ר שמעון הגדול (ר יצחק אבי ר שמעון היה אחיו של ר יהושע זקנו של ר אליעזר). תלמיד ר שמעון הגדול, ר יהודה ליאונטין הכהן. חברו של רבינו גרשום מאור הגולה. מגדולי לותר, מחכמי צרפת הקדמונים בזמן רב האי גאון, דיין אצל רבו ר יהודה ליאונטין. ראש ישיבת מגנצא-ד'תתכ. מתלמידיו: ר יצחק בן יהודה ממגנצא, ר יצחק הלוי מורמייזא-רבו של רש\"י, ר יצחק בן מנחם, ר יצחק בן קלונימוס, ר שמואל בן יהודה הכהן, ר משלם בן ר משה (שרצה לנהוג באבלות על זקנו והיה מחלוקת על כך ור אליעזר מנע ממנו). נזכר בפירוש רש\"י, ר יוסף קרא. חיבר סליחה ליום כיפור קטן. חיבר צוואה לבנו ובגלל שהתחילה במעשה פטירת ר אליעזר בן הורקנוס היו שחשבו שכל הצוואה היא מהתנא ר אליעזר ובאמת מר אליעזר הגדול, ונדפסו עם פירוש \"ארחות חיים\" לאדמור מראדזין ר גרשון העניך (שהיה בדעה שהמחבר הוא ר אליעזר בן הורקנוס). בנו - ר יצחק החסיד-אביו של ר קלונימוס הזקן משפירא אביו של ר שמואל החסיד אביו של ר יהודה החסיד בעל ספר חסידים, יש אומרים שבנו גם ר טוביה בעל \"מדרש לקח טוב\" - וכנראה הוא בנו של ר אליעזר אחר."},{"i":4020,"n":"אליעזר הזקן מניקופול","b":"מחכמי ניקופול-ש'. נזכר בשו\"ת מהרש\"ל עם חכמי אבילונד."},{"i":4021,"n":"אליעזר הכהן הרופא משלוניקי","bp":"קאטאנסאדו-ספרד","dt":"שצח - יז אלול","dp":"שלוניקי","b":"רופא מאנוסי ספרד, ברח לקאטאנסארו-קאלבריה-איטליה, חזר ליהדות והיה רופא בשלוניקי."},{"i":4022,"n":"אליעזר הכהן מאשכנז","f":"יעקב","b":"חותנו של ר אלעזר בעל \"הרוקח\" המזכירו בספרו, תשובה ממנו בתשובת בעל התוספות ובשערי דורא - בשם ר אלעזר מברין."},{"i":4023,"n":"אליעזר הכהן מבודילסב","b":"רב בודיסלב-תק\"ל"},{"i":4024,"n":"אליעזר הכהן מחברון","b":"מחכמי חברון ממקימי ישיבת מגן אבות בשנת תקץ, שליח חברון בשנים תריד - תריח."},{"i":4025,"n":"אליעזר הכהן מטוטשין","f":"שמחה","dt":"שעב - יז טבת","dp":"טוטשין - אוסטרהא","b":"רב קדוש ונערץ. אב\"ד טוטשין, וביקש להיקבר באוסטרהא הסמוכה. המהרש\"א נהג לעלות על קברו מדי שנה."},{"i":4026,"n":"אליעזר הכהן מיאסווין וירושלים","dt":"תרה-ו - ג כסלו","dp":"ירושלים","b":"רבה של יאסוין(=יאסווין), עלה לירושלים ולמד סנדלרות כדי להתפרנס מיגיע כפו. בנו - ר יצחק מיכל אליהו הכהן מירושלים."},{"i":4027,"n":"אליעזר הכהן מלבוב","f":"ראובן","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה."},{"i":4028,"n":"אליעזר הכהן מליוורנו","b":"רב בליוורנו-תמ. תשובה ממנו ב\"שמש צדקה\". נזכר בשו\"ת \"מים רבים\" למהר\"ר מילדולה. מתורתו ב\"קול עוגב\". מכתב אליו מר טוביה הרופא בעל \"מעשה טוביה\" ששלח אליו מירושלים. חתם-תנט על מכתב תמיכה בר משה חגיז - המני\"ח."},{"i":4029,"n":"אליעזר הכהן ממדרוש","dt":"תנו - כו כסלו","b":"רב במדרוש"},{"i":4030,"n":"אליעזר הכהן מסופיה","f":"מאיר בן אברהם מסופיה","b":"גביר בסופיה-שנות ה-ת'-תק'."},{"i":4031,"n":"אליעזר הכהן מפודהייץ","b":"רב בפודהייץ."},{"i":4032,"n":"אליעזר הלוי מאזמיר","b":"רב באזמיר-תכח."},{"i":4033,"n":"אליעזר הלוי מאיטליה","b":"בנו - ר יהודה מינץ מפדובה."},{"i":4034,"n":"אליעזר הלוי מאשכנז-ראבי\"ה","f":"יואל","k":"ראבי\"ה - אבי אסף","bt":"ד'תתק-כ","dt":"ד'תתקפה - בערך","b":"נכד-(בן בתו) הראב\"ן ותלמידו, תלמיד ר אליקים בן יוסף ממגנצא, דודו - ר שמואל בן נטרונאי, משה הכהן ממגנצא, יהודה בן קלונימוס ממגנצא(=ריב\"ק), אליעזר בן שמשון מקולוניא ועוד. מגדולי הפוסקים הראשונים-ד'תתקן ונחשב לאחד מעמודי ההוראה באשכנז, רב בוורמייזא, מיץ, בונא, קולוניא, שפירא, רגנשבורג. חיבר \"אבי העזרי\" (אבי - ר\"ת אליעזר בן יואל), \"אבי אסף\", פירושים ותוספות ותשובות. חיבר גם פיוטים. מכונה גם \"הרא\"ה\" - בהגהות מיימוניות. מתלמידיו: ר יצחק בעל \"אור זרוע\", ר גרשום בן יעקב הגוזר, ר דוד בן שאלתיאל, ר שלמה הכהן, ועוד. מבניו: ר יואל הזקן. אחיו - ר אורי - נהרג עק\"ה-ד'תתקעו. מצאצאיו - ר מרדכי בן הלל בעל \"המרדכי\"."},{"i":4035,"n":"אליעזר הלוי מבוכניה","b":"אב\"ד בוכניה-תרנא."},{"i":4036,"n":"אליעזר הלוי מהורדנא","f":"יחזקאל הלוי מהורדנא","dt":"תריג - ה אד\"א","dp":"הורדנא","b":"נכד(-אבי אמו) ר הלל פריד. מו\"צ בהורדנא."},{"i":4037,"n":"אליעזר הלוי מהעלשניא","b":"מחדושיו בספר \"עדות ביהוסף\" קטן."},{"i":4038,"n":"אליעזר הלוי מסופיה","f":"משה","b":"גביר בסופיה-שנות ה-ת'-תק'."},{"i":4039,"n":"אליעזר הלוי מספרד","b":"רב בספרד לפני הגירוש. אביו של ר אברהם בעל \"משרא קטרין\"."},{"i":4040,"n":"אליעזר הלוי מפינסק","b":"ר\"מ בפינסק-תק\"נ"},{"i":4041,"n":"אליעזר הלוי מפרשבורג","dt":"תרז - יז טבת","dp":"פרשבורג","b":"מחכמי פרשבורג, נפטר צעיר."},{"i":4042,"n":"אליעזר הלוי מקולוניא","f":"נתן","k":"בעל גזירות תתנו","b":"יש אומרים שהוא המחבר \"גזירות תתנ\"ו\", ויש אומרים שהוא מראב\"ן."},{"i":4043,"n":"אליעזר הפייטן","f":"שלמה","b":"תלמיד ר\"ת והרשב\"ם. פייטן - חיבר \"האל יגלה חסד\" שאומרים בסליחות."},{"i":4044,"n":"אליעזר הקליר השני מספרד","k":"בעל כבוד ה'","b":"מקובל מחכמי ספרד ופרובנס. יתכן ושמו קליר ע\"ש עירו קליר באיטליה או סרדיניה. נזכר בריב\"ש."},{"i":4045,"n":"אליעזר הרופא מקיוסטנדיל","f":"צבי","b":"רופא מחכמי קיוסטנדיל-תקס, תמך בקרובו ר יהודה מנוח ן סיד."},{"i":4046,"n":"אליעזר התוכן","k":"בעל גיא חזיון","b":"חיבר \"גיא חזיון\"-שיט, על חכמת הכוכבים והתכונה."},{"i":4047,"n":"אליעזר זאב הכהן מסעגעד","f":"שלמה שמואל","b":"דיין בסעגעד-תרמו אצל ר אברהם חיים לעף."},{"i":4048,"n":"אליעזר זוסמן הכהן","f":"יצחק","b":"מחכמי חברון, בשנת תקמב חתם על אגרת שליחות ר אברהם ישראל זאבי. בשנת תקמח על מכתב בקשת עזרה של קהילת חברון"},{"i":4049,"n":"אליעזר זוסמן מהאלעש","k":"בעל ספר המקנה","b":"אב\"ד האלעש."},{"i":4050,"n":"אליעזר זוסמן מפרשבורג","dt":"תקפג - ט תמוז","dp":"פרשבורג","b":"סופר סתם מחכמי פרשבורג."},{"i":4051,"n":"אליעזר זוסמן מקאמין","f":"יצחק","b":"תלמיד וסופר ר מנחם מנדל מויטבסק, ועלה עמו לארץ-תקלז, והו\"ל את ספרו \"פרי הארץ\". בנו ר משה."},{"i":4052,"n":"אליעזר זשמודסקי מזאמוט","b":"זכה למדליה מהצאר על עזרתו בזמן מלחמת נפוליאון."},{"i":4053,"n":"אליעזר חב\"ת (חנינא בן תרדיון)","b":"בנו - ר יהודה מוילנא היסו\"ד."},{"i":4054,"n":"אליעזר חזן","k":"מראשוני בעלי התוספות","b":"מראשוני בעלי התוספות. רבו של רבינו שמואל החסיד"},{"i":4055,"n":"אליעזר חיים","dt":"קח","b":"מגדולי חכמי אשכנז"},{"i":4056,"n":"אליעזר חיים מאשכנז","f":"אליעזר","b":"מחכמי אשכנז בזמן מהר\"ם רוטנבורג ותלמידיו. תשובה ממנו בשו\"ת מהר\"ם מינץ (וכתב שמצא תשובתו בתוך תשובות ישנות). ונזכר ב\"אור זרוע\"."},{"i":4057,"n":"אליעזר טודרוס משלוניקי","dt":"רפז","b":"משורר מחכמי שלוניקי. חברו של ר שמואל אלמושנינו."},{"i":4058,"n":"אליעזר יהודה הלוי מירושלים","f":"משלם","dt":"תרד - תרך - תרל","b":"מחכמי ירושלים, חתם עם גדולי ירושלים. בשליחות בחו\"ל ונפטר בשליחותו."},{"i":4059,"n":"אליעזר יעקב הלוי מגרובין","dt":"תרסט - כב כסלו","b":"ר\"מ בגרובין, רב בצייטעווע"},{"i":4060,"n":"אליעזר יעקב מבורשטין","b":"רב בבורשטין-תרמז."},{"i":4061,"n":"אליעזר ירוחם מרדושיץ","f":"ישראל יצחק מראדושיץ","b":"רב ברדושיץ"},{"i":4062,"n":"אליעזר ירושלמי","b":"רב בירושלים-שמז, וחתם בתקנת המס ונזכר ב\"כתר תורה\", ועוד."},{"i":4063,"n":"אליעזר ירמיה מטישוביץ","f":"אליקים גץ","b":"רב בטישאוויץ"},{"i":4064,"n":"אליעזר לאזי מיעמניץ","f":"פנחס מטריבטש","b":"אב\"ד יעמניץ-מורביה."},{"i":4065,"n":"אליעזר ליזר מאיגרא","f":"נתן מאיגר","b":"רב באשכנז-קע. נזכר בשו\"ת מהרי\"ל, ועוד."},{"i":4066,"n":"אליעזר ליזר מבונבורג","b":"מחכמי אשכנז-ן' נזכר במנהגי מהר\"ם מרוטנבורג שהיה מרבותיו של המהר\"ם."},{"i":4067,"n":"אליעזר ליזר מברלין","f":"זליג גנץ בישיטץ מפרג","b":"מראשי הקהילה בברלין-תע, והיה מתומכי ר מרדכי ראנבאך בזמן המחלוקת אודות ביהכ\"נ בברלין."},{"i":4068,"n":"אליעזר ליזר משטרליץ","b":"ש\"ץ ושו\"ב ומו\"ץ רנזיבורג(=רנדסבורג)-ליד אלטונא על מקום ר יעקב פוזן, ור זאב פאהן מהמבורג על מקומו אחריו."},{"i":4069,"n":"אליעזר ליטמן (ליפמן) מטרספולי","f":"דוד","k":"בעל מעגלות אור","bt":"תקעה","dt":"תרמג - ז חשון","b":"אב\"ד טרספולי(=טרעספולי), רב בבריסק."},{"i":4070,"n":"אליעזר ליפא","f":"מאיר","b":"חתן ר לוי יצחק מברדיטשוב. חתנו - ר משלם זלמן פרנקל מבוקרשט."},{"i":4071,"n":"אליעזר ליפא מזבארז וצילץ","f":"פנחס אלימלך","b":"חתן ר צבי הירש בושקא מאה\"ו. רב בצילץ, זבארז."},{"i":4072,"n":"אליעזר ליפא מלאפאחאי","k":"אבי ר אלימלך מליזנסק","dt":"יט אדר","b":"צדיק נסתר בלאפאחאי"},{"i":4073,"n":"אליעזר ליפמן אשכנזי","f":"יעקב אשכנזי טמערליש","b":"רב,מקובל-תל. הו\"ל ספר אביו \"ספרא דצניעותא דיעקב\"."},{"i":4074,"n":"אליעזר ליפמן הכהן מארה\"ב","f":"יונתן בנימין-נפש יונ","bt":"תרעא","bp":"סעליש","dt":"תשג","b":"תלמיד ר יוסף נחמיה קורניצר מקראקא, ר יוסף צבי דושינסקי, ר שאול ברוך מקאשוי, ר הלל וינברגר מסערדאהלי. נסמך מאת: ר דוד מייזלש מאויהל, ר מנחם ברודי מקאלעף, ר יקותיאל ליכטנשטין מבאלקאן, האדמור ר יצחק איזיק מספינקא. חתן אחיו - ר צבי הכהן מדערטשקא. היגר לארה\"ב- וכיהן כר\"מ בישיבת \"תורה ודעת\" בניו יורק, רב קהלת \"אגודת אחים\" בניו יורק, מנהל ישיבת ר דוד ליבוביץ בפלטבוש. חבר אגודת ישראל."},{"i":4075,"n":"אליעזר ליפמן מבריגל","b":"רב בבריגל-תקצג."},{"i":4076,"n":"אליעזר ליפמן מדומברובה","dt":"תרלב - בערך","dp":"ירושלים","b":"רב בדומברובה. עלה לירושלים."},{"i":4077,"n":"אליעזר ליפמן מוולשיסק","f":"אברהם יעקב ישראל","b":"דיין בליסא."},{"i":4078,"n":"אליעזר ליפמן מזאמושט","f":"מנחם מנלי","k":"בעל לקח טוב","b":"רב בזאמושט-ת\"מ. חיבר גם פירוש על מסכת אבות."},{"i":4079,"n":"אליעזר ליפמן מזולקוא","f":"צבי הירש","dt":"תעו - יט סיון","dp":"זולקוא","b":"מחכמי זולקוא, חתם-תנב על בחירת ראשי העדה, ועוד."},{"i":4080,"n":"אליעזר ליפמן מטימישואר","f":"בנימין זאב","k":"בעל עץ החיים - בכת\"י","r":"רב בקהילה הספרדית בטמשוואר","dt":"תקכח-א -יז תשרי","dp":"טימישואר","b":"רב הקהלה הספרדית בטימישואר-תקג. ניסח עבור קהילת מאקווא את תקנות החברא קדישא-תקח, סידר גט מסובך עבור ביה\"ד בקרלסבורג-תקיח.","bk":[["עץ החיים - בענייני קבלה (כת\"י)",""]]},{"i":4081,"n":"אליעזר ליפמן מליסא","k":"בעל משנת ר אליעזר","b":"רב בצילץ-תק\"ל-תקנ\"ד"},{"i":4082,"n":"אליעזר ליפמן מסטרליסק","b":"אב\"ד סטרליסק. הסכים על שו\"ע זולקוא תקב עם ביה\"ד של זולקוא."},{"i":4083,"n":"אליעזר ליפמן מפרג","dt":"תנד - ז סיון","b":"דיין בפרג,רב בטפליץ,קאלין,בומסלא"},{"i":4084,"n":"אליעזר ליפמן מפרשבורג","dt":"תקכז - טו ניסן","dp":"פרשבורג","b":"דיין בפרשבורג בבית דינו של ר משה לבוב."},{"i":4085,"n":"אליעזר ליפמן מקובלנץ","f":"יצחק בנימין וולף-נחל","b":"נכד ר אליעזר ליפמן מגטינגן. אב\"ד קובלנץ-תפה, הסכים על \"יפה מראה\" לגיסו ר מיכל חסיד, ועל \"יד כל בו\"-תפז."},{"i":4086,"n":"אליעזר ליפמן מרסטיצקי","dt":"תקכז - כב אדר","b":"חתן ר יעקב חריף מלעשנוב. רב ברסטיצקי"},{"i":4087,"n":"אליעזר ליפמן סגל","b":"רב שנות ה-ש', חתן המהר\"ם מלובלין. (לברר?)"},{"i":4088,"n":"אליעזר ליפמן סגל מלבוב","f":"עקיבא","bt":"שעט","dt":"תיא - ז שבט","dp":"לבוב","b":"מחכמי לבוב."},{"i":4089,"n":"אליעזר ליפמן סגל מלבוב","f":"יהודה ליב","k":"בעל טל אורות?","b":"דיין בלבוב, חתם-תפח עם ר חיים יהודה ליב איטינגא, וחתם-תץ ו-תקג. לדעת ר יוסף לוינשטין הוא המחבר \"טל אורות\" - וינה תקנב (ראה ר אליעזר ליפמן אלטשטט מברודי)."},{"i":4090,"n":"אליעזר מאוסטילא","f":"יוסף מראדוויל","b":"רב באוסטילא-תר\"מ"},{"i":4091,"n":"אליעזר מאוסטרהא","f":"משה","dt":"תקי - א אלול","dp":"אוסטרהא","b":"מחכמי אוסטרה, אולי אביו של ר יעקב מאוסטרהא נכד ר יקותיאל מלודמיר."},{"i":4092,"n":"אליעזר מאוסטרהא","f":"צבי הירש","dt":"תקסא - כא כסלו","dp":"אוסטרהא","b":"מחכמי אוסטרהא. בנו ר יוסף משה מקומרנא. (סופר עליו כי במלחמה עם הרוסים בראשות-סוברוב-תקנב שצרו על העיר - יצא ר אליעזר (שהבין רוסית) אל הרוסים שעמדו להתחיל לירות בתותחים אל העיר, והראה להם דרך לבוא אל העיר וכך הציל את בני העיר מהמלחמה - ועל כך במגילה-ז תמוז תקנב)."},{"i":4093,"n":"אליעזר מאוסטרווצי","k":"בעל אמרי שפר","b":"דרשן,רב באוסטרווצי"},{"i":4094,"n":"אליעזר מאורליאנס","b":"תלמיד רבנו תם. נזכר ב\"אור זרוע\"."},{"i":4095,"n":"אליעזר מאזאריץ ובוחוב","b":"רב באזאריץ,בוחאוו חדש"},{"i":4096,"n":"אליעזר מאלכסנדריה","f":"חלפון","b":"מחכמי אלכסנדריה-ה'א. נזכר אצל ר יוסף סמברי."},{"i":4097,"n":"אליעזר מארה\"ב","f":"שמואל","k":"בעל סדר התפלות","b":"רב ומדקדק באמריקה. חיבר \"סדר התפלות\" נ\"י תקפו."},{"i":4098,"n":"אליעזר מאשכנז","f":"שמואל","b":"מחכמי אשכנז. אחיו של ר ברוך ממגנצא. נזכר בשו\"ת צ\"פ, ובתקנות שו\"מ-ד'תתקף (יש האומרים שהכוונה לרא\"ם בעל היראים - וכנראה שטועים)."},{"i":4099,"n":"אליעזר מאשכנז","f":"שלמה","b":"מחכמי אשכנז. אחיו של ר יצחק. תלמיד ר יצחק בעל \"אור זרוע\", ואולי גם תלמיד מהר\"ם מרוטנבורג. מתלמידיו: ר חיים פלטיאל, ר חיים אור זרוע. מתשובותיו ב\"מרדכי\", בשו\"ת מהר\"ם החדשות, ועוד."},{"i":4100,"n":"אליעזר מאשכנז","f":"יצחק","b":"מחכמי אשכנז-ק'. תשובה ממנו בשו\"ת מהר\"ם מרוטנבורג (אולי הוא ר אליעזר מברונא)."},{"i":4101,"n":"אליעזר מבויסק","dt":"תקעב - י אדר","b":"רב בבויסק"},{"i":4102,"n":"אליעזר מבורגונדיא","f":"אהרן","k":"בעל שער הפנים","b":"מגדולי חכמי בורגונדיא(=בורגוניא)-ד'תתק\"נ. נזכר ב\"ארחות חיים\", בשו\"ת הרמ\"ה - אחד מ-6 החכמים שאליהם פנה בדבר הרמב\"ם. יתכן והוא ר אליעזר מטול. לדעת צונץ הוא המחבר \"שער הפנים\" שנזכר אצל שד\"ל."},{"i":4103,"n":"אליעזר מבוריסוב","b":"רב בבוריסוב"},{"i":4104,"n":"אליעזר מביהם","f":"יצחק","b":"תלמיד רבינו תם, מגדולי בעלי התוספות, מרביץ תורה בביהם, פרג, ביקר גם ברוסיה. מתלמידיו: ר אברהם בעל \"ערוגת הבשם\", ר משה בן יעקב מביהם."},{"i":4105,"n":"אליעזר מבלגנצי - באנגוסי","b":"תלמיד רשב\"ם. מגדולי הפרשנים הקדמונים, מחכמי צרפת בבלגנצי-ד'תתקנ. חיבר פירוש לתנ\"ך. נדפס מאמר בשם \"מבוא לפרושי ר\"א מבלגנצי\" לאחד החכמים."},{"i":4106,"n":"אליעזר מבלגרד","f":"דניאל","b":"רב בבלגרד-תקמח."},{"i":4107,"n":"אליעזר מברודי","dt":"תסב - ה אייר","b":"דיין בברודי"},{"i":4108,"n":"אליעזר מברונא","b":"מחכמי מעהרן-קן. נזכר ב\"שערי דורא\". אולי שמו אליעזר חיים."},{"i":4109,"n":"אליעזר מבריסק","f":"יעקב אליעזר","b":"גביר מחכמי וילנא. חתן נכדת הרמ\"א וסייע בהוצאת שו\"ת הרמ\"א-ת'."},{"i":4110,"n":"אליעזר מברסטוביץ","b":"רב בברסטוביץ. חתנו - ר דוד בעל \"גליא מסכת\""},{"i":4111,"n":"אליעזר מגריידינג","b":"תלמיד ר אברהם יהושע השל מאפטא."},{"i":4112,"n":"אליעזר מדובנא","f":"העשל מקרקא","b":"רב בדובנא"},{"i":4113,"n":"אליעזר מדולינא","f":"שלמה","k":"ר' אליעזר הגדול","dt":"תרכב - יט שבט","b":"מתלמידי החוזה מלובלין, ור צבי הירש מזידיטשוב. רב בדולינא, קולומייא."},{"i":4114,"n":"אליעזר מדינבורג","b":"רב בדינבורג"},{"i":4115,"n":"אליעזר מדיסנא","b":"עלה לארץ בשיירת תקלז או סמוך לכך."},{"i":4116,"n":"אליעזר מהורדנא - א","b":"רב בהורדנא. חתנו ר שאול - רב באוסטרין-תקס."},{"i":4117,"n":"אליעזר מהורדנא - ב","f":"צבי הירש","k":"בעל מהדורה קמא על הש","bt":"תפב","dt":"תקנא - כא כסלו","dp":"הורדנא","b":"נכד-אבי אמו ר משה בן הגביר ר יעקב אליעזר קצין מוילנא-פרנס ועד המדינות. רב באורלא ובנו ר תנחום על מקומו אחריו, אב\"ד הורדנא על מקום ר משה יהושע הורביץ ור בנימין ברוידא על מקומו אחריו, סירב לרבנות מזריטש. חיבר \"מהדורא קמא ובתרא על הש\"ס - בכת\"י, ועוד. הסכים על \"צורת הבית\" תקמט. בנו ר תנחום. מנכדיו: ר בערעלע בונעס בעל \"פעולת שכיר\", ור הירש בעל \"זרע גד\"."},{"i":4118,"n":"אליעזר מהלברשטט וירושלים","f":"יהודה ליב","dt":"תריג - כה שבט","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":4119,"n":"אליעזר מהלברשטט ושאכטיץ","b":"רב בשאכטיץ. ישב כדיין בבחירת ר אברהם וינר לרב בעיר חדש - עם ר יוסף צבי סגל מל\"ב מוערבוי, ור יוסף בן אשר מוערבוי."},{"i":4120,"n":"אליעזר מוורמייזא","f":"יצחק","b":"מגדולי הראשונים בוורמייזא-ד'תת\"מ"},{"i":4121,"n":"אליעזר מוילנא","b":"רב בוילנא. בעל תוקע אצל הגר\"א. נזכר ב\"עליות אליהו\". בנו - ר ישראל מזארעצע."},{"i":4122,"n":"אליעזר מוילנא","f":"שלמה מטיקטין","dt":"תקם - יד סיון","dp":"וילנא","b":"מחכמי וילנא."},{"i":4123,"n":"אליעזר מוילנא","f":"חיים בן חיים","dt":"תקסה - יח אד\"ב","dp":"וילנא","b":"מחכמי וילנא, נקבר לצדו של בעל רביד הזהב. חתנו - ר משה רוקח מוילנא."},{"i":4124,"n":"אליעזר מוילנא (ליפשיץ)","f":"גרשון מנדל או יהודה","dt":"תקטז - כא כסלו","dp":"וילנא","b":"דיין בוילנא, ומראשי הקהלה, חתם-תפח עם דייני וילנא. (שם אביו גרשון או גרשם או יהודה)."},{"i":4125,"n":"אליעזר מוירונא","f":"שמואל","k":"בעל תוספות ותשובות","b":"מגדולי ראשוני בעלי התוספות,מרביץ תורה בוירונא-ד'תתק\"נ. מתלמידיו - ר אביגדור כץ. נזכר ב\"שבלי הלקט\"."},{"i":4126,"n":"אליעזר מוירונא","b":"מגדולי הראשונים-שנת מ'"},{"i":4127,"n":"אליעזר מוערבלוב והורדנא הקדוש","f":"שלמה","dt":"ד סיון","b":"מחכמי וורבלוב(-וערבלוב), הורדנא. נהרג עק\"ה."},{"i":4128,"n":"אליעזר מורמייזא ולבוב","f":"מנוח","k":"ליזר מורמייזא","b":"נכד(-אבי אמו) ר אליעזר משלעטשטט. חתן ר קלמן מוורמייזא ולבוב. רב בוורמייזא-ש', מחכמי לבוב (כנראה עבר עם חותנו מוורמייזא ללבוב). תשובה ממנו בשו\"ת הרמ\"א. בנו - ר מאיר ונכדו ר אליעזר ליפמן מוורמייזא."},{"i":4129,"n":"אליעזר מזאגער","f":"יהודה ליב מגורזד","b":"רב בזאגער. אחיו - ר ברוך בנדיט מגורזד. בנו - ר ישכר בער גברונסקי."},{"i":4130,"n":"אליעזר מזאלבין","f":"דוד פינס","b":"רב בזאלבין"},{"i":4131,"n":"אליעזר מזולקוא","f":"חיים","b":"חתם-תסא על תקנות זולקוא בלבוב."},{"i":4132,"n":"אליעזר מזולקוא","f":"אברהם","dt":"תקמב - ב אדר","dp":"זולקוא","b":"ר\"מ בזולקוא."},{"i":4133,"n":"אליעזר מזיטומיר","k":"בעל פרקי הנאזר.","b":"תלמיד וסופר ר זאב וולף מזיטומיר. שו\"ב בזיטומיר."},{"i":4134,"n":"אליעזר מזלוטשוב הזקן","b":"חתנו - ר יהודה מפאטיק. אחיו - ר יחיאל מיכל מנמירוב?."},{"i":4135,"n":"אליעזר מזלוטשוב הנכד","f":"יהודה מפאטיק","b":"נכד ר אליעזר הזקן-אבי אמו. בניו: ר יצחק מיברוב, ר יעקב שברשינר."},{"i":4136,"n":"אליעזר מזסקוביץ","f":"מנשה","b":"רב בזעסקוביץ-תר\"כ"},{"i":4137,"n":"אליעזר מחמלניק","b":"רב בחמעלניק-תס\"ג"},{"i":4138,"n":"אליעזר מטוך","f":"אפרים","k":"בעל תוספות טוך","dt":"נא","b":"תלמיד ר יחיאל מפאריס, ר שמואל בן שלמה מפאריס, מהר\"ם מרוטנבורג, ר אביגדור הכהן, דודו-אחי אמו ר חזקיה בן יעקב (המכונה מהרי\"ח), ר אהרן מרגנשבורג. מאחרוני בעלי התוספות, ראש ישיבת צרפת, הרביץ תורה בטוך-נורמנדי, רב בקלוניא(=קלן). ערך וקיצר את תוס' תלמידי הר\"י ובהם תוס' שאנץ, והוסיף להם מחדושי רבני איברא ושאר גדולים שהיו לפניו - והוא המקור לרוב התוספות הנדפס כיום בש\"ס. חיבר גם \"גליון התוספות\" והוא הגהותיו והוספותיו על התוספות. ב\"הגהות אשרי\" מכונה בשם פרישת מהר\"א (פרישה הוא שם נוסף לתוספות). חיבר גם פיוטים. כנראה היה גם רופא."},{"i":4139,"n":"אליעזר מטול","f":"[אהרן]","b":"תלמיד ר\"י בעל התוספות. מגדולי בעלי התוספות. אחיו של ר אברהם מטול. בניו: ר אהרן מרגנשבורג, ור יהודה. אולי הוא הפייטן ר אליעזר בן אהרן שמפיוטיו במחזור ויטרי. אולי הוא ר אליעזר מבורגניא."},{"i":4140,"n":"אליעזר מטולטשין","k":"ר' אליעזר הקדוש","dt":"תח - יא תמוז","b":"עק\"ה,רב בטולטשין"},{"i":4141,"n":"אליעזר מטומשוב","b":"רב בטאמשוב-תק\"ל"},{"i":4142,"n":"אליעזר מטומשפיל","b":"תלמיד הבעשט, ומבני החבורה של ר יעקב יוסף בעל \"תולדות יעקב יוסף\"."},{"i":4143,"n":"אליעזר מטרשקו","f":"עמנואל","k":"בעל ספר הויכוח","b":"רב בטרשקו-מב. אחיו של ר יהושע. בנו ר עמנואל ומצאצאיו ר יצחק די לטאש בעל \"שערי ציון\". חיבר ספר הויכוח כנגד תלמידו שנשתמד (ונקרא פול) וחיבר ספרים נגד היהדות, ור מרדכי בן יוסף חיבר על כך \"מחזיק האמונה\". נזכר ב\"ארחות חיים\"."},{"i":4144,"n":"אליעזר מטשען","f":"ישראל","b":"נכד המגיד מזלטושוב. חתן ר דב בער מטולשטין. נפטר בחיי אביו."},{"i":4145,"n":"אליעזר מיאסי וירושלים","dt":"תרי - ו כסלו","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":4146,"n":"אליעזר מיוון","f":"יהודה בן אליעזר הגדו","b":"נכד ר אליעזר הגדול מיוון. מחכמי שלוניקי. נתפרסם כבעל גילוי אליהו. בזמן גזירת ד'תתנו (מלחמת מסעי הצלב) חשב עם אחרים שזוהי מלחמת גוג ומגוג והגאולה קרבה."},{"i":4147,"n":"אליעזר מירושלים","f":"שמואל החסיד אשכנזי","k":"דמשק אליעזר","dt":"תקכא","dp":"ירושלים","b":"עלה לירושלים והקים ישיבה \"דמשק אליעזר\", החידא משבחו על נדיבותו."},{"i":4148,"n":"אליעזר מירושלים","f":"נסים","dt":"תרנז","dp":"ירושלים","b":"מחכמי ירושלים"},{"i":4149,"n":"אליעזר מלבוב","b":"רב בלבוב-ש\"ל"},{"i":4150,"n":"אליעזר מלבוב","f":"אביגדור","dt":"תכד - ח אייר","dp":"לבוב","b":"ר\"מ בלבוב. נהרג עק\"ה."},{"i":4151,"n":"אליעזר מלבוב","f":"מנשה","dt":"שנב - ל סיון","dp":"לבוב","b":"רב בלבוב."},{"i":4152,"n":"אליעזר מלבוב","f":"יוחנן ברוך מיונה","dt":"תלב - א אלול","dp":"לבוב","b":"ממשפחת יונה הלביא (קיקניס) בלבוב. רב ורופא בלבוב. אחיו - ר שמחה דוקטור."},{"i":4153,"n":"אליעזר מלבוב","f":"שמואל","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה יחד עם אחיו שלמה."},{"i":4154,"n":"אליעזר מלבוב","f":"אליהו ד\"ש","dt":"תכד - יד אייר","dp":"לבוב","b":"ר\"מ בלבוב. נהרג עק\"ה עם אחיו ר יצחק."},{"i":4155,"n":"אליעזר מלבוב","f":"אשר","dt":"תכד - ח אייר","dp":"לבוב","b":"ר\"מ בלבוב. נהרג עק\"ה."},{"i":4156,"n":"אליעזר מלבוב","f":"במוהר\"ח","b":"רב בלבוב, חתם-תנה עם ר פנחס משה, ר\"י יאזלוויצר, ר חיים מאך מצוזמיר, ועוד."},{"i":4157,"n":"אליעזר מלבוב - ב","f":"אשר","dp":"לבוב","b":"רב ור\"מ בלבוב."},{"i":4158,"n":"אליעזר מלובלין","f":"משה","dt":"תקסב - טו אד\"ב","dp":"לובלין","b":"ראב\"ד בלובלין. חתם בפנקס ביהכ\"נ - ר צבי הירש בר משה דאקטאר."},{"i":4159,"n":"אליעזר מלובמעלא","b":"רב בלובמעלא-ת\"ס"},{"i":4160,"n":"אליעזר ממגנצא","f":"נתן","k":"ראב\"ן","bt":"ד'תתנ","dt":"ד'תתקל","b":"מבעלי התוספות, תלמיד חותנו ר אליקים בן יוסף, ר קלונימוס בן יהודה ממגנצא, ר יעקב - יעבץ הלוי. ראש חכמי דורו, פוסק פייטן, מרביץ תורה במגנצא. חיבר שו\"ת, \"צפנת פענח\", \"אבן העזר\", פירוש התפילה, ועוד. חתניו: ר יואל הלוי בן יצחק מבונא-אבי ראבי\"ה, ר שמואל בן נטרונאי הי\"ד, ר אורי, ר אליקים. מצאצאיו הרא\"ש (לא ידוע כיצד). אחיו של ר חזקיה. נזכר בתוס' - כר אליעזר הזקן.","bk":[["ראב\"ן / אבן העזר (צפנת פענח)",""]]},{"i":4161,"n":"אליעזר ממונטינו","b":"מחכמי איטליה-רן. בנו - ר קלמן ממנטובה."},{"i":4162,"n":"אליעזר ממינסק","b":"מג\"מ בקובנה,מינסק-תקע\"ב"},{"i":4163,"n":"אליעזר ממיץ","f":"שמואל","k":"רא\"ם - בעל ספר יראים","b":"מגדולי בעלי התוספות, תלמיד רבנו תם, ר חיים הכהן בן חננאל מפאריס, רב במיץ-ד'תתקפ, מגנצא. חיבר תוספות על הש\"ס, ספר יראים, ועוד. בנותיו נפטרו בחייו. סתם ר אליעזר בתוספות הכוונה בדרך כלל אליו. מתלמידיו: ר אליעזר בעל הרוקח, ר אליהו הכהן-ממנו הגהות על ספר יראים, ר שמחה בן שמואל משפירא, ראבי\"ה, ר ברוך בן שמואל ממגנצא, ר שמואל בן ברוך מבונבורג, ר יונתן בן יצחק מוירצבורג. פיוט ממנו במחזורים (חתום - אליעזר בן שמואל - וכנראה ממנו)."},{"i":4164,"n":"אליעזר ממיקלוש","b":"רב במיקלוש-תק\"פ"},{"i":4165,"n":"אליעזר מנחם משלוניקי וארטא","bp":"שלוניקי","b":"תלמיד מהר\"ם קלעי, רב בארטא-שנות ה-ת', ור משה יעקב על מקומו אחריו."},{"i":4166,"n":"אליעזר מנייטרא","b":"דומ\"צ בנייטרא-תקפ\"א"},{"i":4167,"n":"אליעזר מניישטט-אוסטריה","b":"תלמיד בעל \"תרומת הדשן\". רב בניישטט-ליד וינה. היה במחלוקת עם ר מיישטרליין יחד עם חבריו ר יוזמאן ור יוקליין. נזכר ב\"תורת חטאת\" לרמ\"א."},{"i":4168,"n":"אליעזר מנירנברג","f":"אליקים","dt":"קח - כג כסלו","b":"רב בנירנברג. נהרג עק\"ה עם בני עדתו בשנת הגזירות-קח."},{"i":4169,"n":"אליעזר מנעשוויז","b":"אב\"ד נעשוויז-תקלח, ונזכר בפרענומעראנטען על החומש של משה מנדלסון."},{"i":4170,"n":"אליעזר מסוסנוביץ","b":"רב בסוסנוביץ"},{"i":4171,"n":"אליעזר מסופיה","f":"אברהם","b":"רב בסופיה-שנות ה-ת'."},{"i":4172,"n":"אליעזר מסטניסלבציק","b":"רב בסטניסלבציק."},{"i":4173,"n":"אליעזר מספרד","f":"שמואל","b":"זקנו של הרד\"ק, שהזכירו בספרו ספר הברית."},{"i":4174,"n":"אליעזר מפולין","f":"מנחם מאניש","k":"בעל פתח עינים","b":"מחכמי פולין-ש'. חיבר \"פתח עינים\" ובו מראי מקומות מספר הזהר. נזכר ברמ\"א."},{"i":4175,"n":"אליעזר מפולנאי","b":"חתן ר ישראל יהודה מלעטשוב בן ר אברהם דב מחמלניק. רב בפולנאי."},{"i":4176,"n":"אליעזר מפינטשוב","f":"יהודה","k":"בעל משנת ר אליעזר","bt":"תכ","dt":"תצ","b":"מנהיג למדינת פולין קטן, פרנס דגליל קראקא, רב בחמלניק, ראב\"ד בפינטשוב-תע. חיבר פירוש לתנ\"ך \"דמשק אליעזר\"."},{"i":4177,"n":"אליעזר מפינסק","k":"בעל כרם חמד","b":"רב בפינסק-תק\"ב"},{"i":4178,"n":"אליעזר מפלאגי וטרויש","f":"שמשון","b":"מחכמי טריויש-קן. תשובה ממנו ב\"מרדכי\", נזכר ב\"מנהגי טריויש\" לר מנחם חזן. חיבר פיוטים ונכנסו למחזור."},{"i":4179,"n":"אליעזר מפפד\"מ","b":"רב בפפד\"מ-שכ\"ה"},{"i":4180,"n":"אליעזר מפרובנס","f":"חיים","b":"רב בפרובנס-ס'. חתם עם הרשב\"א על החרם נגד הפילוסופיה לצעירים מגיל 25, ונזכר ב\"מנחת קנאות\"."},{"i":4181,"n":"אליעזר מפרובנס","f":"זכריה","b":"מחכמי פרובנס-דתתקל. נזכר ב\"שערי ציון\" לר\"י דלטאש, מאירי."},{"i":4182,"n":"אליעזר מפריוויש","b":"תלמיד ר יחיאל מפאריס. נזכר ב\"ארחות חיים\"."},{"i":4183,"n":"אליעזר מפרמישלא וזולקוא","b":"דיין בפרמישלא. חתם-תמא על תקנה מועד ירוסלב עם ר יעקב בהר\"ש מקראקא, ר יהודה אברהם הלוי, ר יצחק כהנא מבריסק, ר קלונימוס בן ר משה הקדוש מפוזנא, ר מרדכי כהנא מוילנא."},{"i":4184,"n":"אליעזר מצילץ","b":"רב בצילץ-תק\"י"},{"i":4185,"n":"אליעזר מצרפת","f":"שלמה","b":"תלמיד רבנו תם. מגדולי חכמי צרפת,ד'תתקנ. ואולי הוא ר אליעזר משאץ."},{"i":4186,"n":"אליעזר מקאטה","dt":"תקפ - ה תמוז","b":"רב בקאטה"},{"i":4187,"n":"אליעזר מקאסווי","dp":"קיידן","b":"רב בקאסווי. מחותן עם ר משה דרשן בן בעל בית הלל, בנו - ר יצחק איזיק מקרוז."},{"i":4188,"n":"אליעזר מקובנא","b":"דרשן,מגיד בקובנה-תק\"ע"},{"i":4189,"n":"אליעזר מקולומיאה","f":"מאיר","dt":"תרכז","b":"רב בקולומיאה."},{"i":4190,"n":"אליעזר מקולוניא-אשכנז","f":"שמשון","b":"תלמיד קרובו הראב\"ן, ריב\"א. מבעלי התוספות, פוסק, פייטן, מרביץ תורה בקולוניא(=קלן)-ד'תתק. מתלמידיו - ראבי\"ה. תשובותיו בספרי חכמי הדור."},{"i":4191,"n":"אליעזר מקופישוק","b":"אב\"ד קופישוק. פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג."},{"i":4192,"n":"אליעזר מקופישוק ושאוולי","k":"בעל בית לוי","b":"רב בשאוולי-עד תקעה. חיבר גם \"תורת הבית\"."},{"i":4193,"n":"אליעזר מקינון","f":"יוסף מקינון","dt":"סו-פג - ב תשרי","dp":"צרפת","b":"נכד ר נתנאל מקינון. תלמיד גיסו רבינו פרץ. אחיהם של ר נתנאל השני ור יעקב. מגדולי חכמי צרפת, מרביץ תורה בקינון. נהרג עק\"ה בגזירות-פב (או סו) יחד עם אחיו. חיבר פסקים ופירושים תלמידו ר אשתורי הפרחי בעל \"כפתור ופרח\" מזכירו בספרו. היה במחלוקת אודות כתובת אשת אביו עם כמה חכמים ובהם ר שמשון מקינון, עד שהגיע אל הרשב\"א שהכריע בדין."},{"i":4194,"n":"אליעזר מקיקינדע","b":"רב בקיקינדע"},{"i":4195,"n":"אליעזר מקראקא","k":"בעל אסירי התקוה","b":"דיין בקרקא-ת\"צ"},{"i":4196,"n":"אליעזר מקרוז' ווילנא","f":"יצחק איזיק","dt":"תקכט - א אב","dp":"וילנא","b":"רב בקרוז' על מקום אביו. הובא לוילנא ללמד את ר שמואל בן אביגדור - חתנו של היסו\"ד שהיה לימים האב\"ד האחרון בוילנא. מתורתו בספר תלמידו \"הדרת זקנים\" - בכת\"י. בתו - אסתר נהרגה עק\"ה-תקסד בשובה מבית העלמין בוילנא. בניו - ר אברהם אבלי מולנא, ר משה מצייקישוק. אחיו - ר יהושע מדיסנא, ר עוזר מבורבירשוק."},{"i":4197,"n":"אליעזר מראסיין","b":"מתורתו ב\"יד אליהו\" - תקצב."},{"i":4198,"n":"אליעזר מרבטשיק","dt":"שנט - כה אד\"ב","b":"דרשן בפרג"},{"i":4199,"n":"אליעזר מרוסק","b":"מחכמי פולין-ש'. נזכר ב\"צמח דוד\"."},{"i":4200,"n":"אליעזר משאנץ ופלישא","b":"מבעלי התוספות. תלמיד הרשב\"ם, חתנו ותלמידו של ר שמשון מפלישא. רב בפלישא על מקום חותנו. נזכר ב\"ספר הישר\" שרבנו תם כותב לר שמשון על חתנו שבלבל וצירף דברי \"רבינו זקני ורבנו אחי\" וכו'."},{"i":4201,"n":"אליעזר משברשין","f":"יהושע","k":"בעל דמשק אליעזר","b":"חיבר \"דמשק אליעזר\" חדושים על תורת חטאת - וילהמשדורף תעח."},{"i":4202,"n":"אליעזר משדליץ","b":"מ\"מ בסערנאק,שדליץ-תק\"ל"},{"i":4203,"n":"אליעזר משה הכהן מקושטא","b":"דיין בקושטא-תקיא אצל ר מאיר יצחקי עם ר אברהם בן שמואל יהודה, עלה לירושלים. חתם על מינוי ר אליקים גירון לרב באדרינופול."},{"i":4204,"n":"אליעזר משה מלובלין","f":"יעקב קופל","dt":"תקפח - יט אלול","dp":"לובלין","b":"מחכמי לובלין. ראה גם: אברהם בן יעקב קופל מלובלין."},{"i":4205,"n":"אליעזר משולח מוילנא","f":"אליהו בן הלל מוילנא","k":"לייזר שירווינדט","bp":"שירווינט","dt":"תרכד - כ שבט","dp":"וילנא","b":"הגיע משירווינט לוילנא ועבד כמשולח אצל הגביר ר זלמן ר אורי'ס מוילנא. גביר מחכמי וילנא, גבאי בחברות שונות וגבאי צ\"ג למעלה מ-18 שנה. תרם למעלה מ40,000 רובל לצדקה."},{"i":4206,"n":"אליעזר משערשוב","b":"רב בשארשוב-תקעג. בנו - ר דוד."},{"i":4207,"n":"אליעזר נחום מאדרינופול","f":"יעקב נחום","k":"בעל חזון נחום","bt":"תא-תיג-תכב","bp":"קושטא או אדרינופול","dt":"תצג - תקה","dp":"ירושלים","b":"תלמיד ר יעקב שטרימר באדרינופול(=אינדירני), ראש ישיבה ורב בקהלת פורטוגל באדרינופול-תכג, עלה לירושלים-תצא-ה עם אשתו ונתמנה לרב הכולל על מקום ר בנימין מעלי ור נסים חיים משה מזרחי על מקומו אחריו. מחבריו ר יצחק זרחיה אזולאי אבי החיד\"א. חתם-תצז על תקנת העזבונות והחזקות, בשנת תקא על כתב שליחות ר אברהם בן אשר ור יצחק זרחיה אזולאי. חיבר \"חזון נ חום\" - קושטא תקצה, ועוד רבים בכתב יד. בנו חורגו היה ר אברהם בן רפאל קארו מצאצאי ר יוסף קארו, חתנו - ר יצחק תמה מחברון, רב הכולל בירושלים-תצב. מתלמידיו ר בנימין קזיס בעל \"מגילת ספר\", החיד\"א. (לפי רוזניס תאריך פטירתו - תקיח?)"},{"i":4208,"n":"אליעזר ניישטאדטער","f":"גרשון","b":"תלמיד חכם, עסקן ציבור ושתדלן בליטא (ניישטאדט?) בזמן הגר\"א. בשליחות אצל קיסרי רוסיה פבל ואלכסנדר."},{"i":4209,"n":"אליעזר ניסן מדארנא-ואטרא","b":"חתן ר יחיאל פפר מיעזערזאני. רב בדארנא-ווטרא-תרע."},{"i":4210,"n":"אליעזר פישל מסטריזוב","k":"בעל עולם הגדול","bt":"תק בערך","dt":"תקעב - טו כסלו","b":"מקובל, רב בסטריזוב, מגיד בברוד. חיבר גם \"עולם אחד\", \"עולם הפוך\", ועוד.","bk":[["עולם אחד",""],["עולם ברור",""],["עולם הגדול \\ מדרש לפירושים",""],["עולם הפוך",""],["קונטרס העברונות \\ עולם ועד",""],["פרשת אליעזר – קרנים \\ דן ידין",""]]},{"i":4211,"n":"אליעזר צבי מניקלשבורג","b":"מו\"צ בניקלסבורג"},{"i":4212,"n":"אליעזר צבי קב ונקי מירושלים","f":"מרדכי מהורדנא","dt":"תרלה - ט אייר","dp":"ירושלים","b":"מחכמי ירושלים, חתום על שטרי כוללות ופשר החלוקה עם הספרדים בשנת תרל."},{"i":4213,"n":"אליעזר ש\"ח מנורצי","dt":"תקפט","b":"רב פרנס ומוהל בנורצי."},{"i":4214,"n":"אליעזר שלום מפיעטרקוב","b":"רב בפיעטרקוב-תרכ\"ו"},{"i":4215,"n":"אליעזר שלום מפרצוב","b":"רב בפרצוב-תרס\"ז"},{"i":4216,"n":"אליעזר שלום מצפת","b":"מגדולי חכמי צפת-ר\"צ"},{"i":4217,"n":"אליעזר ששון משלוניקי","b":"מגדולי חכמי שלוניקי"},{"i":4218,"n":"אליעזר תודרוז משלוניקי","b":"מחכמי שלוניקי-רס. נזכר בספרי חכמי דורו ובהם שו\"ת \"בנימין זאב\"."},{"i":4219,"n":"אליעזרוב, שלמה יהודה ליב מחברו","f":"אליעזר שמעון קזרנובס","r":"ראב\"ד ומנהיג קהילת חב\"ד והאשכנזים בחברון","bt":"תרכ-ג","dt":"תשיב","b":"מצאצאי הרבנית מנוחה רחל סלונים מחברון. חתן ר דב בער הלוי אשכנזי מקליסק-ה\"חוזר\" של הצמח צדק. עלה עם הוריו-תרלג והתישב בחברון, תלמיד ר שמעון מנשה חייקין ור אליהו מני, רב בחברון, בשליחות בארצות המזרח, ונתקבל לרב בסמרקנד. (שם משפחתו היה קזרנובסקי ושינה שמו בבוכרה לאליעזרוב - בן אליעזר). גיסו - ר מנחם מנדל נאה (היו נשואים לשתי אחיות).","bk":[["מחשבת שלמה – אגדה",""],["שאילת שלמה – שו\"ת",""],["שאילת שלמה – שו\"ת , מחשבת שלמה – אגדה",""]]},{"i":4220,"n":"אליעזרי שמואל בן אליעזר","bt":"1907","dt":"ה'תשנא 1991","bk":[["מלאכת שמואל",""],["תרומת חלה",""]]},{"i":4221,"n":"אליעזרי, דב בר מירושלים","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\"."},{"i":4222,"n":"אליעזרי, שמואל","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":4223,"n":"אליפלא ן, יוסף מספרד","b":"מגדולי חכמי ספרד בארגון,גדול בתורה ורפואה-שנת נ\"ז,מתרגם פירוש המשניות להרמב\"ם"},{"i":4224,"n":"אליקום געטשליק כץ מאלזענץ","dt":"תקפד - כד אב","b":"רב במנהיים. חתנו - ר יעקב קופל במברגר מוורמייזא. נתן כתב סמיכה לבעל \"ערוך לנר\"-תקפא."},{"i":4225,"n":"אליקום גץ מזולקוא","f":"ישראל","b":"ראש הקהלה בזולקוא-תנד, חתם פעמים רבות ובהם עם ר הלל בעל \"בית הלל\"."},{"i":4226,"n":"אליקום גצל הכהן","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":4227,"n":"אליקום מוילנא","f":"נפתלי הרץ","dt":"תקנו - כא שבט","dp":"וילנא","b":"מגיד בווילנה"},{"i":4228,"n":"אליקום מירושלים","b":"מחכמי ירושלים-שנות ה-ר'-ש'."},{"i":4229,"n":"אליקום מקופנהגן","f":"איסרל זאלדין","k":"בעל קרית ארבע","b":"חיבר \"קרית ארבע\" קופנהגן תקמז, \"שומר אמונים\" קופנהגן 1787."},{"i":4230,"n":"אליקום, יחיאל ראה","f":"יחיאל יעקב מירושלים","k":"בעל דקדוקי תורה","b":"מחכמי ירושלים-תק\"נ"},{"i":4231,"n":"אליקים","f":"יוסף בן שלמה","b":"השלים את פירוש שיר השירים לאביו."},{"i":4232,"n":"אליקים","f":"יהודה","b":"אביו של ר אורי-אבי ר יחיאל-אבי הרא\"ש. וכנראה היה חתן הראב\"ן שמזכיר בספרו \"ר אליקים חתני\"-ד'תתקיב."},{"i":4233,"n":"אליקים","f":"הרא\"ש","b":"אחד משמונת בניו של הרא\"ש, ונזכר ב\"דברי יוסף\" שהיה גדול בבית השר בעיר וכו' והחזיר בתשובה לאיש אחד וכו'. אחיו ר יהודה כותב בספרו שנמנע מלדון מפני שאחד מבעלי הדין הוא אחיו ר אליקים."},{"i":4234,"n":"אליקים","f":"מיכאל","b":"פייטן ונמצאו ממנו פיוטים."},{"i":4235,"n":"אליקים - זקנו של רש\"י","f":"אלעזר הרופא מרומי","b":"עבר מאיטליה לאשכנז. מופיע ב\"מגילת יוחסין\" כמה פעמים ושם אביו מופיע גם - שלמה, והכל משובש."},{"i":4236,"n":"אליקים געטשליק מאוסטריה","b":"מחכמי אוסטריה-רן. חיבר הגהות למנהגים של ר איזיק טירנא. תלמיד ר פיבש."},{"i":4237,"n":"אליקים געטשליק מרוטנבורג","k":"בעל גאולת הגר","dt":"ת'","b":"רב במדינת שוואבן. חיבר \"גאולת הגר\" - פרג שעח."},{"i":4238,"n":"אליקים גץ","b":"זקן ויושב בישיבה"},{"i":4239,"n":"אליקים גץ","f":"שמואל בן יחיאל איכל","b":"נינו של ר ליבר הגדול מברדיטשוב. חתן ר יוסף מיאמפולא (זלוטשוב)."},{"i":4240,"n":"אליקים גץ בן יעקב יוסף מאוסטרה","f":"ראה: ספרד, אליקים גץ"},{"i":4241,"n":"אליקים גץ בן מאיר","dt":"ה'תסה 1705","bk":[["רפדוני בתפוחים",""]]},{"i":4242,"n":"אליקים גץ הכהן מביסטריץ","b":"רב בביסטריץ-תק\"צ"},{"i":4243,"n":"אליקים גץ מאוסטרהא","f":"יעקב יוסף - ייבי","dt":"תקפד - כו אלול","dp":"אוסטרהא","b":"צדיק באוסטרהא ועסק כל ימיו בצדקה וחסד - למרות היותו חי חיי צער ודוחק כל ימיו, אב ליתומים ותומך דלים, היה משגיח מטעם עצמו על המדות והמשקולות בשוק וגם הנכריות שם היו יראות ממנו והיו מסתירים את המדות שלהם מדי עוברו. נפטר בצעירותו. מתורתו בשו\"ת \"מים חיים\". הו\"ל ספר אביו \"רב ייבי\". הניח בת אחת. (מסופר ממנו כי פעם הגיע מגיד לעיר ולא שלמו לו והחל לקלל את הבעלי בתים ור אליקים אמר לו אתה גרוע מבלעם - שהוא לקח כסף על הקללות וברך בחינם ואתה הפוך)"},{"i":4244,"n":"אליקים גץ מאוסטרהא","f":"יחיאל מיכל מאוסטרהא","dt":"תקמח - כח אב","dp":"אוסטרהא","b":"נכד ר אליקים גץ. פרנס באוסטרהא-תקיד."},{"i":4245,"n":"אליקים גץ מאמשטרדם","b":"רב באמשטרדם. תשובה ממנו ב\"חכם צבי\". בנו - ר שלמה שריגים. הגיה משניות מנוקדות - אמשטרדם."},{"i":4246,"n":"אליקים גץ מברוידא וקידאן","f":"שלמה זלמוני מוילנא","dt":"תסב","dp":"קידאן","b":"רב בקידאן על מקום ר הלל בעל \"בית הלל\" ובנו ר יהושע השל על מקומו אחריו. נזכר אצל החכם צבי בתשובותיו. הסכים על שערי שמים לקרובו - ר יחיאל מיכל מקאליש-תלה. (לא יתכן שאביו הוא המופיע באוצר הרבנים - שהיה ממשפחת ר חיים מוולוזין)"},{"i":4247,"n":"אליקים גץ מלאסק - הנכד","f":"מאיר הילדסהיים מלוסק","dt":"תק - טז חשון","b":"נכד ר אליקים גץ מפוזנא. רב בלוסק-תצח על מקום אביו. נפטר צעיר. אחיו - ר ישעיה. בנו - ר מאיר ונכדו - ר ישעיה מפשדבורז."},{"i":4248,"n":"אליקים גץ מליברטוב","b":"רב בליברטוב"},{"i":4249,"n":"אליקים גץ מעגערסעג","b":"רב בעגערסעג-תקס\"ד"},{"i":4250,"n":"אליקים גץ מפוזנא-הזקן","f":"מאיר מדנהויזן","k":"ר' מרדכי","b":"אחיהם של ר יעקב טעמרל ר ליב חנהליס, מהרל\"ח, ר עקיבא מהאצי פלאטץ. דיין בפוזנא-תנ-תעה. בנו ר מאיר מפוזנא ופילא ונכדו ר אליקים גץ בעל \"אבן שהם\". חתנו - ר שלמה זלמן אוירבך מפוזנא."},{"i":4251,"n":"אליקים גץ מקאזין","f":"יעקב יוסף מאורזיסטשו","k":"אדמור מאורזיסטשוב","dt":"תרנה - טז ניסן","b":"חתן ר אליקים געץ מאוסטרהא, ובזיוו\"ש חתן ר חיים יצחק מיאנוב (ליבישוב). אדמור באורזיסטשוב וקאזין. חיבר \"אמרי אמת\"."},{"i":4252,"n":"אליקים גץ מקמינקא","f":"דוד מרבינו","k":"אדמור מקמינקא","dt":"תקמה","b":"תלמיד הבעשט - אחד מ\"האחים הקדושים מקמינקא\". אודותיו בספר נכדו ר בן ציון בוגולמני \"החיים והברכה\"."},{"i":4253,"n":"אליקים גץ מראצקי","f":"זאב וואלף אלטשולר","k":"בעל ארץ חמדה","b":"מ\"מ ומו\"צ בראצקי-תק\"מ"},{"i":4254,"n":"אליקים גץ מראקוב","dt":"תקיח - ו טבת","b":"אב\"ד ראקוב, רב בקראקא. חתנו - ר יהודה ליב בן אליהו מראקוב. ונכדו - ר יהושע."},{"i":4255,"n":"אליקים גץ משוורזנץ - הזקן","f":"מאיר מפוזנא","k":"בעל אבן השהם","dt":"תע - בערך","dp":"פוזנא","b":"תלמיד ר אברהם ברוידא מפפד\"מ. רב בשוורזנץ-תלט, הילדסהיים, רב בלוסק-תע ובנו ר מאיר על מקומו אחריו?, עלה לארץ ובדרכו בפוזנא התעכב לבקשתם כדיין ונפטר שם. בניו: ר מאיר הילדסהיים מלוסק הו\"ל את ספר אביו עם הקדמה ממנו, ר זנוויל, ר ישעיה מפשדזבורז, חתנו - ר רפאל בן משה מוילנא."},{"i":4256,"n":"אליקים גצל מביאליסטוק","b":"אב\"ד ביאליסטוק-שנות ה-תר."},{"i":4257,"n":"אליקים החזן","f":"שלמה","b":"פייטן ומשורר-קן ופיוטים ממנו במחזור."},{"i":4258,"n":"אליקים הכהן מאשכנז","b":"מחכמי אשכנז-ן. נזכר בספר אחיינו \"ספר חסידים הקטן\" לר משה הכהן, ונזכר בשו\"ת מהר\"ם מרוטנבורג."},{"i":4259,"n":"אליקים הלוי מאשכנז וקורפו","b":"מחכמי אשכנז שהתישבו בקורפו. רב בקורפו-ר' בזמן ר גרשון בונפונצי, והיה מחלוקת ביניהם. מחותן עם ר\"י מינץ ונזכר בתשובותיו. מתלמידיו: ר בנימין בן מתתיה בעל \"בנימין זאב\" ומזכירו בספרו."},{"i":4260,"n":"אליקים הלוי משפיירא","f":"משלם","k":"בעל פיוט אות ברית","b":"חברו של רש\"י. מגדולי מרביצי התורה בשפיירא-ד'ת\"ת. חתנו - ר יצחק בן אשר - הריב\"א. חיבר פיוט לברית מילה \"אות ברית\"."},{"i":4261,"n":"אליקים הלוי משפירא","f":"אשר","b":"מחכמי שפירא-ד'תתקן. אחיו של ר יצחק בן אשר(=ריב\"א הלוי) שנהרג עק\"ה. חתום עם חבריו ר שמחה ור נתן בן יצחק משפירא על פסק דין ונזכר בראבי\"ה."},{"i":4262,"n":"אליקים הלוי משפירא","f":"קלונימוס","b":"מחכמי אשכנז-ד'תתל, חברו של רש\"י ותלמיד ר\"י בן יקר, ור יצחק הלוי שהיו רבותיו של רש\"י. חיבר פירוש לתלמוד (ונדפס על הש\"ס חלק מפירושו בשם רגמ\"ה ובאמת הוא ממנו), יש אומרים שהפירוש המיוחס לרש\"י לנזיר ובכורות הוא ממנו או מר יצחק בן יהודה. חתנו - ר יצחק בן אשר(=ריב\"א הלוי) בעל התוספות."},{"i":4263,"n":"אליקים הפרנס מקושטא","b":"רב בקושטא-ד'תתקלו, נזכר אצל ר בנימין מטודילא."},{"i":4264,"n":"אליקים חזקיה","f":"יאיר","b":"נכד הרמב\"ם. חיבר פיוט-ר' - \"אתיתי מרבבות קדש\" ב\"אילימה ירושלים\"."},{"i":4265,"n":"אליקים מאשכנז","f":"ברוך","b":"השיב לו ר אפרים בן נתן ממגנצא, ונזכר במרדכי."},{"i":4266,"n":"אליקים מלונדון","f":"אברהם","b":"מקובל ומדקדק. חיבר עשרה מאמרות בחכמות ומחקריות ומהם נדפסו בלונדון ובהם: \"מלחמות ה'\", \"צוף נובלות\", ועוד."},{"i":4267,"n":"אליקים ממאציראנטה","b":"פסק ממנו ב\"פחד יצחק\" בענין יבום."},{"i":4268,"n":"אליקים ממגנצא","f":"יוסף","k":"ר' אליקים ממגנצא","bt":"ד'תתל","dt":"ד'תתקה-תתקיב","b":"רב במגנצא-ד'תתן בזמן רש\"י, ובזמן ר קלונימוס בן יהודה ממגנצא. חותנו של הראב\"ן. נזכר במגלת ר אפרים מבונא שבניו ר יצחק ור אליקים, ובנו ר יצחק נהרג עק\"ה בוירצבורג עם יהודים רבים-ד'תתקו, ור חזקיה אחיו קנה את מקום קברם והפכו לבית קברות."},{"i":4269,"n":"אליקים ממציראטא-איטליה","f":"ישעיה משה","b":"רב בפיסא-ש'. נזכר בהקדמת זהר מנטובה - שקבלו ממנו כת\"י של הזהר. תשובהו ממנו ב\"פחד יצחק\"-שלג."},{"i":4270,"n":"אליקים מפולין","f":"נפתלי","k":"בעל טוב שם","b":"רב ומקובל בפולין-שן. חיבר \"טוב שם\", \"אבן שתיה\". בנו ר יוסף הו\"ל את ספרו \"טוב שם\" - ונציה שסו."},{"i":4271,"n":"אליקים מפיסארו","f":"ישעיה משה","b":"מגדולי חכמי דורו,מרביץ תורה בפיסארו-של\"ג"},{"i":4272,"n":"אליקים מפרשבורג המכונה ויבלמאן","f":"קלונימוס","b":"חתן ר חיים הי\"ד. רב בפרשבורג-רמד, וחתם על זכרון עדות."},{"i":4273,"n":"אליקים מצרפת","f":"מנחם","b":"מגדולי הראשונים בחכמי צרפת-עג. חיבר פירוש על התורה. תלמידו ר יהודה בן אלעזר בעל \"מנחת ריב\"א\" מביא מתורת רבו."},{"i":4274,"n":"אליקים מקלון(=קולוניא)","b":"מחכמי אשכנז-ה'א. נזכר ב\"הגן\"."},{"i":4275,"n":"אליקים מרנדענג","dt":"תרסג - כו שבט","b":"רב בראנדענג. חתנו - ר משה שמואל הרצוג משטאמפי בעל \"קורות בתינו\"."},{"i":4276,"n":"אליקים משלוניקי","f":"שמעיה","dt":"שג - טו אדר","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":4277,"n":"אליקים משפירא","dt":"קח","b":"מחכמי שפירא. נהרג עק\"ה בגזירות קח."},{"i":4278,"n":"אליקים, אברהם מדמשק","b":"מחכמי דמשק-שסא, עלה לארץ והתישב בעזה. הגיה את \"כסף נבחר\" לר יאשיהו פינטו."},{"i":4279,"n":"אליקים, אברהם מסופיה","b":"רב בסופיה--שע, יחד עם ר ישראל בן יעקב, בזמן ר אסטרוק ן שאנג'י."},{"i":4280,"n":"אליקים, חיים יוסף מסופיה","b":"רב בסופיה-תקן."},{"i":4281,"n":"אליקים, חנניה די ריאטי מאיטליה","k":"בעל מנחת חנניה","bt":"שכ","dt":"שפג","b":"תלמיד ר יהודה מוסקאטו. פייטן וש\"צ, מגדולי חכמי מנטובה, מחכמי ירושלים ואחיו של ר ישראל אליקים. נזכר בשו\"ת \"אהלי יעקב\" לר יעקב קאשטרו. אולי הוא מחבר \"מקיץ רדומים\" מנטובה תח."},{"i":4282,"n":"אליקים, יום טוב מסופיה","bt":"תקל","bp":"סופיה","dt":"תרו - טז תשרי","dp":"ירושלים","b":"רב בסופיה, עלה לצפת-תקעג והיה מורו של ר חיים אברהם גאגין(=אג\"ן). משם עבר לחברון ויצא בשליחות לאדרינופול בשנת תקסו. חתם על כתב שליחות ר יוסף עייאש ור יעקב בורלא. בשנת תקצה נתמנה כרבה של חברון. עבר לירושלים ונספד ב\"שמש ומגן\". בנו ר רפאל ישראל מרבני חברון."},{"i":4283,"n":"אליקים, יוסף מחברון","k":"בעל חשב (וישב) יוסף","b":"מחכמי חברון, בשליחות חברון-תקפט היה באדרינופול-תריח. היה ראש בית הדין בירושלים. חיבר \"חשב יוסף\" בכתב יד."},{"i":4284,"n":"אליקים, יחיאל יעקב מירושלים","f":"ישראל חיים יוסף מסופ","k":"בעל דקדוקי תורה","bp":"סופיה או ירושלים","b":"מחכמי ירושלים-תקן, שלוניקי. חתן ר דוד מאג'ר בעל \"חסדי דוד\". חיבר \"דקדוקי תורה\" בכת\"י, בשנת תקנח הגיה והוציא לאור \"שו\"ת ר ישראל מברונא\", והוציא לאור ספרים נוספים. חיבר \"יד יעקב\" בשנת תקסה בכת\"י. מבניו - ר יעקב שאול, ר ישראל חיים יוסף."},{"i":4285,"n":"אליקים, ישראל חיים יוסף מסופיה","k":"בעל שם יוסף","bt":"1725","dt":"תקנא - א אייר","dp":"ירושלים","b":"מחכמי סופיה-בולגריה, עלה לירושלים. חיבר \"שם יוסף\" שלוניקי תקכט. (באוצה\"ס - נכתב שמו בטעות מוספיא במקום מסופיה).","bk":[["שם יוסף","מפרשי רמב\"ם"],["שם יוסף – רמב\"ם",""],["שם יוסף [על רמב\"ם]",""]]},{"i":4286,"n":"אליקים, משה מאיר חי מטבריה","f":"נסים","k":"משמ\"ח-בעל מלחמת המגן","bt":"תרלב","bp":"טבריה","dt":"תשח - תמוז","b":"מחכמי טבריה. חתן ר רפאל אוחנא. בשליחות-תרעא במצרים וצפון אפריקה ונתעכב שם בזמן מלחמת העולם ה-I. דיין במוגדור-תרעט, דיין בטבריה-תרפא, בשליחות באלגיר-תרפג, רב בקזבלקנה-תרפד.הו\"ל מספרי אביו ובהם \"דבר נאה\" ועוד ובהם גם מחדושיו שלו. היה במחלוקת עם ר חנניה חביב אזולאי - בענין היבום, ועל כך בספרו \"מלחמת המגן\" שנכתב כנגד \"מגן הדת\" לר חנניה חביב אזולאי. (יש אומרים שנפטר - תרצט). פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":4287,"n":"אליקים, נסים מטבריה","k":"בעל הדר נאה","bt":"תרי","bp":"טבריה","dt":"תרמ - כא אדר","dp":"טבריה","b":"מחכמי טבריה בסוף המאה ה-19. נפטר בגיל 30. חיבר גם \"חדר נא\"ה\" ו\"פרי נא\"ה\", \"הדר נא\"ה\" ירושלים תרעא. בנו ר משה מאיר הדפיס את חבוריו, עם תוספות משלו, והיה בשליחות במרוקו-תרעב ונשאר שם. בנו - ר משה מאיר חי-המשמ\"ח."},{"i":4288,"n":"אליקים, רפאל ישראל מחברון","f":"יום טוב","bt":"תקסה","bp":"סופיה","dt":"תרכה - יז תשרי","dp":"ירושלים","b":"מחכמי חברון, עלה עם אביו-תקעג, בשליחות בצפון אפריקה-תריא ובשנת תריט בשליחות באיטליה, היה סופר קהילת חברון. בהיותו בתונס הסכים על \"ויקן יוסף\" לר יוסף בורג'ל. תשובה ממנו בענין זכות ירושה של מומר ב\"די השיב\" לר דוד בונאן."},{"i":4289,"n":"אליקים, שלמה ממצרים","b":"מחכמי אלכסנדריה-תר בערך. מתורתו ב\"חדר נא\"ה\""},{"i":4290,"n":"אלישוב, אברהם מירושלים","k":"בעל בכורי אברהם","dt":"תשג - ד חשון","dp":"ירושלים","b":"חתן בעל הלשם. רב בהומל, עלה לירושלים-תרפד. בנו - ר שלום אלישיב."},{"i":4291,"n":"אלישיב, חיים מארה\"ב","k":"בעל מזמור לתודה","b":"רב בארה\"ב-תרמד."},{"i":4292,"n":"אלישיב, יוסף שלום מירושלים","f":"אברהם פופקא","b":"נכד בעל הלשם. מגדולי הפוסקים בדורו. (שם אביו נרשם בדרכון כשעלה לארץ - דוד שמחה)"},{"i":4293,"n":"אלישיב, יצחק משקוד","f":"שלמה-בעל הלשם","b":"מחכמי שקוד-פלך קובנא, סייע לאביו בעריכת כתביו."},{"i":4294,"n":"אלישיב, ישראל איזידור בעל מחשב","f":"שלמה זלקינד","k":"בעל סקירות ורשמים","bt":"1873","bp":"קובנא","dt":"1924","b":"תלמיד ר שמחה זיסל בגרובין. פנה להשכלה ולמד רפואה בברלין. עורך \"אידישע שטימע\" בריגה. תרגם ספרים לאידיש. חיבר גם \"אונטערן ראד\" על שנות המהפכה ברוסיה. אחותו אסתר אלישיב - סופרת ומרצה."},{"i":4295,"n":"אלישיב, שלמה","k":"בעל לשם שבו ואחלמה","bt":"תרא","bp":"זאגר-ליטא","dt":"תרפו-ח","dp":"ירושלים","b":"תלמיד ר גרשון תנחום בישיבת מינסק, תלמיד ישיבת טלז, ושאוולי. מגדולי המקובלים בליטא, רב בשאוועל, הומל-בזמן מלחה\"ע ה-I, ברדיאנסק, ליטא. עלה לירושלים-תרפד, היה ממשפחה המיוחסת לארי מצד אביו ומצד אמו, והיה מגדולי המקובלים. חיבר \"לשם שבו ואחלמה\" פיעטרקוב תרסט, ועוד. חתנו ר אברהם אלישיב. נכדו ר יוסף שלום אלישיב מירושלים. הרב קוק אמר על ספרו כי \"מימי ר משה קורדובירו לא יצא לאור ספר בקבלה כמוהו\".","bk":[["לשם שבו ואחלמה (בעל הלשם)",""]]},{"i":4296,"n":"אלישיוף, פרג'ולה מפרס","bt":"תרמט","bp":"פרס","dt":"תשב","dp":"משהד","b":"רב במשהד-פרס."},{"i":4297,"n":"אלישע","f":"אברהם","b":"הו\"ל פירוש לסדר זרעים לרא\"ש, והוסיף עליו חדושים בשם \"פי שנים\" אלטונא תצה."},{"i":4298,"n":"אלישע הכהן מוינה","f":"נחום מהוסיאטין","b":"עמד בראש ישיבת הוסיאטין בוינה על מקום אביו. עבר לניו יורק-תרצט והיה שם רב, עלה לירושלים-תשל. חתן ר נחמן זאב בירנבוים ממנוסטרישץ."},{"i":4299,"n":"אלישע הכהן מוינה","k":"סיניור מורינו","b":"גביר בקהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":4300,"n":"אלישע מהורדנא","f":"אברהם מלונטשיץ","k":"בעל קב ונקי","dt":"תקט - טו תמוז","dp":"הורדנא","b":"מצאצאי ר יוסף בעל \"שארית יוסף\"-גיסו של הרמ\"א. תלמיד ר יוסף שמואל בן צבי מקראקא ופפד\"מ. ראב\"ד בהורדנא, רב בלונטשיץ בזמן ר יעקב ששפורטש. חיבר \"קב ונקי\" - תנט, \"פי שנים\"."},{"i":4301,"n":"אלישע מפורטוגל וקושטא","f":"אברהם בן מתתיה","k":"בעל מגן דוד","b":"ממגורשי פורטוגל, חכם ומדקדק בקושטא-רעג. חיבר \"מגן דוד\" יחד עם ר שלמה אלמולי, השגות בדקדוק על \"מעשה אפוד\" - בכת\"י ומסכים עם דעות רד\"ק."},{"i":4302,"n":"אלישע מקורפו","k":"ר' אלישע מפאנו","b":"מו\"ץ בקורפו, רב במילאנו"},{"i":4303,"n":"אלישעווסקי, שמואל אריה מנ\"י","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"מגדל תורה\" - נ\"י תרפה."},{"i":4304,"n":"אלישקובסקי, יעקב","bt":"תרלב","dt":"תשו - שבט","b":"רב באלסנדרי-תרס\"ג,קיוב,עלה לא\"י תרפ\"ו"},{"i":4305,"n":"אלישר (אליסר), יוסף","b":"מחכמי ספרד נמנה בין 17 העולים הראשונים מספרד שעלו לארץ בשנת רסד, חתם על אגרת מצפת. לדעת בניהו מוצאו מהעיר ייסר שבארגון והוא אבי משפחת אליישר."},{"i":4306,"n":"אלישר הלוי פולאקו, ח'","f":"יעקב אלישר","dt":"תר","b":"מקובל,בקי בש\"ס ירושלמי,דיין בצפת,רב בחברון"},{"i":4307,"n":"אלישר יעקב שאול בן אליעזר ירחם","bt":"1817","dt":"ה'תרסו 1906","bk":[["איש אמונים",""],["יש\"א אי\"ש",""],["כבוד לאיש",""],["מעשה אי\"ש",""],["עולת אי\"ש",""],["שאל האי\"ש ופני חמ\"א",""],["שמחה לאיש",""]]},{"i":4308,"n":"אלישר, אברהם מירושלים","dt":"תע - לפני","b":"מחכמי ירושלים יחד עם בנו יוסף, ידוע כרב הראשון בעל השם אלישר. הו\"ל \"נגיד ומצוה\" לר יעקב צמח באמשטרדם-תעב."},{"i":4309,"n":"אלישר, אליהו מירושלים","f":"יצחק","bt":"תרס","bp":"ירושלים","b":"מחברי ועד העדה הספרדית, פרסם מאמרים בעתוני התקופה."},{"i":4310,"n":"אלישר, אליעזר ירוחם מירושלים","f":"יעקב שאול-ישא ברכה","dt":"תרלה - ב סיון","b":"נפטר צעיר. בנו - ר בן ציון, וחתנו - ר נסים פרנקו - בנו של החרי\"ף."},{"i":4311,"n":"אלישר, אליעזר ירוחם מירושלים","f":"חיים משה-חמ\"א","dt":"תרצז - כט אייר","dp":"ירושלים","b":"חתן ר יוסף נבון ביי."},{"i":4312,"n":"אלישר, אליעזר ירוחם מצפת","f":"יעקב מירושלים","k":"יעקב וילנא","bt":"תקלה","bp":"צפת","dt":"תקפד - יב אד\"ב","dp":"ירושלים","b":"מחכמי צפת, דיין וש\"ץ בקושטא, חזר לצפת בנו ר יעקב שאול ה\"ראשון לציון\", אחרי שעבדללה פשה מושל עכו הרג את חיים פרחי בשנת תקפ, החל לרדוף את יהודי צפת, ואסר את ר אליעזר ירוחם, בתקפג הצליח לברוח מכלאו, ואז ברח לדמשק ואחר כך לירושלים"},{"i":4313,"n":"אלישר, אלעזר מירושלים","f":"יוסף","bt":"תרמט","bp":"ירושלים","b":"תלמיד זקנו חמ\"א. למד מסחר בפאריס. פעיל צבור."},{"i":4314,"n":"אלישר, בן ציון","f":"אליעזר ירוחם","bt":"תרלד","dt":"תשך","dp":"ניו יורק","b":"גדל אצל סבו היש\"א ברכה, גדל בחברון, דיין בירושלים, רב בניו יורק-תרס\"ה, חזר לא\"י לטיפול רפואי-תש\"ח, חזר לברוקלין-תשי\"ב"},{"i":4315,"n":"אלישר, חיים יוסף מירושלים","f":"אברהם","b":"מחכמי ירושלים אבי ר' יעקב שאול. בגלל גזרות ברח לחברון, בשנת תעב בשליחות עם ר אברהם יצחק באמשטרדם, הוציא לאור \"נגיד ומצווה\" לר יעקב צמח, חזר לירושלים דרך תורכיה. סמוך לשנת תפ נשא את בתו של ר יעקב וילנא מעולי שיירת ר יהודה החסיד, היה מראשי קהילת חברון, חתם על אגרת שליחות ר יום טוב קריספו ור אברהם גדליה בשנת תפז. יצא לשליחות מירושלים עם ר אליהו בן ארחא, בשנת תץ היה בטריפולי."},{"i":4316,"n":"אלישר, חיים משה מירושלים","f":"יעקב שאול-ישא ברכה","k":"חמ\"א","bt":"תרה (תריז)","bp":"ירושלים","dt":"תרפד - ד שבט","dp":"ירושלים","b":"מחכמי ירושלים, למד אצל ר יוסף בורלא ואצל אביו ה\"ראשון לציון\", חותנו ר רפאל מאיר פאניזל. בשנת תרפב כיהן כ\"ראשון לציון\" למשך שנתיים. נציג היהודים במועצה, מגבאי ביה\"ח \"שערי צדק\", וממייסדי \"משגב לדך\", ראש ועד הרבנים הספרדים-תרעט. חדושיו בספרי שו\"ת וביניהם \"משה האיש\" ירושלים תרפא, \"כבוד לאיש\" ירושלים תרע, ו\"שאל האיש\" ירושלים תרסט.","bk":[["משה האיש",""]]},{"i":4317,"n":"אלישר, יוסף מחברון","b":"מרבני חברון-ת\"צ"},{"i":4318,"n":"אלישר, יוסף מירושלים","f":"אברהם","b":"מחכמי ירושלים, בשליחות באשכנז-תעב. הו\"ל \"נגיד ומצוה\" לר יעקב צמח."},{"i":4319,"n":"אלישר, יוסף שאול מירושלים","f":"חיים משה","k":"בעל ויוסף שאול","bt":"תרכז","bp":"ירושלים","dt":"תשח - כב סיון","b":"נכד ר רפאל מאיר פאניז'ל. תלמיד ר מנחם בכר יצחק, ר גבריאל שבתי. חתן נכדת ר חיים נסים ברוך מירושלים. מחכמי ירושלים, ועסקן ציבור. חתנו - ר משה בן אברהם בן אברהם מירושלים."},{"i":4320,"n":"אלישר, יעקב וילנא מחברון","f":"חיים יוסף ירוחם","k":"בעל מגילת פרס","bt":"תפ - אחרי","bp":"חברון","dp":"צפת","b":"מחכמי חברון, בשליחות בשנת תקיג באירופה, ובשנת תקכג בשליחות בערב ולאחר מכן בתורכיה. היה מקורב לחיד\"א, ובשנת תקלב יצאו ביחד בשליחות באירופה. בשנת תקלג בהיותו בשליחות בבגדד נפטר ר צדקה חוצין רב העיר ור יעקב נתמנה לרב במקומו. ואחר כך התיישב בצפת לשיקום הקהלה. חיבר \"מגלת פרס\", וכן ספרים וכתובים שברובם אבדו. בניו - ר משה שמואל, ר אליעזר ירוחם ונכדו היש\"א ברכה, ולפי רוזניס בנו - ר חיים (מאשתו הראשונה)."},{"i":4321,"n":"אלישר, יעקב וילנא מירושלים","f":"בנימין וולף אשכנזי","k":"בעל הגהות לתקוני זהר","bp":"וילנא","dt":"תק - אחרי","dp":"ירושלים או צפת","b":"חתן ר אביגדור קרא מאפטא (ואצל פרומקין - חתן ר ליב בן יוסף מקוברין). עלה לירושלים בשנת תס בערך - בימי עליית ר יהודה החסיד, והיה ראשון העולים ממשפחת אלישר. למד בישיבת \"ישראל יעקב פיררה\", יצא לשליחות באירופה ובהיותו בפירירה התארח אצל ר יצחק למפרונטי והסכים על ספרו \"פחד יצחק\". חזר לירושלים עם ר נתן נטע מנהיים (האגגי) מחבורת ר יהודה החסיד, וחברו ספר \"יאיר נתיב\", חיבר \"הגהות לתקוני הזהר\" ליוורנו תפח. ובמשך השנים יצא מספר פעמים בשליחות לאירופה ובאמשטרדם הדפיס \"שיטה מקובצת\" שאותו גם הגיה. חיבר \"יאיר נתיב\" בקבלה עם חברו ר נתן מנהיים = והוא ביאור לספר \"מאורי אש\". שד\"ר בפרס. בנו ר חיים ירוחם וילנא מירושלים. תאריך פטירתו ב\"יהדות ליטא\" - צפת לפני תצז. (יש בלבול בינו לבין ר יעקב בן נפתלי המכונה ר הירש ר יאקב איסרלש שהיה מגיה באמשטרדם."},{"i":4322,"n":"אלישר, יעקב שאול מירושלים","f":"אליעזר ירוחם","k":"יש\"א","r":"ראשל\"צ בירושלים - ישא ברכה","bt":"תקעז","bp":"צפת","dt":"תרסו - כח תמוז","dp":"ירושלים","b":"התייתם בגיל צעיר, אמו נישאה לראבד ירושלים ר בנימין מרדכי נבון שגדלו ולמדו. בשנת תרטו נסע לדמשק לישוב סכסוך, באותה שנה נשלח לאלכסנדריה לשנות את החלטתם שלא לקבל שדרים מארץ ישראל והצליח במשימתו. בשנת תרכט ראבד ירושלים, בתרנג התמנה לראשון לציון לאחר פטירת חותנו ר מאיר פאניג'ל. חיבר \"מעשה איש\" ירושלים תרנב, ועוד. פרסם מאמרים ב\"המאסף\" - ירושלים תרנו, מאמר ממנו ב\"תבונה\" - ירושלים תשא-תשח, \"תורה מציון\" - ירושלים תרנה-תרסה. בניו - ר חיים משה, ר אליעזר-נפטר צעיר, ר נסים בנימין מרדכי.","bk":[["איש אמונים (יש\"א ברכה)",""],["איש אמונים - דרוש",""],["דברי אי\"ש - דרוש",""],["דרך איש - דרוש",""],["ישא אי\"ש - שו\"ת",""],["מעשה אי\"ש - שו\"ת",""],["עולת אי\"ש - שו\"ת",""],["פני האיש - דרוש",""],["שאל האי\"ש ופני חמ\"א - שו\"ת",""]]},{"i":4323,"n":"אלישר, יצחק שמעיה מירושלים","f":"חיים משה","bt":"תרלג","dt":"תרצג - טו תמוז","dp":"ירושלים","b":"תלמיד \"דורש ציון\" אצל ר יצחק פראג, ר מנחם בכר יצחק. עסקן ציבור."},{"i":4324,"n":"אלישר, ירוחם מירושלים","f":"נסים בנימין מרדכי","bt":"תרמו","bp":"ירושלים","dt":"תרפא - כז אב","dp":"ירושלים","b":"מחכמי ירושלים. תלמיד ישיבת זקנו \"ישא ברכה\". רב בבגדד וחזר לירושלים. נפטר ללא ילדים."},{"i":4325,"n":"אלישר, מנשה חי מירושלים","f":"יצחק","bt":"תרסב","bp":"ירושלים","b":"עסקן צבור בירושלים."},{"i":4326,"n":"אלישר, משה שמואל מצפת","f":"יעקב מירושלים","b":"מחכמי צפת בשנת תקפד ואחר כך בעכו, אחיו של ר אליעזר ירוחם."},{"i":4327,"n":"אלישר, נסים רפאל מירושלים","f":"יעקב שאול - ישא ברכה","bt":"תריג","dt":"תרצד - יב תמוז","dp":"ירושלים","b":"תלמיד ר שבתי גבריאל. דיין בירושלים ומראשי ישיבת \"פורת יוסף\". חתן ר אברהם פנסו מירושלים. נקרא בנימין מרדכי ע\"ש אביו-חורגו של היש\"א ברכה."},{"i":4328,"n":"אלישר, רפאל יהושע מירושלים","f":"נסים בנימין מרדכי","bt":"תרכט","bp":"ירושלים","dt":"תרעב - ז טבת","dp":"ירושלים","b":"סוחר מחכמי ירושלים."},{"i":4329,"n":"אלישר-וילנא, חיים נסים ירוחם","f":"יעקב-מאורות נתן","bt":"תסג","dt":"תקלה","dp":"עירק","b":"מראשי קהילת האשכנזים בירושלים. חיבר הערות לספר \"תקוני הזוהר\" שחיבר יחד עם אביו ונדפס בשם \"הערות ימי\"ן וחיו\"ן\" קושטא תק. בשנת תקג נאלץ לצאת מהארץ בגלל חובות שירש מאביו (מחבורת ר יהודה החסיד). היה בשליחות מטעם קהילת ירושלים וכנראה גם צפת בקושטא ובוינה, עמד לימין ר יונתן אייבשיץ במחלוקתו עם ר יעקב עמדין. בשנת תקכח חזר לירושלים, וביקש לחתום בשמו כי כהו עיניו, על מכתב לקהילת מיץ על ידי השליח ר חיים אהרן בנו של ר אברהם גרשון מקיטוב. שליח בפרס וטבע בנהר החידקל בשנת תקלה. בנו ר יעקב השלים את שליחותו בערי פרס ובצרה"},{"i":4330,"n":"אלכבאש, חיים מאלגיר","bt":"תר - בערך","dt":"תרף - בערך","b":"רב בעין תמושנת-אלגיר-תרן. נזכר בהקדמה ל\"פרחי כהונה\" לר דוד ן כליפא. סייע בהדפסת \"בית שלמה\" - ירושלים תרנב."},{"i":4331,"n":"אלכולי, אברהם ממצרים","dt":"תיג","dp":"מצרים","b":"שר-ג'יליבי במצרים-שצא-תיא על מקום ר יעקב טבול ור פרץ על מקומו אחריו. נזכר במכתב ר מנשה בן ישראל לאוליבר קרומוול."},{"i":4332,"n":"אלכולי, שמואל ממצרים","k":"בעל תולדות אדם","b":"רב במצרים. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":4333,"n":"אלכורדי, אברהם","bt":"תר","dt":"תרעח","b":"מקובל, מגדולי רבני כורדיסטאן, רב בארביל"},{"i":4334,"n":"אלכלאץ, אברהם מאלגיר","f":"יהודה בן שלמה","dt":"שן - בערך","b":"אולי חתנו של ר אברהם גבישון בעל \"עומר השכחה\". רב בתלמסאן. אביו של ר יהודה."},{"i":4335,"n":"אלכלאץ, אליהו הכהן ממרוקו","f":"נחמיה","b":"מחכמי מרוקו. חתם על פס\"ד עם ר משה ן זמרא. מתלמידיו: ר שמואל ן צור, ר דוד סירירו."},{"i":4336,"n":"אלכלאץ, אפרים מפאס","f":"נחמיה","b":"מחכמי פאס, חתם על תקנה-שי, הניח חיבורים בכת\"י."},{"i":4337,"n":"אלכלאץ, יהודה הכהן מאלגיר","f":"אברהם בן יהודה בן של","k":"בעל אלף המגן","dt":"שפ","b":"נינו של ר יהודה כלץ מספרד ואלגיר, ונכד ר אברהם גבישון. תלמיד ר שלמה בן צמח מאלגיר. רופא רב ור\"מ בתלמסאן, דיין באלגיר-שנא, משורר וכתב חבורים הלכתיים בדרך שיר - \"אלף המגן\" ונדפס בחלקו בתוך \"זכות אבות\" לר אברהם קוריאט, ו\"שמע שלמה\" - לכבוד בנו שלמה - ונדפס בתוך \"זבחי אלקים\" לר לוי אסולין תונס תרע. ?? לא באוצר ??"},{"i":4338,"n":"אלכלאץ, יהודה הכהן מפאס","f":"שלמה בן יהודה","k":"בעל עיר חדשה","b":"מחכמי פאס, חתם על שטר-תקל, חתם-תקמד עם ר משה אלבאז. חיבר \"עיר חדשה\" ו\"משמרות כהונה\". אחיו של ר אהרן. אולי הוא זקנו של ר יקותיאל."},{"i":4339,"n":"אלכלאץ, יהודה מאלגיר - הנכד","f":"שלמה","k":"בעל מגיד משנה","b":"רב ודיין בתלמסאן-שעז. חיבר פירוש להלכות שחיטה לרמב\"ם בשם \"מגיד משנה\", קונטרס \"כלל בטרפות\". נכדו - ר יהודה בעל \"שמע שלמה\"."},{"i":4340,"n":"אלכלאץ, יהודה מספרד","k":"בעל ספר המפואר","b":"מחכמי המוסר-שנות ה-ר'. חיבר ספר המוסר הנקרא \"המפואר\" - קושטא רצז - עם הגהות נכדו המקובל ר משה כלץ."},{"i":4341,"n":"אלכלאץ, יהודה מספרד ואלגיר-הזק","f":"שלמה הכהן","k":"בעל משיח אלמים","bt":"ר","dt":"רע - בערך","b":"מגדולי חכמי אלגיר, מרביץ תורה. בא בצעירותו מקשטילייא לגרנדה-רלז, מאלאקא(=מלגה?)-רמב, הוניין-אלגיר-רמו (לפני הגירוש), רב בתלמסאן. מתלמידיו ר מרזוק בן עמרם ן טוואה. החזיק בספריה גדולה - ותלמידיו עסקו בהעתקת ספרי קדמונים. חיבר \"משיח אלמים\" על פירוש רש\"י לתורה - ירושלים תשמו. מיוחס לו \"ספר המוסר\" - קושטא רצז, ו\"פי יהודה\" - כת\"י. תשובות ממנו בשו\"ת מהר\"י בירב, שו\"ת המבי\"ט. מתורתו בספרי גדולי אלגיר ובהם ר יהודה עייאש - המכנהו \"אלכלאצי\". בנו - ר שלמה."},{"i":4342,"n":"אלכלאץ, יהודה מפאס","f":"אברהם","b":"רב בפאס, חתם על פס\"ד-תעד."},{"i":4343,"n":"אלכלאץ, יהודה מתלמסאן-אלגיר","b":"מגדולי חכמי דורו,רב בתלמסאן-ש\"צ"},{"i":4344,"n":"אלכלאץ, יעקב מפאס","f":"לוי","b":"תלמיד ר יהודה ן עטר. מחכמי פאס-תעה, העתיק את \"תפוחי זהב\"."},{"i":4345,"n":"אלכלאץ, יקותיאל משה הכהן מפאס","b":"מחכמי פאס."},{"i":4346,"n":"אלכלאץ, מימון מאלגיר","bt":"שי","dt":"שפ - בערך","b":"רב ודיין בתלמאסן בזמן רשב\"ץ האחרון."},{"i":4347,"n":"אלכלאץ, משה הכהן מפאס - מכנאס","f":"נחמיה","bt":"תמג","dt":"תעד - ו אלול","dp":"מכנאס","b":"רב ומקובל במכנאס (או פאס). נהרג עק\"ה-תעד יחד עם אחיו ר שם טוב בעלילה והלשנה ע\"י המלך מולאי אסמאעיל. למד בעלית ביה\"כ של ר שמואל אלבז ומאז נחשב המקום לקדוש. נזכר ב\"ראש משבי\"ר\", ואצל היעב\"ץ."},{"i":4348,"n":"אלכלאץ, משה מאלגיר וחלב","bt":"רן","dt":"שך - בערך","b":"אחיינו או נכדו ר יהודה כלץ בעל ספר המוסר. תלמיד המבי\"ט, רב באלגיר, עלה לארץ, יצא לקושטא והדפיס את ספר המוסר לזקנו או דודו - עם הערות והגהות ממנו ע\"פ תורת הנסתר. רב בעדת המסתערבים בחלב. אולי הוא הנזכר ב\"אבקת רוכל\"."},{"i":4349,"n":"אלכלאץ, משה מחמת","b":"רב קהלת הספרדים בחמת-סוריה-שנות ה-ש'."},{"i":4350,"n":"אלכלאץ, משה מקושטא","f":"אליעזר","b":"נכד ר יהודה אלכאלץ, מחכמי קושטא. הו\"ל ספר זקנו \"המפואר\" עם הגהות ותוספות ממנו - קושטא רצז."},{"i":4351,"n":"אלכלאץ, נחמיה הכהן - א","dt":"תנו - לפני","b":"מחכמי פאס. נזכר ב\"משפט וצדקה ביעקב\"."},{"i":4352,"n":"אלכלאץ, נחמיה הכהן - ב","b":"רב בפאס. נזכר ע\"י היעב\"ץ (=ר יעקב ן צור). בניו ר משה ור שם טוב נהרגו עק\"ה בפקודת המלך אסמעיל (המכונה סמאעיל = סמאל)-תרעד. חתן נכדתו - ר שמואל אלבאז מפאס שירש ממנו את חזקת שררת ביהכ\"נ בפאס."},{"i":4353,"n":"אלכלאץ, נחמיה יהודה הכהן - ג","b":"דיין מחכמי פאס-תקסא, וחתם עם ר שמואל אברהם ן זמרא, ועם ר אליהו הצרפתי ועם ר בנימין לכרייף. ונזכר אצל היעב\"ץ."},{"i":4354,"n":"אלכלאץ, רפאל הכהן מפאס","f":"נחמיה יהודה","b":"מחכמי פאס, חתם-תקצט עם ר ראובן סירירו, ועם ר יוסף אשוראקי-תקפא."},{"i":4355,"n":"אלכלאץ, שלמה הכהן מפאס-מרוקו","f":"יהודה","b":"מחכמי פאס, גלה עם משפחתו-תצח בזמן הרעב לתאפילאלת-מרוקו ולאזילא-מרוקו. תלמיד ר שמואל מייארא, ור חיים ן עטר. חיבר ספר דרושים בכת\"י. בנו - ר אהרן."},{"i":4356,"n":"אלכלאץ, שלמה מאלגיר","b":"מגדולי חכמי אלג'יר-ק\"פ"},{"i":4357,"n":"אלכלאץ, שלמה מאלגיר","f":"יהודה בן אברהם","dt":"שעד - בערך","b":"רב ודיין בתלמסאן. תשובה ממנו ב\"חוט המשולש\"."},{"i":4358,"n":"אלכלאץ, שלמה מאלגיר","dp":"צפת","b":"רב באלגיר, עלה לצפת-שנה."},{"i":4359,"n":"אלכלאץ, שלמה מאלגיר וצפת","dp":"צפת","b":"מחכמי אלגיר, עלה לצפת בשנת שנה."},{"i":4360,"n":"אלכלאץ, שלמה מסאלי","f":"מרדכי","b":"מו\"ץ בסאלי-תפח, שאלה ממנו ומחברו ר שמואל קארו - אל חכמי מכנאס."},{"i":4361,"n":"אלכלאץ, שלמה מספרד ואלגיר","f":"יהודה","bt":"רמ - בערך","bp":"ספרד","dt":"שי - בערך","b":"מחכמי ספרד, תלמיד ר יצחק אבוהב, בזמן הגירוש עבר עם אביו לתלמסאן-אלגיר וכיהן כרב וראש ישיבה. מתלמידיו: ר יוסף אלאשקר בעל \"צפנת פענח\" המזכירו בספרו, ור אברהם גבישון בעל \"עומר השכחה\" ומזכירו בספרו."},{"i":4362,"n":"אלכלאץ, שם טוב הכהן ממרוקו","f":"נחמיה","dt":"תעד - ו אלול","dp":"מכנאס","b":"מחכמי פאס, נהרג עק\"ה עם אחיו ר משה-תעד בפקודת המלך סמאעיל. היה בעל צדקות והחזיק ביד אחיו ר משה שיעסוק בתורה."},{"i":4363,"n":"אלכסדנר משדה לבן","bt":"תס","dt":"תקלג - לפני","b":"תלמיד הבעש\"ט. סופרו הראשון במשך 8 שנים, והבעשט ציוה עליו לעזוב בגלל שהיה לו \"צער גידול בנים\". שו\"ב בשדה לבן, ברדיטשוב, נמירוב. חתנו ר דב בער מליניץ בעל \"שבחי הבעשט\". נפטר צעיר ושתי בנותיו גדלו בבית הבעש\"ט והוא שהשיאם."},{"i":4364,"n":"אלכסנדר","b":"רב דמדינות וואנעפרידן"},{"i":4365,"n":"אלכסנדר","f":"יצחק","b":"נכד ר מאיר בעל \"שערי דורא\". מחכמי אשכנז-ה'ן ונזכר בספר המחכים שסיפר דבר הלכה בשם אביו שפגש את ר טוביה מצרפת וכו'."},{"i":4366,"n":"אלכסנדר הכהן מפפד\"מ","f":"יהודה","b":"מראשי קהילת פפד\"מ - בעל תואר \"מורנו\"."},{"i":4367,"n":"אלכסנדר הכהן מקובלנץ וקלן","f":"יעקב","dt":"תסד - כו תמוז","dp":"דייץ","b":"רב בקובלנץ, קולוניא, נויליך, בערג."},{"i":4368,"n":"אלכסנדר זוסלין מפפד\"מ","f":"שלמה וימפפן","k":"זיסקינד וימפען","dt":"סח - י תשרי","dp":"ורמייזא","b":"גביר מפפד\"מ. פדה את גופתו של מהר\"ם מרוטנבורג-שנפטר בשבי, תמורת סכום כסף גדול, וביקש בתמורה להיקבר לידו בוורמייזא."},{"i":4369,"n":"אלכסנדר זוסלן הכהן - מהרא\"ך","k":"בעל ספר האגודה","dt":"קח","dp":"ערפורט","b":"רב בערפורט, קלן, פפד\"מ. מכונה גם מהרא\"ך ו-מהרז\"ך. תלמיד ר יצחק בעל \"שערי דורא\" (ובאמת לא פגשו - אלא הביא מספרו), ר יצחק הלוי בעל \"פענח רזא\". נהרג עק\"ה בגזירות קח. חיבר ספר האגודה שעליו נכתבו פירושים והגהות מגדולי הדורות ובהם הגהות אשרי והגהות מיימוניות. מתלמידיו: ר שמשון ברוך שאמר."},{"i":4370,"n":"אלכסנדר זיסקינד מאונסדורף","f":"דוד קאנטשינרו","k":"בעל מצנפת בד","dt":"תקלג","b":"נכד ר אליהו מנדל. חתן ר שמואל בן עזריה זיסקינד מטורנא. דרשן נודד, מו\"ץ בטורנא, רב בווארברום-ליד קראקא, אונסדורף-תקטו ור יוסף משה שמחה רפפורט על מקומו אחריו. חיבר \"מצנפת בד\" זולקוא תקטז. בניו: ר יוסף מרדכי, ר צבי הירש מעלקוש. אחיו - ר מרדכי מזמיגרוד."},{"i":4371,"n":"אלכסנדר זיסקינד מאסווע","b":"רב באסווע-תר\"י"},{"i":4372,"n":"אלכסנדר זיסקינד מגרודנא","f":"משה","k":"בעל יסוד ושורש העבוד","r":"האדמו\"ר מאלכסנדר","bt":"תצ \\ תצד","dt":"תקנד - יח אדר","b":"חסיד ומקובל מחכמי גרודנא וסירב לרבנות. יצא לגרמניה לאסוף תרומות ונאסר שם ושוחרר. חיבר גם \"קרני אור\", ועוד. צוואתו נדפסה כמה פעמים. על קברו הונחו שתי מצבות לצד ראשו ולצד רגליו. בנו - ר אריה ליב.","bk":[["יסוד ושורש העבודה",""],["יסוד ושורש העבודה - מוסר",""],["יסוד ושורש העבודה - מוסר, קרני אור – זוהר הקדוש, צוואה יקרה",""],["צוואה יקרה",""],["קרני אור – זוהר הקדוש",""]]},{"i":4373,"n":"אלכסנדר זיסקינד מירושלים","f":"צבי הירש מאמשטרדם","bp":"אמשטרדם?","dt":"תריג","dp":"ירושלים"},{"i":4374,"n":"אלכסנדר זיסקינד מלבוב","f":"ר\"א ליב","b":"דיין בלבוב, חתם-תצ עם ר יקותיאל זלמן אפשטין, ר יהושע פאלק שור, ועוד."},{"i":4375,"n":"אלכסנדר זיסקינד מלבוב","f":"משה","b":"חתן ר יהודה דובש הנקרא ר ליב ר יהושע'ש. רב בלבוב-תקח, חתמו עמו ר אריה ליב רפפורט, ר משה מגיד, ועוד. בנו - ר יעקב גבריאל."},{"i":4376,"n":"אלכסנדר זיסקינד מלובלין","f":"יהונתן","dt":"תג - יד שבט","dp":"לובלין","b":"מחכמי לובלין."},{"i":4377,"n":"אלכסנדר זיסקינד מלובלין","f":"בנימין זאב","b":"חתם על כתב החרם של ר יעקב חיים מלובלין על היוצאים כנגד ר יהונתן איבשיץ-תקיא."},{"i":4378,"n":"אלכסנדר זיסקינד ממיץ-צרפת","f":"שמואל זנויל","k":"בעל דרך הקדש","b":"מקובל, מדקדק, מחכמי מיץ. חיבר \"דרך הקדש\" - קאטהען תעח."},{"i":4379,"n":"אלכסנדר זיסקינד מנוברדוק","dt":"תרב","b":"רב בנוברדוק"},{"i":4380,"n":"אלכסנדר מאויבן","b":"מו\"צ באויבן-תל\"ד"},{"i":4381,"n":"אלכסנדר מאפשטין","b":"מחכמי אשכנז. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":4382,"n":"אלכסנדר מדראביאן","b":"מרבני דראביאן"},{"i":4383,"n":"אלכסנדר מסטבניק","f":"צבי","b":"רב בסטבניק"},{"i":4384,"n":"אלכסנדר מפריסטיץ","b":"רב בפריסטיץ-תפ\"ה"},{"i":4385,"n":"אלכסנדר מצוזמיר","dt":"תנח","dp":"לובלין","b":"מחכמי צוזמיר. נהרג עק\"ה."},{"i":4386,"n":"אלכסנדר מקסטהעלי","b":"רב בקסטהעלי-תקע\"ה"},{"i":4387,"n":"אלכסנדר סנדר","b":"בנו ר יוסף חיים."},{"i":4388,"n":"אלכסנדר סנדר גדליה מסלופצי","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":4389,"n":"אלכסנדר סנדר וולף מדרמשטט","b":"תלמיד ר נתן מאז, ר משלם זלמן חסיד, ור אברהם טריר בפפד\"מ. דיין בדרמשטט-תקצ. העתיק את דרשת ר פנחס הורביץ בעל ההפלאה-תקמב כנגד ה\"ביאור\" של מנדלסון. בנו - הרב ד\"ר וולף - רבה של קופנהגן."},{"i":4390,"n":"אלכסנדר סנדר יעקב מוילקוטש","b":"רב בוילקוטש. תשובה אליו ב\"דבר משה\"."},{"i":4391,"n":"אלכסנדר סנדר מזבורוב","b":"שו\"ב בזבורוב. תשובה אליו בשו\"מ."},{"i":4392,"n":"אלכסנדר סנדר מסלוצק","f":"מהרא\"ם-תלמיד המג\"א","k":"ר סנדר ר חיימ'ס","b":"שם אביו אלכסנדר? בן משה בן צבי הירש. חתן ר יהודה יידל מקאוולא בעל \"קול יהודה\". פרנס ומנהיג בסלוצק. בניו - ר יוסף צייטליש(=צייטלין) מביליניץ, ר יהודה יודל מקלצק וסלוצק, ר אריה ליב מניעשויז וסלוצק."},{"i":4393,"n":"אלכסנדר סנדר מפדרבורן ווסטפליה","b":"רב אזורי בפדרבורן ובווסטפליה-גרמניה - תקלב. באזור חיו יהודים מפוזרים בכפרים קטנים ועליהם היה ממונה רב אזורי. חתם \"אלכסנדר סנדר מצ\"פ לב\"י (מצודתו פרוסה לבני ישראל) במדינת פ\"ב (פאדער בורן) וליפא (ווסטפליה)\"."},{"i":4394,"n":"אלכסנדר סנדר מצפת","f":"מרדכי","b":"מראשי הקהלה בצפת, חתם-תקץ על אגרת."},{"i":4395,"n":"אלכסנדר סנדר סגל רייז מרוזדול","bt":"תקעח או תקלה","dt":"תרסג","b":"רב ברוזדול. נכדו ר יעקב רייז על מקומו אחריו. נפטר בן למעלה ממאה שנים."},{"i":4396,"n":"אלכסנדר סנדרליין כץ מפפד\"מ","f":"יצחק","b":"רב בפפד\"מ-ש'. בנו ר ליווא כץ שחתם באגרת חכמי ישיבת פפד\"מ."},{"i":4397,"n":"אלכסנדר צבי מוואלאווע","b":"רב בוואלאווע-תר\"מ"},{"i":4398,"n":"אלכסנדר, ראובן חיים מלודז","dt":"תשג","b":"רב בטשרניכא,לודז"},{"i":4399,"n":"אלכסנדרוב, אהרן","f":"משה אלכסנדרוב","b":"שנת תר\"י"},{"i":4400,"n":"אלכסנדרוב, משה","b":"רב-שנת תק\"צ"},{"i":4401,"n":"אלכסנדרוב, שמואל מבוברויסק","b":"פרסם מאמרים ב\"בית המדרש\" - קראקא תרמח, \"מאסף דרושי\" - וילנא תרסט."},{"i":4402,"n":"אלכסנדרוביץ, פסח בן ציון","k":"בעל דעת תורה","b":"חיבר קובץ מאמרים בשם \"דעת תורה\" קובנא תרפו."},{"i":4403,"n":"אלכסנדרובסקי, ישראל שלמה זלמן","f":"יצחק איזיק משארשוב","k":"בעל זבחי שלמה","bt":"תקע","dt":"תרמז - ח טבת","b":"נכד ר יעקב \"כהן גדול\" מואלפא. שו\"ב בשערשוב. חתן ר יוסף מקמיניץ. תלמיד ר נח מלכוביץ, ר משה מקוברין, ר אברהם מסלונים, ועוד. חיבר גם \"תקוני שלמה\", \"המזכיר\", ועוד."},{"i":4404,"n":"אלכסנדרזון, יונתן הלוי מבניהאד","k":"בעל תומך כבודי","b":"הגיע מפוזן לכהן כרב בבוניהאד(=באניהאד) על מקום ר צבי הירש הלר ונתקבל - אולם הרב הלר שעבר לבודפשט לא אישר את המינוי, רב בטשאבא(=האיו-צ'אבא)-תקצד, עבר לגרמניה. היה מחלוקת כנגדו בגלל שנחשד בנטיה לרפורמה ובי\"ד רבני שלל ממנו את סמיכתו לרבנות. חיבר \"תומך כבודי\" ברלין תרה - להצדיק את עמדתו."},{"i":4405,"n":"אלכסנדרי הכהן מפפד\"מ","f":"יצחק","b":"מחכמי פפד\"מ-שכה, חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ. בניו: ר משה, ר יהודה ליווא."},{"i":4406,"n":"אלכסנדרי מאשכנז","b":"מחכמי אשכנז-ד'תת, תלמיד ר יצחק בן אלעזר הלוי וחברו של רש\"י. נזכר בספר הפרדס."},{"i":4407,"n":"אלכסנדרי, יהודה מירושלים","b":"סופר קהילת ירושלים, חתם בשנת רסט על התקנה לשחרור ת\"ח ממסים. לדעת ריבלין הוא ר יהודה סופר המוזכר במכתב ר משה בסולה משנת רפב - בן למשפחה מספרד שהתישב באלכסנדריה."},{"i":4408,"n":"אלכסנדרי, יעקב מבלגרד","b":"הגיע מתורכיה לבלגרד, מקורב לשלטון-תן."},{"i":4409,"n":"אלכרסאני, יהודה מפאס (קורצאן)","f":"יוסף","k":"בעל ארון העדות","b":"מקור משפחתו מהעיר כורסאן. תלמיד ר יוסף ן סוסאן מפאס. גדול בתורה, פילוסוף, בקי בתכונה, מחכמי פאס-שנות ה-ק'. חיבר \"ארון העדות\", פירוש על איוב - בכת\"י, חיבר מחברת \"סימני רעשים ורעמים\" על הוראת העתים מהמאורעות שתהיינה."},{"i":4410,"n":"אלמאכאני, אפרים","f":"יוסף","b":"מחכמי המזרח-ד'תתקן. פייטן ומשורר כאביו לפניו - ר יהודה אלחריזי זלזל בפיוטיהם ואמר \"שאינם במעלת חכמת השיר כלל וכלל\"."},{"i":4411,"n":"אלמאל, י' ממרוקו","b":"מחכמי מרוקו אולי במכנאס, נזכר ב\"משפטים ישרים\". (אולי הכוונה לאלמליח?)"},{"i":4412,"n":"אלמאש, מאיר ממטרסדורף","bt":"תקכח","dt":"תרב - יג כסלו","dp":"וינה","b":"תלמיד מהר\"ם ברבי, ר יוסף מפוזנא-חתנו של הנודע ביהודה. גביר ורב בבוקרשט, מטרסדורף-תקצא על מקום ר בנימין גינז (אחיו של ר עקיבא איגר) ועזב בגלל מחלוקת, וינה, ראש ישיבה באלמאש, רב באיזנשטט, בסוף ימיו עבר לטשאנגר. חתנו - ר אשר אנשל יונגרייז בעל מנחת אשר."},{"i":4413,"n":"אלמדארי, יהודה מחלב","b":"רב בחלב(=ארם צובא)-שנת ל', חיבר פירוש להלכות הרי\"ף."},{"i":4414,"n":"אלמדיאל, יוסף מיוזיל-היסר","b":"רב ביוזיל-איסר-ליד אזמיר-שנות ה-ת'."},{"i":4415,"n":"אלמדיאל, יצחק מיוזיל-היסר","dt":"תקנט","dp":"קוש-אדאסי - ליד","b":"נהרג, ור רפאל יצחק די מאיו קיבל עדות על מותו, ונתכנס בי\"ד בקוש-אדאסי בראשות ר חיים שמעון גדיליה."},{"i":4416,"n":"אלמדיוני, יעקב מאלגיר","bt":"תקסה","bp":"תלמסאן-אלגיר","dt":"תרכז","b":"רב מקובל דרשן ודיין בתלמסאן, ווהראן-תר. חיבר חיבור על התלמוד, הו\"ל מחזור תלמסאן. נזכר ב\"מלל לאברהם\"."},{"i":4417,"n":"אלמו, אברהם","b":"ממשפחת ר משה אלמושנינו. נינו פרח בשנת שנב והניח ספר אחד בחכמת הקבלה בעיר פרנקפורט, שחיבר בירושלים."},{"i":4418,"n":"אלמוזגינו, נתן מרוסג'וק","b":"מאנשי קהלת רוסג'וק-תקס בערך."},{"i":4419,"n":"אלמולי, ישי משלוניקי וגליפולי","dt":"תלד - ה חשון","dp":"אזמיר","b":"חתן ר מאיר די בוטון. מחכמי שלוניקי-תך, רב בגליפולי-תכח על מקום ר שמעון ן חביב. (יש רושמים תאריך פטירתו - תן)."},{"i":4420,"n":"אלמולי, שלמה מספרד ותורכיה","f":"יעקב","k":"בעל הליכות שבא","bt":"רמה - לפני","bp":"ליסבון","dt":"שב - אחרי","b":"מחכמי ספרד, מדקדק, רופא, פילוסוף ומקובל, לאחר הגירוש עבר לשלוניקי, רב בקושטא וכנראה גם רופא הסולטן, משגיח בדפוס שונצינו-שב. חיבר גם \"מפשר חלמין\", \"הליכות שבא\", החל לכתוב אנציקלופדיה בביהדות ומדעים, ועוד."},{"i":4421,"n":"אלמולי, שמואל מסרייבו","b":"גביר תקיף בסרייבו. חתנו - ר חייא חיון (הארוך) מסרייבו."},{"i":4422,"n":"אלמוני, יוסף מאויבן","b":"מו\"צ באויבן-ר\"פ"},{"i":4423,"n":"אלמועלים, שלמה מספרד","b":"פייטן מחכמי ספרד בזמן ר אברהם ן עזרא שכתב עליו \"מהמעולים שבחכמי ההלכה וחיבר שירים מצויינים\"."},{"i":4424,"n":"אלמועלים, שמעון ממרוקו","f":"יצחק","b":"מחכמי מרוקו-תעז, העתיק ספר \"קול ברמה\"."},{"i":4425,"n":"אלמושנינו - משפחה","b":"משפחה עתיקה מספרד. מקור השם בעיר אלמזן במחוז קסטיליה, ויש אומרים שהוא מהמילה הערבית - \"אלמסנינו\" = הנואם - בעברית."},{"i":4426,"n":"אלמושנינו, אברהם בכור מירושלים","b":"בשליחות ירושלים-תקלד במרוקו, היה במחלוקת עם החיד\"א ונזכר ב\"מעגל טוב\"."},{"i":4427,"n":"אלמושנינו, אברהם מטיטואן","bp":"טיטואן?","b":"מחכמי טיטואן ממשפחת ר' משה אלמושנינו, חתום על פסק דין משנת תפו ותצז עם ר שמואל הצרפתי, הסכים על ספר אדמת קודש ועל \"שער המים\", עלה לירושלים, בשנת תקיח נמנה עם חכמי ישיבת ר יעקב פיררה יחד עם ר יצחק אבי החידא,"},{"i":4428,"n":"אלמושנינו, אברהם מירושלים","bt":"תסח - בערך","b":"מחכמי ישיבת בית יעקב פיררה בירושלים-תקו. (ואולי הוא ר אברהם בכור)."},{"i":4429,"n":"אלמושנינו, אברהם מספרד","b":"מחכמי ספרד, ראש קהילת אוסקה, הועלה על המוקד-רמט. נכדו-בן בתו - ר משה בן ברוך אלמושנינו משלוניקי."},{"i":4430,"n":"אלמושנינו, אברהם מספרד ופאס","b":"ממגורשי ספרד והגיע למרוקו, מו\"ץ בפאס-מרוקו, וחתם על תקנות-שה. בניו: ר משה, ר יוסף ונזכר בספרו \"שורשי המצוות\" לר יוסף אלומשנינו."},{"i":4431,"n":"אלמושנינו, אברהם מתורכיה וירוש","f":"משה","b":"מחכמי תורכיה-שן, ירושלים. בשנת שנב שהה בשליחות בפרנקפורט, והביא לשם כת\"י \"תקונים וסודות\" שהועתק בפרנקפורט ונאמר כי הוא מיסוד הארי (בודיליאנה נויבויאר 1602). נזכר בספר קרובו ר משה אלומשנינו. אחיו - ר שמעון."},{"i":4432,"n":"אלמושנינו, אבשלום מאיטליה ושלו","f":"אברהם","dt":"שסט - אדר","dp":"ונציה","b":"מחכמי ונציה, שלוניקי. חתם על הסכמות הקהל בשלוניקי. משורר מחברי ר גדליה ן יחיא משלוניקי."},{"i":4433,"n":"אלמושנינו, ברוך משלוניקי","b":"מחכמי שלוניקי. (אולי אביו של ר משה)."},{"i":4434,"n":"אלמושנינו, גבריאל אברהם מירקד","bt":"תקץ","bp":"ניקופול","dp":"ירושלים","b":"למד בניקופול ומרבני הבלקן, רב בניקופול-תקצח, עלה לירושלים, בשנת תרלה בשליחות ירושלים בבלקאן, רב ראשי בסופיה-תרלו, רב ראשי בבולגריה-תרמא, בשנת תרמט חזר לירושלים. (לפי ארזי הלבנון - נולד-תקסה ועלה לארץ רק בזקנותו)."},{"i":4435,"n":"אלמושנינו, גבריאל משלוניקי","b":"גביר בשלוניקי-תרן, יסד ישיבה בשלונקי ונקראה על שמו."},{"i":4436,"n":"אלמושנינו, חסדאי מטנג'יר וטיטו","k":"בעל חסד אל","bp":"טיטואן","dt":"תפח - טבת","dp":"טיטואן","b":"רב ומורה הוראה בטנג'יר-מרוקו, טיטואן-מרוקו, יחד עם ר משה ן זמרא, ר מנחם אנהורי, ר אברהם אבודרהם ור יצחק נהון. חיבר \"משמרות הקדש\" על פירוש רש\"י על התורה,נודע כבעל נסים."},{"i":4437,"n":"אלמושנינו, יוסף","b":"רב-שנת ת\"ס"},{"i":4438,"n":"אלמושנינו, יוסף מבלגרד","f":"יצחק בן משה","k":"בעל עדות ביהוסף","bt":"שצז","dt":"תמט","b":"תלמיד ר חנניה טאיטצק. תלמיד וחתן ר שמחה בן גרשם הכהן. מחכמי שלוניקי, רב בוידין, בלגרד, נשבה בכיבוש האוסטרי-תמח, נפדה ע\"י יהודי ניקלשבורג לובלין ועוד. מתומכי ש\"ץ בתחילת דרכו. בנו - ר יצחק - הדפיס את ספר פסקיו מתוך כת\"י שנפדה מרוכלים לאחר שנשדד בכיבוש בלגרד."},{"i":4439,"n":"אלמושנינו, יוסף מירושלים","dt":"תקלח - יח סיון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":4440,"n":"אלמושנינו, יוסף ממרוקו","f":"אברהם","k":"בעל שרשי המצות","bt":"רץ - בערך","dt":"שס - בערך","b":"רופא, גביר וראש הקהל בפאס-שלו. חתם על תקנות הקהל-שם-שן. חיבר גם \"פסח שני\" על ההגדה, ועוד. מתלמידיו - ר אהרן ן חיים מפאס, בנו - הרופא ר משה. אולי היה תלמיד ר משה סידיקארו מפאס יחד עם ר שמואל בן סעדיה דנון?"},{"i":4441,"n":"אלמושנינו, יוסף משלוניקי","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי."},{"i":4442,"n":"אלמושנינו, יצחק מלונדון","b":"רב בלונדון-תקף בערך. תשובה אליו מר שמואל חיים ב\"שמן המשחה\"."},{"i":4443,"n":"אלמושנינו, יצחק מקושטא","f":"יוסף מבלגרד","b":"מחכמי בלגרד, קושטא. הו\"ל ספר השו\"ת לאביו בשם \"עדות ביהוסף\"."},{"i":4444,"n":"אלמושנינו, יצחק משלוניקי","f":"אברהם","dt":"שנד-ו - כח סיון","dp":"שלוניקי","b":"נכד ר משה אלמושנינו. נפטר צעיר."},{"i":4445,"n":"אלמושנינו, יצחק משלוניקי","dt":"שכו - כד אייר","dp":"שלוניקי","b":"מחכמי שלוניקי. תרגם את האיתיקה של אריסטו לעברית."},{"i":4446,"n":"אלמושנינו, ישראל מירושלים","b":"מחכמי ירושלים, בשליחות באיטליה-תקצז, ור שמואל מרדכי גירונדי רשם חדושי תורה משמו."},{"i":4447,"n":"אלמושנינו, משה ממרוקו","b":"מחכמי מרוקו. תלמיד וחתן ר אליהו הצרפתי. נספד ב\"נער בוכה\" לר אליהו הצרפתי."},{"i":4448,"n":"אלמושנינו, משה מספרד ושלוניקי","k":"בעל מאמץ כח","b":"מגדולי חכמי דורו,חריף, ממגורשי ספרד-רנב, עבר לשלוניקי. חיבר \"מאמץ כח\" ונציה, ועוד בדפוס ובכת\"י."},{"i":4449,"n":"אלמושנינו, משה מפאס","f":"יוסף מפאס","b":"מחכמי פאס-שנות ה-ש'. חיבר ביאורים לתנ\"ך."},{"i":4450,"n":"אלמושנינו, משה מפאס","f":"אברהם","b":"רופא ומו\"ץ בפאס."},{"i":4451,"n":"אלמושנינו, משה משלוניקי","f":"ברוך","k":"בעל תורת משה","bt":"רעו-רפג","bp":"שלוניקי","dt":"שמ-א","dp":"קושטא","b":"משפחתו ממגורשי ספרד מאראגון. מצאצאי ר אברהם אלמושנינו הקדוש, ור אברהם קורוגבריאל הקדוש. תלמיד ר יוסף טאיטצק בקושטא, ר משה בוטון, ולמד מדעים ורפואה אצל ר פרחיה הכהן ור אהרן עפייה, בקי במדעים בשפות ורפואה. רב בשלוניקי, ועמד בראש משלחת-שכו אצל השולטן בקושטא אודות זכויות היהודים. חיבר ספרים בלאדינו, תרגם ספרי מדע מלטינית, יונית וערבית. מתשובותיו בספרי חכמי דורו. חיבר עוד \"תפלה למשה\", \"ידי משה\", \"הקצוות וגדולת קושטנדינא\", ועוד. נספד ע\"י ר סעדיה לונגו. בניו: ר שמעון, ור ברוך."},{"i":4452,"n":"אלמושנינו, שלמה ממצרים","b":"גביר במצרים-שנות ה-תק'."},{"i":4453,"n":"אלמושנינו, שלמה משלוניקי","dt":"שיז - ו חשון","dp":"שלוניקי","b":"אולי הכונה לר שלמה טאיטצק או ר שלמה ן ארדוט."},{"i":4454,"n":"אלמושנינו, שמואל","f":"אברהם","b":"מחכמי צפת, בשנת תר בשליחות בתורכיה."},{"i":4455,"n":"אלמושנינו, שמואל מספרד - א","k":"בעל פירוש לתורה","b":"מחכמי ספרד בזמן הריב\"ש ונזכר בתשובותיו כדון שמואל אלמושנינו, ובזמן ר יהודה כלץ שהזכירו בהקדמת \"משיח אלמים\". חיבר פירוש לתורה - נדפס ירושלים תשנח ע\"י ר משה פיליפ."},{"i":4456,"n":"אלמושנינו, שמואל משלוניקי - ב","k":"בעל פירוש לרשי לתורה","dt":"שיא - אב","dp":"שלוניקי","b":"ר\"מ בק\"ק \"קאטאלן\" בשלוניקי כ-40 שנה. מחותמי \"ההסכמות\" עם ר יוסף קארו ור יוסף טאיטצק. פירוש ממנו בתוך \"קהילת משה\" לר משה פרנקפורט - אמשטרדם. חיבר פירוש על רש\"י לתורה - קושטא. נספד ע\"י ר סעדיה לונגו, ור שלמה הלוי הזקן. (יתכן שיש בלבול בינו לר שמואל מספרד - והוא זה שחיבר פירוש על רש\"י)."},{"i":4457,"n":"אלמושנינו, שמעון הקדוש מאראגון","b":"רב באראגון. נהרג עק\"ה עם חברו ר אברהם קונמבריאל."},{"i":4458,"n":"אלמושנינו, שמעון משלוניקי","f":"משה","b":"מחכמי שלוניקי-שמ. אחיו של ר אברהם."},{"i":4459,"n":"אלמיטרי, יוסף מטריקאלה וקשטורי","b":"רב בטירקאלה, קאשטוריה-שנות ה-ש', והיה מחלוקת כנגדו ועזב בתוך שלש שנים, ור שלמה מבורך על מקומו אחריו."},{"i":4460,"n":"אלמילדה, אברהם מקושטא","b":"מחכמי קושטא - בשנים תק-תקן."},{"i":4461,"n":"אלמיצחק, יהודה מקומורג'ינה","f":"דוד","b":"רב בקומורג'ינה(=קומוטינה)-בשנות ה-ש'."},{"i":4462,"n":"אלמלי, יוסף","b":"חכם מופלא בדורו-שנת מ'"},{"i":4463,"n":"אלמלידה, יהודה משלוניקי","b":"מבני הקהלה האיטלקית בשלוניקי-תקד וחתם אז על הסכם בין האיטלקים לבין בני קהלת שלוניקי בענין הסדרת המס. חותנו - חיים שלמה די ליאון חתם עמו."},{"i":4464,"n":"אלמליח אליהו בן יעקב","bt":"1837","dt":"ה'תרסח 1908","bk":[["בקע לגלגלת",""]]},{"i":4465,"n":"אלמליח, אברהם מירושלים - א","f":"יוסף","k":"בעל שובע שמחות","b":"רב בירושלים-תצ\"ז"},{"i":4466,"n":"אלמליח, אברהם ממוגדור-מרוקו","b":"רב במוגאדור-מרוקו, שירים ממנו ב\"שובע שמחות\"."},{"i":4467,"n":"אלמליח, אברהם ממרוקו","f":"יהודה","dp":"אמיזמיס","b":"מצדיקי מרוקו"},{"i":4468,"n":"אלמליח, אברהם רפאל מירושלים","f":"יוסף","k":"בעל היהודים בדמשק","bt":"תרמה","bp":"ירושלים","b":"תלמיד \"דורש ציון\" בירושלים, פנה להשכלה, עסקן ציבור, חוקר וסופר."},{"i":4469,"n":"אלמליח, אהרן","k":"סבא דמשפטים","b":"דיין."},{"i":4470,"n":"אלמליח, אהרן ממרוקו","f":"אלעזר","b":"מו\"צ במוגדור(=מוגאדור)-מרוקו, רבאט-תקפט, חתם על פס\"ד-תריא עם ר אברהם אביטבול, ר אלישע בירדוגו. בנו - ר יוסף."},{"i":4471,"n":"אלמליח, אליהו מאלגיר וירושלים","f":"יעקב","k":"בעל בקע לגלגלת","bt":"תקצז","bp":"מוגדור-מרוקו","dt":"תרסח - יא אב","dp":"ירושלים","b":"רב באלגיר, טנגיר-תרסב, עלה לירושלים, חיבר \"בקע לגולגולת\""},{"i":4472,"n":"אלמליח, אליהו ממרוקו","f":"ראובן","b":"מחכמי מרוקו-שנות ה-תק', בזמן ר יונתן סירירו שכתב אליו."},{"i":4473,"n":"אלמליח, דוד מאדרינופול","b":"רב באדרינופול-רע."},{"i":4474,"n":"אלמליח, חיים ממוגאדור-מרוקו","b":"מחכמי מוגאדור-שנות ה-תק'."},{"i":4475,"n":"אלמליח, יהודה","dp":"אמיזמיס","b":"מצדיקי מרוקו"},{"i":4476,"n":"אלמליח, יהודה מטיטואן","f":"מרדכי","k":"בעל פירוש על הריף","b":"מו\"צ בטיטואן-מרוקו, חתם על פס\"ד-תקצד, חתם עם ר ראובן אלמליח. חיבר פירוש לרי\"ף."},{"i":4477,"n":"אלמליח, יהודה ממרוקו ואלגיר","f":"מרדכי","k":"בעל לחם יהודה","b":"מקובל, רב במרוקו, ווהראן(אוראן)-אלגיר-תקצז לקהילת בני מערבא(מרוקו), וחתם אז על שטר. חיבר \"לחם יהודה\"-תקם-תרי, פירוש לתורה, חיבור בהלכה שהיה בידי ר פארוז קרסיינטי, ועוד. נזכר ב\"מלל לאברהם\"."},{"i":4478,"n":"אלמליח, יוסף - הנכד","f":"עמרם","b":"נכד ר יוסף בעל \"תקפו של יוסף\". נזכר בהקדמת המגיה לספר זקנו, ובהקדמת עוז והדר לר שמואל די אבילה."},{"i":4479,"n":"אלמליח, יוסף - יוא\"ל מסאלי ורב","f":"עיוש","k":"בעל תקפו של יוסף","dt":"תקפג - יא אלול","b":"מו\"ץ בסאלי, רבאט-מרוקו-תקמח. חיבר \"תקפו של יוסף\". חתם על פס\"ד-תקס עם ר משה די אבילא, ר שמואל די אבילא, ר יעקב ן עלון."},{"i":4480,"n":"אלמליח, יוסף מדמנאת-מרוקו","b":"מחכמי דמנאת-תקצד."},{"i":4481,"n":"אלמליח, יוסף ממרוקו וירושלים","f":"אליהו","bt":"תריב","bp":"רבאט-מרוקו","dt":"תרפב - כה כסלו","dp":"ירושלים","b":"מחכמי ירושלים, ומראשי עדת המערבים, בשליחות הקהלה."},{"i":4482,"n":"אלמליח, יוסף מרבאט","f":"אהרן","bt":"תקסט","bp":"ראבאט (מרוקו)","dt":"תרמו","dp":"ירושלים","b":"תלמידו ובן דודו של ר יוסף בעל תקפו של יוסף. מלומד בנסים, מחכמי מרוקו, ראב\"ד במוגאדיר(=מוגאדור)-מרוקו-תר, קונסול אוסטריה, היה בגיברלטר, עלה לירושלים. חתם על פס\"ד-תרט עם ר דוד צבאח, ר אלעזר חזן, ר מסעוד רפאל ן מוחא, ר משה פינטו, ור יעקב בטאן."},{"i":4483,"n":"אלמליח, יעקב מדמנאת-מרוקו","b":"מחכמי דמנאת-שנות ה-התר'. אחיו של ר שלמה."},{"i":4484,"n":"אלמליח, יעקב מיפו","f":"יוסף","b":"עסקן ציבור, מחנך ביפו-תרלב."},{"i":4485,"n":"אלמליח, יעקב ממוגאדור וטנג'יר","b":"נכד-בן בתו ר אברהם קוריאט בעל \"ברית אבות\". מחכמי מוגאדור, עבר לטנג'יר-מרוקו."},{"i":4486,"n":"אלמליח, יעקב ממוגאדור-מרוקו","b":"רב במוגאדור, חיבר קינה על רדיפות-תקן, תשובה ממנו ב\"שופריה דיעקב\", חתם על הסכמה-תרכב עם חכמי ראבאט ובהם ר שמה טולידנו, ר יצחק בן שעיא, ר אברהם צבאע, ר דוד בויטץ, ועוד. אולי הוא שחתם-תקמג על פס\"ד עם ר שלם ישראל."},{"i":4487,"n":"אלמליח, יעקב ממרוקו","b":"נעים זמירות,מרבני מכנאס-ת\"ק"},{"i":4488,"n":"אלמליח, יצחק מאלגיר","f":"שלמה","k":"בעל שיח יצחק","bt":"תרסו","bp":"מרוקו","dt":"תשלד","b":"רב בעין לכיחל, סבדו-(מחוז תלמסאן), תלמסאן, פאריס-תשכב."},{"i":4489,"n":"אלמליח, יצחק מתארודאנת-מרוקו"},{"i":4490,"n":"אלמליח, ישועה מתונס","k":"בעל תנובות שדי","dt":"תשיח - ו אייר","dp":"תונס - ירושלים","b":"תלמיד ר שלמה דאנה מתונס. למד עם ר דוד קטורזא, ור דוד בן בארון. שו\"ב בתונס, ואח\"כ דיין. חיבר עם חברו ר דוד קטורזא ספר בהלכות טריפות - \"תנובות שדי\". אחיו של ר יצחק שנפטר צעיר, והקידש לו את ספרו \"ויזרע יצחק\". חתנו - ר יצחק בוכניק בעל \"ויאמר יצחק\" ומביא מתורת חותנו ותולדותיו.","bk":[["תנובות שדי",""]]},{"i":4491,"n":"אלמליח, מכלוף מסאלי","b":"רב בסאלי-תץ וחתם עם ר שלם אבוזגלו, ור עיוש אבוזגלו ב\"משפט וצדקה ביעקב\"."},{"i":4492,"n":"אלמליח, משה","f":"ראובן","dt":"תשנג - כח אב","b":"רב בעתלית. לזכרו יצא ספר זכרון - ירושלים תשנה."},{"i":4493,"n":"אלמליח, משה מאדרינופול","f":"דוד","b":"רב באדרינופול-רע."},{"i":4494,"n":"אלמליח, משה ממרוקו","b":"מחכמי מרוקו, חתם-תקמז על פס\"ד עם ר דוד ן חסין, ר שמעיה מור יוסף."},{"i":4495,"n":"אלמליח, עיוש מסאלי","b":"חתן ר שמואל בן שלמה קארו מסאלי. רב בסאלי - בשנות התק'. חתם עם ר שאול ן דנאן, ור רפאל עובד ן צור. חתן ר שמואל (או יוסף) קארו. בנו ר יוסף בעל \"תקפו של יוסף\"."},{"i":4496,"n":"אלמליח, עמרם","f":"יוסף-תקפו של יוסף","b":"סייע בהדפסת ספר אביו. בניו - ר יוסף, ר יהודה, ונכדו ר אברהם שהו\"ל את הספר בליוורנו."},{"i":4497,"n":"אלמליח, ראובן ממרוקו","b":"דיין בטיטואן. חתם בשנת תריא על פסק דין של ר יצחק ן וואליד עם ר אברהם אנהורי. חתם-תרח עם ר אברהם אנהורי ואושרה החתימה בידי ר מרדכי משה כלפון."},{"i":4498,"n":"אלמליח, שלמה מירושלים","f":"אהרן","dt":"תרמט - יג אד\"א","dp":"ירושלים","b":"מחכמי ירושלים, רבה של עדת המערבים. נפטר ערירי."},{"i":4499,"n":"אלמליח, שלמה מירושלים וספרד","bt":"תרנו","bp":"יפו","b":"רב בירושלים, ליסבון-פורטוגל, גיברלטר אצל ר משה ן נאים-תרלא."},{"i":4500,"n":"אלמליל, שלמה ממרוקו","b":"מחכמי מרוקו-שנות ה-תר'."},{"i":4501,"n":"אלמלך, משה מקהיר","b":"מחכמי קהיר בזמן ר חיים כפוסי ור מאיר גאביזון."},{"i":4502,"n":"אלמלקי, שלמה מאלגיר","bt":"רל - בערך","dt":"שי - בערך","b":"רב ומשורר בתלמסאן. חיבר שיר לכבוד ר יעקב גבישון בעל \"דרך השכל\" ונזכר ב\"עומר השכחה\"."},{"i":4503,"n":"אלמנטורי, מרדכי","b":"מחכמי ארץ ישראל, חתם בשנים תקכה ותקכח על כתב שליחות ר אברהם רויגו ור מיכאל הכהן."},{"i":4504,"n":"אלמנצי יוסף בן ברוך","bt":"1801","dt":"ה'תרכ 1860","bk":[["אבני זכרון",""],["יד יוסף",""],["מעיל קינ\"ה",""],["קינים והגה וחי",""],["תולדות ר' משה חיים לוצאטו",""]]},{"i":4505,"n":"אלמנצי, יוסף מפאדובה","k":"בעל הגיון בכנור","dt":"תרך - כה אדר","dp":"פדובה?","b":"מחכמי פדובה. חיבר גם \"נזם זהב\" פדובה תריח, \"תולדות הרמח\"ל\" - בכרם חמד, קינה לזכר ר יעקב חי פארדו, העתקת מצבות ישראל בטוליטולא(=טולדו) מכת\"י קדמון עם הערות ממנו ונדפס בידי שד\"ל בשם \"אבני זכרון\" תרא."},{"i":4506,"n":"אלמנצרי, זכריה","f":"סעדיה","b":"חיבר שיר בדרכי הגמרא ונדפס בתוך כתב העת \"משא ומתן\" - טירנוי תרצא."},{"i":4507,"n":"אלמסילי מאלגיר","f":"אלגסוס","bt":"ד'תשף","dt":"ד'תתן","b":"רב במסילא(ליד בורג בוערירג)-ד'תשף-ד'תתן. תלמיד ר נסים בן יעקב. חיבר חיבור בעניני תפילה, ונזכר בתשובות הרמב\"ם."},{"i":4508,"n":"אלמץ, מנחם מנדל מלבוב","b":"מנהיג ופרנס בלבוב, חתם-תקל על פסק דין."},{"i":4509,"n":"אלמרחבי, זכריה מתימן","f":"אבא מרי שלם בן אברהם","b":"סופר מעתיק בתימן."},{"i":4510,"n":"אלמרידי, אליהו מצפת","b":"מקובל מחכמי צפת, תלמיד הארי, ר חיים ויטאל מונהו בין ה\"כת השנייה\""},{"i":4511,"n":"אלנבויגן, חיים זאב מסטנוב","bt":"תקפח","dt":"תרסה","b":"רב בטשהן (רוסיה), סטנוב-תרכו, רישא-תרסד, בנו ר יוסף על מקומו אחריו ברישא."},{"i":4512,"n":"אלנבויגן, טוביה מסטמאר","f":"נפתלי","b":"מחכמי סאטמר."},{"i":4513,"n":"אלנבויגן, יוסף (סטנובר) מרישא","f":"חיים זאב","bt":"תרכה","dt":"תרפה","b":"רב ברישא-תרף על מקום אביו, מראשי ה\"מזרחי\"."},{"i":4514,"n":"אלנבויגן, יצחק משומאג'","dt":"תשד","b":"רב בקהילה הניאולוגית בשומאג'-מחוז זאלא-1922. נספה בשואה."},{"i":4515,"n":"אלנברג","k":"ראה: אילנברג","b":"רב בדוברומיל"},{"i":4516,"n":"אלנד, מיכל יחזקאל הכהן מטרנוב","dt":"תרסב - בערך","b":"תשובה אליו מאת תלמידו רמ\"מ מילר ב\"מנחם ציון\"-תרמד."},{"i":4517,"n":"אלנדאף, אברהם מתימן וירושלים","f":"חיים","k":"בעל שרידי תימן","bt":"תרכו","bp":"אלקאבל (ליד צנעא)","dt":"תש","dp":"ירושלים","b":"מחכמי תימן, תלמיד ר שלום מנצורה. עלה לירושלים-תרנא או תרמב, רב לעדה התימנית בירושלים, בשליחות בקושטא-תרסז כדי להשיג רשיון ממלכתי המכיר ביהודי תימן כעדה נפרדת. יסד ישיבה \"תורת משה\" ועמד בראשה. ראב\"ד העדה והדיינים היו ר שלום מזרחי עדני, ר שלמה מדמון ור חיים דמתי, כלם מחכמי \"בית אל\" ו\"רחובות הנהר\". הדפיס את ה\"תכלאל\" בירושלים, היה שליח בתימן, כתב ספר זכרונות בכת\"י שנדפס בחלקו בסיני כרך ד', פרסם שערי טהרה ירושלים תרנד, שרידי תימן ירושלים תרפח, מבשר טוב ירושלים תרעא, \"ענף חיים\", ועוד. אחיו ר מאיר ור פנחס מחכמי \"בית אל\". לחם עם אביו במשכילים בתימן. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. שלח איגרת עם השליח יבנאלי שסייעה לו בביקורו בתימן."},{"i":4518,"n":"אלנדאף, יעיש מתימן וירושלים","f":"ראובן מתימן וירושלים","k":"הו\"ל תפסיר מגילות","b":"עלה מתימן-תרסא (והצטרף לאביו שעלה-תרנא) והיה מראשי עדת התימנים בירושלים, ממיסדי שכונת \"נחלת אחים\". פרסם דו\"ח-תרצא על המוסדות התימנים בירושלים."},{"i":4519,"n":"אלנדאף, מאיר מתימן וירושלים","f":"חיים","b":"אחיו של ר אברהם אלנדאף. עלה לירושלים ונמנה על חכמי \"בית אל\". חתם-תרע מטעם ועד כולל התימנים בירושלים. הניח כתבים שלא נדפסו."},{"i":4520,"n":"אלנדורף, הינריך מאנגליה וצרפת","bp":"ראוויץ-פלך פוזנא","dt":"1865","b":"עבר לאנגליה ולפאריס. חוקר התלמוד. חיבר ספרים בחכמת התלמוד באנגלית, צרפתית. לתולדותיו מאת ר שלמה מונק."},{"i":4521,"n":"אלנעים, שם טוב מפאס","f":"משה","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":4522,"n":"אלנקאר, אברהם מאלגיר","k":"בעל עפרא דאברהם","b":"דיין באלגיר אצל ר יעקב בן נאים. הדפיס \"תקוני הזהר\" - ליוורנו עם תוספות משלו. חיבר \"עפרא דאברהם\" בכת\"י. חיבר פירוש למחזור ספרדי - ליוורנו."},{"i":4523,"n":"אלנקאר, אברהם מפאס וליוורנו","k":"בעל זכור לאברהם","bp":"פאס","b":"מחכמי פאס ובגלל הרעב עבר לליוורנו-תצח, בעל מחזור \"זכור לאברהם\", חיבר שיר \"ארצות עומק\"."},{"i":4524,"n":"אלנקאר, ראובן מפאס","b":"מחכמי פאס-שנות ה-ש'. אולי הוא שחיבר פירוש ימים נוראים."},{"i":4525,"n":"אלנקוה, אברהם מטולדו","f":"שמואל","dt":"קכ - ט תשרי","dp":"טולדו","b":"פרנס קהלת טולדו, נרצח עק\"ה."},{"i":4526,"n":"אלנקוה, אהרן בכור מירושלים","bt":"תרז","bp":"קושטא","dt":"תרסו - יט אלול","dp":"ירושלים","b":"רב בקושטא, עלה לירושלים-תרמב, והיה ראש בית הדין ספרדים, ממנהיגי \"בית אל\" - שני לר פריסיאדו בכר משה. הכין לדפוס \"ברוך מבנים\" לר ברוך ירושלמי - ירושלים תרס."},{"i":4527,"n":"אלנקוה, יוסף משלוניקי","f":"אברהם","b":"מגיה בדפוס גדיליה בשלוניקי--רפב."},{"i":4528,"n":"אלנקוה, יצחק מסיליבריאה","b":"רב בסילביריאה-ליד אדרינופול-שנות ה-ת'."},{"i":4529,"n":"אלנקוה, יצחק מקושטא","b":"תלמיד ר יוסף טרני מקושטא, עשיר ורב בקושטא-שנות ה-ת'."},{"i":4530,"n":"אלנתן הכהן הפייטן","b":"חיבר פיוט ונכנס למחזורים ישנים."},{"i":4531,"n":"אלנתנסי, יצחק מאושקה","b":"מחכמי אושקה בזמן הריב\"ש"},{"i":4532,"n":"אלסגלמאסי, שלמה","f":"נתן","b":"מחכמי מרוקו, אולי הוא הדיין מגלמססה שהזכיר הרמב\"ם."},{"i":4533,"n":"אלסטר, שמעון ישליסק","b":"אב\"ד ישליסק, תשובות אליו ב\"אמרי יושר\", ו\"בשות מהרש\"ם\"-תרנט."},{"i":4534,"n":"אלסנג'רי, שלמה מבבל","f":"עמר (עומק)","b":"פייטן בבבל בזמן רב האי גאון. חיבר כאלף פיוטים וביניהם יוצרות לפרשיות השבוע, רבים מפיוטיו נכללו במחזור ובהם \"אזהרה\" ליו\"כ. רבים מפיוטיו נמצאו בגניזה בקהיר."},{"i":4535,"n":"אלסקר, אברהם צבי שפירא מאוסטרה","k":"ר הירש עלקשיר","b":"שמו גם שפירא. פרנס באוסטרהא."},{"i":4536,"n":"אלסקר, חיים מברוד ואוסטרהא","f":"שמואל הלוי מברוד","b":"מחכמי אוסטרהא, מגיד בראוונא. אחיו הגדול של ר זאב וולף בעל \"חדושי הרז\"ה\" המזכירו בספרו. נזכר ב\"צל\"ח\" לר יהודה יחזקאל לנדא שכינהו \"כבוד ידידי וכו'\". הסכים על \"הלכה פסוקה\" לר טודרס מראוונע."},{"i":4537,"n":"אלסקר, יוסף מאוסטרהא","f":"אברהם צבי שפירא","b":"אביו נקרא גם עלקשיר וגם שפירא. פרנס באוסטרהא-תקח. בנו ר שמשון עלקשיר, וחתנו ר יואל פיבש בן יוסף אפרים פרנס ומנהיג באוסטרהא."},{"i":4538,"n":"אלסקר, שמשון מאוסטרהא","f":"יוסף","dt":"תקיז - ו אדר","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":4539,"n":"אלעג'ים, אברהם מקיוסטנדיל","b":"מראשי קהלת קיוסטנדיל-שנות ה-ת'-תק'."},{"i":4540,"n":"אלעג'ים, אברהם מקיוסטנדיל","b":"שו\"ב בדובניצה-תקס בערך."},{"i":4541,"n":"אלעג'ים, אליעזר מוידין","dt":"תקכב - ו אב","dp":"וידין","b":"מחכמי וידין."},{"i":4542,"n":"אלעג'מי, אברהם ממרוקו","b":"רב במכנס-תק\"פ"},{"i":4543,"n":"אלעג'מי, אליהו מירושלים","bt":"תרלא","bp":"צפון אפריקה","dt":"תרפז - כ אייר","dp":"ירושלים","b":"מרבני המערב שהתיישב בירושלים מראשי ישיבת \"בית אל\" ומראשי עדת המערבים ודיין בירושלים אצל ר שמעון אשריקי."},{"i":4544,"n":"אלעדני, דוד","k":"בעל מדרש הגדול","b":"מגדולי חכמי תימן-שנת ס'"},{"i":4545,"n":"אלעזוז, עבד הרופא ממצרים","b":"רופא מחכמי מצרים בזמן הרדב\"ז."},{"i":4546,"n":"אלעזר","f":"קלונימוס הזקן","b":"נזכר במעשה רוקח, וכנראה ט\"ס ואולי צריך להיות ר יצחק בן קלונימוס הזקן."},{"i":4547,"n":"אלעזר"},{"i":4548,"n":"אלעזר"},{"i":4549,"n":"אלעזר","bt":"תח","b":"עק\"ה עם בני קהילתו"},{"i":4550,"n":"אלעזר","dt":"תצח"},{"i":4551,"n":"אלעזר","f":"אריה ליב הגבוה מקרקא"},{"i":4552,"n":"אלעזר","f":"הודיה","b":"מחכמי הפייטנים ומפיוטיו במחזור."},{"i":4553,"n":"אלעזר אברהם הלוי מירושלים","f":"אליהו","k":"בעל בית דין","dt":"תקפד - א אב","dp":"קושטא או ירושלים","b":"מחכמי ירושלים, נכדו של ר אברהם סגרי, אחיו של ר רפאל הלוי בעל \"קול בן לוי\", בנו ר אברהם היה רבה של רודוס, חיבר ספר בכתב יד \"בית דין\" ו\"בית הלוי\", יצא בשליחות לתורכיה בשנת תקנז ונפטר בדרכו, הוספד ע\"י ר חיים אברהם איטרושה בעיר קומרג'ינה. לפי גליס נפטר - תקסא."},{"i":4554,"n":"אלעזר אלוף גאון מספרד","b":"רב בספרד בזמן הגאונים. תשובותיו בשו\"ת שערי צדק."},{"i":4555,"n":"אלעזר אלימלך מבוקובסק","b":"מחכמי בוקובסק. תשובה אליו \"ענף עץ אבות\"."},{"i":4556,"n":"אלעזר בויסקער מוילנא","b":"חתן ר ישראל אנטאקאליער ליפשיץ מוילנא. דיין בוילנא-בשנים תרל-תרם."},{"i":4557,"n":"אלעזר בן תמים","b":"עלה לארץ ישראל-מ' (1280) וגר בצפת. חתם עם רבני צפת על חרם ראש הגולה בדמשק נגד מתנגדי הרמב\"ם."},{"i":4558,"n":"אלעזר החבר מבגדד","b":"מראשי ישיבת בגדד-ד'תתקל בזמן רב שמואל בן עלי הלוי גאון, ואולי הוא ר אלעזר בן פהד."},{"i":4559,"n":"אלעזר החוזה הנקדן מרומא","b":"מחכמי רומא, בקי בתכונה. חיבר \"הילוך שבילי הכוכבים\", \"אקלימי עולם\", ועוד - בכת\"י."},{"i":4560,"n":"אלעזר הכהן בנו של אהרון הכהן, קבור בהר אפרים","dt":"א אב"},{"i":4561,"n":"אלעזר הכהן הבבלי הש\"ץ","f":"יעקב","b":"פייטן ומשורר-כ'. חיבר פיוטים ושירים לכבוד חכמי דורו וקינות (והוא המקור לזכר כמה מחכמי המזרח). היה חזן וכמה מפיוטיו היה מכניס לנוסח התפילה."},{"i":4562,"n":"אלעזר הכהן החסיד","f":"יהודה בן אלעזר","b":"שאלה ששאל עם חבריו ר יוסף בן אהרן ור יוסף בן מאיר ותשובת רש\"י אליהם - בתשובות חכמי צרפת. אביו של ר יעקב הכהן החסיד."},{"i":4563,"n":"אלעזר הכהן מארץ ישראל","f":"משה","b":"רב בארץ ישראל-ן'. חתם על חרם ראש הגולה מדמשק בזמן המחלוקת על ספרי הרמב\"ם."},{"i":4564,"n":"אלעזר הכהן מאשכנז","f":"אליהו","b":"חתן ר יחיאל וגיסו של הרא\"ש. אחיו של ר אביגדור הכהן, ונזכרו שניהם ב\"אור זרוע\", תשובה אליו ממהר\"ם מרוטנבורג. ב\"שפתי ישנים\" נאמר שחיבר \"אגרת המוסר\" - וכנראה הוא הנקרא ספר חסידים חדש לר משה בן אלעזר הכהן בן אחותו של הרא\"ש. חיבר הרבה פיוטים."},{"i":4565,"n":"אלעזר הכהן מלאסק","f":"יחיאל מיכל מלוסק","b":"חתן ר איצק גאלדעס מלוסק. מחכמי לוסק. בנו - ר יחיאל מיכל ונכדו הגביר ר וולף לייפציגער מוארשא ונינו - ר אלעזר הכהן ממאקווא וסוכטשוב. אחיו של ר שמואל לסקר מלוסק, ור אברהם."},{"i":4566,"n":"אלעזר הכהן מלונדון","b":"רב בלונדון-ה'א. תלמיד רבנו שלמה מלונדון וסידר את ספר מנהגיו. נזכר ברשב\"א."},{"i":4567,"n":"אלעזר הכהן ממגנצא","f":"אברהם","b":"נכד ר מאיר בן ר אברהם בן ר יהודה ליאונטין. רב במגנצא-ד'תתן. בניו: ר יהודה, ר יצחק. סדר יחוסו ב\"מצרף לחכמה\" ליש\"ר מקנדיא."},{"i":4568,"n":"אלעזר הכהן מסוכטשוב","b":"מתורתו ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":4569,"n":"אלעזר הכהן מפולטוסק וסוכטשוב","f":"וולף ליפסקר","k":"בעל חדושי מהרא\"ך","r":"ליפסקער","bt":"תקנא-ה","dt":"תרמב - כא חשון","b":"תלמיד קרובו ר זאב וולף מזאלושין ולוסק, ר אברהם יהושע השל מאפטא, ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק - והיה בעל תוקע אצלו, חדושי הרי\"מ, ר\"א מטשכנוב. חתן ר יעקב מליסא בעל חוות דעת. רב במאקובה, סוכטשוב, פולטוסק-תרג, פלוצק, וחזר לסוכאטשוב. היה מועמד לרבה של וארשא (נבחר ר חיים דוידזון) בניו ר אברהם מוארשא, ר יחיאל מיכל מזקרוטשין, ר צבי הירש מגרזש, ר גרשון ור אפרים. חתנו - ר דוד דב מייזלש מלוסק.","bk":[["נחל בכי – הספד",""],["זכר צדיק יסוד עולם – הספד",""],["חידושי מהרא\"ך – או\"ח ויו\"ד, ליקוטים על ש\"ס ורמב\"ם",""]]},{"i":4570,"n":"אלעזר הכהן מקולוניא","f":"יהודה","b":"מחכמי קולוניא(=קלן). תלמיד מהר\"ם מרוטנבורג שהשיב לו בספרו."},{"i":4571,"n":"אלעזר הכהן מקושטא וכיאו","b":"ר\"מ בתלמוד תורה בכיאו-יון-שעה יחד עם ר כלב קלפי, בזמן כהונת ר משה הכהן מרודוס כרב בכיאו. והיה ממנהיגי הקהלה."},{"i":4572,"n":"אלעזר הכהן משלוניקי - א","f":"שלמה - מהרש\"ך","b":"מחכמי שלוניקי-שץ בערך."},{"i":4573,"n":"אלעזר הלוי","f":"אשר","b":"חיבר ספר זכרונות - בכת\"י, ובו מלוקט מספר יוסיפון וירחמיאלי ועוד ספרים שאבדו."},{"i":4574,"n":"אלעזר הלוי","f":"יצחק","b":"פוסק בזמן רש\"י. נכד ר אלעזר סגן לויה. מצאצאי ר\"י הלוי-זקנו של רש\"י. אחיהם של ר יעקב, ר שמואל ור אשר מוורמייזא. נזכר בספר הפרדס. חיבר סליחה \"אלקי בשר עמך סמר\" ונכנס לספרי הסליחות. מתלמידיו: ר נחמיה בן מכיר."},{"i":4575,"n":"אלעזר הלוי מבגדד","f":"צמח","b":"ראש ישיבה בבגדד-ד'תתק, בזמן רב שמואל בן עלי והרמב\"ם. נזכר במסעות ר בנימין מטודלה שהיו הוה ואחיו יודעים לנגן הזמירות כמו שהיו הלויים בבית המקדש."},{"i":4576,"n":"אלעזר הלוי מהעלישוי","f":"אברהם ליכטנשטט","b":"רב בהעלישוי"},{"i":4577,"n":"אלעזר הלוי מטסימניץ","b":"רב בטיסמניץ-תקכ\"ו"},{"i":4578,"n":"אלעזר הלוי מירושלים","f":"יצחק","b":"מחכמי האשכנזים בירושלים, בשליחות בשנת תסג, בשנת תסז חתם על כתב רבנות ר דוד אופנהיים"},{"i":4579,"n":"אלעזר הלוי ממגנצא","f":"דוד","b":"נזכר ב\"אהל אברהם\"."},{"i":4580,"n":"אלעזר הלוי ממצרים","f":"יפת","b":"מחכמי מצרים-ד'תתקלו. חתם על תקנות הרמב\"ם."},{"i":4581,"n":"אלעזר הלוי ממראקש","k":"בעל עבודת הלוי","dt":"תרף - חשון","b":"ראש ישיבה במראקש. חיבר \"עבודת הלוי\"."},{"i":4582,"n":"אלעזר הפייטן","f":"פנחס","b":"פייטן-ד'תר, ואולי הוא בנו של פנחס הפייטן. נזכר אצל רב סעדיה גאון בין ראשוני הפייטנים."},{"i":4583,"n":"אלעזר הצרפתי מברצלונה","b":"מחכמי צרפת שהתישבו בספרד-ן'. היה מחלוקת בינו לבין הריטב\"א ונזכר במהרלנ\"ח."},{"i":4584,"n":"אלעזר הקליר","f":"[קלירי]","k":"בעל פיוטים","b":"מגדולי הפייטנים. דעות שונות על זמנו ועל מקומו. יש שאמרו שהוא התנא ר אלעזר בן שמעון, ויש שאחרוהו לסוף תקופת הגאונים (ר יוסף שטינהרט בעל \"זכרון יוסף), יש אומרים שהיה תלמיד ר יניי הפייטן מארץ ישראל. כנראה היה בשנים ד'תק - לפני זמנו של רב סעדיה גאון שמזכיר את פיוטיו. פיוטיו נכנסו למחזור אשכנז, וגם האר\"י היה נוהג לאמרם (ולא אמר פיוטים מהאחרונים)."},{"i":4585,"n":"אלעזר הרופא מרומא","b":"מחכמי רומא בזמן הגאונים."},{"i":4586,"n":"אלעזר וועלשום (וילזיס)","f":"שלום הכהן הרופא","k":"מאנושקריווי (משפחה)","bp":"צפת","b":"אביו כיהן כרב בצפת, הגיע לקראקא להדפיס ספר \"ראשית חכמה\" לדודו ר אליהו די וידאש, השתקע בקרמניץ-פולין והיה שם רב, בנו ר משה היה אב\"ד מיץ ואביו של טוביה הרופא בעל \"מעשה טוביה\". בנו מביא מחדושי אביו בספרו \"ברכת טוב\""},{"i":4587,"n":"אלעזר זלמן הלוי ממגנצא","f":"שמואל","dt":"קיח - א תשרי","b":"מגדולי חכמי מגנצא. נכד ר שמואל בונדינט חזן במגנצא בן ר יקר. אחיו של ר משה חזן משפירא. סדר צוואתו לבניו צורף לספר מהרי\"ל. נזכר ב\"דרכי משה\", ובשו\"ת \"בנימין זאב\". רשם את סדר יחוסו - בן ר שמואל בונפרנט ממגנצא בן ר יקר בן ר שמואל בן ר אברהם בן ר יקר הזקן בן ר שמואל מאור עינים בן ר יצחק בן ר אשר הלוי - הוא הראשון שהתישב בורמייזא לאחר שחרבה הקהילה בפרעות ד'תתנו."},{"i":4588,"n":"אלעזר ישראל מרוזדול וסוקולוב","k":"בעל עומר התנופה","bt":"תקף","dt":"תרל-מה","b":"תלמיד ר צבי הירש מזידיטשוב. רב ברוזדול, סוקולוב-תרה. חיבר גם \"שמן רוקח\". בנו ר מנחם מניש גוטסמן אב\"ד סוקולוב."},{"i":4589,"n":"אלעזר מאויבן","b":"רב באויבן,עלה לא\"י"},{"i":4590,"n":"אלעזר מאוסטרהא","f":"נפתלי","k":"לאזי דיין","b":"דיין באוסטרהא אצל ר חיים רפפורט בעל \"מים חיים\". הסכים על \"סדר עבודה ומורה דרך\" יחד עם ר חיים רפפרוט - סלאויטא תקצו."},{"i":4591,"n":"אלעזר מאורליאנס","f":"מאיר בן יצחק","b":"נזכר בפירוש דבה\"י המיוחס לרש\"י (ואינו מרש\"י)."},{"i":4592,"n":"אלעזר מאושפיצין","f":"נתן נטע","b":"רב באושפיצין"},{"i":4593,"n":"אלעזר מאיטליה","f":"שבתי","k":"בעל דברי שלום","b":"מחכמי יוון, רב בריקולה, עבר לאיטליה, חיבר \"דברי שלום\""},{"i":4594,"n":"אלעזר מאליסנה","f":"שמואל","k":"אלעזר חורנא ריש כלה","b":"מחכמי ספרד-ד'תרי, בא ללמוד בישיבת גאוני בבל אצל רב פלטוי ורב נטורנאי. נזכר בסידור רב עמרם גאון. תשובה אליו מרב נטרונאי בספר העיטור."},{"i":4595,"n":"אלעזר מארטא","b":"רב בארטא-שנות ה-ת'."},{"i":4596,"n":"אלעזר מארפורט","b":"נזכר בתוס' תלמידי ר ישראל (קשור עם ר זלמן מארפורט??)."},{"i":4597,"n":"אלעזר מאשכנז","f":"יוסף","b":"מחכמי אשכנז-ד'תתקן. נזכר אצל קרובו הראבי\"ה."},{"i":4598,"n":"אלעזר מאשכנז","f":"שמעון","dp":"ד","b":"חתם על תקנות קהלות שו\"ם-ד'תתקן. פסק ממנו בראבי\"ה וחתם עם אחיו? ר נתן בן שמעון ושלח את הפסק לחבריו ר שמחה משפירא והראבי\"ה. חיבר פיוטים ומהם במחזור."},{"i":4599,"n":"אלעזר מבבל","f":"הלל בן פאהד","b":"גאון בבגדד-ד'תתקן על מקום ר שמואל בר עלי גאון, ואולי הוא ר אלעזר החבר, ור דניאל בן אלעזר על מקומו אחריו. נשארו תשובות ממנו ומסתיימות תמיד \"אלקים לנו מחסה סלה\" שהוא סגנונו היחודי."},{"i":4600,"n":"אלעזר מבודון","b":"אב\"ד בבודון-תכ בזמן ר אפרים הכהן."},{"i":4601,"n":"אלעזר מביאליסטוק","k":"אלעזר פיוק","b":"מגדולי תלמידי ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק, ובנו ר דוד."},{"i":4602,"n":"אלעזר מוארדין","b":"תלמיד ר יצחק בעל התוספות, נשא ונתן עם ר אלעזר מוורמייזא בעל הרוקח."},{"i":4603,"n":"אלעזר מוורדון (וירונה)","b":"וורדין הינו שיבוש והכוונה לוירונה. (בספר \"בשמים ראש\" מביא תשובה מר אלעזר מוורדון ומכאן הוכיחו את זיופו - כי אין חכם כזה ומבוסס על ט\"ס במרדכי)."},{"i":4604,"n":"אלעזר מוורמייזא (גרמייזא)","f":"יהודה בן קלונימוס","k":"בעל הרוקח","bt":"ד'תתקכ","bp":"מגנצא","dt":"ד'תתקצז","dp":"ורמייזא","b":"תלמיד ר יהודה משפירא בן קלונימוס - הריב\"ק בעל \"יחוסי תנאים ואמוראים\", ר משה הכהן ממגנצא, ר שמריה משפירא בן מרדכי, ר אליעזר ממיץ בעל \"יראים\", קרובו - ר יהודה החסיד ברגנשבורג, ועוד. מגדולי הראשונים, פוסק, מקובל, בקי בנגלה ובנסתר, רב וראש ישיבה בוורמייזא(=וורמס). אשתו ובנותיו נהרגו עק\"ה והוא ובנו נפצעו. מתלמידיו: ר יצחק בעל \"אור זרוע\", ר מנחם בעל \"כתר שם טוב\", ר אברהם אכסלרוד, ר אברהם בעל \"ערוגת הבשם\", ועוד. חיבר גם \"חכמת הנפש\", \"דרכי תשובה\", \"סודי רזיא\", ועוד. חיבר גם פיוטים. (לא היה נכדו של ר יהודה החסיד - כפי שכתב רא\"ז מרגליות). אשתו - דולצא - מלומדת וחכמה, והיתה מלמדת תורה והלכות לנשים, ודורשת בשבת."},{"i":4605,"n":"אלעזר מוירונה","f":"שמואל","b":"מבעלי התוספות באיטליה-ד'תתקף. תלמיד ר\"י הזקן. בנו ר שמואל ונכדו ר הלל בעל \"תגמולי הנפש\". תשובה ממנו ב\"רוקח\" וחלק עליו ר יוסף קארו ואילו המבי\"ט הסכים עמו (ושם בטעות וורדונא וצ\"ל וירונה), ועוד תשובה ממנו בדיני עגונה ונזכר בספר ראבי\"ה. ב\"אור זרוע\" נזכר שאלות ששאל מר ישעיה מטרני ומר אלעזר מוירונה. יש אומרים שהוא המחבר תוספות על מסכת בבא בתרא. נזכר במרדכי כר אלעזר מוורדין והוא טעות וצ\"ל וירונה."},{"i":4606,"n":"אלעזר מוכיח הכהן - כץ","f":"יעקב","b":"נכד-אבי אמו ר אברהם-אחיו של המהרש\"א. בנו - ר יחיאל מיכל הכהן מלוסק."},{"i":4607,"n":"אלעזר מזלושיץ","b":"רב בזאלושיץ"},{"i":4608,"n":"אלעזר מטאפאלשטיין","b":"מקובל בה' מאד"},{"i":4609,"n":"אלעזר מטופורוב","b":"רב בטופורוב-תריא"},{"i":4610,"n":"אלעזר מלאסק","f":"ר\"א","b":"פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":4611,"n":"אלעזר ממאזיר","b":"מו\"צ במאזיר תר\"כ"},{"i":4612,"n":"אלעזר ממטרסדורף","b":"רב במטרסדורף"},{"i":4613,"n":"אלעזר ממילהויזן","dt":"קח","b":"מחכמי אשכנז. נהרג עק\"ה בגזירות-קח. קינה לזכרו מאת ר ישראל בן יואל זיסליין מארפורט ונדפסה ב\"עמודי העבודה\"."},{"i":4614,"n":"אלעזר ממצרים","f":"מיכאל","b":"מחכמי מצרים בזמן הרמב\"ם-ד'תתק-ד' תתקן. חתם עם בית דינו של הרמב\"ם כנגד הקראים-ד'תתקלה. כנראה הוא שהיה במחלוקת עם ר פנחס בן משלם מאלכסנדריה בענין חשבון יג מדות - והציעו חכמי הקהל את ההכרעה בפני הרמב\"ם."},{"i":4615,"n":"אלעזר ממצרים","f":"מתתיה","b":"אולי מחכמי מצרים. חיבר פירוש על הראב\"ע, ומזכיר את ר אלישע בן שמעיה מאלכסנדריה. ואולי אביו הוא ר מתתיה ממיץ ועלו שניהם לארץ ונזכרו בתקנות קנדיא-ד'תתקפח."},{"i":4616,"n":"אלעזר ממצרים","f":"פצלין","b":"מחכמי מצרים-ש'. נזכר בשו\"ת הרדב\"ז."},{"i":4617,"n":"אלעזר ממראחוב","k":"הרב ממראחוב","dt":"תקע - טו כסלו","b":"רב במראחוב-אוקראינה, ברדיטשוב, ידידו של ר ר לוי יצחק מברדיטשוב."},{"i":4618,"n":"אלעזר מספרד","k":"אלעזר אלוף","b":"רב באליסנה(ספרד) בתקופת הגאונים"},{"i":4619,"n":"אלעזר מספרד","b":"מחכמי ספרד, תלמיד הרא\"ש"},{"i":4620,"n":"אלעזר מספרד","f":"הרא\"ש","b":"אחד משמונת בניו של הרא\"ש."},{"i":4621,"n":"אלעזר מעכו","f":"יעקב","b":"מחכמי אשכנז או צרפת עלה לארץ, מחכמי עכו, חתם-ד'תתקצד על שאלת ר יוסף בן גרשום מעכו אל ר אברהם בן הרמב\"ם."},{"i":4622,"n":"אלעזר מפאקש","b":"רב בפאקש-תק\"ע"},{"i":4623,"n":"אלעזר מפאריס","f":"יהודה בן יו\"ט","b":"רב בפאריס בזמן רבנו תם שהזכירו בספר הישר. (אחיו של ר אליהו או שהוא אותו אדם ונקרא בטעות פעם אליהו ופעם אלעזר)"},{"i":4624,"n":"אלעזר מפינטשוב","k":"בעל אסירי התקוה","b":"חיבר פירוש למשלי בשם \"אסירי התקוה\" - נאייויט תקס."},{"i":4625,"n":"אלעזר מפיעטריקוב","f":"שלמה זלמן מפיעטריקוב","b":"חתן ר צבי הירש מרישא בעל \"גאון צבי\". גביר בפיעטריקוב. סירב לרבנות פאטשינוב. בנו - ר אברהם צבי פצנובסקי בעל \"ברית אברהם\"."},{"i":4626,"n":"אלעזר מפלירא","f":"יהודה - הריב\"ן","b":"נכד רש\"י, כנראה תלמיד רבנו תם, מגדולי בעלי התוספות, מרביץ תורה בפלירא. אחיו של ר יו\"ט מפלני. חתנו - ר אלעזר."},{"i":4627,"n":"אלעזר מקולומאי","b":"רב בקאלאמאי"},{"i":4628,"n":"אלעזר מקומרנא","b":"רב בקומרנא"},{"i":4629,"n":"אלעזר מקושטא","f":"נחמן","b":"מראשי קהלת שטיפי-שנות ה-ר'-ש'."},{"i":4630,"n":"אלעזר מקרוז'","b":"רב בקראז-ת\"ק"},{"i":4631,"n":"אלעזר מראסיין","f":"מאיר","dt":"תריד - כב כסלו","dp":"ראסיין","b":"שו\"ב בראסיין. גיסו - ר אהרן נוראק."},{"i":4632,"n":"אלעזר מרוזוודוב","b":"תלמיד ר ישכר בר מרדושיץ. דיין ברוזוודוב."},{"i":4633,"n":"אלעזר מרומא","f":"מרדכי הרופא","b":"מחכמי רומא-קן. חיבר פירוש לתורה. בנו - מרדכי הרופא."},{"i":4634,"n":"אלעזר מריקולה","f":"שבתי בלגוד","b":"רב בריקולה לקהל סיציליאני, עבר לאיטליה והו\"ל \"בית העוזיאלי\", ו\"דברי שלום\"."},{"i":4635,"n":"אלעזר משעוועל וזאגר","f":"אברהם אביש מפפד\"מ","b":"רב בשאוועל,זאגער-תק\"מ"},{"i":4636,"n":"אלעזר ן - משפחה","b":"משפחה מספרד בשנים ד'תת ועד ה'ר. היו ממנה הרבה חכמים, שרים מקורבים למלכות. הרבה חכמים מספרד המופיעים כ-בן אלעזר הכוונה לשם המשפחה ולא לשם האב."},{"i":4637,"n":"אלעזר פורנא","b":"מחכמי אשכנז, רב בפמגוסטא-קפריסין-קיט. נזכר בלקוטי מהרי\"ל שהשיב לר עוזר. נזכר במרדכי."},{"i":4638,"n":"אלעזר שמחה מסובאלק","dt":"תרעא - אב","dp":"לומזה","b":"רב בסובאלק, לומזה, קאלוואריה. חתנו - ר בנימין בן זרח דיסקין."},{"i":4639,"n":"אלעזרי, חיים מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"המסלה\" - נ\"י תרצו, \"שערי אמונה\" - ירושלים תרצה, \"תבונה\" - ירושלים תשא-תשח."},{"i":4640,"n":"אלעזרי, שמואל מתירייא","b":"רב בתירייא - בדור שלאחר הגירוש."},{"i":4641,"n":"אלעזרסון, אברהם מבלטרמאנץ","k":"בעל מחזה אברהם","b":"רב בבלבירישוק, בוטרימאנץ(=בלטרומאנץ) - במאה ה-19. חתנו ר שמואל יעקב רבינוביץ הביא ממנו בספרו \"אורח ישר\"."},{"i":4642,"n":"אלעיארזש, מאיר מזאמוטש","f":"צבי מזאמוטש","k":"אדמור מזאמוטש לובלין","dt":"תש..","b":"חתן ר בונם יצחק הולצמן מחורזל. אדמור בלובלין על מקום אביו והיו לו חסידים רבים גם מחוץ ללובלין. נספה בשואה עם משפחתו."},{"i":4643,"n":"אלעיארזש, צבי מזאמוטש","f":"יעקב מגוברובה","k":"אדמור מזאמוטש לובלין","dt":"תרץ","b":"חתן ר מאיר הולצמן מגורבובה. מקורב לאדמורי ווארקי, ראדזימין ורוזין. אדמור בלובלין."},{"i":4644,"n":"אלעיש ן, יוסף","dt":"קי","b":"מגדולי מרביצי תורה באלקלעה(ספרד)"},{"i":4645,"n":"אלעלוף, שלמה ממרוקו","f":"[שלמה]","dt":"תרסא - ניסן","b":"מצדיקי מרוקו."},{"i":4646,"n":"אלעלוף, שלמה מפאס","f":"יהודה","b":"מחכמי פאס."},{"i":4647,"n":"אלעלוף, שלמה מפאס","f":"שמואל","dt":"תרס - כד סיון","dp":"ירושלים","b":"מחכמי פאס, עלה לירושלים."},{"i":4648,"n":"אלעלוף, שמואל ממרוקו וירושלים","f":"שלמה","bt":"תרכח","bp":"פאס","dt":"תרצג - כז אלול","dp":"ירושלים","b":"עלה עם אביו לירושלים-תרמג, מראשי העדה המערבית בירושלים, ואחראי על כספי התרומות וחלוקתן."},{"i":4649,"n":"אלעמאני, אהרן חבר בן ציון","f":"ישועה","b":"מחכמי אלכסנדריה-ד'תתק, והיה רופא ופקיד אצל הנגיד ר שמואל בן חנניה. היה עשיר ומכבד חכמים ובהם ראב\"ע ור יהודה החסיד שחיברו שירים לכבודו (ר יהודה החסיד התארח אצלו בדרכו לארץ). חיבר פיוטים ונמצאו במחזורים ישנים. בנו ר ישועה גם הוא חיבר פיוטים."},{"i":4650,"n":"אלעמי, שלמה מפורטוגל","k":"בעל אגרת מוסר","b":"מגדולי חכמי ספרד, עד ראיה לגירוש-קנ\"א. חיבר \"אגרת מוסר\" קושטא, ונדפס במחזור אשכנזי ע\"פ הדרת קדש."},{"i":4651,"n":"אלענקרי, מרדכי ממרוקו","f":"יצחק","b":"מחכמי מרוקו-תמה, העתיק ספר דרושים, חיבר חרוזים לסדר הפרשיות."},{"i":4652,"n":"אלענקרי, שמואל ממכנאס","b":"מחכמי מכנאס בשנות ה-תק'."},{"i":4653,"n":"אלעסרי, אברהם ממרוקו","f":"יעקב","k":"בעל תענוג ושמחה-כת\"י","b":"מחכמי מרוקו, חתם על פס\"ד עם רבני מראקש-תקיא עם ר דוד בן יוסף אלכלאס."},{"i":4654,"n":"אלעסרי, מכלוף ממרוקו","k":"בעל טעמי השחיטה","bt":"תרעה","bp":"קסר א-סוק-מרוקו","b":"תלמיד ישיבת \"אביר יעקב\" בתפיללת אצל ר ישראל אבוחצירא - הבבא סאלי ורבו שלחו לכהן כרב בקהילת \"ריש\"-מרוקו. עלה לארץ-תשכג והתישב בבית שאן וכיהן כרב ומקובל ושו\"ב. היה כל שנותיו בקשר עם משפחת אבוחצירא."},{"i":4655,"n":"אלעפרי, שלמה מגיברלטר","b":"רב הכולל בגיברלטר-תרל."},{"i":4656,"n":"אלפאגי, אליהו הלוי","f":"דוד","b":"מחכמי טורקיה"},{"i":4657,"n":"אלפאכר - משפחה","b":"משפחת נשיאים בספרד. פירוש השם אלפאכר - היוצר."},{"i":4658,"n":"אלפאכר ן, יצחק הספרדי","b":"חיבר לוחות על התכונה לכבוד המלך אלפונסו. מאמר ממנו על עיקרי התורה אצל די רוסי."},{"i":4659,"n":"אלפאכר, אברהם מטולידו","dt":"ד'תתקפח -כה טבת","b":"ממשפחת הנשיאים בספרד. חתן ר יוסף ן שושן מטולדו, גיסו של הרמ\"ה(=ר מאיר הלוי). שר בטולדו ומקורב למלך אלפונסו השמיני. חיבר שירים בערבית. נזכר ב\"תחכמוני\". שיר לזכרו מר יהודה בן שבתי, שיר עליו מגיסו הרמ\"ה."},{"i":4660,"n":"אלפאכר, יהודה הנשיא","f":"אברהם","dt":"ד'תתצה","b":"רופא, נשיא מחכמי טולדו-ספרד. חכמי צרפת ופרובנס התיעצו אתו בענין \"מורה נבוכים\" - היה ממתנגדי הספר, היה במחלוקת על כך עם ר דוד קמחי (הרד\"ק) שנסע לספרד כדי להצדיק את הרמב\"ם."},{"i":4661,"n":"אלפאנדרי, אליהו","k":"בעל סדר אליהו","b":"דיין, ראש רבני קושטא, חיבר \"סדר אליהו\" ו\"מכתב מאליהו\""},{"i":4662,"n":"אלפאסה, משה מאדרינופול","b":"מראשי קהלת אדרינופול, חתם-תקצה על בקשת עזרה לקהלה מקהלת רוסג'וק לאחר השריפה עם הרבנים ר יוסף בכמוהר\"ר מרדכי ור יקיר אשטרוק גירון, ועם נסים יוסף פיזה, חיים עובדיה, אהרן רודריג ויהודה בן יצחק."},{"i":4663,"n":"אלפאראבי מחמד אבן מחמד אבו נצר","bt":"950","dt":"ד'תרלד 874","bk":[["מהות הנפש",""]]},{"i":4664,"n":"אלפארח, משה מאלגיר","b":"רב באלגיר ונזכר באשכבתא דרבנן של ביהכ\"נ הגדול באלגיר."},{"i":4665,"n":"אלפגי, אליהו הלוי מקושטא","f":"דוד","b":"מחכמי קושטא-ש'. נזכר בספרי חכמי דורו ובהם הרא\"ם, ושו\"ת בנימין זאב. חיבר ספר בחכמת המדידה - בכת\"י."},{"i":4666,"n":"אלפואל, אברהם מספרד","b":"רב בטורטשה(=טורטולה)-קן בזמן מהר\"ם חלאווה. תשובה אליו מהריב\"ש."},{"i":4667,"n":"אלפואל, חיים מרודוס","f":"יצחק","k":"בעל נופת צופים","b":"רב ברודוס-שנות ה-ש'. שאלות ממנו לרדב\"ז, ר יוסף ן לב."},{"i":4668,"n":"אלפואל, יצחק מקושטא","f":"חיים","k":"בעל נופת צופים?","b":"מחכמי רודוס, רב בקושטא."},{"i":4669,"n":"אלפוס, יוסף מיעזוב","dt":"תשג","b":"רב ביעזוב"},{"i":4670,"n":"אלפיה, יעקב חיים ישראל רפאל","f":"יצחק ישעיה","k":"רי\"ח","bt":"תרך-תרכג","bp":"ארם צובא","dt":"תרעו - כג שבט","dp":"ירושלים","b":"מחכמי ארם צובא, עלה לירושלים לישיבת \"בית אל\". מחדושיו נדפסו בספרי בנו","bk":[["רי\"ח ליצחק",""]]},{"i":4671,"n":"אלפיה, יצחק מארם צובא - י-ם","f":"יעקב חיים ישראל","k":"בעל קונטרס היחיאלי","bt":"תרלח","bp":"ארם צובא","dt":"תשטו - כו אלול","dp":"ירושלים","b":"עלה לירושלים בילדותו ולמד ב\"בית אל\". דיין מחכמי ירושלים ועסק בקבלה, הקים ישיבה \"אור חדש וצמח צדיק\". חיבר \"שיח יצחק\", \"ריח ליצחק\" ועוד."},{"i":4672,"n":"אלפיה, יצחק מאר\"ץ - א","f":"ישעיה","bt":"תקפז","bp":"ארם צובא","dt":"תרעב - כז ניסן","dp":"ירושלים","b":"שו\"ב באר\"ץ, עלה לירושלים-תרן ולמד בישיבת \"בית אל\". זקנו של ר יצחק אלפיה בעל קונטרס היחיאלי."},{"i":4673,"n":"אלפיה, מאיר מזאכו","bt":"תרלח","bp":"זאכו-כורדיסטן","dt":"תשא - כא חשון","dp":"בגדד","b":"רב בזאכו - התפרנס מעבודת אריגה. מקובל ובעל קמיעות ורבים עלו אליו לקבל ברכה ועצה, ושימש כרב בקהלה. חיבר פיוטים."},{"i":4674,"n":"אלפיה, מרדכי משה מירושלים","k":"בעל מאמר מרדכי","bp":"ירושלים","dp":"ביירות","b":"אחיו של ר יצחק. מחכמי ירושלים, רב בביירות."},{"i":4675,"n":"אלפינו, אליהו מספרד וקושטא","b":"ממגורשי ספרד-רנ\"ב,בא לקושטא"},{"i":4676,"n":"אלפלאס, דוד ממראקש","b":"מו\"ץ במראקש, חתם על פס\"ד-תקיא."},{"i":4677,"n":"אלפלאס, משה משלוניקי","k":"בעל הואיל משה","b":"רב דרשן בטיטואן, נדד כרב ודרשן בתורכיה, היה בצפת ופגש את ר יעקב גווייוזו, רב בראגוזה, בלגרד, איסקופיה, שלוניקי, איטליה, והיה שם ממיסדי ישיבת ליואנטיני בונציה. חזר לטיטואן-שנה. בונציה-שנז והדפיס את ספריו \"הואיל משה\" ו\"ויקהל משה\", חיבר גם \"בא גד\" ועוד. ופגש את ר יהודה אריה ממודנא, עסק בונציה בהגהת ספרים. חתנו - ר יהודה בן אליעזר רבנו מלאבאדיה, ור יהודה אריה חיבר שיר לחתונתם."},{"i":4678,"n":"אלפללו, שמואל ממרוקו","b":"מחכמי מרוקו-תרב."},{"i":4679,"n":"אלפנבין, ישראל מבוצאץ","f":"אליקום חנוך פיבוש","k":"בעל ספר מנהגים דבי","bt":"תרנב","bp":"בוצ'ץ'","dt":"תשכה","b":"מצאצאי הש\"ך והט\"ז. תלמיד המהרש\"ם, ולמד בישיבת פרשבורג. בשנת תרעא היגר לארה\"ב ולמד בישיבת ר יצחק אלחנן. עבר לסמינר שכטר וקיבל תואר דוקטור. רב בשיקגו-תרעו, ניויורק-תרעט, חיבר \"ספר מנהגים דבי מהרם\" ניו יורק תרצח."},{"i":4680,"n":"אלפנדרי - משפחה","b":"רב בירושלים-רן. פסקי דינים ממנו ב\"שיורי ברכה\", ובשו\"ת הרדב\"ז."},{"i":4681,"n":"אלפנדרי חיים בן יצחק רפאל","bt":"1660","dt":"ה'תצג 1733","bk":[["אש דת",""]]},{"i":4682,"n":"אלפנדרי, אברהם דוד מביירות","f":"רפאל","b":"פקיד כוללות ארץ הקדש בביירות-תרו."},{"i":4683,"n":"אלפנדרי, אברהם מקושטא","b":"מחכמי קושטא. בנו - ר יצחק - מדפיס אצל ר יונה יעקב אשכנזי."},{"i":4684,"n":"אלפנדרי, אהרן מחברון","f":"משה","k":"בעל יד אהרן","bt":"תסא","bp":"אזמיר","dt":"תקלד או תצז","dp":"חברון","b":"נכדו של ר חיים אלפנדרי הזקן, למד אצל ר ברזילי יעבץ, ור בנימין בן שלמה הלוי-אב\"ד אזמיר. בצעירותו ישב ברודוס והיה בקשר עם ר משה ישראל רבה של רודוס, היה רב באזמיר, ועלה לחברון, מחכמי ישיבת \"דמשק אליעזר\" בירושלים. בשנת תקכג חתם בחברון על מכתב לר אברהם גטנינו, ועל אגרת שליחות ר חיים רחמים באגאיו, בשנת תקל ראש רבני חברון. חיבר \"יד אהרן\" אזמיר תצה, \"מרכבת המשנה\" אזמיר תקטו. כתב הרבה הגהות ותקונים לספר \"כנסת הגדולה\". נכדו - ר יצחק ארדיט בעל \"יקר הערך\". רוב כתביו אבדו בשריפה-תצח."},{"i":4685,"n":"אלפנדרי, אהרן מספרד","b":"מגדולי ספרד לפני הגירוש-ר\"כ"},{"i":4686,"n":"אלפנדרי, אליהו מקושטא","f":"יעקב","k":"בעל מכתב מאליהו","dt":"תעז","dp":"קושטא","b":"תלמיד ר חיים שבתי משלוניקי. דיין בקושטא עם ר אברהם קמחי ור אהרן רוזניס ור יהודה רוזניס. חתנו - ר מרדכי בכר שבתי אלפנדרי סייע לו בהדפסת ספרו \"אליהו רבה\" - קושטא תעט."},{"i":4687,"n":"אלפנדרי, חזקיה רפאל מקושטא","dt":"תקסד","b":"אב\"ד קושטא-תקסג, חתם בראש הרבנים בשו\"ת מהר\"ם מינץ וספר הפרדס - קושטא תקסב."},{"i":4688,"n":"אלפנדרי, חיים יצחק רפאל","f":"חיים","b":"מגיה בדפוס יונה בן יעקב אשכנזי בקושטא-תעז."},{"i":4689,"n":"אלפנדרי, חיים מירושלים","b":"מחכמי ירושלים-תקיד, נשלח ליפו לזרז את החיד\"א וחבריו בנסיעתם לקושטא להתלונן נגד המושל בירושלים."},{"i":4690,"n":"אלפנדרי, חיים מירושלים - הנכד","b":"מראשי הקהלה הספרדית בירושלים-תריד, חתם על מכירת בתי הכולל לר יוסף שלום בן עבדאלה."},{"i":4691,"n":"אלפנדרי, חיים מירקדו","bt":"תרו","bp":"קושטא","b":"גדול בנגלה ובנסתר,רב ראשי בדמשק-תרי, עלה לצפת-תרע."},{"i":4692,"n":"אלפנדרי, חיים מספרד","b":"מגדולי חכמי ספרד-ר\"מ"},{"i":4693,"n":"אלפנדרי, חיים מקושטא - הזקן","f":"יעקב","k":"בעל דרך הקדש","bt":"שמ-שמח","dt":"ת - טו ניסן","dp":"ירושלים","b":"תלמיד ר יוסף טרני. רב בקושטא. מתשובותיו בספר בניו: ר יעקב, ר יצחק רפאל שהו\"ל את ספרו \"מגיד מראשית\" קושטא תע."},{"i":4694,"n":"אלפנדרי, חיים מקושטא וירושלים","f":"יצחק רפאל","k":"בעל אש דת","bt":"תך-ס","bp":"קושטא","dt":"תצג-תקכד - אחרי","dp":"קושטא","b":"נכד ר חיים אלפנדרי הזקן, למד אצל אביו ואצל דודו ר יעקב אלפנדרי ור אברהם רוזנס. היה מרבני קושטא בימי ר יהודה רוזניס ור אליעזר ן שנגי והסכים עמם על \"עדות ביהוסף\". בשנת תעג עלה לירושלים ואחר כך לצפת בה שימש כרב. חיבר \"אש דת\" קושטא תעח. מתורתו בספרי חכמי דורו. היה בין הרבנים שהחרימו את ש\"ץ בקושטא (וחזר בו). הו\"ל ספר \"משמרה\" קושטא תף. מתלמידיו - ר ישראל מאיר מזרחי."},{"i":4695,"n":"אלפנדרי, יהודה מקושטא","b":"מחכמי קושטא-שנות ה-ת'. בנו - ר יעקב-דיין בקושטא."},{"i":4696,"n":"אלפנדרי, יוסף מקושטא","k":"בעל פורת יוסף","b":"מגדולי חכמי קושטא-ת\"ר"},{"i":4697,"n":"אלפנדרי, יוסף משלוניקי","dt":"רף - יט אד\"ב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":4698,"n":"אלפנדרי, יעקב","b":"מתורתו ב\"פקודת המלך\". חיבר פירוש לתורה בכת\"י."},{"i":4699,"n":"אלפנדרי, יעקב מספרד","f":"שלמה","b":"חתם תורני ובקי בלשון ערבית, חברו של ר שמואל ן סינה-צרצה ותרגם למענו פירוש על הרמב\"ם, ואת ספר העצמים שחבר האבן עזרא בערבית."},{"i":4700,"n":"אלפנדרי, יעקב מקושטא","f":"חיים","k":"בעל מוצל מאש","b":"רב ומשורר בקושטא-תל, חיבר הקדמה ל\"נתיבות המשפט\" לר חיים אלגזי. בנו - ר אליהו בעל \"סדר אליהו רבא וזוטא\". אחיו - ר יצחק רפאל."},{"i":4701,"n":"אלפנדרי, יעקב מקושטא","f":"יצחק רפאל","k":"בעל סדר מודעה","b":"רב בקושטא. אחיו של ר חיים. נפטר צעיר. מתורתו בספר אחיו."},{"i":4702,"n":"אלפנדרי, יעקב מקושטא","f":"יהודה מקושטא","b":"דיין בקושטא-תף."},{"i":4703,"n":"אלפנדרי, יצחק מספרד","b":"מגדולי חכמי טולידו-שנת כ'"},{"i":4704,"n":"אלפנדרי, יצחק מקושטא","b":"מגדולי רבני קושטא-תקס\"ד"},{"i":4705,"n":"אלפנדרי, יצחק מקושטא","b":"מגיה ופועל בדפוס ר יונה יעקב אשכנזי בקושטא. סייע בהדפסת \"אש דת\" לקרובו."},{"i":4706,"n":"אלפנדרי, יצחק מקושטא","f":"אברהם","b":"מדפיס-תעא בדפוס של יונה בן יעקב בקושטא."},{"i":4707,"n":"אלפנדרי, יצחק משלוניקי","f":"משה","b":"מחכמי שלוניקי-שנות ה-ת'."},{"i":4708,"n":"אלפנדרי, יצחק רפאל מקושטא","f":"חיים","k":"בעל מגיד מראשית","bp":"קושטא","dt":"תט-י?","dp":"צפת?","b":"תלמיד ר יוסף מטרני, ור אהרן קופינו. רב בקושטא, עבר לשלוניקי, רב בקהלת \"גרוש\" בברוסה-תכב עם ר שמואל סאגיס, עלה לצפת. אחיו של ר יעקב מקושטא. (יש אומרים שלא הגיע לצפת). בניו - ר חיים ור יעקב (אחד מהם נפטר בחייו). (תאריך פטירתו צריך בדיקה)."},{"i":4709,"n":"אלפנדרי, מרדכי","b":"מגדולי חכמי ספרד לפני הגירוש-רנ\"ב"},{"i":4710,"n":"אלפנדרי, משה מספרד","b":"מחכמי טולידו-שנת ר'"},{"i":4711,"n":"אלפנדרי, משה מקושטא","b":"דיין בקושטא-תטו."},{"i":4712,"n":"אלפנדרי, משה משלוניקי","dt":"תכ-א - ב תשרי","dp":"שלוניקי","b":"מחכמי ישיבת ר שלמה הלוי הבחור. רב בשלוניקי. אחיו - ר יצחק מצפת. בנו - ר יצחק, בניו מתו בחייו."},{"i":4713,"n":"אלפנדרי, רחמים מירושלים","b":"רב בירושלים, רב עדת הספרדים בביירות-תר."},{"i":4714,"n":"אלפנדרי, שבתי מקושטא","b":"רב בקושטא-תץ, אחיו של ר חיים אליפנדרי הזקן. שלח שאלות לר חייא הרופא בעל \"מעשה חייא\" והשיב לו."},{"i":4715,"n":"אלפנדרי, שלמה אליעזר מקושטא וי","f":"יעקב בן שלמה","k":"בעל אש\"א עיני","bt":"תקעב-פו-פט","bp":"קושטא","dt":"תרצ - כב אייר","dp":"ירושלים","b":"מחכמי קושטא ועמד שם בראש ישיבה, ולמרות שלא נשא בתפקיד רשמי היה לפוסק החשוב בעיר, ומינה את תלמידו ר יצחק עקריש לרב העיר. רב בדמשק-תרנט, עלה לחיפה-תרסד, רב בצפת, בתרפו עבר לירושלים. מכל כתביו לא הדפיס בחייו מלבד במאסף \"תורה מציון\" ובספרי חכמי דורו. חיבר שו\"ת הסבא קדישא, ועוד. חלק מכתביו אבדו. (אין הסכמה על תאריך לידתו - נפטר הרבה למעלה מ-100. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. (נהג לחתום על הגהותיו \"אשא עיני\".","bk":[["מהרש\"א אליפנדרי [שו\"ת]",""],["אפקעתא דמלכא - שביעית",""],["אשא עיני - הגהות על ספר דברי אמת נדפס על הגליון",""],["שו\"ת הסבא קדישא",""],["שו\"ת הסבא קדישא, אפקעתא דמלכא - שביעית , אשא עיני - הגהות על ספר דברי אמת נדפס על הגליון",""]]},{"i":4716,"n":"אלפנדרי, שלמה מספרד","b":"מגדולי רבני ולנסיה-תכ\"ז"},{"i":4717,"n":"אלפנדרי, שלמה מקושטא","f":"חיים","dt":"תקלד - כז אדר","dp":"אורטה קיואי-קושטא","b":"דיין בקושטא-תקח, חתם אז על הסכמה ל\"שות הרמד\", בשנת תקכג חתם על מכתב קהילת חברון, ועוד הרבה תקנות והסכמות של הקהלה. בניו ר רפאל חזקיה חיים ור אברהם."},{"i":4718,"n":"אלפנדרי, שלמה משירון","b":"מראשי קהלת שירון-שנות ה-ת'."},{"i":4719,"n":"אלפנדרי, שמואל משלוניקי","dt":"תקלג","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":4720,"n":"אלפנט, אברהם מניר טאש","f":"אליעזר צבי","b":"תלמיד הכת\"ס. חתן ר יוסף קליין, מחכמי ניר טאש-תרכא. בנו ר דב בריש אלפנט רב בניו יורק - מו\"ל \"עין הבדולח\"."},{"i":4721,"n":"אלפני, אליהו מקושטא","f":"דוד","b":"מחכמי קושטא, חתם-רפ על החזרת השתדלן ר שאלתיאל."},{"i":4722,"n":"אלפס בנציון בן ירמיהו עקיבא","bt":"1851","dt":"ה'תש 1940","bk":[["א ווירקליכע הערצליכע ליעבע",""],["א ריינע הערצליכע ליעבע",""],["אוצר התורה",""],["ברית ציון",""],["דער קלוגער קינד",""],["הייליגער",""],["סוד קיומנו",""],["קלוגער קינד",""]]},{"i":4723,"n":"אלפס, בנציון מוילנא וירושלים","f":"ירמיהו עקיבא","k":"בעל מקור דמעה","bt":"1851","bp":"וילנא","dt":"1940","dp":"ירושלים","b":"תלמיד ישיבת איישישוק. עלה לארץ-תרלב והתישב בירושלים, עבר לחברון. חזר לוילנא ועבד כמגיה בבית דפוס. חיבר ספרים עממיים לנשים עם תוכן דתי ומוסרי כדי להרחיקם מספרות פסולה. חיבר תחינות, \"אוצר התחיה\", ועוד. תרגם לאידיש \"שערי תשובה\" לר יונה גירונדי, ועוד. עבר במקומות שונים והשפיע בדרכי המוסר. עלה לירושלים שנית-תרפב."},{"i":4724,"n":"אלפסי, אברהם מדזעויצא","f":"משה שמחה מאופוטשנא","bt":"תקפז","dt":"תרעב - ח שבט","b":"חתן ר נחמיה רוטנברג בן ר אהרן אליהו-אחיו של בעל חדושי הרי\"ם. תלמיד ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר, ועוד. נתקבל כרב באופוטשנא-תרכב אולם סירב, רב בדזעויצא."},{"i":4725,"n":"אלפסי, דוד הקראי","f":"אברהם","k":"בעל אגרון","b":"חכם קראי בן דורו של ר סעדיה גאון."},{"i":4726,"n":"אלפסי, חיים מאזמיר","dt":"תפו - יד אב","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":4727,"n":"אלפסי, חיים מטיריא","b":"שו\"ב מחכמי טיריא-שנות ה-ת'."},{"i":4728,"n":"אלפסי, חיים מתונס","f":"רפאל מסעוד","dt":"תקמג - יח אדב","b":"מרבני תונס"},{"i":4729,"n":"אלפסי, יעקב הכהן מאלגיר","k":"אבי הרי\"ף","dp":"קלעה חמאד-אלגיר","b":"רב בקלעת בני חאמאד-אלגיר. אביו של הרי\"ף."},{"i":4730,"n":"אלפסי, יעקב ממרוקו וספרד","f":"יצחק - הרי\"ף","bp":"פאס","b":"עבר עם אביו מפאס לספרד, רב באלוסינא בחיי אביו אך לא כיהן ברבנות אחריו (אלא ר יוסף מיגאש - ע\"פ צוואת הרי\"ף)."},{"i":4731,"n":"אלפסי, יצחק","f":"ראובן","k":"בעל שערים דרב אלפס","b":"נכדו או נינו של הרי\"ף. מגדולי חכמי דורו-ד'תתק\"מ"},{"i":4732,"n":"אלפסי, יצחק - הרי\"ף","f":"יעקב הכהן מאלג'יר","k":"הרי\"ף","bt":"ד'תשעג","bp":"קלעת חמאד-אלגיר","dt":"ד'תתסד - י אייר","b":"גדול הפוסקים הראשונים, מאור הגולה, מרביץ תורה בצפון אפריקה, ראש הישיבה בקירואן, ברח לספרד והתישב בקורדובה-ספרד, רב של אליסנה(=לוסינה). חיבר שו\"ת, וספר הלכות. מתלמידיו: ר אפרים קלעי."},{"i":4733,"n":"אלפסי, יצחק מספרד","f":"יוסף","k":"בעל משכיות האורות","b":"מחכמי ספרד, פילוסוף. העתיק ותרגם את ספרי אבוחמד אלגזלי - \"משכיות האורות\", \"פרדס הנצנים\"."},{"i":4734,"n":"אלפסי, יצחק מראבאט","b":"סופר בי\"ד בראבאט-תקמט."},{"i":4735,"n":"אלפסי, מימון מפאס","b":"מחכמי פאס, חתם-תפט עם ר יהודה ן עטר."},{"i":4736,"n":"אלפסי, מסעוד מספרד ותונס","b":"מגדולי רבני ספרד בתקופת הגירוש,רב בתוניס-ש\"ט"},{"i":4737,"n":"אלפסי, מסעוד מתונס ואלגיר","k":"בעל משחא דרבותא","dt":"תקלה - ב טבת","dp":"תונס","b":"מחכמי פאס, למד אצל ר רפאל ידידיה צרור באלגיר, היה בדרכו לעלות לארץ עם ר שמעון לביא ור אהרן פרץ ובדרכו הגיע לתונס-תפג, ולבקשתם נשאר שם, מגדולי הרבנים בתונס, והשיב לכל רחבי צפון אפריקה ובעיקר לאלגיר וכן השיב לאיטליה ועוד. בניו ר שלמה - אב\"ד תונס ור חיים. חתנו - אחי אשתו - ר משה עשור. נכדיו שהדפיסו את ספרו - ר חיים עשור ור רפאל ראובן רחמים קורקוס - וכתבו הקדמה והערות לספר. חיבר גם ספרים בקבלה ו\"כללי התלמוד\" בכת\"י - ואבדו. ב\"שבחי הצדיקים\" מסופר על הנס שנעשה לו עם האריה."},{"i":4738,"n":"אלפסי, מרדכי ממראקש","b":"רב במראקש-תקסה, חידוש ממנו אצל ר יצחק ן נאים."},{"i":4739,"n":"אלפסי, משה שמחה מאופוטשנא","dt":"תרכב - ג חשון","b":"מבחירי החבורה של ר שמחה בונם מפשיסחא. נודע בגאונותו ובעושרו - גיסה של תמריל ברגסון."},{"i":4740,"n":"אלפסי, ראובן מספרד","bp":"פאס","b":"נכדו של הרי\"ף (ויש אומרים בנו של הרי\"ף). מגדולי חכמי ישראל בקורדובה-ד'תתקי (1150). בנו - ר יצחק אלפסי."},{"i":4741,"n":"אלפסי, שלמה מטבריה","dp":"טבריה","b":"מחכמי טבריה בזמן ר חיים אבולעפיה ור אליעזר ן דנאן. חתם על כתב שליחות ר דוד בכור יונה, ר יהודה נחמד-תקצא, ור חיים שמואל הכהן קונורטי-תר."},{"i":4742,"n":"אלפסי, שלמה מתונס","f":"מסעוד רפאל-משחא דרבו","k":"בעל כרוב ממשח","bp":"תונס","dt":"תקסא - טו תמוז","b":"רב בתונס. מתורתו בספר אביו \"משחא דרבותא\". חיבר \"כרוב ממשח\" ונדפס עם \"חיים וחסד\" ליוורנו תריט."},{"i":4743,"n":"אלפקי, יהודה ממונסטיר","b":"רב במונסטיר-שנות ה-ש'."},{"i":4744,"n":"אלפרה, יצחק","bp":"ספרד","dt":"רז - לפני","dp":"ירושלים","b":"מחכמי ירושלים, עלה עם גיסו ר משה אלמושנינו ואת אשתו השאיר במלאגה (ספרד) משום שסרבה לעלות ונשא אשה אחרת. מוזכר בשות הרשבש שאלה בנוגע לחליצה לאשתו לאחר פטירתו."},{"i":4745,"n":"אלפרכו, שם טוב מדמשק","b":"רב קהלת המסתערבים בדמשק-רפא."},{"i":4746,"n":"אלפרן, מרדכי מקובנא","f":"יהודה","bt":"1874","bp":"קובנא","dt":"1949","dp":"תל אביב","b":"תלמיד ישיבה וולוזין, והתחבר שם לאגודה ציונית. סוחר בקובנא ומראשי המרכז הציוני בליטא וממיסדי \"אידישע שטימע\". עלה לארץ-1932."},{"i":4747,"n":"אלפרנג'י, משה מברוסה","b":"רב בברוסה(=ברושה) עם ר אברהם אשיאו."},{"i":4748,"n":"אלפרנג'י, משה ממצרים","b":"מגדולי רבני מצרים-ש\"ל"},{"i":4749,"n":"אלפרנג'י, משה מצפת","f":"שם טוב","bp":"ספרד","dt":"רסו-רעא","dp":"צפת או ירושלים","b":"תלמיד ישיבת ר יצחק קנפנטון - יחד עם חברו ר יצחק אבוהב, ראש ישיבה בואליאדוליד. לאחר הגירוש התישב בברושא-תורכיה, עלה לצפת-רנט, חתם ראשון על אגרת חכמי צפת לירושלים אודות שנת השמיטה-רסד, עבר לירושלים. חיבר קונטרס בענין טריפות. בנו - ר שם טוב מחכמי צפת-רסד, ועבר לירושלים עם אביו, ולימים רב בדמשק."},{"i":4750,"n":"אלפרנג'י, שלמה ממצרים","f":"שם טוב","b":"מצאצאי ר מאיר ן טודרוס הלוי הנקרא גם ר מאיר אבולעפיה וכנראה שגם שמו של ר שלמה היה אבולעפיה והשם אלפרנאג'י הוא על שם מוצאו מאירופה. מחכמי קהיר בזמן ר יעקב קסטרו המזכירו בספרו."},{"i":4751,"n":"אלפרנג'י, שם טוב מדמשק","f":"משה","b":"מחכמי דמשק, עלה לצפת-רסד, וחזר לדמשק-רפא. נשא ונתן עם ר יוסף קארו."},{"i":4752,"n":"אלפרנסי, יהודה מגזילי","b":"רב בגזילי-ליד תירייא - בדור שלאחר הגירוש."},{"i":4753,"n":"אלפרשטין, אברהם אליעזר","f":"ישעיה","k":"בעל הר אל","bt":"תריג","bp":"קוברין-פלך גרודנא","dt":"תרעז","dp":"ניו יורק","b":"תלמיד קרובו הרידב\"ז, ישיבות וילנא וקובנה. חתן הגביר ר משה שניידר ממלדעטשנא (ממשפחת הגר\"א). רב בבהכנ\"ס בוילנא, רב בנובוגרד-ליד וילנא, סלובודקה, שיקגו-תרמא, ניו יורק-תרמד, סט פאול, קהלת \"משכן ישראל\" בניו יורק-תרסא. נסמך מאת: ר מרדכי מלצר מלידא, ר אריה ליב שכנוביץ (ילין) בעל \"יפה עינים\", פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג. חיבר גם \"פרי גנוסר ופרי הלולים\" - בכת\"י."},{"i":4754,"n":"אלץ-גוט, אליהו סמרגונר","f":"הלל הלוי מוילנא","k":"בעל יד אליהו","bt":"תקמג","dt":"תרכג - כז כסלו","dp":"וילנא","b":"תלמיד ר שמואל אוטינאנער. חתן הגביר ר דוד דאנושעווער מסמרגון. דיין בסמרגון, וילנא-תקפג. הסכים על ש\"ס וילנא-תקצה, ועוד. חתנו ר מנחם מנדל טברסקי - דיין בוילנא. בנו ר נחום טוען. מתלמידיו: ר אליעזר לנדא בעל \"דמשק אליעזר\", ר יצחק ליב רבינוביץ, ועוד."},{"i":4755,"n":"אלצהארי, זכריה יחיא מתימן","f":"סעדיה בן יעקב","k":"בעל ספר המוסר","b":"גדול בתורה ובשיר, מגדולי חכמי תימן בצנעא-שכה-שס, ביקר בירושלים-שלד, והביא אגרת לחכמי טבריה."},{"i":4756,"n":"אלצורפי, אברהם מבבל","f":"מוסר","k":"בעל ספר הגלוי -החלפן","b":"מחכמי בבל-ד'תש, תלמיד רס\"ג, חיבר ספר \"אלכשאף\"(=הגילוי)"},{"i":4757,"n":"אלצייג, שלמה מאיפסולה","b":"מחכמי איפסולה-תכז, חתום על ההסכם עם נתן העזתי."},{"i":4758,"n":"אלצייג, שמואל משה מסליבנה","b":"רב בסליבנה(=איסלימנה)-תקן בערך. דיינים אצלו - ר יהודה יוסף דנון, ר רחמים אליעזר הלוי."},{"i":4759,"n":"אלצפט, יוסף הכהן מפאס","f":"מרדכי","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":4760,"n":"אלצפן מוידין","f":"אברהם","dt":"תקלא - יג אב","dp":"וידין","b":"מחכמי וידין, בנו - ר אברהם בן אלצפן מוידין."},{"i":4761,"n":"אלקאיים, אברהם ממרוקו","b":"מחכמי מרוקו-תקם."},{"i":4762,"n":"אלקאיים, אברהם מעזה","bp":"דמשק?","dp":"עזה","b":"בערוב ימיו עלה לעזה, נזכר כמגיה בספרים \"כסף נבחר\" לר' יאשיהו פיגו, וספר \"נעים זמירות ישראל\"."},{"i":4763,"n":"אלקאיים, דוד מאצווירא","b":"מקובל, רב באצווירא-תק\"ס"},{"i":4764,"n":"אלקאיים, דוד ממוגאדור-מרוקו","b":"מו\"ץ במוגאדור-שנות ה-תק', הסכמה ממנו ב\"מאור ושמש\"."},{"i":4765,"n":"אלקאיים, דוד ממראקש","b":"מחכמי מראקש-שנות ה-תק'."},{"i":4766,"n":"אלקאיים, ישועה מאלגיר","bt":"תקס","dt":"תרם - בערך","b":"חתן ר חיים דוד שלמה זוראפה. רב וראש ישיבה בלמדייא(=מידיאה)-אלגיר, בזמן ר חיים פלאגי, שהשיב לו בספרו. חיבר הקדמה לספר חותנו \"שער שלמה\". הסכים על \"כרם חמר\", ועוד. החזיק בספריה גדולה בביתו. יועץ למושל העיר (ביי) וסייע לבני עדתו."},{"i":4767,"n":"אלקאיים, משה ממרוקו","f":"שמעיה","k":"בעל תועפות ראם","b":"מחכמי מרוקו. חיבר פירוש לתורה."},{"i":4768,"n":"אלקאיים, סאלם ממכנאס","b":"מחכמי מכנאס-תקפז."},{"i":4769,"n":"אלקאיים, עמרם ממראקש","b":"מחכמי מראקש. חיבר פירוש על אזהרות."},{"i":4770,"n":"אלקבץ שלמה בן משה","bt":"1505","dt":"ה'שלו 1576","bk":[["אילת אהבים",""],["ברית הלוי",""],["מנות הלוי",""],["שרש ישי",""]]},{"i":4771,"n":"אלקבץ, יהושע הלוי משלוניקי","f":"שלמה","dt":"שץ - כד טבת","dp":"שלוניקי","b":"מחכמי שלוניקי-שנות הר'. דודו של ר שלמה אלקבץ-בעל \"לכה דודי\"."},{"i":4772,"n":"אלקבץ, יוסף מאדרינופול","b":"רב באדרינופול, תמך-תקסט בר אהרן אברהם ארוליא בענין המחלוקת ברוסג'וק."},{"i":4773,"n":"אלקבץ, יצחק הלוי מקושטא","bp":"שלוניקי","dp":"קושטא","b":"גביר מחכמי שלוניקי, עבר לקושטא-תח בגלל המגפה."},{"i":4774,"n":"אלקבץ, יצחק הלוי משלוניקי וירו","dp":"ירושלים","b":"עשיר, מגדולי שלוניקי ואדרינופולי, עלה לירושלים."},{"i":4775,"n":"אלקבץ, יצחק מסידרוקאפסי","bp":"שלוניקי","b":"גביר בסידרוקאפסי-תורכיה, תרם לת\"ת בשלוניקי - לפני שמג."},{"i":4776,"n":"אלקבץ, מסעוד (סעייד) הלוי מאלג","f":"יוסף","bt":"תקנט","bp":"אלגיר","b":"רב באלגיר, עלה לצפת-תקצד והיה מחכמי צפת. בשליחות באדרינופול-תרח, בשנת תרג חתם על תקנת הגאבילה. עליו ב\"ספונות\" ו."},{"i":4777,"n":"אלקבץ, משה הלוי - הנכד","f":"שלמה","k":"בעל נועם ה'","bt":"[רצט]","bp":"צפת","dt":"שמא","dp":"חלב","b":"נכדו של ר משה אלקבץ. תלמיד ר יוסף קארו, הגיע לקושטא-שכד עם אביו והו\"ל ספר אביו \"שרש ישי\"-שכו, וחזר לצפת. רב בחלב-שלג. חיבר \"נועם ה'\" על התורה ואבד. נספד ע\"י ר מיכאל קודוטו מאיטליה."},{"i":4778,"n":"אלקבץ, משה הלוי מצפת","b":"רב בצפת. מוזכר בספרי בנו - \"שורש ישי\", \"מנות הלוי\", \"אילת אהבים\"."},{"i":4779,"n":"אלקבץ, משה הלוי משלוניקי - חלב","f":"שלמה","b":"מחכמי שלוניקי, אדרינופול, עבר לארם צובא ואחר כך עלה לצפת. אביו של ר שלמה אלקבץ בעל \"לכה דודי\". נזכר ב\"אהלי תם\" לר תם ן יחיא, שו\"ת המבי\"ט."},{"i":4780,"n":"אלקבץ, משה מספרד","b":"נקרא גם בשם ר משה אמרקויט ור משה אלקויט. רב בקלעת איוב-ספרד-קכז (1367), בהוראת המלך פדרו הרביעי, לאחר מיכן ביטל המלך את המינוי בגלל שסתר הוראה קודמת שבני הקהלה יבחרו ברב בעצמם. ולאחר מכן המשיך לכהן כדיין שם. משרת הרבנות הוצעה לריב\"ש, ולבסוף כיהן ר שלמה ראובן."},{"i":4781,"n":"אלקבץ, סעיד מצפת","f":"יוסף הלוי","b":"מחכמי צפת. וחתם-תרג על תקנה, ונזכר ב\"משא חיים\" לר חיים פלאג'י."},{"i":4782,"n":"אלקבץ, רפאל חיים יצחק מירושלי","bt":"תקכא - בערך","dt":"תקצב - כו חשון","dp":"ירושלים","b":"מקובל, דיין באדרינופול-תקנה, סופר הקהל, עלה לירושלים-תקצא בסוף ימיו. פסק לטובת ר מרדכי בכמוהר\"ר מנחם מאדרינופול במחלוקת עם ר שלמה פאלומבו ושותפו בענין זכיון המסטיק. (השם חיים רפאל נוסף לו בזמן מחלתו). חדושי תורה שלו נתגלו על ידי מ.ד. גאון."},{"i":4783,"n":"אלקבץ, שלמה הלוי הזקן","b":"נזכר בספרי נכדו - ר שלמה - \"שורש ישי\", ו\"אילת אהבים\"."},{"i":4784,"n":"אלקבץ, שלמה הלוי מצפת","f":"משה מספרד","k":"בעל לכה דודי","bt":"רס - רסה","bp":"אדרינופול","dt":"שמד או שלח-ט","dp":"צפת","b":"מחכמי שלוניקי מצאצאי גולי ספרד. נכד זקנו ר שלמה. למד אצל ר יוסף טייטצאק. חתן הגביר ר יצחק הכהן-מעשירי שלוניקי, וכמתנת אירוסים שלח לה את ספרו \"מנות הלוי\", היה גיסו ורבו של ר משה קורדוברו. עלה עם אביו לצפת והיה מגדולי המקובלים בין שומעיו היה ר יוסף קארו. חיבר \"ברית הלוי\" למברג תרכב, ועוד."},{"i":4785,"n":"אלקבץ, שלמה מספרד","b":"מחכמי ספרד, ואחרי הגירוש התישב בשלוניקי. היה מדפיס בקשטיליה - הדפיס פירוש לתורה - רלו. נכדו - ר שלמה אלקבץ בעל \"לכה דודי\". חתם עם חבריו בשלוניקי-רעד."},{"i":4786,"n":"אלקבצי, יעקב מאמאסיה-תורכיה","f":"אברהם","b":"מחכמי אמאסיה(=מסיא)-תורכיה-רסה."},{"i":4787,"n":"אלקובי - משפחה","b":"כנראה מקור השם ב-אליעקובי הנזכר ב\"מלכי רבנן\"."},{"i":4788,"n":"אלקובי, אהרן מאלגיר","f":"נסים","k":"בעל אור החמה","b":"רב ודיין בתלמסאן. חתם על פסק דין-תרעה. חיבר \"אור החמה\" ביחד עם ר אברהם בן סאמון."},{"i":4789,"n":"אלקובי, מ' ממכנאס","b":"מחכמי מרוקו-תקנג, נזכר ב\"תקפו של יוסף\"."},{"i":4790,"n":"אלקוביץ, לימא","b":"ראש ישיבה בסלונים"},{"i":4791,"n":"אלקונסטנטיני, עובדיה משלוניקי","f":"ראה: אלקוסטנטיני","bp":"ניקופול"},{"i":4792,"n":"אלקוסטיל, יוסף","b":"רב בזמן ר יהודה חייט שהביא מדבריו ב\"מערכת האלוקות\". הזכירו גם \"ר\"ש הלוי ן אלקבץ בספרו \"אפריון שלמה\"."},{"i":4793,"n":"אלקוסטנטיני, אברהם מספרד","b":"מחכמי ספרד. עלה לארץ-ד'תתקל ושם פגש בר בנימין מטודלה שכתב עליו ומכנהו ר אברהם החסיד מאבלי ירושלים."},{"i":4794,"n":"אלקוסטנטיני, דון בונאפוס משלונ","dt":"רץ - לפני","b":"מחכמי איניון, ניקופול, שלוניקי. גיסו (ולפי רוזניס - דודו-אחי אמו) של ר יוסף הכהן בעל \"עמק הבכא\". בנו - ר עובדיה משלוניקי."},{"i":4795,"n":"אלקוסטנטיני, דון טודרוס","b":"מחכמי ספרד-ק\"נ-ר', רב בגושקה, משלוחי הקהילות לויכוח עם המומר לורקי"},{"i":4796,"n":"אלקוסטנטיני, חנוך","f":"שלמה","k":"בעל מראת אלקים","b":"מגדולי חכמי המחקר ביהדות ספרד-ק\"ס. חיבר \"מראת אלוקים\" בכת\"י על יחזקאל ופירוש על האבן עזרא."},{"i":4797,"n":"אלקוסטנטיני, יצחק מאנקונא","b":"רב באנקונא-תק והקים שם ישיבה בשם \"ישיבת שלום\". מתורתו ב\"פחד יצחק\", ב\"שמש צדקה\". ראש ישיבת שלום באנקונא עם ר משה שמואל גיניטי. מוזכר ב\"שירי זמרה\" לר\"י מוסאטי."},{"i":4798,"n":"אלקוסטנטיני, משה מקנדיא","f":"מנחם","bp":"קנדיא(=כרתים)","b":"רב בקנדיא-תל על מקום ר אברהם ברוך."},{"i":4799,"n":"אלקוסטנטיני, עובדיה מניקופול","f":"בונאפוס","bp":"ניקופול","b":"רב בשלוניקי-בשנות ה-ר'-ש'. גיסו או אחיינו (לפי רוזניס - בן דודו) של ר יוסף הכהן בעל \"עמק הבכא\"."},{"i":4800,"n":"אלקוסטני ן, משה מסארסוגה","f":"בחיי","b":"מחכמי סארגוסה-ספרד-תחילת האלף השישי. דיין בולנסיה-ספרד בכח המלכות - ע\"י דודו ר שלמה שהיה מקורב למלכות - והיה מחלוקת על כך ובראש המתנגדים היה דון יהודה קלבאריא. היה מקורב למלך ונאסר וחזר למעמדו והיה מתורגמן המלך עם הערבים בספרד."},{"i":4801,"n":"אלקוצר, בנימין מירושלים","bt":"תרכו","bp":"ירושלים","b":"מגדולי חכמי ירושלים"},{"i":4802,"n":"אלקחלי, אברהם מאלקלעי-ספרד","b":"רב באלקעלי-ספרד-קן. מתלמידיו: ר שמואל בן ביבאש, ר\"ר חביב."},{"i":4803,"n":"אלקחלי, שם טוב מספרד","b":"רב וראש ישיבה באלקלעא-ספרד, בדור שלפני הגירוש. רבו של ר משה אבורביע."},{"i":4804,"n":"אלקין, אברהם יוסף מארהיוב","f":"משה חיים מארהיוב","bt":"תרלד","b":"רב בארהיוב-בסרביה-תרסב על מקום אביו. חיבר ספר על תריג מצוות - בכת\"י."},{"i":4805,"n":"אלקין, משה חיים מארהיוב","b":"רב בארהיוב-בסרביה-תר\"ס"},{"i":4806,"n":"אלקין, שלמה זלמן מאלטונא","dt":"תס - א תמוז","dp":"אלטונא","b":"מחכמי אלטונא. נפטר צעיר."},{"i":4807,"n":"אלקין, שמואל אליהו מביחוב","k":"בעל דבר שמואל","b":"רב בביחוב, ברונזויל-ניו יורק."},{"i":4808,"n":"אלקלעי, אברהם מאלגיר","bt":"ד'תת - בערך","dt":"ד'תתע - בערך","b":"רב ודיין בקלעת בני חאמאד. נזכר במכתבים בגניזה בקהיר."},{"i":4809,"n":"אלקלעי, אברהם מדובניצה וצפת","f":"שמואל","k":"בעל זכור לאברהם","bt":"תץ-תקט-תקכא","bp":"שלוניקי","dt":"תקעא - כו אדר","dp":"צפת","b":"מצאצאי ר יעקב אריה (לב אריה) בעל הנס. נכד-אבי אמו - ר משה ברכה משלוניקי והספד ממנו על זקנו-תקיו. תלמיד ר' יוסף ן יעיש, ראש ישיבה בדובניצה (בזמן רבנות ר יעקב נסים)-תקם, עלה לארץ-תקע, חיבר \"זכור לאברהם\" שלוניקי תקלז, שות \"חסד לאברהם\" שלוניקי תקעג, דרושים לשבתות השנה בכת\"י (ספריה לאומית). בניו: ר משה, ר יוסף חיים, ר שמואל, ר משה. אחיו - ר משה."},{"i":4810,"n":"אלקלעי, אברהם מסופיה","b":"חזן בסופיה. בנו - הרב ד\"ר יצחק אלקלעי - רבה של יוגוסלביה."},{"i":4811,"n":"אלקלעי, אהרן מנצור מטבריה","f":"בן ציון מטבריה","bt":"תרמז","bp":"טבריה","b":"עבר בילדותו לחברון, ואחר כך לירושלים, היה עוזרו וסופרו של אביו שהיה עיוור."},{"i":4812,"n":"אלקלעי, אפרים מירקדו מדמשק","dt":"תרנה - יא חשון","dp":"ירושלים","b":"מחכמי סרביה, רב בדמשק, מקובל בירושלים."},{"i":4813,"n":"אלקלעי, אריה מירושלים","f":"יעקב","k":"בעל מכשירים לפיסיקה","bt":"תרנה","bp":"פיליפופולי-יוון","b":"עסקן צבור, ומחנך בירושלים. חיבר גם \"שער לשוננו\" עם אבינועם ילין ואריה אילן."},{"i":4814,"n":"אלקלעי, בן ציון ממרוקו וירוש","f":"משה מטבריה","k":"בעל עשיר ורש","bt":"תריח","bp":"רבאט-מרוקו","dt":"תרעג - כ אב","dp":"ירושלים","b":"נסמך מאת: ר יעקב שאול אלישר, ר יצחק אבולעפיה בעל \"פני יצחק\". עלה לטבריה-תרלז, היה סגינהור, בשנת תרלח בשליחות, ובשנת תרכו שליח קהילת חיפה. בתרסב עבר לחברון ונתמנה דיין אצל ר חיים חזקיהו מדיני, אחר כך עבר לירושלים, בשליחות עם בנו אהרן מנצור אלקלעי לצפון אפריקה ולמצרים. חיבר גם \"הלכה רווחת\", ועוד.","bk":[["חמדת ירושלים",""]]},{"i":4815,"n":"אלקלעי, דוד מבלגרד - א","f":"משה","bt":"תקעד","bp":"בלגרד","dt":"תרמב","dp":"וינה","b":"סופר ומחנך בבלגרד, עבר לוינה. תרגם פרקי אבות לספרדית, הו\"ל סידור \"עבודת השנה\"-תרטז. בנו - ר משה."},{"i":4816,"n":"אלקלעי, דוד מבלגרד - ב","f":"משה","bt":"תרכב","dt":"תרצג - ח שבט","b":"מראשי קהלת בלגרד, עסקן ציוני. חיבר פרקי זכרונות - בכת\"י."},{"i":4817,"n":"אלקלעי, דוד מירושלים","f":"שמואל","dt":"תקפט - י אדר","dp":"ירושלים","b":"מחכמי ירושלים מחברי \"בית אל\"."},{"i":4818,"n":"אלקלעי, דוד מירושלים","b":"מראשי הח\"ק בירושלים. הסכים על \"חלקת מחוקק\"-תרסא."},{"i":4819,"n":"אלקלעי, דניאל מירושלים","dt":"תרה - ה כסלו","dp":"ירושלים","b":"בן אחיו של ר אברהם אלקלעי בעל \"זכור לאברהם\" ו\"חסד לאברהם\". מחכמי ישיבת \"בית אל\" בירושלים, חתם על הסכמה לספר \"דברי שלום\" וכן על אגרת הסכמה משנת תרה, סייע לר ישראל בק ביסוד בית הדפוס בירושלים-תרא, ואסף עבורו הסכמות הספרדים לבל יפתח דפוס אחר עד שנת תרך, סידר לראשונה את ספרי החיד\"א בשם \"עבודת הקודש\". הו\"ל \"עבודת הקדש\" לחיד\"א. חתם על שטרת שליחות ר מיכאל באדהב-תרה. נזכר בהקדמת ר מאיר בנימין דנון בספרו \"באר בשדה\"."},{"i":4820,"n":"אלקלעי, חיים מירושלים","f":"דוד","dt":"תקעט - א ניסן","dp":"ירושלים","b":"מחכמי ירושלים מתלמידי \"בית אל\", ר יום טוב דאנון כותב עליו, נפטר בלא בנים."},{"i":4821,"n":"אלקלעי, חיים נסים מפיליפופולי","bt":"תקפה","bp":"פיליפופולי","dt":"תרכ","dp":"פיליבי","b":"עלה לירושלים ללמוד ונסמך לרבנות, רב ואב\"ד פיליפופולי-תרז (בגיל 22). מתלמידיו - ר חיים בג'ראנו מקושטא. בנו - ר יעקב - עלה לירושלים-תרצב."},{"i":4822,"n":"אלקלעי, יהודה חיים","f":"משה מדובניצה","b":"נכד ר אברהם בעל זכור לאברהם. הגיה ספר זקנו \"חסד לאברהם\" והוציאו לאור - שלוניקי תקעד."},{"i":4823,"n":"אלקלעי, יהודה חיים משלוניקי","f":"משה","dt":"תרט","dp":"שלוניקי","b":"דיין בשלוניקי-תרא. הו\"ל \"שעת רצון\" לר שלמה הכהן, \"מטה אהרן\" לר אהרן הלוי, ועוד. הגיה ספרי דודו - ר אברהם אלקלעי. החזיק בספריה הגדולה והחשובה ביותר בזמנו בכל המזרח."},{"i":4824,"n":"אלקלעי, יהודה שמואל חי","f":"שלמה","k":"בעל גורל לה'","bt":"תקנח-עז","bp":"סרייבו","dt":"תרלט - ד תשרי","dp":"ירושלים","b":"תלמיד ר אליעזר פפו, עלה לירושלים בצעירותו, רב בזמלין ליד בלגרד, תומך ומשפיע לרעיון השיבה לארץ ישראל. בשנת תרלג חזר לירושלים. חיבר \"גורל לד'\" וינה תריז, \"דרכי נועם\" בלגרד תקצט ועוד."},{"i":4825,"n":"אלקלעי, יוסף חיים מדובניצה","f":"אברהם - זכור לאברהם","b":"רב בדובניצה, ועסק גם במסחר. הו\"ל ספר אביו."},{"i":4826,"n":"אלקלעי, יוסף מירושלים","f":"דוד שמואל","k":"בעל אמר יוסף","dt":"תקעח (באו תקפ","dp":"אזמיר","b":"מחכמי ירושלים, הגיע לאזמיר עם אביו ונעזרו שם בגביר ר יוסף חמצי, ונפטר בחיי אביו. חיבר \"אמר יוסף\" שלוניקי תקצא. באוצר נפטר אחרי תקף"},{"i":4827,"n":"אלקלעי, יוסף מקושטא","b":"מדפיס בקושטא עם שותפיו רפאל טרוויש ויהושע מזרחי, הדפיסו \"חדושי גטין\"-תעא."},{"i":4828,"n":"אלקלעי, יזרעאל מניש","dp":"תקסה - בערך","b":"חתן ר יהודה ן משה עלי מירקאדו מניש בעל \"קמח סולת\". מלמד תינוקות מחכמי ניש, נהרג בדרכו ליד סאמאקוב-תקסה."},{"i":4829,"n":"אלקלעי, יעקב מטבריה","b":"מרבני טבריה-תרמ\"ח"},{"i":4830,"n":"אלקלעי, יצחק מבלגרד","f":"אברהם מסופיה","bt":"תרמא","bp":"סופיה","b":"רופא וד\"ר לפילוסופיה. רב ראשי בבלגרד, ראש הרבנים ביוגוסלביה."},{"i":4831,"n":"אלקלעי, לוי מקלעה חמאד-אלגיר","f":"יעקב","k":"בעל קיצור ספר השבועו","b":"רב בקלעת בני חאמאד (עיר הולדתו של הרי\"ף - אך יש חולקים על כך - ישראל שציפנסקי). חיבר שיר קיצור ספר השבועות לרב האי גאון."},{"i":4832,"n":"אלקלעי, מאיר מאזמיר וטבריה","dt":"תקן - לפני","dp":"טבריה","b":"מחכמי אזמיר, עלה לטבריה יחד עם ר חיים אבולעפיה-תקב. חתם על כתב שליחות ר דוד גפני-תקלו, ר רפאל אברהם לב אריה-תקמה. בשנת תקפז היה בשליחות באדרינופול."},{"i":4833,"n":"אלקלעי, משה מבלגרד ווינה","f":"דוד","k":"בעל בואו חשבון","bt":"תקצד","bp":"בלגרד","dt":"תרסא","dp":"וינה","b":"עבר לסרייבו, וינה והיה מראשי המשכילים, מדפיס בוינה. חיבר גם \"חנוך לנער\", \"היסטוריה די קולומבוס, ועוד."},{"i":4834,"n":"אלקלעי, משה מדובניצה","b":"רב בדובניצה, ועסק גם במסחר.בנו - ר יהודה חיים."},{"i":4835,"n":"אלקלעי, משה מטבריה","bp":"ניש-סרביה","dt":"תרלד - כ תשרי","dp":"טבריה","b":"עלה מניש-סרביה לירושלים ולבסוף טבריה. בשליחות במרוקו-תקצז ובזמן שליחותו נספתה משפחתו ברעש בטבריה. התחתן בשנית בעיר רבאט ונשאר שם. חזר לארץ לאחר 37 שנה. בנו - ר בן ציון אלקלעי, חתנו - ר חביב חיים דוד סתהון מטבריה."},{"i":4836,"n":"אלקלעי, משה משלוניקי","dt":"שפה","dp":"שלוניקי","b":"מגדולי מרביצי התורה בשלוניקי-ש\"ס, מתלמידיו: ר דניאל אישטרושא, ר יהודה בנבנישתי, ר יוסף פרץ, ר יוסף צרפתי, ר ידידיה קארו. חבוריו נשרפו בתבערה הגדולה-שפה."},{"i":4837,"n":"אלקלעי, שלמה חי מטימישואר","dt":"תרכג - יז אלול","b":"רב הקהלה הספרדית בטימישואר-תקצא - למעלה משלושים שנה, לצד ר יוסף לוי בעל \"בן אבות הלוי\". (במורשת הונגריה - שמו ר משה)"},{"i":4838,"n":"אלקלעי, שלמה מירושלים","f":"דניאל","dt":"תרמב - י טבת","b":"רב בירושלים-תריא."},{"i":4839,"n":"אלקלעי, שמואל מדובניצה","f":"אברהם - זכור לאברהם","b":"רב בדובניצה, ועסק גם במסחר. הו\"ל ספר אביו."},{"i":4840,"n":"אלקלעי, שמואל מטבריה","f":"אברהם","dp":"טבריה","b":"רב בטבריה-תקצא."},{"i":4841,"n":"אלקלעי, שמואל משלוניקי","b":"מחכמי שלוניקי-שנות ה-ר'-ש'."},{"i":4842,"n":"אלקנה","f":"אביגדור-אבן גדור","k":"בעל ספר הקנה","b":"נכד ר נחום המקובל. חיבר ספר הקנה וספר הפליאה."},{"i":4843,"n":"אלקנה","b":"דרשן. נכד ר יעקב מדובנא. נזכר בספרי הדרשן ר אברהם דב פלאם."},{"i":4844,"n":"אלקנה הפייטן","f":"שמריה הפרנס","b":"פייטן מחכמי יוון-ק', והיה שם גם פייטן בשם ר שמריה בן אלקנה - כנראה בנו או אביו."},{"i":4845,"n":"אלקנה מלבוב","f":"דוד","dt":"תמד - יב טבת","dp":"לבוב","b":"מראשי קהלת לבוב."},{"i":4846,"n":"אלקנה מלובלין","b":"דיין מחכמי לובלין. חתם בפנקס הח\"ק-תנה."},{"i":4847,"n":"אלקנה מספרד","k":"בעל מפתח הדקדוק","b":"חכם ומדקדק. חיבר \"מפתח הדקדוק\" ונזכר ב\"מנחת שי\". חיבר הקדמה לבקשת ר שמואל בן יוסף מרומא (בס' תפארת ישיבה הופמאן)."},{"i":4848,"n":"אלקנה מקאבאלה","f":"יעקב","b":"רב בקאבאלה-שנות ה-ש'."},{"i":4849,"n":"אלקנווי, שמעון מאלגיר","bt":"תרב","dt":"תרעה","b":"ראש קהלת ווהראן כ-50 שנה, והיה מבוני ביהכ\"נ הגדול ועוד מפעלים קהילתיים. אכסן בביתו את ר יעקב אבוחצירא בביקוריו בווהראן."},{"i":4850,"n":"אלקס, אלחנן מקובנא","f":"ישראל מאיר","bt":"1879","bp":"קאלואריה","dt":"1944","dp":"דכאו","b":"למד רפואה בקניגסברג. רופא במקומות שונים ומגדולי הרופאים בליטא. פעיל בתנועה הציונית, בזמן הכיבוש הרוסי-1940 ניצל את קשריו וסייע למאות פליטים לקבל רשיון למעבר דרך רוסיה. בזמן הכיבוש הנאצי היה יו\"ר מועצת זקני הגיטו ונתגלה כמנהיג אהוב ונערץ. נספה בשואה."},{"i":4851,"n":"אלקפאעי, עמרם מתימן","b":"תלמיד ר דוד בן סעד. חיבר \"ביאור על התקבצו חכמים\" על הרמב\"ם, ונדפס ב\"קבץ על יד\" ירושלים תשמט."},{"i":4852,"n":"אלקשטיל, יוסף מחלב","b":"רב בקהלת הספרדים בחלב-שנות ה-ש'."},{"i":4853,"n":"אלקשטל, יוסף","b":"ממגורשי ספרד(רנ\"ב),רב בארם צובה,מייסד קהילת המסתערבים שם"},{"i":4854,"n":"אלרבי, יואל מצפת","b":"מחכמי צפת-שנות ה-ש'."},{"i":4855,"n":"אלרג'יל, יצחק ממרוקו","k":"יצחק בלחכם","b":"מצדיקי מרוקו ולא נודע יום לידתו ופטירתו. מוזכר ב\"מלכי רבנן\"."},{"i":4856,"n":"אלרגלי, משה מאלגיר","bt":"קפ - בערך","dt":"רן - בערך","b":"שו\"ב בתנס-אלגיר (לא תוניס) בזמן הרשב\"ש ונזכר בתשובותיו. מאמר על העיר-תנס ב\"ספונות\" מאת עמינח."},{"i":4857,"n":"אלרהנד, יצחק משה מברזן","b":"גביר מחכמי ברזן - תשובה אליו ב\"בית יצחק\"-תרלז."},{"i":4858,"n":"אלרואי, דוד","b":"מחכמי בגדד, תלמיד ר' עלי ור' חסדאי ראשי הגולה, הכריז על עצמו משיח ונהרג בידי חתנו"},{"i":4859,"n":"אלרואיטי, יוסף ממונסטיר","b":"רב במונסטיר-שנות ה-ש'. נזכר ב\"דברי ריבות\"."},{"i":4860,"n":"אלרויו ן, יצחק משלוניקי","f":"משה","k":"בעל תנחומות אל","b":"תלמיד ר יוסף טאיטצק. רב בתורכיה בזמן מהרשד\"ם. חיבר גם דרשות, ועוד. הו\"ל ספר הגדרים לר מנחם בונאפוס הפרפנייני - עם הקדמה ממנו - שכז."},{"i":4861,"n":"אלרייך, מרדכי מקרשנוב","f":"טוביה","k":"בעל דרשות על התורה","bp":"בודיני (בוהמיה)","dt":"תקצא","b":"תלמיד בעל ר שמואל קעלין \"מחצית השקל\" וה\"מאור ושמש\". מקורב לחוזה מלובלין ולמגיד מקוזניץ. רב בקשנוב(=קרשנוב) אצל ר שלמה חריף בוכנר. חיבר \"דרשות על התורה\" - בכתב יד."},{"i":4862,"n":"אלשיך משה בן חיים","bt":"1520","dt":"ה'שנג 1593","bk":[["אלשיך",""],["דברים טובים",""],["דברים נחומים",""],["חבצלת השרון",""],["חבצלת השרון וחזון למועד",""],["חלקת מחוקק",""],["ירים משה",""],["מגילת איכה",""],["מגילת אסתר",""],["מגילת קהלת",""],["מגילת רות",""],["מגילת שיר השירים ע'פ האלשיך",""],["מראות הצובאות",""],["משאת משה",""],["עיני משה",""],["קיצור אלשיך",""],["קצור אלשיך",""],["רב פנינים",""],["רוממות א",""],["רוממות אל",""],["שאלות ותשובות הרב משה אלשיך",""],["שושנת העמקים",""],["תורת משה",""]]},{"i":4863,"n":"אלשיך, אברהם הלוי מתימן","f":"שלום","bt":"תקט","dt":"תקפט","b":"מחכמי תימן, מקובל, מדקדק, נגיד יהודי תימן, וממונה על הטבעת מטבעות"},{"i":4864,"n":"אלשיך, חיים מצפת ודמשק","f":"משה - מהר\"ם","b":"מחכמי צפת, חלב ודמשק, אחרי פטירת אביו נסע לונציה והדפיס ספרי אביו."},{"i":4865,"n":"אלשיך, חסדאי משלוניקי וירושלים","f":"מנחם אלשיך","k":"ירושלים","dt":"תרנז - כח ניסן","dp":"ירושלים","b":"רב בשלוניקי, עלה לירושלים והיה בועד ביה\"ח \"משגב לדך\"."},{"i":4866,"n":"אלשיך, יהודה ממונסון","b":"רב במונסון"},{"i":4867,"n":"אלשיך, יהודה מניקופול","b":"מראשי קהלת ניקופול-שנות ה-ת'-תק'."},{"i":4868,"n":"אלשיך, יוסף מירקאדו משלוניקי","f":"משה משלוניקי","dt":"תקס","b":"מחכמי שלוניקי. גיסו - ר אברהם אישטרושא מקומירג'ינה."},{"i":4869,"n":"אלשיך, יעקב יצחק משלוניקי","bt":"תרכד","dt":"תרעט - ט חשון","b":"הקים בתי ספר עבריים בשלוניקי. בניו: יצחק ואברהם - מנהלי המוסדות אחריו. הו\"ל סידור עם תרגום ללדינו יחד עם שני אחיו - תרלח."},{"i":4870,"n":"אלשיך, יצחק מוידין","b":"מחברי החברא קדישא בוידין-תקלג, עם הרופא חיים דוד בן גבריאל."},{"i":4871,"n":"אלשיך, יצחק משלוניקי"},{"i":4872,"n":"אלשיך, מנחם מירושלים","dt":"תרכג - יז סיון","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תריג בשליחות בארצות ערב, בשנת תקצו הסכים עם חכמי ירושלים על מינוי ר יונה נבון ל\"ראשון לציון\"."},{"i":4873,"n":"אלשיך, משה מאדריאנופול","f":"חיים","k":"בעל תורת משה","bt":"רסח-רפ","bp":"אדרינופול","dt":"שנג-שנז","dp":"צפת","b":"נקרא \"הקדוש\". תלמיד ר יוסף קארו, ובשלוניקי אצל ר יוסף טייטצאק, עלה לצפת יחד עם רבו - ר יוסף קארו, ונסמך על ידיו ושימש כדיין בבית דינו. היה רבו של חיים ויטאל בנגלה, וסמך אותו. עסק גם בקבלה והיה דרשן חשוב וגם ר יוסף קארו בא לשמוע את דרשותיו. כיהן כרב ראשי אחרי ר יוסף קארו והמבי\"ט. בשנת שמז (או שכט) עבר לדמשק-שכט (או שמז), ונציה - לשם נסע להדפיס את ספריו וכיהן כר\"מ ודיין - אצל ר יעקב אבולעפיה, תיקן את מוסד השדרו\"ת לטובת קהלת צפת. חיבר \"תורת משה\" קושטא שנד, ועוד. (תאריך פטירתו נרשם גם - יג ניסן של, שמ)."},{"i":4874,"n":"אלשיך, משה משלוניקי","b":"רב בשלוניקי-תקמ. בנו - ר יוסף מירקאדו, חתנו - ר אברהם אישטרושא מקומירג'ינה ושלוניקי."},{"i":4875,"n":"אלשיך, נתנאל הלוי מתימן","f":"שלום","bt":"תרמא","dt":"תרפא","b":"תלמיד ר חיים קורח. רב וראש ישיבת \"בית אלשיך\" בצנעא-תימן. חיבר חדושים בתורה ואבדו. תשובות ממנו כנגד המתנגדים לקבלה ב\"אמונת ה'\". בנו - ר יחיא הלוי אלשיך."},{"i":4876,"n":"אלשיך, רפאל הלוי מתימן","f":"שלום","bt":"תרמא","bp":"צנעא","dt":"תשיח - יז תשרי","dp":"תל אביב","b":"תלמיד ר לוי חמדי. מחכמי תימן, עבר לעדן-תרסג מחמת הרעב, עלה לירושלים-תרסה. תלמיד קרובו של שלום אלשיך - רבה של קהילת התימנים בירושלים ותלמיד ר חיים דמתי. מלמד בקהלה התימנית בתל אביב-תרעח, ורב הקהלה, ייצג את קהילת התימנים באסיפת הנבחרים וב\"ועד הלאומי\". לזכרו הקובץ - \"הראל\"."},{"i":4877,"n":"אלשיך, שאלתיאל מתורכיה","b":"מחכמי תורכיה בזמן המהרש\"ל, גם אביו היה מחכמי תורכיה."},{"i":4878,"n":"אלשיך, שלום מתימן וירושלים","f":"יוסף","k":"בעל דורש שלום","bt":"תרט-יב-ט","bp":"צנעא","dt":"תשד - א אלול","b":"מקובל, מגדולי חכמי תימן, עלה לירושלים-תרמב-ט, ראב\"ד לעדה התימנית בירושלים יחד עם ר אברהם אלנאדף על מקום ר שלום עראקי - חברי בית דינו: ר חיים עראקי, ר יהודה חבשוש, ר דוד קפאח. ממיסדי ישיבת המקובלים \"רחובות הנהר\", בשליחות-תרעג בסוריה ומצרים. חתם על פסקים ותקנות הקהילה. חיבר גם \"דובר שלום\"."},{"i":4879,"n":"אלשירזי אלמוקמץ, דוד","k":"ר' דוד אבן מרואן","b":"מחכמי מצרים שבאו מבבל, פילוסוף"},{"i":4880,"n":"אלשמסא, יוסף","b":"תרגם מגלת אסתר לערבית, ונדפסה ע\"י ר שבתי חמוי - חלב תרסו."},{"i":4881,"n":"אלשניצקי, משה מואסליקוב","f":"מרדכי צבי","bt":"תרח","b":"רב בטגנטשי(=טאגאנטשי)-פלך קיוב-תרם, וואסילקוב(=ואסילקוב)-פלך קיוב-תרנח."},{"i":4882,"n":"אלשקר, אברהם ממצרים","f":"משה - מהר\"ם אלשקר","b":"רב במצרים-שעה. תשובה ממנו בשו\"ת \"אבקת רוכל\", ועוד."},{"i":4883,"n":"אלשקר, דוד מירושלים","k":"מולאי יגגי","bp":"יגגי(מרוקו)?","dt":"תעז?","dp":"מולא אגן(אלגיר)","b":"מחכמי ירושלים-תי, בשליחות באלגיר ונפטר שם בכפר מולא אגן, מ.ד. גאון מעיד בשם ר מסעוד בן שמעון-מחכמי צפת שבאים יהודים וגויים ממרחקים להשתטח על קברו ועושים אותו יום משתה ושמחה."},{"i":4884,"n":"אלשקר, יהודה","k":"בעל פירוש לאבות","b":"מגדולי חכמי דורו בקושטא-שנת ש'. חיבר פירוש לאבות"},{"i":4885,"n":"אלשקר, יהודה מאלגיר","bt":"תקס","dt":"תרל - בערך","b":"תלמיד ר חיים בלייח מתלמסאן. רב בתלמסאן-אלגיר."},{"i":4886,"n":"אלשקר, יהודה מספרד ואלגיר","f":"משה בן יהודה בן שמוא","bt":"רך","dt":"רץ - בערך","dp":"מסתגאנם","b":"ממגורשי ספרד, רב במסתגאנם-אלגיר. אחיו של ר יוסף בעל \"צפנת פענח\", וחיבר שיר לכבוד אחיו. ציון קברו נחשב לקדוש."},{"i":4887,"n":"אלשקר, יוסף ארקאייז מספרד ואלג","f":"משה בן יהודה בן שמוא","k":"בעל אברך","bt":"רכה - בערך","dt":"ש- בערך","b":"מגדולי חכמי ספרד, בתורה במדע וברפואה, בגירוש עבר לתלמסאן-אלגיר-רנב. שיר ממנו ב\"יבין שמועה\". קברו נחשב למקום מקודש. חיבר גם \"צפנת פענח\", \"מרכבת משנה\", ועוד (ולפי ר יוסף משאש הוא משל רב אחר). אחיו של ר יהודה."},{"i":4888,"n":"אלשקר, יצחק מאלגיר","f":"דוד","bt":"תקך - בערך","dt":"תקץ - בערך","b":"רב ומשורר בתלמסאן-אלגיר. חיבר פיוט אודות מאורעות תלמסאן-תקסה."},{"i":4889,"n":"אלשקר, ישועה מאלגיר","b":"רב בתלמסאן-אלגיר. נזכר בפנקס ר סעדיה בן סידון."},{"i":4890,"n":"אלשקר, משה מאלגיר","f":"יהודה בן שמואל","bt":"קפ - בערך","dt":"רס - בערך","b":"רב, רופא ומשורר בתלמסאן. אביו הגיע מספרד לאחר הפרעות-קנא. חיבר שיר בדיני שחיטה ונזכר ב\"צפנת פענח\". קרובו של ר משה בן יצחק בעל השו\"ת."},{"i":4891,"n":"אלשקר, משה ממצרים","dt":"שמג","b":"עק\"ה, שר, נדיב, מחכמי מצרים בזמן הרדב\"ז, עלה לירושלים."},{"i":4892,"n":"אלשקר, משה מספרד","f":"יצחק","k":"בעל השגות על האמונות","bt":"רכ-ה","bp":"זמירה-ספרד","dt":"שא - רצח","dp":"ירושלים","b":"תלמיד ר שמואל בן אברהם ולנסי יחד עם ר יעקב ן חביב. פוסק, מקובל ופייטן, ממגורשי ספרד, נפל בשבי שודדים ולבסוף הגיע לתונס ושם עמד בראש העדה יחד עם ר אברהם זכות בעל \"יוחסין\", עזב את תונס בגלל מלחמות עם הספרדים ועבר לטרבלוס(=טריפולי), ולפטרס-יון, הגיע למצרים וכיהן כדיין אצל הרדב\"ז בקהיר, עלה לצפת ועבר לירושלים. בשליחות בתורכיה. חיבר \"השגות על ספר האמונות\" פירארא שיג, ועוד. בנו ר אברהם היה מרבני מצרים."},{"i":4893,"n":"אלשקר, משה מפאס","b":"מחכמי פאס-של. חיבר ספר דרושים."},{"i":4894,"n":"אלשקר, שלום מאלגיר","bt":"תמ - בערך","dt":"תקי - בערך","b":"רב בתלמסאן. נזכר ב\"משפט וצדקה ביעקב\" לר יעקב ן צור."},{"i":4895,"n":"אלשקר, שלמה ממצרים","dt":"שמג","dp":"מצרים","b":"גביר מחכמי מצרים, ג'יליבי על מקום ר שמואל הכהן ולאחר שנהרג חזר ר שמואל הכהן על מקומו, מחזיק רבנים וישיבות, הקים ת\"ת בצפת בראשות ר יצחק עראמה משלוניקי, נזכר ב\"דברי יוסף\" לר יוסף סמבורי. נהרג עק\"ה."},{"i":4896,"n":"אלתבן, לוי מסרגוסה","b":"מחכמי ספרד, מדקדק ומשורר ופייטן בסרקוסטה(=סרגוסה)-ד'תת. שיריו נדפסו בספר \"ששים פיוטים\" -תשכח. נזכר אצל ר יהודה הלוי, ור משה ן עזרא."},{"i":4897,"n":"אלתירני, יצחק מטורקיה","f":"שמואל","b":"ראש קהלת איטליה-בקושטא בזמן גירוש ספרד. חברו של ר מיכאל בר שבתי, והתכתב עם ר משה קפסאלי, היה במחלוקת עמו והיה בקשר עם ר יוסף קולון בענין זה."},{"i":4898,"n":"אלתנאסי ן, ברוך","b":"רב באושקה"},{"i":4899,"n":"אלתר","b":"רב בקונסטנטין ישן-תר\"ל-תר\"נ"},{"i":4900,"n":"אלתר בן ציון מגיד מארה\"ב","k":"בעל אבני המחצב"},{"i":4901,"n":"אלתר בן ציון מדויד הורודוק","f":"ישראל יוסף מדויד הור","dt":"תרעח","b":"חתן ר לוי יצחק מקאמין (נסכיז)."},{"i":4902,"n":"אלתר יוזפא הכהן","dt":"תשג","b":"מ\"מ בטרנופול"},{"i":4903,"n":"אלתר מגידזאן וארה\"ב","k":"בעל מעשה אבות","b":"רב בארה\"ב-תרפז."},{"i":4904,"n":"אלתר מקולומיי","f":"משה יהושע","b":"דיין בקולומיי"},{"i":4905,"n":"אלתר מקלוואריה","f":"יעקב","b":"דיין בקלוואריה, חתם-תקצז עם הראב\"ד ר אריה ליב ברוידא, ועם ר משה בן יהודה ור צבי הירש בן פנחס חיים כהנא"},{"i":4906,"n":"אלתר, אברהם חיים מזלישטשיק","k":"הו\"ל פורחת עלתה נצ\"ה","b":"שו\"ב בזלישטשיק. תלמיד ר מאיר מפרימישלן. הוציא לאור \"פורחת עלתה נצ\"ה\" זלישטשטיק תרנג (רכש את הזכויות מהמחבר)."},{"i":4907,"n":"אלתר, אברהם יהודה מלמברג","f":"דוד מרדכי","bt":"תרכה","dt":"תשג","b":"מחכמי לבוב, חתנו של ר בנימין זאב בלומנפלד. נספה בשואה."},{"i":4908,"n":"אלתר, אברהם ישכר","f":"מנחם מנדל אלתר","dt":"תשב","b":"רב בפאביאניץ"},{"i":4909,"n":"אלתר, אברהם מצורטקוב","b":"מחכמי צורטקוב. תשובה אליו ב\"קול יהודה\"."},{"i":4910,"n":"אלתר, אברהם מרדכי","f":"יצחק מאיר מגור-הרי\"מ","bt":"ה'תרכו","dt":"ה'תשח","b":"רב בגור כ\"א אב תרטו. נפטר צעיר. בניו - ר יהודה אריה ליב בעל שפת אמת, ר שלמה.","bk":[["אמרי אמת (גור)",""],["אמרי אמת – עה\"ת",""]]},{"i":4911,"n":"אלתר, אברהם מרדכי","f":"שלמה אלתר","dt":"תש","b":"רב בזכלין"},{"i":4912,"n":"אלתר, אברהם מרדכי מגור","f":"יהודה אריה - שפת אמת","k":"אדמור מגור-אמרי אמת","bt":"תרכו","bp":"גור","dt":"תשח - ו סיון","b":"חתן ר נח שחור מביאלא, ובזיוו\"ש חתן גיסו ר יעקב מאיר בידרמן. ממייסדי אגודת ישראל, ביבליוגרף מפורסם, אדמור בגור-תרסה על מקום אביו, ניצל מהשואה ועלה לירושלים-תשא. מתולדותיו ב\"ראש גולת אריאל\". מבניו: ר מאיר, ר יצחק. ה\"בית ישראל\", ה\"לב שמחה\", ה\"פני מנחם\". חתניו: ר יצחק מאיר אלתר בן אחיו ר משה בצלאל - נספה בשואה, ר שלמה יוקוביץ, ר יצחק אהרן אפרים פישל היינה, ר יצחק מאיר לוין-בן גיסו ר צבי חנוך מבנדין. פרסם מאמרים ב\"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"קהילת יעקב\" - זבארוב-סלובקיה תרפה, \"קול תורה\" - פאביאניץ תרפו.","bk":[["אמרי אמת","מפרשי רמב\"ם"],["אמרי אמת","חסידות"]]},{"i":4913,"n":"אלתר, אברהם עוזר מאושפיצין","b":"ר\"מ בישיבת \"כתר תורה\" באושפיצין. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"כתר תורה\" - אושפיצין תרצט."},{"i":4914,"n":"אלתר, חיים מנחם מקוסוב"},{"i":4915,"n":"אלתר, יהודה אריה ליב מגור","f":"אברהם מרדכי מגור","k":"אדמור מגור-שפת אמת","r":"אב\"ד ביאלסטוק","bt":"תרז","dt":"תרסה - ה שבט","b":"מגדולי האדמורים בדורו. נכד האדמור מגור בעל \"חדושי הרי\"ם\", ור ברוך פרנקל תאומים מלייפניק בעל \"ברוך טעם\". חתן ר יהודה קמינר בעל \"דגל יהודה\", ובזיוו\"ש חתן ר ברוך הלברשטם מגורליץ. אדמור מגור-תרל על מקום זקנו - כשביניהם עברה ההנהגה לר חנוך הניך האדמור מאלכסנדר. חיבר \"שפת אמת\". מבניו: ר משה בצלאל מגור ר נחמיה מגור בעל \"חדושי רבי נחמיה\", ר מנחם מנדל מקאליש. חתניו: ר יעקב מאיר בידרמן מוארשא, ר צבי חנוך הכהן לוין מבנדין.","bk":[["שפת אמת","מפרשי ש\"ס - אחרונים"],["שפת אמת","מפרשי רמב\"ם"],["שפת אמת","שו\"ת - אחרונים"],["שפת אמת","חסידות"],["שפת אמת – עה\"ת וש\"ס",""],["שפת אמת (גור)",""]]},{"i":4916,"n":"אלתר, יהודה אריה ליב מלודז","f":"נחמיה מגור","bt":"תרסה","dt":"תש..","b":"דודו של האדמור מגור."},{"i":4917,"n":"אלתר, יעקב אריה מגור ירושלים","f":"שמחה בונם-לב שמחה","k":"אדמור מגור בירושלים","bt":"תרצט","b":"אדמור מגור בירושלים-תשנו על מקום דודו בעל \"פני מנחם\"."},{"i":4918,"n":"אלתר, יצחק מאיר","f":"משה בצלאל אלתר","k":"חתן ה\"אמרי אמת\"","bt":"1799","dt":"תשג","b":"חתן ר אברהם בעל \"אמרי אמת\". רב בגור. נספה בשואה.","bk":[["חדושי הרי\"מ","מפרשי ש\"ס - אחרונים"],["חדושי הרי\"מ","מפרשי שו\"ע"],["חדושי הרי\"מ","שו\"ת - אחרונים"]]},{"i":4919,"n":"אלתר, יצחק מאיר מגור - הרי\"ם","f":"ישראל רוטנברג ממגניש","k":"אדמור מגור-חדושי הרי","bt":"תקנט","dt":"תרכו - כג אדר","b":"חתן הגביר ר משה חלפן מוארשא. תלמיד המגיד מקוזניץ, ובנו ר משה אליקים בריעה, ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק. אדמור בגור-תריט לאחר פטירת רבו מקוצק. מייסד שושלת גור, ר חנוך הניך האדמור מאלכסנדר על מקומו אחריו באופן זמני עד למינוי נכדו בעל שפת אמת. חיבר \"חדושי הרי\"ם\" ועוד."},{"i":4920,"n":"אלתר, ישראל מגור ירושלים","f":"אברהם מרדכי-אמרי אמת","k":"אדמור מגור-בית ישראל","r":"האדמו\"ר מגור","bt":"תרנה","dt":"תשלז - ב אדר","dp":"ירושלים","b":"חתן דודו ר יעקב מאיר בידרמן, ובזיוו\"ש חתן ר דוד וידנפלד מוארשא. אדמור מגור בירושלים על מקום אביו. ממיסדי החינוך העצמאי בארץ. חיבר \"בית ישראל\", ועוד. מתולדותיו ב\"אדמורי גור\", \"תפארת שבתפארת\".","bk":[["בית ישראל – עה\"ת",""]]},{"i":4921,"n":"אלתר, ישראל מלמברג","k":"בעל שירי ישראל","bt":"תרסב","bp":"למברג","dt":"תשם","dp":"ניו יורק","b":"חזן בוינה - מחבר הלחן ל\"עקביא בן מהללאל\". חזן בהנובר. רב ביהונסבורג. חיבר \"שירי ישראל\"."},{"i":4922,"n":"אלתר, מאיר מגור","f":"אברהם מרדכי-אמרי אמת","bt":"תרמג","dt":"תש..","b":"בנו בכורו של האדמור מגור. נספה בשואה."},{"i":4923,"n":"אלתר, מנחם מנדל מקאליש","f":"יהודה אריה - שפת אמת","bt":"תרלז-ח","dt":"תשב - כט תמוז","dp":"טרבלינקה","b":"חתן ר אברהם ישכר רבינוביץ מרדומסק, ובזיוו\"ש חתן ר משה פריווס. בעל כשרונות נדירים ובעל זכרון פינומינלי. נשיא אגודת הרבנים בפולין-תרצד, ראש ישיבה \"דרכי נועם\" בגור, רב בפאביניץ(=פאביאניץ)-תרפ, קאליש-תרצד. נספה בשואה."},{"i":4924,"n":"אלתר, משה אלחנן מלמברג","f":"אברהם יהודה","bt":"תרמט","bp":"למברג","dt":"תשב - אב","b":"מחסידי בעלז. חתן ר משה זיידמן מבוצ'ץ'. תלמיד ר מאיר אריק. עבר לוינה עם רבו וחמיו, דיין בלמברג וראב\"ד. נספה בשואה עם משפחתו."},{"i":4925,"n":"אלתר, משה בצלאל מגור","f":"יהודה אריה - שפת אמת","bt":"תרכח-ט","dt":"תשב - כג אלול","dp":"טרבלינקה","b":"בן האדמור מגור בעל \"שפת אמת\". חתן דודו ר שמעון חיים. רב בגור אצל אחיו האדמור בעל \"אמרי אמת\", ובצוואתו מינהו למלאות את מקומו אחריו - \"הוא קשור אצלי בלבי רוחי ונשמתי..\". ביקר בארץ-תרפו ושהה בה חצי שנה. נספה בשואה."},{"i":4926,"n":"אלתר, משה חנה מלבוב","dt":"תשג","b":"רב בלמברג"},{"i":4927,"n":"אלתר, נחמיה מגור","f":"יהודה אריה - שפת אמת","k":"בעל חדושי רבי נחמיה","bt":"תרלד-ה","dt":"תשב - כב תמוז","b":"בן האדמור מגור בעל \"שפת אמת\". חתן ר צבי הירש מורגנשטרן מלומאז-בן ר דוד מקוצק. עלה לצפת-תרפה, ראש ישיבת \"שפת אמת\" בירושלים-תרפז, חזר לפולין-תרצא וכיהן כרב בועד הרבנים בלודז-תרפט. נספה בשואה."},{"i":4928,"n":"אלתר, פנחס מנחם מגור ירושלים","f":"אברהם מרדכי-אמרי אמת","k":"אדמור מגור-פני מנחם","r":"האדמו\"ר מגור","bt":"תרפו","dt":"תשנו - טז אדר","dp":"ירושלים","b":"חתן בן דודו ר אברהם מרדכי בן ר משה בצלאל אלתר. ראש ישיבת \"שפת אמת\", נשיא מועצת גדולי התורה. אדמור מגור-תשנב על מקום אחיו בעל \"לב שמחה\", ובנו ר יעקב אריה על מקומו אחריו. חיבר \"פני מנחם\". בניו: ר שאול, ר דניאל, ר יצחק דוד.","bk":[["פני מנחם (גור)",""],["פני מנחם – עה\"ת",""]]},{"i":4929,"n":"אלתר, רפאל הלוי משטוצין","b":"תלמיד ישיבת סלוצק (היה מ-14 התלמידים שהביא עמו ר איסר זלמן מלצר - כשהקים את הישיבה). ר\"מ בשטוצין-תר\"ס"},{"i":4930,"n":"אלתר, שלמה מגור","f":"אברהם מרדכי אלתר","b":"רב בגור-תר\"ל"},{"i":4931,"n":"אלתר, שמואל מארה\"ב","k":"בעל לקוטי בתר לקוטי","b":"רב בארה\"ב-תשה."},{"i":4932,"n":"אלתר, שמואל מוינה וארה\"ב","f":"אברהם יהודה","k":"בעל קלוטי בתר לקוטי","bt":"תרמה","bp":"למברג","dt":"תשל","b":"מחותן עם רבו ר מאיר אריק, היה רב בוינה-תרעד, ברח מהנאצים להוואנה-קובה-תשב, עבר לארה\"ב וכיהן כרב בברוקלין. חיבר \"לקוטי בתר לקוטי\" ניו יורק תשה, ועוד."},{"i":4933,"n":"אלתר, שמחה בונם מגור ירושלים","f":"אברהם מרדכי-אמרי אמת","k":"אדמור מגור-לב שמחה","bt":"תרנו","dt":"תשנב - ז תמוז","dp":"ירושלים","b":"חתן דודו ר נחמיה בן ר יהודה אריה ליב מגור. אדמור מגור בירושלים-תשלז על מקום אחיו ר ישראל בעל \"בית ישראל\". חיבר \"לב שמחה\".","bk":[["לב שמחה (גור)",""]]},{"i":4934,"n":"אמאדו, אברהם מאזמיר","f":"דוד","dt":"תקצב - יג כסלו","b":"נספה במגפה באזמיר"},{"i":4935,"n":"אמאדו, דוד מאזמיר","f":"יעקב","k":"בעל תהלה לדוד","bt":"תקלז","bp":"אזמיר","dt":"תקצב - יג כסלו","dp":"אזמיר","b":"דיין באזמיר, בשנת תקפה נשאל על ידי ר חיים פאלג'י. חיבר \"תהלה לדוד\" שלוניקי תקצה, \"עיני דוד\" אזמיר תרכו, הדפיס את ספר הדורשים של ר עזרא מלכי בשנת תקעא. התיישב בירושלים.","bk":[["עיני דוד","מפרשי רמב\"ם"],["עיני דוד - רמב\"ם",""],["תהלה לדוד – דרוש",""],["תהילה לדוד",""]]},{"i":4936,"n":"אמאדו, חיים מאזמיר","b":"מחכמי ורבני איזמיר"},{"i":4937,"n":"אמאדו, יאושע יאודה","f":"רפאל יצחק","k":"בעל אהלי יהודה","bt":"תקכ","dt":"תקע","b":"מחכמי ורבני איזמיר,חיבר \"אהלי יהודה\",דרשות על התורה וחידושים על הרמב\"ם"},{"i":4938,"n":"אמאדו, יעקב מאזמיר","f":"דוד - עיני דוד","k":"בעל אמרי אמת","dp":"תרלה","b":"חתן ר יוסף ן עזרא בעל \"שלחן המלך\". תלמיד ר חיים פלאג'י ונזכר בספריו. מחכמי אזמיר."},{"i":4939,"n":"אמאדו, יעקב מאזמיר","dt":"תקלב - כא אדר","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":4940,"n":"אמאדו, מאיר מאזמיר","b":"רב באזמיר."},{"i":4941,"n":"אמאדו, רפאל יצחק מאזמיר","b":"גביר באזמיר-שנות ה-תק'. בנו - ר יהודה יהושע בעל \"אהלי יהודה\"."},{"i":4942,"n":"אמאדו, שמואל יעקב מאזמיר","f":"יהודה","dt":"תרכה - כ אדר","b":"מחכמי אזמיר, אחיינו ר יעקב אמאדו מזכירו בספרו \"אמרי אמת\"."},{"i":4943,"n":"אמאטו, חיים מרודוס","b":"גביר ברודוס-תקן בערך, תמך ברבני ובהדפסת ספריהם."},{"i":4944,"n":"אמאטו, יהודה מרודוס","f":"משה מרודוס","b":"רב ברודוס-אחרי שע, לצד אביו."},{"i":4945,"n":"אמאטו, יוסף מאזמיר","dt":"תיד - כ אב","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":4946,"n":"אמאטו, יוסף מרודוס","b":"דיין ברודוס-תם, עם ר שמואל נחמיאש."},{"i":4947,"n":"אמאטו, משה מרודוס","b":"רב ברודוס - אחרי שע, על מקום ר אליעזר וילייסיד, ולצדו בנו ר יהודה אמאטו."},{"i":4948,"n":"אמאטו, נסים מאזמיר - א","dt":"תג - ב סיון","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":4949,"n":"אמאטו, נסים מאזמיר - ב","b":"גביר מחכמי אזמיר-תל, ארגן את השלחנים(=בנקאים) היהודים באזמיר."},{"i":4950,"n":"אמאטו, נסים מאזמיר וירושלים","dt":"תקיד - יב חשון","dp":"ירושלים","b":"רב בקושטא?, אזמיר, עלה לירושלים. נספד ע\"י ר ידידיה טריקא מרודוס בספרו \"קידש ידיד\". נזכר ב\"עין יוסף\" לר יוסף חזן."},{"i":4951,"n":"אמאטו, נסים ממגניסיאה","bp":"שלוניקי","b":"מחכמי אזמיר, רב במגניסיאה-תלא על מקום ר משה עוזיאל."},{"i":4952,"n":"אמאטו, נתן","b":"תרגם מערבית את ספר הקאנון של אביסנא, ועוד (די רוסי)."},{"i":4953,"n":"אמאטו, שלמה אברהם מאזמיר","b":"מחכמי אזמיר. תשובה ממנו ב\"ויען אברהם\" לר אברהם פלאג'י."},{"i":4954,"n":"אמאטו, שמואל מקושטא","f":"יוסף","b":"רב ומשורר בקושטא-שנות ה-תק', חיבר שיר בהקדמת \"משאת משה\" לר משה ישראל."},{"i":4955,"n":"אמאיול, ישראל","b":"נבחר למפשר במחלוקת בקהלת גאליפולי-שנות ה-ש'."},{"i":4956,"n":"אמאלריי, אברהם ממצרים","b":"מחכמי מצרים, עלה לא\"י, ירושלים-שנז. נזכר בתשובות ר בצלאל אשכנזי."},{"i":4957,"n":"אמארג'י, יהושע משלוניקי","b":"גביר בשלוניקי. חתן הגביר עזרא ברזילי משלוניקי. סייע בהדפסת \"בתי אבות\" לר יוסף דוד-תקפה יחד עם חותנו."},{"i":4958,"n":"אמארג'י, יוסף משלוניקי","f":"משה","b":"רופא בשלוניקי. אחיו של מנחם."},{"i":4959,"n":"אמארג'י, יצחק משלוניקי","f":"מנחם","dt":"תעו","dp":"שלוניקי","b":"גביר בשלוניקי, תרם להחזקת התלמוד תורה."},{"i":4960,"n":"אמארג'י, יצחק משלוניקי","k":"בעל מוסר השכל ודרכי","b":"מחכמי שלוניקי, ותרגם ספרים ללאדינו ובהם: \"חזוק אמונה\" לר יצחק מטרוקי, \"שבילי עולם\" לר שמשון בלוך-תריג, \"ספר הברית\" בשם \"מוסר השכל\" יחד עם ר יוסף מאיר ששון."},{"i":4961,"n":"אמארג'י, מנחם משלוניקי","f":"משה (יוסף)","dt":"תנב","dp":"ירושלים","b":"רופא מחכמי שלוניקי בשנת תו, בשנת תלה נדב לטובת התלמוד תורה. חתם עם ראשי הקהלה בשנת תלו. עלה לירושלים. אחיו של יוסף-הרופא גם הוא."},{"i":4962,"n":"אמארג'י, משה הרופא משלוניקי","dt":"תח - יז תמוז","dp":"שלוניקי","b":"רופא מחכמי שלוניקי, רופא השולטן בקושטא. תמך בר שבתי יונה בעל \"שי למורא\". בניו - ר מנחם ור יוסף רופאים בשלוניקי."},{"i":4963,"n":"אמאריו, ראובן מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק',"},{"i":4964,"n":"אמוזג, אברהם חי מטבריה","f":"מרדכי או מאיר","k":"בעל קנה לאברהם","bt":"תרך","bp":"טבריה","dt":"תרצ-א - כד כסלו","dp":"ירושלים - טבריה","b":"שדר בצרפת טורקיה-תרסח, ומרוקו. נמנה על רבני טבריה, חיבר קנה אברהם ירושלים תרפג, תולדותיו רשומות בספרו \"אברהם בכל\" ירושלים תרצט, נקבר בטבריה","bk":[["קנה אברהם",""]]},{"i":4965,"n":"אמוזג, אליהו מאיטליה","k":"בעל המוסר היהודי","bt":"תקפג","bp":"ליוורנו או מוגאדור-מרוקו","dt":"תרס","dp":"ליוורנו","b":"נכד ר אברהם קוריאט בעל \"זכות אבות\". לפי \"מלכי רבנן\" עבר ממוגאדור-מרוקו לליוורנו-תרד. פילוסוף, מקובל, דרשן, רב בליוורנו ומדפיס-תרל, ר\"מ בביהמ\"ד לרבנים בליוורנו. חיבר \"המוסר היהודי והמוסר הנוצרי\", \"אם למקרא\", \"אימת מפגיע\" - כנגד \"ארי נוהם\" לר יהודה אריה די מודנא - ובו מגן על חכמת הקבלה, ועוד."},{"i":4966,"n":"אמוזג, דוד מפאס","b":"מחכמי פאס, חתם על הסכמה-תנח עם ר מנחם סירירו, ר וידאל הצרפתי היעב\"ץ, ועוד."},{"i":4967,"n":"אמוזג, חיים מפאס-מרוקו","dt":"תצה","b":"מצאצאי ר כלפון. מומחה בשחיטה, שו\"ב ורב בפאס. חדושים ממנו ב\"מראה עינים\" לר אלעזר בהלול. חתם-תנח עם ר מנחם סירירו וחבריו."},{"i":4968,"n":"אמוזג, כלפון מפאס","b":"מחכמי פאס בשנות ה-ת."},{"i":4969,"n":"אמוזג, משה מפאס","b":"רב בפאס, חתם-תט על הסכמה עם ר סעדיה ן דנון."},{"i":4970,"n":"אמוזג, עזריאל מפאס","b":"מחכמי פאס-שנות ה-תק'."},{"i":4971,"n":"אמוזג, שם טוב מפאס","dt":"תצב - אחרי","b":"מחכמי פאס-מרוקו, תלמיד ר שמואל אלבאז, פגש את ר חיים בעל \"אור החיים\" בהיותו בפאס. הניח חיבורים שונים ובהם על מסכת אבות."},{"i":4972,"n":"אמון, יוסף מירושלים","dt":"תקעא - ז אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":4973,"n":"אמון, יעקב מנא אמון","b":"מחכמי נא אמון. הזכירו ר אברהם עיני בנימוקיו על הרמב\"ם."},{"i":4974,"n":"אמוץ מתבץ","f":"גרשום","b":"רב בתיביץ(=טיווה)-במוריאה-יון בדור שלאחר הגירוש."},{"i":4975,"n":"אמוראי ארץ ישראל","r":"נוצקה תבניתו שתי דורות קודם ע\"י ר' יוחנן","dt":"ד' קלח","bk":[["תלמוד ירושלמי",""]]},{"i":4976,"n":"אמזלג - משפחה","b":"משפחה ממרוקו, גיבלרטר."},{"i":4977,"n":"אמזלג, אברהם","b":"מחכמי מרוקו"},{"i":4978,"n":"אמזלג, בן ציון מירושלים","bt":"תרכה","dt":"תרצא","dp":"יפו - ירושלים","b":"גביר נדיב בירושלים ויפו."},{"i":4979,"n":"אמזלג, חיים יהודה מירושלים","bp":"מרוקו","b":"מתלמידי ר חיים בן עטר שעלו אתו לארץ ישראל בשנת תקב ולמדו בישיבתו בירושלים, חתום שני בהקדמה ל\"ראשון לציון\"."},{"i":4980,"n":"אמזלג, חיים מירושלים","f":"יוסף","bt":"תקף","bp":"ירושלים","dt":"תרעו","dp":"אלכסנדריה","b":"בן למשפחה שהגיע מגיברלטר לירושלים. גביר ועסקן ציוני ומדיני."},{"i":4981,"n":"אמזלג, יוסף","dt":"תרה - כד כסלו","b":"דיין בירושלים"},{"i":4982,"n":"אמזלג, יוסף מיפו","f":"חיים","bt":"תרך","bp":"יפו","b":"גביר ועסקן בארץ ישראל."},{"i":4983,"n":"אמזלג, יוסף מירושלים","dt":"תקן בערך","dp":"ירושלים","b":"מחכמי ירושלים מתלמידי ר חיים בן עטר, ונתמנה על ידו לעמוד בראש הישיבה אחריו, אך סירב. כנראה ראש משפחת אמזלג שהגיע מגיברלטר לירושלים."},{"i":4984,"n":"אמזלג, יוסף מירושלים","b":"גביר בעל אזרחות אנגלית, עלה לירושלים, סייע לכולל הפרושים וקיבל כמשכון את חצר החורבה. בניו: יצחק דוד, חיים, שלמה, רפאל."},{"i":4985,"n":"אמזלג, יצחק דוד מירושלים","f":"יוסף","dt":"תקצב - ב אדר","dp":"ירושלים","b":"לוח לזכרו בחצר ה\"חורבה\"."},{"i":4986,"n":"אמזלג, משה מליסבון","f":"שבת","k":"בעל יצחק ארוביו די ק","b":"מראשי קהלת האנוסים \"שערי תקוה\" בפורטוגל, מלומד וחוקר בליסבון, פרסם מאמרים, וספרים."},{"i":4987,"n":"אמזלג, משה מפאס","dt":"שפא - סוכות","b":"מחכמי פאס. נספד בספר הדרושים לר שאול סירירו."},{"i":4988,"n":"אמזלג, רפאל מירושלים","f":"יוסף","dt":"תרלד - כז שבט","dp":"יפו","b":"גביר ביפו. נפטר צעיר."},{"i":4989,"n":"אמזלג, שלמה מירושלים","f":"יוסף","b":"מחכמי ירושלים בשנים תרי - תרל. חתום על כתב בענין החלוקה בשנת תרל, החזיק בית תפילה בביתו."},{"i":4990,"n":"אמזלג, שמואל מאלג'יר","bt":"תרך - בערך","dt":"תש - בערך","b":"רב בתניית אלחד-אלג'יר. סייע בהוצאת \"והוכח אברהם\" - תונס תרעב."},{"i":4991,"n":"אמיאל, שלמה","b":"מגדולי חכמי ספרד-שנת פ'"},{"i":4992,"n":"אמיאש, משה משלוניקי","dt":"רעו - ה אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":4993,"n":"אמיגו, אברהם הלוי מירושלים","k":"בעל פרי חדש","bt":"שס או שע-א","bp":"אדרינופול (או קושטא)","dt":"תמג בערך","dp":"ירושלים","b":"רב באדרינופול, הוזמן ללמד בישיבת ר' יעקב חגיז בירושלים, למד קבלה אצל ר יעקב צמח, היה מעורב במלחמה בש\"ץ, חיבר ספרים שאבדו, מהם: פרי חדש על בית יוסף מצוין על ידי החידא כאבוד, שות ופסקים שנשמר רק קטעים בכתי, אחת מתשובותיו נדפסה בספר נהרות דמשק חומ יג. קיימים מספר כתבים ממנו בכתי. (הואשם ע\"י גרץ בשבתאות - ופרומקין מגן עליו)."},{"i":4994,"n":"אמיגו, אברהם מטימישואר","b":"ראה הקהלה הספרדית בטימישואר-תקב, סייע לברון דייגו די אגילאר הוא משה לופז פיררה לביטול גזירת הגירוש מוינה."},{"i":4995,"n":"אמיגו, חיים משלוניקי ואיסקופיא","b":"תלמיד ר שמואל בן יצחק חיון בשלוניקי. דרשן בשלוניקי, רב בקהלת \"בית יעקב\" באישקופיה. דיין-תיג עם ר שלמה רוסו ור יצחק קמחי."},{"i":4996,"n":"אמיגו, יעקב מפאס","dt":"ש-שה","dp":"פאס?","b":"תלמיד ר משה חלאווה. רב בפאס-שנות ה-ש', חתם על התקנות."},{"i":4997,"n":"אמיגו, מאיר מטימישואר","b":"שתדלן בטימישואר."},{"i":4998,"n":"אמיגו, שם טוב מספרד ופאס-מרוקו","f":"יעקב","dt":"שכח - לפני","dp":"[פאס]","b":"ממשפחה ממגורשי ספרד שהגיע למרוקו. רב בפאס-שה. תלמיד ר אברהם סבע בעל \"צרור הכסף\" והעתיק את ספרי רבו \"צרור החיים\", \"צרור הכסף\", ו\"אשכול הכפר\". חתם על תקנות המגורשים בפאס-שה, על תקנה של ק\"ק קשטיליה-שו - ב\"כרם חמר\". מתורתו בספרי חכמי דורו."},{"i":4999,"n":"אמייס (כמוס), מרדכי הכהן","f":"יצחק","k":"בעל גדולת מרדכי","r":"רב בסטרופקוב ואדמו\"ר שם","dt":"תשלד - ו סיון","dp":"תונס","b":"תלמיד ר יוסף ברבי, ר דוד הכהן יהונתן, ור משה כלפון הכהן מג'רבא. רב בג'רבא-תרפה, וראש הרבנים בתונס-תשטו. רוב כתביו אבדו. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"קרן דוד\" - גרבה תרעו.","bk":[["גדולת מרדכי",""]]},{"i":5000,"n":"אמינוף, אברהם מירושלים","f":"בנימין","k":"בעל שלחן הטהור","bt":"תריד","bp":"בוכארה","dt":"תרצו-ט - שבט","dp":"ירושלים","b":"פוסק, לימד תורה בסמרקנד, עלה לירושלים-תרמט, נשיא העדה בירושלים, שדר בבוכארה וטרקיסטן, הקים ישיבת מגן אברהם, הוציא לאור 6 כרכים של לקוטי דינים מהשוע בתרגום פרסי. שלחן הטהור - ברכות בתרגום פרסי. חוק לישראל, תהלים עם פירוש, נביאים ראשונים בתרגום פרסי, עקרת הבית הלכות טהרת המשפחה. (אצל גאון תאריך פטירתו - כט תשרי תרצח)."},{"i":5001,"n":"אמינוף, דוד יצחק מבוכארה","f":"יצחק","k":"ר' דוד סמרקנדי","bt":"תרכח - אלול","bp":"בוכרה","dt":"תש - כד אלול","dp":"ירושלים","b":"מחכמי בוכארה, רב ראשי בסמרקנד, דרשן, מרביץ תורה, עלה לירושלים-תרצג-ה, היה ממונה על תרומות ומעשרות בירושלים"},{"i":5002,"n":"אמיני, חיים מקושטא","b":"מחכמי קושטא-ש\"פ"},{"i":5003,"n":"אמיקו, יוסף מאיטליה","b":"רב באיטליה בזמן ר אליקים ממאציראטה. תשובה ממנו ב\"פחד יצחק\"."},{"i":5004,"n":"אמיתי - הנכד","f":"שפטיה בן אמיתי","b":"נכד הפייטן ר אמיתי. פייטן ור\"מ בישיבה. בנו ר עבדיאל. חיבר פיוטים ומהם במחזור ובהם \"אדון מגיד מראשית אחרית\" שחיבר לכבוד נשואי אחותו עם ר חסדיה בן דודו ר חננאל-אחיו של שפטיה אביו."},{"i":5005,"n":"אמיתי בעל שם מאיטליה - הזקן","f":"שפטיה","b":"פייטן מחכמי אוריה-איטליה-ד'תרנ. חיבר פיוטים ותפלות רבים שנכנסו למחזור ולסליחות ובהם פיוט יג מדות לעשי\"ת. דיין באשכנז אחרי ר בנימין בן זרח-שהיה דיין ראשון-ד'תן. בניו: ר שפטיה, ר חננאל, ר אלעזר, נכדו ר אמיתי בן שפטיה - שהיה גם הוא פייטן. לתולדותיו במגילת אחימעץ. בסדר סליחות כת\"י נאמר שבגלות ירושלים הגיעו לרומא שלשה חכמים ובהם ר אמיתי, ר שפטיה, ור יוסיפיה והם תקנו תפילת \"והוא רחום\" ואולי הוא מצאצאיו."},{"i":5006,"n":"אמלאל, שלמה ממרוקו","b":"רב במרוקו, מכתב אליו-תקסא מקהלת טבריה בידי השליח ר דוד בן ישראל אשכנזי."},{"i":5007,"n":"אמנון","dt":"ד'תרפה","b":"נזכר ב\"תחכמוני\" שהיה אחד מעשרה חכמים שנהרגו עק\"ה."},{"i":5008,"n":"אמנון ממגנצא","k":"בעל ונתנה תוקף","b":"גדול הדור, עשיר, קרוב למלכות-מגנצא-ד'תת\"פ, קידש ה' בפיוט \"ונתנה תוקף\"."},{"i":5009,"n":"אמסטר, מרדכי מסנוק","b":"מחכמי סנוק - תשובה אליו ב\"צבי לצדיק\"-תרע."},{"i":5010,"n":"אמסטרדם, נפתלי","f":"שלמה","bt":"תקצב","bp":"סלנט","dt":"תרעו","dp":"ירושלים","b":"מחכמי ליטא, תלמיד ר ישראל סלנט, רב בנווגרד, בשנת תרכז רב בהלסינקי עד שנת תרלה, בשנת תרסו עלה לירושלים, והיה מחכמי המוסר בחצר שטרויס."},{"i":5011,"n":"אמסל, אליעזר מלוגמץ","b":"מצאצאי ר יעקב עמדין, ור נפתלי הכהן מפוזנא. רב בלגמץ(=לוגמץ)-תרע. אחיו - ר יצחק צבי מזבורוב."},{"i":5012,"n":"אמסל, יצחק מאילאק וארה\"ב","f":"אליעזר מלונמץ","k":"בעל קיצור דרכי התשוב","bt":"תרנד","bp":"אויהל","b":"תלמיד ר מרדכי וינקלר בעל \"לבושי מרדכי\", ונסמך מרבו וגם מאת: ר שמואל אנגל מרדמישל, האדמור ממונקטש בעל \"מנחת אליעזר\", דודו-ר יצחק צבי אמסל מזבורוב. חתן נכדת ר פנחס מקוריץ. רב באילק, לגמץ, נאוואמעסטא, ארה\"ב-תרצה, יסד ישיבה לתורה ולמלאכה-תרצט. חיבר \"קיצור דרכי התשובה\" - נ\"י תשך."},{"i":5013,"n":"אמסל, יצחק צבי מזבורוב","k":"בעל חשן ואפוד","dt":"תרצד - שבט","b":"דומ\"צ בסטרופקוב-תרנ, רב בזבורוב-סלובקיה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"קהילת יעקב\" - זבורוב-סלובקיה תרפה. אחיו - ר אליעזר מלוגמץ."},{"i":5014,"n":"אמסל, מאיר מארה\"ב","k":"בעל המאור","b":"רב בארה\"ב. עורך ירחון \"המאור\" ניו יורק."},{"i":5015,"n":"אמסלם, אליהו מאלגיר","f":"יוסף","dt":"תשיג","b":"רב בבני אוניף(-מחוז בשאר)-אלגיר. סייע בהדפסת \"יוסף חן\" לר יוסף נחמיאש - תונס תרעה. חתנו - ר ישראל אבוחצירא."},{"i":5016,"n":"אמסלם, דוד מאלגיר","f":"יוסף או שמחה","k":"בעל שירי דוד","bt":"תרן","bp":"פיגיג-מרוקו","dt":"תשמז - ז תמוז","b":"רב ודרשן בפיגיג-מרוקו, עין צפרא-אלגיר. משורר - מפיוטיו ב\"שירי דוד\". הניח חדושי תורה ומהם נדפס \"וידבר דוד\" - ירושלים תשלג, \"שירי דוד\"."},{"i":5017,"n":"אמסלם, יחיא מאלגיר","bt":"תרל - בערך","dt":"תש - בערך","b":"מחכמי קצמטינא-אלגיר. הו\"ל לוחות שנה. פרסם קריאה להזהיר את בני הקהלה ממסיונרים - ונזכר בספר אזהרות - סוסה תרפג."},{"i":5018,"n":"אמסלם, יעקב בלחזן ממרוקו ואלגי","k":"יעקב בלחסן","bt":"תרמט","bp":"פיגיג-מרוקו","dt":"תשכד","b":"רב ומקובל ממרוקו, עבר לבני אוניף-אלגיר, ווהראן וכיהן כרב לא רשמי."},{"i":5019,"n":"אמסלם, מכלוף מאלגיר","f":"יצחק","k":"בעל תפוחי זהב - תשלח","bt":"תקצז","bp":"וואהרן","dt":"תרפח","dp":"ירושלים","b":"עבר מווהראן-אלגיר לפאס, מקובל ועסק גם בקבלה מעשית וברפואה עממית ורוקחות. עלה לירושלים בזקנותו, החזיק בספריה ובה כת\"י בנושאי קבלה מעשית ואלכימיה. חיבר \"תפוחי זהב במשכיות כסף\", \"מנורת המאור\", ועוד."},{"i":5020,"n":"אמסלם, מסעוד ממרוקו","f":"יוסף","b":"מחכמי מרוקו-שנות ה-תק'. חתם שמו - \"המאמי\"ץ\" (מסעוד אמסלם ישמרהו צורנו)."},{"i":5021,"n":"אמסלם, צמח מאלגיר","bt":"תקצז","dt":"תרפח","b":"תלמיד ר חיים בלייח, והתכתב עם רבו. רב בעין תמושנת-אלגיר, מסתגאנם, רוליזן. מכתב מרבו-ר חיים אליו ובו מבקשו לפעול כנגד ארגון \"חופש המחשבה\" ברוליזאן - שפעל לשילוב יהודי אלגיר בדרך האמנסיפציה."},{"i":5022,"n":"אמסלם, שלמה ממרוקו","f":"משה","k":"בעל בני שלמה","bp":"מידלת-מרוקו","dt":"תשכג - אייר","dp":"מידלת","b":"מחכמי מידלת-מרוקו, תלמיד ר אברהם עטיה, עבר לתאפיללת ולמד אצל בני משפחת אביחצירא, וקבלה אצל ר יצחק בן יעקב אביחצירא. רב במידלת בהמלצת ר מסעוד בן יעקב אביחצירא - אביו של הבבא סאלי. והיה חברו של הבבא סאלי, ור מאיר בנו של הבבא סאלי היה דיין אצלו במידלת. חתנו ר משה עטיה."},{"i":5023,"n":"אמקרויט, אלכסנדר חיים מפרמישלא","dt":"תרנא - בערך","b":"מדפיס מחשובי חסידי ר דוד מדינוב בפרמישלא, חמיו של ר יהודה ליבוש מקומרנא."},{"i":5024,"n":"אמקרויט, יעקב משה מפרמישלא","b":"מחכמי פרמישלא, מדפיס ומו\"ל בשנים תרם-תרס. מצאצאי ה\"חכם צבי\" והיה ברשותו כתב יד על תריג מצוות להרמבם מזקנו."},{"i":5025,"n":"אמרו, דוד נזיר מירושלים","b":"בשנת שס היה שליח ירושלים באטליה, ושוב בשנים שפ-שץ, מינה לגזבר לטובת ירושלים את ר ליב סאראואל, בהיותו בונציה תיקן תקנות שונות. בשות ר יהודה ממודנא מוזכרת תקנה שתקן ר דוד ברומא בענין השבתת המלאכה בערב שבת, לדעת בניהו ר דוד הנ\"ל הוא ר דוד אמריליו."},{"i":5026,"n":"אמריליו, אברהם מטריקולה וירושל","k":"בעל ברית אברהם","dt":"תקיד-מד -ה סיון","dp":"ירושלים","b":"רב בשלוניקי, טריקולה-יון, עלה לירושלים-לפני תקלח. חיבר \"ברית אברהם\" שלונקי תקנד-תקסב. (באוצר ואצל רוזניס ואצל גאון - תאריך הפטירה תקיד). בנו - ר יצחק משלוניקי. (במאמר ב\"ציון\" נכתב בטעות שהיה בירושלים בשנת רעב)."},{"i":5027,"n":"אמריליו, אברהם מירושלים","b":"היה בירושלים-שמז וחתום על תקנה לשחרור תח ממסים, חתום על שטר צוואה משנת שן המובא בשות ר בצלאל אשכנזי, אולי הוא רבי אברהם הנזכר בשות המביט א סימן קפט"},{"i":5028,"n":"אמריליו, אברהם משלוניקי","dt":"תקה","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"בני יונה\" לר יונה ן ריי מקושטא-תקג."},{"i":5029,"n":"אמריליו, אהרן משלוניקי","f":"שלמה - פני שלמה","k":"בעל פני אהרן","dt":"תקלב","dp":"מונסטיר","b":"תלמיד ר יצחק די בושאלדו. רב הכולל בשלוניקי-תקכב על מקום ר יהושע בדרשי - לצדו של ר אלעזר בן שמואל נחמיאש. חיבר גם דרשות - ואבדו, חיבר הקדמות ל-5 ספרים, הגיה את \"מלכי בקדש\"-תקט, והסכים על 7 ספרים."},{"i":5030,"n":"אמריליו, דוד יצחק משלוניקי","dt":"תרסד","dp":"שלוניקי","b":"דרשן וסופר בשלוניקי."},{"i":5031,"n":"אמריליו, דוד מצפת וחברון","b":"מחכמי צפת - ש\"נ ואחר כך בחברון בשנת שס, עורר את ר שלמה עדני לחבר את ספרו \"מלאכת שלמה\". בניהו (ארשת ב) משער שהוא ר דוד נזיר אמרו, שהוא קיצור של אמריליו."},{"i":5032,"n":"אמריליו, חיים מירושלים","dt":"תרח - יז אד\"ב"},{"i":5033,"n":"אמריליו, חיים משה משלוניקי","f":"שלמה","k":"בעל דבר משה","bt":"תנו","b":"חתן אחיו ר' שמואל-תקח. דרשן,כתב פסקים כבר בגי 18,עבר לקושטא-תפה, את שמו חיים קיבל בעקבות מחלה, רב הכולל-תקא, חיבר \"דבר משה\" שו\"ת."},{"i":5034,"n":"אמריליו, חיים משה משלוניקי","b":"דיין בשלוניקי-תר."},{"i":5035,"n":"אמריליו, יוסף אהרן משלוניקי","f":"אהרן","b":"רופא וגביר בשלוניקי-שנות ה-ת'-תק'."},{"i":5036,"n":"אמריליו, יוסף משלוניקי","f":"שלמה - פני שלמה","b":"מו\"צ בשלוניקי-שנות הת'."},{"i":5037,"n":"אמריליו, יצחק דוד משלוניקי","dt":"תרמא","dp":"שלוניקי","b":"דרשן מחכמי שלוניקי."},{"i":5038,"n":"אמריליו, יצחק מאדרינופול","b":"רב באדרינופול-בדור שאחר גירוש ספרד עם ר יעקב פיירו."},{"i":5039,"n":"אמריליו, יצחק משלוניקי","k":"בעל ליל שמורים","dp":"שלוניקי","b":"מגדולי רבני שלוניקי-תקס. חברו של ר יצחק ברגילון. מתלמידיו: ר חיים עובדיה די בושאל."},{"i":5040,"n":"אמריליו, יצחק משלוניקי","f":"שלמה","k":"בעל ליל שמורים?","dt":"תקטז","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו של ר משה-רבה של שלוניקי. גזבר הקהלה - היה סכסוך בינו לבין שבעת טובי העיר בעניני כספים וזכה בדין. נאסר בידי השלטון בגלל חוב של הקהלה."},{"i":5041,"n":"אמריליו, יצחק משלוניקי","f":"אברהם - ברית אברהם","b":"מחכמי שלוניקי-תקמח."},{"i":5042,"n":"אמריליו, יצחק משלוניקי","f":"אברהם","dt":"תקצח","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":5043,"n":"אמריליו, יצחק משלוניקי","b":"מראשי קהלת שלוניקי-תרפא."},{"i":5044,"n":"אמריליו, מרדכי משלוניקי","f":"יוסף","b":"מחכמי שלוניקי. תלמיד וחתן ר משה אמריליו. חיבר הקדמה לספר חותנו \"דבר משה\"-תקג."},{"i":5045,"n":"אמריליו, משה משלוניקי","f":"שלמה - פני שלמה","k":"בעל הלכה למשה","r":"פרוייקט השו\"ת","bt":"תנו","dt":"תקח - כג סיון","dp":"שלוניקי","b":"תלמיד בישיבת ר יוסף דוד. חתן אחיו - ר שמואל אמריליו. דרשן בכמה מקומות והיה מחלוקת כנגדו והורידוהו ממשרתו, לאחר מכן דיין, ואח\"כ רב הכולל בשלוניקי-תצז על מקום ר יוסף דוד-מהרי\"ד (והיה כנראה הרב הכולל הצעיר ביותר בשלוניקי), ברח לקושטא בגלל רדיפת השלטון שתבע מס גם מתלמידי חכמים. חיבר גם \"יד משה\", \"דבר משה\". נפטר במגפה-תקח - זמן קצר לאחר פטירת אשתו ובנותיו, בנו - יעקב נפטר במגיפה, חתניו - אחיינו ותלמידו ר מרדכי בן יוסף אמריליו(אחיו), ר יצחק.","bk":[["דבר משה – שו\"ת",""],["הלכה למשה – רמב\"ם",""],["יד משה – דרשות",""]]},{"i":5046,"n":"אמריליו, שאול משלוניקי","f":"יצחק","bt":"תרי","dt":"תרצז","dp":"שלוניקי - תל אביב","b":"תלמיד ר דניאל מורדוך-שהו\"ל לוחות שנה בשלוניקי. מחכמי שלוניקי ובקי גם באסטרונומיה וחכמות נוספות, והיה חבר החברה הצרפתית לאסטרונומיה והתכתב עם האסטרונום קאמיל פלמריון. ראש השמאים (שהעריכו את הנדוניה - שנתנו משפחות החתן והכלה). הו\"ל לוחות שנה \"חלילות\" על מקום רבו ר דניאל. חוקר תולדות יהודי שלוניקי. בעל ספרייה גדולה ובה כתבי יד יחודיים, ורובם אבדו בשואה."},{"i":5047,"n":"אמריליו, שלמה משלוניקי","f":"יוסף","k":"בעל פני שלמה","bt":"תה-תי","bp":"שלוניקי","dt":"תפא - כט אלול","b":"תלמיד קרובו ר אליהו קובו. דיין-תמו, רב ודרשן, וראש ישיבה בשלוניקי בקהלת \"איטליה ישן\", רב ראשי על מקום ר שמואל יצחק מודיליאנו יחד עם אחיינו-בן אחותו - ר יוסף קובו, ובנו ר משה על מקומו אחריו. תשובות ממנו ב\"תורת חיים\" למהרח\"ש. היה מקורב לנתן העזתי וכתב עליו בכבוד - ואף קיבל כמה מנהגים ממנו - יחד עם חברו ר יוסף קובו. מתשובותיו ב\"כרם שלמה\", ו\"עוללות אפרים\". חתנו - ר חיים בן יהודה שעלה לירושלים. בניו - ר יוסף, ר אהרן, ר משה, ר שמואל, אברהם-שעסק במסחר., וכל בניו היו אוכלים על שלחנו גם כשהיו נשואים.","bk":[["כרם שלמה - שו\"ת",""],["פני שלמה - דרוש",""]]},{"i":5048,"n":"אמריליו, שלמה משלוניקי","f":"יצחק","dt":"תקל - יד אב","dp":"שלוניקי","b":"מחכמי שלוניקי, תלמיד דודו ר משה אמריליו, וחיבר הקדמות לספריו \"דבר משה\" \"יד משה\" ועוד. מגיה בבית הדפוס בשלוניקי-תקב. תשובות ממנו ב\"ראש משביר\", ועוד. השיב לקורפו, סופיה ועוד."},{"i":5049,"n":"אמריליו, שלמה משלוניקי","f":"שמואל","b":"רב ופוסק בשלוניקי-תקמ."},{"i":5050,"n":"אמריליו, שלמה משלוניקי","f":"אהרן","k":"בעל בני אהרן","dt":"תקם","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר במגפה."},{"i":5051,"n":"אמריליו, שלמה משלוניקי","f":"משה","b":"מחכמי שלוניקי. הגיה את \"מטה יוסף\" לר יוסף יצחק יקואל-תקמה."},{"i":5052,"n":"אמריליו, שלמה משלוניקי","dt":"שמו - כד תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי. אולי הוא אביו של ר יוסף וזקנו של ר שלמה בעל \"כרם שלמה\"."},{"i":5053,"n":"אמריליו, שלמה משלוניקי - הנכד","f":"חיים יהודה בן שלמה","dt":"תקכט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":5054,"n":"אמריליו, שם טוב משלוניקי","b":"מחכמי שלוניקי, דיין בלאריסה-תקעו."},{"i":5055,"n":"אמריליו, שמואל משלוניקי","f":"משה - הלכה למשה","k":"הו\"ל הלכה למשה","dt":"תקיט","dp":"שלוניקי","b":"מחכמי שלוניקי-תקו, הו\"ל והוסיף הקדמה והגהות לספרי אביו \"דבר משה\" ו\"הלכה למשה\". נפטר במגפה בחיי אביו, עם אמו, ועם חכמים נוספים."},{"i":5056,"n":"אמריליו, שמואל משלוניקי","f":"שלמה - פני שלמה","b":"מו\"צ בשלוניקי-שנות הת'. אחיו - ר משה."},{"i":5057,"n":"אמרנט, יצחק צבי מקוזובה","b":"דיין בקוזובה-תרלט. תשובות אליו בשות מהרשם."},{"i":5058,"n":"אמש, א'","b":"פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":5059,"n":"אמשטרדם, גרשון מוילנא","f":"משה","k":"גרשון מיכל קצין'ס","dt":"תרלא - ד תמוז","b":"חתן ר יחיאל מיכל בן שרגא פיבש מזעטל ווילנא. מחכמי \"ישיבת הארבעים\" בוילנא-תקפז. תלמיד ר אבלי - ונתן לו רשות לחתום בשמו על כמה פסקים. גבאי ישיבת מייליס בוילנא. בורר בסכסוכים שונים. חתם על כתב התמנות ר ישראל סלנטר לראש הישיבה, על מקום ר מרדכי מלצר. קנה את זכויות ספר ה\"שאגת אריה החדשות\" מבנו ר אשר גינצבורג, וכן כמה מכתבי היד של ר אשר גינצבורג, ומכרם לר שמואל חיים איישטיין שהדפיסם בוילנא, הו\"ל בעצמו את \"גבורות ארי\" לתענית. רב בוילנא על מקום ר ישראל גורדון, ור אפרים כהן על מקומו אחריו. מחתניו: ר שלמה טוביה מאומסק-סיביר."},{"i":5060,"n":"אמשטרדם, נפתלי מליטא וירושלים","f":"שלמה","k":"בעל אור ישראל","bt":"תקצב","bp":"סלנט","dt":"תרעו","dp":"ירושלים","b":"תלמיד ר ישראל סלנטר ור יוסף זונדל מסלנט. ערך גלות יחד עם ר יצחק בלאזר. רב בהלסינגפורס(=הלסניקי)-תרכז, קובנה-תרלה, רב בפטרבורג לצד ר יצחק בלאזר, רב ביוסוואין, ואלקוסוט התחתית-ליד קובנה, עזב את הרבנות והתישב בקובנה וביתו נעשה מרכז לאברכי קובנה. פרסם מאמרים ב\"הלבנון\". עזר לר יצחק בלאזר בעריכת תולדות רבותיהם ב\"אור ישראל\". עלה לארץ-תרסב. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב. מתורתו (מכת\"י) ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"תבונה\" - ירושלים תשא-תשח."},{"i":5061,"n":"אנאסיכון, מאיר מחלב","b":"רב בקהלת הספרדים בחלב-שנות ה-ש'."},{"i":5062,"n":"אנאשכון, מאיר","bp":"ספרד","b":"מחכמי ספרד, עלה לירושלים אחר הגירוש. בשנת שך היה בירושלים, מוזכר בשות הרלבח. תשובה ממנו בבית הספרים הלאומי."},{"i":5063,"n":"אנאשכון, מאיר מצפת","f":"[יוסף]","bp":"[צפת]","b":"רב בצפת, עבר לירושלים-תך. תשובה אליו מר שמואל גארימזן."},{"i":5064,"n":"אנבימיאס, משה מספרד","dt":"רן","dp":"ספרד","b":"רב בלה גרדיאה-ספרד. נהרג עק\"ה-רן בעלילת דם, עם יהודים נוספים ואנוסים."},{"i":5065,"n":"אנג'אר, מימון ממרוקו","b":"היה עבד אצל יהודי מדרעא, התגייר, וסייע ליהודים אחר השמד בדרעא - ר אברהם ןן עזרא חיבר קינה על השמד."},{"i":5066,"n":"אנג'יל משלוניקי","f":"חיים","k":"בעל עץ חיים","dt":"תצג","dp":"שלוניקי","b":"מחכמי שלוניקי. חיבר דרשות והספדים וטעמי מצוות בשם \"עץ חיים\"."},{"i":5067,"n":"אנגילו מאופני","b":"מגדולי חכמי ספרד,בגירוש עבר לפיררה-רנ\"ב"},{"i":5068,"n":"אנג’ל ברוך","dt":"ה'תל 1670","bk":[["חידושי הרב",""],["ספר חדושי הרב",""],["שאולת ותשובות הרב ברוך אנג’יל",""]]},{"i":5069,"n":"אנגל משלוניקי","f":"חיים","b":"מחכמי שלוניקי-שנות ה-ת'-תק'."},{"i":5070,"n":"אנגל, אברהם - ג'ילבי","k":"בעל פתוחי חותם","dt":"תקעט","dp":"ירושלים","b":"רב בשלוניקי - תקס, עלה לירושלים בסוף ימיו, חיבר גם \"פתוחי חותם\" שלוניקי תקעט, אולי חתום על מכתב רבני צפת לקהילת פיסא משנת תקכז"},{"i":5071,"n":"אנגל, אברהם מירושלים","f":"רפאל","bp":"ירושלים","b":"עסקן בועד העדה הספרדית בירושלים-תרף."},{"i":5072,"n":"אנגל, אהרן מניו גרסי","f":"הרץ","k":"בעל לב אהרן","b":"בן דודו של ר\"ש אנגל. רב בבעיאן (ניו גרסי). חיבר \"לב אהרן\" ניו יורק תרפו."},{"i":5073,"n":"אנגל, אהרן מסערדאוהל","b":"חתן ר משה מסערדאוהל. חתנו - ר אברהם פליישמן."},{"i":5074,"n":"אנגל, ברוך מקושטא","dt":"תל - יד טבת","b":"מגדולי חכמי דורו בקושטא-ש\"פ (יתכן שהוא זהה לר ברוך אנגל משלוניקי)."},{"i":5075,"n":"אנגל, ברוך משלוניקי","k":"בעל שות וחדושי ר ברו","bt":"שנה-שס - לפני","bp":"שלוניקי","dt":"תכב או תח","dp":"אזמיר","b":"תלמיד ישיבת ר אשר ן ארדיט (ונקבר לצד רבו), ישיבת ר חיים שבתי בשלוניקי וכיהן כראש הישיבה אחריו, פוסק, דרשן, רב וראש ישיבת \"חברת ת\"ת\" בשלוניקי, ורב הכולל-תיח, עבר לאזמיר והרביץ שם תורה. מתלמידיו: ר דוד קונפורטי בעל \"קורא הדורות\", ר שלמה בן שמואל פלורנטין בעל \"דורש משפט\", ר יצחק פלורנטין. חיבר חידושים על הש\"ס ושו\"ת. בניו: ר משה, ר יהושע. חתניו (שהיו תלמידיו): ר יהודה פישי, ר יוסף פילוסוף-חותנו של שבתי צבי - נכדתו מירה היתה נשואה לש\"ץ. חיבר שו\"ת - שלוניקי תעז. מפסקיו ב\"דורש משפט\" שלוניקי תטז. בנו נפטר בחייו. נכדו - ר ברכה אנגל מרשיד הו\"ל מכתביו בשו\"ת אנגל - שלוניקי תעב. (ראה גם ר ברוך אנגל מקושטא - כנראה רוזנס מערב ביניהם ואולי הם זהים)."},{"i":5076,"n":"אנגל, ברכה משלוניקי","b":"נכד ר ברוך אנגל משלוניקי. הו\"ל כתבי זקנו - שו\"ת אנגל - שלוניקי תעז."},{"i":5077,"n":"אנגל, דוד מבאטאני","f":"דב","bt":"תרז","b":"רב בבאטאני, קאוואטשהאזא"},{"i":5078,"n":"אנגל, דוד משלוניקי","dt":"תקלג","dp":"שלוניקי","b":"גביר בשלוניקי. נהרג עק\"ה-תקלג."},{"i":5079,"n":"אנגל, דוד משלוניקי","dt":"תרט","dp":"שלוניקי","b":"גביר ופרנס בשלוניקי."},{"i":5080,"n":"אנגל, הרש משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":5081,"n":"אנגל, וידאל מירושלים","f":"חנוך משה","bt":"תרלה","bp":"שלוניקי","dt":"תרסז - כח שבט","dp":"ירושלים","b":"עלה לירושלים-תרלה, דיין אצל ר' יעקב שאול אליישר, ראב\"ד לעדת הספרדים, ראש בית הדין וראש מדרש \"בית אל\", פרסם מאמרים ב\"המאסף\" - ירושלים תרנו, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":5082,"n":"אנגל, זאב וולף מטרנוב","f":"זאב וולף","bt":"תריט","dt":"תשב","b":"מחכמי טרנוב, אחיו של ר שמואל אנגל."},{"i":5083,"n":"אנגל, זכריה משה מקושטא","b":"גביר בקושטא-שנות ה-ת', סייע ללומדי תורה."},{"i":5084,"n":"אנגל, חיים","b":"תשובות ממנו ב\"כתונת יוסף\"."},{"i":5085,"n":"אנגל, חיים ביג משלוניקי","b":"רופא צבאי בשלוניקי-תרס."},{"i":5086,"n":"אנגל, חיים וידאל משלוניקי","f":"שבתי","k":"בעל ספר החיים","b":"דרשן, רב בקהילת קטלוניה בשלוניקי-תצג. חיבר \"סיפור החיים\"."},{"i":5087,"n":"אנגל, חיים מרדומישל","f":"שמואל","bt":"תרם","dt":"תשא-ג","b":"ראב\"ד רדומישל, על כסא אביו. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"קהלת אשר\" - אושפיצין תרפג, \"שערי תורה\" - קראקא תרפה."},{"i":5088,"n":"אנגל, חנוך משה מירושלים","f":"וידאל בן משה","dt":"תרמה - ז תשרי","dp":"ירושלים","b":"מחכמי ירושלים - תרלד, ומראשי ישיבת \"בית אל\", חתם על כמה פסקים. מתורתו ב\"המאסף\" לקאינקה. אולי אביו של ר וידאל."},{"i":5089,"n":"אנגל, יהודה ליב מיארמוט","b":"רב ביארמוט-תץ, ור ברמן בן דוד מביזינץ על מקומו אחריו."},{"i":5090,"n":"אנגל, יהודה מונציה","bt":"תק","dt":"תקן","b":"רב בויניצא, אבי משפחת אנגל."},{"i":5091,"n":"אנגל, יהודה מקושטא ושלוניקי","b":"מדפיס בשלוניקי, עבר לקושטא-תקב לדפוס של בנימין בן משה רוסו."},{"i":5092,"n":"אנגל, יהודה משלוניקי","dt":"תעז","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":5093,"n":"אנגל, יהושע מפשוורסק","f":"שמואל","b":"מחכמי פשוורסק - תשובה אליו ב\"מחזה אברהם\"-תרע."},{"i":5094,"n":"אנגל, יוחנן משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'-תק'."},{"i":5095,"n":"אנגל, יוסף מבודפשט","f":"יעקב","bt":"תקעה","bp":"אויהל","dt":"תרכא - יח אב","dp":"בודפשט","b":"תלמיד החת\"ס, ור צבי הרש הלר מאויבן."},{"i":5096,"n":"אנגל, יוסף מקראקא","f":"יהודה","k":"בעל עין פנים לתורה","bt":"תריט","bp":"טרנוב","dt":"תרף","dp":"וינה","b":"מחכמי בנדין, (למד גרמנית ועסק לפרנסתו ביעוץ משפטי לעו\"ד). חתן ר משה קליינר. סירב להצעת ר אליעזר גורדון לעמוד בראש ישיבת טלז. ראב\"ד קראקא-תרסו. השתתף בועידת היסוד של \"אגודת ישראל\". בזמן המלחמה עבר לוינה. חיבר \"עין פנים לתורה\" למברג תרמט, ועוד."},{"i":5097,"n":"אנגל, יוסף משלוניקי","b":"מחכמי שלוניקי-תקפה, הו\"ל \"בתי אבות\" לר יוסף דוד-תקפה."},{"i":5098,"n":"אנגל, יחיאל","f":"שלום אנגלרט","b":"חתן ר ישראל איסר יונה אייזנברג. חסיד ר משה מרוזוודוב."},{"i":5099,"n":"אנגל, יצחק הירש מדאראג","b":"גביר מחכמי דאראג."},{"i":5100,"n":"אנגל, יצחק מטרנוב","f":"יהודה","bt":"תרך","dt":"תרנב","b":"אחיו של ר יוסף ראבד קראקא. מחכמי טרנוב, סידר לדפוס את ספרי אחיו. השיג על ספר \"אתוון דאוריתא\" של אחיו ונדפס בשות \"בן פורת\"."},{"i":5101,"n":"אנגל, יצחק מצפת","b":"מחכמי צפת, חתם-תקכג על כתב שליחות ר אשר קוריאט."},{"i":5102,"n":"אנגל, יצחק משה משלוניקי","dt":"תרטז","dp":"שלוניקי","b":"רב ופוסק בשלוניקי-תקצה. תשובה ממנו ב\"אמר שמואל\" לר שמואל חביב."},{"i":5103,"n":"אנגל, יצחק משלוניקי","dt":"תקיג - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"מעם לועז\"-ויקרא-תקיג, ובנו ר משה - שסייע בהדפסת ח\"ד-במדבר."},{"i":5104,"n":"אנגל, ישראל מקאליב","b":"דיין בקאליב-תקפב."},{"i":5105,"n":"אנגל, מאיר מסופיה","f":"אברהם","k":"בעל קשת נחושה","bt":"שכד","bp":"שלוניקי","dt":"תז","dp":"צפת","b":"מחכמי שלוניקי וקושטא, תלמיד ר אלעזר אזכרי, ור ישראל בן סרוק - מגורי האר\"י. רב בסופיה-בולגריה, בלגרד. עלה לצפת-שפב. חיבר \"קשת נחושה\" חמד שנג, \"מסורת הברית הגדול\" - מנטובה."},{"i":5106,"n":"אנגל, מירקדו חיים משלוניקי","b":"רב בשלוניקי-תרכז, מנהל דפוס סעדי אשכנזי."},{"i":5107,"n":"אנגל, מנחם מנדל מפריסטיק","b":"מחמכי פריסטיק, השתתף באהל מועד תרנט."},{"i":5108,"n":"אנגל, מרדכי מרומא","b":"גדול בדורו,שר היהודים ברומא-שנת ש'"},{"i":5109,"n":"אנגל, מרדכי משלוניקי","dt":"תמב","dp":"שלוניקי","b":"מחכמי שלוניקי. דודו-אחי אמו של ר שלמה אמריליו."},{"i":5110,"n":"אנגל, משה מוערעשוואר","f":"יהודה אנגל","dt":"תקפ - טז חשון","b":"רב בווערעשוואר"},{"i":5111,"n":"אנגל, משה מוערעשוואר","k":"בעל שירת האדון","b":"רב בפיליש וארוש וואר(=וערעשוואר) או בשארוואר-תקלט כ-50 שנה. חיבר שירים בעברית לז' אדר בשם \"שירת האדון\" - פעסט תרלג."},{"i":5112,"n":"אנגל, משה משלוניקי","f":"ברוך","dt":"תמט","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":5113,"n":"אנגל, משה משלוניקי","f":"יצחק","dt":"תקך - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"מעם לועז\"-במדבר-תקך, (אביו סייע בהדפסת ויקרא-תקיג)."},{"i":5114,"n":"אנגל, נחמן מירושלים","f":"וידל חנוך","bt":"תרכט","bp":"שלוניקי","dt":"תרפה - א טבת","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים והיה מקובל מחכמי ירושלים, ומראשי \"בית אל\". רב מטעם ועד העזרה האמריקאי שע\"י \"העדה החרדית\" הספרדית, ונרדף על כך מהמשכילים. בעל דרושים ופירושים על התנך, ונדפסו על ידי בנו."},{"i":5115,"n":"אנגל, סעדי שמואל משלוניקי","b":"מדפיס בשלוניקי אצל אברהם בן דוד נחמן ויום טוב קאנפיליאש-תס."},{"i":5116,"n":"אנגל, עזריאל מאיר מפרשבורג","bt":"תרלו","bp":"סערדאוהל","dt":"תרצב - ב אייר","dp":"פרשבורג","b":"תלמיד השב\"ס. מחכמי ראצרסדורף, פרשבורג-תרעא וכיהן כנשיא הקהלה-תרץ, ממיסדי ביה\"ח היהודי-תרצא. עמד בראש מחנה המתונים בפרשבורג-תרף-תרץ המכונים \"הלבנים\" - בתמיכת ה\"מזרחי. מג\"מ ומחברי אגודה \"עץ חיים\" - פרשבורג תרעא - ללימוד תורה של חבורה מחכמי פרשבורג."},{"i":5117,"n":"אנגל, שאול מקאליב","f":"אברהם","dt":"תר - כ אב","b":"תלמיד ר יצחק איזיק מקאליב, והחוזה מלובלין. ראש חסידי קאליב באשוואר - עוד בחיי רבו מקאליב. דיין בקראלי, קאליב. בניו ר יוסף מקאליב, ר וולף מקאליב, ר אביגדור. תולדותיו ב\"צפונות\"-ז."},{"i":5118,"n":"אנגל, שבתי מירושלים","b":"מחכמי ירושלים, בשנת תקיח נמנה על הישיבה \"חסד לאברהם ובנין שלמה\" ור\"מ בישיבה. יתכן שהוא אביו של ר חיים וידאל אנגל בעל \"ספור החיים\""},{"i":5119,"n":"אנגל, שם טוב משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'-תק'."},{"i":5120,"n":"אנגל, שמואל מבילגוריא","f":"זאב וולף","k":"בעל שות מהר\"ש אנגל","bt":"תריג","bp":"טרנוב","dt":"תרצה - יט אדר","b":"תלמיד הדברי חיים מצאנז. חתן ר יצחק הרמן שהיה חתן ר שמואל מנחם ויסמן מבילגוריי, ועבר לגור שם. רב בבילגוריי-תרלב, דוקלא-תרמא, רדומישל-תרמו, קשוי-תרפג, חיבר גם \"שפתי מהר\"ש\". פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"הירדן\" - רישא תרץ, \"הכוכב\" - מונקטש תרצה, \"כרמנו\" - אלכסנדר-לודז תרצג, \"קהילת יעקב\" - זבארוב-סלובקיה תרפה, \"קובץ דרושים\" - פיעטרקוב תרפג, \"שערי תורה\" - קראקא תרפה."},{"i":5121,"n":"אנגל, שמעון מזלחוב","dt":"תשג","b":"רב בזעלחוב"},{"i":5122,"n":"אנגל, שמעיה מקושטא ודמשק","dt":"תרלד","dp":"דמשק","b":"חתן הרב ר אברהם גאגין-אג\"ן. גביר בקושטא ודמשק, תרם הרבה ליהודי ארץ ישראל. בנו - ר אלעזר שהמשיך את דרכו."},{"i":5123,"n":"אנגל-הורביץ, אברהם שמעון מקרקא","f":"מאיר הלוי","k":"בעל שובה ישראל","bt":"תרלו","bp":"ז'ליכוב","dt":"תשג","b":"מצאצאי בעל השל\"ה. מחסידי ר אבי עזרי זליג אלעזר מקוזניץ, תלמיד ר אלכסנדר לבין מזידיטשוב, ומקורב לגדולי האדמורים. חתן הגביר ר משה פינגבוים מגרוולין. סירב לרבנות וכיהן כמגיד שיעור בזליחוב, צאנז, קשנוב, סטולין, ליובאויטש, סייע לר מאיר שפירא לנהל את ישיבת חכמי לובלין. רב בקראקא. חיבר \"שובה ישראל\" - להזהיר מפני הבאות לפני השואה - קראקא בעילום שמו (א\"ש - ראשי תיבות שמו). נספה בשואה. לקוטי תורתו - \"נהרי א\"ש\" - ירושלים תשנג."},{"i":5124,"n":"אנגלברג, דוד מאמריליב","b":"מחכמי אמריליב (ליד זלישטשיק). מתורתו ב\"ועד חכמים\"."},{"i":5125,"n":"אנגלמאיר, מרדכי מלומנא","k":"בעל עזרת ישראל","bt":"תרו","bp":"לומנא","dt":"תרץ","b":"אב\"ד לומנא (ליד טורקא)-תרלו בהשפעת רבו האדמור מבלז. עבר לנירנברג ופפד\"מ. חיבר \"עזרת ישראל\" ירושלים תשנג."},{"i":5126,"n":"אנגלמן, אהרן מקויל","bt":"תקנז","dt":"תרה - ו אלול","b":"רב בקויל"},{"i":5127,"n":"אנגלמן, אפרים (אביגדור) ברוך","f":"אהרן מקויל","bt":"תקצו","dt":"תרפא - יח חשון","b":"תלמיד ר מאיר מקאליש בעל \"אמרי בינה\", ר הירצקי מבלאשקי, ר שמחה מגאמבין(=גומבין). נסמך מאת: ר דוד טיבנפליגל מקויל, ר שמשון מקאליש, ר נחום מסוכטשוב. רב באלימונוב(=בילימאוו)-פלך וארשא-תרכ, קלאדובה(=קלאדאווע)-פלך קאליש-תרכה, (קולו - תרו?)."},{"i":5128,"n":"אנגלמן, גרשון מקרושנביץ","f":"אהרן אנגלמן","dt":"תרסא - א טבת","b":"רב בסלאשין,קרושנביץ"},{"i":5129,"n":"אנגלמן, שלמה מקרושנביץ","f":"גרשון אנגלמן","b":"רב בקרושנביץ-תרס\"א"},{"i":5130,"n":"אנגלנדר, אברהם מאויהל","b":"דומ\"צ באוהעל-תר\"כ"},{"i":5131,"n":"אנגלנדר, אליעזר ליפמן מקאשוי","b":"מראשי קהלת קאשוי, חתם-תרלג על כתב מינוי ר משה יונגרייז."},{"i":5132,"n":"אנגלנדר, זאב","f":"שאול יצחק הכהן","bt":"תרעב","bp":"בוכניה","dt":"תש..","b":"תלמיד ישיבת בובוב בבוכניה. עבר ליבורוזנה. נספה בשואה."},{"i":5133,"n":"אנגלנדר, חיים מלמברג","f":"יעקב הכהן מצאנז","dt":"תשנח","b":"חתן נכדת ר חיים קלוגר מטשבין. מחכמי למברג. ניצל מהשואה, עבר לפריס. עלה לארץ-תשלח."},{"i":5134,"n":"אנגלנדר, ישראל אהרן הכהן","bt":"תרי","b":"נשלח ע\"י הדברי חיים לשמש כרב בבוקובסק לצד נכדו ר שלמה הלברשטם, ראב\"ד פריסטיק-תרסז. תשובות אליו בשות מהרשם. הדפיס-תרנז \"מעין גנים\" לרמ\"ע מפאנו (מכת\"י שקבל ממהר\"י מבלז)."},{"i":5135,"n":"אנגלנדר, מנשה יחזקאל מצאנז","b":"מחכמי צאנז-תרצא, פרסם מאמרים ב\"הפרדס\" - צאנז תרצא."},{"i":5136,"n":"אנגלנדר, משה אהרן הכהן","k":"בעל אור משה","b":"מחכמי קרשצינקה. נכד ה\"סמיכת חכמים\". חסיד בובוב. חיבר \"אור משה\"."},{"i":5137,"n":"אנגלנדר, שמעון מקרשצינקה","f":"משה אהרן הכהן","k":"בעל שער שמעון","bt":"תרלד","bp":"קרשצינקה","dt":"תשי","b":"חתן ר צבי הירש מאיר ערנסט מנימרקט. מדפיס. עלה לארץ-תרצד, והתישב בחיפה. חיבר \"שער שמעון\" ירושלים תשט."},{"i":5138,"n":"אנגלנדר-פרנקל, יעקב ברוך מקאלי","f":"אורי ליפמן מבית חלפן","k":"בעל מליץ יושר","bt":"תקנב","dt":"תרכד - כב אד\"ב","dp":"קאלוב","b":"השם רפפורט מזקנו ר יצחק הכהן רפפורט מלייפניק. תלמיד החת\"ס, ר יואב בן ירמיה מאונסדורף, ר צבי הלר מאויבן ואחיו הגדול ר יצחק פרנקל מקראלי. חתן הגביר ר יחיאל מיכל זיכרמן מאפערטא וגר שם. רב בקאליב-תקפא. בזיוו\"ש חתן אלמנת ר שלמה ורטהימר מפעזינג. אחיו של ר יצחק פרנקל מקראלי בעל \"זבד טוב\". נזכר ב\"אמרי א\"ש\" לר מאיר איזנשטט מאונגואר."},{"i":5139,"n":"אנגלנדר-פרנקל, יעקב מקאליב","f":"יעקב ברוך פרנקל מב\"ח","bt":"תקעג","bp":"פרשבורג","dt":"תרמד - כ כסלו","b":"תלמיד החת\"ס, ודודו ר יצחק פרנקל מב\"ח אב\"ד קראלי, ור שמואל קליין מבאלקאן וסעליש. חתן ר משה פופר מבאלקאן ועבר לשם-תקצד. רב בקאליב."},{"i":5140,"n":"אנגלסברג, נפתלי הרץ מקרסניברד","dt":"תשג","b":"רב בקרסניברד"},{"i":5141,"n":"אנגלסמן, גבריאל הכהן מרכניץ","f":"ראובן ישראל איש מלאכ","k":"בעל עיני ישראל","r":"אב\"ד רעכניץ","bt":"תקלא","bp":"ואג-אויהלי","dt":"תריא - כד טבת","dp":"רכניץ","b":"תלמיד ר הירש ברוידא בקיטזע. חתן דודו ר משה באשאן מעיר חדש. דיין בעיר חדש(=ניישטט), מו\"ץ בואג-אויהלי, רב ברכניץ-תקפב כ-30 שנה (הרב החרדי האחרון שם). חיבר גם \"פני משה\". בניו: מאיר, משה - נפטרו צעירים. הסכים על \"אות ברית\" לר שמעון מנאדאש. תשובה ממנו בשו\"ת מהרי\"א אסאד. חיבר גם \"גבורת השם\".","bk":[["עיני ישראל - מאיר עינים - שבועות וב\"ב",""],["עיני ישראל - פני משה - חולין",""]]},{"i":5142,"n":"אנגלסמן, ראובן ישראל מעיר חדש","f":"מאיר כץ","k":"איש מלאכי","b":"רב בעיר חדש-תקם. בנו - ר גבריאל הכהן מעיר חדש."},{"i":5143,"n":"אנגלרד, אברהם ישכר מראדזין","f":"ישעיה מסוסנוביץ","k":"אדמור מראדזין ב\"ב","bt":"תרע","b":"נכד ר נתן נחום רבינוביץ האדמור מקרימלוב. חתן ר מרדכי יוסף אלעזר ליינר האדמור מראדזין. נשיא ישיבת \"סוד ישרים\" של אחיו האדמור מראדזין. ניצל מהשואה - לאחר שאיבד את כל משפחתו, ואחריה רב בסוסנוביץ על מקום אביו, היגר לארה\"ב, עלה לארץ וכיהן כאדמור מראדזין בבני ברק."},{"i":5144,"n":"אנגלרד, אברהם מאברא","f":"מאיר צבי","k":"בעל אמרי אברהם","bt":"תרע","bp":"סנוק","dt":"תשלו","b":"למד בישיבת בובוב. חתן ר חיים ליברמן אב\"ד אברא, והיה רב באברא לאחר חותנו. בתחילת המלחמה ברח ללמברג והקים בה ישיבה, הוגלה לבוכרה ולסיביר, עלה לארץ בתש\"ו והיה אב\"ד בקרית בובוב בבת ים. חיבר \"אמרי אברהם\" בני ברק תשלה."},{"i":5145,"n":"אנגלרד, אהרן מפריסטוק","b":"תלמיד ישיבת רדומסק בסוסנוביץ. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":5146,"n":"אנגלרד, יצחק איזיק מרישא","k":"בעל ריח דודאים","b":"מחכמי רישא, דברי תורה ממנו ב\"בנין מנחם\", \"מציון תצא תורה\" - זאמושט תרפט. חיבר \"ריח דודאים\" ו\"עורך הירדן\"-קראקא תרץ."},{"i":5147,"n":"אנגלרד, ישעיה מסוסנוביץ","bt":"תרמה","dt":"תשג","b":"רב פעלים,רב במונדזאוו,סוסנובצה"},{"i":5148,"n":"אנגלרד, מאיר משידלובצה","b":"רב בשידלובצה"},{"i":5149,"n":"אנגלרד, מנחם מנדל מבנדין","b":"חתן ר ישראל איסר יונה איזנברג מזמיגרוד. ר\"מ בישיבת כתר תורה דרדומסק בפודגורזע, סוסנוביץ ובנדין. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":5150,"n":"אנגלרד, שלום מקולבסוב","b":"רב בקולבסוב ליד חמיו ר יצחק אליעזר גרהר. חזן בפריסטיק."},{"i":5151,"n":"אנגלשטין, משה יעקב מקראקא","b":"חסיד רדומסק בקראקא. מחותן עם המהרש\"ם. בנו ר מרדכי דב מארה\"ב מח\"ס \"דברי מרדכי\" שנדפס בסוף \"מנחת אברהם\" לדודו ר אברהם רינהולד."},{"i":5152,"n":"אנגלשטין, שלום מרדכי","b":"נכד המהרשם, מופיע בספר \"מנחת אברהם\" לר ריינהולד."},{"i":5153,"n":"אנדאם, יוסף מאלגיר","b":"רב בתלמסאן-אלגיר. נזכר בפנקס ר סעדין בן סידון (ובפנקס ר יצחק רוש - בצרפתית)."},{"i":5154,"n":"אנדיבו, נסים מדמשק","b":"רב ראשי בדמשק."},{"i":5155,"n":"אנדראן, שמואל יצחק מארה\"ב","b":"מיסד ישיבת יעקב יוסף - הישיבה הראשונה באמריקה. חתנו - ר יעקב יוסף הרמן מניו יורק וירושלים."},{"i":5156,"n":"אנדרוויצר, אברהם שמשון","bt":"תרכג","bp":"הולנד","b":"תלמיד ביהמ\"ד לרבנים באמשטרדם. רב באמשטרדם-תרמח. חיבר פירוש ותרגום לתורה בהולנדית. יסד חברת \"בצלאל\" ללימוד אמנות."},{"i":5157,"n":"אנדריאס","b":"יש פיוט סליחה לארבע צומות שחתום בו בראשי חרוזים \"אנדריאס\" וב\"טעם זקנים\" כתוב שהיה אחד מחכמי ישראל שהמיר דתו ונעשה הגמון וביטל גזירה נגד היהודים וביקש מחכמי ישראל שיחברו סליחה לכבודו."},{"i":5158,"n":"אנה מריה קונקורדיה שם העט שלה רות נהידה שטורמהפל","r":"נוצריה שהתגיירה בשנת תרנה","bt":"תרט","bk":[["דאס יידישע וייב \\ האשה היהודיה - התייחסות היהדות אל האשה",""],["מחקרים תרבותיים על היהדות",""]]},{"i":5159,"n":"אנהורי - משפחה","b":"משפחת רבנים במרוקו ובארץ ישראל."},{"i":5160,"n":"אנהורי, אברהם מצפת","bp":"מרוקו","dt":"תקצז","dp":"צפת","b":"מחכמי טיטואן עלה לצפת וכיהן כאב\"ד, הסכים על \"עפר יעקב\" - ברסלוי תקצט, \"פאת השלחן\" לר ישראל משקלוב, נהרג ברעידת אדמה שהחריבה את צפת. חתם על הספר עפר יעקב לר יעקב אייכהורן. בספריה הלאומית כת\"י פרטי דינים מה שפסקו רבני מאראקיש עם חתימתו והערות והוספות שלו."},{"i":5161,"n":"אנהורי, אלישע","b":"חכם שלם-תקט\"ו"},{"i":5162,"n":"אנהורי, יהודה מסאלי ורבאט","f":"מנחם","dt":"תקנב","b":"מרביץ תורה, מו\"צ בסאלי, רב ברבאט. בנו - ר משה."},{"i":5163,"n":"אנהורי, ישראל מטבריה","b":"רב בטבריה-תרה."},{"i":5164,"n":"אנהורי, מנחם מטיטואן","b":"רב בטיטואן-תעב בזמן ר חסדאי אלמושנינו, וחתם אז על תשובה ב\"משפט וצדקה ביעקב\", טנג'יר-תק. בנו - ר יהודה שהיה רב בסאלי ורבאט."},{"i":5165,"n":"אנהורי, משה מסלי וראבאט","f":"יהודה","dt":"תקפד - יח ניסן","b":"מחכמי סאלי ורבאט בזמן היעב\"ץ. חתנו ר נתן עמרם בעל \"נועם המידות\". רב בחלב-תקעז, מצרים-תקעט. בזמן מלחמת העולם השניה ערכו יהודי מצרים תפלה על קברו."},{"i":5166,"n":"אנהורי, שמואל מאלגיר","b":"רב בווהראן, עלה לצפת-תקצג - לאחר הכיבוש הצרפתי, והיה מלמד תשב\"ר. הכין עבור מונטיפיורי את רשימת יהודי צפת."},{"i":5167,"n":"אנוכביץ, יוסף משאקי","dt":"תשג","b":"רבה האחרון של שאקי. נספה בשואה."},{"i":5168,"n":"אנוליק שמעון דובר בן אברהם","bt":"1848","dt":"ה'תרסו 1906","bk":[["אורח משפט",""],["אמרי רש\"ד",""]]},{"i":5169,"n":"אנזלם מפפד\"מ - א","b":"רב בפפד\"מ. חתם-מח על תעודה עם חברו ר יצחק מברוכזלדה."},{"i":5170,"n":"אנזלם מפפד\"מ - ב","f":"פיבש מקלן","b":"רב ומלמד תורה בפפד\"מ-קי."},{"i":5171,"n":"אנטאלטי, אליהו הרופא מונציה","b":"רופא בונציה בזמן ר יהודה אריה די מודנא המזכירו בספרו."},{"i":5172,"n":"אנטאקאליע-קהילה","b":"פרבר של וילנא. היתה כפופה לאב\"ד וילנא עד פטירת האב\"ד האחרון ר שמואל, ומאז מינתה מו\"ץ לעצמה. רבנים: ר ישראל ליפשיץ אנטאקאליער מו\"ץ אחר פטירת הראב\"ד האחרון בוילנא ר שמואל, ואחריו ר יעקב הרץ בן יוסף-נפטר תרה, ואחריו ר ישראל אידל בן ר יהודה ליב רחי ממיילאט-נפטר תרכב, ואחריו ר יעקב בן אברהם הכהן בעל \"דברי חפץ\", ואחריו ר אריה ליב בן עקיבא לוריא - העילוי מקיידאן, ואחריו ר נחום שמעון בן נתן נטע, ואחריו ר שלמה הכהן-שעבר לוילנא, ואחריו ר ליב בן גרשון, ואחריו ר דב בער הכהן צייטלין, ואחריו ר יהושע פאלק בן שמעון הורביץ."},{"i":5173,"n":"אנטולי","f":"יעקב - מלמד התלמידים","k":"בעל רוח חן","b":"חיבר דיוואן שירים, וחיבר שירים לחבריו ובהם ר שמואל הנפוסי בן ר מנחם. חיבר \"העולם - רוח חן\" - ביאור התורה בפילוסופיה ומוסר (הספר יוחס בטעות לר\"י ן תבון)."},{"i":5174,"n":"אנטולי הנשיא מצרפת ומצרים","f":"יוסף","b":"רב במארשילייא-צרפת-ד'תתק, עבר לאלכסנדריה ושלח מכתב לרמב\"ם בבקשה ללמדו ביאורי תורה והרמב\"ם השיב לו. בניו: ר שמעון, ר יעקב - ונזכרו עם אביהם אצל ר בנימין מטודלה מביקורו במארשילייא (ויש אומרים ר אנטולי מאלכסנריה הוא רב אחר). נכדו - ר אבא מרי ונינו ר יעקב בעל \"מלמד התלמידים\"."},{"i":5175,"n":"אנטולי מאוטרנטו-איטליה","b":"פייטן קדום. פיוטים ממנו במחזורים קדומים."},{"i":5176,"n":"אנטולי, יעקב","f":"שמעון","b":"נכד ר אנטולי בן ר יעקב בעל \"מלמד התלמידים\"."},{"i":5177,"n":"אנטולי, יעקב ממרשילייא","f":"אנטולי ממצרים","b":"מחכמי מרשילייא ונזכר עם אחיו ר שמעון אצל ר בנימין מטודלא שפגש בהם. אביו עבר לאלכסנדריה."},{"i":5178,"n":"אנטולי, יעקב מנפולי","f":"אבא מארי בן שמעון","k":"בעל מלמד התלמידים","b":"נינו של ר אנטולי מאלכסנדריה וצרפת. חתן ר שמואל ן תבון ותלמידו. חיבר \"מלמד התלמידים\" בכת\"י. נקרא ע\"י הקיסר פרידריך השני לנפולי כדי לתרגם את ספרי החכמים הערבים ללטינית. בנו ר אנטולי ונכדו ר שמעון בעל \"רוח חן\"."},{"i":5179,"n":"אנטולי, שמעון ממרשילייא","f":"אנטולי ממצרים","b":"מחכמי מרשילייא ונזכר עם אחיו ר יעקב אצל ר בנימין מטודלא שפגש בהם. אביו עבר לאלכסנדריה."},{"i":5180,"n":"אנטוניא יוסף מפורטוגל","bt":"תמה","bp":"פורטוגל","dt":"תקה","dp":"פורטוגל","b":"מאנוסי פורטוגל, עבר לברזיל וחזר לפורטוגל, משורר, היה יהודי בסתר - נהרג עק\"ה."},{"i":5181,"n":"אנטוקולסקי, משה שמעון מוילנא","f":"ברוך ראובן","k":"בעל דברי כהן","bt":"תרי","bp":"וילנא","b":"תלמיד ישיבת מייליס בוילנא. רב ומטיף בוילנא ונוטה להשכלה, שימש עוזרו הראשי של רש\"י פין בהוצאת \"הכרמל\". פרסם מאמרים בעתוני התקופה ובהם \"הכרמל\", \"האסיף\", ועוד. הו\"ל כתב עת \"הכרם\"-תרסו. חיבר \"אבל כבד\" - הספד על ר מתתיה שטרשון."},{"i":5182,"n":"אנטמן, יהודה ליביש מלינסק","b":"מחכמי לינסק-תרצה, מופיע תשובה אליו ב\"דובב מישרים\"."},{"i":5183,"n":"אניגואר, משה","dt":"תקצח","b":"רב בגעביטץ"},{"i":5184,"n":"אניסימוב, שרבת מדגסטן","f":"נסים","dt":"תרסו - ב טבת","dp":"ירושלים","b":"עלה לירושלים-תרכה, תלמיד ישיבת עץ חיים אצל ר משה נחמיה כהנא, חזר לדגסטאן ולמד רפואה, עלה שנית לירושלים והיה מראשי עדת דגסטאן בירושלים."},{"i":5185,"n":"אניקסטר, יהודה ליב מאניקשט","f":"צבי","b":"הסכים על ש\"ס וילנא-תקצה."},{"i":5186,"n":"אניקסטר, יהודה ליב משיקגו","k":"בעל חדושי אב\"י","b":"רב בשיקגו-תרסה."},{"i":5187,"n":"אנישבון, שלום ממגניסיאה","b":"רב במגניסיאה-שנות ה-ת', ור יעקב עוזיאל על מקומו אחריו. היה במחלוקת עם ר משה עבאש מטיריא."},{"i":5188,"n":"אנלדודי, אלקנה מיוון","b":"מחכמי יוון. חתם-רן בפסק עגונה ונזכר בשו\"ת \"בנימין זאב\"."},{"i":5189,"n":"אנליק, יהודה ליב","f":"שמעון דוב אנוליק","k":"בעל וזאת ליהודה","dt":"תרצז - ו סיון","b":"רב במישעניץ"},{"i":5190,"n":"אנליק, יהושע ליב","dt":"תשג","b":"רב במישינץ"},{"i":5191,"n":"אנליק, שמעון דב בר מליטא","k":"בעל אורח משפט","bt":"תרח","bp":"וילקומיר","dt":"תרסד-ז -ז-ט טבת","dp":"שדליץ","b":"תלמיד ר יהושע איזיק חריף בעל \"נועם ירושלמי\", ישיבת וולוזין. רב בשאקי, אוסטרוב, מזובייצק, טיקטין, שדליץ."},{"i":5192,"n":"אנסיכי, אברהם","f":"ענתבי, אברהם","dt":"תריח - כה שבט","b":"רב בדמשק"},{"i":5193,"n":"אנסר, משה מלמברג","f":"חיים","k":"בעל משאת משה","bt":"תקסד","bp":"למברג","b":"חתן ר צבי הירש מאטשיר. חיבר \"משאת משה\" למברג תריד. ידיד לשי\"ר וחבריו ובקי בשפות ובמיוחד בעברית. השתתף בכתבי עת שונים."},{"i":5194,"n":"אנפיל הכהן מאלגיר","f":"יוסף","bt":"רל","dt":"שי - בערך","b":"רב בתלמסאן. בקי בשפות ופיענח עבור המושל כתב סתר - ונזכר ב\"עומר השכחה\"."},{"i":5195,"n":"אנצ'אס, יעיש מפאס","b":"מחכמי פאס-תמט והספיד את ר יהודה עוזיאל, ואת ר שלמה עמאר-תנא."},{"i":5196,"n":"אנצוייג, יצחק הכהן מדוקלא","b":"פרסם מאמרים ב\"התפוח\" - בנדין תרפח."},{"i":5197,"n":"אנצילביץ, גרשון","f":"ישכר בער מדרושקביץ","b":"רב בדאלינוב-ת\"ר"},{"i":5198,"n":"אנצילביץ, גרשון מוורניאן-ליטא","f":"חיים מסמרגון","bt":"תקפב","bp":"סמארגון","dt":"תרסג","b":"תלמיד ר לייב שפירא. רב בוורניאן(=ואראניאן), מוזיר(=מאזיר)-פלך מינסק-תרכג. בנו ר זלמן על מקומו אחריו במוזיר."},{"i":5199,"n":"אנצילביץ, דובער","f":"זלמן ממאזיר","b":"סופר. חתן הגביר ר חיים אשר זלציאנוב מזלאבין."},{"i":5200,"n":"אנצילביץ, זלמן ממאזיר","f":"גרשון מואראניאן","bt":"תרכא","bp":"אוסטרוביץ-פלך וילנא","dt":"תרצז - ט חשון","b":"חתן הגביר ר יצחק גורביץ. תלמיד ר מאניא ממינסק, ישיבת וולוזין. רב במאזיר-פלך מינסק-תרנז על מקום אביו, עלה לארץ. נסמך מאת: הנצי\"ב, ר יצחק אלחנן מקובנא, ר רפאל שפירא מוולוזין. בניו - ר דובער, חיים."},{"i":5201,"n":"אנצילביץ, חיים מסמרגון","f":"גרשון מדאלינוב","b":"מו\"צ בסמרגון-תרל."},{"i":5202,"n":"אנצילביץ, ישכר בער מדרושקביץ","b":"תלמיד הגר\"א. חתן ר זלמן ריבעהלעס-דודו של הגר\"א. רב בדרושקביץ-תקע."},{"i":5203,"n":"אנקאב, דוד מפאס","b":"חכם שלם בפאס-תע"},{"i":5204,"n":"אנקאב, מסעוד - ב","b":"חכם וחתם בשטר-תקנה."},{"i":5205,"n":"אנקאב, מסעוד ממכנאס - א","dt":"תף - לפני","b":"מחכמי מכנאס, חתם על שאלה עם חברו ר אפרים אלבז - לחכמי פאס - ר שמואל הצרפתי, היעב\"ץ ועוד - שהשיבו להם."},{"i":5206,"n":"אנקאב, מרדכי מסאלי","b":"מחכמי סאלי, חתם-תקכט על שטר."},{"i":5207,"n":"אנקאווה, אברהם - אבא\"ן, אב\"א","f":"מרדכי","k":"בעל כרם חמד","bt":"תקסז","bp":"סאלי","dt":"תרנא - טז חשון","dp":"אוראן","b":"תלמיד ר רפאל ביבאס מסאלי. מקובל, פוסק, דיין בסאלי, ביקר בלונדון-תרא, עלה לירושלים-תרג, נסע לליוורנו, חזר לסאלי ונאסר ע\"י המלך ונפדה ע\"י בני הקהלה, עבר לכהן כרב בתלמסאן-אלגיר-תרי, דיין במעסקאר(=אלמעסכר)-תריב כ-30 שנה, ווהראן. חיבר שו\"ת \"כרם חמר\" ובסופו \"תקנות חכמי פאס\", \"כסף אחר\", \"זבחים שלמים\", ועוד. מתלמידיו: ר נתן אסייג, ר חיים בלייח, ר מסעוד בן יצו', ר מסעוד בן סוסאן. היה מחלוקת כנגד ספריו ור משה סבעון מווהראן אסר לפסוק מהם - כי לדבריו זלזל בגדולי ישראל ובהם השו\"ע (ובזמן המחלוקת היו שהשתמשו בדפי \"זבחים שלמים\" לאריזת מצרכים), ואל המחלוקת באלגיר הצטרפו חכמי צפון אפריקה וירושלים ור אברהם פרסם \"טהרת כסף\" להגן על ספריו."},{"i":5208,"n":"אנקאווה, אפרים מאלגיר - הנכד","f":"ישראל","bt":"ר - בערך","dt":"רפ - בערך","b":"רב ודיין בתלמסאן, על מקום זקנו ר אפרים. היה בקשרי מכתבים עם ר צמח בן הרשב\"ש שהביא ממנו בספרו \"עומר השכחה\"."},{"i":5209,"n":"אנקאווה, אפרים ממרוקו","f":"ישראל","b":"תלמיד ר רפאל אנקאווה בסאלי. רב באושדה-מרוקו ומראקש."},{"i":5210,"n":"אנקאווה, אפרים מספרד ומרוקו","f":"ישראל בן יוסף","k":"בעל שער כבוד ה","bt":"קיד","bp":"טולידו","dt":"רב או רח","dp":"תלמסאן","b":"ממשפחת גבישון - המשפחה עברה לגרדנה משבלייאה(=סביליה) וכמעט כלם נהרגו עק\"ה - נצלו האחים ר יעקב ור אברהם בני ר יוסף גבישון. נכד ר ישראל נקוואה שנהרג עק\"ה בטוליטולא עם ר יהודה בן הרא\"ש. פייטן, רב בספרד וברח-קנא לאלגיר עם חברו הריב\"ש, רב במראקש, הוניין-אלגיר, דיין בתלמסאן-קנד ורופא בחצר המלך ובהשפעתו ניתנה ליהודים רשות לשבת בעיר (עד אז ישבו בכפר אגאדיר הסמוך). נהגו לעלות על קברו שנחשב למקום קדוש וקבלה בידם שפעם ריפא את בת המושל ובזה הוטב ליהודים שם. תשובה אליו מהריב\"ש להוניאן. חיבר פיוטים, תשובה ממנו ב\"יכין ובועז\" ומוסר דרישת שלום לר יהודה אלנקוה - דודכם, וכנראה זהו בנו שהיה תלמיד הרשב\"ש וחותנו של ר צמח בן הרשב\"ש. השיב תשובות גם לרשב\"ש, חיבר פיוטים ומהם ב\"יבין שמועה\" לרשב\"ץ. עמו נעשה הנס המפורסם עם האריה ששמר עליו בשבת במדבר. מפאת כבודו לא נקרא בשמו אלא בתואר \"רב\" סתם - כך אצל ר משה גבישון. מבניו: ר ישראל, ר יהודה."},{"i":5211,"n":"אנקאווה, דוד מקושטא","f":"נסים","bt":"תרמב","bp":"קושטא","b":"תלמיד ביהמ\"ד לרבנים ע\"ש דאנון. יסד עתון \"איל זודייו\" (היהודי)-תרסח, ציר קושטא בקונגרס הציוני, עבר לבואנוס-איירס והו\"ל עתון \"לה לוז\" (האור)-תרצא. היה במחלוקת עם החכם באשי ר משה הלוי, ר חיים נחום, ר חיים בג'ראנו, ועוד."},{"i":5212,"n":"אנקאווה, יהודה מאלגיר","f":"אפרים מספרד ואלגיר","bt":"קס - בערך","dt":"רס - בערך","b":"למד באלג'יר עם הרשב\"ש. מחכמי ווהראן, אלגיר, מסתגאנם ועוד, עסק במסחר. התכתב עם חברו הרשב\"ש בעניני הלכה, ועם ר יוסף ששפורטש מהוניין ונזכר בתשובותיו. חתנו - ר יעקב בזיז."},{"i":5213,"n":"אנקאווה, יום טוב מקושטא","k":"בעל שביתת יום טוב","b":"תלמיד ר אברהם מיוחס. רב בקושטא-תקל."},{"i":5214,"n":"אנקאווה, יוסף מאלגיר","f":"דוד בן אהרן","k":"בעל שומע יוסף","bt":"תרלא","dt":"תרץ - בערך","b":"מצאצאי ר אפרים אנקאווה. תלמיד ר חיים בלייח בתלמסאן. מו\"צ באלגיר, מקורב לארגון הקהילות - הקונסיסטוואר."},{"i":5215,"n":"אנקאווה, יעקב ממרוקו ואלגיר","f":"עמרם","k":"תרגם דת יהודית","bp":"סאלי-מרוקו","dt":"תרנד - לפני","b":"עבר לאלגיר וכיהן כרב באטנא. סייע בהדפסת \"ויגד לאברהם\" - ליוורנו תרכב, תרגם מלדינו ליהודית ערבית \"דת יהודית\" לר אברהם לארידו."},{"i":5216,"n":"אנקאווה, ישראל מאלגיר","f":"אפרים מספרד ואלגיר","bt":"קס - בערך","dt":"רל - בערך","b":"רב בתלמסאן. שאל את אביו שאלות על \"מורה נבוכים\" ואביו כתב בתשובה קונטרס \"שער כבוד ה'\"."},{"i":5217,"n":"אנקאווה, ישראל מספרד","f":"יוסף","k":"בעל מנורת המאור","bt":"קכ","bp":"טולידו","dt":"קנא","b":"רב בטולידו. נהרג עק\"ה בזמן השמד-קנא (יחד עם ר יהודה בן אשר). חיבר פיוטים."},{"i":5218,"n":"אנקאווה, מיכאל ישכר","f":"רפאל","bt":"תרנה","bp":"סאלי","dt":"תשלב - א אדר","b":"דיין בביה\"ד לערעורים בסאלי על מקום אביו אצל ר יהושע בירדוגו, וסירב להיות אב\"ד אחרי ר יהושע ונתמנה במקומו ר שאול ן דנאן, ואחר שעלה ר שאול לירושלים, נתמנה לאב\"ד על מקומו על כל מרוקו, ולאחר פטירתו בטלה משרה זו."},{"i":5219,"n":"אנקאווה, מסעוד מסאלי","b":"רב ודיין בסאלי וראש ישיבה בזמן אחיינו ר רפאל אנקווא, ונזכר בקרני רא\"ם."},{"i":5220,"n":"אנקאווה, מסעוד מסאלי","f":"מרדכי","bp":"סאלי","dt":"תרל","b":"רב בסאלי-תרי, אוראן-אלגיר, עלה לארץ. חתם עם ר יהודה יאיון מסאלי."},{"i":5221,"n":"אנקאווה, מרדכי","f":"יוסף","b":"תלמיד ר רפאל אלנקאוה במרוקו. רב בטנג'יר, רב בקראקס-ונצואלה."},{"i":5222,"n":"אנקאווה, מרדכי מאלגיר","f":"אברהם","dt":"תרץ - לפני","b":"חתן ר שלמה זוראפא. רב בענאבא(=בון)-אלגיר. הסכים עם רבני העיר על זכות יהודי טבריה בכספי רמבע\"ה."},{"i":5223,"n":"אנקאווה, מרדכי מסאלי","f":"משה מאלגיר","b":"רב בסאלי, נזכר בהקדמת \"קרני ראם\". בניו - ר עמרם, ר אברהם, ר מסעוד."},{"i":5224,"n":"אנקאווה, משה מאזמיר","k":"בעל אוצר נחמד","b":"רב באזמיר-תפ."},{"i":5225,"n":"אנקאווה, משה מאלגיר ומרוקו","bt":"תק - בערך","bp":"אלגיר","dt":"תקע - בערך","b":"ראש משפחת אנקאווה במרוקו. ממשפחה מיוצאי ספרד באלגיר, עבר למרוקו בדרכו לארץ, והתישב בסאלי. בנו - ר מרדכי."},{"i":5226,"n":"אנקאווה, נסים יוסף","dt":"תרכו - כו אלול","dp":"חיפה","b":"תלמיד ר חזקיה מדיני בעל \"שדי חמד\", ונזכר ב\"מכתב לחזקיהו\"."},{"i":5227,"n":"אנקאווה, נעים","b":"נזכר ב\"מכתב לחזקיהו\" לר חזקיה מדיני."},{"i":5228,"n":"אנקאווה, עמרם מגיברלטר","dt":"תרלד - כז סיון","dp":"גיברלטר","b":"מחכמי מרוקו, עבר לכהן כרב בגיברלטר."},{"i":5229,"n":"אנקאווה, רפאל מסאלי-מרוקו","f":"מרדכי מסאלי","k":"בעל קרני ראם","bt":"תרח","bp":"סאלי","dt":"תרצה - ד אב","b":"בן למשפחה מיוחסת מספרד אלג'יר ומרוקו, ומצאצאי ר אפרים בעל הנס עם האריה. חתן ר ישכר אצראף מסאלי וירושלים. דיין בסאלי-תרלה עם ר יצחק אמזלאג ודודו ר מסעוד אנקאווה, וראש ישיבה שם ומתלמידיו - ר אברהם ריווח בעל \"ויען אברהם\", ר אפרים אנקאווה, ור מיכאל אנקאווה שכיהן על מקומו אחריו. רב ראשי ברבאט-תרעח ומנהיג יהדות מרוקו בהכרת השלטון הצרפתי. חיבר גם \"תועפות ראם\", \"פעמוני זהב\", ועוד. בהלוויתו השתתפו רבבות אנשים ונציגים מרחבי העולם."},{"i":5230,"n":"אנקאווה, שלמה מאלגיר","bt":"שי","dt":"שפ - בערך","b":"מצאצאי ר אפרים אנקאווה. רב בתלמסאן-אלג'יר, שאלה ממנו לר שלמה בן צמח ב\"חוט המשולש\"."},{"i":5231,"n":"אנקונה, אברהם מאקווי","b":"תלמיד ביהמ\"ד לרבנים בפדובה. רב באקווי-איטליה-תרם."},{"i":5232,"n":"אנקונה, חביב מחלב","b":"מחכמי ורבני חלב"},{"i":5233,"n":"אנקונה, יוסף דוד אלחנן מאיטליה","f":"שלמה אברהם חי","b":"רב בלוגו, סינגאליה-איטליה שנות ה-תר'. נסמך מאת: ר יקותיאל חיים הכהן מסביוניטה, ר אליהו שלמה נסים מסביוניטה, ר יעקב ישראל קרמי מריגיו, ר דוד יעקב מאריני מפיטיליאנו, ר יצחק אליהו מנחם אסקולי מפיררה."},{"i":5234,"n":"אנקונה, יצחק מחלב","b":"מחכמי אר\"ץ, מתורתו ב\"המאסף\" לר בן ציון קואינקה."},{"i":5235,"n":"אנקונה, כלפון מחלב","bp":"חלב","dt":"תרסב - תשרי","dp":"ישראל","b":"לימד תלמוד בת\"ת בחלב,עלה לא\"י"},{"i":5236,"n":"אנשבורג, שמעון הלוי מפפד\"מ","f":"יצחק","k":"בעל דבק טוב","dt":"שס - לפני","b":"תלמיד ר חיים מפרידברג. איש חסד, רב בפפד\"מ, עלה לירושלים-שן דרך ונציה ושם הדפיס את ספרו."},{"i":5237,"n":"אנשיל הכהן מפפד\"מ","b":"מחכמי פפד\"מ-שכה, תמך אך לא חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ - בגלל שיש לו שייכות בדבר."},{"i":5238,"n":"אנשיל הלוי","b":"מגדולי חכמי אשכנז,רב הכולל על כל מדינות אשכנז-קצ\"ה"},{"i":5239,"n":"אנשיל לוי ציון מונציה","b":"רב באיטליה (בולוניה) בזמן ר חייא מאיר בן דוד ור בינידינו ור דוד פציגיטון - לפני גירוש היהודים מבולוניא. חיבור ממנו בענין אחד מדיני ממונות - נדפס בונציה."},{"i":5240,"n":"אנשיל מאוישפורג","b":"תלמיד המהרי\"ל שהזכירו בספרו. שלח סדר גטין לר\"י צרפתי כפי שקיבל מרבו המהרי\"ל."},{"i":5241,"n":"אנשיל ממרפורק","b":"תלמיד מהר\"ש מוינה, מהר\"מ הלוי מוינה. רב במרפורק-אוסטריה-קן. מתורתו במהרי\"ל ועוד מחכמי דורו."},{"i":5242,"n":"אנשיל מסערעד","b":"רבה הראשון של סערעד-תקב, ור דוד הלוי מהעלישוי על מקומו אחריו."},{"i":5243,"n":"אנשיל מרגנשבורג","b":"מגדולי חכמי דורו,מרביץ תורה ברגנשבורג-רכ\"ה"},{"i":5244,"n":"אנשיל סגל מקולוניא","b":"מגדולי אשכנז,רב באנדרנך"},{"i":5245,"n":"אנשיל סגל מרגנשבורג","b":"רב וראש ישיבה ברגנשבורג, וורמייזא-קצה (ונקרא בהסכמת המלכות - ר אנשל קעלן רב המדינה בכל ריינוס וכו'), וחזר לרגנשבורג מתלמידיו: ר יונה בעל איסור והיתר הארוך. נזכר בתשובות ר\"י ברונא שפגשו ברגנשבורג - והיה מחלוקת ביניהם שר אנשל טען כנגדו שהוא מקפח פרנסתו וכו'' בשו\"ת מהר\"מ מינץ"},{"i":5246,"n":"אנשיל, אברהם מניקלשבורג","f":"פרץ","dt":"תז - כא סיון","b":"רב בניקלסבורג"},{"i":5247,"n":"אנשפכר, אברהם מארה\"ב","f":"שמואל","bp":"ניו יורק","b":"תלמיד ביהמ\"ד לרבנים בסינסינטי. רב בינגהמטון-ניו יורק, סקרנטון-פנסילבניה."},{"i":5248,"n":"אסא, אברהם מקושטא","f":"יצחק","k":"בעל צרכי צבור","bt":"תע - בערך","bp":"קושטא","dt":"תקכה - בערך","b":"מחכמי קושטא, תרגם ספרים ללדינו. חיבר \"צרכי צבור\"-תצג, ועוד."},{"i":5249,"n":"אסא, יעקב מקיזאלניק","f":"רפאל אהרן","b":"רב בקיזאלניק-תקפה."},{"i":5250,"n":"אסא, יצחק מזאגרה","b":"דיין בזאגרה אצל ר גבריאל משה קריספין, יחד עם ר אברהם חובש. ישב בדין-תקפה עם ר אליקים בן יעקב אברהם גירון בהיותו בזאגרה."},{"i":5251,"n":"אסא, רפאל יעקב מזאגרה וירושלים","dp":"ירושלים","b":"בנו או קרובו של ר אברהם אסא. מחכמי זאגרה-בולגריה. עלה לירושלים ולימד תורה-תקם, תשובה ממנו בספר \"מירא דכיא\" לר מרדכי שמחון. מתלמידיו - ר חיים שמואל."},{"i":5252,"n":"אסאד ן, ישועה הקראי","f":"יהודה או אלפרג פורקן","k":"בעל משיבת נפש","b":"מחכמי הקראים הקדומים-שנות הד-תת. חיבר גם \"בראשית רבה\"."},{"i":5253,"n":"אסאד, אהרן שמואל מסערדאוהל","f":"יהודה מסערד-אוהל","r":"אב\"ד ור\"מ סעהרדעלי, ומקודם רב בקאטה","bt":"תקץ","bp":"סערדאוהל","dt":"תרסה-ח - ו ניסן","dp":"סערדאוהל","b":"תלמיד הכת\"ס, ור עזריאל הילדסהימר מברלין. חתן ר יו\"ט ליפמן גלזר מניקלשבורג ועבר לשם. רב בקאטה-תרך על מקום גיסו ר יונה ריכהרט. רב וראש ישיבה בסערדאוהל-תרכו על מקום אביו. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. חתנו - ר שמואל חיים בן משה נתן יונגרייז.","bk":[["חידושי ראשבי\"ד - אש דת",""],["שאילת שמואל - שו\"ת",""],["שאילת שמואל - שו\"ת , חידושי ראשבי\"ד - אש דת",""]]},{"i":5254,"n":"אסאד, יהודה מסערדאוהל","bt":"תקנד-ט","bp":"אסאד","dt":"תרכו - כו סיון","b":"מגדולי דורו. תלמיד הרב פאלק מסודיטץ, ישיבת ר אהרן ביכלר וסרדאוהל, ואצל ר מרדכי בנט בניקלשבורג. מרביץ תורה לאלפים, דומ\"צ בסרעדאוהל, רב ברוגנדורף, רטה, סמניץ, סערדאוהל וראש ישיבה ובנו ר אהרן שמואל על מקומו אחריו. יצא בראש משלחת רבנים אל הקיסר פרנץ יוזף למנוע הקמת סמינר לרבנים, ובירך את הקיסר לבקשתו באריכות ימים. (היה בעל חוש הומור ופעם כשעבר ליד ביכנ\"ס של ניאולוגים אמר \"אין זו אלא תיבת נח שעליה נאמר מבית ומחוץ בכופר\")."},{"i":5255,"n":"אסאד, יצחק משה ממאקווא","f":"יהודה מסערדאוהל","bt":"תרג","dt":"תרץ - ו אב","dp":"מאקווא","b":"תלמיד הכת\"ס, ור נתן בנימין הלוי ליבר מפרשבורג. מחכמי מאקווא, עבר לאמריקה וחזר למאקווא."},{"i":5256,"n":"אסאד, מאיר מסערדאוהל","f":"אהרן שמואל אסאד","dt":"תרסח","b":"דומ\"צ בסערדאהעלי"},{"i":5257,"n":"אסאד, מרדכי מסערדאוהל","f":"יהודה מסעמניץ","bt":"תקצד","bp":"סעמניץ","dt":"תרכג - כג ניסן","dp":"סערדאוהל","b":"תלמיד הכת\"ס, ור עזריאל הילדסהימר. מחכמי לעווא, סערדאוהל."},{"i":5258,"n":"אסאד, שמואל וולף מסעמלין","f":"מרדכי","b":"תלמיד החת\"ס. רב בנייזאץ-תקפט, סעמלין-תקצו. תשובה אליו ב\"חתם סופר\"."},{"i":5259,"n":"אסאייסקי, שלמה","b":"חתן ר אריה ליב ולפרט מגרינקישק."},{"i":5260,"n":"אסבאג - משפחה","b":"משפחה במרוקו ואלג'יר ויתכן שמקור השם - צובע צמר, ע\"ש אבי המשפחה שזה היה מקצועו."},{"i":5261,"n":"אסבאג, אלעזר ממרוקו","b":"רב במרוקו (מרקאש?), חתם-תקז עם ר אברהם קורקוס."},{"i":5262,"n":"אסבאג, אלעזר ממרוקו","b":"רב במרוקו, חתם עם ר אברהם קורקוס על העתקת פסק דין של רבני מראקש ר יוסף בן סעדון וחבריו."},{"i":5263,"n":"אסבאג, בצלאל חי","f":"שלמה","bt":"תרכט","bp":"טבריה","dt":"תרעו - יט כסלו","dp":"טבריה","b":"סופר סת\"ם"},{"i":5264,"n":"אסבאג, ברוך","f":"יעקב","b":"תקי\"ז"},{"i":5265,"n":"אסבאג, ברוך","k":"בעל מנחת משה","dt":"תשו - ג אד\"ב","dp":"סאפי","b":"רב ראשי אספ\"י, מחכמי מרוקו, מקובל, דיין, חיבר \"מנחת משה\""},{"i":5266,"n":"אסבאג, ברוך ממכנאס","b":"דיין במכנאס, חתם-תריט עם ר רפאל יוסף חרוש, ר רפאל מסעוד ן מוחא, ועוד, חתם-תרמא על פסד דין."},{"i":5267,"n":"אסבאג, דוד","k":"בעל משגב לעתות","b":"רב במרוקו, ערך ספר תיקונים \"משגב לעתות\""},{"i":5268,"n":"אסבאג, יהודה הקדוש מאליג-מרוקו","b":"מחכמי אליג-מרוקו. נשרף-תרי עק\"ה."},{"i":5269,"n":"אסבאג, יצחק - ב","b":"חתם בשטר נדוניא-תקסב."},{"i":5270,"n":"אסבאג, יצחק ממכנאס - א","b":"מחכמי מכנאס, חתם על פס\"ד-תעז עם ר יעקב ן מלכא."},{"i":5271,"n":"אסבאג, מרדכי מפאס","b":"סופר מחכמי פאס - שנות ה-ת'."},{"i":5272,"n":"אסבאג, משה ממראקש","b":"מו\"ץ במראקש(=מרקאש) בזמן ר דוד צאבח - שנות ה-תר'. היה מחזיק ביד לומדי תורה."},{"i":5273,"n":"אסבאג, משה ממרוקו","b":"רב באזדידא-מרוקו. בקשרי מכתבים עם ר יהודה ן מוייאל ממוגאדור, ונזכר ב\"שבט יהודה\"."},{"i":5274,"n":"אסבאג, סלאם מאליג-מרוקו","f":"יצחק","b":"דיין באליג-מרוקו-תש, חתם עם ר אליהו רבוח."},{"i":5275,"n":"אסבאג, עזריה מכנאס-מרוקו","dt":"תרו - כו אלול","b":"חתם-תקץ על תקנה מבית דינו של \"אביר יעקב\"."},{"i":5276,"n":"אסבאג, שלמה ממוגאדור-מרוקו","b":"רב במוגדור-מרוקו. חתם-תרמא עם ר יהודה מויאל על פסק דין."},{"i":5277,"n":"אסבאג, שלמה ממכנאס","b":"גביר במכנאס-שנות ה-תק'."},{"i":5278,"n":"אסבאג, שלמה ממראקש","f":"שלום (שלם)","b":"מו\"ץ במראקש-שנות ה-תק', חתם על הסכמה ל\"תהלה לדוד\" לר דוד חסין, נזכר ב\"ליצחק ריח\"."},{"i":5279,"n":"אסבאג, שלמה ממרוקו וטבריה","b":"רב במרוקו, עלה לטבריה והיה רב בטבריה. אביו של ר בצלאל, נכדו ר עקיבא."},{"i":5280,"n":"אסבאג, שלמה מתלמסאן-אלגיר","b":"רב וסופר בתלמסאן-תק וחתם אז על שטרות."},{"i":5281,"n":"אסביסקי, זלמן שלמה","bt":"תרמה","dt":"תשא - כח סיון","b":"רב בקופיאנסק,רבה האחרון של וויליאמפול-סלובודקה"},{"i":5282,"n":"אסביסקי, יהודה","dt":"תשג","b":"רב בפאיורע"},{"i":5283,"n":"אסבל, דוד יעקב מסמיאטיץ","b":"נכד ר לוי יצחק מברדיטשוב. חתן ר חיים בער גרינגרוס מקרמנצוג. רב בסמיאטיץ."},{"i":5284,"n":"אסובסקי, יהודה","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":5285,"n":"אסודרי, אהרן","f":"ישועה","k":"בעל חשבתי דרכי","bt":"תרלט","bp":"מרוקו","dt":"תשז - כה אלול","b":"מרביץ תורה, דרשן, משורר, חיבר \"חשבתי דרכי\""},{"i":5286,"n":"אסודרי, דוד","f":"אברהם","bp":"מכנאס (מרוקו)","dt":"תרסד - כז טבת","b":"עלה לטבריה בשנת תרה, ונמנה עם חכמי טבריה, בשנת תריז חתם על תעודות בדבר ישיבת בית יעקב, יצא בשליחות לעירק הודו ומרוקו, ולאחר מכן לערי בוכארה. בשנת תרן הסכים בבומביי על הדפסת ספר תהלים בידי ר יחזקאל שם טוב."},{"i":5287,"n":"אסולין, אברהם ממראקש","b":"רב ומו\"ץ במראקש-תקפו, חתם על פס\"ד ב\"שופריה דיעקב\" עם ר דוד צבאח, ר מימון פינטו, ור אליעזר חזאן."},{"i":5288,"n":"אסולין, אהרן","dp":"פרכלה(מרוקו)","b":"מצדיקי מרוקו"},{"i":5289,"n":"אסולין, אלעזר מפאס","b":"סופר שטרות בפאס, חתם על פס\"ד-תקח עם ר רפאל עובד ן צור."},{"i":5290,"n":"אסולין, בנימין מאלגיר","f":"יעקב","bt":"תרעח","bp":"קצמטינא","dt":"תשנג","dp":"ירושלים","b":"רב בליון-צרפת, עלה לארץ וכיהן כרב במושב בית עוזיאל. קרובו של ר לוי אסולין."},{"i":5291,"n":"אסולין, יהודה ממרוקו","b":"רב בפאס-מרוקו. חתם-תרמא."},{"i":5292,"n":"אסולין, יוסף ממרוקו","f":"דוד","b":"רב במקנאס, חתם-תקסב עם ר מרדכי אלבאז."},{"i":5293,"n":"אסולין, יחיא מסאלי-מרוקו","b":"מחכמי סאלי, רב באזדידא-מרוקו. אחיינו-בן אחותו ר לוי אסולין בעל \"זבחי אלקים\" ומזכירו בספרו."},{"i":5294,"n":"אסולין, לוי ממראקש ואלגיר","f":"יוסף","k":"בעל בני לוי","bt":"תקפח","bp":"מראקש","dt":"תרסג - טז אדר","b":"אחיינו של ר יחיא אסולין מג'דידא. למד אצל חכמי סאלי. שו\"ב, מו\"ץ, דיין ודרשן בקצמטינא-אלגיר. חיבר גם \"זבחי אלקים\"."},{"i":5295,"n":"אסולין, מימון ממראקש","b":"רב במראקש, חתם בעניני טריפות-תקמח."},{"i":5296,"n":"אסולין, מכלוף מפאס","b":"ממשפחה ממגורשי ספרד. סופר בי\"ד בפאס יחד עם ר שמואל בן סעדיה ן דאנון. חתם על תקנות המגורשים-שה, ועל תקנות והסכמות במשך השנים עד שסד."},{"i":5297,"n":"אסולין, מסעוד","b":"מחכמי צפת, בשנת תקנא חתם על כתב שליחות ר חיים מודעי."},{"i":5298,"n":"אסולין, משה מפאס","f":"מרדכי","b":"מחכמי פאס-של, בזמן ר סעדיה בן שמואל ן דנאן. חיבר ספר דרשות."},{"i":5299,"n":"אסולין, משה מפאס","b":"סופר בי\"ד מחכמי פאס-תפח."},{"i":5300,"n":"אסולין, שמואל מפאס","b":"מחכמי פאס בזמן היעב\"ץ. בנו - ר משה."},{"i":5301,"n":"אסולין, שמעון ממרוקו","b":"רב בפאס-תרם."},{"i":5302,"n":"אסוקדי, דוד","k":"בעל ויחי יעקב","dt":"תרסה - ח שבט","b":"אב\"ד דמשק, בערוב ימיו עלה לירושלים, חיבר \"ויחי יעקב\""},{"i":5303,"n":"אסט, יעקב מסטרי","f":"ברוך צבי הלוי","k":"בעל שושני יעקב","bt":"תרמח","bp":"סטרי","dt":"תשלו","dp":"ירושלים","b":"עלה לירושלים-תרע, ועבר לארה\"ב-תרפג. חזר לירושלים-תשטו. חיבר \"שושני יעקב\" ירושלים תשיט."},{"i":5304,"n":"אסטלינן, שמואל מלנצהוט","b":"רב בלנצהוט-תקנה."},{"i":5305,"n":"אסטנוביץ, אלעזר הלוי מנוביטרג","f":"דב","k":"בעל זכרון עולם","bt":"תרם","bp":"לובלין","dt":"תש","b":"ר\"מ בישיבה בסנוק, רב בנוביטרג, רב בלובלין. חיבר \"זכרון עולם\" לובלין תרצד."},{"i":5306,"n":"אסטפלד, אלעזר מסקאהל","b":"מחכמי סקול. תשובה אליו ב\"אור המאיר\"."},{"i":5307,"n":"אסטרומזה, אברהם משלוניקי","b":"מורה בביה\"ס ת\"ת בשלוניקי-לפני השואה."},{"i":5308,"n":"אסטרומזה, בנבנישתי מרדכי משלונ","dt":"תרמט","dp":"שלוניקי","b":"למד רפואה בקושטא, רופא צבאי בשלוניקי."},{"i":5309,"n":"אסטרומזה, יעקב משומלא","b":"רב בשימלא(=שומלא)-בולגריה-תרלג."},{"i":5310,"n":"אסטרומזה, ישראל משלוניקי","b":"ממיסדי ה\"מזרחי\" בשלוניקי-תרעט."},{"i":5311,"n":"אסטרייך, יחיאל טוביה מטורבין","b":"פרסם מאמרים ב\"כרם בית שמואל\" - פיעטרקוב תרצב - כתב עת תלמידי ישיבת אלכסנדר."},{"i":5312,"n":"אסטרייך, יעקב הירש מאויבן","dt":"תקמז - יז טבת","dp":"בודפשט","b":"דיין באויבן בזמן ר משה מינץ. בנו - ר מאיר יהודה מבודפשט."},{"i":5313,"n":"אסטרייך, ישכר בר מניקלשבורג","dt":"תקט","b":"רב בניקולסבורג-תס\"ט"},{"i":5314,"n":"אסטרייך, שמחה בונם מקשנוב","dt":"תש..","b":"מחסידי אלכסנדר, ר\"מ בישיבת \"בית ישראל\" באלכסנדר, בישיבת \"כתר תורה\" בקשנוב. נספה בשואה. פרסם מאמרים ב\"בית ישראל\" - לודז תרץ, \"כרמנו\" - אלכסנדר-לודז תרצג, \"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":5315,"n":"אסטריכר, אברהם מביטשקע","f":"אלעזר","dt":"תרלט -כ-כא תשרי","b":"רב בביטשקע"},{"i":5316,"n":"אסטריכר, אהרן","b":"נכד ר יונתן בנימין מטשאנגער."},{"i":5317,"n":"אסטריכר, אליעזר מאויבן","f":"משה יהודה אסטריכר","b":"דומ\"צ באויבן,רב בדומאן"},{"i":5318,"n":"אסטריכר, יהונתן בנימין מטשנגר","f":"משה אריה אסטריכר","dt":"תקצד - כג אדר","b":"איש מופת, רב בטשענגער. נכדו - ר אהרן."},{"i":5319,"n":"אסטריכר, יוסף שלמה זלמן","f":"אליעזר בן משה אריה","dt":"תרי - אלול","dp":"מונקטש","b":"תלמיד החת\"ס. רב במונקטש-תקעא. חתנו - ר דוד זלצר ממונקטש בעל \"דברי דוד\"."},{"i":5320,"n":"אסטריכר, יעקב מפרשבורג","b":"ראש הרופאים בביה\"ח היהודי בפרשבורג."},{"i":5321,"n":"אסטריכר, יעקב צבי מדאמאן","b":"רב בדאמאן"},{"i":5322,"n":"אסטריכר, מאיר יהודה - הנכד","f":"משה אריה מקראלי","dt":"תרט - ב טבת","dp":"בודפשט","b":"גביר וראש הקהלה באונסדורף-תר. (באוצר הרבנים יש בלבול בינו לבין זקנו מקארולי). ראש הקהלה באונסדורף-תר?, דומ\"צ באויבן-תקצב?, רב מחוז סאטמר ורבה הראשון של קרולה(=קראלי)-תפד ובנו ר משה אריה על מקומו אחריו. נזכר אצל ר עקיבא איגר ב\"משנת דר' עקיבא\", ועוד. התנגד לחסידות ונאמר עליו כי נמנע מלפגוש את ר לוי יצחק מברדיטשוב בהגיעו לקרולה. (יש בלבול באוצר הרבנים בינו לבין נכדו?). חתם-תקפא עם ר משה שפיץ, ור משה אבלס. הסכים על \"ארץ חיים\" - פרג תקנב, \"דעת זקנים\" - אופן תקצג."},{"i":5323,"n":"אסטריכר, מאיר יהודה מקרולי-הזק","dt":"תקלד-ה -יח חשון","b":"רב מחוז סאטמר ורבה הראשון של קרולי(=קראלי)-תפד ובנו ר משה אריה על מקומו אחריו. נזכר אצל ר עקיבא איגר ב\"משנת דר' עקיבא\". התנגד לחסידות ונאמר עליו כי נמנע מלפגוש את ר לוי יצחק מברדיטשוב בהגיעו לקרולה."},{"i":5324,"n":"אסטריכר, מאיר מאונגוואר","dt":"תשד","b":"דומ\"צ באונגוואר"},{"i":5325,"n":"אסטריכר, מרדכי דוד מטשימפא","b":"רב בטשימפא, זיבנבירגן. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":5326,"n":"אסטריכר, משה אריה מקרולה","f":"מאיר יהודה מקרולה","dt":"תקף - י אדר","b":"רב בפזינג וראש ישיבה, קרולה על מקום אביו-תקלד כ-45 שנה ור יצחק פרנקל על מקומו אחריו, ורב מחוז סאטמר. חתן ר נפתלי הירש ליפחוביץ מגרוסורדין. נספד ע\"י ר יחזקאל פאנט ב\"מראה יחזקאל\". חיבר הספד בגרמנית על הגראף קאראלי - גרוסורדין תקנג. בניו: ר יונתן בנימין מטשענגר, ר מאיר יהודה מאונסדורף, חתנו - ר משה שפיץ מטשענגר."},{"i":5327,"n":"אסטריכר, משה דוד מטשימפא","f":"יוסף זלמן","k":"בעל תפארת אדם","r":"אב\"ד טשימפא","bt":"תרמג","bp":"ראקעשין - ליד מונקטש","dt":"תשיד -ח-כה אייר","dp":"ניו יורק - בני ברק","b":"תלמיד ר צבי הירש שפירא-מונקטש, ר יהודה גרינפלד, ור יהודה גרינוולד-סטמר. עבר למיידאן וישב אצל חותנו. רב בצ'ימפא-מחוז הוניאד-תרסט, זיבנבירגן, אראד - אחרי מלחמת העולם ה-I. ניצל מהשואה ואחריה דיין בביה\"ד להתרת עגונות. היגר לניו יורק, בנו ר ישראל אליהו שטינמץ מנ\"י. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד.","bk":[["תפארת אדם - שו\"ת",""]]},{"i":5328,"n":"אסטריכר, משה יהודה ליב מאויבן","b":"מו\"צ באויבן. בנו ר אליעזר."},{"i":5329,"n":"אסטריכר, צבי הירש מדרוהוביטש","bp":"דרוהוביטש","dt":"תרב","b":"מראשי חסידי זידיטשוב במונקטש. דיין אצל הבני\"ש. חתנו - ר שמואל צבי ממונקטש."},{"i":5330,"n":"אסטרין, ישראל אהרן","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":5331,"n":"אסטרליץ, נתן הלוי מניקלשבורג","dt":"תפט","b":"דיין בניקלסברג"},{"i":5332,"n":"אסיאו, פיריד משלוניקי","b":"מהפכן יהודי בתורכיה-תרס ונאסר לשנים בקושטא על פעילותו."},{"i":5333,"n":"אסיאן, אברהם","b":"מו\"צ בצידון-תקי\"ח"},{"i":5334,"n":"אסייג, אליהו מקושטא","b":"מחכמי קושטא-שנות ה-ש'-ת'. בנו - ר יוסף משלוניקי."},{"i":5335,"n":"אסייג, יוסף ממרוקו - א","b":"מחכמי מרוקו-שנות ה-תק', נפטר צעיר. נספד בידי ר אליהו הצרפתי ב\"נער בוכה\"."},{"i":5336,"n":"אסייג, יוסף מפאס - ב","b":"שו\"ב בפאס-שנות ה-תק'."},{"i":5337,"n":"אסייג, יוסף משלוניקי","f":"אליהו מקושטא","b":"דיין בשלוניקי-שף, עבור לקושטא."},{"i":5338,"n":"אסייג, נתן מאלגיר - א","bt":"תע - בערך","dt":"תקמ - בערך","b":"רב בתלמסאן. פייטן ומפיוטיו בכתבי חכמי דורו."},{"i":5339,"n":"אסייג, נתן מאלגיר - ב","bt":"תקץ - בערך","dt":"תרע - בערך","b":"מצאצאי ר נתן אסייג הזקן. תלמיד ר אברהם אנקאווא. רב בתלמסאן."},{"i":5340,"n":"אסייג, סעדיה ממרוקו","f":"יוסף","dt":"תרלג","b":"מחכמי מרוקו."},{"i":5341,"n":"אסייג, סעדיה מפאס","f":"ישראל","b":"מחכמי פאס-תקע."},{"i":5342,"n":"אסייג, שמואל מפאס","b":"מחכמי פאס-תקע. אחיו של ר סעדיה השני."},{"i":5343,"n":"אסכורי, משה ממרוקו","f":"לוי","b":"מחכמי מרוקו-מהשנים תר-תש. חיבר תוכחה בשם 'אויה לי אויה לגופי'."},{"i":5344,"n":"אסכורי, שלם ממרוקו","f":"אברהם","b":"מחכמי כפר בג'עד-מרוקו, שאלה ממנו-תקטו לחכמי מכנאס."},{"i":5345,"n":"אסלקי, גבריאל זאב ממגילניצא","f":"יצחק","k":"בעל הר המוריה","bt":"תרכט","b":"נכד ר אברהם יהושע השל משענא ותלמידו, גם נכד ר זאב יצחק יוזפוף. רב בקרעשוב-תרן, גרבוביץ-תרסט. פרסם מאמרים ב\"הכרם\" - וארשא תרצא, \"קובץ דרושים\" - פיעטרקוב תרפג. חיבר גם \"גינת אגוז\", ועוד."},{"i":5346,"n":"אסמא","b":"אישה חכמה וחיברה פיוטים, ושירים ובהם לעג לדת מוחמד. נהרגה עק\"ה ע\"י הערבים."},{"i":5347,"n":"אסמאג'ה, יצחק","f":"חיים","bt":"תקעד","bp":"טבריה","dt":"תרמד","dp":"טבריה","b":"מחכמי טבריה, בשנת תריד בשליחות בעירק וכורדיסטן וכיהן שם כרב."},{"i":5348,"n":"אסמה מערב","f":"מרואן","b":"חברה שירי התולים כנגד מחמד נביא הערבים, ונרצחה ע\"י אחד מאנשיו."},{"i":5349,"n":"אסמן ברוך בן יעקב יוסף","bt":"1836","dt":"ה'תרע 1910","bk":[["חד וחלק",""],["חד וחלק חלק ב",""]]},{"i":5350,"n":"אסמן, ברוך מקיוב","f":"יעקב יוסף מאיוונקוב","k":"בעל חד וחלק","bt":"תקצו","dt":"תרע - ז אייר","b":"גביר ותלמיד חכם מקיוב שהגיע לגליציה. חיבר \"חד וחלק\" וילנא תרמב."},{"i":5351,"n":"אסמן, יעקב יוסף מאיבנקוב","f":"הרש נארינסקער","b":"חתן ר משה רוטמן מאיבנקוב(=איוואנקאוו)-פלך קיוב, רב באיוונקוב-תרך על מקום חותנו. בניו: ר ברוך בעל \"חד וחלק\", ר משה רוטמן מהורודישץ."},{"i":5352,"n":"אסמעאל ן, אברהם מספרד","f":"משה","k":"תלמיד הרשב\"א","b":"תלמיד הרשב\"א. מחכמי ספרד-צד. רבו של רבינו ירוחם המביאו בספרו. חיבר חדושים לש\"ס, וסדר עבודת יוה\"כ."},{"i":5353,"n":"אסמעיל, חיים","b":"מגדולי חכמי מאלאגה-ק\"פ"},{"i":5354,"n":"אסף אלקוטי","k":"חבס ן אל דור","b":"פייטן קדום. חיבר שירים בערבית. נזכר אצל ר\"ש ן גבירול, ואבן עזרא - שכותב שתרגם ספר תהלים לערבית."},{"i":5355,"n":"אסף הרופא הירחוני","f":"ברכיה","b":"רופא וחכם קדום. חיבר ספר רפואה ובו נאמר מאת אסף בבן ברכיה הירחוני ויוחנן בן זבדא."},{"i":5356,"n":"אסף ראש הסדר","b":"מחכמי בבל-ד'תשפ. דיין אצל רב שרירא גאון ובנו רב האי גאון. נזכר בתעודה ממצרים שבכל עת שבא ר אלחנן גאון מצרים לבגדד היה נכנס לבקרו ר אסף וכו'."},{"i":5357,"n":"אספג', נסים ממרוקו","b":"מחכמי מרוקו-שנות ה-ת'."},{"i":5358,"n":"אספניא, אברהם משלוניקי","bt":"שא","dt":"שצא","b":"רב בשלוניקי"},{"i":5359,"n":"אספסקי, שלמה זלמן","dt":"תשד","b":"מרבני סלובקיה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":5360,"n":"אסקולי, דבורה","b":"תרגמה לאיטלקית תוכחת רבינו בחיי - שאומרים הספרדים ביום כפור, ואת חיבורי ר משה ריאיטי - ונציה."},{"i":5361,"n":"אסקולי, דוד די","b":"חיבר מאמר להוכיח צדקת עם ישראל... - בכת\"י (מובא אצל די רוסי)."},{"i":5362,"n":"אסקולי, יצחק אליהו מנחם מפיררה","k":"בעל ראשית דעת","b":"רב בפיררה-תקצח, חתם על שטר כתובה עם ר שמואל יצחק פינצי, סמך את ר יוסף דוד אלחנן אנקונה מלוגו וסינגאליה לרב."},{"i":5363,"n":"אסקורה, יהודה מספרד","b":"מחכמי ספרד בדור הריב\"ש,חיבר ספר שו\"ת"},{"i":5364,"n":"אסקורי, רפאל משה ממרוקו","f":"יהודה","b":"מחכמי פאס בשנות ה-תק'. חיבר פירושים לש\"ס, והגהות על משניות ורש\"י בכת\"י. בנו - ר אליהו."},{"i":5365,"n":"אסקירא, חננאל","f":"אברהם","b":"מקובל,תלמיד ר' שם טוב אבן גאון,למד אצל הרשב\"א ועלה עם ר' חננאל לטבריה"},{"i":5366,"n":"אסקירא, יהודה","b":"מגדולי חכמי א\"י-ש\"כ"},{"i":5367,"n":"אסקירא, יצחק ממכנאס","dt":"תקנט - יט סיון","b":"סופר בי\"ד מחכמי מכנאס, חתם עם ר משה ן שלוש. תלמידו - ר יהודה בן מאיר טולידנו מזכירו ב\"אמרי בינה\"."},{"i":5368,"n":"אסקירא, שלמה אברהם ממראקש","b":"רב במראקש-תרטו, וחתם אז בענין שחיטה."},{"i":5369,"n":"אסתורק, אברהם מסופיה","dt":"תרלח - י תשרי","dp":"סופיה","b":"מראשי הקהלה בסופיה. בנו - עזרא."},{"i":5370,"n":"אסתר אשת הרופא משה פישל","b":"מקורבת למלכות בתקופת זיגמונד הראשון מלך פולין."},{"i":5371,"n":"אסתרוק, אליהו אריסטיד מצרפת","k":"בעל עוללות אליהו","bt":"תקצב","bp":"בארדוי(=בורדו)-צרפת","b":"תלמיד ישיבת מיץ. דיין בפאריס-תרטז אצל ר צדוק הכהן, רב הכולל בבלגיה-תרכו, רב הכולל בבייאן-צרפת-תרלט. חיבר ספרים בצרפתית ובהם: \"עוללות אליהו\", \"תולדות ישראל\", ועוד."},{"i":5372,"n":"אסתרוק, עזרא מסופיה","f":"אברהם","bt":"תרלא","bp":"סופיה","b":"עלה לירושלים-תרמב. פעיל צבור בירושלים."},{"i":5373,"n":"אסתרוק, שבתי השמעוני משלוניקי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":5374,"n":"אסתרוק, שלמה","b":"רב-שנת ר\"מ"},{"i":5375,"n":"אפאטוב, יהודה מוילנא","f":"צבי הירש","bp":"אראן","dt":"תרכח - י תמוז","dp":"וילנא","b":"אחיינו-אחי אביו של ר מרדכי מראדין בעל \"פתח השער\". בזיוו\"ש חתן ר משה הכהן ציפקעס, בזיוו\"ש חתן הגביר ר בנימין בן יצחק קצנלנבוגן. גביר מחכמי וילנא. עזר הרבה בזמן מגיפת הכולירה-תרח. בנה בית כנסת מהודר והחזיק בו ת\"ח. ותרם הרבה לעניים. בניו: ר צבי הירש-חתן ר טוביה גינצבורג ממזריטש, ר דניאל-חתן ר יוסף עטינגר, חתניו: ר יעקל בן אברהם פרנס, הפרופ' מרדכי אנטאקלסקי, דוקטור נאדווארגי סאוויעטניק זיגמונד וילקוביסק מויטבסק."},{"i":5376,"n":"אפאצקער, מיכאל","b":"מגדולי תלמידי בעל התניא."},{"i":5377,"n":"אפומאדו, אברהם משלוניקי וצפת","b":"רב בשלוניקי-שנות ה-ש', צפת."},{"i":5378,"n":"אפומאדו, יצחק מיוזיל-היסר","b":"נכד-אבי אמו ה\"חכם צבי\". רב בלעשנוב, מראשי ועד ארבע ארצות."},{"i":5379,"n":"אפומאדו, יצחק מצפת","bp":"מצרים","b":"מחכמי מצרים בשנת ש', מתלמידי הרדב\"ז וחברו של האר\"י, עלה לצפת. בספר \"מדרש אליהו\" מסופר שהרדב\"ז שלחו לשלוניקי לישיבת מהרשד\"ם להראות את גדולתם בתורה של חכמי צפת אחר שנודע לו כי בשלוניקי מזלזלים בגדלותם של חכמי צפת."},{"i":5380,"n":"אפומאדו, שמואל מקושטא","dt":"תקמד - יג אלול","b":"רב בקושטא, וממונה על איסור והיתר-תקלב."},{"i":5381,"n":"אפונדופולו, כלב אבא מאדרינופול","f":"אליהו","k":"בעל עשרה מאמרות","bt":"רכז","dt":"רע","dp":"בלגרד","b":"מחכמי הקראים באדרינופול, קושטא, בלגרד. תלמיד ר מרדכי כומיטיאני הרבני, ותלמיד גיסו - ר אליהו בשייצי הקראי בעל \"אדרת אליהו\", והשלים את ספרו אחר פטירתו של ר אליהו. בניו: שלמה ידידיה, משה, מנחם. אחיו: ר שמואל הרמתי, ר יהודה בלי."},{"i":5382,"n":"אפוסאדו, יהודה מטריפולי-לבנון","b":"רופא מחכמי טריפולי-לבנון(=סינים)-שנות ה-ש', חיבר שירים ונזכר אצל ר ישראל נג'ארה ששיבח את שיריו."},{"i":5383,"n":"אפורמאן, חיים יהודה מלבוב","dt":"תרכט - יח ניסן","dp":"לבוב","b":"מחכמי לבוב, יסד חבורה בשם \"אנשי מעמד\"."},{"i":5384,"n":"אפותיקר, דוד מניו יורק","bt":"1855","bp":"פוניבז","dt":"1911","dp":"ניו יורק","b":"תלמיד ישיבת וילקומיר. פנה להשכלה והצטרף למחתרת סוציליסטית. היגר לארה\"ב-1888 וניסה להקים מושבה קומוניסטית. הו\"ל עתונים באידיש \"דיא בייטש\", \"דיא פלעדערמויז\", ועוד. עסקן ציבור."},{"i":5385,"n":"אפטוביצר, אביגדור מוינה","f":"משה אהרן","k":"הו\"ל ספר ראביה","bt":"תרלא","bp":"טרנופול","dt":"תשג","dp":"ירושלים","b":"למד בוינה באוניברסיטה ובבית המדרש לרבנים. היה מזכיר של אברהם אפשטין. היה פרופסור לתלמוד בוינה, חבר \"המזרחי\" עלה בתרצח. הוציא ספר \"הראבי\"ה\" ברלין תרעג, ועוד. היה מגדולי חכמת ישראל בדורו, והעמיד תלמידים רבים."},{"i":5386,"n":"אפטוביצר, אשר זליג מיזירנה","f":"ליפא","bt":"תר","dt":"תרעה","b":"רב ביזירנה(=איזערנא)-תרמד, חתנו היה ר חיים ליבוש המרלינג אב\"ד לופטין."},{"i":5387,"n":"אפטיקר, אריה ליב רוקח מבוברקא","b":"מחכמי בוברקא. חתן ר חיים שמחה ויטלס מבוברקא."},{"i":5388,"n":"אפטיקר, דוד מלינסק","b":"מחכמי לינסק-תרמו."},{"i":5389,"n":"אפטיקר, דוד מפילדלפיה","bt":"תרטו","bp":"פוניביז","b":"תלמיד רמ\"ל לילינבלום בקלויז שמוקלערס בוילקומיר, ולמד גם עברית ורוסית. היגר לארה\"ב-תרמח והיה סופר ב\"טאגבלאטט\", עבר לפילדלפיה-תרנה והו\"ל \"דיא געגענווארט\" יחד עם המשורר דוליצקי."},{"i":5390,"n":"אפטיקר, מיכאל מיכל מקראקא","f":"מתתיהו קלהרי הקדוש","b":"מחכמי קראקא."},{"i":5391,"n":"אפטיקר, משה מפשמישל","b":"מחכמי פשמישל - מתורתו ב\"עטרת תפארת\"-תרצא. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":5392,"n":"אפטיקר, משלם ישכר מסנדובה","b":"חתן ר שמואל לנדא מוישנה. מחכמי סנדובה וישניה-תרצד, תשובות אליו ב\"דובב מישרים\" ו\"חזון נחום\". פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":5393,"n":"אפטר, אליהו","f":"צבי הירש מקאליש"},{"i":5394,"n":"אפטר, משה יהודה מטרנוב","f":"יעקב","k":"בעל אמרי משה","bt":"תר","bp":"טרנוב","dt":"תרסג","b":"ראב\"ד בטרנוב והעמיד תלמידים חשובים. חיבר \"אמרי משה\" טרנוב תרסג."},{"i":5395,"n":"אפטר, צבי הירש מקאליש","f":"יעקב הקדוש-נחלת יעקב","dt":"תסד","b":"(בן או נכד - ר יעקב קצנלנבוגן בעל \"נחלת יעקב\"). פרנס ומנהיג בקאליש. בנו - ר אליהו."},{"i":5396,"n":"אפטרגוט, אליהו מפשמישל","f":"חיים","dt":"תש..","b":"תלמיד ר מאיר אריק. מראשי הקהלה בפשמישל. חתן ר חיים בוטרמן מדוברומיל. נספה בשואה."},{"i":5397,"n":"אפטרוט, דוד אליקים מפפד\"מ","f":"משה אליקים","k":"בעל פירוש לספר חסידי","dt":"תפה-ח - א שבט","dp":"פפד\"מ","b":"דיין בפפד\"מ. חיבר פירוש על ספר חסידים - ובנו ר שלמה הו\"ל את ספרו - פפד\"מ תעג. נכדו - ר יוסף דוד זינצהיים בעל \"יד דוד\" ומזכירו בספרו."},{"i":5398,"n":"אפטשינסקי, שמואל","b":"גביר. גיסו של המלבי\"ם שסייע לו בהדפסת ספריו."},{"i":5399,"n":"אפיסדורף, אריה מגריידינג","b":"מחכמי גריידינג - תשובה אליו \"הרי בשמים\"-תרם."},{"i":5400,"n":"אפיסדורף, ישכר דב בריש מיברוב","f":"יוסף","k":"בעל עבודת היום","bt":"תקף","dt":"תרל","b":"מחכמי יברוב. חיבר \"עבודת היום\" למברג תרכח. מצאצאי ר יעקב אשכנזי מגינצבורג אב\"ד פרידבורג שעלה לארץ."},{"i":5401,"n":"אפל, חיים","f":"צבי","b":"חתן ר יעקב וינר. חתנו - ר אברהם אבא איזנר."},{"i":5402,"n":"אפל, יהודה ליב מליטא ותל אביב","f":"יצחק","bt":"1857","bp":"ואקשנה","dt":"1935","dp":"תל אביב","b":"תלמיד בישיבה וכונה \"העילוי מוואקשנה\". פרש להשכלה והצטרף לחובבי ציון בוילנא. מעוזריו של הרב ריינס ביסוד \"המזרחי\". הדפיס ספרות תעמולה לציונות בבית דפוס שהקים בוילנא. עלה לארץ-1921. פרסם מאמרים בתוך \"ראשית התחיה\" - ת\"א תרצו."},{"i":5403,"n":"אפל, יוסף יהושע","f":"שרגא פיבל","k":"בעל יד יוסף","bt":"תרעא","bp":"צאנז","dt":"תשנו","b":"למד ברעדים ואחר כך בבית מדרש לרבנים בברלין והיה תלמידו של ה\"שרידי אש\". גורש בידי הנאצים והגיע לוארשא, משם הגיע לאנגליה ושימש כחזן ואח\"כ ונתמנה לדיין בלידז ולבסוף לאב\"ד. התכתב עם גדולי דורו. חיבר \"יד יוסף\""},{"i":5404,"n":"אפל, יעקב אריה ממארמארוש","f":"בצלאל","k":"בעל ארון בצלאל","b":"חסיד האדמור ר מנחם מנדל האגר מויזניץ. מחכמי כפר יועד-מארמרוש. חיבר גם \"איל מלואים\" - רוב כתביו אבדו, ושריד מהם נדפס ע\"י נכדו ר דוד אפל - בשם קונטרס \"ארון בצלאל ואיל מילואים\" תל אביב תשלה (בסוף ספר זכרון מהר\"י)."},{"i":5405,"n":"אפל, צבי","k":"בעל זכרון משה","b":"חתן ר יעקב וינר. בנו - ר חיים."},{"i":5406,"n":"אפלבוים, אברהם אבא","f":"פתחיה חיים יעקב","bt":"תרכא","bp":"רישא","dt":"תרצג","b":"מורה ומחנך, פרסם מאמרים בכתבי עת בשפות שונות. חיבר שלשה ספרי ביוגרפיה אודות גאוני איטליה מהם תולדת ר יהודה מוסקאטו דראהביטש תרס, ועוד. כתב ערכים באוצר ישראל."},{"i":5407,"n":"אפלבוים, אפרים יצחק מליסקא","f":"ליבוש","k":"בעל משנה אחרונה","bt":"תקכב","bp":"דוברומיל","dt":"תרג","b":"תלמיד ר אלימלך מליזנסק. רב בליסקא, פרמישלא-תקף. חיבר \"משנה אחרונה\" פרזמישל תרמב."},{"i":5408,"n":"אפלבוים, אפרים שמעון","f":"מרדכי","k":"בעל מאמר מרדכי","b":"חיבר \"מאמר מרדכי\" למברג תרלא."},{"i":5409,"n":"אפלבוים, יעקב מלודמיר","bt":"תרטו","b":"רב בלודמיר-ווהלין-תרסג."},{"i":5410,"n":"אפלבוים, שמריהו מהונשטשט","f":"מרדכי","k":"בעל תורת כהנים","bt":"תרלג","b":"נכד ר שמריל מלובמלא. רב בהונטשעשט-פלך בסרביה-בסרביה. נסמך מאת: ר שלמה הכהן מוילנא, ר הלל דוד הכהן טריוש מוילקי, ר שלמה חאסילוב, ור ברוך פולינקובסקי מקעשינוב. חיבר גם \"משפט הגר\", \"בית המדרש\"."},{"i":5411,"n":"אפלברג, יצחק ליב הלוי","b":"מחכמי רוזניאטוב - תשובה אליו \"אבן יקרה\"."},{"i":5412,"n":"אפלגרין, אברהם מסטרי","b":"פרסם מאמרים ב\"הבונה\" - לבוב תרסד."},{"i":5413,"n":"אפלח, משה משלוניקי","dt":"שח - כד תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":5414,"n":"אפללו, יחיא מאגאדיר-מרוקו","b":"מחכמי אגאדיר-מרוקו, חתם על פס\"ד-תקטז עם ר יעקב טולדנו, פסק ממנו בשו\"ת רב אד\"א."},{"i":5415,"n":"אפללו, ישועה מאגאדיר","b":"מו\"ץ באגאדיר-מרוקו. תשובה אליו מהיעב\"ץ-תקו ואל חבריו: ר יעקב גדליה, ר ישועה אפלאלו."},{"i":5416,"n":"אפללו, ישועה מאגאדיר-מרוקו","b":"רב באגאדיר-מרוקו, בזמן היעב\"ץ ממרוקו בשנות ה-ת'."},{"i":5417,"n":"אפללו, מימון ממרוקו","f":"חיים","bp":"אזאוויא-מרוקו","dt":"תנו - אחרי","b":"נולד בכפר אזאוויא, גורש עם כל היהודים-תיא ועבר לפאס. כיהן כרב יחד עם ר יהודה עוזיאל, ר מנחם סירירו ור וידאל הצרפתי - שסייע לו להקים ביכ\"נ נפרד לקהילתו. חתם על תקנות - תמח-תנד. בנו - ר סעדיה."},{"i":5418,"n":"אפללו, מסעוד מאופראן","f":"מוסא","dt":"ד'תיג - ד שבט","dp":"אופראן","b":"נהרג עק\"ה."},{"i":5419,"n":"אפללו, סעדיה מפאס","f":"מימון","b":"רב בפאס עם ר וידאל הצרפתי, ר מנחם סירירו ור יהודה ן עטר ועוד, וחתם עמם על פסקי דין-תפח."},{"i":5420,"n":"אפללו, עיוש מארבאט","b":"מחכמי ראבאט-תקלג."},{"i":5421,"n":"אפלמן, דב בר מאוריטש","f":"אהרן","bt":"תרן","bp":"יאנוב-פלך גרודנא","b":"תלמיד ישיבות לומזה, נוברדוק, סלובודקה, מיר, קובנה. נסמך מאת: ר אליעזר הגדול ממינסק, ר שמואל לנדוי מלוסק, ר משה מרדכי אפשטין, ר ישראל ניסן קארק, ר חיים עוזר גרודזינסקי. חתן ר יעקב מאיר כהנא ממינסק. רב באוריטש-פלך מינסק (ליד סטרי)-תרעג, היגר לארה\"ב-תרפב וכיהן כרב ביהכ\"נ \"חברה תהלים כתר ישראל\" בניו יורק. עסק בעניני צבור. בניו: ר אברהם יוסף, ר חיים, ר משה. חתנו - ר יעקב סאדין מניו יורק."},{"i":5422,"n":"אפלפלד, יהונתן ליב","b":"רב ביאמניץ"},{"i":5423,"n":"אפלר, שמואל מיאהאנא","b":"תלמיד החת\"ס. מחכמי יאהנא-תקץ. נזכר בתשובה מר יהודה אסאד וב\"חתם סופר\"."},{"i":5424,"n":"אפמן, זאב וולף מטשישוי","bt":"תרכד","b":"תלמיד בעל \"וידבר משה\" מבאניהאד(=באניהד). מו\"ץ בטשיטשי. פרסם מאמרים ב\"וילקט יוסף\"."},{"i":5425,"n":"אפנזר, שלמה ממרוקו","dp":"תאגונית","b":"מצדיקי מרוקו."},{"i":5426,"n":"אפסג, משה מאגאדיר","b":"מו\"ץ באגאדיר-מרוקו, חתם על פס\"ד-תצה."},{"i":5427,"n":"אפערט, יוליוס מגרמניה וצרפת","b":"חוקר במדעים ובלשן בגרמניה ובצרפת. חיבר ספרים ומאמרים ובהם על פרסית עתיקה."},{"i":5428,"n":"אפרון, צבי אליהו","b":"רב בווישניבה,רחובות-תרפ\"ז"},{"i":5429,"n":"אפרון, צבי אלימלך","dt":"תשג","b":"רב בשצוצין"},{"i":5430,"n":"אפריון, אורי דוד מזאגר","f":"יוסף מסימנא","k":"בעל אפריון דוד","bt":"קלריץ","b":"תלמיד בישיבת איישישוק. רב בנאמוקשט, זאגר חדש-תרכ. שאלות אליו מר שמעון זרחי, ר משה צייטלין ועוד. התכתב עם ר יצחק אלחנן מקובנא שהזכירו בספרו \"באר יצחק\". בניו ר אליהו דב רבינוביץ מירושלים, ר יוסף יעקב רבינוביץ מרוסטוב, ר מנחם מנדל אפריון. חתנו ר שבתי חיים שוחט בעל \"זהב שחוט\"."},{"i":5431,"n":"אפרייאט, אלישע מצפרו-מרוקו","dt":"תרפט - טז שבט","dp":"ירושלים","b":"מו\"ץ בצפרו-מרוקו, עלה לירושלים."},{"i":5432,"n":"אפרייאט, יהודה","f":"נפתלי","dp":"אופראן(מרוקו)","b":"מקדושי מרוקו,נהרג עק\"ה בשריפה עם עוד 50 שסירבו להמיר דתם באופראן"},{"i":5433,"n":"אפרייאט, יעקב יוסף מצפת","f":"משה","b":"בשליחות קהלת צפת-תרנה בצפון אפריקה."},{"i":5434,"n":"אפרייאט, מסעוד ממראקש","b":"מחכמי מראקש-שנות ה-תק'."},{"i":5435,"n":"אפרייאט, משה מאלגיר","bt":"תקמח","bp":"ווהראן","b":"עלה לארץ לאחר הכיבוש הצרפתי-תקץ והיה רב בצפת. בשליחות צפת במרוקו-תרטז."},{"i":5436,"n":"אפרייאט, נפתלי מאופראן-מרוקו","f":"יהודה","dt":"תקיא","dp":"אופראן","b":"נהרג עק\"ה."},{"i":5437,"n":"אפרייאט, רחמים אלישע ממרוקו","bt":"תרה","bp":"צפרו-מרוקו","dt":"תרסט - טז שבט","dp":"ירושלים","b":"רב במרוקו. עלה לירושלים-תרנה."},{"i":5438,"n":"אפרים","b":"מגדולי בעלי התוספות-ד'תתק\"נ"},{"i":5439,"n":"אפרים","f":"קפרון","b":"מדקדק בספרד-ד'תשן, תלמיד ר מנחם ן סרוק."},{"i":5440,"n":"אפרים","f":"יהודה","b":"פייטן קדום, ומובא ממנו במחזורים קדומים."},{"i":5441,"n":"אפרים","f":"יהודה","b":"מחכמי אשכנז. נזכר בשו\"ת מהר\"ם מרוטנבורג, ובהגהות מיימוניות - אודות פסק דין של הדיינים ר אפרים בן יהודה ור יצחק בן פרוגרוס כנגד החולק אליהם ר אברהם הלוי בן אליעזר ומהר\"ם מרוטנבורג הכריע כר אברהם."},{"i":5442,"n":"אפרים","f":"יואל","b":"נזכר בשאלת ר משה הדרן ששאל את מהר\"ם מרוטנבורג-ה'לא."},{"i":5443,"n":"אפרים (אבריל) מלבוב","f":"אליקום געציל","dt":"תכה - א ניסן","dp":"לבוב","b":"דומ\"צ בלבוב. חתם עם בעל הט\"ז, ועוד. חתם-תיד עם ר משה נח יונה מזולקוא, וחתימתו נתקיימה מאת ר יהודה אברהם הלוי, ר אפרים בן שלום פרידמן, ר ישעיה בן סנדר כץ ומאת בעל הט\"ז. (יש שרשמו שמו אבריל - לפי בובר שמו אפרים ולא אבריל)."},{"i":5444,"n":"אפרים (שלום) מבונא","f":"יעקב בן קלונימוס","k":"בעל מגילת אפרים","bt":"ד'תתצה-ז","bp":"בונא","dt":"ד'תתקנו","b":"נכד ר קלונימוס. מגדולי הראשונים, רב בנייס עד הגירוש-ד'תתקנז (בגירוש נהרג ר שמואל בן נטרונאי ור אפרים ניצל בנס), רב בבונא-ד'תתקן בזמן הראבי\"ה ורבנו טוביה. אחיהם של ר אברהם, ר קלונימוס, ר גרשום. נזכר ב\"זכרון ברית לראשונים\" מאחיינו ר יעקב הגוזר, השיב לר יעקב בן גרשום אחיו ב\"אמרכל\". בנו ר אליקים נהרג עק\"ה-ה'לא בבונא. חיבר פירוש לתפילות ולמחזור - בכת\"י, סליחות ופיוטים וחתם עליהם ובהם \"אלקים צויתי לידידך\", \"הרחמן\" לברית מילה, ועוד. חיבר גם \"דברי הימים מגזירות שאירעו לישראל משנת ד'תתנו\" ונקרא - \"מגילת אפרים\". הוא המקור למעשה ר אמנון ממגנצא וממנו הביא ה\"אור זרוע\""},{"i":5445,"n":"אפרים - חתן רש\"י","b":"שיבוש בשה\"ק - לא מצינו כזה."},{"i":5446,"n":"אפרים איסר מרבקה","b":"שו\"ב ברבקה. תשובה אליו \"דובב מישרים\"-תרפה."},{"i":5447,"n":"אפרים בכר משה","f":"ראה אפרים בן משה"},{"i":5448,"n":"אפרים בעל התוספות","f":"דוד","b":"נזכר בתוס' עבו\"ז והוא ט\"ס וצ\"ל ר אברהם בן דוד - הראב\"ד."},{"i":5449,"n":"אפרים בר\"מ מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":5450,"n":"אפרים הבבלי","b":"פייטן קדום, מפיוטיו במחזורים קדומים."},{"i":5451,"n":"אפרים הגביר מאשכנז","f":"אפרים","b":"מחכמי אשכנז-ה'א, הובא בתוספות, ובשו\"ת מהר\"ם מרוטנבורג נזכר כ\"גביר רבו של ר יעקב\", וי\"א שהיה מרגנשבורג."},{"i":5452,"n":"אפרים הגדול מרגנשבורג","k":"בעל ארבעה פנים","dt":"ד'תתקלה","b":"מגדולי חכמי רגנשבורג הקדמונים,פוסק,מרביץ תורה בוירמייזא ושפירא"},{"i":5453,"n":"אפרים הדיין מסוריה","b":"מחכמי צפת בשנת תקכד"},{"i":5454,"n":"אפרים הזקן מרמלה","f":"משה","b":"חכם ברמלה בשנת ד תשצח (1038), תעודה ממנו פורסמה בידי מ אסף בספרו \"מקורות ומחקרים\"."},{"i":5455,"n":"אפרים הכהן מאוסטרהא ואמ\"ד","b":"רב באוסטרהא, ר\"מ בבימ\"ד ספרדים באמשטרדם, ונציה, עלה לארץ. הסכים על \"זרע שמשון\" - אמשטרדם תצא, לתלמידו ר שמשון נחמני."},{"i":5456,"n":"אפרים הכהן מאמשטרדם","b":"מגדולי חכמי פולין,מרביץ תורה באמסטרדם,האג,התכונן לעלות לא\"י אך נבחר לרב במודנא-תע\"ד"},{"i":5457,"n":"אפרים הכהן מבלשביץ","b":"רב בבלשביץ-תרי."},{"i":5458,"n":"אפרים הכהן מוילנא","dt":"תרך - ט אב","dp":"ברלין","b":"חתן ר בנימין בן יוסף מנדלשטם. מראשוני תלמידי ביהמ\"ד לרבנים בוילנא, מורה בביהמ\"ד לרבנים, עוזר לגנרל גוברנאטור בעניני דת ישראל יחד עם ליב לעואנדא ור יונה גרשטין. מזכיר אסיפת הרבנים בפטרבורג-תריז. ר מטעם הראשון בוילנא-תרך על מקום ר גרשון אמשטרדם והיה מחלוקת כנגדו. נפטר צעיר."},{"i":5459,"n":"אפרים הכהן מוילנא ובודה -הנכד","f":"יעקב מוילנא (אהרן)","k":"בעל שער אפרים","bt":"שעו","bp":"וילנא","dt":"תלח - יג סיון","dp":"אופן(=בודון, בודה)","b":"נכד ר אפרים מבריסק וירושלים. מגדולי הפוסקים בדורו. חתן ר אליהו-נכד ר אליהו בעל שם. תלמיד ר משה בעל \"חלקת מחוקק\", דיין אצל רבו בוילנא-שצו, גלה מוילנא עם חבריו בעל \"באר הגולה\" בעל \"ברכת הזבח\" והש\"ך, והגיע לפרג-תטו והעמיד שם תלמידים, רב בטרעביטש, ברודא, וינה, אויבן(=אופן)-תכו וייסד שם ישיבה עם בנו ר אריה יהודה ונכדו ה\"חכם צבי\", הוזמן לירושלים לכהן כרב על מקום זקנו ר אפרים מירושלים ובריסק ולובלין - אך לא הספיק ונפטר באופן. (מסופר כי בזמן גזירות תח - חשבו שר יעקב נהרג, והעידו עדים כשרים שראוהו מוטל הרוג - ובאמת התחבא בין ההרוגים, ור השל מלובלין התיר את אשתו ולאחר זמן הופיע - ומאז נמנע ר השל מלדון בדיני עגונות). בניו: ר אריה יהודה הו\"ל ספר אביו \"שער אפרים\" (3319), ר יחזקיה (9115). חתניו - ר יעקב בן בנימין זאב ז\"ק (ונכדו החכם צבי), ר יצחק הלוי שולהוף.","bk":[["שער אפרים [שו\"ת]",""],["שער אפרים",""]]},{"i":5460,"n":"אפרים הכהן מירושלים","bt":"תרמד","dt":"תשיז","b":"מקובל,מחכמי בבל,ר\"מ בישיבת פורת יוסף בירושלים"},{"i":5461,"n":"אפרים הכהן ממודנא","b":"מחכמי מודנא-תפח. מתשובותיו ב\"פחד יצחק\", וב\"דברי יוסף\" אירגס. תלמידו - מוהרי\"ך."},{"i":5462,"n":"אפרים הכהן מפאס","f":"מנשה","b":"מחכמי פאס, חתם עם ר סעדיה ן דנאן."},{"i":5463,"n":"אפרים הכהן מפאס","f":"נחמיה","b":"מחכמי פאס"},{"i":5464,"n":"אפרים הלוי","b":"מחכמי חברון, חתם בשנת תקצט על סדר הכוללות"},{"i":5465,"n":"אפרים הלוי מוילהאן","b":"רב בוילהאן. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":5466,"n":"אפרים הלוי מטאלסן","bp":"פוקרוי","b":"מחכמי טאלסן. בנו - ר יעקב מטאלסן."},{"i":5467,"n":"אפרים הלוי מסטאויסק","k":"בעל אשל ברמה","dt":"שצח - לפני","b":"דרשן ומו\"ץ בסטאויסק. חיבר גם \"אבל כבד\"-בכת\"י - הספד על כמה רבנים."},{"i":5468,"n":"אפרים הלוי מפרשבורג","b":"בעל בית מסחר ספרים בפרשבורג-תקלה, עבר לפשט-תקסט."},{"i":5469,"n":"אפרים הרופא מיוון","f":"גרשון","b":"רב בוורוגה(=וראיה), אגריפון(=נגרפונטי)-ר'. חיבר ספר דרשות - בכת\"י, הדרשות לכבוד ר מרדכי קומטיני, ר שבתי הכהן ועוד."},{"i":5470,"n":"אפרים ויטעס מוילקומיר","k":"בעל אבל יחיד","b":"מחכמי וילקומיר. חיבר הספד למלבי\"ם בשם \"אבל יחיד\" - וארשא תרמז, ובו מתורת ר\"י מוולוזין."},{"i":5471,"n":"אפרים זלמן מברסטיצקא","f":"שאול","b":"רב בברסטיצקא-תק\"י"},{"i":5472,"n":"אפרים זלמן מזאמוטשט","f":"שמואל נפתלי הירץ"},{"i":5473,"n":"אפרים זלמן מיזירנה","b":"רב ביזירנה-תרטז."},{"i":5474,"n":"אפרים זלמן מרוזינאי","f":"אלחנן","dt":"תרטו - יב אדר","b":"רב ברוזינאי"},{"i":5475,"n":"אפרים יעקב מדומברובה","b":"מחכמי דומברובה - תשובה אליו \"שם עולם\"-תרלו."},{"i":5476,"n":"אפרים יצחק מפרמישלא","f":"אריה ליב משצרזיץ","k":"בעל משנה ראשונה","bt":"תקכב","dt":"תרג - כז תשרי","b":"תלמיד דודו ר שמעון אשכנזי מדוברומיל, ובהשפעתו היה לחסידו של ר אלימלך מליזנסק. רב ודיין בליסק, רב בפרמישלא-תקף.","bk":[["משנה אחרונה",""],["משנה ראשונה",""]]},{"i":5477,"n":"אפרים מאוסטרהא","f":"יעקב קופל","dt":"תקמ - טז טבת","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":5478,"n":"אפרים מאוסטרהא","f":"אהרן","dt":"תקכג","dp":"אוסטרהא","b":"פרנס באוסטרהא-תפט. חתם בפנקס הח\"ק. בניו: ר יונה, ר אהרן פרנס באוסטרהא."},{"i":5479,"n":"אפרים מאוסטרהא","f":"משה","dt":"תקצד - כז ניסן","dp":"אוסטרהא","b":"גבאי מחכמי אוסטרהא. חתן ר ישראל רב דחייטים מאוסטרהא. כונה בשם \"אפרים דעם שניידערשין רב'ס\". צאצאיו ממשפחת קופירשטין."},{"i":5480,"n":"אפרים מאיטליה","f":"יוחנן","b":"מחכמי איטליה-ש'. תרגם תנ\"ך לאיטלקית וחלקו קיים."},{"i":5481,"n":"אפרים מאשכנז","f":"אברהם","dt":"נח","dp":"וירצבורג","b":"רב בוירצבורג, נהרג עק\"ה יחד עם בני עדתו ועם הרבנים ר אליה בן שמואל, ור יצחק בן נתן. תשובה ממנו ב\"אור זרוע\"."},{"i":5482,"n":"אפרים מבוסניה","f":"משה","k":"הו\"ל תולדות יעקב","dt":"תרמב - יד טבת","dp":"ירושלים","b":"מחכמי בוסניה, אחיו של ר ששון בן משה, עלה לירושלים, חתם בתרכו על שטר שובר, היה ראש ישיבת הגביר ר רפאל משה. בשנת תרלב חתם על כתב שליחות ר אברהם יוסף בן שלמה שהיה בשליחות \"בית אל\". היה שליח ירושלים. הדפיס ספר \"דת יהודית\" לר אברהם לארידו, ובסופו הוספות משלו. תשובה ממנו בספר \"ישמח לב\" ל שלום גאגין. עוד הוציא לאור ספר התכונה לר חיים ויטל ירושלים תרכו, וכן \"תולדות יעקב\" לר יעקב קאשטרו. נספד בספר \"שמש ומגן\""},{"i":5483,"n":"אפרים מבוצאץ","b":"רב בבוצאץ-תקסז."},{"i":5484,"n":"אפרים מדוברוביל","b":"רב בדוברומיל"},{"i":5485,"n":"אפרים מויטבסק","b":"תלמיד הבעשט. מחכמי ויטבסק. דודו של ר מנחם מנדל מויטבסק בנו של אחיו ר משה."},{"i":5486,"n":"אפרים מזולקוא","f":"ישעיה","dt":"תקע - א חשון","dp":"זולקוא","b":"דיין בזולקוא."},{"i":5487,"n":"אפרים מחעלם","f":"יוסף","k":"בעל בכושרות","dt":"תטו","b":"מחכמי פולין-ש'. חיבר שירים וזמירות וקינות בשם בכושרות - קרימונה שסח. נהרג עק\"ה. רב במעהרן, קראקא, ווערשאן"},{"i":5488,"n":"אפרים מירושלים","b":"מחכמי ירושלים-רס\"ט"},{"i":5489,"n":"אפרים מירושלים","f":"שמואל","b":"מחכמי ירושלים, בשנת רסט חתם על הסכמת הנגיד בדבר פטור תלמידי חכמים ממסים"},{"i":5490,"n":"אפרים מירושלים","f":"משה","k":"בעל דת יהודית","dt":"תרמב - יד טבת","dp":"ירושלים","b":"מקובל, עלה מבוסניא, דיין-תרכו, מקובל, ראש ישיבת הגביר ר רפאל משה. בשליחות בתונס-תרלז. בנו ר אברהם בכר אפרים מקרים. חיבר \"דת יהודית\". אחיו של ר ששון."},{"i":5491,"n":"אפרים מירושלים","dt":"תרך","dp":"קאבול-אפגניסטן","b":"חברו של ר יעקב ספיר, בשליחות בהודו ונפטר בדרכו מהודו לבוכרה - ליד קאבול."},{"i":5492,"n":"אפרים מלובלין וירושלים","b":"רב בירושלים, לובלין על מקום ר ישראל בן שלום שכנא. תלמידו בירושלים - ר יו\"ט צהלון המזכירו בספרו. נכדו ר אפרים הכהן מוילנא בעל \"שער אפרים\"."},{"i":5493,"n":"אפרים ממגנצא","f":"נתן","b":"רב באשכנז-ן' נזכר בשו\"ת מהר\"ם מרוטנבורג, יחד עם חברו ר יצחק בן יהודה בעל \"פענח רזא\". חיבר ספר חדושים והלכות - בכת\"י - ואבד. מתלמידיו ר מרדכי בן הלל בעל \"המרדכי\". חיבר פיוט ליוה\"כ \"אתה אחד ושמך אחד\". (בחת\"ס אומר שסתם ראב\"ן בספרים הוא חותנו של ר יואל הלוי והוא ר אפרים זה - וכנראה טעות)."},{"i":5494,"n":"אפרים ממודנא","b":"מחכמי איטליה-קן. חיבר ספר המוסר ונדפס."},{"i":5495,"n":"אפרים ממצרים","f":"שמריהו","bp":"עזה","b":"נכד ר יחיא העזתי. בנעוריו הגיע עם אביו הרב לפוסטאט במצרים ועמד שם בראש קהלת ירושלים בפוסטאט-ד'תתל. היה תלמידו וידידו של הגאון הירושלמי ר שלמה בן יהודה, ועזר הרבה לישיבה ולישוב בארץ ישראל, ואגרות מהם נמצאו בגניזה. היה חבר בסנהדרי גדולה (ישיבת ר שלמה בירושלים). נמצאה תעודה אודות ר אברהם בן אהרן אלבצרי - חזן ודרשן, שיצא כנגד ר אפרים ועל כך נידוהו בית הדין. מכתב ממנו אל ר צדוק הלוי מישיבת ירושלים."},{"i":5496,"n":"אפרים מסקאהל וליפאוויץ","b":"תלמיד הבעשט. רב בליפאוויץ. בנו ר דוד מליפאוויץ."},{"i":5497,"n":"אפרים מעכו","f":"אליעזר","b":"מחכמי עכו-ה'א."},{"i":5498,"n":"אפרים מפאפא","b":"רב בפאפא-תק\"מ"},{"i":5499,"n":"אפרים מפפד\"מ","dt":"קח","dp":"פפד\"מ","b":"מחכמי פפד\"מ-ק'. נהרג עק\"ה בגזירות קח."},{"i":5500,"n":"אפרים מפרוינקירכן","b":"רב בפרוינקירכן"},{"i":5501,"n":"אפרים מצור","b":"מחכמי א\"י בזמן הרמב\"ם שהשיב לו-ד'תתקלז, נזכר אצל ר בנימין מטודלא-ד'תתקך ונקרא ר אפרים מצרי דיין וחברו ר מאיר מקרקושנה."},{"i":5502,"n":"אפרים מצרפת","f":"שמשון","k":"בעל פירוש לתורה","b":"מגדולי הראשונים בצרפת-ד'תתק\"נ. חיבר פירוש לתורה ע\"פ הקבלה - בכת\"י ונדפס בחלקו - שלוניקי תריא, והיה בידי החיד\"א שהביא ממנו בספריו. הביא שמועה מר אושעיא-שחי בזמן רבנו תם.."},{"i":5503,"n":"אפרים מצרפת","b":"מחכמי צרפת הקדומים. נזכר בפירוש אבות במחזור ויטרי לר יעקב בן שמשון מפלישא ושם מביא ממשנת ר אפרים."},{"i":5504,"n":"אפרים מקאלק","b":"תלמיד המגיד מזלוטשוב, ויד ימינו בקאלק."},{"i":5505,"n":"אפרים מרגנשבורג - אלמאניה","f":"מאיר","k":"אפרים החסיד","b":"רב ברגנשבורג, שאל את זקני רגנשבורג - ובהם ר יהודה החסיד ונזכר בספרו. נזכר בפירוש המיוחס לראב\"ד על תמיד כר אפרים החסיד."},{"i":5506,"n":"אפרים מרגנשבורג - יקר","f":"יצחק בן אברהם","dt":"ד'תתקלה (מסופק)","b":"תלמיד הריב\"א משפירא-תלמיד רש\"י, תלמיד חבר לרבנו תם ונזכר בספרו. ישב כדיין יחד עם הריב\"ם, ועם ר משה בן יואל. היה במחלוקת עם ר יואל הלוי בן יצחק מבונא. מכונה גם ר יקר (על שם הפסוק הבן יקיר לי אפרים), וגם נזכר בספר המנהיג בשם \"רבנו אפרים מאלמאניא\" - ואינו ר אפרים הנזכר ברמב\"ן ובראב\"ד ובעל המאור (שם הכוונה לר אפרים תלמיד הרי\"ף). בנו - ר משה זלסמאן שנזכר באור זרוע. חיבר פיוטים. מתלמידיו: ר ברוך בן שמואל ממגנצא, בעל פירוש למסכת תמיד (המיוחס בטעות לראב\"ד) ובנו ר משה, ר זלמן בן ר יהודה החסיד."},{"i":5507,"n":"אפרים מרמלה","f":"יעקב","b":"חבר בית הדין ברמלה בשנת ד תשצח (1038) תעודה ממנו פורסמה על ידי מ. אסף בספרו \"מקורות ומחקרים\""},{"i":5508,"n":"אפרים נפתלי הירש","f":"יוסף יונה","b":"חתן ר יעקב הלוי. מרביץ תורה, עשיר גדול, ר\"מ בבריסק, ראב\"ד בלובלין (לודמיר?)"},{"i":5509,"n":"אפרים פישל","b":"חתם-תמז ביריד ירוסלב, יחד עם ר פנחס משה."},{"i":5510,"n":"אפרים פישל הכהן מצפת","f":"במז\"ל","b":"אב\"ד ריסישיץ, עלה לצפת וכיהן כדיין אצל ר שמואל הלר. הסכים על \"זבחי שלמים\" תרמג, \"כנסת מרדכי\" תרמו, \"בית שלמה\" תרמט."},{"i":5511,"n":"אפרים פישל זאסלווער מטבריה","b":"בשליחות קהילת החסידים כמה פעמים. היה בקוריץ-תקמח והדפיס שם \"עין יעקב\", ופגש את ר פנחס מקוריץ. כתוצאה משליחותו הוקם \"כולל וואהלין\" בטבריה. מכתבי המלצה בעדו לר מרדכי מנסכיז, החוזה מלובלין, המגיד מקוזניץ והרב מאפטא."},{"i":5512,"n":"אפרים פישל כץ הכהן מירושלים","dt":"שן - בערך","dp":"ירושלים","b":"מחכמי אשכנז, עלה לירושלים, רב בירושלים-שכ ונשיא קהל אשכנזים בירושלים. בנו - ר יעקב ונכדו ר אפרים בעל \"שער אפרים\"-אבי ה\"חכם צבי\". (יש אומרים שהוא חתן המהרש\"ל - ולא נראה כדבריהם)."},{"i":5513,"n":"אפרים פישל מבאייא","b":"רב בבאייא-תק\"מ"},{"i":5514,"n":"אפרים פישל מבוברקא ופרמישלן","f":"משה יחזקאל","b":"רב בבוברקא,פרעמישלאן"},{"i":5515,"n":"אפרים פישל מבלוינא","b":"פרסם מאמרים ב\"הכרם\" - וארשא תרצא."},{"i":5516,"n":"אפרים פישל מברסטיצקא","f":"בנימין בושקא","b":"רב בברסטיצקא-תק\"י"},{"i":5517,"n":"אפרים פישל מוערעשוער","dt":"תרד - א אדר","b":"רב בווערעשווער-תקפא."},{"i":5518,"n":"אפרים פישל מטיקטין","b":"עשיר גדול,רב בטיקטין-תק\"ל"},{"i":5519,"n":"אפרים פישל מלבוב","f":"צבי בן אפרים פישל","dt":"תיג","dp":"לבוב","b":"חתן ר מרדכי (ובטעות נרשם חתן מהר\"ל מקראקא במקום חתנו - מהר\"ל מקראקא). רב בלוקאב, רב ומנהיג דד\"א, נשיא א\"י בלבוב. בנו - ר זאב וולף, חתנו - ר אריה ליב הגבוה מקראקא (המכונה ר ליב ר פישלס - על שם חותנו - פישל)."},{"i":5520,"n":"אפרים פישל מלובלין","f":"צבי הירש מהלברשטט","dt":"תקסה - ט אדר","dp":"לובלין","b":"בן אב\"ד הלברשטט. דיין בלובלין. חתם פעמים רבות עם ר שאול מרגליות אב\"ד לובלין, וחתם על החרם של ר שאול שלא לקבוע מנינים חדשים בלובלין."},{"i":5521,"n":"אפרים פישל מלובלין","f":"אלכסנדר רורקרש","dt":"תקסט - כא סיון","dp":"לובלין","b":"נכד-אבי אמו ר אריה ליב אב\"ד טרניגרד. מחכמי לובלין. חתם על תקנות ופסקים עם ר שאול מרגליות - אב\"ד לובלין, וחתם על החרם שלא ליסד מנינים חדשים."},{"i":5522,"n":"אפרים פישל מסטריקוב","f":"יוסף יהודה ליב מבלטא","k":"אדמור מסטריקוב","bt":"תקג","dt":"תקפב - יז טבת","b":"תלמיד המגיד ממזריטש, ר לוי יצחק מברדיטשוב, ר עוזיאל מייזליש בעל \"עץ הדעת טוב\", ור אלימלך מליזנסק. עבר מבאלטא לפולין והתישב בברעזין. הוסמך לאדמור ע\"י ר משה יהודה ליב מסאסוב, וכיהן כאדמור בסטריקוב-ליד ברעזין, והיה מראשוני האדמורים בפולין. מתולדותיו ב\"להב אש\" - זיכלין."},{"i":5523,"n":"אפרים פישל מפודקמין","b":"עלה לארץ עם ר אברהם מקליסק והתישב בטבריה. בשליחות-תקמו."},{"i":5524,"n":"אפרים פישל מפרוביזנא","b":"מחכמי פרוביזנא - תשובה אליו \"בית שלמה\"-תריא."},{"i":5525,"n":"אפרים פישל מקולמייא","f":"חיים מקולומייא ולבוב","dt":"תקמג - יג תשרי","b":"רב בקולומייא. נכדו - ר משולם מטיסמניץ ופרשבורג. אחיו - ר צבי הירש מברזאן ודרוהוביטש."},{"i":5526,"n":"אפרים פישל משטעקטשין","f":"לייבש חעלמער","b":"נכד ר שמעון מרילס מירוסלב. חתן האדמור ר משה מללוב. בנו ר שמעון משטקטשין, וחתניו: ר יהודה לייביש מאוזרוב, ור צדוק הכהן מלובלין."},{"i":5527,"n":"אפרים פישל סגל מפונשוב וירושלי","b":"רב בירושלים-תריז."},{"i":5528,"n":"אפרים צבי מזרנוב","b":"רב בזרנוב"},{"i":5529,"n":"אפרים צבי מסאהל","b":"רב בסאהל"},{"i":5530,"n":"אפרים שלום מירושלים","b":"מרבני ירושלים"},{"i":5531,"n":"אפרים שלום משלוניקי","dt":"תנט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":5532,"n":"אפרים שניאור מקולומיאה","b":"מחכמי קולומיאה - תשובה אליו \"מנחת פתים\"."},{"i":5533,"n":"אפרים תלמיד הרי\"ף","f":"יהודה","b":"תלמיד הרי\"ף. חיבר השגות והערות על הרי\"ף. נזכר בספר המאור."},{"i":5534,"n":"אפרימזון, יעקב","f":"יקותיאל","b":"סופר תלמיד חכם. חיבר מאמרים בכתבי עת ובהם פולמוס כנגד המשכילים."},{"i":5535,"n":"אפרימזון, יקותיאל הלוי מבויסק","f":"יעקב הלוי מטאלסן","bt":"תר","b":"חתן ר משה ארינבלט(=לרנבלאט) מסאסמקין. תלמיד ר משה יצחק הלוי מגולדינגן, ור ישראל סלנטר בקובנא, ור משה צייטלין. רב בסאסמקין-תרכב, מטוי(=מיטאוי), בויסק-קורלנד-תרנו. נסמך מאת: ר משה יצחק הלוי מגולדינגן. בנו - ר יעקב. אחיו ר מרדכי ממיטאוי."},{"i":5536,"n":"אפרימזון, מרדכי ממיטאוי","f":"יעקב הלוי מטאלסן","dt":"תרמב - יט אלול","b":"שו\"ב במיטאוי."},{"i":5537,"n":"אפרת, יוזאפ","b":"בקי,דיין בברדיטשוב-תר\"ס"},{"i":5538,"n":"אפרתי משה צבי","bt":"1908","dt":"ה'תשמד 1984","bk":[["רבי עקיבא",""]]},{"i":5539,"n":"אפרתי שמעון בן יקותיאל","bt":"1908","dt":"ה'תשמח 1988","bk":[["מגיא ההרגה",""],["מעמק הבכא",""],["שבי ציון",""],["שערי הלכה",""]]},{"i":5540,"n":"אפרתי, אברהם","f":"אליעזר פרוזינר","bt":"תקכז","dt":"תרך","dp":"מערעץ","b":"מצאצאי היסו\"ד מוילנא. בנו - ר דוד טעבל מויטבסק."},{"i":5541,"n":"אפרתי, אליעזר הלוי מפינסק","f":"מאיר שמרינגר","k":"בעל שיח השדה","dt":"תקנה - אחרי","dp":"קרלין","b":"חתן ר ישראל איסר מפינסק. ראש ישבה בפינסק, רב בחומסק-תקם, פינסק. התקרב לר אהרן הגדול מקרלין ובעקבותיו נסע למגיד ממזריטש, ששלח אליו מכתב שפורסם. חיבר גם \"ריח השדה\". בנו ר משה מברדיטשוב-בוישאן, וחתניו ר מאיר בן ר לוי יצחק מברדיטשוב, ר ישראל דב בער מסטפין, ר יחיאל מיכל מקאשיווקא, ר דוד צבי קביליאנסקי מברדיטשוב, ר משה - זקנו של ר ר אברהם וינברג מסלונים, ר זאב וולף מוילנא."},{"i":5542,"n":"אפרתי, אליעזר משאוולי","b":"עסקן ציבור בשאוולי - הקים שם בית חולים יהודי-תרנא."},{"i":5543,"n":"אפרתי, דב בער מחברון","b":"רב בחברון-תרנד."},{"i":5544,"n":"אפרתי, דוד טבלי מליטא","f":"אברהם","k":"בעל מטע אפרתי","bp":"מאראטש","dt":"תרמה - יח חשון","b":"רב בהורודק דוויטבסק. ממשפחת הגר\"א. ידע בע\"פ את כל התלמוד הבבלי והירושלמי. חיבר ספרים בחקר התלמוד. חיבר גם \"תולדות אנשי שם\" לקורות חכמי הדור, ועוד."},{"i":5545,"n":"אפרתי, חיים מאודסה","f":"יצחק איזיק","bp":"ברדיטשוב","dt":"תרכה - כו חשון","dp":"וינה","b":"גביר בברדיטשוב, אודסה, וינה-1854. הקים בית חולים למתישבי חרסון היהודים במושבה \"נהר טוב\", תרם לצרכי צבור."},{"i":5546,"n":"אפרתי, יהודה צבי","b":"פרסם מאמרים ב\"אור תורה\" - לבוב תרפו."},{"i":5547,"n":"אפרתי, יהושע השל מחוליוב","f":"יעקב מברוד","k":"בעל נחלת יהושע","r":"אב\"ד טארטיקוב, פאמארין, חאליוב","bt":"תקם","dt":"תריב - ח סיון","b":"דור עשירי למהרש\"ל. תלמיד האדמור ר אברהם יהושע השל מאפטא. רב בטרטקוב, פמורן, רב ואדמור בחוליוב. בנו ר ראובן על מקומו אחריו. חיבר \"נחלת יהושע\" למברג תריד.","bk":[["נחלת יהושע – עה\"ת",""]]},{"i":5548,"n":"אפרתי, יוסף יוזפא סגל מברדיטשו","b":"זקן רבני ברדיטשוב"},{"i":5549,"n":"אפרתי, יוסף מתל אביב","b":"רב בתל אביב, מנהל מחלקת \"משמרת שבת\" ברבנות הראשית-תש."},{"i":5550,"n":"אפרתי, יצחק מתונס","b":"מרבני תונס, השאיר כתבים. מוזכר ב\"שורש ישי\" לר שלמה שמאמא. שאלה ממנו ב\"כרוב ממשח\" לר שלמה אלפסי - ליוורנו תריט."},{"i":5551,"n":"אפרתי, יצחק צבי מגלינא","f":"יקותיאל מחוליוב","k":"אדמור מגלינא","bt":"תרסה","bp":"חוליוב","dt":"תשג","b":"חתן האדמור ר בצלאל יהושע מושקוביץ מגלינא, רב ואדמור בגלינא-תרפא על מקום חותנו. אחיו ר שמעון חיבר את הקינה \"אני מאמין\" לזכרו והדפיסה בספרו \"מעמק הבכא\"."},{"i":5552,"n":"אפרתי, יקותיאל מחוליוב","f":"מרדכי מחוליוב","k":"אדמור מחוליוב למברג","bt":"תרם","dt":"תרצה - ג תשרי","b":"חתן ר צבי ווארמן מבוצאץ. נכד השרף מסטרליסק. אדמור בלמברג. אב\"ד חוליוב על כסא אביו. בנו ר שמעון."},{"i":5553,"n":"אפרתי, ליביש מלמברג","k":"אדמור מלמברג","b":"נכד השרף מסטרליסק, אדמור בלמברג. קירב את פשוטי העם ואף מחוגי העולם התחתון שאותם השיב בתשובה."},{"i":5554,"n":"אפרתי, מרדכי (נתן) מחוליוב","f":"ראובן דוד מחוליוב","k":"אדמור מחוליוב","bt":"תרך","dt":"תרץ - ב ניסן","dp":"למברג","b":"חתן ר מאיר רייך מרישא-חתן ר מנחם מסטריזוב בעל \"שובע שמחות\". אב\"ד טרטקוב-תרמב על מקום אביו. רב ואדמור בחוליוב-תרסג על מקום אביו, בנו ר יקותיאל מילא מקומו כרב חוליוב. בזמן מלחה\"ע ה-I עבר ללבוב והיה בא לתקופות לחוליוב. כתביו אבדו בשואה. חתנו - ר יצחק באבד מטרטקוב."},{"i":5555,"n":"אפרתי, עמרם מספרד ואלגיר -הנכד","f":"מרואס","bt":"[קי]","dt":"קץ - בערך","dp":"ווהארן או גרנדה","b":"נכד ר עמרם אפרתי מרואס מולנסיה. ונכד דון משה שושאן. מקובל ובקי בשבע חכמות. ברח מספרד בזמן הפרעות-קנא. רב באוראן-אלגיר, גרנדה-ספרד. חברו של הריב\"ש שרבות מתשובותיו מופנות אליו. וכן בקשרי שות עם הרשב\"ץ, (למרות שר צמח בן הרשבש לא סמך על פסקיו), היה בידידות עם ר שאול אשתרוק הכהן."},{"i":5556,"n":"אפרתי, עמרם מרואס מולנסיה הזקן","f":"נתן מרואס","b":"רב בולנסיה-ספרד-קלה כ-40 שנה בזמן הרשב\"ץ והריב\"ש, שהטיל חרם על שוחט שפגע בכבוד ר עמרם. נכדו ר עמרם אפרתי מאוראן-אלגיר ונזכר בשות הריב\"ש."},{"i":5557,"n":"אפרתי, ראובן דוד מחוליוב","f":"יהושע השל מחוליוב","bt":"תקץ","dt":"תרסג - ו תמוז","b":"חתן ר יקותיאל הכהן מברסטיצקא, ובזיוו\"ש חתן אחות ר זושא מזל מחוליוב-נכדו של האדמור ר משולם זושא מאניפולי. רב בחוליוב על כסא אביו."},{"i":5558,"n":"אפרתי, שמעון מחוליוב","f":"יקותיאל מחוליוב","k":"בעל מעמק הבכא","bt":"תרסט","bp":"חוליוב","b":"חתן האדמור ר יוסף ורטהיים מבענדר. אב\"ד הרובשוב-תרצג, אב\"ד בנדרי(=בענדר) על מקום חותנו-שעלה לארץ. ברח לרוסיה במלחמה, אב\"ד וארשא-תשו, בשנת תשז עלה לירושלים ועמד בראש מחלקת הכשרות של הרבנות. חיבר \"מעמק הבכא\" ירושלי תשח, ועוד."},{"i":5559,"n":"אפשטין יוסף דוד בן שלמה זלמן","bt":"1912","dt":"ה'תשסב 2002","bk":[["אוצר האגרת",""],["מוסר און הלכה",""],["מצוות הבית",""],["מצוות המוסר",""],["תורת האדם ב",""]]},{"i":5560,"n":"אפשטין משה יחיאל בן אברהם שלמה","bt":"1890","dt":"ה'תשלא 1971","bk":[["אש דת",""]]},{"i":5561,"n":"אפשטין, א.ב.","b":"חיבר יומן מסע באוטונומיה היהודית בבירוביז'אן בשנות ה-30."},{"i":5562,"n":"אפשטין, אברהם אשר מטרספול","b":"רב בטערספאלע(=טרספול), הסכים-תרסה על \"חמדת ימים\" לר קלמן חיים מיטקס."},{"i":5563,"n":"אפשטין, אברהם בצלאל מרעוואל","f":"צבי יעקב","bt":"תרלו","b":"רב ברעוואל-אסטלנד-תרסז."},{"i":5564,"n":"אפשטין, אברהם הלוי - הנכד","f":"מאיר בן אברהם בן מאי","dt":"תס-פ - בערך","b":"חתן ר נחמן פעסיש-ליפשיץ רפפורט מדובנא, וגיסו-בעל אחותו של של ר שמחה רפפורט מראוונא. נזכר בשו\"ת הב\"ח החדשות. מבניו: ר נחמן אב\"ד באר - בזמן ה\"חכם צבי\", ר יצחק איזיק."},{"i":5565,"n":"אפשטין, אברהם הלוי מסקאלי","f":"אפרים מרדכי","b":"רב בסקאלי. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":5566,"n":"אפשטין, אברהם יוסף משטעמעליוו","dt":"תשג","b":"רב בשטעמעליוו"},{"i":5567,"n":"אפשטין, אברהם יצחק מיורבורג","f":"מרדכי מסלונים","b":"חתן ר שרגא פייטל פיינשטין מסלונים. מצאצאי ר אריה ליב בעל הפרדס. אב\"ד יורבורג."},{"i":5568,"n":"אפשטין, אברהם יקותיאל מעיר חדש","f":"קלונימוס קלמן עפשטין","dt":"תקצג - כג תשרי","b":"רב בעיר חדש"},{"i":5569,"n":"אפשטין, אברהם מאיר מליסקוב","f":"אריה ליב בעל הפרדס","k":"בעל דברי ידידים","bt":"תפו","bp":"גרודנא","dt":"תקלב - ד אד\"א","dp":"נובומינסק","b":"אב\"ד ליסקוב-תקו, מעש(=מוש) חדש, נובו-מינסק-תקיב. תלמיד המגיד ממזריטש, ומקורב לר ישראל מפולוצק. היה מעורב במחלוקת בין ר יעקב עמדין ור יהונתן איבשיץ ותמך כאביו בר יהונתן. מתורתו ב\"גבורת הארי\" לר אפרים מרדכי אפשטין. חיבר פירוש לתלמוד יחד עם אביו בעל \"הפרדס\" והערותיהם לש\"ס נדפסו במהדורות התלמוד הבאות. מתורתו ב\"גבורת ארי\". בניו - ר אפרים מרדכי מקראסויא, ר אלכסנדר ממוש(=מאש) חדש, ר זאב מקאסווא, ר אברהם ממוש חדש."},{"i":5570,"n":"אפשטין, אברהם מאיר מסנאוו","f":"שאול מקוסוב וקוברין","k":"בעל אמרי נועם","bt":"תרה או תריד","b":"חתן ר גרשון תנחום ממינסק בעל \"אילנא דחיי\". רב בסנאוו-פלך מינסק-תרך או תרמא, לאהויסק(=לאהוסק)-פלך מינסק-תרנב. חיבר גם \"מנחה בלולה\". הניח חדושים בכת\"י. דודו-אחי אמו של החזון איש. חתנו - ר נחמן רבינוביץ-נכד הגדול ממינסק."},{"i":5571,"n":"אפשטין, אברהם מבריסק - הזקן","f":"מאיר הלוי מבריסק","dt":"שצט - תג","dp":"בריסק","b":"מצאצאי הרא\"ה מברצלונה ובעל המאור, נינו של ר נתן הלוי מפפד\"מ. אב\"ד הורדנא-שעו ור יצחק איזיק בן אברהם ור יהושע בעל \"מגיני שלמה\" על מקומו אחריו (האחד כאב\"ד והשני כראב\"ד), בריסק-שצד ור אברהם בן בעל \"משאת בנימין\" מטרנופול על מקומו אחריו, לובלין-שצט. נזכר ב\"בית חדש\", \"פני יהושע\" ובסידור \"אור הישר\" לר מאיר פפירש. חידוש ממנו בענין התפלה מבעל \"אור הישר\", ובספר \"יעיר אזן\". בנו ר יחיאל מיכל הלוי-רופא בלובלין וחתנו של ר מרדכי יפה בעל הלבושים."},{"i":5572,"n":"אפשטין, אברהם מווישינטי-ליטא","bt":"תרלד-ז","dt":"תרצט - טז תשרי","b":"רב בוישינטה על מקום ר יוסף חיים טרופ."},{"i":5573,"n":"אפשטין, אברהם מליטוביסק","f":"יוסף אלתר ממגרוב","bt":"תרם","dt":"תרץ","b":"רב בליטוביסק, חתן היהודי הטוב מניישטט."},{"i":5574,"n":"אפשטין, אברהם מסטופניץ","f":"חיים מאיר מניישטאט","k":"אדמור מניישטט","dt":"תרצג - כא תשרי","b":"מצאצאי בעל \"מאור ושמש\"."},{"i":5575,"n":"אפשטין, אברהם מסטנוב ראוונא ור","f":"מאיר הלוי","k":"בעל ברכת אברהם","b":"נכד ר אברהם מהורדנא ובריסק. מקובל. רב בראוונא, רכניץ-עד תף. מקורב לר שמשון ורטהיימר מוינה. נזכר ב\"פנים מאירות\" - תעח. בניו: ר נחמן מבאר, ר יצחק איזיק מסלוצק."},{"i":5576,"n":"אפשטין, אברהם שלמה","f":"יהודה אריה ליב מאוזר","k":"אדמור מאוזרוב","bt":"תרכה","dt":"תרעח - יא חשון","dp":"אפטא","b":"חתן ר חיים שמואל מחנטשין (שושלת לובלין). רב ואדמור באוז'ירוב, יוזפוף, במלחה\"ע ה-I ברח לאפטא. חיבר \"שארית ברכה\"."},{"i":5577,"n":"אפשטין, אהרן הלוי","bt":"ה'תרס-סג","dt":"תשג","b":"דומ\"צ בפרג","bk":[["כפי אהרן [שו\"ת]",""]]},{"i":5578,"n":"אפשטין, אהרן הלוי מפרג","f":"אפרים פישל","k":"בעל שארית אפרים","bt":"תרס - בערך","bp":"סטמר","b":"אביו נהרג במלחמת העולם ה-I. תלמיד ר אליעזר דוד גרינוולד מסטמר, ור חיים אלעזר שפירא ממונקטש. חתן ר אהרן צבי קסטנבוים מטיסא-אוילאק. מנהל ישיבה בבעלעניעש(=באלניש), מחכמי טאפלטשאן. רב בפרג-תרצא. נספה בשואה. חיבר גם \"מנוחת שבת\", ועוד."},{"i":5579,"n":"אפשטין, אהרן מקראקא","f":"קלונימוס קלמן מקראקא","k":"הו\"ל מאור ושמש","bt":"תקנה","dt":"תרמב - ז כסלו","b":"חתן ר ישראל מלובלין, רב בקראקא ומפיץ החסידות שם על מקום אביו. היה חסידו של ר שלמה מרדומסק. הדפיס את ספר אביו \"מאור ושמש\"."},{"i":5580,"n":"אפשטין, אליהו","dt":"תרצח - כט תמוז","b":"רב בבלפוריה"},{"i":5581,"n":"אפשטין, אליהו","b":"רב בטרענטשין"},{"i":5582,"n":"אפשטין, אליעזר יהושע מחמלניק","f":"אברהם שלמה מאוזרוב","bt":"תרנט","dt":"תשב","dp":"טרבלינקה","b":"חתן דודו ר יצחק שלמה גולדברג מזליחוב-חתן ר חיים שמואל מחנטשין. ראש ישיבה בקילץ, רב באפטא, ראקוב-פלך קיעלץ, חמלניק. נספה בשואה. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"דגל הרבנים\" - וארשא תרפו, \"הכרם\" - וארשא תרפז, \"הנשר\" - טירנוי תרצג-תשד, \"עמק הלכה\" - באטארקס תרפא, \"קובץ דרושים\" - פיעטרקוב תרפג, \"שערי חכמה\" - אוזרוב תרפד - בעריכת אחיו ר ישראל דוד."},{"i":5583,"n":"אפשטין, אליעזר מזאלושיץ","f":"חיים מאיר מניישטאט","k":"אדמור מניישטט זלושיץ","bt":"תרם","bp":"ניישטאט","dt":"תש..","b":"מצאצאי בעל \"מאור ושמש\". חתן ר יעקב משה מקומרנא. אדמור בניישטאט, עבר לזאלושיץ. נספה בשואה."},{"i":5584,"n":"אפשטין, אליעזר מזלוטשוב","f":"יחיאל מיכל אפשטיין","b":"רב בזלאטשוב(=זלוטשוב). בנו - ר יחיאל מיכל מנמירוב? (ובמקום אחר נזכר כחתנו ולא בנו)."},{"i":5585,"n":"אפשטין, אלכסנדר ממוש חדש","f":"אברהם מאיר מליסקוב","b":"מחכמי מוש חדש."},{"i":5586,"n":"אפשטין, אלכסנדר סנדר מוילנא","f":"שרגא פיבש","dt":"תרכג - יא אב","dp":"וילנא","b":"מו\"ץ וראש ישיבת מייליס בוילנא, בנו ר יצחק על מקומו אחריו."},{"i":5587,"n":"אפשטין, אלתר משה דוד מטשמילוב","f":"יהודה אריה ליב מאוזר","k":"אדמור מטמשילוב","dt":"תשב","b":"חתן ר מאיר שלום מקאלושין (שושלת פשיסחא). רב בטארלא, רב ואדמור בטשמילוב."},{"i":5588,"n":"אפשטין, אפרים הלוי מסלונים","k":"בעל גבורת הארי","b":"חיבר \"גבורת הארי\" - ובו לתולדות משפחת אפשטין."},{"i":5589,"n":"אפשטין, אפרים מבאקשט ונ\"י","f":"צבי חיים מבאקשט","bt":"תרלו","bp":"באקשט","dt":"תשכ","b":"נכד(-אבי אמו) ר חיים באקשטר (אבי משפחת באקשט בליטא), אחיו של ר משה מרדכי מסלובודקה. תלמיד ישיבת סלובודקא, ותלמיד ר יצחק בלזר. חתן ר ישראל אליהו איזראלוביץ מפלונגיאן. נסמך מאת: ר יחיאל מיכל אפשטין, ר אליהו ברוך קאמאי, הרידב\"ז. ראש ישיבה בסלוצק-תרנז אצל הרידב\"ז, רב בבאקשט-תרס על מקום אביו, היגר לניו יורק וכיהן כמנהל ישיבת \"תפארת ירושלים\" ורב קהלת \"זכרו תורת משה\", וקהלת אנשי זאמוט בניו יורק, שיקאגו-תרע. נשיא ועד הישיבות באמריקה. בראש משלחת רבנים-תשח לעזרת פליטי השואה. בנו אהרן דוד נהרג עק\"ה בחברון-תרפט."},{"i":5590,"n":"אפשטין, אפרים מקזלויטשינע","dt":"תשג","b":"רב בקזלוויטשינע"},{"i":5591,"n":"אפשטין, אפרים מרדכי מנוברדוק","f":"שלמה זלמן","k":"בעל מירא דכיא","b":"מצאצאי ר אברהם מאיר ממוש חדש. מחכמי נוברדוק. חיבר \"מחנה אפרים\", \"גבורות הארי\" לתולדות משפחת אפשטין, \"מירא דכיא\"."},{"i":5592,"n":"אפשטין, אפרים מרדכי מקאסווי","f":"אברהם מאיר מליסקוב","dt":"תקסח - ט טבת","b":"אב\"ד קאסווי(=קראסוויא)."},{"i":5593,"n":"אפשטין, אריה ליב מקניגסברג","f":"מרדכי מהורדנא","k":"בעל הפרדס","r":"אב\"ד קעניגסברג","bt":"תסח","bp":"גרודנא","dt":"תקלה - יג תמוז","b":"רב בברסטוביץ-תקא, הלינקן, קניגסברג-תקה והיה ממיסדי ביהכ\"נ הגדול שם. במחלקות בין ר יעקב עמדן ור יהונתן אייבשיץ עמד לצד ר יהונתן יחד עם בנו ר אברהם מאיר, חיבר פירוש לתלמוד יחד עם בנו והערותיהם לש\"ס נדפסו במהדורות התלמוד אחריהם. בניו: ר מרדכי מוילנא, ר יצחק מסלונים ווילנא, ר חיים, ר משה מטשסניק, ר שמואל אהרן מוילנא, ור אברהם מאיר. נחשב לאבי משפחת אפשטין (והסימן לצאצאיו - מי שאינו לוי אינו מהמשפחה המקורית). (לפי ברוורמן-אנשי שם - שם אביו ר צבי הירש מהורדנא).","bk":[["הפרדס",""],["אור השנים - סידור \\ ספר משנת גור אריה",""],["הלכה אחרונה וקונטרס הראיות",""],["הפרדס - מצות עשה יד, ופב",""],["הפרדס - מצות עשה יד, ופב, אור השנים - סידור \\ ספר משנת גור אריה, הלכה אחרונה וקונטרס הראיות",""]]},{"i":5594,"n":"אפשטין, אריה ליבוש מליעוו","b":"מו\"צ בלייעוו-תר\"כ"},{"i":5595,"n":"אפשטין, אריה ליבש הלוי מאוזרוב","dt":"תקצו - כג טבת","b":"אדמו\"ר הראשון באוז'רוב"},{"i":5596,"n":"אפשטין, בנימין","k":"בעל נחלת בנימין"},{"i":5597,"n":"אפשטין, בנימין וולף מהמבורג","dt":"תמד","b":"מגדולי חכמי דורו,רב בהמבורג, הנובר, פרידבורג-תמ"},{"i":5598,"n":"אפשטין, בנימין וולף סגל מלבוב","f":"יהודה","b":"ראב\"ד ור\"מ בלבוב, חתם-תמה, תסא, תסז, תשובה ממנו בשו\"ת \"אמונת שמואל\"."},{"i":5599,"n":"אפשטין, בצלאל משטוקהולם וארה\"ב","f":"יעקב אפשטין","bt":"תרלח","dt":"תרצח - ה אלול","b":"רב בשטוקהולם,סינסניטי"},{"i":5600,"n":"אפשטין, ברוך הלוי מפינסק","f":"יחיאל מיכל-ערוך השלח","k":"בעל תורה תמימה","bt":"תרך","bp":"בוברויסק","dt":"תשא","b":"נכד-אבי אמו ר יעקב ברלין ממיר-אביו של הנצי\"ב. תלמיד ישיבת וולוזין דודו הנצי\"ב מוולוזין (שהיה גם גיסו-בעל אחותו), חתן ר אלעזר משה הורביץ מפינסק, סירב לרבנות פינסק מוסקבה ופטרבורג, עבר לניו יורק-תרפה, והסכים שם על \"מעדנים\"-תרפד, חזר לאירופה ונספה בשואה. חיבר גם \"ברוך שאמר\", \"מקור ברוך\". פרסם מאמרים ב\"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז. נסמך מאת: הנצי\"ב, ר יוסף דב סולוביציק, ר חיים יהודה סאססניצער מסמרגון, ר רפאל שפירא מוולוזין."},{"i":5601,"n":"אפשטין, ברוך מקלימנטוב","b":"רב בקלימנטוב, דאמראווא-גורניטשא. פרסם מאמרים ב\"דגל הרבנים\" - וארשא תרפו, \"חדרי תורה\" - קראקא תרפו, \"הנצח\" - לבוב תרפז. עורך \"התפוח\" - בנדין תרפח."},{"i":5602,"n":"אפשטין, גרשון ממגרוב","f":"יוסף אלטר","bt":"תרך","dt":"תרף","b":"רב במגרוב-תרנד."},{"i":5603,"n":"אפשטין, דב בר הלוי מירושלים","f":"יחיאל מיכל-ערוך השלח","b":"מחכמי וילנא, גברי ישיבת \"עץ חיים\" בירושלים, גבאי בבית היתומים דיסקין בירושלים-תרפז."},{"i":5604,"n":"אפשטין, דוד הלוי מהאלוסק","f":"יצחק אייזיק","b":"מצאצאיו - ר יחיאל מיכל בעל \"ערוך השלחן\". אב\"ד ור\"מ בהלוסק-תקם. בנו ר מרדכי ונכדו ר יצחק איזיק מהומל. (באוצר מופיע פעם אחת בטעות כאביו של ר יצחק במקום זקנו)."},{"i":5605,"n":"אפשטין, דוד הלוי מוילנא","f":"שמעון זימל","dt":"תרלב - יח אד\"א","dp":"וארשא","b":"חתן ר יחזקאל לנדא ראב\"ד וילנא. אחיו של ר יודיל, ודודו-בן אחותו של ר אברהם בן יצחק ז\"ק מפטרבורג. חיבר חדושים על הרמב\"ם - בכת\"י. בנו ר איזיק מוילנא - החזיק בכתבי אביו."},{"i":5606,"n":"אפשטין, דוד שלמה מטאווריג","f":"צבי","b":"מצאצאי בעל \"נודע ביהודה\", חתן ר דוד שרשבסקי מטויראגען. מחכמי טאווריג(=טויראגען)-פלך קובנא."},{"i":5607,"n":"אפשטין, וולף מטיקטין","dt":"תצד - א טבת","b":"רב בטיקטין"},{"i":5608,"n":"אפשטין, זאב וולף הלוי מקאסווי","f":"אברהם מאיר מליסקוב","b":"מחכמי קאסווי."},{"i":5609,"n":"אפשטין, זיידל מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":5610,"n":"אפשטין, זליג ממונטריאול","b":"ר\"מ בישיבת מיר. עורך \"מרכז התורה\" - מונטריאול תשב, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":5611,"n":"אפשטין, זרח אפרים מירושלים","f":"ישעיה","bt":"תרלג","dt":"תרצא","dp":"ירושלים","b":"עלה לירושלים והתחנך בישיבת תורת חיים, וראש הישיבה ר יצחק וינוגרד לקחו חתן לאחותו. לימים נתמנה לראש הישיבה. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"הדביר\" - ירושלים תרעט, \"שערי ציון\" - ירושלים תרפא."},{"i":5612,"n":"אפשטין, חיים הלוי","f":"מרדכי","k":"ר חיים גיטקע טויבעס","dt":"תרי - כא חשון","b":"חתן ר אליעזר מליובטש-בן ר אריה ליב הקטן שפירא בעל \"נחלת אריאל\". מחכמי וילנא ר\"מ ומשגיח בישיבה בביהמ\"ד יסו\"ד. ומשגיח בישיבה שם, עלה לארץ."},{"i":5613,"n":"אפשטין, חיים ליב הלוי","k":"בעל פרי חיים","b":"רב בחאריזל,צ'זעווע,סוקולוב,קאלושין,סטאבישין-ת\"ר"},{"i":5614,"n":"אפשטין, חיים מאיר","f":"אליעזר הלוי מזלושיץ","dt":"תשמה","dp":"תל אביב","b":"נכד לאדמורי קומרנא-ניישטט."},{"i":5615,"n":"אפשטין, חיים מאיר מניישטאט","f":"קלונימוס קלמן מנישטט","k":"אדמור מניישטט","bt":"תרם","dt":"תרעד - ז טבת","b":"נינו של בעל \"מאור ושמש\". רב בעיר חדש-תר\"מ"},{"i":5616,"n":"אפשטין, חיים מניו יורק","f":"אבא יצחק","b":"מצאצאי בעל הפרד\"ס. אחיו של ר שלמה מניו יורק. חתן הגביר ר יעקב ורבלובסקי מניו יורק. הוריו עלו לירושלים (ואולי עלה עמם), היגר לארה\"ב והיה גביר בניו יורק - ויחד עם אחיו ר שלמה עסקו בעניני ציבור וצדקה והקימו ת\"ת בברוקלין."},{"i":5617,"n":"אפשטין, חיים מניישטט","k":"אדמור מניישטט","b":"אדמור בניישטט."},{"i":5618,"n":"אפשטין, חיים פישל מסייני ונ\"י","f":"דוד שלמה","k":"בעל תשובה שלמה","bt":"תרלד","bp":"טאווריג-ליטא","dt":"תשב - כ תמוז","b":"תלמיד זקנו ר דוד שרשבסקי מטויראגען(=טאווריג), זקנו - ר צבי, ר מאיר קעלמער מטויראגען. חתן ר ברוך נתנאל נייוויידל מטאווריג. נסמך מאת: ר שלמה הכהן מוילנא, ר משה מסלובודקא, ר שמעון דוד משדליץ, ר אלכסנדר משה לפידות מראסיין, ר מנדל זיו מטויראנגען. רב בהורזובה(=גרוזובה)-פלך מינסק-תרמח, סייני-פלך סובאלק-תרסח, דורפאט-תרעו ולימד באוניברסיטה שם פילוספיה ואתיקה, ליבאו-ארה\"ב, קליבלנד, סינסינטי, ניו יורק, סט לואיס. נשיא אגודת הרבנים האורטודוכסים באמריקה. חיבר \"חנוך לנער\" - בהיותו בן 16, ועוד. פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"הלבנון\" - סטמר תרפח, \"מגדל תורה\" - נ\"י תרפה, \"המגיד\" - סטמר תרפח, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז. חיבר \"חינוך לנער\" - בגיל 15, \"תשובה שלמה\", ועוד.","bk":[["תשובה שלמה [שו\"ת]",""],["מדרש החיים",""]]},{"i":5619,"n":"אפשטין, חיים צבי","r":"רב דבאקשט","bt":"תר","dt":"תרס - כט אדר","b":"ר\"מ בבאקשט","bk":[["שאלה ותשובה",""]]},{"i":5620,"n":"אפשטין, יהודה אריה ליב מאוזרו","f":"יחיאל חיים מאוזרוב","k":"אדמור מאוזרוב-ברכת ט","bt":"תקצז","dt":"תרעד - ז ניסן","b":"חתן ר שלום אליעזר מורגנשטרן משדליץ ופיעטרקוב, ובזיוו\"ש חתן ר אפרים פישל הכהן משטקטשין-חתן ר משה מללוב. תלמיד ר אלעזר מקוזניץ. רב בטארלא, אופולא, יוזפוף, חמלניק, אוזרוב, אליזבטגרד(=יליזבטגרד) ור חיים ברלין על מקומו אחריו. חיבר \"ברכת טוב\"."},{"i":5621,"n":"אפשטין, יהודה אריה ליב מאוזרוב","f":"יחיאל מיכל","k":"אדמור מאוזרוב אופולא","dt":"תקצז - כג טבת","b":"מצאצאי בעל \"קיצור של\"ה\". בזיוו\"ש חתן ר ראובן הלוי הורביץ מזרנובצא בעל \"דודאים בשדה\". תלמיד החוזה מלובלין, היהודי הקדוש מפשיסחא, ור מאיר מאפטא. רב באוזרוב-תקעב ואדמור-תקפז אחר פטירת ר מאיר מאפטא, רב ואדמור באופולא. תולדות ב\"לבת אש\". חתנו - ר מאיר יהושע מקלימנטוב."},{"i":5622,"n":"אפשטין, יהודה הלוי מורשא","f":"זימל","b":"גביר מחכמי ורשא, מכתב ממנו בפתח הספר 'שמן ששון' לר יצחק ששון מהורדנא."},{"i":5623,"n":"אפשטין, יהודה הלוי מיאלסטווגרד","b":"רב ביאלסטווגרד-תר\"ל"},{"i":5624,"n":"אפשטין, יהודה יודל מבריסק","f":"שמעון זימל","k":"בעל קנמון בשם","dt":"תרם - כ תשרי","dp":"וארשא","b":"אחיו של ר דוד הלוי. תלמיד ר טעבעלע אב\"ד מינסק. חיבר \"מנחת יהודה\" על כמה מסכתות - וארשא תרלז - ובו כותב את תולדותיו."},{"i":5625,"n":"אפשטין, יהודה ליווא סגל מלבוב","f":"יעקב","dt":"שצא - א אלול","dp":"לבוב","b":"מרביץ תורה, ראב\"ד בלבוב. חתם בשנת שמו עם ר יוסף קלמנקיש ור מרדכי אשכנזי מלבוב. חתם-תח בספר \"איתן האזרחי\" עם ר מרדכי בן הירש ור אהרן בן פנחס (וכנראה הוא רב אחר באותו השם - אולי נכדו)."},{"i":5626,"n":"אפשטין, יהושע חיים מוילנא","f":"מרדכי צבי מוילנא","k":"בעל חדושי רי\"ח","b":"חתן בנימין אוירבך בן יוסף בן יואל. גביר מחכמי וילנא. גבאי בית עקד הגרמ\"ש. בנו - ר מרדכי בעל \"שערי תודה\"."},{"i":5627,"n":"אפשטין, יהושע מקורטשין","f":"נחמן","k":"בעל קרן יהושע","bt":"תרטז","b":"מצאצאי ר אריה ליב אפשטין בעל הפרדס. תלמיד ישיבת איישישוק, כולל קובנא - היה אחת מעשרה המיסדים את הכולל ע\"י ר ישראל סלנטר ור יצחק אלחנן. רב בקארטשין-פלך גרודנא-תרמד. נסמך מאת ר יצחק אלחנן מקובנא, ר יצחק איזיק מסלובודקא, ר יהודה ליב מגרודנא."},{"i":5628,"n":"אפשטין, יוסף אליעזר מליטא","k":"בעל יד לזהב","bt":"תקפא","bp":"שאוולי","dt":"תרלה","b":"מחנך וסופר. חיבר גם \"דברי הימים למלכי רוסיה\", \"מרים החשמונאית\", ביוגרפיה על לינקולן - ב\"הכרמל\"."},{"i":5629,"n":"אפשטין, יוסף אלתר ממגרוב","f":"מרדכי מזידיטשוב","k":"בעל גנזי יוסף","bt":"תקצה","dt":"תרנט","b":"חתן ר יצחק אברהם וייס הי\"ד. רב במגרוב-תרל, אוזיראן-תרנד. חיבר \"גנזי יוסף\" מונקטש תרנה, ועוד."},{"i":5630,"n":"אפשטין, יוסף ברוך מניישטט","f":"קלונימוס קלמן-מאור ו","k":"היהודי הטוב מניישטאט","bt":"תקנב","dt":"תרכז - י אדר","b":"רב בניישטט, תלמיד החוזה מלובלין ועוד מגדולי האדמורים, בתחילה סירב לשמש כאדמור, כונה היהודי הטוב, והיה מקורבם של גדולי אדמורי דורו. בנו ר קלונימוס היה אדמור אחריו."},{"i":5631,"n":"אפשטין, יוסף דוד","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"היכל התורה\" - מיר-נוברדוק תרצה."},{"i":5632,"n":"אפשטין, יוסף דוד מסוקולוב","f":"אליעזר מזלושיץ","k":"אדמור מניישטט בסוקול","dt":"תש..","b":"מצאצאי בעל \"מאור ושמש\". חתן ר דודו מפשעצלא (רופשיץ). אדמור בחיי אביו. נספה בשואה."},{"i":5633,"n":"אפשטין, יוסף מוילנא","bt":"1873","bp":"אחוזת ראזלובקה-פלך פולטבה","dt":"1916","dp":"וילנא","b":"תלמיד ישיבות מיר, וילנא. פנה להשכלה ולמד רפואה. הצטרף לתנועה הציונית. יסד \"חדר מתוקן\" והיה ציר בקונגרס הציוני. עבר לוילנא והיה רופא ופעיל ציוני. יסד את הגמנסיה העברית הראשונה בוילנא (ובגולה)."},{"i":5634,"n":"אפשטין, יוסף מסטמר","f":"אפרים פישל אברהם","dt":"תש..","b":"אחיינו ר יוסף אלתר בעל \"גנזי יוסף\". תלמיד בעל \"ערוגת הבשם\". חתן ר שלום גולדנברג מסוואליווע. סופר סת\"ם במונקטש, רב בסטמר. נספה בשואה."},{"i":5635,"n":"אפשטין, יוסף מקיטוב","b":"רב בקיטוב-ת\"ר"},{"i":5636,"n":"אפשטין, יוסף מקיטוב","f":"אליעזר דב","bt":"תקמה","dt":"תרי","b":"אב\"ד קיטוב-תרח. חתן ר נחמן צבי אבד קולומיאה."},{"i":5637,"n":"אפשטין, יחזקאל איזידור","bt":"1894","bp":"קובנא","b":"תלמיד ישיבת פרשבורג, היגר לאנגליה-1911 ולמד בביהמ\"ד היהודי למורים בלונדון. מרצה לשפות שמיות וספרן בביהמ\"ד היהודי בלונדון. רב במידלסבורו. ערך תרגום אנגלי לתלמוד בבלי - לונדון 1935, קובץ באנגלית לזכר הרמבם. ספר היובל לכבוד הרב הראשי לאנגליה ר י.צ. הרץ - לונדון 1944."},{"i":5638,"n":"אפשטין, יחיאל חיים מאוזרוב","f":"יהודה אריה ל' מאוזרב","k":"אדמור מאוזרוב","bt":"תקף","dt":"תרמח - ח תמוז","b":"חתן ר אברהם שלמה מוולאדובה. תלמיד ר ישכר בער מרדושיץ, ור אברהם מטריסק. רב באופולא-בגיל 17 על מקום אביו, אפטא רב ואדמור באוז'רוב-תר."},{"i":5639,"n":"אפשטין, יחיאל מיכל מלובלין","f":"אברהם מבריסק","k":"בעל קיצור של\"ה","b":"חתן ר מרדכי יפה בעל הלבושים. רב ורופא בלובלין. חתנו - ר אברהם הלפרין מקאוולע."},{"i":5640,"n":"אפשטין, יחיאל מיכל מנוברדוק","f":"אהרן הלוי","k":"בעל ערוך השולחן","bt":"תקפט-ץ","bp":"בוברויסק","dt":"תרסח - כב אד\"ב","dp":"נווהרדוק","b":"חתן ר יעקב ברלין-אבי הנצי\"ב. רב בנובוזיבקוב-בקהלה שרובה חסידים, נוברדוק(=נווהארדוק)-תרלג על מקום ר ברוך מרדכי ליפשיץ ור מנחם קרקובסקי על מקומו אחריו, ועמד בראש ישיבה שם. ספריו נדפסו ע\"י בתו בריינה ואלאברינסקא. חיבר גם \"אור לישרים\", ועוד. מתורתו ב\"מאסף דרושי\" - וילנא תרסט. בניו ר ברוך מפינסק בעל \"תורה תמימה\", ר דב בער מוילנא וירושלים. (חתנו - הנצי\"ב מוולוזין??? כך אצל מרקוביץ - נוברדוק), ר משה צבי ולברינסקי בעל \"שאל וענה\"."},{"i":5641,"n":"אפשטין, יחיאל צבי הירש מאוזרוב","b":"פרסם מאמרים ב\"שערי חכמה\" - אוזרוב תרפד."},{"i":5642,"n":"אפשטין, יעקב","dt":"תשג","b":"רב בסובאט"},{"i":5643,"n":"אפשטין, יעקב הלוי","f":"משה עפשטיין","b":"רב בלאמאז-תר\"כ"},{"i":5644,"n":"אפשטין, יעקב הלוי מסלוצק","f":"יצחק אפשטיין","dt":"תקנא - יד שבט","b":"ראש מדינה בסלוצק"},{"i":5645,"n":"אפשטין, יעקב מארה\"ב","b":"רב בדולוט-מיניסוטה(ארה\"ב)-תר\"נ"},{"i":5646,"n":"אפשטין, יעקב מוארשא","bt":"תקלא","dt":"תרג","dp":"ורמברוגנן - וארשא","b":"גביר ופרנס בוארשא, יסד בית חולים."},{"i":5647,"n":"אפשטין, יעקב משובאט","f":"אליהו דוד","k":"בעל בית יעקב","b":"נכד ר מרדכי רוזנלבט מסלונים. אב\"ד בשובאט(=שובאץ)-לטביה-תרצג."},{"i":5648,"n":"אפשטין, יעקב קופל","f":"ראובן","bt":"תקצח","b":"רב במעליטאפול-פלך טאיירי-תרכז, נעטשיוויעווקא-פלך יקטרינסלב-תרכט, מאריומפאל(=מאריופאל)-פלך יקטרינסלב-תרל."},{"i":5649,"n":"אפשטין, יצחק איזיק מהומל","f":"מרדכי בן דוד","k":"בעל עשרה מאמרות","bt":"תקם","dt":"תרטז - כו אייר","b":"תלמיד בעל התניא, בנו ר דב בער, וחתנו ר מנחם מנדל. סירב לאדמורות. רב בהומל-תקסה. חיבר גם \"חנה אריאל\", \"מאמר שני המאורות\". תולדותיו ב\"תולדות יצחק איזיק\"."},{"i":5650,"n":"אפשטין, יצחק איזיק ממארמרוש","f":"יוסף מסטמר","dt":"תש..","b":"רב בפטריווה-מארמרוש-לפני השואה. נספה בשואה."},{"i":5651,"n":"אפשטין, יצחק איזיק מסלוצק","f":"אברהם מסטנוב וראוונא","b":"רב בסלוצק-תק. בנו - ר נפתלי הירש מיאנוב ואלטונא."},{"i":5652,"n":"אפשטין, יצחק איזיק מפעטראווא","dt":"תשד","b":"רב בפעטראווא"},{"i":5653,"n":"אפשטין, יצחק הלוי מקולומיאה","f":"נחמן צבי מבאר","bt":"תץ","dt":"תקנה - ג אדר","b":"אביו היה ידידו של הבעשט (ובעירו באר היה נהוג שלא לומר לכה דודי משבת בראשית עד פסח - לזכר הנס שהציל את העיר). רבה של קולומיאה. חתנו של ר משולם רבה של קולומיאה וירש את כסאו. בנו ר נחמן צבי ישב על כסאו אחריו."},{"i":5654,"n":"אפשטין, יצחק הלוי מתל אביב","dt":"תשכט","b":"דיין בתל אביב. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"שילה\" - ירושלים תשה, \"תבונה\" - ירושלים תשא."},{"i":5655,"n":"אפשטין, יצחק זאב מקולומיאה-ב","f":"נחמן צבי מקולומיא","bt":"תקלה","dt":"תרט - טו חשון","b":"רב בקולומיאה-תקץ על מקום אביו."},{"i":5656,"n":"אפשטין, יצחק ליב מניו יורק","bt":"תרמג","dt":"תרצח - ט אב","b":"מרבני ניו יורק-תרס\"ו"},{"i":5657,"n":"אפשטין, יצחק מוילנא","f":"אלכסנדר סנדר מוילנא","dt":"תרמב - א טבת","dp":"וילנא?","b":"נכד ר יצחק אפשטין. ראש ישיבת מייליס בוילנא על מקום אביו."},{"i":5658,"n":"אפשטין, יצחק מסלונים","f":"אריה ליב בעל הפרדס","b":"רב בסלונים. בניו - ר מרדכי מסלונים, ר אברהם ונכדו ר מאיר משניפישוק. אחיו - ר אברהם מאיר ממוש חדש, ר מרדכי מוילנא."},{"i":5659,"n":"אפשטין, יצחק משלוניקי","b":"מנהל חינוכי של ביה\"ס ת\"ת בשלוניקי-תרע, בעברית וברוח המסורת."},{"i":5660,"n":"אפשטין, יצחק משלוניקי","b":"מנהל בית הספר ת\"ת בשלוניקי-תרס, ושלח כמה מבוגריו ללימודי המשך בירושלים. היה במחלוקת עם הרב הראשי ר יעקב מאיר בקשר ליחס ליוונים בשלוניקי, ועל רקע זה התפטר ועזב את שלוניקי-תרעג."},{"i":5661,"n":"אפשטין, יצחק נעכעס","b":"רב בהורדנא-תק\"פ"},{"i":5662,"n":"אפשטין, יצחק שמעון הלוי","dt":"תרל - לפני","b":"מו\"צ בוילנא בזמן כהונת ר יחזקאל לנדא כראב\"ד."},{"i":5663,"n":"אפשטין, יקותיאל זלמן סגל מלבוב","f":"מאיר אפשטיין","b":"דיין בלבוב, חתם-תץ עם ר יהושע פאלק שור, ר שמריה הורביץ ועוד."},{"i":5664,"n":"אפשטין, ישעיה","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"תבונה\" - ירושלים תשא-תשח."},{"i":5665,"n":"אפשטין, ישעיה מביאליסטוק וירוש","b":"מרביץ תורה בביאליסטוק,עלה לירושלים-תרמ. בנו - ר פנחס-ראב\"ד העדה החרדית."},{"i":5666,"n":"אפשטין, ישראל דוד הלוי מאוזרוב","f":"אברהם שלמה מאוזרוב","b":"רב באוסטרובצה-פלך קיעלץ. עורך \"שערי חכמה\" - אוזרוב תרפד."},{"i":5667,"n":"אפשטין, ישראל מפאפא","b":"דומ\"צ בפאפא-תקצ\"ט"},{"i":5668,"n":"אפשטין, לואי מ.","bt":"1887","bp":"אניקשט-ליטא","dt":"1949","b":"היגר לארה\"ב-1904, מוסמך לרבנות במכון היהודי התיאולוגי בנ\"י. רב ריפורמי בקהלות שונות. ומדריך לפילוסופיה באוניב' של טולידו-ארה\"ב. נשיא אסיפת הרבנים באמריקה-1918. פרסם בכתבי עת מדעיים שונים בנושאים יהודיים."},{"i":5669,"n":"אפשטין, מאיר הלוי","b":"נכד ר אברהם מהורדנא ובריסק. מחכמי דורו-ת\"ב. בנו - ר אברהם מסטנוב ראוונא ורכניץ."},{"i":5670,"n":"אפשטין, מאיר הלוי שניפישקר","f":"אברהם מטולטשין","k":"מאיר שניפישקער","dt":"תריא - יד אד\"א","b":"חתן ר שמואל בן יצחק משניפישוק, ונקרא שניפישקער ע\"ש שהיה שנים אצל חותנו בשניפישוק, ובזיוו\"ש חתן ר שמואל אהרן בן הפרד\"ס מקניגסברג. תלמיד ר ישראל אנטקאליער בשניפישוק. דיין בוילנא-תקעט, רב ודרשן בקופישוק ומגיד על מקום ר אברהם הוראדנער. הסכים על \"מדרש כונן\"-תקצג, ועוד. חיבר דרשות, ופירוש לתורה ועוד - בכת\"י, והיו אצל בנו ר שאול אב\"ד קאסאווי - ואבדו בשריפה בקאסאווי."},{"i":5671,"n":"אפשטין, מאיר מהורדנא","f":"מרדכי","dt":"תקצד - ה חשון","dp":"הורדנא","b":"מחכמי הורדנא."},{"i":5672,"n":"אפשטין, מאיר סגל","f":"יחיאל עפשטיין","b":"רב בבריסק-ת\"מ"},{"i":5673,"n":"אפשטין, מאיר סגל","b":"מחכמי דורו-ש\"פ"},{"i":5674,"n":"אפשטין, מאיר שמחה","f":"יצחק זאב אפשטין","dt":"תרה - כד אלול","b":"רב בקולומיי"},{"i":5675,"n":"אפשטין, מנחם מנדל","dt":"תשג","b":"רב בפארצווע"},{"i":5676,"n":"אפשטין, מנחם מנדל מטבריה","f":"מרדכי ממינסק","b":"עלה לארץ-תקצד, ראש \"כולל רייסין\" בטבריה."},{"i":5677,"n":"אפשטין, מנחם נחום מקוברין","f":"יהודה ליב","k":"אדמור מקוברין","bt":"תרו","dt":"תרעח - א אב","b":"תלמיד ר אברהם האדמור מסלונים. אדמור בקוברין-תרמד, עבר לביאליסטוק-תרנו."},{"i":5678,"n":"אפשטין, מרדכי הלוי מהורדנא","f":"יהושע מוילנא","dt":"תקמז - ל כסלו","dp":"הורדנא","b":"מראשי קהלת הורדנא. בניו - ר אריה ליב בעל הפרדס, ר צבי הירש מהורדנא (יש אומרים שר' אריה ליב היה נכדו). (תאריך פטירתו אינו מסתדר)."},{"i":5679,"n":"אפשטין, מרדכי הלוי מהורדנא","f":"צבי הירש","dt":"תקפב - כ שבט","dp":"הורדנא","b":"חתן ר נתן מפרען בעל אבן בחן. מחכמי הורדנא. דודו - הרב מקניגסברג."},{"i":5680,"n":"אפשטין, מרדכי הלוי מוילנא","f":"אריה ליב בעל הפרדס","k":"מרדכי גיטקע טויבעס","bp":"וילנא","dt":"תקסט - ז כסלו","b":"נקרא על שם אשתו שהיתה חוכרת רחוב בוילנא שנקרא על שמה. נקבר לצד ר אברהם בן הגר\"א ומצבה אחת על קברם. חתנו ר שמחה מטרוקי בן משה."},{"i":5681,"n":"אפשטין, מרדכי יצחק משפילד","b":"פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":5682,"n":"אפשטין, מרדכי מאוזיראן","f":"יוסף אלטר","bt":"תרל","dt":"תרץ","b":"ראב\"ד אוזיראן על כסא אביו. חתנו הרב פענער ישב על כס הרבנות אחריו."},{"i":5683,"n":"אפשטין, מרדכי מוטל מלודז","f":"חיים מאיר מניישטאט","k":"אדמור מניישטט","dt":"תש..","b":"מצאצאי בעל \"מאור ושמש\". נספה בשואה."},{"i":5684,"n":"אפשטין, מרדכי מוילנא","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":5685,"n":"אפשטין, מרדכי מוילנא","f":"יהושע חיים-חדושי ריח","k":"בעל שערי תודה","bt":"תרד","dt":"תרעו - כו תמוז","dp":"וילנא","b":"גביר מחכמי וילנא, ועסקן צבור. חיבר גם \"מאמר מרדכי\" - נדפס בסוף ספר אביו."},{"i":5686,"n":"אפשטין, מרדכי מלודז","f":"קלונימוס קלמן מנישטט","b":"נינו של בעל \"מאור ושמש\". רב בלודז."},{"i":5687,"n":"אפשטין, מרדכי מסלונים","f":"יצחק מסלונים","b":"דיין ומו\"ץ בסלונים. בנו - ר אברהם יצחק מיורבורג."},{"i":5688,"n":"אפשטין, מרדכי צבי הלוי מוילנא","f":"יהודה ליב בן יהושע","dt":"תקצט - יז סיון","b":"גביר מחכמי וילנא. בנו - ר יהושע חיים מוילנא בעל \"חדושי רי\"ח\"."},{"i":5689,"n":"אפשטין, משה הלוי מקוברין","b":"רב בקוברין-תק\"צ"},{"i":5690,"n":"אפשטין, משה יחיאל מאוזרוב","f":"אברהם שלמה מאוזרוב","k":"אדמור מאוזרוב","r":"אדמו\"ר מאוז'רוב","bt":"תרן","bp":"אוזרוב(=אוזירוב)","dt":"תשלא - א שבט","b":"חתן ר עמנואל מפבניץ-לודז (שושלת פשדבורז), ובזיוו\"ש חתן ר מנחם מנדל טננבוים מוריזבניק. אדמור בפאביניץ, אוזרוב, ואוטואצק, היגר לארה\"ב-תרפו, עלה לארץ-תשיג והתישב בתל אביב. חיבר \"אש דת\" תל אביב תשיד, ועוד. בנו ר אברהם שלמה - נפטר על פניו.","bk":[["אש דת",""],["באר משה - עה\"ת",""],["באר משה (אוז'רוב)",""],["באר משה",""]]},{"i":5691,"n":"אפשטין, משה מירושלים","f":"ישעיה אפשטין","bt":"תרמ","dt":"תשטו - ב אלול","b":"מרביץ תורה,ר\"מ בתורת חיים בירושלים-תרצ\"א"},{"i":5692,"n":"אפשטין, משה מפפד\"מ","b":"מחכמי פפד\"מ-שכה, תמך אך לא חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ - בגלל שיש לו שייכות בדבר."},{"i":5693,"n":"אפשטין, משה מקלצק","dt":"תשג","b":"רב בקלצק"},{"i":5694,"n":"אפשטין, משה מקרוטושין","f":"צבי הירש","bt":"תרן","dt":"תשב","b":"חתן ר אשר רובין מקורטשין, ושימש שם כדיין. נספה בשואה."},{"i":5695,"n":"אפשטין, משה מרדכי מחברון","f":"צבי חיים","k":"בעל לבוש מרדכי","r":"ראש ישיבת חברון","bt":"תרכו-ז","bp":"באקשט-ליד וולוזין","dt":"תרצד-ה","dp":"ירושלים","b":"חתן הגביר ר פיבל פראנק. למד בוולוזין, בשנת תרנד ראש ישיבת סלובודקה עם המייסד ר נתן צבי פינקל, ביקר בארץ-תרן וקנה קרקע באזור שעליו הוקמה חדרה. רב בסלובודקה, נדד בזמן מלחה\"ע ה-I למינסק ולקרמנצוג, חזר לסלובודקה-תרף, יצא בשליחות לאמריקה לטובת הישיבה. ובשנת תרפד החל להעביר את הישיבה לחברון עלה-תרפו עם הישיבה לחברון, ולאחר פרעות תרפט עברו לירושלים. בשליחות בארה\"ב-תרפד. חיבר \"לבוש מרדכי\" ורשה תרסא, ועוד. היה חבר במועצת גדולי התורה של אגו\"י. מתולדותיו ב\"הגאון ר משה מרדכי\" לר ישראל דבורץ. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"קול תורה\" - ירושלים תרץ, \"שערי ציון\" - ירושלים תרפא, \"תבונה\" - קובנא תרפא. חתניו - ר יחזקאל סרנא, ר אהרן כהן, ר משה חברוני - ראשי ומנהלי ישיבת חברון בירושלים, ה\"ה ירושלמי, ר משה סקארוטע מסלובודקא הי\"ד - נספו בשואה.","bk":[["לבוש מרדכי","מפרשי ש\"ס - אחרונים"],["לבוש מרדכי","שו\"ת - אחרונים"],["לבוש מרדכי – ש\"ס ושו\"ת",""]]},{"i":5696,"n":"אפשטין, משלם","f":"ישעיה","dt":"תקו - יז תשרי","b":"רב בקולומייא"},{"i":5697,"n":"אפשטין, משלם הלוי","f":"נחמן צבי עפשטין","dt":"תקעט - ו טבת","b":"רב בפיסטין"},{"i":5698,"n":"אפשטין, משלם זעמל הלוי מפפד\"מ","b":"כנראה אחיו של ר נתן-רבה של פפד\"מ. שתדלן מחכמי פפד\"מ וממנהיגי הקהילה."},{"i":5699,"n":"אפשטין, משלם מפיסטין","f":"נחמן צבי","bt":"תקם","dt":"תקעט","dp":"קולומיאה","b":"רבה של פיסטין."},{"i":5700,"n":"אפשטין, נחמן הלוי מבאר","f":"אברהם מסטנוב וראוונא","dt":"תצה","b":"רב בבאר."},{"i":5701,"n":"אפשטין, נחמן צבי הלוי מקולומיא","f":"יצחק מקולומיא","bt":"תקי","dt":"תקץ - כח תשרי","b":"נכד ר נחמן צבי מבאר. נבחן בילדותו ע\"י הבעשט, חבר של \"בעל הקצות\". תלמיד ר יצחק שור בעל \"כח שור\". רב בקולומיא על מקום אביו-תקנה, ובנו ר יצחק זאב על מקומו אחריו. עוד מבניו: ר משולם אב\"ד פיסטין. חתניו ר יוסף מקיטוב, ר מנחם מנדל רוזן, ור גדליה אביש בלוך מדלטין. באשל אברהם מבוצאץ מביא דבר תורה ממנו בשם הבעשט."},{"i":5702,"n":"אפשטין, נפתלי הירש מיאנוב","f":"יצחק מסלוצק","dt":"תצב - י חשון","dp":"אלטונא","b":"רב ביאנוב, אלטונא."},{"i":5703,"n":"אפשטין, נתן","b":"רב במגנצא"},{"i":5704,"n":"אפשטין, נתן דוד מניישטאט","f":"חיים מאיר מניישטאט","k":"אדמור מניישטט","dt":"תשא - ה אלול","b":"רב בניישטט-תר\"נ. מצאצאי בעל \"מאור ושמש\". חתן ר שמואל אליהו מזוואלין (קוזמיר)."},{"i":5705,"n":"אפשטין, נתן הלוי","b":"רב בהורדנא,בריסק,לובלין-ש\"צ"},{"i":5706,"n":"אפשטין, נתן הלוי מפפד\"מ","f":"יעקב צום שטורקה","b":"תלמיד ר שלמה שאטן, ולפי \"לקט יושר\" היה תלמיד ר זלמן שטרן, ר מנחם בכרך ור פיבוש מקלן. מגדולי חכמי דורו, רב בפפד\"מ-קן, ור שמעון הכהן על מקומו אחריו-רך. נאלץ לעזוב את פפד\"מ עם אחיו ר שלמה בשנת רב וחזר-רז. השתתף באסיפת רבנים בבינגן בראשות הרב זליגמן מבינגן, ושם התנגד להחלטה שנתקבלה והצטרפו אליו ר משה מינץ, ר פיבש מקלן, ועוד - עד שנתבטלה ההחלטה. השיב לשאלת ר משה מינץ וחבריו בנוגע לגט - עם חבריו ר אנזלם, ור זנויל. נכדו-בן בתו - ר נתן בן אהרן אפשטין הפרנס. לפי מסורת משפחת אפשטין - ערוך השלחן ובנו רב ברוך בעל \"תורה תמימה\" הם ובני משפחת אפשטין צאצאי ר נתן ויש אומרים שזהו ענף אחר."},{"i":5707,"n":"אפשטין, עזריאל מקרקלאן","bt":"תרכא","dt":"תרצח - א תמוז","b":"שקדן,רב פעלים,רב בקרקלאן,שיקאגו-תרנ\"ח"},{"i":5708,"n":"אפשטין, פיבל מירושלים","f":"מרדכי משה-ראש ישיבת","b":"מזכיר ישיבת חברון-תרצו (בראשות אביו)."},{"i":5709,"n":"אפשטין, פנחס מירושלים","f":"ישעיה","k":"בעל אוריין תליתאי","r":"ראב\"ד העדה החרדית בי-ם","bt":"תרמז","bp":"גרייבה","dt":"תשל - יח טבת","dp":"ירושלים","b":"עלה לירושלים-תרסה. ראב\"ד לעדה החרדית בירושלים-תרפט. חיבר גם \"מנחה חריבה\". פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"בית ועד לחכמים\" - סטמר תרפב, \"בית ישראל\" - לודז תרץ, \"דברי תבונה\" - קובנה תרף, \"דגל התורה\" - וארשא תרפב, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"כרם בית שמואל\" - פיעטרקוב תרצא, \"הפוסק\" - תל אביב תש-תשיד, \"קהילת יעקב\" - זבארוב-סלובקיה תרפה, \"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\", \"שערי ציון\" - ירושלים תרפא, \"תבונה\" - קובנא תרפא, \"תבונה\" - ירושלים תשא, \"תלפיות\" - נ\"י תשד.","bk":[["אוריין תליתאי - ענינים",""],["מנחה בלולה - שו\"ת",""],["מנחת ירושלים – מנחה חריבה",""],["תעלומות עין - הערות והגהות על ספריהם של גדולי המחברים",""]]},{"i":5710,"n":"אפשטין, פנחס מקיטוב","f":"יוסף","bt":"תקע","dt":"תרכא - כא אייר","dp":"קולומיאה","b":"רב בקיטוב על כסא אביו. חתנו של ר יוסף ראט. (??? ישועות ישראל - ממנו או שמוזכר בו)."},{"i":5711,"n":"אפשטין, צבי","b":"רב-שנת תר\"מ"},{"i":5712,"n":"אפשטין, צבי הירש מהורדנא","f":"מרדכי","dt":"תקכח - ה אלול","dp":"הורדנא","b":"רב בהורדנא, הסכים בעיר זעלווא-תקכח על ספר הפרדס לאחיו ר אריה ליב מקניגסברג (ויש אומרים שלא היה אחיו אלא אביו). בנו - ר אריה ליב מקניגסברג. (ברוב הרשימות שמו של אביו של ר אריה ליב הוא מרדכי ולא צבי הירש)."},{"i":5713,"n":"אפשטין, צבי הירש מנמירוב","bt":"תרם","dt":"תש","b":"חתן ר יעקב בן ציון וייס מסיגט. רב וראש ישיבה בנמירוב-תרסד, בנו ר משה רב לצדו ובנו ר מרדכי רב בוישובה. נספה בשואה."},{"i":5714,"n":"אפשטין, צבי חיים מבאקשט","bt":"תר","bp":"סלוצק","dt":"תרסח או תרס","dp":"באקשט - איוויע","b":"תלמיד ר יוסף דב סולוביציק בישיבת וולוזין, ונסמך ממנו ומאת הנצי\"ב. חתן הגביר ר שמעון יצחק איזיק בלוך (ממשפחת ר חיים באקשט). רב בבאקשט. בניו: ר משה מרדכי-ראש ישיבת חברון, ר אפרים מניו יורק. (לפי תולדות אנשי שם ניו יורק - היה אחיו הגדול של ר משה מרדכי ולא אביו)."},{"i":5715,"n":"אפשטין, קלונימוס קלמן מניישטאט","f":"יוסף ברוך מניישטאט","k":"אדמור מניישטט","dt":"תרסג - ט טבת","b":"גדול בנגלה ונסתר,רב ואדמו\"ר בעיר חדש-תרכח. בנו ר מרדכי - רב בלודז."},{"i":5716,"n":"אפשטין, קלונימוס קלמן מקראקא","f":"אהרן הלוי","k":"בעל מאור ושמש","r":"שלחן ערוך של תורת החסידות","bt":"תקיא","dt":"תקפג - א תמוז","b":"גדל בקראקא, חתן ר מרדכי גוטגולד. התקרב לחסידות בהשפעת הנועם אלימלך שביקר שם. ומאז היה לתלמידו, תלמיד גם של החוזה מלובלין. היה רב חסידי בקראקא והראשון למפיצי החסידות בקראקא בהוראת רבו-תקמה, והיה מחלוקת כנגדו, נאלץ לעבור לזמן מה לניישטאט. היה מיודד עם גדולי האדמורים בדורו. תלמידו ר ישראל הלל ווסטרייך מגריבוב כתב את ספר רבו \"מאור ושמש\". מתולדותיו ב\"יד מאור ושמש\".","bk":[["מאור ושמש - עה\"ת ומועדים",""]]},{"i":5717,"n":"אפשטין, ראובן","dt":"תשג","b":"רב באוזרוב"},{"i":5718,"n":"אפשטין, שאול הלוי מקוברין","f":"מאיר עפשטין","bt":"תקפט","dt":"תרנב - כא תשרי","dp":"קוברין","b":"רב בקאסובה, קוברין. בנו ר אברהם מאיר מסנאוו בעל \"אמרי נועם\". חתנו ר חיים שור ונכדו ר אליהו יעקב דב שור מזופרן בעל \"נטיעות חיים\"."},{"i":5719,"n":"אפשטין, שלמה הלוי מלענטשא","f":"יעקב אפשטין","b":"רב בלענטשנא"},{"i":5720,"n":"אפשטין, שלמה זלמן מירושלים","b":"מראשי כולל חב\"ד בירושלים, חתם-תרכו על כתב שליחות ר נתן נטע נאטקין."},{"i":5721,"n":"אפשטין, שלמה מאושפיצין","f":"חיים סגל","bt":"תרסה","bp":"אושפיצין","dt":"תש..","b":"תלמיד ר יעקב דוד בורנפריינד, ולמד גם בטשבין. מחכמי אושפצין-תרץ. הקים ישיבת בובוב ביסלו. נספה בשואה. תשובה אליו ב\"בית פנחס\"."},{"i":5722,"n":"אפשטין, שלמה מטארלא","dt":"תשג","b":"רב בטארלע"},{"i":5723,"n":"אפשטין, שלמה מניו יורק","f":"אבא יצחק","bt":"תרכו","bp":"פוניביז","b":"מצאצאי בעל הפרד\"ס. תלמיד ר יוסף דובר ויצמין בוארשא. עלה לירושלים עם הוריו ועסק במסחר ספרים. חתן ר מרדכי צבי שמאלצינסקי מקאלואריא. הו\"ל \"דער ארץ ישראל איד\" והיה ממיסדי בית עקד ספרים בירושלים. פרסם ב\"הצפירה\", ועוד. היגר לארה\"ב ועסק במסחר ספרים ועסק בצרכי ציבור בניו יורק עם אחיו הגביר חיים אפשטין והקימו ת\"ת בברוקלין. הניח מאמרים וכתבים בכת\"י."},{"i":5724,"n":"אפשטין, שמואל אהרן","f":"אריה ליב בעל הפרדס","dt":"תקפו - ה שבט","dp":"הנובר","b":"חתן ר וולף בן ר נחום שמש מוילנא. נתקבל לרב בקניגסברג, נפטר בהנובר בדרכו לרבנות קניגסברג."},{"i":5725,"n":"אפשטין, שמואל אליהו מניישטאט","f":"נתן דוד הלוי מניישטט","k":"אדמור מניישטט ארה\"ב","bt":"תרנב","bp":"זוואלין-פולין","dt":"תשמג - יט חשון","b":"מצאצאי בעל \"מאור ושמש\". תלמיד ר יהושע פלאטא מניישטאט. אדמור בקילץ, היגר לארה\"ב-תרפח. מניישטאט בארה\"ב."},{"i":5726,"n":"אפשטין, שמואל הלוי מפאהאר","f":"יצחק","bt":"תרי","b":"רב בפאהאר-פלך צרניגוב-תרנג."},{"i":5727,"n":"אפשטין, שמואל נפתלי הירש מגירט","f":"מנחם אריה ליב","k":"בעל אמרי שפר","b":"רב בגירטיגולה(=גירטגאלי)-תרכ על מקום ר יהודה ליב אופנהיים. בנו ר מרדכי יצחק לוין-אפשטין בעל \"תכלת מרדכי\". חתנו - ר שלמה גורדון בעל \"בנין שלמה\"."},{"i":5728,"n":"אפשטין, שמעון זימל מוילנא","f":"יחיאל מיכל","dt":"תרטו - כט חשון","dp":"וארשא","b":"נכד ר זכריה מנדל מבלז בעל \"באר היטב\". חתן ר יעקב גראייעווער מסלונים. גביר בוארשא. בניו: ר דוד מוילנא, ר יודל בעל \"מנחת יהודה\"."},{"i":5729,"n":"אצבאג, ברוך ממכנאס","b":"מו\"ץ במכנאס, חתם-תריט על איגרת לרבני פאס עם ר רפאל מסעוד ן מוחא ור שמואל יעקב בטאן."},{"i":5730,"n":"אצבאג, חיים ממגאדור","b":"מחכמי מוגאדור-מרוקו-שנות ה-תק'."},{"i":5731,"n":"אצבאג, יצחק מפאס","f":"אברהם","b":"מחכמי פאס-תעז, התכתב עם היעב\"ץ, חתם על פס\"ד-תעו עם ר יהודה ן צור."},{"i":5732,"n":"אצבאן, אברהם","f":"זבולון"},{"i":5733,"n":"אצבאן, אברהם ממכנאס","f":"יצחק","b":"מחכמי מכנאס, חתם-תקלא על אגרת לפטירת מהרי\"ט. מתורתו בלקוטי חדושים-כת\"י. חיבר ספר דרשות. בנו - ר יצחק."},{"i":5734,"n":"אצבאן, אברהם ממכנאס-מרוקו","f":"סלימן","b":"מחכמי מכנאס-תפה, חתם עם ר אליעזר בהלול בשנים - תפה-תקכא."},{"i":5735,"n":"אצבאן, ברוך מפאס","f":"מרדכי","b":"מחכמי פאס-שנות ה-ת'. נכדו - ר אברהם."},{"i":5736,"n":"אצבאן, חיים אברהם ממכנאס","f":"דוד בן מרדכי","b":"מקובל, דרשן, מחכמי מכנאס."},{"i":5737,"n":"אצבאן, יעקב מאלגיר","b":"רב בתלמסאן-שנות ה-תק' (דור רביעי ממנו חי בשנת-תרא)."},{"i":5738,"n":"אצבאן, יעקב מירושלים","b":"מחכמי ישיבת \"כנסת ישראל\" בירושלים-תקיח. (אולי הוא שהיה רב באלגיר)."},{"i":5739,"n":"אצבאן, יצחק ממכנאס","f":"מרדכי","k":"בעל כבוד אלקים","b":"מחכמי מרוקו אולי מכנאס, חתם על פס\"ד-תפו, חתם עם ר משה בירדוגו-המשבי\"ר. בנו - ר מרדכי. נזכר ב\"אמרי שפר\", וב\"לשון למודים\" אגרת אליו."},{"i":5740,"n":"אצבאן, יצחק מפאס","f":"אברהם מפאס","bp":"פאס","dt":"תקסג - אלול","dp":"פאס","b":"מחכמי מכנאס, חברו של המשבי\"ר."},{"i":5741,"n":"אצבאן, מרדכי מאלגיר","f":"יעקב","b":"רב בתלמסאן-תפז, ונזכר בשטר."},{"i":5742,"n":"אצבאן, מרדכי ממכנאס","f":"יצחק","k":"בעל זובח תודה","bp":"מרוקו","dt":"תקי","dp":"בדרכו לארץ","b":"תלמיד ר משה בירדוגו=המשבי\"ר. רב ממערב הפנימי במרוקו, רב בליוורנו ובארם צובא, עלה לירושלים [תצג-ו]. היה בשליחות בבבל ונפטר בדרכו חזרה. תלמידו - ר ראובן ן צור. חיבר \"זובח תודה\" קושטא תצג, \"ישא ברכה\" ועוד."},{"i":5743,"n":"אצבאן, מרדכי מפאס","b":"רב בפאס - בשנות ה-ת. רבו של ר ראובן ן צור. בנו ר יצחק."},{"i":5744,"n":"אצבאן, שלמה מאלגיר","k":"בעל עט סופר","dt":"תש - בערך","b":"רב בגאזאווית(=ראזאווית, נומור)-אלגיר-תרע כ-30 שנה. פייטן ופיוט ממנו ב\"צרור מכתבים\" לר יחיאל שוקרון."},{"i":5745,"n":"אצבי, יוסף מאלגיר","f":"מאיר","k":"בעל חזה התנופה - אבד","bt":"רע - בערך","dt":"שן - בערך","b":"רב באלגיר, מבני הקהלה המקומית שפסקו כרמב\"ם (בניגוד לקהלת בני ספרד - יוצאי מיורקה באלגיר). חיבר חיבור בהלכות שחיטה בשם \"חזה התנופה\" - ואבד. מתלמידיו - הרשב\"ץ."},{"i":5746,"n":"אצבי, משה מאלגיר","f":"מאיר","bt":"רס - בערך","dt":"שמ - בערך","b":"פייטן, דיין ומו\"ץ באלגיר, והשיב תשובות רבות ואבדו. תשובה ממנו אצל ר אברהם ן טוואה. מפיוטיו בקרוב\"ץ מנהג אלגיר. אחיו של ר יוסף בעל \"חזה התנופה\"."},{"i":5747,"n":"אציני, אברהם ממרוקו ואלגיר","f":"יעקב","bt":"תק - בערך","bp":"צפרו-מרוקו","dt":"תקע - בערך","b":"מחכמי צפרו, עבר לתלמסאן, אלגיר-תקמד, חזר לצפרו-תקנד (בעקבות מכתב ר שאול סירירו - שאליו פנתה אשתו בדרישה שיחזור), יצא בדרכו לארץ דרך תלמסאן (לא ברור האם הגיע לארץ). חתם בתלמסאן-תקסב עם ר יהודה צרמון ור דוד עטייה."},{"i":5748,"n":"אצלאן, אברהם","bt":"תרטז","dt":"תשח","b":"מחכמי ורבני בגדאד, חכם באשי-תר\"צ-תרצ\"ב"},{"i":5749,"n":"אצלאן, עזרא מבגדד","b":"מחכמי בגדד - שנות ה-תר', תלמיד ר שמעון אגסי."},{"i":5750,"n":"אצראף, יהודה מפאס","b":"מחכמי פאס-שנות ה-ת'."},{"i":5751,"n":"אצראף, יוסף מנוף סוס-מרוקו","b":"מקובל בכפר קאקאוו-נוף סוס-מרוקו - שנות ה-תק'. נפטר בן למעלה מ-100."},{"i":5752,"n":"אצראף, יעקב מפאס","b":"מחכמי פאס-שנות ה-ש'-ת'."},{"i":5753,"n":"אצראף, ישכר מסאלי וירושלים","bt":"תקעז","bp":"סאלי","dt":"תרנב - כו אב","dp":"ירושלים","b":"רב בסאלי. עלה לירושלים-תרמ, וכיהן כרב העדה המערבית בירושלים על מקום ר רפאל אלעזר בן טובו. תלמידו וחתנו - ר רפאל אנקאווה - רב ראשי במרוקו."},{"i":5754,"n":"אצראף, מסעוד מפאס","b":"דיין בפאס. עם ר משה אסולין - שנות הש'."},{"i":5755,"n":"אצראף, שלמה ממרוקו","b":"חיבר כתב יד על פרשת השבוע, אולאד ברחיל-מרוקו-תרפח בערך."},{"i":5756,"n":"אקדר, יחיא מפאס","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":5757,"n":"אקהאוז, יעקב מטאלשקוביץ","b":"רב בטלשקוביץ - תשובה אליו בשו\"מ."},{"i":5758,"n":"אקהאוז, יצחק","f":"יעקב קופל","k":"הו\"ל ספר התמונה","bt":"תר","dt":"תרס","b":"מצאצאי ה\"נועם אלימלך\". הדפיס את \"ספר התמונה\" עם פירוש ממקובל אחד."},{"i":5759,"n":"אקוני, יצחק משלוניקי","dt":"תקעג","b":"מחכמי שלוניקי. נספד מאת ר יעקב רפאל מנשה."},{"i":5760,"n":"אקוני, רפאל חיים בכור משלוניקי","dt":"תקעו","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":5761,"n":"אקוני, שבתי משלוניקי","dt":"תפח - כסלו","dp":"שלוניקי","b":"שודד יהודי בשלוניקי - מאנשי קהלת \"נוה שלום\", שלאחר שהתרו בו כמה פעמים ולא נענה - נידון למיתה ע\"י ר יוסף דוד-מהרי\"ד ובית דינו ופסק הדין בוצע ע\"י שליח בית הדין."},{"i":5762,"n":"אקוסטא, יצחק מאמשטרדם","k":"בעל פירוש לנביאים","b":"חיבר פירוש לנביאים עם תרגם ספרדי - לידא."},{"i":5763,"n":"אקוסטא, יצחק מצרפת","k":"בעל רתחת הקנאה","b":"מחכמי הספרדים בצרפת, ש\"ץ ומלמד בפינייא אורארא, אב\"ד באוננה. מתורתו ב\"רתיחת הקנאה\" תסח. תרגם נ\"ך לספרדית - ונדפס בליידן תפב."},{"i":5764,"n":"אקטשין, מנחם מנדל מרישא","f":"מרדכי","k":"בעל תנאי הנפש","bt":"תרמה","dt":"תשג","b":"חסיד דזיקוב. חיבר \"תנאי הנפש להשגת החסידות\" וינה תרפ\"א. ספרו שימש כספרי הדרכה פופולריים לנוער חסידי בפולין. בנו ד\"ר ר משה - מורה בסמינר בית יעקב ופרסם באידיש בעתוני וארשא."},{"i":5765,"n":"אקינויציעט, אברהם מקזבלנקה","b":"דיין בקזבלנקה. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":5766,"n":"אקלינסקי, אבנר","bt":"תרמה","dt":"תשא - כ תמוז","b":"ראש ישיבה בטלז"},{"i":5767,"n":"אקלר, מרדכי ממשהד-פרס","f":"רפאל אקלר","k":"מולא מראד","bt":"תרי-טז","bp":"משהד","dt":"תרצו - ח תמוז","dp":"ירושלים","b":"רב קהילת האנוסים במשהד-תרמג על מקום אביו, את רוב לימודו עשה כאנוס - בסתר. עלה לירושלים-תרפז והתישב בשכונת הבוכרים, והנהיג את קהילת עולי משהד, והו\"ל ספרים מתורגמים לפרסית עבורם. בנו ר רפאל על מקומו אחריו."},{"i":5768,"n":"אקלר, רפאל מפרס","b":"מאנוסי משהד-פרס, חזר ליהדותו, וכיהן כרב במשהד-תרמג. בנו ר מרדכי אקלר."},{"i":5769,"n":"אקנר, צבי הירש מבילקמין","b":"אב\"ד בילקמין-תרלט. תשובות אליו \"ברכת רצ\"ה\"."},{"i":5770,"n":"אקסלמן, בן ציון מנ\"י","b":"מעורכי \"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":5771,"n":"אקסלרוד, אברהם אליהו מארה\"ב","b":"רב ביהכ\"נ \"צמח צדק\" בבולטימור. פרסם מאמרים בתלמיד ישיבת אוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":5772,"n":"אקסלרוד, אברהם מקולוניא(=קלן)","f":"אלכסנדר","k":"בעל כתר שם טוב","b":"תלמיד ר אליעזר מגרמיזא בעל הרוקח. מקובל מחכמי אשכנז שנדד לספרד. ויתכן שכנגדו יצא הרשב\"א שעשה מעשים משונים ואמר שאליהו הנביא הוא המדבר וכו'."},{"i":5773,"n":"אקסלרוד, בנדיט הלוי מלמברג","f":"יוסף","k":"בעל בן דעת","b":"דרשן באוסטרובה-ש\"ס. נזכר בשו\"ת \"בנימין זאב\". חיבר גם \"עבודת הלוי\", \"בן דוד\"."},{"i":5774,"n":"אקסלרוד, ברוך בנדיט מאיטליה","b":"רב וראש ישיבה בויניציאה-רע-רצד, בולוניה. חברו של ר חייא בן דוד, והיה במחלוקת עם ר דוד פיציניטין."},{"i":5775,"n":"אקסלרוד, משה מרמת גן","f":"אברהם חיים","bt":"תרנג","bp":"דוקשיץ","b":"מצאצאי ר ישעיה זוכוביצר. תלמיד ישיבות מינסק, קובנא, תלמיד האדמור הרש\"ב מלובביץ. רב בבליוב-טולא-תרעה, ז'לובין-תרעח, טורז'-צ'רניגוב-תרפז, מוסקבה-תרצג, עלה לארץ-תרצו וכיהן כרב ברמת גן, ויסד ישיבות בז'לובין, רומן-פולטבה, סורז' ורמת גן."},{"i":5776,"n":"אקסלרוד, שלמה זלמן מפאלאצק","f":"משה","k":"בעל מנורת שלמה","bt":"תרכ","dt":"תרסג","dp":"קובנא","b":"נכד ר שמואל מביעשינקעויץ, ונכד-אבי אמו ר בנדיט אקסלרוד, נינו של ר אברהם מקאליסק-תלמיד המגיד ממזריטש. חתן הגביר ר מאיר גינצבורג. תלמיד ר יצחק אלחנן בקובנא. רב בדאלהינוב(=דלהינוב)-פלך וילנא-תרנד, פאלאצק. נסמך מאת: ר יצחק אלחנן מקובנא, הנצי\"ב, ר ראובן הלוי מדוינסק, ר שלמה הכהן מוילנא.. חיבר גם \"נר מערבי\", \"דברי שלמה\", \"האלף לשלמה\" - בכת\"י."},{"i":5777,"n":"אקר, חיים ישעיה מירושלים","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\", \"תורת בית הוראה\" - ירושלים תשג - קובץ ישיבת רבנו חיים יוסף."},{"i":5778,"n":"אקר, שמואל מרדיחוב","dt":"תש..","b":"דיין ברדיחוב אצל ר יעקב אונגר. חסיד הוסיאטין. ניהל את אחוזת אביו \"הריציחה\" (ליד סטויאנוב), הכשיר חלוצים באחוזתו לפני עלייתם לארץ. נספה בשואה."},{"i":5779,"n":"אקרמן, אהרן מאטשקוב","k":"בעל בית אהרן","b":"חסיד ר ישראל מרוזין ובנו ר אברהם יעקב מסדיגורה. חתן נכדת ר אהרן משה טויבש מיאסי. מו\"צ ביאסי, רב באטשקוב-פלך חרסון-ליד אודסה-תרל, עלה לירושלים וכיהן כראב\"ד לעדת החסידים שם. חיבר \"בית אהרן\". בספריו הביא מדברי אדמורי רוזין."},{"i":5780,"n":"אקרמן, יוסף מסרעט","b":"פרסם מאמרים ב\"הלבנון\" - סטמר תרפח."},{"i":5781,"n":"אקרמן, ישראל חיים מפרזמישל","f":"אהרן מאטשקוב","k":"בעל מי השלוח","r":"אב\"ד ניאמץ","bt":"תריג","b":"חתן ר אלימלך ויסבלום-נכד ר אלימלך מליזנסק. נסמך מאת: ר יוסף שאול נתנזון מלבוב. רב בטארגא-ניאמץ-רומניה-תרמא, מחכמי פרזעמישל-תרנא. חיבר גם \"בית ישראל\", עורך \"יגדיל תורה\" - ברלין-קראקא תרנא. בניו: ר אליעזר וייסבלום (שם זקנו-אבי אמו) בעל \"דברי אליעזר\", ר יוסף נתן.","bk":[["מי השליח - שו\"ת בעניני שליחות",""]]},{"i":5782,"n":"אקשוטי, יצחק מקושטא","f":"חיים","k":"בעל בני ישחק","dt":"תרכב","b":"מחכמי קושטא - רב בפרבר פירי פאשה-תרך, חתנו של ר אליהו ענוג. חיבר \"בני ישחק\" ירושלים תרמד (נדפס על ידי אחיו ר שבתי עם ספר \"קול שחל\" ). נספד בספר \"קול שחל\". נפטר ללא ילדים."},{"i":5783,"n":"אקשוטי, שבתי מקושטא","f":"חיים","k":"בעל קול שחל","dt":"תרמט - ג טבת","dp":"ירושלים","b":"מחכמי קושטא, עלה לירושלים-תרל והקים ישיבה, הדפיס את חדושי אחיו ר יצחק בשם \"בני ישחק\". חיבורו \"קול שחל\" נדפס בסוף ספרו של אחיו. היה ראש ישיבה בירושלים"},{"i":5784,"n":"אקשוטי, שמואל מקושטא","f":"שבתי","b":"גביר בקושטא, נזכר ב\"מעם לועז\" כנדבן. בניו: ר שבתי, ר יצחק בעל \"בני ישחק\"."},{"i":5785,"n":"אקשטין, אברהם אליעזר מבודפשט","f":"אהרן יהודה ליב אוהן","bt":"תקצח","dt":"תרסח - יג אב","b":"חתן ר פנחס יהודה פייפר מקאוועגרעש ור נפתלי חיים ליבר מטארקאן. תלמיד ר ירמיה לעוו, מהר\"ם א\"ש. דיין בפעסט(=בודפשט) עם ר חיים סופר ור קופל רייך, ובנו ר אלכסנדר רב קהילת אנשי פולין בבודפשט. חתנו ר חיים וינברגר - רב בהאראשפאלווא, וניו יורק."},{"i":5786,"n":"אקשטין, אברהם אליעזר מהעדיס","dt":"תשד","b":"רב בהעדיס. חתן ר יוסף שלמה גויטיין. נספה בשואה."},{"i":5787,"n":"אקשטין, אהרן יהודה ליב מוויצען","f":"שמחה מוויצען","k":"בעל כנפי נשרים","bt":"תקע","dt":"תרכו - חשון","b":"מכונה בשם 'ליב אוהן'. רב בסערדאהעלי, דיין בוויצען על מקום אביו. התכתב עם החת\"ס, ר יהודה אסאד ועוד מרבני הונגריה. מתורתו ב'לא יסור שבט מיהודה' - ירושלים תשנה, בקובץ'פעמי יעקב', 'אוצרות ירושלים'. בניו - ר משה מסערענטש, ר אברהם אליעזר מבודפשט, ור עזריאל מאנטורפן."},{"i":5788,"n":"אקשטין, אלימלך מבילקא","b":"דומ\"צ בבילקא"},{"i":5789,"n":"אקשטין, אלכסנדר מפעסט","f":"אברהם אליעזר עקשטין","dt":"תרעג - יד אלול","b":"דומ\"צ בפעסט. חתן ר צבי אקשטין מפאפא."},{"i":5790,"n":"אקשטין, בנימין זאב וולף מפרשבו","f":"יונה מדארבאן","bt":"תרכט","dt":"תרפט - ט אד\"א","dp":"פרשבורג","b":"תלמיד השב\"ס, חתן ר שמעון רוזנפלד."},{"i":5791,"n":"אקשטין, יונה מדארבאן","dp":"נייטרא-באינא","b":"אביו של ר צבי - תלמיד החת\"ס ודיין בפאפא."},{"i":5792,"n":"אקשטין, יצחק איזיק אלימלך מדוק","bt":"תקע","bp":"דוקלא","dt":"תרך","b":"אב\"ד דוקלא. בן אחותו של ה\"בני ישכר\". בנו ר מנחם מנדל מסיגט מח\"ס יצירה וקונ' \"בכי תמרורים\"."},{"i":5793,"n":"אקשטין, ישראל מרישא","b":"רב ברישא-תרנב."},{"i":5794,"n":"אקשטין, מנחם מנדל מסיגט ונ\"י","f":"יוסף שלמה","k":"בעל ספר יצירה","bt":"תרמג-ד","bp":"סיגט","dt":"תשו - י ניסן","dp":"ניו יורק","b":"תלמיד ר משה גרינוולד מחוסט. מגיד בסיגט-תרסד, קראסנא. היה חברו של האדמור בעל \"עצי חיים\" בסיגט. עבר לארה\"ב-[תרעח-תרף] וכיהן כרב בקליבנלד וניו יורק. חיבר ספר יצירה כנגד \"נפלאות מהר\"ל\" לר\"י רוזנברג, \"בכי תמרורים\" טארנא תרפט, ועוד. פרסם מאמרים ב\"הלבנון\" - סטמר תרפח."},{"i":5795,"n":"אקשטין, מנחם מקאשוי","bt":"תרלה","bp":"נייטרא-באינא","dt":"תשד","dp":"אושוויץ","b":"מצאצאי ר יונה אקשטין מדארבאן. ומצאצאי ר אריה יהודה ליב ריכהרט מקאטה. תלמיד השב\"ס. רב בקאשוי-תרעד. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":5796,"n":"אקשטין, מרדכי מרישא","b":"ראש הקהל ברישא."},{"i":5797,"n":"אקשטין, משה אשר מסערד-סלובקיה","f":"צבי מפאפא או יונה מב","bt":"תרמב-ט","bp":"פאפא","dt":"תשב - ב אייר","dp":"מיידנק","b":"תלמיד הדעת סופר, ור יואל פלנר באויהל או בבלד, ור יהודה ליב פרידמן מפרשבורג. חתן ר מרדכי שטיינר. מלמד בביה\"ס של הקהלה החרדית בפרשבורג, רב בסרעד-תרף ולצדו הדיין ר דוד וסלי. יו\"ר ועד הפועל של אגו\"י בצ'כוסלובקיה. נספה בשואה. חתנו - ר שמואל וינברג מבני ברק-בן הרב מסלונים. (לפי מורשת רבני הונגריה - שם אביו ר יונה מבוינה-סלובקיה). פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":5798,"n":"אקשטין, משה מסערענטש","f":"אהרן יהודה ל' מוויצן","bt":"תרב","dt":"תרעח - יא כסלו","dp":"ירושלים","b":"תלמיד הכת\"ס. חתן ר יואב קורניצר מסערענש ועבר לשם. עלה לירושלים-תרנח. תשובה אליו ב\"כתב סופר\" ו\"שבט סופר\"."},{"i":5799,"n":"אקשטין, ניסן מקוזניץ","dt":"תשג","b":"רב בקוזניצה. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"תלפיות\" - טרנוב תרצח."},{"i":5800,"n":"אקשטין, נתן בנימין מבודפשט","f":"אלכסנדר מבודפשט","bt":"תרמז","bp":"טארקאן","dt":"תשה - יז חשון","dp":"בודפשט","b":"תלמיד השב\"ס, והדעת סופר ועוד. חתן ר אשר אנשל אדלר מדונא-פאלדוואר, ועבר לשם. רב קהלה בבודפשט. נספה בשואה."},{"i":5801,"n":"אקשטין, עזריאל מאנטורפן","f":"אהרן יהודה ליב","bt":"תריט","dt":"תרפד - טו סיון","dp":"אנטורפן - פיטע (הולנד)","b":"תלמיד השב\"ס, חתן ר מרדכי הכהן הולנדר ממישקולץ ועבר לשם. עבר ללונדון, אנטורפן."},{"i":5802,"n":"אקשטין, צבי מפאפא","f":"יונה מדארבאן","bt":"תרז","dt":"תרצו - טו אייר","dp":"פאפא","b":"תלמיד הכת\"ס, ור בנימין זאב וולף פוקס מסערעד. חתן ר נתן ברו ךבנדיט בריינר משארוואר.. רב בפאפא-תרמז. בנו ר משה אשר רב בסערעד, וחתנו ר אלכסנדר אקשטין - דיין בבודפשט."},{"i":5803,"n":"אקשטין, שמחה מוויצען","b":"דיין בוויצען-תר בערך, ובנו - ר אהרן יהודה ליב על מקומו אחריו."},{"i":5804,"n":"ארא, דוד הכהן מטריאסט","f":"קלונימוס מתתיה","b":"חיבר והו\"ל \"קול דוד\" - ונציה תרם, לכבוד בר המצוה של בנו."},{"i":5805,"n":"אראבי, שלמה","b":"מקובל,רופא,עלה מיאסי לא\"י-ש\"ע"},{"i":5806,"n":"אראג'יל, משה מקהיר","b":"מחכמי קהיר-שסז. חתם על מעשה בי\"ד-שסד. נזכר בדרשות ר שבתי ברכה. עלה לירושלים - אחרי שסז."},{"i":5807,"n":"אראוויץ, משה זלמן","f":"יעקב קופל","bp":"דובראווע-פולין","b":"תלמיד ישיבת גרודנא, ר משה טרופ, ר פרץ אחון, ר שמואל הכהן פעליעץ, ר לוי שמעיעס, ר צבי הירש פלטא. נסמך מאת: ר מנחם רגנשבורג מזמבורבא, ר אביגדור ביאליסטוצקי מיאדובנה. היגר לארה\"ב-תרפג, רב בהארלם-ניו יורק-תרפג, ביהכ\"נ \"נצח ישראל\" בברונקס, ביהכ\"נ \"ואהבת אחים\" בברוקלין, ביהכ\"נ \"אנשי יאדובנא\" בניו יורק-תשא. חבר אגודת הרבנים באמריקה."},{"i":5808,"n":"אראזל, דוד מצפרו","dt":"שפח","dp":"צפרו","b":"מחכמי צפרו-מרוקו, חתם על פס\"ד-שפה. חיבר פירוש על מדרש רבא, תחינה. הראשון הידוע מחכמי צפרו."},{"i":5809,"n":"אראזל, יצחק מצפרו","f":"דוד","k":"יצחק בלחכם","b":"מחכמי צפרו-מרוקו."},{"i":5810,"n":"אראמה, מכלוף ממרוקו","dp":"סכורה","b":"ממשפחת קדושים בשם \"איית עראמה\" במרוקו. מקדושי וצדיקי מרוקו, ורבים השטתחו על קברו בעיר סכורה."},{"i":5811,"n":"אראן, אהרן שמעון משטרסבורג","k":"ניעדערברון","bt":"תרט","bp":"ניעדערברון","b":"תלמיד ביהמ\"ד לרבנים בפאריס, בעל תואר ד\"ר. רב בלויטנבורג-תרלה, מיץ-תרן, שטרסבורג-תרנט. חיבר \"פועלים וחכמי חרשים בימי קדם אצל היהודים\" - בצרפתית. אחיו - ר אלכסנדר מפגרסהיים."},{"i":5812,"n":"אראן, אלכסנדר מפוגרסהיים","b":"פרסם מאמרים ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב."},{"i":5813,"n":"אראנוב, יצחק מניו יורק","f":"משה בן מרדכי","bt":"תרסח","bp":"ביאליסטוק","b":"מצאצאי ר משה מקוברין, ר שמואל רבינוביץ, ור זליג מיר. תלמיד ישיבות ביאליסטוק, גרודנא, מיר. נסמך מאת: ר דוד פאיאנס מביאליסטוק, ר מאיר שדרוביצקי, ר יהודה ליב פיין מסלונים, ר אריה בן רפאל שפירא. חתן ר שמעון אהרן. רב בטורונטו-תרצד וכיהן כרב \"חברה לומדי תורה\", וביהכ\"נ \"אנשי לידא\". פעיל צבור ונשיא התאחדות הרבנים בטורונטו."},{"i":5814,"n":"ארבארו, אליהו מאישקופיה - הנכד","b":"נכד ר אליהו משלוניקי. רב באישקופיה-שסז."},{"i":5815,"n":"ארבארו, אליהו משלוניקי - א","b":"מחכמי שלוניקי, רב באישקופיה(=איסקוב)-שלא על מקום ר שלמה הלוי, יחד עם ר אהרן אביוב, היה מחלוקת ביניהם וחזר לשלוניקי."},{"i":5816,"n":"ארבוז, אברהם יצחק ישראל","b":"תלמיד ישיבת מיר. לזכרו קובץ \"תורה אור\" - שנחאי תשו, וגם מאמר ממנו שם."},{"i":5817,"n":"ארבוח, יהודה מטבריה","b":"רב בטבריה-תרס."},{"i":5818,"n":"ארבוחי, מסעוד ממרוקו","b":"מחכמי מרוקו-שנות ה-תק', מכתב ברכה אליו מר חיים דוד סירירו בהולדת בנו."},{"i":5819,"n":"ארבי משה דאנציג מוילנא בנו של הרב חיי אדם","dt":"יד אדר"},{"i":5820,"n":"ארביב, אברהם מטריפולי","k":"ארביב כושנה","bt":"תקצה","dt":"תרע","dp":"טריפולי","b":"רב ומקובל בטריפולי. הניח חבורים בכת\"י, ובהם \"רעדיה\" - עניני רעמים ורעשים."},{"i":5821,"n":"ארביב, יצחק מטריפולי","bt":"תמ","dt":"תקי - בערך","dp":"טריפולי","b":"רב וסופר הקהלה בטריפולי. חתימתו בפנקס בי\"ד טריפולי."},{"i":5822,"n":"ארברמן, משה מצאנז","k":"משה זישעס","b":"מקובל מחכמי צאנז בזמן הדברי חיים. מחותן עם ר משה יהודה שליסל ונכדו - ר דוד ראב\"ד מונקטש בעל \"אמרי דוד\"."},{"i":5823,"n":"ארגואיטי, אברהם","b":"מרבני אוק'י(טורקיה)"},{"i":5824,"n":"ארגואיטי, יעקב מקושטא","f":"אברהם","k":"בעל ירך יעקב","bt":"תרך","bp":"אוקיי-תורכיה","dt":"תש","b":"דיין בקושטא-תרפא. חתם שמו - \"הי\"א שיחתי\" (ר\"ת שמו - הצעיר יעקב ארגואיטי)."},{"i":5825,"n":"ארגואיטי, יצחק משלוניקי","f":"שמריה","k":"בעל מעם לואז","b":"רב בשלוניקי-תקלג. השתתף בחיבור \"מעם לועז\" - דברים."},{"i":5826,"n":"ארגואיטי, שלמה מירושלים","b":"מחכמי ישיבת \"כנסת ישראל\" בירושלים-תקיח (מיסודו של ר חיים ן עטר)."},{"i":5827,"n":"ארגון, יצחק מלובלין","f":"שלמה מספרד","dt":"שסד - יד שבט","b":"מחכמי לובלין - בן למגורשי ספרד שהגיעו לפולין."},{"i":5828,"n":"ארגז, משה מפיליפופולי","b":"רב בפיליפופולי-שנות ה-ש'."},{"i":5829,"n":"ארגיל, אברהם משלוניקי או מצרים","k":"בעל מים חיים","b":"רב בשלוניקי (ולדעת רוזניס באלכסנדריה). בנו - ר חיים יצחק מתתיה. אחיו - ר משה מקהיר."},{"i":5830,"n":"ארגיל, משה","k":"תרגם התורה","b":"תרגם את המקרא לספרדית - מטעם דון לוייז די גוזמן."},{"i":5831,"n":"ארגיל, משה ממצרים","dt":"שסד - אחרי","b":"רב בקהיר. אחיו - ר אברהם מאלכסנדריה."},{"i":5832,"n":"ארדברג, פנחס שלמה","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":5833,"n":"ארדוטל, שם טוב","k":"בעל וידוי ליוה\"כ","b":"חיבר וידוי ליוה\"כ הנדפס במחזור הספרדי. מאמר ממנו נדפס ב\"דברי חכמים\" לר אליעזר אשכנזי - מיץ תרט."},{"i":5834,"n":"ארדיט, (חיים) אברהם מאזמיר","f":"אפרים","bt":"תצה","dt":"תקל","b":"מחכמי ורבני אזמיר"},{"i":5835,"n":"ארדיט, אברהם","b":"תק\"ע"},{"i":5836,"n":"ארדיט, אברהם הכהן משלוניקי","k":"בעל ספר איוב בלאדינו","b":"הגיע מליוורנו לשלוניקי-תרם כדי לנהל את ביה\"ס ת\"ת. תרגם ללאדינו את ספר איוב-תרמט."},{"i":5837,"n":"ארדיט, אברהם הכהן משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":5838,"n":"ארדיט, אברהם משלוניקי","b":"ראש המשפחה בשלוניקי-סוף שנות ה-ר'. גביר מחכמי שלוניקי, חתן ר מאיר עראמה."},{"i":5839,"n":"ארדיט, אליהו מרודוס","bp":"שלוניקי","b":"רב ברודוס-תפד על מקום ר דוד הלחמי. ומשנהו ר אליהו מבורך גליפפה."},{"i":5840,"n":"ארדיט, אלעזר הכהן מספרד","dp":"מיורקה","b":"רופא בספרד-1330 ונזכר אצל ר יוסף ן כספי ב\"גלילי כסף\"."},{"i":5841,"n":"ארדיט, אפרים מאזמיר","f":"אברהם משלוניקי ואזמי","k":"בעל מטה אפרים","bt":"תן-ס","bp":"איזמיר","dt":"תקכח - טו תשרי","b":"מגאוני הדור, רב באזמיר-תקכ. חיבר \"מטה אפרים\" בדפוס, ושות בכת\"י. חתנו - ר משה נוניס בילמונטי, ונכדו ר יצחק נוניס בילמונטי."},{"i":5842,"n":"ארדיט, אשר הכהן משלוניקי","f":"אברהם","k":"מצאצאי עלי הכהן","bp":"שלוניקי","dt":"תה - יט ניסן","dp":"שלוניקי","b":"נכד-אבי אמו - ר מאיר עראמה. תלמיד ר אשר ברודו, ור דוד ן שושן (ששון). ראש ישיבת \"ארגון\" בשלוניקי. מתלמידיו: ר יעקב די בוטון, ר ברוך אנגל, ר שניאור אברבנל, ר מרדכי פינצי, ר אליהו קאטאלאן, ר יוסף קאטריבש, ר אליעזר גינילייו, ר נפתלי הלוי ר אהרן הכהן פרחיה. חתם על הסכמות הקהל-שעד. (אולי מדובר על שני חכמים שונים? - ר מאיר עראמה נפטר בשנת רפב)."},{"i":5843,"n":"ארדיט, דוד יהודה משלוניקי","dt":"תרסד","dp":"שלוניקי","b":"מחכמי שלוניקי, וראש הסופרים בשלוניקי."},{"i":5844,"n":"ארדיט, חיים יוסף משלוניקי","f":"עזריאל","bt":"תצה - בערך","bp":"שלוניקי","dt":"תקפז - י אב","b":"נכד ר יוסף ן ארדיט, ור יוסף דוד-מהרי\"ד-מצד אמו. דיין בשלוניקי-תקמז, ורב הכולל-תקנג על מקום ר רפאל חיים אברהם קובו - עם כמה מחבריו ובהם ר אברהם גטניו, ורב ראשי יחידי לאחר פטירת ר אברהם גטניו, ור חיים נחמה שבתי ור יעקב מנשה ור משה ברכה על מקומו אחריו (כולם ביחד \"רבני הכולל\"). הו\"ל שו\"ת הגאונים \"שערי צדק\" עם ר נסים מודעי מאזמיר-תקנג. הסכים על ספרים רבים בשלוניקי. חתם-תקפב עם ר שאול מולכו ור חיים יוסף ן אדון. הסכים על \"כוכבא דשביט\"-תקנט."},{"i":5845,"n":"ארדיט, חננאל משלוניקי","b":"ראש ישיבת \"בית יוסף\" בשלוניקי-תרס."},{"i":5846,"n":"ארדיט, יהושע שלמה מאזמיר","k":"בעל חינא וחסדא","bt":"תקמט","dt":"תרלו - ה סיון","b":"רב באזמיר. מכתביו נדפס \"חינא וחסדא\", \"איש מבין\". נספד מאת ר חיים פאלג'י.","bk":[["חינא וחסדא",""],["איש מבין",""]]},{"i":5847,"n":"ארדיט, יוסף הכהן משלוניקי - א","b":"תלמיד ר דניאל אישטרושא. חתן ר שלמה אמריליו. מחכמי שלוניקי בשנים תצ - תקיב, ומשנת תקב רב ראשי על מקום ר שאול בן שלמה בן דוד. חתם על הסכמות שונות ובהם על ההסכם עם הפראנקוס-תקד. בשנת תקיד בערך עלה לירושלים. חיבר הקדמה ל\"פני יצחק\"-תקג. הו\"ל תשובות קדמונים בקובץ \"שערי צדק\". בנו ר עזריאל-חתן ר יוסף דוד-המהרי\"ד, נפטר בשנת תקכא."},{"i":5848,"n":"ארדיט, יוסף הכהן משלוניקי - ב","b":"מחכמי שלוניקי-תרס."},{"i":5849,"n":"ארדיט, יוסף מקושטא","b":"עוזרו של דון יוסף נשיא לצורך חידוש הישוב בטבריה."},{"i":5850,"n":"ארדיט, יצחק מאזמיר - הזקן","f":"שלמה - לחם שלמה","k":"בעל יקר הערך","bt":"תפד","dt":"תקלח - כה תשרי","dp":"ירושלים","b":"מחכמי אזמיר, עלה לירושלים. חיבר \"יקר הערך\" שנשלם על ידי בנו ר שלמה ונדפס בשם \"פחות שבערכין\" שלוניקי תקפג. ולדעת רבלין בתח\"י נפטר באזמיר תקעב (והכונה כנראה לנכדו)."},{"i":5851,"n":"ארדיט, יצחק מאזמיר - הנכד","f":"שלמה בן יצחק הזקן","k":"בעל פחות שבערכין","bt":"תקיט","dt":"תקעב - יד תמוז","dp":"אזמיר","b":"נכדו של ר אהרן אלפנדרי בעל \"יד אהרן\". חתן הגביר ר חיים משה ארדיט מאזמיר. רב באזמיר, עלה לארץ וחזר לאזמיר. (יש מהרושמים שהחליפו בינו לבין זקנו). בנו ר שלמה השלים את ספרו וקרא לו \"פחות שבערכין\"."},{"i":5852,"n":"ארדיט, יצחק משלוניקי","dt":"שמא - כב אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":5853,"n":"ארדיט, מאיר","b":"מתלמידי היר\"ח - זקנו של ר חיים פלאגי."},{"i":5854,"n":"ארדיט, מנחם הכהן מאזמיר","dt":"תרלז","dp":"ירושלים","b":"רב בשירון, אזמיר בזמן ר חיים פאלג'י, שלוניקי."},{"i":5855,"n":"ארדיט, משה הכהן מרודוס","b":"דיין ברודוס-תמ אצל ר דוד חיים הלחמי."},{"i":5856,"n":"ארדיט, משה חנניה משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":5857,"n":"ארדיט, משה יצחק משלוניקי","b":"מחכמי שלוניקי-תרס."},{"i":5858,"n":"ארדיט, משה מאזמיר","f":"יהושע שלמה-איש מבין","dt":"תרלג - בערך","b":"רב באזמיר. נספד בספר אביו \"איש מבין\", וב\"בן אברהם\" לר יום טוב קריספין."},{"i":5859,"n":"ארדיט, משלם הכהן מברצלונה","f":"שמואל","b":"רב בברצלונה. חתם עם הרשב\"א-סח בענין החכמות החיצוניות."},{"i":5860,"n":"ארדיט, נסים הכהן משלוניקי","dt":"תיז - א שבט","dp":"שלוניקי","b":"מחכמי שלוניקי. גיסו של ר אהרן פרחיה בעל \"פרח מטה אהרן\" שהספידו."},{"i":5861,"n":"ארדיט, נסים יעקב מירושלים","f":"יהונתן","b":"מחכמי ירושלים, וחתם במחלוקת בענין הרב גאגין-תרו. בשליחות \"בית אל\" במרוקו-תריד."},{"i":5862,"n":"ארדיט, נסים יצחק מאזמיר","f":"ר\"א","k":"בעל נר יצחק - עמודי","dt":"תקפד - יד סיון","dp":"אזמיר","b":"רב באזמיר. אחיינו של ר אפרים בעל \"מטה אפרים\". חיבר גם ספר כללים ונזכר אצל חברו ר חיים בנימים פונטרימולי ב\"פתח הדביר\"."},{"i":5863,"n":"ארדיט, עזריאל הכהן משלוניקי -א","f":"אשר - אולי","dt":"תכא - כג טבת","dp":"שלוניקי","b":"רב בשלוניקי. בניו: נסים, יעקב, דוד. נספד אצל ר אהרן פרחיה ב\"בגדי כהונה\"."},{"i":5864,"n":"ארדיט, עזריאל הכהן משלוניקי -ב","dt":"תן","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":5865,"n":"ארדיט, רפאל מאזמיר","f":"שלמה","k":"בעל מרפא לשון","b":"אחיו ר של ר יצחק בעל \"יקר הערך\". מחכמי אזמיר - סוף שנות התק'. תלמיד ר יוסף רפאל חזן בעל \"חקרי לב\"."},{"i":5866,"n":"ארדיט, רפאל שלמה מאזמיר","f":"יצחק - יקר הערך","k":"בעל פחות שבערכין","dt":"תקצג - כב סיון","dp":"אזמיר","b":"מגדולי חכמי אזמיר-תקפ\"ג. תלמיד ר שלמה חכים בעל \"כסא שלמה\". חיבר גם \"שם משלמה\"."},{"i":5867,"n":"ארדיט, רפאל שלמה מירושלים - א","dt":"תקנז - ח סיון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":5868,"n":"ארדיט, שלמה הכהן משלוניקי","b":"מחכמי שלוניקי - שנות הר'-ש'."},{"i":5869,"n":"ארדיט, שלמה הכהן משלוניקי","f":"אברהם","b":"תלמיד ר חיים שבתי-מהרח\"ש. חברו של ר יהושע חנדאלי וחתם על פסקיו."},{"i":5870,"n":"ארדיט, שלמה מאזמיר וירושלים","f":"יעקב","k":"בעל לחם שלמה","dt":"תקיא - כח כסלו","dp":"ירושלים","b":"מחכמי אזמיר, עלה לירושלים והיה מגדולי חכמי ירושלים. חיבר גם \"דברי שלמה\", \"אוצר שלום\". בנו ר יצחק מחכמי ירושלים ונפטר בירושלים-תקלח."},{"i":5871,"n":"ארדיט, שמואל","dt":"תקכב","b":"נספד ע\"י ר\"י נוניש בילמונטי, ואחיינו ר אברהם ארדיט."},{"i":5872,"n":"ארדיטי, אברהם מאזמיר","dt":"תכב","dp":"צפת או אזמיר","b":"גביר מחכמי אזמיר, מתומכי ר חיים בנבנישתי בעל כנסת הגדולה."},{"i":5873,"n":"ארדיטי, אברהם שם טוב משלוניקי","b":"מצאצאי ר שמואל בן יעקב ארדיטי. עורך העתון הסוציאליסטי \"אבאנטי\", ומראשי התנועה הסוציאליסטית בשלוניקי."},{"i":5874,"n":"ארדיטי, אליהו משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"פני אהרן\" לר אהרן אמריליו-תקנו."},{"i":5875,"n":"ארדיטי, חיים אפרים מאזמיר","b":"גביר מחכמי אזמיר-תקן, סייע לר אברהם רוביו בהדפסת ספר אביו \"שמן מור\"."},{"i":5876,"n":"ארדיטי, חיים משה מאזמיר","b":"גביר מחכמי אזמיר-תקן, סייע לר אברהם רוביו בהדפסת ספר אביו \"שמן מור\"."},{"i":5877,"n":"ארדיטי, חנניה משלוניקי","dt":"תרך","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":5878,"n":"ארדיטי, יהודה משלוניקי","b":"רב בשלוניקי-שנות ה-תק'. בנו - ר עוזיאל."},{"i":5879,"n":"ארדיטי, יצחק מאזמיר","f":"אהרן","b":"גביר מחכמי אזמיר-תקן, סייע לר אברהם רוביו בהדפסת ספר אביו \"שמן מור\"."},{"i":5880,"n":"ארדיטי, יצחק רפאל מאזמיר","b":"גביר מחכמי אזמיר-תקן, סייע לר אברהם רוביו בהדפסת ספר אביו \"שמן מור\"."},{"i":5881,"n":"ארדיטי, יצחק שם טוב משלוניקי","dt":"תרלט-ם","dp":"שלוניקי","b":"דיין ומלמד תורה בשלוניקי."},{"i":5882,"n":"ארדיטי, משה מאזמיר","f":"אפרים","b":"גביר מחכמי אזמיר-תקן, סייע לר אברהם רוביו בהדפסת ספר אביו \"שמן מור\"."},{"i":5883,"n":"ארדיטי, משה ממצרים","b":"גביר במצרים-שנות ה-תק'. תמך בר חיים אביגדור בעל \"פרי עץ הדר\" בהיותו במצרים."},{"i":5884,"n":"ארדיטי, משה משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":5885,"n":"ארדיטי, עוזיאל משלוניקי","f":"יהודה","b":"רב בשלוניקי-שנות ה-תק'."},{"i":5886,"n":"ארדיטי, רפאל","b":"נספד מאת - ר נסים חיים שלום מרגונטו-שנות ה-תק'."},{"i":5887,"n":"ארדיטי, רפאל מפאריס ואלגיר","bt":"תרכא-תרלד","bp":"בולגריה","dt":"תש - בערך","b":"תלמיד ביהמ\"ד לרבנים בפאריס. דרשן, רב בתלמסאן-אלגיר מטעם הקונסטסטואר-תרסה-תרעה. חיבר ספרים בצרפתית."},{"i":5888,"n":"ארדיטי, שלמה משלוניקי","dt":"תקח - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"מגן אבות\" לר מאיר ביקייאם."},{"i":5889,"n":"ארדיטי, שלמה משלוניקי","dt":"תריח","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":5890,"n":"ארדיטי, שם טוב משלוניקי","f":"יצחק","b":"דיין בשלוניקי-ראשית שנות ה-תר'."},{"i":5891,"n":"ארדיטי, שמואל משלוניקי","f":"יעקב","k":"בעל דברי שמואל","bt":"תקעו - בערך","dt":"תרמז - ה אלול","dp":"שלוניקי","b":"רב בשלוניקי-תריז על מקום ר אברהם גאטיניו - שנאלץ לעזוב לאחר מחלוקת עם הגבירים (ובהם ד\"ר משה אלאטיני וחבריו), יחד עם ר מאיר ן נחמיאש ור שמואל יוסף, ורב ראשי-תרמא, והיה גם ממלא מקום הרב הראשי של קושטא שהיה אחראי על הנהגת הקהלות בתורכיה. היה במחלוקת עם הגבירים (שבעת טובי העיר) והתפטר אך לאחר שהפצירו בו הסכים לחזור בו. בזמנו בטל המנהג הקדום, כנגד דעתו, להרחיק החתן והכלה שבוע לפני החופה. בהלוויתו השתתפו נציגים בכירים של השלטון התורכי."},{"i":5892,"n":"ארדמן, ישראל","dt":"תשג","b":"מרביץ תורה בטלז"},{"i":5893,"n":"ארואיטו, מאיר מפליבנא","b":"פרנס מראשי קהלת פליבנא-שנות ה-ש'."},{"i":5894,"n":"ארואיטי, אברהם מצפת","b":"מחכמי צפת-רצח, נמנה על 25 הרבנים שהכתירו את ר יעקב בירב כמוסמך הראוי להסמיך אחרים. חתם-שלא על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":5895,"n":"ארואיטי, מאיר מסידרוקאפצי","b":"רב הספרדים בסידרוקאפצי-של."},{"i":5896,"n":"ארואיטי, מאיר מקאבאלה","b":"רב הקהלה הספרדית בקאבאלה-שנות ה-ש'."},{"i":5897,"n":"ארואיטי, שם טוב ממונסטיר","b":"רב במונסטיר-יוון-שנות ה-ש'."},{"i":5898,"n":"ארובאס, אברהם מצפת","b":"מקובל, מתלמידי האר\"י בצפת, ר חיים ויטאל מונה אותו בין \"הכת השניה\" של התלמידים שהם מפנימיות המוחין."},{"i":5899,"n":"ארובאס, זכריה משלוניקי","dt":"שעז - ג אייר","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":5900,"n":"ארובאס, יצחק מטיטואן","f":"חנניה או נחמיה","k":"בעל אמת ואמונה","b":"רב בטיטואן. חיבר \"אמת ואמונה\" ונציה תלב, \"זבחי צדק\", וספרים בספרדית. מוזכר אצל הרמ\"ז. לפי רוזניס מחכמי קושטא."},{"i":5901,"n":"ארוואה, שלום מטבריה","b":"חתם על קבלה-תרפג מישיבת חכמי הספרדים בטבריה."},{"i":5902,"n":"ארוואח, מסעוד ממכנאס","b":"רב במכנאס-תקסב, ונזכר ב\"תהלה לדוד\", וב\"חיי אברהם\". אגרת אליו מר דוד סירירו."},{"i":5903,"n":"ארוואץ, בנימין מירושלים","bp":"מרוקו","b":"רב בליוורנו, ארם צובה, עלה לירושלים בסביבות שנת ת\"צ"},{"i":5904,"n":"ארוואץ, בנימין ממרוקו","b":"מחכמי מרוקו-שנות ה-תק'. בנו - ר חיים."},{"i":5905,"n":"ארוואץ, חיים ממרוקו","f":"בנימין","b":"מחכמי מרוקו-שנות ה-תק'."},{"i":5906,"n":"ארוואץ, חנניה מטיטואן","b":"דיין בטיטואן-תח עם ר אברהם ן זמרא, ור יעקב הלוי. נזכר ב\"אשר לשלמה\" ל מוהר\"ש ן דנאן."},{"i":5907,"n":"ארוואץ, יוסף מירושלים","f":"משה","k":"בעל הוד יוסף","bt":"תרז או תרכא","bp":"ראבאט או מכנאס","dt":"תרפה - כא כסלו","dp":"יפו","b":"מחכמי ירושלים, עלה בגיל 12 ולמד אצל ר דוד בן שמעון ראש עדת המערבים, ור אליעזר בן טובו ור רפאל מאיר פאניז'ל. בשליחות-תרלג ואחר כך עוד מספר פעמים. דיין בבית הדין של עדת המערבים עם ר משה מלכא, ור נחמן בטיטו. רב ביפו-תרעג עד למינויו של ר בן ציון חי עוזיאל, ואח\"כ דיין בביה\"ד המאוחד. חיבר \"הוד יוסף\" ירושלים תרסה."},{"i":5908,"n":"ארוואץ, מסעוד ממרוקו ואלגיר","f":"עמרם","bp":"אוג'דא-מרוקו","dt":"תרלז","b":"רב באוג'דא-מרוקו, ברח ממושל העיר שרצה להורגו, דיין בתלמסאן-אלגיר-תרי אצל ר שמואל קרסיינטי וחתם עם ר יוסף קרסיינטי-תריב. היה בקשרי מכתבים עם חכמי דורו, תשובה אליו מר יעקב אלמדיוני מתלמסאן (נזכר ב\"גרש ירחים\" לר יוסף משאש - תשמט)."},{"i":5909,"n":"ארוואץ, משה","f":"נסים שמואל","dt":"תרנג - ב תשרי","dp":"ירושלים","b":"משורר מחכמי ירושלים, חיבר פיוטים שנכללו בספר \"יגל יעקב\" לר יעקב בורלא"},{"i":5910,"n":"ארוואץ, נסים שמואל יהודה מירקד","f":"רפאל","k":"בעל דרכי איש","bt":"תקסד","bp":"ירושלים","dt":"תרך - טו אב","dp":"קהיר","b":"רב בירושלים. חתם על כתב שליחות ר מיכאל בדהב שליח \"בית אל\"-תרה. בשליחות באדריאנופול-תרט. ממיסדי עדת המערבים בירושלים. בנו ר משה היה רבו של הראשון לציון ר אברהם אשכנזי (ולפי גאון - הוא בעצמו). מתורתו ב\"אמתחת בנימין\" לר בנימין חמוי.","bk":[["דרכי איש",""]]},{"i":5911,"n":"ארוואץ, שמואל מירושלים","b":"מרביץ תורה בירושלים-תק\"פ"},{"i":5912,"n":"ארווח ן, יחיא מפאס","b":"רב בפאס, חתם-תט על הסכמה עם ר סעדיה ן דנון."},{"i":5913,"n":"ארווירוויר, אברהם ממרוקו","dp":"כפר מוואלין דאר","b":"צדיק שנהגו להשתטח על קברו במחוז דאר לביצ'א."},{"i":5914,"n":"ארויה ן, חיים","k":"בעל מים החיים","b":"רב בפיליפופולי-תק\"צ,עלה לא\"י"},{"i":5915,"n":"ארויה ן, יוסף","b":"מחכמי ארץ ישראל, בשנת שצז בשליחות עם ר יוסף מליריאה."},{"i":5916,"n":"ארויה ן, שלמה","b":"רב ביאסי (רומניה) ורופאו של נסיך מודלביה, מקובל ספרדי, עלה לארץ ישראל. פגש את יש\"ר מקנדיא שביקר ביאסי ולימדו קבלה."},{"i":5917,"n":"ארויה ן, שלמה מספרד","b":"רב ביאס-רומניה, רופא ומקובל, היה רופאו של נסיך מולדביה. עלה לארץ בזקנותו."},{"i":5918,"n":"ארויילר, נפתלי הרץ מפפד\"מ","dt":"תלט - יח חשון","dp":"פפד\"מ","b":"דיין בפפד\"מ-תכו."},{"i":5919,"n":"ארוימי, דוד","f":"שלמה","b":"מחכמי צפת, בשנת תקמח בשליחות באיטליה, הביא לדפוס \"פועל צדק\" לר שבתי כהן בעל השך ליוורנו תקמח."},{"i":5920,"n":"ארוימי, יחיא ממכנאס","b":"מחכמי מכנאס, הספיד-תסז את ר שלמה הלוי בן אחאמי."},{"i":5921,"n":"ארוך, אהרן סגי נהור מצפת","f":"אליעזר בן דוד בן משה","k":"בעל מצנפת","b":"מחכמי צפת-שה. אולי הוא ר הנזכר אצל ר ישראל מפירושה בשם ר אהרן סגי נהור מצפת שהלך למצרים."},{"i":5922,"n":"ארוך, גדליה יצחק מלבוב","b":"מחכמי לבוב. נזכר ב\"נחלה לישראל\" לר יחיאל מיכל הובנר מניוזנוב."},{"i":5923,"n":"ארוך, דוד מירושלים","b":"גביר, דיין בירושלים-רפב בזמן ר יעקב בירב. נזכר בשו\"ת מהר\"י בירב."},{"i":5924,"n":"ארוך, יהודה מאזמיר","b":"מדייני איזמיר"},{"i":5925,"n":"ארוך, יצחק מירושלים","b":"מחכמי קושטא, עלה לירושלים. גיסו של ר יצחק הכהן רפפורט בעל \"בתי כהונה\". חתם על תקנות בירושלים-תצז, ועל כתב שליחות ר אברהם ן אשר ור יצחק זרחיה אזולאי-תקא. מוזכר אצל מהר\"ם ן חביב בספרו. הסכים על הספרים \"חזון נחום\" (תקב) \"נחפה בכסף\" (תקה) ו\"פרי האדמה\" (תקז)."},{"i":5926,"n":"ארוך, ישעיה מאזמיר","b":"מחכמי אזמיר."},{"i":5927,"n":"ארוך, מאיר מכיאו","b":"שליח בי\"ד בכיאו-שע אצל ר כלב קלפי."},{"i":5928,"n":"ארוך, מיכאל משלוניקי","b":"מדפיס בדפוס חיים אברהם בן שבתי נחמה וסעדי הלוי-תקנח."},{"i":5929,"n":"ארוך, מנחם מספרד","b":"רב בספרד בזמן הריב\"ש והתכתב עמו. רב בסלמאנקה, סמורה."},{"i":5930,"n":"ארוך, משה מקושטא","dt":"שעד - אחרי","b":"דיין בקושטא-שנט. נזכר בשו\"ת מהרי\"ט-שט."},{"i":5931,"n":"ארוכים, משה משלוניקי","b":"מחכמי שלוניקי, חתם על ההסכמות הראשונות - שנות הר'. עלה לארץ."},{"i":5932,"n":"ארוליא ן, אהרן אברהם מפיליבי","k":"בעל מים החיים","bt":"תקי","bp":"אדרינופול","dt":"תקעט - יח ניסן","dp":"פיליבי","b":"מו\"ץ בקושטא, רב בפיליבי(=פיליפופולי) על מקום ר יהודה סיד בעל \"אות אמת\" ור משה הלוי על מקומו אחריו. היה מעורב במחלוקת בקהלת רוסג'וק בין ר מנחם בכמוהר\"ר מרדכי ובין ר יקיר גירון. בנו - ר חיים, חיבר \"מים החיים\" ובו הרבה מפסקי אביו."},{"i":5933,"n":"ארוליא ן, דוד מאדרינופול","b":"דיין באדרינופול-תקנט אצל ר יקיר אסטרוק גירון יחד עם ר מרדכי אלגזי."},{"i":5934,"n":"ארוליא ן, חיים יצחק מתתיה","f":"אברהם אהרן","k":"בעל מים חיים","b":"רב ומו\"ץ בפיליבי(=פיליפופולי), חיבר \"מים חיים\" שו\"ת וחידושים. לפי שם הגדולים השלישי אביו היה - ר אברהם ן ארגיל)."},{"i":5935,"n":"ארוליא ן, חיים מפיליפופולי","f":"אהרן אברהם","k":"בעל מים החיים","b":"רב בפיליפופולי-תקץ בערך על מקום ר יעקב פינץ (שעבר לבאזארג'יק בגלל מחלקות בקהלה). חיבר \"מים החיים\" ובו גם רבים מפסקי אביו."},{"i":5936,"n":"ארוליא ן, יום טוב משלוניקי","bp":"שלוניקי","b":"רב בשלוניקי-שנות ה-ש', ברוסה, ור גבריאל בן אליה ממצרים על מקומו אחריו. נזכר ב\"דברי ריבות\"."},{"i":5937,"n":"ארוליא ן, מתתיה מקושטא","b":"מחכמי קושטא-שנות ה-ת'. תשובה ממנו ב\"רב יוסף\"."},{"i":5938,"n":"ארוליא ן, מתתיהו מקושטא וברוש","b":"מחכמי קושטא-שנת ת', רב בברושא."},{"i":5939,"n":"ארוליא, עזרא מפיליפופולי וירו","bt":"תקצג","bp":"פיליפופולי (בולגריה)","dt":"תרעו - יא אדר","dp":"ירושלים","b":"רב בפיליפופולי-תרנג, עלה לירושלים-תרסה, חתנו היה ר אברהם פינטו."},{"i":5940,"n":"ארוליה אברהם אבן","bt":"1750","dt":"ה'תקעט 1819","bk":[["מים החיים",""]]},{"i":5941,"n":"ארונובסקי, יצחק צבי מקובנא","f":"יעקב קופל","k":"בעל יד יצחק","bt":"1850","dt":"תרפא","b":"ראב\"ד בקובנא אצל ר יצחק אלחנן. חיבר גם \"תרומת יצחק\".","bk":[["יד יצחק","מפרשי רמב\"ם"],["תרומת יצחק [על שו\"ע יו\"ד]",""]]},{"i":5942,"n":"ארוש מברדיטשוב","b":"תלמיד ר לוי יצחק מברדיטשוב. נזכר ב\"אורח לחיים\"."},{"i":5943,"n":"ארושדי, יעקב מאלגיר","dp":"תלמסאן - ליד","b":"צדיק נערץ על יהודי ווהראן ותלמסאן. קברו מצפון לתלמסאן."},{"i":5944,"n":"ארזי, מנשה הכהן","f":"רפאל","k":"בעל אלפי מנשה","bt":"תקפז","bp":"טבריה","dt":"תרסב - יד שבט","dp":"טבריה","b":"מחכמי טבריה, בשנת תריג בשליחות במרוקו, ובתריט, בשנת תרלד בשליחות באלגיר. חיבר \"אלפי מנשה\" תרנב. בניו - ר בכור יצחק ור משה חיים."},{"i":5945,"n":"ארזי, רפאל הכהן מטבריה","bt":"תקנא","bp":"דמשק","dt":"תרכט - אד\"ב","dp":"טבריה","b":"מחכמי דמשק, עלה לטבריה-תקסט. חתם על כתב שליחות ר יצחק אירגאס-תקפא, בשליחות במרוקו וסוריה-תקצב יחד עם ר חיים אשכנזי. חתם על העצומה נגד הריפורמים-תרו. חתם על יסוד ישיבת \"בית יעקב\"-תריג. מתורתו בספר בנו \"אלפי מנשה\". השאיר שו\"ת ודרושים בכתב יד."},{"i":5946,"n":"ארזין, יוסף ממצרים וצפת","f":"יעקב","dt":"שעה - אחרי","b":"מחכמי מצרים, עלה לצפת ויצא בשליחות. בשנת שכ\"ח שהה בשלוניקי ור משה אלמושנינו דרש לכבודו (והתפרסם בספרו \"מאמץ כח\"). בשובו נמנה על ראשוני תלמידי הארי, ובשנת שלה חתם על התחייבות תלמידי הארי. חיבר קונטרס על האדרא רבה, וחלק מדבריו נדפס בספר \"קול ברמה\" לר יעקב צמח. בספרי ר חיים ויטאל מאמרים בשמו."},{"i":5947,"n":"ארזין, יעקב משלוניקי","b":"דיין בשלוניקי-שיט."},{"i":5948,"n":"ארזך, מרדכי דב מקוזלוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":5949,"n":"ארחא ן, אברהם מחברון","b":"רב בחברון חתם בשנים תעז - תפז על מכתבי בקשה של הקהלה"},{"i":5950,"n":"ארחא ן, פנחס מחברון","f":"אליעזר מחברון","b":"מחכמי חברון. חתם על כתב שליחות ר חייא דיין."},{"i":5951,"n":"ארחא, אליהו מחברון","f":"אליעזר","b":"מחכמי עזה, חברון, בשנת תפח שליח לקרים, בשנת תץ בטריפולי, בשנת תצג באיטליה, בשנת תקד חתם על אגרת שליחות החידא, בשנת תקכג על אגרת שליחות ר רחמים באג'יו ועוד, בשנת תקלג הסכים על ספרו של החידא \"ברכי יוסף\""},{"i":5952,"n":"ארחא, אליעזר מחברון","b":"מחכמי חברון, חתם על תעודות בשנת תקכג, בשנת תקמח חתם על אגרת שליחות ר שמואול הכהן, בשנת תקנב על אגרת שליחות ר אפרים נבון ור יהודה ליאון, ועוד"},{"i":5953,"n":"ארחא, אליעזר מעזה - א","f":"יצחק מצפת","dt":"תיב - טו חשון","dp":"חברון","b":"רב בעזה בשנת שס, אחותו ברוילה סבלה בשנת שפה מגזרות אבן פארוך כמופיע בספר \"חרבות ירושלים\", עבר לחברון, בשנת שסו חתם בחברון על מכתב ובשנת שעו חתם על מכתב בקשה עם חכמי חברון. בשנת שפג רבה של ירושלים, בה כתב הסכמה ל\"זהרי חמה\" לר אברהם אזולאי, עמד בקשרי מכתבים עם רבים מחכמי דורו, כתב כמה ספרים שלא נדפסו. חלק מתשובותיו בספר \"נבחר מכסף\" לר יאשיהו פינטו, בשות ר יום טוב צהלון, אחת מתשובותיו בקשר לאפורופסי בתו היתומה של השלה. כתב יד דרושים המיוחס לר שמואל גרמיזן, הנמצאבמכון, לדעת בניהו כתב היד של ר אליעזר. נכדיו: ר אליהו ר אליעזר ור יוסף כולם מחכמי חברון ור אהרן בן חיים השני. בשנת תח רב בחברון והסכים על \"ברית אברהם\" לר אברהם גדליה. חיבר פירוש על \"עין יעקב\"."},{"i":5954,"n":"ארחא, יוסף מחברון","b":"מחכמי חברון, בשנת תקמח חתם על אגרת בקשת עזרה."},{"i":5955,"n":"ארחא, יצחק מחברון","f":"אליעזר","b":"מחכמי חברון, חתם על כתב שליחות ר חייא דיין בשנת תכא, ועל כתב שליחות ר יוסף הלוי בשנת תמט. אחיו היה ר פנחס בן ארחא."},{"i":5956,"n":"ארחא, יצחק מצפת - הזקן","b":"מחכמי צפת-רצח, נמנה על 25 הרבנים שהכתירו את ר יעקב בירב כמוסמך הראוי להסמיך אחרים."},{"i":5957,"n":"ארחא, יצחק שלום מצפת חברון ועז","f":"אברהם","b":"מחכמי צפת-שע, תלמיד האר\"י. עבר לחברון ובשנת שעט לעזה ובשנת שפה התמנה לרב שם. חתום בתשובה על ר יוסף קארו בשו\"ת מהר\"י די לאטיש. בנו - ר אליעזר."},{"i":5958,"n":"ארחא, ירמיה מבלגרד","b":"מראשי קהלת בלגרד-תן."},{"i":5959,"n":"ארחא, פנחס מחברון","f":"אליעזר","dt":"תכב","dp":"חברון","b":"רבה של חברון, אחיו של ר יצחק בן ארחא, חתם על כתב שליחות ר חייא דיין בשנת תכא."},{"i":5960,"n":"ארחא, שמואל מקושטא","b":"מחכמי קושטא-שנות ה-ש'-ת'."},{"i":5961,"n":"ארטן, אברהם מתל אביב","b":"מחשובי החסידים בתל אביב, חתם-תש בערך על הכתרת ר שמואל אליהו טאוב כרב שכונה בתל אביב."},{"i":5962,"n":"ארטר, יצחק מלבוב","f":"שלמה","k":"בעל גלגול נפש","bt":"1791","bp":"פרמישלא - ליד","dt":"תריא - יז ניסן","dp":"ברודי","b":"רופא, משכיל, מחבר, מורה בלבוב-תקעו, והתחבר עם המשכילים שלמה ליב רפפורט, ויהודה ליב מיזיס - ויצא חרם כנגדם מאת ר יעקב אורנשטין, עבר לברודי ולימד בבית ספר. למד רפואה בבפעסט-תקפה. חיבר כתבים כנגד החסידות ובהם \"תלונות סני וסנסני וסמנגלוף\"."},{"i":5963,"n":"ארי, אברהם מרדכי מפלשטין","f":"פנחס אריה מטורקא"},{"i":5964,"n":"ארי, אלכסנדר סנדר מוינה","f":"אלעזר","bt":"תרנח","bp":"וינה","dt":"תשנג","dp":"ירושלים","b":"נכד ר יעקב ארי מטורקה. גדל אצל סבו ר ישראל משה צוקר מגלוגוב. עלה לארץ והיה תלמיד ר זליג ברוורמן ממאה שערים. חתן ר שמואל בריכטא. חסיד אדמורי רחמיסטריבקה ומחותן עמם."},{"i":5965,"n":"ארי, דויד מקריפטש","f":"פנחס אריה","k":"בעל קול דודי","bt":"תרלו","dt":"תשב","b":"חתן דודו ר משולם זושא גלר משמישל. רבה של קריפטש על מקום זקנו ר אברהם גלר. חיבר \"קול דודי\" פיעטרקוב תרצה, ועוד."},{"i":5966,"n":"ארי, חיים מסנוק","f":"פנחס אריה מטורקא","bt":"תקסח","dt":"תרכה","b":"רבה של סנוק-תרך. בניו ר צבי הירש בעל \"כתפת האפד\" ור אברהם בעל \"אמרת הצרופה\"."},{"i":5967,"n":"ארי, יהודה ליביש מגלוגוב","f":"פנחס","bt":"תקל","dt":"תקץ","b":"רבה של גלוגוב, חמיו של ר פנחס אריה מטורקה בן אחיו."},{"i":5968,"n":"ארי, יעקב מברזוב וטורקא","f":"פנחס אריה מטורקא","bt":"תקע","dt":"תרטו","b":"רבה של ברזוב, וטורקה-תריג על כסא אביו. חתן ר צבי אלימלך הבני\"ש, ובזיוו\"ש חתן ר משה שינפלד חתן הבני\"ש. בנו ר אברהם יהושע השל מברטש, ר אליקים - ממקורבי הדב\"ח - עבר לקאשוי ונקרא אוהר."},{"i":5969,"n":"ארי, פנחס אריה מטורקה","f":"צבי הירש מסוקולוב","k":"בעל חשב האפוד","bt":"תקן","dt":"תריג - כז תשרי","b":"חתן דודו ר ליביש מגלוגוב. רב בדינוב-תקפה, גלוגוב, טורקה. תלמיד החוזה מלובלין, חיבר \"חשב האפד\" למברג תרכב, ועוד. בניו: ר יעקב מברזוב וטורקא, ר חיים מסאניק, ור אברהם מרדכי מפלשטין."},{"i":5970,"n":"ארי, צבי הירש מסוקולוב","f":"פנחס","k":"בעל אמרת הצרופה","bt":"תקלה","dt":"תקעו","b":"תלמיד החוזה מלובלין. רבה של סוקולוב. חיבר \"אמרת הצרופה\" למברג."},{"i":5971,"n":"אריא, ה' לואיס מאנגליה","b":"גביר באנגליה. יסד בימ\"ד לרבנים בשם \"אריא קאלירזש\"."},{"i":5972,"n":"אריאל, יצחק מקושטא","bt":"תריח","dt":"תרצב - יט תשרי","dp":"קושטא","b":"ראב\"ד בקושטא, ניסה לתקן קידושין על תנאי. הניח חבורים בכת\"י."},{"i":5973,"n":"אריאלי, יצחק מירושלים","k":"בעל עינים למשפט","bt":"תרנז","dt":"תשלד - יג ניסן","b":"תלמיד הרב קוק בירושלים. ממיסדי ישיבת \"מרכז הרב\" בירושלים. רב שכונת כנסת ישראל."},{"i":5974,"n":"אריגור יצחק אריה בן נתן","bt":"1902","dt":"ה'תשלט 1979","bk":[["הרב צבי הירש קלישר",""],["ספר לבני מצוה",""]]},{"i":5975,"n":"אריגור, יצחק","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":5976,"n":"אריה זאב מפאקריי","f":"שלום","b":"דיין בפאקריי, חתם-תרטז עם ר יצחק אליהו בן זאב, ור יהודה אריה בן ראובן."},{"i":5977,"n":"אריה יהודה יוסף מואנדסבק","f":"יוסף יוזפא","k":"בעל תמורת איל","dt":"תקלח - כא טבת","dp":"וונדסבק","b":"ש\"ץ, דרשן ופרנס בואנדסבק והמבורג."},{"i":5978,"n":"אריה יהודה ליב באמזו ממיקלניץ","bt":"תק","dt":"תקפה","b":"תלמיד הבעשט בצעירותו, תלמיד ר שמואל שמלקא מניקלשבורג. התגורר בסטנוב, מיקלניץ. מתורתו ב\"כליל תפארת\", ו\"באר שרים\". חתניו: ר משה שור - אביו של ר ישעיה שור אב\"ד יאס, ור ישעיה פאהריללע ממיקלניץ."},{"i":5979,"n":"אריה יהודה ליב הכהן מירושלים","f":"אפרים-שער אפרים","bt":"תיח","bp":"וילנא","dp":"צפת","b":"חתן הגביר ר יהודה בן ידידיה מבודון. רב באויבן ועזר לאביו בראשות הישיבה, עלה לירושלים-תמו, והצטרף לישיבת ר משה גלנטי, ובעזרתו עסק בסדור כתבי אביו. בשנת תמז חזר לאירופה והדפיס את ספר \"שער אפרים\" לאביו, חזר לירושלים והיה מראשי הקהלה. בשנת תס בשליחות לאיטליה, בשנת תסד עם משלחת רבנים לקושטא בנושא המלחמה בשבתאים, הדפיסו כרוז בשם \"לעיני כל ישראל\". מדברי תורתו כלולים בספרו של אביו, ובקונטרס האחרון הוא מתפלפל עם ר אליהו שפירא מפרג בעל \"אליהו רבה וזוטא\". בנו ר ידידיה הכהן היה חתנו של ר אברהם יצחקי. כאשר הגיע ר אברהם רויגו לירושלים התאכסן בביתו של ר אריה, שהיה נמנה על ישיבתו של ר אברהם."},{"i":5980,"n":"אריה יהודה ליב הלוי מברוד","f":"עקיבא","k":"בעל לב אריה","bt":"תקי-יט","bp":"ברודי","dt":"תקעח - כט שבט","b":"תלמיד בעל \"ספר החכמה\", ור יונתן איבשיץ. רב בברודי-תקמו, פודהייץ-תקסד ראב\"ד בברודי-תקעג. חיבר \"לב אריה\" אוסטרהא תקף, ועוד."},{"i":5981,"n":"אריה יהודה ליב הלוי מלובלין","f":"יצחק איזיק אב\"ד לובל","bt":"תעא","dt":"תפח - יד כסלו","dp":"לובלין","b":"נפטר בגיל 17."},{"i":5982,"n":"אריה יהודה ליב המוכיח מפולנאה","f":"יחיאל מיכל","k":"בעל קול אריה","r":"תלמיד הבעש\"ט","dt":"תקל - כא טבת","b":"מוכיח,משפיע,תלמיד הבעש\"ט,מגיד בפולנאה.","bk":[["קול אריה – עה\"ת",""]]},{"i":5983,"n":"אריה יהודה ליב חסיד מבאניהאד","k":"בעל פני אריה","bt":"ה'תקיט","dt":"תקעו - כג שבט","b":"רב בבאניהאד(=בניהאד).","bk":[["לב אריה [עמ\"ס חולין]",""]]},{"i":5984,"n":"אריה יהודה ליב חסיד מלבוב","f":"משה מייזלס","k":"ר ליב חסיד מלבוב","dt":"תנד - יג אייר","dp":"פרמישלא","b":"מצאצאי הרמ\"א. מקובל, ר\"מ בלבוב, רב בפרעמישלא. הסכים על \"גבורות אנשים\"-לאביו של הש\"ך. חתם בלבוב על תקנות הקהלה עם ר הלל בעל \"בית הלל\" מזולקוא. חתנו - ר יוסף חריף סגל-בנו של ר משה חריף מלבוב, בנו (או חתנו) - ר אלכסנדר מאפטא, ונכדו - ר אריה יהודה מירושלים. (באוצר הרבנים יש כפילות וטעות)."},{"i":5985,"n":"אריה יהודה ליב מאוסטרהא","f":"יונה מאוסטראה","k":"ליבוש פראדילס","dt":"תקפט - טז שבט","dp":"אוסטרהא","b":"מחכמי אוסטרהא (באוצר הרבנים - רב בקראקא). נתפרסם בידי החוזה מלובלין שהגיד שבחו בפני אנשי אוסטרהא ומאז נהגו בו כבוד ובקשו את ברכותיו."},{"i":5986,"n":"אריה יהודה ליב מאוסטרהא","f":"פנחס מלודמיר אוסטרהא","dt":"תקסז - אחרי","b":"חתן ר נחמן בן בצלאל כץ מאוסטרהא. פרנס באוסטרהא. מבניו: ר שמואל אשר פרנס באוסטרהא-תקנח, ר שמחה מאוסטרהא"},{"i":5987,"n":"אריה יהודה ליב מאוסטרהא","f":"שמואל","b":"דיין באוסטרהא אצל ר אברהם משלם זלמן אשכנזי. חתם על צוואת הגביר ר יוסף יוזפא אוסטרר עם ר דוד שבח בן ישראל אברהם."},{"i":5988,"n":"אריה יהודה ליב מזולקוא","f":"מרדכי מזולקוא","b":"מראשי קהלת זולקוא, חתם-תם על תקנת הקהל, וכן בשנת תמט."},{"i":5989,"n":"אריה יהודה ליב מיורבורג-ליטא","b":"רב ביורבורג בזמן הגר\"א. היה מועמד לרב בניישטט-סיגונד כנגד ר נחום חריף - והיה מחלוקת גדולה ביניהם ולאחר שזכה ברבנות ויתר עליה). בניו - ר ראובן יהושע זליג מפילטען, ר יצחק משילאל, ר אליהו מראגולה."},{"i":5990,"n":"אריה יהודה ליב מסקול","f":"שמואל גרשון סירקיש","k":"בעל לוית חן","dt":"תפט - כג אדר","dp":"זולקוא","b":"רב בסקאהל, זאלקוא. מצאצאי הב\"ח ובעל \"יפה תואר\". חיבר \"לוית חן\" ו\"אור יקרות\" ונדפסו בידי בנו - ר יוסף בנימין זאב - זולקוא וונציה תקב."},{"i":5991,"n":"אריה יהודה ליב מרוסטיץ","f":"מנחם מנדל","bt":"תץ - בערך","dt":"תקסו","b":"נכד ר דוד איסרל טריווטש-חתן ר מנחם מנדל קרוכמל. רב במזריטש, בסקביץ, דיין בניקלשברג."},{"i":5992,"n":"אריה יהודה ליב מרכניץ","k":"בעל עולת ראיה","dt":"תקפז - ו אלול","b":"רב ברכניץ(=רוהונץ)."},{"i":5993,"n":"אריה יהודה ליבוש מלנצהוט","f":"ברוך","k":"בעל ארבעה חרשים","bt":"תקיז","dt":"תקפו - כח חשון","b":"תלמיד המגיד מקוזניץ ושל החוזה מלובלין. רבה של לנצהוט-תקלז (התחבב על הגרף פוטוצקי שתרם לו כספים לצדקה), רב בקישינוב-תקעט. חיבר גם \"גבורת אריה\", ועוד. י\"א תאריך פטירתו - א חשון תקפד."},{"i":5994,"n":"אריה יהודה ליבש","bt":"תקג","dt":"תקפח"},{"i":5995,"n":"אריה יהודה מאפטא וירושלים","b":"מראשי העדה האשכנזית בירושלים-תקו, יחד עם ר אברהם גרשון קיטובר."},{"i":5996,"n":"אריה יהודה ממקיליניץ","b":"חריף,בקי,עשיר גדול,רב במקיליניץ-תק\"ל"},{"i":5997,"n":"אריה יהודה מקראקא","b":"רב בקראקא. בנו - ר בנימין ונכדיו - ר צבי הירש בשקא מאה\"ו, ר משה שלמה זלמן מקראקא."},{"i":5998,"n":"אריה יעקב מסמילא","dt":"תקפז - י אב","b":"רב בסמילא-תקס."},{"i":5999,"n":"אריה ליב","f":"צבי"},{"i":6000,"n":"אריה ליב","dt":"תקמט - ו אדר"},{"i":6001,"n":"אריה ליב","f":"נחמן מפינסק","b":"גביר תלמיד חכם."},{"i":6002,"n":"אריה ליב","f":"צבי הירש מלוקטש-חמדת","b":"בנו - ר שמחה נתן מלבוב."},{"i":6003,"n":"אריה ליב אברהם הלוי מלובלין","f":"שאול מזסלב","dt":"תקעט - ג טבת","dp":"לובלין","b":"מחכמי לובלין. רב בזאסלב."},{"i":6004,"n":"אריה ליב בהרא\"ד מירושלים","f":"ראה: הרשלר, אריה ליב"},{"i":6005,"n":"אריה ליב בהר\"צ מירושלים","k":"ליב דיין","b":"רב בירושלים-תרע"},{"i":6006,"n":"אריה ליב די מימלס מלמברג","f":"יוסף ממוסט","dt":"תקעו - כ סיון","b":"נכד ר יעקב יהושע בעל \"פני יהושע\". תלמיד החוזה מלובלין, שהיה גיסו-בעל אחותו - בזיוו\"ש שני. הקים את השטיבל החסידי הראשון בלמברג, וצדיקי הדור סעדו על שלחנו."},{"i":6007,"n":"אריה ליב דיין מלובלין","k":"בעל ליקוטי האור","b":"מחכמי לובלין. חיבר ספר על הלכות קדוש החדש לרמב\"ם."},{"i":6008,"n":"אריה ליב דרשן מפוזנא","dt":"תצז","dp":"פוזנא","b":"דיין בפוזנא. נאסר ערב ראש השנה תצז בעלילת דם עם כמה מראשי הקהלה. נהרג עק\"ה. תיאור המעשה בהקדמת \"עמודי עולם\" ברלין תקא."},{"i":6009,"n":"אריה ליב הכהן","f":"שמואל מאמדור","b":"חתן ר רפאל הכהן מהמבורג. בנו - ר בריה מנדל, ונכדו - ר אברהם ממינסק."},{"i":6010,"n":"אריה ליב הכהן","b":"חתנו - ר נח בלוך (הנקרא ר נח פעטליצער - כך לפי ברוורמן)."},{"i":6011,"n":"אריה ליב הכהן מירושלים - ב","b":"מראשי הכולל בירושלים-תרן."},{"i":6012,"n":"אריה ליב הכהן מצפת","dt":"תרז","dp":"ירושלים","b":"ממיסדי הישוב האשכנזי בצפת, שימש את גדולי תלמידי הגרא, עבר לירושלים"},{"i":6013,"n":"אריה ליב הכהן מקלוש","f":"יוסף הכהן מקאליש","k":"בעל קצות החושן","r":"האדמו\"ר מסדיגורא","bt":"תקה","bp":"מקלוש","dt":"תקעג - יט טבת","b":"רב ברוזניאטוב, סטרי-תקמח. מתנגד לחסידות. חיבר \"קצות החושן\" למברג תקמח, ועוד.","bk":[["קצות החושן",""],["שב שמעתתא, קצות החושן – חו\"מ , אבני מילואים – אה\"ע",""]]},{"i":6014,"n":"אריה ליב הלוי","f":"נפתלי הרץ","b":"קרובו של המהרש\"א. חתן ר שלמה זלמן בן יהודה הלוי- הראב\"ד בוילנא. בנו - ר יחיאל מיכל בעל \"שערי שמים\"."},{"i":6015,"n":"אריה ליב הלוי מווסברין","dt":"תקצו - ו אד\"ב","b":"רב בגרוגנדורף,ווסברין-תקע\"ו"},{"i":6016,"n":"אריה ליב הלוי מטיקטין","f":"מרדכי הלוי","k":"בעל גבורות ארי","dt":"תקצח - יז תשרי","b":"רב בטיקטין-תקעז על מקום ר משה זאב מרגליות בעל \"אגודת אזוב\" שעבר לביאליסטוק (ושהיה על מקום אביו בטיקטין). חיבר גם \"אסיפת הגאונים\" ובו משא ומתן הלכתי בין זקנו - ר העשל מקראקא ובין בעל \"חלקת מחוקק\"."},{"i":6017,"n":"אריה ליב הלוי מסטריזשוב","f":"יהודה הלוי","b":"רב בסטריזשוב-תק\"מ"},{"i":6018,"n":"אריה ליב הלל מנובואלכסנדרובסק","b":"רב בנובי-אלכסנדרובסק(=נאויליקסאנדריסקי)."},{"i":6019,"n":"אריה ליב המגיד מויליאמפול","f":"יחזקאל פייבל מוילנא","bt":"תקנ","dt":"תרכו - ח כסלו","b":"חתן הגביר ר הענך נאוויאזער מקובנא. דרשן, מרבני ויליאמפול(=סלובודקא). בנו - ר פייבל מוילנא, חתניו - ר ברוך וולף גורפניקל-רופא, ר מיכאל בן אברהם מרדכי רבינוביץ מוילנא, דיין בדושאט (לא ידוע שמו)."},{"i":6020,"n":"אריה ליב זאב ממיר ווילנא","f":"יוסף","dt":"תקף","dp":"וילנא","b":"מחכמי מיר, וילנא."},{"i":6021,"n":"אריה ליב חסיד מסלונים","dp":"צפת","b":"מעולי ארץ ישראל תלמידי הבעש\"ט-תקעג. נפטר בגיל 36. נכדו - ר משה אליעזר דן רלב\"ג."},{"i":6022,"n":"אריה ליב חריף מהומול","k":"בעל קול אריה","b":"רב בהומול(=האמלי)-תר. חיבר גם \"אם למסורה\". נכדו ר שניאור זלמן בן מנחם מנדל מחברון הו\"ל את ספרו \"קול אריה\" בירושלים."},{"i":6023,"n":"אריה ליב חריף מסלוצק","f":"שלמה חריף מסלוצק","dt":"תסו - ו אלול","b":"רב בסלוצק. אחיו - ר אברהם אבלי מבריסק. (ראה גם: אריה ליב סלוצקר)"},{"i":6024,"n":"אריה ליב לוקשטר מברוד","b":"מחכמי ברודי. ממנו ב\"אמתחת בנימין\"."},{"i":6025,"n":"אריה ליב ליאון מירושלים","b":"דיין בירושלים-תקצב ומראשי כולל הפרושים. חתם עם ר חיים הורביץ-תקצב."},{"i":6026,"n":"אריה ליב מאוסטרהא","f":"אשר אנשל","k":"ליב ר אנשיל'ש","dt":"תקעד - יח אלול","dp":"אוסטרהא","b":"מצאצאי המהרש\"א - ונקבר לידו. מחכמי אוסטרהא. בנו ר אפרים דדין בדיקלוב."},{"i":6027,"n":"אריה ליב מאוסטרהא","f":"חיים סגל","b":"דיין וש\"ץ באוסטרהא. הסכים על \"עין יעקב\"-תקעא, ועוד. אולי אחיו של ר שמואל ר יקיר'ס מאוסטרהא."},{"i":6028,"n":"אריה ליב מאוסטרהא","f":"ישראל רב דחייטים","dt":"תקפו - יז שבט","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":6029,"n":"אריה ליב מאמשטרדם","b":"רב באמשטרדם. בנו - ר דוד."},{"i":6030,"n":"אריה ליב מאפטא","b":"רב באפטא-תקנ\"א,סאחטשוב,התיישב בוורשה"},{"i":6031,"n":"אריה ליב מבוטושאן","f":"ישכר","dt":"תקעד","b":"תלמיד ר חיים מטשרנוביץ."},{"i":6032,"n":"אריה ליב מבוסק","b":"דרשן,רב בבוסק-ת\"כ"},{"i":6033,"n":"אריה ליב מביזוונגין","f":"יהודה זליגמן","b":"מחכמי ביזוונגין-שוואבין, הגהות ממנו-תקלב על הספר 'שפע טל'."},{"i":6034,"n":"אריה ליב מבסקוביץ","dt":"תקטו - כז אדר","b":"רב בבסקוביץ"},{"i":6035,"n":"אריה ליב מברדיטשוב","f":"מרדכי","b":"דיין בברדיטשוב אצל ר לוי יצחק"},{"i":6036,"n":"אריה ליב מבריסק","b":"רב בבריסק-תק\"י"},{"i":6037,"n":"אריה ליב מגיד מדרוהוביטש","b":"תלמיד ר חיים חייקא מאמדור."},{"i":6038,"n":"אריה ליב מגלוגוב","b":"תלמדי החוזה מלובלין. אב\"ד גלוגוב."},{"i":6039,"n":"אריה ליב מדוברומיל","b":"רב בדוברומיל-תקל. חתן ר יוקיל הורביץ."},{"i":6040,"n":"אריה ליב מדרוהוביטש","k":"המגיד מדרוהוביטש","dt":"תקסז - א אב"},{"i":6041,"n":"אריה ליב מהורדנא","f":"אלכסנדר זיסקינד","dt":"תקצב - כב סיון","dp":"הורדנא","b":"ראש הקלויז בהורדנא. (אביו הוא בעל \"יסוד ושורש העבודה\")."},{"i":6042,"n":"אריה ליב מהורדנא","f":"משה","b":"מחכמי ירושלים, מוכר בפנקס ח\"ק בשנת תר"},{"i":6043,"n":"אריה ליב מהמבורג","f":"שאול","dt":"תקעא - יג טבת","dp":"אלטונא","b":"תלמיד ר אלעזר לאזי היילבוט-ברלין. גביר עשיר, פרנס קהלת אה\"ו, הקים בימ\"ד המכונה \"ר ליב בר שאול קלויז\"."},{"i":6044,"n":"אריה ליב מהנובר","b":"רב בהנובר."},{"i":6045,"n":"אריה ליב מואליסטשיק","b":"רב בוואליסטשיק,עלה לא\"י-תק\"ע"},{"i":6046,"n":"אריה ליב מואליש וליסא","f":"משה","b":"דיין בליסא-תקך, חתם עם ר צבי הירש ברלין וחבריו על מכתב לר דוד ברלין באה\"ו."},{"i":6047,"n":"אריה ליב מוילנא","b":"רב בוילנא-תקפ. חתנו - ר חיים נחמן מדובנא."},{"i":6048,"n":"אריה ליב מוילנא","f":"אליעזר","k":"לייב לייזרס","dt":"תקמג - כא אלול","dp":"וילנא","b":"גביר בוילנא. ועוד דורות אחריו נקרא ביתו \"חצר לייב לייזרס\". פעל לטובת בית העלמין בוילנא-תקמב (עם חבריו: ר יהודה בן ליפמן, ר אברהם בן יחיאל מיכל גורדון, ליב בן ליזר, ר אברהם בן מיכל ור אריה ליב מייטעס מפינסק) בנו - אליעזר - נפטר צעיר."},{"i":6049,"n":"אריה ליב מוילנא","f":"דב בר מוילנא","k":"ליבלי ר בערס","dt":"תקצא - כד תשרי","dp":"וילנא","b":"נכד ר אליהו פעסעלעס. ניהל עסק עם דודו ר יוסף-חתן ר שמואל בן אביגדור. גבאי צדקה בוילנא, ותרם רבות גם ברחבי ליטא וגם לעניי ארץ ישראל. הגר\"א אמר עליו: \"אין זה כי אם אחד משרפי מעל\" (יצקן - אליהו מוילנא). חבר בועד בראשות ר משה בן אברהם אשר - שנבחר אחרי פטירת הגר\"א כדי ללחום בחסידות. בנו - ר יעקב מוילנא (המכונה \"ר יעקעלע ר ליבעלעס\"). חתניו - ר יחזקאל הלוי לנדא מוילנא, ר חיים נחמן פרנס מוילנא, ר משלם פיבש מברוד בן ר מנחם מנדל מראוונע. אחיו - ר צבי הירש מוילנא המכונה - \"ר צבי די בערס\". נזכר ב\"נשמת אדם\" לר אברהם דנציג, שגם הקדיש לו את ספרו \"תולדות אדם\", ועוד."},{"i":6050,"n":"אריה ליב מוילנא","f":"טוביה","dt":"תקעג-ז -יח חשון","dp":"וילנא","b":"מראשוני המדפיסים בוילנא-תקנט בערך, יחד עם שותפו ר טוביה בן אברהם אבלי רי\"ט."},{"i":6051,"n":"אריה ליב מוילנא","f":"שמעון","dt":"תקלא - כא אד\"א","dp":"וילנא","b":"מחכמי וילנא."},{"i":6052,"n":"אריה ליב מוילנא וירושלים","f":"חיים","dt":"תרג - ב חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":6053,"n":"אריה ליב מזוואלין","f":"דוד","b":"חתן ר צבי נפתלי סופר מוילנא. אב\"ד זוואלין. בנו - ר דוד לידא מאמשטרדם. גיסו - ר משה ריבקש בעל באר הגולה."},{"i":6054,"n":"אריה ליב מזולקוא","f":"מרדכי מרדיש מקמינקא","b":"מראשי קהלת זולקוא, חתם-תם על תקנת הקהל, וכן בשנת תנב."},{"i":6055,"n":"אריה ליב מזמוטשט","b":"רב בזאמוטשט-תפ\"ד-תצ\"ט"},{"i":6056,"n":"אריה ליב מחודרוב","f":"שמואל","b":"אב\"ד חודרוב, הסכים-תקב על שו\"ע באר היטב - זולקוא תקב עם ביה\"ד של זולקוא ובהם ר נפתלי הרץ הורביץ."},{"i":6057,"n":"אריה ליב מחווראן","f":"אורי","b":"רב בחווראן"},{"i":6058,"n":"אריה ליב מטאוריג (קצנלנבוגן)","f":"שאול מז'וסלי","dt":"תקצט","b":"אב\"ד טאוריג. בנו - ר שאול מראסיין. אחיו - ר מאיר רובין בעל \"מיישר תועי דרך\"."},{"i":6059,"n":"אריה ליב מטבריה","f":"אברהם","b":"ממונה \"כולל ווהלין\"-תרטו."},{"i":6060,"n":"אריה ליב מטרנוב וקראקא","f":"שמואל","dt":"תקלו - ח ניסן","dp":"קראקא","b":"רב בקראקא על מקום ר יצחק לנדא, ור יצחק הלוי בן מרדכי מלבוב על מקומו אחריו."},{"i":6061,"n":"אריה ליב מטרניגרד","f":"שמשון מטרניגרד","bt":"תס","dt":"תצד - כו כסלו","b":"רב בטרניגרד. בנו ר שמואל מטרניגרד."},{"i":6062,"n":"אריה ליב מטשיטש","f":"נחמיה","k":"בעל נעימה קדושה","b":"מחכמי טשיטש. חיבר \"נעימה קדושה\" זולקוא תקמב. גיסו ובן דודו של המדפיס ר דוד מן מזולקוא."},{"i":6063,"n":"אריה ליב מטשכנווצה","b":"מקובל,רב בטשכנווצה"},{"i":6064,"n":"אריה ליב מיורברג","b":"רב ביורברג"},{"i":6065,"n":"אריה ליב מייטעס מפינסק ווילנא","dt":"תקסז - כא ניסן","dp":"וילנא","b":"שתדלן מראשי קהילת וילנא. בשנת תקמד הצליח לקבל פסק דין מחצר המלך שסיים סכסוך בן 150 שנה בין הקהילה לבין מגיסטרט וילנא - ובעקבותיו הותר ליהודים לצאת מהגיטו ולעסוק במסחר ובוטל מס שנתי מיוחד שהיה מוטל על הקהילה. פעל לטובת בית העלמין בוילנא-תקמב (עם חבריו: ר יהודה בן ליפמן, ר ליב בן ליזר, ר אברהם בן יחיאל מיכל גורדון). בנו - ר משה זאב ליפשיץ מוילנא."},{"i":6066,"n":"אריה ליב מירושלים","f":"אליעזר מפוזן","b":"מחכמי ירושלים-שנות ה-ת'. חתם על מכתב ירושלים לברסלוי."},{"i":6067,"n":"אריה ליב מירמפולי","f":"בנימין וולף","b":"רב בירמפולי (ליד ברודשין)."},{"i":6068,"n":"אריה ליב מלאסק","f":"פנחס זליג-עטרת פז","bp":"לוסק","b":"מחכמי לוסק. בנו - ר אלעזר לעוו-מינץ בעל \"שמן רוקח\"."},{"i":6069,"n":"אריה ליב מלבוב","f":"זאב וולף","b":"דיין בלבוב, חתם-תעב עם ר משה מזאמושט, חתם-תע על קיום חתימות ר שלמה זלמן רייז ור משלם בן משה מלאצק, עם ר שמואל מרגליות ועוד, חתם-תעג עם ר דוד טבל בן מאיר, ועוד."},{"i":6070,"n":"אריה ליב מלבוב","f":"יוסף (גץ) מלבוב","b":"נכד(-אבי אמו) מהר\"ם מלובלין. מחכמי לבוב. אחיו - ר זאב וולף. גיסיו: ר משה בן דוד סגל, ר נחמן רפפורט מדובנא."},{"i":6071,"n":"אריה ליב מלבוב","f":"יהושע חיים מראווי","b":"דיין בלבוב, חתם-תצט עם ר יוסף יהושע פאלק שור, ר אלכסנדר זיסקינד בן ליב, ר ישכר בר איגרא, ועוד."},{"i":6072,"n":"אריה ליב מלבוב","f":"צבי הירש","b":"מראשי קהלת לבוב, חתם-תקד על תקנה."},{"i":6073,"n":"אריה ליב מלבוב ואמשטרדם-הזקן","f":"שאול מבריסק וקראקא","bt":"תנ","dt":"תקטו - כא ניסן","dp":"אמשטרדם","b":"חתן החכם צבי, גיסו של היעב\"ץ. רב ברישא-תפד, גלוגא-תצט, לבוב, אמשטרדם-תקא. בתולדות יעב\"ץ מביא אגרת ששלח ר משה חגיז מאלטונה אל ר אריה ליב ברישא. (בתולדות אנשי השם - לנצהוט אומר שלא כיהן בפועל בלבוב). הסכים על \"תולדות יעקב\" תפד. בניו: ר שאול מלוקטש ואמשטרדם בעל בנין אריאל, ר צבי הירש מלונדון וברלין. חתניו - ר יצחק הלוי מחעלמא וקראקא, ר שאול הלוי מהאג, ר משה ר יוסק'ס מזולקוא."},{"i":6074,"n":"אריה ליב מלבוב ואמשטרדם-הנכד","f":"שאול - בנין אריאל","b":"חתן ר יעקב עמדין-היעב\"ץ. אחיו של ר יעקב משה-אב\"ד אמשטרדם. רב באמשטרדם."},{"i":6075,"n":"אריה ליב מלובלין","f":"אברהם משה אלימלך","dt":"תקף - בערך","dp":"לובלין","b":"מחכמי לובלין."},{"i":6076,"n":"אריה ליב מלודמיר","b":"מחכמי ועד ארבע ארצות, חתם-תנג על הסכמות עם שאר חכמי הועד."},{"i":6077,"n":"אריה ליב מ\"מארי דחושבנא\"","b":"תלמיד הבעשט. היה עושה כל יום חשבון הנפש, והבעשט גילה לו את יום הסתלקותו."},{"i":6078,"n":"אריה ליב ממזריטש","b":"אב\"ד מזריטש(-ליד פוזנא)-תקפו, ומקורב לר עקיבא איגר ונזכר בתשובותיו. הסכים על שו\"ת גבר\"י - פפד\"א תקפו."},{"i":6079,"n":"אריה ליב ממינסק","k":"ליבל בעל התוספות","dt":"תצו","b":"רב במינסק על מקום ר משה ז\"ק וראש ישיבה שם, ולצדו בגליל ר משה זאב בן יהודה מקאוולי בעל \"קול יהודה\". בנו - ר יהודה מקלצק ונינו - בעל שאגת אריה, ר אשר ממינסק,"},{"i":6080,"n":"אריה ליב ממינסק","f":"אברהם פרנס מוילנא","dt":"תרלז - א כסלו","dp":"מינסק","b":"חתן הגביר ר מרדכי צבי מרשלקוביץ מדובנא. מחכמי מינסק."},{"i":6081,"n":"אריה ליב ממיקוליניץ","b":"רב במיקוליניץ. אליו ב\"זכרון יהודה\"."},{"i":6082,"n":"אריה ליב ממעמל","f":"מרדכי","k":"בעל פני אריה","b":"מחכמי מעמל. חתנו - שמואל אריה בן אליעזר מיליאן ווירנמאהן."},{"i":6083,"n":"אריה ליב מנוברדוק","k":"בעל דברי אריה-בכת\"י","dt":"תקלא - כח טבת","b":"חתן ר שמחה רפפורט מדובנא ולובלין. רב בנוברדוק(=נווברדוק) על מקום ר יצחק איזיק מלכוביץ ונוברדוק ור נפתלי הרץ בן אשר מאליק, ויטבסק. בניו - ר שמחה פריד מלענטשנא, ר מרדכי, ר אורי מקאמאי, ר נחמן מקידאן, ר זאב וולף, ר מאיר, ר צבי הירש, ר ברוך מפלוצק. חתניו - ר מרדכי מהורדנא, ר חנניה ליפמן, חתנו - ר שמואל בן אביגדור-רבה האחרון של וילנא (יש בלבול בינו לבין גיסו ר יהודה אריה איטיניגא - מי מהם היה חותנו של ר שמואל)."},{"i":6084,"n":"אריה ליב מניזנוב","f":"מנדל","b":"רב בניזנוב-תקכו, בלשביץ. אליו ב\"נדרי זריזין\"."},{"i":6085,"n":"אריה ליב מנעשוויז","dt":"תקלד - ג אדר","b":"רב בנעשוויז"},{"i":6086,"n":"אריה ליב מסדילקוב","f":"אברהם מקורסיטשוב","b":"נכד ר צבי הירש מקורשטשיב. רב בסדילקוב-תר. חתן ר דוד הלוי הורביץ מסדילקוב-חתנו של ר אפרים בעל \"דגל מחנה אפרים\". בניו ר אפרים נחום גוטמן ממאזשיר, ר אברהם דב ממזיקוב, ר ברוך יוסף מסדילקוב, ר שלום משטפינשט, ור ישראל מיאס-חתן ר יוסף לנדא מליטין בעל \"תפארת בית לוי\". מכתבים ממנו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד. גיסו של ר ישראל מרוזין (אחותו חוה היתה אשת ר ישראל)."},{"i":6087,"n":"אריה ליב מסטנוב","b":"רב בסאטנוב-תקנ\"ד"},{"i":6088,"n":"אריה ליב מסלוצק","f":"יהודה יידל-קול יהודה","dt":"תפב - יב ניסן","b":"חתן ר נפתלי הירץ גינצבורג. רב בסלוצק. (ראה גם: אריה ליב סלוצקר)"},{"i":6089,"n":"אריה ליב מסלוצק והורדנא - הזקן","f":"נתן נטע מטרניגרד","dt":"תפט - כט ניסן","b":"חתן ר זכריה מנדל בעל \"באר היטב\". רב בסלוצק-תעד, הורדנא. בניו: ר יעקב מלויצק, ר זכריה מנדל מהורדנא, ר נתן מברודי."},{"i":6090,"n":"אריה ליב מסקרקוסניצא","f":"משה","dt":"תקפח - כה ניסן","dp":"וילנא","b":"מו\"צ בסקרקוסניצא-ליד לובקא."},{"i":6091,"n":"אריה ליב מסרוצק","dt":"תקעח - א ניסן","b":"רב בסעראצק"},{"i":6092,"n":"אריה ליב מעזריטשיר מאוסטרהא","f":"משה יוסף בן משלם זלמ","dt":"תקלה - ו אייר","dp":"אוסטרהא","b":"תלמיד הבעשט, וכשחלה הצילו הבעשט. אחיו של ר משלם זלמן מעזריטשיר מאוסטרהא. מחכמי מזריטש-ליד אוסטרהא, פרנס באוסטרהא-תקכז יחד עם ר משה שמואל הרופא ועם ר נחמן כץ. בניו ר יהונתן ור ישעיה."},{"i":6093,"n":"אריה ליב מפוזנא","f":"אברהם ר חיים מלובלין","b":"חתן ר יעקב מרדכי מפוזנא. רב בפוזנא-תק\"כ. חתנו - ר יהושע הורביץ."},{"i":6094,"n":"אריה ליב מפילץ","b":"חתן ר דוד בירנבוים-אביו של ר שמואל בירנבוים בעל \"מעשה חושב\"-חתנו של ר עקיבא איגר. מחשובי חסידי ר מנחם מנדל מקוצק. (בהשפעתו סירב ר עקיבא איגר לצאת נגד חסידי קוצק). פעל להכתרת בעל \"חדושי הרי\"מ\" אחר פטירת האדמור מקוצק."},{"i":6095,"n":"אריה ליב מפינטשוב","b":"רב בפינטשוב-תקע. בנו - ר יעקב יוסף זכריה מנדל."},{"i":6096,"n":"אריה ליב מפלנטש","b":"רב בפלאנטש"},{"i":6097,"n":"אריה ליב מפמורן","b":"רב בפמורן - תשובה אליו בשו\"מ."},{"i":6098,"n":"אריה ליב מפרוסטיץ","dt":"תקנז - אלול","b":"רב בפרוסטיץ."},{"i":6099,"n":"אריה ליב מצפת","f":"נתן","b":"כורך ספרים בצפת. חתם על מכתב-תקמט, בשליחות קהילת החסידים בצפת-תקנב וחזר תקנד."},{"i":6100,"n":"אריה ליב מקובנא","dt":"יח שבט","b":"רב בקובנה"},{"i":6101,"n":"אריה ליב מקריניצא","b":"רב בקריניצא-תר\"מ"},{"i":6102,"n":"אריה ליב מקריניק וזאבלודוב","f":"ברוך בנדיט","k":"בעל שאגת אריה","dt":"תקף","b":"רב בקרינאק(=קריניק), זאבלודוב, ראב\"ד ביאליסטוק-תק\"מ"},{"i":6103,"n":"אריה ליב מקרמניץ","f":"שמואל","b":"רב בקרמניץ והגליל-תקיא-תקלה. נאמן מדינת ואהלין. הסכים על \"מנחה חדשה\" - תקלד וחתם בראש, וכן הסכים על ספרים נוספים. בנו ר שמואל מאוסטרהא. חתנו - ר יצחק איזיק מראוונא."},{"i":6104,"n":"אריה ליב מראסיין","f":"יצחק","dt":"תקע - טו שבט","dp":"ראסיין","b":"רב בראסיין. חברו של ר שמואל חסיד מראסיין."},{"i":6105,"n":"אריה ליב מרוגנדורף","b":"רב ברוגנדורף-ת\"ר"},{"i":6106,"n":"אריה ליב מרימיסק","b":"רב בריטמיסק-תק\"נ. אביו של ר אברהם בעל משכיל לאיתן."},{"i":6107,"n":"אריה ליב משברשין ולובלין","b":"אב\"ד שברשין. דיין בלובלין אצל ר שאול מרגליות-תקמג. נזכר בפנקס קובץ פסקים אודות דין ודברים שהיו לו עם ר השל בהגאון אב\"ד קראקא אודות שכירת חנות אצל ר שאול מרגליות-תקמג."},{"i":6108,"n":"אריה ליב משניפישוק","b":"רב בשניפישניאק-תרנ\"ו"},{"i":6109,"n":"אריה ליב מתתיהו מהורדנא","f":"ישראל","bt":"תקנו","dt":"תרכ-ו - יב טבת","dp":"הורדנא","b":"דיין בהורדנא-תקפה כ-35 שנה."},{"i":6110,"n":"אריה ליב פרץ מלברטוב","f":"משה","k":"בעל בית פרץ","b":"אחיינו של ר שמואל-חותנו של ר לוי יצחק מברדיטשוב. תלמיד ר שמואל שמלקא מניקלשבורג, ר ישכר בער מזלוטשוב. חברו של ר יוסף יהודה ליב מבאלטא-תלמיד המגיד ממזריטש. קירב את קרובו (חתן דודו ר שמואל פרץ) - ר לוי יצחק מברדיטשוב לחסידות. חיבר \"בית פרץ\" בכת\"י שאבד. בנו ר יהודה פרץ מלברטוב. חתנו ר יעקב יוקל מראדזין. מתלמידיו ר ישראל יונה לנדא מקמפנה, ר יצחק איזיק מלענטשנא. חתנו - ר יעקב יוקיל מראדזין."},{"i":6111,"n":"אריה ליבוש מאלפין","dt":"תרטו","b":"בא מאלפין לשמש רב בגורליץ."},{"i":6112,"n":"אריה ליבוש מבוליחוב","b":"תלמיד החוזה ומחכמי בוליחוב - עליו ב\"שארית לשארית\"."},{"i":6113,"n":"אריה ליבוש מבוצאץ לבוב","f":"יצחק מיאברוב","b":"מראשי קהלת לבוב והגליל-תפד. בנו - ר זכריה מנדל בעל \"מנורת זכריה\" ומביא מחדושיו בספריו. חתנו - ר בעריש מפודהייץ בנו של הפני יהושע."},{"i":6114,"n":"אריה ליבוש מבורשטשוב","b":"מחכמי בורשטשוב-תריא."},{"i":6115,"n":"אריה ליבוש מדרוהוביטש","b":"בנו של אב\"ד לשטשוב. מחכמי דרוהוביטש-תקע."},{"i":6116,"n":"אריה ליבוש מלנצהוט","k":"בעל גבורות אריה","b":"רב בקישינוב-תק\"ע"},{"i":6117,"n":"אריה ליבוש מקראקא","b":"רב בקראקא-תרל."},{"i":6118,"n":"אריה ליבוש מרישא","b":"מחכמי רישא ועבר לקולבסוב-תריג."},{"i":6119,"n":"אריה ליביש מאושיצא","b":"תלמיד ר ישראל אברהם מטשרני אוסטרהא (שושלת אניפולי)."},{"i":6120,"n":"אריה ליביש מויסליץ","b":"חתן ר משה דוד לידא מויסליץ. תלמיד החוזה מלובלין. אב\"ד ויסליץ."},{"i":6121,"n":"אריה ליביש מפיטערקוב","f":"אברהם דוד טעביל","k":"ר לייביש ר טעביל'ס","b":"נכד ר צבי הירש אב\"ד ברלין. נבחר לרב בפיעטרקוב אך בעצת החוזה מלובלין סירב לקבל את הרבנות. אדמור בוארשא ור יצחק מאיר-חדושי הרי\"ם בא אליו."},{"i":6122,"n":"אריה ליביש מקוזמיר","dt":"תקצה","b":"תלמיד החוזה מלובלין. מגיד בקוזמיר."},{"i":6123,"n":"אריה ליביש משידלובצא","k":"אדמור משידלובצא","dt":"תקפו","b":"תלמיד ר אלימלך מליזנסק, החוזה מלובלין, והיהודי הקדוש מפשיסחא. אדמור בשידלובצא-תקעה. מתלמידיו ר מנחם מנדל מקוצק."},{"i":6124,"n":"אריה ליביש סופר ממזבוז","f":"אהרן הנסתר","b":"תלמיד ר אברהם יהושע השל מאפטא - והפרשן המוסמך של תורתו. גיסו של ר מאיר מאפטא. סופר סת\"ם."},{"i":6125,"n":"אריה ליבש","f":"יהושע","dt":"תרעו - כה אדר","b":"רב בטאמשוב"},{"i":6126,"n":"אריה ליבש מקאריב","f":"אברהם אביש מפפד\"מ","b":"רב בקארוב"},{"i":6127,"n":"אריה מהורדנא","k":"ר' אריה הגדול","b":"דרשן,מגיד בהורדנא"},{"i":6128,"n":"אריה מזאמוט","f":"שמואל","b":"חתם על כתב רבנות ר דוד אופנהיים."},{"i":6129,"n":"אריה מזולקוא","f":"אברהם","dp":"זולקוא","b":"מחכמי זולקוא."},{"i":6130,"n":"אריה מצנסטחוב","b":"רב בטשנסטחוב-תקנ\"ו"},{"i":6131,"n":"אריה משטרשין","b":"רב בשטרעשין,לאייעוו"},{"i":6132,"n":"אריה פיבוש הלוי מגריידיץ","dt":"תקצה - יז חשון","b":"מגדולי חכמי הנובר"},{"i":6133,"n":"ארייאש, אברהם הכהן","b":"מחכמי אזמיר-תקן בערך."},{"i":6134,"n":"ארייאש, רחמים אריה אברהם הכהן","k":"בעל שפתי רננות","dt":"תקצט - כג אלול","dp":"אזמיר","b":"רב באזמיר ודיין אצל ה\"חקרי לב\". מגדולי החזנים והפייטנים. בנו ר חיים יוסף ארייאש."},{"i":6135,"n":"ארים, אברהם מטרווא","f":"גדליה מפשמישל","b":"מחכמי טרווא. הביא לדפוס \"זרע קודש\" לרנ\"צ מרופשיץ - תרסו."},{"i":6136,"n":"ארינאוויץ, בנימין","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":6137,"n":"ארינשטין, יוסף אריה מסטרי","b":"תלמיד ישיבת \"בנין שלום\" בסטרי - פרסם ב\"דגל הצעירים\" תרפז."},{"i":6138,"n":"ארינשטין, יוסף מקריווטש","b":"חתן ר אברהם אריה באבד ממיקוליניץ. בנו - ר יעקב חתן ה\"מנחת חנוך\"."},{"i":6139,"n":"אריסטולה, מאיר","k":"בעל פירוש לספר יצירה","b":"חיבר פירוש לספר יצירה. נזכר אצל ר שלמה אלקבץ בספרו \"אפריון שלמה\" - שאמר עליו כי לא כיון אל האמת."},{"i":6140,"n":"אריסקר, חיים משקלוב","b":"מגדולי חכמי שקלוב-תר\"כ"},{"i":6141,"n":"אריפול, יום טוב מדמשק","b":"מראשי קהלת דמשק-שנות ה-ת'."},{"i":6142,"n":"אריפול, יצחק מדמשק","b":"מראשי קהלת דמשק-שנות ה-ת'. (אולי בנו או קרובו של ר יום טוב מדמשק)."},{"i":6143,"n":"אריפול, יצחק ממצרים","dt":"תעז","b":"רבו של ר ישועה שבאבו. דיין עם קרובו ר מרדכי הלוי (ובנוסף היו מחותנים), תשובה ממנו ב\"דור אחד בארץ\"."},{"i":6144,"n":"אריפול, יצחק משלוניקי וצפת","b":"מחכמי שלוניקי-שנות ה-ש', עלה לצפת."},{"i":6145,"n":"אריפול, משה ממצרים","b":"מגדולי רבני מצרים-תל\"ו"},{"i":6146,"n":"אריפול, שמואל משלוניקי","f":"יצחק או יום טוב","k":"בעל שר שלום","bp":"שלוניקי","b":"מחכמי שלוניקי מקובל ומשורר, עלה לצפת-שכ בזמן הארי, תלמיד ר משה טרני. רב בצפת. חיבר \"שר שלום\" צפת שלט, \"לב חכם\", \"זבח תודה\", תשובה ממנו ב\"שמש צדקה\". חיבר חדושים ודרשות בכת\"י."},{"i":6147,"n":"אריק, אהרן יהודה מהרמילוב","bt":"תקץ","dt":"תרנב","b":"מחכמי הרמילוב, חידושיו בספרי בניו. היה מועמד לרבנות העיר-תרכה אבל ויתר לר יעקב וידנפלד."},{"i":6148,"n":"אריק, אהרן יהודה מוינה","f":"שמואל","k":"בעל דרושי זמנים-כת\"י","bt":"תרנד-ה","bp":"יזלוביץ","dt":"תשן","b":"תלמיד דודו ר מאיר אריק מטרנוב ונסמך ממנו ומאת ר\"מ שטינברג מברודי. חתן האדמור ר ברוך פנחס רבינוביץ מסקוליע. רב ביזלוביץ, ביהכ\"נ \"אחוה ורעות\" בוינה-תרף, עבר לניו יורק-תרצט וכיהן כרב ביהכ\"נ \"בית שלום\" בברונקס. חבר אגודת הרבנים באמריקה."},{"i":6149,"n":"אריק, זכריה מברוד","f":"אהרן יהודה","bt":"תרמה","dt":"תש","b":"מחכמי ברודי-תרעח, קיבל היתר 100 רבנים, חתן רא\"מ שטיינברג."},{"i":6150,"n":"אריק, יהודה מוינה","f":"שמואל","k":"בעל דרושי זמנים","bt":"תרס","b":"רב קהילה בוינה-תרף, רב בברונקס-תשא, חתן האדמור מסקוליע. חיבר \"דרושי זמנים\" בכתב יד."},{"i":6151,"n":"אריק, יוסף אריה ליביש מטרנופול","b":"חתן ה\"ר ברייטמן מטרנופול וגיסו של ר מאיר שפירא מלובלין. תלמיד ר יעקב וידנפלד מהרמילוב."},{"i":6152,"n":"אריק, ירוחם פישל מאוזיראן","f":"אהרן יהודה","bt":"תריח","dt":"תרפח","dp":"מרון (איטליה)","b":"חתן ר יהודה בר זיידמן מזלישטשיק. רב באוזריאן, וינה-תרפה."},{"i":6153,"n":"אריק, מאיר מיזלוביץ וטורנא","f":"אהרן יהודה","k":"בעל מנחת פתים","bt":"תרטו","bp":"הרמילוב","dt":"תרפו","dp":"טרנוב","b":"תלמיד ר יעקב וידנפלד מהרימלוב, נסמך ממנו וממהרש\"ם מברעזן. רב ביזלוביץ-תרמה, בוצאץ-תרעב, וינה-תרעד, טורנא-תרף. בין תלמידיו ר מאיר שפירא, ר משולם ראטה ועוד גדולים. חסיד צ'ורטקוב, עבר לוינה בשנת תרעד, רב בטרנוב, חיבר \"שירי טהרה\" בתוך \"חדושי הרמל\" קאלאמעא תרן, \"אמרי יושר\", ועוד. פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו, \"אור תורה\" - לבוב תרפו, \"בית מאיר\" - אוסטרובצא - פיעטרקוב - תרצא, \"דגל התורה\" - וארשא תרפב, \"עמק הלכה\" - וארשא תרפו, \"קובץ דרושים\" - פיעטרקוב תרפג, \"רבותינו שבגולה\" - פרשבורג תרעה, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז."},{"i":6154,"n":"אריק, מנחם מטרמבובלה","b":"מלמד בטרמבובלה."},{"i":6155,"n":"אריק, קלונימוס קלמן מטרנוב","bt":"תרס","dt":"תש-ג","b":"נכד ר מאיר ותלמידו ומהדיר ספרו \"שות אמרי יושר\". דיין בטרנוב וחבר בועד הרבנים שם. תשובה אליו ב\"חזון נחום\"."},{"i":6156,"n":"אריק, קלמן מיזלוביץ","b":"רב ביזלוביץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":6157,"n":"אריקיש, משה מספרד","b":"מגולי ספרד, והגיע לטורקיה. תשובה ממנו על מנהג טורקיה שצריך להיות מנהג ספרד כי רוב יהודי טורקיה מקורם בספרד."},{"i":6158,"n":"ארלוורוב, אליקים געץ","b":"ר\"מ ברוגאטשוב-תר\"ס"},{"i":6159,"n":"ארלוזרוב, אברהם יחזקאל מחרקוב","f":"ר\"ש","dt":"תרס","b":"חסיד חב\"ד ומקושר לאדמו\"ר. רב בחרקוב. עמד בקשרי שו\"ת עם גדולי דורו, ר משה נחום ירושלימסקי מביא ממנו בספריו. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. היה מחלוקת בקהלה ודוד קאבאק - בעל בית חרושת לבשר הקים קהלה נפרדת. הניח כתבי יד רבים שעברו למשפחת גור-ארי בקרמנצ'וג. על המחלוקת - מונדשיין - פולומוס הרבנים והשוחטים בחרקוב בקובץ 'זכור לאברהם'."},{"i":6160,"n":"ארלוזרוב, אליעזר מראמען","b":"רב בראמען-תרכ\"ח-תר\"ס"},{"i":6161,"n":"ארלוזרוב, יחזקאל מחרקוב","b":"רב בחארקוב-תר\"מ"},{"i":6162,"n":"ארליאנסקי, יצחק מארה\"ב","f":"חיים נח","bt":"תרנח","bp":"דובראווא-פלך גרודנא","b":"תלמיד ישיבות סלובודקה, נוברדוק אצל ר יוסף יוזל הורביץ. ר\"מ בישיבות \"בית יוסף\" בביעלסק-תרפג, בפינסק, קובעל(=קאוועל), בזמן השואה ברח לסיביר, ואחריה היגר לארה\"ב, כיהן כר\"מ בישיבת \"היכל התורה\" בברוקלין-תשז. חיבר חדושים בכת\"י. חבר אגודת הרבנים באמריקה."},{"i":6163,"n":"ארליאנסקי, צבי הירש שטוצין","k":"בעל דרשות מהרצא","bt":"תרכד","b":"דרשן,מגיד בלונא-תרמ\"ג,קריניאק-תרמ\"ו,שטוצין-תרמ\"ז,לונדון-תרנ\"ה,גלזגוי,לידס,ארה\"ב"},{"i":6164,"n":"ארליך, אברהם אבלי מריגא","k":"בעל הפילוסופיה של אר","bt":"תקצז-ח","bp":"מיטאוי-קורלנד","b":"תלמיד ר מיכאל זאקס בברלין, ביהמ\"ד לרבנים בברלין, בעל תואר ד\"ר. רב בנירנברג-תרלא, מורה בריגא-תרלז, טילזיט-תרנז. חיבר גם \"לרגל היהודים\", \"לקורות קהלת ריגא\"."},{"i":6165,"n":"ארליך, אהרן","k":"א. אריאל","bt":"תרסג","bp":"גלינא","dt":"תשג","b":"מהנהגת תורה ועבודה בגליציה. עלה לארץ-תרצג, חזר לפולין ולמד בביהמ\"ד לרבנים בוארשא. נספה בשואה. פרסם קטעי זכרונות בספר היובל לכבוד רבו מהרם שפירא. פרסם בעתוני התקופה."},{"i":6166,"n":"ארליך, אהרן מיאנקוביץ ואישאק","f":"יעקב ערליך","b":"רב באישאק,יאנקובץ-תר\"כ"},{"i":6167,"n":"ארליך, אפרים מפודגורע","b":"מחכמי קראקא. מחנך בחצר האדמור מבובוב. רב בפודגורזע."},{"i":6168,"n":"ארליך, ארנולד מניו יורק","k":"בעל מקרא כפשוטו","bt":"1848","bp":"ואלדוואקא","b":"תלמיד ביהמ\"ד לרבנים בברלין, לייפציג. היגר לארה\"ב-1878 ולימד ב\"יונייטד היברו טשאריטיס\". חתם על ספרו בשם - \"שבתי בן יום טוב אבן בודד\"."},{"i":6169,"n":"ארליך, בעריש מוארשא","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":6170,"n":"ארליך, יהודה","dt":"תשד","b":"עניו,רב בירדהאז"},{"i":6171,"n":"ארליך, יהודה ליבוש מברגסאס","f":"נפתלי ערליך","dt":"תשד","b":"רב בברגסאס"},{"i":6172,"n":"ארליך, יהודה ליבוש מרוזדול","f":"אברהם משה מאוסטרא","bt":"תקן","dt":"תרך","b":"רב בראזלא-תר. בן דודו של ר צבי הירש מזידיטשוב."},{"i":6173,"n":"ארליך, יהושע שלום מדומברובה","b":"מחכמי דומברובה. תשובה אליו ב\"קנאת סופרים\"."},{"i":6174,"n":"ארליך, יוסף שמואל שמלקא","f":"יהודה מריגליץ","bt":"תרס","dt":"תשד-ה","b":"אחיינו של רנ\"ה בומבך שהשיב לו-תרצז. נקרא גם בשם אמו - הולנדר. בנו של האדמור מנירעדיהאז. אב\"ד ריגליץ. נספה בשואה."},{"i":6175,"n":"ארליך, יחזקאל","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":6176,"n":"ארליך, יעקב מנאדאש","f":"אהרן","k":"בעל דרשה לחינוך..","bp":"פאפא","dt":"תרלא - יג אייר","dp":"נאדאש","b":"תלמיד החת\"ס, ור מרדכי בנט מניקלשבורג. רב בנאדאש-תקפג. חיבר בל\"א דרשה לחנוך ביהכ\"נ בטירנא - טרינא תקצז."},{"i":6177,"n":"ארליך, ישראל מנחם","dt":"תשד","b":"רב בסעליש"},{"i":6178,"n":"ארליך, ישראל שלמה מקראקא","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":6179,"n":"ארליך, מנחם מנדל","dt":"תשג","b":"מרבני לטביה"},{"i":6180,"n":"ארליך, מנחם מנדל מסעליש","k":"אדמור מסעליש","b":"חתן ר אשר ישעיה מזולקוא וקשנוב-נפטר תרעו. אדמור בסעליש-הונגריה."},{"i":6181,"n":"ארליך, משה הירש מלובלין","b":"חתן בעל \"ברית אברהם\" מפיעטרקוב. גביר מחכמי לובלין. חתנו - ר חיים רפאל בן ר יהודה ליב קמפנר מפלוצק."},{"i":6182,"n":"ארליך, משה מרכניץ","b":"רב ברכניץ"},{"i":6183,"n":"ארליך, נפתלי מדלטין","f":"צבי הירש","bt":"תרכג","bp":"רוזדול","dt":"תשג","b":"אב\"ד ווהנילוב יחד עם חותנו ורבו ר מנחם ישראל גסנבויער, בזיוו\"ש חתן ר יוסף רוטנברג מקאסאן. (ולפי אהלי שם - חתן ר שלמה יעקב בן ר יצחק איזיק מזידיטשוב). רב בזידיטשוב-תרן, (היה מעורב במחלוקת המתוארת בספר \"עמק יהושפט\") רב בדלטין-תרנה. נספה בשואה. בנו - ר יהודה ליב, חתנו - ר אברהם מרדכי בן ר חיים משה סאפרין, ר פנחס משה בן משה שמואל רוטנברג."},{"i":6184,"n":"ארליך, נתן פנחס מוארשא","dt":"תשא","b":"מגדולי וורשה"},{"i":6185,"n":"ארליך, צבי הירש מראזלי","f":"יהודה ליבש ארליך","bt":"תקצב","b":"רב בראזלי-שנת תר\"ל"},{"i":6186,"n":"ארליך, שלמה מגריבוב","k":"הו\"ל מדרש יהונתן","bt":"תרן","dt":"תש","b":"רב בגריבוב, הדפיס כמה ספרים וביניהם: \"מדרש יהונתן\" לר יונתן איבשיץ, ועוד."},{"i":6187,"n":"ארלינגר, אליעזר זוסיא","bp":"קליינינגן","dt":"תרכג - כז אייר","b":"רב בוייסנברג-צרפת-תקפג כ-40 שנה. בנו - הגביר ר מיכאל אלרינגר מפאריס. חיבר פירוש לתורה ועל פסקי התוספות."},{"i":6188,"n":"ארלינגר, יוסף מלוצרן","f":"מרדכי","bt":"תרנב - בערך","dt":"תרפה - ב תמוז","b":"מנכבדי הקהלה בלוצרן. נספד ע\"י ר משה אהרן קרויס מבאיע מארע ב\"זכרון יוסף\" שיצא לזכרו - והמחבר התארח אצלו בלוצרן-תרפה. שתי תשובות בספר מאת ידידו ד\"ר רפאל גוגנהיים מלוצרן, בענין רפואה והלכה."},{"i":6189,"n":"ארלקווטי, אלחנן יעקב מאיטליה","b":"מחכמי איטליה-רן, בנו ר שמואל בעל \"ערוגת הבשם\""},{"i":6190,"n":"ארמא, אברהם מספרד ושלוניקי","b":"חזן בספרד, לאחר הגירוש חזן בשלוניקי."},{"i":6191,"n":"ארמלי, יוסף מצרפת","f":"יחיאל מפריס","dt":"כז - לפני","b":"מחכמי צרפת, ועלה עם אביו בשנת כ (1260) בערך, לאחר שישב במאסר. תלמיד הרמבן שביקר בארץ בשנת כז (1267) ראה את קברו בתחתית הר הכרמל."},{"i":6192,"n":"ארמן דב בר בן משה שמואל","bt":"1860","dt":"ה'תשד 1944","bk":[["דברים ערבים",""],["זכרנו לחיים",""]]},{"i":6193,"n":"ארמר, עקיבא מקלסני","f":"צבי","k":"בעל אמרי בינה","bt":"תקעה","dt":"תרן","b":"רב בקלסני-תקצג. חיבר \"אמרי בינה\" למברג תרלג."},{"i":6194,"n":"ארנבסקי, אהרן דב אלתר","b":"רב בווילנה-תר\"צ"},{"i":6195,"n":"ארנברג, אברהם ישראל","f":"אלימלך אלעזר מגורליץ","dt":"תשמז","b":"מחכמי גורליץ. עלה לארץ והתגורר בתל אביב ובני ברק."},{"i":6196,"n":"ארנברג, אברהם מגורליץ","b":"עורך \"הלבנון\" - גורליץ תרפח - כתב עת אגודת \"תפארת בחורים\" בגורליץ."},{"i":6197,"n":"ארנברג, אלימלך אליעזר מגורליץ","f":"יוסף","k":"בעל ארזי לבנון","bt":"תרמח","bp":"גורליץ","dt":"תשלו","dp":"ירושלים","b":"חסיד בובוב, תלמיד קרובו ר\"ש פירר. עבר לארה\"ב-תרף, והיה חבר באגודת הרבנים שם. עלה לירושלים בתשכה. חיבר \"ארזי לבנון\" ירושלים תשכז."},{"i":6198,"n":"ארנברג, חיים ברוך","b":"חתן ר אשר זליג פירר."},{"i":6199,"n":"ארנברג, יהושע מנחם מנדל מקראקא","f":"יצחק אריה ליב","k":"בעל ראשי בשמים","bt":"תרסה","bp":"קעמטשע","dt":"תשלו","dp":"תל אביב","b":"חסיד בעלז, מחכמי קראקא. חתן ר דוד בירנבוים. חיבר \"ראשי בשמים\" על ספר הרוקח נדפס בקראקא אך לא הופץ. בשנת תשה עלה לארץ ונשלח כרב למחנות בקפריסין. ראבד ביפו-תשי. בספר \"דבר הישועה\" - ספור הצלת המשפחה בשואה - בני ברק תשנד. פרסם מאמרים ב\"הלבנון\" - גורליץ תרפח, \"קול תורה\" - ירושלים תרץ-תשז."},{"i":6200,"n":"ארנברג, יוסף אשר מפרמישלא","f":"יעקב משה מנחם מנדל","k":"בעל דברי אמת","r":"אבד\"ק פרעמיסלא","bt":"תקכ","bp":"פרמישלא","dt":"תקצא - ז תמוז","b":"חתן הגביר ר שרגא פיבל מירוסלב. רב בפרמישלא-תקמח. חיבר \"דברי אמת\" פשמישל תרעא. נכדו ר יוסף אשר מרוזדול תלמיד מהרי\"א מקומרנא.","bk":[["דברי אמת - דרוש",""],["ילקוט דברי אמת - תשובות אגרות הסכמות ותעודות",""]]},{"i":6201,"n":"ארנברג, יעקב משה מנחם מנדל","f":"דוד שמואל שמלקא","bt":"תץ","dt":"תקן","b":"רבה של טורקא, פשמישל-תקלו על מקום חותנו ר יחיאל מיכל ליטוואק. בנו ר יוסף אשר עלה על כסאו אחריו."},{"i":6202,"n":"ארנברג, נפתלי מקראקא","f":"חיים","k":"הו\"ל דברי שאול","bt":"תרף","bp":"קראקא","dt":"תשלה","b":"למד בישיבת בובוב, אחרי השואה הגיע לני יורק, הוציא לאור ספרים שונים וביניהם \"דברי שאול\"."},{"i":6203,"n":"ארנברג, פנחס מגורליץ","f":"אלימלך אלעזר","b":"איבד את משפחתו בשואה וניצל, עלה לארץ והדפיס כתבים שהיו ברשותו מר פנחס מקוריץ בשם \"אמרי פנחס\" תל אביב תשלח. אחיו ר אברהם ישראל."},{"i":6204,"n":"ארנברוגר, יוסף מפאקש","b":"בניו - ר מרדכי אליעזר מוראנוב, ור שמואל מטאשנד."},{"i":6205,"n":"ארנגרובר, יוסף מפאקש","b":"מחכמי פאקש-תרלה. בניו - ר שמואל מטאשנד, ור מרדכי אליעזר מורנוב."},{"i":6206,"n":"ארנגרובר, מרדכי אליעזר מורנוב","f":"יוסף הלוי מפאקש","k":"בעל נחלת יוסף","bt":"תרלה","bp":"פאקש","dt":"תשב-ד - יג כסלו","dp":"באלאש-ירמוט","b":"תלמיד השב\"ס, ור משה פולק מבאניהאד. חתן ר פנחס שטיינר מאילאק, ועבר לשם. רב בשטיינמאנגר-תרסא, פאפא-תרסח, וראנוב-תרעב. נספה בשואה."},{"i":6207,"n":"ארנגרובר, שמואל מטאשנד","f":"יוסף הלוי מפאקש","bt":"תרם","bp":"פאקש","dt":"תרף","b":"תלמיד השב\"ס. חתן ר שלמה כץ רוזנברג מטאשנאד, וכיהן כרב בטשאנד(=טשנאד) על מקום חותנו-תרנט."},{"i":6208,"n":"ארנהיים, היימן","k":"בעל לייטפאדען ביים א","bt":"תקנו","bp":"ונגרויטץ","dt":"1865","b":"מלומד בשפות ומדעים, מורה בגיראשטדליץ, פרוישטדט, גלוגא. תרגם חלק מכתבי הקדש לגרמנית. רב בביהמ\"ד של צאללער-1849."},{"i":6209,"n":"ארנובסקי, יצחק הכהן","k":"בעל יד יצחק","b":"ראב\"ד בקובנה-תרע\"ה"},{"i":6210,"n":"ארנובסקי, ישראל","b":"רב בסטרדוב"},{"i":6211,"n":"ארנטיל, אהרן מהארשיץ","f":"מנחם","k":"בעל כרמל","bt":"תקפד","bp":"פרוסטיץ","dt":"תרמח - ו שבט","dp":"הארשיץ","b":"תלמיד הכת\"ס, ור שמשון ב\"ר רפאל הירש מפפדמ. רב בקאפושוואר-תריב, הארשיץ-תרטו. חיבר \"המגיד\", \"מטה אהרן\", \"קול המועד\" ועוד."},{"i":6212,"n":"ארנטיל, יחזקאל מוואג-שעליע","f":"ישעיה ממגנדורף","dt":"תשג","b":"תלמיד השב\"ס, ור משה פולק מבאניהאד, ור משה צבי פוקס מגרוסורדין. רב בוואג-שעליע(=שאלא)-תרעב. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":6213,"n":"ארנטיל, ישעיה ממגנדורף","b":"נכד ר ישעיה כץ מיאקא. חתן ר אליעזר צבי הלוי לוינגר ממגנדורף בעל \"בני לוי\". גיסו של ר משה הלוי פולק מבאניהאד."},{"i":6214,"n":"ארנטריי, אלעזר הכהן מפרשבורג","f":"שמואל מפרשבורג","bp":"פרשבורג","dt":"תרץ - כט טבת","dp":"ירושלים","b":"מג\"מ בפרשבורג בחברה \"פועל צדק\", עלה לירושלים. מתלמידיו האחים ר ישעיה ור אברהם פרוידיגר."},{"i":6215,"n":"ארנטריי, חנוך הכהן ממינכן","f":"יונה","k":"בעל דקדוקי סופרים","bt":"תריד או תרד","bp":"אובן ישן","dt":"תרפז - כח טבת","b":"תלמיד הכת\"ס, ר פיבל פלויט בעל \"חבר בן חיים\", ור פנחס אליהו אסטריכר מאויבן, ר יעקב ניישלס ממינכן, תלמיד וחתן ר מרדכי עמרם הירש מאויבן והמבורג. מורה במשפחת בונדי במיינץ-תרלז, רב הקהלה החרדית במינכן-תרמה, בנו ר יונה על מקומו אחריו. התידד עם בעל \"דקדוקי סופרים\" והשלים את מסכת חולין, ועוד. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא. מכתביו נדפס \"שיירי המנחה\", ו\"קומץ המנחה\"."},{"i":6216,"n":"ארנטריי, יונה הכהן ממינכן","f":"חנוך ממינכן","b":"רב הקהלה החרדית במינכן על מקום אביו, רב בלונדון."},{"i":6217,"n":"ארנטריי, יחזקאל מואגישעליע","bt":"תרלא","b":"תלמיד השב\"ס, ר משה ממגנדורף וניטרא. חתן ר משה קניג מקובלסדורף. דומ\"צ במעדיער(=טאטמעדיאר)-תרסב, ואגישעליע-תרסח."},{"i":6218,"n":"ארנטריי, יצחק","dt":"תשד","b":"רב בפרשבורג"},{"i":6219,"n":"ארנטריי, ישראל מפפדמ","f":"חנוך ממינכן","b":"רב בפפד\"מ, גייטסהד."},{"i":6220,"n":"ארנטריי, נפתלי חיים מפרשבור","bt":"תרסט","bp":"סאבאטישט","dt":"תש..","b":"תלמיד הדעת סופר. חתן ר ישעיה קאליש מפרשבורג. רב בפרשבורג. נספה בשואה."},{"i":6221,"n":"ארנטריי, שמואל מפרשבורג","f":"משה הכהן מאויבן","bt":"תקע","bp":"אויבן","dt":"תרנג - ו תשרי","dp":"פרשבורג","b":"תלמיד החת\"ס. חתן ר מרדכי אפרים פישל סופר מפרשבורג. מחכמי אויבן-תרו, פרשבורג-תריא. היה משמשו של החת\"ס והיה עמו בשעת פטירתו (והחת\"ס בקשו לצאת מכיון שהוא כהן). רשם מחדושיו של החת\"ס. בנו - ר אליעזר."},{"i":6222,"n":"ארנסברג, יצחק מקראקא","b":"מחכמי קראקא-תרפט, תשובה אליו ב\"משיב שלום\"."},{"i":6223,"n":"ארנסון, מנחם מנדל מלאסק","b":"רב בלוסק-תר\"כ"},{"i":6224,"n":"ארנסט חיים יוסף ליב","bt":"1906","dt":"ה'תשמב 1982","bk":[["לב יוסף",""],["תורת ארץ צבי",""]]},{"i":6225,"n":"ארנסט, אברהם מפאביאניץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":6226,"n":"ארנסט, חיים מפאביאניץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":6227,"n":"ארנסט, יוסף ליב מניו יורק","b":"פרסם מאמרים ב\"המסלה\" - נ\"י תרצו, \"תלפיות\" - נ\"י תשד."},{"i":6228,"n":"ארנסט, שמעון","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":6229,"n":"ארנסטר, ישראל","f":"משה","b":"נכד האדמו\"ר ר חיים מאיר האגר מויזניץ. חתן ר יצחק קליש מאמשינוב ניו יורק."},{"i":6230,"n":"ארנפלד, אברהם ממישקולץ","b":"חתן ר יוסף רייניץ ממישקולץ. דומ\"צ במישקולץ."},{"i":6231,"n":"ארנפלד, ב. משארוואר","b":"רב בשארוואר על מקום ר זאב רייך, מטרסדורף."},{"i":6232,"n":"ארנפלד, דוד צבי מפרשבורג","k":"חתן החתם סופר","dt":"תרכב - כז חשון","b":"תלמיד וחתן החת\"ס. מגדולי חכמי פרשבורג - סירב לרבנות. בנו - ר שמואל ממטרסדורף."},{"i":6233,"n":"ארנפלד, דוד צבי משוראן","f":"שמואל - חתן סופר","b":"חתן ר שמואל בן יעקב מאיר צבי פרידלנדר משוראן. מחכמי שוראן."},{"i":6234,"n":"ארנפלד, ישעיה מזענטא","f":"שמואל","b":"נכד ר שמעון ממיהאלביץ. רב בזענטא."},{"i":6235,"n":"ארנפלד, ישעיה משוראן","f":"דוד צבי","k":"בעל שבט סופר","bt":"תרי","bp":"פרשבורג","dt":"תרסב - טז ניסן","dp":"שוראן","b":"נכד החת\"ס. תלמיד הכת\"ס, ותלמיד אחיו ר שמואל ארנפלד ממטרסדורף, מחסידי הדברי חיים מצאנז. חתן ר דוד גרסטל מברזביץ ועבר לשם-תרלב. רב בברזביץ. שאראש-פאטאק-תרמט, שוראן-תרמט, וחתנו ר מאיר יהודה ליב פרייא על מקומו אחריו."},{"i":6236,"n":"ארנפלד, נחום","dt":"תרעב","b":"רב הכולל בפרג"},{"i":6237,"n":"ארנפלד, שאול מסיקסא","f":"דוד צבי חתן החת\"ס","bt":"תקצט-תר","bp":"פרשבורג","dt":"תרסה - כז אלול","dp":"סיקסא","b":"נכד החת\"ס. תלמיד הכת\"ס. חתן ר אהרן פרידמן מבעקעש. התגורר בפרשבורג-תרכה, אויהל-תרכט. ציר בקונגרס היהודי-תרכט מטעם מחוז זעמפלען - ופרש עם שאר הצירים החרדים. מחכמי בודפשט, סטמר-תרלב, גרוסורדין-תרלב. רבה האחרון וראש הישיבה בסיקסא על מקום אחיו - ר שמואל בעל \"חתן סופר\" שעבר למטרסדורף."},{"i":6238,"n":"ארנפלד, שמואל ממטרסדורף הזקן","f":"דוד צבי","k":"בעל חתן סופר","bt":"תקצה","bp":"פרשבורג","dt":"תרמג - א אב","dp":"מטרסדורף","b":"נכד החת\"ס. תלמיד הכת\"ס, חתן ר בנימין בונם פשקוס מסערדאוהל. רב בפרשבורג לצד אביו. בעטלאן-תרכו, רב וראש ישיבה בסיקסא-תרכח ואחיו ר שאול על מקומו אחריו, רב וראש ישיבה במטרסדורף-תרלז ובנו ר שמחה בונם על מקומו אחריו. חיבר גם מספד מר על שבעה צדיקים - אונגואר תרלו."},{"i":6239,"n":"ארנפלד, שמואל ממטרסדורף הנכד","f":"שמחה בונם ממטרסדורף","k":"הו\"ל דרך חיים","bt":"תרנא","dt":"תשם","b":"נכד ה\"חתן סופר\". רבה האחרון של מטרסדורף-תרפז על מקום אביו. יו\"ר קהילות בורגנלנד ואוסטריה (בזמן שהעיר היתה שייכת לאוסטריה), עם כניסת הנאצים-1938 עבר לניו יורק והקים שם ישיבה. הו\"ל \"דרך חיים\" לזקנו, עם הערות ממנו. בניו: ר עקיבא ור שמחה בונם - רמי\"ם בישיבת אביהם. הקים קרית מטרסדורף להנצחת \"שבע קהילות\"."},{"i":6240,"n":"ארנפלד, שמחה בונם ממטרסדורף","f":"שמואל - החתן סופר","k":"בעל מענה שמחה","bt":"תרטו","bp":"פרשבורג","dt":"תרפו - ז אב","dp":"מטרסדורף","b":"תלמיד הכת\"ס. חתן ר אברהם מנחם קרויס מניר-מאדע. רב בשארוואר-תרמא, מטרסדורף-תרמג על מקום אביו ובנו ר שמואל על מקומו אחריו. פרסם מאמרים ב\"המגיד\" - סטמר תרפח."},{"i":6241,"n":"ארנפלד, שמעון ממיהאלביץ","f":"דוד צבי מפרשבורג","bt":"תרטז או תרך","dt":"תרצא - כד תמוז","dp":"מיהאלביץ","b":"נכד החת\"ס. נתייתם בילדותו וגדל אצל דודו הכת\"ס ואצל אחיו הגדול ר שמואל ארנפלד ממטרסדורף. חתן ר ישראל מילר מברזביץ, ועבר לשם. רב בשעניא(=אובו שעננה)-תרמה, מיהאלביץ-תרנד על מקום ר אהרן גרינברגר. עורך \"שערי ציון\". פרסם מאמרים ב\"קהילת יעקב\" - זבורוב-סלובקיה תרפה, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":6242,"n":"ארנפריז, יעקב מלמברג","f":"מרדכי","b":"מדפיס בלמברג אצל חותנו ר אברהם ניסן זיס. פרסם בעתונים באידיש ובעברית. פתח בית מסחר לספרים אצל המדפיס קרל בודוייזער."},{"i":6243,"n":"ארנפריז, ישכר דב בריש","k":"בעל דברי ישכר","b":"רב ומלמד בקריסנפולי, עבר להורודנקה. חיבר \"דברי ישכר\" למברג תרנה."},{"i":6244,"n":"ארנפריז, משה מגריידינג","f":"קלמן","dt":"תשב","b":"רב בגריידינג, למברג. נספה בשואה."},{"i":6245,"n":"ארנרייך, ברנרד מפילדלפיה","bt":"1875","bp":"הונגריה","b":"היגר לארה\"ב ולמד בביהמ\"ד לרבנים בניו יורק. רב רפורמי? באטלנטיק סיטי, \"קהילת \"עדת ישורון\" בפילדלפיה."},{"i":6246,"n":"ארנרייך, חיים יהודה מהלישוי","f":"קלונימוס קלמן מאובלי","k":"בעל ישראל בין העמים","bt":"תרמז-ח","bp":"אובליא (זמפלן-סלובקיה)","dt":"תשב - כח אייר","dp":"לובלין","b":"תלמיד השב\"ס, ור שלמה עהרנריך משימלויא. חתן ר יעקב שיק מנדאודוואר ועבר לשם. רב בהעלישויא-תרעה על מקום גיסו ר ישראל הלוי יונגרייז. רב צבאי במלחמת העולם ה-I. רב בקראלי, דעווא-תרפג, הומנא-תרץ. נספה בשואה. חיבר \"ישראל בין העמים\", \"זמרת הארץ\", ועוד. עורך \"אוצר החיים\" - דעווא תרפה. הו\"ל ספרי ראשונים. פרסם מאמרים ב\"אפריון\" - בודפשט תרפד, \"הנשר\" - טירנוי תרצג-תשד."},{"i":6247,"n":"ארנרייך, חיים יהודה משאמלוי","f":"שלמה זלמן משאמלוי","dt":"תשד","b":"חתן גיסו ר אשר אנשיל כץ מסערדהאלי. רב בשאמלוי-לפני השואה. נספה בשואה."},{"i":6248,"n":"ארנרייך, חיים צבי ממאדע","f":"יעקב","k":"בעל קצה המטה","bt":"תרלב","dt":"תרצז - כה כסלו","b":"נכד ר אברהם יהודה ליב הכהן שורץ מברגסאס. דיין ורב במאדע. פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג.","bk":[["קצה המטה [על מטה אפרים]",""],["קב חיים",""]]},{"i":6249,"n":"ארנרייך, יהושע משאמלוי","f":"שלמה זלמן משאמלוי","bp":"שאמלוי","dp":"ירושלים","b":"שו\"ב במעדיאש, רב במעגעש-לפני השואה. ניצל מהשואה ואחריה רב בשאמלוי. עלה לירושלים."},{"i":6250,"n":"ארנרייך, יעקב","b":"רב-שנת תר\"נ"},{"i":6251,"n":"ארנרייך, משה יהודה ליב ממאד","f":"חיים צבי ממאד","k":"הו\"ל קב חיים","bt":"תרסד","dt":"תשד - כו סיון","b":"תלמיד ר מרדכי ליב וינקלר ממאד. חתן ר שמואל זלמן וינברגר ממארגרטן. דיין במארגרטן אצל חותנו. רב במאד-תרצז על מקום אביו. נספה בשואה. הו\"ל ספר אביו \"קב חיים\" קלינורדין תשג. פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":6252,"n":"ארנרייך, משה יהודה משאמלוי","f":"שלמה זלמן משאמלוי","dt":"תשד","b":"חתן ר שאול רוזנברג מראצפרט. דיין בשאמלוי אצל אביו. רב בכפר שארמאשאג וגליל שאמלוי - ליד אביו. נספה בשואה."},{"i":6253,"n":"ארנרייך, משה מברוד","f":"מרדכי הלוי","k":"בעל חקרי מקרא","bt":"תקעח","dt":"תרס","b":"תלמיד שד\"ל בפדובה. חתן ר יצחק שמואל רגיו (יש\"ר). מנהל ביהמד\"ר ברומא. רב ברומא-תרן. חיבר חקרי מקרא ושירים בשפות שונות, וכן ספר באיטלקית על חותנו."},{"i":6254,"n":"ארנרייך, שלמה זלמן משמלוי","f":"יעקב","k":"בעל אבן שלמה","bt":"תרכג","bp":"ברגסאס","dt":"תשד - ז-יא סיון","dp":"אושויץ","b":"נכד ותלמיד ר אברהם יהודה שורץ בעל \"קול אריה\". מחסידי ותלמידי בעל \"קדושת יו\"ט\" מסיגט, ובנו ר יואל טיטלבוים. חתן ר יוסף דוד הורביץ מליסקא, עבר לסיקס, רב בטשאבא-תרנב, רב וראש ישיבה בשאמלוי(=שמלוי)-תרנט כ-44 שנה, ומגדולי המשיבים. ביקר בארץ והיה מחובבי ציון - אך מתנגד לציונות. נספה בשואה. הניח חבורים בכת\"י וחלקם אבד בשואה. הו\"ל ספר זקנו \"קול אריה\". חיבר גם \"\"לחם שלמה\", יקרא דחיים\" ובו הספד על אחיו ר חיים צבי ממאד, ועוד. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \" וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז,\"לקט ששנ\"ה\" - סטמר תרצד, \"קובץ מפרשי התורה\" - מארגרטן תרצג. מחותן עם ר שמואל רוזנברג מאונסדורף. בניו - ר משה יהודה, ר שמעון זאב. חתניו - ר אשר אנשל כץ, ר יצחק צבי ליבוביץ."},{"i":6255,"n":"ארנרייך, שמעון זאב ממישקולץ","f":"שלמה זלמן - אבן שלמה","b":"חתן דודו - ר חיים צבי ארנרייך. רב ומ\"מ במישקולץ. בזמן השואה נספו אשתו וילדיו, ניצל ועלה לארץ, הדפיס את כתבי אביו, מוהל מומחה."},{"i":6256,"n":"ארנשטין, אברהם מארה\"ב","f":"מיכאל","k":"בעל רנן והלל","b":"ש\"ץ בקרמנצוג-ליטא, ברדיטשוב. היגר לארה\"ב. חזן מפורסם."},{"i":6257,"n":"ארקיוולטי, שמואל מפדובה","f":"אלחנן יעקב","k":"בעל מעין גנים","bt":"רפ","bp":"אקוי - פיאמונט או ציסינה","dt":"שעא - כו אדר","dp":"פדובה","b":"רב בבולוניה, ונציה, רב ורופא בפדובה. מגיה ומחבר הקדמות בונציה, חיבר \"מעין גנים\", \"ערוגת הבושם\", \"דגל אהבה\", ועוד. חיבר שירים ומהם נדפסו. השתתף באסיפת הרבנים בוירונה-שיד - ובין התקנות - שלא יפסוק רב אחד לקהלה אחרת - בלי רשות הרב המקומי."},{"i":6258,"n":"ארקיס, אליהו"},{"i":6259,"n":"ארקע מסעלץ","b":"מחכמי סעלץ בזמן כהונת הגדול ממינסק."},{"i":6260,"n":"ארשנסקי, אליהו","f":"הלל","bt":"תרו","bp":"יקטרינסלב","dt":"תרלה - כו אלול","b":"משפטן, סופר, חיבר מאמרים. אחיו הו\"ל את כתביו אחר פטירתו."},{"i":6261,"n":"אש, אברהם גרשון מארה\"ב","f":"יוסף","b":"רב במוש, היגר לארה\"ב וכיהן כרב ברדינג-פנסילבניה. תשובה אליו ב\"ספר המאור\" לר אליעזר מאיר פרייל."},{"i":6262,"n":"אש, אברהם יוסף מליטא ונ\"י","bt":"תקעג","bp":"סמיאטיטש-ליטא","dt":"תרמח - כה אייר","dp":"ניו יורק","b":"מחכמי ליטא, הגיע לניו יורק-תריב והקים בית מדרש, רב ביהמ\"ד הגדול בניו יורק-[תרכ-ל], לחם למען הכשרות וכנגד הפוקרים. היה במחלוקת עם ר יהודה מיטלמן בענין שוחט שאסר, ולמרות שהשו\"ם - ר יוסף שאול נתנזון פסק כר יהודה מיטלמן להיתר, ואז היה פילוג בקהלה. נזכר ב\"בנין ציון\" לר יעקב עטלינגר, \"שדה יהושע\", ועוד. תשובה ממנו ב\"כרם שלמה\" בענין גט."},{"i":6263,"n":"א\"ש, אברהם מפרשבורג","b":"גבאי ח\"ק בפרשבורג-תקעא, יחד עם ר בער פרנק. (האם ר אברהם איזנשיץ מטרישט ופרשבורג?)"},{"i":6264,"n":"אש, גומפרכט שוחט מפרשבורג","b":"חתן ר יהודה מלמד מפרשבורג. שו\"ב בפרשבורג - נזכר בספר הזכרון של החת\"ס, ובהוראת החת\"ס הו\"ל יחד עם ר בער פרנק \"הלכות גדולות\". התעשר מזכיה בגורל ובעזרתו נבנה ביה\"ח היהודי אחרי שנשרף-תקעא. הציל משריפה את ר יעקב משה קשמן אופיבך."},{"i":6265,"n":"אש, דוד צבי הירש מגרודזיסק","dt":"תרמח - ד תשרי","b":"מצאצאי ר משלם פיבש איזנשטט מוישגראד ומצאצאי בעל \"מגלה עמוקות\". גביר מחכמי גרודזיסק. גיסו של ר ברל גולדפרב. בנו - ר נחום מצנסטחוב."},{"i":6266,"n":"אש, חנוך מפרג","f":"משה - בעל ברנטשפיל","dt":"שץ - י אדר","dp":"פרג","b":"שמש וספרא רבה מחכמי פרג."},{"i":6267,"n":"אש, ישראל מניישטט-שאקי","b":"רב בניישטט-שאקי(=שירווינט)."},{"i":6268,"n":"אש, נחום מצנסטחוב","f":"דוד צבי הירש מגרודזי","k":"בעל ציוני מהרן","bt":"תריח","dt":"תרצו - כ אייר","b":"תלמיד ישיבת ר אביגדור לוונטל בקויל. חתן ר שמשון אורנשטין מקאליש בעל \"תפארת שמשון\". רב בניעשאווא(=נישוואה)-פלך וארשא-תרמט, צנסטחוב(=טשענסטכאוו)-פלך פיעטריקוב-תרנד. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. נסמך מאת: חותנו-ר שמעון אורנשטין, ר חיים אליעזר ואקס מקאליש בעל \"נפש חיה\". נזכר בספריהם של ר חיים סופר - \"מחנה חיים\", ר שלמה גנצפריד \"קיצר שו\"ע\". בניו: ר שמואל יוסף - חוקר תולדות ישראל, ר משה יחיאל. (יש שרשמו תאריך פטירתו יט סיון)."},{"i":6269,"n":"אש, צבי הירש","b":"ר\"מ בישיבת חכמי לובלין בזמן גלותה בוילנא-תש."},{"i":6270,"n":"אש, שלום יוסף מאוזרקוב","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":6271,"n":"א\"ש, שמואל דב מירושלים","f":"אהרן","b":"מחכמי ירושלים, חתם-תרטו עם חברי כולל הפרושים, וחתם כדיין בביה\"ד של ר שמואל סלנט-תרכא."},{"i":6272,"n":"אש, שמואל יוסף","f":"נחום מצנסטחוב","b":"עורך תולדות גדולי ישראל."},{"i":6273,"n":"אש, שמואל מאיר מבלבירישוק","f":"יצחק","bt":"תקעט","dt":"תרמד","b":"רב בבלבירישוק על מקום ר אפרים גבאי, ור משה הורביץ בעל \"ידי משה\" על מקומו אחריו."},{"i":6274,"n":"א\"ש, שמריה מוילנא","f":"יוסף","b":"רב בוילנא, חתם-תפד עם ר צמח בן יעקב, ר יהודה בן בנימין, ר משה בן יהודה ליב."},{"i":6275,"n":"אש-אוירבך, יצחק אייזיק מפרמישל","f":"שלמה זלמן","b":"רב בפרמישלא-תיד."},{"i":6276,"n":"אש-שלזינגר, אברהם מפוזנא","f":"יוסף","k":"בעל מראה אש","b":"רב בצעללע, פוזנא, בנו ר משה יעקב הו\"ל את ספרו \"מראה אש\" - ברלין תרסג. חיבר גם \"תורה כלה על רגל אחת\", \"ברית אברהם\"."},{"i":6277,"n":"אש-שלזינגר, יוסף מדעסוי","b":"מצאצאי מהר\"ם מלובלין. אב\"ד דעסוי. בנו - ר אברהם אש-שלזינגר בעל \"מראה אש\"."},{"i":6278,"n":"אשבילי, יום טוב מספרד","k":"הריטב\"א","dt":"פט - לפני","b":"תלמיד הרשב\"א, ר אהרן הלוי-הרא\"ה. מגדולי מפרשי התלמוד בספרד."},{"i":6279,"n":"אשבילי, יום טוב מפאס","b":"רופא מחכמי פאס-שנות ה-ש'."},{"i":6280,"n":"אשבילי, יוסף מפאס","f":"יום טוב","b":"מחכמי פאס-שנות ה-ת'."},{"i":6281,"n":"אשבילי, שלום מאלגיר","f":"יצחק","bt":"ר - בערך","dt":"רע - בערך","b":"רב בבג'איה(=בוג'י). היה בקשרי שו\"ת עם הרשב\"ש השני בעל \"יכין ובועז\" (ר שמעון בן הרשב\"ש), שאלה ששאל אודות מסחר בקופים והשיב לו שמותר ובידי הוה עובדא (מכאן ששניהם סחרו בבעלי חיים)."},{"i":6282,"n":"אשווער, אריה ליב","b":"רב בנירמאדע"},{"i":6283,"n":"אשומר, יהודה מפאס","b":"מחכמי פאס-שנות ה-ת'."},{"i":6284,"n":"אשטרוק - שם פרטי","b":"במקורו שם כינוי בספרד ותמיד בנוסף לשם עברי, בהמשך היה גם לשם עיקרי."},{"i":6285,"n":"אשטרוק הכהן מיוון","b":"מחכמי יון-רן. בנו - ר שלמה הכהן."},{"i":6286,"n":"אשטרוק הכהן מספרד ואלגיר","f":"בינדיאה","bt":"קל","dt":"ר - בערך","b":"רב ורופא בברצלונה, עבר להוניין-אלגיר-קנא והתפרנס ממסחר, והיה בקשר עם הריב\"ש. כשהגיע ר יצחק בונשטריק-בושטריק לברצלונה - ויתר על רבנותו לטובת ר יצחק, אך בהמשך היה מחלוקת ביניהם. נספד ע\"י הריב\"ש, ור יהודה בן ר ששת אחי הריב\"ש. מצאצאיו ר דוד הכהן הנזכר בשו\"ת הריב\"ש."},{"i":6287,"n":"אשטרוק הלוי מספרד","f":"יצחק","b":"מחכמי דרוקה-ספרד-קן, אחיו של ר אברהם בן יצחק הלוי מגירונה. היה גם בפירפיניאן ומשם נשלח להשתתף בויכוח אצל האפיפיור-קעג ונזכר ב\"שבט יהודה\", (ואולי מדובר בשני חכמים עם אותו השם)."},{"i":6288,"n":"אשטרוק קרשקש מספרד","k":"אשטרוק שלום","b":"רב בשלשונה-ספרד-קן. תשובה ממנו בשו\"ת ריב\"ש ודן עם ר יצחק בונפש בן שאלתיאל-חתן הריב\"ש, ור שמואל בן שלמה בן שלום (כונה גם ר אשטרוק שלום)."},{"i":6289,"n":"אשטרוק, שלמה מספרד","k":"בעל מדרשי התורה","b":"מחכמי ברצלונה-ספרד בדור שלפני הגירוש. חיבר פירוש לתורה ועל האבן עזרא. נזכר בחידא כ\"אנשלמה\" וכנראה התוספת \"אן\" לשם אדם הם תואר כבוד שמשמעו \"אדון\"."},{"i":6290,"n":"אשטרחן, יוסף דב משיקגו","dt":"תרצה","b":"רב בשיקגו. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":6291,"n":"אשיאו, אברהם מברושא","b":"מחכמי ברישא(=ברושא) לאחר גירוש ספרד. נזכר אצל ר תם ן יחיא ב\"תומת ישרים\" יחד עם חבריו ר משה אל פרנגי, ר משה ן חביב."},{"i":6292,"n":"אשיאו, אברהם מירושלים","b":"מחכמי ירושלים-תקיח והיה מחכמי ישיבת ר אברהם מיוחס(=ישיבת הגביר מרדכי תלוק?) - נמנה שלישי לאחר ר מאיר סוראנגה ור יוסף ברבי. היה בצידון-תקכד ונזכר אצל החיד\"א (אולי כיהן שם כרב)."},{"i":6293,"n":"אשיאו, דוד מירושלים","b":"מחכמי ירושלים, חתם בשנת תקא על אגרת שליחות ר אברהם בן אשר ור יצחק זרחיה אזולאי."},{"i":6294,"n":"אשיאו, דוד משלוניקי","dp":"שלוניקי","b":"מחכמי שלוניקי-שפ."},{"i":6295,"n":"אשיאו, חייא משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"גביר מחכמי שלוניקי. מהרוגי דולייא."},{"i":6296,"n":"אשיאו, יוסף ממצרים","b":"מגדולי חכמי מצרים-ת\"צ"},{"i":6297,"n":"אשיאו, יוסף משלוניקי","f":"מרדכי","b":"דיין בשלוניקי-תקל, סופרו של ר אלעזר נחמיאש בשלוניקי. עורך ספר \"מלך שלם\". גיסו - ר יוסף נחמולי בעל \"אשדות הפסגה\"."},{"i":6298,"n":"אשיאו, יוסף משלוניקי ובלגרד","dp":"בלגרד","b":"תלמיד ר דניאל אישטרושא. מחכמי שלוניקי, בלגרד."},{"i":6299,"n":"אשיאו, יצחק משלוניקי","b":"מחכמי שלוניקי-תק.. חברו של ר יוסף מולכו."},{"i":6300,"n":"אשיאו, מרדכי משלוניקי וירושלים","k":"בעל הגיד מרדכי","dt":"תקצח - ט סיון","dp":"ירושלים","b":"מחכמי שלוניקי, שירון - עד שנת תקסה, עלה לירושלים. בשליחות-תקפד באירופה במשך כ-10 שנים והשיב שם להרבה גדולים שפגש שם, בשליחות בקושטא ואזמיר-תקצג. הערות ממנו ל\"נודע ביהודה\" ושלחם לר שמואל לנדא שהדפיסם בספרו \"שיבת ציון\". חיבר \"הגיד מרדכי\" שלוניקי תרה."},{"i":6301,"n":"אשיאו, משה משלוניקי","b":"מחכמי שלוניקי-תקף והתפרנס ממסחר."},{"i":6302,"n":"אשיאו, משה משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"גביר מחכמי שלוניקי. מהרוגי דולייא."},{"i":6303,"n":"אשיאו, משה משלוניקי ודובניצה","bp":"שלוניקי","dp":"ישראל","b":"עבר משלוניקי לדובניצה-בולגריה, עסק במסחר וכיהן כנשיא הקהלה, נבחר לראש העיר, עלה לארץ."},{"i":6304,"n":"אשיאו, רחמים מדובניצה","f":"משה","k":"בעל שפת עבר","bt":"תרמו","bp":"דובניצה","b":"עלה בילדותו לירושלים, מחנך ומחבר ספרי לימוד, מנהל בי\"ס בקיוסטנדיל, רוסג'וק, ציר יהודי בולגריה בקונגרס הציוני. חזר לארץ-תרפו והתישב בתל אביב, מגדיאל."},{"i":6305,"n":"אשיאו, שלמה משלוניקי","dt":"תקפא - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי, אירח בביתו את השליח ר רפאל הלוי בכור מירושלים-תקסג. סייע בהדפסת שו\"ת הרשב\"א."},{"i":6306,"n":"אשיניאס, יצחק משלוניקי","dt":"תקפט","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":6307,"n":"אשינסקי, אהרן מרדכי מארה\"ב","bt":"תרכז","dt":"תשיד","b":"רב בדטרויט-תרמט, פיטסבורג-תרסב. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":6308,"n":"אשישקין","k":"ראה: אישישקין","bt":"תרכג","bp":"אישישוק","b":"תלמיד ישיבות וולוזין, קובנה. רב ביאשון-פלך וילנא, היגר לארה\"ב וכיהן כרב בביהמ\"ד \"נחל יצחק\" בניו יורק, דטרויט-תרסה. מחידושיו ב\"המאסף\" בירושלים. פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו."},{"i":6309,"n":"אשכולי, אהרן זאב","k":"בעל החסידות בפולין"},{"i":6310,"n":"אשכולי, גרציאדה ישעיה מאיטליה","bt":"1829","b":"מחכמי איטליה, בקי בשפות. חיבר ספרים באיטלקית."},{"i":6311,"n":"אשכולי, דוד מאיטליה","b":"מחכמי איטליה שנות ה-ש'. חיבר ספר כנגד פקודת האפיפיור - שטרסבורג 1859?, נאסר בגלל הלשנה."},{"i":6312,"n":"אשכלונה, יוסף ממונסטיר","b":"רב במונסטיר-שנות ה-ש'."},{"i":6313,"n":"אשכנזי ,בן ציון מדוינסק","f":"יוסף מיאקובשטט","dt":"תרסו","b":"רב בפלאן ישן-דוינסק."},{"i":6314,"n":"אשכנזי אברהם משלם זלמן בן צבי","bt":"1710","dt":"ה'תקלז 1777","bk":[["דברי רב משלם",""]]},{"i":6315,"n":"אשכנזי יוסף בן ישראל; יונה בן אברהם גרונדי","bt":"1200","dt":"ה'כג 1263","bk":[["אהל יוסף",""]]},{"i":6316,"n":"אשכנזי נסים אברהם בן רפאל","dt":"ה'תרכ 1860","bk":[["דרש אברהם",""],["מעשה אברהם",""],["נאה להודות",""],["נחמד למראה",""]]},{"i":6317,"n":"אשכנזי, אביגדור מצפת","f":"יוסף-התנא הגדול","b":"מחכמי צפת, תלמיד האר\"י."},{"i":6318,"n":"אשכנזי, אברהם","b":"בנו - ר בצלאל אשכנזי-שיטה מקובצת."},{"i":6319,"n":"אשכנזי, אברהם (הלין)","k":"נכד המהרש\"ל","b":"נכד המהרש\"ל. בנו - ר משה יעקב הלין בעל \"ידי משה\"."},{"i":6320,"n":"אשכנזי, אברהם (יהודה) מקרקוביץ","bt":"תרי","dt":"תרס","b":"רבה של קרקוביץ-תרלה, אבד פשוורסק."},{"i":6321,"n":"אשכנזי, אברהם גד מסופיה","b":"דיין ביה\"ד האשכנזי בסופיה-שנות ה-תי'."},{"i":6322,"n":"אשכנזי, אברהם יהושע השל מבזילי","f":"שמואל","k":"אדמור מבאזיליאה","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. נכד ר יצחק מאיר השל האדמור מזינקוב. חתן ר יוסף דוד מאליק. אדמור בבאזיליאה-ליד פרוסקרוב."},{"i":6323,"n":"אשכנזי, אברהם יוסף מליוורנו","b":"רב בליוורנו-ת\"מ. תשובה ממנו ב\"תודת שלמים\". תשובה אליו מר\"י בסאן."},{"i":6324,"n":"אשכנזי, אברהם יוסף מקנדיא","b":"רב בקנדיא-תצז."},{"i":6325,"n":"אשכנזי, אברהם מאדרינופול","b":"רב באדרינופול-שנות ה-ש'."},{"i":6326,"n":"אשכנזי, אברהם מאיר מלאהוסק","f":"ראה: אפשטין, אברהם מ"},{"i":6327,"n":"אשכנזי, אברהם מברוד ואיטליה","f":"יוסף ישראל מבוליחוב","k":"בעל דבר המלך","bt":"תקט","bp":"ברודי","dt":"תקצז","dp":"פיררה","b":"מצאצאי המהרש\"א ומהר\"ם מלובלין. חתן ר מרדכי מארדיש ויינרב מפאריצק. נדד באירופה המערבית והגיע לאיטליה - טריאסט, ונציה, ליוורנו ולבסוף בפיררה. חיבר גם \"דרך המלך\", \"מאת אדנים\", \"הדור מצוה\"."},{"i":6328,"n":"אשכנזי, אברהם מבריסק","f":"בנימין אשכנזי","b":"רב בבריסק-שנת ת'. דיינים אצלו - ר נח בן משה מושלס, ר\"א בן יקותיאל זלמן."},{"i":6329,"n":"אשכנזי, אברהם מזולקווא","f":"מרדכי - אשל אברהם","b":"מחכמי זולקווא, חתם-שפו על תקנות הקהלה."},{"i":6330,"n":"אשכנזי, אברהם מחלב","f":"גבריאל","dt":"תקפה","b":"חכם שלם, דיין, מרבני ארם צובה"},{"i":6331,"n":"אשכנזי, אברהם מטבריה","f":"יצחק","b":"שליח טבריה בקושטא שלוניקי תימן ועוד בשנת שלט (1579). יסד את הדפוס בצפת בשנים שלז-שלט הדפיס 3 ספרים, בשנת שמז חדש את ההדפסה. מוזכר על ידי ר זכריה בן סעדיה אלצאהרי בתימן בספר המקאמות שלו. בניו - יצחק ויעקב שעברו לדמשק."},{"i":6332,"n":"אשכנזי, אברהם מירושלים","f":"רי\"צ","b":"חתם-תקצו על רכישת חצר עבור כולל הפרושים עם ר אברהם מחסלביץ ור משה יצחק בן בצלאל הכהן."},{"i":6333,"n":"אשכנזי, אברהם מירושלים","dt":"תקצה - לפני","b":"בשנת תקסו חתום על אגרת חכמי י-ם. בשליחות קהלת החסידים בגליל בצפון אפריקה, בשנת תקעט היה ברודוס, נזכר באביר יעקב לר אברהם חיון בסימן יט. חדושים משמו בספר ביאורים לר מימון ברדוגו בכתי, כמו כן בספר נאות מדבר לראמ מונסונייגו מפאס אגרת ממנו."},{"i":6334,"n":"אשכנזי, אברהם מירושלים","f":"יעקב","k":"בעל שמרו משפט","bt":"תקעא","bp":"לאריסה-יון או יינישיר-תור","dt":"תרם - ט שבט","dp":"ירושלים","b":"נכד ר יצחק פרחי. פוסק, ראב\"ד בירושלים, ראשון לציון-תרכט עד תרם על מקום הרב חזן, כתב שו\"ת וכן \"שמרו משפט\", \"דרך אניה\". בזמן המחלוקת בין רבני חברון עמד לצדו של ר אליהו מאני."},{"i":6335,"n":"אשכנזי, אברהם מירושלים","f":"יצחק","b":"רב בירושלים בשנת קנ (1390) שאר בשרו של ר מאיר סגל בן ברוך מוינה. חתום על קיום חרם הנשיא מבבל על ידי חכמי ירושלים."},{"i":6336,"n":"אשכנזי, אברהם מירושלים","b":"הסכים על \"דברי שלום\" - ירושלים תרג."},{"i":6337,"n":"אשכנזי, אברהם מירושלים","b":"מחכמי ירושלים, חתם על שטר חזקה-תקיג, עליו ב\"זכרון לחובבים הראשונים - חוברת י'."},{"i":6338,"n":"אשכנזי, אברהם מלמברג","b":"מתורתו בספר \"ברכת טוב\"."},{"i":6339,"n":"אשכנזי, אברהם מצפת ודמשק","f":"יצחק","b":"יסד את בית הדפוס הראשון בצפת-שכח, עם אחיו ר אליעזר מקושטא. גלו לביריה ועין זיתים בזמן המגפה. עבר לדמשק ויסד שם דפוס-שסה בשיתוף בניו - ר יצחק ור יעקב, ור אברהם בת שבע משלוניקי."},{"i":6340,"n":"אשכנזי, אברהם מקונסטנטין","dt":"תח - ב תמוז","b":"עק\"ה,רב בקונסטנטין"},{"i":6341,"n":"אשכנזי, אברהם מקורלנד וירושלים","k":"איש מופת","dp":"ירושלים","b":"רב בקורלנד-שנות ה-תק', עלה לירושלים בזמן הר\"מ סוזין, והתגורר אצל ר אברהם שלום שרעבי."},{"i":6342,"n":"אשכנזי, אברהם מקושטא","f":"משה","b":"מחכמי קושטא-שנות ה-תק', התכתב עם ר שלמה בכמוהר\"ר מרדכי מאדרינופול בנוגע לר אברהם רוזניס הרב הכולל."},{"i":6343,"n":"אשכנזי, אברהם מקראקא","f":"שמואל","b":"ממגורשי קרקא תק\"י"},{"i":6344,"n":"אשכנזי, אברהם מראוויטש","f":"צבי הירש אשכנזי","b":"רב בראוויטש"},{"i":6345,"n":"אשכנזי, אברהם מרדכי מווריש","f":"משה דוד","bt":"תרסג","dt":"תשג","dp":"סיביר","b":"רב בוואריש על כסא חמיו ר שלום באבד. נפטר בסיביר. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":6346,"n":"אשכנזי, אברהם מרדכי מפשוורסק","f":"שמעון מפשוורסק","b":"חתן ר חיים שמואל לנגר."},{"i":6347,"n":"אשכנזי, אברהם מרודני","bt":"תקעג","dt":"תרסה","b":"רב ברודני-פלך מוהילוב-תרטו כ-50 שנה, ובנו ר גרשון על מקומו אחריו."},{"i":6348,"n":"אשכנזי, אברהם משלוניקי","f":"אורי","b":"דיין ומקובל, ראש ישיבה בק\"ק \"אשכנזים\" בשלוניקי."},{"i":6349,"n":"אשכנזי, אברהם משלוניקי","dt":"תקכב","dp":"שלוניקי","b":"גביר בשלוניקי. נספד מאת ר יצחק פרנסיס בעל \"פני יצחק\". (התאריך לא מסתדר)."},{"i":6350,"n":"אשכנזי, אברהם משלם זלמן מאוסטר","f":"החכם צבי","k":"בעל דברי רב משלם","r":"בנו הצעיר של ה'חכם צבי'","dt":"תקלז - א שבט","dp":"פאסטבה-פלד קיוב","b":"נתייתם בילדותו וגדל אצל גיסו ר אוריה ליבוש מאמשטרדם. חתן ר אהרן בן יוזפא מאוסטרהא (ר יוזפא שהיה פרנס מדינת ואהלין ועשיר גדול ביקש להשתדך עם החכם צבי והציע לו מחצית מהונו - אך החכם צבי סירב, לאחר פטירתו לקח את בנו היעב\"ץ לחתנו, ולימים שידך היעב\"ץ את אחיו הצעיר ר אברהם לבת גיסו). מגדולי חכמי דורו. אב\"ד הקלויז באוסטרהא על מקום ר יצחק איזיק הכהן, בזמן ר דוד הלפרין שהיה אב\"ד אוסטרהא והגליל, לימים היה מחלוקת ביניהם ור דוד עזב - בהוראת הבעש\"ט - לזסלב, ור אברהם היה לאב\"ד-תצז כ-40 שנה. היה מחלוקת (אולי קשור לחסידים) ונאלץ לצאת בגלות היה בשומסק-תקכב, בשודנאב-תקלד. מבניו\" ר צבי הירש מאוסטרהא, ר אהרן פרנס באוסטרהא, ר חיים מאוסטרהא. חתנו ר נפתלי רוקח מברודי. (היה אחד משלושת גדולי אוסטרהא בדורו שנקרא בשם זלמן והם ר אברהם משלם זלמן בן החכם צבי ונקרא - \"זלמיני\", ר שלמה זלמן הכהן שנקרא - \"זעלמלא\", ותלמידו ר משלם ממזריטש שנקרא - \"ר זעלמילא מעזריטשער\").","bk":[["דברי רבינו משולם",""]]},{"i":6351,"n":"אשכנזי, אברהם נפתלי מסטניסלב","f":"אשר אנשיל מסטניסלב","k":"אדמור מאלסק בסטניסלב","dt":"תרפח","b":"נכד ר חנוך הניך דב האדמור מאלסק. אדמור מאלסק בסטניסלב על מקום אביו והגיעו אליו חסידים רבים מרומניה ובסרביה."},{"i":6352,"n":"אשכנזי, אברהם שרגא מחברון","b":"שליח חברון בהודו בשנת תרמב. הדפיס שם פסק דין \"מגן אברהם\", ואישר פסק דינו של השדר ר אשר אברהם הלוי בענין טבילת עבדים משוחררים."},{"i":6353,"n":"אשכנזי, אהרן הלוי מבלגרד","b":"רב בבלגרד,עלה לירושלים-תי\"ז"},{"i":6354,"n":"אשכנזי, אהרן זליג מירושלים","f":"מנחם מן","dt":"תריב - כט אלול","dp":"ירושלים","b":"בשנת תקצז שליח למען פדיון \"החורבה\", שליח לאמריקה בשנת תרח, חתם על תקנת התכשיטים משנת תריב, מחותנו של ר שלמה זלמן צורף"},{"i":6355,"n":"אשכנזי, אהרן מאוסטרהא","f":"אברהם משלם זלמן","b":"נכד החכם צבי. פרנס באוסטרהא-תקכט, וחתם בפנקס ח\"ק שם."},{"i":6356,"n":"אשכנזי, אהרן מבלגרד","f":"דוד","dp":"ירושלים","b":"חכם מעיר בילוגרד(=בלגרד), עלה לירושלים, חתום על כתב שליחות של ר ברוך גד בשנת תיז."},{"i":6357,"n":"אשכנזי, אהרן מטבריה","b":"שליח טבריה בארצות ערב, בשנת תקמח היה בארם נהריים, לדעת יערי הוא ר אהרן בן מאיר מראשי החסידים שחתם על אגרת שליחות ר שלמה זלמן הכהן בשנת תקמט"},{"i":6358,"n":"אשכנזי, אהרן מפירנצי","b":"מחכמי פירנצי בזמן הר\"י אירגז, ובעל ה\"שמש צדקה\" שהביאו תשובה ממנו בספרו. תשובה אליו ב\"דבר שמואל\"."},{"i":6359,"n":"אשכנזי, אולימן מקושטא","b":"מגדולי קושטא-תי. נמנה על משלחת החכמים שנשלחו לבדוק את נתן העזתי בעזה (יחד עם מהר\"א אמיגו, ר גבריאל איפראנסו, ר חיים אבולעפיה)."},{"i":6360,"n":"אשכנזי, אורי יהושע אשר אלחנן","f":"ראה: רבינוביץ, אורי"},{"i":6361,"n":"אשכנזי, אליא מקושטא","dt":"תקעח - תמוז","b":"דיין בקושטא"},{"i":6362,"n":"אשכנזי, אליהו מקראקא","f":"אליעזר אשכנזי","b":"רב,בקרקא"},{"i":6363,"n":"אשכנזי, אלימלך מהורודונקא","f":"יונה אבד פשוורסק","bt":"תרטו","dt":"תרעו","b":"חתן ר משה תאומים מהורודנקה. רב גורא-הומורא(=גירהאמאר)-בוקובינה-תרלח על מקום ר משולם גבירר, הורודנקה-תרמח (אחרי שקנה את הרבנות מגיסו - אב\"ד וילקוטש). מחסידי צורטקוב, השתתף בועידת יסוד המזרחי בגליציה-תרעג. חתנו ר אריה ליבוש לאם התמנה למו\"ץ אחריו (לא נבחר יותר רב בעיר עד השואה). פרסם מאמרים ב\"ועד חכמים\" - יזלוביץ (ועוד) תרנח."},{"i":6364,"n":"אשכנזי, אלימלך מסטניסלב","f":"אלכסנדר חיים מירושלי","bt":"תרעו","bp":"סטניסלב","b":"נכד ר יצחק וילצקר אשכנזי האדמור מסטניסלב. למד בישיבת חכמי לובלין, עלה לירושלים בשנת תש. חתן ר יקותיאל זלמן יום טוב וובר אדמור בפפד\"מ. רב בסן פאולו-תשיח, מלבורן-תשל, עבר לניו יורק, עלה לירושלים."},{"i":6365,"n":"אשכנזי, אליעזר","b":"גביר בקושטא?, יסד ישיבת \"דמשק אליעזר\" בירושלים-שנות ה-תק'."},{"i":6366,"n":"אשכנזי, אליעזר מאיטליה","k":"בעל ערוגת הבשם","b":"רב בשנת קמד. חיבר \"ערוגת הבשם\""},{"i":6367,"n":"אשכנזי, אליעזר מלובלין קושטא","f":"יצחק","bp":"פרג","b":"היה מדפיס בלובלין עם בנו יצחק בשנים שיח - שלג, עבר לקושטא והדפיס שם כמה ספרים, ומשם בשנת שלו עלה לצפת והקים דפוס עם הגביר אברהם בן יצחק (לדעת רוזניס - היה זה אחיו) שהיה הדפוס הראשון במזרח."},{"i":6368,"n":"אשכנזי, אליעזר מליוורנו","b":"הו\"ל \"ספר הזכרון\" לר אברהם בוקראט - ליוורנו תרה."},{"i":6369,"n":"אשכנזי, אליעזר ממצרים ואיטליה","f":"אליהו הרופא","k":"בעל יוסף לקח","r":"נכד המהרי\"ק, דיין במצרים, ואח\"כ רב בקרימונה, ואח\"כ רב בפוזנא","bt":"רעג","dt":"שמו - ב-כב כסלו","dp":"קראקא","b":"מילידי אשכנז ועבר לשלוניקי. תלמיד ר יוסף טאיטצק, חבר לר משה אלשיך, רב במצרים-רצט ברח לונציה, אנקונה, רב בפמגוסטה-קפריסין-שכא, ניקוסיה-קפריסין, פרג, וקרימונה ואחר כך בפוזנא-שלח, גניזן, וקראקא על מקום הרמ\"א, מחכמי ירושלים, חיבר גם \"מעשי ה\", כנראה היה גם שדר ירושלים, וכנראה שישב בירושלים בזמן כלשהו. חתנו - ר שמעון זימל בן חיים פרנקל. בנו - ר אליהו חתן ר שמואל יודא קצנלנבוגן. מתלמידיו ר ברוך קלמיני בן שמחה קלמן טערוויז. חיבר גם \"מעשה ה\", פירוש על הרמב\"ן על התורה, השגות על בית יוסף. חיבר פיוטים וחלקים ב\"עמודי עבודה\".","bk":[["גדולים מעשי ה' - על התורה",""],["הגדת רבי אליעזר אשכנזי",""],["יוסף לקח - מגילת אסתר",""],["סליחה בשביל ילדים קטנים",""]]},{"i":6370,"n":"אשכנזי, אליעזר מקושטא","f":"דניאל","b":"דיין בקושטא-תטו."},{"i":6371,"n":"אשכנזי, אליקים גצל מראקווי","f":"החכם צבי","b":"רב בראקוויי"},{"i":6372,"n":"אשכנזי, אלישע הלוי מירושלים","k":"הו\"ל מגיד מישרים","dt":"תלג - ה סיון","dp":"מכנאס","b":"מחכמי ירושלים, בשליחות במדינות רבות-תו, בשליחות במרוקו יחד עם חברו ר חייא דיין, התישב בסאלי, מכנאס ולימד תורה. מתלמידיו - ר חיים ן עטר בעל \"אור החיים\". בנו - נתן העזתי."},{"i":6373,"n":"אשכנזי, אלכסנדר חיים מסטניסלב","f":"יצחק","bt":"תרמט","bp":"סטניסלב","dt":"תשלד","dp":"ירושלים","b":"עלה לירושלים בילדותו עם משפחתו, אך חזר לגליציה. חתן ר אלימלך אשכנזי אבד הורודנקה - סירב לשבת על מקומו אחריו, מראשי קהילת סטניסלב. רב בשוויץ-תרצח ובלוגנו. עלה לארץ-תשו ועמד בראש מוסדות סאטמר בארץ."},{"i":6374,"n":"אשכנזי, אלעזר ממצרים","k":"בעל צפנת פענח","b":"מגדולי חכמי מצרים-קכד. חיבר ספרים-קמד בכת\"י."},{"i":6375,"n":"אשכנזי, אפרים יוסף דב מסטמר","f":"משלם שרגא פיביש","bt":"תרעא","bp":"צפת","dt":"תשסב","dp":"מונרו","b":"נסע בילדותו לקרולי. משמשו של ר יואל טיטלבוים האדמור מסטמר על מקום אביו. ניצל מהשואה ועבר לארה\"ב, בעל הוצאת ספרים בירושלים. ערך את כתבי רבו וכן חדושים משלו."},{"i":6376,"n":"אשכנזי, אפרים מלבוב","f":"החכם צבי","dt":"תקלב - ג ניסן","dp":"לבוב","b":"רב בלבוב. חתנו - היעב\"ץ (בזיווג שלישי)."},{"i":6377,"n":"אשכנזי, אפרים פישל מבריסק","f":"משה יהודה","dt":"שנו","dp":"ירושלים","b":"זקנו של ר אפרים בעל \"שער אפרים\", חתן המהרש\"ל?, מגדולי דורו, רב בבריסק, לובלין. ר יום טוב צהלון מספר ששמע שהיו לו 200 תלמידים בישיבתו, בין תלמידו ר שמעון אנשבורג מפרנקפורט, מוזכר בפירוש המשניות מלאכת שלמה, ומדרש שמואל לר שמואל די אוזידה, עלה לירושלים בסוף ימי הרדב\"ז, והיה רב האשכנזים, בשנת שן חתם על מכתב למונשטיר, ועל תקנת מס בשנת שכו ובשנת שנד. אולי הוא שחיבר פירוש לאבות שהיה בידי ר שמואל אוזידא בעל \"מדרש שמואל\" שמביא ממנו. בנו - ר צבי."},{"i":6378,"n":"אשכנזי, אריה ליב מאוסטרהא","f":"משלם זלמן מפמורן","dt":"תקסז - ו תשרי","dp":"אוסטרהא","b":"נתייתם בילדותו וגדל אצל ר מאיר חריף מרגליות מאוסטרהא (ולפי בובר-זולקוא גדל אצל דודו ר מרדכי זאב אורנשטין בלבוב). אחיו של ר משלם זלמן אשכנזי מלובלין. חתן ר אבא הכהן מאוסטרהא (שנתן נדוניה גדולה בתנאי שילמד אצל דודו ר מרדכי זאב באוסטרהא - בגיל 13 היתה החתונה ודרש בפני כל גדולי אוסטרהא שהתפעלו ממנו). מחכמי אוסטרהא וחתם בפנקס הח\"ק. מבניו: ר מרדכי זאב-חתן הגביר ר צדוק מדובנא, ר משלם זלמן מאוסטרהא, ר שאול מאוסטרהא. חתניו: ר שלמה זלמן כהנא גוטיס מפולנאה וברדיטשוב, ר חיים הלברשטם בן צבי יעקב מפודקמין."},{"i":6379,"n":"אשכנזי, אשר אהרן","b":"רב-שנת תק\"נ. בנו - ר ישראל אשכנזי."},{"i":6380,"n":"אשכנזי, אשר אנשיל מסטניסלב","f":"יואל מזלוטשוב","k":"אדמור מאלסק סטניסלב","bt":"תקצב","dt":"תרנז - כא חשון","b":"חתן ר חנוך הניך מאייר האדמור מאלסק, התישב בסטניסלב וכיהן כאדמור מאלסק על מקום חותנו. חתנו ר יצחק ויליצקר-אשכנזי על מקומו אחריו. (לפי אוצר הרבנים - רב בזלוטשוב-תרע, ובנו ר ישראל)."},{"i":6381,"n":"אשכנזי, אשר אנשיל מסטניסלב","f":"מרדכי","k":"בעל שמן ראש","bt":"תקצג","dt":"תרסב","dp":"סטניסלב","b":"חתן ר ליטמן ברטלר מקולומיאה, ישב בקולומיאה ולמד ולימד תלמידים. רב בפולטושן-תרל, ראבד בסטניסלב על מקום אביו לאחר שאביו עלה לארץ. (בטעות כתב גליס שעלה לצפת ואינו כן). חיבר \"שמן ראש\" מונקטש תרסג, ועוד בכתב יד.","bk":[["שמן ראש",""]]},{"i":6382,"n":"אשכנזי, אשר אנשיל מסטניסלב","f":"אברהם נפתלי מסטניסלב","k":"אדמור מסטניסלב","dt":"תש..","b":"אדמור בסטניסלב על מקום אביו. נספה בשואה."},{"i":6383,"n":"אשכנזי, אשר אנשיל מרוזדול","f":"משה","bt":"תק","dt":"תקנד - כ חשון","dp":"לבוב","b":"מצאצאי ר שכנא מלובלין רבו של הרמא. רבה של רוזדול, למברג-תקמז. בנו ר משה דוד אבד טולטשווא, ור ישראל אבד היבנוב וטיסמניץ."},{"i":6384,"n":"אשכנזי, אשר אריה ליב","b":"מצאצאי השאגת אריה. בשנת תרח שליח האשכנזים בירושלים בערי סוריה ותורכיה, ור דוד רפאל חזן מביא חדוש הלכתי ששמע ממנו באזמיר,"},{"i":6385,"n":"אשכנזי, אשר הושע מוארשא","dt":"תשג","b":"רב בקלביעל-וארשא"},{"i":6386,"n":"אשכנזי, אשר מטבריה","f":"אליעזר","dt":"תקעט","dp":"טבריה","b":"עלה לארץ-לפני תקמט, מראשוני החסידים בטבריה בראשותו של ר מנחם מנדל מויטבסק, היה שליח טבריה באשכנז יחד עם ר אברהם אזולאי בשנים תקנא-תקנב. פנקס שליחות בכתב יד נמצא בספרית בית המדרש לרבנים בניו יורק. חתם בשנת תקנח על אגרת קהילת טבריה. בנו שמואל שמלקי, וחתנו ר יונה אשכנזי."},{"i":6387,"n":"אשכנזי, אשר מקושטא","f":"יצחק","b":"מחכמי קושטא-רל. היה במחלוקת עם ר משה קפסלי."},{"i":6388,"n":"אשכנזי, אשר מקושטא ואדרינופול","f":"אברהם","b":"גביר בקושטא ואדרינופול, נשלח-תכז אל נתן העזתי שהיה באיפוסולה כשרצה להגיע לאדרינופול עם הרופא דוד קוריאל ור יהודה בן משולם."},{"i":6389,"n":"אשכנזי, אשר משלוניקי","f":"נתן","dt":"שפא - ח תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי. אולי אביו של ר דוד אשר אשכנזי הנזכר אצל הרשד\"מ."},{"i":6390,"n":"אשכנזי, אשר ענזיל מירושלים","k":"הענשל מפינטשוק","dp":"ירושלים","b":"מחכמי ירושלים-תקמט. חי בזמנו של ר יום טוב אלגזי, מוזכר באגרת ר שמואל גרונם"},{"i":6391,"n":"אשכנזי, בולה איקשאתי מקושטא","b":"אשת ר שלמה בן נתן הרופא מקושטא ואיטליה. מקורבת בחצר המלכות בקושטא-שמב."},{"i":6392,"n":"אשכנזי, בנימין הלוי מצפת","f":"מאיר","dt":"תלב","dp":"חלב או חמת (כפר ליד)","b":"תלמיד גורי האר\"י, ובהם ר חייא בעל \"מעשה חייא\". ממקובלי צפת, עבר לירושלים, ואחר יצא לחו\"ל עם תלמידו ר דוד חביליו, בשנת תיז בשליחות באיטליה, נפגש שם עם ר אליעזר נחמן פואה, והשפיע על תלמידו ר משה זכות, ר משה זכות קבל ממנו הנהגות קבליות והנהיגם במספר מקומות באיטליה. הסכים על ספר \"זאת חוקת התורה\" לר אברהם חזקוני. יערי בספרו תעלומת ספר מיחס לר בנימין את חבור הספר \"חמדת הימים\" (אולם רבים אינם מסכימים עמו), בתיז היה בהמבורג ואסף כספים לפדיון בנו שהיה מחכמי אזמיר, הוא קבל רשות מיוחדת לדרוש בקהלה ולאסוף כסף גם מיחידים. חזר לצפת עם בנו ר שלמה הלוי שהגיע מאזמיר, יצאו שניהם לשליחות, רב בצידון-תכח ובנו ר שלמה על מקומו אחריו, רב בחלב. תשובות בשמו בספרו של בנו ר שלמה הלוי \"לב שלמה\" שלוניקי תקסח, תשובה ממנו ב\"אבקת רוכל\" ועוד. מתלמידיו גם ר ישראל שלמה לינגי, ר משה זכות? (פגש בו בונציה). בנו - ר שלמה-חתן ר יונתן גלנטי."},{"i":6393,"n":"אשכנזי, בנימין הלוי משלוניקי","f":"מאיר בן שמעון משלוני","bt":"רלה","dt":"שיט","b":"נינו של המהרי\"ל. ממגורשי אשכנז והגיע עם אביו לסופיה, רב הקהלה האשכנזית בסופיה-רפ, עבר לקושטא והתידד עם ר משה המון, רב בשלוניקי. נבחר כציר בקושטא מטעם קהלות שלוניקי. בשליחות קהלות שלוניקי לבקש עזרה מקהלות שונות אחרי המגפה והשריפה. נספד ע\"י ר סעדיה לונגו. בנו ר דוד משלוניקי. חיבר מחזור אשכנז עם פירוש, ובו קינה על ילדיו שנפטרו במגפה. בניו - ר דוד, ר מנחם מקושטא."},{"i":6394,"n":"אשכנזי, בנימין וולף מוילנא","b":"רב בוילנא, חתם-תעד על פס\"ד עם ר נח בן יוסף ור צבי בן דב בער. בנו - ר יעקב וילנא שעלה לירושלים."},{"i":6395,"n":"אשכנזי, בנימין וולף ממזריטש וא","dt":"תפב - ה אדר","dp":"ואנדסבק","b":"מלמד במזריטש, עבר לאה\"ו."},{"i":6396,"n":"אשכנזי, בנימין זאב מניקופול","b":"מחכמי ניקופול-תק, בשליחות הקהלה לעזרה לאחר שריפת בית הכנסת."},{"i":6397,"n":"אשכנזי, בנימין מלובלין","b":"רב בלובלין-ת\"י"},{"i":6398,"n":"אשכנזי, בצלאל","f":"ב' אהרן אשכנזי-סלניק","b":"רב-שנת ת'"},{"i":6399,"n":"אשכנזי, בצלאל הלוי משלוניקי","dt":"תקיב","dp":"שלוניקי?","b":"מדפיס באמשטרדם, מדפיס בשלוניקי-תק, ממשפחה אשכנזית שהגיעה לתורכיה. מראשי הקהלה האשכנזית. בנו - ר סעדי?, ובמקום אחר - בניו יהודה ושמואל שנפטרו צעירים."},{"i":6400,"n":"אשכנזי, בצלאל יהודה הלוי משלונ","b":"מדפיס בדפוס חיים אברהם בן שבתי נחמה וסעדי הלוי-תקנח. אחיו של השותף סעדי הלוי וירש ממנו את הדפוס-תקעח."},{"i":6401,"n":"אשכנזי, בצלאל ממצרים","f":"אברהם","k":"בעל שיטה מקובצת","bt":"רפ","bp":"צפת או ירושלים","dt":"שנב - שנה","dp":"ירושלים","b":"אביו היה אחיו של ר יצחק בצלאל מגדולי אשכנז וסבו של בעל הט\"ז, ירד עם משפחתו כילד למצרים, למד אצל הרדבז, ואצל ר ישראל די קוריאל. הגיע עם אביו למצרים וכיהן שם כרב הכולל-שטז לאחר עליית הרדבז לארץ. הגיע לירושלים בשנת שמז, חזר למצרים ותלמידו שם היה האר\"י, וגם היה דיין אצלו בבית הדין האשכנזי. חזר לירושלים בשנת שנב ועמד בראש הצבור ור אברהם בן יצחק לניאדו על מקומו אחריו, יצא לשליחות מטעם הקהלה, ר ישראל נג'ארה כתב אגרת בשמו בדמשק המיועדת ליהודי חלב. חיבר ספר \"שיטה מקובצת\" שזכה למהדורות רבות. כן חיבר בצפת-שלה ספר \"כללי התלמוד\", תשובות רבות ממנו."},{"i":6402,"n":"אשכנזי, ברוך משלוניקי ירושלים","f":"שמואל","dt":"שטו - כד תשרי","dp":"שלוניקי","b":"ממגורשי ספרד, מקובל מחכמי שלוניקי-שנות ה-ר'-ש'. נזכר ברשימת ר בנימין עטייה. היה במו\"מ עם ר תם ן יחיא. (לדברי רוזניס - היה מחכמי האשכנזים ולא ממגורשי ספרד)."},{"i":6403,"n":"אשכנזי, גבריאל","b":"זקנו של בעל \"בית הלוי\" (אולי ר לוי אשכנזי?) המביא מזקנו בספרו."},{"i":6404,"n":"אשכנזי, גבריאל","f":"רחמים","bp":"חלב","dp":"שכם","b":"דיין בארם צובה, יחד עם ר' אברהם ענתבי ור' מרדכי לבטון, חיבר ספרים"},{"i":6405,"n":"אשכנזי, גוטה מטריפולי","bt":"תמ","dt":"תקי - בערך","dp":"טריפולי","b":"רב ודיין בטריפולי. נקבר בחלקת משפחת ג'רמון הנקראת \"אג'ראמנא\". נזכר ב\"הגיד מרדכי\" ירושלים תשלט, \"חן טוב\" ג'רבה תשו."},{"i":6406,"n":"אשכנזי, גרשון אוליף מוינה ומיץ","k":"בעל עבודת הגרשוני","bp":"פולין","dt":"תנג - י אד\"ב","b":"למד עם שני חבריו - ר צבי הירש קלויזנר מלובלין, ר מנחם מנדל אוירבך בן ר משלם זלמן פינהוף - בישיבת הב\"ח בקראקא, אצל ר יהושע בעל ה\"מגיני שלמה\", ואצל ר מנחם מנדל קרוכמל בעל \"צמח צדק\" (והזכירם בספרו) - והתישבו בקראקא. חתן ר מנחם מנדל קרוכמל. דיין בקראקא, רב בפרוסטיץ-תיז, הענא, רב בניקלסבורג והמדינה-תכא, וינה ולאחר גירוש וינה עבר למיץ. חיבר \"עבודת הגרשוני\", תפארת הגרשוני\". מתלמידיו - ר מאיר איזנשטט בעל \"נר למאור\"."},{"i":6407,"n":"אשכנזי, גרשון הלוי מרודני","f":"אברהם מרודני","bt":"תריז","b":"רב ברודני-פלך מוהילוב-תרסה על מקום אביו."},{"i":6408,"n":"אשכנזי, גרשון מהורודנקא","f":"יהודה","k":"בעל עבודת הגרשוני","r":"רב ברוזלא","bt":"תקס","bp":"ראזלא","dt":"תרכג - ה סיון","b":"מצאצאי ר נתן נטע מראזלה הלוחם בשבתאים. רב בראזלא-תקפא על מקום אביו, טלומטש-תקפט, הורודנקה וקולומיאה. נפטר ללא בנים. חתן ר מנחם מנדל מקוסוב. אלמנתו הרבנית שרה לאה הדפיסה מתורתו ב\"עבודת הגרשוני\".","bk":[["עבודת הגרשוני - עה\"ת ושו\"ת",""],["עבודת הגרשוני תנינא - עה\"ת",""],["עבודת הגרשוני",""]]},{"i":6409,"n":"אשכנזי, גרשון מפליבנא","f":"יהודה","b":"רב הקהלה האשכנזית בבפליבנא(=פליונה)-ש', שאלה ממנו לרמ\"א."},{"i":6410,"n":"אשכנזי, דב בער הלוי מקאליסק","b":"ה\"חוזר\" של הצמח צדק. חתניו - ר מנחם מנדל נאה מחברון, ר שלמה יהודה אליעזרוב מחברון."},{"i":6411,"n":"אשכנזי, דב בר","dt":"תקעג","b":"רב באלבער-אירשא"},{"i":6412,"n":"אשכנזי, דב בריש מסיגט","b":"מחכמי סיגט-תרסט, תלמיד ר אלתר פפר בעל \"אבני זכרון\"."},{"i":6413,"n":"אשכנזי, דב בריש מסלונים ולובלי","f":"משה","k":"בעל נודע בשערים","bt":"תקסג","dt":"תריב - יד אדר","dp":"לובלין","b":"מצאצאי החכם צבי. אב\"ד בסלונים-תקצח, לובלין-תרד על מקום ר משלם זלמן ור יהושע השל בן ר משלם זלמן על מקומו אחריו. אחיו ר אברהם אריה הו\"ל את ספריו \"נודע בשערים\"-תריט ו\"שערי ירושלים\"-תקכו."},{"i":6414,"n":"אשכנזי, דב מירושלים","b":"מחכמי ישיבת \"חסד לאברהם\" בירושלים-תקיח."},{"i":6415,"n":"אשכנזי, דוד הגדול מטבריה","f":"ישראל מלאזני","k":"דוד פולציקר","b":"תלמיד ר דב בער המגיד ממזריטש, ור מנחם מנדל מויטבסק. עלה לארץ עם רבו. פגש את החיד\"א וסיפר לו על הערכת הבעש\"ט וחסידיו ל\"אור החיים\". בשליחות-תקסא קהלת טבריה במרוקו?"},{"i":6416,"n":"אשכנזי, דוד הלוי מקושטא","b":"רופא בקושטא-שנות ה-ת', מקורב למלכות."},{"i":6417,"n":"אשכנזי, דוד הלוי משלוניקי","f":"בנימין משלוניקי","dt":"שכב","dp":"שלוניקי","b":"רב בק\"ק אשכנזים בשלוניקי על מקום אביו. נפטר צעיר. נספד ע\"י ר סעדיה לונגו."},{"i":6418,"n":"אשכנזי, דוד הלוי משלוניקי - ב","b":"רב בקהלת האשכנזים בשלוניקי-ש', וראש הקהלה על מקום יהודה אבירלין שעלה לצפת."},{"i":6419,"n":"אשכנזי, דוד זאב מניקופול","b":"רב בניקופול-שנות ה-ת'."},{"i":6420,"n":"אשכנזי, דוד טבלי","f":"יעקב","k":"בעל בית דוד","b":"רב ובקי ברפואה. חיבר \"בית דוד\" ובו גם סדר רפואות - וילהמשדורף תצד."},{"i":6421,"n":"אשכנזי, דוד מאלגיר","f":"יהודה","bt":"תרנד","dt":"תשמג","b":"רבה של אוראן(=ווהראן)-אלגיר-תרץ, רב ראשי באלגיר-תשך. עורך \"חבצלת השרון\" - פיוטים לימים מיוחדים. חיבר מאמר לתולדות קהילת ווהארן - אוג'דא תשיא, ועוד."},{"i":6422,"n":"אשכנזי, דוד מארץ ישראל","b":"שליח ארץ ישראל, היה בעיר לארסו שביון בשנת תנא ופסק שם במחלוקת בין קהלות איגרוביץ ופטראס."},{"i":6423,"n":"אשכנזי, דוד מארץ ישראל","f":"מרדכי - אשל אברהם","b":"אביו הוא בעל \"אשל אברהם\". יצא בשליחות בשנת תקה, בשנת תקו הדפיס בונציה \"קורא הדורות\" לר דוד קונפורטי, בשנת תקט הדפיס \"שות הרדב\"ז\" לפי כתב יד מירושלים."},{"i":6424,"n":"אשכנזי, דוד מארץ ישראל - ב","f":"יונה","b":"היה מצאצאי הש\"ך. בשנת תקץ בשליחות ארץ ישראל"},{"i":6425,"n":"אשכנזי, דוד מביחוב","f":"ישראל","b":"רב בביחאווא(=ביחוב), עלה לארץ והיה מראשי עדת החסידים, חתם בשנת תקמט על כתב שליחות ר שלמה זלמן בן צבי הירש הכהן. לדעת יערי הוא ר דוד בן ישראל אשכנזי שיצא בשליחות טבריה לצפון אפריקה-תקסא ואגרת אודותיו נשלחה לר שלמה אמלאל במרוקו, על האגרת חתם ר אברהם מקאליסק וראשי העדה."},{"i":6426,"n":"אשכנזי, דוד מטבריה - א","f":"יונה","dt":"תקמד","dp":"טבריה","b":"מחכמי טבריה, בשנת תקכב בשליחות טבריה ביון, בשנת תקטו חתם על איגרת שליחות ר שמואל שלם. בעברו בעיר ארטא ביון ענה לשאלה בענין עגונה (\"ראש משביר\" א ט), בשנת תקלה חתם על כתב שליחות ר חיים שלמה עמאר."},{"i":6427,"n":"אשכנזי, דוד מטרניגרד","f":"משלם זלמן אשכנזי","b":"רב בטרניגרד"},{"i":6428,"n":"אשכנזי, דוד מיאריטשוב","f":"החכם צבי","dt":"תקיז - כו ניסן","b":"חתן הגביר ר נתן מזולקוא. רב ביאריטשוב, עבר ללעשנוב ליד ברודי והסתיר עצמו והיה שמש ביהכ\"נ, ונחשב לאדם פשוט, עד שגילה את זהותו לפני פטירתו, ועל מצבתו כתבו שמ\"ש (והוא רמז גם להיותו שמש)."},{"i":6429,"n":"אשכנזי, דוד מירושלים","b":"מחכמי ישיבת \"נוה שלום\" בירושלים-תקיח."},{"i":6430,"n":"אשכנזי, דוד ממוהילוב","f":"ראובן הגדול ממוהילוב","dt":"תקצז - א תמוז","dp":"ירושלים","b":"חתן ר חנן קרולער, ובזיוו\"ש חתן ר מנחם מנדל משקלוב, מחכמי ירושלים, חתם על שטרי משכנתא והיה ממונה מטעם הקהלה."},{"i":6431,"n":"אשכנזי, דוד מפוזנא","b":"דיין בפוזנא"},{"i":6432,"n":"אשכנזי, דוד מפלאצק","f":"ישראל","b":"בשנת תצז בשליחות ירושלים לפרס. בשנת תקא חתם על כתב בקשת עזרה לקהלה. בשנת תקיח מחכמי ישיבת \"נוה שלום\"."},{"i":6433,"n":"אשכנזי, דוד מקאבאלה","b":"רב בקאבאלה-שנות ה-ש'."},{"i":6434,"n":"אשכנזי, דוד משה אברהם מרוהטין","dt":"תקי - יח תשרי","b":"רב בראהאטין"},{"i":6435,"n":"אשכנזי, דוד סגל מפוזנא ולבוב","f":"מרדכי אשכנזי","dt":"תה - א כסלו","b":"דרשן, דיין בפוזנא, רב במנוסטרישץ(=מאניסטערזיסק) דיין אצל ר שבתי שפטל בעל \"ווי העמודים\", דיין בלבוב וראש ישיבה. נזכר בשו\"ת מהר\"ם מלובלין, ב\"איתן האזרחי\", הסכים על \"נחלת יעקב\", ועוד. אולי בנו - ר משה שהיה חתן ר יוסף בן אליקים גץ מלבוב. חתנו - ר משה כץ בנו של בעל הסמ\"ע. (בובר מביא ממנו שחתם בפוזנא בשנת תיב ואם כן או תאריך פטירתו שגוי או שהיה חכם אחד בפוזנא ואחר בלבוב)."},{"i":6436,"n":"אשכנזי, דן","dt":"צ","b":"מגדולי הפוסקים בחכמי אשכנז,נדד לספרד"},{"i":6437,"n":"אשכנזי, דניאל ממרוקו","k":"רבי דניאל השומר","b":"מקדושי מרוקו"},{"i":6438,"n":"אשכנזי, הלל מאיטליה","b":"רב בקאנוא-תעז, טריסט-תעט. סמך את ר עמנואל ריקי."},{"i":6439,"n":"אשכנזי, זאב וולף מדובנא","f":"הלברשטט, זאב וולף","b":"חתן ר נחמן הלפרין. גביר,בקי בנגלה ובנסתר,רב בראדיוויל,דובנא-תקל\"ז. בנו - ר חיים יעקב."},{"i":6440,"n":"אשכנזי, זכריה מירושלים וצפת","f":"זעבסיל שבתי הקדוש","k":"חותן ר' יוסף קארו","b":"עלה מאשכנז לירושלים, דיין בבית הדין של האשכנזים בירושלים (עם ר דוד ורנק, ר יוסף לומרושו, ר יהודה בן אורי הלוי מהידלבורג). חתניו - ר יוסף קארו המזכירו בספריו, ר יוסף קולון בן משה לטף. הסכים על פס\"ד עם הרדב\"ז ור דוד ורנק."},{"i":6441,"n":"אשכנזי, חיים יעקב מדובנא","f":"זאב וולף הלברשטט מדו","dt":"תרי - י תשרי","b":"תלמיד ר ניסן בעל עצי לבונה. חתן ר דוד פרנס. רב בראוונא, דובנא על מקום אביו (ובעל שערי תשובה), ור חיים מרדכי מרגליות על מקומו אחריו ואולי חתנו - ר דוד צבי אוירבך על מקומו אחריו, בזמן ר אריה ליב קצנלנבוגן מבריסק, ור משה זאב מביאליסטוק. הסכים על \"עצי לבונה\" ו\"מעין גנים\" לרבו - ר ניסן."},{"i":6442,"n":"אשכנזי, חיים ישראל מקושטא","b":"מחכמי קושטא-שנות ה-ת'-תק'."},{"i":6443,"n":"אשכנזי, חיים מאוסטרהא","f":"אברהם משלם זלמן","b":"נכד החכם צבי. מחכמי אוסטרהא-תקלד ופרנס."},{"i":6444,"n":"אשכנזי, חיים מבוקרשט","b":"רב הקהלה האשכנזית בבוקרשט, חתם-תקעא (בערך) עם ר רחמים אברהם וינטורה (רב הקהלה הספרדית) בענין אישה מורדת."},{"i":6445,"n":"אשכנזי, חיים מחלב","f":"דוד","dt":"תרנא - טו תשרי","b":"רב ודיין בעין טב,דיין בחלב"},{"i":6446,"n":"אשכנזי, חיים מטבריה","b":"מחכמי טבריה, בשליחות בשנת תקעט, בשנת תקפא חתם עם רבני טבריה, בשנת תקצא שליח במרוקו, בהיותו במכנאס ביקש מרבה של העיר ר יעקב ברדוגו שהיה פייטן ידוע לחבר מלים ללחן שהביא מצפת. בשנת תרצד הסכים בפאס על הספר \"פתח הבית\" לר אברהם בלאיש ליוורנו תרו."},{"i":6447,"n":"אשכנזי, חיים מסרייבו ווינה","b":"גביר מראשי קהלת סרייבו, עבר לוינה עם רבים מבני הקהלה-תקס בערך בזמן מרד הסרבים."},{"i":6448,"n":"אשכנזי, חיים מקושטא","b":"מדפיס-תעא בדפוס של יונה בן יעקב בקושטא."},{"i":6449,"n":"אשכנזי, חיים צבי הירש מפשוורסק","f":"יונה מפשוורסק","b":"רב בפשוורסק-תרמה על כסא אביו, חתנו ר דב ברלי תאומים על מקומו אחריו."},{"i":6450,"n":"אשכנזי, חיים צבי מזאויחואסט","f":"משה אפרים מקאליש","b":"תלמיד ר ישכר דב מראדושיץ. רב בזאויחואסט על מקום אביו. הניח חבור על התורה בכת\"י."},{"i":6451,"n":"אשכנזי, חנוך הניך דב מבודפשט","f":"אלכסנדר חיים","bt":"תרעט","bp":"בודפשט","dt":"תשמו","b":"ברח לשוויץ בזמן השואה, עלה לארץ. חתן ר יהושע השל זקס. רב בסאן פאולו - ברזיל."},{"i":6452,"n":"אשכנזי, חנוך הניך דב מרישא","f":"ישראל מטלומטאטש","k":"אדמור מאלסק ברישא","dt":"תשלג - כה אב","b":"חתן ר שלמה זלמן פרנקל. אדמור מאלסק ברישא. ניצל מהשואה והגיע לרומניה, ואחריה עלה לירושלים וכיהן בה כאדמור."},{"i":6453,"n":"אשכנזי, חנוך הניך מלמברג","f":"ישראל מסרעט","bt":"תרמח","bp":"סרעט","dt":"תשא","b":"חתן הגביר ר אברהם וינר בעל אחוזת סמורזיף (ליד ברודי). התישב בלמברג והקים חצר בויאן בעיר. נשיא אגו\"י שם. נספה בשואה."},{"i":6454,"n":"אשכנזי, חנוך הניך מסמרזוב","b":"רב בסמרזוב. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":6455,"n":"אשכנזי, ידידיה משלוניקי","f":"אהרן","k":"בעל ידיד ה'","bt":"תס - בערך","dt":"תקט-טו - ה תמוז","dp":"שלוניקי","b":"תלמיד ר אברהם גטניו. מחכמי שלוניקי. חיבר \"ידיד ה'\"."},{"i":6456,"n":"אשכנזי, יהודה","f":"נתן אשכנזי","b":"תלמיד ר מרדכי יפה בעל הלבוש. חיבר פירוש להלכות קדוש החדש לרמב\"ם, ול\"צורת הארץ\" - נדפסו עם ה\"לבושים\"."},{"i":6457,"n":"אשכנזי, יהודה","f":"חיים מוורמייזא","dt":"שכג","b":"ראב\"ד ור\"מ בכל קהילות אשכנז"},{"i":6458,"n":"אשכנזי, יהודה אהרן צבי מפטרץ","b":"רב הכולל בפטרץ-תק."},{"i":6459,"n":"אשכנזי, יהודה ליב מלובלין","f":"מאיר","dt":"שנז - כא שבט","dp":"לובלין","b":"אב\"ד לבוב, בריסק, לובלין. נזכר בתשובות הב\"ח, תשובות גאוני בתראי - בשם \"ר ליב ר היניכם\" ו\"ר ליב חנהל\" ונזכר גם בפמ\"ג."},{"i":6460,"n":"אשכנזי, יהודה ליב מצפת","b":"מחכמי צפת, בשליחות צפת והיה באזמיר-תכז."},{"i":6461,"n":"אשכנזי, יהודה מאזמיר","f":"יוסף","k":"בעל מחנה יהודה","dt":"תקמד","b":"תלמיד וחתן ר ברזילי יעבץ, רב באזמיר. חיבר \"מחנה יהודה\" חידושים על \"חושן משפט\", \"יד יהודה\", ועוד. בנו - ר רפאל."},{"i":6462,"n":"אשכנזי, יהודה מאינדורנא ירושלי","dt":"תקס - בערך","b":"רב באינדרונא, עלה לירושלים. נקבר ליד ר חיים רפאל נבון (וכנראה בערך באותה השנה - תקס)."},{"i":6463,"n":"אשכנזי, יהודה מאלגיר","bt":"תף - בערך","dt":"תקן - בערך","b":"רב באלגיר. מתורתו ב\"קרבן אהרן\" לר אהרן מועטי."},{"i":6464,"n":"אשכנזי, יהודה מאלגיר וצרפת","f":"דוד","dt":"תשנז","b":"רב ומרביץ תורה בצרפת וארץ ישראל. ייסד ארגון \"מעיינות\", \"יאיר\", ממיסדי ישיבת \"מכון מאיר\" בירושלים."},{"i":6465,"n":"אשכנזי, יהודה מאלטונא","f":"היעב\"ץ","dt":"תקלה - כג שבט","dp":"אלטונא","b":"מחכמי אלטונא, נפטר צעיר."},{"i":6466,"n":"אשכנזי, יהודה מירושלים","f":"שמואל","b":"מחכמי ירושלים, רב הקהלה האשכנזית בשנת תעז, חתם על מכתב לברסלוי ולר דוד אופנהיים."},{"i":6467,"n":"אשכנזי, יהודה מירושלים","f":"יעקב","dt":"תקמו - ג חשון","dp":"ירושלים","b":"מחכמי ישיבת גדולת מרדכי ירושלים."},{"i":6468,"n":"אשכנזי, יהודה מקושטא","b":"דיין בקושטא-תר\"ן"},{"i":6469,"n":"אשכנזי, יהודה מקושטא","b":"מדפיס-תעא בדפוס של יונה בן יעקב בקושטא."},{"i":6470,"n":"אשכנזי, יהודה מראזלה","dt":"תקצט","b":"רבה של ראזלה על כסא אביו. בנו ר גרשון ישב על כסאו. נכדו של ר נתן נטע נאבק בפרנקיסטים יחד עם ר חיים כהן רפפורט מלמברג."},{"i":6471,"n":"אשכנזי, יהודה מרוזדול","f":"גרשון"},{"i":6472,"n":"אשכנזי, יהודה ס\"ט","b":"רב הכולל-שנת תק\"מ"},{"i":6473,"n":"אשכנזי, יהודה שמואל מטבריה","f":"יעקב","k":"בעל גבול יהודה","bt":"תקמ","bp":"טבריה","dt":"תרט","dp":"ליוורנו","b":"מחכמי טבריה, בשנת תר בשליחות באיטליה וצפון אפריקה, התיישב בליוורנו ושני בניו יעקב ואברהם הקימו שם בית דפוס. חיבר \"גבול יהודה\", \"ישא ברכה\" ליוורנו תקפב, ועוד. יש הטוענים שנפטר באזמיר, נספד על ידי ר חיים פאלגי.","bk":[["גזע ישי","מערכות"]]},{"i":6474,"n":"אשכנזי, יהושע השל מלובלין","f":"משלם זלמן מלובלין","dt":"תרכז - ה אדר","dp":"לובלין","b":"חתן ר בנימין ברוידא. רב בהורדנא, לובלין תריג על מקום ר דב בר אשכנזי (ועל מקום אביו שהיה הרב הקודם). הסכים על ש\"ס וילנא. תשובות ממנו ב\"בגדי ישע\". בנו ר בנימין מהורדנא החזיק בכתבי אביו ונשרפו בשריפת גרודנא."},{"i":6475,"n":"אשכנזי, יהושע מקושטא","b":"גביר בקושטא-תקמה, גיסו של ר יום טוב אלגזי וסייע בהדפסת ספרו \"שלמי צבור\" שאותו הדפיס ר אברהם חיון."},{"i":6476,"n":"אשכנזי, יהושע מרדכי מצפת","dt":"תקצד","dp":"מרוקו","b":"בשליחות קהילת צפת בצפון אפריקה. נהרג עק\"ה במרוקו."},{"i":6477,"n":"אשכנזי, יואל יצחק מבקשביץ","f":"שלמה","bt":"תקע","dt":"תרכז","dp":"קולומיאה","b":"אב\"ד בקשביץ על כסא אביו."},{"i":6478,"n":"אשכנזי, יואל מזבורוב (ברוכזון)","f":"ברוך","bt":"תרמד","bp":"זברוב","dt":"תשל","b":"מצאצאי ה\"ברוך טעם\". עלה לצפת בגיל 6 עם אביו. חתן ר נח ויינברג. התיישב בטבריה והיה מזקני החסידות."},{"i":6479,"n":"אשכנזי, יואל מזורובנא","b":"מחכמי זורובנא. תשובה אליו \"הרי בשמים\"-תרמא. (אולי הוא מחותמי כרוז היפרדות מכופרים - תרמא."},{"i":6480,"n":"אשכנזי, יואל מזלוטשוב","f":"משה דוד","k":"בעל שות מהרי אשכנזי","r":"אב\"ד זלאטשוב","bt":"תקע","dt":"תרמג - כב כסלו","b":"נשא את נכדתו של בעל ה\"חוות דעת\". רבה של גוליגור-תקצה, חודרוב-תרה, זלוטשוב-תרטו. רבו של המהרש\"ם. חיבר \"שו\"ת מהר\"י אשכנזי\" מונקטש תרנג. בנו - ר אשר אנשל מאלסק, חתנו - ר חנניה יו\"ט טיטלבוים. (באוצר הרבנים תאריך פטירתו - תרסז)","bk":[["שו\"ת מהר\"י אשכנזי",""]]},{"i":6481,"n":"אשכנזי, יואל מיאסי","f":"יחיאל מיאסי","k":"אדמור מיאסי","bt":"תרסו","bp":"בלז","b":"חתן ר שמואל שמלקא טויבש אב\"ד יאסי, וחתן ר אברהם האדמור מבילקמין. רב ואדמור ביאסי על מקום חמיו. עלה לירושלים-תשד, בתשט עבר לברוקלין והיה רב קהילת אוהב צדק."},{"i":6482,"n":"אשכנזי, יואל מירושלים","f":"חנוך הניך דב","k":"אדמור מאלסק בירושלים","dt":"תשלט","b":"נכד לאדמורי ליזנסק. אדמור מאלסק בירושלים."},{"i":6483,"n":"אשכנזי, יואל מניישטט","b":"רבה האחרון של ניישטט-תרפט אחרי ר מנחם הגר."},{"i":6484,"n":"אשכנזי, יואל מסטניסלב","f":"יצחק","bt":"תרמח","bp":"סטניסלב","dt":"תשד","b":"מצאצאי הבעשט, נכד האדמור מבלז. עלה לירושלים בילדותו, חזר לסטניסלב-תרנז. חתן ר משה טייטלבוים מטעטש והיה שם רב לצד חותנו ואחריו. רב בטערעסיף (קרפטורוס). נספה בשואה."},{"i":6485,"n":"אשכנזי, יואל משלוניקי","dt":"שכט","dp":"ירושלים","b":"רב בקהלת האשכנזים בשלוניקי-ש' ור יצחק הצמאן על מקומו אחריו. היה במחלוקת עם הרשד\"ם ור יוסף ן לב."},{"i":6486,"n":"אשכנזי, יואל פיבוש מזולקוא","f":"מאיר","b":"מחכמי זולקוא, חתם-שפו על תקנה בזולקוא."},{"i":6487,"n":"אשכנזי, יוחנן מירושלים","b":"מחכמי ירושלים, מוזכר במכתב ר ישראל מפירושא משנת רסט."},{"i":6488,"n":"אשכנזי, יונה המדפיס מקושטא","f":"יעקב מזלוויץ","b":"במקורו מזלוויץ-פלך לבוב, מדפיס בקושטא-שנות ה-ת' עם ר נפתלי בן עזריאל אשכנזי מוילנא, ובאזמיר-תצג עם ר דוד חזן. בניו - המדפיסים ראובן ונסים."},{"i":6489,"n":"אשכנזי, יונה מירושלים - א","b":"מגדולי חכמי אשכנז בירושלים-שמ\"ג"},{"i":6490,"n":"אשכנזי, יונה מירושלים - ב","b":"רב בירושלים-תס, בשליחות קהלת האשכנזים יחד עם ר איזיק מסלוצק. נזכר ב\"זרע אברהם\". חתם עם ר משה הכהן מפרג וירושלים, ועם חכמי הספרדים מבית דינו של ר אברהם יצחקי."},{"i":6491,"n":"אשכנזי, יונה מניישטט","dt":"תשג","b":"רב בניישטט. נספה בשואה."},{"i":6492,"n":"אשכנזי, יונה מפשוורסק","f":"שלמה","k":"בעל חשן ואפוד","bt":"תקעה","dt":"תרמה","b":"רב בפשוורסק, סניאטין-תריג. חיבר \"חשן ואפוד\" בכתב יד."},{"i":6493,"n":"אשכנזי, יונה שושנה","f":"יעקב","dp":"ארם צובא","b":"מחכמי צפת, יצא בשליחות עם ר יצחק אייזיק מסלוצק. בשנת תע חתם עם חברי דינו של ר אברהם יצחקי ומוזכר בספרו \"שות אברהם\". נפטר בהיותו בשליחות בארם צובא. אולי הוא זהה לר יונה בן ר\"י שחתם על תקנות הקהלה בשנת תץ."},{"i":6494,"n":"אשכנזי, יוסף דב מטבריה","b":"מחסידי טבריה הותיקים - עוד לפני עליית תקלז, ר מנחם מנדל מויטבסק התייעץ עמו בקשר למעבר מצפת לטבריה-תקמא."},{"i":6495,"n":"אשכנזי, יוסף דוד מבאזיליאה","f":"אברהם יהושע השל מבאז","k":"אדמור מבאזיליאה","dt":"תרעט - טו אד\"א","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. אדמור בבאזיליאה על מקום אביו, עבר לפרוסקרוב-ליד באזיליאה. נהרג עק\"ה."},{"i":6496,"n":"אשכנזי, יוסף הכהן מביירות","b":"דיין בביירות-תלד עם ר אברהם נחמיה ור מרדכי נחמיאש."},{"i":6497,"n":"אשכנזי, יוסף הלוי ממיץ","dt":"שפח - ז אדר","dp":"פפד\"מ","b":"תלמיד ר אליעזר טריווש. מחכמי פפד\"מ-שעח , רב במיץ."},{"i":6498,"n":"אשכנזי, יוסף יאסקי מפודקמין","f":"ישראל אשכנזי","k":"בעל אהל יוסף","dt":"תקכז - יד אלול","b":"רב בפודקמין"},{"i":6499,"n":"אשכנזי, יוסף לבל משלוניקי","b":"גביר מראשי קהלת שלוניקי, השתתף במשלחת אצל השולטן בקושטא-שצז בראשות ר יהודה קובו - שנהרג עק\"ה בידי השולטן."},{"i":6500,"n":"אשכנזי, יוסף ליב מברוד","b":"רב בברודי-תקץ."},{"i":6501,"n":"אשכנזי, יוסף מאדרינופול","b":"מחכמי אדרינופול-תם, פקיד קופת \"עזר\" והיה דין כנגדו ור משה בנבנישתי מקושטא פסק לטובתו."},{"i":6502,"n":"אשכנזי, יוסף מאזמיר","dt":"תקכה - כ סיון","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":6503,"n":"אשכנזי, יוסף מיאקובשטט","f":"ישראל","bp":"שוינציאן","dt":"תרכז - יג אלול","b":"תלמיד ר חיים מוולוזין. ראש ישיבה ביאקובשטט בזמנו של הראב\"ד - ר שמעון זרחי. חיבר ספרים. מבניו - ר משה מיאקובשטט - נפטר בחיי אביו, ר בן ציון מדוינסק."},{"i":6504,"n":"אשכנזי, יוסף מיוזיל-היסאר","b":"מראשי קהלת יוזיל-היסאר-ליד אזמיר-שנות ה-ת'."},{"i":6505,"n":"אשכנזי, יוסף ממצרים","b":"מחכמי מצרים בדור שלאחר הרדב\"ז."},{"i":6506,"n":"אשכנזי, יוסף ממרקשוב וצפת","f":"זאב איידליש","k":"בעל ברכת יוסף","dp":"צפת","b":"אב\"ד במארקשוב, עלה לצפת, ויצא בשליחות-תקפח. חיבר \"ברכת יוסף\" שלוניקי תקצא, ועוד."},{"i":6507,"n":"אשכנזי, יוסף מפרג","k":"התנא האלוקי","bt":"רצב","dt":"שמג","b":"מחכמי פרג, נכדו של ר אביגדור קרא רבה של פרג. חתנו של ר אהרן לנד רבה של פרג, עלה לצפת כנראה מוירונה, אחרי שנת ש\"ל, היה רבו של ר אלעזר אזכרי. ב\"חסד לאברהם\" חדושי תורה משמו. היה מכונה תנא על שם שהיה שונה משניות בניגון. עבר למצרים והגיה את המשנה על פי כתב יד קדום. מספרים עליו שלמד משניות עם הארי, וישנם שמועות בשמו שהגיעו מהארי. ר חיים ויטאל מביא מאמרים ממנו בספרו. לדעת ג. שלום חיבר עוד באיטליה קונטרס אנונימי בכתב יד נגד לימוד פילוסופיה."},{"i":6508,"n":"אשכנזי, יוסף מצפת","k":"התנא הגדול","b":"רב בקהלת האשכנזים בצפת-שנות ה-ש', מכונה \"התנא הגדול\" על שינון המשניות. בנו - ר אביגדור-תלמיד האר\"י."},{"i":6509,"n":"אשכנזי, יוסף מקושטא","f":"ישראל","b":"ראש קהלת האשכנזים בקושטא-שנות ה-ש'."},{"i":6510,"n":"אשכנזי, יחיאל מאלסק נ\"י","f":"משה דוד מסטניסלב","k":"אדמור מאלסק בנ\"י","bt":"תרמב","bp":"אלסק-גליציה","dt":"תרצב - טז אד\"ב","dp":"ניו יורק","b":"חתן ר אברהם לנדמן מבילקמין. רב ואדמור בגרוסוורדין, היגר לניו יורק-תרעט וכיהן בראש קהילת \"בני יחיאל אשכנזי\"."},{"i":6511,"n":"אשכנזי, יחיאל מטבריה","bt":"תרז","b":"עלה לארץ-תרם והתישב בטבריה. דומ\"צ בטבריה-תרמ."},{"i":6512,"n":"אשכנזי, יחיאל מיכל מטולטשין","f":"ברוך","k":"חתן הבעש\"ט","bp":"אשכנז","dt":"תקמד","b":"רב במזיבוז-תק\"כ. זקנו של ר נחמן מברסלב ואביו של ר אפרים בעל \"דגל מחנה אפרים\" שהביא מתורתו בספרו, מתורתו גם אצל ר ישראל מקוזניץ, ור שניאור זלמן מלאדי."},{"i":6513,"n":"אשכנזי, יחיאל מיכל מפודוולוטשי","b":"רב בפודוולוטשיסק. פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":6514,"n":"אשכנזי, יחיאל מיכל משלוניקי","f":"יעקב","b":"מדפיס אצל בצלאל הלוי אשכנזי בשלוניקי-תקו."},{"i":6515,"n":"אשכנזי, יחיאל משלוניקי","k":"בעל היכל ה'","dp":"ירושלים","b":"רב ומקובל, לאחר גירוש ספרד הגיע לשלוניקי, עלה לירושלים. (לדעת פרומקין היו 2 חכמים באותו השם והשני חי כ-60 שנה אחרי הראשון והיה קרובו של האר\"י ונקרא לוריא, והוא שהיה מירושלים וחיבר את \"היכל ה'\")."},{"i":6516,"n":"אשכנזי, יחיאל משלוניקי","f":"משה","b":"מחכמי שלוניקי-שנות ה-ר'-ש', ומחותמי ה\"הסכמות\"-לפני שט. רב בפטרץ ופעל לאיחוד הקהלות שם."},{"i":6517,"n":"אשכנזי, יחיאל פישל הלוי מקושטא","f":"פנחס","b":"מדפיס באזמיר-תצג אצל ר דוד חזן, עבר לקושטא-תצו בדפוס של יונה בן יעקב."},{"i":6518,"n":"אשכנזי, יעקב","b":"רב-שנת ת\"ק"},{"i":6519,"n":"אשכנזי, יעקב הכהן מאלגיר","b":"רב בתלמסאן(אלג'יר)-ר\"כ"},{"i":6520,"n":"אשכנזי, יעקב הכהן מזולקוא","f":"ישראל יוסף","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה עם ר יעקב בן אהרן זליג ור יעקב קופל בן דוד סגל. (ראה גם ר יעקב יוסף הכהן מבריסק - חתן התוי\"ט)"},{"i":6521,"n":"אשכנזי, יעקב הלוי גרמר","f":"מנחם נחום חסיד","b":"מצאצאי ר בצלאל אשכנזי. בנו - ר יעקב גרמר."},{"i":6522,"n":"אשכנזי, יעקב יצחק","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":6523,"n":"אשכנזי, יעקב ישראל מקושטא","b":"מחכמי קושטא - בשנים תק-תקן."},{"i":6524,"n":"אשכנזי, יעקב מיאנוב","f":"יצחק","k":"בעל צאנה וראנה","dt":"שפו","b":"מחכמי פרג, יאנוב. חיבר ספרים לנשים ובהם: \"המגיד\"."},{"i":6525,"n":"אשכנזי, יעקב מירושלים","bt":"תנח - בערך","dt":"תקכט - כג תשרי","dp":"ירושלים","b":"מחכמי ישיבת יעקב פירירה בירושלים. חתם על תקנות ירושלים-תצז. הסכים על \"חזון נחום\"-תקב, \"נחפה בכסף\"-תקו, \"פרי האדמה\"-תקז, ועוד."},{"i":6526,"n":"אשכנזי, יעקב מירושלים","f":"יצחק","dt":"שעו","dp":"עאנה","b":"מחכמי ירושלים, בשנת שע בשליחות בקורדיסטן (ראשון השדרים במדינה זו), בהיותו שם תיקן כמה תקנות. בשנת שע חתם ר יעקב אשכנזי שהיה ראב\"ד על גט כמובא בשות מהריטץ, ויתכן שהמדובר באותו אדם."},{"i":6527,"n":"אשכנזי, יעקב מירושלים","f":"שמואל","b":"מחכמי ארץ ישראל, חתם על שחרור תלמידי חכמים ממס בשנת רסט."},{"i":6528,"n":"אשכנזי, יעקב מירושלים","b":"דיין בירושלים, מכתב תודה ממנו-תרכט לר יצחק דב במברגר."},{"i":6529,"n":"אשכנזי, יעקב ממצרים","b":"רב במצרים-סוף שנות ה-ש'."},{"i":6530,"n":"אשכנזי, יעקב מצפת ודמשק","b":"מדפיס עם אביו בצפת-שמז, עבר לדמשק עם אחיו יצחק ויסד דפוס עם אברהם בת שבע."},{"i":6531,"n":"אשכנזי, יעקב מקאוואלא","b":"גביר בקאוואלא. תרם לת\"ת בשלוניקי-שמד."},{"i":6532,"n":"אשכנזי, יעקב מקושטא","f":"יוסף","b":"מחכמי קושטא, חתם-רפ על החזרת השתדלן ר שאלתיאל."},{"i":6533,"n":"אשכנזי, יעקב מקושטא","f":"אברהם-הקדוש מיימטוב?","b":"דיין ביה\"ד האשכנזי בקושטא-תטו. אולי הוא שהיה מדפיס אצל אברהם פרנקו."},{"i":6534,"n":"אשכנזי, יצחק","f":"אשר אנשל מסטניסלב","b":"טיפל בהוצאת כתבי אביו יחד עם אחיו ר משה דוד מקלוש ור שלמה. במלחמת העולם ה-I, גלה לפרנקפורט והצליח להציל עמו את כתב היד של אביו \"בשמים ראש\"."},{"i":6535,"n":"אשכנזי, יצחק אשר משלוניקי","dt":"תיב - ו חשון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":6536,"n":"אשכנזי, יצחק הכהן מאזמיר","b":"מדפיס באזמיר אצל ר דוד חזן-תצג."},{"i":6537,"n":"אשכנזי, יצחק הלוי מירושלים","b":"מחכמי ירושלים, מוזכר ב\"סדר הדורות\" לר אברהם כלפון שבשנת תקנא היה בשליחות.."},{"i":6538,"n":"אשכנזי, יצחק הלוי משלוניקי","b":"רב בשלוניקי על פני אביו... - בשנות ה-ר'-ש'. אביו של שלמה הלוי הזקן משלוניקי."},{"i":6539,"n":"אשכנזי, יצחק מאזמיר","dt":"תלג-ד","dp":"אזמיר?","b":"רב באזמיר-תכא, יחד עם ר בנימין מלמד."},{"i":6540,"n":"אשכנזי, יצחק מארה\"ב","f":"אלימלך מסן פאולו","bt":"תשג","b":"נכד ר אלכסנדר חיים מירושלים ונינו של ר יצחק ויליצקר אשכנזי מסטניסלב. מתגורר בארה\"ב."},{"i":6541,"n":"אשכנזי, יצחק מבעליצא","f":"יעקב אשכנזי","k":"בעל ברית עולם","dp":"ארלאווא","b":"מקובל,רב בבעליצא-תקס. אחיו - ר משה איוויער. נכדו - ר יצחק בן חיים מביאליסטוק הו\"ל את ספרו-וילנא תקף (יש ספק האם הוא המחבר את הספר)."},{"i":6542,"n":"אשכנזי, יצחק מחברון","f":"שלמה","b":"מחכמי חברון וחסיד חב\"ד, בשנת תקפז בשליחות (ראה גם ר יצחק פ\"ח מירושלים)."},{"i":6543,"n":"אשכנזי, יצחק מחודרוב ולבוב","f":"צבי","k":"בעל טהרת הקודש","bt":"תק","dt":"תקסז - כז ניסן","dp":"לבוב","b":"רב בחודרוב-תקמא, רב בלבוב-תקמב - והיה דיין אצל ר צבי הירש רוזניס יחד עם ר שמואל שינדלינגר. חיבר \"טהרת הקודש\" למברג תקנב. נכדו - ר צבי אביגדור - רבה של מונקטש-תקסט."},{"i":6544,"n":"אשכנזי, יצחק מירושלים","f":"אברהם - הרשל\"צ","k":"בעל כונן למשפט","bt":"תריט","bp":"ירושלים","dt":"תרעה-ו -כא אלול","dp":"אלכסנדריה","b":"בנו של ה\"ראשון לציון\" ר אברהם אשכנזי.דרשן, רב ומלמד בירושלים ודיין אצל ר יעקב שאול אלישר, סירב לכהן כרשל\"צ אחריו. ממקימי ביה\"ח \"משגב לדך\", ובשנת תרנד בשליחות באמריקה לצורך הקמת בית החולים \"משגב לדך\", ובתרסה בשליחות בצפון אפריקה ואחר כך בבוכרה. הוגלה בזמן מלחמת העולם הראשונה לאלכסנדריה ונפטר שם. חיבר \"כונן למשפט\" על ספרו של אביו, ירושלים תרלד, \"שמרו משפט\"."},{"i":6545,"n":"אשכנזי, יצחק מירושלים","f":"מתתיהו","b":"מחכמי ארץ ישראל, בשנת רסט חתם על התקנה לשחרור תלמידי חכמים ממס."},{"i":6546,"n":"אשכנזי, יצחק מלמברג","f":"פיבל מלכוביץ","b":"תלמיד ר ליב שרה'ס. מחכמי למברג. נזכר באגרת שבליקוטי רמ\"ל מססוב."},{"i":6547,"n":"אשכנזי, יצחק מסמיאטיץ","f":"דוד זכריה","b":"רב בסעמיאטיש(=סימיאטיץ)."},{"i":6548,"n":"אשכנזי, יצחק מצפת ודמשק","b":"מדפיס עם אביו בצפת-שמז, עבר לדמשק עם אחיו יעקב ויסד דפוס עם אברהם בת שבע."},{"i":6549,"n":"אשכנזי, יצחק מקושטא","f":"אברהם","b":"מחכמי קושטא-שנות ה-ש'."},{"i":6550,"n":"אשכנזי, יצחק מקראקא וירושלים","b":"מחכמי ירושלים-שנות ה-ת', בשליחות בפפד\"מ, נזכר במכתב ר שמשון ורטהיים לר יוסף רופא המלך."},{"i":6551,"n":"אשכנזי, יצחק מרודשטו","f":"יחיאל","b":"רב ברודשטו-תורכיה. נזכר ב\"יין המשומר\"-שנא ו\"נחלה ליהושע\"."},{"i":6552,"n":"אשכנזי, יצחק משלוניקי","b":"מחכמי שלוניקי - שנות ה-ש'."},{"i":6553,"n":"אשכנזי, יצחק סגל מברושה","b":"רב בברושה-שץ."},{"i":6554,"n":"אשכנזי, יצחק צבי מסרייבו","dt":"תעו","b":"רב הקהלה האשכנזית בסרייבו על מקום החכם צבי (אולי קרובו) ור שם טוב צבי על מקומו אחריו. היה מחלוקת כנגדו מחלק מהקהלה."},{"i":6555,"n":"אשכנזי, יצחק רפאל מחברון","k":"בעל ויען יצחק","b":"מחכמי חברון, חתום על כתב שליחות ר חייא דיין בשנת תכא. חיבר \"ויען יצחק\"."},{"i":6556,"n":"אשכנזי, יקותיאל מצפת","b":"מחכמי צפת, בשנת תפח בשליחות הקהלה בארצות המערב, בשנת תצו חתם עם חכמי צפת. חתם-תפא על כתב שליחות ר משה ישראל מרודוס."},{"i":6557,"n":"אשכנזי, יקותיאל מקושטא","f":"אשר","b":"מדפיס בקושטא-של אצל דוד אזוביב."},{"i":6558,"n":"אשכנזי, יקותיאל מקושטא - ב","b":"דיין בקושטא-תטו."},{"i":6559,"n":"אשכנזי, יקיר גרשון (קיטובר)","f":"אברהם גרשון קיטובר","k":"אחיינו של הבעש\"ט","dt":"תקלו-ט - ו כסלו","dp":"ירושלים","b":"מחכמי ברודי, אחיינו של הבעש\"ט, חתנו של ר משה אוסטרר בעל \"ערוגות הבושם\", עלה לירושלים לאחר אביו, מחכמי ישיבת \"דמשק אליעזר\"-תקיח. בשנת תקיז חתם על מכתב לקהילת מיץ, ועוד בשנת תקכב חותם כסופר וגבאי ק\"ק אשכנזים. מלומדי \"דמשק אליעזר\". בשליחות באירופה-תקלד יחד עם ר אליהו צבי ור יעקב בורלא - שליחות משותפת לקהלה הספרדית והאשכנזית - היה באיטליה אצל החיד\"א-המזכירו בספרו, לאחר איטליה המשיכו בצרפת ואח\"כ נפרדו ור יקר המשיך לאשכנז ופולין. חתם על כתב שליחות ר אברהם ריוח-תקלא יחד עם חכמי הספרדים בירושלים ובהם ר רפאל בן שמואל מיוחס, ר רפאל משה בולה, ועוד. אחיו - ר חיים אהרן מירושלים, ר משה מלאדיזין."},{"i":6560,"n":"אשכנזי, ישכר בער מיאס","dt":"תקיד","dp":"טבריה","b":"מחכמי טבריה"},{"i":6561,"n":"אשכנזי, ישעיה מקושטא","b":"מגיה בדפוס ר יונה בן יעקב אשכנזי בקושטא-תע."},{"i":6562,"n":"אשכנזי, ישעיה מקראקא","dt":"תיא - כג תשרי","b":"דיין בקרקא"},{"i":6563,"n":"אשכנזי, ישראל אריה מסרעט","f":"יואל מזלוטשוב","bt":"תקץ","dt":"תרעט","b":"גביר ורב בסרעט, בניו ר משה דוד ור יעקב על מקומו אחריו. עלה לירושלים-תרעג. חתן הגביר ר אברהם מרדכי מסרעט. גיסו של ר חיים טויבש מבוטושן, ורי\"ה ולרשטין מרישא."},{"i":6564,"n":"אשכנזי, ישראל בנימין זאב","f":"יהודה","b":"מחכמי פולין, עלה לצפת, היה חותנו של ר אברהם סגרי, חתום בין גדולי טבריה בשנת תקמה על כתב שליחות ר חיים שלום עמאר. בשנת תקנא בשליחות בלונדון ואמשטרדם יחד עם ר אברהם שלמה זלמן צורף."},{"i":6565,"n":"אשכנזי, ישראל מאופיבך","f":"נפתלי הרץ מלבוב","b":"חתן ר ברוך כהנא (רפפורט) מפיורדא. רב באופיבך, הענא-תקכ. מתורתו ב\"עיר דוד\" לר דוד לידא."},{"i":6566,"n":"אשכנזי, ישראל מאיטליה וירושלים","f":"יחיאל","bp":"איטליה?","dt":"שיא בערך","dp":"ירושלים","b":"מחכמי איטליה, עמד בראש ישיבה ברומא, עלה לירושלים בשנת רפ, והיה מרבני ירושלים בזמן הנגיד. נזכר במכתב ר משה באסולה כראש ישיבה לאשכנזים. מופיע ב\"חרבות ירושלים\" כאחד הסובלים בפרעות אבן פארוך בשנת שפה. היה תלמיד חבר לר יהודה מינץ באיטליה, השאיר כתבים שהיו בידי הרדבז. לדעת החוקרים פראוור קסוטו ואברהם דוד הוא זהה עם ר ישראל מפירושא, ואילו לדעת ריבלין וד. תמר המדובר בשני חכמים שונים. הניח כתבים ופסקים והיו בידי הרדב\"ז."},{"i":6567,"n":"אשכנזי, ישראל מאלסק","b":"רב באלעסק,ברלד-תר\"נ"},{"i":6568,"n":"אשכנזי, ישראל מהובניב","f":"אשר אנשיל אהרן","bt":"תקלו","dt":"תרא","b":"אב\"ד הובניב-תקסד, טיסמניץ-תקעה. חתנו ר משה חמיידס."},{"i":6569,"n":"אשכנזי, ישראל מהילדסהיים","f":"זאב וואלף","b":"רב בהילדסהיים"},{"i":6570,"n":"אשכנזי, ישראל מירושלים","b":"ראש ישיבת האשכנזים בירושלים-שנות ה-ר'-ש'."},{"i":6571,"n":"אשכנזי, ישראל מירושלים","b":"מקובל, רב בירושלים-שנות ה-ת', חברו של ר יעקב צמח. מתלמידיו - ר מאיר פופרש."},{"i":6572,"n":"אשכנזי, ישראל ממצרים","b":"דיין במצרים ודן בסכסוך שבין הג'יליבי שמואל הכהן לבין האחים ר משה ור יצחק בירב - יחד עם ר בצלאל אשכנזי."},{"i":6573,"n":"אשכנזי, ישראל מפריסטיק ויאסי","f":"אשר אנשל מאלסק","k":"אדמור מאלסק בטלומאטש","dt":"תשא - כו תמוז","dp":"ירושלים","b":"חתן האדמור מטשחויב. רב בפריסטיק, אדמור בטלומטש, רומניה-תרף, ניצל מהשואה ועלה לירושלים. בנו ר אשר אנשל רב בסורוקה, בנו ר חנוך הניך דב מרישא - חתנו של הרב פרנקל מידלובה. (בוונדר ח\"א - תאריך פטירתו תשלג). בנו ר משה - יהלומן בניו יורק - נרצח בתשמו."},{"i":6574,"n":"אשכנזי, ישראל מצפת","b":"מרבני צפת-ת\"צ"},{"i":6575,"n":"אשכנזי, ישראל מקושטא","b":"רב בקושטא-רן והרא\"ם עשה השגות על כמה מכתביו."},{"i":6576,"n":"אשכנזי, ישראל מרודוס","b":"גביר ברודוס-תקן בערך, תמך ברבני ובהדפסת ספריהם."},{"i":6577,"n":"אשכנזי, ישראל משלם זלמן מירלש","f":"היעב\"ץ","bt":"תפג","bp":"ברוד","dt":"תקנה - כח כסלו","dp":"אלטונא","b":"מצאצאי ר זלמן מירלס מאה\"ו ונקרא ע\"ש, נכד-אבי אמו ר מרדכי בן נפתלי הכהן מפפד\"מ. רב בפודהייץ, רב לעדת המבורג בלונדון-תקכט. נזכר בשו\"ת יעב\"ץ וב\"אור הישר\" בענין הגט מקליווא, ועוד."},{"i":6578,"n":"אשכנזי, ישראל נחום מטבריה","b":"מצאצאי החכם צבי. מחכמי טבריה וחתם עם אחיו? ר יעקב פנחס אשכנזי ור יואל אשכנזי."},{"i":6579,"n":"אשכנזי, ישראל נחמן מדרוהוביטש","f":"ראה: דרוהוביטשר, ישר"},{"i":6580,"n":"אשכנזי, ישראל רחל'ס","f":"שמואל","k":"אדמור מזינקוב","bt":"תקצא","dt":"תרסח","b":"מצאצאי האדמור ר אברהם יהושע השל מאפטא. נכד ר יצחק מאיר השל האדמור מזינקוב. חתן ר משה יהושע מפיקוב (ברדיטשוב). אדמור בזינקוב (למרות שסירב לאדמורות)."},{"i":6581,"n":"אשכנזי, לוי","k":"בעל בית הלוי","b":"אולי הוא נכדו של ר גבריאל אשכנזי. מגדולי חכמי דורו-ת\"ס"},{"i":6582,"n":"אשכנזי, מאיר הלוי משלוניקי","f":"שמעון","bt":"ר - בערך","bp":"נירנברג","dt":"רעט - ב תשרי","dp":"שלוניקי","b":"עבר מאשכנז לניקופול, פליבנה והתישב בסופיה, ראש קהלת אשכנז בשלוניקי. נכד ר יעקב מנירנברג. בנו - ר בנימין רב קהלת אשכנז בשלוניקי."},{"i":6583,"n":"אשכנזי, מאיר הלוי משלוניקי - ב","b":"רב בקהלת האשכנזים בשלוניקי-שך בערך."},{"i":6584,"n":"אשכנזי, מאיר מאה\"ו וחעלם","f":"בנימין וולף","b":"ראב\"ד ראשון של שלוש קהילות אה\"ו-תכד (לאחר שהתאחדו), עבר לחלם-תכט, וחזר לאלטונא. היה מחלוקת אודותיו בין קהלת אלטונא לקהלת ונדסבק שנידונה אצל ר יעקב ששפורטש ובסופה נפרדו הקהלות. הסכים על \"נחלת שבעה\" - תכז. נזכר ב\"אהל יעקב\", \"חיי יהונתן\"."},{"i":6585,"n":"אשכנזי, מאיר מירושלים","b":"דיין בירושלים-ש\"נ"},{"i":6586,"n":"אשכנזי, מאיר מירושלים","f":"שמואל","b":"מחכמי ירושלים בשנת שן-ת' בערך. מוזכר בשות מהריט\"ץ שמונה כבורר במחלוקת בקהלה. (ראה גם ר משה מאיר בק מירושלים)."},{"i":6587,"n":"אשכנזי, מאיר מספרד ושלוניקי","b":"מקובל,ממגורשי ספרד(רנ\"ב),בא לשאלוניקי"},{"i":6588,"n":"אשכנזי, מאיר מקונסטנטין","f":"היעב\"ץ","dt":"תקנ","b":"מגדולי דורו, בעל צדקה, רב בקונסטנטין-תקיד. חתנו ר דב בריש רפפורט, ר צבי הירש. הניח תשובות בכת\"י והיו אצל נכד נכדו ר חיים רפפורט מאוסטרהא שהביא בספרו \"מים חיים\" שאלה שנשאל ר מאיר ממזבוז ועל החתום \"ישראל בע\"ש מטליסט\" (=הבעשט) ו\"משה יוסף מ\"מ דפה\", והתשובה שהשיב להם ר מאיר ופנה אל הבעש\"ט \"אלוף ביהודה ובישראל עושה חיל וכו'\"."},{"i":6589,"n":"אשכנזי, מאיר משלוניקי","f":"מצליח","dt":"תקסב - כז ניסן","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":6590,"n":"אשכנזי, מאיר משנחאי","dt":"תשיד","b":"חסיד חב\"ד, בזמן השואה הגיע לשנחאי והיה שם רב. פרסם מאמרים ב\"אור תורה ממזרח\" - שנחאי תשא."},{"i":6591,"n":"אשכנזי, מותיג אברהם","b":"מחכמי טבריה, בשנת תקצג בשליחות לסוריה, חתום על פסק דין בדמשק בדבר ירושת חיים פרחי חותם אברהם אשכנזי ס\"ט (חוקות החיים שות ר חיים פאלאגי אזמיר תרכה). לדעת בניהו זהה לאברהם אשכנזי שהיה ברודוס בשנת תקעט"},{"i":6592,"n":"אשכנזי, מיכאל מחלב","f":"אברהם","dt":"תרמט - ח אלול","b":"רב בחלב, כפר תידיף (ליד חלב)."},{"i":6593,"n":"אשכנזי, מיכאל מקושטא","k":"בעל אם הדרך","dt":"תקסו - אחרי","b":"תלמיד ר אליהו פאלומבו. ממונה על איסור והיתר-תקלז, אב\"ד בקושטא - אחרי תקלה. חתם על פסקים תקנות והסכמות רבות. מתלמידיו - ר חיים שמואל מקושטא."},{"i":6594,"n":"אשכנזי, מלכיאל חזקיהו מחברון","f":"אברהם","k":"בעל מלכיאל","dt":"שנו","dp":"חברון","b":"מחדש הישוב היהודי בחברון בשנת שך, והיה רב הקהלה ור מנחם בן משה הבבלי על מקומו אחריו. חיבר \"מלכיאל\" טהינגן שך."},{"i":6595,"n":"אשכנזי, מנחם בן יצחק","f":"בכמוהר\"ר, מנחם","b":"רב וחכם באשי בבגדד-תרפ\"ו"},{"i":6596,"n":"אשכנזי, מנחם הלוי מקושטא","f":"בנימין משלוניקי","b":"חתן אחיו - ר דוד, ובזיוו\"ש חתן ר חיים באסאן מקושטא. מחכמי שלוניקי, עבר לקושטא. אחיו של ר דוד-רבה של ק\"ק אשכנזים בשלוניקי. חתם-שכט על מכתב התמיכה של רבני קושטא ושלוניקי בדון יוסף נשיא. אחיו - ר דוד."},{"i":6597,"n":"אשכנזי, מנחם יעקב","f":"אליעזר יהודה","b":"מחכמי צפת, עסק במכירת ספרים ונאלץ לנדוד, הגיע לקושטא ולעיר כיאוס, משם לאזמיר ושלוניקי והדפיס באזמיר \"שיר השירים\" עם תרגום ספרדי בשנת שס. הביא לדפוס \"אורים ותומים\" לר מאיר עראמה ונציה שסג."},{"i":6598,"n":"אשכנזי, מנחם מונציה","b":"רב לאשכנזים בויניציאה-ת\"צ"},{"i":6599,"n":"אשכנזי, מנחם מצפת וירושלים","f":"ברוך בנדיט","k":"בעל מים אדירים","dt":"תקפז - ל שבט","b":"גדול בנגלה ונסתר,מדפיס ספרי הגר\"א,עלה לצפת-תקס\"ו,מייסד היישוב החדש בירושלים"},{"i":6600,"n":"אשכנזי, מנחם מקושטא","f":"ראובן","b":"מדפיס בקושטא על מקום אביו-תקל עם בן דודו שמואל בן נסים אשכנזי."},{"i":6601,"n":"אשכנזי, מנחם משלוניקי","f":"עזריאל","dt":"תק - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":6602,"n":"אשכנזי, מנחם נחום","k":"רבי נחום חסיד","b":"רב בכמה קהילות בפולין-שנת ת\"ס"},{"i":6603,"n":"אשכנזי, מצליח מחברון","dt":"תפ - לפני","dp":"שלוניקי","b":"מחכמי חברון, לפני תפ בשליחות בשלוניקי ונהרג בשליחותו"},{"i":6604,"n":"אשכנזי, מרדכי","f":"נתן אשכנזי","b":"רב-שנת תק\"נ"},{"i":6605,"n":"אשכנזי, מרדכי","f":"יהודה ליב","k":"בעל אשל אברהם","b":"חיבר הקדמה ל\"אור נערב\" לר משה קורדובירו, ושם כתב כי חיבר ספר \"אשל אברהם\". בנו - ר אברהם מזולקווא-חתם בשנת שפו."},{"i":6606,"n":"אשכנזי, מרדכי - השבתאי","k":"מרדכי החסיד","b":"מתלמידי שבתי צבי."},{"i":6607,"n":"אשכנזי, מרדכי הכהן מצפת וחלב","f":"יצחק","k":"בעל שפתי כהן","bp":"צפת","dt":"שפ - בערך","b":"חתן ר שמואל לניאדו בעל הכלים. תלמיד ר ישראל די קוריאל בצפת, מחכמי צפת, רב בחלב לצד חותנו-שלט, ועל מקומו אחריו ור חיים בן אברהם הכהן על מקומו אחריו, עלה לצפת (לפי רוזנס נפטר בחלב). חיבר \"שפתי כהן\" ונציה שכה ובו גימטריאות על התורה מכת\"י רבנו שמשון שהיה בידיו. בשנת שצז חתם עם רבני צפת על מכתב לקהילת מנטובה."},{"i":6608,"n":"אשכנזי, מרדכי וולף מאוסטרהא","b":"רב באוסטרהא-ק\"צ"},{"i":6609,"n":"אשכנזי, מרדכי זאב מדובנא","f":"אריה ליב מאוסטרהא","dt":"תריד - כט ניסן","dp":"דובנא","b":"נכד(-אבי אמו) ר אבלי ראש משפחת זוסמן באוסטרהא. חתן הגביר ר צדוק מארשלקוביץ מדובנא. חתנו - ר חיים אליאש מדובנא."},{"i":6610,"n":"אשכנזי, מרדכי זאב מקעמפנא","f":"משלם זלמן אשכנזי","b":"רב בקעמפנא-ת\"ר, חתן ר ישראל יונה לנדא."},{"i":6611,"n":"אשכנזי, מרדכי כהן מאיטליה","k":"בעל מר דרור","b":"רב באיטליה. חיבר \"מר דרור\"."},{"i":6612,"n":"אשכנזי, מרדכי מאטל מטבריה","b":"מראשי כולל ווהלין בטבריה-תרלב."},{"i":6613,"n":"אשכנזי, מרדכי מדמיטש","f":"משה דוד","dt":"תשב","b":"חתן ר אברהם הגר מדמיטש וזבלטוב, רב בדמיטש ובזבלטוב על מקום חותנו. נספה בשואה."},{"i":6614,"n":"אשכנזי, מרדכי מירושלים","f":"יהודה ליב","b":"תלמיד ר אברהם רוויגו בעל \"אשל אברהם\". מקובל מחכמי ירושלים-שנת תמ. התלווה אל רבו במסעותיו."},{"i":6615,"n":"אשכנזי, מרדכי מפיסטין","f":"משה דוד","bt":"תקעה","dt":"תרמה","b":"אב\"ד פיסטין, סטניסלב-תר, עלה לירושלים-תרם. בנו ר מאיר היה לימים רב בנורבגיה-תרלא."},{"i":6616,"n":"אשכנזי, מרדכי מרוסטיץ וירושלים","f":"ישעיה","b":"מכתב ממנו מירושלים-שעו - נדפס ב\"תוצאות ארץ ישראל\". בנו אולי - ר יעקב יקובקי מירושלים ובריסק."},{"i":6617,"n":"אשכנזי, מרדכי סגל","b":"רב-שנת ש\"נ. בנו ר דוד סגל אשכנזי מפוזנא ולבוב."},{"i":6618,"n":"אשכנזי, מרדכי פתחיה מירושלים","b":"מראשי הקהלה האשכנזית בירושלים-תק עם ר אברהם גרשון קיטובר ור אריה יהודה מאפטא."},{"i":6619,"n":"אשכנזי, משה אהרן מפרג","f":"הקדוש שמואל שפירא","k":"חותן התוספות יום טוב","dt":"שפא - א תשרי","b":"מגדולי נכבדי פרג"},{"i":6620,"n":"אשכנזי, משה אפרים מקאליש","f":"מרדכי אשכנזי","b":"נינו של ה\"חכם צבי\". תלמיד ר משה ליב מסאסוב (או קוסוב?) חתן ר מאיר קריסנאמפאלי בעל \"יד המאיר\". רב בזאויחואסט ובנו ר חיים צבי על מקומו אחריו, קאליש-תקפא."},{"i":6621,"n":"אשכנזי, משה דוד (יפה) מצפת","f":"אשר אנשיל מרוזדול","k":"בעל באר שבע","r":"אב\"ד טאלטשוב","bt":"תקלד","bp":"רוזדול","dt":"תרטז - יח תמוז","dp":"צפת","b":"מצאצאי ר שכנא אב\"ד לובלין. בשנת תקסד רבה הראשון של טולטשווא(=טולצ'בא)-מחוז זמפלן-הונגריה כ-40 שנה. עלה לירושלים-תרג, עבר לצפת-תרד וכיהן בה כרב בהוראת ר ישראל מרוזין. חיבר \"באר שבע\" ירושלים תריג, \"תולדות אדם\" ירושלים תרה, ועוד. חתנו ר יקותיאל טיטלבוים בעל \"ייטב לב\".","bk":[["באר שבע - על התורה",""],["תולדות אדם - ש\"ס",""],["באר שבע",""]]},{"i":6622,"n":"אשכנזי, משה דוד מביטשקוב","b":"מחכמי ביטשקוב בהונגריה. תשובה אליו ב\"אבני זכרון\"-תרנה. תלמיד ר אריה ליב הורביץ שהשיב לו בספרו \"הרי בשמים\"."},{"i":6623,"n":"אשכנזי, משה דוד מסטניסלב","f":"אשר אנשיל מסטניסלב","k":"אדמור מסטניסלב","bt":"תרך","dt":"תרף","dp":"סטמר","b":"חתן ר אברהם אהרן טיטלבוים אב\"ד קולבסוב. רב ואדמור מאלסק בסטניסלב על מקום אביו, עבר ללבוב, רב בקלויזנבורג, בלד-באלטי (בסרביה), סטמר."},{"i":6624,"n":"אשכנזי, משה דוד מסרעט","f":"יואל","b":"רב בסרעט. חבר אגודת הרבנים לסמיכה-תרעד."},{"i":6625,"n":"אשכנזי, משה דוד מסרעט","f":"ישראל אריה בן יואל","bt":"תרל","dt":"תרצט - י תשרי","b":"תלמיד דודו ר חנניא יו\"ט ליפא טיטלבוים מסיגט. חתן ר יעקב פאנט מרטיאג בעל \"שארית יעקב\" והזכירו בספרו, ועבר לשם. רב בספערמעזא-תרנח, דעש-תרסג, דיין בסערט. רב בסרעט על מקום אביו (לפי וונדר)."},{"i":6626,"n":"אשכנזי, משה דוד מפרמישלא","f":"אשר מרדכי","b":"מחכמי פרמישלא - תשובה אליו בשו\"מ."},{"i":6627,"n":"אשכנזי, משה דוד מקאליש","f":"אשר אנשיל מסטניסלב","bt":"תריג","dt":"תרעג","b":"בנו של בעל \"שמן ראש\", רב בקלוש(=קאליש), חרסקוב-תרסה. מראשי המזרחי בקולומיאה. בנו ר יונה כיהן אחריו בחרסקוב."},{"i":6628,"n":"אשכנזי, משה דוד מרוזדיל","dt":"תקעה - כד תשרי","b":"רב בראזדיל"},{"i":6629,"n":"אשכנזי, משה הכהן מדאנהויזן","b":"דיין בפרנקפורט, רב בדאנהויזן (ליד אנשבך)-שפ. בנו - ר מאיר כץ ממוהילוב, נכדו ר שבתי בעל הש\"ך, נינו - ר מאיר איזנשטט בעל \"פנים מאירות\"."},{"i":6630,"n":"אשכנזי, משה הלוי משלוניקי","f":"אליעזר","dt":"שד - ג חשון","dp":"שלוניקי","b":"מחכמי שלוניקי, אולי הוא אחיו של ר אליעזר הלוי משלוניקי."},{"i":6631,"n":"אשכנזי, משה זאב וולף מדובנא","b":"רב בדובנא רבתי-תק\"נ"},{"i":6632,"n":"אשכנזי, משה מברודי","f":"נפתלי הירץ מלבוב","b":"נכד(-אבי אמו) ר משה פנחס חריף מלבוב. חתן ר יעקב באב\"ד מברודי. מחכמי ברודי-תקל. בנו - ר נפתלי מראווי וירוסלב."},{"i":6633,"n":"אשכנזי, משה מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":6634,"n":"אשכנזי, משה מזווילין","f":"יצחק א\"ש","b":"רב בזווילין,מיר-ת\"ק"},{"i":6635,"n":"אשכנזי, משה מזולקוא","f":"יוסף (יוסקי) העניכש","k":"משה ר יוסק'ס","dt":"תקכב - יח אלול","dp":"זולקוא","b":"שם אביו לפי בובר - יעקב. חתן ר אריה ליב מאמשטרדם-חתן החכם צבי. רב בזולקוא. בניו - ר מרדכי זאב אורנשטין מלבוב (ונכדו ר יעקב בעל \"ישועות יעקב\"), ר משלם זלמן מפמארין ונכדו ר משלם זלמן אשכנזי מלובלין."},{"i":6636,"n":"אשכנזי, משה מזולקוא","f":"דניאל","b":"מחכמי זולקוא, חתם-שפו על תקנה בזולקוא."},{"i":6637,"n":"אשכנזי, משה מזולקוא וקמינקא","f":"החכם צבי","b":"רב בזולקוא, קמינקא. נזכר בתשובה לאביו. (היה גם ר משה רוקח שהיה חתן החכם צבי - ואולי יש בלבול ביניהם?)"},{"i":6638,"n":"אשכנזי, משה מחברון","f":"יעקב","b":"מחכמי חברון, בשנת תקכג חתם על מכתב רבני חברון."},{"i":6639,"n":"אשכנזי, משה מטארבין","f":"שמואל","b":"רב בטארבין-ת\"פ"},{"i":6640,"n":"אשכנזי, משה מיאקובשטט","f":"יוסף מיאקובשטט","dt":"תרכז - כז טבת","b":"ר\"מ בישיבת אביו ביאקובשטט. נפטר בחיי אביו."},{"i":6641,"n":"אשכנזי, משה מירושלים","dt":"תקמב - יח חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":6642,"n":"אשכנזי, משה מלאריסה - א","f":"מנחם","b":"מראשי קהלת לאריסה-תפב."},{"i":6643,"n":"אשכנזי, משה מלאריסה - ב","dp":"לאריסה","b":"רב בלאריסה-תקן בערך ור אברהם סידיס על מקומו אחריו וחזר אחר פטירת ר אברהם-תקסד בערך."},{"i":6644,"n":"אשכנזי, משה מלבוב","f":"מרדכי","dt":"שס - ז ניסן","dp":"לבוב","b":"אב\"ד בלבוב. חתם-יב טבת שמו - עם ר יוסף קלמנקיש, ור יהודה ליווא אפשטין, תשובה ממנו לבעל הסמ\"ע ומהר\"ם מינץ ונזכר ב\"משאת בנימין\", חתם-שפז עם ר בנימין וולף בן יהודה ליב כץ, ור שמואל בן יהודה אוירבך, חתם-שצג עם ר יוחנן בן דוד עשרים וארבע ור מרדכי בן צבי הירש, ועוד."},{"i":6645,"n":"אשכנזי, משה מלבוב","b":"דיין בלבוב-שנת ת'"},{"i":6646,"n":"אשכנזי, משה מלבוב","f":"מרדכי מטיסמניץ","b":"מו\"צ בלבוב,רב בראזדל-תק\"כ"},{"i":6647,"n":"אשכנזי, משה מלבוב","f":"אורי פיבש","b":"דיין בלבוב, חתם-ת' בפנקס הקהל על מכירת קרקע עם ר נפתלי הרץ בן יהודה זלקל, ור יוסף בן יצחק, ור יהודה ליב בן אורי."},{"i":6648,"n":"אשכנזי, משה מנחם משלוניקי","f":"ישראל דוד","b":"תלמיד מהרשד\"ם בשלוניקי. רב בקהלת האשכנזים בשלוניקי."},{"i":6649,"n":"אשכנזי, משה מניקלשבורג","dt":"תנא - כב ניסן","b":"גדול בנגלה ונסתר,רב בברודא,דיין בניקלסבורג"},{"i":6650,"n":"אשכנזי, משה מפומארין לבוב","f":"צבי הירש מסטניסלב","k":"אדמור מסטניסלב בלבוב","b":"אדמור מסטניסלב בלבוב על מקום אביו."},{"i":6651,"n":"אשכנזי, משה מקושטא - ב","b":"ממונה על איסור והיתר בקושטא-תקלג, ואחד מסופרי העיר."},{"i":6652,"n":"אשכנזי, משה מקושטא ומגניסיא","b":"תלמיד ר יוסף טרני-מהרי\"ט. רב בקושטא, מגנסיה-שעה, תשובה אליו בשות מהרי\"ט."},{"i":6653,"n":"אשכנזי, משה מרדכי מקושטא","b":"מדפיס בקושטא-תקיד-תקל אצל ראובן ונסים בני יונה אשכנזי."},{"i":6654,"n":"אשכנזי, משה סגל","f":"דוד מפוזנא ומנוסטריש","b":"חתן ר יוסף בן אליקים גץ מלבוב. נאסר וברח, חותנו מכר מקום בבית הכנסת כדי לפדות את בתו שנאסרה גם היא."},{"i":6655,"n":"אשכנזי, משה שלמה מקושטא","b":"רופא מחכמי קושטא-תץ בערך, בזמן ר אפרים נבון המזכירו בספרו."},{"i":6656,"n":"אשכנזי, משלם זלמן","f":"אריה ליב מאוסטרהא","bt":"תקמט - בערך","bp":"אוסטרהא","b":"חתן הגביר ר הירש קאזמירער."},{"i":6657,"n":"אשכנזי, משלם זלמן מלובלין","f":"יעקב משלם זלמן מפמור","k":"בעל בית משלם","dt":"תרג - א אייר","b":"נולד אחרי פטירת אביו, מצאצאי החכם צבי-מצד אמו, אחיו של ר מרדכי זאב אורנשטין מפשמישל. לאחר שנתייתמו גדלו אצל אביהם החורג ר צבי הירש מרגליות מלובלין. מגדולי חכמי דורו, אב\"ד קוזמיר, נשלסק, לובלין-תקפו. תשובות ממנו ב\"זכרון צבי מנחם\". חתנו - ר שמעון פוגלמן-גיסו של ר עקיבא איגר מפוזנא."},{"i":6658,"n":"אשכנזי, משלם זלמן מלובלין","f":"נתן אשכנזי","k":"בעל חדושים למשניות","b":"רב בלובלין-תק\"ס"},{"i":6659,"n":"אשכנזי, משלם זלמן מפומורין","f":"דוד או משה","bt":"תקיב","dt":"תקלז - יד חשון","b":"רב בדוברומיל, בפמורן(=פאמורין). חתן ר אריה ליב אוירבך מסטניסלב. נפטר צעיר. בניו: הגביר ר אריה ליבוש אשכנזי מאוסטרהא, ר משלם זלמן מלובלין (נולד אחר פטירת אביו) - אשתו נשאה בזיוו\"ש לר מאיר מרגליות בעל מאיר נתיבים (ולפי בובר-זולקוא נישאה לר בצלאל בעל פנים מאירות מאוסטרהא). (לפי \"גדולי אוסטרהא\" היה בנו של ר משה ואחיו של ר מרדכי זאב אורנשטין-אבי \"הישועות יעקב\")."},{"i":6660,"n":"אשכנזי, משלם ישכר מסטניסלב","f":"צבי הירש מסטניסלב","k":"אדמור מאלסק בלונדון","r":"האדמו\"ר מסטאניסלאוו לונדון","bt":"תרסב-ה","dt":"תשנה - ג כסלו","b":"חתן ר קלונימוס קלמן הכהן יולס מסמבור. תלמיד ר אליהו שמואל וין. ישב בוינה-תרעו ועבר לאנגליה והיה שם אדמור מאלסק-סטניסלב בלונדון ובנו ר אורי על מקומו אחריו. חיבר \"תפארת משולם\" ניו יורק תשסא.","bk":[["תולדות משולם",""],["תפארת משולם",""]]},{"i":6661,"n":"אשכנזי, משלם שרגא פיביש מצפת","f":"ברוך","bt":"תרמז","dt":"תשד","b":"נכד ר יואל אשכנזי מזלוטשוב-חותנו של בעל קדושת יו\"ט. חתן ר יעקב יצחק אונגר מצפת - גיסו של הדב\"ח. תלמיד הרידב\"ז בצפת. יצא בתרעז לחו\"ל אל קרובו ר יואל טיטלבוים ודבק בו כמשמשו 27 שנה. נספה בשואה. בנו - ר אפרים יוסף דב - משמשו של האדמו\"ר על מקום אביו."},{"i":6662,"n":"אשכנזי, נח הכהן מבודון","b":"גביר בבודון(=בודה). תרם לבנית הת\"ת בשלוניקי-שפד אחרי שנשרף, ופעם נוספת בשנת ת', ותרם ללמודי תורה בירושלים ובצפת."},{"i":6663,"n":"אשכנזי, נח משלוניקי","f":"צבי","dt":"תקכב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":6664,"n":"אשכנזי, נחום מירושלים","f":"גרשון - (משה גרשום)","b":"מחכמי ירושלים-תסה, חתם אז על מכתב רבני ירושלים כנגד אנשי ר יהודה החסיד."},{"i":6665,"n":"אשכנזי, נסים אברהם מאזמיר","f":"רפאל - מראה עינים","k":"בעל דרש אברהם","dt":"תרך - טו אלול","dp":"אזמיר","b":"דיין באזמיר אצל ר חיים פלאג'י. חיבר \"דרש אברהם\" שלוניקי תרא, ועוד.","bk":[["דרש אברהם",""],["מעשה (מעשי) אברהם",""],["נחמד למראה",""]]},{"i":6666,"n":"אשכנזי, נסים מחברון","f":"חיים","b":"מחכמי חברון, בשנים תקצג, ותקצח בשליחות בתורכיה."},{"i":6667,"n":"אשכנזי, נסים מקושטא","f":"חיים","b":"מדפיס-תעא בדפוס של יונה בן יעקב בקושטא, והיה מדפיס בשם זה גם בשנת תקל (האם הוא נכדו?)."},{"i":6668,"n":"אשכנזי, נסים מקושטא","f":"יונה בן יעקב מקושטא","dt":"תקכח","b":"מדפיס בקושטא אצל אביו-תקג ואח\"כ עם אחיו ראובן, ובנו - שמואל לצדו ועל מקומו אחריו."},{"i":6669,"n":"אשכנזי, נסים נחמיה מקושטא","dt":"תרכה - א תמוז","b":"רב בקושטא."},{"i":6670,"n":"אשכנזי, נפתלי הכהן מבודה","f":"יצחק","b":"גביר מראשי קהלת בודה-שנות ה-ש'."},{"i":6671,"n":"אשכנזי, נפתלי הרץ","b":"חתם-תסד על תקנת קהלת זולקוא עם ר אברהם בן מרדכי מזולקוא, חתמו גם בועד סטרליסק."},{"i":6672,"n":"אשכנזי, נפתלי הרץ מזולקוא","f":"משה מברודי","k":"רבי הרץ רבי אסרלס","b":"חתן הפרנס ר איסר מזולקוא. ראב\"ד בזולקוא-תקג, רב בראווע-תקלה, ירולסב. הסכים על \"אבן העוזר\", \"מפלגי ראובן\", נחלת שמעון\", ועוד. בנו - הגביר ר יואל נתן, חתנו - ר זליג הוליש מלבוב."},{"i":6673,"n":"אשכנזי, נפתלי הרץ מלבוב","f":"ישראל","dt":"תעב - יח חשון","dp":"לבוב","b":"חתן ר צבי הירש מלבוב ובזיוו\"ש חתן ר משה פנחס חריף מלבוב. מגדולי דורו, נשיא ועד דד\"א, רב בקאוולי, טיקטין-תסא, לבוב-תסב על מקום חותנו, ו\"החכם צבי\" על מקומו אחריו, ונכדו ר יעקב יהושע בעל \"פני יהושע\" על מקום זקנו אחרי ה\"חכם צבי\". בניו - ר ישראל, ר צבי הירש מהלברשטט בעל עטרת צבי (מאשתו הראשונה), ור משה מברודי-חתן ר יעקב באבד (מאשתו השניה). מחותן עם בעל פני יהושע שהביא מתורתו בספרו. מתורתו גם ב\"עיר דוד\" לר דוד לידא, ב\"עדות ביוסף\" לר יוסף איטינגא, ב\"אסיפת חכמים\", ועוד."},{"i":6674,"n":"אשכנזי, נפתלי הרץ מפלאצק","f":"משלם זלמן אשכנזי","dt":"תרלו - ב אב","b":"רב בפלצק"},{"i":6675,"n":"אשכנזי, נפתלי מצפת","f":"יוסף","k":"בעל אמרי שפר","bp":"צפת","dt":"שסב","dp":"ונציה","b":"מחכמי ירושלים, צפת, בשנת שסא היה רב בונציה אצל ר בן ציון צרפתי - רב בישיבת הקצין בילגראדו. ר יהודה אריה ממודנא הזכירו ב\"מדבר יהודה\". חיבר \"אמרי שפר\" ונציה שסא, בספר - שיר שכתב ר אריה די מודנא לכבודו. מתורתו ב\"נובלות חכמה\" ליש\"ר מקנדיא שהחזיק בכתביו, וכן ב\"יוסף אומץ\" לר יוסף האן."},{"i":6676,"n":"אשכנזי, נפתלי מקושטא","f":"עזריאל מוילנא","b":"מדפיס בקושטא-תעא יחד עם ר יונה בן יעקב אשכנזי מזלוויץ. כנראה אחיו של ר אליהו בן עזריאל המדפיס בפפד\"מ."},{"i":6677,"n":"אשכנזי, נפתלי מקושטא ווינה","b":"גביר מראשי ומיסדי עדת יהודי תוגרמה בוינה-תעח (על פי הסכם השלום בין האוסטרים לתורכים)."},{"i":6678,"n":"אשכנזי, נפתלי משלוניקי","f":"יוסף","k":"בעל זהר חדש","b":"רב בקהלה האשכנזית בשלוניקי. חיבר זהר חדש - שלוניקי שנז - יחד עם חברו ר שלמה אשכנזי בן יצחק הכהן."},{"i":6679,"n":"אשכנזי, נתן ליב מטיסמניץ","b":"רב בטיסמניץ-תק\"צ"},{"i":6680,"n":"אשכנזי, נתן מברודי","f":"החכם צבי","bt":"תעח","dt":"תקלח - ו שבט","b":"מגדולי חכמי ברוד. נכדו - ר יעקב ליסא."},{"i":6681,"n":"אשכנזי, נתן מקושטא","f":"שלמה הרופא מאיטליה ו","b":"גביר ורופא בקושטא (אמו היתה מקורבת לחצר השלטן אחר פטירת אביו), עבר לונציה-שסה. תמך בהדפסת \"תורת משה\" ונציה שסו."},{"i":6682,"n":"אשכנזי, נתן מקושטא - ב","dt":"תמה","dp":"קושטא","b":"ר\"מ בקהלת אשכנזים בקושטא, ור חיים עשאל על מקומו אחריו, היה גם בשלוניקי. מקובל שעשה תיקונים בסדר התפלות. (ואולי המדובר בשני חכמים האחד בקושטא והשני בשלוניקי)"},{"i":6683,"n":"אשכנזי, נתן נטע יהודה מדוקלא","f":"יעקב או גרשון","k":"בעל מאורות נתן","bt":"תקן","dt":"תרך","b":"גדל אצל אמו והתחנך אצל דודו ר יעקב מליסא בעל \"חוות דעת\". רב בפאטיק-תרה, רב בדוקלא על מקום מחותנו ר יעקב הכהן גוטוויטרה, בגלל התנגדותו לחסידות עבר לכהן כרב בטיסמניץ. חיבר \"מאורות נתן\" דראהביטש תרסד."},{"i":6684,"n":"אשכנזי, נתן נטע מראדזול","r":"רב בראדזאל","dt":"תקל - יח טבת","b":"גדול בנגלה ונסתר,רב בראזדאל","bk":[["פירוש על הזוהר (כת\"י)",""]]},{"i":6685,"n":"אשכנזי, נתן רפאל מוירונה","bp":"וירונה","b":"רב בוירונה, טריאסט על מקום ר יצחק פורמיגיני."},{"i":6686,"n":"אשכנזי, סעדי הלוי משלוניקי","f":"בצלאל","k":"בעל איל ביאז'י די רב","dt":"תרסג או תקעח","dp":"שלוניקי","b":"נכד המדפיס בצלאל הלוי אשכנזי מאמשטרדם ושלוניקי. מדפיס מחכמי שלוניקי-תרל על מקום אביו. תרגם את מסעות ר ישראל בן יוסף בנימין ללאדינו בשם \"איל ביאז'י די רבי ישראל\" עם הוספות משלו-תרכג. הו\"ל עתון \"לה איפוקה\". הוחרם ע\"י ר אשר קובו - בגלל תמיכתו בהשכלה. (אצל רוזניס מופיע שהדפיס בשנת תקנח - ואולי שני אנשים שונים)."},{"i":6687,"n":"אשכנזי, עובדיה מקושטא","b":"דיין בקושטא-תקמט."},{"i":6688,"n":"אשכנזי, עזרא ממכנאס","b":"היה בשליחות במכנאס-תרלח."},{"i":6689,"n":"אשכנזי, עזריאל הלוי מטרניגרד","k":"בעל נחלת עזריאל","b":"רב בטרניגרד-תל. חתנו - ר מיכאל."},{"i":6690,"n":"אשכנזי, עזריה חיים מירושלים","f":"אלישע","b":"מחכמי ירושלים, שליח האשכנזים בצפון אפריקה בשנת תע. אחיו של נתן העזתי. בשנים תפ - תק היה בחברון."},{"i":6691,"n":"אשכנזי, עזריה יהושע מאזמיר","dt":"שצח","dp":"אזמיר","b":"תלמיד ר חיים שבתי משלוניקי. חיבר הגהות על הטור ובית יוסף. מלמד תורה בשלוניקי, רב באזמיר-שפ בערך לצדו של ר יצחק דיין ועל מקומו אחריו, היה במחלוקת עם ר יוסף אישקאפה שהיה רב לצדו."},{"i":6692,"n":"אשכנזי, פנחס מאיטליה","f":"אברהם","k":"בעל קיצור דיני טריפו","bt":"תק","bp":"פיררה","dt":"תקצו","dp":"וירצלי","b":"תלמיד ר יוסף דוד בסאן בפיררה. מלמד ושו\"ב בערים שונות בפייאמונט, רב בורצללי-תקע - והיה הרב האורטודוכסי האחרון בעיר. תשובה ממנו ב\"זכור לאברהם\". חיבר שו\"ת בענין שחיטה - בכת\"י."},{"i":6693,"n":"אשכנזי, צבי - חכם צבי","f":"יעקב ז\"ק","k":"החכם צבי","bt":"תכ","bp":"טרביטש","dt":"תעח - א אייר","dp":"לבוב","b":"חתן ר משלם זלמן מירלש מהמבורג. רב באה\"ו-תע על מקום חותנו (והיה מחלוקת מצד חלק מקהלת אלטונא על רבנותו שבחרו בר משה רוטנברג), אמשטרדם-תע, לבוב-תעד."},{"i":6694,"n":"אשכנזי, צבי אביגדור ממונקטש","f":"אברהם משה","dt":"תקפד - כט אדר","b":"נכד ר יצחק אשכנזי בעל \"טהרת הקדש\". הו\"ל ספר זקנו עם הערות - לבוב תקנב. רב במונקטש-תקסט."},{"i":6695,"n":"אשכנזי, צבי הירש חריף מהלברשטט","f":"נפתלי הירץ מלבוב","k":"בעל עטרת צבי","r":"רבו של רע\"א הראשון","bt":"תל","bp":"לבוב","dt":"תקח - ד תשרי","dp":"הלברשטט","b":"חתן ר שמחה רפפורט מלובלין וגיסו של ר חיים רפפורט מלבוב, היה גם גיסו של ר יעקב יהושע פאלק בעל \"פני יהושע\". סירב לרבנות קראקא, ולבוב. רב בביאלא-תעז, הלברשטט(=איזנשטט)-תעח וראש ישיבה על מקום ר אברהם ברלין, ומתלמידיו: ר עקיבא איגר בעל \"משנת רבי עקיבא\", ר גדליה ליפשיץ בעל \"מרכבת המשנה\", ועוד. בניו: ר שלמה דב אב\"ד גלינה-חתן הפני יהושע, ר נפתלי הרץ אב\"ד דובנא, ר אברהם אב\"ד ראוויץ, ר שמואל אב\"ד ליסא, ר שמחה אב\"ד דעסוי, ר אריה ליבוש אב\"ד דובנקו ור דוד מלובלין. (כשכיהן בביאלא ניסה הנסיך לובומירסקי לחטוף את בתו מתחת חופתה והחתן הצליח להצילה וברחו - הנסיך אסר את ר צבי והשתדלן ר ישכר בר להמן פעל אצל מלך פולין אוגוסט השלישי לשיחרורו ואז עבר לאיזנשטט). בנו גם - ר יוסף מליסא.","bk":[["חכם צבי","שו\"ת - אחרונים"],["כוס ישועות – מסכתות , עטרת צבי שו\"ת ודרוש",""],["עטרת צבי – שו\"ת ודרוש, כוס ישועות – מסכתות",""],["כוס ישועות – מסכתות",""],["עטרת צבי – שו\"ת ודרוש",""]]},{"i":6696,"n":"אשכנזי, צבי הירש מאוסטרהא וברו","f":"אברהם משלם זלמן","k":"הו\"ל דברי רב משלם","bp":"אוסטרהא","dt":"תקמח - אחרי","b":"חתן ר יוסף יואל הלפרין מסטעפן. רב בברדיטשוב, פרנס באוסטרהא בחיי אביו ואב\"ד ור\"מ בקלויז באוסטרהא על מקום אביו (זה היה כהונתו הראשונה של אביו באוסטרהא). בנו ר מאיר."},{"i":6697,"n":"אשכנזי, צבי הירש מבורשטין","f":"נתן אשכנזי","b":"רב בבורשטין-תק\"נ"},{"i":6698,"n":"אשכנזי, צבי הירש מברוד","bt":"תרמב","bp":"ברודי","b":"נכד החכם צבי, תלמיד ביהמ\"ד לרבנים בברלין-תרסא. רב במושבות איק\"א בארגנטינה-תרעא."},{"i":6699,"n":"אשכנזי, צבי הירש מסטניסלב","f":"אשר אנשיל","k":"אדמור מסטניסלב","bt":"תרל","dt":"תשב","b":"רב בקניהינין-גורקא-עד תרעד, עבר לוינה-תרעו וכיהן שם כאדמור מסטניסלב, חזר לסטניסלב-תרצח חתן ר יצחק יהושע קליגר אב\"ד גריידונג. נספה בשואה. בנו היחיד ששרד ר משולם ישכר אדמור בלונדון."},{"i":6700,"n":"אשכנזי, צבי הירש מרימאנוב","f":"אפרים אשכנזי","b":"רב ברימאנוב-תק\"נ"},{"i":6701,"n":"אשכנזי, קלמן מקושטא","b":"דיין ביה\"ד האשכנזי בקושטא-תי."},{"i":6702,"n":"אשכנזי, קלמן מקושטא","f":"יהודה","b":"מדפיס אצל ר יונה בן יעקב אשכנזי בקושטא-תע."},{"i":6703,"n":"אשכנזי, ראובן [מג'רבה]","b":"נזכר ב\"תרומה הדשן\" לר צמח הכהן מג'רבא."},{"i":6704,"n":"אשכנזי, ראובן זליג מזאמושט","k":"בעל מחנה ראובן","b":"רב בזאמושט-תקל. תלמיד בעל \"תוספת שבת\". נזכר בחיד\"א."},{"i":6705,"n":"אשכנזי, ראובן יהושע זליג מפילט","f":"אריה ליב מיורבורג","dt":"תקצא","dp":"זאגר","b":"חתן ר אברהם שמחה מוולוזין-אחיו של ר חיים מוולוזין, ובזיוו\"ש חתן ר מנדל הכהן מקורלנד, ובזיוו\"ש חתן ר דובער קראקער כהנא-שפירא מזאגר. רב בפילטען. היה מעורב בילדותו במחלוקת בין אביו לבין ר נחום חריף אודות רבנות ניישטט-סוגינד ולכן סירב לרבנות רוב ימיו. מתלמידיו - ר צמח זקש - שנקבר לצדו."},{"i":6706,"n":"אשכנזי, ראובן מקושטא","f":"יונה בן יעקב מקושטא","dt":"תקל","b":"מדפיס בקושטא אצל אביו-תקג ואח\"כ עם אחיו נסים, אומן בציור וצייר וחוקק בעצמו את הציורים בספריו. בנו מנחם על מקומו אחריו."},{"i":6707,"n":"אשכנזי, רפאל אברהם מוידין","b":"גביר מחכמי וידין-תקס, פעל לטובת הקהלה ותמך בהדפסת ספרים, סייע לגיסו - ר יהודה בן משה עלי מניש בהדפסת ספרו \"קמח סולת\". חתנו - ר חיים קאניטי מוידין, בנו - יצחק."},{"i":6708,"n":"אשכנזי, רפאל אברהם מקושטא","b":"רב בקושטא-שנות ה-תק-תקן."},{"i":6709,"n":"אשכנזי, רפאל הלוי משלוניקי","f":"אהרן","dt":"שנד","dp":"שלוניקי","b":"משורר מחכמי שלוניקי."},{"i":6710,"n":"אשכנזי, רפאל יום טוב מאזמיר","b":"רב באזמיר-תרכב."},{"i":6711,"n":"אשכנזי, רפאל מאזמיר","f":"יהודה - מחנה יהודה","k":"בעל מראה עינים","bt":"בע' תקטו","dt":"תקפו - כז חשון","dp":"אזמיר","b":"רב באזמיר. נכדו של בעל ר אליהו חאקו בעל \"רוח אליהו\". חיבר \"מראה עינים\" אזמיר, השאיר חיבור על הרמב\"ם, חיבר גם \"מראה הנוגה\", \"מראה הגדול\" ועוד. נזכר ב\"שפתי רננות\" לר רחמים אריה אברהם ארייאש. בנו ר נסים אברהם אשכנזי בעל \"נחמד למראה\".","bk":[["מראה הגדול - דרוש",""],["מראה הנוגה - רמב\"ם",""],["מראה עינים – מראי מקומות בש\"ס",""]]},{"i":6712,"n":"אשכנזי, רפאל מוידן וירושלים","f":"נפתלי","dp":"ירושלים","b":"מחכמי וידין, עלה לירושלים-שנות ה-תק'."},{"i":6713,"n":"אשכנזי, רפאל מירושלים","dt":"תקלז - ט אלול","dp":"ירושלים","b":"מחכמי ירושלים, אשתו מרים נקברה לצדו."},{"i":6714,"n":"אשכנזי, רפאל מפירנצי","b":"רב בפירנצי. מתורתו ב\"יד מלאכי\"."},{"i":6715,"n":"אשכנזי, שאול הכהן","b":"הדפיס ספר שאלות ששאל לדון יצחק אברבנל ותשובותיו."},{"i":6716,"n":"אשכנזי, שלום מירושלים","b":"רב עדת האשכנזים בירושלים בשנת רמא כמוזכר בספרו של ר משולם מוולטרא."},{"i":6717,"n":"אשכנזי, שלום ממצרים","b":"רב במצרים-שם בזמן ר יעקב ן תבון, ור אליעזר סכנדרי. נזכר ב\"ליקוטי יוסף\"."},{"i":6718,"n":"אשכנזי, שלמה","b":"פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו."},{"i":6719,"n":"אשכנזי, שלמה הכהן משלוניקי","f":"יצחק","k":"בעל פירוש על מסכת אב","b":"מחכמי שלוניקי. חיבר פירוש למסכת אבות - שלוניקי שיא, \"זהר חדש\" - שלוניקי שנו."},{"i":6720,"n":"אשכנזי, שלמה מאזמיר","k":"בעל בן שלמה","b":"רב באזמיר. תלמיד ר יצחק אלבעלי בעל \"פרי העץ\"."},{"i":6721,"n":"אשכנזי, שלמה מאיטליה וקושטא","f":"נתן","bp":"אודינה","dt":"שס - בערך","b":"רופא מחכמי איטליה, עבר לקראקא-שיז והיה רופא המלך זיגמונד, התישב בקושטא-שכד. היה מתווך בין שלטונות ונציה לתורכיה במלחמה ביניהם-שלד - בניגוד לדעתו של דון יוסף נשיא. הצליח לבטל גזרת שמד שנגזרה על יהודי תורכיה. אחיו היה מקורב לוזיר שהיה אחר כך. אלמנתו - בולה איקשאטי היתה מקורבת למלכות ובקיאה ברפואה. בניו: נתן, שמואל, עובדיה - שלמדו באיטליה."},{"i":6722,"n":"אשכנזי, שלמה מטולטשווא","f":"משה דוד - באר שבע","k":"בעל כתנות אור","bt":"תקנב","dt":"תרכב - א אדר","dp":"צפת או ירושלים","b":"אבד בוסקוביץ=קשביץ, רב בטולטשווא לאחר אביו שעלה לארץ. עלה לארץ-תריג, והיה מחכמי צפת, אביו היה אב\"ד צפת. חיבר \"כתנות אור\" בכתב יד. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":6723,"n":"אשכנזי, שלמה מלבוב וירושלים","k":"בעל חוג הארץ","dt":"תקלז","dp":"שלוניקי","b":"רב בלבוב, עלה לירושלים, יצא לשלוניקי להדפיס את ספרו ונפטר שם."},{"i":6724,"n":"אשכנזי, שלמה מצפת","bt":"[שם]","dt":"תל - בערך","dp":"חברון","b":"מחכמי צפת, בשליחות באיטליה-תי, ונשבה במסינה-סיציליה, ונפדה. התישב בירושלים, בשליחות באיטליה-תך עם ר נתן שפירא, והתישב בחברון וכיהן כרב של חברון. תשובה אליו ב\"דבר שמואל\"."},{"i":6725,"n":"אשכנזי, שלמה מקושטא","b":"דיין מחכמי קושטא-שנות ה-ת'-תק'. נזכר ב\"כהונת עולם\"."},{"i":6726,"n":"אשכנזי, שלמה מראויטש","dt":"תקעג - ב אייר","b":"רב בראוויטש"},{"i":6727,"n":"אשכנזי, שלמה משלוניקי","f":"יוסף","b":"מחכמי שלוניקי, הו\"ל \"אמרות טהורות\" - שלוניקי שנד-אחרי, יחד עם ר נפתלי בן יוסף."},{"i":6728,"n":"אשכנזי, שמואל","f":"שמשון אוסטרפאלר","b":"רב-שנת ת\"מ"},{"i":6729,"n":"אשכנזי, שמואל זנויל מבונא","f":"יהודה","dt":"תקכו - תמוז","dp":"בוקהאלט - בונא","b":"אב\"ד מדינת קולוניא, ועסטפליא, מינשטר, בונא."},{"i":6730,"n":"אשכנזי, שמואל יהודה מונציה","b":"רב בונציה-שלג. תשובה ממנו ב\"פחד יצחק\" - אודות דין יבום, ופסק שמנהג פיזארו - לייבם."},{"i":6731,"n":"אשכנזי, שמואל מסנוק","dp":"ירושלים","b":"נכד החכם צבי. תלמיד ר נפתלי מרופשיץ. רב בסנוק. עלה לארץ-תר. מצאצאיו - ר שמואל נפתלי וגנר."},{"i":6732,"n":"אשכנזי, שמואל מפודהייץ","b":"רב בפודהיץ-ת\"נ"},{"i":6733,"n":"אשכנזי, שמואל מצפת","f":"אברהם","b":"מחכמי צפת, בשנת שפא חתם על המכתב לר ישכר בר איילינבורג אודות רבנות צפת."},{"i":6734,"n":"אשכנזי, שמואל מקושטא","f":"נסים בן יונה","b":"מדפיס בקושטא על מקום אביו-תקכח עם בן דודו מנחם בן ראובן אשכנזי."},{"i":6735,"n":"אשכנזי, שמואל צבי משלוניקי","b":"מדפיס אצל בצלאל הלוי אשכנזי בשלוניקי-תקו."},{"i":6736,"n":"אשכנזי, שמחה הלוי מצפת","b":"מחכמי צפת-שנות ה-ש'."},{"i":6737,"n":"אשכנזי, שמעון דייטש מדוברומיל","f":"אברהם","k":"בעל נחלת שמעון","bt":"תק","dt":"תקסב - ז חשון","dp":"דוברומיל","b":"תלמיד ר אלימלך מליזנסק, והחוזה מלובלין. חתן ר אפרים מדוברומיל. רב בדוברומיל-תקץ. כנראה הגיע מאשכנז על מנת להתקרב לחסידות. נפטר ללא בנים. חיבר \"נחלת שמעון\" לשצוב תקעה."},{"i":6738,"n":"אשכנזי, שמעון מצפת","f":"יעקב","b":"מחכמי צפת, בשנת תנב בשליחות באיטליה ואשכנז, כנראה היה ממוצא איטלקי. בשנת תנד היה בפיורדא ובפרנקפורט שם ענה לשאלות התובע הגרמני בענין הארבה בארץ ישראל עבור ספר שכתב אותו תובע בגרמניה. הדפיס \"אגרת מספרת יחוסא דצדיקיא\" פרנקפורט תנד. בשנת תסד בשליחות נוספת. הו\"ל \"יפה ענף\"."},{"i":6739,"n":"אשכנזי, שמעון קשטילץ ממצרים","b":"דיין במצרים-שנ אצל ר בצלאל אשכנזי יחד עם האר\"י."},{"i":6740,"n":"אשכנזי, שניאור זלמן מגרבה","b":"רב בגרבה. מחדושיו ב\"זרע יצחק\"."},{"i":6741,"n":"אשכנזי, שניאור פיבוש מירושלים","f":"מנחם מאנוש","k":"בעל שער פתחי לבנון","bp":"גליציה","dp":"קושטא?","b":"מחכמי ירושלים, עלה מבוליחוב בשנת תקט, בשנת תקיד בשליחות באשכנז ואיטליה לפדות את חצר ר יהודה החסיד, חיבר \"שער פתחי לבנון\". לדעת יערי חזר לירושלים ולדעת אחרים נפטר בחו\"ל."},{"i":6742,"n":"אשכנזי,יחיאל מיכל מפודולוטשיסק","b":"מחכמי פודוולוטשיסק. מתורתו ב\"עטרת תפארת\"-תרצב."},{"i":6743,"n":"אשכנזי-אקוילאה, מנחם מטומשוב","b":"מגדולי המקובלים הראשונים באשכנז-ד'תתק\"צ"},{"i":6744,"n":"אשכנזי-דייטש, י' שמעון מזליחוב","dt":"כב תמוז","b":"גדול בנגלה ונסתר,רב בוישניצא, זליחוב-תקצ, ראדזין."},{"i":6745,"n":"אשכנזי-טדסקי, משה יצחק מטריאסט","f":"שמואל","k":"תרגם רוח ישראל","bt":"תקפא","dt":"תרנח","b":"מו\"צ בטריאסט, תרגם מאיטלקית את \"רוח ישראל\" לר מרדכי מורטרה."},{"i":6746,"n":"אשכנזי-צבי, אליעזר ליזר מאפטא","f":"שמואל החסיד","k":"בעל דמשק אליעזר","dt":"תיא","dp":"ירושלים","b":"נכד ר צבי הלמן מוורמייזא. חברו של בעל הב\"ח, תלמיד ר משולם פייבש אב\"ד קראקא, רב באפטא, חיבר ספר \"דמשק אליעזר\" לובלין תו. לאחר חורבן תח ותט, עלה לירושלים-תיא. בדרכו עבר בבלגרד ובוינה והסכים על ספר \"נחלת צבי\" לר צבי טוך. מכונה גם אליעזר זעירא בן שמואל הילמן אחי ר בצלאל אבי המהר\"ל. בעברו בבילגרד מסר לר שמחה הכהן רפפורט קונטרס בשמות הגטין לזקנו ר נפתלי הירץ טריויש מפרנקפורט, והביאם בספרו \"שמות\" ונציה תיז. מצאצאיו - ר אפרים זלמן מרגליות מברודי. אחיו - ר חיים אשכנזי מקרמניץ."},{"i":6747,"n":"אשכנזי-צבי, חיים מקרמניץ","f":"שמואל החסיד","b":"נכד ר הלמן אחיו של ר בצלאל-אבי המהר\"ל מפרג, אחיו של ר יעקב צבי מפוזנא. רב בקרמניץ-תט, נספד ע\"י ר אברהם רפפורט-שרנצלס ב\"איתן האזרחי\". חתנו - ר שמואל שמלקא - אב\"ד אוסטרהא-תל. הסכים על \"נחלת יעקב\"-תח יחד עם אחיו ר יעקב מפוזנא, והסכים על טור יו\"ד - פרג תנד (ההסכמה ניתנה למדפיס הראשון והועתקה כאן). חתנו - ר שמלקא מאוסטרהא."},{"i":6748,"n":"אשכנזי-צבי, יעקב קופל מלבוב","f":"שמואל אשכנזי","b":"מגדולי חכמי דורו בלבוב-שנת ת'"},{"i":6749,"n":"אשכנזי-צבי, נפתלי הרץ משידלוב","f":"שמואל אשכנזי","b":"סיני ועוקר הרים,מרביץ תורה בשידלוב"},{"i":6750,"n":"אשכנזי-צבי, שמואל מורמייזא","f":"צבי העלמאן","k":"איש צבי","b":"רב בוורמייזא-שצ, עלה לירושלים. בניו - ר חיים(5898), ר נפתלי(16188), ר יעקב קופל(10297), ר אליעזר(2446)."},{"i":6751,"n":"אשכרה צרפתי, שמואל מתורכיה","b":"מחכמי תורכיה בזמן ר יוסף ן לב. בנו ר אברהם כתב הגהה בש\"ס דפוס פיזרו."},{"i":6752,"n":"אשכרה, אברהם","f":"שמואל","b":"מחכמי טורקיה"},{"i":6753,"n":"אשכרעלי, דבורה מאיטליה","b":"משכילה ומשוררת באיטליה. תרגמה משירי ר משה די ריאטי בעל \"מקדש מעט\" לאיטלקית - ונציה 1602, את שירי התוכחות לרבנו בחיי, ואת וידוי הגדול לרבנו נסים, וסדר העבודה לספרדים."},{"i":6754,"n":"אשל","b":"מגדולי הראשונים באשכנז,מקובל,מרביץ תורה בוירמייזא-ד'תת\"ק"},{"i":6755,"n":"אשל, ישראל (הדס-לוביל) מאלגיר","bt":"תרסה","bp":"קוסוב","dt":"תשנה","b":"נולד בקוסוב-גליציה, הגיע לאלגיר-תרצו והתישב בתלמסאן. מחנך ומלמד תורה, ר\"מ ב\"עץ חיים\"-אלגיר-תשיז-תשכב. חיבר בצרפתית \"רב\" - לתולדות ר אפרים אנקאווה (שכונה בשם \"רב\")."},{"i":6756,"n":"אשלג, ברוך שלום מבני ברק","f":"יהודה ליב-בעל הסולם","bt":"תרסז","dt":"תשנב - ה תשרי","b":"חתן ר יחזקאל אלימלך לינדר. הקים מרכז ללימוד הקבלה. הו\"ל ספר אביו \"פרי חכם. בנו ר שמואל.","bk":[["ברכת שלום - שמעתי","חסידות"],["אור ברוך, אור שלום – על ספרי אביו",""],["ברכת שלום – עה\"ת, מאמרים",""],["ה' שמעתי שמעך",""],["ה' שמעתי שמעך , ברכת שלום – עה\"ת, מאמרים , אור ברוך, אור שלום – על ספרי אביו,",""]]},{"i":6757,"n":"אשלג, יהודה ליב הלוי מירושלים","k":"אדמור מאשלג-הסולם","bt":"ה'תרמה","dt":"תשטו - י תשרי","b":"מגדולי המקובלים. תלמיד אדמורי פוריסוב. מו\"צ בוארשא, פגש שם ב\"נסתר\"-תרעט שלימדו את חכמת הקבלה. עלה לירושלים-תרפב - רצה לעלות עם 300 משפחות וכבר נרכשה האדמה לכך - אך לא הצליח ועלה לבד. תלמיד ישיבת \"חיי עולם\" והיה ראש חבורת לומדים וכיהן כאדמור. הקים ישיבה \"עיטור רבנים\", עבר לבני ברק-תשה ולתל אביב. חיבר פירוש על הזהר בשם \"הסולם\", ועוד.","bk":[["הסולם [על הזוהר] (אשלג)",""],["אור פשוט – בית שער הכוונות",""],["הסולם – זוהר הקדוש",""],["מתן תורה",""],["ספר ההקדמות",""],["פנים מאירות, פנים מסבירות - עץ חיים להאריז\"ל",""],["פרי חכם",""],["פתיחה לחכמת הקבלה",""],["תלמוד עשר הספירות",""],["פירוש הסולם לזוהר",""]]},{"i":6758,"n":"אשלג, יחזקאל יוסף מבני ברק","f":"שלמה בנימין מבני ברק","k":"אדמור מאשלג","b":"חתן ר שמאי גינצבורג. אדמור מאשלג על מקום אביו."},{"i":6759,"n":"אשלג, שלמה בנימין מבני ברק","f":"יהודה ליב-בעל הסולם","k":"אדמור מאשלג","r":"אדמו\"ר מאשלג","bt":"תרסו","dt":"תשמד - ז כסלו","b":"החל ללמד קבלה-תשב, עבר לבני ברק-תשטו וכיהן כאדמור מאשלג על מקום אביו.","bk":[["עטרת שלמה",""]]},{"i":6760,"n":"אשלג, שמואל","f":"ברוך שלום","k":"אדמור מאשלג","bt":"תרפט","dt":"תשנז - כט תשרי","b":"מקובל, תלמיד זקנו ר יהודה ליב. אדמור מאשלג על מקום אביו."},{"i":6761,"n":"אשלג, שמחה אברהם מבני ברק","f":"שלמה בנימין מבני ברק","k":"אדמור מאשלג","b":"חתן ר יצחק בן ר משה וינשטוק. ראש ישיבת \"מוהרי\"ל אשלג\" ואדמור על מקום אביו."},{"i":6762,"n":"אשמן, יעקב אליעזר מיברוב","b":"רב ביברוב. תשובה אליו \"בר ליואי\"."},{"i":6763,"n":"אשע, גרשון מפרנצלאווא","f":"טוביה - עט ברזל","k":"בעל נקרת הצור","b":"אב\"ד פרנצלאווא(=פרנצלאו). הו\"ל ספר אביו \"עט ברזל\" עם הוספות ממנו בשם \"נקרת הצור\" - ברלין תקצג, נזכר בשו\"ת ר עקיבא איגר."},{"i":6764,"n":"אשע, טוביה מצמפלבורג","f":"יחזקאל","k":"בעל עט ברזל","b":"אב\"ד ציקלבורג(=צמפלבורג)-תקפ, קרוטושין. בנו - ר גרשון מפרנצלאווא הו\"ל את ספרו עם הוספות בשם \"נקרת הצור\" - ברלין תקצג."},{"i":6765,"n":"אשפיז, צבי הירש ממנוסטרישץ","b":"מחכמי מנוסטרישץ. מתורתו ב\"ועד חכמים\"."},{"i":6766,"n":"אשקלוני, יוסף מקושטא","f":"יצחק","b":"ממונה על בית הדפוס של דונה ריינה בקושטא."},{"i":6767,"n":"אשקלס, אברהם","f":"גבריאל מניקלשבורג","b":"חתן ר מרדכי הכהן מאה\"ו"},{"i":6768,"n":"אשקלס, גבריאל מניקלשבורג","f":"יהודה ליב בן חיים","dt":"תעח - ב אד\"א","dp":"וינה","b":"מצאצאי ר סיני-אחי המהר\"ל. חתן ר בעריש-בן ר אברהם יהושע השל אב\"ד קראקא. אב\"ד עלקוש-תמד, קרעמזיר, פרוסטיץ, פרג, מיינץ או מיץ-תנה על מקוםר גרשון אשכנזי בעל עבודת הגרשוני, ניקלשבורג והמדינה-תסט, דיין בקראקא ורב בעלקיש-תמד. פעל עם הברון די אגילאר לביטול גזרת הגירוש ממדינת מעהרן, תרם הרבה לצדקה וחסד, והניח בצוואתו סכום גדול להקדש, בניו: ר יעקב משטאמפן, יהודה ליב - נפטר צעיר, ברנרד - ר ישכר דב בר מוינה. חיבר חדושים לכמה מסכתות וכן גם בנו. מתורתו ב\"קול יהודה\". הסכים על שו\"ע עם מגן אברהם - דירנפורט."},{"i":6769,"n":"אשקלס, דב בער ממהרין","b":"רב בכמה קהלות במעהרין."},{"i":6770,"n":"אשקלס, יהודה ליב מניקלשבורג","f":"גבריאל מניקלשבורג","dt":"תעא - יח תשרי","dp":"פפד\"מ","b":"בנו של רבה של ניקלשבורג. מחכמי אוסטרהא, פפד\"א. חתן ר נפתלי כץ מאוסטרהא בעל סמיכת חכמים. נפטר צעיר וגם אשתו והניחו בן ר חיים שגדל אצל זקנו ר נפתלי שאמצו לבן."},{"i":6771,"n":"אשקלס, יהודה ליב מקראקא","f":"חיים מוורמייזא","b":"מגדולי חכמי קרקא-ת\"כ"},{"i":6772,"n":"אשקלס, יהודה ליב משאפא","f":"יעקב משטאמפן","dt":"תקכד - כג כסלו","dp":"שאפא","b":"גביר מחכמי שאפא. סייע בהדפסת \"תבנית יוסף\"."},{"i":6773,"n":"אשקלס, יעקב משטמפן","f":"גבריאל מניקלשבורג","b":"חתן ר מרדכי הכהן. רב בשטאמפן-תפ, שאפא-מעהרין. בנו - ר יהודה ליב - נפטר תקכד, חתנו - ר"},{"i":6774,"n":"אשקלס, ישכר דב בער מוינה","f":"גבריאל מניקלשבורג","dt":"תקיג - כו אד\"א","dp":"וינה","b":"חתן השר ר שמשון ורטהיימר. איש חסד, רב בקרזמיר, פרוסטיץ, מגנצא, רב על מהרין הונגריה ומגנצא, וינה, ור משה בן אהרן לבוב על מקומו אחריו."},{"i":6775,"n":"אשקר, משה הכהן מחלב","f":"יוסף","k":"בעל הלל וזמרה","bt":"תרלח","bp":"חלב","dt":"תשא - יח תשרי","dp":"ארה\"ב","b":"מחכמי חלב ומשורר. עבר לארה\"ב וכיהן כחזן של קהילת הספרדים."},{"i":6776,"n":"אשר","f":"דוד בן הראב\"ד","k":"בעל ספר היחוד","b":"נכד הראב\"ד החסיד. רב ומקובל בפרובנס-ה'א בזמן הרמב\"ן. חיבר ביאור על יג מידות - בכת\"י בשם \"ספר היחוד\" - ומביא מתורת אביו ומדודו ר יצחק סגי נהור-בן הראב\"ד, חדושים מהרמב\"ן, סודות הניקוד, ואולי חיבר ספר התמורה - כנזכר ב\"עבודת הקדש\"."},{"i":6777,"n":"אשר","f":"משלם מלוניל","b":"מתורתו ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":6778,"n":"אשר - הרא\"ש","f":"יחיאל","k":"הרא\"ש","bt":"ה'י'","dt":"פח","b":"תלמיד מהר\"ם מרוטנבורג-רבו המובהק, ועוד. גדול הפוסקים הראשונים, רבן של כל בני הגולה, דיין בוורמייזא, הגיע לפרובנס-ה'סג, ברצלונה, ראב\"ד וראש ישיבה בטולידו. בניו: ר יחיאל-נפטר בחיי אביו, ר יעקב בעל הטורים, ר יהודה על מקומו אחריו בטולדו, ר שלמה החסיד, ר אליקים, ר משה, ר אלעזר, ר שמעון. חתנו - ר יהודה בן קרשף מספרד. אחיו: ר חיים, ר אליעזר."},{"i":6779,"n":"אשר אברהם הלוי מירושלים","dt":"תרמה - א אייר","dp":"ירושלים","b":"דיין בירושלים. בשליחות בתורכיה-תרכד. בנו - ר יוסף מרדכי הלוי."},{"i":6780,"n":"אשר אהרן מסופיה","b":"גביר בסופיה-שנות ה-תק'. הציל יהודי מהשלטונות. נספד מאת ר ראובן בן יעקב מסופיה."},{"i":6781,"n":"אשר אלישע מואריצקי","b":"תלמיד האדמור ר צבי אלימלך מדינוב בעל \"בני יששכר\", ושליחו-תקצב הנזכר באגרתו \"תמכין דאורייתא\"."},{"i":6782,"n":"אשר אנשיל","f":"יוסף מרדיק","k":"בעל מרכבת המשנה","b":"חיבר \"מרכבת המשנה\" - קונקורדנציה עם פירוש לתנ\"ך. ונקרא בשם ספר ר אנשל - קראקא שיד."},{"i":6783,"n":"אשר אנשיל הכהן מפפד\"מ","dt":"שמו - יג אדר","b":"מגדולי חכמי פפד\"מ. ניסח יחד עם ר אברהם נפתלי-רבה של פפד\"מ את ההודעה על עצמאות הקהילה, ושאין רשות לאף אחד לתקן תקנות וחרמות כנגד בני קהילה אחרת - אלא רק לביה\"ד המקומי."},{"i":6784,"n":"אשר אנשיל מטיסמניץ ולבוב","f":"משה","k":"בעל מים אדירים","b":"חתן ר מאיר הלוי הורביץ מבוליחוב וטיקטין. רב בגאליגורי, ראב\"ד בלבוב חתם-תקכב עם ר חיים הכהן רפפורט, חתם-תקלג עם ר יחיאל מיכל בריסקר, ר מנחם מנדל רפפורט, ועוד. אולי הוא שהיה מחותן עם ר חיים הכהן רפפורט."},{"i":6785,"n":"אשר אנשיל מטשכנובצא וסלץ","dt":"תקכה - כט אייר","b":"רב בסעלץ, טשכנווצע. תלמיד חבר למגיד ממזריטש."},{"i":6786,"n":"אשר אנשיל מראזדיל","f":"משה בער","k":"בעל בן אמונים","dt":"תקמד - כ חשון","dp":"לבוב","b":"רב בראזדיל. חיבר \"חידות שמשון\", \"בן אמונים\" - פיורדא תקמה."},{"i":6787,"n":"אשר אנשל מפרמישלא","f":"יצחק","k":"בעל שמנה לחמו","b":"תלמיד ר נפתלי כץ מפוזנא (שהסכים על ספרו). רב ומלמד תורה בפרמישלא-תס."},{"i":6788,"n":"אשר אנשל מקראקא","f":"יעקב","dt":"תקלג - ה חשון","dp":"קראקא","b":"מחכמי קרארא. נכד רבה של ליסא."},{"i":6789,"n":"אשר בן יעקב אבינו, קבור בקדש נפתלי","dt":"ב שבט"},{"i":6790,"n":"אשר הכהן מלבוב","f":"יצחק","dt":"שמב - כט ניסן","dp":"לבוב","b":"ראב\"ד ור\"מ בלבוב. בנו ר יעקב קופל - רב בלבוב."},{"i":6791,"n":"אשר הכהן מפרובנס","b":"מחכמי פרובנס-ן', משורר ופייטן. נזכר בשיר מאת ר אברהם בדרשי ב\"חותם תכנית\"."},{"i":6792,"n":"אשר הכהן מקושטא","f":"יצחק מקולוניא","b":"ראש קהלת אשכנז-בקושטא-רן-ש', היה במחלוקת עם ר משה קפסלי."},{"i":6793,"n":"אשר הכהן מקיוב","b":"נזכר בין חכמי קיוב בזמן גירוש ליטא וקיוב יחד עם ר משה בן יעקב בעל \"אוצר נחמד\", ור קלמן אשכנזי."},{"i":6794,"n":"אשר הכהן מקריניק","f":"אביגדור","b":"דיין בקריניק, ואח\"כ אב\"ד שם. בנו - ר יוסף בעל 'כפות זהב'."},{"i":6795,"n":"אשר הכהן משערשוב וטיקטין","f":"צבי הירש מטיקטין","k":"בעל ברכת ראש","dt":"תרכו - ב שבט","b":"תלמיד ר חיים מוולוזין. רב בשערשוב(=שארשוב), טיקטין. תלמיד חבר שלו היה ר פנחס מיכאל רוקח מאנטיפאליע. מחותן עם ר אברהם יצחק מקרלין. בנו - ר דוד מוארשא."},{"i":6796,"n":"אשר הלוי מאיטליה","b":"אביו של ר אליהו בחור אשכנזי המדקדק. בנו מביא ממנו בספרו."},{"i":6797,"n":"אשר הלוי מאינסבורג","f":"יעקב","b":"רב באינסבורג בזמן הרא\"ש. חיבר פירוש לתפילות בדרך פשט וסוד. יתכן והוא נכדו של ר אשר הראשון. ויתכן שהוא בן דודו של ר יצחק בן אלעזר הלוי וכתב לו ספר-ן'."},{"i":6798,"n":"אשר הלוי מאשכנז","f":"יעקב","k":"אש\"ל","b":"תלמיד ראב\"ן במגנצא. מחכמי אשכנז-ד'תתק. מתלמידיו - ר אלעזר בעל הרוקח. אולי אביו הוא ר יעקב יעבץ. מבניו: ר יעקב מחכמי שו\"ם, ור אליקים, ואולי גם ריב\"א השני - ר יצחק בן אשר - שנהרג עק\"ה. מתורתו ב\"פענח רזא\" לר יצחק בן יהודה הלוי, שקורא לר אשר - דודי - ואולי היה אחיו של אביו של ר יהודה. ויש אומרים שאש\"ל הוא ר אברהם משפירא ולא ר אשר."},{"i":6799,"n":"אשר הלוי מדיניץ","b":"חסיד בלז שישב בבלז שנים רבות. רב בדיניץ (ליד דרוהוביטש)-תרנה."},{"i":6800,"n":"אשר הלוי מוורמייזא","b":"היהודי הראשון שהתישב בוורמייזא-ד'תתעב, והגיע לשם מויטרי-צרפת - והכוונה לאחר חורבן ד'תתנו שאז בטלה הקהילה. חיבר את הפיוט לפורים \"אשר הניא\". ואחד מצאצאיו - ר אלעזר זלמן הלוי ממגנצא רשם סדר יחוסו עד ר אשר. בנו - ר יצחק ואולי הוא הנקרא ריב\"א משפירא. גם ר מנחם ציון בעל \"ציוני\" שהיה ממשפחתו רושם סדר יחוסו."},{"i":6801,"n":"אשר הלוי מירושלים","b":"מגדולי חכמי ירושלים-תק\"ט"},{"i":6802,"n":"אשר הלוי מלבוב","f":"דוד","b":"דיין בלבוב, חתם-תלח עם מנהיגי ועד ארבע ארצות בלובלין."},{"i":6803,"n":"אשר הלוי משלוניקי","b":"דיין בשלוניקי-שס בערך - בזמן ר אהרן ן חסון."},{"i":6804,"n":"אשר הלוי ציון מאיטליה","f":"אליקים","k":"אנשל סגל","dt":"רצב - א אייר","b":"מחכמי אשכנז בונציה-רן. היה במחלוקת עם ר אברהם מינץ. נזכר ב\"דעת קדושים\", וב\"שלשלת הקבלה\" אודות רב אשכנזי בפדובה בשם ר אנשל סגל ונזכר בשו\"ת ר יהודה מינצי. ואולי הוא ר אשר משלם הלוי מפדובה."},{"i":6805,"n":"אשר זבולון מבלגרד","b":"תלמיד ר דוד קונפורטי הזקן, ר אברהם מוטאל. מחכמי קושטא?, שלוניקי, סרייבו, רב בבלגרד-שצד יחד עם ר שמחה הכהן. למד בילדותו עם ר דוד קונפורטי-שעו."},{"i":6806,"n":"אשר זליג מאוסטרהא","f":"עזריאל","dt":"תקצב - ו שבט","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":6807,"n":"אשר זליג מאטשקוב וטבריה","dp":"טבריה","b":"רב באטשקוב, עלה לטבריה."},{"i":6808,"n":"אשר זליג מאיזהאוויץ וראדויל","f":"בנימין בזאלוזיץ","b":"רב באיזהאוויץ, ראדויל. הו\"ל ספרי אביו."},{"i":6809,"n":"אשר זליג מבלוזוב","b":"רב בבלוזוב-תרל."},{"i":6810,"n":"אשר זליג מזולקוא","f":"ישראל שמואל","dt":"תכח - כ אדר","dp":"זולקוא","b":"רב בזולקוא. מתלמידיו - ר מנחם מנדל ונגרב בעל \"צנצנת מנחם\"."},{"i":6811,"n":"אשר זליג מזולקוא","b":"מחכמי זולקוא, חתם-תעו על תקנה שלא יהיה אחד מקרובי הרב בתוך מנהיגי הקהלה."},{"i":6812,"n":"אשר זליג מלבוב","f":"יעקב","b":"דיין בלבוב-תקמ, הסכים על היתר גט לר שלמה בעל מרכבת המשנה."},{"i":6813,"n":"אשר ישעיה מבוקובסק","b":"חתן אב\"ד בוקובסק-תרל."},{"i":6814,"n":"אשר ישעיה מקולבסוב","b":"רב בקולבסוב"},{"i":6815,"n":"אשר ישעיהו הלוי מגורליץ","f":"משה יצחק","bt":"תרט","bp":"גורליץ","dt":"תרעב","b":"לאחר שנתייתם נדד ברחבי רומניה בולגריה תורכיה ויון והגיע לשלוניקי - שם שהה כשנתיים, והמשיך לנדוד עד הודו-תרלג. חיבר שם ספרים ובהם \"הררי הימלאייא\" (נדפס בשבועון ערבי באות עברית), \"הרפתקאותיו של אשר הלוי\" ירושלים תרצח. חיבר עוד ספרים רבים."},{"i":6816,"n":"אשר למלין - המקובל","k":"ר' אשר למלין הדרשן","b":"מקובל, עבר בערי אשכנז, איטליה ואוסטריה לעורר העם לתשובה-רס, ולדברי ר אברהם פריצול טען שהמשיח כבר בא וזקנו ר זליגמן גאנץ הרב את תנור המצות שלו כדי לעלות לארץ."},{"i":6817,"n":"אשר לעמיל הלוי","f":"משה","k":"בעל תקופות השנה","b":"משורר. חיבר \"תקופות השנה\" ובו 4 שירים מיסודו של טמהאוזן - ברלין תרב."},{"i":6818,"n":"אשר לעמיל הלוי מגלוגא","k":"בעל חוט המשולש","bt":"תסה","dt":"תקמט - כג תשרי","b":"רב בגלוגא, אייזנשטט. בהיותו בגלוגא קיבל מכתב מר יחזקאל בעל \"הנודע ביהודה\" שניסה לעשות שלום במחלוקת ר יהונתן איבשיץ - ור אשר פנה לבן עירו ר צבי הירש (לימים רבה של לונדון וברלין) ושכנע אותו לכתוב לדודו היעב\"ץ ולבקשו להסכים לשלום."},{"i":6819,"n":"אשר לעמיל מאייבנשיץ","b":"מקובל,רב באייבנשיץ-תק\"י. בנו ר משה - סופר ודיין בקראקא."},{"i":6820,"n":"אשר לעמיל מהמבורג והנליבורג","dt":"תקמ - א טבת","dp":"המבורג","b":"מרביץ תורה בהמבורג."},{"i":6821,"n":"אשר לעמיל מוואהין","dt":"תרכח","b":"תלמיד החוזה מלובלין, ר שמחה בונם מפשיסחא, ר מנחם מנדל מקוצק, ר יצחק מאיר מגור. רב במודליבורזיץ, וואהין-ליד פרצוב. חתנו ר ברוך ישראל על מקומו אחריו."},{"i":6822,"n":"אשר לעמיל ראכלעס מקראקא","f":"יוסף","k":"בעל עמק הברכה","dt":"רצב","b":"מכונה ראכלס על שם חמותו - רחל. רב בקראקא-רס בזמן ר יעקב פולק ור משה פישל על מקומו אחריו. היה מחלוקת בינו לבין ר פרץ שהיה רב שם והגיע למלך שפסק שר פרץ הוא הרב אבל גם ר אשר יכול לכהן כרב, והיה מחלוקת בקהילה על הזכויות בביהמ\"ד בין הותיקים שנקראו פולנים ובין יהודים שהגיעו מבוהמיה - והגיע אל המלך שהחליט לטובת הפולנים בראשות ר אשר ראכלעס. בניו ר יצחק מלבוב, ר אשר לעמל מלובלין, ר שלמה ונכדו ר גדליה בעל \"עץ שתול\", ר גדליה ונכדו - המהר\"ם מלובלין. מחותניו: המהר\"ל, ר ישכר בער מוורמיזא, ר אבא מקראקא (ובאמת היו מחותני המהר\"ם מלובלין)."},{"i":6823,"n":"אשר מאוסטרהא","f":"ישראל רב דחייטים","dt":"תקפא -יט-כ ניסן","dp":"אוסטרהא","b":"מחכמי אוסטרהא וגבאי ח\"ק."},{"i":6824,"n":"אשר מאוסטרהא","f":"שמואל ר יעקבס","dt":"תקיג - ט אייר","dp":"אוסטרהא","b":"מחכמי אוסטרהא. נפטר צעיר. אחיו הפרנס ר יוזפא הניח בצוואתו סכום עצום עבור חלקת קבר לצדו."},{"i":6825,"n":"אשר מאיטליה","f":"אורי","b":"נמנה בספר זכרון נשמות באיטליה."},{"i":6826,"n":"אשר מאשכנז","f":"אליקים","b":"מחכמי אשכנז-ן'. נזכר ב\"אור זרוע\" עם חבריו ר יעקב בן משה, ור מנחם בן תמר."},{"i":6827,"n":"אשר מאשכנז","f":"משה","b":"מחכמי אשכנז-ן', אחיינו - ר יצחק בעל \"אור זרוע\". היה בקשר עם מהר\"ם מרוטנבורג ונזכר בתשובותיו."},{"i":6828,"n":"אשר מאשכנז","dt":"קפא","dp":"אוסטריה","b":"נהרג עק\"ה עם חבריו ר ישראל בן טוביה, ור שאול. בנו ר מנחם הזכירו בספרו."},{"i":6829,"n":"אשר מאשכנז","f":"שמעון הגדול","b":"מחכמי אשכנז-ד'תתק. חיבר פיוט במחזור \"אשחרה פניך\", וחיבר תפילה לשלום המלכות. (ובמקום אחר כתוב שהיה בשנות ה-ש' ואולי הוא ר אשר גינצבורג - וכנראה טעות)."},{"i":6830,"n":"אשר מבדרש","f":"שלמה - שלמיה","b":"אביו היה תלמידו של בעל המאור. מחכמי פרובנס, רב בבדרש-מחוז נרבונא, נרבונא-ד'תקן. חיבר חדושי הש\"ס. נזכר בשו\"ת רשב\"ש בשם ר אשר נרבוני. בנו ר שלמה מבדרש."},{"i":6831,"n":"אשר מבלז","f":"צבי הירש","b":"רב בבעלז"},{"i":6832,"n":"אשר מגייא","b":"רב בגייא-תקע\"ה"},{"i":6833,"n":"אשר מגרודזינסק","f":"אלחנן","dt":"תקנח - ג שבט","b":"רב בגרודזינסק,מ\"מ בפשדבארז"},{"i":6834,"n":"אשר מדריבין","b":"תלמיד הצמח צדק, בנו ר יהודה ליב ונכד ר שלמה זלמן מקפוסט."},{"i":6835,"n":"אשר מהורודוק"},{"i":6836,"n":"אשר מוילנא","f":"משה אהרן מוילקוביסק","dt":"תקנג","dp":"וילנא","b":"מחכמי וילנא."},{"i":6837,"n":"אשר מוילנא","f":"אהרן","b":"דיין בוילנא, חתם-תכד עם ר יצחק מפוזנא."},{"i":6838,"n":"אשר מוילקומיר"},{"i":6839,"n":"אשר מוינה","f":"יצחק","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":6840,"n":"אשר מולקוביסק והורדנא","b":"רב בהורדנא."},{"i":6841,"n":"אשר מטיקטין","f":"מנחם","b":"רב בפולין-ש'. הדפיס את ספרי אביו-שנז עם הגהות ממנו."},{"i":6842,"n":"אשר מיכל הכהן מבאזל","b":"רב בבאזל"},{"i":6843,"n":"אשר מלבוב","f":"ראובן","dt":"תסג - ג כסלו","dp":"לבוב","b":"דיין בלבוב, נהרג בנפילת הבתים שהיתה בלבוב."},{"i":6844,"n":"אשר מלוניל","f":"שאול מלוניל או משלם","k":"הרא\"ש מלוניל -מנהגות","b":"תלמיד הראב\"ד, ר שמואל בן דוד, ואולי גם תלמיד ר יוסף בן פלט. מחכמי פרובנס, פוסק, רב בלוניל-ד'תתקכה, נרבונא. חיבר ספר המנהגות. אחיו של ר אהרן, ור יעקב נזיר המקובל (שי\"א שהיה רבו של הראב\"ד בקבלה). היה חברו של ראב\"ן הירחי - ר אברהם בן נתן בעל \"המנהיג\" ויש שהחליפו ביניהם - לדעת רש\"י פין המדובר באותו החכם."},{"i":6845,"n":"אשר ממינסק","f":"ליבל בעל התוספות","dt":"תצז","dp":"סמילוביץ","b":"התישב בסמילוביץ וכיהן משם כאב\"ד ור\"מ של פלך מינסק על מקום ר מנחם מנדל מרגליות (בזמן כהונת בעל סדר הדורות כרבה של העיר מינסק). בנו - ר יהודה מקלצק. נכדו - בעל שאגת אריה. (ראה גינצבורג אשר מויזון - כנראה יש בלבול אצל איזנשטט-מינסק בענין)"},{"i":6846,"n":"אשר מסטולין","f":"אהרן מקארלין","k":"אדמור מקרלין סטולין","r":"בן ר' אהרן הגדול מקרלין","dt":"תקפד - כו תשרי","b":"אדמו\"ר בסטאלין"},{"i":6847,"n":"אשר מסטולין","f":"אהרן הגדול מקרלין","k":"אדמור מקרלין סטולין","bt":"תקכה","dt":"תקפז - כו תשרי","b":"לאחר שנתייתם גדל אצל ר שלמה מקרלין-תלמידו של אביו. אדמור בקרלין על מקום אביו, ומתלמידי ר ברוך ממזבוז. בזיוו\"ש חתן אלמנת ר אהרן שותק מזליחוב ועבר לפולין-תקנב, חזר לליטא והתישב בסטולין. מתורתו בספר בנו \"בית אהרן\" - חתנו ר ישראל מאוסטרהא-נכד בעל \"מהדורא בתרא\" למהרשא\"."},{"i":6848,"n":"אשר מספרד","f":"שלמה בן הרא\"ש","b":"מחכמי ספרד-ק', אסף וערך את תשובות דודו - ר יהודה בן הרא\"ש. חברו של ר ידידיה הדיין המזכירו ב\"זכרון יהודה\"."},{"i":6849,"n":"אשר מפאלאנקה","b":"רב בפאלאנקא-תקע\"ח"},{"i":6850,"n":"אשר מפליזא","k":"הרא\"ש מפליזא","b":"מגולי הראשונים-ה'ס'"},{"i":6851,"n":"אשר מפפד\"מ","b":"רב בפפד\"מ-קלד, משמו הובא ב\"יוסף אומץ\" - נוסח תפילה בשם ר יוזלמן לואנץ מרוסהיים לומר בשעת קידוש השם (כשהולך אדם למסור נפשו על קידוש השם) וי\"א שמחבר הוידוי הוא ר אשר בעצמו."},{"i":6852,"n":"אשר מפרובנס","f":"מנחם","b":"מחכמי פרובנס-ק'. חיבר פירוש על משלי."},{"i":6853,"n":"אשר מפריסוב","b":"רב בפאריסוב-תק\"ס"},{"i":6854,"n":"אשר מפרנקפורט","k":"בעל וידוי לקדוש השם","b":"רב בפרנקפורט-ק\"פ"},{"i":6855,"n":"אשר מפשדבורז (רבינוביץ)","dt":"תקנח - ג שבט","b":"אביו של היהודי הקדוש ר יעקב יצחק רבינוביץ מפשיסחא"},{"i":6856,"n":"אשר מצרפת","f":"נתן אפיציאל","b":"מחכמי צרפת-ד'תתקן. אחיו של ר יוסף. מתורתו בספרי אביו ואחיו."},{"i":6857,"n":"אשר מקנדיא","f":"יצחק","b":"מחכמי קנדיא."},{"i":6858,"n":"אשר מקראקא","f":"יצחק","dt":"תקכה - כב תמוז","dp":"קראקא","b":"מחכמי קראקא."},{"i":6859,"n":"אשר מקרלין הנכד","f":"אהרן מקרלין הנכד","k":"אדמור מקרלין-\"הצעיר\"","dt":"תרלב-ג - טו אב","dp":"דרוהוביטש","b":"חתן ר מנחם נחום טברסקי ממקרוב (טשרנוביל), ובזיוו\"ש חתן ר אלימלך מגרודזיסק (קוזניץ). אדמור מקרלין על מקום אביו."},{"i":6860,"n":"אשר משברשין","f":"הקדוש יצחק","b":"רב בשברשין-תלג, בעלזא-תנ\"ה"},{"i":6861,"n":"אשר משערשוב","b":"גביר מחכמי שארשוב(=שערשוב)-שנות ה-תק'. בנו - ר שלום, חתניו - ר יהושע רוקח מפינסק, ר חיים משארשוב."},{"i":6862,"n":"אשר משערשוב","f":"יצחק בן חיים","b":"רב בשארשוב. בנו - ר טוביה משארשוב."},{"i":6863,"n":"אשר ן, אברהם (רפאל) מירושלים","b":"ראש ישיבת \"יפאר ענוים\" בירושלים-תקיח. (מיסודה של משפחת פרנקו מליוורנו). בשליחות-תקא. חתם-תקיו על שטר התקשרות עם חכמי ירושלים. חתם על תקנות בשנים תקט-תקכב. כנראה ממשפחת ר אברהם ן אשר בעל \"אור השכל\"-שכב. מתלמידיו - החיד\"א?"},{"i":6864,"n":"אשר ענזיל מאוסטרהא","f":"יהודה ליב מפינסק","k":"בעל ברוך מבנים אשר","dt":"תקלז - יא אד\"א","b":"בן הרב מאוסטרהא סלוצק ופינסק, ואחיו של ר מרדכי-חתנו של הגביר ר יוזפא אוסטריר פרנס מדינת ואהלין. חתן ר דב בר בן ר שמואל ר יעקליש. דיין ודרשן באוסטרהא-תקי\"ד. הסכים על \"מפלגי ראובן\"-תקיד, ועוד. חיבר גם \"קרבן עשיר\", \"אותות למועדים\", ועוד. נפטר ללא ילדים. , ב\"קריה נאמנה\" נאמר כי היה גם ראב\"ד בסלונים - אך זו טעות וכנראה מדובר על חכם אחר באותו השם (הזמן שבו היה בסלונים-תקמד ואילו ר אשר נפטר-תקלז)."},{"i":6865,"n":"אשר ענזיל מפינטשוב","dt":"תעז - יא אדר","b":"חתן ר יצחק רפפורט מאוסטרהא. רב בפינטשוב. בנו - ר יהודה ליב מאוסטרהא, נכדו ר אשר ענזיל מאוסטרהא בעל \"ברוך מבנים אשר\"."},{"i":6866,"n":"אשר ענזיל מפרמישלא","b":"חתן ר יוסף אשר. רב בסטריא,פרעמיסלא-תק\"צ"},{"i":6867,"n":"אשר ענזיל מצורטקוב","b":"מחכמי צורטקוב-תרכה."},{"i":6868,"n":"אשר ענשכין הכהן מאשכנז","f":"יחיאל","dt":"רמג","b":"מגדולי חכמי דורו, פוסק, רב באולמא-רכה, ונציה. נזכר בשו\"ת מהרי\"ק - בין רבני אשכנז, וב\"נחלת שבעה\" מביא ממנו. כנראה הוא ר אשר שנתבקש מבני המהרי\"ל שיסדר את ספרי אביהם-רכג ונקרא גם ר ענשכין ונזכר ב\"שארית ציון\". מתלמידיו - ר יהודה מינץ המזכירו בספרו."},{"i":6869,"n":"אשר צבי מגיד מאוסטרהא","f":"דוד מאוסטרהא","k":"בעל מעין החכמה","bp":"אוסטרהא","dt":"תקעז - טז שבט","dp":"קוריץ","b":"תלמיד המגיד ממזריטש. רב בברעזרוב-ליד אוסטרהא, מג\"מ באוסטרהא, קוריץ-תקסד (לאחר שהיה מחלוקת כנגדו באוסטרהא). הסכים על \"כנפי יונה\" - קורץ תקמה, ספר הקנה, \"עץ חיים\" - קורץ תקמב, \"מאיר נתיבים\" - פולנאה תקנא, ועוד. בנו ר יואל.","bk":[["מעין החכמה [עה\"ת ותהלים] (קארעץ)",""]]},{"i":6870,"n":"אשר שמחה משלוניקי","f":"שמחה, אשר משלוניקי","b":"רבה האחרון של הקהלה האשכנזית בשלוניקי"},{"i":6871,"n":"אשר, קרל מאמשטרדם","bt":"1838","bp":"אמשטרדם","b":"פרופ' למשפטים באמשטרדם, שר המשפטים בהולנד. נבחר לתווך בסכסוכים בין מדינות. חבר באספת השלום בהאג. פעל בעניני הצבור היהודי בהולנד. נמנה בין המפקחים על הסמיכה לרבנים באמשטרדם."},{"i":6872,"n":"אשרוב, אברהם אליהו מריגא","dt":"תשא","b":"רב בריגא"},{"i":6873,"n":"אשרוביץ, חיים זלמן מלחווא","dt":"תשב - כא אלול","b":"רב בלחווא"},{"i":6874,"n":"אשרוביץ, יעקב משה מברעזי","f":"ישראל","bt":"תרכח","b":"תלמיד ישיבת וולוזין, כולל קובנא. חתן ר יחיאל מיכל וולפסון מיאנישוק בעל \"שפת הים\". רב ביאנישץ, רב בברזי(=ברעזי)-פלך גרודנא-תרנה. נסמך מאת: הנצי\"ב, ר יצחק אלחנן מקובנא."},{"i":6875,"n":"אשרי אפרים בן דב","bt":"1914","dt":"ה'תשסג 2003","bk":[["דברי אפרים",""],["ממעמקים",""]]},{"i":6876,"n":"אשרי, אפרים מקובנא וניו יורק","f":"דב","k":"בעל דברי אפרים","bt":"תרעד","bp":"קופישוק-ליטא","b":"תלמיד ישיבות פוניבז, קעלם, סלובודקה. נסמך מאת: ר אברהם דב שפירא מקובנא, ר ליב רובין מוילקומיר, ר ברוך הורביץ מאלקסוט, ר עזרא אלטשולר מווינוטע, ר אברהם זאב הלר ממאריאמפול. רב בקלויז \"אבא יחזקאל\" בסלובודקה, קובנא, ניצל מהשואה ואחריה רבה של קובנא ועסק בשיקום הקהלה. הגיע לאוסטריה ויסד ישיבת במחנה הפליטים בוועלש-ליד זלצבורג, הגיע לרומא-איטליה ויסד ישיבה \"מאור הגולה\", וסייע לפליטים באיטליה. ניו יורק. חיבר \"דברי אפרים\" נ\"י תשט ובו שאלות שנשאל במחנות הריכוז בזמן השואה, \"ממעמקים\". פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה. פרסם מאמרים אודות קורותיו בזמן השואה, וספר באידיש על יהדות ליטא."},{"i":6877,"n":"אשרי, יוסף מראסיין","b":"מחכמי ראסיין. חתנו - ר מנחם מנדל פרידמן מראסיין."},{"i":6878,"n":"אשריקי, יוסף ממרוקו","b":"מו\"ץ במרוקו."},{"i":6879,"n":"אשריקי, יוסף מפאס","b":"מחכמי פאס. סופר ביה\"ד של ר אליהו הצרפתי המכנהו \"סופר הרזים\" (כנראה היה מקובל) יחד עם ר יהודה בן שמול."},{"i":6880,"n":"אשריקי, מסעוד מלמדייא","f":"אברהם","bt":"תס - בערך","dt":"תקל - בערך","b":"מחכמי למדייא(=מידיאה). נזכר אצל ר יהודה עייאש."},{"i":6881,"n":"אשריקי, מרדכי ממרוקו","k":"חון (לחזן?) בבא","dt":"תקן - סיון","dp":"מכנאס","b":"גביר עשיר יועץ מלך מרוקו, ופעל לטובת אחיו היהודים, נהרג עק\"ה בידי המושל אליזיד בזמן הפרעות - לאחר שסירב להמיר דתו. בנו - דוד שתבע את עזבון אביו, ודן בעניניו ר יעקב בירדוגו ממכנאס"},{"i":6882,"n":"אשריקי, שמעון ממרוקו וירושלים","f":"חיים","bt":"תריט-תרך","bp":"מוגדור-מרוקו","dt":"תרץ - כו סיון","dp":"ירושלים","b":"עלה בילדותו ממוגדור-מרוקו, עם הוריו והתישבו ביפו. תלמיד ר שלמה בוחבוט ביפו, לאחר שנתייתם נישאה אמו לר אברהם אשכנזי הרשל\"צ בירושלים וגדלו ולימדו תורה, תלמיד וחתן ר אברהם פנסו. מחכמי ירושלים, בשליחות במרוקו-תרמג, תונס, הודו, ועוד, בשליחות באירופה-תרסב והמגרב. דיין בביה\"ד עדת המערבים, וראב\"ד על מקום ר יוסף חיים הכהן, עם הדיינים ר אליהו לעג'מי, ור יעקב ן עטר - ושלשתם נזכרו אצל הבבא סאלי וחיבבם והעריכם. חתנו ר יצחק יחזקאל יהודה."},{"i":6883,"n":"אתאזי, מאיר מסאלי","f":"חיים","b":"דיין בסאלי. חתם עם ר שמואל בן משה אזאוי-תקלג."},{"i":6884,"n":"אתאזי, מסעוד מסאלי","b":"דיין בסאלי-תכט על מקום ר יעקב ששפורטש. מכתב ממנו אל ר חסאן אדאורקי במכנאס-תכט, חתם על שאלה עם ר יעקב ן סעיד."},{"i":6885,"n":"אתורקי, יהודה","dt":"תלב - יט ניסן","b":"מחכמי מראקש,דיין"},{"i":6886,"n":"אתורקי, יצחק מסאלי","b":"מחכמי סאלי-מרוקו. תלמידו - ר אהרן הסבעוני מסאלי."},{"i":6887,"n":"אתזי, עזר","b":"מחכמי ירושלים, בשנת תמב בשליחות."},{"i":6888,"n":"אתינאר, משה מפאס","b":"סופר בי\"ד מפאס. חתם-שיב עם ר אברהם קטן."},{"i":6889,"n":"אתרוג, יצחק דוד מארה\"ב וישראל","f":"נחום מצפת","k":"בעל מקור החכמה","b":"רב בפורטלנד, לוס אנגלס, עלה לארץ תרצו. פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":6890,"n":"אתרוג, ליב מנייאמץ","k":"בעל הר אבל","dt":"תרנד","b":"רב בנייאמץ-מודלובה. היה בקשר עם גדולי דורו ובהם בעל השו\"מ, ר יעקב וידנפלד, ועוד. אחיינו ר נחום מצפת הדפיס הספד ממנו בשם \"הר אבל\" ב\"אבל משה\" ירושלים תרמד."},{"i":6891,"n":"אתרוג, נחום מצפת","k":"בעל דובב שפתי ישנים","bt":"תרכב","dt":"תרצח","dp":"צפת?","b":"ראבד בצפת. חיבר \"דובב שפתי ישנים\" ירושלים תרפז. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"הדביר\" - ירושלים תרעט, \"שערי ציון\" - ירושלים תרפא."}];
